    ["FlatCoin"] = {
        zh = "在纪念品压币机上硬生生把米老鼠压扁改模出来的产物。仔细端详，那位象征战前流行文化的米老鼠仿佛隔着变形的书本徽章向末日幸存者露出了资本主义最后的惨笑。",
        en = "Crushed flat in a modified tourist souvenir crank-machine. If you catch the light just right, Mickey Mouse's flattened silhouette seems to peer through the crude academy crest, offering capitalism's final distorted grin.",
    },
    ["HAADF_t_substrate"] = {
        zh = "印有塞德拉公司标志的高角暗场显微成像机密报告。纸上密密麻麻的晶格缺陷分析与异次元基质观测记录，如今沦为了幸存者在篝火旁点烟或糊窗户缝的优质草稿纸。",
        en = "A confidential research document stamped with XEDRA insignias depicting anomalous subatomic lattice scans. While detailing reality-bending breakthroughs, desperate survivors value the clean parchment far more for rolling cigarettes and patching drafty windows.",
    },
    ["HEW_printout_data"] = {
        zh = "一张盖着深奥方程的纸质报表，末尾印着“状况正常”。在充斥着传送门风暴与异界怪物的荒原上，“一切正常”往往是研究员被拖进异次元前发出的最后一条幽默讣告。",
        en = "Dense mathematical formulas concluding with the phrase 'Status Normal.' In an apocalypse filled with interdimensional storms, 'everything is fine' is usually the last wry joke a research bunker logs before disappearing.",
    },
    ["HEW_printout_data_amigara"] = {
        zh = "报表代号“01ITO”，页面边缘满是令人毛骨悚然的人形轮廓断层扫描图。无论这些数据有多诡异，请克制住去寻找“属于你的洞穴”的致命冲动。",
        en = "Coded '01ITO' with fault-line seismology graphs. No matter how oddly tailored those humanoid fissures in the margin appear, survivors are strictly cautioned against declaring that 'this hole was made for me.'",
    },
    ["HEW_printout_data_barricaded_church"] = {
        zh = "观测点设置在一座被木板死死钉死的教堂。数据图表清晰地显示，当异常能量飙升时，祈祷的声波频率与门板被撞击的振幅呈现出极其讽刺的负相关。",
        en = "Telemetry logged from a heavily barricaded chapel. The charts document that while ambient spiritual prayers intensified exponentially, the physical structural integrity of the front oak doors declined on a straight linear slope.",
    },
    ["HEW_printout_data_cabin_reverb"] = {
        zh = "记录林间木屋回响的报表。如果林中小屋的地窖里传出复杂的声波共振，理智的废土客应该立刻转身狂奔，而不是按照旧恐怖片的套路念出羊皮纸上的拉丁文。",
        en = "CITW-series data recording audio reverberations inside a lonely forest cabin. Any sensible survivor knows that when a cellar hums in harmonic frequencies, you sprint away rather than reciting the basement diary.",
    },
    ["HEW_printout_data_cabin_reverb_dimension"] = {
        zh = "报表上的三维几何坐标全部向负四维发散。它用无可辩驳的数据证明了一件事：那间木屋的厨房在外面看起来只有五平米，但走进去之后冰箱距离水槽足足有两光年。",
        en = "Coordinate calculations that stubbornly diverge into four-dimensional non-Euclidean space, proving mathematically that while the cabin looks tiny from outside, the distance from stove to sink is roughly two light-years.",
    },
    ["HEW_printout_data_exodii"] = {
        zh = "针对外来生化机械人的电磁波谱观测记录。除了高密度的义体数据流，报告空白处还潦草地手写了一句分析员的哀嚎：“他们的机械义肢为什么连螺丝螺母都不符合公制标准？！”",
        en = "High-frequency electromagnetic surveillance on the cyborg Exodii. Scribbled in the margin beneath the data stream is a researcher's raw anguish: 'Why do none of their bionic prosthetic threads match metric or imperial?!'",
    },
    ["HEW_printout_data_highlands"] = {
        zh = "针对高地神秘现象的观测。报告里记录了剧烈的气压暴跌与地磁反转，但最离谱的结论是一行小字：“建议高地巡逻员在帽子上绑根牵引绳，以防被突然倒转的重力抛入平流层。”",
        en = "Telemetry from the highlands recording barometric crashes and magnetic inversions. The recommendation section simply advises field operatives to anchor their boots with climbing pitons against spontaneous antigravity sneezing.",
    },
    ["HEW_printout_data_inner_cabins_home_cabin"] = {
        zh = "报表底部的柱状图直冲云霄。即使看不懂量子力学，你也能从那根高耸入云的异常能量柱里领悟到一个朴素道理：别在这间屋子里吃晚饭，除非你想把汤喝进第四维度。",
        en = "The bar chart at the bottom shoots straight through the top margin. Even without a doctorate in spatial physics, you can deduce that eating dinner here risks slurping soup into the fourth dimension.",
    },
    ["HEW_printout_data_inner_cabins_open_field"] = {
        zh = "记录了一片看似平静的林中空地。平淡无奇的气象数据掩盖着令人不安的概率崩塌，在草地上打个喷嚏都可能在平行宇宙引发一场微型超新星爆发。",
        en = "Records from an apparently tranquil meadow. The dull weather readings belie catastrophic probability decay, where sneezing on a dandelion might trigger a micro-supernova in an adjacent timeline.",
    },
    ["HEW_printout_data_inner_cabins_warped_cabin"] = {
        zh = "全篇充斥着“值超出预期范围”。测量仪器的报错热情高涨，以至于分析员连方程都懒得写了，直接在页面中央画了一个巨大的问号和一个正在尖叫的火柴人。",
        en = "A solid wall of 'Value Out of Range' overflow errors. The sensor telemetry was so utterly deranged that the analyst simply drew a giant question mark and a screaming stick figure in the center.",
    },
    ["HEW_printout_data_labyrinth"] = {
        zh = "代号DB86的地下迷宫扫描。图纸显示走廊不仅会周期性自我闭合，还会根据闯入者的幽闭恐惧症程度自动延长百分之二十的拐角半径。",
        en = "Structural sonar of an underground labyrinth indicating the hallways not only rearrange periodically, but actively elongate their corridors in direct proportion to the intruder's claustrophobia.",
    },
    ["HEW_printout_data_lixa"] = {
        zh = "代号DP72063的异次元空间报告。密密麻麻的张量公式试图计算出那团流光怪物的本质，却在第四页得出结论：“该实体在热力学第二定律面前拥有完全的外交豁免权。”",
        en = "A thick stack of tensor calculus analyzing extradimensional entities, culminating in the sober conclusion that the anomaly appears to hold full diplomatic immunity against the second law of thermodynamics.",
