    ["book_nonf_soft_psych_psycstlk"] = {
        zh = "多维度探讨病态跟踪狂行为动机与心理机制的专著《跟踪心理学》。书里教受害者如何识别跟踪者的蛛丝马迹，可如今跟着你的根本不是变态暗恋者，而是一只甩都甩不掉的四足变异猎手。",
        en = "A forensic handbook exploring obsessive stalking and fixated harassment. While designed to identify human stalkers, its profiling tips surprisingly help predict the hunting patterns of relentless mutated predators.",
    },
    ["book_nonf_soft_safety_radiaea"] = {
        zh = "国际原子能机构关于防止核材料被恐怖分子走私的官方指导报告。书中制定了无比严密的核安保准则，如今满地都是炸毁的核电站反应堆，这本小册子成了历史的黑色幽默讽刺印记。",
        en = "An international monograph detailing security frameworks to protect radioactive isotopes from rogue non-state actors. With demolished reactors casually leaking glowing isotopes into municipal reservoirs, the handbook is darkly amusing.",
    },
    ["book_nonf_soft_speech_naillaw"] = {
        zh = "西装革履的律所应聘指南，在文明法治彻底荡然无存的今天，书里教的每一个谈判技巧都比不上手里的霰弹枪。",
        en = "Polished tips for acing corporate law interviews; in a world without courts, every rhetorical gambit loses to a loaded 12-gauge.",
    },
    ["book_nonf_soft_sports_bdgt"] = {
        zh = "讲述棒球俱乐部利用严苛预算与大数据分析以弱胜强的纪实小说《廉价球：在被操纵的赛局中取胜》。书里的穷鬼经营哲学让在废土精打细算利用每一发子弹的队长产生强烈精神共鸣。",
        en = "A gripping true-crime sports memoir following a penniless baseball team gaming statistical odds to triumph. Managing scarce shotgun ammunition and dry soup packets demands identical analytical ruthlessness.",
    },
    ["book_nonf_soft_sports_lads"] = {
        zh = "泛黄破旧却字字深情的经典棒球回忆录《夏日少年》。字里行间充满了上世纪五六十年代棒球场的青草香、热狗与木质球棒清脆的击球声，唤醒了废土行者心底最柔软的人性回忆。",
        en = "A worn sports memoir recounting legendary baseball seasons under sunny skies. Savoring tales of cracking wooden bats and sweet soda pop transports battle-scarred wanderers back to a gentler epoch.",
    },
    ["book_nonf_soft_sports_vlly"] = {
        zh = "带有丰富火柴人动作图解的青少年排球入门技巧平装书《排球：做好接球准备》。书里强调的双臂垫球标准手型，被某些幸存者活学活用在徒手格挡变异乌鸦俯冲撕咬的动作上。",
        en = "An energetic beginner's volleyball manual featuring stick-figure serving drills. Adapting its rigid bump-set forearm posture allows quick-thinking survivors to deflect diving mutated crows without sacrificing finger bones.",
    },
    ["book_nonf_soft_wedding_coolring"] = {
        zh = "给婚礼花童准备的可爱励志彩色图画书《当花童的十件酷事》。曾经小男孩在婚礼上捧着戒指接受全场掌声，如今在废土上如果真有人结婚，捧着两盒抗生素出场才是真正全场最酷的花童。",
        en = "A charming children's picture book detailing the joyful duties of wedding ring bearers. If anyone dares hold a wedding amidst the ruins, carrying two bottles of penicillin makes you legendary.",
    },
    ["book_nonf_zine_news_anlyst"] = {
        zh = "被誉为知识分子版读者文摘的战前深度新闻评论双周刊《分析家》。里面对经济危机与地缘博弈的严肃长篇分析，在整个世界突然被维度裂隙撕碎的瞬间全成了无聊废话。",
        en = "A pre-collapse intellectual news magazine crammed with dry policy analysis and economic forecasts. Its grave prognostications about interest rates became delightfully pointless when the sky ripped open.",
    },
    ["book_pieces"] = {
        zh = "撕碎散落的残存纸片，拼在一起可能是一首传世诗歌，也可能是一张没中奖的陈年刮刮乐彩票。",
        en = "Torn, scattered scraps of paper; glued together they might form an immortal sonnet, or an expired three-dollar scratch-off.",
    },
    ["book_pneumatics"] = {
        zh = "一本用俏皮插画讲解高压气动系统的科普书，读完能让你用自行车打气筒造出一把漏气的气枪。",
        en = "A whimsical illustrated primer on compressed air systems; equips you to build an asthmatic BB gun from a bicycle pump.",
    },
    ["book_ruined"] = {
        zh = "被黑血和酸雨彻底浸泡粘连成硬块的无名废书，除了当篝火引火物，还能用来给桌脚找平。",
        en = "A waterlogged brick of cemented pages stained in black bile; serves primarily as kindling or a shim for a wobbly workbench.",
    },
    ["booklet_firstaid"] = {
        zh = "配有卡通插图的急救折页，用极其冷静的语调指导骨折患者“保持镇定并呼叫救护车”，荒谬感拉满。",
        en = "An illustrated first-aid pamphlet calmly instructing compound fracture victims to 'remain seated and dial 911'—peak comedy.",
