    ["boomer_head"] = {
        zh = "浮肿溃烂的头颅，尽管已经身首异处，那两片泛黄的嘴唇似乎随时准备再给你喷上一脸恶臭浆液。",
        en = "A bloated, putrid severed head whose flabby lips look ready to spit foul slurry at your boots even in death.",
    },
    ["boots"] = {
        zh = "一双皮质扎实、历经沧桑的经典日常劳保皮靴。厚重的橡胶大底能稳稳踩过碎玻璃渣和生锈铁钉，虽然没有复杂的战术功能，但它是在废土上陪伴你走过千山万水的最忠实老友。",
        en = "Tough, unpretentious leather work boots built for grinding daily labor. Their thick lugged rubber soles effortlessly crush broken glass and rusty nails, faithfully carrying survivors across countless devastated miles.",
    },
    ["boots_acidchitin"] = {
        zh = "由精心修整打磨的硅化酸蚁外骨骼缝合拼接而成的特种防酸战靴。表面光滑且耐腐蚀，直接踩进冒着刺鼻气泡的高浓度强酸积水坑里，靴底连一丝烟都不会冒。",
        en = "Specialty protective boots fashioned from smoothed biosilicified insect carapaces. Stomping straight through steaming puddles of industrial vitriol, the polished chitin sheds acid without releasing a single puff of smoke.",
    },
    ["boots_bone"] = {
        zh = "在真皮表面密密麻麻缝满了微雕人骨与神秘符咒的异端皮靴。走在寂静的走廊里甚至能听到骨片摩擦发出的清脆细语，不仅防咬极佳，还能极大震撼迷信土匪的心灵。",
        en = "Macabre leather boots shingled with intricately carved bone fragments and strange sigils. Clattering softly on asphalt, their grotesque defensive plating terrifies superstitious scavengers before they can draw weapons.",
    },
    ["boots_bunker"] = {
        zh = "带有重型防砸钢包头与超厚阻燃橡胶层的消防员灭火救援靴。不仅能从容踩过熊熊燃烧的废弃汽车轮胎，哪怕头顶砸下一块沉重的水泥板，你的脚趾也能在钢头护盾下安然无恙。",
        en = "Heavy steel-toed rubber boots originally issued to urban structural firefighters. Walking through blazing pools of burning gasoline without flinching, the rigid caps protect toes from falling concrete rubble.",
    },
    ["boots_chitin"] = {
        zh = "用巨大甲虫背甲缝制而成的足套，防刺效果极佳，走起路来像两只小螃蟹在水泥地上咔嗒作响。",
        en = "Foot wraps cobbled from giant beetle carapaces; puncture-proof, yet clicks across pavement like a pair of tap-dancing crabs.",
    },
    ["boots_combat"] = {
        zh = "军规标准的现代高帮战术军靴。鞋帮对脚踝提供了完美的锁定支撑，在碎砖乱石堆里狂奔跃进绝不会崴脚，坚固的防穿刺鞋底更是让暗藏的铁丝网陷阱无功而返。",
        en = "Modern tactical military combat boots built to survive punishing combat deployments. Lacing them tight locks the ankles against sprains when jumping through rubble, while reinforced shanks stop punji stakes dead.",
    },
    ["boots_denim"] = {
        zh = "用多层厚实牛仔裤布料手工拼合缝制的高帮牛仔布靴。透气轻便且清洗方便，虽然抵挡不住重武器践踏，但在炎热的夏日废土上散步，能让你的双脚免受捂汗恶臭之苦。",
        en = "Handcrafted ankle boots stitched from salvaged layers of heavy denim work jeans. Breathable and easily washed in clean streams, they spare feet from blistering sweat during sweltering midsummer scavenger runs.",
    },
    ["boots_faux_fur"] = {
        zh = "人造毛皮靴看起来毛茸茸很可爱，直到你在沼泽泥地里踩上一脚，它就会吸水膨胀成两枚十磅重的铅球。",
        en = "Cute and fuzzy faux-fur boots until you step into marsh mud, where they soak up moisture like two ten-pound lead bricks.",
