    ["bot_lab_security_drone_GR"] = {
        zh = "配备微型侦察雷达的高阶巡逻机，只要接通电池，两秒钟内就能把整栋建筑里的生命信号查个底朝天。",
        en = "An advanced surveillance drone with micro-radar; powers up in two seconds to unmask every breathing organism in the bunker.",
    },
    ["bot_lab_security_drone_YM"] = {
        zh = "亮黄色高可见度涂装的工业安检无人机，即使处于关机状态，鲜艳的外壳也在向全世界宣告“这里有高压危险”。",
        en = "A high-visibility yellow inspection drone whose dormant chassis still screams 'Hazardous Voltage' to anyone within eye-shot.",
    },
    ["bot_manhack"] = {
        zh = "高速旋转的不锈钢锋利圆锯加上飞行推进器，是每一个缺乏护甲保护的幸存者最纯粹的噩梦具象化。",
        en = "A buzzing circular saw mounted to high-RPM micro-rotors; the unadulterated nightmare of anyone caught without a Kevlar vest.",
    },
    ["bot_nl_surgicalbot"] = {
        zh = "伸出七八根精密手术臂的怪异骨骼机器人，在没有麻醉药的世界里，它的关机状态让人倍感温馨。",
        en = "An eerie robotic spider with eight articulated surgical scalpels; in a world without anesthesia, its 'off' switch is a blessing.",
    },
    ["bot_nursebot"] = {
        zh = "用毫无感情的合成电子音向你询问“哪里不舒服”的医护铁傀儡，通常回答“浑身都疼”会被直接打一针镇静剂。",
        en = "A synthesized nurse asking 'Where does it hurt?'; replying 'Everywhere' immediately triggers an involuntary horse sedative.",
