    ["bot_prototype_cyborg"] = {
        zh = "实验早期的粗糙改造人样品，电线和烂肉杂乱缠绕在一起，完美展现了战前疯狂科学家的审美灾难。",
        en = "An early-generation cyborg prototype; tangled wires and rotting flesh demonstrate the aesthetic catastrophe of pre-war mad science.",
    },
    ["bot_rifleturret"] = {
        zh = "顶着一挺M249班用机枪的遥控防御塔，虽然处于断电状态，那根黑洞洞的枪管依然让人脊背发凉。",
        en = "An automated turret mounting an M249 SAW; even completely powered down, that dark muzzle chills you to the marrow.",
    },
    ["bot_robofac_camspy"] = {
        zh = "只有拳头大小的超静音谍报浮游球，悄无声息地记录你的每一个狼狈瞬间并实时上传到某个未知服务器。",
        en = "A palm-sized whisper-silent camera drone, covertly filming your most humiliating foraging blunders for a mysterious server.",
    },
    ["bot_robofac_hound"] = {
        zh = "四足行走的钛合金机械猎犬，既不会掉毛也不会摇尾巴，只会不知疲倦地用激光测距仪锁死你的咽喉。",
        en = "A quadrupedal titanium hound that neither sheds nor wags; it simply paints your throat with targeting lasers without blinking.",
