    ["bot_robofac_skittergun"] = {
        zh = "像蜘蛛一样多足爬行并架设冲锋枪的小型根除者，在狭窄走廊里突然启动的声音能吓掉你半条命。",
        en = "A multi-legged scuttling sentry armed with an SMG; hearing its servomotors spin up in a hallway takes ten years off your life.",
    },
    ["bot_science_bot"] = {
        zh = "曾经用来在无菌隔离室里搬运试管的科研助理，被临时焊上一挺防暴枪后，看起来就像个愤怒的电饭煲。",
        en = "A cleanroom lab bot hastily welded with riot guns, transformed from a harmless pipette carrier into an enraged pressure cooker.",
    },
    ["bot_secubot"] = {
        zh = "履带底盘的鹰爪无人地面战车，坚固沉重得像块钢铁巨石，唯一的缺点是爬不过稍微高一点的马路牙子。",
        en = "A tracked UGV resembling an armored boulder; impenetrable to small arms, yet utterly defeated by a four-inch concrete curb.",
