    ["bot_turret_searchlight"] = {
        zh = "百万流明的军用自动探照灯，一开机就能把黑夜照成正午，顺便把你视网膜上的感光细胞彻底烧焦。",
        en = "A million-lumen military searchlight; turns pitch midnight into blistering noon and incinerates your retinas in one pulse.",
    },
    ["bot_turret_speaker"] = {
        zh = "高音量防暴扩音警报器，不知疲倦地向废墟广播“请居民待在家中等待救援”，堪称末日最讽刺的背景音乐。",
        en = "An automated loudspeaker loop cheerfully repeating 'Please remain indoors and await rescue'—the wasteland's finest dark comedy.",
    },
    ["bot_yrax_delta"] = {
        zh = "形状像一把三角形金属飞镖的不可理解外星构件，摸起来没有任何缝隙，安静得像一块沉睡的墓碑。",
        en = "An inscrutable triangular alien construct with zero visible seams, resting on the floor as quietly as a polished tombstone.",
    },
    ["bot_yrax_triakis"] = {
        zh = "带有三条蛇状机械足的多面晶体，既像外星古董雕塑又像沉睡的兵器，让人完全不知道该从哪一头下手拆解。",
        en = "A geometric crystal supported by three serpentine metal struts; part sculpture, part dormant weapon, and totally un-salvageable.",
    },
    ["bot_yrax_trifacet"] = {
        zh = "表面光滑如镜的石英金字塔结构体，任何企图用大铁锤敲碎它的幸存者，最后都被反震得手腕脱臼。",
        en = "A featureless quartz pyramid so impenetrable that anyone trying to smash it with a sledgehammer merely dislocates their wrists.",
