        en = "Societies rose and fell within millennia, but this ubiquitous petroleum artifact will calmly endure four hundred years of acid rain and radioactive fallout. Long after our bones turn to dust, alien archeologists will conclude plastic bottles were our sacred religious totems.",
    },
    ["bottle_plastic_355ml"] = {
        zh = "一只容积三百五十五毫升的密封轻便塑料小水瓶。清洗干净后灌满煮沸的干净泉水塞进贴身口袋，在烈日炎炎的废土公路上长途行军时，每一滴都是救命琼浆。",
        en = "A compact watertight plastic beverage bottle holding 355 milliliters. Stashed inside a jacket pocket and filled with boiled rainwater, each measured sip keeps heatstroke at bay along scorched highways.",
    },
    ["bottle_plastic_glue"] = {
        zh = "一只装有半升强力合成胶水的高密度聚乙烯塑料瓶。无论是修补开裂的防暴盾牌、粘合靴底还是自制简易复合弓，这瓶黏稠的工业胶水都是废土作坊里的万能神药。",
        en = "A durable polyethylene bottle holding 500 mL of industrial-strength synthetic adhesive. Vital for bonding split leather boot soles, mending cracked riot shields, and assembling makeshift composite bows.",
    },
    ["bottle_plastic_pill_painkiller"] = {
        zh = "白色塑料止痛药瓶，当你在药柜里摇晃出清脆的药片碰撞声时，那种快感比搜刮到一把重机枪还要美妙。",
        en = "A white plastic pill bottle; the joyful rattle of tablets inside delivers a rush more euphoric than finding an intact machine gun.",
    },
    ["bottle_plastic_pill_prescription"] = {
        zh = "半透明橘黄色处方药瓶，撕掉的标签上看不清是抗生素还是维生素，全靠幸存者用舌尖来赌命。",
        en = "An amber prescription bottle with torn labels; whether it holds penicillin or sleeping pills is a gamble settled by your tongue.",
    },
    ["bottle_plastic_pill_supplement"] = {
