    ["bouquet"] = {
        zh = "彻底干枯发脆的陈年花束，花瓣一碰就变成灰，但在满是腐烂气息的废土上，枯萎的花香依然是一种奢望。",
        en = "Brittle, dried-up flowers that crumble to dust; yet amid the stench of decay, faint floral dust is a luxury commodity.",
    },
    ["bow_saw"] = {
        zh = "弓形钢架绷紧的长锯条，锯木头时沙沙作响，锯到深处被树干夹住时，能让你深刻体验到进退两难的人生哲学。",
        en = "A bow saw with a tensioned blade; slices wood effortlessly right until the kerf pinches the blade in existential paralysis.",
    },
    ["bow_scope"] = {
        zh = "装在弓把上的放大瞄准镜，让你能在五十米外看清僵尸脸上的每一个黑头，以及自己根本射不中它的事实。",
        en = "A magnifying scope for archery; lets you count a zombie's blackheads at fifty yards while missing the target completely.",
    },
    ["bow_sight"] = {
        zh = "带有五个不同距离光纤瞄针的专业弓瞄，在狂暴丧尸冲刺过来的三秒钟里，你根本分不清该用哪根针。",
        en = "Five colored fiber-optic pins; as a feral brute charges across twenty feet, you'll have zero clue which pin to align.",
    },
    ["bow_sight_pin"] = {
        zh = "只有一根细铝针的极简弓瞄，虽然不如五针弓瞄花哨，但至少不会让你在紧张时犯选择困难症。",
        en = "A single aluminum pin sight; lacks tactical flair, but spares you the luxury of choice paralysis while getting ambushed.",
    },
    ["bow_silencer"] = {
        zh = "绑在弓弦上的小橡胶减震垫，能把弓弦回弹的“嗡”声降到最低，防止树上的鸟群嘲笑你脱靶的箭矢。",
        en = "Rubber dampeners bound to the bowstring; muffles the twang so forest crows don't mock your embarrassing missed shots.",
    },
    ["bow_sling"] = {
        zh = "套在持弓手手腕上的尼龙软带，确保你放箭后战弓不会滑脱飞出，顺便把弓砸向自己脑门的可能性降到零。",
        en = "A wrist sling preventing your expensive compound bow from flying into the brush upon release and bonking your own nose.",
    },
    ["bow_stabilizer"] = {
        zh = "向前伸出的碳素平衡长杆，虽然大幅减少了射击时的微小晃动，但钻进密林时总会像根鱼竿一样四处挂草。",
        en = "A forward stabilizing rod that dampens hand tremors, while expertly snagging on every briar bush in the dense forest.",
    },
    ["bow_stabilizer_set"] = {
        zh = "前杆与侧杆构成的专业平衡配重系统，装上后你的猎弓看起来像个便携式人造卫星天线，帅气值突破天际。",
        en = "A full stabilizer matrix that turns your hunting bow into a portable orbital satellite dish; peak tactical vanity.",
    },
    ["bowhat"] = {
        zh = "坚硬笔挺的黑色圆顶礼帽，让你即便浑身沾满丧尸黑血，只要微微抬一抬帽檐，依然是个地道的维多利亚绅士。",
        en = "A stiff black bowler hat; even drenched in zombie ichor, tipping the brim instantly restores your Victorian gentleman poise.",
    },
    ["bowl_clay"] = {
        zh = "粗陶土捏制烧结的汤碗，表面带着手工不规则的凹坑，装上热汤后端在手里，是废土冬夜最真实的幸福。",
        en = "A rough clay bowl with rustic thumbprints; cradling it full of hot broth is the purest luxury available in winter.",
    },
    ["bowl_coconut"] = {
        zh = "半个锯开打磨干净的坚硬椰子壳，装水盛饭两相宜，敲在同伴头上还能发出轻快动听的空心回响。",
        en = "Half a polished coconut husk; holds stew admirably and produces a delightful hollow chime when tapped against a friend's skull.",
    },
    ["bowl_pewter"] = {
        zh = "带着暗淡金属光泽的古朴锡碗，导热快得能把你的指尖烫掉一层皮，逼迫你以破纪录的速度把热汤喝完。",
        en = "A pewter serving bowl that conducts heat so brutally it blisters your fingers, forcing you to chug your soup at world-record speed.",
    },
    ["bowl_plastic"] = {
        zh = "密封盖早就松动了，但依然是末日里最可靠的剩饭保险库；只要别去闻上一位主人在里面留下的变质肉酱味。",
        en = "The snap-on lid lost its airtight seal years ago, yet it remains your premier vault for questionable scavenged stew. Just never inhale when unsealing it.",
    },
    ["bowl_skull"] = {
        zh = "用敌人的头盖骨盛麦片确实霸气外露，但在你端起它喝汤的那一刻，深邃的眼窝总是冷冷盯着你贪婪的下巴。",
        en = "Eating instant oatmeal from a human cranium asserts undeniable wasteland dominance, right up until those hollow eye sockets stare directly into your greedy chewing mouth.",
    },
    ["bowl_wood"] = {
        zh = "边缘坑坑洼洼的手削木碗，每次喝汤都附赠三根木刺和淡淡的松脂苦味，可以说是纯天然粗纤维的最佳来源。",
        en = "A crude hand-carved basin that seasons every broth with three tiny splinters and a distinct resin tang, providing your daily intake of raw woodland roughage.",
    },
    ["bowl_wood_large"] = {
        zh = "容积大到能直接当洗脸盆的巨型木碗，通常用来拌一大锅野菜杂烩，或者在暴雨夜接住避难所漏下的泥水。",
        en = "Large enough to double as a washbasin, this hefty wooden trough excels at mixing wilderness weed porridge or catching filthy ceiling leaks during acid rainstorms.",
    },
    ["bowling_ball"] = {
        zh = "六公斤重的实心树脂球，指孔里塞满了陈年污垢；在保龄球馆早已化为废墟的今天，它最好的归宿是从二楼砸向丧尸脑门。",
        en = "A fourteen-pound solid resin sphere whose finger holes harbor ancient dirt; with the lanes demolished, its ultimate destiny is dropping onto a zombie's skull from a balcony.",
    },
    ["bowling_pin"] = {
        zh = "漆皮剥落的硬木球瓶，重心完美且手感沉重，在球道上它是靶子，在幸存者手里它是一根尊贵的白漆棒球棍。",
        en = "A scuffed maple pin with surprisingly wicked heft; on the polished alley it was an easy target, but out in the ruins it becomes an aristocratic bludgeon.",
    },
    ["box_battery_charger"] = {
        zh = "塞在粗糙木盒里的简易蓄电池充电器，没有电网的它只是一堆毫无生气的电线，正安静等待发电机或雷击的降临。",
        en = "A jury-rigged charging rig packed into a timber crate; disconnected from the grid, it rests as inert wiring until an alternator or lightning bolt revives it.",
    },
    ["box_cigarette"] = {
        zh = "侧面印着的吸烟有害健康警告在满街食尸鬼面前显得无比幽默，对幸存者而言，尼古丁是唯一比现实更温和的毒药。",
        en = "The ominous health warnings on the cardboard flap seem hilarious next to roving feral ghouls; nicotine remains the gentlest poison available in the apocalypse.",
    },
    ["box_compact_wood"] = {
        zh = "带有两个小提手的小巧木盒，既能装下你最珍贵的缝纫针和引信，也足以充当一只变异仓鼠的体面棺材。",
        en = "A petite timber box with twin brass handles, spacious enough for your precious firing pins or serving as a dignified casket for an unlucky mutant hamster.",
    },
    ["box_large"] = {
        zh = "足够让孩童筑起梦幻城堡的巨大瓦楞纸箱，在灾后是潜行大师的终极掩体，直到突如其来的雨水把它泡成烂泥。",
        en = "A colossal corrugated carton that once built childhood forts, now serving as an apex stealth hideout until the first rainfall melts your fortress into mush.",
    },
    ["box_large_folded"] = {
        zh = "被压扁捆扎的大纸箱，携带时像一块巨大的盾牌，展开后却能在水泥地上为你提供一整晚微弱而体面的隔凉防护。",
        en = "Flattened into a giant cardboard shield for easy hauling, ready to unfold across cold concrete to grant one night of marginally dignified insulation.",
    },
    ["box_large_metal"] = {
        zh = "沉重、冰冷且坚不可摧的铁皮大箱，即使整个屋顶塌下来也砸不扁它，是防止变异老鼠偷吃你干肉的最后防线。",
        en = "A ponderous iron vault that could survive a collapsing rafters collapse, representing the final impregnable defense separating your smoked jerky from irradiated rodents.",
    },
    ["box_large_reinforced"] = {
        zh = "贴满了双层厚纸板和胶带的加固大箱，抗压能力明显提升，但依然逃不过被潮湿雨夜彻底软化解体的悲惨宿命。",
        en = "Doubled up with extra fluting and yards of duct tape; it boasts superior rigidity right up until damp night air reduces it to soggy paper mache.",
    },
    ["box_large_wood"] = {
        zh = "钉得结结实实的货运大木箱，只要撬开上面那排生锈铁钉，不仅能获得宽敞的储物空间，还能拆下几根防身木料。",
        en = "A rugged shipping crate bound by rusty nails; prying open the lid yields cavernous storage space alongside a few splintery planks suitable for beating intruders.",
    },
    ["box_longarm"] = {
        zh = "细长而不起眼的军械瓦楞纸盒，外面印着无害的体育用品商标，里面却曾经整整齐齐地躺着能撕裂肉体的猎枪。",
        en = "A discreet, elongated shipping carton stamped with innocuous sporting goods logos, designed to ferry high-caliber long guns past overly nosy neighbors.",
    },
    ["box_medium"] = {
        zh = "最经典的香蕉箱尺寸，搬家公司的忠实伙伴；在废土上，它里面通常塞满了螺栓、旧电池和半卷用脏的手纸。",
        en = "The archetypal grocery box beloved by movers; in the ruins, it reliably holds an untidy mountain of loose bolts, dead batteries, and half-spent toilet paper.",
    },
    ["box_medium_folded"] = {
        zh = "折叠收纳的中号纸盒，平整得可以塞进背包侧缝，是你每次在超市货架前突发贪念时的应急收纳法宝。",
        en = "A collapsed paper carton tucked flat against your rucksack, ready to expand whenever sudden greed strikes in the middle of a ransacked supermarket aisle.",
    },
    ["box_medium_metal"] = {
        zh = "泛着油光的金属方盒，合页关上时发出沉闷的咔哒声，给人一种即使末日核爆也伤不到里面半颗螺丝的虚假安全感。",
        en = "An oiled steel chest that latches with a solid thud, radiating the false confidence that an apocalyptic shockwave couldn't dent the spare washers inside.",
    },
    ["box_medium_wood"] = {
        zh = "带有粗糙木纹和松木气味的结实木箱，无论是放在避难所角落当凳子坐，还是装满罐头藏进地窖，都格外沉稳。",
        en = "A sturdy pine container with rough-sawn planks; equally content serving as a makeshift stool around the camp hearth or holding canned peaches in a root cellar.",
    },
    ["box_oversize"] = {
        zh = "巨大到足以塞进一根排气管或一整把长柄大锤的超长纸箱，拖着它在废墟穿行时，总让人觉得自己像个滑稽的搬运工。",
        en = "An extraordinarily long carton accommodating whole exhaust pipes or sledgehammers, turning anyone dragging it through the ruins into a comical moving-day silhouette.",
    },
    ["box_oversize_folded"] = {
        zh = "卷起来甚至能当瑜伽垫的超长折叠纸盒，虽然收纳时很省空间，但一旦在强风中展开，整个人就像在操控滑翔翼。",
        en = "Rolled so flat it resembles an exercise mat; while wonderfully portable, opening it during a gusty breeze turns you into an unwilling cardboard hang glider.",
    },
    ["box_oversize_metal"] = {
        zh = "长度惊人的重型金属储物箱，通常用来装车载大口径枪管或传动轴，空箱抬起来就足以把幸存者的老腰彻底扭伤。",
        en = "An elongated steel locker meant for heavy drive shafts or machine gun barrels; lifting it empty is enough to permanently misalign your lower vertebrae.",
    },
    ["box_oversize_reinforced"] = {
        zh = "用多层硬纸板压合加固的特长箱子，虽然号称防压耐摔，但在大雨里浸泡十分钟后，软烂程度并不会比普通纸箱慢多少。",
        en = "A heavily corrugated extra-long carton boasting double walls; impressive structural strength that lasts precisely ten minutes once exposed to driving rain.",
    },
    ["box_oversize_wood"] = {
        zh = "宛如长条棺木一般的厚重木箱，沉重得必须两人合力抬运；如果末日没有足够的战利品填满它，躺进去睡觉倒也宽敞。",
        en = "A ponderous wooden crate bearing uncomfortable resemblance to a coffin; if you lack enough loot to fill its depths, it makes a remarkably drafty bunk.",
    },
    ["box_paper_small"] = {
        zh = "脆弱得一捏就扁的小纸盒，原本装着名牌手表或高档点心，如今却用来保护幸存者仅剩的三颗抗生素。",
        en = "A fragile little paper sleeve that once packaged gourmet chocolates, now entrusted with safeguarding the survivor's last three precious antibiotic capsules.",
    },
    ["box_pistol"] = {
        zh = "内衬开孔海绵的高抗冲工程塑料枪盒，外表看起来专业冷酷，打开后里面躺着的可能只是一把生锈的土制转轮手枪。",
        en = "A foam-lined polymer case that screams tactical professionalism, even if the weapon currently nestled inside is a pitted pipe pistol held together by wire.",
    },
    ["box_retool"] = {
        zh = "塞满了弹簧、衬套与转接座的步枪改装纸盒，只要你拥有足够的机械常识，就能把普通的猎枪调教成凶狠的军用杀器。",
        en = "A printed box brimming with springs, bushings, and adaptors; with enough mechanical know-how, it transmutes civilian hunting rifles into ravenous military carbines.",
    },
    ["box_retool_huge"] = {
        zh = "专为精密射击设计的豪华改装套件，厚重的包装箱仿佛在向每一位狙击手保证：只要装上它，远处的丧尸脑壳就会准时开花。",
        en = "A lavish conversion ensemble for precision riflecraft; the weighty packaging virtually promises every wandering marksman a pinpoint headshot across empty highways.",
    },
    ["box_retool_large"] = {
        zh = "沉甸甸的长管步枪改装箱，里面的精密零件散发着机油味，能让你的步枪拥有更长的枪管、更远的射程和更让人肉疼的后坐力。",
        en = "A heavy kit box reeking of industrial grease; its contents grant your rifle greater barrel length, extreme effective range, and shoulder-fracturing recoil.",
    },
    ["box_retool_sbr"] = {
        zh = "短管步枪改装套件，舍弃了多余的枪管长度以换取在逼仄走廊里的敏捷身法，哪怕枪口喷出的火球会闪瞎你自己的眼睛。",
        en = "A short-barreled rifle transformation set that trades muzzle velocity for hallway maneuverability, even if the resulting fireball temporarily blinds the shooter.",
    },
    ["box_retool_sbr_micro"] = {
        zh = "极致轻量化的微型卡宾枪套件，把原本威猛的步枪压缩成冲锋枪尺寸，完美诠释了废土巷战中什么叫做狭路相逢火力猛。",
        en = "An ultracompact carbine kit squeezing full-sized rifle mechanisms into submachine dimensions, epitomizing furious close-quarters panic in narrow stairwells.",
    },
    ["box_small"] = {
        zh = "不到一尺见方的小纸盒，丢在角落平平无奇，但如果你在里面翻出了一整包未开封的火柴，那它就是你的黄金宝箱。",
        en = "An unassuming cubic foot of cardboard sitting in a closet corner, instantly elevated to legendary treasure status if you uncover dry wooden matches inside.",
    },
    ["box_small_folded"] = {
        zh = "压平的小纸盒，薄得可以夹在战术背心里面；在废墟搜刮零碎小物件时，它能迅速撑开变成你的便携杂物兜。",
        en = "A flattened carton slipped flat into a vest pouch, ready to spring into a three-dimensional container whenever valuable pocket litter is discovered.",
    },
    ["box_small_metal"] = {
        zh = "密封严实的小铁盒，无论装满引信、雷管还是珍贵的香料，坚硬的金属壳都能确保里面的宝贝不会被一脚踩碎。",
        en = "A compact tin box that clicks shut tight; whether packed with blasting caps or dried rosemary, its walls prevent total crushing under clumsy combat boots.",
    },
    ["box_small_plastic"] = {
        zh = "带有坚固锁扣和橡胶密封圈的防护塑料盒，即使掉进满是污血的水坑里，里面的电子元件也能安然无恙地保持干燥。",
        en = "A rugged polymer case with locking clasps and rubber gaskets, keeping delicate electronics bone-dry even when dropped into puddles of foul sewage.",
    },
    ["box_small_wood"] = {
        zh = "做工精巧的小木盒，榫卯严丝合缝，曾经装过名贵的雪茄或珠宝，现在成了幸存者存放几枚幸运子弹的体面居所。",
        en = "A handsomely mortised trinket box that once pampered luxury cigars, now demoted to housing three lucky cartridges and a rusty lockpick.",
    },
    ["box_snack"] = {
        zh = "印着快乐卡通形象的零食包装盒，可惜里面的膨化食品早就变成了灰尘，只留下褪色的糖衣炮弹在向你嘲弄昔日文明。",
        en = "A colorful snack carton bearing faded cartoon mascots; the chips within crumbled to dust decades ago, leaving only nostalgic marketing to mock your hunger.",
    },
    ["box_tea"] = {
        zh = "散发着微弱茉莉香气的红茶纸盒，在开水比黄金还金贵的末日，哪怕只泡出一杯微涩的热水，也足以告慰战栗的灵魂。",
        en = "A tea packet box clinging to ghostly floral aromas; in a frozen ruined world, steeping a single dry sachet brings immense psychological salvation.",
    },
    ["boxcutter"] = {
        zh = "刀片可以随时折断换新的美工开箱刀，虽然划开纸箱轻而易举，但如果拿它去捅狂暴丧尸的皮肉，刀刃很可能当场报废。",
        en = "A utility cutter with snap-off razor blades; exquisite for slicing packing tape, thoroughly catastrophic if plunged against the calcified hide of a zombie.",
    },
    ["boxer_briefs"] = {
        zh = "兼具平角裤宽松透气与三角裤贴身支撑的平角紧身内裤。弹性棉料完美包裹大腿根部，哪怕背着几十公斤物资在废墟里狂奔一整天，也绝不会发生尴尬的大腿磨皮擦伤。",
        en = "Comfortable boxer briefs offering optimal thigh support and breathable freedom. Woven from soft cotton, they prevent chafing during grueling cross-country scouting treks laden with heavy rucksacks.",
    },
    ["boxer_shorts"] = {
        zh = "剪裁宽松、通风极佳的男士纯棉平角短裤。虽然在剧烈奔跑时偶尔会堆叠卷边，但在酷热难耐的夏日庇护所里光着膀子单穿它晃悠，堪称末日里难得的惬意时光。",
        en = "Loose-fitting cotton boxer shorts prioritizing maximum ventilation. Occasionally bunching up during frantic sprints away from hounds, loungeing in them beside quiet campfires brings rare domestic serenity.",
    },
    ["boxing_gloves"] = {
        zh = "鲜红厚重的八盎司皮质拳套，原本是为了在拳台上保护对手的脑震荡，现在戴上它去揍丧尸只会让你的重拳变得软绵无力。",
        en = "Crimson padded gloves engineered to keep prizefighters from breaking each other's skulls, a courtesy that feels rather misplaced when punching decomposing ghouls.",
    },
    ["boxpack"] = {
        zh = "用两条破背带绑在旧木箱上改造出来的自制背包，背在身上硬得像块墓碑，每走一步都会沉重地敲打你的脊椎骨。",
        en = "A wooden crate strapped to canvas webbing; wearing it resembles carrying a square tombstone that gleefully hammers your lumbar spine with every stride.",
    },
    ["boy_shorts"] = {
        zh = "弹性良好且剪裁舒适的女式平角内裤，在缺乏换洗衣物的末日废土上，能穿上一条干爽干净的内裤已经是顶级的精神慰藉。",
        en = "Snug and breathable stretch cotton shorts; in a filth-encrusted wasteland where laundry is an ancient memory, dry clean undergarments are pure ecstasy.",
    },
    ["bp_10mm_fmj"] = {
        zh = "填装粗制黑火药的手工复装十毫米全金属被甲弹。击发时枪口喷出的浓烈硫磺白烟能把射手彻底呛哭，但沉重的十毫米弹头依然能把扑来的丧尸打得原地翻滚倒地。",
        en = "Handloaded 10mm Auto cartridges fueled by coarse black powder. While releasing choking clouds of sulfurous white smoke that blind the shooter, the heavy brass-jacketed slug drops charging biters hard.",
    },
    ["bp_10mm_jhp"] = {
        zh = "塞满黑火药与空尖被甲弹头的十毫米自制弹药。虽然黑火药的残渣在三枪之内就会把枪管糊得满是黑灰，但在近距离命中变异怪时炸开的空腔依然令人叹为观止。",
        en = "Hollow-point 10mm rounds hand-filled with black powder. The corrosive fouling rapidly coats firearm chambers in gritty carbon, yet the expanding hollow cavity stops aggressive monstrosities in their tracks.",
    },
    ["bp_123ln"] = {
        zh = "来自平行异界的神秘口径黑火药复装弹。在生锈弹壳里塞满自制黑火药后初速大减，开枪时声势如同小型火铳，刺鼻的黑烟能让周围的游荡丧尸都陷入短暂懵逼。",
        en = "Exotic alternate-dimension cartridges handloaded with homemade black powder. Reduced velocity turns the firearm into an impromptu miniature cannon, spewing pungent smoke that confuses approaching ghouls.",
    },
    ["bp_123ln_ap"] = {
        zh = "装有穿甲钢芯的异界口径黑火药子弹。尽管黑火药推力疲软导致弹头初速打折，但那枚硬质合金弹芯在近距离命中轻型装甲时，依然能凭借高硬度勉强钻出孔洞。",
        en = "Armor-piercing foreign cartridges fueled by improvised black powder charges. Despite sluggish propulsion from degraded propellant, the hardened steel core manages to pierce light scrap plating at point-blank distances.",
    },
    ["bp_223"] = {
        zh = "用黑火药强行复装的点二二三步枪小口径子弹。原本清脆的高速击发变成了沉闷的放屁巨响，几发子弹过后自动步枪的导气管就会被黑火药油垢彻底堵死变成手动大栓。",
        en = "Small-caliber .223 rifle cartridges loaded with smoky black powder. The combustion byproducts instantly foul delicate direct-impingement gas tubes, turning semi-automatic rifles into clumsy manual bolt-actions.",
    },
    ["bp_22_fmj"] = {
        zh = "手工装填黑火药的边缘发火点二二被甲弹。威力微弱得像是气枪子弹，击发时的青烟甚至比子弹飞得还慢，但用来在无风树林里悄悄猎杀松鼠依然绰绰有余。",
        en = "Pivotal .22 LR rimfire cartridges repackaged with sulfurous black powder. Pushing featherweight lead at modest velocities, they remain quiet and practical for potting squirrels in overgrown suburban backyards.",
    },
    ["bp_22_lr"] = {
        zh = "使用纯铅弹头与黑火药复装的点二二微型子弹。极易受潮哑火，虽然打在丧尸头盔上只能留下一点黑印，但在子弹匮乏的初期，有它总好过拿着树枝跟敌人对峙。",
        en = "Bare-lead .22 cartridges primed with coarse black powder. Prone to moisture-induced misfires and leaving heavy barrel fouling, having twenty in a pocket still beats brandishing bare fists.",
    },
    ["bp_270win_fmj"] = {
        zh = "装入黑火药的温彻斯特点二七零全金属猎枪弹。出膛瞬间伴随着巨大的火球与漫天硫磺烟雾，原本优雅的平直弹道全被糟蹋了，但千米之外的声响足够吓退变异狼群。",
        en = "Classic .270 hunting rounds reloaded with black powder. Sacrificing their legendary flat trajectory for thunderous roars and billowing smoke, the booming concussion easily scares away stalking mutant wolves.",
    },
    ["bp_270win_jsp"] = {
        zh = "软尖被甲配合黑火药复装的点二七零猎鹿弹。虽然黑火药推力不足降低了初速，但软铅尖头在撞击中型变异野兽时依然能发生良好形变，换来一顿丰盛的鲜肉晚餐。",
        en = "Soft-point hunting cartridges recharged with smoky black powder. While muzzle velocity drops considerably, the soft lead nose expands cleanly upon striking feral deer, putting hearty meat on camp roasting spits.",
    },
    ["bp_3006"] = {
        zh = "在老牌斯普林菲尔德步枪弹壳里填满黑火药的复装弹。一枪击发宛如南北战争时期的老式前装滑膛枪重现，射手必须在打完一枪后退后三步等待浓烟散去才能看清目标。",
        en = "Vintage .30-06 casings handloaded with black powder. Firing it evokes memories of civil war musketry, forcing riflemen to wait several seconds for acrid sulfur clouds to drift before re-acquiring targets.",
    },
    ["bp_3006_incendiary"] = {
        zh = "填装黑火药的点三零零六曳光弹。在火药本身的滚滚浓烟中拖着一道明亮火迹冲向目标，既能修正弹道，落入干草堆时还能顺便引发一场驱散尸群的冲天大火。",
        en = "Tracer rounds loaded with black powder that ignite downrange targets. Tracing a brilliant fiery path through billowing black smoke, they double as fiery signals and improvised brushfire starters.",
    },
    ["bp_3006_jsp"] = {
        zh = "使用软头弹丸与黑火药复装的点三零零六全威力弹。沉重的弹头在击中变异大野猪时能够彻底释放动能，前提是你开枪后能忍住那股刺鼻的烂鸡蛋味硫磺气体熏眼。",
        en = "Heavy soft-point rifle rounds resurrected with black powder. Delivering blunt kinetic transfer into charging mutated boars, you must squint past stinging rotten-egg fumes to chamber your next round.",
    },
    ["bp_3006fmj"] = {
        zh = "内嵌硬化钢芯的黑火药复装点三零零六穿甲弹。尽管黑火药带来的初速度大不如前，但厚实的穿甲钢芯在近距离依然能强行击穿丧尸巡警身上的旧式轻钢防弹插板。",
        en = "Steel-core armor-piercing cartridges handloaded with black powder charges. Despite diminished muzzle velocity, the hardened core punches reliably through mild scrap metal and reinforced ballistic vests at close range.",
    },
    ["bp_300_winmag"] = {
        zh = "把黑火药塞进超大马格南弹壳里的自制巨弹。枪口喷出的火焰长达两米，宛如手持小型火焰喷射器，强烈的震波能让趴在旁边的观察手耳朵嗡嗡作响一整天。",
        en = "Massive magnum rifle casings crammed with black powder charges. Spewing a six-foot gout of blinding muzzle flame, the concussive pressure wave leaves nearby spotters nursing ringing ears all afternoon.",
    },
    ["bp_300blk"] = {
        zh = "用黑火药复装的三百点黑曜石战术步枪弹。虽然开火时产生了大量无法消音的烟雾与残渣，但重弹头在近距离遭遇战中依然能展现出干净利落的致命停止力。",
        en = ".300 Blackout rounds packed with black powder. Completely defeating the purpose of modern sound suppression with thick smoke, the heavy open-tip projectile still delivers punishing knockdown power in tight alleys.",
    },
    ["bp_300blk_ss"] = {
        zh = "换上黑火药的亚音速重型战术步枪弹。弹丸飞行悄无声息，可惜黑火药击发时冒出的滚滚浓烟和枪机里积攒的厚厚炭垢，在三发之后就会彻底暴露你的潜伏位置。",
        en = "Subsonic tactical loads converted to black powder propellant. While the bullet flies quietly, the massive plume of sulfurous smoke curling from the muzzle exposes your ambush hide to every watchful eye.",
    },
    ["bp_303"] = {
        zh = "英国点三零三老式凸缘步枪弹的黑火药复装版。击发时的清脆声响变成了低沉炮鸣，配合老式李恩菲尔德步枪拉栓射击，瞬间让人恍若置身于一战索姆河战役的泥泞战壕。",
        en = "British .303 rimmed rifle ammunition reloaded with smoky black powder. Chambered in an antique bolt-action rifle, each thundering discharge transports you straight into the muddy, shell-pocked trenches of Passchendaele.",
    },
    ["bp_303fmj"] = {
        zh = "采用尖头全金属被甲与黑火药搭配的点三零三军用弹。弹壳结实耐用，虽然黑火药容易腐蚀枪膛必须勤洗枪管，但在大平原上狙击远处的变异巨蜥依然十分可靠。",
        en = "Spitzer-pointed .303 military cartridges loaded with black powder. Demanding immediate boiling-water barrel scouring to prevent pitting rust, they remain formidable tools for hunting monstrous wasteland game across meadows.",
    },
    ["bp_303sp"] = {
        zh = "配有一百八十格令软铅尖头猎鹿弹丸的黑火药点三零三子弹。击中血肉目标时翻滚碎裂效果极佳，即便面对体型庞大的变异驼鹿，也能一枪在侧肋打出一个致命血洞。",
        en = "Heavy 180-grain soft-point bullets seated over compressed black powder. Deforming violently inside dense muscle tissue, a well-placed shot reliably downs towering mutated elk to fill your winter smokehouse.",
    },
    ["bp_308"] = {
        zh = "用黑火药手工填塞的点三零八全威力步枪弹。曾经是高精狙击手的首选弹药，如今在黑火药的加持下弹道散布大得感人，但两百米内打中目标依然能当场开瓢。",
        en = "Ubiquitous .308 Winchester cartridges handloaded with black powder. While precision long-range accuracy suffers under inconsistent powder burn, center-mass hits within two hundred meters permanently dismantle aggressive raiders.",
    },
    ["bp_30carbine"] = {
        zh = "老式点三零卡宾枪弹的黑火药复装版本。出膛动能虽然所剩无几，但轻巧的后坐力配合半自动卡宾枪，让幸存者能够在烟雾缭绕的掩体后快速补枪压制冲锋的尸群。",
        en = "Vintage .30 Carbine cartridges filled with hand-ground black powder. Producing negligible recoil, rapid semi-automatic fire keeps charging ghoul packs suppressed behind thick screens of lingering sulfur smoke.",
    },
    ["bp_30carbine_jsp"] = {
        zh = "换装软尖弹头的黑火药点三零卡宾弹。软铅尖头在低速命中时依然能提供合格的扩张伤害，用来对付没有护甲保护的普通游荡丧尸，性价比高得令人难以拒绝。",
        en = "Soft-point .30 Carbine rounds powered by black powder. Expanding reliably upon low-velocity impact against soft decaying tissues, they offer cost-effective self-defense when scouring residential housing blocks.",
    },
    ["bp_32_acp"] = {
        zh = "点三二口袋手枪弹的黑火药复装版。威力小巧得像是在放摔炮，但在被变异丧尸逼到死胡同且所有重武器卡壳的绝境下，这发小烟炮就是你唯一的救命稻草。",
        en = "Diminutive .32 ACP pistol rounds resurrected using black powder. Sounding like firecrackers and kicking with mild polite pop, they provide desperate last-ditch protection when cornered inside dead-end utility closets.",
    },
    ["bp_32_acp_jhp"] = {
        zh = "配有小号空尖弹头的黑火药点三二随身弹药。虽然黑火药的低速让空尖杯很难彻底绽开，但击中变异狂犬的面门依然能让对方痛得掉头就跑，保住你的脚踝。",
        en = "Pocket-sized .32 hollow points propelled by improvised black powder. Lacking sufficient speed for dramatic expansion, landing a face shot nonetheless discourages mutated feral dogs from gnawing on your ankles.",
    },
    ["bp_338lapua_api"] = {
        zh = "塞入黑火药的点三三八拉普阿穿甲燃烧重弹。原本能击穿装甲车的顶级反器材弹药，如今在黑火药推动下像一枚冒烟的微型火箭，落地砸中的瞬间依然火光冲天。",
        en = "Extreme long-range .338 Lapua armor-piercing incendiary cartridges reloaded with black powder. Flying like smoky miniature artillery rockets, impacts detonate into spectacular blossoms of blinding fire and burning metal.",
    },
    ["bp_338lapua_fmjbt"] = {
        zh = "装填黑火药的重型拉普阿艇尾穿甲弹。开枪时沉闷的巨响震得脚下大地乱颤，哪怕初速折损严重，庞大弹丸所携带的纯粹物理质量也能将废土土匪直接砸成两截。",
        en = "Boat-tailed .338 Lapua penetrators launched via compressed black powder. The thunderous concussion rattles window frames across town, delivering enough kinetic mass to shear through makeshift sheet-metal vehicle barriers.",
    },
    ["bp_338lapua_hpbt"] = {
        zh = "三百格令空尖艇尾重弹配合黑火药的怪异组合。虽然弹道下坠严重得像是在抛投铁秤砣，但一旦在百米外砸中变异巨怪的胸膛，巨大的铅花能瞬间撕碎所有生机。",
        en = "A 300-grain match hollow-point round lobbed by black powder. Dropping in a steep arc like an iron anvil, striking home tears gaping exit wounds through armored mutant carapaces.",
    },
    ["bp_357mag_fmj"] = {
        zh = "点三五七马格南左轮弹的黑火药复装版本。击发时枪口火光冲天、白烟滚滚，射手宛如化身为西部淘金热时期的荒野恶徒，就是打完六发后手枪转轮转动起来会非常干涩。",
        en = ".357 Magnum revolver cartridges charged with sulfurous black powder. Spewing sheets of blinding fire and dense clouds, the corrosive residue quickly gums up cylinder rotation after a half-dozen shots.",
    },
    ["bp_357mag_jhp"] = {
        zh = "大开口空尖与黑火药搭配的点三五七左轮弹。近距离一枪轰在撕裂者丧尸胸口如同炸开一团血肉烟花，狂暴的停止力足以将任何近身的危险生物当场定格。",
        en = "Hollow-point .357 Magnum loads packed with homemade black powder. Detonating inside decayed chest cavities, the violent hydro-shock halts lunging zombies instantly while draping the room in choking smoke.",
    },
    ["bp_357sig_fmj"] = {
        zh = "采用瓶颈弹壳设计的高压点三五七西格黑火药复装弹。在现代自动手枪里击发黑火药简直是后勤噩梦，打完两发弹匣就必须立刻用热水彻底清洗复进簧与枪膛积碳。",
        en = "Bottleneck .357 SIG cartridges loaded with black powder. Firing black powder through modern tight-tolerance semi-automatic pistols creates a horrific maintenance nightmare requiring immediate hot-water disassembly.",
    },
    ["bp_357sig_jhp"] = {
        zh = "换装空尖弹头的黑火药点三五七西格弹。虽然容易让现代手枪卡壳故障，但只要成功击发，高速出膛的空尖弹片依然能在变异软体怪身上留下深达半尺的致命空腔。",
        en = "Expanding .357 SIG cartridges fueled by black powder. Risking failure-to-extract jams in fine sidearms, successful hits carve cavernous wounds inside soft mutant tissue to stop aggressive ambushes.",
    },
    ["bp_380_FMJ"] = {
        zh = "点三八零小手枪弹的黑火药复装版。击发时的威力柔和温顺，不仅后坐力微乎其微，打完后枪口喷出的小烟圈甚至莫名有一种滑稽的喜感，用来练习压枪倒挺合适。",
        en = "A compact .380 ACP round loaded with mild black powder. Delivering gentle recoil and modest muzzle pops, puffing harmless smoke rings provides an oddly comical diversion during defensive pistol drills.",
    },
    ["bp_380_JHP"] = {
        zh = "配有防卫空尖弹头的点三八零黑火药子弹。虽然黑火药让弹速打了折扣，但在不到三米的贴脸距离遭遇变异老鼠或丧尸犬时，掏出随身小枪开火依然能稳稳保住性命。",
        en = "Defensive .380 ACP hollow points reloaded with black powder. Though lacking blistering military velocity, point-blank impacts against leaping mutant rats effectively prevent nasty infectious bites.",
    },
    ["bp_38_fmj"] = {
        zh = "老旧点三八特种左轮弹的黑火药复装版。回到了这枚子弹一百多年前最初诞生的黑火药形态，低压温和的特性极其适合那些膛线磨平、濒临报废的废土老式转轮手枪。",
        en = "Traditional .38 Special revolver cartridges restored to their historic black-powder origins. Gentle operating pressures prove mercifully safe to fire through pitted, antique revolvers that might crack modern brass.",
    },
    ["bp_38_special"] = {
        zh = "采用空尖铅弹头与黑火药装药的点三八特种弹。后坐力柔和且不易炸膛，在狭窄的下水道里开火时，虽然烟雾会瞬间弥漫整个走廊，但足以将扑上来的丧尸击退数步。",
        en = "Hollow-point .38 Special ammunition handloaded with black powder. Generating modest chamber pressure, it prevents vintage cylinders from rupturing while delivering enough stopping power to stagger hallway creepers.",
    },
    ["bp_38super"] = {
        zh = "原本追求高压高速的点三八超级手枪弹，在黑火药的摧残下彻底沦为了老态龙钟的放烟工具。不过只要弹头能打进丧尸的眼眶，火药新不先进对死人来说毫无差别。",
        en = "Once-hot .38 Super match cartridges dragged down to sluggish velocities by black powder. However, when placing a lead slug squarely through a walker's eye socket, ancient propellant kills just fine.",
    },
    ["bp_38super_fmj"] = {
        zh = "全金属被甲搭配黑火药的点三八超级弹。坚固的弹头在近距离遭遇战中有着良好的防跳弹表现，只是每次扣下扳机后，你都得在浓烈刺鼻的白烟中重新寻找敌人的方位。",
        en = "Full-metal jacket .38 Super rounds recharged with black powder. Ensuring reliable feeding without deformation, pulling the trigger envelopes your immediate vicinity in blinding curtains of white sulfur vapor.",
    },
    ["bp_40fmj"] = {
        zh = "点四零史密斯威森手枪弹的黑火药复装版。原本猛烈的后坐力被黑火药缓冲得略显绵软，枪管里沉积的厚重油垢会在三轮速射后把套筒牢牢卡死在半路上。",
        en = ".40 S&W duty ammunition loaded with black powder. Softening the cartridge's notorious snappy recoil, gummy black residue locks up modern semi-automatic slides after only three swift magazine dumps.",
    },
    ["bp_40sw"] = {
        zh = "空尖防卫弹头塞入黑火药的点四零手枪弹。在近距离肉搏战中打进变异巨蜥的下颚能造成重创，代价是你的手枪必须在战斗后立刻浸泡进煤油盆里进行彻底大修。",
        en = "Expanding hollow-point .40 caliber loads driven by black powder. Carving messy wounds into charging mutant lizards, your service pistol will require an immediate kerosene bath to dissolve baked-on fouling.",
    },
    ["bp_40x53mm_buckshot_m169"] = {
        zh = "在四十毫米重型榴弹壳里塞满黑火药与几十颗大号铅丸的土制大霰弹。开火瞬间简直是一门手提式短管霰弹加农炮，能将整条小巷里的行尸走肉当场轰成满地碎肉渣。",
        en = "An improvised 40mm buckshot shell packed with black powder and dozens of heavy lead pellets. Discharging it transforms automatic grenade launchers into handheld cannons that sweep alleyways clean.",
    },
    ["bp_40x53mm_flechette_m169"] = {
        zh = "填装了一百一十五枚锋利小钢镖与黑火药的四十毫米重型箭形弹。喷射而出的钢镖雨在空中呼啸飞舞，能将前方扇形区域内的变异生物连皮带肉死死钉在身后的墙壁上。",
        en = "A devastating 40mm canister load containing 115 steel flechettes and black powder. Unleashing an aerial razor storm, it pins charging packs of ghouls against brick walls in bloody tableau.",
    },
    ["bp_40x53mm_slug_m169"] = {
        zh = "在重型榴弹弹壳里强行压入半斤重实心铅块的黑火药独头弹。出膛时伴随着震耳欲聋的黑烟咆哮，沉重的铅块砸在报废轿车上能把整扇车门砸得深凹进去半米深。",
        en = "A monstrous 40mm load packing a massive solid lead slug over black powder. Its concussive roar caves in entire car doors, acting like a flying anvil hurled by angry mechanical gods.",
    },
    ["bp_410shot_000"] = {
        zh = "填塞了五颗重铅丸与黑火药的点四一零小霰弹。开火声势比无烟火药沉闷许多，刺鼻的硫磺黑烟中，五颗铅丸依然能在十米内把变异丧尸犬打得皮开肉绽。",
        en = "Petite .410 shotshells reloaded with black powder and five heavy lead pellets. While spewing blinding sulfur clouds, the compact payload reliably stops snarling mutant hounds within ten paces.",
    },
    ["bp_410shot_bird"] = {
        zh = "装入黑火药与细密鸟弹丸的轻型霰弹。出膛动能微弱得像在放烟花，虽然打不穿丧尸的厚皮，但用来在烟雾缭绕的树丛里打落两只野鸟填饱肚子完全没有问题。",
        en = "A modest .410 birdshot shell loaded with improvised black powder. Lacking the velocity to penetrate zombie hides, it reliably bags perched pheasants to keep camp stewpots gently simmering.",
    },
    ["bp_410shot_scrap"] = {
        zh = "把黑火药和碎铁钉、旧螺丝胡乱塞进点四一零塑料弹壳的废土自制弹。每一枪射击都是对枪管寿命的残忍折磨，铁渣乱飞的场面让对面的敌人和旁边的队友同时抱头蹲防。",
        en = "Improvised .410 shells filled with scrap iron filings and black powder. Severely gouging the shotgun barrel on firing, its jagged metallic spray terrifies adversaries and allies in equal measure.",
    },
    ["bp_410shot_slug"] = {
        zh = "配有一百一十格令实心铅块的黑火药点四一零独头弹。虽然黑火药推力有限导致弹道下坠明显，但在二十米距离砸中丧尸胸口，也能砸断两三根腐烂的肋骨。",
        en = "A 110-grain solid lead slug loaded over black powder in a .410 shell. Suffering pronounced trajectory drop, center-mass hits within twenty paces nevertheless crack rotten ribs with satisfying authority.",
    },
    ["bp_44fmj"] = {
        zh = "全金属被甲两百四十格令点四四马格南重弹的黑火药复装版。枪口喷出的炽热火舌足有半米长，震耳欲聋的巨响和滚滚白烟会让你瞬间化身十九世纪的荒野执法官。",
        en = "Heavy 240-grain .44 Magnum cartridges reloaded with black powder. Unleashing two-foot muzzle fireballs and dense smoke screens, firing makes you feel like an authentic nineteenth-century frontier marshal.",
    },
    ["bp_44magnum"] = {
        zh = "换装空尖弹头并填塞黑火药的点四四马格南弹药。虽然低速影响了空尖杯的极致扩张，但在近战中轰碎一具变异爬行者的脑壳依然像踩碎一个烂西瓜一样轻松干脆。",
        en = "Hollow-point .44 Magnum rounds charged with coarse black powder. Diminished velocity hampers optimal cavity flowering, yet landing a direct headshot crushes crawling mutant skulls like overripe watermelons.",
    },
    ["bp_450_ftx"] = {
        zh = "装载两百五十格令塑料尖头弹丸的黑火药点四五零灌木猎手弹。巨大的弹体在黑火药的低沉轰鸣中呼啸飞出，砸在防暴丧尸身上能将其沉重的高分子防爆盾砸得当场脱手。",
        en = "A 250-grain polymer-tipped .450 Bushmaster slug launched via black powder. Striking armored riot zombies with freight-train momentum, the blunt impact violently strips ballistic shields straight from their grasp.",
    },
    ["bp_450_penetrator"] = {
        zh = "采用实心铜弹头与黑火药搭配的点四五零特种穿甲弹。实心铜弹头质地极其坚硬，即便黑火药赋予的动能不如战前标准，在百米内击穿报废皮卡的引擎盖依然易如反掌。",
        en = "Solid copper penetrators seated over black powder inside .450 Bushmaster casings. Despite reduced velocity, the monolithic bronze projectile effortlessly punches through scrap engine hoods to disable getaway vehicles.",
    },
    ["bp_454_Casull"] = {
        zh = "用黑火药强行复装的三百格令卡苏尔超重型左轮弹。开火时的后坐力狂暴得能把无准备的手腕震脱臼，狂暴的枪口烈焰伴随着浓烟，堪比手持微型攻城臼炮。",
        en = "Monster 300-grain .454 Casull rounds handloaded with black powder. Torquing wrists with punishing recoil while spitting fiery sulfur geysers, it functions like a handheld siege mortar against charging monstrosities.",
    },
    ["bp_458wm"] = {
        zh = "点四五八温彻斯特重型非洲大猎弹的黑火药土制版。巨大的黄铜弹壳里塞满了黑火药颗粒，虽然初速大打折扣，但那颗三百五十格令的软铅重弹砸中目标依旧如同飞来铁锤。",
        en = "Dangerous-game .458 Winchester Magnum brass crammed with black powder charges. While velocities dip far below modern standards, the 350-grain soft-lead hammer pulverizes charging mutant bears.",
    },
    ["bp_45_acp"] = {
        zh = "两百三十格令标准点四五手枪弹的黑火药复装版。原本就偏慢的亚音速弹头在黑火药推动下慢得肉眼可见，但沉重弹丸自带的强大物理动能依然足以将丧尸打退半步。",
        en = "Classic 230-grain .45 ACP military ball reloaded with black powder. Creeping along at visible subsonic speeds, its heavyweight kinetic momentum still reliably knocks lunging undead backward onto the pavement.",
    },
    ["bp_45_jhp"] = {
        zh = "使用空尖弹头与黑火药复装的点四五自卫手枪弹。在狭小的室内遭遇战中扣动扳机，整个房间会瞬间被呛人的硫磺白烟填满，好在对面的敌人往往已经在惨叫中倒地。",
        en = "Expanding .45 ACP hollow points charged with black powder. Discharging them inside narrow basements instantly blankets rooms in choking fog, mercifully sparing you the sight of dismembered foes.",
    },
    ["bp_45colt_cowboy"] = {
        zh = "使用两百五十格令平头纯铅弹头的黑火药点四五长柯尔特牛仔弹。这枚子弹终于回归了它在西部拓荒时期的原始面貌，温和的后坐力配合老式单动左轮，散发着浓郁的历史韵味。",
        en = "Flat-nosed 250-grain lead slugs paired with black powder in .45 Long Colt brass. Returning the cartridge to its authentic nineteenth-century cowboy roots, it shoots with nostalgic smoke and gentle recoil.",
    },
    ["bp_45colt_fmj"] = {
        zh = "全金属被甲搭配黑火药的点四五柯尔特子弹。弹壳容量巨大，填入足量黑火药后能爆发出相当可观的动能，是废土拾荒者在缺乏现代弹药时极其信赖的随身护卫底牌。",
        en = "Full-metal jacket .45 Colt rounds loaded with ample black powder. Taking advantage of cavernous internal brass volume, it produces solid kinetic punch that makes frontier lever-actions sing with smoky authority.",
    },
    ["bp_45colt_jhp"] = {
        zh = "换装空尖弹头的黑火药点四五柯尔特弹。黑火药燃烧产生的黑灰会迅速附着在左轮手枪转轮缝隙中，但只要能准确命中目标，空尖弹头造成的创口绝对能让变异野兽知难而退。",
        en = "Hollow-point .45 Colt loads hand-primed with black powder. While sulfur residue rapidly gums up revolver cylinder timing, the expanding mushrooming wound channel stops aggressive predators in their tracks.",
    },
    ["bp_500_Magnum"] = {
        zh = "把黑火药塞进史密斯威森五百超级手枪弹壳里的恐怖巨弹。五百格令的巨型铅弹伴随着漫天火星和黑烟轰然飞出，开枪的后坐力不仅震痛双臂，甚至能把身后的队友吓趴下。",
        en = "A monstrous 500-grain .500 S&W slug propelled by compressed black powder. Detonating with volcanic fury and blinding smoke screens, the savage recoil rattles dental fillings and terrifies standing bystanders.",
    },
    ["bp_50_incendiary"] = {
        zh = "在点五零反器材重机枪弹壳里填满黑火药的复装曳光弹。伴随着浓烟飞出一道耀眼的橘红火球，虽然射程缩水严重，但命中木质哨塔时依然能引发一场毁灭性的大火灾。",
        en = ".50 BMG heavy machine gun tracer rounds converted to black powder propellant. Lobbing blinding orange fireballs downrange through billowing clouds, impacts readily ignite timber watchtowers into roaring bonfires.",
    },
    ["bp_50ae_fmj"] = {
        zh = "装入黑火药的三百二十五格令沙漠之鹰点五零手枪弹。由于黑火药残渣极多，大名鼎鼎的沙漠之鹰气动系统在开完第一枪后就会直接被炭垢卡死，不得不手动拉套筒退壳。",
        en = "Heavy 325-grain .50 AE rounds loaded with black powder. Generating massive carbon fouling, the Desert Eagle's delicate gas piston chokes after a single round, requiring strenuous manual slide racking.",
    },
    ["bp_50ae_jhp"] = {
        zh = "空尖弹头配黑火药的点五零沙漠之鹰弹药。威力惊人但浓烟弥漫，扣动扳机后你必须在刺鼻白烟中屏住呼吸等待视线恢复，才能确认对面的变异撕裂者是否已经被打成两截。",
        en = "Expanding .50 Action Express hollow points seated over black powder. The thunderous blast envelopes the hallway in dense fog, forcing shooters to hold their breath while confirming the target's demise.",
    },
    ["bp_50beowulf_penetrator"] = {
        zh = "塞满黑火药与实心铜穿甲弹头的五十贝奥武夫大口径步枪弹。沉闷的枪声如同雷神怒吼，出膛的粗壮铜桩能在三十米内将废弃汽车发动机舱连同水箱一起砸得粉碎。",
        en = "Solid copper penetrators launched via black powder in .50 Beowulf brass. Emitting a guttural roar, the flying bronze sledgehammer smashes clean through automotive engine blocks within thirty meters.",
    },
    ["bp_50beowulf_xtp"] = {
        zh = "配有被甲空尖弹头的黑火药五十贝奥武夫弹。巨大的横截面让它在命中变异巨怪的瞬间爆发出骇人的空腔毁伤，虽然每次打完自动步枪都要彻底大修，但保命效果立竿见影。",
        en = "Expanding XTP hollow points handloaded into .50 Beowulf cases with black powder. Producing horrific cavitation in soft mutant flesh, the immediate stopping power easily justifies subsequent gun maintenance.",
    },
    ["bp_50match"] = {
        zh = "点五零远程高精比赛弹的黑火药复装版。原本用来在两公里外争夺射击冠军的精密弹丸，如今在黑火药的飘忽弹道下只能拿来轰击两百米外的装甲丧尸，可谓明珠暗投。",
        en = "Match-grade .50 BMG projectiles reloaded with inconsistent black powder. Once capable of sub-MOA precision across miles, erratic propellant pressures now relegate them to bludgeoning armored walkers at short range.",
    },
    ["bp_50ss"] = {
        zh = "带有高密度合金穿甲芯的点五零黑火药重弹。即便黑火药的初速不如军用无烟火药，沉重的弹芯在近距离依然能毫无悬念地击穿变异巨怪厚如钢板的几丁质外骨骼。",
        en = "Dense armor-piercing cores seated inside .50 BMG brass packed with black powder. Heavy penetrators punch ruthlessly through reinforced chitinous carapaces, proving that raw kinetic mass overcomes modest velocities.",
    },
    ["bp_545"] = {
        zh = "俄式五点四五小口径步枪弹的黑火药复装版。轻巧的弹头在黑火药的催动下弹道更加飘忽，但配上老旧苏制步枪，依然能在废土林地交火中提供绵密的压制火力。",
        en = "Soviet-standard 5.45x39mm rifle cartridges revived with homemade black powder. Flying along erratic flight arcs, they nonetheless provide sustained suppressive fire from rugged Kalashnikov rifles.",
    },
    ["bp_545_ap"] = {
        zh = "内嵌轻合金穿甲钢芯的五点四五黑火药步枪弹。虽然黑火药容易腐蚀枪管镀铬层，但坚硬的弹芯在近战中依然能有效穿透普通拾荒者身上挂着的简易铁皮胸甲。",
        en = "Hardened steel penetrator 5.45mm rounds handloaded with black powder. Eating away at chrome bore linings if left uncleaned, the steel core still punches through makeshift raider sheet-metal armor.",
    },
    ["bp_556"] = {
        zh = "北约五点五六通用步枪弹的黑火药复装版。击发时的黑烟会瞬间灌满整支突击步枪的机匣，打光一个弹匣后，枪机部件上积攒的黑色油泥多得能直接拿来当鞋油用。",
        en = "Standard 5.56 NATO cartridges stuffed with smoky black powder. Venting corrosive soot directly into AR-15 upper receivers, emptying a single magazine leaves enough greasy carbon to polish combat boots.",
    },
    ["bp_556_incendiary"] = {
        zh = "装入黑火药的五点五六口径曳光弹。在火药自身的浓烟掩护下，明亮的化学曳光在空中划出清晰轨迹，偶尔还能引燃目标身上干燥的衣物或干枯的变异灌木丛。",
        en = "5.56mm tracer rounds propelled by sulfurous black powder. Glowing brightly through billowing smoke curtains, the incendiary compound reliably sparks dry underbrush and tattered zombie garments on contact.",
    },
    ["bp_57mm"] = {
        zh = "小巧玲珑的五点七毫米微型穿甲弹黑火药复装版。原本依赖超高初速实现穿甲的特性被黑火药大大削弱，但在近距离速射时依然是一把轻便灵活的近身自卫小毒针。",
        en = "Dainty 5.7x28mm personal defense rounds hand-primed with black powder. Stripped of high-velocity armor piercing potential, they still function as venomous close-quarters stingers in compact sidearms.",
    },
    ["bp_762_25"] = {
        zh = "托卡列夫七点六二手枪弹的黑火药复装版。击发时尖锐的枪声夹杂着滚滚白烟，虽然没有原版强装药那么狂暴，但弹头依然能干脆利落地击碎丧尸的额骨。",
        en = "High-velocity 7.62x25mm Tokarev rounds reloaded with black powder. While lacking the blistering snap of original military loadings, the zippy steel-jacketed projectile still cracks walking skulls cleanly.",
    },
    ["bp_762_51"] = {
        zh = "北约七点六二点三零八全威力重弹的黑火药自制版。射击时宛如一门小型野战炮轰鸣，狂暴的后坐力与硫磺浓烟会让射手在两秒钟内失去所有视野，但打中绝对致命。",
        en = "Full-power 7.62x51mm battle rifle cartridges charged with black powder. Barking with the thunderous report of field artillery, center-mass hits permanently terminate heavily mutated humanoids.",
    },
    ["bp_762_51_incendiary"] = {
        zh = "填塞黑火药的全威力点三零八曳光弹。亮红色的曳光轨迹在黑白相间的浓烟中分外刺眼，除了给机枪手指示目标外，命中木屋或油罐时能瞬间引发绚丽的末日烟火。",
        en = "Heavy .308 battle rifle tracer rounds reloaded with black powder. Slicing through smoke clouds like crimson laser beams, they turn fuel barrels and dry wooden shacks into instant tactical bonfires.",
    },
    ["bp_762_54R"] = {
        zh = "老式莫辛纳甘步枪使用的凸缘全威力黑火药复装弹。这枚诞生于沙俄时代的百年老弹配上黑火药可谓相得益彰，沉重的铅弹带着历史的轰鸣把百米外的敌人当场砸翻。",
        en = "Vintage 7.62x54mmR rimmed cartridges matched with historic black powder. Firing them through long Mosin-Nagant rifles feels entirely natural, sending heavy lead slugs crashing through distant barricades.",
    },
    ["bp_762_jhp"] = {
        zh = "换装空尖弹头的七点六二中威力黑火药子弹。打进没有护甲的变异猎犬体内会瞬间翻滚炸开，虽然黑火药初速略低，但空尖造成的巨大创伤完全足以让变异犬当场丧命。",
        en = "Expanding hollow-point 7.62x39mm rounds fueled by black powder. Blossoming aggressively inside unarmored flesh despite lower velocities, they drop aggressive packs of mutated coyotes in seconds.",
    },
    ["bp_762_m87"] = {
        zh = "采用经典铅芯被甲弹头的黑火药七点六二步枪弹。在AK步枪粗大旷量的活塞系统里运行良好，虽然每次开完火整支枪都散发着刺鼻的硫磺味，但胜在皮实可靠不卡壳。",
        en = "Standard military ball 7.62x39mm cartridges reloaded with black powder. Cycling reliably through loose-tolerance AK gas systems, the rifle smells intensely of fireworks while chewing through ammunition.",
    },
    ["bp_77mm_arisaka_jsp"] = {
        zh = "装入黑火药与一百七十四格令软尖铅弹的七点七有坂老步枪弹。这颗来自旧时代战场的遗留弹药配上自制黑火药，在拉动九九式步枪粗壮枪栓时让人产生时空错乱的恍惚感。",
        en = "Obsolete 7.7x58mm Arisaka cartridges loaded with soft-point lead bullets and black powder. Working the heavy bolt of an antique rifle amidst apocalyptic ruins evokes strange ghosts of ancient wars.",
    },
    ["bp_9mm"] = {
        zh = "九毫米手枪空尖弹的黑火药复装版。原本灵动小巧的格洛克手枪打上几发就会因为黑火药残渣卡壳，但在缺乏无烟火药的末日废土上，有枪能响就已经是莫大的幸运。",
        en = "9x19mm hollow-point handgun rounds hand-primed with black powder. While tight modern pistol slides jam after a few smoky magazines, having functioning ammunition remains a priceless blessing.",
    },
    ["bp_9mmfmj"] = {
        zh = "全金属被甲九毫米黑火药通用手枪弹。造价极其廉价且原料易得，虽然开枪时枪口喷出的白烟经常把射手熏得直咳嗽，但在近距离击退丧尸抓咬时依然表现合格。",
        en = "Full-metal jacket 9mm rounds assembled with basic black powder. Cheap to manufacture in field workshops, coughing through stinging smoke screens is a small price to pay for dependable self-defense.",
    },
    ["bp_9x18mm"] = {
        zh = "马卡洛夫九毫米全金属被甲黑火药子弹。老式马卡洛夫手枪简单的自由枪机结构完美兼容黑火药的粗糙脾气，就算打得枪机满是黑泥也能顽强地把每一发子弹正常击发。",
        en = "Standard 9x18mm Makarov ammunition loaded with black powder. Simple blowback surplus pistols tolerate gritty powder residue surprisingly well, chugging through magazines without missing a beat.",
    },
    ["bp_9x18mmfmj"] = {
        zh = "带有硬化钢芯的马卡洛夫黑火药穿甲弹。初速虽然被黑火药拉低，但近距离击中丧尸头颅时，硬质钢芯依然能凭借高硬度击穿骨骼，在绝境中为你杀出一条血路。",
        en = "Steel-penetrator Makarov cartridges reloaded with black powder charges. Compensating for lower velocity with sheer core hardness, point-blank headshots punch through skull bone to save your life.",
    },
    ["bp_nomad_bodyglove"] = {
        zh = "印刷在防水油纸上的贴身内衬制作图纸，详细标注了游牧者如何在严寒与热浪中依靠多层合成纤维维持体温。",
        en = "An illustrated technical manual printed on waxed paper, outlining how wasteland wanderers weave multi-layer fabrics to survive extreme seasonal temperature swings.",
    },
    ["bp_nomad_cowl"] = {
        zh = "详尽绘制的游牧兜帽图解，教你如何用碎皮料缝制出能遮挡酸雨、辐射沙尘以及狂暴冷风的废土标志性头罩。",
        en = "Clear diagrams detailing the stitching of a rugged nomad cowl, engineered to deflect radioactive dust, caustic acid drizzles, and unforgiving blizzard winds.",
    },
    ["bp_nomad_jumpsuit"] = {
        zh = "标满裁切虚线的游牧连体服图纸，穿上这种耐磨且布满口袋的工作服，你就能像一只真正的废土蟑螂般顽强生存。",
        en = "A schematics pamphlet charting a heavy-duty nomad jumpsuit, turning the wearer into a pocket-laden wasteland roach capable of enduring rough brambles.",
    },
    ["bp_shot_00"] = {
        zh = "填装九颗双零大号鹿弹丸与黑火药的十二号标准霰弹。近距离一枪轰出宛如小型手提火炮开火，狂暴的铅雨和翻滚的白烟能把整面木板门连同后面的丧尸当场轰碎。",
        en = "Standard 12-gauge shotgun shells packed with nine 00 buck pellets and black powder. Discharging it like a handheld cannon obliterates wooden doors and approaching ghouls under a hail of lead.",
    },
    ["bp_shot_bird"] = {
        zh = "装入几十粒细小鸟弹的黑火药十二号轻霰弹。出膛动能柔和，漫天飞舞的细密铅粒在林间散布开阔，是末日猎人用来清理野鸡野鸭、填饱肚子最经济实惠的食物收割器。",
        en = "Mild 12-gauge birdshot shells reloaded with black powder and fine lead shot. Spreading wide patterns across autumn treetops, they harvest wild fowl efficiently without destroying precious meat.",
    },
    ["bp_shot_dragon"] = {
        zh = "在十二号霰弹壳里塞满黑火药与高燃镁粉金属碎屑的龙息弹。扣下扳机的瞬间枪口喷射出长达数米的耀眼烈焰风暴，能将眼前的整群丧尸点燃成哀嚎乱窜的人形火炬。",
        en = "Dragon's breath shells loaded with burning magnesium flakes and black powder. Pulling the trigger unleashes a terrifying ten-foot jet of blinding flame, turning charging undead into flailing pyres.",
    },
    ["bp_shot_flechette"] = {
        zh = "装有几十枚锋利小钢镖与黑火药的十二号特种箭形霰弹。钢镖在低速出膛后呼啸散开，在狭窄走廊里密密麻麻地钉满前方所有活物，穿透力深沉且极难止血拔除。",
        en = "A 12-gauge shotshell packed with miniature steel flechette darts over black powder. Spreading along narrow hallways, the flying needles pin soft targets to walls in agonizing clusters.",
    },
    ["bp_shot_scrap"] = {
        zh = "用黑火药和碎玻璃、废铁钉、生锈螺丝拼凑的十二号废料霰弹。击发时枪管里火星四溅，混乱飞舞的金属碎屑在近距离能把任何血肉之躯撕裂得面目全非、血肉模糊。",
        en = "Improvised 12-gauge shells loaded with crushed glass, bent nails, and black powder. The horrific blast chews through shotgun chokes while shredding flesh into unrecognizable crimson ribbons.",
    },
    ["bp_shot_slug"] = {
        zh = "塞入一整枚沉重纯铅大独头弹的黑火药十二号霰弹。开火声势地动山摇，出膛的实心铅坨在五十米内击中变异怪物，其恐怖的钝击动能足以让任何血肉巨兽当场倒地不起。",
        en = "A massive solid lead slug loaded over black powder in a 12-gauge hull. Hitting with the devastating momentum of a thrown boulder, center-mass hits drop massive monstrosities flat.",
    },
    ["bra"] = {
        zh = "带有钢圈和弹性肩带的标准文胸，在逃命奔跑时提供至关重要的支撑；如果拆散开来，里面的钢丝还能当成优秀的撬锁工具。",
        en = "A supportive wired undergarment offering essential running stability; when dismantled in desperation, the underwire makes a remarkably serviceable lockpick.",
    },
    ["bracelet_friendship"] = {
        zh = "彩色编织绳打结制成的友谊手链，在同伴早已失散或变成丧尸的末日，戴着它除了提醒你孤独之外没有丝毫护甲加成。",
        en = "A woven wristband knotted from cheerful embroidery threads; offering zero blunt defense, it exists purely to remind you of friends who probably mutated.",
    },
    ["brain"] = {
        zh = "一整块血淋淋、带有复杂沟回与黏液的生动物脑髓。无论你有多么饥饿，直接生吃这团散发着铁锈腥味的神经组织绝对不是个好主意，除非你迫不及待想感染朊病毒。",
        en = "A raw, glistening chunk of mammalian cerebral tissue dripping with neural fluids. Consuming it uncooked invites severe prion disease and parasitic nightmares, no matter how desperately starving you are.",
    },
    ["brain_cooked"] = {
        zh = "在铁锅里加入野葱和油脂煎炸至表面金黄微脆的熟脑花。外焦里嫩的口感细腻得如同法式鹅肝，让你在享受高胆固醇美味的同时，莫名体验了一把丧尸食脑的快乐。",
        en = "A piece of brain pan-fried in clarified tallow with wild scallions until golden and tender. Its rich, velvety texture resembles gourmet paté, letting you emulate culinary zombie pleasures in safety.",
    },
    ["brandied_fruit"] = {
        zh = "浸泡在烈酒中的整颗水果，虽然甜美多汁，但酒精度高到咬下一口就会让你脸颊发烫，很难分清这是甜点还是麻药。",
        en = "Whole fruit submerged in searing spirits; sweet and succulent, though each boozy bite hits hard enough that dessert rapidly blurs into anesthesia.",
    },
    ["brandy"] = {
        zh = "经过二次蒸馏的芳香烈酒，不仅能用来点燃营火、清洗伤口，还能在极度绝望的寒夜里把幸存者的理智暂时麻醉。",
        en = "Aromatic distilled wine potent enough to disinfect a gash, ignite wet tinder, or pleasantly anesthetize whatever lingering sanity you have left.",
    },
    ["brass_catcher"] = {
        zh = "挂在抛壳窗旁的耐热尼龙网袋，忠实地接住每一枚滚烫的空弹壳，是手摇复装子弹狂热爱好者最不可或缺的省钱神器。",
        en = "A mesh receptacle clamped beside the ejection port, catching scorching spent casings for reloading enthusiasts who treat empty brass like solid gold bullion.",
    },
    ["bratwurst_sausage"] = {
        zh = "肉馅饱满的经典德式香肠，放在铁丝网或火盆上滋滋冒油时散发的浓香，足以把方圆两百米内饥肠辘辘的邻居与野兽全引过来。",
        en = "A plump spiced pork sausage whose sizzling fat over hot coals releases an aroma potent enough to lure starving bandits from miles downwind.",
    },
    ["brazier"] = {
        zh = "带有通风孔的金属火盆，把几块破木板丢进去就能升起一团安全的篝火，让你在漫漫长夜里不必担心把避难所的地板给点着。",
        en = "A ventilated steel basin that safely cradles a roaring wood fire, allowing you to stay warm through frozen nights without incinerating your shelter floor.",
    },
    ["brazing_rod_alloy"] = {
        zh = "细长的铝合金钎焊条，配合喷枪就能修补被机枪打穿的引擎油底壳，是每一个废土机械师口袋里常备的续命灵药。",
        en = "A slender rod of aluminum alloy that, paired with a blowtorch, seals punctured engine sumps and keeps rusted mechanical monstrosities rumbling forward.",
    },
    ["brazing_rod_bronze"] = {
        zh = "表面涂覆助焊剂的青铜焊条，在喷枪的高温下化作金色熔浆，将断裂的铁管和钢板牢牢咬合在一起，修补世界的伤口。",
        en = "A flux-coated bronze alloy rod melting under torch flame to bond fractured iron pipes, sealing the structural fractures of a ruined civilization.",
    },
    ["bread"] = {
        zh = "一块朴实无华的硬皮面包，哪怕烤得像砖头一样坚硬，只要泡进热汤里，依然是人类农业文明给幸存者最温暖的抚慰。",
        en = "A humble loaf of hearth-baked crust; even if staled to the consistency of field masonry, dunking it into stew delivers timeless civilizational comfort.",
    },
    ["bread_flour"] = {
        zh = "富含面筋的高筋白面粉，在受潮发霉之前，它是烘焙松软面包与筋道面条的基石，哪怕在末日也值得用密封袋小心收藏。",
        en = "High-protein milled wheat flour providing stretch and chew; until moisture transforms it into mildew, it represents the gold standard of carbohydrate luxury.",
    },
    ["bread_garlic"] = {
        zh = "抹满了大蒜、黄油与香料的烤面包，浓烈的大蒜香气不仅能极大振奋胃口，或许还能顺便驱散对吸血鬼传说的无端恐惧。",
        en = "Slices toasted with crushed garlic, golden butter, and herbs; the heavenly odor boosts morale instantly while warding off superstitious vampiric paranoia.",
    },
    ["breadboard"] = {
        zh = "布满微型插孔的免焊接电子实验板，在灾前用来给极客调试电路，在废土上则是拼凑炸弹遥控引信和警报器的摇篮。",
        en = "A solderless prototyping grid riddled with tiny sockets; once a playground for electronics hobbyists, now the messy birthplace of improvised tripwire alarms.",
    },
    ["breeches"] = {
        zh = "剪裁贴身且面料厚实的复古马术长裤，虽然骑马的贵族时代早已终结，但耐磨的裤腿依然能很好地抵御灌木丛里的枯枝倒刺。",
        en = "Stiff, tailored equestrian trousers from an aristocratic past; with horses vanished, their durable double-weave fabric remains excellent against roadside briars.",
    },
    ["bren2_556"] = {
        zh = "捷克制造的现代化短突击步枪，结构紧凑且精准可靠，在废土混乱交火中，清脆的连发射击声就是生存者最坚定的答复。",
        en = "A sleek Czech tactical carbine marrying reliability with lightweight ergonomics; its rapid, crisp cadence delivers definitive closure to roadside negotiations.",
    },
    ["brew_burdock_wine"] = {
        zh = "混合了牛蒡根与糖水的粘稠发酵原浆，散发着泥土与药草的苦味，喝之前需要鼓起面对中药汤剂的巨大勇气。",
        en = "A sticky sludge of burdock roots and sugar water reeking of raw loam, demanding the stubborn courage usually reserved for taking foul medicinal draughts.",
    },
    ["brew_dandelion_wine"] = {
        zh = "满桶泛着黄色泡沫的蒲公英花浆，在阳光下宛如液态金子，但在发酵完成前它只是充满草腥味的苦涩糖水。",
        en = "A foaming pail of dandelion petals resembling liquid sunlight; before proper fermentation, however, it remains intensely bitter sugary water smelling of freshly cut grass.",
    },
    ["brew_fruit_wine"] = {
        zh = "用各种搜刮来的野浆果捣烂煮沸的甜浆，甜腻得足以吸引方圆数里的蜜蜂，是末日自酿酒精饮料中最甜美的前奏。",
        en = "Boiled sweet mash pounded from scavenged wild berries, sugary enough to summon every wasp in the county and promising fruity salvation once fermented.",
    },
    ["brew_gin"] = {
        zh = "散发着刺鼻松树针和杜松子香气的发酵浆液，一旦蒸馏成功，就能产出让废土绅士们暂时忘却饥荒的高贵杜松子酒。",
        en = "Pungent mash infused with juniper berries and pine needles, destined after distillation to yield the aromatic liquor that keeps cultured survivors relatively civilized.",
    },
    ["brew_hb_beer"] = {
        zh = "煮熟麦芽与冷水混合而成的粘稠麦汁，咕嘟咕嘟冒着热气，散发着面包房一般的甜香，等待酵母施展酒精魔法。",
        en = "A chilled porridge of boiled malt sugars breathing warm bready fumes, patiently awaiting yeast to execute its sacred enzymatic transformation into tavern-grade ale.",
    },
    ["brew_hb_seltzer"] = {
        zh = "精制糖与酵母在清水中沉浮的原浆，完全没有任何天然风味，证明现代人类为了摄入低卡路里酒精究竟有多拼命。",
        en = "Refined sucrose dissolved in sterile water waiting for fermentation, proving the absurd lengths modern humans went to pursue completely flavorless, low-calorie alcoholic buzzes.",
    },
    ["brew_hopped_mead"] = {
        zh = "用野生蜂蜜调和并加入苦味啤酒花的未发酵蜜汤，甜与苦在桶中激烈交锋，酝酿着维京海盗风格的醉生梦死。",
        en = "Diluted raw wildflower honey boiled with bitter hops, staging a tempestuous clash of sweet and harsh destined for drunken barbarian hall banquets.",
    },
    ["brew_kvass"] = {
        zh = "泡着烤焦黑麦面包皮与碎果肉的浑浊发酵液，酵母正贪婪地啃食淀粉，散发着斯拉夫荒原上最朴实无华的酸甜汽水味。",
        en = "Murky broth floating with charred rye crusts and apple slices, radiating the earthy, tangy perfume of the quintessential Slavic peasant soda in progress.",
    },
    ["brew_marloss_wine"] = {
        zh = "泛着柔和粉红微光的马洛斯浆液，粘稠得像活物的血液，即便尚未发酵，桶边也仿佛传来低沉而温柔的真菌低语。",
        en = "A gently glowing pink slurry made from Marloss pulp; even unfermented, the viscous concoction hums with the faintly seductive whispers of the fungal bloom.",
    },
    ["brew_mead"] = {
        zh = "简单粗暴的蜂蜜稀释水，金黄透亮却毫无生机；只要丢进去一撮活酵母，它就能在几周后把粗暴的掠夺者灌得烂醉如泥。",
        en = "Translucent golden runoff of diluted honey; inert on its own, yet throwing in a pinch of yeast will eventually render battle-hardened raiders completely unconscious.",
    },
    ["brew_milk_curdled"] = {
        zh = "加入了醋和凝乳酶的酸败牛奶，正在分裂成清亮的乳清与雪白的豆腐脑状凝乳，是手工奶酪漫长孕育的丑陋第一步。",
        en = "Milk curdling under acidic vinegar and rennet, splitting into cloudy whey and spongy clumps; the undeniably grotesque first stage of artisanal wasteland cheese-making.",
    },
    ["brew_moonshine"] = {
        zh = "玉米粒、白糖与井水混合搅拌的原始糊糊，在简陋的铁桶里静静酝酿，预示着一桶能够兼当卡车燃料与盲目烈酒的私酿。",
        en = "A coarse mash of crushed corn, river water, and cane sugar, quietly plotting to become high-proof hooch equally suitable for lanterns, engines, or blindness.",
    },
    ["brew_mycus_wine"] = {
        zh = "白浊粘稠的马卡斯真菌原汁，表面偶尔冒出无声的气泡，任何尚存理智的人类看到这团史莱姆状液体都不会想把它喝进肚子里。",
        en = "A milky, gelatinous mass of alien fungal marrow burping silent bubbles; anyone clinging to their baseline humanity would shudder before swallowing this paste.",
    },
    ["brew_pine_wine"] = {
        zh = "带着刺鼻松香和林地泥土味的松树糖水，喝下去可能不会让你飞升，但绝对能让你打出的每一个饱嗝都充满针叶林的气息。",
        en = "Sticky pine syrup laced with wild yeast and resin; drinking it won't grant enlightenment, but your subsequent burps will unmistakably smell of evergreen forests.",
    },
    ["brew_rootbeer"] = {
        zh = "煮沸的黄樟树根与糖水混合液，散发着类似于跌打药膏与草本牙膏的奇特清香，是发酵成传统气泡根啤的关键底料。",
        en = "Boiled sassafras bark and sweetened broth smelling suspiciously like medicinal ointment, representing the essential foundation for old-fashioned carbonated root beer.",
    },
    ["brew_rum"] = {
        zh = "用发黑的糖蜜与红糖熬制出的粘稠黑液，甜得发腻且带着焦香，只要发酵蒸馏出来，就能让最落魄的水手重温海盗梦。",
        en = "Dark, syrupy molasses sludge reeking of caramelized sugar, designed to ferment into the fiery swill that once fueled seafaring pirates and drunken mutinies.",
    },
    ["brew_sake"] = {
        zh = "蒸熟大米与米曲霉亲密纠缠的发酵母液，散发着优雅的米香与微醺的甘甜，是东方古老酿造艺术在末日余晖下的微弱延续。",
        en = "Steamed rice embracing koji mold cultures in an ivory mash, carrying delicate aromas of grain and promising a refined sip amid widespread barbarism.",
    },
    ["brew_sake_koji"] = {
        zh = "沾满灰绿色曲霉孢子的熟米团，散发着奇特的泥土甜味，虽然是古老的废弃配方，但依然承载着发酵文明的微光。",
        en = "Cooked rice granules dusted with greenish koji spores; an obsolete experimental recipe, yet still holding the primordial spark of grain fermentation.",
    },
    ["brew_sake_koji_active"] = {
        zh = "接种了活性曲霉的蒸米，菌丝正如同白色天鹅绒般密密麻麻地包裹米粒，散发出类似于鲜蘑菇和湿树叶的芬芳。",
        en = "Active Aspergillus cultures blooming like velvet across steamed grains, filling the humid cellar with earthy aromas akin to wild mushrooms and forest duff.",
    },
    ["brew_soy_sauce"] = {
        zh = "盐水、碎大豆与炒面粉混合的泥泞酱汁，在曲霉的作用下正在漫长地分解，虽然现在卖相糟糕，却是未来鲜味的核心。",
        en = "A salty brine churning with mashed soybeans and wheat flour; unsightly in its youth, yet slowly decomposing into the savory umami lifeblood of cooking.",
    },
    ["brew_spiced_mead"] = {
        zh = "在浓郁蜂蜜水中浸泡了肉桂、丁香与豆蔻的热浆，香料的辛烈与蜂蜜的甘美完美融合，等待着寒冬时节的开桶盛宴。",
        en = "Honeyed water steeped with cracked cinnamon bark, cloves, and nutmeg, balancing spicy heat and floral sweetness while awaiting winter's celebratory unsealing.",
    },
    ["brew_vinegar"] = {
        zh = "由果汁和残酒混合而成的酸败液体，醋酸菌正在水面上结成厚厚的菌膜，准备把酒精彻底转化为呛人鼻窦的烹饪酸醋。",
        en = "Spoiled cider and stale dregs congealing under a rubbery mother of vinegar, systematically oxidizing innocent ethanol into sharp, nose-stinging acetic seasoning.",
    },
    ["brew_vodka"] = {
        zh = "用煮烂土豆和麦芽酶解出的淀粉糖水，外表浑浊泥泞，但发酵蒸馏后的透明烈火足以融化西伯利亚寒夜里最坚硬的绝望。",
        en = "Mashed potato slurry liquefied by malt enzymes; murky and grey, yet promising pure distilled fire capable of melting any desolate winter gloom.",
    },
    ["brew_whiskey"] = {
        zh = "粗磨谷物在热水里糖化出的浑浊原浆，散发着熟麦片的温暖香气，若能在橡木桶里沉睡三年，它就是废土上最昂贵的硬通货。",
        en = "Cloudy cereal mash releasing the comforting steam of cooked porridge; aged three years in oak, this liquid gold easily buys an entire armored convoy.",
    },
    ["brewing_cookbook"] = {
        zh = "封面沾满酒渍与酵母干渣的自酿指南，用极其通俗的语言教你如何用烂苹果、玉米粒甚至蒲公英把自己灌得人事不省。",
        en = "A stained homebrewing manual detailing how to turn rotten apples, cracked corn, or roadside weeds into potent beverages capable of obliterating sober anxiety.",
    },
    ["brick"] = {
        zh = "经过烈火焙烧的规整红砖，不仅是砌筑坚固避难所墙体的基石，在丧尸靠近时也是一块趁手且破拆力惊人的投掷重物。",
        en = "A kiln-fired red clay block; primarily destined for building perimeter walls, but equally celebrated as an immediate blunt projectile for shattering ghoul teeth.",
    },
    ["brick_oven_pseudo"] = {
        zh = "当游戏底层代码都在警告你这是一个伪物品时，最好的生存策略就是假装它真是一座砖砌烤炉，否则你的生面团就无处可烤了。",
        en = "When the underlying engine warns that this oven is technically a phantom bug, the wisest survival move is pretending it works anyway to bake bread.",
    },
    ["briefcase"] = {
        zh = "带有黄铜锁扣的硬皮公文包，战前里面塞满了机密合同与股票债券，如今里面装几卷绷带和一包牛肉干反而显得更加尊贵。",
        en = "A latched leather case once stuffed with corporate contracts and worthless stocks, now far more respectably occupied by sterile bandages and smoked beef jerky.",
    },
    ["briefcase_smg"] = {
        zh = "特工专用的手提箱冲锋枪，扣动提手上的暗掣就能隔着公文包外壳倾泻弹雨，让任何试图搜身检查的劫匪瞬间领悟商务礼仪。",
        en = "A covert briefcase housing a suppressed MP5 triggered via the handle, delivering sudden lethal firepower to bandits demanding an impromptu business presentation.",
    },
    ["briefs"] = {
        zh = "剪裁紧凑的男式纯棉三角内裤，虽然不如四角裤透气通风，但在狂奔逃命时能牢牢稳固要害，避免任何多余的摇晃与摩擦。",
        en = "Classic snug cotton briefs; though lacking the airy ventilation of boxers, they keep vital anatomy securely fastened during desperate sprints away from predators.",
    },
    ["brioche"] = {
        zh = "揉入了大量黄油与鸡蛋的法式奶油面包卷，金黄松软且香气扑鼻，在满嘴野菜苦味的废土上，咬上一口简直是对苦难的彻底背叛。",
        en = "A golden bun enriched with obscene amounts of butter and egg yolks; biting into its plush crumb feels like an outright luxury treason against post-apocalyptic misery.",
    },
    ["bristol_sherry"] = {
        zh = "在橡木桶中陈酿多年的高级奶油雪利酒，深琥珀色的酒液带着葡萄干的醇甜，在废墟烛光下小酌一口，仿佛文明从未远去。",
        en = "Rich amber fortified wine aged in seasoned casks; sipping its sweet raisin notes by candlelight temporarily tricks the palate into forgetting the apocalypse.",
    },
    ["broadsword"] = {
        zh = "全钢锻造的中世纪阔剑，沉重的双刃剑身与坚固的护手兼备，挥击时带着破空呼啸，能干脆利落地把扑上来的丧尸劈成两半。",
        en = "A broad double-edged blade forged from balanced steel, possessing sufficient momentum to cleave through padded winter coats and rotten bone alike.",
    },
    ["broadsword_fake"] = {
