    ["broken_turret_riot"] = {
        zh = "发射橡皮子弹与催泪瓦斯的防暴炮塔残体，储气罐已经泄露殆尽，塑料防暴弹头滚得满地都是，再也无法维持所谓的街头秩序。",
        en = "A crowd-control platform stripped of compressed air; rubber batons and spent dispersal canisters litter the pavement around its mute, non-lethal barrel.",
    },
    ["broken_turret_searchlight"] = {
        zh = "大功率军用探照灯塔残骸，高压氙气灯泡早已粉碎，只剩下一个空洞的抛物面反射碗，在月光下倒映着凄凉的星空。",
        en = "A high-intensity military searchlight station with its xenon bulb shattered, leaving behind only a convex reflector to catch the pale, lonely moonlight.",
    },
    ["broken_turret_speaker"] = {
        zh = "用于向暴民播送戒严广播的高音扩音器塔残件，喇叭纸盆被撕碎，整个废墟终于迎来了它早该拥有的永恒死寂。",
        en = "A psychological warfare loudspeaker mount with shredded diaphragms; its destruction permanently silences looped pre-war curfew broadcasts, restoring blessed post-apocalyptic quiet.",
    },
    ["broken_yrax_delta"] = {
        zh = "如同箭头般锋利的未知合金残片，来自地外构装体的致命锋刃，表面光滑得连雨水都无法停留，冰冷得不属于这个世界。",
        en = "An alien arrow-shaped shard of unearthly alloy; frictionlessly smooth and impervious to corrosion, it feels unnatural and unnervingly cold in human hands.",
    },
    ["broken_yrax_quadraphract"] = {
        zh = "由金黄合金与闪烁水晶嵌合而成的四足异星战偶残躯，哪怕核心熄灭，那不可名状的精美雕刻依然散发着令人窒息的异界神圣感。",
        en = "A downed crystalline-and-gold construct lying folded upon itself; even devoid of animating energy, its alien symmetry radiates chilling architectural divinity.",
    },
    ["broken_yrax_quadraphract_leg"] = {
        zh = "异星战构体断裂的巨大镰刀状足节，坚硬得可以划开最厚的防弹钢板，如果扛回去装在战车前端，就是一柄完美的撞角利刃。",
        en = "A massive scythe-like limb sheared from an extraterrestrial walker; harder than forged carbon steel, making it an extraordinary prospective ramming spur for armored buggies.",
    },
    ["broken_yrax_triakis"] = {
        zh = "碎裂的三棱体外壳内部露出一整块浑然天成的异星集成结构，没有半根电线或螺栓，彻底嘲弄了人类对于机械工程的浅薄理解。",
        en = "Shattered triakis plating exposing solid-state internal geometries devoid of wires or fasteners, mocking our primitive human understanding of electrical engineering.",
    },
    ["broken_yrax_trifacet"] = {
        zh = "裂开的三琢面异形构件，内部精密咬合的齿轮和金色晶体在微光下偶尔折射出眩目光芒，仿佛只是在沉睡而非真正死亡。",
        en = "Split geometric facet reveals microscopic interlocking crystal gears that still refract ambient light, looking more like a slumbering alien intelligence than dead metal.",
    },
    ["broketent"] = {
        zh = "支架折断且防雨布撕裂的破烂单人帐篷，在晴天它勉强能给你遮挡刺眼的阳光，但在雨夜它只会把外面的暴雨精准汇聚到你的脸上。",
        en = "A battered one-person shelter with fractured poles and torn seams; offers reasonable shade on dry afternoons, but channels driving rain directly onto your sleeping face.",
    },
    ["bronze_armor_cow"] = {
        zh = "专为耕牛量身打造的重型青铜护甲片与皮带组合，虽然看起来像是某种荒诞的青铜时代阅兵道具，但确实能防住丧尸狗的撕咬。",
        en = "Plated bronze cow barding laced with thick leather ties; undeniably ridiculous to behold, yet effectively shields your prize milk beast from roving zombie hounds.",
    },
    ["bronze_armor_horse"] = {
        zh = "闪耀着厚重古铜光泽的青铜战马铠甲，把你的坐骑全副武装成中世纪或青铜时代的冲锋铁兽，威风凛凛但也沉得让战马气喘吁吁。",
        en = "Heavy hammered bronze plates designed to protect equestrian mounts from thrusting spears; looks heroically antique, though the horse definitely groans under the added tonnage.",
    },
    ["bronze_atlatl_spear"] = {
        zh = "配有铸造青铜矛尖与羽翎的投矛器标枪，依靠力臂杠杆甩飞出去时带着破甲呼啸，是猎杀变异巨兽最具性价比的原始重火力。",
        en = "A bronze-tipped javelin tailored for atlatl throwing; hurled with leverage, it punches through thick hides with astonishing kinetic violence without consuming gunpowder.",
    },
    ["bronze_axe"] = {
        zh = "经过冷锻硬化刃口的套筒青铜伐木斧，沉重而坚固，虽然刃口比现代钢斧更容易卷刃，但在没有炼钢炉的废土上它就是神兵利器。",
        en = "A work-hardened socketed bronze axe; while requiring more frequent whetstone maintenance than high-carbon steel, it chops firewood dependably when civilization vanishes.",
    },
    ["bronze_book"] = {
        zh = "厚如砖头般的青铜时代工艺巨著，详细记录了如何采矿、配比红铜与锡以及铸造各种器具，是文盲文明重启的最硬核参考书。",
        en = "A dense encyclopedic volume documenting copper-tin smelting and ancient casting techniques, serving as an irreplaceable practical manual for rebooting metallurgical technology.",
    },
    ["bronze_brush_axe"] = {
        zh = "带有微曲刀刃与木柄的青铜钩镰斧，既能轻松斩断挡路的带刺荆棘，也能在变异怪物扑来时顺势勾住它的咽喉向下猛拽。",
        en = "A hooked bronze bill blade firmly anchored to an ash haft; excels at severing tangled briars or snagging mutant extremities during close-quarters panic.",
    },
    ["bronze_brush_handaxe"] = {
        zh = "刃头前凸且带有反钩的单手青铜柴刀，短小精悍且重心靠前，无论在茂密森林里开路还是在废墟狭窄走廊防身都非常利落。",
        en = "A compact bronze bill with a forward-weighted hook, balanced for clearing tangled roadside thickets or slicing through leather armor in confined hallway skirmishes.",
    },
    ["bronze_brush_pole"] = {
        zh = "安装在长木杆顶端的长柄青铜钩镰，让你能在安全距离之外把树上的成熟果实勾下来，或者顺手把高处的丧尸脑袋拽进陷阱。",
        en = "An elongated polearm tipped with a curved bronze bill hook, allowing survivors to harvest high tree fruit or dismount hostile ambushers from atop barricades.",
    },
    ["bronze_file"] = {
        zh = "用来修整金属边缘的青铜锉刀组，虽然硬度不如高碳钢锉刀，但用来打磨铜器、木器和铅弹依然能带来极为顺滑的切削手感。",
        en = "A specialized suite of cast bronze rasps; softer than tool steel, but perfectly adequate for finishing softer alloys, smoothing wooden hafts, or shaping lead bullets.",
    },
    ["bronze_hoe"] = {
        zh = "沉重结实的青铜农用锄头，铜锡合金赋予了它出色的耐腐蚀能力，深埋在潮湿泥土里也不必担心像铁锄头那样迅速锈烂成渣。",
        en = "A hefty agricultural hoe cast from durable bronze; unlike vulnerable iron tools, it resists damp soil corrosion while churning up fresh garden beds.",
    },
    ["bronze_knife"] = {
        zh = "一体铸造并缠绕了鞣制皮条的青铜直刀，带着古朴典雅的铜绿色调，虽然需要经常磨刀，但剥皮割肉时的手感格外温润扎实。",
        en = "A full-tang bronze dagger wrapped in oiled leather cord; its edge demands regular stropping, yet possesses a warm, dependable balance during field dressing.",
    },
    ["bronze_mag"] = {
        zh = "全彩印刷的古代军事历史杂志，封面印着全副武装的迈锡尼青铜武士，是废土幸存者学习如何在没有火药的世界打群架的通俗读物。",
        en = "A glossy historical magazine detailing bronze-age warfare and shield walls, offering practical tactical tutorials for survivors suddenly thrust backward into antiquity.",
    },
    ["bronze_medal"] = {
        zh = "原本颁发给运动会季军的纯铜奖牌，丝带已经褪色，在末日里没有人会在意第三名的荣誉，但熔成焊条或箭头倒是非常实在。",
        en = "A third-place athletic medallion on a frayed ribbon; sports glory is meaningless in the ruins, but five ounces of pure bronze melts down splendidly.",
    },
    ["bronze_nail"] = {
        zh = "手工锻造的针状青铜钉，虽然比铁钉更容易弯折，但优秀的防腐蚀特性让它成为建造海船或潮湿地窖木架的绝佳固定件。",
        en = "A hand-hammered bronze peg; though slightly prone to bending under wild hammer blows, its imperviousness to marine rot makes it invaluable for boatbuilding.",
    },
    ["bronze_pickaxe"] = {
        zh = "配有尖锐凿头和坚固硬木柄的青铜鹤嘴锄，虽然用来开凿花岗岩有些勉强，但在采掘泥灰岩和黏土矿层时表现得极其可靠。",
        en = "A heavy-headed bronze pick with an ash handle; too soft for deep granite tunneling, but wonderfully capable of breaking clay hardpan and soft sandstone.",
    },
    ["bronze_shears"] = {
        zh = "一体锻造且富有弹性的青铜剪刀，依靠U形弹簧片开合，用来修剪羊毛、裁切布料或者给自己的乱发剪个平头都格外顺手。",
        en = "One-piece spring-tensioned shears cast from bronze; wonderfully reliable for shearing sheep, tailoring coarse canvas cloaks, or executing dreadful self-administered haircuts.",
    },
    ["bronze_sickle"] = {
        zh = "弯曲如新月般的青铜割草镰刀，刀刃锋利且弧度完美，在秋风萧瑟的田野里收割金黄麦浪时，能让人重温数千年前的农耕诗意。",
        en = "A crescent-shaped bronze harvesting sickle; balanced for sweeping strokes through golden wheat stalks, channeling thousands of years of human agrarian heritage.",
    },
    ["broom"] = {
        zh = "带有长木柄的传统扫帚，除了用来清理避难所地板上的灰尘碎屑外，如果拿来挥向变异蟑螂，大概只能激怒对方并把它扫到你脸上。",
        en = "A classic long-handled straw broom; superb at brushing dust from shelter floorboards, thoroughly pathetic if swung at giant insects unless you enjoy provoking them.",
    },
    ["broth"] = {
        zh = "用胡萝卜、洋葱和野芹菜熬制出的清亮蔬菜汤，虽然缺乏让人满足的油脂，但温热甘甜的汤水足以舒缓饥肠辘辘的空虚肠胃。",
        en = "Clear vegetable stock simmered from roots and foraged celery; low on calories, but hot and fragrant enough to soothe an empty, rumbling belly.",
    },
    ["broth_bone"] = {
        zh = "把搜刮来的动物骨骼敲碎并在沸水中慢炖数小时熬出的白汤，富含骨髓油脂与明胶，是对抗废土严寒最有力的营养滋补剂。",
        en = "Rich stock boiled from marrow bones until gelatinous and opaque, delivering dense collagen and warm minerals to combat frostbitten apocalyptic misery.",
    },
    ["broth_meat"] = {
        zh = "用几片肉碎在开水里煮沸熬出的清炖肉汤，漂浮着点点金黄油花，哪怕只放了一小捏粗盐，在寒风中喝上一口也能让人重燃活下去的希望。",
        en = "Savory meat liquor shimmering with fat droplets; seasoned with a pinch of coarse salt, sipping it by the fire rekindles the stubborn desire to survive.",
    },
    ["brown_bread"] = {
        zh = "用黑麦面粉与浓稠糖蜜烘烤出来的黑面包，口感结实厚重甚至带有一丝发糕般的甜糯，吃上一小块就能顶住大半天的重体力劳作。",
        en = "Dense loaf sweetened with dark molasses, possessing a chewy texture that sticks to ribs and powers hours of grueling manual scavenging without hunger pangs.",
    },
    ["brownie"] = {
        zh = "表面带着诱人微裂纹的浓郁巧克力布朗尼，甜腻、绵密且充满黄油香气，就像战前奶奶在温暖壁炉旁烤出来的一模一样。",
        en = "A fudgy chocolate square with cracked crust and chewy corners, tasting precisely like the comforting confections a loving grandmother would bake before the catastrophe.",
    },
    ["brownie_weed"] = {
        zh = "散发着明显草本青草味与可可香气的特制布朗尼，这绝对不是慈祥奶奶会烤出的点心，吃下半块就能让你在沙发上傻笑一整天。",
        en = "A pungent chocolate bar with an unmistakably dank herbal aroma; definitely not baked by grandmother, offering half a day of serene couch-locked giggles.",
    },
    ["browning_a5"] = {
        zh = "外形独特的驼背式半自动狩猎霰弹枪，长后坐动作结实可靠，连续四发十二号鹿弹的轰鸣足以让任何伏击者明白谁才是丛林之王。",
        en = "The legendary humpback semi-automatic shotgun with recoil-operated action; cycling four heavy buckshot shells quickly settles disputes with territorial forest carnivores.",
    },
    ["browning_blr"] = {
        zh = "采用旋转枪机与齿轮齿条传动的精致杠杆步枪，兼具杠杆枪的快速射速与栓动步枪的射击精度，是游荡猎手最信赖的精准伙伴。",
        en = "A rack-and-pinion lever-action rifle feeding modern spitzer cartridges, delivering swift follow-up shots with pinpoint accuracy across open fields.",
    },
    ["brush"] = {
        zh = "硬质塑料丝刷子，在灾前用来刷洗烧烤架上的顽固焦炭，在废土上则常常用来刷洗沾在靴子底部的腐烂丧尸内脏。",
        en = "A coarse plastic scrubbing brush; once employed to scour charred barbecue grates, now constantly scrubbing putrid ghoul intestines from your boot treads.",
    },
    ["brush_axe"] = {
        zh = "将厚重月牙弯刀与伐木斧结合的重型钩镰斧，挥砍时能破开坚硬骨骼，倒钩则能在敌人仓皇逃窜时一把将它拖回身前。",
        en = "A wicked hooked axe marrying a chopping blade with a vicious back-spike, splitting dense bone on impact or dragging fleeing hostiles back into range.",
    },
    ["brush_handaxe"] = {
        zh = "装有坚固木柄的单手精钢柴刀，弯曲的刃尖非常适合割断阻挡去路的带刺灌木，或者在逼仄的房门口勾砍袭来的爪子。",
        en = "A hooked steel brush cutter with a sturdy hickory grip, ideal for slicing tangled thorns or hooking reaching zombie claws in cramped doorways.",
    },
    ["brush_pole"] = {
        zh = "安装在粗长白蜡木杆前端的长柄精钢钩镰，赋予幸存者居高临下的防御优势，能在两米开外干脆利落地勾断丧尸的脚筋。",
        en = "A curved steel bill mounted atop a two-meter ash shaft, granting superior defensive reach to sever zombie hamstrings well beyond biting range.",
    },
    ["brush_toilet"] = {
        zh = "丧尸不会感到受辱，也没人需要再清洗抽水马桶，但这根沾满可疑污渍的硬毛刷至少能让你体面地戳开挡路的变异大老鼠。",
        en = "Zombies feel neither shame nor disgust, but brandishing this stiff, stained porcelain brush remains a surprisingly effective deterrent against inquisitive mutant rats.",
    },
    ["brussels_sprout"] = {
        zh = "外形如微缩卷心菜般的小巧绿甘蓝，虽然煮熟后带有一股独特的微苦味道，但在绿叶蔬菜绝迹的冬天，它是顶级的维生素宝库。",
        en = "Tiny emerald cabbages packed with dense nutrients; though releasing a sulfurous bitterness when boiled, they deliver lifesaving vitamins during bleak winter famines.",
    },
    ["brussels_sprout_stalk"] = {
        zh = "挂满了密密麻麻抱子甘蓝的粗壮绿色茎秆，直接扛在肩上像一根狼牙棒，既是新鲜的蔬菜串，也是绿油油的应急钝器。",
        en = "A thick vegetable stalk encrusted with miniature leafy nodules, slung over a shoulder like a verdant mace that doubles as several days of fresh greens.",
    },
    ["bscabbard"] = {
        zh = "用厚实公牛皮缝制的背负式大剑鞘，虽然拔刀时总需要把胳膊拉得很长，但背在身后能让每一个废土游侠都显得格外冷酷英挺。",
        en = "A heavy-duty bull-hide back scabbard; while unsheathing a long blade requires comical arm contortions, it instantly grants you dramatic wasteland wanderer swagger.",
    },
    ["bt_apc9k"] = {
        zh = "瑞士精工制造的紧凑型闭膛待击冲锋枪，射速惊人且后坐力柔和，在狭窄的地下掩体走廊里，是向敌人泼洒弹雨的战术终极答案。",
        en = "A premium Swiss-engineered compact submachine gun with silky recoil; in narrow underground bunker corridors, its blistering cyclic rate settles all tactical arguments.",
    },
    ["btmp9mag_9x19mm_10rd"] = {
        zh = "十发装的半透明聚合物短弹匣，小巧平整得几乎不会凸出握把，虽然容弹量捉襟见肘，但在紧要关头依然能救下你一条小命。",
        en = "A stubby ten-round polymer magazine that sits flush in the grip; painfully limited in capacity, but miraculously compact for discreet concealed carry.",
    },
    ["btmp9mag_9x19mm_15"] = {
        zh = "十五发容量的半透明聚合物弹匣，在便携性与持续火力之间达成了精妙平衡，能让你一眼看清里面仅存黄铜弹药的消耗速度。",
        en = "A translucent polymer stick holding fifteen rounds; nicely balancing bulk against firepower while letting you monitor your dwindling brass supply at a glance.",
    },
    ["btmp9mag_9x19mm_20"] = {
        zh = "二十发容量的中号透明弹匣，在密闭室内突击时提供充裕的短点射弹量，是兼顾换弹手感与背包容积的标准战术配置。",
        en = "A twenty-round clear polymer magazine offering sufficient burst capability during building sweeps without turning your sidearm into an unwieldy walking stick.",
    },
    ["btmp9mag_9x19mm_25"] = {
        zh = "二十五发聚合物长弹匣，外壳坚韧防刮，无论在泥浆里摸爬滚打还是从高处跌落，都能稳定将九毫米子弹一颗颗推入枪膛。",
        en = "A rugged twenty-five round translucent magazine engineered to endure drops and gritty mud, feeding parabellum rounds flawlessly under intense panic fire.",
    },
    ["btmp9mag_9x19mm_30"] = {
        zh = "三十发军规全尺寸聚合物弹匣，给紧凑的冲锋枪插上一对结实的獠牙，只要扣住扳机不放，就能在两秒钟内制造一场弹幕风暴。",
        en = "A full-capacity thirty-round stick feeding sustained full-auto bursts, converting your compact submachine gun into an uncontrollable room-clearing buzzsaw.",
    },
    ["btmp9mag_9x19mm_50rd"] = {
        zh = "笨重庞大的五十发铝合金双排弹鼓，虽然插在枪上会让整把武器头重脚轻，但在被尸群团团围住时，谁会嫌弃弹药太多呢。",
        en = "A bulky fifty-round drum magazine that completely ruins weapon balance; when encircled by a screaming horde, however, aesthetic ergonomics become utterly irrelevant.",
    },
    ["bubblewrap"] = {
        zh = "布满充气小气泡的塑料缓冲垫，除了用来保护脆弱物品外，也是全人类公认的减压神器；但在潜行时踩上一脚无异于自杀。",
        en = "A sheet of pressurized plastic bubbles; universally therapeutic to pop in safety, yet stepping onto one during a night infiltration is outright suicidal.",
    },
    ["bucket"] = {
        zh = "表面镀锌的结实白铁皮水桶，既能从被污染的井里打水，也能在暴风雨之夜反扣在脑袋上充当一面咣当作响的临时头盔。",
        en = "A galvanized iron pail for hauling well water, washing laundry, or slamming over your head during a sudden hail storm as an impromptu clattering helmet.",
    },
    ["bucket_5gal"] = {
        zh = "建筑工地上随处可见的亮橙色五加仑大塑料桶，容量惊人且带结实提手，是废土拾荒者搬运废铁、机油和腌菜的万能容器。",
        en = "A ubiquitous five-gallon orange plastic bucket; remarkably resilient and spacious, serving wasteland looters as an all-purpose vessel for scrap, fuel, or pickles.",
    },
    ["bucket_wood"] = {
        zh = "用硬木实木精心凿刻拼接并套上铁箍的传统木水桶，沉甸甸的很有质感，只要木板不干裂漏水，它就是水井旁最忠实的水车伴侣。",
        en = "A coopered wooden bucket bound with iron hoops; rustic and heavy, demanding perpetual dampness to keep its stave joints swollen shut against leaking.",
    },
    ["buckle_steel"] = {
        zh = "坚固的冲压精钢皮带扣，表面镀铬防锈，不管是用来缝补快要断裂的战术腰带，还是用来加固重型背包的受力肩带都非常关键。",
        en = "A solid stamped steel harness buckle; crucial for mending frayed tactical belts or reinforcing high-stress webbing before heavy packs tear off your shoulders.",
    },
    ["buckwheat"] = {
        zh = "野外采集到的干燥荞麦种子，带有一层坚硬的黑褐色外壳，虽然直接生嚼会磕碎牙齿，但磨成面粉后能做出香气扑鼻的面饼。",
        en = "Hard triangular buckwheat grains wrapped in dense black hulls; unchewable raw, but yielding wonderfully earthy flour for nutrient-dense griddle cakes.",
    },
    ["buckwheat_cooked"] = {
        zh = "煮得软烂开花的荞麦热粥，带有一股独特的苦香与泥土清香，虽然口感粗糙，但能给冻僵的胃袋提供漫长而平稳的饱腹感。",
        en = "A steaming bowl of cooked buckwheat porridge; slightly bitter with wholesome nutty depth, releasing sustained carbohydrates to fuel hours of freezing winter patrols.",
    },
    ["buckwheat_stalks"] = {
        zh = "齐腰高的长叶荞麦秸秆，穗头上缀满了沉甸甸的三角籽粒，只要在防雨棚下脱粒晒干，就是整整一个冬天的救命口粮储备。",
        en = "Waist-high leafy buckwheat stalks laden with ripening grain clusters; harvesting and thrashing these bundles secures essential carbohydrate survival reserves for the winter.",
    },
    ["budget_steel_chunk"] = {
        zh = "从廉价货架或劣质护栏上砸下来的一块粗钢废料，形状扭曲且边缘毛糙，但在没有工具时，拿它直接砸烂丧尸脑袋也未尝不可。",
        en = "A jagged scrap chunk of low-grade structural steel; coarse and misshapen, yet heavy enough to crush a zombie cranium if thrown with desperate intent.",
    },
    ["budget_steel_lump"] = {
        zh = "经过粗劣熔炼浇铸的粗钢锭，虽然内部气孔密布且杂质较多，但在缺乏现代合金的废土上，它依然是锻造粗劣刀剑的好底子。",
        en = "A heavy ingot of poorly refined scrap steel pitted with slag bubbles; far from aerospace grade, but entirely sufficient for hammering out crude machetes.",
    },
    ["bulk_liquid_tank"] = {
        zh = "由十个钢制大储罐串联焊接而成的大型散装储液架，能安全容纳六百升燃油或清水，是每一座永久要塞车间最令人安心的生命线。",
        en = "An interconnected rack of ten industrial steel tanks holding six hundred liters of precious fuel or purified water, anchoring the fortress supply depot.",
    },
    ["bullet_crossbow"] = {
        zh = "经过特殊改装的弹弓弩，利用弓弦的强大张力发射重型钢珠或铅弹，既避开了制作复杂弩箭的繁琐，又保留了近乎无声的暗杀特性。",
        en = "A hybrid crossbow modified to fling heavy lead slugs or steel ball bearings, eliminating arrow crafting hassles while preserving terrifyingly silent assassination capabilities.",
    },
    ["bullwhip"] = {
        zh = "由生牛皮精心编织而成的长皮鞭，挥动时鞭梢能突破音速发出清脆的炸响，虽然杀伤力平平，但对付变异野狗时有奇妙的威慑奇效。",
        en = "A braided rawhide whip whose leather popper cracks the sound barrier; while lacking armor penetration, the sonic snap terrifies approaching packs of feral dogs.",
    },
    ["bullwhip_razor"] = {
        zh = "带有九条皮带并镶嵌了锋利碎铁片的九尾鞭，原本是残酷刑罚的象征，现在挥舞起来能在成群的肉身怪物身上撕开漫天血痕。",
        en = "A brutal cat-o-nine-tails bristling with barbed steel splinters, formerly a sadistic torture scourge, now repurposed to flay flesh from unarmored abominations.",
    },
    ["bum_wine"] = {
        zh = "极其廉价的高度强化甜葡萄酒，装在粗糙的塑料瓶里，带着一股浓烈的工业酒精和糖精味，是废土流浪汉告别清醒最迅速的捷径。",
        en = "A plastic jug of fortified bum wine reeking of chemical flavoring and industrial ethanol, serving as the quickest and cheapest detour away from sobriety.",
    },
    ["bunker_coat"] = {
        zh = "消防员专用的厚重防火防护外套，由耐磨凯夫拉与阻燃芳纶层层缝合，不仅能抵御烈焰灼烧，甚至能硬抗丧尸疯狂的撕咬。",
        en = "A heavy-duty firefighter turnout jacket woven from Kevlar and Nomex; impervious to scorching embers and surprisingly resilient against desperate zombie bites.",
    },
    ["bunker_pants"] = {
        zh = "厚实笨重的消防长裤，带有加宽背带和反光条，虽然穿上后走起路来像个臃肿的太空人，但下半身的防刺防烫防护直接拉满。",
        en = "Bulky thermal firefighting overalls equipped with high-visibility stripes; cumbersome to sprint in, but granting near-impenetrable lower-body insulation against puncture and burns.",
    },
    ["bunny_ears_black"] = {
        zh = "缝在塑料发箍上的毛绒黑色兔耳，毛茸茸的触感十分柔软，在崩坏的废土上戴着它搜刮，除了彰显独特的末日审美外毫无防护意义。",
        en = "Fuzzy black rabbit ears mounted on a plastic headband; offering zero ballistic or environmental defense, but adding unforgettable chaotic style to scavenging runs.",
    },
    ["bunny_suit_playboy"] = {
        zh = "在废墟衣柜深处找到的紧身兔女郎连体衣，光滑反光的缎面材质依然光鲜，虽然防御力无限趋近于零，但绝对能给避难所带来精神震撼。",
        en = "A sleek satin playboy bunny bodysuit preserved inside a closet; completely devoid of protective qualities, yet guaranteed to generate pure theatrical campsite shock.",
    },
    ["burdock_cooked"] = {
        zh = "用沸水焯熟并去除苦味的野生牛蒡嫩叶，虽然口感类似于煮烂的青草，但在缺乏维生素的地下避难所里，它能拯救你溃烂的牙龈。",
        en = "Boiled burdock greens rendered palatable through vigorous blanching; tastes distinctly like lawn clippings, but heroically rescues your bleeding gums from scurvy.",
    },
    ["burdock_fried"] = {
        zh = "裹上面糊用热油炸至金黄酥脆的野牛蒡根，表皮咔嚓作响，内芯软糯微甘，是荒野求生食谱中不可多得的高热量人间美味。",
        en = "Wild burdock roots dipped in batter and fried to golden perfection, offering a crispy, nutty crunch that briefly rivals pre-war fast food indulgences.",
    },
    ["burdock_wine"] = {
        zh = "用牛蒡根精心发酵酿造的草本低度果酒，带着一丝泥土的清冽甘甜与微苦回味，在火堆旁小酌不仅暖胃，还能抚平焦虑的神经。",
        en = "A light herbal vintage fermented from wild burdock root; slightly earthy with a mellow sweetness, perfect for sipping around evening embers to settle ragged nerves.",
    },
    ["burette"] = {
        zh = "带有高精度活塞的细长玻璃滴定管，刻度细密而精确，如果不想在配制炸药或强酸时因为多滴了一滴而把自己炸飞，它是必备神器。",
        en = "A graduated glass tube with a precision stopcock; an indispensable laboratory instrument when synthesizing volatile explosives without accidentally detonating your own tabletop.",
    },
    ["burnt_out_bionic"] = {
        zh = "在剧烈电击或电磁脉冲下彻底烧焦的生化义体，曾经是昂贵的人体改造科技，如今里面的芯片全部炭化，只剩下几根废铜烂线。",
        en = "A charred bionic implant whose internal microprocessors were fried to ash by electromagnetic pulses, leaving behind worthless silicon and melted copper traces.",
    },
    ["butane"] = {
        zh = "高度易燃的液化丁烷燃料，无论用来给一次性打火机充气，还是用来给便携式喷火枪供火，都是废土上点燃希望之火的重要能源。",
        en = "Highly flammable liquefied hydrocarbon gas; whether replenishing plastic lighters or running handheld soldering torches, it reliably fuels the flames of survival.",
    },
    ["butane_can"] = {
        zh = "配有多种充气转接头的便携式丁烷气罐，只要小心对准充气阀门往下按压，就能让干瘪的打火机重新迸发出温暖可靠的蓝色火苗。",
        en = "A slim aerosol canister with universal filling nozzles, ready to recharge dried-out lighters and keep your fires burning through damp, sodden weeks.",
    },
    ["butane_tank"] = {
        zh = "厚壁钢质高压压缩丁烷气罐，阀门密封完好，不仅能为长期驻地的野营灶台提供数周的燃料，必要时挂上雷管就是一枚猛烈的燃料炸弹。",
        en = "A pressurized steel tank containing compressed butane; equally suited for powering camp stoves for weeks or being wired into a devastating makeshift fuel-air bomb.",
    },
    ["butchering_kit"] = {
        zh = "卷在帆布包里的专业屠宰刀具套件，剔骨刀、剥皮刀与排骨锯一应俱全，能让你在半小时内把一头巨鹿肢解得干干净净、分毫不浪费。",
        en = "A roll-up canvas pouch containing honed boning knives and skinning blades, allowing skilled hunters to strip clean cuts from giant game without wasting meat.",
    },
    ["butchery_tree_pseudo"] = {
        zh = "当游戏代码向你弹出一棵屠宰树的伪物品警告时，假装它是一根挂满肉钩的结实树杈就好，毕竟肉块挂在上面总比掉在泥里强。",
        en = "When the simulation coughs up a phantom butchery tree bug, simply pretend it is a real timber frame; hanging venison beats dropping it in the mud.",
    },
    ["butt_hook"] = {
        zh = "安装在枪托底部的弧形铝合金尾钩，能牢牢卡在射手的腋下提供三角支撑，即使端着沉重的大口径步枪长时间瞄准也不会让手臂颤抖。",
        en = "An ergonomic aluminum hook clamping underneath the shooter's armpit, distributing rifle weight to eliminate muscle fatigue during prolonged precision overwatch.",
    },
    ["butter"] = {
        zh = "一整块金黄诱人的天然动物黄油，富含浓郁的乳脂香气与救命的热量，无论是抹在干硬面包上还是煎野蘑菇，都是极致的味觉救赎。",
        en = "A solid golden brick of churned milkfat; packed with lifesaving calories and decadent aroma, transforming hardtack and foraged wild mushrooms into banquet fare.",
    },
    ["butter_churn"] = {
        zh = "一个配有木质搅拌叶片与摇把的传统立式搅黄油木桶。只要往里面倒入足量的新鲜牛奶并耐心地摇晃半小时，你就能收获一块散发着诱人乳香的纯天然黄油块。",
        en = "A traditional wooden butter churn fitted with hand-cranked internal paddles. Agitating fresh milk patiently for thirty minutes separates thick buttermilk, yielding blocks of golden, fragrant natural butter.",
    },
    ["buttercream"] = {
        zh = "用大量黄油与糖粉搅拌得极其细腻顺滑的奶油糖霜，甜得让人牙齿发酸，但这种纯粹的高糖高脂炸弹能给绝望的大脑注入海量多巴胺。",
        en = "Whipped butter and powdered sugar creating decadent frosting, sweet enough to cause toothaches while flooding your exhausted brain with unadulterated dopamine.",
    },
    ["buttered_toast"] = {
        zh = "抹上厚厚一层融化咸黄油的金黄烤吐司片。浓郁的奶香与焦脆的麦香交织在一起，在阴暗潮湿的避难所里咬下一口，那份简单纯粹的美味能驱散一切彻骨严寒。",
        en = "A slice of warm toast generously slathered with melted salted butter. The crisp golden crust and rich savory aroma provide a transcendent burst of domestic comfort inside dreary concrete bunkers.",
    },
    ["butterfly_net_collapsible"] = {
        zh = "采用轻质铝合金折叠杆制成的便携蝴蝶网，收起时只有折伞大小，展开后能在几秒钟内捕捉任何乱飞的珍稀蝴蝶或毒飞虫。",
        en = "A collapsible aluminum-framed insect net; shrinking down like an umbrella for travel, ready to deploy in seconds to capture fluttery pollinators or toxic bugs.",
    },
    ["butterfly_net_collapsible_extended"] = {
        zh = "完全拉伸展开的长柄折叠昆虫网，尼龙细网兜随风飘动，让你能够在安全距离内网住那些带有剧毒螯针的变异巨蜂。",
        en = "The extended form of the collapsible net offering ample reach, allowing survivors to catch venomous mutant wasps while keeping soft flesh safely out of range.",
    },
    ["butterfly_net_makeshift"] = {
        zh = "用一根弯曲树枝和破布蚊帐拼凑出来的简陋捕虫网，虽然卖相寒酸甚至经常兜底漏虫，但在缺少工具时它至少能帮你抓到晚饭的蛋白质。",
        en = "A bent twig wrapped with scavenged mesh netting; crude and perpetually unraveling, yet fully capable of netting crawling grasshoppers for emergency protein.",
    },
    ["butterfly_swords"] = {
        zh = "成对使用的少林传统双短刀，厚重的阔刃配有指骨护手，反手持握时便于近身格斗与格挡，是在逼仄小巷中贴身肉搏的防暴利刃。",
        en = "A matched pair of broad-bladed martial swords with sturdy knuckle guards, lethal in close-quarters skirmishes where swinging longer weapons becomes impossible.",
    },
    ["buttermilk"] = {
        zh = "经过发酵并分离出黄油后的微酸脱脂乳，带有清爽的酸奶香气，不仅能生喝解渴，更是烘焙出松软松饼和苏打面包的灵魂催化剂。",
        en = "Tangy cultured milk left behind after churning butter, refreshingly tart to drink cold and chemically essential for leavening fluffy hearth-baked soda breads.",
    },
    ["butternut"] = {
        zh = "带壳的野生白胡桃，坚硬如铁的外壳保护着里面香甜多油的坚果肉，想要吃到它，你得先找一块结实的石头把它砸个粉碎。",
        en = "Tough-hulled white walnuts guarding rich, buttery kernels inside; harvesting their calorie-dense meats requires heavy rocks and considerable physical patience.",
    },
    ["butternut_husk"] = {
        zh = "敲碎取肉后剩下的坚硬白胡桃果壳，边缘如刀片般锋利，丢进灶膛里不仅能当耐烧的高热引火柴，还能提取出深褐色的天然染料。",
        en = "Cracked woody husks stripped of nutmeats; burning hot and long in campfires while yielding rich dark brown tannins for coloring homespun wool and linen.",
    },
    ["butternut_roasted"] = {
        zh = "在滚烫柴火余烬中慢慢烘烤出油脂的白胡桃仁，外焦里嫩，散发着诱人的坚果焦香，是漫长寒夜守夜人最贴心的能量零食。",
        en = "Shelled walnuts gently roasted over dying coals until glistening with natural oil, delivering a fragrant, crunchy burst of calories for freezing midnight sentry shifts.",
    },
    ["butternut_shelled"] = {
        zh = "小心剥去坚硬外壳后露出的白胡桃仁，白嫩饱满且油脂丰富，既可以直接嚼碎补充体力，也能捣碎拌入野菜汤里增添浓香。",
        en = "Carefully peeled white walnut meats brimming with healthy fats; ready to chew raw on the march or pound into thick, creamy nut milk for gruel.",
    },
    ["button_plastic"] = {
        zh = "最普通不过的四孔塑料小纽扣，虽然毫不起眼，但在呼啸的寒风中，正是它替你牢牢扣紧了外套领口，阻挡致命的寒气钻入胸膛。",
        en = "A tiny four-hole plastic disc; thoroughly unimpressive until biting subzero winds hit, where keeping your jacket buttoned tightly makes the difference between warmth and frostbite.",
    },
    ["buttonshirt"] = {
        zh = "一件带有整齐纽扣与翻领的长袖正装衬衫。曾经是旧时代都市白领出入写字楼的体面行头，如今穿在满身血污与泥巴的废土拾荒者身上，显得格外优雅而讽刺。",
        en = "A crisp button-down long-sleeved shirt once worn by office workers in glass high-rises. Donned by a grime-caked scavenger clutching a shotgun, it adds an absurd touch of professionalism to urban ruin.",
    },
    ["buylocalpamphlet"] = {
        zh = "彩色印刷的战前“支持本地特产”宣传折页，上面印着热情的农场主和新鲜草莓，如今成了给废土篝火充当引火物的廉价废纸。",
        en = "A brightly colored pre-war pamphlet championing locally sourced organic produce, ironically reduced to igniting campfires built from scavenged timber.",
    },
    ["bwirebat"] = {
        zh = "密密麻麻缠绕了生锈带刺铁丝网的重型实木棒球棒。挥动起来带着破风的呼啸声，每一记全垒打不仅能敲碎颅骨，铁丝倒刺还能顺手扯下一大片腐烂的血肉。",
        en = "A heavy wooden baseball bat wrapped tightly with rusty strands of barbed wire. Whistling viciously on the downswing, landing a hit cracks skulls while tearing away rancid zombie flesh with malicious ease.",
    },
    ["c4"] = {
        zh = "带有微弱杏仁气味的军用C-4高爆炸药块，像橡皮泥一样可以随意揉捏塑形，在没有雷管电击引爆前，它甚至安全得能用来点火烧水。",
        en = "A putty-like block of military RDX explosive smelling vaguely of almonds; stable enough to withstand bullet impacts, yet utterly devastating when detonated by a blasting cap.",
    },
    ["c4_payload"] = {
        zh = "微型爆炸无人机内部挂载的预制C4战斗部，这是系统预设的代码核心，能出现在你手上说明某只机械飞虫刚刚在爆炸中失去了它的灵魂。",
        en = "The compact high-explosive core nestled inside an kamikaze drone; handling this raw ordnance means someone dismantled an automated airborne assassin in the nick of time.",
    },
    ["c4armed"] = {
        zh = "计时器已经开始闪烁倒计时的C-4炸药块，蜂鸣声急促刺耳；在按下停止按钮和转身逃跑之间，你只有几秒钟时间决定生死。",
        en = "A block of C-4 with a blinking, high-pitched digital timer; you have precisely three seconds to choose between diffuse panic or sprinting.",
    },
    ["c_fishspear"] = {
        zh = "采用航空级碳纤维管打造的水下打鱼矛，轻若无物且强度惊人，本该在珊瑚礁打鱼，现在则被幸存者用来在河边戳变异泥鳅。",
        en = "An aerospace carbon fiber spearfishing shaft; once intended for tropical reefs, now repurposed by riverbed scavengers to spear slimy irradiated mudpuppies.",
    },
    ["c_hydrogen_gas"] = {
        zh = "被高压压缩在高强度钢瓶中的氢气，清洁环保的未来清洁能源，但在废土上，大家通常只把它当成极度狂暴的易爆气体。",
        en = "High-pressure cylinder of pure hydrogen gas; marketed pre-collapse as clean green energy, universally appreciated in the ruins as an intensely volatile bomb.",
    },
    ["cabbage"] = {
        zh = "一把被切得整整齐齐的卷心菜细丝，虽然脱水后略显蔫软，但如果能拌上一勺蛋黄酱，那就是废土最奢侈的顶级凉拌沙拉。",
        en = "A handful of finely shredded raw cabbage; slightly wilted from travel, yet transforming instantly into five-star coleslaw if tossed with scavenged mayonnaise.",
    },
    ["cabbage_head"] = {
        zh = "一颗沉甸甸、叶片紧实脆嫩的白卷心菜，剥掉最外面沾满泥巴的脏叶子，里面就是足以让一家人吃上三天的爽脆绿叶宝库。",
        en = "A dense head of crisp winter cabbage; peeling away outer muddy leaves reveals tightly bound pale layers that feed a hungry patrol for days.",
    },
    ["cable"] = {
        zh = "带绝缘塑料皮的多股铜芯电线，柔软且导电极佳，在懂电工的幸存者手里是重修电网的神器，在其他人手里只是结实的捆绑绳。",
        en = "Plastic-jacketed copper electrical wire; an essential conduit for rebuilding power grids to electricians, or merely exceptionally durable cordage to everyone else.",
    },
    ["cable_instrument"] = {
        zh = "厚实橡胶屏蔽层的专业乐器音频线，哪怕在满是变异怪兽嘶吼的荒原上，它依然忠实地等待着将电吉他的狂暴失真传给音箱。",
        en = "A heavy-duty shielded quarter-inch audio cable; patiently waiting to transmit righteous electric guitar overdrive across the silent ruins once electricity returns.",
    },
    ["cable_speaker"] = {
        zh = "粗壮的双绞纯铜喇叭连接线，能无损传输强劲的音频电流，用来给防御基地的警报大喇叭供电，能把十里外的怪物都给震醒。",
        en = "Heavy gauge twisted speaker wire carrying high-wattage audio current, capable of driving deafening perimeter sirens loud enough to awaken surrounding townships.",
    },
    ["cable_xlr"] = {
        zh = "带有自锁卡扣的三针专业卡农平衡线，牢固防脱且抗干扰极佳，是末日废土上录音师调试收音麦克风或自制雷达天线的专业线材。",
        en = "A three-pin balanced XLR cable with click-lock metal housings; impervious to ground interference whether patching microphones or jury-rigging makeshift antenna arrays.",
    },
    ["cac2powder"] = {
        zh = "焦炭与生石灰精细研磨混合而成的电石原料粉末，只要丢进电弧炉高温熔炼，就能获得遇水即喷出乙炔气体的危险化学晶体。",
        en = "A powdered premix of coke and calcined lime; smelting it produces calcium carbide, the magical stone that spits flammable acetylene gas upon tasting water.",
    },
    ["cactus_pad"] = {
        zh = "小心刮去坚硬毛刺的仙人掌多肉茎片，口感爽脆多汁且带有微酸，不仅能生嚼解渴，更是沙漠中补充维生素的绿色奇迹。",
        en = "De-spined nopal cactus pads; crisp, gelatinous, and pleasantly tart, delivering lifesaving hydration and vitamin C across scorching desert badlands.",
    },
    ["caff_gum"] = {
        zh = "添加了大剂量纯咖啡因的无糖咀嚼口香糖，薄荷味辛辣冲鼻，嚼上两口就能让熬夜站岗的哨兵眼珠发亮、神经瞬间紧绷。",
        en = "Sugar-free chewing gum laced with extreme doses of caffeine; biting into the bitter peppermint blast shocks sleepy sentries back to twitching readiness.",
    },
    ["caffeine"] = {
        zh = "高浓度医用级咖啡因药片，外表朴实无华的小白片，但在体能耗尽、眼皮打架的逃亡路上，它是让你心脏狂跳、多跑十公里的救命兴奋剂。",
        en = "Maximum-strength pharmaceutical caffeine tablets; tiny chalky white pills that kickstart exhausted adrenal glands to grant five more frantic miles of flight.",
    },
    ["cake2"] = {
        zh = "涂满了厚厚纯黑巧克力甘纳许的浓郁蛋糕切片，糖分高得足以让牙齿发痛，在秩序瓦解的世界里，这一口甜腻简直是对苦难的终极嘲讽。",
        en = "A lavish wedge of chocolate sponge smothered under decadent ganache; its concentrated sugar payload feels like an outright mocking insult to post-apocalyptic misery.",
    },
    ["cake3"] = {
        zh = "抹着堪比城墙倒塌般厚重糖霜的“离谱”蛋糕，每一口咬下去都像在直接吞嚼纯黄油与白糖，吃完一块能让你一周都不想再碰任何甜食。",
        en = "A legendary pastry slice buried beneath two inches of neon buttercream; eating it feels like consuming raw sugar paste, curing sweet cravings permanently.",
    },
    ["calcium_tablet"] = {
        zh = "含有高浓度碳酸钙的小白片，战前是老年人预防骨质疏松的保健品，如今则是幸存者在没有牛奶可喝时抢救牙齿和骨骼的救命矿物。",
        en = "High-dose calcium carbonate pills; once elderly bone supplements, now coveted by irradiated wastelanders trying to keep their surviving teeth from rattling loose.",
    },
    ["calming_stone"] = {
        zh = "表面宛如水波般流动却坚硬冰冷的异常未知造物，只要握在手心里，原本被怪物逼到崩溃边缘的癫狂心灵就会奇迹般地重归死寂。",
        en = "A paradoxical anomaly feeling solid yet rippling like mercury; clutching it washes away screaming psychic panic, leaving behind profound, unnatural tranquility.",
    },
    ["caltrops"] = {
        zh = "无论如何丢掷都必定有一根尖刺直立朝上的四角铁蒺藜，撒在追兵必经的黑暗走廊里，能让任何不穿厚底靴的追击者发出凄厉惨嚎。",
        en = "Four-pointed steel spikes engineered so one barb always points upward; scattering them along dark floorboards produces instant agony for barefoot pursuers.",
    },
    ["caltrops_glass"] = {
        zh = "用大量厚玻璃碎渣和强力胶水粘合而成的恶毒陷阱，透明隐蔽且边缘锋利如手术刀，踩上去不仅割裂脚底，还会把玻璃渣深埋肉中。",
        en = "Serrated glass shards glued into jagged clusters; virtually invisible in dim moonlight, slicing through sneaker soles to leave festering transparent splinters.",
    },
    ["caltrops_teeth"] = {
        zh = "用收集来的变异兽或狂暴丧尸的尖牙粘接成的白骨蒺藜，散发着腐臭，一旦刺穿鞋底，随之而来的严重感染往往比创口本身更致命。",
        en = "Macabre spikes glued together from sharpened mutant molars; piercing an unwary scavenger's boot guarantees a raging septic infection worse than the puncture itself.",
    },
    ["camelbak"] = {
        zh = "内置聚氨酯水囊的贴身水袋背包，柔软的水管直接搭在嘴角旁，让你在全速狂奔逃避尸群围捕时，无需停步就能大口补充水分。",
        en = "A slim tactical hydration pack with hands-free sip tube, allowing dehydrated couriers to guzzle cool water while sprinting full-tilt from howling packs.",
    },
    ["camera"] = {
        zh = "带有可伸缩镜头的民用便携数码相机，虽然像素早已落后于时代，但在文明化为灰烬的今天，它是记录废墟风貌最珍贵的光学仪器。",
        en = "A pocket point-and-shoot digital camera; though technologically obsolete, its optical sensor faithfully captures haunting photographic evidence of the falling world.",
    },
    ["camera_bag"] = {
        zh = "带有厚实防震海绵隔断的尼龙单肩摄影包，虽然原本用来装镜头与机身，但如今里面塞着高爆手雷和止血带显得同样严丝合缝。",
        en = "A padded camera satchel with modular Velcro dividers; engineered for delicate glass lenses, yet cradling fragmentation grenades and trauma bandages with equal elegance.",
    },
    ["camera_control"] = {
        zh = "由多台显像管或小型液晶监视器拼接成的安防监控控制台，虽然大半屏幕已布满雪花点，但仍能让你坐在保险室里偷窥外面的尸群。",
        en = "A security monitor array flicking with static snow; half the feeds are dark, but the surviving screens let you surveil perimeter fences from indoor safety.",
    },
    ["camera_pro"] = {
        zh = "配有大光圈红圈镜头的专业级单反数码相机，镁合金机身沉重而耐造，在没有胶卷限制的电子时代，它能把末日风光拍得像国家地理杂志。",
        en = "A professional SLR camera with heavy glass optics and magnesium body, rendering radioactive sunsets and smoking ruins with terrifying, publication-grade fidelity.",
    },
    ["camisole"] = {
        zh = "用顺滑真丝缝制的轻薄吊带内衣，质地轻盈如云朵，虽然在防御撕咬上没有任何卵用，但至少能让粗糙的重型防弹衣不至于磨破你的皮肤。",
        en = "A delicate silk camisole soft as a cloud; utterly useless against claw swipes, yet preventing coarse Kevlar vests from chafing raw blisters across your ribs.",
    },
    ["camp_chair"] = {
        zh = "一拉即合的便携式折叠帆布露营椅，配有标志性的扶手网兜杯架，在险象环生的避难所外围，坐下来喝罐冰汽水是文明最后的倔强。",
        en = "A folding canvas armchair with a mesh cup holder; sitting back with a scavenged cola brings five minutes of astonishingly civilized leisure amidst ruins.",
    },
    ["camp_meal_large"] = {
        zh = "用多个饭盒盛装的大份营地熟食，热气腾腾且荤素搭配均匀，是阵营食堂向外出砍树或搜刮的伐木工队发放的最丰盛劳动报酬。",
        en = "A massive faction camp tray laden with steaming stew and baked bread, representing the generous culinary reward promised to hardworking timber crews.",
    },
    ["camp_meal_medium"] = {
        zh = "用深铝碗盛装的标准营地配给熟食，分量刚好够一个成年劳动力维持半天的体力，是秩序重建时期最公平且无可挑剔的实物工钱。",
        en = "A standard camp meal bowl packed with hearty gruel; calibrated precisely to sustain one laborer through an afternoon of quarrying or palisade building.",
    },
    ["camp_meal_small"] = {
        zh = "装在小铁盒里的营地工作简餐，虽然分量少得像是在打发难民，但在物资匮乏的拓荒前哨站，一口热糊糊已经足以让人感恩戴德。",
        en = "A modest ration cup of hot porridge issued to camp apprentices; meager in scale, yet gratefully gulped down in freezing frontier watch towers.",
    },
    ["camphine"] = {
        zh = "将松节油与高纯度乙醇按比例混合调配出的精制松脂燃料，燃烧时火焰明亮且几乎没有黑烟，是古老煤油灯和汽化喷灯的上等燃料。",
        en = "A historic blend of rectified spirits and turpentine; burning with brilliant smokeless luminescence, ideal for antique lanterns when refined kerosene vanishes.",
    },
    ["camping_multitool"] = {
        zh = "折叠握柄里集成了尖嘴钳、主刀、锯子和开罐器的经典露营多功能工具，握在手里沉甸甸的，是每个荒野生存狂最贴身的万能救星。",
        en = "A Swiss-style stainless multi-tool concealing pliers, saw blades, and can openers; an absolute pocket-sized survival church for lone wanderers.",
    },
    ["can_aluminum_250ml"] = {
        zh = "一只容量二百五十毫升的小巧空铝制易拉罐。虽然里面的汽水早就被喝得一滴不剩，但剪开后柔软锋利的铝皮是制作报警陷阱或简易箭头的绝佳金属原料。",
        en = "A compact empty 250 mL aluminum soda can. Though drained of sweet carbonated nectar long ago, snips easily transform its thin pliable metal into sharp perimeter tripwire noise alarms.",
    },
    ["can_beans"] = {
        zh = "最经典的末日马口铁罐装豆子，虽然浸泡在浓稠咸汁里的豆粒卖相平平，但它保质期长达数十年，是全人类最后的生存支柱。",
        en = "The holy grail of post-apocalyptic sustenance: baked beans in salted tomato sauce, practically immortal in its tin can and fueling desperate wanderers.",
    },
    ["can_cheese"] = {
        zh = "压入金属铁罐中的再制加工软干酪，口感油滑且咸香浓烈，哪怕抹在发霉发硬的黑面包上，也能瞬间将其变成让人垂涎的高热量快餐。",
        en = "Processed cheese spread sealed inside a tin; rubbery and aggressively salty, yet transforming dry hardtack biscuits into glorious survival delicacies.",
    },
    ["can_chicken"] = {
        zh = "打开后散发着浓郁肉冻香气的碎鸡肉罐头，虽然肉质被高温高压压得像泥一样粉碎，但在满嘴野菜的废土上，每一丝肉沫都金贵无比。",
        en = "A tin of compressed chicken flakes swimming in clear savory gelatin; mushy in texture, but delivering genuine poultry protein in an age of starvation.",
    },
    ["can_chowder"] = {
        zh = "满满一罐浓稠奶白的蛤蜊海鲜浓汤，里面沉淀着细腻的土豆块与贝肉碎，加热后散发的奶油海鲜香气足以让任何人暂时忘却身处的地狱。",
        en = "Rich, creamy clam chowder studded with tender potato dices and clam morsels; heating the tin releases heavenly seafood aromas that banish apocalyptic despair.",
    },
    ["can_clams"] = {
        zh = "浸泡在清亮咸水中的碎蛤蜊肉罐头，带着浓浓的海风咸腥味，虽然直接冷吃略显滑腻，但丢进蔬菜汤里却能瞬间提升整锅汤的鲜度。",
        en = "Chopped ocean clams preserved in salty brine; slightly rubbery eaten cold, but injecting intense marine umami into dull, watery root vegetable stews.",
    },
    ["can_coconut"] = {
        zh = "开罐后表面凝结着一层厚厚白色油脂的浓缩椰奶，甘甜浓郁，无论是用来调制野果咖喱还是直接大口喝下，都能带来爆炸般的热量补充。",
        en = "Thick, fragrant coconut milk crowned with rich coagulated cream; an extraordinary calorie bomb that elevates wild game stews into tropical curries.",
    },
    ["can_corn"] = {
        zh = "浸泡在微甜清水中的金黄甜玉米粒罐头，每一颗都饱满清脆，嚼在嘴里咯吱作响并爆出清甜的汁水，是末日最容易带来的简单快乐。",
        en = "Sweet yellow corn kernels suspended in water; popping crisp, sugary bursts against teeth, delivering uncomplicated childhood joy straight from the tin.",
    },
    ["can_drink"] = {
        zh = "表面沾满尘土的空铝制饮料罐，薄薄的铝皮极易剪切变形，把它剪开压平后，不仅能做成锋利的箭头，还能改造成精巧的酒精炉。",
        en = "An empty aluminum soda can with paper-thin walls; effortlessly sliced and hammered into razor-sharp hunting arrowheads or miniature alcohol penny stoves.",
    },
    ["can_food"] = {
        zh = "被暴力撬开的金枪鱼空罐头，内边缘卷曲着锯齿般的锋利铁皮。在昏暗的废墟里摸黑翻找物资时，它割开你手指动脉的概率，甚至比你在方圆五公里内遇到狂暴变异兽的概率还要高上几分。",
        en = "A jagged steel cylinder that formerly contained mushy tuna. In pitch-black scavenging conditions, its razor-sharp torn lid has inflicted more severe lacerations on desperate human fingers than the claws of several minor mutated wildlife species combined.",
    },
    ["can_food_big"] = {
        zh = "容积足有一升的大号马口铁食品空罐，边缘经过开罐器粗暴切割后锋利如锯，洗干净后就是最经济实惠的野营吊锅或临时量杯。",
        en = "A cavernous one-liter steel food can; its jagged lid removed, it immediately serves as an economical camp kettle or indestructible measuring cup.",
    },
    ["can_herring"] = {
        zh = "浸泡在粘稠白酱汁中的腌鲱鱼罐头，开罐瞬间那股强烈的醋酸与海鱼腥气会让缺乏心理准备的人当场干呕，但北欧老饕却视为珍馐。",
        en = "Pickled Atlantic herring packed in pungent spiced sauce; the vinegary fish aroma terrifies novices, but provides oily, life-prolonging omega fats.",
    },
    ["can_medium"] = {
        zh = "吃完罐头汤后留下的中号马口铁罐，坚硬耐火，只要在底部打几个小孔、套上一截铁丝，就能改造成一个能抵御寒风的简易蜡烛风灯。",
        en = "A durable medium tin can salvaged from vegetable soup; puncture a few holes and loop some wire to forge an effective, wind-resistant candle lantern.",
    },
    ["can_opener"] = {
        zh = "带有旋转齿轮和硬质切刀的折叠手动开罐器，在所有拉环都被扯断的世界里，它是唯一能打开食物宝库与阻止你被罐头逼疯的钥匙。",
        en = "A mechanical handheld can opener with hardened cutting wheels; the indispensable golden key that unlocks sealed steel food vaults when pull-tabs snap.",
    },
    ["can_peach"] = {
        zh = "浸泡在透亮轻糖水里的金黄黄桃切片，果肉肥厚软糯，冰凉甜美的汁水滑过喉咙的那一刻，你会觉得这场灾难也许还有盼头。",
        en = "Thick halves of clingstone yellow peaches floating in sweet syrup; the cool, sugary nectar brings instantaneous tears of gratitude to exhausted wanderers.",
    },
    ["can_pineapple"] = {
        zh = "切成规整圆环状的菠萝罐头，金黄多汁且酸甜可口，浓烈的热带果酸能彻底唤醒你麻木的味蕾，连剩下的菠萝糖水都舍不得倒掉。",
        en = "Perfect golden pineapple rings packed in light juice; their sharp tropical acidity electrifies numb taste buds, and wastefully discarding the syrup is a sin.",
    },
    ["can_salmon"] = {
        zh = "呈现诱人粉红色的三文鱼肉泥罐头，保留了软烂的鱼骨和丰润的鱼油，直接用勺子挖着吃，能给疲惫不堪的身躯提供顶级的高级脂肪酸。",
        en = "Pink salmon paste packed with soft edible bones and rich orange oils; spooning it straight from the can refuels run-down bodies with precious marine nutrients.",
    },
    ["can_sardine"] = {
        zh = "整整齐齐码在薄扁铁盒里的浸油小沙丁鱼，虽然咸得让人狂喝井水，但咬碎软骨时的浓郁鲜味足以搭配任何干涩难咽的压缩饼干。",
        en = "Salty, silvery little sardines packed tightly in vegetable oil; intensely salty and rich, providing magnificent savory grease for dry hardtack biscuits.",
    },
    ["can_sealer"] = {
        zh = "依靠手摇曲柄和压边滚轮运作的重型铸钢罐头封装机，能把装满腌肉和果酱的新铁罐严丝合缝地卷边密封，是长期储粮的工业奇迹。",
        en = "A heavy-duty hand-cranked steel can crimper; hermetically rolling seams onto fresh tins to preserve harvested meats and fruits for future years.",
    },
    ["can_spam"] = {
        zh = "散发着诱人油光和人工防腐剂香气的经典午餐肉罐头，粉嫩胶状的猪肉糜煎至两面金黄时，其香气能让避难所里所有人瞬间失去冷静。",
        en = "The legendary block of pink gelatinous luncheon meat; sliced thick and browned over hot coals, its salty, sizzling aroma causes mutinous campsite riots.",
    },
    ["can_tomato"] = {
        zh = "浸泡在浓稠红亮番茄汁中的整颗去皮番茄罐头，酸甜浓郁，只要倒进炖锅里煮沸，就能掩盖住变质肉类或粗劣野菜的所有古怪异味。",
        en = "Whole peeled plum tomatoes soaking in dense red juice; throwing them into simmering kettles masterfully masks the gamey stink of questionable meat.",
    },
    ["can_tuna"] = {
        zh = "标榜着“已剔除百分之九十五海豚肉”的油浸金枪鱼罐头，虽然这幽默标签让人有点犯嘀咕，但紧实多油的鱼肉依然是不可挑剔的蛋白质。",
        en = "Oil-packed tuna proudly proclaiming ninety-five percent fewer dolphins; unsettling marketing aside, the dense white fish flakes provide clean, vital protein.",
    },
    ["canadian_whiskey"] = {
        zh = "用玉米与黑麦混合谷物发酵蒸馏而成的加拿大威士忌，口感柔顺甘冽，在零下三十度的暴风雪夜灌下一大口，能让整个胸膛如火般燃烧。",
        en = "Blended Canadian grain whiskey offering mellow caramel warmth; swigged during subzero blizzard watch shifts, it ignites a defiant furnace in your chest.",
    },
    ["candle"] = {
        zh = "粗壮厚实的石蜡圆柱蜡烛，虽然微弱的黄色烛火无法照亮整座房间，但它静谧稳定的燃烧至少能驱散黑暗中那些让人发疯的未知恐惧。",
        en = "A thick wax pillar casting a warm, quiet halo; while inadequate for illuminating large warehouses, its gentle flame keeps lurking terrors at bay.",
    },
    ["candle_lit"] = {
        zh = "一支正在静静燃烧、散发着微弱暖黄光晕的粗蜡烛。虽然照亮的范围只有身边两三米，但在伸手不见五指的漆黑地下室里，摇曳的烛光就是对抗恐惧的唯一定心丸。",
        en = "A thick wax candle burning steadily with a warm, amber flame. While casting barely enough luminescence to illuminate a closet, its gentle flicker keeps claustrophobic midnight terrors at bay.",
    },
    ["candle_small"] = {
        zh = "细细长长的蛋糕小蜡烛，虽然几口风吹就会摇摇欲坠，但在狭窄的睡袋里用它点燃一根烟或烤热一根针，依然表现得足够体贴。",
        en = "A slender taproom candle; burns down rapidly in drafts, yet sheds just enough gentle illumination to thread needles or read roadmaps inside sleeping bags.",
    },
    ["candle_small_lit"] = {
        zh = "一支正在微风中跳跃燃烧的纤细小蜡烛。微弱的烛火随时可能被漏风的窗缝吹灭，短短的蜡身也烧不了两个小时，但借着这豆大光芒足够看清地图上的撤离路线。",
        en = "A slender candle flickering precariously against drafty cellar breezes. Burning down in under two hours, its modest yellow light buys just enough time to study tactical road maps.",
    },
    ["candle_wax"] = {
        zh = "凝固成块的乳白色石蜡原料，熔点极低且没有异味，只要架在火上化成蜡水并埋进棉线，你就能源源不断地生产出照亮长夜的蜡烛。",
        en = "A dense block of refined paraffin wax; melting easily over modest flames, ready to receive cotton cordage and multiply into reliable night lamps.",
    },
    ["candlestick"] = {
        zh = "表面涂覆金漆的黄铜复古烛台，重心稳固且带有优雅的蜡滴托盘，插上蜡烛端着在走廊巡逻，总让人感觉自己像中世纪城堡的幽灵。",
        en = "A weighted brass candleholder with wide drip tray; carrying it down pitch-black basements makes you feel like an eccentric haunted mansion master.",
