    ["candy"] = {
        zh = "包裹在褶皱锡箔纸里的花生酱巧克力杯，香浓的花生酱咸甜适中，是你在被尸群追赶得喘不过气时，塞进嘴里最极致的精神救赎。",
        en = "Peanut butter encased in decadent chocolate cups; the perfect marriage of salt and sugar that rescues mental sanity during horrific zombie pursuits.",
    },
    ["candy2"] = {
        zh = "一把五颜六色的糖衣硬壳巧克力豆，放在手心里花花绿绿宛如彩虹，在满目疮痍的灰暗废墟里，嚼碎这把色彩是难得的童真慰藉。",
        en = "Crisp candy-coated chocolate disks rattling like colorful marbles; tossing back a handful delivers intense sugary optimism in a grey, sunless world.",
    },
    ["candy3"] = {
        zh = "各种水果风味的半透明果汁软糖，酸甜筋道且极其耐嚼，能让口腔分泌出大量唾液，是在没有口香糖时消磨无聊行军时光的最佳零食。",
        en = "Vibrant fruit-flavored gummy chews; bouncy, sour, and stubbornly elastic, keeping jaws occupied and spirits high across grueling cross-country treks.",
    },
    ["candy3gator"] = {
        zh = "鳄鱼形状的水果味嚼劲软糖，虽然外表做成了狰狞的爬行动物，但在饥肠辘辘的幸存者嘴里，它只是一团酸甜有嚼劲的明胶糖块。",
        en = "Chewy fruit-flavored gummies molded into ferocious little alligators; in starving mouths, their reptilian ferocity dissolves into delightfully sweet gelatin nostalgia.",
    },
    ["candy4"] = {
        zh = "散发着可乐与混合果汁香气的彩色橡皮糖，晶莹剔透且弹性十足，嚼上一颗能让人暂时忘却满鼻子的泥土与辐射尘埃。",
        en = "Translucent gummy candies bursting with artificial fruit and cola essences; bouncing playfully between molars, temporarily drowning out the harsh taste of wasteland grime.",
    },
    ["candy5"] = {
        zh = "用植物果胶替代明胶制成的素食软糖，口感不如普通软糖筋道，但至少能向变异动物们证明你在饮食道德上是多么一尘不染。",
        en = "Plant-pectin vegan gummies lacking the springy chew of animal gelatin, serving primarily to demonstrate your immaculate dietary ethics to uninterested carnivorous mutants.",
    },
    ["candy_bracelet"] = {
        zh = "用细弹力绳串起彩色糖果圆环制成的手链，戴在手腕上既是俏皮的童年首饰，也是逃亡路上最容易偷偷啃食的应急糖分。",
        en = "A stretchy elastic bracelet threaded with powdery pastel sugar beads; equal parts whimsical fashion accessory and discreet emergency carbohydrate reserve on the run.",
    },
    ["candy_coated_peanuts"] = {
        zh = "裹着一层厚实酥脆红色糖壳的糖炒花生，外甜内香，咬碎时发出的咔嚓脆响能在死寂的末日掩体里唤起对游乐园的久远回忆。",
        en = "Roasted peanuts encased in crunchy candy shells; each loud, sugary bite echoes through dark bunker concrete, summoning ghostly memories of summer carnivals.",
