    ["cell_phone_flashlight"] = {
        zh = "开启了机身顶部高亮LED照明灯的老式按键手机，虽然光束散乱且照不远，但在漆黑一片的废弃地下室里摸索时，它就是你的掌中明灯。",
        en = "A legacy cellphone utilizing its built-in white LED emergency torch; casting a diffuse puddle of white light across cobwebbed cellar corridors.",
    },
    ["centrifuge"] = {
        zh = "配有高速无刷电机与试管配重槽的台式电动离心机，通电后能以每分钟上万转飞速旋转，将浑浊的血液和化学提取物分层得清清楚楚。",
        en = "A laboratory centrifuge spinning test tubes at thousands of revolutions per minute, separating blood components and chemical precipitates with automated precision.",
