    ["ceramic_armor"] = {
        zh = "由碳化硼陶瓷烧结压制而成的防弹装甲插板，能在击碎自身的瞬间彻底吸收大口径穿甲弹的致命动能，救下士兵脆弱的胸膛。",
        en = "A curved boron-carbide ceramic torso plate; shattering upon impact to absorb high-velocity rifle kinetic energy and spare your ribs from liquefaction.",
    },
    ["ceramic_bowl"] = {
        zh = "表面覆着光滑白釉的普通陶瓷汤碗，端在手里沉甸甸的且保温良好，只要不手滑把它摔在水泥地上，它能陪你喝上一辈子的热汤。",
        en = "A standard glazed porcelain soup bowl; holding heat beautifully during winter meals, provided you don't fumble it onto unforgiving bunker concrete.",
    },
    ["ceramic_cup"] = {
        zh = "带有小巧把手的典雅陶瓷茶杯，杯壁薄而透光，在危机四伏的废土晨曦中，用它小口啜饮一杯刚煮好的热茶，能找回做人的尊严。",
        en = "A delicate ceramic teacup with a gilded rim; sipping hot pine needle tea from its lip reclaims a sliver of human dignity amidst the wilderness.",
    },
    ["ceramic_mug"] = {
        zh = "一只印着世界最佳老爸标语的普通彩色陶瓷咖啡杯。用它在篝火边啜饮热气腾腾的松针茶或速溶咖啡，指尖传来的温热能让人暂时忘记身处文明灭绝的废土地狱。",
        en = "A colorful ceramic coffee mug stamped with an ironic faded pre-war slogan. Sipping hot dandelion tea from its sturdy rim brings quiet domestic dignity back to freezing wilderness mornings.",
    },
    ["ceramic_plate"] = {
        zh = "最普通的平底陶瓷餐盘，虽然边角可能已经磕出了小缺口，但把烤好的肉排整齐码在盘子里吃，依然比直接用手抓着吃文明得多。",
        en = "An unremarkable glazed ceramic dinner plate; though chipped around the rim, dining from it feels vastly more civil than tearing meat with bare hands.",
    },
    ["ceramic_shard"] = {
        zh = "打碎瓷碗后留下的三角形陶瓷碎片，边缘比手术刀还要锋利，在没有任何铁器的情况下，绑在木棍上就是一柄极其致命的割喉小刀。",
        en = "A razor-sharp triangular shard of broken glazed porcelain; strapped to a split stick, it fashions an extraordinarily lethal improvised field scalpel.",
