    ["cereal"] = {
        zh = "浸透了大量人工色素和白糖的彩虹甜麦圈，只要倒上一点冷牛奶，就能在两分钟内给你提供一整天所需的糖分与童年般的快乐。",
        en = "Neon-colored puffed grain cereal frosted with granulated sugar; drowning a bowl in milk provides an immediate, dizzying sugar rush of pure nostalgia.",
    },
    ["cereal2"] = {
        zh = "保留了麸皮与胚芽的全谷物粗粮麦片，口感粗糙坚硬甚至需要用力咀嚼，虽然不如甜麦片诱人，但能提供极为持久平稳的饱腹能量。",
        en = "Fiber-dense whole-wheat flake cereal; coarse on the palate and demanding vigorous chewing, but supplying rock-solid sustained energy for scavengers.",
    },
    ["cereal3"] = {
        zh = "金黄薄脆的原味烤玉米片，开袋即食，嚼在嘴里沙沙作响并带有淡淡的玉米焦香，是每个避难所货架上最常见也最不容易变质的早餐。",
        en = "Crisp, toasted golden cornflakes; plain and unpretentious, but remaining edible inside airtight foil bags long after flashier foods have spoiled.",
    },
    ["cereal_fp1"] = {
        zh = "食品乐园自营的廉价无名甜麦片，包装极其简陋，甚至连吉祥物都懒得画，但里面的每一颗糖粒都能在饥荒中拯救一条虚弱的生命。",
        en = "Generic store-brand sugary cereal in an unprinted bag; devoid of marketing mascots, yet delivering lifesaving refined carbohydrates when food stocks fail.",
    },
    ["cereal_fp2"] = {
        zh = "印着卡通木匠挥舞锯子的“木匠嘎嘣脆”麦片，口感硬得堪比刨花碎屑，咬碎时需要牙齿付出巨大的代价，名副其实的木工硬核早餐。",
        en = "Foodplace Carpenter Crunch cereal; boasting kernels so aggressively dense they resemble seasoned cedar chips, challenging the structural integrity of teeth.",
    },
    ["cereal_fp4"] = {
        zh = "裹满厚厚人造巧克力霜的“方糖嚼嚼”麦片，甜到发腻，宣传语号称能给孩子们带来充沛活力，实际上只是纯粹的液态糖分催化剂。",
        en = "Sugar Chomps chocolate-frosted cereal; an unapologetic delivery vehicle for refined fructose, guaranteed to make youngsters bounce off bunker ceilings.",
    },
    ["cestus"] = {
        zh = "在厚牛皮绑带上嵌满铁板与尖刺的古罗马铁拳套，把拳头握紧时能将肉拳化为铁锤，每一拳挥出都能砸裂丧尸腐朽的面颊骨。",
        en = "A gladiatorial leather hand wrap reinforced with iron studs and plates; transforming soft human fists into bone-shattering close-quarters sledgehammers.",
    },
    ["ch_armguard_metal"] = {
        zh = "用废旧汽车钣金手工捶打成型并经过渗碳淬火的硬化钢板护臂。表面带有粗犷的锤痕，但硬度扎实无比，抬手格挡时能轻松弹开迎面砸来的带钉木棒。",
        en = "Curved arm guards hammered out of scrap automotive sheet metal and heat-treated. The rough hammer-peened surface shrugs off spiked clubs and blunt pipes with resonant metallic clangs.",
    },
    ["ch_armguard_metal_sheets_bracer"] = {
        zh = "专门加固前臂内外侧的硬化钣金前臂护腕。结实的皮带将其紧紧锁在小臂上，即便与狂暴丧尸在泥浆里近身扭打，尖锐的指甲也休想划破坚硬的硬化钢甲层。",
        en = "Hardened sheet-metal bracers strapped tightly across forearm tendons. Buckled over heavy leather, they turn frantic close-quarters grappling into futile scratching against cold, hardened steel.",
    },
    ["ch_armguard_metal_sheets_elbows"] = {
        zh = "经淬火硬化处理的钣金弯曲手肘护罩。凸起的圆锥形钢罩完美包裹住脆弱的手肘骨节，在近战格斗中顺势送出一记肘击，足以把敌人的面门骨骼砸得彻底凹陷。",
        en = "Pointed elbow cops forged from hardened sheet steel. Cushioning vulnerable joint bones, driving a vicious backward elbow into an attacker's nose breaks cartilage and ends grappling struggles.",
    },
    ["ch_armguard_metal_sheets_shoulders"] = {
        zh = "由数层弧形硬化钢板手工铆接的钣金护肩。层层叠叠的钢板能顺畅滑移，既不影响挥舞双手重武器的伸展动作，又能稳稳挡住自上方坠落的碎石砖块。",
        en = "Layered pauldrons articulated from hardened steel sheet plates. Gliding smoothly with every swing of a two-handed sledgehammer, they shield clavicles from falling masonry and overhead ambushes.",
    },
    ["ch_arming_sword"] = {
        zh = "采用硬化碳钢精心锻打打磨的经典单手骑士剑。剑刃经过严苛淬火调质，坚韧锋利且重心绝佳，单手挥砍刺击时如同手臂的延伸，是近战大师的致命杰作。",
        en = "A classic medieval arming sword forged from expertly heat-treated hardened steel. Razor-sharp and perfectly balanced for single-handed fencing, it slices through decayed flesh like silk.",
    },
    ["ch_aztec_spear"] = {
        zh = "以现代硬化高碳钢重新锻造刀片的阿兹特克阔刃矛，矛头两侧密布如鲨鱼齿般的锋利钢刃，刺入时能瞬间撕开深可见骨的恐怖伤口。",
        en = "A modernized Mesoamerican tepoztopili lined with hardened steel teeth; thrusting this broad spearhead inflicts devastating, jagged lacerations.",
    },
    ["ch_aztec_sword"] = {
        zh = "将传统黑曜石锯剑以高碳钢刃片重塑的阿兹特克斩击剑，挥击时带着沉重的撕裂力，能把厚皮变异兽的肢体像锯木头一样生生锯断。",
        en = "A brutal steel-edged macuahuitl delivering the momentum of an executioner's axe with the sawing devastation of high-carbon steel serrations.",
    },
    ["ch_battleaxe"] = {
        zh = "配有一体硬化钢宽阔月牙刃的重型双持战斧。沉重的斧头蕴含着毁灭性的劈砍动能，一斧挥出能连甲带骨将变异装甲丧尸当场劈成两半，血腥霸道至极。",
        en = "A devastating war axe sporting a broad, hardened steel crescent blade. Delivering terrifying cleaving momentum with two hands, it splits bone and scavenged riot gear in a single bloody arc.",
    },
    ["ch_brigandine_hands"] = {
        zh = "在坚韧皮革手套手背处铆接硬化钢片的布面甲防咬手套。握拳挥出时如同指虎般坚硬沉重，近距离徒手夺刀或阻挡丧尸的疯狂啃咬都显得游刃有余。",
        en = "Sturdy work gloves reinforced with riveted plates of hardened carbon steel across knuckles and fingers. Punching delivers knuckles of iron while safely blocking snapping jaws during grapples.",
    },
    ["ch_brigandine_hands_xs"] = {
        zh = "针对纤细手型紧密剪裁的小号硬化钢片布面手套。钢片排列紧凑小巧，不仅手指关节弯曲自如毫不僵硬，在握持精密手枪时更是兼顾了射击手感与防咬保护。",
        en = "A petite pair of steel-plated brigandine gloves proportioned for slender hands. Articulated joints maintain fine trigger finger dexterity, keeping sidearm manipulation smooth and protected.",
    },
    ["ch_broadsword"] = {
        zh = "配有宽大双刃与笼手护柄的硬化碳钢双手阔剑。硬化钢刃耐磨不易卷刃，宽阔的剑面在招架敌人凶狠劈砍时坚如磐石，是废土阵地防守反击的钢铁中流砥柱。",
        en = "A robust early-modern broadsword forged from tempered carbon steel. Its broad, durable double edge resists chipping, allowing heavy parries that turn incoming raider axes aside with ease.",
    },
    ["ch_cavalry_sabre"] = {
        zh = "经过硬化工艺处理的高韧性弧形骑兵军刀。刀身弧度完美兼顾了下劈与拖割的切削效率，即便连续斩断十几具丧尸的颈椎骨，锋利的刀刃依然寒芒逼人、毫无崩口。",
        en = "A hardened steel cavalry sabre balancing flexibility with terrifying cutting aggression. Retaining its razor edge through dozens of decapitations, it gleams with cold, unyielding lethality.",
    },
    ["ch_chain_link"] = {
        zh = "经过热处理硬化的优质碳钢锁环，防剪切性能极佳，用它编织而成的锁子甲能够抵御最锋利的狼牙和带有倒钩的丧尸利爪。",
        en = "Individual hardened carbon-steel rings; heat-treated to resist shearing forces, forming the building blocks of virtually bite-proof mail armors.",
    },
    ["ch_chainmail_arms"] = {
        zh = "采用经过渗碳硬化的粗钢丝密密织造的手臂锁子甲护袖。带扣紧密贴合上臂与小臂，彻底免除了一切被抓伤咬伤的风险，让双手近战挥刀时毫无后顾之忧。",
        en = "Custom sleeves crafted from interlocking rings of hardened carbon steel. Fastened securely across wrists and biceps, they grant complete immunity to vicious slashing claws and infectious bites.",
    },
    ["ch_chainmail_aventail"] = {
        zh = "安装在头盔下沿、自然垂坠护住整个脖颈的硬化钢锁子甲护喉帘。致密的铁环能彻底化解割喉利刃与变异犬齿撕咬，为人体最脆弱的喉头气管筑起移动铁壁。",
        en = "A wide chainmail aventail designed to lace beneath helmets, draping across the throat. Densely woven hardened rings prevent lethal throat slashes from feral horrors lurking in darkness.",
    },
    ["ch_chainmail_face"] = {
        zh = "仅遮掩下颚与口鼻半面部的硬化钢锁环半护面。在保证畅通呼吸与良好视野的同时，正面挡住扑击而来的丧尸利齿，避免在近身缠斗中被咬烂半张面孔。",
        en = "A partial chainmail veil shielding jaw and lower face while leaving sightlines clear. Deflecting direct lunges aimed at your throat, it preserves breathing freedom during exhausting melees.",
    },
    ["ch_chainmail_feet"] = {
        zh = "通体由硬化锁环编织而成并包裹在靴外的防刺铁链袜。直接踩在布满铁蒺藜与破碎生锈玻璃的险恶地面上，细密的钢环能为你隔绝一切足底被刺穿感染的隐患。",
        en = "Chainmail foot coverings laced over boots to protect feet and ankles from puncture. Stomping across fields of rusty nails and caltrops, the dense rings prevent debilitating foot infections.",
    },
    ["ch_chainmail_half_legs"] = {
        zh = "仅防护大腿与小腿正面的轻量化硬化钢锁子甲半腿裤。大大减轻了全身负重与行动阻力，跑动起来灵活轻便，同时为双腿正面提供了抵御变异野兽扑咬的绝对硬度。",
        en = "Lightweight half-leggings shielding the front of shins and thighs with hardened rings. Halving encumbrance, they permit rapid running while turning low canine lunges into harmless rattling.",
    },
    ["ch_chainmail_hands"] = {
        zh = "用极细硬化钢环连体手工编织的全包覆锁子甲手套。十指弯曲灵动自如，无论是徒手抓向锋利的刀刃还是格挡丧尸的疯狂啃咬，坚硬的钢环都会让袭击者无从下嘴。",
        en = "Supple gloves intricately woven from microscopic hardened steel rings. Allowing full finger articulation, grabbing naked blade edges or parrying snapping jaws leaves palms entirely unhurt.",
    },
    ["ch_chainmail_hauberk"] = {
        zh = "覆盖躯干与双臂的长款硬化钢全套锁子甲长袍。数万枚微型硬化钢环环环相扣，穿在棉甲外层防刺防割，行走在尸群中宛如披着一层波光粼粼的金属鳞片水波。",
        en = "A full-length chainmail hauberk draping from shoulders to knees. Composed of tens of thousands of hardened rings worn over padding, it flows like metallic water while repelling razor claws.",
    },
    ["ch_chainmail_hauberk_xs"] = {
        zh = "针对瘦小身材紧密剪裁的小号硬化锁子甲长袍。重量分布均衡，下摆适度缩短避免奔跑绊脚，让敏捷的游侠在林间伏击时既拥有全面防刺保护又能健步如飞。",
        en = "A scaled-down chainmail hauberk tailored for compact frames. Balancing weight ergonomically while trimming excess hem length, it keeps woodland scouts protected without slowing their stride.",
    },
    ["ch_chainmail_hood"] = {
        zh = "完整包裹头顶、后脑与双耳的硬化钢锁子甲头巾。单独佩戴或塞在安全帽底下都极其贴合，能有效防止后方偷袭的扑击撕扯直接撕脱你的整片头皮。",
        en = "A form-fitting chainmail coif enveloping cranium, ears, and neck in hardened steel mesh. Worn under a hardhat, it stops creeping attic stalkers from tearing off your scalp from behind.",
    },
    ["ch_chainmail_jumpsuit"] = {
        zh = "从脖颈一路覆盖到脚踝的全身一体式硬化钢锁子甲连身衣。宛如一具量身定制的钢铁第二皮肤，全身上下除了面孔几乎毫无破绽，给予穿戴者无与伦比的肉搏安全感。",
        en = "A complete head-to-toe jumpsuit fashioned from hardened chainmail links. Functioning like a second skin of flexible steel, it eliminates nearly every chink against opportunistic biter jaws.",
    },
    ["ch_chainmail_jumpsuit_xs"] = {
        zh = "小号修身的一体式硬化钢锁环全身连身衣。关节处收缩贴合，挥舞长兵器或快速翻滚时轻便无阻，让体型较小的格斗高手在尸潮乱军中如入无人之境。",
        en = "A sleek, form-fitting chainmail jumpsuit crafted for slender combatants. Articulated joints eliminate binding during acrobatic dodges, letting nimble blade masters dance through hordes unscathed.",
    },
    ["ch_chainmail_legs"] = {
        zh = "带有加固绑带的硬化钢全包覆锁子甲裤。牢固地固定在大腿与腰部，在齐腰深的变异荆棘灌木丛中开辟道路时，细密的钢环能为你隔绝一切毒刺划伤与撕裂啃咬。",
        en = "Full chainmail leggings strapped firmly around thighs and waist. Striding through waist-high thorn thickets or swarms of crawling infected, the armored links turn tears into harmless noise.",
    },
    ["ch_chainmail_sjumpsuit"] = {
        zh = "采用无袖剪裁的硬化钢锁环连身衣。躯干与双腿得到严密防御的同时彻底解放了双臂与肩膀的活动范围，无论是狂暴挥舞大锤还是拉满重弓都丝毫不受拘束。",
        en = "A sleeveless chainmail jumpsuit covering torso and legs in hardened rings. Unshackling shoulders and arms for fluid movement, it maximizes stamina when swinging heavy sledges or greatbows.",
    },
    ["ch_chainmail_sjumpsuit_xs"] = {
        zh = "小号无袖硬化钢锁环连身衣。专为追求极致敏捷的身法流幸存者打造，下半身与核心脏器得到坚固防护，双臂挥洒自如，堪称废土近战斥候的终极刺客装束。",
        en = "A petite sleeveless chainmail suit providing solid torso and leg armor. Leaving arms free for rapid-fire archery or dual-blade fencing, it serves as the ultimate agile scout garment.",
    },
    ["ch_chainmail_suit"] = {
        zh = "配有躯干连体裤的全套硬化钢经典锁子甲。配合厚实的防内伤武装衣穿戴，哪怕挨上一记带刺狼牙棒的当头闷击，坚韧的锁环也能化解大部分杀伤动能。",
        en = "A traditional full suit of hardened steel chainmail armor. Paired with a quilted gambeson underneath, it absorbs heavy spiked mace impacts, preventing broken bones beneath the iron weave.",
    },
    ["ch_chainmail_suit_xs"] = {
        zh = "按较小骨架优化重量与链环密度的小号硬化锁子甲套装。穿戴舒适且受力均匀，在长时间巡逻警戒中不会把肩膀压出深痕，防砍防咬性能却丝毫不打折扣。",
        en = "A scaled-down suit of hardened chainmail proportioned to eliminate dragging weight. Distributing pressure comfortably across narrow shoulders, it provides tireless, all-day bite protection.",
    },
    ["ch_chainmail_vest"] = {
        zh = "专为保护胸腹要害打造的硬化钢无袖锁子甲背心。轻便简洁，套在普通保暖毛衣外面毫不起眼，却能悄无声息地抵挡来自暗处的致命刺刀偷袭。",
        en = "A sleeveless hardened steel chainmail vest focused on protecting the vital core. Worn discreetly over sweaters, it turns would-be fatal shiv ambushes into futile, ringing metallic thuds.",
    },
    ["ch_chestguard_metal_sheets"] = {
        zh = "用废品站钣金冲压并经过热处理硬化的粗旷铁皮胸甲。表面粗粝不羁，但厚实的钢板在正对冲撞时坚如磐石，能把狂暴丧尸的利爪硬生生弹得反折骨折。",
        en = "A rugged chestplate beaten out of salvaged vehicle body panels and heat-treated. The crude plating laughs off claw strikes, fracturing fingers when ghouls swipe frantically at your chest.",
    },
    ["ch_chestguard_metal_sheets_heavy"] = {
        zh = "用双层硬化碳钢板手工锻打成型的重型胸甲，沉重压肩，虽然穿上后敏捷大降，但能让近距离袭来的霰弹钢珠当场弹飞开裂。",
        en = "A double-thick curved breastplate hammered from hardened sheet steel; ponderous and hot, yet turning aside shotgun pellets with ringing defiance.",
    },
    ["ch_chestguard_metal_sheets_light"] = {
        zh = "仅遮盖上胸要害的轻型硬化钣金护胸板。大幅削减自重以换取奔跑耐力，在确保心肺不受致命穿透的同时，让你拥有充沛的体能甩开身后追击的尸潮。",
        en = "A minimalist hardened sheet metal chest guard covering only the upper pectorals and heart. Sacrificing lower belly coverage for running agility, you easily outdistance plodding pursuers.",
    },
    ["ch_cutlass"] = {
        zh = "采用硬化碳钢锻造的经典海盗弯砍刀。带有结实的碗状护手与宽厚厚背刀身，在狭窄的船舱或走廊里挥舞起来势大力沉，一刀就能斩下扑击丧尸的头颅。",
        en = "A broad naval cutlass forged from hardened carbon steel and fitted with a basket hilt. Ideal for hacking through tight apartment corridors, its hefty blade cleaves through necks in single blows.",
    },
    ["ch_demi_gaunt"] = {
        zh = "在掌背与手指关节密布硬化钢环的半指皮手套。既保留了手指握持小工具和扣动扳机的灵活触觉，又在手背构筑起坚固的铁甲，近战挥拳杀伤力极其凶猛。",
        en = "Supple leather demi-gauntlets reinforced with hardened chainmail across the knuckles. Maintaining fine fingertip touch for picking locks, closing your fist turns punches into iron bludgeons.",
    },
    ["ch_elbow_guards"] = {
        zh = "由两毫米硬化碳钢冲压制成的一对专业护肘。轻巧坚硬且边缘倒角平滑，贴合关节弯曲，在碎石废墟中摔倒时能稳稳护住脆弱的手肘关节不被磕碎。",
        en = "A pair of thin elbow guards forged from resilient hardened steel. Protecting delicate elbow joints when diving onto asphalt, they let you drop prone into sniper cover without winces.",
    },
    ["ch_elbow_guards_xs"] = {
        zh = "针对纤细手肘量身打造的紧凑型硬化钢护肘。小巧的弧形钢片紧密贴合骨骼关节，在碎砖废墟中匍匐前进时，不仅毫无阻碍，更能彻底免除手肘撞击骨裂的痛苦。",
        en = "Slim hardened steel elbow guards contoured for petite builds. Snapping snugly over jackets, they protect vulnerable joint bones from agonizing impact fractures during frantic crawling runs.",
    },
    ["ch_esapi_plate"] = {
        zh = "采用硬化工具钢整体锻压而成的加重防弹插板。沉重得像是在战术背心里塞了一块小铁砧，虽然穿久了腰酸背痛，但能正面硬接全威力步枪子弹而绝不发生致命击穿。",
        en = "A heavy-duty ballistic plate forged from case-hardened tool steel. Though turning your tactical carrier into a walking anvil, it laughs off high-velocity battle rifle fire with negligible backface deformation.",
    },
    ["ch_esbi_plate"] = {
        zh = "六边形硬化碳钢战术侧防弹板。专门塞在防弹背心两侧肋骨部位，虽然略微限制弯腰捡垃圾的灵活性，但能稳稳防住躲在拐角处放冷枪的丧尸暴徒偷袭软肋。",
        en = "A hexagonal hardened steel side plate protecting exposed lateral ribs. While slightly hindering flexible dumpster diving, it stops close-range ambush fire from shattering your fragile ribcage.",
    },
    ["ch_estoc"] = {
        zh = "一把通体采用硬化钢淬火、没有开刃的四棱破甲细长刺剑。剑身刚硬如钻头，专为刺穿重型铠甲与鳞甲缝隙而生，一剑全力刺出能直接贯穿变异巨怪的喉部气管。",
        en = "An unedged edgeless estoc forged from hardened carbon steel. Acting like a giant rigid needle designed to puncture plate harness joints, a precise thrust punches straight through chitinous throat carapaces.",
    },
    ["ch_falx"] = {
        zh = "源自达契亚传统的向前弯曲前勾型硬化钢双持大砍刀。反曲的锋利刀尖具有骇人的钩割拉扯力，挥砍在丧尸盾牌或肢体上能借力直接将对手的胳膊当场生生钩断。",
        en = "A forward-curving Dacian war sword forged from hardened steel. Its vicious hooked geometry pulls behind shields and limbs, tearing through flesh and bone with horrifying cleaving leverage.",
    },
    ["ch_greaves_brigandine"] = {
        zh = "在帆布夹层中交错铆接硬化钢板条的布面护胫。兼具了轻便跟脚与吸收重击的特性，在满地瓦砾与生锈铁丝网的战场上，能确保你的胫骨不被飞溅的流弹碎石砸断。",
        en = "Splint greaves sandwiching alternating hardened steel bars beneath heavy canvas duck. Balancing footwork mobility with impact deflection, they protect delicate shinbones from flying concrete shrapnel.",
    },
    ["ch_heavyhelm_close"] = {
        zh = "十五世纪末期全包覆闭锁式超重型硬化钢板全盔。坚固的面甲严丝合缝地锁死，除了呼吸略显闷热外，整颗头颅宛如置身于小型银行保险库中，彻底无惧任何重击。",
        en = "A late-fifteenth-century close helmet hammered from heavy hardened plate. Locking your cranium inside a miniature vault, its sealed visor shrugs off lead pipes and broadswords with resounding thuds.",
    },
    ["ch_heavyhelm_close_raised"] = {
        zh = "面甲掀起锁定状态下的超重型硬化闭锁头盔。在视野开阔与顺畅大口喘气的同时，沉重的头顶与颈部护甲依然默默守护着要害，适合在激烈战斗间隙擦汗小憩。",
        en = "The heavy hardened close helmet with its pivoting visor propped open. Allowing refreshing gasps of air and unobstructed sightlines between skirmishes, the heavy neck gorget keeps throat arteries secure.",
    },
    ["ch_helm_close"] = {
        zh = "标准厚度的硬化碳钢中世纪闭面骑兵全盔。面罩闭合后只留下一条窄窄的观察缝，虽然严重剥夺了眼角余光视野，但在迎面硬抗霰弹枪近距离轰击时能保住整张面孔。",
        en = "A standard-weight hardened steel close helmet enveloping the entire head. While the narrow eye slit eliminates peripheral awareness, surviving point-blank buckshot blasts makes tunnel vision a worthwhile trade.",
    },
    ["ch_helm_close_raised"] = {
        zh = "掀起面甲透气的中型硬化碳钢闭合盔。方便幸存者在搜刮废墟时辨认队友面孔与辨识地标，遭遇突发敌情时只需抬手一拍面罩，瞬间就能恢复全封闭战斗姿态。",
        en = "The medium hardened steel close helmet with its faceplate flipped upward. Perfect for identifying salvage markings and conversing with allies, slamming the visor down takes half a second when ambushed.",
    },
    ["ch_helmet_metal_sheets"] = {
        zh = "用废品站厚钣金手工弯折成型并经过渗碳淬火的粗制头盔。造型粗糙得像一只倒扣的铁皮电饭煲，但在遭遇丧尸破门偷袭时，它能实打实挡下足以致命的下劈重棒。",
        en = "A crude combat helmet beaten into shape from scrap automotive paneling and hardened. Resembling an inverted cooking pot, it reliably prevents lead pipes from caving in your forehead.",
    },
    ["ch_helmet_metal_sheets_full"] = {
        zh = "由数块粗铁板铆接并经过热处理的大号圆桶形巨盔。戴在头上滑稽得像戴了一只水桶，但厚实的铁皮外壳能把狂暴丧尸的钝击冲击波完全隔绝在外，堪称安全感拉满。",
        en = "A towering great helm riveted together from heavy scrap sheet metal. Looking hilariously like a medieval galvanized bucket, its unyielding walls turn frantic zombie clawing into pointless metallic scratches.",
    },
    ["ch_helmet_nasal"] = {
        zh = "带有垂直硬化鼻梁护条的早期中世纪诺曼式圆顶钢盔。鼻梁处的坚固钢条能有效挡开迎面劈来的直刺武器，简单的圆顶造型利落开阔，丝毫不阻碍你的战术视野。",
        en = "An early medieval nasal helmet featuring a sturdy downward nose bar. Deflecting diagonal slashes away from delicate facial bones, its open-face design preserves wide panoramic peripheral vision.",
    },
    ["ch_helmet_turban"] = {
        zh = "带有圆柱形顶部与面部锁网护垂的中东风格硬化钢缠头盔。高耸的盔顶利于滑开沉重的下劈战斧，垂挂在四周的细密钢环更能为脖颈提供全方位的防割咬保护。",
        en = "A conical Middle Eastern turban helmet forged from hardened steel with chain aventail. The sloping dome glances heavy axe blows aside, while hanging steel rings protect neck sinews from slashing.",
    },
    ["ch_jian"] = {
        zh = "采用硬化高碳钢精工锻造的中国传统双刃直剑。剑身刚柔并济，八面研磨的脊线笔直冷冽，挽出剑花刺入丧尸咽喉要害时如游龙出水，兼具绝伦的杀伤力与古典美感。",
        en = "A traditional Chinese double-edged straight sword forged from hardened steel. Flawlessly balanced and razor-sharp on both cutting edges, thrusting through zombie throats feels fluid and deadly.",
    },
    ["ch_katana"] = {
        zh = "由硬化钢整体锻造并经过严格调质处理的日式武士太刀。虽然在面对重型防弹钢板时劈砍容易崩口，但对付无护甲的变异丧尸时，极速拔刀斩能干脆利落地将其一刀两断。",
        en = "A refined Japanese katana forged from uniformly hardened carbon steel. While brittle against heavy vehicle plating, quick-draw slashing through unarmored ghouls bisects decaying torsos like wet straw.",
    },
    ["ch_khopesh"] = {
        zh = "仿照古埃及镰刀剑造型锻打的硬化钢弯刃重剑。前段外凸的圆弧形刀刃赋予了它如同战斧般的狂暴劈砍惯性，反向钩角更能轻易拨开丧尸手里的武器撕开防线。",
        en = "An ancient Egyptian sickle-sword forged from hardened steel. Combining the crushing chopping momentum of an axe with a hooking tip, it wrenches makeshift barricades aside while eviscerating foes.",
    },
    ["ch_kilij"] = {
        zh = "刀头带有明显加宽阔刃段的土耳其风格硬化钢弯刀。前端突出的配重让劈砍威力和穿透力呈几何级暴增，一刀挥出足以连皮带骨斩断变异狂犬的整截脊梁骨。",
        en = "A Turkish kilij saber sporting a flared, flared yelman tip for maximum impact momentum. The added forward mass shears through mutated canine spines with terrifying, bone-cleaving velocity.",
    },
    ["ch_knee_guards"] = {
        zh = "经淬火工艺精炼的一对硬化碳钢护膝。包裹严密的钢壳能在猛烈跪地或摔倒滑行时吸收所有冲击，更能直接用来发动致命膝撞，将冲上来的变异老鼠当场顶得骨肉成泥。",
        en = "Hardened carbon steel knee cops curved to cup patellar joints comfortably. Allowing aggressive knee slides into combat trenches, landing an offensive knee strike shatters mutant ribcages.",
    },
    ["ch_knee_guards_xs"] = {
        zh = "小号剪裁的人体工学硬化钢护膝。专为小个子战士优化曲率，绑带紧致不下滑，不仅在跨越矮墙瓦砾时毫无拖拽感，还能完美护住脆弱的膝盖韧带免受钝伤。",
        en = "A compact pair of hardened steel knee guards contoured for slender legs. Securing snugly without slipping during vaulting climbs, they safeguard delicate patellas from jagged masonry impacts.",
    },
    ["ch_knife_rambo"] = {
        zh = "带有中空手柄与锯齿背刃的硬化重型生存兰博刀。刀身厚重沉稳，既能当砍柴柴刀劈开坚硬灌木，近战突刺时更能凭借硬化钢刃一刀刺穿变异野兽的颅骨。",
        en = "A massive survival combat knife featuring a hollow storage handle and spine saw. Chopping firewood by day, its hardened clip point punches through mutant beast skulls during nighttime ambushes.",
    },
    ["ch_knife_trench"] = {
        zh = "配有一体式硬化钢指虎护手的一战风格重型壕沟刺刀。粗短刚直的刀身专为狭窄战壕里的贴身死斗而生，一拳砸倒敌人的同时顺势补上一刀，狠辣致命到了极致。",
        en = "A brutal combat trench knife armed with an integrated steel knuckle-duster hilt. Engineered for cramped subterranean brawling, bludgeoning a walker with the grip smoothly segues into a fatal thrust.",
    },
    ["ch_kriegsmesser"] = {
        zh = "带有长手柄与单面开刃大弯刀身的德国硬化大剑。挥动时依靠两只手的杠杆力能产生骇人的斩击速度，在面对成群涌来的丧尸步兵时宛如一台行走的血肉收割机。",
        en = "A German two-handed war knife sporting a long curved cutting edge. Harnessing two-handed leverage to unleash blisteringly fast chopping arcs, it reaps through approaching ghoul formations like grain.",
    },
    ["ch_kukri"] = {
        zh = "刀头向前下坠弯曲的廓尔喀硬化钢军刀。独特的反曲力学重心让劈砍动作威力无穷，无论是开辟荆棘林间小路还是当面斩杀伏击的变异野狗，都能做到手起刀落一击必杀。",
        en = "A forward-curved Gurkha kukri hand-forged from hardened carbon steel. Angling weight forward for devastating chopping power, it clears tangled jungle brush and feral hounds with equal fluid efficiency.",
    },
    ["ch_legguard_metal_sheets"] = {
        zh = "用坚固铁皮敲打成型并经过整体硬化的粗糙腿部护具。全包覆钢片能够有效抵御贴地爬行丧尸的突袭抓咬，即便被钝器砸中也能凭借坚固的钢壳化解大部分骨折危险。",
        en = "Crude sheet metal leg guards hardened to absorb punishing blunt trauma. Enclosing lower extremities from knees to ankles, low-crawling biters find nothing to chew except unyielding plate.",
    },
    ["ch_legguard_metal_sheets_greaves"] = {
        zh = "经渗碳硬化的粗工钣金护胫。坚硬的铁皮牢牢包裹在小腿迎面骨前方，让幸存者在踢踹带刺防盗铁门或在满是碎石的废墟里冲刺时再也不必担心胫骨受创。",
        en = "Hardened sheet-metal greaves buckled across the shins with thick leather straps. Kicking down reinforced security doors or sprinting through rubble leaves your shins completely undamaged.",
    },
    ["ch_legguard_metal_sheets_hip"] = {
        zh = "由数片活动硬化薄钢板手工拼接而成的废土板甲短裙。如同中世纪战裙般垂挂在腰胯四周，在完全不阻碍奔跑迈步的同时，稳稳护住了腰侧与大腿根部的动脉要害。",
        en = "A flexible skirt composed of articulated hardened sheet-steel plates. Hanging loosely around the waist, it grants wide striding freedom while guarding vulnerable femoral arteries from low blade slashes.",
    },
    ["ch_legguard_metal_sheets_knees"] = {
        zh = "用废弃铁皮冲压弧度并经过淬火硬化的自制简易护膝。虽然外表粗糙带有手工敲打的凹凸痕迹，但紧扣在膝盖上能挡下狂暴丧尸抡来的铁管，保住你的半月板。",
        en = "Homemade knee cops hammered out of scrap sheet metal and hardened in an oil bath. Uneven hammer dimples aside, they absorb lead pipe blows that would otherwise shatter knee cartilage.",
    },
    ["ch_lighthelm_close"] = {
        zh = "经过轻量化减薄处理的硬化钢封闭头盔。在保留了对头颅与下颚全面包覆的同时削减了近半重量，大幅减轻长途行军时的颈椎负担，深受敏捷型重甲战士喜爱。",
        en = "A lightened close helmet forged from thinned hardened steel plates. Retaining full-face locking protection at half the mass, it prevents crippling neck fatigue during long road patrols.",
    },
    ["ch_lighthelm_close_raised"] = {
        zh = "面甲掀开锁定的轻型硬化钢封闭头盔。在视野开阔与空气清新之余，轻巧的盔身不会压得脖子酸痛，一旦前方突发敌情，单手按下卡扣就能瞬间完成全封闭防御部署。",
        en = "The lightweight hardened close helmet with its pivoting visor flipped open. Breathing effortlessly without neck strain, a quick tap snaps the steel visor down for immediate sealed combat readiness.",
    },
    ["ch_link_sheet"] = {
        zh = "由无数淬火碳钢锁环紧密铆接而成的锁环网，柔韧而坚固，只要依照身材剪裁缝制，就能做成足以传给下一代幸存者的护身软甲。",
        en = "A flexible expanse of riveted hardened steel chainmail rings, ready to be tailored into defensive hauberks that shrug off claws and knife thrusts.",
    },
    ["ch_longsword"] = {
        zh = "比例协调完美、剑刃经过严苛淬火调质的硬化碳钢标准双手长剑。无论劈、刺、切、割还是利用十字护手进行招架锁刀，都是中世纪冷兵器格斗体系中的全能神兵。",
        en = "A classic medieval longsword forged from hardened carbon steel. Excelling equally at slashing, thrusting, and crossguard parries, it represents the absolute apex of martial versatility in ruins.",
    },
    ["ch_mace"] = {
        zh = "顶端铸有厚实破甲突棱的硬化碳钢重型钉头锤，重心完全集中在锤头，无需任何花哨招式，只需顺势一砸就能将丧尸头盔连同脑壳砸扁。",
        en = "A solid high-carbon steel flanged mace atop a reinforced shaft; unbothered by armor or bone, delivering crushing kinetic devastation with every swing.",
    },
    ["ch_mirror_armor"] = {
        zh = "表面擦拭得光可鉴人的东方硬化钢护心镜板甲。中央凸起的圆形抛光大铜镜钢板不仅极具威严美感，更能将正面射来的流弹与突刺动能完美滑开偏转，防护一流。",
        en = "Polished eastern mirror armor centered around a gleaming convex hardened steel disc. Deflecting oncoming punctures and ricochets away from vital organs, its bright surface blinds sunny attackers.",
    },
    ["ch_mitten_gaunt"] = {
        zh = "将手指整体包覆在硬化钢壳内的中世纪连指锁甲重手套。虽然无法单独活动每一根手指，但在近身格斗中握紧拳头砸向丧尸脸部时，坚如铁锤的杀伤力令人胆寒。",
        en = "Articulated mitten gauntlets encasing fingers within solid hardened steel plates. Sacrificing individual finger motion, landing a clenched fist strike hits with the crushing impact of an iron mace.",
    },
    ["ch_mitten_gaunt_metal_sheets"] = {
        zh = "由废弃车壳铁皮手工铆接的简易硬化连指铁手套。外形虽然粗犷笨重，但厚实的钢壳手套能直接徒手抓住带刺铁丝网或丧尸咬过来的大嘴，保住你的双手毫发无伤。",
        en = "Crude mitten gauntlets hammered from hardened automotive sheet metal. Rugged and unpolished, they let you safely grab razor wire or shove attacking zombie mouths aside with impunity.",
    },
    ["ch_nodachi"] = {
        zh = "全长近两米、双手挥舞的超大号硬化钢日式野太刀。长长的弧形刀身带着惊天动地的破空怒吼，挥斩而出时能在十步之外将并排冲上来的三只丧尸连刀带人一并斩断。",
        en = "A colossal two-handed nodachi exceeding six feet in length, forged from hardened steel. Unleashing monumental sweeping arcs, a single overhand cut severs multiple approaching ghouls in half.",
    },
    ["ch_pike"] = {
        zh = "前端装有硬化淬火四棱钢锥的长达数米的重型木柄长矛。只要将矛尾死死顶在泥地里，迎面狂暴冲刺而来的变异野猪或狂暴巨兽就会凭借自身的巨大惯性将自己穿透致死。",
        en = "An extraordinarily long wooden pike tipped with a case-hardened steel socket point. Braced firmly against earth, charging mutant monstrosities impale themselves on their own reckless momentum.",
    },
    ["ch_rapier"] = {
        zh = "配有繁复精美鸟笼形护手盘的硬化高碳钢细刺剑。剑身细长笔直且极富弹性，轻轻一抖就能如闪电般刺穿丧尸眼眶直达脑干，是废土决斗家最自豪的优雅凶器。",
        en = "A slender rapier fitted with an intricate swept-hilt guard, forged from hardened carbon steel. Springy and lightning-fast, surgical thrusts slip effortlessly through eye sockets to extinguish ghouls.",
    },
    ["ch_sabaton"] = {
        zh = "由多层铰接硬化钢片顺畅滑移构成的中世纪铁甲铁鞋。紧密贴合靴子外表面，既不影响跑步弯曲脚掌，又能确保在满地地雷破片与生锈铁钉上行军时脚背不被洞穿。",
        en = "Articulated steel sabatons composed of overlapping hardened lames laced over boots. Flexing naturally with your gait, they ensure that stomping across caltrops and broken glass leaves feet pristine.",
    },
    ["ch_sabaton_metal_sheets"] = {
        zh = "用废品站钣金冲压制成的一对硬化铁皮鞋盖。直接绑扎在普通徒步靴外面，虽然每走一步都会发出轻微的金属摩擦脆响，但在遭遇低位变异毒虫咬噬时能提供万无一失的铁甲屏障。",
        en = "Makeshift sabatons fashioned from hardened sheet metal and strapped over work boots. Rattling slightly with every stride, they deflect low bites from venomous crawling insect swarms.",
    },
    ["ch_scimitar"] = {
        zh = "采用中东传统大弧度大马士革曲度打造的硬化钢弯刀。刀刃开锋极致细腻，挥舞时空气中留下尖锐的呼啸声，切削撕裂变异生物厚重皮毛如同划过薄纸般顺滑。",
        en = "A deeply curved shamshir saber forged from hardened spring steel. Its razor cutting belly glides through dense hide and muscle, turning close-quarters evasion into effortless dismemberment.",
    },
    ["ch_sheet_metal_small"] = {
        zh = "经过淬火硬化的高强度薄钢板，硬度极高且不易形变，无论是用来作为盾牌前部的补强片，还是做成防刺插板都极为可靠。",
        en = "A hardened high-carbon sheet steel plate; resistant to bending and piercing, perfect for reinforcing shields or fabricating custom trauma inserts.",
    },
    ["ch_shoulder_guards"] = {
        zh = "采用两毫米硬化碳钢冲压出完美弧形的一对护肩板。轻便贴身且防御可靠，无论是遭遇高空抛物砸伤还是敌人挥舞钝器的势大力沉下劈，都能将冲击力顺着弧面滑开。",
        en = "A pair of sleek shoulder guards pressed from two-millimeter hardened steel. Deflecting falling bricks and downward club strikes cleanly off their sloped domes, they prevent collarbone injuries.",
    },
    ["ch_shoulder_guards_xs"] = {
        zh = "小号剪裁的人体工学硬化钢护肩。专为娇小身材打造，双肩转动灵活丝毫不产生阻碍，在狭窄的通风管道里爬行时也不会刮擦管壁发出声响，堪称潜行暗杀利器。",
        en = "Compact hardened steel shoulder caps proportioned for slender builds. Never scraping against walls while crawling inside cramped ducts, they afford silent, reliable protection during stealth ops.",
    },
    ["ch_spear_steel"] = {
        zh = "在坚实硬木白蜡杆前端牢牢套接硬化锻钢枪头的经典作战长枪。两米开外的安全攻击距离让你可以面带微笑地隔着栅栏把堵路的丧尸脑袋一个个捅出透明窟窿。",
        en = "A stout ash polearm topped with a socketed hardened steel spearhead. Keeping snapping jaws safely six feet away, you can methodically dispatch fence-bound zombie crowds without risking a scratch.",
    },
    ["ch_steel_chunk"] = {
        zh = "边缘锐利且质地坚韧的硬化碳钢碎块，在没有铁砧时是一块极好的临时砧垫，直接当成投掷武器甩出去也能砸裂变异狗的颅骨。",
        en = "A jagged chunk of work-hardened carbon steel; wonderfully stubborn against deformation, doubling as a field anvil or lethal hand-thrown projectile.",
    },
    ["ch_steel_facemask"] = {
        zh = "配有开孔眼部防盾的硬化碳钢装甲面罩，佩戴后宛如一个没有感情的钢铁恶鬼，能让佩戴者的脸颊免遭酸液飞溅与近距爪击。",
        en = "A sinister hardened steel face plate with slotted eyeholes; turning the wearer into an emotionless metal wraith while safeguarding features from acid spray.",
    },
    ["ch_steel_lump"] = {
        zh = "经过精炼与淬火的高碳钢锭，散发着冷冽的青灰色光芒，是废土顶级铁匠打造高阶长剑、破甲箭头与机械传动齿轮的无价母料。",
        en = "A refined ingot of quenched tool-grade steel; the holy grail for wasteland weaponsmiths fashioning razor-edged longswords and armor-piercing broadheads.",
    },
    ["ch_steel_staff"] = {
        zh = "两端套有硬化高碳钢重装箍套的镔铁长棍，坚硬如铁且韧性极佳，挥动时呼呼作响，一记横扫就能让逼近的敌人膝盖当场粉碎。",
        en = "A heavy wooden fighting staff shod with hardened steel caps; balanced for sweeps and crushing thrusts that shatter kneecaps without dulling an edge.",
    },
    ["ch_talwar"] = {
        zh = "带有碟形圆盘护手柄与大弯曲刀身的印度传统硬化钢弯刀。特殊的握把锁死手腕发力姿态，每一记沉重的反手劈斩都能凭借极佳的切割角将迎面之敌切成两段。",
        en = "A traditional Indian talwar forged from hardened carbon steel and fitted with a disc pommel. Locking the wrist into powerful chopping planes, draw-cuts effortlessly shear through tough sinew.",
    },
    ["ch_vambrace_brigandine"] = {
        zh = "在坚固帆布夹层中交错铆接硬化钢板条的布面甲臂盾护腕。兼顾了灵活挥动近战武器的自由度与抵挡钝器劈砍的防护硬度，是废土刀口舔血者不可多得的臂部护具。",
        en = "Durable canvas vambraces lined with riveted splints of hardened steel. Preserving full wrist flexibility for rapid weapon parries, they turn shattering bludgeon blows aside with steady composure.",
    },
    ["ch_wakizashi"] = {
        zh = "日式武士在室内防身时专用的硬化钢胁差短刀。刀身短小精悍且锋利绝伦，在狭窄走廊或车辆座舱内挥舞自如，是长太刀施展不开时的终极保命副武器。",
        en = "A compact Japanese wakizashi short sword forged from hardened carbon steel. Highly maneuverable in cramped hallways or vehicle cabins, it serves as the ultimate companion blade in tight spots.",
    },
    ["ch_warhammer"] = {
        zh = "一端为破甲尖锥、另一端为平头凹槽战锤的硬化钢战锤。沉重的钢铁质感专克任何顽固护甲，一锤砸在防弹钢盔上能直接将对方的脑浆在头盔内部震成豆腐脑。",
        en = "A ruthless medieval war hammer sporting a blunt crushing face and a piercing rear beak. Delivering concentrated kinetic shock through the heaviest plate armor, it liquifies brains beneath helmets.",
    },
    ["ch_wire"] = {
        zh = "高弹性且极难剪断的硬化碳钢钢丝，不仅是制作强力扳机簧和高压陷阱的极品材料，也是布设致命绊雷引信的隐形杀手。",
        en = "Stiff high-tensile carbon steel wire; resisting wire cutters, prized for fashioning heavy recoil springs or invisible, lethal tripwire triggers.",
    },
    ["ch_zweihander"] = {
        zh = "德国文艺复兴时期标志性的超重型硬化钢双手斩剑。剑身前带有锋利的护指突刺，双手全力抡起时犹如一台毁灭性的钢铁风车，能将面前扇形区域的一切生物尽数腰斩。",
        en = "A gargantuan German zweihänder featuring flanged parrying hooks above the ricasso. Whirled with two-handed fury, its sweeping blade forms an impassable perimeter of flying steel and severed limbs.",
    },
    ["chaff"] = {
        zh = "谷物脱粒扬场后扬弃的碎干燥谷壳与秸秆碎屑，虽然无法下咽，但塞进麻袋里就能缝出一个松软透气的枕头，或是垫在牛棚里保温。",
        en = "Dry winnowed grain husks and brittle straw flakes; unpalatable as food, but stuffing them into burlap sacks yields surprisingly comfortable, airy pillows.",
    },
    ["chai_tea"] = {
        zh = "融入了肉桂、小豆蔻与浓缩鲜奶的南亚风味印度香料茶，辛香浓郁且甜美丝滑，在寒冬夜里喝下一杯，能让疲惫的灵魂重新振作。",
        en = "A spiced South Asian black tea simmered with milk, cloves, and cardamom; its warming aroma cuts through freezing dampness to revive morale.",
    },
    ["chain"] = {
        zh = "由粗壮精钢圆环焊接相扣的重型钢链，沉甸甸的很有分量，既能用来拖拽抛锚的装甲重卡，甩动起来也是一件势不可挡的范围兵器。",
        en = "A heavy welded steel link chain; versatile enough to tow stalled technicals out of mud or whirl through the air to sweep multiple pursuers off their feet.",
    },
    ["chain_link"] = {
        zh = "最普通的未经淬火的普通铁质锁环，容易弯折与闭合，虽然强度不如硬化碳钢，但用来练习锁甲编织技巧或是修补破损链甲十分趁手。",
        en = "Standard mild steel jump rings; easily bent and riveted, serving as affordable material for novice armorers practicing chainmail weaving techniques.",
    },
    ["chainmail_armor_cow"] = {
        zh = "由数万个小铁环编织而成的全身牛用锁子甲，厚重严实，虽然给奶牛穿上它像是在准备一场魔幻阅兵，但能有效阻挡丧尸抓破牛皮。",
        en = "A sprawling chainmail barding tailored for domestic cattle; undeniably comical to behold, yet effectively shields prize livestock from slashing claws.",
    },
    ["chainmail_armor_horse"] = {
        zh = "闪耀着金属寒光的马用全身链甲，贴合马匹身形，随着奔跑如银色水波流动，让你的战马在突围时完全免疫扑咬和投掷石块。",
        en = "Flowing iron chainmail horse barding; draping gracefully over equestrian contours, allowing charges through hostile skirmish lines without bleeding out.",
    },
    ["chainmail_harness_dog"] = {
        zh = "专为忠诚猎犬量身编织的锁子甲背心，轻便透气且防护到位，不仅能保护狗狗的内脏免受刺伤，穿上后更显得威风凛凛、霸气外露。",
        en = "A tailored chainmail harness protecting the chest and flanks of loyal hunting dogs, turning your furry camp companion into an armored war hound.",
    },
    ["chainmail_junk_arms"] = {
        zh = "用各种粗细不一的生锈铁丝手工圈绕编织的废料锁子甲护袖。虽然铁环表面泛着斑驳的锈迹，但套在小臂上依然能稳稳咬住丧尸的狂暴撕扯，是初期极其实用的防咬防具。",
        en = "Improvised chainmail sleeves bent from salvaged baling wire and rusty metal rings. While pitted with surface oxidation, they reliably catch feral teeth and prevent gruesome arm infections.",
    },
    ["chainmail_junk_feet"] = {
        zh = "用零碎铁环手工拼接而成的简易链甲镫靴，套在靴子外面叮当作响，虽然极其磨损鞋面，但能有效防止丧尸趴在地上偷啃你的脚踝。",
        en = "Makeshift chainmail chausses laced over combat boots; noisy and abrasive against leather, yet denying crawling zombies the pleasure of chewing on your Achilles tendons.",
    },
    ["chainmail_junk_hands"] = {
        zh = "用废旧细铁丝环手工密密麻麻缝在手套上的链甲手套，虽然让手指屈伸略显僵硬，但在徒手格挡丧尸飞扑时能保护手掌不被咬碎。",
        en = "Crude wire-link chainmail mittens stitched over work gloves; reducing fine dexterity, but providing critical bite-proof armor when wrestling thrashing ghouls away from your throat.",
    },
    ["chainmail_junk_hauberk"] = {
        zh = "用废品站捡来的各种旧铁环手工拼凑编织的粗制锁子甲长袍。走起路来像一串生锈的钥匙相互碰撞叮当作响，虽然卖相破烂不堪，但在乱军中能实打实为你挡下致命乱刀。",
        en = "A makeshift chainmail hauberk assembled from miscellaneously sized scrap wire loops. Jingling loudly like a bag of rusty hardware, its multi-layered mesh nevertheless stops knives dead in their tracks.",
    },
    ["chainmail_junk_hood"] = {
        zh = "用粗糙铁环拼凑缝制的锁环头罩，垂在双肩上冰冷沉重，戴在安全帽底下虽然压得脖子酸痛，但能彻底防住来自头顶的割喉伏击。",
        en = "A heavy coif woven from scrap iron rings; chilling the neck and shoulders, yet preventing overhead lurkers from slashing open your jugular in dark tunnels.",
    },
    ["chainmail_junk_legs"] = {
        zh = "用废品站铁丝圈手工编制并配有皮带固定的粗制锁子甲护腿。金属表面虽然布满了红褐色的锈斑，但在低位撕咬战中能稳稳卡住丧尸犬的尖牙，保住你的脚筋。",
        en = "Makeshift chainmail leggings cobbled from rusty baling wire and scavenged straps. Pitted with rust, they nonetheless catch snapping canine jaws, preserving your Achilles tendons during scuffles.",
    },
    ["chainmail_junk_suit"] = {
        zh = "从报废车辆和旧篱笆上拆铁丝串起来的全套铁屑锁子甲套装。每走一步浑身就像挂满了钥匙串一样哗啦作响，虽然毫无潜行可言，但能实打实为你抵挡无数次利爪抓挠。",
        en = "A full scrap chainmail suit fashioned from salvaged fence loops and scrap wire. Rattling like a bag of wrenches with every step, it utterly ruins stealth while turning deadly claw swipes aside.",
    },
    ["chainmail_junk_vest"] = {
        zh = "由锈迹斑斑的旧铁环手工拼凑串缝的无袖废料锁子甲背心。外表看起来像是一件破渔网，但套在棉袄外面，能出其不意地把迎面刺来的生锈弹簧刀刀尖当场折断。",
        en = "A sleeveless chainmail vest woven from corroded metal links. Looking like a discarded fishing net, slipping it over padded jackets unexpectedly snaps incoming bandit shivs upon impact.",
    },
    ["chainmail_suit_faraday"] = {
        zh = "利用导电金属锁环将全身严密包覆以形成法拉第笼特性的特种锁子甲。面对放电丧尸的致命高压电弧，电流会顺着金属外壳滑入大地，让你在雷光狂暴中闲庭信步。",
        en = "A specialized chainmail suit engineered to form an unbroken Faraday cage around the body. Lethal lightning arcs discharged by shocking zombies ground harmlessly, leaving you completely unshocked.",
    },
    ["chainmail_suit_faraday_xs"] = {
        zh = "专为瘦小身材量身织造的小号法拉第笼防雷击锁子甲。各处接缝导电极佳且轻巧贴身，穿上它在变异电鳗泛滥的地下积水坑里涉水，再也不用担心被电得浑身抽搐。",
        en = "A compact Faraday chainmail suit scaled for slender survivors. Ensuring uninterrupted electrical grounding, you can wade through flooded basements crawling with bio-electric horrors without trembling.",
    },
    ["chainsaw_off"] = {
        zh = "尚未拉响引擎的重型伐木链锯，锯条上布满凝固的黑色机油与陈年木屑，虽然现在一片死寂，但谁都知道它一旦苏醒将是何等残暴。",
        en = "A silent gas-powered forestry chainsaw crusty with dried sap and oil; quiet for now, but harboring apocalyptic kinetic fury awaiting the yank of a pull cord.",
    },
    ["chainsaw_on"] = {
        zh = "正以极高转速疯狂咆哮并冒着刺鼻蓝烟的通电链锯，高速飞旋的锋利锯齿足以把挡路的一切原木或血肉瞬间粉碎成漫天血雾。",
        en = "A deafening two-stroke chainsaw shrieking at maximum RPM in blue exhaust haze; spinning teeth ready to mulch fallen timber or encroaching abominations into crimson sawdust.",
    },
    ["chair_folding"] = {
        zh = "铁管支撑的经典白色塑料折叠椅，往地上一放就能提供短暂的休憩，但在被变异怪物逼到墙角时，也是摔角手最喜欢的格斗道具。",
        en = "A ubiquitous tubular steel folding chair; offering five minutes of campsite rest, or acting as an iconic pro-wrestling bludgeon when cornered by mutant fiends.",
    },
    ["chair_plywood"] = {
        zh = "用弯曲胶合板固定在细铁架上的学校工字椅，硬邦邦的毫无舒适度可言，除了提醒你末日前的枯燥课堂外，劈碎了当柴火倒是很耐烧。",
        en = "A stiff plywood classroom chair bolted to steel tubing; thoroughly unergonomic, bringing back dull lecture memories before being smashed apart for evening campfire kindling.",
    },
    ["chair_wood"] = {
        zh = "四平八稳的传统实木餐椅，带有舒适的靠背条，虽然在逃亡路上带不走它，但在废弃民宅里坐下来吃顿罐头会让你感到格外安心。",
        en = "A solid four-legged dining chair with turned spindles; too heavy to haul on patrols, but offering immense psychological comfort while dining inside quiet ruins.",
    },
    ["chair_wood_black"] = {
        zh = "刷着黑色亮光漆的木质靠背椅，典雅庄重甚至带有一丝哥特式的压抑感，放在废弃大宅的壁炉前，仿佛正等待一位吸血鬼领主落座。",
        en = "A black lacquered timber armchair exuding gothic sobriety; sitting solemnly before a cracked hearth, looking as if awaiting an undead nobleman's midnight audience.",
    },
    ["chair_wood_white"] = {
        zh = "刷着乡村风格白色油漆的木椅，漆皮已经有些斑驳脱落，透着一丝战前田园生活的温馨余韵，如今静静立在满是灰尘的废墟客厅里。",
        en = "A distressed white farmhouse chair peeling with age; radiating bittersweet country charm amidst crumbling drywall, mourning a tranquil lifestyle swept away by catastrophe.",
    },
    ["chalice"] = {
        zh = "由纯金铸造并镶嵌了未琢磨红宝石的宗教圣杯，沉甸甸的握感彰显着神圣与奢华，拿它来喝雨水或者野果汁总显得有些暴殄天物。",
        en = "A solid gold liturgical chalice studded with raw garnets; exquisitely weighted, making scavenged ditch water or wild berry juice taste almost sacrilegiously divine.",
    },
    ["chamomile"] = {
        zh = "一把刚刚采摘下来的白色野生洋甘菊鲜花，散发着苹果般的清新甘甜，在沸水里泡上一小撮，就能舒缓一整天高度紧绷的逃亡神经。",
        en = "Fresh white chamomile blossoms releasing delicate apple-like fragrance; steeping a small pinch in boiling water gently untangles frayed, hypervigilant survival nerves.",
    },
    ["chamomile_tea"] = {
        zh = "用滚烫开水冲泡的淡黄色洋甘菊茶，水汽中弥漫着温暖的药草清香，在凄风苦雨的寒夜里喝下一杯，能让你在睡袋里安稳沉睡到天亮。",
        en = "Pale golden herbal infusion breathing soothing floral warmth; drinking it before bed invites peaceful slumber untroubled by screaming sirens or ravenous nightmares.",
    },
    ["chaplet"] = {
        zh = "用野花与坚韧常青藤条手工编织的精美花冠，戴在头上宛如林地仙子，虽然没有任何防御属性，但在灰暗废土上是极珍贵的浪漫点缀。",
        en = "A delicate circlet woven from wild blossoms and evergreen vines; completely devoid of tactical utility, yet injecting pure fairytale defiance into grim wasteland reality.",
    },
    ["chaps_cut_resistant"] = {
        zh = "采用高强度凯夫拉纤维层层织就的专业伐木护腿，专门用于在链锯脱手反弹时咬死链条，在废土上也是防御近距爪击撕扯的绝佳护具。",
        en = "Heavy ballistic Kevlar logging chaps engineered to jam runaway chainsaws; offering extraordinary cut resistance against sweeping mutant claws during frantic melee scuffles.",
    },
    ["chaps_leather"] = {
        zh = "由坚韧黑色牛皮缝制的西部风格开裆皮护腿，套在牛仔裤外面能抵御灌木丛倒刺与扬起的沙尘，更能为你的步伐增添几分废土枪手的野性。",
        en = "Tough black leather riding chaps buckled over denim; warding off roadside brambles and flying grit while gifting your stride unmistakable gunslinger swagger.",
    },
    ["char_forge"] = {
        zh = "由耐火砖与手摇鼓风机组合而成的便携式木炭锻造炉，只要填入足够的木炭并猛摇风机，升腾的白炽炭火能轻松将高碳钢烧至通红。",
        en = "A portable charcoal metalworking forge with hand blower; churning out blinding white heat capable of softening high-carbon steel bars for custom toolmaking.",
    },
    ["char_kiln"] = {
        zh = "用重型油桶和排烟铁管改造而成的便携式热解炭窑，把砍伐的硬木塞进去闷烧数天，就能把普通木材转化为高效无烟的高热木炭。",
        en = "A drum kiln engineered for wood pyrolysis; transforming chopped logs into dense, smokeless charcoal essential for smelting, forging, and long winter heating.",
    },
    ["char_purifier"] = {
        zh = "填满了高吸附性活性木炭颗粒的便携净水筒，浑浊有毒的野外脏水缓缓滤过炭层后，能滤除大部分异味与毒素，是野外解渴的护身符。",
        en = "A compact canister packed with granular activated carbon; stripping toxic runoff and swamp stink from scavenged water to produce safe drinking hydration.",
    },
    ["char_purifier_clay"] = {
        zh = "由烧结多孔陶土与厚厚活性炭层构成的大型重力滤水器，不仅能高效吸附水中的化学异味，更是永久性避难所建立清洁水源的基石。",
        en = "A ceramic gravity filter packed with crushed charcoal media; providing a steady, continuous trickle of sterile drinking water for fortified wilderness compounds.",
    },
    ["char_smoker"] = {
        zh = "配有双层铁丝网与通风阀门的便携式木炭烟熏烤架，把腌制好的兽肉挂在里面慢熏十二小时，就能做出能存放整个冬天的风干肉干。",
        en = "A portable steel smoking chamber with dual racks; slowly curing salted venison in aromatic wood smoke to create shelf-stable winter protein provisions.",
    },
    ["character_sheet"] = {
        zh = "一张写满了力量敏捷敏锐数值与技能检定的龙与地下城角色卡。在现实世界彻底变成满是怪物的黑暗地下城后，纸上那只二十级满配大法师再也无法跳出来拯救主人。",
        en = "A classic Dungeons and Dragons tabletop character sheet filled with stats and modifiers. Now that reality has permanently morphed into a lethal dungeon, that level-twenty wizard cannot save you.",
    },
    ["charcoal"] = {
        zh = "由硬木在缺氧环境下缓慢干馏烧制出来的黑色高纯度木炭，质地轻脆，燃烧时温度极高且没有刺鼻黑烟，是锻造冶炼的灵魂火种。",
        en = "Light, brittle lumps of hardwood charcoal; burning hotter and cleaner than raw timber, serving as the pure carbon lifeblood for camp forges.",
    },
    ["charcoal_cooker"] = {
        zh = "带有灰烬托盘与铸铁锅架的小型便携煤炭炉，虽然其貌不扬，但只要丢进几块木炭，就能在十分钟内为你烧开一壶热茶或煮熟一锅浓汤。",
        en = "A compact sheet-steel stove burning coal or charcoal nuggets; boiling billycans of tea or simmering hearty stews using minimal fuel inside drafty bunkers.",
    },
    ["chaturanga"] = {
        zh = "装在抛光木盒里的古印度四色战棋，被认为是国际象棋与中国象棋的共同始祖，在漫长冬夜里和同伴推演战局，能有效防止精神退化。",
        en = "An ancient Indian predecessor of modern chess tucked inside a sandalwood box; maneuvering miniature elephants and infantry keeps tactical faculties razor-sharp during blizzards.",
    },
    ["chaw"] = {
        zh = "带着浓烈留兰香薄荷味的有机咀嚼烟草，塞一撮在牙龈与嘴唇之间，辛辣的尼古丁能迅速麻痹痛觉，虽然会让你吐出满地恶心的棕色唾沫。",
        en = "Pungent mint-flavored chewing tobacco; packing a wad against the cheek releases an intense nicotine burn that numbs toothaches and stains floors dark brown.",
    },
    ["cheap_ammo_pouch"] = {
        zh = "用廉价帆布缝制的军规斜挎四联装弹挂，虽然扣具简陋，但挂在肩上能整齐容纳四个三十发步枪弹匣，让你在火拼时换弹有条不紊。",
        en = "A rugged cotton bandolier partitioned for four standard assault rifle magazines, slinging spare firepower across your torso without adding excessive combat weight.",
    },
    ["cheap_ammo_pouch_belt223"] = {
        zh = "专为容纳百发五点五六毫米弹链设计的加宽帆布腰袋，坚固耐磨，能防止脆弱的金属弹链在剧烈奔跑中发生扭曲变形或沾染泥沙。",
        en = "A wide canvas belt pouch tailored for a hundred-round 5.56mm linked ammo belt, keeping machine gun ammunition clean and tangle-free during flanking maneuvers.",
    },
    ["cheap_ammo_pouch_belt308"] = {
        zh = "粗帆布缝制的重机枪弹链腰包，专门容纳沉重的大口径全威力步枪弹链，挂在腰间沉甸甸的，每一步都能感受到钢铁重火力的安心分量。",
        en = "A reinforced canvas container cradling linked full-power 7.62mm cartridges, providing steady feeding for heavy support weapons pinning down hostile marauders.",
    },
    ["cheap_whiskey"] = {
        zh = "装在粗劣塑料扁平瓶里的廉价调和威士忌，带着刺鼻的焦糖色素与劣质乙醇辛辣味，喝下去如同一把烈火从食道一直烧到胃底。",
        en = "Bottom-shelf blended whiskey sold in a flimsy plastic flask; harsh and chemical, igniting a fiery trail down the esophagus straight into the liver.",
    },
    ["checkers"] = {
        zh = "装在粗糙松木盒里的黑白双色西洋跳棋，规则简单粗暴，无论大字不识的拾荒流民还是精明商人，都能在棋盘上为了连跳吃子杀个你死我活。",
        en = "A wooden box housing turned wooden draughts tokens; simple rules allowing anyone from illiterate scavengers to battle commanders to wage miniature wooden war.",
    },
    ["cheek_pad"] = {
        zh = "绑在步枪枪托上方的加厚氯丁橡胶贴腮垫，能为射手提供稳定舒适的贴腮高度，让你通过高倍瞄准镜追踪远距离目标时视野毫不晃动。",
        en = "A cushioned neoprene stock riser securing consistent cheek weld; perfectly aligning pupil with scope reticles for motionless long-range marksmanship.",
    },
    ["cheerleader_dress"] = {
        zh = "蓝白配色的轻盈啦啦队连身短裙，胸前印着褪色的学校队徽，在到处是死者与废墟的世界上，穿上它除了嘲弄现实之外没有任何防御加成。",
        en = "A breezy blue-and-white cheerleading uniform; offering zero thermal or physical protection, standing as a bright theatrical mockery of grim post-collapse ruins.",
    },
    ["cheerleader_skirt"] = {
        zh = "鲜红色的经典百褶啦啦队短裙，面料轻软且便于大幅度运动奔跑，虽然防不住寒风和变异荆棘，但能在末日废土上保持无与伦比的回头率。",
        en = "A scarlet pleated cheer skirt designed for acrobatics; totally defenseless against cold winds or thorny brush, yet undeniably striking amidst drab rubble.",
    },
    ["cheerleader_skirt_short"] = {
        zh = "极其清凉简短的红色超短百褶裙，走动时裙摆飞扬，如果穿着它在满是碎砖瓦砾和丧尸残骸的废墟里匍匐前进，膝盖大概会伤痕累累。",
        en = "An ultra-short pleated cheerleading skirt; lightweight and breezy, but attempting to crawl across fractured concrete in it will shred knees into ribbons.",
    },
    ["cheerleader_top_short"] = {
        zh = "印着金色“Cheers”字样的红色无袖紧身短背心，弹性良好，除了能展现紧绷的肌肉线条外，在遇到寒潮时只会让你冻得浑身发抖。",
        en = "A cropped red athletic tank top emblazoned with faded team slogans; showing off toned wasteland muscles, but offering negligible insulation against freezing fog.",
    },
    ["cheese"] = {
        zh = "整块金黄诱人的再制加工硬质奶酪，质地均匀且富含盐分与油脂，切下一大片夹在饼干里，浓郁的乳酪咸香足以抚平胃袋的一切不满。",
        en = "A yellow block of processed American cheese; salty, fatty, and shelf-stable, delivering an explosion of savory dairy comfort atop stale hardtack.",
    },
    ["cheese_fries"] = {
        zh = "炸至金黄酥脆的厚切粗薯条，表面淋满了厚厚一层滚烫浓稠的融化奶酪酱，趁热用叉子挑起，拉丝的奶酪是末日最堕落的高热量狂欢。",
        en = "Golden potato wedges buried beneath a lava flow of melted cheddar; piping hot and stringy, representing the pinnacle of junk-food indulgence.",
    },
    ["cheese_grater"] = {
        zh = "带有四种不同孔径冲压刀口的不锈钢方盒刨丝器，不仅能把坚硬干酪刨成细腻如雪的碎屑，在急眼时也是一把能刮掉敌人皮肉的恶毒近战钝器。",
        en = "A four-sided stainless box grater; effortlessly shredding aged cheese blocks into culinary snow, or serving as a horrifyingly abrasive tavern brawler weapon.",
    },
    ["cheese_grits"] = {
        zh = "在熬得浓稠细腻的白玉米糊里拌入大量切达奶酪碎的热粥，香浓软糯，带着淡淡的玉米甘甜与奶酪咸香，是南方最温暖人心的早餐。",
        en = "Coarse white hominy cornmeal simmered with salted cheddar cheese into rich porridge; buttery, savory, and keeping shivering patrols fueled for hours.",
    },
    ["cheese_hard"] = {
        zh = "经过长期熟化脱水风干的古老硬质奶酪，硬度堪比坚硬的河卵石，需要用锋利的猎刀用力切削，但其含水量极低，能保存数年不坏。",
        en = "Rock-hard aged farmhouse cheese cured for long-term storage; demanding a stout knife to shave flakes, but impervious to mold across multiple winters.",
    },
    ["cheese_powder"] = {
        zh = "脱水干燥研磨而成的亮橙色高浓缩奶酪粉，通常来自通心粉料包，只要撒上一小勺在野菜汤或面条里，就能瞬间染上一层诱人的浓郁奶香。",
        en = "Vibrant orange dehydrated cheese powder salvaged from pasta boxes; stirring a spoonful into watery weed broth transforms it into creamy culinary comfort.",
    },
    ["cheese_rehydrated"] = {
        zh = "用温开水与奶酪粉搅拌调和还原出来的粘稠黄色奶酪酱，口感顺滑浓郁，虽然带有明显的人造香味，但蘸着干硬的烤馕吃格外香甜。",
        en = "Reconstituted warm cheese spread whipped from powder and water; slightly synthetic to the palate, yet glorious for smothering dry emergency ration crackers.",
    },
    ["cheese_wheel_wax"] = {
        zh = "从一整轮大陈年奶酪外壳上剥下来的厚重封蜡层，质地柔韧且密封绝缘，熔化后不仅能用来密封自制罐头，也是制作蜡烛的极品原料。",
        en = "A thick, pliable wax shell peeled from a giant cheese wheel; melting it down yields airtight sealant for preserved food jars or excellent candle stock.",
    },
    ["cheeseburger"] = {
        zh = "在多汁肉饼上盖着融化奶酪片并夹着酸黄瓜的经典美式芝士汉堡，散发着让人发狂的油脂焦香，咬上一口简直是对整个崩坏文明的终极致敬。",
        en = "A toasted bun clutching a beef patty smothered under melted cheddar and pickles; the quintessential crown jewel of pre-collapse fast-food civilization.",
    },
    ["cheesy_spinach_casserole"] = {
        zh = "用大量鲜奶油、磨碎切达奶酪与嫩菠菜烘烤出的热腾腾焗菜，表面覆盖着焦黄起泡的芝士脆壳，每一口都是维生素与浓郁乳脂的完美融合。",
        en = "A bubbly baked casserole combining tender spinach greens with heavy cream and molten cheese; decadent, vitamin-packed nourishment straight from the oven.",
    },
    ["chem_DMSO"] = {
        zh = "工业级二甲基亚砜透明溶剂，具有极其可怕的极性穿透力，能带着任何溶解在其中的毒素瞬间渗透人体皮肤，使用时必须格外小心。",
        en = "Clear liquid dimethyl sulfoxide; an extraordinarily powerful solvent possessing the terrifying trait of carrying dissolved compounds straight through human skin.",
    },
    ["chem_acetic_acid"] = {
        zh = "带有强烈刺鼻酸味的浓缩冰醋酸，不仅是工业化学合成的重要基料，稀释上百倍后也是烹饪调味与腌制肉类防腐的上乘原料。",
        en = "Pungent concentrated acetic acid; blindingly sharp to inhale, serving as an essential chemical reagent or diluted into preservative pickling vinegar.",
    },
    ["chem_acetone"] = {
        zh = "极易挥发且高度易燃的纯丙酮透明液体，散发着类似于指甲油去除剂的甜烈气味，是清洁精密枪械零件与溶解树脂塑料的超级溶剂。",
        en = "Volatile pure acetone emitting a sweet solvent aroma; indispensable for stripping carbon fouling from firearms or synthesizing volatile chemical mixtures.",
    },
    ["chem_acrylamide"] = {
        zh = "呈现白色结晶粉末状的丙烯酰胺，毒性剧烈且具有神经毒性，虽然是合成各种高分子聚合物的关键单体，但操作时严禁吸入粉尘。",
        en = "A white crystalline monomer powder; highly toxic to nervous systems, requiring respirators during handling while synthesizing specialized laboratory polyacrylamides.",
    },
    ["chem_agar"] = {
        zh = "从深海红藻中提炼脱水干燥的半透明天然琼脂片，在沸水中溶解冷却后能凝结成坚硬果冻，既能做成果冻甜点，也是培养细菌的培养基。",
        en = "Translucent dried seaweed flakes; dissolving in boiling broth to form firm gelatinous slabs for sweet jellies or sterile microbiological culture media.",
    },
    ["chem_aluminium_powder"] = {
        zh = "细度极高的银灰色金属铝粉，极具还原性，一旦与强氧化剂混合就是毁天灭地的铝热剂，在夜色中燃烧能释放出融化钢轨的耀眼白光。",
        en = "Fluffy metallic aluminum dust; harmless on its own, yet transforming into terrifying thermite mixtures capable of liquefying engine blocks when sparked.",
    },
    ["chem_aluminium_sulphate"] = {
        zh = "呈现半透明白色结晶状的硫酸铝矿物，投入浑浊泥水后能迅速让悬浮的泥沙沉淀聚沉，是野外大规模净化死水湖泊的关键净水混凝剂。",
        en = "A handful of astringent aluminum sulfate crystals; acting as a flocculating agent that clumps murky suspended clay out of pond water during purification.",
    },
    ["chem_ammonium_nitrate"] = {
        zh = "洁白细小的硝酸铵吸湿结晶粉末，在和平年代是让农作物疯长的高效氮肥，但在暴徒手里，只要淋上一点柴油就是摧毁大楼的恐怖炸药。",
        en = "A white crystalline oxidizer powder; commercially traded as high-nitrogen plant fertilizer, notoriously converted into building-level explosives when soaked in diesel.",
    },
    ["chem_ammonium_nitrate_pellets"] = {
        zh = "经过防潮包衣处理的多孔粒状硝酸铵颗粒，专门为了方便储存运输而设计，是调配重型土制采矿炸药最理想的固体氧化剂颗粒。",
        en = "Porous prilled ammonium nitrate pellets coated against humidity; optimized for agricultural spreading or absorbing fuel oil to brew explosive charges.",
    },
    ["chem_anfo"] = {
        zh = "将多孔硝酸铵颗粒充分浸润轻质柴油后制成的棕褐色铵油炸药丸，散发着刺鼻的油味，虽然性质极其钝感，但雷管引爆后的威力摧枯拉朽。",
        en = "Brownish pellets soaked in diesel fuel oil; stubbornly insensitive to open flame, yet detonating with catastrophic earth-shattering shockwaves when primed.",
    },
    ["chem_antimony_trichloride"] = {
        zh = "散发着刺鼻呛人气味的无色软质三氯化锑粉末，遇水极易水解喷出白色酸雾，是高级化学合成与定性分析实验中不可多得的无机试剂。",
        en = "Soft hygroscopic antimony trichloride powder releasing choking acidic fumes; prized by post-collapse chemists for esoteric inorganic syntheses and qualitative testing.",
    },
    ["chem_apex"] = {
        zh = "臭名昭著的过氧化丙酮白色粉末，极度敏感且不稳定，哪怕是轻微的摩擦、静电或摔打都会引发猛烈爆轰，被化学家敬畏地称为撒旦之母。",
        en = "Infamous triacetone triperoxide crystals; so savagely shock-sensitive that friction, static, or warm sunlight triggers violent instantaneous supersonic detonation.",
    },
    ["chem_baking_soda"] = {
        zh = "洁白无暇的无水碳酸氢钠小苏打粉，不仅能用来中和被强酸烧伤的皮肤，也是烘焙蓬松薄饼、去除冰箱异味与擦洗油污的居家万能神药。",
        en = "White sodium bicarbonate powder; an all-purpose household miracle neutralizer for battery acid spills, rising griddle cakes, or scrubbing greasy gear.",
    },
    ["chem_benzene"] = {
        zh = "散发着芳香甜味但极具致癌毒性的透明无色苯液体，极易挥发燃烧，是石油化工合成中不可替代的芳香烃母体，但千万别大口去闻。",
        en = "Sweet-smelling colorless aromatic benzene; fiercely flammable and heavily carcinogenic, serving as a versatile foundational building block for organic chemistry.",
    },
    ["chem_black_powder"] = {
        zh = "将硝石、木炭与硫磺按古法精密调配而成的经典黑火药细颗粒，稍微摩擦遇火就会剧烈爆燃并喷出浓烈白烟，是文明重启初期最可靠的火器动力。",
        en = "A gritty gray-black granular mix of sulfur, charcoal, and saltpeter; billowing dense acrid white smoke while launching lead balls from antique muskets.",
    },
    ["chem_borax"] = {
        zh = "洁白细腻的十水四硼酸钠粉末，既能用来洗衣服和自制粘液史莱姆玩具，也是高温金属铸造焊接时最不可或缺的优秀助焊剂。",
        en = "Pure white powdered borax crystals; equally suited for laundering bloodied combat fatigues, mixing toy slimes, or acting as essential flux during high-temperature blacksmithing.",
    },
    ["chem_caco3"] = {
        zh = "研磨极细的高纯度碳酸钙白粉，无论是用来配制抗酸剂中和胃酸，还是用来中和强酸废液以防烧穿下水道，都非常安全平稳。",
        en = "Fine calcium carbonate powder ground from pure limestone; safe and gentle for settling severe acid reflux or neutralizing caustic chemical spills before pipes dissolve.",
    },
    ["chem_calcium_chloride"] = {
        zh = "极易吸潮结块的白色无味氯化钙粉末，丢进水里会剧烈放热，在极寒暴风雪天气中，它是拯救冻结水管的极速融雪除冰神器。",
        en = "Aggressively hygroscopic calcium chloride flakes that generate intense heat when dissolving, acting as a miracle de-icer for frozen bunker hatch hinges and pipes.",
    },
    ["chem_carbide"] = {
        zh = "散发着微弱大蒜味的碳化钙灰色碎石，只要吐上一口唾沫就会立刻剧烈喷出高纯度乙炔气体，是矿灯照明和焊接切割的催化魔石。",
        en = "Grey calcium carbide stones exuding faint garlic odors; reacting violently with mere spittle to generate flammable acetylene gas for miner headlamps and welding torches.",
    },
    ["chem_chloroform"] = {
        zh = "带有甜美芳香气味的无色重质氯仿液体，在侦探小说里是常客，倒在手帕上捂住口鼻，几分钟内就能让狂躁的劫匪安静倒地沉睡。",
        en = "Heavy, sweet-smelling liquid chloroform renowned in crime thrillers; soaked into a rag, it reliably sedates raving hostiles without requiring noisy firearms or physical wrestling.",
    },
    ["chem_chromium_oxide"] = {
        zh = "呈现鲜艳深绿色的三氧化二铬粉末，化学性质极其稳定耐高温，不仅是调制绿色陶瓷釉彩的颜料，更是高级刀具精细研磨膏的核心。",
        en = "Deep olive-green chromium oxide powder impervious to thermal degradation; prized as vibrant refractory ceramic pigment or the abrasive core of fine knife-stropping pastes.",
    },
    ["chem_citric_acid"] = {
        zh = "尝起来酸得让人五官扭曲的纯柠檬酸白色晶体，只要在平淡无奇的水里加一小捏，就能做出媲美战前罐装柠檬汽水的清爽酸饮。",
        en = "Tart white crystals of concentrated citric acid; adding a tiny pinch to boiled rainwater instantly replicates the mouth-puckering refreshment of pre-war lemon sodas.",
    },
    ["chem_compositionb"] = {
        zh = "由黑索金与梯恩梯高温熔融浇铸混合而成的B炸药，性质稳定且威力惊人，在军工拆迁中能干脆利落地把最厚重的地堡大门炸成碎铁片。",
        en = "A castable blend of RDX and TNT yielding formidable high-explosive brisance, shattering reinforced subterranean blast doors with merciless, shockwave-driven finality.",
    },
    ["chem_ethanol"] = {
