    ["coat_gut"] = {
        zh = "由原住民利用干燥海兽肠膜精心拼接缝制的防水风雨衣，半透明且轻若无物，不仅完全阻隔冰雨和浪花，还能散发出一股纯正的荒野气息。",
        en = "A translucent traditional parka meticulously sewn from split seal intestines, shedding icy sea spray and freezing drizzle with natural, featherlight waterproofing.",
    },
    ["coat_lab"] = {
        zh = "带有深大下摆口袋的白色长款棉质科研实验服，虽然早已染上斑斑点点的可疑化学试剂污渍，但穿上它总能让人产生一种懂科学的错觉。",
        en = "A standard knee-length white lab coat stained with mysterious reagent drips, granting an unearned aura of scientific authority while searching subterranean research ruins.",
    },
    ["coat_lab_xedra_mark"] = {
        zh = "内层编织了铅丝与导电碳纤维复合网的XEDRA特制屏蔽实验服，不仅能阻挡有害辐射尘埃，更能微弱削弱不可名状异界能量的心智侵蚀。",
        en = "A custom XEDRA research smock lined with lead mesh and conductive filaments, dampening harmful ambient radiation while shielding against subtle psychic interference.",
    },
    ["coat_light_winter"] = {
        zh = "采用防撕裂尼龙外壳制成的轻薄防风冲锋衣，接缝压胶严密，虽然缺乏厚实保暖内衬，但在狂风暴雨中能给里层衣物提供最干净的防雨屏障。",
        en = "A lightweight uninsulated technical shell jacket with taped seams; perfectly blocking biting gale winds and moisture while moving swiftly through ruined avenues.",
    },
    ["coat_rain"] = {
        zh = "一件带有宽大兜帽与两个大口袋的亮黄色乙烯基长款雨衣。虽然没有任何防弹防撕咬能力，但在暴雨倾盆的漆黑泥泞废墟里，它能保住你的内衣干爽避免致命失温。",
        en = "A bright vinyl raincoat equipped with a deep hood and generous cargo pockets. Useless against biting horrors, it keeps clothing bone-dry during freezing torrential rains that cause lethal hypothermia.",
    },
    ["coat_straw"] = {
        zh = "采用天然稻草层层编织而成的传统蓑衣，下垂的草穗能让倾盆大雨顺势滑落，虽然穿在身上像个移动的稻草人，但防雨透气性出奇地优秀。",
        en = "A traditional layered straw raincoat shedding heavy downpours along natural thatch fibers, turning the wearer into a walking haystack that stays surprisingly dry.",
    },
    ["coat_winter"] = {
        zh = "填充了厚实白鸭绒的连帽防寒羽绒服，蓬松轻盈，拉紧拉链和防风帽后，外界的一切狂暴冰霜都会被这层轻柔的羽绒温室彻底隔绝在外。",
        en = "A puffy down-filled winter coat with deep insulated pockets; incredibly light and warm, creating a cozy personal microclimate amidst frozen winter wastes.",
    },
    ["cobalt_60"] = {
        zh = "未受任何防护铅罐屏蔽的高放射性钴六十金属颗粒，表面看似平平无奇，但它向四周狂暴喷射的伽马射线能在几分钟内彻底摧毁人体DNA。",
        en = "An unshielded metallic pellet of Cobalt-60 silently spewing ferocious gamma rays, lethal enough to scramble cellular DNA and cook marrow within minutes.",
    },
    ["cocaine_topical"] = {
        zh = "医用级外用局部可卡因麻醉软膏，涂抹在擦伤或割口表面能瞬间收缩局部毛细血管并完全止痛，是战地外科缝合伤口时的顶级止痛灵药。",
        en = "A topical anesthetic medical cream containing pharmaceutical cocaine; constricting severed capillaries while totally numbing excruciating surgical lacerations in field clinics.",
    },
    ["cocoa_powder"] = {
        zh = "经过脱脂精细研磨的纯天然苦可可粉，没有添加任何糖分或奶粉，虽然直接尝起来苦涩发干，但它是烘焙巧克力点心与提神的黑色黄金。",
        en = "Unsweetened, finely milled pure cocoa powder; intensely bitter on the tongue, yet serving as the indispensable dark soul for baking rich survival cakes.",
    },
    ["cocoa_powder_milk"] = {
        zh = "预先混合了全脂奶粉与精幼白糖的速溶可可冲饮粉，只要舀进热开水里轻轻搅拌，就能在冰冷刺骨的战壕里享用一杯浓郁甜美的热巧克力。",
        en = "Sweetened instant cocoa mix blended with milk solids; stirring three spoonfuls into boiling snowmelt yields rich, steaming hot chocolate that lifts broken spirits.",
    },
    ["coconut"] = {
        zh = "带有毛茸茸纤维硬壳的完整热带椰子，敲开坚硬的椰壳不仅能畅饮甘甜清凉的椰汁，厚实的白色椰肉更是荒岛与废土顶级的植物热量来源。",
        en = "A hairy, hard-shelled tropical drupe guarding sweet water and dense white flesh; cracking its stubborn armor rewards wanderers with magnificent hydration and calories.",
    },
    ["coconut_flesh"] = {
        zh = "从新鲜椰壳内壁小心刮取下来的大片雪白椰肉，口感脆嫩且富含浓郁的植物油脂，细细咀嚼能散发出迷人的奶香，是难得的纯天然能量块。",
        en = "Chunks of fresh, ivory coconut meat rich in natural saturated oils; delightfully chewy and sweet, fueling hours of heavy foot travel through desolate sands.",
    },
    ["coconut_water"] = {
        zh = "从青椰子中倒出来的半透明清凉椰汁，口感甘甜微酸且富含天然电解质，在烈日炙烤中大口痛饮，能比任何人工运动饮料更快地驱散中暑。",
        en = "Cloudy, sweet coconut water naturally brimming with potassium and electrolytes; drinking it deep from the shell cures dehydration and exhaustion under blazing suns.",
    },
    ["codeine"] = {
        zh = "印着微小药厂代码的温和阿片类止痛药片，不仅能平复剧烈的肌肉钝痛与关节酸痛，也是压制废土肺尘病引发的剧烈干咳的特效药。",
        en = "A clinical blister pack of codeine sulfate tablets; mild opiates suppressing agonizing chest coughing and dull bone fractures to allow restful sleep.",
    },
    ["coffee"] = {
        zh = "相传九世纪埃塞俄比亚牧羊人卡尔迪发现山羊吃下某种红果实后兴奋乱跳，人类由此获得了抵御困倦的圣水。而在崩塌后的废土上，这杯苦涩黑水依旧维持着幸存者神经元最后的体面运转。",
        en = "Legend holds that 9th-century Ethiopian goat herder Kaldi discovered coffee after watching his flock dance vigorously upon eating red berries. Centuries later, this bitter black nectar remains the only catalyst preventing survivors from curling up into a miserable ball.",
    },
    ["coffee_bean"] = {
        zh = "经过深度烘焙、表面微微渗出诱人芳香油滴的阿拉比卡咖啡豆，散发着坚果与黑巧克力的浓香，光是闻一闻就能唤醒沉睡已久的文明记忆。",
        en = "Dark-roasted whole coffee beans glistening with fragrant essential oils; grinding them releases intoxicating nutty aromas that temporarily resurrect the civilized world.",
    },
    ["coffee_pod"] = {
        zh = "从北美野生的肯塔基咖啡树上采集到的坚硬粗大豆荚，剥开后露出含有微毒的硬籽，只有经过长时间的彻底水洗与重度烘焙才能安全饮用。",
        en = "Tough woody seed pods harvested from the wild Kentucky coffeetree; mildly toxic raw, requiring rigorous boiling and dark roasting to brew frontier java.",
    },
    ["coffee_raw"] = {
        zh = "将精选咖啡豆研磨成均匀颗粒的现磨咖啡粉，深褐色且香气浓郁，只要架起滴滤壶注入开水，就能萃取出一杯让疲惫大脑重归清醒的圣水。",
        en = "Coarsely ground roasted coffee beans reeking of rich caramel; pouring boiling river water over a paper filter yields liquid alertness for midnight watchmen.",
    },
    ["coffee_raw_kentucky"] = {
        zh = "将肯塔基咖啡树种子经过洗毒并深度炭化烘焙后研磨而成的代用咖啡粉，虽然带有一丝泥土杂味，但在咖啡绝迹的荒原上依然让人感恩。",
        en = "Detoxified and heavily roasted Kentucky coffeetree beans pulverized into grounds; slightly earthy, yet providing a warm, dark morning simulation of lost coffee.",
    },
    ["coffee_substitute"] = {
        zh = "用烤焦大麦、菊苣根与肯塔基咖啡籽混煮出来的代用黑咖啡，没有真正的咖啡因，但滚烫苦涩的口感能很好地欺骗胃袋与习惯性神经反射。",
        en = "A dark, bitter decoction brewed from roasted grains and wild chicory; devoid of actual caffeine, yet successfully tricking psychological habits into alertness.",
    },
    ["coffee_substitute_sweetened"] = {
        zh = "在苦涩的代用咖啡汤中加入了双倍蔗糖的甜代用咖啡，浓稠温热，甜味巧妙地掩盖了草本根茎的土腥味，是一杯让人感到被呵护的暖心热饮。",
        en = "Herbal grain coffee sweetened heavily with scavenged sugar; hot, rich, and comforting, masking woody astringency behind sweet, familiar morning warmth.",
    },
    ["coffee_sweetened"] = {
        zh = "加入了浓缩炼乳与大量白糖的香浓美式甜咖啡，甜苦交织且咖啡因强劲，在漫漫严冬的避难所里，喝下一杯能让人重新拥有战胜绝望的勇气。",
        en = "Freshly brewed aromatic coffee enriched with heavy cream and cane sugar; the quintessential morning ritual that makes facing another day in hell worthwhile.",
    },
    ["coffee_syrup"] = {
        zh = "将浓缩黑咖啡与大量白糖熬制至拉丝状态的黑褐色咖啡糖浆，香浓醇厚，无论浇在松饼上还是兑入凉开水，都能瞬间化作提神高糖能量剂。",
        en = "A thick, glossy molasses-like syrup infused with concentrated coffee; drizzled over hot pancakes or stirred into water for an instantaneous sugary stimulant rush.",
    },
    ["coffeemaker"] = {
        zh = "配有透明玻璃分享壶与电加热底座的经典滴滤式美式咖啡机，只要插上蓄电池并按下开关，那熟悉的咕嘟咕嘟煮咖啡声就是文明最美妙的音符。",
        en = "An automatic drip coffee brewer with glass carafe; the rhythmic bubbling of water through grounds inside safe base camps sounds like heavenly civilization music.",
    },
    ["coffeepot"] = {
        zh = "一只耐高温玻璃制成的经典美式家用滴滤咖啡壶。只要在壶底架上一堆温热余烬，丢进一把磨碎的蒲公英根或陈年咖啡粉，升腾而起的苦香能瞬间治愈疲惫的灵魂。",
        en = "A heat-resistant glass carafe designed for brewing morning coffee. Simmering ground chicory or roasted dandelion root over embers, its fragrant steam restores weary survivalist spirits.",
    },
    ["coilgun"] = {
        zh = "利用多级电磁线圈环环加速铁磁弹丸的自制电磁线圈枪，击发时只有轻微的电容啸叫与空气破裂声，在悄无声息中将钢钉打入目标的头颅。",
        en = "A multi-stage electromagnetic coilgun accelerating iron slugs through copper windings; silent save for capacitor whines, punching steel through skulls in shadows.",
    },
    ["coin_dime"] = {
        zh = "刻有富兰克林·罗斯福侧面头像的十美分硬币，边缘带有防滑滚花，在失去货币价值的今天，它小巧的尺寸刚好可以拿来给自制步枪垫平机械瞄具。",
        en = "A silver-colored cupronickel ten-cent coin; economically worthless, but its precise thickness makes it a handy leveling shim for misaligned rifle optics.",
    },
    ["coin_dollar"] = {
        zh = "刻有女权先驱苏珊·安东尼肖像的一美元硬币，沉甸甸的很有质感，在荒废的旧时代自动售货机前投进去，偶尔还能惊喜地掉出一包过期口香糖。",
        en = "A heavy brass-hued dollar coin; largely an antique token now, yet occasionally triggering ancient vending machines to spit out fossilized snack cakes.",
    },
    ["coin_gold"] = {
        zh = "重达一金衡盎司的美国水牛二十四K纯金金币，金光夺目且沉坠压手，无论人类文明崩塌成何种地狱，黄金永远是全人类共通的终极硬通货。",
        en = "A one-ounce pure 24-karat gold Buffalo bullion coin; heavy, gleaming, and timeless, instantly commanding reverence and purchasing entire armories from wasteland merchants.",
    },
    ["coin_half_dollar"] = {
        zh = "印有肯尼迪总统头像的大尺寸五十美分硬币，硕大厚重，翻转抛在空中时会发出清脆的长鸣，是废土流浪赌徒在火堆旁赌命下注的经典筹码。",
        en = "A broad fifty-cent coin ringing with crisp resonance when flipped; a favorite token among drifters and gamblers deciding perilous crossroads paths by coin toss.",
    },
    ["coin_highlands"] = {
        zh = "从苏格兰高地古代古墓尸骨上搜刮出来的微型银质奥波尔硬币，边缘残破古朴，虽然上面的铭文早已磨损，但纯银质地依然散发着冷冽的寒光。",
        en = "A tiny antique silver obol salvaged from ancient cairns; worn smooth by centuries, its cold precious silver mass prized by post-cataclysm alchemists and traders.",
    },
    ["coin_nickel"] = {
        zh = "印有托马斯·杰斐逊头像与蒙蒂塞洛庄园的五美分白铜硬币，质地坚硬耐磨，在弹药短缺时，把七八枚镍币塞进霰弹枪弹壳里就是致命的飞钱霰弹。",
        en = "A chunky cupronickel five-cent piece; robust and dense, easily loaded into empty 12-gauge hulls to fashion improvised close-range canister buckshot rounds.",
    },
    ["coin_penny"] = {
        zh = "印有亚伯拉罕·林肯头像的镀铜锌合金一美分硬币，轻薄廉价，虽然以前被所有人嫌弃，但搜刮一大把熔化后能得到上好的锌合金浇铸原料。",
        en = "A copper-plated zinc one-cent piece; disregarded by pre-war shoppers, now hoarded by backyard metallurgists for its low-melting-point zinc casting core.",
    },
    ["coin_quarter"] = {
        zh = "刻有乔治·华盛顿头像的经典二十五美分硬币，在末日废土的洗衣房和游戏厅残骸中随处可见，用螺丝刀在上面钻个洞就能当成平垫圈使用。",
        en = "A standard 25-cent quarter featuring George Washington; drilled through the center with a hand drill, it becomes an unyielding steel washer for carriage bolts.",
    },
    ["coin_silver"] = {
        zh = "含有一金衡盎司点九九九纯银的美国鹰扬银币，铸造精美绝伦，银白如雪的币面在阳光下熠熠生辉，既能杀灭水中华丽细菌，也是保值的无价财富。",
        en = "A magnificent one-ounce .999 pure Silver Eagle coin; brilliant uncirculated silver luster that disinfects water jugs or secures safe passage across warlord bridges.",
    },
    ["coin_wrapper"] = {
        zh = "由厚牛皮纸卷制而成的圆筒形硬币包装纸卷，侧面印着币值与金额，能把散乱的硬币整整齐齐码成一条，在没有银行的废土上显得格外规整。",
        en = "A heavy-duty kraft paper sleeve engineered to wrap rolls of coinage, turning loose scrap metal pocket change into tidy, dense weighted cylindrical weapons.",
    },
    ["coke"] = {
        zh = "从古柯叶中精炼提取的高纯度可卡因白色结晶粉末，极具成瘾性与狂暴的中枢兴奋性，吸入鼻腔后能让濒死战士在狂乱错觉中透支最后的生命。",
        en = "Crystalline white alkaloid extracted from coca leaves; inducing rapid euphoria and reckless adrenaline surges that push exhausted bodies far beyond organic limits.",
    },
    ["cola"] = {
        zh = "风靡全球数十年的经典深色气泡碳酸饮料，虽然防腐剂和焦糖色极其浓重，但在冰凉时灌下一大口，碳酸气泡在喉间炸裂的感觉是文明最纯粹的滋味。",
        en = "The legendary effervescent dark brown soda bubbling with caffeine and high-fructose corn syrup, delivering an unmistakable, crisp, cold sip of lost human civilization.",
    },
    ["cola_meth"] = {
        zh = "将高浓度脱氧麻黄碱粉末、咖啡因与超甜玉米糖浆粗暴混调的恶毒“冰毒可乐”，颜色古怪浑浊，喝下一瓶能让你在心跳爆表的三天三夜里不眠不休。",
        en = "A toxic wasteland cocktail dissolving street amphetamines directly into sugary cola syrup; a twitching, heart-exploding elixir guaranteeing three sleepless hyper-focused nights.",
    },
    ["colamdew"] = {
        zh = "颜色荧光发绿且尝起来宛如挡风玻璃清洗液的能量混合可乐，气泡狂暴且牛磺酸严重超标，喝完后不仅舌头发绿，连打出的嗝都像化学气体。",
        en = "A neon-green carbonated hybrid that looks and tastes alarmingly like radiator coolant, loaded with dangerous taurine levels that leave your teeth buzzing.",
    },
    ["colander_steel"] = {
        zh = "冲压有密集细小沥水孔的不锈钢滤网盆，结实坚固且永不生锈，不仅是淘洗野生谷物和野菜的得力助手，也是淘洗河底砂金时的轻便筛网。",
        en = "A perforated stainless steel basin engineered to strain boiling pasta water, doubling admirably as a gold panning sieve across gravelly wasteland creekbeds.",
    },
    ["collar_playboy"] = {
        zh = "带有黑色丝绸领结与魔术贴暗扣的白色可拆卸兔女郎假领，小巧俏皮，在满目疮痍的血腥战场上佩戴它，将废土后现代黑色幽默推向了顶峰。",
        en = "A crisp detachable white wingtip collar adorned with a black satin bowtie, injecting theatrical nightclub absurdity directly into muddy survival foxholes.",
    },
    ["collarpin"] = {
        zh = "带有双头螺纹旋钮的优雅镀金西装衬衫领针，能把领带结稳稳顶托在最挺拔的高度，是在废墟中依然坚持穿着整齐西装的体面人最后的尊严徽章。",
        en = "A gold-plated collar bar threaded through shirt eyelets to elevate neckties, serving as the proud badge of eccentric post-apocalyptic dandies who refuse to dress like savages.",
    },
    ["collector_book"] = {
        zh = "曾经被塑封加真空袋细心珍藏在防潮柜里的特装限量版，现在唯一的溢价体现在它的书页比普通平装书更抗风，引火时能多烧半分钟。",
        en = "Once sealed inside mylar sleeves and pampered on climate-controlled shelves; its post-apocalyptic collector premium amounts to burning thirty seconds longer in the campfire.",
    },
    ["colt_anaconda_4"] = {
        zh = "缩短到四英寸的枪管并没有让它的后坐力变得更温顺，只是让你在手腕被震得发麻的同时，能更快地从腰套里把它拔出来吓唬自己。",
        en = "Chopping the barrel down to four inches did not tame its ferocious recoil; it merely lets you draw faster to sprain your wrist that much sooner.",
    },
    ["colt_anaconda_6"] = {
        zh = "六英寸枪管在威力与便携之间取得了完美的折中，只要你忽略开火时如晴天霹雳般的枪声和瞬间照亮整条走廊的巨大枪口火团。",
        en = "The six-inch barrel strikes an admirable balance between brute stopping power and holsterable bulk, assuming you disregard the deafening thunderclap and corridor-blinding muzzle flash.",
    },
    ["colt_anaconda_8"] = {
        zh = "八英寸的沉重长枪管让它看起来更像一门手提攻城炮，即便弹巢里的子弹全部打光，光凭砸过去的惯性也能把丧尸的颅骨当场砸扁。",
        en = "An eight-inch barrel transforming a sidearm into a handheld siege cannon; even when running dry, swinging this slab of steel will cave in zombie skulls with ease.",
    },
    ["colt_army"] = {
        zh = "一百多年前用来打南北战争的老古董，现在重返前线对抗活死人；每次填装火药和铅丸的漫长过程，都足够丧尸慢条斯理地走过来吃掉你。",
        en = "An antique black powder relic drafted from historical reenactments into the zombie apocalypse; ramming loose powder and lead balls takes long enough for ghouls to stroll over and feast.",
    },
    ["colt_lightning"] = {
        zh = "泵动式卡宾枪的射速快得惊人，唯一的代价是它娇贵的供弹机构极其容易卡壳，让你在尸群冲脸时体验把泵动手柄当健身器拉扯的绝望。",
        en = "A lightning-fast pump-action carbine whose finicky feed elevator jams so eagerly that frantic cycling feels more like emergency upper-body workout in front of charging hordes.",
    },
    ["colt_navy"] = {
        zh = "优雅的八角形枪管散发着历史沉淀的魅力，火帽击发时的白烟能在你面前筑起一道烟幕，让你和对面的丧尸谁也看不清谁。",
        en = "An octagonal barrel exuding nineteenth-century chivalry; firing black powder caps creates a cloud of dense white smoke that leaves both you and the undead completely blind.",
    },
    ["colt_python"] = {
        zh = "蓝钢光泽依然耀眼的左轮之王，几乎所有灾变前硬汉警匪片主角的标配；可惜在末日世界里，无论你怎么甩枪耍帅，也没有剧组给你付片酬。",
        en = "The crowned king of blued revolvers, immortalized by cinematic lawmen; sadly, spinning the cylinder with movie-grade swagger will not earn a paycheck from roaming shamblers.",
    },
    ["colt_ro635"] = {
        zh = "把突击步枪的机匣硬塞进手枪弹药和乌兹弹匣的怪异造物，连发倾泻手枪弹时的抖动小得像玩具，只是消耗弹药的速度快得像破产清算。",
        en = "An odd mashup grafting an Uzi magazine into an AR platform; spitting nine-millimeter bursts with minimal kick, though draining your scarce stockpile faster than bankruptcy.",
    },
    ["colt_saa"] = {
        zh = "西部片牛仔神魂颠倒的单动左轮，退弹壳必须用推弹杆一根一根往外捅；在变异怪兽扑向你的生死关头，优雅的复古风格往往致命。",
        en = "The legendary single-action peashooter of the Wild West; having to punch spent casings out one by one makes vintage cowboy elegance a lethal liability.",
    },
    ["comb_lice"] = {
        zh = "齿密得连空气都几乎滤不过去的钢梳，在末日野外摸爬滚打几个月后，它成了你头皮上唯一能对抗那些寄生虫大军的微型装甲车。",
        en = "Steel teeth spaced so densely that even stray lice despair; after months of scavenging damp ruins, it is your scalp's solitary armored division against invasive parasites.",
    },
    ["comb_pocket"] = {
        zh = "一把质地轻巧、带有细密梳齿的塑料随身折叠小口袋梳。在这个全员蓬头垢面、满头干涸血浆和跳蚤的末世，偶尔能掏出梳子梳顺刘海，堪称人类文明最后的尊严。",
        en = "A simple plastic pocket comb for smoothing tangled hair. In a filthy world choked with dried gore and lice, pausing to comb your bangs preserves the last shreds of personal human dignity.",
    },
    ["combat_exoskeleton_armor_arm_heavy"] = {
        zh = "厚达六毫米的重型战斗外骨骼专用手臂装甲模块。整块高强度装甲板如同一座小型步战车炮塔侧舷，穿戴后抬手格挡能够毫发无损地硬抗大口径反器材穿甲弹直击。",
        en = "A six-millimeter heavy exoskeleton arm plate built like the side armor of an infantry fighting vehicle. Raising an arm deflects high-caliber anti-materiel rounds without bruising tissue beneath.",
    },
    ["combat_exoskeleton_armor_arm_heavy_reinforced"] = {
        zh = "在六毫米装甲基底上额外焊接复合抗冲击覆层的强化重型外骨骼手臂装甲。极致厚重的防护让你的整条手臂化作不可撼动的钢铁撞角，近身肉搏宛如开着坦克冲撞。",
        en = "A reinforced heavy exoskeleton arm plating augmented with bonded shock-absorbing composites. Turning your forearm into an impenetrable battering ram, close-quarters melee feels like colliding with tanks.",
    },
    ["combat_exoskeleton_armor_arm_light"] = {
        zh = "两毫米厚度的轻型战斗外骨骼手臂防护装甲。采用航空级高强度钛铝合金制成，在赋予前臂卓越防破片能力的同时，丝毫不影响穿戴者操纵精密武器的反应灵敏度。",
        en = "A lightweight two-millimeter titanium-alloy exoskeleton arm shell. Providing dependable shrapnel shielding without dragging down arm velocity, it preserves reflexive weapon manipulation.",
    },
    ["combat_exoskeleton_armor_arm_light_reinforced"] = {
        zh = "经过复合纤维额外加固的轻型战斗外骨骼手臂装甲。兼顾了惊人的轻盈手感与出色的抗撕裂性，无论在复杂废墟攀爬还是格挡凶狠抓咬，都能确保手臂骨骼安然无恙。",
        en = "Lightweight two-millimeter exoskeleton arm plates reinforced with high-tensile aramid backing. Preserving gymnastic agility, they shrug off frenzied clawing during tight urban climbing runs.",
    },
    ["combat_exoskeleton_armor_arm_medium"] = {
        zh = "四毫米标准厚度的中型战斗外骨骼手臂装甲板。在防弹硬度与机动负重之间取得了完美平衡，无论是抵挡自动步枪扫射还是近身格挡战斧劈砍，都表现得极其沉稳可靠。",
        en = "A balanced four-millimeter medium exoskeleton arm plate. Hitting the tactical sweet spot between mass and ballistic protection, it easily weathers full-auto rifle bursts and heavy broadaxe chops.",
    },
    ["combat_exoskeleton_armor_arm_medium_reinforced"] = {
        zh = "加装了陶瓷防弹防热贴片的中型外骨骼强化手臂装甲。不仅能稳稳吸收步枪弹药的高速贯穿动能，面对等离子与火焰喷射器的灼烧时也能为外骨骼机械伺服提供全方位隔热。",
        en = "A four-millimeter medium exoskeleton arm plate reinforced with ceramic ballistic tiles. Absorbing rifle penetrations while insulating internal servos from intense flame thrower heat, it stays combat-ready.",
    },
    ["combat_exoskeleton_armor_head_heavy"] = {
        zh = "六毫米厚度的超重型战斗外骨骼全包覆头部装甲。面罩内置全景态势感知HUD，厚重的实心合金装甲宛如一座套在脖子上的钢铁碉堡，无视任何普通枪械的正面爆头企图。",
        en = "A six-millimeter heavy combat exoskeleton helmet transforming your head into an armored fortress. Deflecting direct center-mass rifle fire, its integrated tactical sensors track multiple hostiles.",
    },
    ["combat_exoskeleton_armor_head_heavy_reinforced"] = {
        zh = "在六毫米重甲基础上增设了高分子防震内衬与强化面甲的终极外骨骼头盔。即便在距离炸药爆炸中心不到两米处硬抗冲击波，头骨内的脑髓也不会发生剧烈震荡。",
        en = "A reinforced six-millimeter heavy exoskeleton helmet lined with advanced concussive dampers. Surviving close-range artillery detonations, your cranium remains shielded from catastrophic shockwaves.",
    },
    ["combat_exoskeleton_armor_head_light"] = {
        zh = "两毫米轻质钛合金战斗外骨骼头部护具。大面积高透防弹面罩提供了极其宽广的自然视野，轻盈的佩戴感让特战侦察兵在全速战术转进时头部毫无负担感。",
        en = "A two-millimeter light exoskeleton helmet emphasizing expansive panoramic visibility and agility. Deflecting shrapnel while imposing zero neck strain, scouts sprint through ruins with unhindered vision.",
    },
    ["combat_exoskeleton_armor_head_light_reinforced"] = {
        zh = "额外涂覆了防激光抗烧蚀复合涂层的轻型外骨骼强化头盔。兼具敏捷的视野转动速度与抵御高能热射线的能力，是废土游侠与精确射手在开阔地带交火时的安全守护神。",
        en = "A reinforced two-millimeter light exoskeleton helmet treated with thermal-ablative ceramic coatings. Shrugging off stray lasers and shrapnel, it keeps mobile snipers safe across exposed terrain.",
    },
    ["combat_exoskeleton_armor_head_medium"] = {
        zh = "四毫米硬化装甲板构筑的中型战斗外骨骼全封闭头盔。各处密封接缝具备生化防毒防尘功能，厚重的合金壳体能把重型狙击枪的擦边跳弹轻描淡写地弹飞至半空。",
        en = "A four-millimeter medium combat exoskeleton helmet with integrated CBRN air seals. Glancing heavy sniper ricochets harmlessly off its sloped shell, it protects vital neurological functions.",
    },
    ["combat_exoskeleton_armor_head_medium_reinforced"] = {
        zh = "加焊了附加防弹钢片与高分子防震层的中型外骨骼强化头盔。无论正面撞击厚重的水泥墙壁还是硬接变异怪兽的飞扑铁拳，它都能像铁钳一样将使用者的颅骨牢牢锁住保护。",
        en = "A reinforced four-millimeter medium exoskeleton helmet fitted with appliqué ballistic plates. Breaching concrete barricades or withstanding savage beast blows leaves your skull utterly undamaged.",
    },
    ["combat_exoskeleton_armor_leg_heavy"] = {
        zh = "六毫米超厚合金打造的重型战斗外骨骼下肢腿甲。沉重如战车履带护板，包裹在双腿外侧不仅彻底免除任何踩雷断腿的厄运，重重踩下一脚更能直接踏碎丧尸的脊椎骨。",
        en = "Massive six-millimeter heavy exoskeleton leg guards functioning like tank treads around limbs. Completely neutralizing landmine blasts, stomping downward shatters mutant spines into powder.",
