    ["combat_exoskeleton_armor_leg_heavy_reinforced"] = {
        zh = "在六毫米重腿甲正面铆接高硬度碳化硅复合块的强化超重外骨骼护腿。走在尸潮群中宛如一尊钢铁魔像横冲直撞，任何试图绊倒你的变异爪牙都会在接触瞬间被折断粉碎。",
        en = "A reinforced six-millimeter heavy leg assembly fortified with silicon carbide composite inserts. Striding through dense hordes like an unstoppable golem, lunging biters break their limbs against it.",
    },
    ["combat_exoskeleton_armor_leg_light"] = {
        zh = "两毫米轻型外骨骼腿部装甲板。紧密贴合外骨骼液压连杆，在保护大腿小腿骨骼不受弹片飞石侵袭的同时，能让穿戴者随心所欲地施展百米冲刺与跨越障碍跳跃。",
        en = "Slender two-millimeter light exoskeleton leg guards contouring alongside powered hydraulic actuators. Protecting lower limbs from ricochets, they permit effortless full-speed obstacle vaulting.",
    },
    ["combat_exoskeleton_armor_leg_light_reinforced"] = {
        zh = "采用芳纶纤维加固内衬的轻型外骨骼强化腿甲。大幅削减自重与行动噪音，轻盈灵动，让敏捷的侦察兵在布满瓦砾的废弃街巷中健步如飞且无需担心暗处的尖刺陷阱。",
        en = "A reinforced two-millimeter light exoskeleton leg harness lined with aramid composites. Suppressing mechanical rattling, it keeps agile scouts swift and silent over jagged obstacle courses.",
    },
    ["combat_exoskeleton_armor_leg_medium"] = {
        zh = "四毫米厚度的标准中型战斗外骨骼护腿。能全面吸收大口径霰弹枪与近身钝器的狂暴冲击，即使正面被狂暴巨怪猛烈冲撞，坚固的下肢框架也能稳如泰山地支撑你伫立原地。",
        en = "A four-millimeter medium combat exoskeleton leg armor system. Absorbing point-blank shotgun blasts without buckling, the motorized framework keeps you anchored against violent shockwaves.",
    },
    ["combat_exoskeleton_armor_leg_medium_reinforced"] = {
        zh = "加装了膝关节侧向防扭强化支架的中型外骨骼腿甲。不仅防弹防砍性能拔群，更彻底杜绝了激烈跳跃冲撞时膝关节错位骨折的可能，是废土重步兵最值得信赖的钢铁双足。",
        en = "A reinforced four-millimeter medium leg armor assembly featuring rigid lateral knee stabilization braces. Eliminating sprain and hyperextension risks, it serves as the backbone of frontline infantry.",
    },
    ["combat_exoskeleton_armor_torso_heavy"] = {
        zh = "厚达六毫米的超重型战斗外骨骼躯干装甲。整套胸腹装甲宛如一面钢铁盾墙，沉重雄浑，即便正面挨了一发大口径穿甲火箭弹直射，穿戴者也能在液压缓冲下安然幸存。",
        en = "A monstrous six-millimeter heavy exoskeleton torso carapace. Acting like an impenetrable bulwark, surviving point-blank anti-tank rockets leaves the wearer shaken but completely unbroken.",
    },
    ["combat_exoskeleton_armor_torso_heavy_reinforced"] = {
        zh = "在六毫米重型装甲胸腹部额外覆盖复合防爆插块的终极外骨骼躯干甲。真正的人形装甲战车核心，穿上它在废土上行走，游荡尸群的所有撕咬攻击都与清风拂面毫无二致。",
        en = "An ultimate reinforced six-millimeter heavy exoskeleton torso harness clad in multi-layered composite reactive blocks. Walking through hordes clad in this suit, zombie fangs feel like gentle spring rain.",
    },
    ["combat_exoskeleton_armor_torso_light"] = {
        zh = "两毫米轻量化钛合金战斗外骨骼胸腹甲。在为心肺等关键脏器提供军规防破片保护的同时，极大地减轻了整机电力消耗与负重压力，深受远征巡逻队员的赞赏。",
        en = "A streamlined two-millimeter light exoskeleton torso shell. Delivering military-grade ballistic protection across vital organs without draining power cells, it is beloved by long-range recon patrols.",
    },
    ["combat_exoskeleton_armor_torso_light_reinforced"] = {
        zh = "内衬芳纶高分子防刺层的两毫米轻型外骨骼强化胸甲。轻薄透气且能有效吸收子弹动能，让穿戴者在遭遇埋伏突袭时拥有绝佳的战术机动性与关键时刻的防贯穿底线。",
        en = "A reinforced two-millimeter light exoskeleton breastplate backed by multi-layered aramid fabric. Combining breathability with exceptional kinetic dispersion, it turns fatal rifle hits into blunt bruises.",
    },
    ["combat_exoskeleton_armor_torso_medium"] = {
        zh = "四毫米厚度的中型战斗外骨骼标准躯干装甲。坚固厚实的人体工学胸甲将前胸后背完整覆盖，无论遭遇近距离突击步枪全自动泼水扫射还是变异怪兽重击，都能稳稳接下。",
        en = "A solid four-millimeter medium combat exoskeleton torso plate. Enclosing the chest and spine in contoured alloy armor, it absorbs sustained assault rifle bursts with stoic mechanical perfection.",
    },
    ["combat_exoskeleton_armor_torso_medium_reinforced"] = {
        zh = "增设了双层防破片陶瓷贴片的中型外骨骼强化胸甲。面对重型爆炸物产生的漫天高速破片与冲击波，坚固的复合装甲板能完美吸收一切物理破坏，守护穿戴者的核心生命线。",
        en = "A reinforced four-millimeter medium exoskeleton torso harness layered with ceramic strike faces. Shattering high-velocity shrapnel on impact, it preserves the wearer's life during artillery barrages.",
    },
    ["combat_exoskeleton_heavy"] = {
        zh = "战前被媒体俗称为坦克装甲服的初代超重型动力外骨骼。全自重极其惊人，未通电时笨重得寸步难行，但只要插上高能电池组，你就是废土街道上不可阻挡的活体装甲车。",
        en = "The legendary first-generation heavy combat exoskeleton colloquially dubbed a tank suit. Impossibly heavy when unpowered, slotting in fresh energy cells unleashes an unstoppable motorized juggernaut.",
    },
    ["combat_exoskeleton_heavy_on"] = {
        zh = "处于全力通电运转状态下的重型坦克装甲外骨骼。大功率液压伺服电机发出低沉威严的轰鸣声，机械臂爆发出的恐怖怪力能徒手掀翻废弃集装箱，所向披靡。",
        en = "The heavy combat exoskeleton fully powered with internal hydraulic pumps humming fiercely. Amplifying physical strength tenfold, you can casually shove overturned shipping containers aside like cardboard boxes.",
    },
    ["combat_exoskeleton_light"] = {
        zh = "大灾变前夕军方定型的第三代轻型军用动力外骨骼。设计极其紧凑修长，将微型电机与碳纤维支撑骨架完美结合，是科技巅峰时期人机工程学皇冠上的明珠。",
        en = "The refined third-generation light military combat exoskeleton developed just before the collapse. Melding high-torque micro-servos with carbon-fiber struts, it represents the absolute zenith of powered infantry mobility.",
    },
    ["combat_exoskeleton_light_on"] = {
        zh = "通电激活状态下的三代轻型动力外骨骼。轻柔的电机蜂鸣声中，穿戴者的每一次跨步冲刺与翻滚跳跃都被赋予了超凡的机械助力，宛如一只穿梭在钢铁丛林中的机械猎豹。",
        en = "The light combat exoskeleton actively humming with agile electric assist. Amplifying every sprint, leap, and vault, you glide across urban obstacle courses with the lethal grace of a cybernetic panther.",
    },
    ["combat_exoskeleton_light_salvaged"] = {
        zh = "在核爆辐射与战火中残存、经由废土机修工勉强修补的三代轻型外骨骼。电线外露且个别伺服偶尔抽搐，但只要主轴承还能运转，它就能为你提供宝贵的动力支撑。",
        en = "A battle-scarred third-generation light exoskeleton hastily patched by wasteland mechanics. Exposed wiring and occasional servo twitches aside, its core actuators still provide invaluable power assistance.",
    },
    ["combat_exoskeleton_medium"] = {
        zh = "战前军方大规模列装的二代中型主力战斗外骨骼。兼具了初代的坚固装甲挂载力与三代的运动灵活性，是经受过残酷城市平叛巷战检验的经典重装动力骨架。",
        en = "The second-wave military combat exoskeleton that saw widespread frontline deployment. Successfully bridging heavy armor capacity with tactical running speed, it forms the battle-tested backbone of powered warfare.",
    },
    ["combat_exoskeleton_medium_on"] = {
        zh = "处于高能待命运转状态的二代中型动力外骨骼。动力电缆中奔涌的电流驱动着四肢强劲的无刷电机，穿上它在断壁残垣中狂奔如履平地，手撕铁丝网更是小菜一碟。",
        en = "The medium combat exoskeleton humming with active high-output power. Channeling current through robust brushless motors, you charge through barricades and tear down chain-link fences with bare fists.",
    },
    ["combat_shirt"] = {
        zh = "专为配合重型防弹背心设计的拼接衬衫，袖子耐磨防刮，胸背却薄如蝉翼；一旦你脱掉防弹插板，就会瞬间在寒风中冻得瑟瑟发抖。",
        en = "Specially engineered for plate carriers, offering tough ripstop sleeves alongside a paper-thin torso; stripping your vest off immediately invites the freezing post-Cataclysm winds.",
    },
    ["combatnail"] = {
        zh = "专为高压气动钉枪或特种霰弹枪研制的微型全钢箭形钉。虽然每根只有手指长短，但在高压喷射下拥有极其恐怖的侵彻力，能把硬化丧尸的头颅牢牢钉在水泥电线杆上。",
        en = "A lethal miniature steel flechette engineered for pneumatic nailguns and specialized shotguns. Fired under high pressure, it punches through craniums to pin thrashing walkers directly to utility poles.",
    },
    ["combination_gun"] = {
        zh = "枪管上下堆叠了步枪与两根霰弹枪管的瑞士军刀式猎枪，专为有选择困难症的猎人设计，让你在开火前必须花半秒思考扳机到底管哪一根。",
        en = "A break-action chimera stacking a rifle barrel atop twin shotgun bores; designed for indecisive sportsmen who enjoy wondering which trigger discharges which payload while being charged.",
    },
    ["combination_gun_shotgun"] = {
        zh = "附着在下方的双联霰弹枪管，在远距离步枪失手后的最后一搏；两发近距离轰出十二号铅弹，通常要么解决危机，要么解决你自己的肩膀。",
        en = "The twin underbarrel shotgun tubes offering a frantic last resort; unleashing twelve-gauge buckshot point-blank will either resolve the incoming ambush or dislocate your shoulder.",
    },
    ["combo_cover"] = {
        zh = "笔挺威严的尖顶大檐帽，戴上它立刻让你散发出舰队司令的威风，前提是没有丧尸注意到你司令帽底下那身打满补丁的破烂运动裤。",
        en = "A crisply peaked commander cap radiating impeccable martial authority, right up until roaming zombies notice that the glorious fleet admiral is wearing duct-taped sweatpants underneath.",
    },
    ["commune_prospectus"] = {
        zh = "详尽描绘了如何开荒种田、自给自足并走向繁荣的公社企划书；文字里洋溢着天真的乌托邦憧憬，完全没把酸雨和变异巨虫算进资产负债表。",
        en = "An earnest prospectus detailing sustainable agro-communes and pastoral prosperity; brimming with utopian optimism that completely omitted acid rain and giant mutated wasps from the balance sheet.",
    },
    ["compact_ASRG_containment"] = {
        zh = "重得宛如铅锭的斯特林放射性发电机，内藏能烧几十年的微型核源；只要不把它当哑铃砸在脚趾上，它能比废土上绝大多数活人都要长寿。",
        en = "A leaden brick housing a space-age Stirling nuclear core; provided you avoid dropping it onto your toes, it will outlive practically every living survivor in New England.",
    },
    ["compbow"] = {
        zh = "偏心轮和滑轮拉线构造精巧的现代猎弓，在中拉力下省力比极高；在安静解决丧尸方面它是无声利器，只要你别在拉满弦时手滑打到小臂内侧。",
        en = "A modern compound bow with shaped cams granting generous let-off; silent and lethal for quiet sentry duty, until a stray string-slap bruises your forearm to the bone.",
    },
    ["compbow_high"] = {
        zh = "调整到了极限磅数的高拉力复合弓，箭矢射出时带着破空尖啸；要想把弓弦拉到满月，你的背肌力量最好比被你射穿的防暴丧尸还要狂暴。",
        en = "Cranked up to punishing draw weight, sending broadheads screaming through dense timber; pulling it fully demands broader back muscles than the riot zombie you are trying to impale.",
    },
    ["compbow_low"] = {
        zh = "调低了磅数的轻便复合弓，拉开它轻松得像拉橡皮筋；虽然射程和穿透力打了折扣，但至少能保证你拉满五十次后肩膀依然属于你自己。",
        en = "Dialed down to a gentle draw weight, pulling as effortlessly as rubber bands; sacrificing velocity and penetration so your rotator cuff survives past the fiftieth arrow.",
    },
    ["compcrossbow"] = {
        zh = "带有滑轮组的现代复合重弩，扣动扳机时的推力足以穿透铁皮；唯一的缺点是每次用上弦绳重新挂弦时，你弯腰吃力的姿势都像在拔萝卜。",
        en = "A high-tech compound crossbow punching bolts through sheet metal; the downside is that heaving the cocking rope makes you look like you are hauling frozen turnips out of mud.",
    },
    ["compensator"] = {
        zh = "拧在枪口处开槽的金属配重块，利用向上喷射的燃气压住后坐力；枪口上跳确实减小了，但耳膜被横向冲击波震得嗡嗡作响的快乐翻了一倍。",
        en = "Ported muzzle slots venting hot expanding propellant upwards to tame climb; your sight picture stays flat while sideways concussive blasts double the ringing in your ears.",
    },
    ["compgreatbow"] = {
        zh = "庞大如床弩的变态重型巨弓，寻常人连弓弦都拉不动分毫；只有注射了过多变异血清的非人壮汉，才配用它把整根铁矛当弓箭射穿卡车。",
        en = "An enormous monstrous greatbow resembling a portable ballista; ordinary humans cannot budge the string, reserving it for mutated juggernauts firing rebar spears through engine blocks.",
    },
    ["compositebow"] = {
        zh = "用动物角、木料与牛筋在鱼鳔胶浸泡下古法压制而成的重弓，磅数惊人；在潮湿的酸雨天里使用前必须祈祷，免得开弓时胶水受潮当场解体。",
        en = "An ancient laminated recurve of horn, sinew, and fish glue; hits like a truck until humid acid rains dissolve the animal adhesive and detonate the limbs into splinters.",
    },
    ["compositecrossbow"] = {
        zh = "结合了传统木骨角材工艺的古典重弩，击发时震颤浑厚；结构虽不如现代滑轮花哨，但在没有备用滑轮轴承的末日废土上，它能一直用到下辈子。",
        en = "A traditional crossbow crafted from seasoned timber, horn, and sinew; lacking delicate modern pulleys means fewer moving parts to snap while hunting through shattered ghost towns.",
    },
    ["compressor"] = {
        zh = "从废弃冰箱或空调外机里拆下来的金属密封压缩机，沉重得像块秤砣；通电时发出轰隆隆的喘息声，让人分不清它是在压缩冷媒还是在向死神哀鸣。",
        en = "A sealed electric hermetic pump salvaged from roadside refrigerators; humming like an asthmatic diesel engine, compressing coolant while rattling hard enough to walk across the workshop bench.",
    },
    ["computer_science"] = {
        zh = "厚达上千页的计算机科学中阶教科书，详细讲解了算法复杂度与数据结构；在电力网络彻底瘫痪的废土上，二叉树平衡算法能帮你的营火稳定燃烧。",
        en = "An advanced college textbook analyzing algorithm complexity and memory management; with the power grid utterly dead, binary search trees make exceptionally reliable kindling.",
    },
    ["con_milk"] = {
        zh = "浓稠发黄的高糖浓缩奶，甜得足以糊住嗓子；在缺乏冷藏的废土上，这罐哪怕放上十年也不会变质的甜腻能量炸弹，是求生路上最昂贵的慰藉。",
        en = "Sticky, hyper-sweetened condensed cow's milk that coats your tongue like syrup; an indestructible shelf-stable calorie bomb that survives decades after fresh dairy vanished forever.",
    },
    ["con_mix_foldable"] = {
        zh = "可以折叠轮式拖运的小型电动水泥搅拌机，滚筒旋转时发出震耳欲聋的金属轰鸣；只要沙石水泥管够，它就能在尸潮围城前帮你筑起最后一面护墙。",
        en = "A portable steel drum mixer rumbling like an earthquake when filled with gravel; deafening everyone nearby while spinning out the reinforced mortar needed to barricade the safehouse.",
    },
    ["conc_paralytic"] = {
        zh = "从变异三尖树浆液里提取的高纯度麻痹原液，散发着甜腻的枯叶气味；只要擦在箭头上划破一点油皮，再狂暴的变异巨兽也会瞬间僵硬得像块木雕。",
        en = "Pure paralytic distillate milked from thrashing triffid fronds; a single scratch delivered by a coated broadhead turns charging abominations into rigid lawn ornaments within seconds.",
    },
    ["conc_venom"] = {
        zh = "收集了无数变异蜂刺浓缩提炼出的浅绿色剧毒液体，腐蚀性极强；在涂抹武器时双手千万不要发抖，因为解毒剂早已随着现代文明一起绝迹了。",
        en = "A luminescent greenish vial of hyper-concentrated wasp venom; handle with steady fingers when tipping dart tips, because antivenom vanished along with the rest of civilization.",
    },
    ["concrete"] = {
        zh = "干水泥粉与沙石的粗糙混合物，加水就能变成坚不可摧的避难所掩体，或者在你搅拌动作太慢时变成一个彻底报废的塑料桶。",
        en = "A coarse gray mixture of cement powder and aggregate; add water to construct an impenetrable bunker, or wait too long and ruin your only bucket.",
    },
    ["concrete_book"] = {
        zh = "介绍了如何浇筑掩体与工事的建筑学专著；在满是狂暴怪物的废土上，真正的浪漫不是鲜花，而是八十厘米厚的钢筋混凝土防爆墙。",
        en = "An authoritative engineering manual on structural aggregate; in a ruined world crawling with abominations, true romance is an eighty-centimeter thick reinforced blast wall.",
    },
    ["concrete_mix_tool"] = {
        zh = "一台装有倾斜旋转滚筒的电动混凝土搅拌机。只要倒入沙子、碎石和水泥并启动电机，几分钟内就能搅拌出一大桶修补防御工事与封死地下室大门的坚固砂浆。",
        en = "A motorized drum concrete mixer built for heavy masonry duty. Blending sand, aggregate, and cement in minutes, it churns out high-strength mortar to seal off breached perimeter defenses.",
    },
    ["condenser_pristine"] = {
        zh = "崭新得连散热片都没弯折的精密冷凝器；在到处是锈蚀废铁的末日里，它干净得让人忍不住想把它拆成铜管换取几罐炖肉罐头。",
        en = "A flawless condenser unit without a single bent aluminum fin; so suspiciously immaculate amidst the apocalyptic rust that scavengers want to strip it for copper.",
    },
    ["condensor_coil"] = {
        zh = "弯弯曲曲的铜制冷凝盘管；除了用来修好一台嗡嗡作响的冰箱，在有追求的私酿酒大师手里，它是蒸馏高纯度伏特加的灵魂圣物。",
        en = "Serpentine loops of heat-exchanging copper tubing; useful for repairing a refrigerator, though prized far more passionately by moonshiners condensing seventy-proof survival spirits.",
    },
    ["condiment_bottle_sealed"] = {
        zh = "密封良好的倒立式挤压酱料瓶；不管外面的世界崩塌成什么样，里面的黄芥末酱依然保持着工业文明最后的强烈辛辣与刺激酸味。",
        en = "An airtight inverted squeeze bottle; no matter how thoroughly civilization crumbled outside, the yellow mustard inside preserves the pungent, acidic bite of late-stage industrialism.",
    },
    ["condom"] = {
        zh = "包装上印着安全至上的乳胶套；在灾变世界里，它最尊贵的使命其实是充当能装下一升净水且绝对防水耐磨的超弹性便携水囊。",
        en = "The gentleman's single-use latex balloon; in the post-apocalyptic wilderness, its noble destiny is serving as an emergency, ultra-stretchy one-liter waterproof canteen.",
    },
    ["condom_sealed"] = {
        zh = "尚未撕开铝箔包装的避孕套；在生死逃亡的废土上，保持它干燥密封的最大意义，是下雨天套在枪口上防止泥沙和雨水堵塞枪管。",
        en = "A pristine foil packet; the primary survivalist reason to keep it dry and sealed is slipping it over your rifle muzzle to keep mud out.",
    },
    ["confit_meat"] = {
        zh = "浸泡在厚重凝固白油里的古法油封肉；只要你不嫌弃舀出来时满手猪油，这坨高热量脂肪块能在地窖深处静静等你十年而不变质。",
        en = "Salted cuts submerged in cold solidified lard; grease-coated fingers are a minor price to pay for dense calories that slumber safely in cellars for decades.",
    },
    ["connect_four"] = {
        zh = "蓝黄两色塑料圆片的立式连珠棋；在没有电子游戏的漫长避难所长夜里，它是少数能让两个全副武装的幸存者吵到拔枪的桌面游戏。",
        en = "A vertical grid with colored plastic tokens; during long candle-lit bunker nights without electricity, this simple game reliably drives heavily armed companions to gunpoint.",
    },
    ["cookbook"] = {
        zh = "教你如何用临期罐头和边角料做饭的省钱食谱；作者大概做梦也想不到，读者有朝一日真的要靠书里的省钱妙招煮变异蟑螂骨头汤。",
        en = "A budget cooking guide utilizing pantry scraps and leftovers; the author never anticipated readers taking their thrift tips literally to boil roasted mutant roach broth.",
    },
    ["cookbook_bloodforgood"] = {
        zh = "倡导将血液作为日常营养膳食来源的奇葩食谱《为了更大的善：血之盛宴》。书里记载了各种血豆腐、血肠与血汤的烹饪秘方，在肉食匮乏的废土上倒成了救命指南。",
        en = "A macabre culinary volume advocating animal and human blood as prime nutritional fuel. Detailing black pudding, blood tofu, and curd stews, it becomes surprisingly practical during famine.",
    },
    ["cookbook_curry"] = {
        zh = "一本详细介绍数十种辛香咖喱配方的美食谱《咖喱之书》。无论你往炖锅里扔的是变异老鼠肉、变质罐头还是野草根，只要加入两勺浓烈咖喱粉，出锅时都是一顿人间美味。",
        en = "A colorful culinary guide celebrating the glory of spiced curries. Smothering mystery rodent morsels and wild roots in pungent turmeric and cumin effortlessly masks even the gamest flavors.",
    },
    ["cookbook_daintydishes"] = {
        zh = "汇集了旧时代欧洲宫廷繁复精巧甜品与名贵烤肉的奢华食谱《君王之宴》。看着配料表里动辄需要的松露、藏红花与顶级鹅肝，坐在破避难所里啃生冷野菜的你忍不住翻白眼。",
        en = "A lavish royal cookbook filled with elaborate banqueting dishes, truffles, and saffron pastries. Reading its aristocratic ingredient lists while choking on boiled dandelion roots is darkly hilarious.",
    },
    ["cookbook_eatyrway"] = {
        zh = "由所谓的国际养生大师撰写的健康轻食塑形食谱《吃出健美体魄》。书里一本正经教人严格计算卡路里摄入以避免肥胖，而废土上的幸存者巴不得一天能摄入一万大卡脂肪。",
        en = "A trendy pre-collapse diet book preaching strict caloric deficits and low-carb bowls to avoid muffin tops. Starving wanderers would cheerfully trade their souls for an extra ten thousand calories.",
    },
    ["cookbook_foodfashions"] = {
        zh = "战前大都市时髦青年推崇的前卫分子料理食谱《年轻现代人的美食风尚》。书里教人如何把菠菜汁做成泡沫、把牛肉做成胶囊，对于急需大口嚼实心纯肉的流浪汉来说纯属脱裤子放屁。",
        en = "A pretentious culinary trend book advocating liquid nitrogen spheres, foams, and molecular gastronomy. To an exhausted scavenger desperate to chew solid meat, edible foam feels like an insult.",
    },
    ["cookbook_human"] = {
        zh = "著名的经典黑色幽默食谱《如何做人》；翻开之前你以为是心灵鸡汤，翻开之后才发现目录第一章赫然写着两百磅灵长类全身剔骨指南。",
        en = "The infamous pulp classic titled To Serve Man; disguised as uplifting self-help until page three reveals a butcher diagram for a two-hundred-pound primate.",
    },
    ["cookbook_indian"] = {
        zh = "一本厚重大气、将印度地理文史与传统香料烹饪深度融合的精装食谱《品味印度》。通读全书不仅能掌握如何用小茴香和豆蔻激发食欲，还能让人从精神层面体验南亚大陆的风土人情。",
        en = "A magnificent hardcover exploring regional Indian cuisine and fragrant spice markets. Masterfully detailing cardamom, clove, and fenugreek combinations, it turns bland foraged tubers into exotic feasts.",
    },
    ["cookbook_italian"] = {
        zh = "满篇都是精美彩图的意大利经典菜谱；可惜在连面粉都要配给的末日里，对着热气腾腾的披萨图片流口水是它能提供的唯一精神营养。",
        en = "Glossy color photos detailing authentic pasta and pizza recipes; in an era where grain is strictly rationed, drooling over the pictures provides zero edible calories.",
    },
    ["cookbook_liverforkids"] = {
        zh = "试图通过花哨造型哄骗挑食儿童多吃猪肝牛肝的奇葩食谱《孩子们爱吃的肝脏盛宴》。在满地都是重度贫血与营养不良患者的废土上，根本不需要哄，生肝脏一出锅就被瞬间抢光。",
        en = "A well-meaning family cookbook disguising organ meats as colorful cartoon animal shapes for picky toddlers. In a starving apocalypse, no deception is needed to make survivors ravenously inhale liver.",
    },
    ["cookbook_mexican"] = {
        zh = "充满热情色彩的墨西哥传统料理全书；即使文明毁灭了，只要你敢往变异野味排上狂撒哈拉佩纽辣椒，末日求生生活就依然火辣刺激。",
        en = "A vibrant celebration of Mexican street food and rich mole; reminding you that even after collapse, dumping pickled jalapeños on fried mutant steaks cures existential despair.",
    },
    ["cookbook_native"] = {
        zh = "苏族原住民传统美食与生存采集宝典；当工业供应链灰飞烟灭后，书里教你辨识的野草块茎与熏肉技术成了最不需要电池的救命粮典。",
        en = "A hardcover treasury of indigenous foraging and game preservation; when the global supply chain evaporated, gathering acorns and wild roots suddenly became the ultimate superpower.",
    },
    ["cookbook_sushi"] = {
        zh = "步骤详尽的手握寿司入门指南；在到处都是变异发光鱼的新英格兰废土，生食海鲜的唯一后果是你的胃也会跟着在黑夜里发出荧光。",
        en = "An easy-to-read guide for rolling nigiri and maki; unfortunately, eating raw irradiated river carp in New England will only cause your stomach to glow in the dark.",
    },
    ["cookbook_turkish"] = {
        zh = "极尽奢华的土耳其烤肉与香料烹饪手册；在如今只能啃压缩饼干的废土上，多看两眼烤羊肉串的诱人插图都算是一种极其残忍的精神折磨。",
        en = "An opulent handbook of spiced kebabs and savory flatbreads; flipping through smoking lamb illustrations while choking down hardtack crackers borders on voluntary psychological torture.",
    },
    ["cookbook_useless"] = {
        zh = "一本内容平庸至极、充斥着煎蛋卷和番茄汤基础做法的粗糙泛用菜谱。书里介绍的家常菜即便没读过书的人闭着眼睛也能做出来，唯一的作用是撕下来垫在油腻的砧板底下。",
        en = "A painfully generic cookbook reciting basic instructions for boiled potatoes and scrambled eggs. Offering zero culinary revelations, its grease-stained pages serve far better as disposable campfire napkins.",
    },
    ["cooked_bell_pepper"] = {
        zh = "在铁板上煎烤至表皮微焦发皱的美味红甜椒。去除了生涩的蒂把与辣椒籽后，浓缩的天然糖分在炭火烘烤下散发出甘甜多汁的风味，是补充维生素C的无上极品蔬菜。",
        en = "A roasted sweet bell pepper cored and cooked over coals until tender. Concentrating its natural fructose while shedding bitter green notes, its succulent flesh delivers a welcome burst of vitamin C.",
    },
    ["cooked_burdock_stalk"] = {
        zh = "剥去坚硬外皮后切段在沸水里煮透的野生牛蒡嫩茎。口感清脆略带一丝植物特有的甘苦，虽然热量不高，但丰富的膳食纤维能有效唤醒你早已被生肉干折磨得麻木的肠胃。",
        en = "A peeled burdock stalk boiled in salted water until crisp-tender. Imparting an earthy, mildly bitter mineral crunch, it provides vital dietary fiber when survival rations cause intestinal gridlock.",
    },
    ["cooked_cattail_stalk"] = {
        zh = "从湿地泥塘拔出洗净后下锅焯水煮熟的香蒲嫩茎白芯。咬下去口感如同多汁鲜嫩的春笋，甘甜清爽且极易消化，是湿地沼泽探险途中最可靠、最绿色的生存能量源泉。",
        en = "The tender white heart of a marsh cattail stalk boiled over open embers. Resembling sweet, watery bamboo shoots, it represents the most reliable and abundant green carbohydrate in wet biomes.",
    },
    ["cooked_cured_meat"] = {
        zh = "用清水浸泡洗去多余粗盐后在滚水里焖熟的优质腌肉。肥瘦相间的肉块散发着迷人的咸香与烟熏风味，每一口咀嚼都能带来纯粹扎实的高蛋白能量补充，耐饥抗饿。",
        en = "A thick slab of salted cured meat thoroughly rinsed and simmered until fork-tender. Bursting with savory smoky juices, each dense mouthful delivers dense protein reserves for grueling travel.",
    },
    ["cooked_dinner"] = {
        zh = "刚刚用篝火加热完毕的双拼快餐拼盘；虽然钠含量超标到足以让心脏骤停，但在暴风雪的寒冷夜晚里，热气腾腾的肉汁比黄金还要暖胃。",
        en = "A reheated partitioned tray of gravy-soaked meatloaf and mashed starch; boasting enough sodium to stop an elephant's heart, yet comforting beyond measure in freezing blizzards.",
    },
    ["cooked_elderberries"] = {
        zh = "经彻底煮透的接骨木浆果；高温破坏了浆果内天然的微量氰化物毒素，让你不必在补充维生素和痛苦口吐白沫之间做出残酷的人生抉择。",
        en = "A steaming bowl of thoroughly boiled elderberries; cooking neutralizes natural cyanogenic glycosides, sparing you the awful dilemma between scurvy prevention and violent stomach cramps.",
    },
    ["cooked_marrow"] = {
        zh = "用炭火烤得滋滋冒油的牛骨髓；虽然吃相极为野蛮甚至需要用木棍往外捅，但那口滚烫浓郁的骨脂足以瞬间治愈你的末日精神内耗。",
        en = "Sizzling rich bone marrow roasted over hot embers; scooping it out with a whittled stick looks barbaric, but liquid hot fat instantly cures existential gloom.",
    },
    ["cooked_pumpkin"] = {
        zh = "在铁锅里蒸熟捣碎并拌入少许油脂的香甜金黄南瓜泥。口感细腻绵密如奶油慕斯，温热的甜味在舌尖化开，不仅极易吞咽吸收，还能让受惊的心灵得到极大的抚慰。",
        en = "Steamed sweet pumpkin pulp mashed into a creamy golden puree. Melting smoothly across the tongue with comforting natural sweetness, it soothes strained digestion and elevates battered morale.",
    },
    ["cookies"] = {
        zh = "酥脆香甜的经典黄油曲奇；在这个充满绝望的世界里咬上一口，甜蜜的黄油香气能让你短暂忘记天花板上正倒挂着一只变异跳跃丧尸。",
        en = "Sweet, buttery cookies baked to golden perfection; a single sugary bite provides enough nostalgic bliss to make you temporarily ignore the undead scratching outside.",
    },
    ["cookies_egg"] = {
        zh = "被特意压成彩蛋形状的复活节糖霜饼干；虽然高糖甜得发腻，但包装上印着的卡通彩蛋兔，成了废土上罕见而珍贵的童年文明遗存。",
        en = "Egg-shaped novelty butter biscuits drenched in pastel frosting; an aggressively sweet relic of holidays past, promising a toothache alongside nostalgic childhood joy.",
    },
    ["cooking_oil"] = {
        zh = "金黄透亮的大桶压榨植物烹调油；无论是用来炸松脆的变异鼠肉，还是在柴油发电机缺油时充当紧急燃料灌进油箱，它都表现得同样出色。",
        en = "Golden yellow vegetable oil packaged in bulk jugs; equally magnificent whether crisping up breaded rodent cutlets or poured directly into a starving diesel generator.",
    },
    ["copbot_chassis"] = {
        zh = "被拆得只剩一副空壳的警用防暴机器人底盘；虽然失去了电击枪和那句烦人的公民止步广播，但这身加厚合金重甲依然坚固得令人安心。",
        en = "The hollow armored shell of a decommissioned police droid; silenced of its irritating halt-citizen warnings, but retaining bullet-resistant steel plates eager to be recycled.",
    },
    ["copper"] = {
        zh = "几块沉甸甸的纯铜废料与碎铜管；除了敲成粗糙的小刀或自制弹头，在这个重返以物易物的蛮荒时代里，它闪亮的红金属光泽本身就是硬通货。",
        en = "Scrap chunks and stripped plumbing pipes of pure copper; prized equally for hand-loading jacketed bullets or trading as glittering bartering currency among barter camps.",
    },
    ["copper_ax"] = {
        zh = "用纯铜硬生生锻打淬火出的原始短柄手斧；虽然砍几下硬木斧刃就会卷成波浪形，但好歹标志着你的幸存者科技正式跨出了旧石器时代。",
        en = "A primitive hand ax forged from beaten copper; the soft edge deforms against seasoned oak, but it proudly proclaims your graduation from the Stone Age.",
    },
    ["copper_bracelet"] = {
        zh = "带有古典花纹的粗笨纯铜手镯；尽管宣称能缓解关节疼痛是老旧骗局，但在徒手格挡强盗偷袭时，硬邦邦的金属手镯确实能保住你的手腕。",
        en = "A heavy burnished copper bangle; while its arthritic healing claims remain dubious pseudo-science, parrying a bandit's rusty switchblade with it proves genuinely therapeutic.",
    },
    ["copper_ear"] = {
        zh = "相当压耳垂的沉重铜质耳坠；戴着它在树林里潜行时只要稍微晃头，金属撞击声就能精准吸引方圆百米内所有丧尸敏锐的听觉关注。",
        en = "A hefty pair of dangling copper earrings; shaking your head while stalking through ruins produces a gentle metallic chiming that delight nearby feral predators.",
    },
    ["copper_hairpin"] = {
        zh = "一根纯铜打造的结实长发夹；不仅能在狂风中固定你蓬乱的幸存者长发，磨尖的一端还能在被怪物近身扑倒时充当极其顺手的应急刺针。",
        en = "A sturdy forged copper hairpin; keeping greasy survival locks out of your eyes during a sprint, while doubling as an improvised eye-gouging stylus in grappling range.",
    },
    ["copper_knife"] = {
        zh = "用废铜块手工敲打研磨出的简易小铜刀；虽然切硬肉时钝得像把黄油抹刀，但总比蹲在泥水里用打火石慢慢敲碎石片要体面得多。",
        en = "A crudely ground copper blade with a wrapped handle; dulling quickly against tough sinew, yet remarkably more civilized than knapping flint splinters in the rain.",
    },
    ["copper_locket"] = {
        zh = "表面覆满铜绿的古旧盒式吊坠，里面照片上微笑的面孔早已被霉菌蚀烂；在残酷的废土上，它最大的价值是倒出碎照片后藏进两粒救命抗生素。",
        en = "A green-patinated copper locket whose interior portrait was devoured by mildew; its ultimate survival utility is dumping the moldy photo to stash two emergency antibiotics.",
    },
    ["copper_necklace"] = {
        zh = "由简单铜环串起的朴素项链，戴在脖子上久了会在皮肤上留下一圈发青的铜锈；虽然毫无防护属性，但足以向其他流民宣称你不是空手出来的。",
        en = "A plain chain of linked copper rings leaving greenish oxide marks on your collarbone; offering zero armor, yet proving you raided somewhere wealthier than a dumpster.",
    },
    ["copper_pan"] = {
        zh = "内壁镀有光亮锡层的传统重型紫铜平底煎锅。导热极其均匀迅速，无论在野外煎变异鸟蛋还是香煎野猪肉排都能做到火候精准，遭遇偷袭时挥锅反击的击打感同样沉稳扎实。",
        en = "A heavy copper frying pan lined with a protective tin barrier. Conducting heat rapidly and evenly, it cooks delicate fillets to perfection while doubling as a brutal skull-denting melee bludgeon.",
    },
    ["copper_ring"] = {
        zh = "一枚黯淡无光的简陋铜戒指，廉价得连典当行都不会正眼瞧；戴在手指上除了让你显得像个落魄骑士，唯一的实际用处是融掉做几粒发射药底火。",
        en = "A dull, unpolished copper band once snubbed by pawn shops; wearing it lends vintage beggar charm, though melting it down into ammunition primers makes far more sense.",
    },
    ["copper_rod"] = {
        zh = "一根沉甸甸的实心细铜棒；既是拉丝制作电线的前置材料，也是你在工具箱打翻时顺手抄起来给扑脸丧尸脑袋开瓢的简易钝器。",
        en = "A solid, unyielding rod of ductile copper; slated for wire drawing on a workbench, yet instantly repurposed as an impromptu club when ghouls interrupt your tinkering.",
    },
    ["copper_wire"] = {
        zh = "剥去绝缘塑料皮的裸露铜导线，散发着微弱的金属腥味；只要接错一个接头，它就会用闪亮的电弧教你懂得什么叫废土电工的代价。",
        en = "A spool of naked conductive copper strand; wire it incorrectly into your vehicle rig and a blinding electrical arc will teach you the meaning of amateur electrician.",
    },
    ["coqauvin"] = {
        zh = "用红酒与香草慢炖出来的法式烩鸡，浓郁的酒香能让人瞬间热泪盈眶；即使鸡肉很可能来自你在野外抓到的变异秃头雉鸡，酱汁也掩盖了一切罪恶。",
        en = "A fragrant French chicken stew braised in rich wine; even if the poultry was a mangy mutant pheasant, the velvety burgundy sauce forgives every post-apocalyptic sin.",
    },
    ["cordage_36"] = {
        zh = "一根长约三英尺、用天然植物韧皮纤维紧密搓捻而成的粗绳段。结实耐磨且不易脱结，无论是捆扎大捆柴火、绑扎木筏还是制作简易弓弦，都是不可或缺的基础耗材。",
        en = "A three-foot length of rugged cordage twisted from natural plant fibers. Invaluable around camp, it binds firewood bundles, secures rain tarps, and provides cordage for makeshift survival bows.",
    },
    ["cordage_36_leather"] = {
        zh = "一根长达三英尺的坚固熟牛皮长皮绳。皮质柔韧且抗拉伸断裂强度极高，常用于修复重型铠甲的皮带搭扣、缠绕剑柄防滑吸汗，或者编织坚韧的高级捕兽网。",
        en = "A three-foot strand of supple rawhide lace boasting extreme tensile strength. Essential for replacing broken armor buckles, wrapping blade hilts for grip, and rigging heavy animal snares.",
    },
    ["cordage_6"] = {
        zh = "一小截六英寸长的天然植物麻绳短段。虽然长度有限干不了大工程，但用来绑牢松动的火把头、固定箭矢尾羽或者系紧口袋封口都表现得恰如其分、物尽其用。",
        en = "A modest six-inch snippet of twisted fibrous cord. Perfect for small utility tasks like securing arrow fletchings, tightening pocket pouches, and binding pine pitch torches to walking sticks.",
    },
    ["cordage_6_leather"] = {
        zh = "一根六英寸长的短小精致熟皮革系带。柔软而耐磨，经常被用来绑在随身匕首的刀鞘尾部当防掉手绳，或者在鞋带断裂时充当临时的应急连接皮筋。",
        en = "A short six-inch leather lace salvaged from discarded boots. Tough and pliable, it works splendidly as an impromptu knife lanyard or an emergency replacement lace for split hiking boots.",
    },
    ["corded_demolition_hammer"] = {
        zh = "通电时震动得能把人五脏六腑震移位的工业拆除锤；只要你有一台足够给力的发电机，整座小镇的钢筋水泥墙对你来说都不过是一块块嫩豆腐。",
        en = "A ferocious electric demolition hammer vibrating hard enough to loosen molars; backed by a beefy generator, brick masonry and concrete walls yield like warm butter.",
    },
    ["corded_powerdrill"] = {
        zh = "带有一根长电线的传统电动钻机；虽然被限制在电源插座方圆几米之内，但只要钻头开始旋转，没有任何丧尸的头盖骨能在它面前保持完整。",
        en = "A heavy black drill tethered to a wall cord; tethered close to generators, its relentless torque cores through hardwood, sheet metal, and undead skulls without hesitation.",
    },
    ["cordless_drill"] = {
        zh = "装有锂电池包的无线电钻，机械师在废土穿梭时的万能钥匙；唯一的问题是电池电量永远在你把防爆螺栓拧到一半时准时耗尽。",
        en = "A portable battery-driven drill serving as the universal skeleton key for wasteland mechanics; its battery pack invariably runs flat right as the final locking bolt loosens.",
    },
    ["cordless_impact_wrench"] = {
        zh = "能爆发出惊人扭矩的高频冲击扳手，伴随着刺耳的突突打铁声；即使是生锈三十年的卡车轮毂螺母，在它的疯狂敲击下也只能乖乖屈服。",
        en = "A cordless impact wrench delivering deafening hammer blows; rusted suspension bolts fused by decades of road grime either yield instantly or shear completely off.",
    },
    ["corkscrew"] = {
        zh = "小巧的螺旋开瓶钻；灾变前它是浪漫烛光晚餐的必备工具，如今它是你在酒窖深处砸开名贵葡萄酒软木塞时唯一能防止木屑掉进嘴里的救星。",
        en = "A pocket corkscrew engineered for extracting wine corks; a romantic luxury pre-collapse, now the sole tool preventing soggy wood shavings from contaminating vintage cellar scavenges.",
    },
    ["corn"] = {
        zh = "一整根颗粒饱满的金黄玉米棒；虽然嚼起来稍硬，但它不仅能直接下锅煮熟充饥，啃完剩下的玉米芯还能在厕纸绝迹的废土上充当历史悠久的替代品。",
        en = "A golden ear of dried corn; high in starch and satisfying to gnaw, while the stripped fibrous cob offers a time-honored, rustic substitute for toilet paper.",
    },
    ["corn_kernels"] = {
        zh = "从玉米棒上剥下来的一大捧硬玉米粒；扔进热油锅里能爆出一大盆爆米花，或者在绝望时充当简易霰弹枪弹药塞进弹壳里给敌人迎面痛击。",
        en = "A handful of hard golden kernels; pop them in scalding fat for movie snacks, or funnel them into empty shotgun hulls as improvised pepper-spray buckshot.",
    },
    ["corn_on_cob"] = {
        zh = "包裹在锡纸里在炭火中烤得焦香四溢的烤玉米；趁热咬下一大口，香甜的汁水和焦糖风味能让你暂时忘记自己正蹲在四面漏风的废墟营地里。",
        en = "An ear of sweet corn blistered to perfection inside aluminum foil; savory caramelized butter distracts you thoroughly from the freezing draft blowing through your barricaded cabin.",
    },
    ["cornbread"] = {
        zh = "金黄扎实的玉米面包，带着浓浓的谷物香甜与粗糙颗粒感；吃完两块不仅能填饱肚子，掉在盘子里的碎渣还能引来几只无害的废土麻雀。",
        en = "Dense, crumbly yellow cornbread baked with rustic grain; two heavy slices will anchor your gut for hours, while loose buttery crumbs make excellent songbird bait.",
    },
    ["corndogs_cooked"] = {
        zh = "油炸得金黄酥脆的玉米糊裹热狗肠，插在一根小木棍上；虽然满嘴都是防腐剂和人工香精的味道，但这根高热量油炸棒子能带来纯粹的快乐。",
        en = "A deep-fried batter-dipped hot dog impaled on a wooden skewer; dripping in industrial preservatives, yet delivering sheer nostalgic euphoria in a world devoid of funfairs.",
    },
    ["corndogs_frozen"] = {
        zh = "冻得硬如冰球棒的生玉米热狗；在解冻并放进油锅重新加热之前，你完全可以握着木棍把它当成一柄小号钝击冰柱敲碎丧尸的牙齿。",
        en = "A rock-hard frozen corn dog; until you thaw and fry it over grease, gripping the icy wooden stick gives you an excellent close-quarters tooth-loosening truncheon.",
    },
    ["corndogs_homemade"] = {
        zh = "用手揉玉米糊和搜刮来的自制香肠炸出来的手工热狗；外形虽然歪歪扭扭甚至炸裂了缝，但香脆的面皮证明了废土厨师的执着。",
        en = "A homemade corn dog cobbled from scavenged sausage and cornmeal batter; lumpy and split down the seam, yet proudly demonstrating that artisanal street food survives.",
    },
    ["cornmeal"] = {
        zh = "磨得粗细不一的金黄色玉米粉；只要有锅和水，就能煮成一大锅糊状的玉米粥，是在缺乏面粉时维系你生命体征的忠实伙伴。",
        en = "Coarse yellow stone-ground cornmeal; boil it with water and salt into a thick mush to stave off starvation when refined white flour is ancient history.",
    },
    ["corpse"] = {
        zh = "一具安详平躺的普通人类尸体；虽然现在看起来人畜无害，但每个老练幸存者路过时都会掏出撬棍或匕首给它狠狠补刀以绝后患。",
        en = "A motionless human body resting quietly on the floor; completely peaceful for now, which is why veteran wanderers instinctively draw combat knives to butcher it immediately.",
    },
    ["corpse_ash"] = {
        zh = "在熊熊烈火中彻底焚化后剩下的一捧灰烬；无论生前曾拥有多么显赫的财富或地位，在高温火焰的公平洗礼下，最终都化作了同样的无机白灰。",
        en = "A handful of fine gray bone and ash; proving that whether someone was a corporate CEO or a vagrant, high-temperature cremation equalizes everyone into fertilizer.",
    },
    ["corpse_bloody"] = {
        zh = "浑身浸透在凝固暗红血泊里的凄惨尸体；周围凌乱的抓痕和拖拽血迹无声地诉说着死者生前曾与某种嗜血怪物进行过多么惨烈的挣扎。",
        en = "A mangled corpse coated in sticky dark gore; surrounding claw gouges tell a grim tale of desperate hand-to-hand combat against whatever nightmare lurked in the hallway.",
    },
    ["corpse_child_calm"] = {
        zh = "面容异常平静的孩子尸体，仿佛只是在梦乡中沉睡；在末日世界的残酷阴影下，这种宁静的安息往往比任何挣扎求生更让人心生酸楚。",
        en = "The motionless body of a child bearing a peaceful, slumbering expression; in a ruined world defined by violence, such quiet stillness is heartbreakingly heavy to behold.",
    },
    ["corpse_child_gunned"] = {
        zh = "一具布满密集枪眼弹孔的小孩尸体。生前显然遭遇了无差别的大口径自动武器残酷扫射，惨不忍睹的创口在寂静的废墟角落里无声控诉着末日降临时的野蛮与灭绝人性。",
        en = "The tragic remains of a child riddled by indiscriminate automatic rifle fire. The horrifying spectacle stands as an agonizing monument to the senseless brutality that accompanied the collapse.",
    },
    ["corpse_dermatik_victim"] = {
        zh = "一具面容定格在极度扭曲痛苦尖叫中的怪异尸体。皮肤下密布着被寄生幼虫啃噬钻透的恶心孔洞，任何看到这一幕的幸存者都会下意识抓紧手里的火焰喷射器瑟瑟发抖。",
        en = "A corpse frozen in an eternal, silent shriek of unimaginable agony. Riddled with burrowing exit tunnels left by parasitic dermatik larvae, the sight makes wanderers grip flame weapons tightly.",
    },
    ["corpse_generic_boy"] = {
        zh = "一个男孩的冰冷遗体，口袋里还塞着几颗彩色玻璃弹珠；大灾变从不区分年龄与无辜，它只是冷酷无情地将所有人一视同仁地拖入深渊。",
        en = "The lifeless remains of a young boy with glass marbles in his coat; the Cataclysm made no distinction between innocence and age, dragging everyone down equally.",
    },
    ["corpse_generic_female"] = {
        zh = "一具年轻女性的尸体，衣物上还残留着办公室制服的痕迹；她可能还没来得及请假，整个现代社会的早九晚五制度就随着丧尸潮一起报销了。",
        en = "A young woman's corpse still clad in office attire; she never had to submit that resignation letter, because civilization dissolved into riots first.",
    },
    ["corpse_generic_girl"] = {
        zh = "一名小女孩的瘦小遗体，书包散落在一旁；无论你心肠多么坚硬，在废土上看到这样的景象，都足以让手中的武器沉重得让人握不住。",
        en = "The small body of a young girl with an abandoned backpack nearby; even the most callous scavenger feels a lump in their throat looking at this site.",
    },
    ["corpse_generic_gunned"] = {
        zh = "额头正中留有一个触目惊心大弹孔的成年人死尸。后脑勺的大面积空腔表明死者遭遇了近距离行刑式处决，身上的物资早已被洗劫一空，只剩苍白空洞的眼眶望着阴沉天空。",
        en = "A human body bearing a fatal bullet hole squarely between the eyebrows. Executed at close range and stripped of possessions, the blank glassy eyes stare upward at an indifferent gray sky.",
    },
    ["corpse_generic_human"] = {
        zh = "一具失去生机的人类遗骸，在风雨侵蚀下渐渐干瘪；它是大灾变夺走数十亿生命的微小缩影，也是废土上随处可见的最寻常背景板。",
        en = "A nameless human corpse slowly withering under rain and wind; a silent statistical fraction of billions lost, and the single most ubiquitous scenery in the post-apocalypse.",
    },
    ["corpse_generic_infected"] = {
        zh = "一具手臂和颈部留有发黑撕裂齿痕的感染者尸体。伤口周围布满暗紫色脉管状坏死纹理，黑色的黏稠毒血早已凝固，随时都有可能在新一波黑潮激发下突然诈尸复活。",
        en = "A human corpse marked by jagged, blackened human bite wounds across the throat. Veins radiating necrotic purple lines warn that without rapid decapitation or cremation, it will rise again.",
    },
    ["corpse_generic_male"] = {
        zh = "一名中年男子的尸体，粗糙的手掌表明他生前可能是个蓝领技工；他没能熬过第一波尸潮，但他的工具包或许能让下一位幸存者多活两天。",
        en = "The remains of a calloused middle-aged tradesman; he failed to survive the initial outbreak, but his leftover tool pouch might grant the next scavenger two more days.",
    },
    ["corpse_gunned"] = {
        zh = "额头上留着清晰弹孔的死者，伤口边缘焦黑；显而易见，夺走他性命的并不是变异感染体，而是末日里更可怕、更贪婪的同类幸存者。",
        en = "A corpse bearing a charred bullet entrance in the forehead; indisputable evidence that the deadliest predator in the apocalypse was never the undead, but fellow survivors.",
    },
    ["corpse_half_beheaded"] = {
        zh = "颈部被某种极其暴力的利器或巨颚切开一半的残躯；从断口处撕裂的肌肉组织来看，行凶者当时大概根本没有停下来欣赏作品的耐心。",
        en = "A half-decapitated corpse with torn cervical sinews; judging by the jagged fracture, whatever claw or blade severed this neck did not linger for surgical precision.",
    },
    ["corpse_halved_upper"] = {
        zh = "只剩下半截的上半身残躯，断裂的脊柱刺穿皮肉；如果是变异巨怪干的，那它扔垃圾的力道显然比市政环卫工人的压缩垃圾车还要粗暴。",
        en = "A severed torso torn clean at the waist with fractured vertebrae exposed; whatever monster discarded this half clearly possessed more brute horsepower than an industrial trash compactor.",
    },
    ["corpse_oldwoman_jewelry"] = {
        zh = "一位老妇人的遗体，耳垂被撕裂，手指上的戒指被粗暴捋走；即便世界已经毁灭，某些土匪流氓抢劫死者的下贱勾当依然保持着极高的执行力。",
        en = "An elderly woman with torn earlobes and stripped fingers; proof that even after total societal collapse, petty looters maintained stellar efficiency at robbing the defenseless dead.",
    },
    ["corpse_painful"] = {
        zh = "面部定格在极度痛苦扭曲表情下的死者，十指深深抓入泥土；在没有麻醉剂的末世里，很多死亡过程漫长且残忍得让人不忍卒读。",
        en = "A corpse frozen in a grotesque agonizing grimace with fingers clawed into frozen soil; dying without painkillers in the ruins is an excruciatingly drawn-out affair.",
    },
    ["corpse_scorched"] = {
        zh = "被高温烈焰烧得面目全非的焦黑肉块，散发着令人作呕的碳化焦臭；无论生前是谁，现在都不过是一具被火焰喷射器或汽油弹烤焦的碳化雕像。",
        en = "A blackened charred mass reeking of incinerated meat; whether caught in a flamethrower mishap or a molotov crossfire, fire made this poor soul completely unidentifiable.",
    },
    ["corpse_stabbed"] = {
        zh = "后背插着一把致命深刺凶器的成年人遗体。致命伤从后心直贯而入，显然是遭遇了最亲近之人的卑鄙背叛，在这毫无道德约束的废土上，后背永远是最危险的暴露面孔。",
        en = "A slain traveler with a gaping puncture wound penetrating straight through the spine. Slain from behind by treacherous companions, it serves as a bloody reminder to never turn your back.",
    },
    ["corpse_void_mummified"] = {
        zh = "皮肤呈现出蜡样光泽的干瘪古怪木乃伊尸体；被某种来自虚空维度的不可知能量抽干了所有水分与生命，连腐败细菌都对它敬而远之。",
        en = "A waxen mummified corpse desiccated by unearthly extra-dimensional energy; so thoroughly drained of moisture and vitality that even rot-inducing bacteria refuse to touch it.",
    },
    ["corpse_yugg_jade"] = {
        zh = "用整块温润深绿玉石精心雕琢而成的尤格巨噬虫神像；雕刻它的邪教徒大概做梦也没想到，在末日废土上，昂贵的玉雕还不如一罐午餐肉值钱。",
        en = "A yugg effigy sculpted meticulously from deep green nephrite jade; the subterranean cultist who carved it never imagined jade would trade lower than canned spam.",
    },
    ["corpse_yugg_mutflesh"] = {
        zh = "一段泛着诡异浅绿微光的巨型肉质软管，触感黏滑恶心；即便已经脱离母体多日，某些神经节依然会偶尔神经质般蠕动一下抗议你的注视。",
        en = "A massive slimy tube of pale-green alien flesh; despite being severed for days, localized ganglia still twitch spasmodically whenever you stare too closely.",
    },
    ["corpse_yugg_rubber"] = {
        zh = "由黑色半凝固橡胶状物质构成的巨型虫尸中空管道；质地坚韧耐腐，如果不是散发着刺鼻的深渊腥臭，洗干净甚至能当成优秀的下水道排水管。",
        en = "A hollow rubbery yugg carcass resisting rot like vulcanized vulcanite; wash away the subterranean slime and it would make an outstanding, acid-resistant drainage conduit.",
    },
    ["corset"] = {
        zh = "紧绷服帖的纯黑皮质束身衣；虽然勒得你几乎喘不上气，也没有任何一个口袋装弹夹，但至少在被丧尸撕碎前，你的身段依然保持着火辣。",
        en = "A snug black leather corset lacking utility pockets and crushing your ribs; sacrificing breathability and tactical capacity purely to ensure you look fashionable while being devoured.",
    },
    ["corset_loose"] = {
        zh = "一件带有金属排扣与绑带的宽松款黑皮革束身胸衣。虽然由于缺乏内部硬质龙骨而无法提供多少防刺护甲值，但穿上它在废土营地走上一圈，回头率绝对高达百分之百。",
        en = "A supple black leather corset featuring decorative steel eyelets and loose lacing. Lacking rigid whalebone stays for real ballistic defense, it nonetheless turns heads across dingy frontier trading posts.",
    },
    ["corset_waist"] = {
        zh = "一条用厚皮革与金属骨架撑起的黑色紧身束腰；不仅能强行塑造纤细腰线，被丧尸用拳头砸在腹部时，坚硬的金属撑条还能充当防暴护甲。",
        en = "A rigid leather waist cincher reinforced with steel boning; aggressively shaping posture while accidentally serving as hard armor against stray ghoul punches to the kidneys.",
    },
    ["corset_waist_loose"] = {
        zh = "采用软牛皮缝制的一件宽松款护腰皮束腰。不仅能在长途跋涉时为腰椎核心肌肉提供轻微的支撑缓冲，搭配粗犷的战术裤更显利落，是废土时尚达人的点睛之笔。",
        en = "A stylish waist cincher crafted from pliable dark leather. Providing modest lumbar support during long backpacking hauls, it injects unmistakable post-apocalyptic swagger into tactical utility wear.",
    },
    ["cot"] = {
        zh = "军用折叠行军床，帆布绷得紧邦邦的；虽然睡在上面翻个身就会发出嘎吱嘎吱的尖叫，但总比直接躺在潮湿冰冷且满是跳蚤的水泥地板上强。",
        en = "A folding military canvas cot squeaking rhythmically with every breath; horribly spartan, yet vastly superior to waking up on wet concrete crawling with irradiated ticks.",
    },
    ["cottage_cheese"] = {
        zh = "由凝乳和乳清滤沥出来的白色新鲜茅屋奶酪，口感微酸微咸；在没有防腐剂的情况下它容易发酸，提醒你尽快在它变质成毒药前吞进肚里。",
        en = "Crumbly curds and whey drained without aging; mildly salted and pleasantly sour, but spoiling fast enough to demand consumption before it turns into biological warfare.",
    },
    ["cottage_cheese_with_fruit"] = {
        zh = "拌入了新鲜野果的茅屋奶酪，酸甜爽口；在被尸潮围困在阁楼上的暗淡清晨，这碗充满小资情调的早餐能让你产生文明尚未毁灭的奇妙幻觉。",
        en = "Cottage cheese tossed with sweetened wild berries; enjoying this delicate breakfast while barricaded in an attic creates a temporary, dangerous hallucination that society never fell.",
    },
    ["cottage_cheese_with_savory_veg"] = {
        zh = "拌入了黄瓜丁与黑胡椒的咸味蔬菜奶酪；口感清脆爽口，是废土素食主义者在没有新鲜肉排时安慰自己味蕾的最健康选择。",
        en = "Salted curds mixed with diced wild greens and black pepper; crisp and refreshing, giving vegan wastelanders a respectable calcium boost without butchering sewer rodents.",
    },
    ["cotton_ball"] = {
        zh = "一小堆雪白蓬松的脱脂棉球；不仅能浸泡酒精给受感染的伤口清创，在晚上睡在呼啸狂风的破窗旁时，塞进耳孔里还能充当绝佳的隔音耳塞。",
        en = "Fluffy clumps of sterile white cotton; soak them in moonshine to cleanse necrotic gashes, or stuff them in ears to muffle blizzard winds howling through broken windows.",
    },
    ["cotton_boll"] = {
        zh = "刚从棉株上采摘下来的坚硬干燥棉桃；剥开外壳需要费不少指甲功夫，但里面藏着的致密天然棉纤维，是手工纺线编织衣服的核心原料。",
        en = "A tough woody capsule packed with tangled fibers and seeds; peeling it destroys your fingernails, but raw cotton remains the beating heart of wasteland tailoring.",
    },
    ["cotton_patchwork"] = {
        zh = "一块六英寸见方的方形纯棉布片；无论你的夹克被丧尸撕开了多大的口子，只要掏出针线缝上这块补丁，它就能继续陪伴你征战废土。",
        en = "A six-inch square swatch of sturdy woven cotton; regardless of how badly zombie claws shredded your field jacket, this humble patch will keep the insulation inside.",
    },
    ["cottonwood_tree_boll"] = {
        zh = "白杨树随风飘落的飞絮种包；虽然看起来和真正的棉花一样白花花一团，但纤维过短完全无法纺线，只能收集起来充当营火的速燃引火物。",
        en = "Airborne tufts of fluffy cottonwood seed lint; resembling true cotton yet far too brittle to spin into thread, settling for a humble career as instant tinder.",
    },
    ["counterweight"] = {
        zh = "一块重达数十磅的规整配重钢块；除了用来平衡机械臂或起重机吊臂，在遭遇破门而入的暴徒时，从二楼阳台垂直扔下去效果拔群。",
        en = "A dense rectangular ingot of structural counterweight steel; designed for balancing heavy cranes, yet delightfully effective when dropped from second-story balconies onto trespassing looters.",
    },
    ["counterweight_pouch"] = {
        zh = "挂在战术头盔后脑勺上的配重配重袋；用来平衡前方夜视仪造成的脖子前倾酸痛，代价是让你的整个脑袋沉得像套了一颗实心保龄球。",
        en = "A counterweight pouch strapped behind night vision goggles; sparing your neck muscles from forward tipping, while transforming your entire skull into a ten-pound bowling ball.",
    },
    ["cow_bell"] = {
        zh = "挂在牛脖子上的铁制大牛铃；走路时发出当啷当啷的宏亮铜声，在这个到处是听觉敏锐丧尸的世界里，给同伴挂上它基本等同于谋杀。",
        en = "A resonant iron bell designed for grazing livestock; walking with it clanking on your hip in a zombie-infested city is essentially premeditated assisted suicide.",
    },
    ["cow_candy"] = {
        zh = "被压成小奶牛造型的黑白巧克力夹心糖；小巧可爱且含糖量惊人，在逃亡路上嚼上一颗，仿佛童年的和平牧场从未经历过生化灾变。",
        en = "A handful of chocolate confections molded into adorable bovines; highly concentrated sucrose nuggets that allow you to pretend pastoral farms still exist without brain-eating parasites.",
    },
    ["cowboy_hat"] = {
        zh = "宽大挺括的经典深褐色牛仔帽；不仅能遮挡刺眼的艳阳和淅淅沥沥的酸雨，戴上它走到酒馆废墟门口，谁都得先看你三分薄面。",
        en = "A wide-brimmed felt cowboy stetson; deflecting scorching sun and drizzling acid rain alike, while demanding immediate outlaw respect when kicking open ruined saloon doors.",
    },
    ["cowl_wool"] = {
        zh = "厚实暖和的粗针织羊毛兜帽；在零下二十度的严寒风雪天里套在脖子和下巴上，能有效防止你的鼻尖在严酷的废土寒风中当场冻伤脱落。",
        en = "A bulky, soft-knitted wool cowl; bundling your throat and lower jaw against sub-zero blizzards, preventing your nose from snapping off in howling winter gales.",
    },
    ["cowrie_bracelet"] = {
        zh = "用光洁子安贝壳串成的手镯；在古老文明中曾被当成珍贵货币，如今在金钱贬值的废土上，某些眼光独到的幸存者部落再次承认了它的价值。",
        en = "A bracelet strung with polished cowrie seashells; prized as ancient currency centuries ago, and unexpectedly respected once paper banknotes became worthless campfire kindling.",
    },
    ["cowrie_hair_beads"] = {
        zh = "用贝壳串成的精致发珠，在旧时代是波西米亚风格的象征；如今戴在头上穿过灌木丛时，只会像风铃一样叮当作响，提前为附近的丧尸引路。",
        en = "Charming shell hair beads once celebrated as trendy boho chic; now clinking noisily like wind chimes whenever you brush against bushes, politely alerting nearby undead hordes.",
    },
    ["cowrie_necklace"] = {
        zh = "一串在多个古老文明中曾被当作货币的贝壳项链；可惜现在的幸存者只认子弹和抗生素，除非你遇到沉迷人类学研究的变异穴居人。",
        en = "A cowrie shell necklace historically traded as currency across continents; useless now when traders only accept 9mm rounds, unless you barter with an anthropologically inclined troglobite.",
    },
    ["crab_cakes"] = {
        zh = "油炸至金黄酥脆的蟹肉饼，带着浓郁的大海鲜味；只要你别仔细思考这只螃蟹究竟是在核废料排放口还是在酸雨沼泽里长大的就好。",
        en = "Crispy deep-fried crab patties bursting with ocean savory aroma; perfectly appetizing so long as you ignore whether the crab matured near toxic runoff or mutagenic acid swamps.",
    },
    ["crabapple"] = {
        zh = "酸涩坚硬的野生小苹果，直接咬下去能酸得你五官挤成一团；如果舍不得做成果酱，它坚硬的果核至少能在弹弓里充当低配钢珠。",
        en = "Tart and unyielding wild crabapples capable of contorting your entire face upon the first bite; if not stewed into jam, they serve adequately as sling ammunition.",
    },
    ["crack"] = {
        zh = "高纯度结晶的违禁毒品，能提供几分钟狂乱的虚假全能感；代价是随后断崖式下跌的士气，以及让你在下雨天光着身子去单挑半身丧尸。",
        en = "Crystalline narcotics granting a few fleeting minutes of manic omnipotence, followed by a ruinous mood crash that tempts survivors to duel skeletal juggernauts completely buck naked.",
    },
    ["crackers"] = {
        zh = "干瘪易碎且毫无油水的薄脆咸饼干；咀嚼时发出的嘎吱声能穿透两个街区，吃完后还会把你嘴里仅存的最后一滴唾液彻底榨干。",
        en = "Brittle salted crackers that crunch loud enough to alert every lurker on the block, rapidly absorbing every remaining microgram of moisture from your parched mouth.",
    },
    ["cracklins"] = {
        zh = "炸得金黄膨化的酥脆猪油渣，富含极其夸张的热量；在严冬的地下避难所里嚼上一把，能让快要冻僵的肠胃重新感受到文明的温暖。",
        en = "Deep-fried crispy pork rinds packed with absurd caloric density; crunching a handful inside a freezing evac shelter makes frostbitten innards temporarily remember modern civilization.",
    },
    ["crackpipe"] = {
        zh = "一根带球形吹嘴的纤细玻璃吸管，残留着可疑的烧焦结晶；废土化学家发誓它其实是一根微型冷凝试管，但没人相信这种蹩脚的借口。",
        en = "A slender glass pipe with charred residue at the bowl; wasteland tinkerers vigorously claim it is an improvised micro-condenser, though no sensible scavenger buys the excuse.",
    },
    ["craft"] = {
        zh = "拖延症与突发灾难受害者的共同丰碑。它可能是一张半成品木椅或未完工的弓。工匠在敲下下一颗钉子前听到了门外的骨骼碎裂声，这项宏伟工程便永久冻结在了烂泥中。",
        en = "A tragic monument to survivor procrastination and sudden violent interruptions. The carpenter was halfway through assembling a bench or bow before a howling shriek outside caused an immediate evacuation, leaving this unidentifiable bundle of components frozen in perpetual incompletion.",
    },
    ["crafted_suppressor"] = {
        zh = "用废铁管和消音垫粗暴拼凑的土制消音器；虽然开火几枪后里面的垫片就会被打飞，但至少能保住你潜入枪械店时脆弱的耳膜。",
        en = "A crude suppressor fashioned from metal pipes and scrap rubber wipes; its baffles disintegrate after three rounds, yet it spares your fragile eardrums during midnight break-ins.",
    },
    ["cranberries"] = {
        zh = "一把酸涩发硬的野生蔓越莓，野生动物都嫌弃它的酸味；但对于天天啃生肉的幸存者来说，这是预防牙龈出血和坏血病的天然救命果。",
        en = "A handful of bitterly sour wild cranberries shunned by forest fauna; an invaluable post-cataclysm boon to keep scurvy from loosening your teeth on a diet of scorched meat.",
    },
    ["cranberry_juice"] = {
        zh = "用本地蔓越莓压榨出的暗红色酸汁，酸得能瞬间唤醒昏迷的队友；只要加进自酿劣质烈酒里，就能调配出一杯让士气暴涨的废土鸡尾酒。",
        en = "Tart crimson juice pressed from tart bog berries, sour enough to revive comatose allies; mixed with moonshine, it creates a wasteland cocktail capable of curing existential dread.",
    },
    ["crane_pseudo_item"] = {
        zh = "虚空屠宰吊架，一段不应该出现在现实背包里的引擎底层占位符；如果你能用它砸人，说明宇宙的代码裂缝已经比传送门风暴还要深邃了。",
        en = "A butchering hoist pseudo-item that has no business existing in physical inventory; wielding it suggests the fabric of reality has ruptured far beyond ordinary portal storms.",
    },
    ["crash_axe"] = {
        zh = "机载应急破拆斧，弧形刀刃能轻松劈碎客机舱门和安全玻璃；现在它最常见的工作，是在飞机残骸旁给那些系着安全带的丧尸乘客做安息仪式。",
        en = "A lightweight emergency axe designed to breach aircraft hulls; currently relegated to mercifully putting seatbelt-bound zombie passengers to permanent rest amidst smoking airplane wreckage.",
    },
    ["crater_bomb"] = {
        zh = "外星母舰遗留下的高能塑坑爆弹，原本用于重塑地表地形；请千万不要用打火机去试探它的引信，除非你渴望亲眼见证蘑菇云在鼻尖绽放。",
        en = "An alien terrain-shaping munition intended for rapid terraforming excavation; striking its detonation fuse with a lighter is the quickest known way to witness a localized stellar eruption.",
    },
    ["creamsoda"] = {
        zh = "充满香草甜香与细腻气泡的高糖汽水；在没有冷藏设备的末日盛夏，喝上一口温热甜腻的奶油汽水，连大脑都会被糖分刺激得短暂麻痹。",
        en = "Fizzy vanilla soda brimming with synthetic sweetness; chugging a lukewarm can under the scorching summer sun paralyzes your weary brain with intense sugar euphoria.",
    },
    ["credit_card"] = {
        zh = "一张印着旧世界银行标志的金边塑料信用卡。曾经象征着无限透支额度与奢靡消费，如今整个金融系统连同银行大楼都灰飞烟灭，它只能用来在门缝里滑动撬开生锈的弹簧锁舌。",
        en = "A gold-embossed magnetic credit card once granting unlimited borrowing power. With global financial architectures reduced to rubble, it performs noble second-career service shimming simple spring door latches.",
    },
    ["creepy_doll"] = {
        zh = "一个破烂但电池依然有电的恐怖会说话玩偶；只要你在黑暗的走廊里不小心踩到它，它就会发出凄厉的笑声，把整栋楼的丧尸全部招引过来。",
        en = "A battered talking doll with mysteriously immortal batteries; stepping on it inside a pitch-black corridor triggers an eerie giggle that summons every zombie in the district.",
    },
    ["crepe"] = {
        zh = "薄如蝉翼的法式传统可丽饼，散发着诱人的黄油与蛋奶香气；但在野外泥泞的篝火旁煎这玩意，稍有不慎就会被风吹得糊在你的防毒面具上。",
        en = "A paper-thin French crepe exuding buttery elegance; attempting to flip one over an open camp embers in high winds usually plasters the delicate pastry across your gas mask.",
    },
    ["crepe_plain"] = {
        zh = "没有涂抹任何果酱或巧克力的无馅料可丽饼；口感朴素得像嚼一块温热的细棉布，但只要能填饱肚子，幸存者绝不会挑剔法式甜点的尊严。",
        en = "A plain, unadorned crepe devoid of chocolate or fruit spreads; tasting like warm culinary cloth, yet no starving survivor debates Michelin standards while dodging rabid ferals.",
    },
    ["crispycran"] = {
        zh = "将蔓越莓酸汁与柠檬汽水混合调配出的清爽气泡饮品；酸甜的气泡在舌尖炸裂开来，足以抚平你刚刚被变异恶犬追赶了三条街的惊恐内心。",
        en = "A sparkling concoction of sour cranberry juice and fizzy lemon soda; popping bubbles across your tongue soothe raw nerves after being chased across three city blocks by hounds.",
    },
    ["crossbow"] = {
        zh = "一把纯手工削制的木质狩猎十字弓；威力虽然不足以穿透变异重装丧尸的硬皮，但其完美的静音射击能让你在夜间悄无声息地猎杀野兔。",
        en = "A handcrafted wooden crossbow lacking the kinetic punch to breach Kevlar zombie carapaces, yet firing quietly enough to harvest wandering swamp turkeys without waking slumbering hordes.",
    },
    ["crossbow_trap"] = {
        zh = "将上弦的十字弓与绊线连接组成的简易阵地陷阱；布设在避难所门口非常可靠，前提是你半夜梦游出去上厕所时千万别忘了它的具体坐标。",
        en = "A tripwire rigged to a cocked crossbow trigger; exceptionally dependable for perimeter defense, provided you do not absentmindedly stumble across your own wire during midnight bathroom emergencies.",
    },
    ["crowbar"] = {
        zh = "废土哲学中最无可争议的终极仲裁者。它既是一把能解决九成门锁故障的物理万能钥匙，也是一根无需装填弹药的头部重塑器。当你的交涉技能归零时，它总能帮你强行打开沟通的新渠道。",
        en = "The ultimate universal key and silent diplomatic envoy. It bypasses deadbolts, raises sewer grates, and resolves philosophical differences with feral trespassers via blunt force trauma, requiring neither ammunition nor a silver tongue to negotiate entry.",
    },
    ["crowbar_warhammer"] = {
        zh = "在一根厚重撬棍顶端焊接尖刺与配重块改装成的破甲战锤；既保留了暴力撬开防盗门锁的核心功能，又能一击敲碎变异防暴警察的合金头盔。",
        en = "A heavy crowbar retrofitted with a balance beak into a brutal warhammer; equally adept at popping reinforce bunker locks and caving in reinforced riot police helmet visors.",
    },
    ["crown_golden"] = {
        zh = "雕刻着繁复花树纹样的精美纯金王冠；即便旧世界的权力和法律早已化为乌有，戴上它在变异生物面前晃悠依然能让你显得极具仪式感。",
        en = "An intricate golden coronet sculpted with ornate blooming branches; although civilizations and dynasties collapsed, striding through fungal fields wearing this radiates morbidly regal flair.",
    },
    ["crown_golden_survivor"] = {
        zh = "用金银碎屑与废土工艺为幸存者之王打造的野性金冠；在满地丧尸与残骸的世界里称王也许很荒谬，但至少你的头顶在黄昏中闪闪发光。",
        en = "A custom-forged golden crown fashioned for the monarch of ruined wastelands; reigning over scorched craters feels absurd, yet your regal silhouette dazzles magnificently against setting sunsets.",
    },
    ["crucible"] = {
        zh = "一口小巧结实的耐火铸造坩埚；在土窑高达上千度的高温中熔炼铜屑和铝锭时，它是每一位渴望打造近代金属武器的末日工匠的心脏。",
        en = "A rugged refractory crucible built to endure fiery forge temperatures; melting down scrap brass and aluminum slugs, it beats as the beating heart of every aspiring wasteland blacksmith.",
    },
    ["crucible_clay"] = {
        zh = "用黏土经过高温烘烤烧制而成的原始冶金坩埚；虽然比石墨坩埚更容易开裂老化，但在荒郊野岭找不到工业陶瓷时，它是唯一的铸铁希望。",
        en = "A primitive metallurgical vessel sculpted from baked river clay; fragile compared to industrial graphite versions, yet the sole hope for casting molten iron in uncivilized backwoods.",
    },
    ["crude_40mm"] = {
        zh = "将下挂榴弹发射管粗糙焊接在简易枪托上制成的发射器；每次扣动扳机时剧烈的后坐力都会震得你虎口发麻，但前方的爆炸确实震耳欲聋。",
        en = "A rudimentary single-shot launcher cobbled together from unmounted 40mm barrels; the fierce recoil rattles your wrists, yet the resulting fiery blast obliterates barricades with authority.",
    },
    ["crude_firestarter"] = {
        zh = "用电池和细导线改装成的简易电火花点火器；只要接通电路就能靠短路红热引燃引火绒，是在狂风暴雨中彻底失去打火机时的救命稻草。",
        en = "An electric firestarter assembled from loose wires and battery terminals; sparking incandescent heat via intentional short-circuiting, it rescues shivering scavengers stranded in torrential rainstorms.",
    },
    ["crude_goedendag"] = {
        zh = "在粗大重木棒前端镶嵌坚固金属破甲尖锥的经典佛兰德棍枪。既能当钝击大棒把敌人的头盔砸扁，又能顺势向前突刺穿透厚甲，是步兵近战克制装甲丧尸的粗暴凶器。",
        en = "A Flemish goedendag consisting of a heavy club topped with a thick steel spike. Alternating between crushing club strikes and vicious thrusts, it excels at dismantling armored zombie soldiers.",
    },
    ["crude_heating_element"] = {
        zh = "将细铁丝紧密缠绕在耐热绝缘骨架上制成的原始电热丝；通电后能迅速发出暗红色的微光，用来加热一杯凉水或者在寒夜烘干湿透的袜子。",
        en = "A primitive heating coil wound from scrap resistance wire; glowing a faint cherry red under voltage, it boils murky ditch water and warms soggy socks on frozen nights.",
    },
    ["crude_lamp_oil"] = {
        zh = "从动物油脂和植物残渣中粗糙压榨出的天然灯油；在油灯里点燃时会散发出浓重的黑烟和刺鼻的焦糊味，但至少能驱散地下室里的无尽黑暗。",
        en = "Unrefined natural fuel pressed from animal tallow and seed mash; burning it fills enclosed shelters with acrid soot, but any flickering flame beats stumbling blindly into basement terrors.",
    },
    ["crude_oil"] = {
        zh = "从地下深处抽取出的漆黑粘稠原油；在未经工业分馏之前它黏糊糊得像恶魔的口水，但对于熟练的化工幸存者而言，这就是未提纯的黄金。",
        en = "Viscous, pungent crude pumped from underground reserves; sticky as demonic bile before catalytic distillation, yet possessing the latent potential to power rumbling wasteland roadsters.",
    },
    ["crude_picklock"] = {
        zh = "用废弃钢丝和扭力扳手粗暴磨制而成的简易开锁工具；虽然开高档保险箱时极易断在锁孔里，但对付居民楼脆弱的木门弹子锁已经绰绰有余。",
        en = "Improvised lockpicks ground from spring steel and torsion wrenches; prone to snapping inside heavy safes, yet perfectly capable of bypassing rusty suburban deadbolts without making noise.",
    },
    ["crude_plastic_vest"] = {
        zh = "用大型塑料垃圾桶切割片和打包带拼凑出的土味防弹背心；虽然挡不住步枪子弹的直击，但在面对游荡丧尸虚弱的撕咬时确实能救你一命。",
        en = "An armor vest assembled from rigid plastic trash can fragments; hopeless against high-velocity rifle fire, yet offering surprising resistance against the frenzied bites of wandering ghouls.",
    },
    ["crustacean_sample"] = {
        zh = "从变异巨蟹或变异虾体内提取出的几丁质遗传样本；试管里翻滚的粘液散发着深海生物的气味，是调制重装外骨骼突变诱导剂的核心原料。",
        en = "A concentrated genetic slurry harvested from mutated arthropods; swirling inside a glass vial, it holds the biological blueprint for cultivating hardened chitinous shell mutations.",
    },
    ["crutches"] = {
        zh = "一副铝合金制成的双拐；当你的小腿在逃离巨型真菌变异体时不慎摔成骨折时，这两根轻巧的金属支架就是你避免被活活吃掉的唯一靠山。",
        en = "A pair of lightweight aluminum crutches; indispensable when your leg fractures while sprinting away from fungal horrors, offering just enough mobility to limp inside safe basements.",
    },
    ["crystal_urn"] = {
        zh = "一只雕工极尽奢华的半透明水晶骨灰盒；在生者连尸体都来不及埋葬的灾变纪元，拿它来盛放骨灰显得过于奢侈，幸存者更倾向于用它存蜂蜜。",
        en = "An opulent translucent crystal urn meant for ancestral ashes; in an age where corpses rot unburied, survivors find it far more practical for storing wild comb honey.",
    },
    ["crystallizing_sugar"] = {
        zh = "正在慢慢析出晶体的过饱和浓缩糖浆；在它彻底硬化成白砂糖之前，每一只路过的小昆虫和偷吃甜食的幸存者都忍不住想用手指蘸上一小口。",
        en = "Super-saturated syrup gradually precipitating crystalline sugar; before solidifying into sweet granulate, wandering survivors cannot resist dipping a greedy finger into the sticky batch.",
    },
    ["crystallizing_sugar_active"] = {
        zh = "处于活跃结晶过程中的温热糖浆；需要放置在阴凉避光处耐心等待水分蒸发，它是战后重建面包房与甜品供应链不可或缺的甜蜜基石。",
        en = "Active crystallizing sugar solution demanding patience and steady temperature; once fully dried, it delivers the precious granulated sweetness necessary for high-morale wasteland bakeries.",
    },
    ["cu_pipe"] = {
        zh = "一根细长的工业紫铜管；虽然作为近战武器又软又容易弯曲，但在改装蒸馏器或者为太阳能热水器铺设管路时，它的导热性无可替代。",
        en = "A slender length of malleable copper tubing; too bendable for bashing zombie skulls, yet prized above silver when soldering together moonshine stills or vehicle radiators.",
    },
    ["cucumber"] = {
        zh = "一根翠绿爽脆的新鲜沙拉黄瓜；在满是防腐罐头与脱水军粮的世界里咬上一口水灵灵的黄瓜，能让幸存者产生一种文明社会从未崩塌的错觉。",
        en = "A crisp, hydrating salad cucumber freshly plucked from garden soil; tasting crisp green moisture amid dusty MRE crackers brings fleeting illusions of an intact, peaceful world.",
    },
    ["cucumber_cut"] = {
        zh = "切成均匀小块的清脆黄瓜片；不管是直接撒上一撮盐生吃，还是丢进炖锅里提鲜，都是末日避难所里不可多得的爽口绿色配料。",
        en = "Crisp cucumber chunks diced cleanly for culinary prep; enjoyed raw with coarse salt or tossed into camp stews to impart refreshing crunch to otherwise dreary survival rations.",
    },
    ["cudgel"] = {
        zh = "一根经过精心削制与打磨的长木棍；看似平平无奇的简陋农具，在精通棍法的武僧幸存者手中却能行云流水地打出致命的击退与招架连击。",
        en = "A slender wooden rod carved and balanced for personal defense; deceptively humble, yet devastating in experienced hands capable of chaining fluid parries and rapid concussive strikes.",
    },
    ["cufflinks"] = {
        zh = "一副闪烁着银光的素面绅士袖扣；昔日华尔街高管的标配饰品，如今即使你把它们擦得锃亮，也换不来半块掉在烂泥里的受潮压缩饼干。",
        en = "A pair of sleek silver cufflinks once fastened to boardroom suits; meticulously polished though they are, no trader will swap them for a moldy crust of stale bread.",
    },
    ["cufflinks_intricate"] = {
        zh = "一对带有微雕浮雕图案的高档精美银袖扣；做工之精湛令人叹为观止，只可惜在荒野里你用它擦拭瞄准镜嫌硬，拿去当鱼钩又嫌太圆润。",
        en = "Intricately filigreed silver cufflinks displaying remarkable aristocratic artistry; unfortunately too hard to wipe optics and far too blunt to bend into makeshift fishing hooks.",
    },
    ["cuffs"] = {
        zh = "一对带有精致蕾丝花边的纯白色假袖口；穿在满是污血与机油的防化服外面显得荒诞离奇，但确实能满足极度讲究着装品位的末日怪人。",
        en = "A pair of spotless white decorative wrist cuffs; pairing them with oil-stained ballistic vests looks downright surreal, yet thoroughly delights eccentric survivors obsessed with vintage attire.",
    },
    ["cuirass_bronze"] = {
        zh = "由整块厚重青铜板捶打成型的坚固胸甲；散发着古典英雄史诗的厚重金属质感，穿在身上沉甸甸的，能有效抵挡大部分变异野兽的尖牙利爪。",
        en = "A solid bronze breastplate hammered by hand into timeless heroic contours; noticeably heavy across the chest, yet reliably turning aside beast fangs and stray shrapnel.",
    },
    ["cuirass_lightplate"] = {
        zh = "由现代高强度合金钢精心锻造的轻型板甲胸甲；贴身弧线设计能巧妙卸掉劈砍的冲击力，是近战流幸存者敢于与变异暴君正面硬拼的底气。",
        en = "A contoured steel cuirass representing peak protective metallurgy; deflecting heavy kinetic slashes with angled slopes, it grants brawlers courage to confront hulking brutes in close quarters.",
    },
    ["cuirass_scrap"] = {
        zh = "用铁皮、路标和电线胡乱绑在胸前的废料胸甲；虽然穿戴后行动时噪音大得像个移动垃圾箱，但那层凹凸不平的铁皮确实能挡下丧尸的爪击。",
        en = "Jagged scrap plates bound across the chest with tangled wire; noisy as an overturned trash bin on the move, yet thick enough to stop lacerating ghoul claws.",
    },
    ["cuirass_tire"] = {
        zh = "将重型卡车废旧轮胎切成厚橡胶条编织成的轮胎胸甲；具有出色的抗撕裂与冲击吸收能力，唯一的问题是在烈日下会散发出浓烈的刺鼻橡胶味。",
        en = "A resilient cuirass crafted from layered vulcanized truck tread; soaking up blunt trauma remarkably well, provided you endure the suffocating stench of hot rubber baking in summer sun.",
    },
    ["cup_foil"] = {
        zh = "用一层易拉罐铝箔纸折叠捏成的简易小金属杯；虽然脆弱得一捏就变形，但它好歹耐火，足以让你在蜡烛苗上把几口雪水烧开消毒。",
        en = "A fragile drinking cup pinched together from folded aluminum foil; hopelessly flimsy under thumb pressure, yet fireproof enough to boil mouthfuls of melted snow over candle flames.",
    },
    ["cup_plastic"] = {
        zh = "一个廉价轻薄的一次性透明塑料杯；装热水时会烫得严重变形，但在废土上能拥有一件不漏水的干净容器喝水，本身就是一种小小的奢侈。",
        en = "A cheap vacuum-formed disposable plastic cup; softening alarmingly when filled with scalding soup, yet possessing any non-leaking vessel remains a genuine luxury after civilization falls.",
    },
    ["cup_plastic_yoghurt"] = {
        zh = "一个洗得很干净的小酸奶塑料杯；杯壁上似乎还残留着淡淡的蓝莓香精味，用来当作称量火药的量杯或者育苗容器都异常趁手。",
        en = "A thoroughly rinsed yogurt cup retaining phantom hints of synthetic blueberry; ideally suited for measuring black powder charges or sprouting mutant tomato seedlings on windowsill gardens.",
    },
    ["cured_hide"] = {
        zh = "刮净了多余油脂与碎肉并经过硝制硬化处理的厚兽皮；卷成一捆便于携带，是制作硬质皮甲、枪套和高耐久工装靴的顶尖原材料。",
        en = "A cured animal hide thoroughly scraped of meat and cured firm; rolled tightly for hauling, it serves as prime material for hardening into leather armor and durable boots.",
    },
    ["cured_pelt"] = {
        zh = "保留了完整浓密绒毛的熟化硬毛皮；既拥有皮革的韧性又具备极致的防寒保暖性能，在寒冬凛冽的暴风雪之夜，披上一张就能救你一命。",
        en = "A cured pelt retaining dense, insulating animal fur; combining structural toughness with thermal retention, wrapping yourself inside one prevents freezing during brutal blizzard nights.",
    },
    ["cured_roe"] = {
        zh = "用高浓度浓盐水精心腌制出的废土鱼子酱；虽然原料可能来自受到下水道污染的变异鲤鱼，但那一粒粒在齿间爆开的咸鲜依然让人沉醉不已。",
        en = "Post-apocalyptic fish caviar cured in dense brine; though harvested from suspicious mutant carp, the salty explosion of roe against your palate feels shockingly decadent amidst the ruins.",
    },
    ["curing_roe"] = {
        zh = "正在高浓度盐水中脱水熟化的生鱼子；虽然系统标注为废弃代码，但在饥寒交迫的幸存者眼里，只要吃下去不中毒就是正经的高级海鲜。",
        en = "Fish roe gradually curing in dense salt brine; marked as obsolete code by the engine, yet starving scavengers gladly devour anything savory that spares them food poisoning.",
    },
    ["curing_roe_active"] = {
        zh = "浸泡在饱和浓盐水中正处于深度腌渍发酵过程中的大粒野生鱼卵。随着多余水分被缓慢拔出，晶莹剔透的鱼籽正蜕变成高热量且耐储存的珍贵废土黑金鱼子酱。",
        en = "Wild fish roe actively curing in saturated rock salt brine. As osmosis pulls moisture from the glistening orange spheres, it transforms delicate river eggs into shelf-stable luxury survival caviar.",
    },
    ["curler_hair"] = {
        zh = "一个轻飘飘的粉色塑料卷发发筒；文明崩塌后已经没人关心刘海的弧度，但把它剪开做成钓鱼浮标或者套在电线上防磨损倒是相当合适。",
        en = "A lightweight pink plastic cylinder designed for hair styling; nobody cares about bangs during the apocalypse, yet it excels as a makeshift fishing bobber or wire protector.",
    },
    ["curling_iron"] = {
        zh = "一把插电发热的陶瓷卷发钳；在没有市电的末日，把它接到改装太阳能电池组上，不是为了烫波浪卷，而是为了给冻僵的罐头快速解冻。",
        en = "A ceramic curling iron demanding electrical current; plugged into a vehicle battery bank, it serves not for styling glamorous curls, but for rapidly thawing frozen ration cans.",
    },
    ["curry_meat"] = {
        zh = "用浓郁辛香料与大块肉块精心熬煮的咖喱炖肉；扑鼻的辛香能完美掩盖肉块来自变异两栖动物的可疑事实，吃得人满头大汗、士气大振。",
        en = "Savory meat curry simmering with potent spices; its aromatic heat thoroughly masks the questionable provenance of mutant amphibian meat, leaving you sweating with boosted morale.",
    },
    ["curry_powder"] = {
        zh = "一罐金黄刺鼻的复合咖喱香料粉；无论锅里煮的是烂树根、野草还是变异老鼠肉，只要狠心倒进去半勺，就能瞬间化腐朽为异域风情大餐。",
        en = "A tin of pungent golden spice blend; whether boiling bitter roots or dubious rodent cuts, tossing in a generous spoonful transforms grim starvation soup into exotic cuisine.",
    },
    ["curry_veggy"] = {
        zh = "混合了块茎与野葱的纯素蔬菜咖喱；虽然没有半点荤腥，但浓烈的姜黄与辣椒能让寡淡无味的煮野菜产生一种豪华盛宴般的错觉。",
        en = "Vegetarian curry packed with harvested wild tubers; devoid of meat, yet the fiery blast of turmeric and chili tricks your stomach into celebrating a festive feast.",
    },
    ["currywurst"] = {
        zh = "淋满浓厚咖喱番茄酱汁的切片香肠；德国街头的经典小吃在废土避难所里重现，让人在一边咀嚼一边忍不住怀念那个秩序尚存的和平旧时代。",
        en = "Sliced sausage drenched in zesty curry ketchup; this classic street food reviving inside grim evac shelters inspires nostalgic tears for an orderly, bygone pre-cataclysm world.",
    },
    ["cutlass"] = {
        zh = "一把水手与海盗在狭窄甲板短兵相接时最钟爱的经典宽刃短水手刀。宽厚的刀身具有惊人的劈斩惯性，带有弧形护手保护手指，挥砍破门砍杀丧尸时干净利落、极度称手。",
        en = "A classic naval cutlass featuring a broad, curving blade and solid knuckle-guard. Designed for brutal deck scuffles, its forward weight hacks through furniture and encroaching zombies effortlessly.",
    },
    ["cutlass_fake"] = {
        zh = "一把万圣节海盗装扮专用的塑料喷漆短水手刀道具。刀刃软绵绵得如同硬纸板，连一个烂番茄都切不开，拿着它去对峙丧尸只会被对方当场咬断手臂，属于纯粹的笑话。",
        en = "A plastic Halloween costume cutlass coated in tacky silver paint. Flimsier than cardboard, attempting to parry with it snaps the blade in half, leaving you defenseless before hungry undead.",
    },
    ["cutlass_inferior"] = {
        zh = "一把钢材杂质极多、刃口热处理极为粗糙的劣质短水手刀。虽然外观颇具杀气，但在全力劈砍丧尸头骨时极易发生刃口崩碎飞溅，对使用者的眼睛构成严重威胁。",
        en = "A poorly manufactured cutlass marred by excessive slag inclusions and brittle quenching. Chopping hard bone chips large chunks out of the cutting edge, showering the wielder's face with shrapnel.",
    },
    ["cutting_board"] = {
        zh = "一块厚实平整的厨房木砧板；上面布满了深深浅浅的刀痕，既能用来切菜剁肉，也能在变异蟑螂爬上餐桌时充当沉重的物理灭虫拍。",
        en = "A thick, flat hardwood chopping board scarred by knife cuts; perfect for dicing vegetables, and equally functional as a blunt bludgeon when mutated roaches invade the prep counter.",
    },
    ["cuvettes"] = {
        zh = "一盒高精度的实验室光学比色皿；脆弱的石英玻璃容不得半点划痕，如今在野外生存中，幸存者经常拿它来精准滴定自制炸药的硝化酸液。",
        en = "A set of precision optical spectrometry cuvettes; exquisitely fragile, post-cataclysm chemists repurpose them for measuring delicate acid ratios while synthesizing high explosives.",
    },
    ["cyborg_matrix"] = {
        zh = "布满微型导管与神经接口的生化神经矩阵；原本用于将人类思维与机械中枢连接，现在看它在营养液里微弱脉动，让人分不清它究竟是生是死。",
        en = "A complex cybernetic matrix webbed with fluid conduits; once linking human consciousness to machine cores, its rhythmic pulsing in nutrient fluid blurs the boundary of life and machine.",
    },
    ["cz600"] = {
        zh = "一把做工紧凑轻巧的栓动式巡逻卡宾枪；虽然射速无法压制成群的丧尸狂潮，但精准平稳的弹道能让你在安全距离上一枪掀翻游荡的特感尸怪。",
        en = "A compact bolt-action trail carbine offering crisp precision; incapable of mowing down dense swarms, yet ideally balanced for dropping hostile ferals cleanly from extreme range.",
    },
    ["cz75"] = {
        zh = "经典的捷克制半自动手枪，握把人机工效极佳；出色的可靠性与精准度让它成为幸存者探索废弃警局或地下实验室时最值得信赖的副手武器。",
        en = "The iconic CZ 75 semi-automatic pistol with sublime ergonomics; famous for combat reliability, it remains the scavenger's most trusted sidearm when clearing pitch-black labs.",
    },
    ["cz75mag_10rd"] = {
        zh = "容量为十发的钢制冲压手枪弹匣；虽然容弹量受限于民用合规法案，但紧凑短小的体积能让你把它塞进贴身口袋而不会在翻滚时硌断肋骨。",
        en = "A 10-round steel box magazine designed around obsolete compliance laws; its stubby profile slips into waist pouches without jabbing your ribs during desperate combat rolls.",
    },
    ["cz75mag_16rd"] = {
        zh = "容量为十六发标准手枪弹匣；不多不少的容量在重量与火力持久度之间取得了完美平衡，是每一位持枪求生者最基础的弹药补给单元。",
        en = "A standard 16-round steel magazine for the CZ 75; achieving the golden balance between pack weight and sustained firepower, it serves as the frontline survivor's daily bread.",
    },
    ["cz75mag_20rd"] = {
        zh = "扩容至二十发的手枪大容量长弹匣；从握把底部延伸出一段硬朗的钢壳，能让你在遭遇丧尸群贴脸伏击时不必手忙脚乱地频繁换弹。",
        en = "An extended 20-round magazine protruding from the pistol grip; providing crucial extra sustained fire when ambushed in narrow stairwells by aggressive crawling horrors.",
    },
    ["cz75mag_26rd"] = {
        zh = "超长尺寸的二十六发手枪弹匣；插在手枪上显得滑稽得像一根回旋镖，但它能让你一口气把半个弹药盒的子弹全部倾泻在变异巨兽的脸上。",
        en = "An unwieldy 26-round extended magazine resembling a boomerang; looking comical in holsters, it unleashes a torrent of 9mm rounds straight into charging brute faces.",
    },
    ["dahlia_baked"] = {
        zh = "在火堆炭灰中慢慢烤熟的大丽花块根；经过高温烘烤后淀粉彻底糊化，口感软糯香甜，让人惊叹原来花园里的观赏植物也能如此顶饱。",
        en = "A dahlia tuber slow-roasted under campfire embers; heat breaks down stubborn starch into soft, sweet pulp, proving ornamental suburban flowerbeds are actually edible treasure troves.",
    },
    ["dahlia_root"] = {
        zh = "从庭院花坛里挖出的大丽花肥大块根；闻起来带着淡淡的泥土辛香，虽然生吃味道寡淡发涩，但洗净煮熟后是一笔可观的淀粉热量来源。",
        en = "A fleshy tuberous root harvested from wild dahlia beds; carrying an earthy scent, it tastes bitter raw but yields substantial carbohydrate fuel once thoroughly boiled.",
    },
    ["dairy_book"] = {
        zh = "一本泛黄的实用家庭乳制品制作手册；详细记录了如何挤奶、分离奶油和熟化干酪，让手握一头变异奶牛的幸存者看到了开办奶酪作坊的曙光。",
        en = "A dog-eared guide titled 'Things to Do with Milk'; detailing cheese aging and curd separating, it inspires mutant livestock owners to establish thriving dairy cottage industries.",
    },
    ["damaged_shelter_kit"] = {
        zh = "一套被狂风撕裂的破损简易棚屋构件；树枝断裂、兽皮穿孔，必须用绳索和胶带重新修补固定，否则下暴雨时你在里面只会睡在一滩泥浆里。",
        en = "A disassembled wilderness shelter battered by storms; fractured poles and punctured hides demand urgent tape repairs, lest midnight downpours leave you slumbering in muddy soup.",
    },
    ["dance_shoes"] = {
        zh = "一双鞋底光滑的高跟社交舞鞋；在铺着高级红毯的宴会厅里光彩照人，但穿着它在布满碎玻璃和丧尸残肢的公路上奔跑纯属自寻死路。",
        en = "Polished dancing shoes with elevated heels; elegant across ballroom parquet, yet sprinting across glass-strewn apocalyptic asphalt in them constitutes an elaborate suicide attempt.",
    },
    ["dandelion_cooked"] = {
        zh = "用开水焯烫烹煮过的野生蒲公英嫩叶；虽然入口依然残留着淡淡的青草苦味，但丰富的维生素和矿物质能有效挽救你濒临崩溃的免疫系统。",
        en = "Boiled wild dandelion greens glistening with hot broth; retaining a faint grassy bitterness, their concentrated vitamins prevent nutritional collapse during harsh spring shortages.",
    },
    ["dandelion_fried"] = {
        zh = "裹上面糊在热油里炸至金黄酥脆的蒲公英花朵；咬下去嘎吱作响且带着植物的清香，是荒野求生者在油锅旁能享受到的最美妙的春季野味。",
        en = "Crispy battered dandelion blossoms fried in hot lard; crunching delightfully with delicate floral aromatics, this wild snack elevates foraging into genuine haute cuisine.",
    },
    ["dandelion_tea"] = {
        zh = "用焙干的蒲公英根部浸泡出的深色草本热茶；口感浓厚微苦，神似低配版黑咖啡，具有极佳的利尿和清热功效，能平复感染带来的燥热。",
        en = "A dark herbal infusion brewed from roasted dandelion roots; tasting remarkably like rustic decaf coffee, its diuretic properties soothe internal fevers after vicious infections.",
    },
    ["dandelion_wine"] = {
        zh = "用金色蒲公英花瓣与糖分缓慢发酵酿成的淡黄色果酒；口感清甜微酸，小酌一口能让在废土上紧绷了一整天的神经彻底放松下来。",
        en = "A delicate straw-colored wine fermented from golden dandelion petals; mildly sweet with floral undertones, a quiet sip unwinds nerves frayed by days of scavenging.",
    },
    ["dandelionburdock_fried"] = {
        zh = "将蒲公英嫩叶与牛蒡根切丝裹上面糊炸成的什锦天妇罗；酥脆的外皮包裹着爽口的野生植物，即使冷着吃也足以让人忘却末日的苦难。",
        en = "Wild dandelion petals and burdock root fried together in light batter; crispy and surprisingly earthy, this rustic tempura banishes thoughts of despair with every crunchy bite.",
    },
    ["dandelionburdock_tea"] = {
        zh = "将蒲公英根与野生牛蒡切片烘烤后冲泡出的养生茶；微苦回甘的味道能迅速唤醒疲惫的肠胃，是老派草药师极力推崇的废土排毒饮品。",
        en = "A robust medicinal brew steeping roasted burdock and dandelion roots; offering bitter-sweet complexity, wasteland herbalists swear by its capacity to purge systemic toxins.",
    },
    ["dao"] = {
        zh = "一柄单刃微弯的中式传统钢刀；刀身宽厚沉稳，重心靠前，劈砍力道凶猛无匹，即使是没有受过正规剑术训练的幸存者也能一刀斩断丧尸颈椎。",
        en = "A traditional curved Chinese broadsword with a broad forward balance; devastating on heavy cleaving strikes, it enables untrained survivors to decapitate zombies with sweeping momentum.",
    },
    ["datura_seed"] = {
        zh = "从带刺蒴果中剥落的剧毒曼陀罗种子；含有大量致幻生物碱，少量使用可作为强效麻醉剂，但稍微多吃几粒就会让你在狂暴幻觉中停止呼吸。",
        en = "Toxic datura seeds gathered from spiky seed pods; laden with potent tropane alkaloids, minute doses numb excruciating agony while reckless overdoses induce fatal hallucinatory spasms.",
    },
    ["daypack"] = {
        zh = "一个轻薄结实的超轻尼龙单日徒步包；容量虽然不足以支撑跨州远征，但装上几瓶水、两盒弹药和急救包进行快速搜刮搜刮已经绰绰有余。",
        en = "An ultralight nylon daypack tailored for quick scouting runs; insufficient for hauling engine blocks, yet offering optimal ergonomics for raiding pharmacies and dashing home.",
    },
    ["dayquil"] = {
        zh = "一瓶不瞌睡的日用复方感冒止咳糖浆；能迅速压制打喷嚏和咳嗽反射，避免你在屏息潜行绕过变异丧尸时不合时宜地咳出一记夺命巨响。",
        en = "Non-drowsy daytime cold syrup suppressing coughs and sneezes; an essential lifesaver that prevents you from hacking uncontrollably while creeping past slumbering night stalkers.",
    },
    ["dead_solar_beetle_radiosphere"] = {
        zh = "一具沉重的巨型太阳能甲虫机器人残骸；蓝色的外壳已经布满划痕，拆解后能收获高品质太阳能板碎片，但小心别被它未泄放的高压电容电飞。",
        en = "The metallic chassis of a fallen solar beetle automaton; despite scratched photovoltaic plating, salvage yields rare solar cells provided you dodge ungrounded internal capacitors.",
    },
    ["deaglemag"] = {
        zh = "容量为八发的大口径沙漠之鹰点四四口径手枪弹匣；装满重弹头后沉甸甸的，每次推进握把都伴随着清脆的机械声，代表着毁天灭地的单发威力。",
        en = "An 8-round steel magazine chambering thunderous .44 Magnum cartridges; remarkably heavy when topped off, each solid lockup promises devastating hand-cannon destruction.",
    },
    ["deaglemag_357"] = {
        zh = "沙漠之鹰点三五七马格南口径九发弹匣；精准的高速手枪弹兼顾了穿透力与弹容量，是对付中近距离变异甲壳生物的绝佳弹药载体。",
        en = "A 9-round magazine built for .357 Desert Eagle variants; offering superior velocity and penetration, it feeds reliable armor-piercing kinetic energy into chitinous horrors.",
    },
    ["deaglemag_50"] = {
        zh = "点五零口径行动快车沙漠之鹰七发弹匣；粗大如手电筒的巨型子弹整齐排列，扣下扳机的那一刻，连周围的空气都会被枪口巨焰彻底撕裂。",
        en = "A 7-round magazine hosting gargantuan .50 Action Express rounds; feeding thumb-sized lead projectiles that turn zombie torsos into pulverized mist while brutalizing your wrists.",
    },
    ["death_note"] = {
        zh = "一张用圆珠笔在废纸片上潦草写下的绝望临终遗言。上面写满了对家人的思念、对末日背叛者的咒骂或是某个藏有军火物资的秘密地点坐标，读来让人心情沉重复杂。",
        en = "A tattered scrap of paper scrawled with desperate dying words in frantic ballpoint ink. Detailing whispered betrayals, buried ammunition caches, and lost loved ones, it chills readers to the bone.",
    },
    ["debug_apply_fault"] = {
        zh = "全能调试故障注入器，能够强行为任何机械或电子设备添加底层故障；如果你在废土生活得太惬意，可以用它给自己的重型战车添点刺激的麻烦。",
        en = "An omnipotent debug fault injector assigning mechanical flaws on demand; when post-apocalyptic living feels too peaceful, use this to plague your deathmobile with engine seizures.",
    },
    ["debug_backpack"] = {
        zh = "折叠了高维物理空间的调试口袋宇宙背包；据说能容纳数以亿计的底层程序漏洞，但如果把它装满，当心现实服务器因内存溢出而当场崩溃。",
        en = "A miniature pocket universe folded into a backpack, capable of holding 384 million software bugs; pack it to capacity and reality crashes from an unhandled heap overflow.",
    },
    ["debug_calories"] = {
        zh = "一块违背热力学定律的调试神圣天使蛋糕；只需咬上一小口，就能为你注入支撑横跨整块大陆的虚空卡路里，连消化器官都来不及反应。",
        en = "A blasphemous slice of debug angel cake defying thermodynamics; a single bite grants enough phantom calories to run across continents without ever gaining body fat.",
    },
    ["debug_chloroform_rag"] = {
        zh = "浸透了绝对昏睡药剂的调试级三氯甲烷抹布；只要在任何生命体鼻尖轻轻一晃，对方就会毫无抵抗地陷入死猪般的沉睡，甚至包括你自己。",
        en = "A debug rag soaked in absolute soporific agent; waving it near nostrils forces instant, dreamless slumber upon any sentient entity, including careless survivors sniffing it.",
    },
    ["debug_dimension_traveller"] = {
        zh = "掌控多维虚空穿梭的维度跳跃罗盘；只要拨动刻度盘就能瞬间传送到平行现实，是神明级观察者用来逃避丧尸包围的最作弊逃脱道具。",
        en = "A spatial compass dialing across parallel dimensions; rotating its dials teleports the wielder across multiverse coordinates, circumventing mortal blockades like an omnipotent observer.",
    },
    ["debug_energy_shield"] = {
        zh = "能够吸收弹道动能的轻量调试能量护盾；虽然能量读数并不起眼，但开启后足以让你在自动炮塔的机枪扫射中闲庭信步，宛若漫步雨中。",
        en = "A personal energy shield diffusing kinetic ballistics; hums unobtrusively, yet withstands heavy turret machine gun fire as if strolling through a gentle summer drizzle.",
    },
    ["debug_item_damager"] = {
        zh = "能够直接扣除物品一整格耐久度的调试破坏器；轻轻一按就能让完好无损的钛合金护甲当场开裂，是测试装备修理技能最残忍的教具。",
        en = "A debug tool cleanly deducting a full tier of item durability; a single click cracks pristine titanium plate, serving as brutal tuition for testing repair proficiencies.",
    },
    ["debug_item_damager_adv"] = {
        zh = "高阶调试破坏仪，可以精准指定任何目标并削减其耐久；无论是坚不可摧的防空洞大门还是神圣神器，在它的数据修改射线前都会应声碎裂。",
        en = "An advanced structural damager targeting arbitrary items; from impenetrable vault blast gates to holy relics, all crumble before its destructive variable-altering beam.",
    },
    ["debug_item_search"] = {
        zh = "一件隐藏在底层搜索逻辑里的虚空幽灵物品；它本不该在任何幸存者的储物箱里现身，如果你看到了它，说明现实的数据索引已经走样了。",
        en = "A phantom dummy item lingering inside search subroutines; never intended for survivor inventories, its presence indicates that index arrays are whispering secrets.",
    },
    ["debug_lux_meter"] = {
        zh = "能够洞悉周围空间光照强度的调试照度仪；精确显示当前方格的勒克斯读数，告诉你那些隐藏在阴影里的潜伏者究竟还能隐蔽多久。",
        en = "A scientific debug radiometer reading localized lux levels; strips away gloom to quantify ambient light, revealing whether shadowy horrors can truly remain undetected.",
    },
    ["debug_mortar"] = {
        zh = "掌控全地图天谴的神权调试迫击炮；只要在大地图上轻轻一点，远在三个县城之外的巨型真菌塔就会伴随着一阵刺眼的白光灰飞烟灭。",
        en = "A divine debug mortar granting omnipotent cartographic wrath; clicking coordinates across the overmap vaporizes distant fungal spires into glowing ash with zero travel time.",
    },
    ["debug_nutrition"] = {
        zh = "一罐神圣的调试级斯帕姆午餐肉；一口咬下去能精准补满所有微量元素与电解质，是末日程序员留给饥饿观察者的究极数据维生口粮。",
        en = "A sacred slab of debug SPAM packing calculated nutrients; a mouthful satisfies every electrolyte craving, acting as coder benevolence for underfed wandering observers.",
    },
    ["debug_template"] = {
        zh = "纳米制造机专用的顶级光学模板；内部蚀刻着尖端纳米机械装配序列，只要插入纳米锻造炉，就能凭空重构出旧文明巅峰科技的结晶。",
        en = "A state-of-the-art optical template for nanofabricators; etched with microscopic assembly blueprints, it reconstructs peak pre-cataclysm wonders out of inert raw materials.",
    },
    ["debug_timer"] = {
        zh = "能够暂停与记录微秒级时间流速的调试秒表；用来测量劈砍丧尸与装填弹药消耗的实际计算周期，是废土速度论学者最钟爱的神秘仪轨。",
        en = "A debug chronometer tracking execution ticks; measuring weapon swings and reload delays down to clock cycles, it serves as the ultimate benchmark for survival efficiency.",
    },
    ["debug_weather_check"] = {
        zh = "实时接入大气层微观数据链的调试气象仪；在酸雨降临或传送门风暴撕裂天空之前，它会冷静地向你汇报下一秒的天象剧变。",
        en = "A debug meteorological readout tapping atmospheric variables; predicts torrential acid downpours and portal squalls seconds before the sky tears itself into screaming ribbons.",
    },
    ["deck_chair"] = {
        zh = "一把可折叠的轻便布面日光浴躺椅；展开后往草地上一放，泡上一杯热茶躺在上面晒太阳，会让你险些忘记五米外正有三只丧尸在啃栅栏。",
        en = "A foldable canvas deck chair for leisure sunbathing; reclining outdoors with brewed tea almost makes you forget the trio of ghouls gnawing through your garden fence.",
    },
    ["deck_of_cards"] = {
        zh = "一副崭新光滑的标准五十二张扑克牌；在漫长寂静的防空洞寒夜里，它是幸存者打发无聊时间、赌博分配口粮甚至测试队友欺骗倾向的神器。",
        en = "A glossy 52-card playing deck; essential for surviving boring bunker evenings, gambling over emergency rations, and subtly testing your companion's poker face.",
    },
    ["deck_of_tarot_cards"] = {
        zh = "一套印刷精美、画风神秘的占卜塔罗牌；虽然占卜师发誓它能预言未来，但抽出的牌往往无一例外全是象征终结的死神与高塔倒塌。",
        en = "An ornate deck of mystic tarot cards; though fortune tellers claim it reveals destiny, apocalyptic draws inevitably yield endless streaks of Death and inverted Towers.",
    },
    ["decorative_wreath"] = {
        zh = "由松针、红丝带与干果编织的圣诞节日花环；挂在地下室紧锁的铁门上，让在寒冬中躲避丧尸撕咬的幸存者感受到一抹苦涩的节日温情。",
        en = "A decorative pine needle holiday wreath; hung across reinforced basement gates, it offers bitter holiday warmth while survivors shelter from freezing winter zombie prowlers.",
    },
    ["decoy_anarch"] = {
        zh = "一本伪装成汽车俱乐部旅游指南的诱饵手册；翻开里面其实印满了当地的景点介绍，足以让搜刮特工在翻找真正的违禁情报时彻底抓狂。",
        en = "A tourist travel guide serving as an operational decoy; flipping through reveals picturesque roadside diners, intensely frustrating intelligence scavengers searching for insurgent blueprints.",
    },
    ["decoy_elfa"] = {
        zh = "一本装订整齐的供水立管日常维护日志；里面密密麻麻记录着水压与阀门检修记录，是用来伪装掩盖地下机密设施入口的极佳烟雾弹。",
        en = "A neat binder recording standpipe maintenance logs; dense with banal valve inspections, it effectively camouflages covert access routes to classified underground installations.",
    },
    ["deep_fryer"] = {
        zh = "一台餐厅后厨淘汰下来的大容量商用电炸锅；只要你能在末日收集到足够的动物油脂和电力，它就能炸出让附近整条街丧尸闻香而动的美味油渣。",
        en = "A bulky commercial deep fryer; provided you amass sufficient lard and generator current, it fries batches of food aromatic enough to lure distant street ghouls.",
    },
    ["default_dimension_teleport_orb"] = {
        zh = "一颗表面泛着干裂泥土质感的暗褐色虚空球体；捏碎它会撕开一道不稳定的空间裂隙，将你毫无征兆地甩进另一个充满不可名状恐惧的维度。",
        en = "A dull brown orb feeling like parched soil; crushing it rips open volatile spatial tears, hurling travelers unceremoniously into dimensions steeped in eldritch dread.",
    },
    ["deflated_wheel"] = {
        zh = "一只气压彻底放空的十七寸汽车轮毂轮胎；橡胶完好但毫无支撑力，若不找到打气筒给它充气，你的末日改装逃生战车就只能在原地打滑。",
        en = "A deflated 17-inch automobile wheel; possessing intact rubber yet zero air pressure, running without a pump leaves your customized getaway buggy spinning uselessly on rims.",
    },
    ["deflated_wheel_bicycle"] = {
        zh = "一只瘪气的二十七寸民用自行车轮；内胎可能已经被地上的碎玻璃扎破，在修补充气之前推着它走，只会像拖着一头倔强的瘸腿毛驴。",
        en = "A flat 27-inch commuter bicycle wheel; likely punctured by street glass, dragging it uninflated feels like hauling a stubborn, three-legged donkey across rubble.",
    },
    ["deflated_wheel_bicycle_or"] = {
        zh = "一只带有粗大防滑胎齿的二十七寸越野山地自行车轮；即使处于漏气状态，厚实的橡胶胎齿依然散发着征服荒野泥泞道路的坚韧气息。",
        en = "A rugged 27-inch studded off-road bicycle wheel; even completely drained of air, its aggressive tread practically begs to conquer rocky wilderness trails.",
    },
    ["deflated_wheel_motorbike"] = {
        zh = "一只泄了气的十六寸公路摩托车轮；虽然橡胶胎体已经变软塌陷，但只要换上新内胎重新打气，就能让你那台吵闹的机车再次狂飙突进。",
        en = "A squishy 16-inch road motorbike wheel; currently flattened, yet replacing its tube and pumping it firm revives the thunderous speed of your scout chopper.",
    },
    ["deflated_wheel_motorbike_or"] = {
        zh = "一只带有钢钉防滑纹路的二十寸越野摩托车轮；抓地力惊人，只要修好气门嘴充上高压气体，就能带你从变异尸潮的包围圈中弹射起步。",
        en = "A heavy 20-inch studded dirtbike wheel; boasting aggressive grip, restoring air pressure enables high-traction escapes through muddy ditch traps and encircling swarms.",
    },
    ["deflated_wheel_slick"] = {
        zh = "一只完全平滑毫无花纹的十六寸专业赛道赛车光头胎；虽然处于瘪气状态，但在平整柏油路面上能提供极致的极速过弯抓地力。",
        en = "A treadless 16-inch racing slick drained of air; though flat, once pressurized it delivers blistering cornering grip across smooth post-apocalyptic asphalt straights.",
    },
    ["deflated_wheel_wide"] = {
        zh = "一只夸张的二十四寸超宽重型车轮；虽然现在软趴趴地塌在地上，但装在多轴重型装甲车上能提供无与伦比的压路机般的平稳越野体验。",
        en = "A gargantuan 24-inch wide deflated wheel; currently limp, yet bolted onto multi-axle deathmobiles it delivers steamroller stability over collapsed road barriers.",
    },
    ["deflated_wheel_wide_or"] = {
        zh = "一只带有巨型泥地胎齿的二十四寸超宽越野重轮；硕大的橡胶花纹犹如履带齿，是穿越深厚沼泽与核冬积雪时不可替代的钢铁巨足。",
        en = "A massive 24-inch studded off-road wheel; featuring tread blocks rivaling bulldozer tracks, it crawls effortlessly through toxic mud and deep radioactive snow.",
    },
    ["dehydrated_cured_meat"] = {
        zh = "被彻底抽干水分的脱水熟化咸肉干；坚硬得像一块树皮，嚼在嘴里能磨平你的臼齿，但极其漫长的保质期让它成为远征时最坚实的后盾。",
        en = "Rock-hard dehydrated cured jerky; chewing it tests the endurance of your molars, yet its indefinite shelf life makes it an irreplaceable wilderness staple.",
    },
    ["dehydrator"] = {
        zh = "一台多层托盘的家用食物脱水机；通电运转时发出轻微的嗡嗡热风，能把多余的浆果、菌菇和鲜肉转化为能够跨年保存的救命干粮。",
        en = "A multi-tier electric food dehydrator; humming gently with warm circulation, it preserves perishable fruit and game into durable trail rations for barren winters.",
    },
    ["delay_fuze"] = {
        zh = "一枚结构精巧的机械延时起爆引信；倒计时齿轮滴答作响，为埋设炸药的爆破狂幸存者争取了足够连滚带爬逃出安全杀伤半径的宝贵时间。",
        en = "A precision mechanical delay fuze; its ticking clockwork mechanism provides just enough frantic seconds for demolition enthusiasts to dive behind reinforced blast barriers.",
    },
    ["deltoid_plates"] = {
        zh = "一对符合三级防护标准的肩部三角防弹插板；虽然稍微牺牲了双臂挥刀的灵活性，但能稳稳挡住流弹和丧尸对脆弱肩部大动脉的致命扑咬。",
        en = "A pair of Level III curved deltoid armor plates; slightly restricting overhead swings, yet shielding your vulnerable shoulder arteries from stray shrapnel and savage bites.",
    },
    ["deluxe_beans"] = {
        zh = "慢火慢炖的豆子配上不知名肉块；在废土上能同时吃到蛋白质和淀粉已是帝王级待遇，唯一的战术隐患是饭后排气可能会暴露你精心伪装的藏身地洞。",
        en = "Slow-cooked beans simmered with mystery meat chunks; dining on both protein and starch feels like royal luxury, though post-meal flatulence risks revealing your camouflaged underground bunker.",
    },
    ["deluxe_beansnrice"] = {
        zh = "浓郁豆汁与喷香米饭裹着肉粒和蔬菜；这顿豪华大餐能提供三天所需的全部热量，前提是你不会因为吃得太撑而在变异兽经过时陷入幸福的昏睡。",
        en = "Rich beans and rice thoroughly tossed with seasoned meat and wild greens; a feast packing three days of calories, assuming food coma doesn't knock you out before mutant patrols pass by.",
    },
    ["deluxe_cheeseburger"] = {
        zh = "夹着厚实肉饼、融化奶酪与新鲜脆菜的终极汉堡；这是旧时代快餐文明的辉煌巅峰，咬下去的瞬间足以让你短暂忘记避难所外熊熊燃烧的废土地狱。",
        en = "A towering cheeseburger packed with melted dairy, juicy meat, and crisp vegetables; the ultimate monument to pre-apocalyptic fast food culture, tasty enough to make you forget the burning ruins outside.",
    },
    ["deluxe_eggs"] = {
        zh = "蓬松嫩滑的炒鸡蛋里拌入了喷香的肉粒与鱼丁；在营地篝火旁煎出这锅金黄早餐时，方圆五里内的幸存者都会立刻记起他们是跟你共患难的至爱亲朋。",
        en = "Fluffy scrambled eggs folded with savory meat bits and fish flakes; cooking this over camp embers instantly convinces every hungry vagrant within five miles that they are your dearest lifelong friend.",
    },
    ["deluxe_fried_egg_sandwich"] = {
        zh = "两片金黄焦脆吐司中间夹着溏心单面煎蛋与融化奶酪的奢华三明治。咬下一口流心蛋黄在口腔里肆意四溢，浓郁的脂肪与碳水化合物能在瞬间抚平末日生存的所有创伤。",
        en = "A decadent toasted sandwich cradling a sunny-side-up fried egg with a runny golden yolk and melted cheese. Taking a warm, messy bite banishes traumatic nightmares of howling wasteland beasts.",
    },
    ["deluxe_fried_eggs"] = {
        zh = "在热油锅里煎得边缘焦香酥脆、中心蛋黄依然保持完美流心状态的特级单面煎蛋。撒上一小撮珍贵的黑胡椒与海盐，在阳光初照的清晨品尝，简直是国王般的无上享受。",
        en = "Deluxe sunny-side-up eggs fried in rendered tallow until edges turn delightfully lacework-crisp while centers remain liquid gold. Seasoned with salt, they offer a regal breakfast amidst the apocalypse.",
    },
    ["deluxe_rice"] = {
        zh = "在热锅里翻滚着大块咸肉与碎菜的热腾腾炒饭；铁锅与焦香油脂的滋滋作响声，比任何战前心理辅导师的安慰更能治愈幸存者濒临崩溃的精神状态。",
        en = "Steaming fried rice packed with savory meat cubes and wild herbs; the comforting sizzle of skillet grease does far more to soothe frayed survivor nerves than pre-war therapy ever could.",
    },
    ["deluxe_veggy_beans"] = {
        zh = "慢炖豆子与新鲜采摘的野菜根茎煨煮成一锅；在这片充斥着血腥杀戮与掠夺的残酷废土上，它是极少数完全不带道德负担与寄生虫风险的清爽盛宴。",
        en = "Slow-simmered beans stewed alongside freshly foraged wild greens; a gentle, cruelty-free culinary oasis offering wholesome nutrition without moral dilemmas or parasite risks across an otherwise ruthless wasteland.",
    },
    ["deluxe_veggy_beansnrice"] = {
        zh = "精心调味的豆粒、大米与脆嫩蔬菜焖煮而成；对于那些坚决不碰来源可疑的末日神秘肉罐头的谨慎搜刮者来说，这是能保命又绝不闹肚子的顶配佳肴。",
        en = "Hearty legumes and fragrant rice simmered with garden vegetables; the perfect wholesome refuge for paranoid scavengers who refuse to gamble their digestive tracts on suspicious wasteland mystery meats.",
    },
    ["deluxe_veggy_rice"] = {
        zh = "粒粒分明的炒饭搭配着各色鲜嫩碎菜；哪怕锅里没有半点变异兽肉的油脂，焦香酥脆的锅气也足以让饥肠辘辘的浪人重新燃起活到明天的希望。",
        en = "Golden grains tossed with crisp garden greens and wild leeks; proof that even without greasy mutant bacon, a hot skillet of charred rice can rekindle your desire to survive.",
    },
    ["demihuman_blood"] = {
        zh = "从变异亚人体内抽取的半透明发紫黏稠奇异血液。散发着一股类似臭氧与金属铁锈混合的怪异气味，在某些疯狂生化科学家眼里，这是研究基因诱变与血清药剂的珍宝。",
        en = "A vial of viscous, faintly luminescent purple blood harvested from a demihuman mutant. Emitting an ozone scent, deranged wasteland geneticists hoard it for brewing mutagenic stabilization serums.",
    },
    ["demihuman_brain"] = {
        zh = "一整块从变异亚人颅骨中剥离的生脑髓组织。表面沟回异常密集且覆盖着淡蓝色斑点，任何理智尚存的人都不会考虑吃下它，因为那无异于直接向脑膜炎与疯狂张开怀抱。",
        en = "A portion of convoluted brain matter extracted from a demihuman skull. Speckled with anomalous blue striations, consuming it uncooked is a direct invitation to catastrophic prion degeneration.",
    },
    ["demihuman_cooked"] = {
        zh = "在铁板上烤至全熟的一大片变异亚人熟肉排。尽管油脂滋滋作响且香气与寻常猪排无异，但只要一想到它生前曾是会讲人话的类人生物，你的喉咙就会止不住地产生痉挛抽搐。",
        en = "A pan-seared fillet carved from a demihuman carcass, browned in fat. Though smelling savory, swallowing meat harvested from something that spoke fluent English induces violent moral nausea.",
    },
    ["demihuman_cracklins"] = {
        zh = "炸得金黄酥脆、入口油香四溢的脆皮油渣；高热量且极其解馋，不过在变异横行的废土聚落里，懂规矩的食客从不会不识趣地打听这块皮到底来自哪种生物。",
        en = "Golden, crunchy morsels of deep-fried skin and rendered fat; irresistibly savory and packed with calories, though polite wasteland diners know better than to ask which creature originally wore the hide.",
    },
    ["demihuman_fat"] = {
        zh = "从亚人尸体上割下的一大块白花花纯油脂肥肉。虽然生吃让人恶心反胃，但扔进热铁锅里慢慢熬炼，能熬出一大罐极高热量的优质照明灯油与手工肥皂制造原料。",
        en = "A greasy pale slab of adipose tissue butchered from a demihuman. Melting it down inside a heated kettle produces abundant tallow suitable for fueling lamps, lubricating gears, or soapmaking.",
    },
    ["demihuman_flesh"] = {
        zh = "从变异亚人身上切下的一大块血淋淋生肉块。肉质纹理粗糙发暗，握在手里沉甸甸的，在道德彻底归零的绝境荒野上，它是饥民眼中最后能维系心跳的残酷蛋白质来源。",
        en = "Raw reddish muscle cut from the limbs of a demihuman. Coarse and smelling faintly of copper, desperate wanderers facing lethal starvation view it as the grim boundary between survival and extinction.",
    },
    ["demihuman_heart"] = {
        zh = "一颗肌肉纤维极其紧密厚实的生变异亚人心脏。坚硬的肌肉瓣膜宛如一块结实的橡胶块，在饥寒交迫的绝境下，切片用盐水煮熟后能为你提供撑过暴风雪的强大热量。",
        en = "A dense, muscular heart butchered from a fallen demihuman. Exceptionally fibrous and rich in iron, braising it with wild forest roots provides sustaining calories during sub-zero blizzards.",
    },
    ["demihuman_kidney"] = {
        zh = "一块深紫红色、表面带有腺体褶皱的生亚人肾脏。散发着一股刺鼻的尿素骚味，在扔进锅里烹饪前必须用大量清水反复浸泡焯水，否则那一股骚味能把整个避难所熏晕。",
        en = "A purplish demihuman kidney exhibiting deep glandular fissures. Smelling intensely pungent, exhaustive soaking and multiple water changes are mandatory before attempting to cook it into stew.",
    },
    ["demihuman_liver"] = {
        zh = "一大块沉甸甸、质地黏软的生变异亚人肝脏。深红色的表面在阳光下泛着油光，虽然富含巨量的维生素与矿物质，但潜在的毒素富集让每一口下咽都变成一场生死豪赌。",
        en = "A heavy dark-red liver harvested from an altered demihuman. Laden with vitamins and heavy metals, pan-frying it provides rich nutrition while testing your liver's tolerance for bio-accumulated toxins.",
    },
    ["demihuman_lung"] = {
        zh = "一块带有无数微小气孔、质地如同多孔海绵的生变异亚人肺叶。手感轻飘飘且软绵绵的，在废土黑市肉铺里它向来被归为最廉价的下水，通常只能丢进烂菜锅里煮汤喝。",
        en = "Spongy, porous lung tissue extracted from a slaughtered demihuman. Light and chewy, it represents bottom-tier offal relegated to boiling cauldrons of wild weed stew during desperate times.",
    },
    ["demihuman_marrow"] = {
        zh = "从亚人长骨骨髓腔内小心刮出的柔软多孔骨髓油脂。滑腻丰腴且蕴含着纯净的高密度脂肪，抹在烤焦的面包干上撒上一点盐，口感堪比旧时代米其林餐厅的昂贵前菜。",
        en = "Soft, fatty marrow scooped from the fractured leg bones of a demihuman. Richly unctuous, spreading it across toasted stale hardtack with salt mimics high-end culinary delicacies of old.",
    },
    ["demihuman_meat_scrap"] = {
        zh = "屠宰剔骨过程中切碎剥落的小块亚人碎肉沫。肉质边角料零碎干瘪，丢进陶锅里和几把野燕麦一起熬成浓稠的肉末糊糊，是荒原难民填饱饥渴肚肠的最底层温存。",
        en = "A scattering of ragged meat trimmings butchered from a demihuman. Boiling these stringy scraps into oatmeal porridge supplies just enough caloric fuel to keep emaciated vagabonds moving.",
    },
    ["demihuman_stomach"] = {
        zh = "一只肌肉壁异常厚实且带有强韧黏膜的变异亚人胃袋。内部消化腺体极度发达，洗干净后不仅可以当成大容量的天然储水囊，切条煮烂后也是相当耐嚼的荤菜食材。",
        en = "The tough muscular stomach harvested from a demihuman corpse. Thoroughly scrubbed with wood ash, its elastic volume functions as a durable canteen or as chewy tripe in foraging stews.",
    },
    ["demihuman_stomach_boiled"] = {
        zh = "在滚水里彻底煮透洗净的一整只熟亚人胃肚。惨白紧实的肉壁呈现出类似牛肚的蜂窝纹理，咬在嘴里嘎吱作响韧性惊人，是废土老兵下酒解馋的最硬核荤下酒菜。",
        en = "A cleaned demihuman stomach boiled thoroughly until pale and rubbery. Resembling thick honeycomb beef tripe, gnawing on its chewy strips beside a campfire keeps hungry jaws occupied for hours.",
    },
    ["demihuman_stomach_large"] = {
        zh = "从一头体型庞大的重型亚人巨怪体内剖出的大号胃囊。容量巨大得能直接装进四五升水，清洗晾干后绑上背带，就是废土长途穿越沙漠时容量最惊人的生物水袋。",
        en = "An enormous stomach pouch butchered from a hulking brute mutant. Holding several liters of liquid when tanned, it serves wanderers as a cavernous biological waterskin across arid wastes.",
    },
    ["demihuman_sweetbread"] = {
        zh = "从变异亚人胸腔中剥离的生胸腺与胰腺下水碎肉。质地如同白嫩的豆腐般柔滑细腻，虽然心理障碍极难克服，但在铁板上煎炸至金黄焦香时，其鲜嫩口感让饥民欲罢不能。",
        en = "Delicate pancreatic sweetbread tissues harvested from demihuman thoracic cavities. Silky like firm tofu, searing them in fat produces an exquisitely tender luxury that tests moral boundaries.",
    },
    ["demihuman_tallow"] = {
        zh = "将变异亚人脂肪彻底熬炼提纯后冷却凝固的光滑纯白油脂块。没有任何异味，既可以用来制作经久耐烧的无烟蜡烛，也能代替黄油在铁锅里煎炸野菜菌菇。",
        en = "A smooth block of rendered demihuman fat bleached clean of impurities. Odorless and dense, it serves equally well as clean-burning candle fuel or as culinary tallow for wild mushrooms.",
    },
    ["denat_alcohol"] = {
        zh = "掺入了极苦变性剂的高浓度燃料酒精；用来给野营便携炉点火效率极高，但若有走投无路的酒鬼试图拿它解瘾，那股深入骨髓的苦味会让他后悔来到人世。",
        en = "Potent fuel ethanol spiked with excruciating bittering agents; excellent for heating portable camp stoves, but any desperate alcoholic attempting to sip it will endure bone-deep remorse for days.",
    },
    ["denim_overalls"] = {
        zh = "结实耐磨的工装牛仔连体裤，胸前和裤腿遍布大大小小的口袋；不论大灾变前是蓝领技工还是复古潮人，穿上它的人现在都在忙着往口袋里猛塞钉子和螺栓。",
        en = "Rugged denim overalls bristling with roomy pockets and sturdy shoulder straps; whether worn by pre-war mechanics or vintage hipsters, anyone wearing them today is furiously hoarding salvage nails and scrap bolts.",
    },
    ["denim_patch"] = {
        zh = "一块从旧裤子上剪下来的蓝色牛仔布补丁；它是一条破烂裤衩与体面保暖衣物之间的最后防线，也是末日裁缝大师缝补战损长裤时不可或缺的救命材料。",
        en = "A neat square of tough indigo denim salvaged from worn trousers; the humble boundary between a drafty wardrobe malfunction and rugged wasteland couture, vital for patching battle-torn survival gear.",
    },
    ["denim_shirt"] = {
        zh = "采用厚实粗斜纹牛仔布缝制的长袖纽扣工装衬衫。耐磨结实抗刮擦，在荆棘灌木与生锈铁丝网丛中穿行时，厚实的布料能为双臂提供最可靠的日常防蹭保护。",
        en = "A rugged button-down shirt woven from heavy blue denim twill. Providing dependable defense against thorny blackberry brambles and jagged scrap edges, it remains a beloved wasteland workwear staple.",
    },
    ["dental_tools"] = {
        zh = "一套亮晶晶的不锈钢牙科刮匙、探针与尖钩；原本用于清理牙结石，如今在野战外科、精细撬锁或者审讯狂人手中，都能发挥出令人牙酸胆寒的奇特妙用。",
        en = "A gleaming bundle of surgical steel picks, scrapers, and hooks; intended for scrape-cleaning dental plaque, yet equally adept at improvised lockpicking, splint surgeries, or striking absolute terror into cavity sufferers.",
    },
    ["dentures"] = {
        zh = "一副按照特定牙龈倒模定制的树脂全口假牙；除非碰巧遇到骨骼清奇的完美契合者，否则捡到它的幸存者只能把它串成项链，用来冒充食人魔吓退毛贼。",
        en = "A pair of rigid acrylic false teeth custom-fitted to someone else's mouth; entirely useless for chewing your own hardtack, unless strung into a macabre necklace to scare away superstitious scavengers.",
    },
    ["deployment_bag"] = {
        zh = "缝满战术挂带与快拆卡扣的军规尼龙包；不仅能稳固挂载在防弹背心后方，还能作为大号腰包使用，让你在弯腰搜刮罐头时兼具战术精英的干练范儿。",
        en = "A heavy-duty tactical nylon utility pack fitted with MOLLE webbing; clips effortlessly onto plate carriers or waistbelts, ensuring you look like a seasoned commando while rummaging through convenience store dumpsters.",
    },
    ["destroyed_large_ceramic_plate"] = {
        zh = "一块内部布满粉碎性裂纹的重型防弹陶瓷插板；它确实英勇地替前主人挡下了致命步枪弹，但现在它只是一块重得要命、一碰就掉碎渣的贵重破砖头。",
        en = "A shattered heavy ceramic armor insert riddled with pulverized fractures; having heroically absorbed a high-caliber bullet for its previous wearer, it now functions merely as a heavy, crumbling tactical brick.",
    },
    ["destroyed_medium_ceramic_plate"] = {
        zh = "边缘崩碎的中型侧腰陶瓷防弹插板；虽然防弹性能早已彻底归零，但许多多疑的幸存者依然舍不得把它扔掉，毕竟背着几斤重的心理安慰总比光着腰强。",
        en = "A cracked medium ballistic side plate with fractured ceramic backing; while offering zero ballistic protection against stray shrapnel, carrying three pounds of pure psychological placebo still beats facing gunfire bare-flanked.",
    },
    ["detergent"] = {
        zh = "散发着刺鼻人工花香的经典去污洗衣粉；在满地丧尸污血与泥泞的末日废土上，一身散发着薰衣草清香的衣服是只有精神贵族才配享受的奢侈炫耀。",
        en = "A box of aromatic pre-cataclysm laundry powder; in a grim wasteland caked with zombie gore and ash, wearing clothes smelling crisp like lavender is the ultimate aristocratic flex.",
    },
    ["devil_horn_headband"] = {
        zh = "廉价塑料发箍上顶着两只亮红色的卡通小恶魔角；戴上它去跟虚空裂隙里涌出的可怖异形对峙，试图用十元店万圣节道具向恶魔军团证明你们是自己人。",
        en = "A flimsy plastic headband sporting bright scarlet horns; slip it on before confronting eldritch netherworld horrors, futilely attempting to prove your infernal credentials with a dollar-store costume accessory.",
    },
    ["devil_tail"] = {
        zh = "一条末端带尖角箭头的红色人造革长尾巴；别在后腰上逃命时会跟着屁股滑稽地左右甩动，让追逐你的丧尸巨汉误以为抓到了某种变异的小恶魔。",
        en = "A slick red costume tail tipped with a pointed spade; clipped to your belt while fleeing mutant brutes, it swings absurdly with every stride like a deranged carnival mutation.",
    },
    ["deviled_kidney"] = {
        zh = "源自维多利亚时代的香辣酱煎动物腰子；尽管末日里只能用野蒜和辛辣变质调料凑合代替原版酱汁，那股浓郁霸道的重口味依然能把整个避难所熏得精神大振。",
        en = "Victorian-style spicy sauteed kidneys tossed in makeshift wasteland sauces; despite dubious pantry substitutions for the original devilling blend, its pungent aroma and rich iron flavor instantly revive exhausted campmates.",
    },
    ["diamond"] = {
        zh = "一颗璀璨夺目、折射出冰冷光芒的裸钻；它既不能点火充饥，也挡不住丧尸利爪，但人类刻在基因深处的贪婪依然会让幸存者冒着被爆头的风险去争抢它。",
        en = "A sparkling gemstone reflecting radiant facets; totally incapable of starting a campfire or deflecting mutant talons, yet ancient human greed still compels survivors to risk sniper fire just to pocket it.",
    },
    ["diamond_dental_grill"] = {
        zh = "镶满碎钻的黄金嘻哈牙套；套在牙齿上不仅硌嘴还让人疯狂大舌头，但若是哪天不幸被丧尸啃死，至少你的骷髅头在地下城暗处闪耀着匪帮说唱的荣光。",
        en = "A diamond-encrusted gold dental grill; it fits horribly and induces an awkward lisp, but should a zombie swarm overwhelm you, your bare skull will at least gleam with street prestige.",
    },
    ["diamond_gold_bracelet"] = {
        zh = "黄金打造、嵌满闪耀钻石的奢华手镯；在夜间潜行搜刮时，只要漏进一丝月光就会闪瞎附近的掠食者，如同一座戴在手腕上的移动信标发射器。",
        en = "An opulent gold bracelet encrusted with fine diamonds; catches the faintest moonlight during nocturnal salvage runs, acting as a brilliant personal beacon for every blood-tracking predator in town.",
    },
    ["diamond_gold_cufflinks"] = {
        zh = "一对镶嵌钻石的黄金袖扣；原本配对的高级定制衬衫早已烂成布条，现在被幸存者拿来固定防尘披风的领口，让乞丐装瞬间焕发出一丝贵族晚宴的气派。",
        en = "A pair of gold cufflinks adorned with inset diamonds; their original tailored shirts have long rotted away, leaving them to fasten greasy survivor ponchos with baffling high-society elegance.",
    },
    ["diamond_gold_earring"] = {
        zh = "一对精巧摇曳的钻石金耳环；在阳光下闪闪发亮极其耀眼，但在穿过带刺灌木丛逃避狂暴变异狼群追捕时，它也是最容易被树枝钩住撕裂耳垂的致命小玩意。",
        en = "Elegant dangling earrings forged of gold and diamonds; gorgeous under sunlight, but exceptionally hazardous when sprint-dodging feral wolves through thorny brambles eager to snag dangling jewelry.",
    },
    ["diamond_gold_pendant_necklace"] = {
        zh = "吊挂着闪亮钻石吊坠的金项链；在狂奔逃命时会重重拍打在你的锁骨上生疼，防御力为零，唯一的用处是在避难所里向难友吹嘘自己曾经的身家千万。",
        en = "A shimmering gold necklace bearing a brilliant diamond pendant; violently thumps against your collarbone while sprinting, offering zero ballistic protection but boundless opportunities to boast about former wealth.",
    },
    ["diamond_gold_tiara"] = {
        zh = "镶嵌着排排钻石的耀眼金王冠；将它端端正正戴在头上，你就是这座废弃商场里无可争议的至高帝王，尽情接受橱窗塑料模特与灰尘兔子的臣服朝拜。",
        en = "A radiant gold tiara bristling with diamonds; crown yourself the supreme monarch of an abandoned department store, ruling sovereignly over silent clothing mannequins and swirling dust bunnies.",
    },
    ["diamond_platinum_bracelet"] = {
        zh = "镶嵌碎钻的纯铂金手镯；这种贵重金属完全不惧酸雨腐蚀，在末日里最大的实际价值，大概是套在右手腕上充当挥舞砍刀时的镀金平衡配重块。",
        en = "A gleaming platinum band studded with brilliant diamonds; completely immune to acidic rain corrosion, its primary wasteland utility is serving as an indestructible luxury counterweight for swinging machetes.",
    },
    ["diamond_platinum_cufflinks"] = {
        zh = "质感沉重的钻石铂金袖扣；在文明时代其价值足以在繁华市区置办房产，如今在黑市商人摊位前，它大概能换到半壶煮沸的池塘水和两发受潮的步枪子弹。",
        en = "Heavy platinum cufflinks inlaid with diamonds; once valuable enough to purchase suburban real estate, they now barter for half a canteen of boiled pond water and two damp rifle cartridges.",
    },
    ["diamond_platinum_earring"] = {
        zh = "沉甸甸的钻石铂金耳钉；戴上它不仅下垂拉扯耳垂，还给贴身缠斗的丧尸提供了一个坚固抗拉的手抓借力点，堪称战术自杀级的华丽饰品。",
        en = "Weighty platinum stud earrings set with diamonds; not only dragging down your earlobes, they provide close-quarters grappling zombies with high-tensile handles to wrench your neck sideways.",
    },
    ["diamond_platinum_pendant_necklace"] = {
        zh = "挂着璀璨钻石的白金吊坠项链；冰凉刺骨的铂金贴在胸前皮肉上，无情地提醒着幸存者：当冬夜柴火烧尽时，再昂贵的首饰也无法散发半点生命的温度。",
        en = "A dazzling diamond pendant hung on a platinum chain; resting freezing cold against your chest, it bluntly reminds shivering survivors that raw luxury generates zero BTUs of winter warmth.",
    },
    ["diamond_platinum_ring"] = {
        zh = "一枚顶部镶嵌大颗钻石的铂金戒指；象征永恒誓言的坚固合金比整座人类文明还要长寿，在婚约双方化为骸骨之后，它依旧在废墟瓦砾间闪闪发光。",
        en = "A pristine platinum ring crowned with a solitaire diamond; engineered for eternal vows, it easily outlasted civilization and its owners, glittering serenely amid the rubble of collapsed jewelry vaults.",
    },
    ["diamond_platinum_tiara"] = {
        zh = "镶满顶级钻石的奢华铂金王冠；当你顶着它蹲在泥泞路边、用生锈铁盒煮野草浑水充饥时，哪怕再落魄的流浪汉也会油然而生出一种末日女皇的傲慢。",
        en = "An opulent platinum tiara glittering with premium diamonds; balancing it on your helmet while boiling marsh puddle water over trash fires lends undeniable imperial elegance to apocalyptic squalor.",
    },
    ["diamond_ring"] = {
        zh = "托着闪亮单钻的经典黄金戒指；旧世界里它曾代表一笔巨额财富与终身契约，如今它在幸存者眼中要么能充当割玻璃的小刀，要么用来换两发能打响的霰弹。",
        en = "A classic gold ring sporting a sparkling solitaire diamond; once representing years of mortgage savings, wastelanders now value it strictly as an improvised glass cutter or two functional shotgun shells.",
    },
    ["diamond_silver_bracelet"] = {
        zh = "镶嵌细碎钻石的纯银手镯；表面因废土酸雾而微微氧化发黑，但依然无声地向周围的废土拾荒者证明：你在捡垃圾时也是个有品位的中产阶层。",
        en = "A sterling silver bracelet set with modest diamonds; slightly tarnished by sulfurous acid rain, yet silently informing fellow scavengers that you maintained refined, bourgeois aesthetics even in ruins.",
    },
    ["diamond_silver_cufflinks"] = {
        zh = "镶嵌微钻的纯银袖扣；在河滩边给肥硕的变异野兽剥皮放血时，用它能整齐收束住肮脏的破烂衣袖，展现出一种荒诞而严谨的末日屠夫礼仪。",
        en = "Modest silver cufflinks featuring tiny diamonds; remarkably useful for clipping back frayed flannel sleeves while field-dressing a bloated mutant beaver, maintaining impeccable apocalyptic butcher etiquette.",
    },
    ["diamond_silver_earring"] = {
        zh = "一对缀有小钻石的雅致银耳环；在篝火烟熏下几天就会发黑氧化，但至少能保证你在暴毙街头时，依然是一具打扮得体、略带轻奢品味的优质遗体。",
        en = "Delicate silver earrings tipped with sparkling diamonds; soon tarnished black by open campfire soot, they nonetheless ensure your eventual corpse looks stylishly accessorized for the forensic post-apocalypse.",
    },
    ["diamond_silver_pendant_necklace"] = {
        zh = "细银链上悬挂着一颗晶莹剔透的钻石吊坠；它垂在你满是补丁的防弹衣胸前晃晃悠悠，如同一枚纪念旧世界浮华与虚荣的闪光悼词。",
        en = "A slender silver chain carrying a diamond pendant; dangling over a heavily patched kevlar vest, it serves as a glittering epitaph commemorating pre-collapse vanity and forgotten boutique luxuries.",
    },
    ["diamond_silver_ring"] = {
        zh = "顶部固定着小巧钻石的银戒指；戴在食指上不仅外观清秀，在与丧尸贴身肉搏时挥拳击打，还能当成一颗微型金刚石指虎砸碎对方腐烂的面颊。",
        en = "A slender silver ring mounted with a cut diamond; while appearing dainty, clenching it into a fist converts your desperate punch into an abrasive diamond-tipped jawbreaker against rotting skulls.",
    },
    ["diamond_silver_tiara"] = {
        zh = "嵌有小碎钻的优雅银质小王冠；每次钻过狭窄锈蚀的通风管道都会被铁皮刮歪，但它依然能无可辩驳地加冕你为这栋废弃大楼通风管区的合法女皇。",
        en = "A dainty silver tiara glittering with diamond accents; constantly knocked askew when slithering through rusty ventilation ducts, firmly establishing your sovereign claim over the crawlspace kingdom.",
    },
    ["dias"] = {
        zh = "一枚不起眼的金属制简易自动阻铁；塞进民用步枪机匣就能解锁全自动泼水功能，在两秒钟内清空你珍藏的所有弹药，并顺便把枪管烧成烫手的红烙铁。",
        en = "An unassuming piece of bent steel that slips into civilian lower receivers, instantly converting semi-automatic rifles into ammo-devouring bullet hoses that turn barrels cherry red in seconds.",
    },
    ["diazepam"] = {
        zh = "强效苯二氮䓬类镇静处方药；当窗外天空变成诡异紫红色、真菌孢子漫天飘洒且你的精神即将崩溃时，服下它就是给大脑按下最安详的化学关机键。",
        en = "Potent prescription benzodiazepine tablets; when the sky bleeds eldritch violet and lurking cosmic horrors shatter your sanity, this pill functions as an immediate chemical snooze button for your brain.",
    },
    ["diesel"] = {
        zh = "浓稠油腻的石化柴油燃料；散发着重工业时代的粗犷气味，它不像汽油那样容易挥发变质，是驱动重型改装装甲车碾碎尸潮的真正黑色血液。",
        en = "Greasy, dark petroleum fuel smelling of heavy machinery; far less volatile and perishable than gasoline, it serves as the vital black lifeblood powering armored deathmobiles through zombie hordes.",
    },
    ["diesel_generator"] = {
        zh = "装有小轮子的重型施工柴油发电机；插上电缆就能输出源源不断的强劲电力，但引擎轰鸣震天响，能在两分钟内把方圆三公里的变异生物都请来参加派对。",
        en = "A heavy wheeled construction generator; supplies boundless kilowatts for base floodlights and welders, while roaring with enough deafening horsepower to invite every wandering mutant within three kilometers to your doorstep.",
    },
    ["dieselpunk_tailor"] = {
        zh = "厚重皮革装订的柴油朋克时装指南；教你如何把废旧橡胶管、黄铜齿轮与浸油皮料缝在一起，做出虽然重达四十斤却能让废土拾荒客帅到窒息的工业风战甲。",
        en = "A hefty, leather-bound volume brimming with retro-industrial patterns; guides survivors in riveting greasy leather, rubber hoses, and brass valves into stylish protective garments that weigh forty pounds.",
    },
    ["digging_stick"] = {
        zh = "一根削出扁平尖刃的粗木棍；人类农耕与挖掘工程最原始的始祖道具，在挖出几颗干瘪植物块茎的同时，能保证慷慨地给使用者的双手磨出四五个血泡。",
        en = "A crude wooden stake carved with a broad chisel tip; the most primitive excavating tool known to mankind, yielding shallow root trenches at the expense of bloody hand blisters.",
    },
    ["dimensional_anchor"] = {
        zh = "印有XEDRA机密标记的五点式背带碟形装置；处于关机状态时，它只是一块绑在胸前的古怪高科技陶瓷盘，除了让你像个误入歧途的实验品外毫无反应。",
        en = "A featureless ceramic disc harness bearing classified XEDRA markings; while switched off, it sits quietly against your chest, doing absolutely nothing except making you look like an escaped laboratory guinea pig.",
    },
    ["dimensional_anchor_on"] = {
        zh = "肩部指示灯泛出幽绿微光的开启式空间锚；虽然表面上风平浪静，但它释放的无形力场正死死钉住你的现实坐标，防止你被虚空恶犬拽进亚空间或者卡进水泥墙里。",
        en = "An active spatial anchor with a soft green shoulder LED; while silent, its field locks your molecular coordinates into baseline reality, preventing teleporting horrors from displacing you halfway into a concrete pillar.",
    },
    ["dimensional_perambulator"] = {
        zh = "一辆用低碳钢精心焊接而成的跨维度折叠婴儿推车；原本用于悠闲漫步的推车如今被改造成穿梭多重宇宙的交通工具，让你推着随身物资在虚空裂隙中闲庭信步。",
        en = "A low-carbon steel baby carriage adapted for casual strolls across the multiverse; roll your salvage packs or toddlers straight through rift tears without bumping your interdimensional carriage wheels.",
    },
    ["directed_floodlight"] = {
        zh = "一盏笨重的大功率半圆形定向泛光灯；点亮瞬间能把前方扇形区域照得亮如白昼，虽然能让潜行尸群无所遁形，但也会瞬间烧毁你适应黑暗的夜视瞳孔。",
        en = "A heavy, high-output industrial floodlight casting a broad arc of brilliance; perfectly illuminates creeping night horrors, while instantly blinding your own dark-adapted retinas with hundreds of searing watts.",
    },
    ["directional_antenna"] = {
        zh = "由铜线与木料拼接而成的定向接收天线；将它对准特定方向就能捕捉微弱无线电波，无论是避难所残存的呼救循环，还是全自动气象站永无止境的冷漠播报。",
        en = "An improvised antenna crafted from copper wire and wood; aiming it at distant coordinates catches faint broadcasts, whether automated emergency distress loops or the lonely hum of forgotten weather stations.",
    },
    ["disassembly"] = {
        zh = "散落一地、拆到一半的半成品零件堆；它充分展现了工匠雄心勃勃的改装蓝图，直到一只咆哮的变异丧尸犬闯入作坊，迫使所有拆解工作永久无限期搁置。",
        en = "A half-gutted pile of loose screws and components; an unfinished monument to ambitious craftsmanship, promptly abandoned the moment a howling zombie dog interrupted your delicate workshop repairs.",
    },
    ["disc_golf"] = {
        zh = "质地紧密沉重的小号高尔夫专用飞盘；比普通沙滩飞盘更硬、飞行速度更快，在紧急情况下反手全力甩出，说不定能给迎面扑来的丧尸造成一次极其合乎空气动力学的脑震荡。",
        en = "A compact, high-density plastic golf disc; far heavier and faster than beach frisbees, a sharp backhand throw can deliver a remarkably aerodynamic concussion directly to an advancing ghoul's forehead.",
    },
    ["discharged_storage_battery"] = {
        zh = "在盐水桶里泡了整整一天后，它理论上已经彻底失活。但在你鼓起勇气徒手拆解前，依然忍不住拿一根长木棍远远戳它两下，生怕它突然化身暴躁的化学烟花。",
        en = "After soaking in brine for a full day, it is theoretically neutralized. Still, before daring to disassemble it barehanded, you poke it with a long stick just in case it explodes into chemical fireworks.",
    },
    ["discharging_battery"] = {
        zh = "在盐水桶里冒着可疑的微小气泡并嘶嘶作响。盯着它缓慢放电是废土上最考验心跳的等待，仿佛在厨房水桶里用食盐和自来水慢炖一枚随时可能炸裂的小型炸弹。",
        en = "Hissing softly and releasing suspicious bubbles inside a bucket of brine. Watching it discharge is nerve-wracking, like slow-cooking an explosive bomb in kitchen soup and praying your salinity math was accurate.",
    },
    ["dish_towel"] = {
        zh = "一条吸水性极强的棉质厨房擦碗布。除了用来擦干洗净的餐具外，在紧急关头撕成布条包扎流血伤口，或者蘸上枪油擦拭生锈的枪机机匣，都异常趁手好用。",
        en = "An absorbent cotton kitchen towel designed for drying cookware. When crisis strikes, it readily tears into sterile emergency wound bandages or cleans gritty carbon buildup from firearm actions.",
    },
    ["dishwasher"] = {
        zh = "在装甲防撞杆与重机枪之间挤进一台洗碗机，堪称末日生存美学的巅峰——哪怕车窗外全是呼啸的尸群，幸存者的油腻餐盘和生锈铁罐也必须洗得洁净如新。",
        en = "Squeezing a motorized dishwasher between armor plates and heavy machine guns is peak wasteland decadence; even with ravenous hordes banging outside, your greasy mess kits and dented cans deserve a sparkling wash cycle.",
    },
    ["disincotton_ball"] = {
        zh = "一团吸饱了药水的蓬松白色小云朵，也是最纯粹的肉体酷刑。被变异丧尸抓伤时你连眉头都没皱一下，把这团棉球按在伤口上的瞬间，灵魂却疼得差点当场升天。",
        en = "A fluffy white cloud saturated with chemical agony. You barely flinched when the feral ghoul clawed your arm, yet pressing this tiny cotton ball against the wound makes your soul temporarily leave your body.",
    },
    ["disinfectant"] = {
        zh = "旧时代的家长总骗孩子“痛一下就好了”。如今倒在溃烂的伤口上，那股钻心的灼烧感非但没让人崩溃，反倒成了证明自己还是个活人、尚未尸变的最有力证据。",
        en = "Old-world parents used to promise it only stings for a second. Poured directly over a bloody gash, that searing chemical fire is the only reassuring sensation proving you are still human rather than turning undead.",
    },
    ["disinfectant_makeshift"] = {
        zh = "用土制蒸馏器熬出的高浓度酒精溶液。一半用来浇在血淋淋的伤口上杀菌，另一半灌进喉咙麻痹神经——废土上的全科医生向来只信奉这种内外兼修的双重疗法。",
        en = "Crude moonshine distilled from a rusty backyard apparatus. Half gets splashed over infected lacerations, while the other half goes down your throat to numb the agony—the classic two-step prescription of wasteland medicine.",
    },
    ["disinrag"] = {
        zh = "从破旧背心上撕下并浸透药水的布条。包扎树枝擦伤还算凑合，要是被腐烂的丧尸深嵌入肉，这块布条最大的作用大概也就是让遗体散发出淡淡的消毒水味。",
        en = "A torn shirt strip soaked in pungent disinfectant. While adequate for superficial scrapes, if a rotten biter sank its teeth to the bone, this damp rag merely ensures your remains smell faintly of hospital corridors.",
    },
    ["display_freezer"] = {
        zh = "便利店里常见的玻璃盖卧式冰柜。通电后最大的好处是隔着滑盖就能欣赏里面整齐码放的变异兽排，不必像开普通冰箱那样，放跑废土盛夏里无比珍贵的冷气。",
        en = "A commercial chest freezer with sliding glass panels. Connecting it to your generator lets you admire neatly arranged mutant steaks without swinging open the door and losing precious arctic air to the sweltering wasteland summer.",
    },
    ["display_fridge"] = {
        zh = "分层明亮的大型玻璃展示冷藏柜。你费尽心思把搜刮来的罐头和能量饮料摆得整整齐齐，尽管整条街上唯一会趴在玻璃前眼巴巴观赏的顾客，只剩下一群流口水的行尸。",
        en = "A towering glass refrigerator built for supermarket aisles. You can meticulously arrange salvaged cans and soda bottles in tidy rows, even though the only eager shoppers pressing against the glass are drooling undead corpses.",
    },
    ["distaff_spindle"] = {
        zh = "两根粗糙却精巧的木质纺具。在刚用霰弹枪轰碎尸潮的下午，静静坐在避难所弹药箱上搓捻植物纤维，恍惚间让人分不清人类文明究竟是倒退了一万年还是刚刚破晓。",
        en = "A pair of primitive wooden spinning tools. After spending the morning blasting zombies with shotguns, sitting quietly on an ammo crate to hand-spin plant fibers makes you wonder whether civilization collapsed or simply hit rewind.",
    },
    ["distilling_cookbook"] = {
        zh = "废土上最具含金量的生存宝典。无论手头积攒的是发霉烂玉米、酸野果还是杂草，只要翻开对应的章节，就能将它们通通转化为消毒剂、摩托车燃料或者换取军火的硬通货。",
        en = "The ultimate survival manual for aspiring wasteland alchemists. Whether dealing with moldy corn or bitter berries, its recipes show you how to brew potent fuel, sterile antiseptic, or premium trade currency from rotten compost.",
    },
    ["dive_bag"] = {
        zh = "透气性极佳的网眼潜水背包。它的排水性能无懈可击，代价则是你搜刮来的全部家当都会被暴雨淋得透湿，顺便向周围所有的强盗毫无保留地展示你的全部隐私。",
        en = "A breathable mesh backpack designed for swimmers. It drains water effortlessly, but also ensures that sudden downpours soak your provisions while advertising every piece of valuable salvage to watching bandits.",
    },
    ["diveknife"] = {
        zh = "带有锯齿刃和撬杠尖头的多功能潜水刀。柄部加装的软木塞是为了防止它在深水里沉底，但在陆地上握着它捅丧尸时，总让人觉得自己手里攥着一枚过分膨胀的香槟瓶塞。",
        en = "A versatile blade equipped with serrated teeth and a prying tip. The bulky cork handle keeps it from sinking into oceanic abyss, though on dry land, stabbing biters feels like brandishing an overgrown champagne cork.",
    },
    ["divemask_full_modular"] = {
        zh = "造型前卫的高端模块化面罩。戴上它能让你看起来像是执行绝密任务的水下特工，直到你在浑浊河底撞见变异巨鲶，急促的喘息瞬间让整个防雾面罩蒙上一层白茫茫的绝望。",
        en = "A high-tech modular diving mask that gives you the silhouette of an elite operative, right until you stumble into an amphibious predator and panic-breathe the entire glass visor into an impenetrable wall of condensation.",
    },
    ["divemask_full_scuba_notready"] = {
        zh = "覆盖整张脸的面罩本体，尚未安装水肺调节器。在耐着性子完成改装之前，千万别把它当成防毒面具套在头上，否则你只是花大价钱把自己闷死在一个气密橡胶盒子里。",
        en = "A sealed diving mask awaiting proper regulator assembly. Until you install the appropriate valves, wearing this rubber apparatus won't protect you from toxic gas; it simply suffocates you inside a premium watertight chamber.",
    },
    ["diving_flashlight_small"] = {
        zh = "小巧耐压的铝制潜水手电。在被水淹没的废弃地下室里保持关闭是明智之举，既能节约电池，又能避免照亮水底下那条正轻轻擦过你小腿的未知滑腻触须。",
        en = "A compact aluminum diving light, currently switched off. Navigating flooded basements in total darkness saves valuable battery power, while sparing you from illuminating whatever slimy mutant tentacle just grazed your submerged boots.",
    },
    ["diving_flashlight_small_hipower"] = {
        zh = "高亮版铝柄潜水手电筒，目前处于关闭状态。深黑的浑水里潜藏着无光环境演化出的食肉生物，关掉它能保住电量，顺便避免让自己成为整片水域里最显眼的活体诱饵。",
        en = "A high-output waterproof flashlight awaiting activation. Keeping it switched off conserves scarce battery charge, while ensuring you do not become a brightly illuminated, appetizing target for blind aquatic monstrosities lurking in the flooded ruins.",
    },
    ["diving_flashlight_small_hipower_on"] = {
        zh = "强劲的光柱像利刃般刺穿浑浊的积水，电池电量也在飞速见底。它确实照亮了深水中的每一个角落，包括前方三米处那张正缓缓张开、布满倒刺獠牙的变异巨口。",
        en = "A searing beam of illumination cutting through filthy underwater murk at the cost of rapid battery drain. It illuminates submerged wonders clearly, including an enormous fanged maw opening three meters directly in front of you.",
    },
    ["diving_flashlight_small_on"] = {
        zh = "在浑浊的积水中投射出一道微弱的光圈。光线虽然不算耀眼，但已经足够让你辨认出前方浮浮沉沉的阴影并不是普通的塑料垃圾袋，而是一具泡得发胀的丧尸尸体。",
        en = "Casting a steady cone of light through murky wastewater. Though not blindingly bright, it provides just enough illumination to confirm that the floating silhouette ahead is definitely a bloated corpse rather than a discarded trash bag.",
    },
    ["diving_flashlight_variable"] = {
        zh = "带有三档调光功能的多用途潜水手电。既能装在头套上也能扣在手腕上，让你在漆黑的水下逃命时彻底解放双手，更从容地在乱石堆和尸群之间惊慌扑腾。",
        en = "A multi-setting diving torch with an adaptable plastic mount. Strapping it to your wrist frees both hands while swimming, allowing you to paddle with uninhibited terror when something grabs your flippers in murky depths.",
    },
    ["diving_flashlight_variable_on_hi"] = {
        zh = "高功率档位全开，耀眼的光芒将暗无天日的水底照得亮如白昼。除了电池正在以肉眼可见的速度衰竭之外，整座湖泊里的发光浮游生物和食肉水兽也都兴奋地聚了过来。",
        en = "Blazing at maximum output, this setting turns underwater trenches into bright daylight. While your batteries drain within minutes, every carnivorous predator within a nautical mile receives an unmistakable invitation to a freshly illuminated midnight snack.",
    },
    ["diving_flashlight_variable_on_low"] = {
        zh = "温和的低亮度档位，电量消耗微乎其微。这点微弱的光晕刚好能看清面前两步的水草，既不会踢到沉在烂泥里的铁桶，也不至于惊醒旁边石缝里沉睡的捕食者。",
        en = "Switched to low intensity, drawing barely any juice from the battery cell. The faint glow reveals underwater obstacles just in time to avoid tripping, without waking ferocious nocturnal hunters sleeping in nearby riverbed crevices.",
    },
    ["diving_flashlight_variable_on_med"] = {
        zh = "调至中等亮度的折中档位。它既不像强光档那样挥霍宝贵的蓄电池电量，也不像弱光档那样让人疑神疑鬼，是残酷废土里罕见的一抹充满理性妥协的中庸之光。",
        en = "Operating at a balanced medium output. It avoids burning through scarce battery capacity like high mode, while offering enough clarity to prevent underwater paranoia—a rare testament to practical moderation amidst apocalyptic madness.",
    },
    ["diving_watch"] = {
        zh = "工艺精湛的不锈钢自动上弦潜水表。哪怕你在探索水下实验室时不幸耗尽氧气沉入渊底，它依然能保证你的遗体在冰冷的水流中极其精准地知晓当前时间与水温。",
        en = "A rugged self-winding stainless steel timepiece. Even if an aquatic mutant drags you into an abyssal trench and your oxygen tanks run dry, your waterlogged remains will maintain immaculate punctuality and precise ambient temperature readings.",
    },
    ["dnd"] = {
        zh = "一款以末日求生为主题的桌面角色扮演游戏。蜷缩在断电的避难所里，为了缓解被门外变异怪撕碎的焦虑，幸存者们决定围着蜡烛掷骰子，假装自己正在废土上艰难求生。",
        en = "A post-apocalyptic roleplaying game. Huddled inside a barricaded basement while monstrous blobs roam the streets, survivors gather around candlelight to roll dice and pretend they are heroic scavengers trying to survive a ruined world.",
    },
    ["dnd_2"] = {
        zh = "充满剑与魔法的中世纪跑团桌游。当现实里的战斗充斥着破伤风铁管和化脓伤口时，围坐在一起假装自己能随手搓出连环火球轰飞哥布林，成了最甜美也最廉价的心灵避风港。",
        en = "A high-fantasy tabletop adventure. When daily reality revolves around rusty rebar and infected bite marks, pretending to be an archmage incinerating orcs with spell slots is the cheapest psychological therapy left in the Cataclysm.",
    },
    ["dnd_3"] = {
        zh = "重返石器时代的史前部落桌游。在现代文明彻底倒塌、逼得所有人茹毛饮血的当下，还要在纸板上扮演古人类钻木取火打磨石器，多少带着点对现实处境的恶意嘲弄。",
        en = "A Stone Age tabletop survival game. After catastrophic collapse stripped humanity of electricity and plumbing, rolling dice to simulate primitive hominids rubbing sticks together feels like an uncomfortably literal mockery of your current living standards.",
    },
    ["dnd_handbook"] = {
        zh = "厚重无比的精装规则书。尽管里面密密麻麻的条文依然没讲清多手变异丧尸该怎么判定摔跤，但凭借那砖头般的分量，把它塞进夹克胸口充当防弹板倒是效果拔群。",
        en = "A massive hardcover manual packed with convoluted rulings. While it fails to clarify how grappling rules apply to tentacled abominations, the sheer density of its paper makes it exceptionally effective as makeshift chest armor.",
    },
    ["dog_tag"] = {
        zh = "用金属细珠链串在一起的两枚椭圆形军用身份识别金属牌。冰冷的金属牌上冲压着姓名、血型与部队番号，在荒野中发现它，往往意味着旁边埋着一位牺牲的战士。",
        en = "A pair of stamped oval aluminum discs hanging from a ball chain. Bearing a fallen soldier's name, blood type, and serial number, discovering them marks another forgotten battlefield tragedy.",
    },
    ["dog_tag_dog"] = {
        zh = "一枚刻着宠物名字和主人联系电话的金属小骨头项圈挂圈。曾经代表着一个家庭对忠诚爱犬的无尽宠溺，如今旧世界的主人早已不在，唯有项圈见证了昔日的温情。",
        en = "A stamped brass tag bearing an engraved pet name and disconnected phone number. A heartbreaking relic of suburban love, it outlived both its pampered hound and the vanished civilization that loved it.",
    },
    ["dog_whistle"] = {
        zh = "吹响时人类只能听见微弱的漏气声，周围的变异犬群却早已警觉地立起耳朵。你最好祈祷它们把这个高频音调当成战斗集结号，而不是送餐铃声响起的开饭信号。",
        en = "Blowing into it produces merely a faint hiss to human ears, yet nearby dogs instantly perk up. You can only hope the ultrasonic pitch signals an attack order rather than announcing dinner time for the pack.",
    },
    ["dog_whistle_wood"] = {
        zh = "用坚硬林木纯手工削出的小巧哨子。虽然外观像根烧火棍，但只要肺活量足够，就能向忠诚的猎犬下达无声军令——前提是你雕刻的气道没走音成招引变异杀人蜂的频率。",
        en = "Carved from seasoned timber by a campfire. This rustic whistle conveys silent tactical commands to loyal hounds—provided your rough woodworking did not accidentally tune the acoustic chamber to the resonant frequency of angry hornets.",
    },
    ["dogbane"] = {
        zh = "茎部韧皮纤维极为强韧的野生植物。它是编制应急绳索和网兜的极佳原料，但自带微毒；搓绳子时千万别学老农习惯性拿舌头舔线头，除非你想体验胃痉挛的滋味。",
        en = "A wild stalk possessing exceptionally tough fibers and mild toxicity. It yields fantastic cordage for wasteland snares, though licking the fibers while twisting thread will quickly reward you with an unpleasant lesson in gastrointestinal distress.",
    },
    ["dogfood"] = {
        zh = "散发着奇异肉香的粘稠肉糜罐头。在和平年代它是宠物的豪华大餐，但在废土上断粮三天的幸存者眼里，只要闭上眼睛屏住呼吸，这坨胶质物就是世界上最美味的红酒炖牛肉。",
        en = "Gelatinous canned meat emitting a bizarre olfactory aroma. Designed for pampered hounds, it becomes indistinguishable from gourmet steak tartare once you have endured seventy-two hours of wilderness starvation without finding edible scavenged rations.",
    },
    ["dogfood_dry"] = {
        zh = "富含维生素和微量元素的坚硬颗粒犬粮。它的保质期比生产它的食品厂还要长久；虽然嚼起来像风干的碎砖头，但在缺乏新鲜蔬菜的末日里，它是最硬核的抗坏血病口粮。",
        en = "Nutrient-enriched crunchy kibble boasting an absurd shelf life. Though gnawing on these dry pellets feels like chewing pulverized masonry, their vitamin cocktail keeps scurvy at bay long after fresh wasteland produce has vanished.",
    },
    ["dogfood_raw"] = {
        zh = "碎生肉与切碎菜叶的粗糙混合物。原本是为了照顾杂食家犬的营养均衡，但在避难所炉火上稍微翻烤两下，撒点盐粒，就成了末日流民梦寐以求的多汁手打肉饼。",
        en = "A crude mixture of raw minced trimmings and leafy greens. Intended for omnivorous domestic animals, a desperate survivor can easily shape it into a patty over a campfire to create a surprisingly decent wasteland burger.",
    },
    ["domino"] = {
        zh = "打磨细腻的浅色木质骨牌套装。耐着性子在避难所桌上把它们排成蜿蜒长龙，刚准备推倒第一块享受连锁反应的快感，门外巨型丧尸的一声咆哮就把整桌骨牌震得提前坍塌。",
        en = "A set of handcrafted wooden tiles housed in a neat box. Patiently lining them up across a barricaded table provides soothing solace, until a feral brute stomps past outside and triggers premature chain-reaction destruction.",
    },
    ["donut_holes"] = {
        zh = "裹满糖霜、外脆里嫩的油炸面团小球。曾经游乐场里的廉价快乐，如今成了废土上不可多得的奢侈甜点；一口咬下去不仅能提供热量，还能让你深切怀念早已绝迹的牙医。",
        en = "Crispy fried dough balls glazed with crystallized sugar. Once a cheap carnival treat, these golden spheres now serve as decadent luxury snacks, offering an instant rush of calories alongside deep regret for the extinction of dentists.",
    },
    ["door_lock"] = {
        zh = "一套包含齿轮与连杆的结实门锁组件。把它装在战车的钢门上能带给你虚幻的安全感，完全无视了那些身高三米的变异巨尸从不费心撬锁、而是喜欢连门带框直接扯下的事实。",
        en = "A mechanical lock assembly complete with internal linkages. Bolting it onto your armored vehicle provides soothing psychological comfort, right up until an eight-foot mutant brute ignores the lock entirely and tears the door off its hinges.",
    },
    ["doormat"] = {
        zh = "印着“欢迎光临”字样的防滑入户地垫。尽管站在门外的访客从不擦掉脚上的泥泞和腐血，甚至只想把主人的脑浆当成开胃头盘，这块垫子依然日复一日保持着最后的待客礼仪。",
        en = "A friendly rubber-backed mat extending greetings in faded lettering. It maintains domestic courtesy outside your bunker door, even when the shuffling guests never wipe their bloody boots and only seek to feast on your vital organs.",
    },
    ["doublespeargun"] = {
        zh = "配有双重高弹力皮筋的水下重型猎鱼枪。在水流阻力下它能爆发出洞穿鳞甲的惊人穿透力，但如果在陆地上拿它迎击丧尸，射程不仅大打折扣，掉在地上的鱼叉还会让你瞬间陷入尴尬。",
        en = "A dual-band underwater harpoon weapon. Submerged in water, its double elastic rollers propel steel spears with armor-piercing force; fired on dry pavement, however, the heavy dart flops pathetically onto the asphalt, leaving you defenseless.",
    },
    ["down_blanket"] = {
        zh = "柔软轻盈的蓬松羽绒毯。像受惊的小孩一样把它蒙过头顶确实挡不住破门而入的尖牙利爪，但至少在避难所零下十度的寒夜里，它能保证你不会在被怪物吃掉之前先被冻成冰棍。",
        en = "A plush blanket stuffed with insulating feathers. Pulling it over your head like a terrified toddler provides zero protection against hungry predators, but it guarantees you won't freeze to death before the monsters breach your door.",
    },
    ["down_feather"] = {
        zh = "一把洁白蓬松的飞禽绒羽。它是缝制高级保暖被褥的绝佳填充料，唯一的缺点是在避难所里千万不能打喷嚏，否则纷飞的白毛能让你足足花上两个小时在乱石堆里挨个捡拾。",
        en = "A handful of fluffy plumage harvested from wild birds. Unrivaled as cozy insulation for tailoring sleeping gear, provided you suppress every sneeze—lest your shelter transform into a swirling blizzard of feathers requiring hours to gather back.",
    },
    ["down_mattress"] = {
        zh = "填满了蓬松羽绒的单人床垫。躺上去的一瞬间仿佛陷进了天鹅绒般的云朵，让人彻底忘却身处地狱般的废土；然而一旦被篝火飞溅的火星引燃，它散发的烧焦羽毛味能熏倒整座大楼。",
        en = "A lavish mattress stuffed with soft bird feathers. Sinking into its plush surface makes you forget the apocalyptic hellscape entirely, until a stray campfire spark ignites the ticking and fills your shelter with blinding foul smoke.",
    },
    ["down_pillow"] = {
        zh = "卷成圆筒以便打包携带的羽绒枕头。在水泥管道或阴冷防空洞里铺开它的那一刻，它蓬松的回弹力会温柔地托起你疲惫的头颅，让人在末日的噩梦中短暂品尝到旧文明的尊严。",
        en = "Tightly compressed into a transportable roll for nomad travel. Unrolling it across damp bunker concrete grants your weary skull a luxurious cloud of softness, offering a fleeting taste of pre-collapse dignity amidst grim apocalyptic nightmares.",
    },
    ["dp_12"] = {
        zh = "把两根枪管和两个弹仓强行揉进同一个枪身的火力狂魔。一次泵动，两发上膛，连续扣动扳机能将近距离扑来的任何变异体轰成肉雾——它不在乎精准度，只负责执行彻底的物理超度。",
        en = "A monstrous firearm cramming dual barrels and separate magazines into one bulky receiver. One pump primes two shells; pulling the twin triggers in rapid succession vaporizes whatever horror stood nearby, substituting sheer devastation for pinpoint marksmanship.",
    },
    ["draw_plate"] = {
        zh = "开满不同口径圆孔的淬火厚钢板。徒手把粗金属棒一遍遍拽过越来越狭窄的圆孔，直到双臂抽筋、虎口流血，这项工序能让每一个幸存铁匠深刻理解工业流水线究竟有多么伟大。",
        en = "A hardened steel plate drilled with diminishing apertures. Manually yanking thick metal through smaller and smaller holes until your muscles cramp and blisters bleed will make any wasteland blacksmith deeply appreciate why ancient civilization industrialized wire production.",
    },
    ["dress"] = {
        zh = "一袭剪裁简朴的纯棉轻便连衣裙。穿着它挥舞钉头棒或驾驶改装战车在废土废墟中呼啸而过，虽然防御力约等于零，但那份飘逸的超现实优雅足以震慑所有审美尚未丧失的暴徒。",
        en = "A simple lightweight cotton dress. Roaming ruined highways in fluttering fabric while clutching a spiked war club offers zero ballistic protection, but the sheer surreal aesthetic is enough to give pause to any aesthetic-conscious raider.",
    },
    ["dress_shirt"] = {
        zh = "熨烫平整的长袖纽扣衬衫，胸前还带有一个端正的小口袋。穿上它让你看起来像个随时准备去开周会的白领精英，即使那个小口袋里现在塞满了点四五手枪子弹和发黑的肉干。",
        en = "A crisp button-down shirt featuring long sleeves and a breast pocket. Wearing it gives you the professional aura of an office worker heading into a board meeting, even if your pocket now holds loose ammunition and jerky.",
    },
    ["dress_shoes"] = {
        zh = "油光发亮的体面正装皮鞋。穿去参加和平年代的求职面试堪称无可挑剔，但如果你穿着它踩过布满碎玻璃和锈铁钉的街道、试图甩掉身后狂奔的变异猎犬，那下场绝对是灾难性的。",
        en = "Gleaming patent leather shoes crafted for corporate prestige. Flawless for boardroom meetings and formal galas, yet wearing these stiff, slick-soled relics while sprinting across broken glass to escape rabid zombie hounds is a recipe for orthopedic tragedy.",
    },
    ["dress_sleeved"] = {
        zh = "一件带有舒适长袖的纯棉印花日常连衣裙。虽然在打打杀杀的废土生活中略显累赘，但换上它在安全的壁炉旁静静坐着，能让你找回作为文明人类的平静与优雅。",
        en = "A soft cotton dress featuring full sleeves and subtle floral patterns. Ill-suited for muddy trench warfare, wearing it beside a warm hearth rekindles fading memories of peaceful domestic life.",
    },
    ["dress_wedding"] = {
        zh = "在旧世界，它象征着“直到死亡将我们分开”的浪漫誓言。如今穿着九公斤重的洁白蕾丝穿行在废土泥潭里，除了在五百米外给变异怪物充当高反差的惨白活靶子之外，再无别的战术价值。",
        en = "In the old world, it symbolized solemn vows of until death do us part. Now, dragging nine kilos of lace through mud merely offers distant mutant horrors an impeccably high-contrast white target.",
    },
    ["dressage_whip"] = {
        zh = "曾经用于在皇家盛装舞步赛场上优雅地轻叩温血名驹。如今在死城街头用它抽打狂暴的变异巨蚁，只会让对方深感困惑——在昆虫的词典里，“贵族马术礼仪”大概等同于开饭前的轻拍。",
        en = "Once crafted to politely cue warmbloods through dressage arenas. Flicking it at an enraged mutant centipede in the ruins only breeds confusion, as giant arthropods have remarkably little regard for aristocratic equestrian etiquette.",
    },
    ["dried_salad"] = {
        zh = "战前食品工业的荒诞产物：把冻干蔬菜叶泡进水坑里，再拌上永不变质的蛋黄酱。嚼起来如同浸湿的绿纸板，但至少能让你在啃腐肉度日的废土上假装自己依然保有健康饮食的中产体面。",
        en = "A pre-cataclysm corporate miracle: rehydrating freeze-dried leaves with swamp water and slathering them in immortal mayonnaise. It tastes like damp cardboard, yet lets you maintain the polite delusion of a healthy, fiber-rich lifestyle.",
    },
    ["drift"] = {
        zh = "铁匠台上用来给烧红钢板开孔和扩孔的利器。在避难所工坊里，它最常用来见证你满头大汗凿了两小时装甲孔，最后却发现捡回来的粗螺栓依旧比孔径大上一圈的人间悲剧。",
        en = "Specialized steel spikes forged to punch and expand holes in glowing iron. In your wasteland workshop, their primary duty is watching you hammer for two hours only to find the salvaged bolt is still too wide.",
    },
    ["drill_press"] = {
        zh = "一台能够以微米级精度垂直打孔的重型机床，可惜在电网崩溃后沦为废铁。在你捣鼓出稳定的发电机组之前，它最精准的作用就是充当一个能把求生日记稳稳压在桌面上的高档铁坨。",
        en = "A precision industrial beast capable of perpendicular drilling, rendered entirely mute by grid failure. Until you wire up a generator, its most accurate task is serving as a massively overengineered paperweight for your survival notes.",
    },
    ["drill_press_tool"] = {
        zh = "一台安装在稳固重型铸铁底座上的专业立式台钻机床。只要接通电源拉下操纵手柄，高速旋转的硬质合金钻头能在坚硬钢板上精准钻出毫厘不差的垂直螺丝孔。",
        en = "A stationary motorized drill press mounted to a heavy cast-iron table. Guided by a smooth hand quill, its high-speed carbide bits drill perfectly aligned bores through thick armor plate.",
    },
    ["drill_rock_primitive"] = {
        zh = "一根圆头木棍，配上水和细沙，全靠纯体力摩擦在坚石上慢慢磨孔。等你终于靠这套远古石器工艺钻通一块石斧时，外面的丧尸可能已经进化出了三阶形态，而你的掌心也长出了厚茧。",
        en = "A blunt stick relying solely on abrasive sand, water, and endless friction. By the time this primitive method bores through a river stone, external hordes have evolved further and your palms are tough enough to deflect shrapnel.",
    },
    ["drink_beeknees"] = {
        zh = "禁酒令时期的人们用蜂蜜和柠檬掩盖私酿浴缸杜松子酒的煤油味。而在大灾变里，你得冒着被两米长的变异杀人蜂扎成筛子的风险去掏蜜，才能让喉咙里的工业酒精尝起来带点爵士时代的风雅。",
        en = "Bootleggers used honey and citrus to mask the caustic bite of bathtub gin. In the apocalypse, you must dodge five-foot mutant wasps just so your toxic moonshine tastes like jazz-age elegance instead of degreaser.",
    },
    ["drink_bloody_mary"] = {
        zh = "战前早午餐派对上赫赫有名的醒酒圣药。不过在充满狂犬与尸群的荒野里端着这杯鲜红浑浊的液体晃悠，周围神经高度紧绷的幸存者多半会误以为你在咳血，并毫不犹豫地端起猎枪自卫。",
        en = "The undisputed hangover remedy of civilized brunch crowds. Clutching this thick, crimson potion in the wasteland, however, usually convinces paranoid scavengers that you are coughing up arterial spray, prompting them to aim shotguns at your face.",
    },
    ["drink_bloody_mary_blood"] = {
        zh = "当温室番茄全部被酸雨烂透后，废土调酒师决定在字面上彻底落实这款鸡尾酒的真谛。新鲜提取的温热血液兑上烈酒，吸血鬼变种人喝了拍手叫好，而普通人类咽下一口就需要重塑三观。",
        en = "When acid rain ruined the last tomato crops, wasteland mixologists embraced merciless literalism. Lacing pure alcohol with fresh mammalian blood creates a concoction that delights mutant vampires while utterly wrecking any normal survivor's sanity.",
    },
    ["drink_boozeberry"] = {
        zh = "把发酵蓝莓捣碎成泥状调制的烈酒，浓稠得仿佛某种紫色的润滑油。虽然下肚后能提供扎实的饱腹感，但那种在喉咙里滑腻蠕动的质感，总会让你怀疑自己喝下去的是变异软体幼虫。",
        en = "A fermented blueberry mash boasting the alarming viscosity of purple motor lubricant. It provides surprisingly hearty calories, yet the thick, sludgy mouthfeel constantly tricks your panicked brain into thinking you swallowed live mutant grubs.",
    },
    ["drink_gintonic"] = {
        zh = "大英帝国殖民军官为了咽下苦涩的防疟疾奎宁水而发明的经典配方。虽然旧世界的按蚊已经灭绝，但面对扑面而来的巨型变异马蜂，喝上一杯至少能让你被叮死时保持英国绅士般的从容。",
        en = "Invented by colonial officers to make bitter anti-malarial tonic water palatable. While regular mosquitoes are extinct, facing giant irradiated hornets feels considerably more civilized when your gullet is lined with crisp, fizzy botanical liquor.",
    },
    ["drink_grog"] = {
        zh = "风帆战舰时代水手用来兑进发臭木桶死水里的廉价朗姆酒溶液。这种甜丝丝又略带酒气的浑浊液体，能让你深刻领悟人类文明的早起拓荒史，究竟是在多么糟糕的卫生条件下勉强维系的。",
        en = "Seventeenth-century sailors splashed cheap rum into stagnant barrel bilge to keep from mutinying. Gulping down this sweet, mildly boozy brew reminds you that global maritime exploration was fueled entirely by bad sanitation, scurvy, and liquid defiance.",
    },
    ["drink_gunfire"] = {
        zh = "英国陆军士兵在黎明冲出战壕冒着枪林弹雨冲锋前喝的热红茶加朗姆酒。在废土寒夜灌下一大杯滚烫的“炮火”，能赋予你盲目的虚妄勇气，让你觉得自己凭一把撬棍就能正面硬撼坦克。",
        en = "British soldiers knocked back mugs of piping hot tea laced with dark rum before dawn trench assaults. Swallowing this fiery brew provides just enough liquid delusion to convince you that your crowbar can dismantle a military tank.",
    },
    ["drink_hard_seltzer"] = {
        zh = "灾变前中产阶层泳池边风靡一时的低热量气泡酒。当你满身油污躲在漏雨的混凝土管子里，听着废墟里夜魔的惨叫啜饮这罐人造青柠味汽水时，强烈的反差感会让你笑出声来。",
        en = "The low-calorie darling of pre-war suburban patio parties. Sipping this fizzy, artificially flavored fruit water while huddled inside a dripping drainage culvert escaping nocturnal predators delivers the absolute zenith of absurd lifestyle dissonance.",
    },
    ["drink_hobo"] = {
        zh = "名字里的“精致”纯属黑色幽默，骨子里不过是三家废弃加油站垃圾桶里搜罗出的残酒大杂烩。入口宛如吞下一口工业溶剂配变质糖浆，所谓的讲究，无非是倒进了一个没破口的塑料杯里。",
        en = "The word fancy is sheer mockery; this is merely dregs salvaged from shattered liquor store floors mixed together. It scorches your throat like industrial cleaner, served with supreme post-apocalyptic elegance inside an unwashed plastic oil funnel.",
    },
    ["drink_kalimotxo"] = {
        zh = "西班牙年轻人把廉价酸红酒与可乐等比混兑的发明。虽然旧世界的侍酒师看到会气得发狂，但在废土上，碳酸饮料强烈的磷酸与糖分，恰好能完美掩盖陈年变质酒那股刺鼻的烂葡萄醋酸味。",
        en = "A Basque invention marrying cheap bulk wine with fizzy cola. Old-world sommeliers would shudder, but scavengers rejoice because the heavy sugar and fizz effortlessly disguise the harsh vinegar bite of oxidized five-year-old table plonk.",
    },
    ["drink_karsk"] = {
        zh = "北欧硬核传统：杯里放一枚硬币，倒黑咖啡直到硬币隐没，再倒烈酒直到硬币重新浮现。这杯滚烫的高浓度心跳起搏器，能让你的神经瞬间紧绷，足以在齐腰深的暴风雪中甩脱变异野兽。",
        en = "Traditional Nordic wisdom requires dropping a coin into black coffee until obscured, then pouring moonshine until visible again. This boiling cardiac catapult accelerates your pulse enough to sprint through subzero snowdrifts away from ravenous predators.",
    },
    ["drink_martini"] = {
        zh = "曾经是高档鸡尾酒吧里间谍与名流的风雅标志。如今你用布满齿痕的军用水壶摇匀它，再插上一颗腌变异松果充当橄榄，靠在破沙发上假装自己的漏风避难所是蒙特卡洛的无烟赌场。",
        en = "Once the crisp emblem of secret agents and mahogany lounges. Shaken inside a dented canteen and garnished with a pickled wild pinecone, it lets you pretend your leaky storm cellar is a glamorous high-stakes casino.",
    },
    ["drink_pinacolada"] = {
        zh = "菠萝汁、浓郁椰奶与加勒比朗姆酒的热带海滩交响乐。当你身披焊接铁皮重甲、站在新英格兰冰冷的酸雨中抿上一小口时，那种阳光沙滩的虚假幻觉甚至能暂时压过身后的辐射警报。",
        en = "Pineapple, coconut cream, and sugarcane rum conjuring idyllic Caribbean beaches. Sipping this tropical dream while drenched in freezing acid sleet wearing fifty pounds of scrap metal armor is peak delusional post-apocalyptic escapism.",
    },
    ["drink_pinitacolada"] = {
        zh = "剔除了朗姆酒的椰林飘香无酒精版，纯粹的热带糖分炸弹。虽然嘴唇上会沾上一圈滑稽的白色椰奶胡子，但至少你保持了绝对的清醒——这能确保你在避难所大门被撞塌时能清晰目睹全过程。",
        en = "A virgin mocktail delivering lush tropical richness without a trace of rum. It leaves a goofy coconut mustache on your face and zero intoxication to numb the horror when barricades crumble under a zombie swarm.",
    },
    ["drink_queenmary"] = {
        zh = "往苦涩的麦芽啤酒里倒进大半勺甜腻的红石榴糖浆。它冒着粉红色的气泡，尝起来像加了碳酸的止咳糖浆；虽然毁了一罐好啤酒，但那抹艳丽的亮红色在阴暗的地道里显得格外喜庆。",
        en = "Concocted by splashing sugary grenadine into bitter lager. It looks like bubbling pink cough syrup and completely ruins honest beer, but the absurdly bright coloration provides rare festive cheer inside a murky subway tunnel.",
    },
    ["drink_royrogers"] = {
        zh = "旧世界用来哄小男孩假装自己是西部电影神枪手的无酒精饮品。把石榴糖浆灌进可乐里会引发一场惊人的血糖风暴，其提供的热量峰值甚至能支撑你一口气把一辆报废卡车推上斜坡。",
        en = "Pre-war diners served this to children who wanted to feel like heroic movie cowboys. Spiking cola with heavy grenadine triggers a colossal sugar rush capable of fueling an exhausted survivor pushing a stalled truck uphill.",
    },
    ["drink_rumcola"] = {
        zh = "跨越世纪的平民高球经典。当五年前出厂的没气可乐遇见土法蒸馏的刺鼻朗姆酒，两者产生的化学反应足以麻痹你酸痛的双腿，支撑你继续在凌晨的废墟里搜刮撬棍与螺丝钉。",
        en = "The immortal budget cocktail of dives and dormitories. Blending flat, oxidized soda with raw sugarcane hooch produces an elixir potent enough to numb your aching joints while ransacking abandoned garages at three in the morning.",
    },
    ["drink_screwdriver"] = {
        zh = "据说当年油田技工为了上班偷喝，抓起工具箱里的螺丝刀来搅拌伏特加和橙汁。在废土维修车间里，你确实只能用刚捅完丧尸脑门的十字螺丝刀来搅匀它，并附带一股淡淡的润滑油陈香。",
        en = "Born when thirsty mechanics stirred illicit liquor into citrus juice using workshop tools. In your post-apocalyptic garage, you literally stir it with a screwdriver fresh from dispatching wanderers, seasoning each sip with oxidized machine grease.",
    },
    ["drink_shirleytemple"] = {
        zh = "战前专为童星调制的粉嫩无酒精气泡水，满载着纯真与石榴糖浆。当你满脸硝烟、单手端着战术霰弹枪蹲在沙袋后小口抿着这杯亮粉色饮料时，方圆十里的狂怒掠夺者都会对你敬而远之。",
        en = "The sweet pink mocktail created for child movie stars, bursting with candied grenadine bubbles. Crouching behind sandbags clutching a riot shotgun while sipping this neon pink potion makes you look delightfully and terrifyingly unhinged.",
    },
    ["drink_strawberry_surprise"] = {
        zh = "所谓“惊喜”，在于一罐在发霉塑料桶里自然发酵的烂草莓居然没有产生致命肉毒杆菌。尽管第一口喝下去如同生吞火炭，但只要咬牙咽下前三杯，你的咽喉就会对现实彻底妥协。",
        en = "The real surprise is discovering that moldy strawberries stewing in a plastic tub did not turn into pure poison. The initial swallow scorches like battery acid, but your desensitized throat soon surrenders to sweet oblivion.",
    },
    ["drink_tequilasunrise"] = {
        zh = "沉底的深红糖浆与上层明亮橙汁层层分明，宛如加州壮美的朝阳。但在废土上，它能让你唯一联想到的破晓景观，只有地平线远处被流弹引爆的化学品仓库所升腾起的那道橙红色毒焰。",
        en = "Layered crimson and bright gold mimicking a serene California sunrise. In the wasteland, the only dawn it resembles is the noxious orange glow of a bombed ammunition depot erupting against the smoggy horizon at five in the morning.",
    },
    ["drink_virgin_mary"] = {
        zh = "去掉了伏特加的血腥玛丽，说穿了就是一碗撒了胡椒粉和盐巴的冷番茄酱。在废土上叫它鸡尾酒纯粹是为了心理安慰，但为了补充维C防止牙龈出血，装模作样地品尝调料汁也并不丢人。",
        en = "Bloody Mary shorn of its vodka soul, reducing it to cold, seasoned pasta sauce in a tumbler. Calling it a cocktail is polite fiction, but sipping spicy vegetable juice beats bleeding gums from full-blown wasteland scurvy.",
    },
    ["drink_wild_apple"] = {
        zh = "淳朴的农家苹果西打被灌入了烈性伏特加。它绝不是秋季集市上的温情甜饮，而是一剂能让你断片十二小时、醒来发现自己正和变异浣熊同挤一个睡袋的狂野毒药。",
        en = "Wholesome harvest cider violently sabotaged with unrectified vodka. This is not grandmother's cozy autumn cider, but the exact volatile fuel responsible for you blacking out and waking up sharing a sleeping bag with a mutant raccoon.",
    },
    ["drink_wsour"] = {
        zh = "威士忌的橡木辛香被柠檬酸汁与白糖驯服。即使废土上的酸味来自于酸雨灌溉出的变异野山楂，那种刺激的酸甜回味依然能让你那张经历过无数次恶战的沧桑面孔瞬间皱成一团风干咸菜。",
        en = "Charred whiskey mellowed by tart citrus and melted sugar. Even when the sour component comes from radioactive wild crabapples, the intense pucker will instantly crumple your hardened combat scowl into a remarkably sour grimace.",
    },
    ["drinking_hat"] = {
        zh = "两个易拉罐架在头盔两侧，软管直接通进嘴里，让你在双手持刀砍杀尸群时轻松补水。致命缺陷是毫无密封性——一旦你被扑倒，里面的死水就会一滴不漏地全灌进你的鼻孔。",
        en = "A ridiculous helmet harness feeding beverage directly into your mouth via rubber tubing, freeing both hands for machete combat. Its chief drawback is leaking uncontrollably into your collar whenever you dodge a lunging zombie.",
    },
    ["drive_by_wire_controls"] = {
        zh = "一套高度精密的车载电传线控系统，能让你在驾驶舱外用遥控器操控车辆。你花费数日焊装它，就是为了趴在两百米外的草丛里，像玩遥控赛车一样把重型装甲车开进丧尸窝里去开荒。",
        en = "A sophisticated fly-by-wire module allowing vehicular piloting from outside the cabin. Its supreme purpose is letting you crouch safely behind a ditch while joyriding your twenty-ton armored death machine through a howling horde like an RC car.",
    },
    ["drivebelt"] = {
        zh = "嵌有钢丝的合成橡胶三角皮带，工业动力的核心纽带。人类文明未毁于外星异形，却可能毁于摩擦力——任凭你的末日战车装了多强的引擎，一旦胶带崩断，全车都得沦为废铁。",
        en = "A heavy-duty rubber loop reinforced with steel cords, silently driving internal combustion. When this single belt snaps, your turbocharged battle rig is instantly reduced to an inert metal boulder, proving civilization bows to tensile friction.",
    },
    ["drivebelt_makeshift"] = {
        zh = "用撕烂的皮带和废弃牛仔裤布条死死缝合的权宜之计。只要发动机转速超过一千五百转，它就会发出凄惨的尖啸并在机舱里弥漫开一股焦肉味，用随时可能崩解的震颤考验你脆弱的神经。",
        en = "Improvised by braiding salvaged trouser denim with a cracked leather belt. Revving past low idle produces a piercing screech and the ominous smell of burnt cowhide, reminding you that your journey depends on frayed fabric thread.",
    },
    ["drum_percussion"] = {
        zh = "工厂量产的军用小军鼓，能敲出清脆威严的行军节拍。在死寂的废土街区，只要你不慎敲响第一下，其清脆的共鸣音就能在三十秒内把三个街区外的盲目丧尸全招募进你的个人送葬仪仗队。",
        en = "A factory-machined snare drum built for rousing military parades. Striking it in a ruined ghost town instantly summons every wandering predator within three city blocks, promptly enrolling them as honorary members of your personal funeral procession.",
    },
    ["drum_percussion_primitive"] = {
        zh = "掏空圆木并绷紧生牛皮制成的手工原始击鼓。夜晚在营火旁敲击它能鼓舞幸存者士气，但如果密林深处传来的沉重脚步声开始精准契合你的鼓点节拍，你最好立刻丢下鼓槌并拔出手枪。",
        en = "A hollowed log topped with tightly bound animal rawhide, booming with primal resonance. Playing it beside a campfire lifts survivor spirits wonderfully, until heavy footsteps from the dark tree line begin keeping perfect time with your beat.",
    },
    ["drum_skin"] = {
        zh = "一张鞣制平整、张力均匀的圆形兽皮。在乐器工匠手中它能发出悠扬的低音；但在断粮一周的避难所里，它最动人的旋律莫过于被剪成小条丢进铁锅里，炖成一碗能勉强延命的无味明胶皮冻。",
        en = "A cured, uniform disc of animal hide waiting to be mounted on a musical frame. To a starving survivor, however, its most harmonious destiny is being sliced into ribbons and boiled into a desperate pot of tasteless gelatin.",
    },
    ["dry_bag"] = {
        zh = "专为潜水和水上运动打造的卷口密封背包。无论你是在辐射酸雨中狂奔，还是被迫泅渡泛着诡异荧光的废弃下水道，它都能恪尽职守地保证你最后几盒干燥火柴和备用内裤滴水不沾。",
        en = "A rugged roll-top pack engineered for coastal divers. Even when you are forced to swim through glowing toxic drainage canals, it faithfully ensures that your last box of dry matches and spare socks remain completely untouched by sewage.",
    },
    ["dry_bag_large"] = {
        zh = "容积惊人的特大号厚塑料防水袋，常用于独木舟探险。你可以把半个超市搜刮来的饼干全倒进去；万一你在沼泽里遭遇变异水怪翻了船，紧紧抱着这个巨大的充气塑料囊还能防止你沉底溺亡。",
        en = "A gargantuan waterproof sack built for whitewater expeditions. It easily swallows an entire grocery store aisle, and should swamp horrors capsize your canoe, this massive buoyant capsule doubles as an emergency life raft to keep you afloat.",
    },
    ["dry_barley_stalks"] = {
        zh = "一捆晒干的金黄大麦秸秆。农场里的牛羊看到它会欢呼雀跃，而人类要想享用它，就得费尽心机去脱粒、磨粉并酿造成啤酒。人类文明的全部骄傲，大抵就体现在绝不肯像牲口一样生嚼草秆。",
        en = "A golden sheaf of sun-dried barley. While cattle happily munch the raw straw, human survivors must thresh, winnow, and ferment it for weeks, proving that civilization is entirely defined by refusing to graze like livestock.",
    },
    ["dry_beans"] = {
        zh = "坚硬如卵石的脱水大白芸豆。直接干嚼会磕碎智齿，但泡水慢炖后就是救命的植物蛋白。唯一的战术禁忌：严禁在密闭防空洞里多吃，其消化尾气的杀伤力甚至超过了芥子气。",
        en = "Rock-hard dehydrated northern beans. Chewing them dry will shatter teeth, but boiling them yields vital survival protein. Just refrain from eating them inside a sealed bunker, where the resulting digestive emissions pose a lethal asphyxiation hazard.",
    },
    ["dry_bottle_gourd"] = {
        zh = "远古先民跨越白令海峡时携带的古老容器。晒干掏空后就是天然的水密水壶。腰间挎着它在废土漫步颇有隐士风范——只要别人能假装没看见你背上的那杆突击步枪。",
        en = "Carried across the frozen Bering Strait by prehistoric nomads, this hollow dried squash forms an immortal canteen. Wearing one lends an air of ancient wilderness mastery, slightly compromised by the assault rifle strapped across your shoulder.",
    },
    ["dry_buckwheat_stalks"] = {
        zh = "一堆带棱角种子的干枯荞麦秸秆。除非你长了四个能消化粗纤维的牛胃，否则就得拿着木棍在泥地上拼命敲打半天，才能从灰尘中筛出一捧能煮成黑褐色粗粮糊糊的坚硬谷粒。",
        en = "A tangled bundle of desiccated buckwheat stems. Unless blessed with four bovine stomachs, you must spend an exhausting afternoon thrashing it against dirt with a stick just to harvest a handful of dark, gritty porridge grain.",
    },
    ["dry_canola_stalks"] = {
        zh = "脆硬干燥的油菜秸秆，豆荚一碰就会爆裂。耐心脱粒后能压榨出宝贵的照明灯油和生物燃料；但若是在风口脱粒时不小心打了个喷嚏，你这周仅有的夜间光源就会伴随狂风散落进荒草丛。",
        en = "Brittle dried brassica stalks concealing tiny, oil-dense seeds. Threshing them provides lamp fuel and crude biodiesel, though an ill-timed sneeze in the wasteland breeze will permanently scatter your evening lighting budget into the weeds.",
    },
    ["dry_chili"] = {
        zh = "干瘪发皱的暗红色辣椒，浓缩了灼热的纯粹痛觉。整颗干嚼会让你涕泪横流并痛悔人生，但磨成粉末撒进炖锅，就能把寡淡发酸的变异植物根茎伪装成一顿热气腾腾的末日川味火锅。",
        en = "A wrinkly pod of concentrated capsaicin malice. Chewing it raw brings immediate tears and deep regret, but grinding it into broth magically transforms bland, bitter mutant roots into a tolerable simulation of hot spicy stew.",
    },
    ["dry_corn"] = {
        zh = "金黄结实的脱水玉米粒。你可以把它们当种子播种在温室里，或者磨成玉米糁煮糊；而在最无聊的守夜时光里，把一把玉米粒扔进滚烫的柴油机排气管上，还能换来几朵焦香的微型爆米花。",
        en = "Hard golden kernels loaded with post-apocalyptic potential. You can sow them for future harvests, grind them into meal, or toss a handful onto a scorching engine block to enjoy an impromptu, surprisingly cheerful popcorn snack.",
    },
    ["dry_duffelbag"] = {
        zh = "容积堪比衣柜的巨型防水圆筒包，密封后扔进水里甚至能像充气救生艇一样漂浮。唯一的缺点是毁灭性的累赘度——背着它逃跑时，你的机动性基本等同于一只在沙滩上蹒跚挪动的充气海象。",
        en = "A colossal watertight duffel that doubles as a flotation raft when sealed. The trade-off is staggering encumbrance: running while wearing this monstrosity reduces your combat mobility to that of an exhausted, overstuffed walrus on land.",
    },
    ["dry_fish"] = {
        zh = "经过脱水风干加工的半透明硬质干鱼片。虽然闻起来有一股浓烈刺鼻的鱼腥风味，但只要密封保存在干燥罐子里，能存放几年不变质，丢进开水锅里就能煮出一锅鲜汤。",
        en = "Crisp dehydrated fish flakes preserved through hot-air drying. Smelling intensely briny, storing them in sealed jars ensures high-protein rations that simmer into savory broths years later.",
    },
    ["dry_froglegs"] = {
        zh = "脱水风干的一对青蛙后腿，干瘪蜷缩的外形活像某种微型外星异形的干尸。只要扔进煮沸的雨水里咕嘟半小时，它就会奇迹般地舒展开来，并提供一份保质期长到跨越世代的沼泽鸡肉风味。",
        en = "A desiccated pair of amphibian limbs looking suspiciously like mummified alien hands. Boiled in rainwater for twenty minutes, they hydrate into a surprisingly tender swamp delicacy that stubbornly refuses to expire across decades of fallout.",
    },
    ["dry_fruit"] = {
        zh = "脱去水分但锁死糖分的干果薄片。在旧世界这只是办公室抽屉里的健康零嘴，但在充斥着变质军粮和老鼠肉的废土上，这一把金黄甜美的果脯就是能让强盗放下猎枪与你和平交易的顶级硬通货。",
        en = "Paper-thin dried fruit slices retaining intense natural sugars. Once a mundane office desk snack, in a world dominated by stale rations and grilled rodent, these sweet golden flakes hold enough barter value to negotiate truces.",
    },
    ["dry_garlic"] = {
        zh = "干燥脱水的大蒜瓣。直接啃食会像吞下烙铁般灼烧食道，并让你呼出足以击晕丧尸的口臭；但只要将其碾碎成粉洒进烤肉，无论多么腥臊恶臭的野生变异怪物肉都会被强行赋予家常风味。",
        en = "Shriveled cloves packed with intense, dormant sulfur. Chewing one raw scorches your throat and generates breath foul enough to stun wildlife, yet grinding it into powder makes even the gnarliest mutant roadkill taste like dinner.",
    },
    ["dry_lentil_stalks"] = {
        zh = "田野里自然干枯的短小扁豆秸秆，豆荚在微风中像小沙锤一样沙沙作响。采收它们无需任何工具，但要把那些比跳蚤大不了多少的小扁豆全部从豆荚里抖落出来，会耗尽你仅存的所有耐心。",
        en = "Short, brittle field stalks with pods rattling like tiny maracas in the wind. Gathering them takes zero effort, but meticulously shelling thousands of flea-sized legumes will utterly shred whatever patience you have remaining.",
    },
    ["dry_lentils"] = {
        zh = "扁平如鹅卵石的古老豆类。法老陵墓建造者吃它，中世纪灾民吃它，如今蹲在废墟里煮它的依然是你。帝国与科技皆成灰烬，唯有这锅扁豆汤始终在人类的铁锅里翻滚。",
        en = "Tiny, pebble-like legumes that sustained Egyptian laborers, Roman legionaries, and medieval peasants. Modern civilization lies in smoking ruins, yet here you sit beside a trash fire, stirring the exact same indestructible lentil soup.",
    },
    ["dry_lobster"] = {
        zh = "经过真空冻干处理的昂贵野生龙虾肉碎干。在旧世界堪称高档海鲜大餐的代表，如今撕开包装直接当咸味零食咀嚼，浓缩的鲜美海味在唇齿间迸发出令人感动的回甘。",
        en = "Freeze-dried morsels of premium claw and tail lobster meat. Once the crowning glory of seaside gourmet restaurants, chewing the crunchy savory pieces dry provides a decadent protein luxury.",
    },
    ["dry_meat"] = {
        zh = "干燥坚韧得宛如旧卡车轮胎皮的脱水肉片。每一口都需要你调动整排槽牙奋力撕咬咀嚼十五分钟；虽然下咽过程如同吞下一把木屑，但其坚挺的保质期足以确保在你饿死之前肉块绝不会先坏。",
        en = "Strips of cured flesh dehydrated to the structural resilience of vulcanized truck tires. Each bite demands fifteen minutes of relentless jaw exercise, but its indefinite shelf life guarantees it will patiently outlive your remaining teeth.",
    },
    ["dry_meat_tainted"] = {
        zh = "精心脱水风干的感染肉干；虽然去除了所有水分并保证永不腐坏，但这只是让你拥有了一块能在三十年后依然精准毒死你的丧尸肉干。",
        en = "Meticulously dehydrated tainted jerky; removing every drop of moisture prevents spoilage, successfully ensuring this toxic slab of zombie flesh can still poison you just as efficiently thirty years from now.",
    },
    ["dry_mollusk"] = {
        zh = "晒干脱水保存的野生螺肉与贝肉干块。质地坚硬得如同小石子，丢在嘴里当口香糖咀嚼能耐嚼一整个下午，丢入野外杂烩汤里慢慢炖煮更能煮出奶白浓稠的鲜美汤汁。",
        en = "Rock-hard dried mollusk meat preserved through traditional air dehydration. Chewing a single nugget occupies your jaw for hours, while simmering it in bone broth releases rich oceanic minerals.",
    },
    ["dry_mushroom"] = {
        zh = "脱水烘烤后的干蘑菇；外表硬得像陈年树皮，但在用浑浊雨水泡发后，它能给那锅毫无油水的浆糊汤带来一丝战前米其林餐厅般的虚妄尊严。",
        en = "Shriveled into tough woody flakes, dried mushrooms look like ancient bark until soaked in boiled rainwater, lending your greasy survival slop an absurd illusion of pre-cataclysm fine dining.",
    },
    ["dry_oat_stalks"] = {
        zh = "一捆干燥的燕麦穗；在末日里你得花上整整一个下午用木棒狠命捶打脱粒，才能换来几勺粗糙的燕麦，并深刻体会到战前收割机是多么伟大的发明。",
        en = "A bundle of brittle oat stalks; you must spend half an afternoon flailing them with a stick just to harvest enough grain for watery porridge, gaining immense newfound respect for combine harvesters.",
    },
    ["dry_poultry"] = {
        zh = "口感宛如硬纸板的脱水禽肉干；虽然吃起来毫无汁水且像在嚼木屑，但其惊人的保质期意味着它极有可能比你、避难所乃至整个人类文明活得还要长久。",
        en = "Cardboard-textured dehydrated chicken flakes; completely devoid of moisture and tasting remarkably like salted wood chips, yet possessing an incredible shelf life destined to outlast you, your bunker, and human civilization.",
    },
    ["dry_rice"] = {
        zh = "干燥坚硬的长粒米；直接生啃能崩断幸存者仅剩的臼齿，但只要你奢侈地拥有宝贵的净水与柴火将其煮熟，你就是避难所废墟里最富有体面的人。",
        en = "Rock-hard grains of uncooked rice; chewing them raw will shatter your remaining molars, but if you possess enough clean water and firewood to boil them, you live like post-apocalyptic royalty.",
    },
    ["dry_seaweed"] = {
        zh = "一小块干枯蜷缩的海藻；散发着变异海滩与腐烂盐碱的怪味，不可食用连黑心商人都不收，唯一的宿命就是作为引火物在篝火里冒出一股咸涩的浓烟。",
        en = "A shriveled scrap of desiccated seaweed; smelling intensely of brine and mutated tidepools, traders refuse to touch it, leaving its finest post-apocalyptic calling as pungent tinder for a campfire.",
    },
    ["dry_seaweed_pile"] = {
        zh = "好大一堆恶臭的干海藻；虽然坚韧有毒无法下咽，但堆在一起足以点燃一场浓烟滚滚的篝火，向那些早就不复存在的救援直升机绝望地发送求救信号。",
        en = "A substantial heap of leathery dried seaweed; entirely inedible and mildly toxic, yet bulky enough to fuel a smoky bonfire signaling desperately for rescue helicopters that stopped flying years ago.",
    },
    ["dry_soybean"] = {
        zh = "坚如鹅卵石的干大豆；情急之下完全可以装进弹弓充当打怪弹丸，或者花费两个小时珍贵的柴火把它炖烂，体验植物蛋白在舌尖引发的漫长腹胀。",
        en = "Pebble-hard dried soybeans; durable enough to serve as makeshift slingshot pellets during ambushes, or simmered over precious firewood for hours to reward you with plant protein and immense flatulence.",
    },
    ["dry_tofu"] = {
        zh = "真空密封的脱水豆腐；脱水后硬邦邦地像一块建筑隔音海绵，但只要放进沸水里，它就能毫无怨言地彻底吸收你搜集来的任何变异泥浆汤风味。",
        en = "Sealed blocks of dehydrated tofu; dense and rigid like packing foam until rehydrated, when it loyally absorbs the questionable essence of whatever muddy puddle water you managed to boil.",
    },
    ["dry_veggy"] = {
        zh = "脱水烘干的混合绿色脱水蔬菜碎屑。虽然失去了新鲜蔬菜脆嫩多汁的口感，但泡开后依然能提供维持生命所需的珍贵叶绿素与维生素，是野外远征防烂嘴角的法宝。",
        en = "Brittle flakes of mixed dehydrated vegetables and leafy greens. Rehydrating in hot water, they supply critical micronutrients and vitamins that prevent scurvy during endless canned-meat diets.",
    },
    ["dry_veggy_tainted"] = {
        zh = "经过烘烤脱水处理的异界变异真菌干燥肉块。虽然干燥阻止了孢子在罐子里发芽扩散，但散发出的怪异荧光与金属化学味，依然时刻提醒着食用者潜在的变异风险。",
        en = "Dehydrated alien mushroom chunks preserved to prevent rampant spore germination. Though biologically inert, their faint purple glow and chemical aroma warn travelers of unpredictable mutagenic risks.",
    },
    ["dry_wheat_stalks"] = {
        zh = "一捆干燥的小麦麦穗；看起来充满了田园诗般的浪漫，直到你不得不亲手捶打脱粒、扬谷吹壳、用石块碾成碎粉，才能在灰烬里烤出一块硌牙的面饼。",
        en = "A sheaf of golden dried wheat stalks; looking deceptively pastoral until you realize you must manually thresh, winnow, grind the grain with rocks, and bake ash-cakes just to have breakfast.",
    },
    ["dry_wild_rice"] = {
        zh = "从沼泽边缘冒险收割的干野生米；烹饪后是香气浓郁的黑色谷物粥，但要是缺乏燃料试图硬吞，它的坚硬程度绝对能给你的牙齿上一堂生动的物理课。",
        en = "Dry wild rice scavenged from murky wetlands; delightfully nutty when patiently boiled into dark porridge, yet unforgivingly hard enough to teach your fillings a harsh physics lesson if chewed raw.",
    },
    ["dry_wild_rice_stalks"] = {
        zh = "一扎从变异泥沼里拖回来的干野生稻穗；杂乱枯黄，在你忍着冻疮脱粒半天只掉出几小撮米粒时，你会忍不住怀疑自己冒着被水怪咬死的风险是否值得。",
        en = "A tangled sheaf of dried marsh rice stalks; threshing them in the cold produces a tiny handful of dark grains, prompting deep regret over wading through zombie-infested bogs to gather them.",
    },
    ["dry_winter_wheat_stalks"] = {
        zh = "顶着严寒积雪顽强成熟的干冬小麦穗；好不容易扛过了漫长的寒冬，最终的下场却是被饥肠辘辘的幸存者扔在地板上，用棒球棍凶狠地狂砸脱粒。",
        en = "Resilient stalks of dried winter wheat; having miraculously survived frost and radioactive blizzards, their triumphant reward is being smashed furiously against concrete by a starving survivor swinging a baseball bat.",
    },
    ["duct_tape"] = {
        zh = "这种万能胶带最初由强生公司在二战期间研发，用棉质鸭帆布配橡胶粘合剂为弹药箱防水。在末世它成了真正的神迹：修枪、封窗、止血、闭嘴，全宇宙唯有缺乏胶带解决不了的工程学灾难。",
        en = "Originally developed during World War II using durable cotton duck cloth to waterproof military ammunition cases, this miracle adhesive holds the entire apocalypse together. If it moves and shouldn't, use tape; if it doesn't move and should, find a crowbar.",
    },
    ["duffelbag"] = {
        zh = "厚重粗糙的帆布行李袋；容量确实惊人，能塞进你搜刮来的全部家当，但也让背着它逃命的你看起来像一只背着沉重水泥圆筒、随时会被丧尸追上的笨龟。",
        en = "A rugged canvas duffel bag; capable of swallowing half an abandoned supermarket, though fleeing swift predators while hauling it makes you resemble an overburdened tortoise dragging an awkward cylinder of lead.",
    },
    ["duffelbag_gym_l"] = {
        zh = "大号弹力织物运动包；曾经用来装拳套与蛋白粉摇摇杯，如今里面塞满了生锈的蓄电池与燃烧瓶，让你在废土奔波中被动完成了最硬核的全身力量举训练。",
        en = "A large synthetic gym bag; once carrying fresh sweatbands and whey protein, now overloaded with rusted lead batteries and pipe bombs, giving you the most punishing unintentional workout of your life.",
    },
    ["duffelbag_gym_m"] = {
        zh = "中号运动包；旧时代刚好装下一双跑鞋与干毛巾，如今塞满了脏绷带和狗粮罐头，散发着潮湿更衣室与末日绝望混合的复杂气味。",
        en = "A medium gym bag; once holding clean sneakers and a towel, it now carries stained bandages and canned pet food, retaining an aroma of locker rooms and sheer desperation.",
    },
    ["duffelbag_gym_s"] = {
        zh = "小号运动包；设计初衷是晨间去健身房快走，在灾变后却成了逃亡腰包，刚好塞下一盒手枪弹药和两双干袜子，随着亡命狂奔在屁股上拼命晃荡。",
        en = "A small gym bag; originally tailored for light cardio sessions, now drafted into high-stakes courier duty, bouncing frantically on your hip while packed with handgun ammunition and dry socks.",
    },
    ["duffelbag_gym_xl"] = {
        zh = "十五升超大容量运动包；如果你真把它塞满搜刮来的战利品，你这辈子都不用去健身房了，因为仅凭双腿站起来就需要避难所的液压千斤顶协助。",
        en = "A colossal fifteen-liter gym bag; stuffing this cavernous pouch with scavenged loot guarantees you will never need a fitness membership again, as standing upright demands sheer hydraulic willpower.",
    },
    ["duffelbag_gym_xs"] = {
        zh = "轻便小巧的运动提包；容量小得连半支步枪都装不下，但正好够你揣上两罐能量饮料假装只是在郊区散步，直到一只变异丧尸犬打破这片宁静。",
        en = "An ultralight compact gym bag; far too small for hauling serious armaments, yet perfectly sized for carrying emergency snacks while pretending you are merely enjoying a brisk suburban jog.",
    },
    ["duffelbag_gym_xxs"] = {
        zh = "迷你袖珍运动包；基本上就是个印着健身品牌商标的大号笔袋，既装不下撬棍也塞不进枪支，唯一的优点是能让私藏的巧克力棒享受防雨待遇。",
        en = "A miniature gym pouch; practically a glorified pencil case with athletic branding, incapable of carrying crowbars or firearms, though perfectly suited to keeping precious hoarded chocolate bars dry.",
    },
    ["duffelbag_l_poly"] = {
        zh = "大号弹力面料行李袋；虽然能装下废弃便利店里的半个货架，但带来的严重负重阻碍会逼你在抛弃珍贵物资与被瘸腿丧尸追上之间做出痛苦抉择。",
        en = "A large synthetic duffel bag; capable of swallowing half a convenience store shelf, though its severe encumbrance forces a grim calculation between ditching hard-won provisions or being caught by slow zombies.",
    },
    ["duffelbag_xl_nylon"] = {
        zh = "超大号抗撕裂尼龙行李袋；结实到在碎石路上拖拽都不会破损，但将它背在身上的那一刻，你的敏捷度就会瞬间暴跌得如同陷入深海泥潭。",
        en = "An oversized ripstop nylon duffel; tough enough to endure endless scraping across gravel ruins, yet wearing it instantly reduces your sprint to a sluggish crawl that no body armor can redeem.",
    },
    ["dump_pouch"] = {
        zh = "快速收纳织带袋；战术手册说它用于在交火中迅速丢弃空弹匣，但在实际末日生活里，它主要被幸存者用来疯狂抓取野莓果、亮晶晶的瓶盖与生锈螺丝。",
        en = "A tactical dump pouch; designed for clearing empty rifle magazines mid-firefight, yet in grim reality, survivors primarily use it to hastily stash wild blackberries, shiny bottlecaps, and loose screws.",
    },
    ["duster"] = {
        zh = "粗帆布防尘风衣；穿上它能瞬间让你拥有废土孤胆枪手的苍凉气质，更妙的是哪怕你日后变异出软体动物的腹足或触手，这件宽松大衣依然合身。",
        en = "A rugged canvas duster; instantly granting you the brooding swagger of a wasteland gunslinger, with the added evolutionary perk of accommodating snail feet or leg tentacles should mutations strike.",
    },
    ["duster_faux_fur"] = {
        zh = "厚重的人造毛皮长风衣；三十米开外看起来像尊贵的废土军阀，但一旦遭遇酸雨淋湿，就会散发出如同浸水晴纶地毯般的刺鼻怪味。",
        en = "A thick faux fur duster; projecting warlord glamour from thirty yards away, right until acidic rainfall drenching the synthetic pile turns you into a shivering, chemical-scented soggy carpet.",
    },
    ["duster_fur"] = {
        zh = "变异野兽皮毛缝制的厚风衣；在核冬天的凛冽刺骨中无比温暖，但强烈的原始野兽气味会让五公里内的野生食肉动物以为是一顿行走的午餐正在向它们靠近。",
        en = "A heavy genuine fur duster; delightfully cozy against nuclear winter frosts, though its pungent primal scent convinces every ravenous predator within five miles that lunch has graciously walked to them.",
    },
    ["duster_leather"] = {
        zh = "厚实的黑色皮革长风衣；既能抵御酸雨又能防范小抓伤，造型帅气冷酷，唯一的缺点是盛夏穿它宛如随身背着便携式桑拿房，能把幸存者活活闷熟。",
        en = "A rugged leather duster; deflecting light zombie claws and acid rain with effortless post-apocalyptic cool, though during summer heatwaves it functions primarily as a wearable, self-basting personal sauna.",
    },
    ["dutch_oven"] = {
        zh = "配有凹陷厚重铸铁锅盖的经典野营荷兰烤锅。放在炭火堆上不仅能炖汤煎肉，在锅盖上堆满滚烫红炭更能直接烘烤出表皮金黄酥脆的烤面包，堪称全能烹饪神器。",
        en = "A heavy cast-iron dutch oven fitted with a flanged rimmed lid. Heaped with glowing coals above and below, it roasts joints of wild venison and bakes sourdough loaves to crusty perfection.",
    },
    ["dye_powder"] = {
        zh = "一包色彩鲜艳的布匹染料粉末；当丧尸在防空洞门外疯狂挠门时，你却决定用宝贵的净水把破烂帆布裤染成亮紫色，这种对时尚的执念简直令人肃然起敬。",
        en = "A handful of cloth dye powder; because when undead hordes claw at your bunker blast doors, spending scarce potable water to dye your shredded canvas trousers neon violet is the ultimate statement of defiance.",
    },
    ["dynamite"] = {
        zh = "捆绑着引信的烈性炸药棒；废土上解决顽固铁门、塌方坑道与巨型甲虫的终极谈判工具，前提是你在被怪物扑倒前能用颤抖的手摸出打火机。",
        en = "Sticks of dynamite bundled with a fuse; the ultimate wasteland diplomacy tool for jammed steel vaults, collapsed mines, and armored horrors, provided your trembling fingers locate matches in time.",
    },
    ["dynamite_act"] = {
        zh = "引信嘶嘶冒火的激活炸药；此时绝不是欣赏绚丽火花或反思人生的时刻——把它狠狠扔出去，否则你的剩余寿命将直接以毫秒为单位倒计时。",
        en = "A hissing stick of active dynamite; this is distinctly not the moment to admire pretty sparks or contemplate life choices—throw it immediately, or your lifespan expires in milliseconds.",
    },
    ["dynamite_bomb"] = {
        zh = "塞满破片钢珠的简易炸药炸弹；粗暴地将工业爆破升级为无差别破片杀伤，一旦点燃，你对安全的唯一定义就是能在爆炸前狂奔出多远。",
        en = "Dynamite packed into a steel shrapnel casing; crudely upgrading industrial demolition into horrific fragmentation slaughter, where your only measure of safety is how fast your boots can sprint away.",
    },
    ["dynamite_bomb_act"] = {
        zh = "引信飞速缩短的激活炸药炸弹；如果你还没把它扔到厚混凝土墙后面，那你马上就要作为人体靶标，向周围展示破片动能守恒定律的生动案例。",
        en = "A hissing steel fragmentation bomb ticking down; if you haven't hurled it behind reinforced concrete already, you are mere seconds away from serving as an unwilling physics demonstration of blast shrapnel.",
    },
    ["e_handcuffs"] = {
        zh = "刺耳鸣响的高科技电子手铐；警报器不知疲倦地呼叫警察，并对挣扎者施加电击。遗憾的是，如今唯一可能循声赶来的警员全都是流着涎水想啃你脑子的丧尸警察。",
        en = "High-tech electronic handcuffs screaming shrill alarms while shocking your wrists; unfortunately, the only responding officers in the apocalypse are rotting zombie patrols interested strictly in devouring your brain.",
    },
    ["e_scrap"] = {
        zh = "废旧电路板上拆下的一堆电容与电阻；在普通拾荒者眼里这是不能吃的破烂，但在电气电工手里，它们能变戏法般组合成让丧尸骨肉分离的高压电击陷阱。",
        en = "A tangle of salvaged capacitors, resistors, and diodes; utterly useless to starving survivors, yet treated as sacred treasure by wasteland electricians building electrified perimeter traps to fry approaching hordes.",
    },
    ["e_tool"] = {
        zh = "结实的多功能折叠工兵铲；不仅能挖战壕、砍干柴，还能架在余烬上煎蛋，并在丧尸靠得太近时利落地削下它的脑袋，堪称废土近战与园艺全能神兵。",
        en = "A stout military folding shovel; trench digger, wood chopper, makeshift campfire skillet, and zombie decapitation blade all rolled into one indispensable, mud-caked steel package.",
    },
    ["ear_plugs"] = {
        zh = "工业级降噪防噪耳塞；能完美隔绝怪物的刺耳嘶吼与霰弹枪的震耳轰鸣，让你在避难所里享受婴儿般的香甜睡眠，直到一只变异猎手温柔地拍了拍你的肩膀。",
        en = "Industrial-grade foam earplugs; effectively muffling deafening shotgun blasts and unholy mutant shrieks, allowing you to sleep like a baby right up until a feral stalker taps you politely on the shoulder.",
    },
    ["ear_spool"] = {
        zh = "彰显叛逆个性的耳扩耳钉；在旧时代是前卫朋克青年的潮流标志，但在废土肉搏战中，它最主要的功能是为近身扑咬的丧尸提供一个绝佳的挂钩抓手。",
        en = "A chunky decorative ear spool; once the pinnacle of alternative youth fashion, now practically serving as a convenient, finger-sized grappling hook for leaping zombies to latch onto your head.",
    },
    ["earthworm"] = {
        zh = "一条在泥土里疯狂扭动的湿滑蚯蚓；看起来恶心至极且泥腥扑鼻，但在断粮三天的绝境下，这团扭动的无脊椎动物蛋白就是世界上最珍贵的救命圣餐。",
        en = "A wriggling, slimy earthworm dug from damp soil; utterly revolting to look at, yet transformed into five-star survival sustenance the exact moment starvation overrides your gag reflex.",
    },
    ["earthworm_boiled"] = {
        zh = "清水煮过的一小把蚯蚓；焯水去掉了泥沙杂质，却留下了橡胶般的灰暗口感与无法抹去的土腥味，每一口都在提醒你人类文明究竟堕落到了何种地步。",
        en = "A gray handful of boiled earthworms; parboiling washes away the grit, leaving behind rubbery, earthy noodles that forcefully remind you how far human cuisine has fallen since the cataclysm.",
    },
    ["earthworm_dried"] = {
        zh = "烘干研磨后的脱水蚯蚓干；脱水消除了令人不适的黏腻触感，只要你闭着眼睛一口吞下，就可以催眠自己正在享用某种高档的战前浓缩昆虫蛋白粉。",
        en = "Crunchy dried and ground earthworms; dehydration completely eliminates the disgusting slime, allowing you to close your eyes and pretend you are consuming expensive artisan protein powder instead of dirt-dwelling invertebrates.",
    },
    ["earthworm_fried"] = {
        zh = "用珍贵食盐煎炸至焦黄的油炸蚯蚓；油脂赋予了它嘎嘣脆的口感，只要不去深究它的前身，它甚至能让你产生在战前酒吧享用炸薯条的荒诞错觉。",
        en = "Salted and pan-fried earthworms; sizzling in rendered fat gives them a surprisingly crisp texture, serving as the nearest apocalyptic substitute for greasy bar snacks you are ever likely to find.",
    },
    ["earthworm_handful"] = {
        zh = "一整把湿冷蠕动的活蚯蚓；在手指缝隙间拼命挣扎扭动，对钓鱼爱好者来说是满分鱼饵，对弹尽粮绝的求生者来说则是令人反胃却又舍不得扔的活命资本。",
        en = "A squirming handful of slimy live earthworms; writhing frantically between your fingers, representing either prime freshwater fishing bait or a gut-wrenching emergency protein ration you cannot afford to waste.",
    },
    ["eboshi"] = {
        zh = "传统的黑色尖顶神道教乌帽；虽然在面对丧尸扑咬时无法提供哪怕一点防护，但戴上它至少能让你在废墟里看起来像一位随时准备做法驱邪的落魄大祭司。",
        en = "A tall black Shinto ceremonial cap; offering zero ballistic protection against charging horrors, though roaming restless spirits might just hesitate, mistaking you for a severely underpaid visiting exorcist.",
    },
    ["ecig"] = {
        zh = "一次性电池供电的电子香烟；虽然整个人类文明都已化为灰烬，但你依然可以在酸雨中吸出一口草莓西瓜味的尼古丁烟雾，享受这毫无意义的化学慰藉。",
        en = "A disposable battery-operated electronic cigarette; society may have burned to ash, but you can still exhale sweet strawberry-watermelon vapor in the acid rain, indulging pre-apocalyptic nicotine dependency.",
    },
    ["eclipse_glasses"] = {
        zh = "纸框铝箔日食眼镜；原本为了让人类安全仰望日食奇观而设计，如今流落废土，最实用的场合大概是直视远方核弹爆炸或等离子聚变反应堆时护住眼角膜。",
        en = "Cardboard-framed eclipse glasses with protective aluminum coating; originally engineered for safely observing rare solar events, now equally adept at shielding your corneas when distant nuclear detonations illuminate the horizon.",
    },
    ["edamame_roasted"] = {
        zh = "烘烤得香脆微咸的一把毛豆；吃起来口齿留香，剥豆入口的节奏能让你暂时忘掉周围游荡的丧尸，仿佛自己还坐在街角那个早已化作焦土的居酒屋里。",
        en = "A warm handful of salty roasted edamame; delightfully crunchy and fragrant, popping them into your mouth creates a fleeting, beautiful illusion that your favorite neighborhood tavern is still open for business.",
    },
    ["effective_emitter"] = {
        zh = "精密调校的高效能量发射器组件；优化了高能武器的放电脉冲周期，让你在用激光步枪轰散变异怪物时能节省宝贵的电池电量，实现节能环保型末日屠戮。",
        en = "A precision electronic emitter mod; optimizing weapon energy discharge cycles so your laser rifle sips battery cells conservatively, allowing you to disintegrate mutant terrors on a strict energy budget.",
    },
    ["efile_junk"] = {
        zh = "储存在生锈U盘里的一堆毫无意义的损坏电子乱码数据碎片。可能是战前某人的垃圾邮件回收站，也可能是系统崩溃遗留的临时日志，翻看半天除了浪费电池毫无收获。",
        en = "A corrupted heap of fragmented digital gibberish stored on a flash drive. Sifting through its scrambled sectors reveals only broken temporary cache files, wasting precious handheld battery life.",
    },
    ["efile_lore"] = {
        zh = "一份侥幸完整读取出来的旧时代可疑多媒体音频文件。录音里夹杂着实验员惊恐的喘息、警报长鸣与异界怪物的低沉咆哮，揭示了大灾变爆发前夜冰山一角的黑暗秘密。",
        en = "A salvaged multimedia recording containing frantic researcher audio and echoing containment sirens. Listening through static reveals chilling eyewitness whispers from the terrifying eve of the cataclysm.",
    },
    ["efile_map"] = {
        zh = "从废弃车载导航仪中导出的周边地形离线地图缓存数据。详细标注了附近的变电站、地下净水厂以及废弃采石场位置，让你的避难所选址与行军路线变得胸有成竹。",
        en = "A cached offline GIS cartographic database retrieved from automotive GPS units. Outlining regional substations, secondary access roads, and water reservoirs, it makes tactical route planning effortless.",
    },
    ["efile_photos"] = {
        zh = "保存在存储卡里的整套高清家庭生活与风景摄影相册。照片里那些沐浴在阳光下欢笑的父母、孩童与摇尾巴的金毛犬，在末日阴云下看一眼便能让人心痛得无法呼吸。",
        en = "A digital photo gallery displaying sunlit birthday parties, laughing children, and frolicking golden retrievers. Looking at these frozen glimpses of paradise brings profound, aching melancholy.",
    },
    ["efile_recipes"] = {
        zh = "整理归档的各种电子版工坊蓝图、PDF手册与机械维修图纸库。里面详尽记载了如何用废铜烂铁组装自制发电机与风车，是废土工程师重建工业文明的宝贵指南针。",
        en = "A curated library of technical manuals, machinery blueprints, and workshop guides. Detailing how to improvise wind generators and mechanical latches, it serves as an engineer's survival Bible.",
    },
    ["efile_recipes_medical"] = {
        zh = "从医院总服务器复制提取的应急野战外科与药物合成配方数据库。手把手教你如何在缺乏无菌手术室的环境下提纯抗生素与自制止血粉，每一行代码都关系着生死。",
        en = "A clinical archive detailing emergency surgical procedures and field pharmacology recipes. Teaching wanderers to synthesize crude antiseptics and stitch deep wounds, it saves lives daily.",
    },
    ["efile_recipes_science"] = {
        zh = "涵盖了高能物理、合成化学与材料工程的顶级前沿科研文献库。复杂的分子化学式与热力学公式让人眼花缭乱，是打造高科技电磁武器与能量护盾的核心理论蓝图。",
        en = "An advanced technical compendium covering synthetic chemistry, physics, and metallurgy. Its complex equations unlock the secrets for manufacturing high-yield energy cells and railgun components.",
    },
    ["egg_antlion"] = {
        zh = "一枚圆滚滚、外壳坚硬得如同白瓷卵石的巨型蚁蛉卵。拿在手里沉甸甸的，外壳坚韧防磕碰，打破坚硬的钙质壳倒进铁锅煎熟，能提供足足相当于三枚鸡蛋的浓厚蛋白质。",
        en = "A large spherical antlion egg sporting a porcelain-hard calcified outer shell. Cracking its stubborn armor over a skillet yields dense, protein-packed yolk equivalent to three chicken eggs.",
    },
    ["egg_bird_unfert"] = {
        zh = "一枚未受精的健康野生鸟蛋。蛋壳光洁无瑕且内部绝无血丝胚胎，直接磕开生吞滑嫩清爽，丢进烧开的菜叶野草汤里打散更是能煮出一碗香气四溢的美味蛋花汤。",
        en = "A clean, unfertilized wild bird egg gathered from high tree canopies. Free of developing embryos, whipping it into boiling nettle broth creates a velvety, nutrient-dense egg drop soup.",
    },
    ["egg_blackfish"] = {
        zh = "从黑鱼体内完整剥离的一大捧细密发亮的黑色野生鱼卵。富含丰富的不饱和脂肪酸与鱼油香味，用细盐稍微腌制后抹在烤鱼片上吃，是河畔拾荒者最难得的天然营养补品。",
        en = "Glistening clusters of dark fish roe harvested from river blackfish. Packed with omega oils, lightly salting them over smoked fillets produces an exceptionally savory riverside delicacy.",
    },
    ["egg_bluefin_tuna"] = {
        zh = "极其罕见的变异蓝鳍金枪鱼大块饱满鲜美鱼卵。在旧世界这是只有顶级日料店才能供应的珍馐美味，如今在避难所篝火旁拿树枝串着烤熟，浓郁的油脂香气令人陶醉。",
        en = "Massive plump roe sacks harvested from deep-sea bluefin tuna carcasses. Once an ultra-luxury delicacy reserved for elite sushi bars, roasting them over embers fills camps with mouthwatering aroma.",
    },
    ["egg_bluefish"] = {
        zh = "成串晶莹剔透的蓝鱼野生鱼子。带着大海特有的微咸潮汐气息，丢进开水锅里煮熟后颗粒分明且极具爆浆口感，是长期食用单一干瘪口粮后唤醒味蕾的绝佳海产。",
        en = "Translucent amber clusters of wild bluefish roe. Simmering them gently in sea brine pops each tiny sphere across the palate with refreshing marine juices, reviving tired tastebuds.",
    },
    ["egg_bluegill"] = {
        zh = "从淡水蓝鳃太阳鱼腹中采收的细小金黄色鱼卵簇。虽然单颗个头不大，但聚在一起足有一大勺，拌上一点野葱末在平底锅里稍微翻炒，就是一盘金黄诱人的天然鱼子酱。",
        en = "Fine golden roe harvested from freshwater bluegill panfish. Sautéed with wild wild chives in animal fat, this delicate pan-fried caviar makes humble lake catches feel celebratory.",
    },
    ["egg_bluejay"] = {
        zh = "一枚带有淡蓝底色与深色细小斑点的蓝松鸦鸟蛋。小巧玲珑精致得宛如艺术品，虽然只有一口的分量，但在饥肠辘辘的丛林潜行途中，它能为你提供最直接的纯净热量。",
        en = "A petite blue jay egg speckled with handsome chocolate-brown flecks. Though offering barely a mouthful, stumbling across a nest in the pines provides an instant morale and caloric boost.",
    },
    ["egg_bowfin"] = {
        zh = "从远古孑遗弓鳍鱼腹中剖出的暗色重胶质鱼卵。颗粒粘连紧密且外皮韧劲十足，加入大蒜与干辣椒在铁锅里爆炒，能有效去腥并爆发出让人停不下来的浓烈鲜香味道。",
        en = "Dark gelatinous roe stripped from prehistoric bowfins. Heavily salted and fried with wild garlic, its stubborn chewiness gives way to rich, earthy flavors that satisfy deep hunger.",
    },
    ["egg_brook_trout"] = {
        zh = "从清澈见底的高山溪流溪红点鲑体内采收的红宝石般鲜艳鱼籽。颗颗晶莹剔透，入口带着高山雪水洗涤出的纯净甘美，是荒野深处大自然给予耐心垂钓者的最高奖赏。",
        en = "Ruby-red trout eggs stripped from pristine mountain brook trout. Glistening like polished gemstones, each popping bead bursts with clean, cold-water sweetness that rewards patient anglers.",
    },
    ["egg_brown_trout"] = {
        zh = "粒粒饱满、泛着温润琥珀金芒的褐鳟野生鱼卵。在平底铜锅里用小火慢慢烘熟，表面泛起一层薄薄白霜，入口微咸回甘，是冰冷雨季补充体温与脂肪的最佳美味。",
        en = "Lustrous amber eggs harvested from hefty wild brown trout. Gently warmed in a skillet with a dash of rendered grease, they supply essential fatty acids to combat autumn chills.",
    },
    ["egg_bullfrog_frog"] = {
        zh = "漂浮在池塘水面上一大团半透明胶状物包裹的牛蛙卵团。虽然滑腻腻的触感让人有些头皮发麻，但捞起来滤掉泥水后下锅煮透，就是一碗富含纯天然胶原蛋白的浓稠糊糊。",
        en = "A gelatinous film of wild bullfrog eggs skimmed from murky swamp shallows. While scooping the slimy mass feels repulsive, boiling it yields rich collagen broth that nourishes during famine.",
    },
    ["egg_bullhead"] = {
        zh = "从泥泞水底黄颡鱼腹中挤出的小粒金黄色野生鱼籽。带有淡淡的河底泥腥味，用热油配合碎辣椒爆炒至金黄微焦，那股独特的香辣风味能让你连吃三大碗糙米饭。",
        en = "Fine yellow roe extracted from bottom-dwelling bullhead catfish. Searing them vigorously with dried chili flakes banishes muddy undertones, producing a deliciously savory field delicacy.",
    },
    ["egg_bullhead_yellow"] = {
        zh = "黄刺鲶体内饱满紧凑的一整块黄鱼子。富含高密度卵磷脂，直接在炭火烤网的一角慢慢炙烤至微微膨胀，咬在嘴里干香四溢，是夜间围炉取暖时绝佳的下酒小吃。",
        en = "A compact cluster of yellow bullhead eggs harvested from riverbanks. Slowly toasted beside red embers, they firm into crunchy, savory nuggets perfect for snacking during night sentry shifts.",
    },
    ["egg_burbot"] = {
        zh = "从深水鳕鲈江鳕体内获取的大号深色鱼卵。油脂含量极其丰富，在严寒冬夜的冰钓营地里丢进烧滚的雪水锅中，能熬煮出一锅奶白肥美、让人满血复活的高热量鲜鱼汤。",
        en = "Plump roe sacs harvested from cold-water burbot caught through lake ice. Boiled with chunks of fresh fish liver, they produce a rich chowder that restores warmth to frostbitten fingers.",
    },
    ["egg_butterfly"] = {
        zh = "密密麻麻紧密产在变异野花叶片背面的微型蝴蝶卵。虽然每一颗只有针尖大小，但整片叶子收集起来足有小半勺，直接生嚼有着类似酸葡萄干的独特微酸风味。",
        en = "A microscopic cluster of butterfly eggs glued beneath wild plantain leaves. Scraping them off provides an acidic, caviar-like crunch reminiscent of sour raisins on wilderness marches.",
    },
    ["egg_calico_bass"] = {
        zh = "从黑白花斑斑纹鲈鱼腹中收集的金黄色优质鱼卵。颗粒紧实且毫无异味，直接生拌上一滴野蜂蜜或者在平底锅里轻微煎烤，都能带给舌尖极致滑嫩的爆浆口感体验。",
        en = "Firm golden eggs collected from calico bass caught in freshwater reservoirs. Mild and sweet, tossing them directly into hot pans produces a rapid golden scramble that delights fatigued travelers.",
    },
    ["egg_cardinal"] = {
        zh = "一枚带有淡绿底色与密集灰褐斑纹的北美红雀鸟蛋。小巧圆润，敲碎蛋壳打进沸水锅里瞬间凝固成一团滑嫩的白玉小丸子，为长途跋涉的拾荒者注入一丝难得的活力。",
        en = "A delicate cardinal egg sporting greyish-brown speckles over a pale mint shell. Poaching it inside a boiling kettle yields a tender protein morsel that fuels long morning marches.",
    },
    ["egg_carp"] = {
        zh = "从肥硕大鲤鱼肚子里剖出的足足有半斤重的一大盘粗大鱼子。虽然肉质颗粒偏硬，但裹上面粉在铁板上压成鱼子饼煎炸，外酥里嫩，足够一家人美美饱餐一顿。",
        en = "A massive, heavy sack of coarse carp roe pulled from muddy lake carp. Dusted in crushed hardtack crumbs and pan-fried into dense cakes, it fills bellies with hearty, satisfying bulk.",
    },
    ["egg_centipede"] = {
        zh = "一枚软质皮革感外壳的超大号变异巨型蜈蚣卵。透过半透明的卵皮甚至能隐隐看到里面蜷缩的多足幼体，若不是饥饿到了生死关头，没有人愿意下嘴咬破这团胶状噩梦。",
        en = "A leathery, soft-shelled egg laid by a giant mutant centipede. Glimpsing the curled segmented horror through its translucent skin ensures only acute starvation compels you to cook it.",
    },
    ["egg_centipede_house"] = {
        zh = "在阴暗潮湿地下室砖缝里发现的蚰蜒小软卵。虽然体积极小且散发着一股怪异的湿木头气味，但在这虫子也是高蛋白生存资源的末日，收集一小把也能补充微量元素。",
        en = "A tiny gelatinous house centipede egg scraped from moist brick crevices. While visually unsettling, collected in quantity it supplies emergency protein when traditional larders run dry.",
    },
    ["egg_channel_catfish"] = {
        zh = "从大体型斑点叉尾鮰腹中收获的一大串明黄黏稠鱼卵块。在铁锅里加入浓烈野葱野蒜大火爆炒，浓厚的油脂香气能在瞬间盖过一切腥气，是河畔生存基地的荤菜顶梁柱。",
        en = "A generous clump of yellow catfish eggs bound by protective mucus. Searing them over furious wood fires with wild alliums produces a deeply fragrant, oily feast along riverbanks.",
    },
    ["egg_chickadee"] = {
        zh = "一枚只有拇指肚大小、带有红褐色小斑点的黑顶山雀细鸟蛋。小巧精致得让人舍不得下口，一口吞下滑顺清爽，是敏锐的树冠猎手在清晨树梢搜刮到的大自然无声馈赠。",
        en = "A miniature chickadee egg no larger than a thumb tip, adorned with reddish dots. Swallowed raw in a single smooth gulp, it offers an instant natural gift of clean energy.",
    },
    ["egg_chicken"] = {
        zh = "一枚完好无损的鲜鸡蛋；在充满爆炸与碎石的废土上完好存留简直是个奇迹，把它煎熟是珍贵的美食，但要是放在口袋里被丧尸撞一下，那就是黏糊糊的灾难。",
        en = "An intact, uncracked chicken egg; surviving radioactive cataclysms unbroken is a true miracle, making it a five-star breakfast unless a charging ghoul bumps your backpack and turns it into sticky yellow laundry.",
    },
    ["egg_cicada"] = {
        zh = "密密麻麻排插在干枯树皮裂缝里的硬质知了蝉卵。只要用小刀尖轻轻一刮就能刮下一小盒，虽然单颗微不足道，但在平底锅里烘烤至微微焦黄后嚼着吃，干香酥脆如芝麻。",
        en = "Hardened cicada eggs embedded inside slit tree twigs. Scraping a handful into a heated tin pan and roasting them until fragrant yields crunchy, nutty grains resembling toasted sesame.",
    },
    ["egg_cod"] = {
        zh = "来自深海野生大西洋真鳕鱼的整条饱满厚实鱼籽。在冰冷的大海里孕育出无与伦比的丰富油脂，无论是盐渍风干还是裹油焖烤，都是能让人在暴风雪夜忘却严寒的无价圣品。",
        en = "A massive, firm cod roe sac plucked from cold coastal waters. Teeming with clean marine fats, salting and slow-drying it creates high-energy rations that outlast the fiercest blizzards.",
    },
    ["egg_coot"] = {
        zh = "一枚带有淡棕褐色底色与深色细碎麻点的白骨顶水鸟蛋。质地紧实，敲开后蛋黄呈现出鲜艳夺目的深橙红色，在芦苇荡里摸索半天能找到两枚便足以告别一整天的饥饿。",
        en = "A mottled buff-colored American coot egg pulled from floating reed nests. Breaking its shell reveals a vibrant dark orange yolk that banishes hunger pangs across swampy expanses.",
    },
    ["egg_cormorant"] = {
        zh = "一枚外壳覆盖着厚厚一层粗糙白垩质涂层的双冠鸬鹚海鸟蛋。虽然剥开粗糙外壳时有些费劲且带有微微鱼腥味，但沉甸甸的分量能为饥肠辘辘的海岸拾荒者提供扎实热量。",
        en = "A chalky, pale blue cormorant egg scavenged from rocky coastal bluffs. Scrubbing off its pungent guano crust reveals a substantial yolk that satisfies hungry shoreline foragers.",
    },
    ["egg_crow"] = {
        zh = "一枚从高高树冠乌鸦窝里掏出来的橄榄绿带有密集深色斑点的黑乌鸦蛋。蛋清粘稠紧致，虽然偷乌鸦窝时容易遭到漫天恶鸦的俯冲围攻，但热腾腾的煎蛋能告慰一切辛劳。",
        en = "An olive-green crow egg densely marked with slate-colored splotches. Surviving the wrath of swooping parental flocks pays off when the rich fried yolk hits your camp plate.",
    },
    ["egg_dragonfly"] = {
        zh = "一枚尚且湿漉漉、泛着奇异金属光泽的巨型变异蜻蜓卵。表面黏液带有微弱的麻醉感，虽然直接吃可能引起轻微胃部翻江倒海，但在沸水里煮硬后口感脆韧如同明胶软糖。",
        en = "A moist, glistening egg harvested from predatory mutant dragonflies. Boiled thoroughly to neutralize mild digestive toxins, its firm rubbery interior resembles savory gelatin candy.",
    },
    ["egg_duck"] = {
        zh = "一枚来自野生绿头鸭巢穴的饱满青皮大鸭蛋。比寻常鸡蛋大了一整圈，厚实的蛋壳锁住了浓郁丰腴的油脂与蛋白，水煮后剥开撒上粗盐，流油的蛋黄能让人回味一整天。",
        en = "A hefty mallard egg sporting an oily greenish porcelain shell. Considerably richer than ordinary chicken eggs, hard-boiling and dipping its oily yolk into salt makes days brighter.",
    },
    ["egg_duck_domestic"] = {
        zh = "一枚从农场家鸭窝里搜刮到的沉甸甸白壳家鸭蛋。蛋黄个头硕大且富含油脂，打进滚烫的平底锅里滋滋作响，那股纯正温润的农家蛋香是末日里最让人落泪的人间烟火气。",
        en = "A dense white egg collected from abandoned farmyard duck coops. Sizzling vigorously in a hot skillet, its rich agricultural fragrance evokes sweet nostalgic tears of pre-collapse countryside mornings.",
    },
    ["egg_fallfish"] = {
        zh = "从溪流坠鱼体内剥离的小粒透明野生鱼卵。散发着清新的淡水水草香气，丢进开水锅里与野葱一起煮沸，瞬间变成一碗鲜美滑爽的天然鱼籽蛋花浓汤。",
        en = "Delicate freshwater roe harvested from river fallfish. Emitting the clean scent of running stream weed, dropping it into boiling water with wild scallions creates an exquisite poached caviar soup.",
    },
    ["egg_firefly"] = {
        zh = "一枚拳头大小、在黑暗中散发着幽绿生物荧光的变异巨型萤火虫卵。把它装在透明玻璃罐里不仅是一盏永远不耗电的天然小夜灯，烤熟后更是一顿高蛋白大餐。",
        en = "A fist-sized mutant firefly egg glowing with eerie green bioluminescence in the dark. Kept in a glass jar, it serves as a battery-free nightlight before being roasted into high-protein mush.",
    },
    ["egg_fish"] = {
        zh = "从不知名水生怪物肚子里掏出的一捧生鱼子；黏滑咸腥的红色颗粒，只要你不去深究那条长了四只眼睛的三文鱼长相，就能自欺欺人地称之为废土黑金鱼子酱。",
        en = "Glistening roe harvested from an unknown aquatic creature; salty, slippery pearls of protein that you can confidently brand as gourmet caviar, provided you ignore the four eyes on the parent fish.",
    },
    ["egg_flounder"] = {
        zh = "深海比目鱼体内紧密排列的细小金黄色鱼子。油脂丰富且毫无腥味，在滚烫的平底锅里轻微翻炒，每一粒鱼籽在齿间爆开的瞬间都能带来浓郁的深海风味享受。",
        en = "Fine golden roe harvested from coastal flounder. Searing gently in animal fat pops each tiny marine sphere against your teeth, releasing concentrated savory juices that brighten dreary rations.",
    },
    ["egg_fly"] = {
        zh = "一小堆附着在腐肉表面的微小苍蝇虫卵。虽然看着让人胃部翻江倒海、食欲全无，但在这残酷的废土上，收集起来洗净煮熟依然是一份不可多得的纯动物蛋白来源。",
        en = "A microscopic cluster of fly eggs scraped from decaying meat. While turning the stomach of uninitiated travelers, boiling them thoroughly provides desperate wanderers with clean, uninfected emergency protein.",
    },
    ["egg_foul_bigfrog"] = {
        zh = "宛如一条浮水浮标线般连绵数米的巨型恶臭变异青蛙卵带。黏液里包裹着拳头大的半透明胚胎，虽然散发着沼泽烂泥的腥气，但一大勺就能满足全队三天的热量缺口。",
        en = "A multi-meter gelatinous strand of giant frog eggs resembling a buoy line. Reeking of swamp muck, a single bucket scooped from the reeds provides enough boiled calories to feed three.",
    },
    ["egg_fowler_toad"] = {
        zh = "在死水坑塘水草间漂浮的长条状蟾蜍卵带。细密的黑色小点均匀嵌在透明胶质里，经过多道沸水彻底焯水去毒后，口感滑溜清脆，是沼泽求生者的救命野味。",
        en = "Long strings of Fowler's toad eggs drifting lazily through stagnant swamp water. Boiling the gelatinous mass through multiple water changes neutralizes mild toxins, leaving a slippery, filling survival broth.",
    },
    ["egg_freedom_toad"] = {
        zh = "缠绕在水下杂草上的螺旋形蟾蜍卵囊。滑腻的黏膜在阳光下泛着七彩微光，虽然卖相让人不敢恭维，但煮熟后的高热量碳水蛋白质混合物能让濒死者重新站立起来。",
        en = "A spiraling strand of toad eggs anchored to submerged aquatic weeds. While visually unappealing, boiling this gelatinous bounty provides concentrated carbohydrates and proteins to keep starving wanderers on their feet.",
    },
    ["egg_gar_longnose"] = {
        zh = "长鼻雀鳝体内产出的大粒暗绿色鱼卵。必须严厉警告的是这种鱼卵对人类具有中度神经毒性，但在饥荒当头的废土上，某些狠人依然会用醋酸反复浸泡冒险尝试下咽。",
        en = "Dark green roe sacks taken from longnose gars. While toxic to humans when raw, reckless wasteland cooks pickle them thoroughly in vinegar to neutralize poisons before consuming them out of desperation.",
    },
    ["egg_goldfish"] = {
        zh = "从废弃观赏鱼池变异金鱼肚子里挤出的小粒橙红色鱼籽。小巧晶莹，虽然原本只是旧时代庭院里的观赏宠物，但在末日餐桌上，这捧鱼子能带来最纯粹的饱腹能量。",
        en = "Tiny, bright orange roe harvested from overgrown ornamental goldfish. Once swimming in pristine suburban garden ponds, these delicate eggs now supply essential calories beside smoky wasteland campfires.",
    },
    ["egg_goose"] = {
        zh = "一枚分量十足、蛋壳厚实坚硬的农场家鹅大蛋。个头比三个寻常鸡蛋还要大，沉甸甸的油脂与金黄蛋黄在锅里煎熟，散发出纯正醇厚的农场香气，让人陶醉不已。",
        en = "A colossal domestic goose egg boasting a thick porcelain-like shell. Yielding as much yolk as three chicken eggs, frying it over coals fills your shelter with intoxicating farmhouse aromatics.",
    },
    ["egg_goose_canadian"] = {
        zh = "冒着被暴躁狂暴加拿大野鹅啄碎面门的生命危险偷来的野生大鹅蛋。沉甸甸的蛋壳上沾满杂草，磕开煎熟后味道浓郁野性十足，每一口都是在向大自然宣示胜利。",
        en = "A heavy wild Canada goose egg stolen at the risk of serious facial trauma from vicious nesting parents. Its rich, gamy yolk tastes like hard-won victory after a harrowing forest battle.",
    },
    ["egg_grass_carp"] = {
        zh = "从巨型草鱼体内剥落的大捧半透明淡色鱼卵。颗粒圆润饱满且极具弹性，在热油里加入几颗野花椒快速翻炒爆香，外酥里爆浆的口感堪称废土河鲜一绝。",
        en = "Translucent pale roe clusters harvested from a chunky grass carp. Sautéed briskly with wild peppercorns, each delicate grain bursts on the tongue with rich, buttery river flavors.",
    },
    ["egg_grasshopper"] = {
        zh = "一枚白色长药丸形状的变异巨型蚱蜢卵。外壳光滑结实，透过半透明的外皮能看到内部蜷缩的节肢雏形，在平底锅里烘烤至膨胀焦脆，吃起来像是烤坚果蚕豆。",
        en = "A pill-shaped white egg laid by a giant mutant grasshopper. Toasting its rigid shell over a dry skillet puffs the interior into a crunchy, nutty treat that resembles roasted fava beans.",
    },
    ["egg_gray_frog"] = {
        zh = "漂浮在静止水坑表面的一小片灰色树蛙卵团。薄薄的胶质膜保护着中间黑色的生命胚胎，用树皮勺子舀起来直接煮熟，滑润如西米露般容易下咽，极易被人体消化。",
        en = "A modest sheet of gray tree frog eggs resting atop quiet pond scum. Scooped with a birch bark spoon and boiled, its slippery sago-like consistency goes down easily without upsetting sour stomachs.",
    },
    ["egg_grebe"] = {
        zh = "一枚从芦苇荡浮巢里摸索到的角鸊鷉野生水鸟蛋。表面沾染着水生植物的黄绿斑痕，蛋白紧致滑嫩，煮熟切片夹在自制烤硬面包干里，是湿地探险途中的无上珍馐。",
        en = "A wild horned grebe egg scavenged from a floating reed nest. Stained with marsh algae, hard-boiling it yields a firm, savory yolk that pairs wonderfully with charred hardtack biscuits.",
    },
    ["egg_green_frog"] = {
        zh = "一层清澈胶质薄膜、内部缀满黑芝麻般小胚胎的绿青蛙卵。在清澈溪流回水湾里轻轻捞起，滤掉泥沙下锅，与嫩野蒲公英叶一起能炖出一锅清香扑鼻的绿色菜羹。",
        en = "A delicate translucent sheet of green frog eggs speckled with dark embryos. Simmered alongside tender dandelion greens, it yields a fragrant, restorative vegetable pottage after days of travel.",
    },
    ["egg_green_sunfish"] = {
        zh = "从绿太阳鱼体内剔出的小粒明黄色野生鱼籽。散发着温暖阳光照射过的水草清香，稍微撒点细盐抹在烤熟的土豆块上，浓缩的鲜美风味让干硬的根茎变得无比多汁美味。",
        en = "Fine yellow roe extracted from a feisty green sunfish. Lightly salted and spread across roasted wild potatoes, its rich, briny burst transforms dry, chalky tubers into succulent comfort food.",
    },
    ["egg_grouse"] = {
        zh = "一枚带有密集深棕色麻点的披肩榛鸡鸟蛋。小巧坚硬的外壳完美锁住了浓郁甘甜的野禽风味，敲开倒进热水杯里冲泡开，就是一杯补充电解质与蛋白质的纯天然能量蛋饮。",
        en = "A speckled ruffed grouse egg concealed beneath dead pine needles. Cracking its shell into a mug of hot water yields an instant, nourishing egg-drop broth that revives chilled sentries.",
    },
    ["egg_guinea_fowl"] = {
        zh = "一枚质地极其坚硬、外壳厚重如同石质的珍珠鸡蛋。即使从一米高掉在木地板上也绝不会摔碎，必须用刀背用力敲击才能破壳，里面浓郁稠厚的蛋黄绝对值得一切费劲功夫。",
        en = "An extraordinarily thick-shelled guinea fowl egg that survives being dropped on concrete without cracking. Prying its stubborn armor open rewards you with an exceptionally rich, velvety golden yolk.",
    },
    ["egg_haddock"] = {
        zh = "从大西洋黑线鳕体内捕获的整副饱满大鱼籽包。在沿海废墟的咸涩海风中用木屑熏制风干，能将其转化为极其坚硬耐存的深海鱼子干，削成薄片下酒，回味悠长醇厚。",
        en = "A generous haddock roe sack taken from coastal waters. Smoked over pine shavings, it cures into a firm, shelf-stable marine sausage that slices thin for long-lasting savory camp snacks.",
    },
    ["egg_halibut"] = {
        zh = "从重型野生大比目鱼腹中剖出的大粒高品质金黄鱼卵。油脂含量极其惊人，直接在炭火烤石上用自身渗出的鱼油慢煎至金黄酥脆，每一口都是在享受大自然最纯粹的馈赠。",
        en = "Golden, fat-rich halibut roe harvested from deep coastal depths. Searing in its own rendered oils on a heated flat rock, the popping eggs deliver an opulent feast of pure marine lipids.",
    },
    ["egg_hummingbird"] = {
        zh = "一枚只有豌豆大小、轻若无物的红喉蜂鸟微型鸟蛋。小巧精致得如同一颗温润小珍珠，虽然热量微乎其微连塞牙缝都不够，但捧在手心里能让人感受到生命昔日的脆弱与美好。",
        en = "A pea-sized ruby-throated hummingbird egg no heavier than a feather. While supplying negligible calories, holding this tiny porcelain miracle in scarred hands brings a moment of profound poetic wonder.",
    },
    ["egg_kokanee_salmon"] = {
        zh = "从内陆红鲑腹中采收的晶莹鲜红如玛瑙的无暇鱼籽。在冰冷刺骨的淡水湖泊里孕育出无与伦比的鲜美油脂，无论是冷水生腌还是铁板炙烤，都是废土垂钓者的终极梦幻食材。",
        en = "Agate-red kokanee salmon eggs glistening like polished rubies. Spawning in glacial freshwater streams, their bursting juices offer clean, cold-water sweetness that makes rugged mountain survival feel luxurious.",
    },
    ["egg_lady_bug"] = {
        zh = "一枚外观酷似大粒黄米、附着在灌木叶片上的变异瓢虫卵。质地微硬且带有轻微草本香气，洗干净直接生嚼有着类似爆米花的爽脆口感，是林间漫步时随手采撷的野趣零食。",
        en = "A mutant ladybug egg resembling a plump yellow rice grain glued to wild leaves. Chewing it raw delivers a surprising, crunchy burst of herbal tang reminiscent of roasted sunflower seeds.",
    },
    ["egg_lake_trout"] = {
        zh = "从深邃寒冷的冰川湖泊巨型湖鳟腹中提取的大粒橙红鱼卵。颗粒肥厚紧实，在野营铁锅里加入少许雪水慢火焖炖，熬出的一层金黄鱼油能让整碗粗粮糊糊变得鲜美绝伦。",
        en = "Large orange lake trout eggs harvested from cold glacial depths. Simmering them with melted snow yields a shimmering layer of fish oil that transforms coarse grain gruel into a gourmet feast.",
    },
    ["egg_lbass"] = {
        zh = "从凶猛大口黑鲈腹中割取的一整团金黄黏稠鱼子。富含高密度蛋白质，用大蒜末和动物油脂在锅里大火翻炒成金黄的鱼子酥，焦香扑鼻，连周围巡逻的流浪猫都会被吸引过来。",
        en = "A rich cluster of largemouth bass eggs stripped from a predatory river catch. Pan-frying them with wild garlic crunches into savory golden curds that draw hungry camp felines from blocks away.",
    },
    ["egg_leo_frog"] = {
        zh = "紧密团聚在水草根部的一大团深色豹蛙卵团。密密麻麻的小黑点被透明明胶死死护住，虽然外观让人联想起外星黏液，但用柴火烧开煮透后，是一道极易吸收的流质温补食物。",
        en = "A dense spherical cluster of dark leopard frog eggs anchored to aquatic roots. Resembling alien spawn, boiling them down creates an easily digestible, warm protein porridge for convalescing survivors.",
    },
    ["egg_locust"] = {
        zh = "一枚拳头大小、外壳呈坚韧角质层的变异巨蝗卵。剥开外皮里面是高浓度的脂肪与蛋白质浆液，扔进篝火热灰里慢煨烤熟，撕开吃口感如同烤红薯般绵密扎实、极度耐饥。",
        en = "A fist-sized locust egg enclosed within a tough, fibrous sheath. Roasted inside glowing campfire embers, the steaming interior firms into a dense, nutty paste that staves off starvation for hours.",
    },
    ["egg_mackerel"] = {
        zh = "从远洋鲐鱼体内采收的细小油润野生鱼卵。油脂含量极高且带有独特的鲭鱼咸鲜味，在铁板上稍微烘烤至表面微焦，散发出的浓郁海鱼香气能飘出半条废弃街区。",
        en = "Fine, oily mackerel roe taken from swift pelagic schools. Toasting lightly over iron griddles releases mouthwatering ocean aromatics that linger invitingly across ruined seaside settlements.",
    },
    ["egg_mantis"] = {
        zh = "一块外观如同干瘪发泡泡沫塑料的螳螂硬质螵蛸卵鞘。里面紧密粘连着数十枚卵粒，用小刀剥开丢进热开水里煮熟，嚼起来像是一把酥脆的小花生米，充满野趣。",
        en = "A spongy, papery praying mantis ootheca glued to tree bark. Cracking open the protective foam reveals dozens of tiny eggs that boil into crunchy, nutty snacks rich in essential minerals.",
    },
    ["egg_mink_frog"] = {
        zh = "常常在沉水木头缝隙里发现的球状紧实水蛙卵团。带有淡淡的麝香水腥味，洗净后与野蒜一起下锅，煮成一锅浓郁微咸的野味高汤，能让疲惫的双腿重新焕发活力。",
        en = "A tight spherical egg cluster scavenged from submerged river logs. Carrying a distinctive musky river scent, boiling it with wild ramps produces a restorative broth that revitalizes tired legs.",
    },
    ["egg_mole_cricket"] = {
        zh = "深埋在沙土松软洞穴里的变异蝼蛄卵。表面沾满了湿润的泥沙，洗净后呈现出白玉般的微光，放在滚烫石板上烤熟，口感如同烤鹌鹑蛋黄般细腻干香、回味悠长。",
        en = "A plump mole cricket egg unearthed from subterranean burrows. Rinsed clean of gritty sand and roasted on hot slate, its interior resembles a rich, delicate quail yolk with an earthy finish.",
    },
    ["egg_moorhen"] = {
        zh = "一枚从沼泽水草浮巢里搜刮到的黑水鸡野生水鸟蛋。表面布满深色斑点，蛋壳坚硬厚实，打碎煎熟后蛋香扑鼻，在漫长寒冷的湿地跋涉中是一份弥足珍贵的生命补给。",
        en = "A wild common gallinule egg retrieved from floating marsh thickets. Protected by a tough speckled shell, frying its rich orange yolk provides invaluable warmth during freezing wetland expeditions.",
    },
    ["egg_mosquito"] = {
        zh = "漂浮在死水桶表面的一排排微小变异蚊子卵筏。虽然一想到它孵化后吸人鲜血的恐怖模样就让人作呕，但趁着还没孵化直接用沸水煮死，就是一碗无害的高蛋白微型营养羹。",
        en = "A tiny raft of mutant mosquito eggs scooped from stagnant rainwater barrels. While the adult horror disgusts the soul, boiling the unhatched raft neutralizes danger into harmless micro-protein.",
    },
    ["egg_moth"] = {
        zh = "成片整齐排布在变异橡树叶片背面的绒毛飞蛾软卵。外层覆盖着细密的保温鳞毛，用刀尖整片刮下放进铁盒烘干，研磨成粉末拌进汤里，就是纯天然的高效营养增稠剂。",
        en = "Soft moth eggs clustered beneath mutated oak foliage, shielded by fine downy scales. Scraping them into a tin cup and drying them creates a nutritious protein powder to thicken watery wild stews.",
    },
    ["egg_moth_fly"] = {
        zh = "在潮湿下水道管道壁上发现的微型蛾蠓小虫卵。虽然生长环境极其令人反胃，但在这人人争抢垃圾食物的残酷时代，用消毒水彻底杀菌煮沸后，它依然是能救命的热量。",
        en = "Microscopic drain fly eggs scraped from damp subterranean plumbing joints. Despite their repulsive origin, boiling them vigorously renders them safe, life-sustaining calories in the darkest hours.",
    },
    ["egg_muskellunge"] = {
        zh = "从水中霸王巨型北美狗鱼腹中收获的大颗粒顶级野生鱼籽。在湖底冷水中孕育出的鱼卵颗颗饱满如豆，撒上细盐腌制成黑金般的鱼子酱，是避难所最顶级的奢侈盛宴。",
        en = "Giant roe clusters harvested from a monster muskellunge. Glistening like golden pearls, lightly curing them with coarse salt produces an extravagant caviar feast worthy of bunker royalty.",
    },
    ["egg_mutant_salmon"] = {
        zh = "一枚足有拳头大小、半透明胶质内部清晰可见一条变异小鱼苗在游动的怪诞鱼卵。虽然散发着淡淡的化学金属荧光，但煮熟后的饱腹感极其强悍，足以让人一天不觉得饿。",
        en = "A fist-sized translucent globe containing a wriggling mutated salmon fry. Though emitting an eerie phosphorescence, boiling it thoroughly yields a colossal caloric payload that satisfies all day.",
    },
    ["egg_odd_bigfrog"] = {
        zh = "一条粗大如消防水带、盘旋缠绕在水下树桩上的巨型异种青蛙螺旋卵带。粗壮的胶质层坚韧防割，用大锅煮透切块食用，口感细腻弹牙如同魔芋豆腐，分量十足。",
        en = "A thick, spiraling rope of giant frog eggs draped around submerged timber like a fire hose. The rubbery jelly cooks into chewy cubes resembling konjac tofu, easily feeding a hungry patrol.",
    },
    ["egg_pattern_bigfrog"] = {
        zh = "远看宛如一大堆巨型斑纹珍珠项链的罕见花纹大青蛙卵簇。每一颗卵粒足有乒乓球大小，外层包裹着结实的抗菌黏液，丢进篝火灰里煨熟，剥开即可品尝滚烫的流心蛋黄。",
        en = "A bizarre cluster of giant frog eggs resembling a heap of mottled pearls. Scaled to the size of table tennis balls, roasting them in ashes yields steaming, savory yolks of unmatched richness.",
    },
    ["egg_pbass"] = {
        zh = "从河道巨物孔雀鲈腹中采掘的璀璨金橙色大颗粒野生鱼卵。带着热带水域特有的鲜活风味，用动物油脂大火快煎至两面金黄酥脆，香气扑鼻，让人彻底忘却末日的苦闷。",
        en = "Vibrant orange roe extracted from an aggressive peacock bass. Searing them over furious charcoal fires produces golden, crispy caviar patties whose rich flavor banishes apocalyptic despair.",
    },
    ["egg_peeper_frog"] = {
        zh = "在早春融雪溪流边稀疏附着在水草叶片上的春雨蛙小卵粒。数量稀少且极具早春的气息，在经历了一个冬天的干瘪肉干折磨后，这一小碗嫩滑的鲜卵是春天到来的信标。",
        en = "A modest clutch of tiny spring peeper eggs clinging to thawed riverbank sedges. Rare and delicate, finding this slippery seasonal bounty signals the arrival of spring after months of starvation.",
    },
    ["egg_perch"] = {
        zh = "从河鲈体内取出的细长缎带状淡黄色野生鱼籽排。鱼卵颗粒排列整齐致密，直接挂在通风处风干成硬鱼子排，切成薄片随时随地都能放进嘴里嚼出满口浓郁的深沉鲜香。",
        en = "Ribbon-like strands of pale yellow roe stripped from freshwater river perch. Wind-drying them into hard cakes produces portable, chewable jerky that releases concentrated umami during marches.",
    },
    ["egg_pheasant"] = {
        zh = "一枚从麦田草丛深处搜寻到的环颈雉野鸡鸟蛋。橄榄棕色的坚硬外壳保护着纯净浓郁的野禽蛋清与蛋黄，在锅里煎成荷包蛋咬破的一刹那，醇香的滋味让人忍不住闭眼赞叹。",
        en = "A wild pheasant egg discovered deep within overgrown grain fields. Its glossy olive shell encases a rich, velvety yolk that fries into a heavenly breakfast beside ruined agricultural silos.",
    },
    ["egg_pickerel"] = {
        zh = "从敏捷的白斑狗鱼体内剔出的小粒琥珀色淡水鱼卵。虽然单颗个头不大，但一整条鱼体内能采出足足两大碗，拌上野蒜泥在大平底锅里烘烤成鱼籽干饼，是极佳的行军干粮。",
        en = "Fine amber eggs stripped from a slender chain pickerel. Yielding copious quantities, baking them with wild garlic into flat savory cakes creates portable, nutrient-packed travel biscuits.",
    },
    ["egg_pickerel_american"] = {
        zh = "美洲红鳍狗鱼体内孕育的晶莹野生鱼子。在清凉的溪水里清洗干净，撒上一撮粗盐直接拌饭食用，在舌尖上噼啪破裂的爆浆快感足以让任何挑剔的废土老饕心满意足。",
        en = "Glistening wild roe harvested from an American redfin pickerel. Salted and eaten raw, the delightful sensory pop across the palate satisfies even the most cynical wasteland epicure.",
    },
    ["egg_pickerel_frog"] = {
        zh = "在清澈溪流中发现的球状聚拢斑点水蛙卵团。带有特殊的淡黄色胶质保护层，下锅用文火慢炖化成一碗浓稠鲜甜的胶原蛋白浓羹，对久病虚弱的伤员有着极好的温补奇效。",
        en = "A globular mass of pickerel frog eggs collected from clear gravelly brooks. Simmered into a thick, sweet gelatinous pottage, it acts as an easily absorbed restorative tonic for injured survivors.",
    },
    ["egg_pigeon"] = {
        zh = "一枚从废弃大厦楼顶鸽子窝里掏出来的雪白野鸽子蛋。虽然个头小巧玲珑，但在缺乏食物的断壁残垣顶端，这枚带着母鸽体温的新鲜小蛋就是大自然对攀爬者最慷慨的奖励。",
        en = "A smooth white pigeon egg scavenged from a high-rise rooftop vent. Small and tender, finding this warm little treasure atop shattered concrete structures rewards dangerous climbing exploits.",
    },
    ["egg_pike"] = {
        zh = "从凶残白斑大狗鱼腹中收获的整副金黄色厚重野生鱼籽囊。饱满紧凑，在炭火平底锅上用动物油脂慢慢煎透，表面焦黄酥脆内部软嫩滑顺，堪称湖畔营地的顶级荤菜代表。",
        en = "A massive golden roe sack butchered from an apex northern pike. Gently roasted over embers with lard, its crispy crust and melting interior form the undisputed centerpiece of lakeside camps.",
    },
    ["egg_pollock"] = {
        zh = "来自冷水狭鳕体内的经典海产大鱼卵包。在旧世界是风靡各地的明太子与辣鱼籽核心原料，用粗盐与辣椒粉深度腌制风干后，切片配烤饼吃，辛辣鲜香令人欲罢不能。",
        en = "A hefty pollock roe sack hauled from chilly coastal waters. Cured with hot chili flakes and salt in the style of classic mentaiko, its spicy, savory pop elevates stale flatbread into a culinary joy.",
    },
    ["egg_porgy"] = {
        zh = "从海鲈鱼腹中刮取的小粒半透明咸水鱼卵。带着浓郁的潮汐咸鲜味，洗净后撒入粗盐腌制成鱼子酱，抹在烤焦的面包干上，能带来难得的沿海美味回忆。",
        en = "Delicate translucent roe harvested from coastal porgy fish. Carrying clean salty tides, lightly salting and spreading them across charred biscuits creates a rare coastal culinary treat.",
    },
    ["egg_proxy_bigfrog"] = {
        zh = "一大团半透明胶状的变异巨型牛蛙卵；个头比拳头还大，黏糊糊地颤动着，尽管煮熟确实能填饱肚子，但吞下去时总让人担心肚子里会不会突然蹦出一只带蹼的小怪物。",
        en = "A gelatinous clump of giant frog eggs, each sphere larger than a fist; thoroughly cooking them provides rich emergency calories, though you will spend the entire digestive cycle dreading an unexpected internal ribbit.",
    },
    ["egg_pumpkinseed"] = {
        zh = "从色彩斑斓的南瓜籽太阳鱼体内取出的细小金黄鱼籽。单颗小如针尖，汇聚成团后在平底锅里用动物油脂快速翻炒，金黄酥脆的口感能极大抚慰疲惫的身心。",
        en = "Fine golden eggs extracted from vibrant pumpkinseed sunfish. Clustered into hot skillets with tallow, they fry into crisp, savory nuggets that soothe weary scouting bodies.",
    },
    ["egg_rainbow_trout"] = {
        zh = "来自虹鳟体内晶莹剔透、犹如橙红玛瑙般诱人的高品质大鱼卵。在清冽冰冷的雪山融水溪流中孕育而成，入口爆浆清甜毫无杂味，是荒野钓客的梦幻补品。",
        en = "Glistening agate-orange roe sacs harvested from wild rainbow trout. Spawned in pristine alpine snowmelt, their crisp, clean popping sweetness represents the supreme dream of wilderness anglers.",
    },
    ["egg_raven"] = {
        zh = "一枚从险峻悬崖渡鸦巢穴里冒死搜刮出来的暗绿麻点大鸟蛋。个头比乌鸦蛋更大，蛋黄浓郁稠厚且带有微微的坚果香气，在冰冷的峭壁上吃下一枚能迅速恢复体力。",
        en = "A dark green speckled raven egg retrieved from a sheer cliffside aerie. Considerably richer than ordinary crow eggs, its dense, nutty yolk rapidly restores flagging mountaineering stamina.",
    },
    ["egg_redbreast"] = {
        zh = "从红胸太阳鱼体内剥离的小粒明黄鱼卵簇。油脂温和清爽，与野葱末一同在铁锅里快速烘炒成金黄的鱼子碎，是河畔垂钓营地最让人食指大动的下饭好菜。",
        en = "Bright yellow roe clusters stripped from a freshwater redbreast sunfish. Stir-fried briskly with wild leeks, this fragrant golden scramble forms the undisputed highlight of riverside dinners.",
    },
    ["egg_roach"] = {
        zh = "一枚足有拳头大小、油光发亮且散发着恶臭的变异巨型蟑螂卵鞘。即便知道它富含高密度蛋白质，但光是看着那层令人作呕的深褐色甲壳，就需要赌上全部的理智。",
        en = "A fist-sized, greasy egg ootheca laid by a giant mutant cockroach. Even knowing its monstrous protein payload, cracking open its vile brown casing demands every ounce of mental discipline.",
    },
    ["egg_roach_plague"] = {
        zh = "从瘟疫传播者体内产出的剧毒变异巨蟑卵囊。表面泛着病态的暗紫脓光，必须用沸水彻底烹煮杀菌半小时以上，否则吞下它就是在主动向死神递交投名状。",
        en = "A venomous ootheca harvested from an irradiated plague roe-carrier. Glistening with sickly purplish secretions, boiling it vigorously for half an hour is mandatory to prevent agonizing fatal infections.",
    },
    ["egg_robin"] = {
        zh = "一枚呈现出标志性梦幻知更鸟蓝色的精致野生小鸟蛋。光滑无瑕的蓝色外壳宛如一件易碎的瓷器艺术品，水煮后剥开一口吞下，清甜温润的滋味让人久久难忘。",
        en = "A delicate wild robin egg boasting iconic robin-egg blue porcelain perfection. Peeling its fragile azure shell after a gentle boil yields an exquisitely sweet, tender yolk that lifts spirits.",
    },
    ["egg_rock_bass"] = {
        zh = "从岩鲈体内采收的金黄微咸野生鱼籽包。颗粒饱满紧凑，在干燥的微风中风干成硬质鱼子饼，切成薄片作为长途行军时的应急零食，能持续补充盐分与能量。",
        en = "Plump golden roe sacs taken from territorial rock bass. Air-drying them into hard savory patties yields portable travel jerky, continuously supplying sodium and vital fats on extended cross-country treks.",
    },
    ["egg_salad"] = {
        zh = "将煮熟的鸡蛋切碎并拌入自制蛋黄酱与野葱末调配的经典鸡蛋沙拉。口感绵密滑顺且奶香浓郁，抹在干硬的烤吐司上大咬一口，仿佛瞬间穿越回了旧时代的野餐聚会。",
        en = "A creamy egg salad prepared from chopped hard-boiled eggs, rich mayonnaise, and wild herbs. Slathered across charred toast, its velvety texture transports wanderers back to carefree sunny summer picnics.",
    },
    ["egg_salmon"] = {
        zh = "整副饱满硕大、鲜红欲滴的大西洋野生鲑鱼大鱼子包。在海水与淡水交汇处捕获的极品鱼籽，撒上精盐简单腌渍就是顶级鲑鱼子酱，颗颗爆浆的美味无与伦比。",
        en = "A hefty salmon roe sack bursting with glistening crimson spheres. Lightly salted, each magnificent bead explodes with opulent, oceanic juices that rival any pre-collapse fine-dining luxury.",
    },
    ["egg_sbass"] = {
        zh = "从凶悍条纹鲈体内剖出的金黄大颗粒优质鱼卵。带着干净的半咸水水域风味，在铁板上压成薄饼用猪油慢煎至两面金黄酥脆，香气能传遍整个废弃海港码头。",
        en = "Generous golden roe harvested from a predatory striped bass. Flattened into patties and seared in rendered fat, their crisp, savory aroma wafts invitingly across abandoned harbor docks.",
    },
    ["egg_shift_bigfrog"] = {
        zh = "高尔夫球大小、依靠黏液紧紧粘连在一起的变异相移巨蛙卵团。每一颗卵都沉重而富有弹性，煮熟后切片蘸粗盐吃，口感弹牙滑脆如同特大号魔芋软糖。",
        en = "Golfball-sized giant frog eggs bound together by tenacious adhesive secretions. Boiled until firm, slicing and dipping them in rock salt produces a springy texture akin to giant savory jelly candies.",
    },
    ["egg_silverfish"] = {
        zh = "在发霉旧书堆与潮湿纸箱缝隙里搜刮到的微型衣鱼软卵。单颗微小如尘埃，但耐心地用小毛刷扫成一小堆下锅烘烤，吃起来有着类似烘烤坚果碎的微妙香脆口感。",
        en = "Microscopic silverfish eggs brushed from moldy library book bindings. Gathering a thimbleful and toasting them in a clean tin lid releases an unexpectedly pleasant, toasted-almond aroma.",
    },
    ["egg_skink_fivelined"] = {
        zh = "从向阳烂木桩里挖出的一窝白皮五线石龙子小蜥蜴蛋。皮革质感的外壳极具韧性，直接埋进火塘的温热余烬里慢煨烘熟，剥开吃口感细腻爽滑如微型鸽子蛋。",
        en = "Leathery white lizard eggs discovered beneath sun-warmed rotting logs. Roasting them in soft campfire ash firms their interiors into tender, delicate spheres resembling miniature quail eggs.",
    },
    ["egg_slug"] = {
        zh = "一小堆裹在黏稠湿润黏液里的小巧野生鼻涕虫软卵。虽然收集过程让人手上黏糊糊的十分难受，但在极度缺乏食物的阴雨荒野中，煮熟后依然是一份纯净的热量补充。",
        en = "Translucent slug eggs coated in thick, sticky moisture under damp forest rocks. Washing them clean and boiling thoroughly yields neutral-tasting micro-calories during sodden wilderness emergencies.",
    },
    ["egg_snail"] = {
        zh = "在潮湿草丛深处发现的一小窝洁白如珍珠的野生蜗牛白卵。在旧时代西方高级餐桌上被称为白鱼子酱的昂贵珍品，如今在废土上直接洗净下锅，滑嫩鲜香别有一番风味。",
        en = "Pristine white snail eggs resembling tiny glowing pearls nestled in damp moss. Once prized as expensive snail caviar in haute cuisine, pan-frying them delivers delicate, earthy umami.",
    },
    ["egg_spade_frog"] = {
        zh = "排成数条紧密短黑线状的锄足蟾胶质卵带。从临时雨水坑里捞起，经过沸水彻底滚煮后胶质收缩紧致，拌入一点野蒜泥大口吞咽，能迅速填饱空空如也的肠胃。",
        en = "Short, dense strands of black spadefoot toad eggs gathered from temporary rain pools. Boiling contracts the slippery jelly into firm strings that fill growling bellies with needed calories.",
    },
    ["egg_sparrow"] = {
        zh = "一枚从屋檐下麻雀窝里摸索出来的带褐色密集斑点的麻雀小蛋。只有指甲盖大小，水煮后剥开一口一个，浓郁纯正的鸟蛋香味能给艰辛的拾荒清晨带来一抹暖意。",
        en = "A speckled wild sparrow egg retrieved from beneath eaves in ruined suburbs. Fingertip-sized and tender, popping this warm, hard-boiled morsel into your mouth brightens harsh mornings.",
    },
    ["egg_spider_cellar"] = {
        zh = "挂在阴暗地窖蛛网中央由细丝紧紧包裹的幽灵蛛卵包。虽然用火把烧掉蛛丝后里面的小卵粒看着令人发怵，但在弹尽粮绝的困境下，煮熟后也是不可多得的生还资源。",
        en = "A delicate silk-wrapped egg sac spun by cellar spiders in dark basements. Singeing away the webbing and boiling the tiny eggs yields clean, neutral emergency protein during long sieges.",
    },
    ["egg_spider_jumping"] = {
        zh = "在向阳树皮缝隙里发现由棉絮状蛛丝包裹的跳蛛微型卵包。剥开蛛丝里面是金黄色的小卵粒，丢进热水里烫熟后吃起来有着淡淡的草木清香，毫无异味。",
        en = "A cottony silk nest protecting jumping spider eggs hidden within tree bark. Boiling the golden beads produces a mild, grassy-sweet broth that goes down without any unpleasant aftertaste.",
    },
    ["egg_spider_trapdoor"] = {
        zh = "在坚固地洞活板门深处挖掘出的螲蟥活板门蛛卵包。蛛丝外壳厚重坚韧如皮革，用小刀剖开里面的成团卵粒，用热灰慢烤至熟透，嚼起来有一股浓郁的干坚果香味。",
        en = "A thick, leathery egg sac unearthed from a camouflaged trapdoor spider burrow. Toasting the dense cluster over coals imparts a rich, roasted-nut flavor that surprises skeptical palates.",
    },
    ["egg_spider_web"] = {
        zh = "悬挂在废弃工厂角落大型蛛网中央的结实蜘蛛卵囊。厚实的蛛丝外层有效阻绝了灰尘侵蚀，剥开后将里面干净的小卵煮熟，能为饥肠辘辘的拾荒者提供立竿见影的体能补充。",
        en = "A resilient egg sac suspended within thick aerial webs across industrial ruins. Peeling away the tough silk envelope reveals pristine eggs that boil into an immediate, clean energy boost.",
    },
    ["egg_spider_widow"] = {
        zh = "表面带有尖刺状凸起的致命黑寡妇蜘蛛丝织卵包。虽然母蛛含有剧毒令人闻风丧胆，但卵粒本身并没有毒腺，用长树枝挑下来彻底煮沸，也是救急的蛋白质来源。",
        en = "A spiky, teardrop silk egg case harvested from dangerous black widow webs. While the mother's venom paralyzes, thoroughly boiling the unhatched clutch provides safe emergency nutrition.",
    },
    ["egg_spider_wolf"] = {
        zh = "从母狼蛛腹部强行剥离的大号球形丝织卵囊。母蛛生前用生命守护的这团高蛋白卵球，在剥去外层致密蛛丝后下锅焯熟，是荒原猎人最顶级的纯天然能量药丸。",
        en = "A dense spherical egg sac carried fiercely by a mother wolf spider. Stripping away the tough outer silk and poaching the mass yields a concentrated bundle of survival energy.",
    },
    ["egg_stag_beetle"] = {
        zh = "一枚体型硕大、半透明外壳中能隐约看到幼虫缓缓蠕动的变异巨鹿角甲虫卵。外壳光滑坚韧如塑料胶囊，直接扔进开水锅里煮硬剥壳，口感宛如煮熟的鲜鲍鱼肉。",
        en = "A colossal translucent beetle egg revealing a developing larva within. The rigid capsule cooks like a firm sea scallop in boiling water, offering substantial, highly satisfying meat.",
    },
    ["egg_strange_bigfrog"] = {
        zh = "成片漂浮在池塘水面、厚实如小型浮岛的怪异巨型青蛙卵团。用捕鱼抄网整大网捞起，在营地大铁锅里加入野葱大火翻炒，足以让整支探险小队美美饱餐好几天。",
        en = "A buoyant flotilla of giant frog eggs blanketing stagnant pond surfaces like floating islands. Netting a large bucketful and boiling it with wild chives feeds entire exploration parties.",
    },
    ["egg_strider"] = {
        zh = "附着在水生植物茎秆上黏糊糊的湿润水黾大卵粒。表面覆盖着一层强力防水黏胶，用开水清洗脱胶后下锅煎熟，口感清脆弹牙，带有微弱的天然淡水甘甜。",
        en = "A sticky, glistening egg laid by overgrown water striders across reed stems. Rinsing off the water-repellent gelatin and pan-searing yields a crisp, slightly sweet freshwater treat.",
    },
    ["egg_sturgeon_lake"] = {
        zh = "来自淡水巨物湖鲟体内整副纯黑发亮的稀世极品鱼子包。颗粒硕大圆润，在旧世界堪称千金难求的顶级黑鱼子酱，如今在避难所篝火旁整勺大口吞食，极致奢华。",
        en = "A prized sack of glossy black roe taken from a massive freshwater lake sturgeon. Curing into world-class caviar, scooping it with wooden spoons beside a crude campfire feels wildly decadent.",
    },
    ["egg_sturgeon_shortnose"] = {
        zh = "从珍稀短吻鲟体内收获的顶级纯黑野生鱼卵。每一颗鱼籽都如抛光黑珍珠般晶莹饱满，入口在舌尖轻轻挤破，浓稠细腻的天然奶油风味在大脑中引发幸福的轰鸣。",
        en = "Rare dark caviar harvested from a shortnose sturgeon. Bursting with velvety, buttery marine creaminess, each mouthful provides an unforgettable shock of pure luxury amidst devastation.",
    },
    ["egg_sunfish"] = {
        zh = "从普通太阳鱼腹中采收的细密淡黄色野生鱼籽排。颗粒细腻且毫无杂质，与少许野韭菜一同在陶罐里蒸成鲜嫩的鱼子蛋羹，入口即化，是废土伤员最好的流质滋补品。",
        en = "Delicate pale-yellow roe gathered from freshwater sunfish. Steaming them inside clay pots with wild alliums creates a silky, custard-like porridge ideal for injured or feverish survivors.",
    },
    ["egg_turkey"] = {
        zh = "一枚从深山灌木丛火鸡窝里搜寻到的带褐色大斑点的野生火鸡大蛋。个头几乎是普通鸡蛋的两倍，浓郁的蛋黄在铁锅里煎熟，散发出令人垂涎欲滴的纯正野禽肉香。",
        en = "A speckled wild turkey egg retrieved from dense upland briars. Nearly twice the size of chicken eggs, frying its massive golden yolk releases an intoxicating, deeply savory wild fowl aroma.",
    },
    ["egg_turkey_domestic"] = {
        zh = "从废弃农场禽舍里搜刮到的沉甸甸白底麻点家养火鸡蛋。蛋壳坚硬厚实，富含丰富的优质脂肪与卵磷脂，打进滚烫的肉汤里搅散，能让整锅野菜汤变得浓郁醇厚无比。",
        en = "A heavy domestic turkey egg scavenged from abandoned poultry coops. Its rich lipids and dense albumen transform thin, watery dandelion soups into thick, comforting survival broths.",
    },
    ["egg_turtle_painted"] = {
        zh = "在向阳沙滩上费力刨出的一窝椭圆形锦龟软皮蛋。革质的外壳柔软而坚韧，即便煮熟蛋白也不会完全凝固，直接撕开外皮吸食里面热气腾腾的浓稠蛋黄，鲜美无匹。",
        en = "Leathery wild turtle eggs excavated from warm river sandbars. The pliable shells never fully harden when boiled, allowing you to tear the skin and slurp hot, rich yolks directly.",
    },
    ["egg_turtle_snapping_common"] = {
        zh = "冒着被断头指风险从凶残拟鳄龟巢穴里掏出来的圆滚滚乒乓球状龟蛋。外壳坚韧如橡皮，煮熟后蛋黄油脂丰富得流油，是在泥泞沼泽中搏命搜刮的最佳战利品。",
        en = "Spherical snapping turtle eggs dug up while watching your fingers around fierce nesting mothers. Cooking them over coals yields intensely rich, oily yolks that reward perilous swamp hunts.",
    },
    ["egg_vocal_bigfrog"] = {
        zh = "犹如一层厚重透明橡胶垫般漂浮在水面的鸣响巨蛙卵团。每一颗卵粒都如同大号果冻布丁，用砍刀切成规整方块下锅炖煮，口感筋道滑嫩，是极其耐饥的扎实口粮。",
        en = "A thick, rubbery mat of vocal giant frog eggs floating like a transparent raft. Sliced into tidy cubes with a machete and boiled, it yields a chewy, satisfying staple that curbs hunger.",
    },
    ["egg_void_spider"] = {
        zh = "散发着幽蓝荧光的虚空蛛卵珠；外表如同精致发光的奇异水晶球，放在避难所里当小夜灯格外浪漫，直到你隐约听到玻璃外壳内侧传出节肢动物细微的抓挠声。",
        en = "A luminescent bead housing an unhatched void spider; glowing with hypnotic alien brilliance, it serves as a lovely decorative nightlight right until you hear tiny spectral claws scratching the inside.",
    },
    ["egg_walleye"] = {
        zh = "从冷水大眼蛳鲈体内采掘的璀璨金黄色顶级野生鱼籽。在冰凉纯净的深水湖泊里孕育，用细盐抓匀腌渍半小时后直接食用，每一颗爆浆都带着极其清冽甘甜的湖鲜原味。",
        en = "Lustrous golden walleye eggs gathered from pristine deep-water lakes. Lightly salted and eaten fresh, each delicate sphere pops with refreshing sweetness that revitalizes weary paddlers.",
    },
    ["egg_warmouth"] = {
        zh = "从温口太阳鱼腹中采收的细密微黏鱼籽团。在平底锅里加入少许动物板油慢慢煎至两面金黄硬脆，焦香的鱼油混合着脆脆的口感，是长途行军路上极佳的高能口粮小零食。",
        en = "Tightly bound roe extracted from a feisty warmouth fish. Pan-fried in rendered lard into crisp, golden fritters, it provides high-energy crunchy snacks for arduous scouting treks.",
    },
    ["egg_wasp"] = {
        zh = "一枚从变异巨型胡蜂巢穴深处偷采的白色软质长卵。外观如同光滑的一大粒无瑕长米，外皮富有弹性，在铁板上稍微烘烤即散发出类似烘烤杏仁的诱人干香，毫无毒性。",
        en = "A pristine white wasp egg harvested from deep within a dangerous paper nest. Resembling a polished grain of rice, light grilling releases an almond-like fragrance completely free of stings.",
    },
    ["egg_water_beetle"] = {
        zh = "附着在沉水杂草根部的一小排椭圆形龙虱水生甲虫卵。外皮坚固且具有防水胶质，剥下来洗净泥沙丢进热汤里煮透，入口酥脆微弹，是不可多得的高蛋白天然配菜。",
        en = "Elliptical water beetle eggs anchored to aquatic roots by waterproof glue. Stripped and simmered in soup, their tender, popping bite provides invaluable protein in desolate wetlands.",
    },
    ["egg_water_bug"] = {
        zh = "产在水草叶片上的一小簇变异水蝎子长圆卵粒。外表带有奇特的微型呼吸角，虽然母虫长相凶神恶煞，但彻底煮熟的虫卵却异常鲜美甘甜，毫无任何不良异味。",
        en = "A clutch of water scorpion eggs bearing tiny filamentous respiratory horns. Despite the horrifying appearance of adult bugs, boiling the eggs produces sweet, harmless protein.",
    },
    ["egg_waxwing"] = {
        zh = "一枚带有淡灰蓝色底色与深色细碎斑纹的太平鸟小蛋。小巧坚硬的外壳里锁住了浓缩的纯净野禽蛋清，打进热气腾腾的松针茶里冲泡，是一杯令人心情大好的提神暖饮。",
        en = "A pale grayish-blue cedar waxwing egg sprinkled with delicate dark flecks. Whisked into a steaming mug of pine-needle tea, it provides a warm, nutritious morning beverage.",
    },
    ["egg_white_catfish"] = {
        zh = "从白鲶鱼腹中割取的一大串金黄发亮的黏稠野生鱼子。油脂极其丰厚，在铁锅里下入大量野蒜爆炒至外表微焦，浓郁的焦香味能让任何饥肠辘辘的幸存者大流口水。",
        en = "A glistening cluster of golden roe taken from a white catfish. Pan-seared with wild garlic, its lavish oily richness creates a deeply satisfying meal for famished survivors.",
    },
    ["egg_white_sucker"] = {
        zh = "从白吸盘鱼体内挤出的细小淡色野生鱼卵。在沸水里烫熟后捞出拌入少许粗盐与野葱，口感滑嫩清爽且极易下咽，是老人与虚弱病患补充体力的绝佳营养流食。",
        en = "Fine pale roe stripped from a freshwater white sucker fish. Blanched quickly in hot water and salted, its smooth, gentle texture provides effortless nutrition for convalescing invalids.",
    },
    ["egg_whitefish"] = {
        zh = "从大湖白鲑体内捕获的整副饱满大鱼子。在冰凉纯净的淡水深湖中生长，颗粒紧致弹牙，在冷烟熏房里慢熏两天，能制成极为硬实耐存的顶级便携鱼子肉肠干粮。",
        en = "A plump roe sack harvested from Great Lakes whitefish. Cold-smoking it over hardwoods yields an exceptionally durable, firm marine sausage packed with enduring survival energy.",
    },
    ["egg_whitefish_round"] = {
        zh = "来自圆白鲑体内的细小金黄高品质野生鱼卵。在平底锅里轻微烘干炒散，金黄的颗粒如同微型小米粒般干香酥脆，撒在烤熟的土豆块上，是不可多得的美味调味神品。",
        en = "Delicate golden eggs harvested from round whitefish. Toasted gently in an iron pan into dry, nutty granules, they serve as a savory, protein-dense topping across plain roasted tubers.",
    },
    ["egg_wood_frog"] = {
        zh = "在早春林间水洼里发现的垒球大小黏稠林蛙卵团。大团胶状物紧紧抱成一团，虽然直接看让人心里发毛，但用大铁锅煮熟后就是一盆富含胶原蛋白的浓稠高能量浓羹。",
        en = "A softball-sized cluster of gooey wood frog eggs scooped from early spring melt pools. Simmering the mass transforms wild pond jelly into a thick, warming pottage loaded with collagen.",
    },
    ["egg_woodpecker"] = {
        zh = "一枚从树干树洞深处小心掏出来的纯白色绒啄木鸟蛋。外壳光滑如白玉，蛋黄浓郁滑润，在经历了艰苦的林间伐木后敲开煎熟，是一份能让心头涌起暖流的珍贵犒赏。",
        en = "A glossy white downy woodpecker egg carefully extracted from deep tree cavities. Frying its rich, velvety yolk beside your woodchopping camp rewards difficult timber-felling labor.",
    },
    ["egg_worm"] = {
        zh = "在肥沃黑土深处翻找出来的微型土黄色蚯蚓卵茧。虽然每一颗只有火柴头大小，但在泥泞里翻挖一上午收集半碗洗净煮熟，依然是荒原求生中最接地气的活命蛋白质。",
        en = "A tiny amber earthworm cocoon unearthed from rich compost loam. Gathering a handful and boiling them clean provides humble, unglamorous survival protein during bitter mud seasons.",
    },
    ["egg_wormsnake"] = {
