    ["landmine"] = {
        zh = "伪装成普通碎石压盘的高爆反步兵地雷，冷酷无情的地面死神。埋下它需要惊人的勇气，而记住它的确切埋设位置则需要天才般的记忆力，否则半夜起夜将成为你此生最后的冒险。",
        en = "A high-explosive pressure mine waiting patiently beneath dirt and fallen leaves. Planting one takes nerve; remembering exactly where you buried it requires genius, lest a midnight stumble outside your camp triggers sudden, permanent retirement.",
    },
    ["landough_calrisean"] = {
        zh = "被达娜一家悉心喂养多年的老面酵头，散发着复杂迷人的酸香。即便外面的文明世界已经崩塌稀烂，只要这罐面糊还活着，人类对松软酸面包的执着追求就永远不会熄灭。",
        en = "A lovingly nurtured family sourdough starter radiating a complex, sharp fermentation scent. While global civilization lies in ruins, this bubbling jar ensures that humanity's divine right to fresh, crusty sourdough survives intact.",
    },
    ["lanyard"] = {
        zh = "印着某家倒闭科技公司花哨标志的尼龙挂绳，末世前用来悬挂门禁胸卡。现在它依然挂在幸存者的脖子上，只不过下面吊着的已经从打卡磁卡换成了开锁铁丝和生锈的避难所钥匙。",
        en = "A brightly branded corporate lanyard formerly used to display employee ID badges. It still hangs proudly around survivors' necks, though the plastic badge has been replaced by lockpicks, dog tags, and scavenged bunker keys.",
    },
    ["laptop"] = {
        zh = "一块电量早已耗尽的便携式电脑，内部硬盘里或许封存着灾前的机密文件或无聊游戏。如果找不到发电机和适配电源，这块沉重的塑料方块唯一的用处就是拿来当防弹板垫在胸口。",
        en = "A dead personal computer whose hard drive might hold classified scientific data or frivolous vacation photos. Without a generator or matching adapter, this bulky slab serves mainly as an improvised mousepad or blunt bludgeon.",
    },
    ["laptop_boris"] = {
        zh = "贴满奇怪代码标签与战术涂装的定制笔记本，据说是某位特工埃什的随身遗物。里面加密存储着大量不知所云的坐标，引诱着每一个好奇的蠢蛋踏入布满陷阱的军事基地。",
        en = "A ruggedized custom laptop covered in cryptic alphanumeric stickers and combat wear, formerly belonging to operative Ash. Its encrypted partitions lure curious scavengers toward heavily guarded military installations with promises of buried secrets.",
    },
    ["laptop_hard_case"] = {
        zh = "内置防震海绵的高强度聚碳酸酯手提箱，能在十米高空坠落中保护内部精密仪器。可惜在丧尸狂潮中，怪物们并不在乎里面的笔记本是否完好，它们只想把拎着箱子的你撕成两半。",
        en = "A heavy-duty crushproof case lined with custom shock-absorbing foam. It easily protects delicate electronics from catastrophic drops, though ravenous ghouls will happily rip off your arm without caring about hardware warranties.",
    },
    ["laptop_hard_case_back"] = {
        zh = "加装了战术背带的电脑保护硬箱，可以像背包一样紧紧固定在后背。它不仅能在奔跑时解放双手，还能在被背后偷袭的丧尸扑咬时，充当一块极为结实的塑料后心护甲。",
        en = "A rigid electronics case fitted with backpack straps to ride securely across your spine. It keeps hands free while sprinting through ruins, serving double-duty as a resilient plastic shield against cowardly surprise bites.",
    },
    ["laptop_hard_case_shoulder"] = {
        zh = "配有加厚单肩垫的便携电脑保险箱，散发着灾前高级IT工程师的干练气质。在泥泞废土中单肩挎着它狂奔极易滑脱，但至少能让你在逃命时依然保持某种荒诞的白领风度。",
        en = "A tough protective briefcase outfitted with an ergonomic shoulder strap. While sling-carrying a bulky polymer brick makes obstacle sprinting awkward, it preserves an absurd semblance of punctual commuter dignity amid burning wreckage.",
    },
    ["laptop_screen_lit"] = {
        zh = "屏幕依然幽幽发亮的工作笔记本，在黑暗地下室里投射出令人安心的蓝光。光芒虽然照亮了周围的废弃桌椅，也如同一座微型灯塔，热烈邀请着整个走廊里的游荡丧尸前来围观。",
        en = "A miraculously functioning laptop casting cool LCD glow across a pitch-black basement. While the bright light comforts weary eyes, it also acts as a homing beacon inviting every wandering creature down the hall to inspect.",
    },
    ["large_biogas_tank"] = {
        zh = "焊接粗糙但密封极好的巨型储气罐，专门用来收集粪便和烂菜发酵产生的沼气。只要你不在意它散发出的微弱臭气，罐子里沉甸甸的易燃气体就是你冬季取暖与做饭的终极底气。",
        en = "A massive sealed storage vessel designed to capture volatile methane bubbling from rotting manure. If you can stomach the nauseating bouquet, its pressurised contents guarantee warm winter nights and blazing cookstove burners.",
    },
    ["large_bone"] = {
        zh = "从巨型变异兽或史前标本上拆下来的粗壮腿骨，质地沉重且异常坚硬。在缺乏铁器的荒野中，不需要任何精细加工，直接握住一端就是一根能敲碎外骨骼的原始天然大棒。",
        en = "A dense femur scavenged from a gigantic mutant monstrosity. Free of meat and heavy as iron, it requires zero blacksmithing: simply gripping the narrow shaft yields an ancient, skull-cracking club ready for war.",
    },
    ["large_bone_fossil"] = {
        zh = "早已完全矿物化的古生物巨骨化石，坚硬程度堪比花岗岩石块。把它从自然博物馆里偷运出来需要惊人的体力，而在近战中挥舞这根千万年前的化石敲丧尸，充满历史沧桑感。",
        en = "A mineralized prehistoric fossil heavy enough to anchor a small yacht. Hauling it out of a museum wreckage was exhausting, but crushing modern necrotic abominations with primeval stone bone possesses magnificent poetic justice.",
    },
    ["large_bone_plaster"] = {
        zh = "博物馆展览用的巨型恐龙骨骼石膏翻模复制品，空心且外表刷了一层仿古漆。虽然看起来威风凛凛像一件神级骨槌，但只要用力朝丧尸砸下去，它就会当场粉碎成一地白色石膏粉。",
        en = "A hollow plaster replica of a museum dinosaur skeleton finished with faux petrified varnish. Though it looks like a fearsome primeval club, striking a zombie head will shatter it into useless chalky powder.",
    },
    ["large_damaged_shelter_kit"] = {
        zh = "被暴风雨或变异生物撕裂的大型简易避难所构件，帆布破洞且支架弯曲。想要用它遮风挡雨，你必须先花费大量胶带和绳索修补，否则躺在里面只会享受局部暴雨灌顶。",
        en = "Torn tarpaulins and buckled poles belonging to a battered prefab emergency shelter. Erecting it without extensive duct tape repairs ensures you enjoy indoor rainfall directly onto your sleeping bag throughout every midnight storm.",
    },
    ["large_lcd_screen"] = {
        zh = "从商场广告牌或会议室墙上拆下来的超大液晶面板，表面布满裂纹与灰尘。在没有电网驱动视频信号的今天，它最大的价值无非是拆出几块结实的光学有机玻璃和导电排线。",
        en = "A massive flat-panel display liberated from conference rooms or shattered billboards. Lacking power grids or video processors, its sole apocalyptic worth lies in salvageable acrylic sheets, thin diffusers, and copper ribbon cables.",
    },
    ["large_pressure_vessel"] = {
        zh = "采用厚重合金钢板焊接而成的重型承压容器，能够承受恐怖的内部气压。在化学狂热幸存者眼里，它既是建造高级蒸馏反应釜的核心元件，也是随时可能把整个营地送上天的大炸弹。",
        en = "A thick-walled steel vessel capable of containing enormous atmospheric pressure. In the hands of chemical scavengers, it serves as the heart of advanced stills or a terrifying accidental bomb waiting to level the compound.",
    },
    ["large_printout_portal_storm_data"] = {
        zh = "长达数米的连续针式打印纸，上面密密麻麻记录着传送门风暴期间的时空畸变读数。那些扭曲跳跃的正弦波曲线仿佛有生命一般，多盯上几分钟就会让你开始听到墙壁里的窃窃私语。",
        en = "Yards of continuous tractor-feed paper recording quantum fluctuations during catastrophic portal storms. Staring at its jagged sine waves too long induces headaches and makes the concrete walls seem like they are softly whispering.",
    },
    ["large_propane_tank"] = {
        zh = "常见于乡村住宅后院的巨大白色丙烷气罐，储量足以供应整个据点数月的热水与烹饪。唯一需要祈祷的是，流窜掠夺者的流弹千万别击穿它的减压阀，否则全镇都能看见这朵蘑菇云。",
        en = "A bulbous white fuel tank salvaged from rural homesteads, holding enough liquefied gas for months of survival cooking. One must pray stray bandit bullets never pierce the valve, lest the entire county witness the resulting fireball.",
    },
    ["large_repairkit"] = {
        zh = "装满各种精密锉刀、量规、冲子与优质润滑油的高级枪匠工具箱。拥有这套工具的幸存者在废土享有极高声望，毕竟谁也不想在扣动扳机反击狂暴僵尸时，发现自己的枪管当场炸膛。",
        en = "A comprehensive toolbox packed with gunsmith files, precision calipers, punches, and solvent bottles. Survivors guarding this set command supreme respect, since nobody enjoys clearing catastrophic weapon jams while being hunted down by beasts.",
    },
    ["large_shelter_kit"] = {
        zh = "包含加固支架与防风帆布的大型简易营地搭建包，展开后能容纳一个小队落脚。它是荒野求生的终极移动城堡，只要周围没有游荡的巨型变异酸蚁决定把你的帐篷当作开胃零食。",
        en = "A bundle of heavy-duty stakes and weatherproof fabric capable of housing a patrol squad. It forms the ultimate wilderness basecamp, provided no burrowing acidic monstrosities mistake your sturdy canopy for an all-you-can-eat midnight buffet.",
    },
    ["large_space_heater"] = {
        zh = "工业厂房常见的大功率电暖风机，外壳沉重且布满粗壮的加热丝。虽然能在一小时内烤干整间湿漉漉的避难所，但启动它所需的庞大电量，足以在十分钟内榨干你辛辛苦苦拼凑的电池阵列。",
        en = "A rugged industrial convection heater built to warm damp warehouses. While it can dry out soaked survivor shelters within an hour, its monstrous wattage drain will suck a cobbled solar battery bank dry in minutes.",
    },
    ["large_space_heater_on"] = {
        zh = "电热丝通红如晚霞般炽热的大型空间加热器，呼呼吹出滚烫的干燥热风。在零下二十度的严寒末日里，缩在它面前享受热浪是无上的奢华，前提是隔壁发电机隆隆的咆哮没把附近的尸群引来。",
        en = "A humming space heater glowing incandescent orange, throwing fierce heat into frozen air. Basking before its coils in mid-winter is absolute bliss, assuming the roaring generator powering it hasn't lured every zombie for miles.",
    },
    ["large_stomach_sealed"] = {
        zh = "从巨型变异兽腹腔里完整剥离并经过盐渍鞣制的厚韧胃袋，用皮绳扎紧充当大容量水囊。虽然里面的饮用水总带着一股淡淡的胃酸和腐食余味，但比起活活渴死，这股酸味简直如同甘霖。",
        en = "A massive mutant beast stomach cured in brine and bound tight with sinew. While every mouthful of stored water carries an unmistakable tang of dried gastric juice, it beats fatal dehydration in the scorching wilderness.",
    },
    ["large_storage_battery"] = {
        zh = "沉重得需要两人合力才能抬起的工业级超大容量蓄电池，内部储藏着难以置信的清洁电力。将它焊接进重型战车底盘，你就能彻底告别汽油发动机的震耳欲聋，享受悄无声息碾碎丧尸的快乐。",
        en = "An enormous industrial energy cell heavy enough to require two people or a crane to hoist. Installed into a deathmobile frame, it provides clean, silent kilowatts to grind through zombie hordes without engine noise.",
    },
    ["large_surface_pseudo"] = {
        zh = "游戏底层为了模拟平整桌面或宽阔加工台而生成的虚拟交互占位实体。哪怕在现实末世里你永远摸不到这团虚无的代码，你的潜意识依然本能地想在上面堆满乱七八糟的破铜烂铁。",
        en = "A virtual engine construct existing solely to represent broad crafting surfaces and tables. Though flesh hands cannot grasp abstract UI anchors, survivor instincts still compel you to clutter every flat tabletop with scrap metal.",
    },
    ["large_survival_kit_box"] = {
        zh = "装满急救用品、净水片、钓线和信号棒的加固生存铁盒，末世预备狂的毕生心血结晶。打开它就像拆开一份精心包装的圣诞礼物，唯一的遗憾是前主人显然没能靠它活过大灾变首日。",
        en = "A reinforced steel box containing emergency rations, water tabs, bandages, and flare sticks. Opening it feels like unwrapping a doomsday Christmas present, though its original owner clearly failed to survive day one.",
    },
    ["large_tent_kit"] = {
        zh = "配备加固铝合金骨架的大号野营帐篷包，防雨防潮且空间充裕。在危机四伏的森林中支起它，能给你带来虚幻的文明安全感，直到第一只游荡僵尸被帐篷拉绳绊倒并直接砸在你的脸上。",
        en = "A spacious family tent packed with sturdy aluminum poles and coated rainflies. Pitching it in deep woods brings an illusion of domestic comfort, until a stumbling zombie trips over the guyline and collapses onto your face.",
    },
    ["large_turbine_engine"] = {
        zh = "拆自主战坦克或喷气客机的高性能燃气涡轮引擎，重达数吨且能爆发惊人的六千马力。只要你的储油罐足够支撑这头油老虎的鲸吞，点火时掀起的气浪就能把挡路的狂暴丧尸直接吹飞上天。",
        en = "A monstrous multi-ton gas turbine stripped from a battle tank, kicking out six thousand horsepower. Fueling this beast requires an entire oil refinery, but roaring down the highway blows shamblers into low orbit.",
    },
    ["largebroketent"] = {
        zh = "龙骨折断、防雨面料被抓得千疮百孔的废弃大帐篷。横七竖八散落在草地上的破烂残骸，无声诉说着上一批露营幸存者遭遇变异熊夜袭时的绝望与狼狈，如今只剩几根勉强可拆的废铝管。",
        en = "A ruined camping pavilion with snapped struts and claw-shredded waterproof nylon. This tangled mess silently narrates the grisly fate of previous occupants ambushed at midnight, leaving behind only bent aluminum poles to salvage.",
    },
    ["lasagne"] = {
        zh = "在末日里能叠出多层肉酱与奶酪的千层面堪称贵族行径。即便肉馅的真正来源最好别细问，趁热下肚时带来的多巴胺也能让你短暂忘记窗外的丧尸咆哮。",
        en = "Stacking multiple layers of meat and melted cheese amidst the Cataclysm is pure aristocracy. Even if asking about the minced meat's origin is ill-advised, devouring it warm drowns out the zombie horde outside.",
    },
    ["lasagne_raw"] = {
        zh = "饿急了的幸存者会像啃纸板一样直接嚼生面皮。它既能磨牙又能发出足以引来半条街丧尸的清脆嘎吱声，但只要胃里不再泛酸水，尊严早就不值一提。",
        en = "Desperate survivors gnaw on raw pasta sheets like brittle cardboard. While the loud crunching echoes loudly enough to alert half the block's undead, dignity matters very little when your stomach is screaming.",
    },
    ["laser_rifle"] = {
        zh = "战前大公司为了争夺军火专利斗得头破血流，如今文明覆灭，只剩这把高精尖激光枪还在恪尽职守地将变异怪物融成焦炭——只要你的便携电源还没当场耗尽。",
        en = "Pre-Cataclysm mega-corporations sabotaged each other over its patent, yet now only this sleek laser rifle remains, dutifully turning mutated horrors into smoking ash—provided your bulky UPS pack has not died mid-firefight.",
    },
    ["laser_sight"] = {
        zh = "枪管下的红色光点能极大提升射击精度，唯一的小毛病是：当你试图在黑暗的居民楼里潜行时，那道耀眼的红光简直就像在向周围所有丧尸广播“外卖已送达”。",
        en = "Mounting a vivid red beam under your barrel drastically speeds up target acquisition. The only drawback is that during nighttime scrounging, it politely broadcasts your exact coordinates to every nocturnal predator nearby.",
    },
    ["latex"] = {
        zh = "从变异灌木里辛辛苦苦刮出来的白色树汁，既能熬成绝缘橡胶，也能在极度饥荒时勉强咽下。虽然喝下去的感觉就像在生吞未凝固的避孕套原料。",
        en = "White milky sap scraped from wasteland shrubs can be vulcanized into rubber or swallowed during catastrophic starvation. Mind you, chugging it feels remarkably like guzzling liquid condoms straight from the processing vat.",
    },
    ["lathe"] = {
        zh = "重达一百五十公斤的工业母机静静趴在车间废墟里。只要你能搞定三相动力电并把它拖回避难所，你就能把废铁车成任何形状——前提是搬运途中没压断脊椎。",
        en = "A three-hundred-pound metal monster sleeping silently in industrial rubble. If you solve three-phase power and drag it home without shattering your spine, you can spin scrap into precision parts for eternity.",
    },
    ["latrunculi"] = {
        zh = "罗马军团士兵用这套棋盘打发漫长的行军与围城，而在大灾变废墟的烛光下，两个满身血迹的幸存者也在下棋，并为吃掉对方一个木头骑兵争得拔出了手枪。",
        en = "Roman legionnaires once played this tactical game to endure grueling sieges. By flickering candlelight in ruined bunkers, blood-splattered survivors still argue furiously over wooden pieces, occasionally reaching for their sidearms over bad moves.",
    },
    ["launcher_ballista"] = {
        zh = "当现代火药彻底耗尽后，人类的暴力美学迅速倒退回古典时代。这架沉重的扭力弩炮能把大号石块砸进丧尸巨怪的脑袋，只是每次上弦都需要你用全身肌肉拼命死磕。",
        en = "When gunpowder dries up, apocalyptic ballistics happily regress to antiquity. This massive torsion engine hurls stone boulders through mutated brutes with devastating force, though cranking the winch back tests your lumbar sanity.",
    },
    ["lawn_dart"] = {
        zh = "战前因为极度容易扎穿邻居家小孩脑袋而被全面禁售的草坪游戏玩具。在丧尸横行的末世，它致命的空气动力学设计终于名正言顺地找到了一展拳脚的新舞台。",
        en = "Banned in civilized times for puncturing neighborhood kids' skulls during backyard barbecues, this heavy plastic dart finally found its true calling: plunging aerodynamically into the rotting foreheads of approaching zombies.",
    },
    ["lawnmower"] = {
        zh = "郊区中产阶级打理草坪的骄傲图腾，如今沦为草丛里生锈的铁疙瘩。幸存者拆下它的刀片当砍刀，拆下小汽油机装在推车上，彻底完成了割草工具的末日暴改。",
        en = "Once the suburban homeowner's weekend trophy, now a rusty iron relic choking in overgrown weeds. Clever scavengers strip its whirring blades for machetes and bolt its tiny engine onto armored grocery carts.",
    },
    ["lazy_lobster_casserole"] = {
        zh = "在末日里捕捞变异巨鳌虾并配上黄油饼干烘烤，这种奢靡的吃法堪称对废土苦难生活的莫大讽刺。唯一让人不安的是，这只龙虾生前可能也吃过不少落单的幸存者。",
        en = "Sautéing mutated river crustaceans in rich butter and crumbled crackers is supreme culinary decadence. The sole unsettling thought is remembering that this particular lobster grew so massive by feasting on drowned raiders.",
    },
    ["lc_arming_sword"] = {
        zh = "低碳钢打造的单手骑士剑，虽然硬度欠佳且在剧烈格挡后容易发生弯曲，但轻便的重量和适中的长度让初入废土的近战菜鸟也能挥舞得有模有样。",
        en = "Forged from soft mild steel, this arming sword bends under severe lateral strain, yet its friendly balance allows inexperienced survivors to execute basic slashing drills effectively.",
    },
    ["lc_aztec_spear"] = {
        zh = "把阿兹特克武士的古老长矛插上现代低碳钢刀刃，虽然缺少了黑曜石的锋利碎裂感，但至少捅在坚硬的骷髅丧尸身上时，钢刃不会当场崩得连渣都不剩。",
        en = "Fitting an ancient Mesoamerican spear with mild steel instead of fragile obsidian loses some surgical sharpness, but at least your cutting edges will not shatter into powdery glass upon impaling an armored skeleton.",
    },
    ["lc_aztec_sword"] = {
        zh = "镶满低碳钢片的阿兹特克阔头板剑。挥舞起来既有棒槌的钝击快感，又有锯齿撕裂皮肉的血腥效能。虽然低碳钢容易卷刃，但在废土上砸碎脑袋可不需要外科手术般的精细。",
        en = "Lined with mild steel plates along a stout wooden club, this brutal paddle blends blunt trauma with jagged slicing. The softer metal dulls rapidly, but cracking mutant skulls rarely requires razor-sharp perfection.",
    },
    ["lc_battleaxe"] = {
        zh = "采用低碳钢锻造的双刃战斧，斧刃厚重且极具威慑力，虽然劈入丧尸脑壳后经常因为钢质偏软而卡在骨头缝里拔不出来，但砸倒敌人的效果确实无可挑剔。",
        en = "Heavy and intimidating, this mild steel battle axe splits rotten skulls with authority, occasionally wedging its soft iron cheeks deep into bone during overenthusiastic downward chops.",
    },
    ["lc_brigandine_hands"] = {
        zh = "厚实帆布里铆接了数块低碳钢薄板，手感虽然略显僵硬，但当狂暴丧尸试图顺着你的手腕啃咬时，冰冷坚硬的金属夹层会给它的腐烂牙齿上一堂深刻的物理课。",
        en = "Sandwiched rivets and mild steel plates give these canvas gloves an awkward stiffness, but whenever a rabid zombie gnaws your wrist, the hidden metal delivers a rude dental lesson to its rotten jaws.",
    },
    ["lc_brigandine_hands_xs"] = {
        zh = "内部铆接低碳钢薄片的小号布面甲手套，虽然无法阻挡大口径步枪直射，但能有效防止丧尸在近身撕扯时咬烂你的手指，是轻装斥候的贴心护具。",
        en = "Featuring small mild steel plates riveted beneath canvas, these compact gloves protect nimble fingers from frantic zombie bites without overly compromising lockpicking dexterity.",
    },
    ["lc_broadsword"] = {
        zh = "带有篮状护手的低碳钢阔剑，护手能严密笼罩住整个手掌防止被碎玻璃和爪子划伤，虽然剑刃需要频繁用磨刀石修磨，但在混战中依旧是一把稳健的防身利器。",
        en = "Sporting a protective basket hilt over soft mild steel, this broadsword shields your knuckle joints during chaotic scuffles, even if the blade requires frequent evening sharpening sessions.",
    },
    ["lc_cavalry_sabre"] = {
        zh = "带有轻微弧度的低碳钢轻骑兵弯刀，划砍动作极其顺畅优雅，在跨越障碍奔跑时顺势掠过丧尸的脖颈能斩出深长伤口，只是砍到坚硬钢盔时容易卷刃。",
        en = "Sweeping with classic cavalry curvature, this mild steel saber cuts smoothly on running strikes, though accidental impacts against heavy steel helmets leave disheartening edge dents.",
    },
    ["lc_chain_link"] = {
        zh = "单独一枚低碳钢环渺小得像个被踩扁的钥匙扣。但只要你肯花费几百个小时用钳子机械重复地穿孔与铆接，无数个这种小环就能编织成一件拯救你小命的铁锁链甲。",
        en = "A single mild steel ring looks utterly pathetic, like a dropped key ring in the mud. Yet weave thousands of them together over weeks, and this tiny loop becomes lifesaving mail stopping feral claws.",
    },
    ["lc_chainmail_arms"] = {
        zh = "一对用低碳钢丝环环相扣编织的锁环护臂，套在手臂上能完全免疫丧尸的尖牙啃咬，唯一的缺陷是长时间浸泡在酸雨中很容易锈成两根僵硬的红褐色铁筒。",
        en = "Interlinked mild steel rings protect your forearms from ravenous teeth, though neglect in radioactive drizzle rapidly rusts the flexible mesh into two stiff, squeaking orange cylinders.",
    },
    ["lc_chainmail_aventail"] = {
        zh = "挂在头盔下沿的低碳钢锁环垂帘，能将锁骨和颈动脉严严实实地护在冷钢之后。除了每次转头时冷冰冰地铁环蹭得脖子发痒外，它确实防住了不少偷袭的利齿。",
        en = "Draping from your helm to encase neck and collarbones in mild steel rings, this heavy aventail guards vital arteries reliably, even if the cold greasy links relentlessly pinch your throat with every glance.",
    },
    ["lc_chainmail_face"] = {
        zh = "专门护住下巴与喉咙的锁环小面帘。虽然它能有效阻挡丧尸近距离扑咬，但冬天呼出的热气会在冰冷的铁环上结霜，让你每次张嘴说话都像在撕扯自己嘴角的皮。",
        en = "A modest chainmail veil protecting your throat and chin from desperate bites. Unfortunately, winter breath freezes instantly upon the steel links, painfully waxing your stubble every time you shout for cover.",
    },
    ["lc_chainmail_feet"] = {
        zh = "用成百上千个铁环编织成的钢丝脚套。穿着它踩在丧尸踩碎的碎玻璃上毫无感觉，但在雨天泥地里潜行时，那沉重湿滑的触感会让你觉得自己穿了两只吸饱水的铁铸潜水鞋。",
        en = "Booties knit from interlocking steel rings shrug off broken glass and jagged debris. Slogging through post-apocalyptic mud, however, makes them feel like soggy, ten-pound iron anchors clinging to your weary feet.",
    },
    ["lc_chainmail_half_legs"] = {
        zh = "覆盖小腿前侧的低碳钢锁环护胫，用皮带紧紧系在裤腿外侧，不仅能弹开变异爬行者突如其来的伏击扑咬，走起路来还会发出细碎而规律的金属叮当声。",
        en = "Strapped over trousers to guard vulnerable lower legs, these mild steel chainmail half-chaps foil crawling ankle-biters while accompanying your hiking strides with steady metallic chimes.",
    },
    ["lc_chainmail_hands"] = {
        zh = "这双全钢环手套让你能直接伸手去扼住带电或者带刺变异生物的喉咙。不过在零下几度的寒风里千万别徒手戴它，除非你想体验皮肤与低碳钢冰冷焊死在一起的酸爽。",
        en = "Enclosing fingers in flexible steel mesh lets you safely grapple thorny mutants. Just avoid wearing them barehanded during freezing blizzards unless you enjoy peeling your frostbitten skin off cold metal links.",
    },
    ["lc_chainmail_hauberk"] = {
        zh = "长及膝盖的传统低碳钢锁环长衣，密集的铁环提供了大面积的切割防护，虽然整件衣服沉甸甸得压得人直不起腰，但至少让你在丧尸群中更有底气。",
        en = "Extending down to your knees, this heavy mild steel hauberk repels slashing claws reliably, gradually convincing your aching shoulders that medieval infantry marches were exceptionally grueling endeavors.",
    },
    ["lc_chainmail_hauberk_xs"] = {
        zh = "专为娇小身材量身改短的低碳钢锁环长衣，减轻了下摆的多余重量，让体型敏捷的探索者在废墟中翻越断壁残垣时，既拥有可靠防护又不会被铁环绊倒。",
        en = "Scaled down for petite survivors, this shortened mild steel hauberk sheds unnecessary skirt bulk, letting nimble scouts vault shattered concrete barriers without tripping over trailing chainmail links.",
    },
    ["lc_chainmail_hood"] = {
        zh = "贴头佩戴的轻钢锁子头巾，能完美防止掠夺者的闷棍砸碎后脑勺。唯一的副作用是如果没戴内衬小帽，脱下它时你头顶原本就不多的头发会被硬生生扯掉一大撮。",
        en = "A close-fitting mail coif stopping blunt strikes from cracking your skull. Forgetting an arming cap underneath, however, means the hungry links will gleefully scalp your remaining hair whenever you yank it off.",
    },
    ["lc_chainmail_jumpsuit"] = {
        zh = "从头到脚全包裹的低碳钢锁环连体服，穿上它就像给自己套上了一层铁丝编织的全身外皮，防御面积无可挑剔，但若想一个人脱下来没有同伴帮忙几乎是不可能的。",
        en = "Enclosing your entire body in interlinked mild steel rings, this suit offers complete laceration immunity while proving virtually impossible to peel off without assistance from a friend.",
    },
    ["lc_chainmail_jumpsuit_xs"] = {
        zh = "紧凑版低碳钢锁环连体衣，细密的钢环紧密贴合身形，有效防止任何细小的变异寄生虫钻入衣物内层，只是穿久了之后衣服上的机油与汗味会让人难以忍受。",
        en = "Fitted snugly for narrow builds, this miniature chain jumpsuit keeps biting parasites off your skin, while absorbing sweat and motor oil until you smell like a submerged diesel workshop.",
    },
    ["lc_chainmail_legs"] = {
        zh = "全包式低碳钢锁环护腿，从大腿根部一直严密保护到脚踝，彻底消除了被低矮丧尸狗咬断腿筋的危险，缺点是每次蹲下翻找货架时膝关节都极其吃力。",
        en = "Enclosing legs completely in mild steel ring mail, these chaotic leggings eliminate fear of rabid mutant hounds, making deep scavenging squats feel like strenuous competitive powerlifting reps.",
    },
    ["lc_chainmail_sjumpsuit"] = {
        zh = "没有衣袖的低碳钢连体锁环衣，解放了双臂的活动范围，让你在举枪瞄准或是拉弓射击时毫不受限，至于暴露在外面的胳膊，就只能全凭自己的走位躲避伤害了。",
        en = "Leaving your arms completely free for swift archery draws or rifle aiming, this sleeveless mild steel suit protects your vitals while leaving forearms vulnerable to sudden ambushes.",
    },
    ["lc_chainmail_sjumpsuit_xs"] = {
        zh = "小号无袖低碳钢连体衣，轻量化的剪裁大幅降低了体力消耗，是废土中身材纤细的潜行猎手们在酷暑季节兼顾躯干防御与散热通风的理想战术装备。",
        en = "Cut for smaller silhouettes, this sleeveless mild steel jumper minimizes stamina drag, offering woodland stalkers a practical compromise between torso protection and summer heat dissipation.",
    },
    ["lc_chainmail_suit"] = {
        zh = "经典的低碳钢全身锁子甲套装，覆盖躯干与四肢，在面对刀剑和爪击时表现沉稳，虽然防御力不及高碳淬火钢，但容易修理，拿钳子和铁丝就能随时打补丁。",
        en = "A classic mild steel chainmail suit offering dependable anti-slash defense, favored by frontier tinkerers because bent or ruptured rings can be quickly repaired with pliers and scrap wire.",
    },
    ["lc_chainmail_suit_xs"] = {
        zh = "专为小体型人物打造的低碳钢全身锁甲，比例匀称且重心分布合理，虽然跑动起来依然像一麻袋铁器在互相碰撞，但至少不会因为铠甲晃荡而影响射击准度。",
        en = "Perfectly proportioned for smaller wanderers, this full mild steel mail suit balances mass evenly, clattering loudly during runs yet staying firm enough not to disrupt steady rifle marksmanship.",
    },
    ["lc_chainmail_vest"] = {
        zh = "仅覆盖胸腹核心部位的低碳钢锁环背心，用最少的钢铁重量换取了对心脏和内脏的基础防咬保护，是废土长途行商们最喜欢穿在厚夹克里面的贴身保命底牌。",
        en = "Protecting strictly chest and stomach, this lightweight mild steel chain vest tucks discreetly beneath leather coats, giving traveling merchants peace of mind without weighing down pack mules.",
    },
    ["lc_cutlass"] = {
        zh = "带有厚实护手圆盘的低碳钢短弯刀，挥舞起来兼具防守与劈刺功能，在狭窄的下水道和废弃地铁车厢里遭遇丧尸时，短小强悍的刀身总能发挥出意想不到的奇效。",
        en = "Featuring a solid bowl handguard, this short mild steel cutlass maneuvers cleanly through tight subway cars, turning chaotic close-quarters encounters into manageable hacking chores.",
    },
    ["lc_demi_gaunt"] = {
        zh = "皮革掌心套着锁环，手背覆着弯曲钢板，在灵巧开锁与硬抗撕咬之间达成了精妙的平衡。就算不小心被尸群逼入死角，你也能反手用手背的硬钢狠狠赏丧尸一记耳光。",
        en = "Combining chainmail palm flexibility with rigid back-of-the-hand steel plates strikes a neat compromise. Trapped in a tight doorway, you can deliver a bone-crushing steel backhand across any rotting ghoul's jaw.",
    },
    ["lc_elbow_guards"] = {
        zh = "简单敲弯的低碳钢肘弯护板，套在链甲外能有效化解从侧面袭来的钝击。虽然翻窗逃跑时金属肘尖总会发出刺耳的撞击声，但总比关节被丧尸一口咬碎强得多。",
        en = "Curving mild steel plates over your elbows wards off jarring blunt impacts against walls and claws. While they clatter loudly whenever you vault broken windows, intact joints easily outweigh stealth concerns.",
    },
    ["lc_elbow_guards_xs"] = {
        zh = "专为细胳膊打造的小号低碳钢护肘，弧形钢片用皮带牢牢绑在肘关节处，不仅能在被击倒翻滚时防止手肘碎裂，还能在近距离肉搏中充当凶狠的金属冲撞钝器。",
        en = "Strapped securely onto slender joints, these small mild steel elbow cops absorb pavement impacts during defensive dives while doubling as wicked blunt weapons in tight clenches.",
    },
    ["lc_esapi_plate"] = {
        zh = "避难所铁匠用低碳钢手工敲打出来的土味防弹板。虽然自重沉得像在胸口绑了块铺路石，防弹能力也比不上军规陶瓷，但面对土匪猎枪时，它确实能买你一条命。",
        en = "Hand-hammered from mild steel slab, this makeshift ballistic plate weighs down your chest like a sidewalk slab. It lacks ceramic refinement, yet stopping a raider's buckshot blast makes every bruised rib worthwhile.",
    },
    ["lc_esbi_plate"] = {
        zh = "六边形的钢制侧身防弹插板，厚重的低碳钢配上海绵衬垫，勉强堵住了肋骨侧翼的致命防御盲区。穿上它跑步虽然会硌得腰侧生疼，但至少不用担心被流弹穿腰而过。",
        en = "Bolstered with synthetic padding, this hexagonal side plate covers your vulnerable flanks against stray shrapnel. Running with it mercilessly bruises your floating ribs, but keeping your liver unperforated remains a winning trade.",
    },
    ["lc_estoc"] = {
        zh = "纯粹为刺击而生的低碳钢破甲剑，长棱锥形的剑身没有任何锋刃，虽然钢质较软导致不能用力硬撬铁门，但精准刺入变异丧尸的眼眶依然能造成致命的脑干破坏。",
        en = "Featuring an edgeless, triangular mild steel thrusting blade, this estoc should never be used to pry crates, yet slides into necrotic eye sockets with lethal, single-minded precision.",
    },
    ["lc_falx"] = {
        zh = "拥有恐怖内弧刀刃的低碳钢达西安战镰，劈砍时巨大的拉扯力能轻易将敌人的盾牌或肢体强行拽碎，即便钢材偏软容易卷刃，其野蛮的造型也足以吓退大部分匪徒。",
        en = "With a savage inward curve, this mild steel falx generates terrifying ripping torque upon contact, overcompensating for softer steel with pure, primeval limb-severing mechanical geometry.",
    },
    ["lc_greaves_brigandine"] = {
        zh = "结实帆布上整齐铆着一道道低碳钢板条，将迎面骨严密包裹。在灌木丛和尸群中突围时，无论是荆棘利刺还是潜伏在草丛里的爬行丧尸，都休想啃透你的小腿。",
        en = "Riveting parallel steel splints across sturdy fabric creates splendid protection for your shins. Slogging through thorny briars or crawling zombie swarms, your lower legs remain thoroughly immune to frantic snapping jaws.",
    },
    ["lc_heavyhelm_close"] = {
        zh = "重达近十斤的低碳钢全封闭头盔，扣上面罩的瞬间你就像缩进了一座铁铸碉堡。视野虽然被压缩成一道窄缝，但当巨型丧尸一拳砸过来时，你绝不会后悔把脑袋焊死在里面。",
        en = "Locking the heavy visor of this ten-pound steel helm transforms your head into an iron bunker. Your slit vision feels claustrophobic, yet you will praise that enclosure when a mutant brute swings a club.",
    },
    ["lc_heavyhelm_close_raised"] = {
        zh = "把沉重的钢面罩往上一推，清新空气和开阔视野立刻涌入肺部。当然，在面罩升起的状态下，你的整张脸也等于直接向阴影里潜伏的酸液喷吐者敞开了怀抱。",
        en = "Flipping the heavy visor upward restores peripheral vision and crisp air to your breathless lungs. Naturally, it also invites lurking spitters to bathe your unprotected nose in corrosive wasteland bile.",
    },
    ["lc_helm_close"] = {
        zh = "15世纪骑兵防具在末日工坊的重现。低碳钢锻造的面罩不仅能防刺击，还能在正面交火时有效阻挡丧尸溅出的黑色脓血，虽然呼吸孔吹出来的气味全是你自己的口臭。",
        en = "A faithful apocalyptic recreation of medieval cavalry armor. The closed visor halts slashing claws and infectious bile alike, though you must endure breathing your own foul, adrenaline-drenched stench for hours inside.",
    },
    ["lc_helm_close_raised"] = {
        zh = "掀起面罩不仅能让你看清脚下的绊线地雷，还能顺便喝口水喘口气。只是别忘了在拐入漆黑走廊前把它按回去，除非你打算用鼻梁硬接丧尸迎面飞来的骨棒。",
        en = "Raising the visor lets you spot tripwires and swig muddy canteen water comfortably. Just remember to slam it shut before clearing tight basements, lest a feral ghoul bash your unshielded face with a rock.",
    },
    ["lc_helmet_nasal"] = {
        zh = "维京掠夺者的经典防具，垂直护鼻钢片干净利落地从两眼之间垂下。它不挡视线也不闷热，并且能确保你在近距离肉搏战中不会被丧尸一拳打塌高挺的鼻梁骨。",
        en = "Authentic Viking craftsmanship featuring a vertical steel bar shielding the nose without narrowing peripheral vision. It keeps you ventilated and guarantees your nasal septum survives a savage punch from an enraged marauder.",
    },
    ["lc_helmet_turban"] = {
        zh = "带有浓厚中东风情的圆柱形钢盔，独特的穹顶能让当头劈下的钝器顺着弧面滑向一侧。虽然看起来像把一个倒扣的铁锅顶在头上，但保命效果可比时尚感实在多了。",
        en = "With its bulbous dome tapering upward, this steel helmet deflects downward blows gracefully off its curved crest. It looks remarkably like wearing an upside-down soup pot, but style yields humbly to skull preservation.",
    },
    ["lc_jian"] = {
        zh = "采用低碳钢锻造的中式双刃直剑，剑身在格挡重击时容易产生永久性弯曲，虽然无法像传世宝剑那样削铁如泥，但用它修习基础剑术或是挑刺丧尸依然十分顺手。",
        en = "A straight double-edged jian forged from mild steel, tending to hold a slight bend after heavy parries yet remaining an elegant practice weapon for disciplined martial artists.",
    },
    ["lc_katana"] = {
        zh = "用普通低碳钢板切割打磨成型的武士刀，虽然没有漂亮的烧刃纹与高超的淬火硬度，但宽厚的刀身保证了它在胡乱劈砍时不易折断，是废土新人的廉价武士梦。",
        en = "Ground from flat mild steel stock without fancy differential heat-treat lines, this beginner katana trades legendary Japanese myth for affordable, forgiving durability during frantic zombie brawls.",
    },
    ["lc_khopesh"] = {
        zh = "低碳钢铸造的古埃及镰状剑，镰刀般的弯曲刀头在勾拽丧尸兵器时极其有效，虽然材质较软导致刀刃需要频繁打磨，但沉重的重心挥砍起来依然威慑力十足。",
        en = "This mild steel khopesh combines sickle hooking utility with blunt chopping mass, demanding regular whetstone touch-ups while reliably ripping crude shields from startled wasteland raiders.",
    },
    ["lc_kilij"] = {
        zh = "用低碳建筑钢材粗暴锻打而成的奥斯曼式弯刀。刀头配有标志性的加宽加厚回砍破甲反刃，虽然钢材硬度一般且容易卷刃，但沉重的挥砍势能依旧能将奔跑中的丧尸整颗头颅齐刷刷削下。",
        en = "A crude reproduction of an Ottoman kilij forged from soft structural steel. Featuring an enlarged flared tip, its heavy forward balance delivers brutal chopping momentum that decapitates charging horrors despite requiring frequent whetstone honing.",
    },
    ["lc_knee_guards"] = {
        zh = "简陋但保命的低碳钢弧形护膝，专门防止你在末世跌进“膝盖中了一箭”的悲惨境地。即便被扑倒在地，钢壳也能护住脆弱的半月板，让你随时能爬起来继续逃命。",
        en = "Simple curved plates forged from mild steel to save your knees from crippling doom. Even if tackled onto concrete, your fragile kneecaps remain intact, letting you scramble up before the ravenous horde pounces.",
    },
    ["lc_knee_guards_xs"] = {
        zh = "采用冲压低碳钢皮弯折制成的特小号加固护膝。专为身材娇小或腿部异变的生还者剪裁，虽在受到变异大锤重击时容易变形凹陷，但好歹保护了脆弱的半月板免遭碎石尖刺扎穿。",
        en = "Extra-small knee guards hammered out of malleable low-carbon sheet metal. Tailored for petite scavengers, they bend under crushing impacts yet reliably shield fragile kneecaps from jagged rubble and venomous crawler bites.",
    },
    ["lc_knife_rambo"] = {
        zh = "模仿硬汉动作电影造型打造的低碳钢大型生存直刀。背齿粗糙且中空手柄里塞着几根受潮发霉的火柴，虽经不起剧烈撬撬，但握在手中至少能让胆小的幸存者产生无所畏惧的心理安慰。",
        en = "A cinematic survival bowie knife ground from mild carbon steel. Packing matches inside a hollow handle that weakens the tang, its fearsome jagged silhouette at least bolsters morale when lurking through pitch-black basements.",
    },
    ["lc_knife_trench"] = {
        zh = "带有铸铁指虎握把的低碳钢一战风格堑壕格斗刺刀。在逼仄无光的地下走廊里遭遇贴身缠斗时，你可以先用厚重的金属拳套砸碎丧尸的面门，再反手将三角尖刃狠狠送入颅骨眼眶深处。",
        en = "A brutal trench dagger fitted with an integrated cast-knuckle grip. Forged from workable low-carbon steel, it allows desperate scavengers to shatter rotting cheekbones with brass-knuckle punches before driving the spike deep into craniums.",
    },
    ["lc_kriegsmesser"] = {
        zh = "采用单刃弯曲刀身与木柄护手铆接制成的低碳钢大型战争战刀。双手紧握长柄大力横斩，厚重的刀刃能凭借蛮横的自重斩断四肢，虽然缺乏高碳钢的锋锐持久度，但在大乱斗中相当趁手。",
        en = "A two-handed curved war sword fashioned from low-carbon stock. Relying on sheer mass rather than razor sharpness, its wide blade cleaves through decaying limbs with satisfying authority during desperate crowd control brawls.",
    },
    ["lc_kukri"] = {
        zh = "具有标志性前曲重心与厚重背脊的低碳钢廓尔喀砍刀。劈砍性能极其凶猛，无论是深入荆棘丛生的沼泽密林开路砍伐藤蔓，还是在狭窄废墟门后伏击丧尸，向下猛劈的一击都势大力沉。",
        en = "A forward-curved kukri machete pounded out of ductile low-carbon plate. Its front-heavy balance generates ferocious chopping power, excelling equally at clearing tangled brambles and executing downward hacking strikes against ambushing ghouls.",
    },
    ["lc_lighthelm_close"] = {
        zh = "削减了钢板厚度的封闭轻盔，重量轻了一大截，你的颈椎终于不用天天哀嚎。虽然对大口径步枪子弹毫无抵御力，但弹开丧尸扑抓的爪子和飞石还是绰绰有余的。",
        en = "Thinner steel plating sheds crucial weight, sparing your cervical spine from chronic agonizing fatigue. While high-velocity rifle rounds will punch through easily, it happily bounces away rotting claws and hurled debris.",
    },
    ["lc_lighthelm_close_raised"] = {
        zh = "升起轻盔面罩能让你畅快地大口呼吸冷空气，甚至能朝队友大喊战术指令。但别在飞虫成群的沼泽地里这么干，否则扑面而来的变异蚊虫会顺着你的嗓子眼直接灌进去。",
        en = "Pushing this lightweight visor up lets you bellow tactical commands and inhale deeply. Avoid doing so near irradiated swamps, however, unless you fancy swallowing a dozen acidic mutant gnats in one breath.",
    },
    ["lc_link_sheet"] = {
        zh = "密密麻麻铆合在一起的低碳钢环网片。虽然单独拿在手里像块冰凉沉重的铁抹布，但在精通缝纫与锻造的幸存者眼里，这就是两小时后披在身上的救命防具雏形。",
        en = "Thousands of interlocking rings forming a pliable metal mesh that feels like a cold, greasy dishcloth. In an artisan survivor's hands, this clumsy scrap evolves into armor that halts lethal bites.",
    },
    ["lc_longsword"] = {
        zh = "依照中世纪经典形制手工敲打出来的低碳钢双手长剑。重心控制略微前倾，虽比不上真正军械库里的顶级弹簧钢剑条那般柔韧回弹，但在面对无甲软目标时依然能刺出极具威胁的贯穿伤。",
        en = "A handmade medieval longsword ground from mild steel bar stock. Lacking the resilient spring temper of authentic armory blades, its point nonetheless punches through unarmored zombie torsos with lethal puncturing leverage.",
    },
    ["lc_mace"] = {
        zh = "低碳钢铸就的钉头锤把手粗糙且容易磨出水泡，砸碎几只硬壳变异甲虫后棱角还会肉眼可见地变钝。但无论金属怎么变形，物理学定律依然能把对面的颅骨直接敲个稀烂。",
        en = "Forged from soft steel, this homemade mace blunts visibly after bashing through chitinous carapaces. Its handle blisters your palms mercilessly, yet pure Newtonian momentum still pulps zombie foreheads with brutal, undeniable efficiency.",
    },
    ["lc_mirror_armor"] = {
        zh = "在粗糙皮甲上拼贴几块抛光低碳钢方板，虽然没能复原古代近卫军的华贵光彩，但当你在烈日下迎风站立时，晃眼的镜面反光说不定能先把扑过来的掠夺者眼睛闪瞎。",
        en = "Patching polished steel plates over a leather cuirass lacks imperial majesty, but standing against midday sun creates brilliant glare. If the armor fails to stop a bullet, blinding your attacker might buy time.",
    },
    ["lc_mitten_gaunt"] = {
        zh = "连指板金手套让你的手指完全无法做精细活，开保险或者掏钥匙都成奢望。但当你一记重拳挥在铁头丧尸面门上时，整块连体钢板的反冲力绝对能让你体验到铁锤般的快感。",
        en = "Clumping your fingers together under arched steel plates obliterates fine motor skills, making lockpicking impossible. However, clobbering an armored ghoul feels like swinging an iron ingot bolted directly to your knuckles.",
    },
    ["lc_nodachi"] = {
        zh = "刀身长达数尺、造型极其夸张的低碳钢重型野太刀。由于钢质偏软导致整把刀份量沉重无比，拔刀出鞘都需要退后两步，但抡圆后的狂暴斩击范围足以将身前三米内的矮小变异体尽数拦腰斩断。",
        en = "An oversized Japanese field sword beaten from heavy structural flat bar. Awkward to draw in tight spaces, sweeping its massive arc keeps approaching mutant hounds at bay through sheer reach and momentum.",
    },
    ["lc_pike"] = {
        zh = "一根长逾四米、顶端装配冲压低碳钢菱形矛尖的超长方阵长步枪。两人一组在狭窄公路哨卡上架起长枪阵，能在丧尸爬行者甚至变异疯牛靠近前，远远地将其钉死在几米开外的公路地面上。",
        en = "A four-meter infantry pike tipped with a stamped mild-steel socket point. Braced against paved highway barricades, a defensive spear wall halts lunging zombie predators well before their rotting claws can reach defenders.",
    },
    ["lc_rapier"] = {
        zh = "带有精细碗形护手和纤细刺击剑刃的低碳钢刺剑。由于未经严苛淬火回火，在强行刺击厚重防暴盾牌时容易永久弯折，但在对付轻装行尸时，一剑穿眼的速度快如闪电且优雅致命。",
        en = "A slender thrusting rapier fitted with an elaborate swept hilt. Prone to bending against hard ceramic armor, its needle point darts forward with lightning speed into soft ocular sockets during nimble duels.",
    },
    ["lc_sabaton"] = {
        zh = "铰接钢片层层叠叠包覆在靴子表面，走起路来哐当作响像个移动铁匠铺。但当你一脚重重踩在爬行丧尸的颈椎骨上时，那声清脆的断裂音会证明负重跑步完全是值得的。",
        en = "Articulated plates clanking over your sturdy hiking boots turn every stealth attempt into a marching gong. Still, stomping through a crawling zombie's spine with cold steel heels yields immense, crunching satisfaction.",
    },
    ["lc_scimitar"] = {
        zh = "拥有优雅大弧度弯曲刃线的低碳钢东方马刀。在荒野开阔地带奔跑或骑乘机车呼啸掠过敌人身侧时顺势拉刀拖割，即便钢口不算锋利，凭借高速相对运动也能轻易切开喉管与肌腱。",
        en = "A sweeping oriental scimitar forged from malleable leaf spring steel. Gliding effortlessly through fleshy targets during high-speed vehicle drive-bys, its wide belly executes devastating draw-cuts that sever grasping tendons.",
    },
    ["lc_shoulder_guards"] = {
        zh = "两片冲压成弧形的低碳钢护肩，安装在布面甲上能防止上方坠物或尸群从高处飞扑啃咬。唯一的麻烦是钻过狭窄通风管道时，它们总会卡在管壁边缘发出刺耳的刮擦声。",
        en = "Curved steel pauldrons strapped over your shoulders protect against descending ceiling claws and blunt rubble. Unfortunately, squirming through rusted air ducts causes them to screech against metal walls, alerting every ghoul downstairs.",
    },
    ["lc_shoulder_guards_xs"] = {
        zh = "用几块冲压低碳钢片铆合叠缀而成的特小号金属护肩。专为体型瘦削的侦察兵设计，牢固绑在双肩外侧，能够有效分散高处掉落碎砖的砸击，并防止丧尸居高临下扑咬你的锁骨神经。",
        en = "Extra-small articulated shoulder pauldrons riveted from light steel plates. Sized for slender agile scouts, they deflect glancing claw swipes and protect vulnerable collarbones from jagged falling building masonry.",
    },
    ["lc_spear_steel"] = {
        zh = "将低碳钢矛尖紧固在长木杆顶端的经典猎矛。结构虽然质朴无华，但两米左右的有效安全距离与直截了当的穿刺手感，让它成为每一个废土新兵告别近战恐慌的最可靠武器起步选择。",
        en = "A simple steel-headed hunting spear bound to a straight ash shaft. The generous two-meter reach keeps dripping zombie jaws safely distant while providing intuitive, repeatable thrusting mechanics for nervous recruits.",
    },
    ["lc_steel_bar_flat"] = {
        zh = "一根平平无奇的矩形低碳钢条，工业文明里最平凡的加工母料。在废土铣床主轴的轰鸣下，它可以变成锋利的长刀、坚固的铰链，或者在深夜遭遇偷袭时充当顺手的防身闷棍。",
        en = "An unassuming rectangular bar of mild steel, quintessential fodder for machine shops. Under a humming milling cutter, it transforms into lethal bayonets, heavy hinges, or a heavy bludgeon during midnight ambushes.",
    },
    ["lc_steel_bar_round"] = {
        zh = "重达近二十公斤的实心圆钢棒，未经车床旋削前就是一块纯粹的工业肌肉。要是把它从二楼阳台直接朝底下路过的丧尸脑袋扔下去，其重力加速度造成的毁伤绝不逊色于迫击炮弹。",
        en = "Nearly twenty kilos of dense cylindrical steel waiting for a humming lathe. Dropping this colossal solid billet from a second-story fire escape onto a wandering zombie hits with the crushing fury of a mortar.",
    },
    ["lc_steel_chunk"] = {
        zh = "一块从废墟机械上敲下来的扭曲低碳钢块。既能充当锻造炉里的原料，也能当临时铁锤敲钉子，甚至还能塞进袜子里做成流星锤，让胆敢逼近的土匪领教脑震荡的滋味。",
        en = "A jagged chunk of twisted steel salvaged from shattered machinery. It serves as furnace scrap, an emergency hammer, or a weighted bludgeon stuffed inside a woolen sock to give aggressive raiders acute concussions.",
    },
    ["lc_steel_facemask"] = {
        zh = "挂在头盔下方的粗糙低碳钢面罩，把鼻子和下巴严密包裹在冷钢内。虽然它能替你挡下飞溅的骨刺和酸液，但说话时闷在铁皮里的沉闷回音，会让你听起来像个感冒严重的铁皮人。",
        en = "Strapped below your helmet, this crude faceplate shields your mouth and nose from acidic vomit. The muffled resonance inside turns every battle shout into the nasal grunting of an asthmatic tin soldier.",
    },
    ["lc_steel_lump"] = {
        zh = "沉重扎实的规整低碳钢锭。在锻造炉彻底烧透前，你甚至可以用它压住避难所被狂风吹得乱晃的铁皮屋顶；或者丢在公路上当路障，把掠夺者横冲直撞的皮卡轮胎当场硌爆。",
        en = "A solid, hefty ingot of mild steel. Until your forge fires up, it works nicely anchoring rattling tin roofs against radioactive gales, or puncturing the tires of aggressive raider buggies charging your gate.",
    },
    ["lc_steel_staff"] = {
        zh = "坚韧白蜡木棍的两端箍上了沉重的低碳钢保护套。舞动起来呼呼生风，虽然没有刀刃那么血肉横飞，但每一记横扫都能利用力矩轻松敲碎丧尸的膝盖骨和下颌。",
        en = "Thick mild steel caps encase both tips of this heavy hardwood stave. Whirling it creates frightening momentum; while it lacks blades, the mechanical leverage snaps zombie femurs and shatters rotten jaws effortlessly.",
    },
    ["lc_talwar"] = {
        zh = "带有独特圆盘形配重刀柄与宽身弧刃的低碳钢印度塔瓦弯刀。圆盘刀首将手腕紧紧锁定，强迫射手以小臂带动手腕进行纯粹的弧形下切劈斩，在近身肉搏战中展现出惊人的撕裂杀伤力。",
        en = "An Indian curved talwar sword featuring an enclosed disc pommel forged from mild steel. Locking the wrist into position, it channels shoulder strength into vicious downward chops that carve through rotten flesh.",
    },
    ["lc_vambrace_brigandine"] = {
        zh = "夹在帆布夹层里的低碳钢条顺着小臂整齐排列，抬手格挡时宛如立起一面微型护盾。即便硬接丧尸迎面劈下的锈水管，钢板也能将冲击力迅速分散，保全你的尺骨。",
        en = "Parallel steel slats sewn inside tough canvas forearm sleeves act like miniature tower shields. Raising your guard absorbs direct blows from swinging iron pipes, saving your forearm bones from splintering into fragments.",
    },
    ["lc_wakizashi"] = {
        zh = "传统日式短刀造型的低碳钢配刀。紧凑的尺寸便于反手插在腰带内侧，在室内被数只丧尸扑倒压在地板上时，这是你无需大幅度挥臂就能反手捅进恶臭咽喉的最后一根救命稻草。",
        en = "A compact Japanese short sword hammered from scrap steel flat stock. Tucked discreetly into utility sashes, it serves as the ultimate close-quarters backup weapon when wrestling pinned beneath undead horrors.",
    },
    ["lc_warhammer"] = {
        zh = "在硬木短柄上焊接了低碳钢方锤头与后背破甲钩的钝器战锤。全凭自重与离心力砸击目标，哪怕金属头因为敲击花岗岩有些变形，也丝毫不妨碍它一锤将防暴头盔和颅骨砸成扁平肉饼。",
        en = "A spiked warhammer welded from low-carbon stock atop a solid oak handle. Relying on blunt percussive kinetic transfer, deformation matters little when its heavy square face caves in reinforced riot helmets.",
    },
    ["lc_wire"] = {
        zh = "从废弃铁丝网上抽出来的低碳钢丝，纤细却坚韧。它能绑紧摇摇欲坠的车辆防撞杠，也能拉在走廊门槛边做成诡雷绊线，教不长眼的入侵者见识一下什么是真正的四脚朝天。",
        en = "Pulled from abandoned security fencing, this stiff steel wire is pure survival utility. It lashes dented bumpers together or strings across dark thresholds as tripwires, sending nocturnal intruders crashing onto broken glass.",
    },
    ["lc_zweihander"] = {
        zh = "长达近两米、带有防夺刀双突刺护叉的低碳钢重型双手中世纪巨剑。挥舞起来风声呼啸如狂风过境，虽然沉得像扛着一根铁轨，但向前全力旋转横扫一圈能把贴身的整个尸群逼退三步。",
        en = "A monstrous two-handed greatsword ground out of structural steel. Unwieldy and exhausting to brandish in tight corridors, sweeping its broad crossguard through a clearing forces approaching swarms backward in panic.",
    },
    ["le_havre"] = {
        zh = "包含大量木质货船和港口建筑棋子的硬核德式桌游。在现实世界所有航道彻底瘫痪、物资极度匮乏的末日废土上，围坐在昏暗油灯下模拟法国港口经商算账，有一种荒诞绝伦的幽默感。",
        en = "A heavyweight board game simulating maritime commerce in historic French docks. Strategizing shipping routes and building warehouses around a smoky tallow candle offers wonderfully absurd escapism while real-world supply lines lie utterly destroyed.",
    },
    ["lead"] = {
        zh = "柔软而沉重的灰暗金属，自古以来就是制造枪弹与防辐射的最佳原料。在废土上熔化铅块时记得戴好防毒面具，否则还没被丧尸咬死，你的脑细胞就已经先被铅蒸气毒光了。",
        en = "Soft, dense, and grimly useful for casting homemade bullets or shielding radioactive fallout. Always don a respirator when melting it down, lest boiling lead fumes melt your brain cells long before mutants attack.",
    },
    ["lead_plate_xedra_mark"] = {
        zh = "从医院放射科防辐射背心上拆下的厚重铅板，背后焊着钢板加固。塞进防弹背心里虽然沉得让人直喘粗气，但面对变异体喷吐的高能辐射时，这块沉重的护板就是你的第二个器官。",
        en = "Salvaged from a hospital radiography vest and reinforced with steel backing, this plate is absurdly heavy. Shoving it into your tactical vest induces wheezing, yet it shields your organs from lethal gamma flares.",
    },
    ["leather"] = {
        zh = "割自战前破旧皮夹克或者废弃沙发的一小块六英寸皮革。它是废土手艺人的万金油补丁，无论磨破的靴底、开裂的枪套还是漏风的防风面罩，全靠这块小皮子缝缝补补。",
        en = "Scavenged from a ruined leather jacket or vintage sofa cushion, this humble square patch is essential tailor fuel. It mends blown-out boot heels, reinforces holster straps, and patches drafty respirators against radioactive grit.",
    },
    ["leather_armor_cow"] = {
        zh = "鞣制厚皮与刺绣布料缝制的全套牛用战铠，上面甚至还绣着恶龙与狮鹫的史诗决斗。穿在避难所的老黄牛身上虽然滑稽无比，但至少能保住你每天清晨唯一的鲜牛奶来源。",
        en = "Boiled leather barding embroidered with mythic dragons battling regal griffins, tailored exclusively for livestock. Your milk cow looks hilariously aristocratic wearing it, but keeping bovine flanks safe from mutant wolves preserves fresh dairy.",
    },
    ["leather_armor_horse"] = {
        zh = "用厚重熟牛皮手工鞣制缝合而成的马用全身防护皮马铠。严密包裹战马的胸腹颈部，既能防范荒野低矮灌木尖刺刮伤皮肉，也能在遭遇游荡狼群伏击时为坐骑争取脱身冲刺的关键生机。",
        en = "Heavy boiled leather barding crafted to fit riding horses. Protecting the equine chest and flanks from biting brush and snapping wolf jaws, it keeps precious mounts alive through hostile frontier travels.",
    },
    ["leather_bellow"] = {
        zh = "木板与熟牛皮组合成的古老风箱。双手反复挤压拉伸就能向锻炉送出咆哮的氧气流。在没有鼓风电机的末世，正是这规律的呼哧呼哧声支撑起了整个避难所的冶金产业。",
        en = "A timeless contraption of seasoned wood and pliable cowhide that blasts oxygen into glowing charcoal. Without electric blowers, this rhythmic puffing keeps your makeshift forge alive, hammering crude scrap into lifesaving weaponry.",
    },
    ["leather_belt"] = {
        zh = "一条带黄铜扣的结实皮带。除了在严重营养不良的末日里勒紧你缩水好几圈的裤腰带，侧面的挂扣还能随时别上一把剥皮折刀，提醒你生存与饥饿只有一扣之遥。",
        en = "A rugged leather belt with a solid buckle. Beyond keeping your pants from dropping off your starved, scrawny waist, its loops securely holster a survival knife—reminding you how thin the line is between hunger and survival.",
    },
    ["leather_cat_ears"] = {
        zh = "纯黑皮革缝制而成的猫耳发箍，防御力彻底归零。但在所有规则与体面荡然无存的破败世界里，戴上一对傲娇的猫耳朵去砍杀丧尸，是幸存者对残酷现实最荒唐的朋克嘲讽。",
        en = "Glossy black leather cat ears mounted on a headband offering zero defensive value. Yet stalking through apocalyptic ruins slaying ghouls while wearing feline ears remains the ultimate satirical mockery of modern civilizational collapse.",
    },
    ["leather_cat_tail"] = {
        zh = "填充了塑料小珠的漆黑皮质猫尾巴，走起路来会在身后随性摆动。虽然它既不能当鞭子抽人也不能保暖，但只要你自己不觉得尴尬，尴尬的就是对面迎面走来的掠夺者。",
        en = "Weighted with plastic pellets, this glossy leather tail sways rhythmically behind you as you march. It cannot lash enemies nor provide warmth, yet projecting sheer bizarre confidence easily bewilders any superstitious wasteland raider.",
    },
    ["leather_collar"] = {
        zh = "缀着一枚哑音小铜铃的黑色皮革项圈。原本可能是情趣用品或宠物配件，戴在脖子上虽然毫无防弹效果，但至少那颗安静无声的铃铛不会在潜行摸哨时出卖你的位置。",
        en = "A snug black leather choker adorned with a mute little bell. Originating as pet gear or fetish wear, its silent pendant thankfully never jingles, keeping your position concealed while crawling through infested corridors.",
    },
    ["leather_filing"] = {
        zh = "抹满粗砺石英沙的生硬皮革片，废土工匠在砂纸用尽后的绝妙发明。虽然打磨枪托时会把手掌磨得通红发痛，但比起用粗糙铁锉毁掉精细木纹，它已经温和太多了。",
        en = "A patch of tough hide slathered in coarse river sand, the scavenger's rough substitute for sandpaper. Smoothing rifle stocks with it burns your fingertips, yet it avoids carving ugly gouges into delicate wood.",
    },
    ["leather_funnel"] = {
        zh = "用防水油脂反复浸泡过的锥形皮革漏斗。在酸雨倾盆的废土荒野上架在塑料桶口，它能把每一滴天降甘霖汇聚进壶中——只要你记得先测试一下收集的水有没有强腐蚀性。",
        en = "Waxed leather folded into a crude cone funnel to harvest falling showers. Perched over an empty jug, it gathers precious precipitation—provided you remember to test whether the falling drizzle dissolves flesh before drinking.",
    },
    ["leather_harness_dog"] = {
        zh = "采用多道加固熟牛皮带与黄铜搭扣拼接缝制的军犬战术挽具。贴合伴侣犬的背部与胸腹肌肉，上方配有牢固的牵引握把与外挂小包扣，让忠诚的四足伙伴也能分担几公斤搜刮干粮。",
        en = "A riveted leather working harness fitted with brass buckles for companion dogs. Contoured across canine shoulders, its integrated dorsal grab handle and miniature side pouches allow loyal hounds to pack emergency rations.",
    },
    ["leather_journal"] = {
        zh = "装订结实的厚牛皮日记本，封面散发着陈年鞣质与雨水的混合气味。每一位拾荒者都曾在第一页写下豪迈的生存誓言，可惜翻过三页后，剩下的空白往往只能用来撕下生火。",
        en = "A rugged leather-bound notebook smelling of aged tannin and stale rainwater. Many survivors enthusiastically draft grandiose survival credos on page one, only to tear out subsequent blank leaves for kindling three days later.",
    },
    ["leather_police_jacket"] = {
        zh = "厚重硬挺的黑色交警皮革夹克，兼具防风保暖与抵挡丧尸啃咬的扎实防御。穿上它走在废土高速公路上，你甚至能找回几分执法者的威严，可惜游荡的狂暴飞车党只会对你鸣笛扫射。",
        en = "A heavy, stiff highway patrol leather jacket providing superb windproofing and decent bite resistance. Strolling along cracked asphalt in it lends a phantom aura of authority, though roaming bandits will simply shoot at you regardless.",
    },
    ["leather_pouch"] = {
        zh = "用鞣制熟皮手工缝制的小腰包，抽绳一拉就能将所有零碎杂物牢牢束紧。在翻箱倒柜的搜刮中，它永远被塞满生锈铁钉、几粒抗生素和舍不得扔的糖纸，是流浪者的移动藏宝库。",
        en = "A supple leather pouch closed with a sturdy rawhide drawstring. Scavengers instinctively cram it with bent nails, loose antibiotics, and cherished candy wrappers, turning their belts into miniature traveling vaults of assorted post-apocalyptic bric-a-brac.",
    },
    ["leather_stone_pouch"] = {
        zh = "专为弹弓射手设计的半硬质皮革石子袋，开口宽大便于单手盲操取弹。在缺乏火药弹药的荒野里，摸出光滑鹅卵石悄无声息打爆变异鸟脑袋的快乐，绝不亚于开枪的快感。",
        en = "A semi-rigid leather hip pouch tailored for quick one-handed access to sling ammunition. In a bullet-starved world, plucking a river stone to silently brain a mutant fowl offers unmatched, ammo-free satisfaction.",
    },
    ["leather_tarp"] = {
        zh = "将多块厚实皮革精心拼接缝合的重型防水皮布，沉重得像一块湿透的毛毯。把它搭在树枝上就是避雨顶棚，裹在身上就是抵御寒潮的防风斗篷，唯一的缺点是湿水后腥臊扑鼻。",
        en = "A heavy sheet crafted from stitched cowhides, weighing almost as much as wet carpet. It serves equally well as a waterproof lean-to roof or winter bivouac wrap, provided you tolerate its gamey stench after downpours.",
    },
    ["leatherbone_armor_cow"] = {
        zh = "用煮沸硬化熟皮并用粗大兽骨加固的全套牛用战铠，将温顺的乳牛武装成一辆活体骨刺坦克。只要你的牲口没有被沉重的骨甲吓瘫在草地上，它就能在尸群中蛮横地撞开一条生路。",
        en = "Boiled leather barding studded with bleached animal bones, transforming docile dairy cows into living siege engines. Assuming the beast doesn't collapse under the weight, its spiked silhouette terrifies roaming ghouls into giving way.",
    },
    ["leatherbone_armor_horse"] = {
        zh = "用坚韧熟皮与削尖肋骨编织而成的末世战马装甲，散发着野蛮游牧部落的肃杀气息。骑在身披骨甲的骏马上疾驰冲锋极具末日废土大片感，前提是你的坐骑没有被尖锐骨刺硌破皮肤。",
        en = "Stout leather barding reinforced with sharpened skeletal ribs, outfitting your mount with savage warlord flair. Galloping across scorched plains atop a bone-plated stallion feels glorious, provided the crude rivets don't chafe the horse raw.",
    },
    ["leatherbone_harness_dog"] = {
        zh = "在牛皮犬用挽具表面缝嵌了磨尖变异兽骨尖刺的野战防护背带。不仅外观凶悍残暴，任何试图飞扑撕咬战犬颈部的变异捕食者都会被尖锐骨刺反扎得满嘴鲜血，极大提升了宠物的战斗生存率。",
        en = "A protective canine combat harness reinforced with carved animal bones and protective outward spikes. Any feral predator attempting to throat-bite your trained warhound receives a bloody mouthful of sharpened bone.",
    },
    ["leathersandals"] = {
        zh = "由两块厚熟皮底和几根可调皮带拼接打结制成的简易皮凉鞋。透气轻凉且赤足感极强，虽然踩到碎玻璃或被生锈铁钉扎到会极其酸爽，但在炎炎夏日涉水摸鱼时是难得舒爽的轻便鞋履。",
        en = "Simple leather sandals fashioned from thick hide soles tied with rawhide thongs. Permitting cool airflow during blistering summer heatwaves, they keep bare soles cushioned against scorching tarmac.",
    },
    ["leaves"] = {
        zh = "从路边变异灌木上随手抓来的一把干枯树叶。除了在避难所壁炉里充当转瞬即逝的引火物，当你在荒郊野岭遭遇突发腹泻时，这捧粗糙的叶片就是你唯一能指望的文明替代品。",
        en = "A crinkly clutch of forest leaves scooped from muddy undergrowth. Beyond offering five seconds of crackling fire kindling, discovering these dry leaves during sudden wilderness gastrointestinal emergencies feels like striking pure, unrefined gold.",
    },
    ["leech_flower"] = {
        zh = "长满红色脉络与吸盘状肉质花瓣的诡异变异植物，靠近时能闻到淡淡的血腥味。把它做成药剂需要冒着被花刺倒钩吸血的危险，但其惊人的止血凝固特性让每一个垂死伤员欲罢不能。",
        en = "A disturbing carnivorous blossom pulsing with vermilion veins and tiny fleshy suckers. Harvesting its medicinal nectar risks getting bitten by predatory thorns, yet its miraculous clotting power keeps bleeding survivors crawling back for more.",
    },
    ["leg"] = {
        zh = "从某种大型变异生物身上生生砍下来的粗壮下肢，肌肉纤维粗大且泛着诡异的荧光。哪怕在极度饥荒的寒冬，盯着这根长满肉瘤和硬毛的大腿，你也需要巨大的心理建设才敢下锅。",
        en = "A severed limb butchered from an unidentified mutant brute, striated with fibrous tissue and eerie bioluminescence. Even during starving blizzards, staring at this bristled monstrosity requires tremendous stoic denial before tossing it into the stewpot.",
    },
    ["leg_bag"] = {
        zh = "紧紧绑在大腿外侧的战术吊袋，能在剧烈奔跑和翻越废墟时保持重心稳定。任何摸过它的幸存者都会在里面塞满急救绷带和备用弹匣，祈祷自己永远没有机会在跪地时拉开拉链。",
        en = "A tactical drop-leg pouch tethered firmly around the thigh to prevent bouncing during acrobatic sprints. Scavengers load it with tourniquets and backup magazines, praying they never have to frantically unzip it while bleeding out behind cover.",
    },
    ["leg_sheath6"] = {
        zh = "固定在小腿外侧的多联装飞刀皮鞘，能整齐插入六把平衡良好的投掷飞刀。它让你在近身对峙中看起来宛如冷酷的刺客大师，尽管在实战中你很可能在拔出第二把刀前就被丧尸扑倒。",
        en = "A calf-mounted leather carrier holding six balanced throwing knives in snug slots. It lends survivors an aura of deadly martial precision, even if they usually panic and fumble the draw before the first ghoul lunges.",
    },
    ["leg_small_bag"] = {
        zh = "绑在大腿上的紧凑型战术附包，容积不大但贴合度极佳。它是存放多功能军刀、打火机和防风火柴的最佳位置，保证你在被怪物扒光外套狂奔时，依然保有重启文明的火种。",
        en = "A compact pouch cinched around the thigh, perfectly sized for everyday utility essentials. Keeping a multi-tool and waterproof matches secured here ensures you retain the tools to rebuild fire even if cornered and stripped of heavy gear.",
    },
    ["leg_splint"] = {
        zh = "用两根结实木条和破布条紧紧绑扎的简易腿骨夹板。虽然戴上它走路一瘸一拐且速度慢如蜗牛，但比起任由断骨在肌肉里互相摩擦穿刺，这种被木棍强行固定的钝痛简直是无上救赎。",
        en = "Rigid wooden slats lashed around a fractured shin with torn denim straps. Hobbling along with it feels painfully clumsy, but prevents broken bone ends from grinding internally while you limp back to safety.",
    },
    ["leg_warmers"] = {
        zh = "用彩色毛线织成的复古健美操暖腿套，散发着上世纪八十年代的迪斯科热潮气息。虽然对丧尸尖牙没有半点抵挡力，但在零度以下的寒风中，温暖小腿肌肉至少能让你逃跑时少抽一次筋。",
        en = "Knit acrylic sleeves pulled over lower legs, evoking fluorescent aerobics studios from a bygone era. They offer no protection against biting horrors, but warming stiff calves prevents sudden agonizing cramps while sprinting for your life.",
    },
    ["leg_warmers_f"] = {
        zh = "用捕猎剥下的厚实动物毛皮简单缝制的护腿套，保暖性能狂暴得像直接把腿塞进了熊肚子里。在暴风雪呼啸的旷野中踏雪前行，只要不被融化的雪水泡烂，它能让你的双腿始终热气腾腾。",
        en = "Thick fur pelts stitched together into burly leggings that trap furnace-like body heat. Trudging through howling blizzards becomes almost cozy, provided the raw pelts remain dry enough to avoid rotting into foul, frozen sludge.",
    },
    ["leg_warmers_xl"] = {
        zh = "尺寸夸张的大号针织暖腿套，专门为变异肥胖或体型魁梧的重装幸存者量身编织。套在臃肿的防化服或变异粗腿外面，它以一种滑稽却极其务实的姿态守护着你的关节不被冻僵。",
        en = "Extra-large knitted sleeves tailored to accommodate bulky hazmat trousers or heavily mutated calves. Wrapping snugly over oversized limbs, they cut a hilarious figure while genuinely keeping stiff joints from freezing solid in arctic ruins.",
    },
    ["leg_warmers_xlf"] = {
        zh = "专为长出反曲蹄足或粗壮兽腿的变异幸存者定制的厚重毛皮护踝套。它不仅完美包裹了变异肢体上的敏感关节，还让原本狰狞可怖的半兽化双足显出一种荒诞的野蛮时尚感。",
        en = "Massive fur wraps modified for mutated digitigrade legs or hooves. Beyond insulating vulnerable transformed joints against bitter frostbite, they lend monstrous hooves an uncanny touch of wild, prehistoric winter couture.",
    },
    ["leg_warmers_xs"] = {
        zh = "采用腈纶毛线织就的特小号贴身针织保暖腿套。套在纤细小腿肚上能有效锁住下肢热量，在寒风呼啸的晚秋早晨，它们是防止腿部肌肉在激烈奔跑时突然抽筋痉挛的暖心小配件。",
        en = "Extra-small knitted acrylic leg warmers tailored for slender calves. Trapping body heat around lower shins, they keep leg muscles supple and prevent crippling cramps during dawn scavenging sprints.",
    },
    ["leg_warmers_xsf"] = {
        zh = "带有毛茸茸人造软毛内衬的特小号时尚保暖腿套。虽然在泥泞的废墟里走一圈就会沾满苍耳与丧尸黑血，但穿上它在避难所镜子前照一照，总能让人回忆起大灾变前流行文化的青春活力。",
        en = "Fancy faux-fur trimmed extra-small leg warmers rescued from boutique ruins. Though quickly fouled by swamp muck and gore, their whimsical flair brings colorful nostalgic cheer to grim bunker living.",
    },
    ["leg_xlsplint"] = {
        zh = "采用粗大原木和加厚帆布带精心制作的加大号骨折夹板，专为巨型变异幸存者的粗壮骨骼设计。固定这种粗腿需要两人合力拉紧带子，疼痛之剧烈甚至能让狂暴变异人当场痛得流下眼泪。",
        en = "An oversized leg splint crafted from heavy lumber and thick canvas straps, built to immobilize mutated limbs. Binding it securely requires two strong adults, producing agony intense enough to make even hardened hulks weep openly.",
    },
    ["leg_xs_splint"] = {
        zh = "用两根削薄木片和绷带缠绕而成的小号夹板，适合纤细肢体或幼年幸存者的断腿。在缺乏麻醉剂的残酷末世，给哭泣的孩子或虚弱同伴绑上这根夹板，是对施救者心理承受力的终极考验。",
        en = "A miniature splint assembled from thin wooden laths and gauze, sized for petite limbs or wounded youths. Fastening this brace without painkillers tests the emotional fortitude of whoever must tighten the unforgiving cords.",
    },
    ["leg_zed"] = {
        zh = "一条从变异感染者身上完整扯下的腐烂残腿。带着断裂发黄的股骨和发黑剥落的僵硬死肉，挥舞起来又臭又沉，虽然恶心得让人干呕，但急眼时拿来当投掷钝器敲碎丧尸天灵盖倒也别具讽刺意味。",
        en = "A severed, putrefying zombie leg complete with an exposed, jagged femur. Dripping blackened gore and reeking foully, brandishing this grim bludgeon serves as poetic, morbid retribution against surrounding undead.",
    },
    ["leggings"] = {
        zh = "高弹性化纤面料制成的贴身紧身裤，轻便透气且完全不影响肢体做出高难度战术动作。唯一的缺点是面料单薄得如同蝉翼，不仅防不住丧尸利爪，连路边的荆棘灌木都能把它刮成布条。",
        en = "Stretchy synthetic trousers that hug skin tightly and allow unrestricted athletic movement. Their featherweight fabric offers zero armor value; walking through roadside brambles is enough to shred them into scandalous rags.",
    },
    ["leggings_thessalonian"] = {
        zh = "借鉴东罗马重装甲骑兵风格打造的重型层叠护腿，全覆式钢片与熟皮交织出坚不可摧的防护。穿上它你就是中世纪战场的移动要塞，只要不掉进泥沼里，成群的丧尸只能无助地磨平指甲。",
        en = "Heavily articulated plate-and-leather leggings inspired by elite Byzantine cataphract cavalry. Striding through ruins encased in this steel shell makes you invulnerable to low-tier teeth, unless you tumble into muddy drainage ditches.",
    },
    ["legguard_acidchitin"] = {
        zh = "用硅化酸蚁甲壳拼合打磨而成的异种护腿，表面泛着幽绿色的耐酸光泽。不仅硬度比肩高碳钢，还能完全免疫腐蚀性酸液喷淋，是深入酸蚁巢穴搜刮虫卵的不二神装。",
        en = "Exotic greaves sculpted from biosilicified acid ant carapaces, gleaming with an oily, chemical-resistant sheen. Harder than high-carbon steel, they laugh off corrosive bile sprays during suicidal nest-scavenging expeditions.",
    },
    ["legguard_bronze"] = {
        zh = "表面打磨得锃光瓦亮的古典青铜护胫，弧线优雅地包裹住小腿迎面骨。迎着末世斜阳奔跑时它闪耀着荷马史诗般的英雄光芒，只是在潮湿地窖里呆久了容易长满绿油油的铜锈。",
        en = "Burnished bronze greaves curving gracefully over shin bones, echoing classical hoplite antiquity. Charging through mutant wastelands in them feels like an ancient myth, until persistent damp basements coat them in chalky green verdigris.",
    },
    ["legguard_ch_brigandine"] = {
        zh = "在坚韧帆布夹层中密密麻麻铆接了细密锁子甲环网的护腿装甲。兼具了锁甲的优异防割抗劈砍性能与布面的消音吸震特质，奔跑时静音效果出色，能为双腿提供均衡可靠的近战防御。",
        en = "Brigandine leg guards reinforced with integrated chainmail mesh between heavy cloth layers. Muffling metal jingling while deflecting slicing machete cuts, they keep scout legs agile and well-armored.",
    },
    ["legguard_ch_brigandine_xs"] = {
        zh = "特小号剪裁的锁子甲复合帆布护腿板。完美贴合轻巧身形，在保证关节灵活大角度屈伸的同时，锁甲内层能有效阻绝变异爬行虫与矮小丧尸的致命撕咬，是敏捷型近战斥候的首选下肢甲。",
        en = "Extra-small chain-reinforced brigandine leg protectors sized for nimble scouts. Allowing unhindered sprinting and deep squats, internal mail links stop low-crawling zombie ankle-biters in their tracks.",
    },
    ["legguard_chitin"] = {
        zh = "用打磨过的巨型变异昆虫甲壳鳞片层叠编织的护腿，质轻而坚韧。虽然防御力惊人，但走起路来甲片互相摩擦会发出清脆的沙沙声，就像一只巨大的蟑螂正在废墟走廊里欢快漫步。",
        en = "Overlapping scales harvested from giant mutant beetle exoskeletons, strung into flexible armor. Extremely tough yet lightweight, their only downside is the clicking clatter they make, announcing your approach like an oversized cockroach.",
    },
    ["legguard_hard"] = {
        zh = "采用厚重工程塑料与减震泡沫复合压制的专业防暴护腿。无论是面对丧尸的疯狂飞踢还是近距离钝击，它都能完美吸收冲击力，堪称下三路肉搏战中最让人安心的塑料防线。",
        en = "Impact-resistant polymer guards backed by closed-cell shock foam, straight from riot police arsenals. Absorbing crushing kicks and feral club strikes effortlessly, they provide total peace of mind during chaotic close-quarters brawls.",
    },
    ["legguard_hc_brigandine"] = {
        zh = "内衬重型加厚帆布与密密麻麻冲压铁片的重装步兵护腿。分量沉重但结构极其扎实，走动时金属铆钉在帆布间轻微摩擦，能直接正面硬抗钝器重击与乱箭攒射，是攻坚巷战的铁壁。",
        en = "Heavy-canvas brigandine leg armor lined with overlapping riveted steel splints. Substantially weighty yet extremely resilient, it absorbs crushing blunt hammer blows and flying shrapnel in violent street skirmishes.",
    },
    ["legguard_hc_brigandine_xs"] = {
        zh = "专为小体型战士量身打造的重型帆布布面铁甲护腿。厚实的加固层将膝盖和小腿严密保护在内，无论是在乱石堆里滑跪寻找掩体还是突入狭窄地道，都能让双腿免受致命撞击创伤。",
        en = "Extra-small heavy-canvas brigandine leg guards engineered for compact defenders. Encasing shins within overlapping plates, they permit aggressive sliding tackles into concrete cover without fracturing kneecaps.",
    },
    ["legguard_larmor"] = {
        zh = "经过植物单宁反复浸泡鞣制并烘干硬化的重型皮护胫，边缘缝线粗壮结实。它能有效抵御大部分变异犬类的撕咬，只要平时注意上油保养，这副护腿甚至能比穿着它的主人活得更久。",
        en = "Thick cuir-bouilli greaves hardened by repeated wax boiling and vegetable tanning. Capable of repelling savage dog jaws, with regular tallow polishing this durable leg armor will easily outlive its desperate scavenger owner.",
    },
    ["legguard_lc_brigandine"] = {
        zh = "将多块低碳钢薄条用铆钉密集固定在厚帆布内衬上的条板护腿。虽然外观平平无奇像裹了两截厚护膝，但在遭遇偷袭下盘的丧尸狗时，这些坚硬钢条能救下你的整条小腿肌肉。",
        en = "Splints of mild steel securely riveted between layers of rugged canvas. While visually resembling lumpy quilted gaiters, those concealed metal bars prevent scavenging zombie hounds from tearing your Achilles tendons to shreds.",
    },
    ["legguard_lc_brigandine_xs"] = {
        zh = "采用轻型薄帆布与轻量合金薄片铆合而成的特小号轻质护腿。自重极轻且毫无阻碍感，在提供基础防刮防刺能力的同时完全不拖累冲刺速度，适合长距离潜行奔袭的流浪荒原猎人。",
        en = "Light-canvas extra-small brigandine leg guards riveted with thin metal plates. Prioritizing featherweight mobility over heavy siege defense, they shrug off briars and dog bites during woodland sprints.",
    },
    ["legguard_mc_brigandine"] = {
        zh = "采用中等厚度帆布与多排弧形钢板铆接制成的平衡型布面护腿。在防御厚度与穿戴负重之间找到了绝佳平衡点，既不会让你走几步就气喘吁吁，又足以弹开多数近战挥砍与丧尸爪击。",
        en = "Medium-canvas brigandine leg guards featuring rows of overlapping curved steel plates. Achieving an ideal compromise between encumbrance and protection, they reliably turn aside melee slashes.",
    },
    ["legguard_mc_brigandine_xs"] = {
        zh = "特小号标准中型帆布布面铁甲护腿。板型收束服帖，能够牢固绑缚在皮靴外侧，是小体型巡逻队员在清理狭窄超市货架走廊或下水道管网时兼顾灵活性与安全性的中坚防具。",
        en = "Extra-small medium-canvas brigandine leg guards contoured snugly over boots. Offering dependable shin armor without bulky protrusion, they excel during high-risk sweeps of confined supermarket aisles.",
    },
    ["legguard_metal"] = {
        zh = "用锻打熟铁板弯曲敲打成型的手工铁护胫，沉重质朴且毫无装饰。它能硬接丧尸铁管的结实挥击，唯一需要忍受的是出汗后贴肉铁板磨破皮肤，顺便附赠一股挥之不去的铁锈味。",
        en = "Hand-hammered wrought iron plates bent into rigid shin protectors without decorative pretense. They easily deflect swung lead pipes, though walking miles in them rubs shins raw and leaves skin smelling permanently of oxidized iron.",
    },
    ["legguard_metal_sheets"] = {
        zh = "从报废汽车车门或通风管道上裁剪铁皮手工敲弯的护腿。边缘粗糙甚至还有毛刺，奔跑时哗啦作响像带了两对金属响板，好在它确实能在近距离挡住丧尸的指甲抓挠。",
        en = "Sheet metal sheared from junked car panels and hammered into crude leg wraps. Their ragged burred edges rattle like tambourines during jogs, but they reliably turn aside jagged claws that would otherwise flay your shins.",
    },
    ["legguard_metal_sheets_greaves"] = {
        zh = "经过细致修边并加装了皮带搭扣的铁皮护胫，工艺比纯废料拼接更上一层楼。它能稳稳扣紧在皮靴上方，防止你在穿越杂草丛生的瓦砾堆时被尖锐碎玻璃和断钢筋扎穿脚踝。",
        en = "Carefully trimmed sheet steel greaves outfitted with scavenged leather cinch straps. Snapping securely over hiking boots, they shield vulnerable lower legs against hidden rusty rebar and shattered plate glass lurking beneath overgrown rubble.",
    },
    ["legguard_metal_sheets_hip"] = {
        zh = "由多片活动铁皮冲压拼接挂在腰间的简易铁裙甲，专为保护髋骨与腹股沟而生。虽然走路时下摆金属片会不断碰撞胯部发出叮当响声，但能保住致命大动脉的安全比任何体面都重要。",
        en = "An articulated skirt of light steel plates suspended from an old work belt to shield hips and groin. The plates clank rhythmically against your pelvis with every stride, but safeguarding femoral arteries easily outweighs quiet dignity.",
    },
    ["legguard_metal_sheets_knees"] = {
        zh = "用铁皮敲打成碗状并衬以碎布垫层的简易钢护膝。当你为了躲避炮火或潜行搜刮而不得不整天在水泥地上跪爬时，这对铁碗就是拯救你半月板与膝盖软骨的无名英雄。",
        en = "Dished steel cups padded with cloth rags and strapped over vulnerable knees. When crawling across shattered concrete to evade turret sensors, these crude domes save your patellas and cartilage from permanent, crippling agony.",
    },
    ["legguard_paper"] = {
        zh = "把好几本废旧电话簿和硬纸板用胶带厚厚缠在小腿上的极限制品。虽然看起来滑稽无比且极其怕水，但其紧密的纸层结构在抵挡普通丧尸牙齿撕咬时，有着超乎想象的奇效。",
        en = "Several phonebooks and layers of corrugated cardboard wrapped tightly in duct tape. While comic to behold and destroyed by rain, dense pressed paper offers surprisingly respectable resistance against dull human teeth.",
    },
    ["legguard_qt_brigandine"] = {
        zh = "采用厚实绗缝棉布作为内衬垫底、外层铆合钢制骨片的软甲布面护腿。多层棉花吸收了大量钝击震波，使得穿戴者即使挨上一闷棍也不至于小腿骨折，穿戴体感柔软舒适宛如包裹棉被。",
        en = "Quilted padded brigandine leg guards packed with dense layers of cotton beneath riveted steel splints. The thick quilting cushions blunt concussive trauma, preventing fractured tibias under club strikes.",
    },
    ["legguard_qt_brigandine_xs"] = {
        zh = "特小号绗缝保暖型复合布面护腿。紧凑包裹下肢，在深秋与寒冬废土执勤时不仅能抵御敌人劈砍，还能充当出色的保暖护腿，防止刺骨穿堂冷风吹透关节引发老寒腿关节疼痛。",
        en = "Extra-small quilted brigandine shin guards pairing steel plates with insulating down padding. Delivering robust melee barrier defense, they simultaneously keep lower extremities warm on freezing winter watches.",
    },
    ["legguard_scrap"] = {
        zh = "用铁罐皮、合页与生锈铁丝七拼八凑捆在腿上的绝望护甲。它几乎是在丧尸围城的最后一刻紧急拼凑出来的产物，除了给穿着者提供心理安慰外，往往最先刺伤的正是自己的小腿。",
        en = "Tin cans, loose hinges, and rusty baling wire slapped together in blind desperation. Cobbled together minutes before a breach, it provides emotional reassurance, though its sharp wire tips frequently poke your own calves.",
    },
    ["legguard_tire"] = {
        zh = "用锋利裁刀从废旧重卡轮胎上割下来的厚橡胶护腿，内嵌坚固的钢丝编织层。厚实得几乎能反弹丧尸的啃咬与小口径流弹，代价是橡胶在烈日下散发出令人窒息的硫化焦味。",
        en = "Tough tire treads sliced from abandoned semi-trucks, retaining internal steel wire belts. Thick enough to bounce dog fangs and stray shrapnel, they punish the wearer with suffocating hot rubber fumes under summer sun.",
    },
    ["legpouch"] = {
        zh = "绑在脚踝上方的超小型隐藏弹药袋，刚好能塞下一只微型备用弹匣或几发散装子弹。它是特工与末日幸存者压箱底的绝招，专门留给被丧尸按倒在地上时做出最后的翻盘一击。",
        en = "A discreet pouch strapped above the ankle, holding one compact magazine or loose rounds. It represents the ultimate desperate ace-in-the-hole, meant to be unholstered when tackled flat on your back in the mud.",
    },
    ["legpouch_large"] = {
        zh = "容量可观的大腿战术弹药包，内部有弹力带分隔，能稳稳插入多只步枪弹匣。在突围火并中单手快速下探就能摸到新弹匣，只要你奔跑时不会被这沉甸甸的铁块甩得失去平衡。",
        en = "A high-capacity thigh pouch fitted with elastic loops to hold heavy rifle magazines. Snatching a fresh reload on the run feels smooth and tactical, provided several pounds of ammunition don't throw your sprint off balance.",
    },
    ["legrig"] = {
        zh = "带有快拆搭扣的多功能战术腿挂平台，表面布满标准魔术贴与织带接口。你可以按心情在上面挂载手枪套、医疗包或手榴弹袋，将整条大腿打造成一座移动的小型战术武器库。",
        en = "A modular drop-leg panel covered in webbing straps and quick-detach buckles. It allows scavengers to configure sidearms, medkits, or grenade pouches directly onto their thigh, turning one leg into a portable tactical arsenal.",
    },
    ["legrig_wetsuit"] = {
        zh = "专为潜水服设计的轻量化氯丁橡胶腿挂小袋，不仅排水迅速而且完全不受泥沙锈蚀影响。无论你是在被洪水淹没的地下地铁站潜水，还是在沼泽里淌泥跋涉，它都能紧紧吸附在腿上。",
        en = "Neoprene thigh pouches tailored for amphibious operations, draining water instantly and immune to salt corrosion. Whether diving flooded subway tunnels or wading murky marshes, they cling smoothly without dragging down your swim stroke.",
    },
    ["lemon"] = {
        zh = "从废弃超市冷柜或荒野温室里搜刮到的鲜黄色柠檬，散发着提神醒脑的柑橘清香。在坏血病悄然蔓延的末世废土，咬下一口酸得让人面部扭曲的柠檬，是维系生命与理智的奢侈体验。",
        en = "A bright yellow citrus fruit miraculously scavenged from an abandoned greenhouse. In a wasteland where scurvy lurks behind every canned meal, braving its eye-watering sourness provides vital ascorbic acid and a sharp shock of vitality.",
    },
    ["lemonade"] = {
        zh = "用压榨柠檬汁混合清水与珍贵白糖调配出的冰凉柠檬水。在烈日炙烤柏油路的酷暑午后，喝下一大口酸甜微凉的饮料，能让你在几秒钟内忘却身边游荡的丧尸与毁灭的世界。",
        en = "Freshly squeezed lemon juice mixed with clean water and rationed white sugar. Downing a chilled jar on sweltering summer afternoons makes you momentarily forget the burning ruins and roaming horrors outside.",
    },
    ["lemonade_powder"] = {
        zh = "一小包灾前生产的速溶柠檬风味固体饮料粉，富含人造色素、柠檬酸与糖精。只要有一壶浑浊的过滤死水，倒进去用力摇晃几下，就能把带有土腥味的泥水变成带气泡的柠檬味神仙水。",
        en = "A foil packet of artificial lemon beverage crystals packed with citric acid and saccharin. Stirred into murky filtered pond water, it miraculously masks stagnant ditch flavors with bright, chemical sweetness.",
    },
    ["lemonlime"] = {
        zh = "铝罐装的经典柠檬青柠味碳酸汽水，开罐时依然能听到悦耳的二氧化碳嘶嘶声。猛灌一口任由气泡在舌尖炸裂，那份熟悉的工业甜味是无数幸存者在噩梦惊醒后最想念的旧日幻影。",
        en = "An intact aluminum can of classic citrus soda that still hisses with carbonated pressure when cracked open. That prickly, bubbly burst of artificial lime is the sweetest reminder of extinct supermarkets survivors could ask for.",
    },
    ["lens"] = {
        zh = "从高级单反相机或精密实验室仪器上小心拆卸下来的高透光镀膜玻璃镜片。只要找到镜筒，它就能用来组装望远镜或高倍瞄准镜，让你在几百米开外就辨认出狂暴丧尸的丑恶嘴脸。",
        en = "A precision-ground optical glass element coated to eliminate reflections, liberated from laboratory gear. Fitted into a tube, it forms telescope optics that let you identify deadly mutants long before they catch your scent.",
    },
    ["lens_crude"] = {
        zh = "用厚玻璃瓶底经过粗糙磨砂与抛光手工打磨出来的凸透镜，内部充满微小气泡与划痕。用来瞄准射击会让人视线扭曲头晕目眩，但在晴朗无风的日子里拿来聚焦阳光点火，效率惊人。",
        en = "A bubbly glass disc ground from heavy bottle bottoms and roughly polished with sand. Looking through it causes dizzying optical distortions, but focusing midday sunlight through it ignites campfire tinder reliably.",
    },
    ["lens_small"] = {
        zh = "精致小巧的高清微距镜片，常见于破损的智能手机摄像头或精密怀表目镜中。在修理复杂电子设备或安装激光准星时，它是必不可少的光学元件，只要别手滑掉进废墟地缝里。",
        en = "A tiny, pristine glass optic salvaged from smartphone cameras or watchmaker loupes. Essential for fabricating miniature laser pointers or inspecting micro-circuits, provided your trembling fingers don't drop it into floorboard cracks.",
    },
    ["lentils_cooked"] = {
        zh = "在一小锅沸水中煮得软烂浓稠的熟扁豆，虽然颜色灰暗像一滩湿泥，但富含救命的植物蛋白。撒上一小撮粗盐大口吞咽下去，肚子里传来的充实饱腹感足以支撑你再搜刮一整栋废弃写字楼。",
        en = "A pot of brown lentils simmered until mushy and thick, resembling grey mud but packed with lifesaving protein. Swallowed warm with coarse salt, this hearty porridge provides the calories needed to sweep high-rise ruins.",
    },
    ["leotard"] = {
        zh = "色彩鲜艳、弹性极佳的一体式体操紧身衣，紧密包裹着躯干却把四肢完全暴露在外。穿上它在废土上跑跳确实灵活轻盈，但面对任何哪怕擦伤级别的丧尸抓咬，都等于直接用肉身硬抗。",
        en = "A form-fitting spandex bodysuit in garish retro colors, hugging the torso while leaving limbs bare. It grants complete athletic agility for vaulting barricades, though encountering even minor zombie claws guarantees raw physical trauma.",
    },
    ["letter"] = {
        zh = "封在泛黄信封里的一封亲笔信件，字迹工整却因雨水侵蚀而有些晕开。信中絮絮叨叨写着灾前琐碎的思念与家常，在所有人都在为了生存相互厮杀的末日里，读来让人莫名鼻酸。",
        en = "A handwritten letter preserved inside a faded envelope, its ink softly feathered by moisture. Reading mundane domestic news and expressions of affection from an extinct world brings an unexpected lump to cynical survivors' throats.",
    },
    ["lettuce"] = {
        zh = "刚刚用小刀细细切碎的一捧新鲜生菜叶丝，水灵翠绿且散发着泥土清香。把它夹在烤肉三明治里能极大地缓解油腻感，唯一的挑战是必须趁着变蔫之前赶紧吃下肚去。",
        en = "A crisp handful of shredded garden greens freshly cut with a clean blade. Tucking these vibrant ribbons into gamey roasted meat sandwiches cuts grease wonderfully, assuming you consume them before they wilt into brown sludge.",
    },
    ["lettuce_head"] = {
        zh = "一整颗紧实饱满的新鲜结球生菜，外层包裹着带露水的嫩绿叶片。在到处都是压缩饼干和腐烂罐头的末世，能捧着这颗嘎嘣脆的蔬菜直接生啃，是土豪农场主才能享有的无上尊荣。",
        en = "A tight, crisp head of pale green lettuce harvested from well-tended survival soil. In an era dominated by stale rations and salty jerky, taking a massive crunchy bite of fresh vegetable feels like billionaire luxury.",
    },
    ["level_3_vest"] = {
        zh = "塞入了重型陶瓷复合防弹插板的军规防弹背心，硬挺得像一块穿在身上的墓碑。虽然能稳稳挡下数发全威力步枪弹，但挨上一枪后那股折断肋骨的剧烈闷痛，依然会让你跪在地上怀疑人生。",
        en = "A military carrier fitted with heavy ceramic plates, as rigid as wearing a personal tombstone. While stopping rifle rounds dead in their tracks, the bruising impact will still leave you gasping for breath on bruised knees.",
    },
    ["leverpostej"] = {
        zh = "用猪肝、猪油与洋葱精心烤制而成的丹麦传统肝酱，口感绵密浓郁。厚厚涂抹在干硬的黑麦饼干上，是北欧幸存者寒冬里最奢侈的能量炸弹，唯一的缺点是开封后极易引来嗜血变异鼠。",
        en = "A traditional Danish liver paste baked with pork fat and onions into silky decadence. Slathered thickly across stale crackers, it provides immense winter calories, provided ravenous mutant rats do not smell the rich offal first.",
    },
    ["lgpistol_primer"] = {
        zh = "封装在高灵敏度黄铜小杯里的马格南手枪底火，只要受到击针轻微撞击便会爆发出炽热火花。在手工复装大威力左轮子弹时，它是赋予铅头弹丸致命初速的心脏，千万别用金属锤子直接敲击。",
        en = "Sensitive brass percussion cups holding chemical priming compound for magnum handguns. The vital spark that awakens heavy revolver cartridges, handle them gently; tapping them with a steel tool turns your fingers into smoking hamburger.",
    },
    ["lgrifle_primer"] = {
        zh = "大口径全威力步枪子弹专用的重型底火，能耐受极端膛压并瞬间引燃大量发射药。在破旧台虎钳上复装狙击弹药的枪匠，每压入一颗底火都屏住呼吸，生怕一丝火花引爆整个工作台。",
        en = "Heavy percussion primers engineered to withstand extreme chamber pressures in full-bore rifles. Reloading brass on a shaky workbench demands surgical care; a single careless slip could detonate your entire hoarded gunpowder cache.",
    },
    ["licorice"] = {
        zh = "黑如沥青、风味两极分化的茴香风味甘草软糖。讨厌它的人觉得这玩意儿比丧尸口水还难以下咽，而狂热的甘草爱好者却能在嚼完一整条后，获得在恶劣暴风雨中继续搜刮的精神抗性。",
        en = "Jet-black gummy twists boasting a pungent, anise-heavy medicinal punch. Detractors claim it tastes worse than zombie bile, but fanatical chewers swear that swallowing a stick bolsters their mental fortitude against bleak apocalyptic weather.",
    },
    ["lifestraw"] = {
        zh = "内置微孔滤膜的便携式净水吸管，户外极客在灾前最爱的救生玩具。直接趴在漂浮着丧尸浮尸的臭水沟旁吸水确实需要巨大的心理素质，但清凉甘甜的无菌清水足以让你打消所有疑虑。",
        en = "A micro-filtration straw allowing parched wanderers to drink straight from stagnant puddles. Sucking pond water beside decomposing corpses demands strong nerves, but safe, purified gulps make this lightweight tube worth its weight in gold.",
    },
    ["light_battery_cell"] = {
        zh = "常见于各类小型手电筒和遥控器中的轻型一次性干电池。在到处都是变异怪物的漆黑夜晚，它所能维持的几个小时光亮比纯金还要珍贵，唯一的绝望是眼睁睁看着光柱在危机中渐渐泛黄熄灭。",
        en = "Standard disposable dry cells scavenged from dead TV remotes and compact flashlights. Their meager hours of juice are more precious than gold in pitch darkness, though watching the beam turn feeble during ambushes is pure terror.",
    },
    ["light_bulb"] = {
        zh = "带有脆弱玻璃外壳和纤细钨丝的普通白炽灯泡。在电网瘫痪后的废土世界里，它就像一个易碎的文明标本，想要让它重新发光，你不仅需要自制发电机，还得祈祷灯丝没在颠簸中震断。",
        en = "A fragile glass bulb enclosing a delicate coiled tungsten filament. Surviving as a brittle relic of electrified civilization, getting it to glow again requires wired generators and hoping bumpy travels haven't already snapped the wire.",
    },
    ["light_cell_rechargeable"] = {
        zh = "一枚标准规格的微型可充电高能量锂电池电芯。只要放入基地充电底座或连接太阳能板，便能反复充满电量，为手电筒、激光瞄具或便携检测仪器注入稳定纯净的电气动力。",
        en = "A compact rechargeable lithium battery cell built to standard dimensions. Swapped into charging stations or solar trickle banks, it repeatedly powers tactical flashlights and electronic red-dot sights.",
    },
    ["light_detector"] = {
        zh = "用来感应周围环境光照强度的精密光敏传感器电路板。在改装自动化陷阱或夜间防盗警报时极为有用，只要有一束车灯或探照灯扫过，它就能立刻触发预设的蜂鸣器或机枪炮塔。",
        en = "A sensitive photocell circuit tuned to register ambient illumination shifts. Wired into perimeter security nets, it instantly trips klaxons or automated turret relays the moment a prowling bandit's headlamp sweeps across your darkened compound.",
    },
    ["light_emergency_blue"] = {
        zh = "从报废警车车顶撬下来的高亮度蓝色旋转警示灯。装在你的废土武装越野车上，在夜间疾驰时闪烁着耀眼的蓝色光芒，虽然完全吓不走丧尸，但至少能让敌对劫匪远远认出你不好惹。",
        en = "A pulsing blue strobe liberated from a shot-up police cruiser roof. Mounted onto an armored deathmobile, its flashing beams deter cautious marauders, even if mindless undead couldn't care less about civilian traffic laws.",
    },
    ["light_emergency_red"] = {
        zh = "鲜艳夺目的红色旋转应急警示灯，旧时代常用于消防车和救护车。在深不见底的废弃研究所长廊里，接通电源让红光疯狂扫过斑驳墙面，会瞬间营造出生化危机临头的绝望氛围感。",
        en = "A crimson emergency beacon stripped from rescue trucks. Powering it on inside subterranean lab tunnels bathes concrete walls in frantic bloody sweeps, instantly manufacturing the theatrical ambiance of an impending reactor meltdown.",
    },
    ["light_load_bearing_vest"] = {
        zh = "采用轻质尼龙网眼布缝制的战术战备背心，透气凉爽且具备充足的弹匣插槽。在炎炎夏日长途跋涉时，穿上它既能带齐弹药又不会中暑虚脱，代价是薄薄的网眼对利齿毫无防御。",
        en = "A breathable nylon mesh tactical harness optimized for carrying magazines without trapping body heat. Ideal for grueling summer scouting treks, its airy frame provides abundant gear carriage at the cost of zero bite protection.",
    },
    ["light_minus_battery_cell"] = {
        zh = "极其小巧的纽扣状微型电池，通常用于给电子手表或小型助听器供电。在搜刮到激光瞄准镜或高级电子门禁解码器时，这枚不起眼的小电池就是决定整件神装能否开机的唯一钥匙。",
        en = "A minuscule coin-sized battery designed for wristwatches and compact electronics. Small enough to swallow accidentally, finding a fresh one determines whether your prized laser sight or electronic lockpick can actually power up.",
    },
    ["light_minus_disposable_cell"] = {
        zh = "一枚微型一次性碱性或氧化银钮扣化学电池。电量极其有限且无法重复充能，但在搜刮到完全断电的古董手电或测辐射笔时塞入它，往往能为你换来黑暗走廊中宝贵的几十分钟光明。",
        en = "A miniature single-use chemical battery cell. Though incapable of recharging and packing modest reserves, inserting it into a dead emergency headlamp buys thirty vital minutes of guidance through black tunnels.",
    },
    ["light_snare_kit"] = {
        zh = "包含细钢丝、触发滑轮与地桩的便携式捕猎套索工具包。只要将它巧妙布置在森林兽道或灌木丛边，第二天清晨你就能收获一只倒霉的野兔，或者一根被狂暴变异狼生生扯断的废钢丝。",
        en = "A compact snaring kit containing aircraft wire, spring triggers, and ground stakes. Setting it along overgrown forest trails yields plump woodland rabbits by dawn, or a shredded steel cable left by enraged mutant wolves.",
    },
    ["lighter"] = {
        zh = "廉价塑料外壳下封存着普罗米修斯的火种。只要你的大拇指没被火石磨破皮，它就能轻松点燃香烟、篝火或者一个扔向尸群的莫洛托夫鸡尾酒。唯一的玄学规律是：当你最冷的时候，它绝对打不着火。",
        en = "Promethean fire trapped inside brittle transparent plastic. It readily ignites campfire kindling or Molotov cocktails, provided your callous thumb can spark the flint. Naturally, by universal law, it will fail repeatedly only when you are soaked in freezing sleet.",
    },
    ["lightstrip"] = {
        zh = "粘在透明柔性塑料胶带上的长条形LED灯珠阵列，散发着柔和而明亮的白光。将它贴在战车天花板或地下安全屋四周，只需极小的蓄电池电量，就能将冰冷阴森的地窖变成温暖温馨的起居室。",
        en = "A flexible adhesive ribbon lined with efficient micro-LED emitters casting pleasant, uniform illumination. Taped along deathmobile roofs or bunker ceilings, it sips minimal battery power while transforming depressing concrete vaults into cozy sanctuaries.",
    },
    ["lightstrip_inactive"] = {
        zh = "断开电源卷成一盘的柔性LED发光胶带，背面带有保护纸。只要找到焊枪接通十二伏直流电，这盘看似普通的塑料软带就能瞬间驱散黑暗，是每一位废土室内装潢狂热者的必备材料。",
        en = "A rolled reel of unpowered LED strip awaiting electrical wiring. Connected to twelve-volt vehicle batteries, this silent plastic ribbon dispels midnight gloom, making it the favorite interior decorating material of bunker architects.",
    },
    ["link_sheet"] = {
        zh = "用数以千计的小铁环相互铆接编织成的锁子甲铁网片，质感柔软且冰冷沉重。在末世工坊里，它是裁剪拼接锁子甲背心、护颈和防咬手套的基础原料，只要你有足够的耐心一把把穿环。",
        en = "A flexible, heavy fabric woven from thousands of interlocking steel rings. It forms the essential raw material for tailoring chainmail hauberks and bite-proof coifs, assuming you possess endless patience for link riveting.",
    },
    ["liq_bandage"] = {
        zh = "装在小玻璃瓶里的高挥发性医用液体创口贴，散发着刺鼻的丙酮气味。刷在细小割伤上会带来瞬间痛彻心扉的灼烧感，但随后凝固生成的防水薄膜能彻底杜绝脏水与尸毒感染伤口。",
        en = "A pungent medical adhesive packaged with a tiny application brush. Painting it over raw lacerations produces eye-watering chemical agony, quickly followed by a flexible waterproof seal that seals out tainted sludge and infection.",
    },
    ["liq_bandage_spray"] = {
        zh = "采用气雾压力罐装的速干液体绷带喷雾，专为紧急战场快速封闭大面积擦伤而设计。面对奔涌而来的腐蚀蚁酸或污泥，对着流血的皮肤猛喷一圈，虽然疼得让人跳脚，却能救你一条小命。",
        en = "A pressurized aerosol canister dispensing quick-drying liquid bandage across broad scrapes. Blasting wounded skin stings like raw fire, but rapidly forms an elastic protective barrier that shrugs off corrosive fluids and filthy mud.",
    },
    ["liquid_soap"] = {
        zh = "装在按压泵塑料瓶里的浓稠洗手液，散发着人造芦荟的清新香气。在满地污血、内脏与黏液的后末日世界，用少许清水搓洗出一手雪白细腻的泡沫，是重拾人性尊严的最佳心理疗法。",
        en = "Thick cleansing liquid stored inside a pump bottle, scented with soothing synthetic aloe. Lathering up a handful of soapy foam after butchering slimy monstrosities washes away toxic grime while restoring a precious scrap of sanity.",
    },
    ["liver"] = {
        zh = "从刚宰杀的变异动物体内完整剥离出来的暗红色生动物肝脏。手感滑腻柔软，虽然散发着浓烈铁锈腥味，但富含极其惊人的维生素A、铁元素与易于吸收的高能量动物蛋白质。",
        en = "A slippery, deep-red lobe of raw fresh liver harvested from a wild kill. Reeking sharply of iron, it constitutes a nutritional goldmine packed with vitamin A, minerals, and restorative calories.",
    },
    ["liver_cooked"] = {
        zh = "在热铁锅里用油脂煎炸熟透的焦香熟肝片。表面微焦而内里细腻粉糯，稍许盐粒便能激发出极其醇厚浓郁的油脂风味，大口咀嚼下肚，能让贫血虚弱的幸存者瞬间感到四肢回暖。",
        en = "Thick slices of fresh liver pan-fried over campfire embers until sizzling brown. Tender and mineral-rich with a crumbly texture, eating this savory offal revitalizes pale, exhausted survivors within minutes.",
    },
    ["liver_onion"] = {
        zh = "在大铁锅里用动物油高温爆炒的切片新鲜肝脏与焦香洋葱，香气浓郁诱人。肝脏特有的铁锈醇厚口感与洋葱的甘甜完美交融，咬下一大口，能让因贫血而眼花缭乱的废土客瞬间满血复活。",
        en = "Tender liver slices pan-fried with caramelized onions in rich animal fat. The earthy, iron-rich organ meat paired with sweet charred onions restores stamina instantly, driving away the dizzy exhaustion of wasteland anemia.",
    },
    ["livestock_carrier"] = {
        zh = "用粗壮角钢与坚固铁丝网焊接而成的重型牲畜运输笼，带有滑动插销铁门。把它固定在拖车底盘上，你就能把好不容易驯服的奶牛和绵羊安全运回营地，不必担心它们在路上被丧尸咬死。",
        en = "A heavy-duty transport crate welded from angle iron and wire fencing to haul cattle safely. Bolted onto cargo trailers, it safeguards tamed livestock from lunging predators during nerve-wracking relocations across hostile highways.",
    },
    ["livestock_scale"] = {
        zh = "底盘极其宽大沉重的工业级牲畜地磅，能够准确测量上千斤的巨型活体动物。在变异生物横行的荒野农场，经常把自家那头越长越怪的牛羊赶上去过磅，能让你直观感受到它变异的惊人速度。",
        en = "A massive low-profile mechanical platform scale designed to weigh heavy farm beasts. Regularly herding your mutant steer onto its checkered deck provides alarming numerical proof of just how fast strange bio-mass accumulates.",
    },
    ["lixa_data"] = {
        zh = "保存在军规三防移动硬盘中的LIXA绝密实验研究备份，记录着关于时空畸变与异常物质的惊人理论。任何读懂其中数据的科学家都会不寒而栗，意识到这场灾难从数十年前便已注定发生。",
        en = "A ruggedized hard drive containing complete research archives from the classified LIXA project. Decrypting its complex astrophysical models reveals that portal rifts tearing through reality were predicted and engineered decades in advance.",
    },
    ["lizard_sample"] = {
        zh = "浸泡在浑浊福尔马林防腐液里的变异蜥蜴鳞皮与器官切片。在废弃实验室的离心机里提取其遗传物质，是合成蜥蜴系诱变剂的核心原料，只要你不介意自己未来长出一条鳞片尾巴。",
        en = "Preserved reptilian tissue floating inside a sealed glass vial of yellowish preservative fluid. Centrifuging its genetic sequences unlocks potent lizard mutagens, provided you are comfortable with eventually sprouting a scaly tail.",
    },
    ["llink"] = {
        zh = "一小片经过精细折弯的优质薄钢弹片，军火黑市上传奇的快装全自动转换阻铁。只要将其巧妙塞入半自动步枪机匣后方，就能让民用武器瞬间化身狂暴的泼弹机器，前提是你的弹药足够挥霍。",
        en = "A bent strip of stamped spring steel famed in underground weapons lore as a full-auto converter. Dropped behind standard bolt carriers, it transforms mild sporters into roaring bullet hoses that empty magazines in seconds.",
    },
    ["load_bearing_vest"] = {
        zh = "标准军用战术战备承载背心，布满重型插扣、调节织带与模块化附包。穿上它能让你把数十公斤的弹匣、手雷、水壶和急救包均匀分摊在躯干上，让你在负重行军时依然能保持战斗姿态。",
        en = "A full-featured load bearing harness engineered to distribute substantial combat gear across your shoulders and torso. Loaded with magazines, canteens, and grenades, it keeps your arms free and weight properly balanced during firefights.",
    },
    ["load_bearing_vest_sling"] = {
        zh = "加装了快速武器挂扣与单点枪背带的战术承载背心。不仅能稳固携带大量战备物资，还能让沉重的突击步枪直接悬挂在胸前，在遭遇伏击的瞬间单手一扬就能立即举枪开火。",
        en = "A load bearing harness integrated with a quick-release single-point rifle sling. Carrying heavy combat carbines securely centered on your chest, it allows instant weapon transition the split second an ambush erupts.",
    },
    ["lobster"] = {
        zh = "从沿海捕捞或变异沼泽中猎杀的巨型龙虾尾部斩下的白嫩大肉块。肉质紧实弹牙且散发着纯净的海洋鲜味，在黄油煎锅里滋滋作响时，能让围在火堆边的幸存者馋得口水横流。",
        en = "A thick chunk of succulent white tail meat carved from a giant coastal crustacean. Searing it in clarified butter fills the campsite with an aroma decadent enough to make starving scavengers weep tears of joy.",
    },
    ["lobster_cakes"] = {
        zh = "将剁碎的鲜甜龙虾肉混合面包糠、野葱和香料捏成厚饼并煎至金黄。外酥里嫩，每一口都充满了浓郁的高级海鲜风味，让你在满目苍夷的废墟里享受到国宾宴席般的顶级奢华。",
        en = "Crispy patties formed from sweet shredded lobster meat bound with breadcrumbs and wild scallions. Pan-fried to golden perfection, they offer an astonishingly lavish culinary oasis amidst the soot and misery of civilization's collapse.",
    },
    ["lobster_canned"] = {
        zh = "密封在马口铁罐头中、浸泡在清淡盐水里的高档清蒸龙虾尾肉。开罐后那股纯净海鲜清香在充斥着腐臭的末日里宛如来自天堂的馈赠，肉质紧致弹牙，每一口都是无法估量的奢侈享受。",
        en = "A preserved luxury tin of tender lobster meat packed in light sea brine. Opening it releases heavenly oceanic aromas into squalid bunkers, offering succulent bites of pure pre-collapse decadence.",
    },
    ["lobster_cooked"] = {
        zh = "整只用沸水加盐煮得通红油亮的大龙虾。掰开坚硬外壳，白嫩饱满的紧实虾肉在蒸汽中诱人无比，蘸上少许融化黄油嚼碎吞下，那股鲜甜美妙的滋味会让你彻底忘掉身处末日地狱。",
        en = "A whole sea lobster boiled bright crimson over outdoor stoves. Cracking open the hard carapace reveals sweet, succulent tail meat that makes starving foragers completely forget the surrounding apocalypse.",
    },
    ["lobster_platter"] = {
        zh = "摆满整只红亮熟龙虾、融化黄油碟与新鲜烤野菜的豪华大拼盘。这是只有废土顶级霸主在凯旋时才敢摆出的豪横盛宴，任何受邀享用这盘大餐的拾荒客，都会愿意为你卖命一整年。",
        en = "A magnificent spread featuring whole steamed crustaceans alongside melted tallow dips and crisp herbs. Serving such opulent bounty marks you as the undisputed ruler of the wastes, commanding absolute loyalty from any hungry guest.",
    },
    ["lobster_roll"] = {
        zh = "在烤得焦黄酥脆的黄油长面包中间，塞进堆积如山的蛋黄酱拌龙虾肉。咬下去的瞬间，浓郁的黄油香与冰凉弹牙的虾肉在口中爆发，让人由衷感叹人类文明的烹饪精髓并未彻底灭绝。",
        en = "Heaps of chilled, sweet lobster tossed in mayonnaise and piled into a toasted buttered bun. Biting through the crisp, golden roll into savory seafood proves that the highest achievements of humanity endure after doomsday.",
    },
    ["lobster_smoked"] = {
        zh = "在苹果木烟熏架上慢火熏烤风干的深色龙虾熟肉条。木质烟熏香气深深浸透了原本甘甜的虾肉纤维，既耐嚼又极耐长期保存，是远洋捕捞者跨越漫长荒野巡逻时的顶级便携硬口粮。",
        en = "Hardwood-smoked lobster tail jerky cured gently over sweet applewood embers. Imbued with deep smoky flavor and stripped of perishable moisture, it provides an exquisite high-protein trail ration.",
    },
    ["lock"] = {
        zh = "一把小巧玲珑但结构扎实的铜质挂锁，配有一把原装小钥匙。在丧尸横行的废土，虽然它挡不住挥舞撬棍的大力士或狂暴酸液，但锁住日记本或珍贵饼干盒以防室友顺手牵羊，绰绰有余。",
        en = "A brass padlock accompanied by its original notched key. While useless against power tools or mutant hulks, it reliably prevents sticky-fingered survivor bunker roommates from raiding your secret stash of scavenged chocolates.",
    },
    ["log"] = {
        zh = "从倒塌大树上锯下来的一整根沉重实木原木。它是搭建结实原木庇护所、加固防御拒马或在冰雪严冬维持漫长壁炉火堆的基础材料，唯一的挑战是怎样把它从密林深处一路扛回据点。",
        en = "A hefty timber trunk felled from old-growth woods. Indispensable for framing sturdy cabins, constructing defensive palisades, or fueling prolonged winter hearths, dragging it through overgrown brush is the ultimate workout.",
    },
    ["log_immersion27"] = {
        zh = "一张左上角印有神秘机构XEDRA官方标志的泛黄机密纸质事故报告单。上面用冰冷的打字机字体记录了一起代号为沉浸-27A的多维裂隙收容失效惨剧，读来令人毛骨悚然。",
        en = "A confidential incident report printed on heavy bond paper bearing the classified XEDRA insignia. Detailing a catastrophic containment breach designated IMMERSION-27A, its cold clinical prose induces chills.",
    },
    ["loincloth"] = {
        zh = "用简单布片包裹下身并用细绳系住的原始兜裆布。它提供了人类文明所能容忍的绝对最低限度遮羞效果，轻便通风到了极点，代价是走在荆棘丛里随时可能遭受皮肉之苦。",
        en = "A rudimentary strip of scavenged cloth tied around the waist with twine. Satisfying the absolute bare minimum requirements of modesty, its breezy design offers maximum ventilation and zero protection against thorny briars.",
    },
    ["loincloth_fur"] = {
        zh = "用整块带毛动物皮毛裁剪而成的野性兜裆布，穿上后瞬间变身远古穴居蛮族勇士。不仅在寒冬里给胯下带来意想不到的温暖，还能在赤膊挥舞石斧冲锋时极大增强你的野蛮恐吓力。",
        en = "A shaggy pelt fashioned into savage barbarian groin wrap. Beyond keeping crucial personal anatomy shockingly toasty in sub-zero frost, charging into battle wearing this fur skirt strikes primal terror into cultured bandits.",
    },
    ["loincloth_leather"] = {
        zh = "用厚实鞣制熟皮裁成的角斗士风格皮兜裆布，边缘打孔穿入结实皮绳。虽然防护面积仅仅覆盖了关键部位，但结实的皮革至少能抵挡飞溅的碎石，造型狂野得像废土角斗场上的擂台冠军。",
        en = "A rugged leather flap suspended from a thick belt, reminiscent of ancient arena gladiators. Though offering minimal anatomical coverage, the stiff hide deflects flying grit while lending you the swagger of an undefeated pit-fighter.",
    },
    ["loincloth_wool"] = {
        zh = "用粗纺羊毛毡布缝制的保暖兜裆布，摸起来略微扎手却极其耐磨。在零下寒风中跋涉时，这块小小的羊毛布能有效防止关键部位遭受冻疮侵袭，是赤贫流浪汉最后的温暖底线。",
        en = "A scratchy but remarkably warm flap woven from boiled virgin sheep wool. Trudging through sub-zero blizzards with bare legs is madness, yet this humble insulating garment keeps frostbite away from vital personal real estate.",
    },
    ["long_dress"] = {
        zh = "一件采用透气棉麻面料剪裁而成的拖地素雅长裙。宽松优雅且垂感极佳，虽然在满是荆棘瓦砾的废墟中穿行极易挂烂裙摆，但对于怀念文明礼仪的生还者而言，穿上它自有一番平和韵味。",
        en = "A flowing ankle-length vintage dress tailored from light breathable fabric. While completely impractical for scrambling through shattered concrete rubble, wearing it restores a fleeting sense of civilized tranquility.",
    },
    ["long_dress_sleeved"] = {
        zh = "带有修长衣袖与高立领设计的维多利亚风格端庄正式长裙。严密的包裹性在荒野微凉的黄昏能阻挡蚊虫叮咬与微风侵袭，优雅考究的排扣设计总让人联想起旧时代上流舞会的华美灯影。",
        en = "A modest long-sleeved formal gown featuring a tailored high-collar neckline. Providing full bodily coverage against swarming insects and evening chills, its delicate buttons recall pre-war parlor gatherings.",
    },
    ["long_extension_cable"] = {
        zh = "长达数十米的高耐久重型户外橡胶延长线，两端装有防雨插头。在安全屋据点建设中，它是将房顶太阳能阵列或远方喧闹发电机电力安全输送到地下避难所的关键生命线。",
        en = "A heavy-duty waterproof extension cord stretching dozens of meters on a spool. Vital for routing current from noisy remote generators or sunny rooftop solar panels deep into secure, soundproof subterranean living bunkers.",
    },
    ["long_glove_white"] = {
        zh = "一直延伸到手肘上方的洁白丝绸或真皮晚礼服手套，散发着灾前上流晚宴的奢华贵气。在末世泥泞里戴着它翻找垃圾堆极具讽刺意味，好在光滑的面料能有效阻隔细小毛刺。",
        en = "Pristine opera gloves extending past the elbows, once worn to lavish metropolitan galas. Sifting through filthy radioactive wreckage while sporting these spotless accessories is absurdly ironic, yet the slick fabric stops slivers nicely.",
    },
    ["long_island"] = {
        zh = "将金酒、伏特加、朗姆、龙舌兰与可乐猛烈摇匀的经典长岛冰茶，看似像红茶其实是纯烈酒炸弹。一杯下肚，废土的苦难与绝望瞬间烟消云散，剩下的只有头重脚轻的欢愉与宿醉预警。",
        en = "A potent cocktail shaking four hard spirits together with a dash of cola. Disguised as innocent iced tea, this lethal liquid hammer banishes apocalyptic misery, leaving you dizzy, cheerful, and bracing for a brutal hangover.",
    },
    ["long_knit_scarf"] = {
        zh = "长度足以在脖子上缠绕三圈的长款纯毛针织围巾，两端还缀着调皮的流苏。在呼啸的冬日暴风雪中将整张下半脸严密包裹起来，你就能在冰天雪地里从容呼吸，不至于被冰碴冻伤肺部。",
        en = "An extra-long knitted muffler capable of wrapping three full loops around the neck. Bundling up beneath its bulky folds protects airways from freezing blizzard winds, letting you scout snowy ruins without coughing blood.",
    },
    ["long_knit_scarf_headwrap"] = {
        zh = "将超长针织围巾巧妙编织包裹在头顶与面部的头巾形态，宛如废土游牧僧侣的兜帽。它不仅能阻挡刺骨寒风吹刮头皮，还能把你的面容彻底隐藏在阴影中，增添一份神秘莫测的游侠气质。",
        en = "A long knit scarf wound tightly around head and cheeks like a nomadic desert shemagh. Shielding scalp and ears from freezing gales, it envelops your visage in brooding shadow, projecting the stoic aura of an ascetic wanderer.",
    },
    ["long_knit_scarf_loose"] = {
        zh = "随性松垮搭在双肩上的长款针织围巾，两端随着奔跑步伐在风中悠然飘荡。虽然这种穿法牺牲了一部分防风保暖性，但走在废土残破的大街上，那一抹飘逸的风度足以让你看起来像电影主角。",
        en = "A long muffler draped loosely across broad shoulders, trailing theatrically behind as you jog. Sacrificing snug insulation for dramatic flair, fluttering knitted fringe ensures you cut an unmistakably cinematic profile among burning ruins.",
    },
    ["long_patchwork_scarf"] = {
        zh = "用几十块不同颜色和质地的废旧布料拼缝而成的超长百家布围巾。每一块布料或许都来自一件旧世界的窗帘、桌布或衬衫，五彩斑斓地围在脖子上，既能保暖又充满了末世嬉皮士的乐观幽默。",
        en = "An eccentric scarf stitched together from dozens of mismatched fabric scraps salvaged from curtains and flannel shirts. Wrapping this chaotic mosaic around your neck keeps frost at bay while exuding joyful, ragtag wasteland bohemian spirit.",
    },
    ["long_patchwork_scarf_headwrap"] = {
        zh = "将彩色布块拼接围巾层层缠绕在头顶的头巾造型，造型奇特宛如废土狂欢节的神秘巫师。它不仅能有效抵御尘暴与毒雾的扑面侵袭，还能让你在一群灰头土脸的幸存者中瞬间脱颖而出。",
        en = "A colorful patchwork wrap bundled around the cranium like an eccentric sorcerer's turban. Beyond filtering blowing grit during dust storms, its vivid patchwork pattern makes you impossible to overlook among grime-caked refugees.",
    },
    ["long_patchwork_scarf_loose"] = {
        zh = "松垮拖在身后的彩色拼布长围巾，色彩斑斓的碎布条在风中招摇过市。虽然很容易在穿过灌木丛或翻越铁丝网时被挂住扯烂，但在灰暗阴沉的废土废墟中，这抹亮色是让人会心一笑的风景线。",
        en = "A loose patchwork muffler trailing flamboyantly behind you. While disastrously prone to snagging on razor wire or jagged brambles, its bright dancing colors inject much-needed whimsical cheer into dreary concrete landscapes.",
    },
    ["long_pole"] = {
        zh = "一根笔直结实的长木杆，末端经过简单倒角。在探索充满未知的废弃建筑时，它是探查暗坑、排查绊线地雷和挑开变异蜘蛛网的神器，比用自己的肉体去踩雷明智一万倍。",
        en = "A sturdy, straight wooden stave trimmed smooth. Indispensable for probing suspicious floorboards, testing for tripwires, and clearing poisonous arachnid webs, it saves reckless scavengers from triggering lethal hidden booby traps.",
    },
    ["long_speargun"] = {
        zh = "配有大拉力乳胶皮筋和金属滑道加长水下渔枪，能在水下激发高动能钢制鱼标。在淹没的地下蓄水池或湖泊中搜寻变异巨鱼时，它是唯一能克服水阻提供致命穿透力的无声杀手。",
        en = "An elongated pneumatic speargun fitted with heavy latex bands to propel barbed steel harpoons. In flooded subway tunnels and murky reservoirs, it delivers silent, bone-shattering penetration against lurking aquatic predators.",
    },
    ["long_underpants"] = {
        zh = "紧贴腿部皮肤的加厚棉质保暖秋裤，灾前无数年轻人嫌弃、末世所有幸存者疯抢的保命神器。在零下十几度的严冬里，穿上它在雪地里长途奔波，双腿肌肉才能时刻保持爆发力。",
        en = "Snug thermal bottoms crafted from waffle-knit cotton, once mocked by fashionable youths but prized like jewels in doomsday winters. Slipping these beneath jeans keeps leg muscles warm and ready for life-saving evasive maneuvers.",
    },
    ["long_undertop"] = {
        zh = "带有罗纹袖口的紧身长袖保暖秋衣，能完美锁住上半身核心体温。单穿它虽然显得有些滑稽单薄，但只要套上一件战术夹克，你就能在凛冽刺骨的北风中镇定自若地举枪瞄准。",
        en = "A fitted long-sleeved thermal undershirt with ribbed cuffs designed to trap vital body heat. Wearing it under rugged armor layers keeps your core comfortably insulated, preventing shivering from wrecking your precision rifle aim.",
    },
    ["long_undertop_sleeveless"] = {
        zh = "去掉了长袖以保证双臂活动灵活的无袖保暖背心。在寒冷天气中高强度挥舞大锤或锯伐木材时，它既能保护心肺等重要脏器不被寒气侵袭，又能让双臂肆意挥洒汗水而不受束缚。",
        en = "A sleeveless thermal undershirt focusing its warmth exclusively around the thoracic core. When chopping firewood or swinging sledgehammers on crisp autumn mornings, it preserves vital chest heat while leaving muscular arms completely unencumbered.",
    },
    ["longbow"] = {
        zh = "由优质紫衫木或复合木料精心削制而成的传统高拉力大长弓，弓身比成年人还要高大。拉满弓弦需要惊人的臂力，而射出的重箭足以在百步之外洞穿铁甲丧尸的颅骨，无声而致命。",
        en = "A towering traditional warbow carved from resilient hardwood, standing taller than an archer. Drawing its heavy limbs demands exceptional back strength, but loosed arrows punch cleanly through steel helms without making a sound.",
    },
    ["longrifle_flintlock"] = {
        zh = "一把采用燧石撞击发火机与细长八角形线膛枪管的复古前装黑火药长步枪。虽然装填过程繁琐得需要整整半分钟，但射出的沉重圆铅弹射程极远且穿透力惊人，百米外猎鹿极其致命。",
        en = "A traditional muzzleloading flintlock longrifle fitted with an octagonal barrel. While demanding thirty frantic seconds to reload with powder and ball, a well-placed round drops forest game with unerring accuracy.",
    },
    ["longshirt"] = {
        zh = "下摆一直垂到大腿中部的加长棉质长袖衬衫，宽松舒适且透气性良好。它不仅能有效防晒防蚊虫叮咬，在紧急时刻还能随时撕下几根长布条，当作包扎流血伤口的简易止血带。",
        en = "An oversized cotton shirt whose generous hem drops well past the hips. Breezy and comfortable during dusty chores, in desperate emergencies its sweeping shirttails can be ripped into clean bandages to staunch arterial bleeding.",
    },
    ["longsword"] = {
        zh = "采用现代弹簧钢精心锻打淬火、开双刃且重心极其完美的真品双手长剑。十字护手与配重圆首手感极佳，挥舞破空时如银蛇狂舞，无论刺割劈砍都能轻易斩断丧尸颈椎与硬质皮革。",
        en = "An authentic, masterfully balanced European longsword forged from tempered high-carbon steel. Dancing effortlessly between offensive thrusts and fluid parries, its razor edges slice cleanly through bone and leather.",
    },
    ["longsword_fake"] = {
        zh = "在旅游纪念品店或影视道具展柜里搜刮来的不锈钢未开刃装饰壁挂长剑。剑条生硬脆弱且刀柄仅用细螺杆锁紧，一旦用力挥砍硬物，整根剑身很可能会直接从护手处断裂飞出反噬主人。",
        en = "A cheap stainless-steel wall-hanger replica of a longsword. Unsharpened and welded to a weak threaded tang, swinging it aggressively against armored enemies risks snapping the brittle blade right into your face.",
    },
    ["longsword_inferior"] = {
        zh = "由毫无经验的铁匠学徒用生锈废铁敲打出来的劣质长剑。刃口参差不齐且未经良好淬火，挥砍时震手发麻，虽然杀伤力比不上真正的军规钢剑，但总比赤手空拳面对丧尸扑咬要安全得多。",
        en = "A poorly balanced longsword hammered together by an amateur smith. Riddled with soft spots that bend upon heavy impact, its uneven edge is nonetheless vastly preferable to fighting barehanded against infected hordes.",
    },
    ["loom_frame"] = {
        zh = "用坚固木方榫卯拼接组装而成的框架式手动织布机，配有基础的经纬线梳理机构。只要你搜集到了足够的植物纤维或动物毛线，坐在它面前摇动机柄，你就是废土上唯一的布料供应商。",
        en = "A rigid timber frame outfitted with basic warp tensioners and a hand-shuttle. Feeding it plant fibers or spun wool lets patient artisans weave bolts of cloth, becoming essential suppliers of fabric to freezing enclaves.",
    },
    ["lotus"] = {
        zh = "从被生化泥浆污染的池塘中顽强绽放的洁白莲花，出淤泥而不染的花瓣散发着清雅芳香。在荒诞破败的世界里注视着这朵纯净的生命奇迹，能让最冷血的拾荒客心头涌起一丝久违的宁静。",
        en = "A pristine blossom opening gracefully above stagnant, irradiated marsh mud. Gazing upon its immaculate white petals amidst decomposing urban decay softens even the most cynical mercenary's heart with a glimpse of enduring peace.",
    },
    ["lotus_rhizome"] = {
        zh = "从黑臭池塘淤泥深处奋力挖掘出来的多节新鲜生莲藕，断面上布满标志性的透气气孔。虽然洗去外面厚厚的淤泥需要耗费不少功夫，但里面爽脆多汁的淀粉质地是无上的天然美味。",
        en = "A knobby root harvested from thick pond muck, revealing its signature pattern of hollow chambers when sliced. Scrubbing away stinking silt is labor-intensive, but crunching into crisp, starchy flesh rewards you with pure nutrition.",
    },
    ["lotus_rhizome_boiled"] = {
        zh = "在沸水陶罐中慢火煮得粉糯拉丝的熟莲藕块，口感从爽脆转为甘甜绵密。在饥寒交迫的避难所里喝上一碗热气腾腾的煮莲藕汤，胃里传来的温润饱胀感能彻底抚平所有的生存焦虑。",
        en = "Thick slices of lotus root simmered until fork-tender and gently sweet. Downing a bowl of steaming broth alongside soft, starchy rounds warms chilled bones and dispels the nagging existential dread of empty bellies.",
    },
    ["lotus_tea"] = {
        zh = "用晒干的清香荷花花瓣与荷叶浸泡冲调而成的澄澈花茶，入口微苦却带有悠长的甘甜回味。在满口都是铁锈罐头余味的夜晚，小口啜饮这杯清香茶水，不仅降火解毒，还能安神助眠。",
        en = "Fragrant dried lotus petals steeped in boiling water to produce an amber, subtly bitter infusion. Drinking this delicate herbal tea washes away the metallic aftertaste of canned rations while soothing frayed post-apocalyptic nerves.",
    },
    ["louverture"] = {
        zh = "一柄在尾部配重锤头内部暗藏可充填燃油储罐与排气喷嘴的特制奇门喷火战槌。按下点火滑钮挥击，喷口喷射出的灼热烈焰能伴随破甲钝击将目标瞬间点燃成火球，极具毁灭性威能。",
        en = "An ingenious flame-vented war mace housing a pressurized fuel reservoir in its pommel. Striking targets triggers searing jet flames alongside crushing blunt trauma, engulfing heavily armored brutes in blazing chemical fire.",
    },
    ["lowtops"] = {
        zh = "旧时代街头随处可见的经典帆布低帮平底系带运动鞋。轻便灵活且抓地力适中，虽然无法提供脚踝支撑且极易被水洼浸湿，但在水泥道路上奔跑逃命时转弯轻巧，是跑酷幸存者的轻便之选。",
        en = "Classic low-top canvas sneakers featuring flexible vulcanized rubber soles. Offering virtually zero ankle support and soaking up puddles instantly, they remain featherweight choices for swift rooftop parkour escapes.",
    },
    ["ls_sd_passcode"] = {
        zh = "内部蚀刻着纳米级加密光学图案的半透明全息碎片，散发着微弱的彩虹偏振光。将其插入特定实验室的主控终端，就能解锁锁死多年的绝密科研数据库，或者触发基地的自我毁灭倒计时。",
        en = "A translucent crystalline shard etched with microscopic diffraction gratings that shimmer iridescently. Slotting it into sealed lab terminals bypasses security firewalls, unlocking classified databases or triggering catastrophic facility self-destruct routines.",
    },
    ["ls_sd_passcode_used"] = {
        zh = "已经被终端读取并永久注销的全息钥匙碎片，内部精密的偏振光栅已经烧蚀发黑。如今它只是一块毫无意义的人造水晶边角料，除了穿孔挂在脖子上当纪念品，毫无实用价值。",
        en = "A burned-out holographic key fragment whose micro-gratings were permanently wiped during terminal authorization. Now just inert crystalline scrap, its only remaining purpose is dangling from a neck cord as a nerdy post-apocalyptic trophy.",
    },
    ["lsd"] = {
        zh = "印着鲜艳粉色卡通图案的微型吸墨纸方片，浸透了强效致幻剂。在满地丧尸和食尸鬼的恐怖末日里吞下这玩意儿，你大概率会在五彩斑斓的幻觉中欢笑着张开双臂，主动拥抱狂暴生化怪。",
        en = "A tiny pink paper tab saturated with potent psychoactive lysergamides. Dropping this amidst flesh-eating zombie hordes ensures you trip into vivid psychedelic wonderlands, happily hugging slobbering horrors as if they were giant plush teddy bears.",
    },
    ["lsurvivor_armor"] = {
        zh = "雇佣兵们用凯夫拉纤维与硬化塑钢手工拼缝的轻量化胸甲，兼顾机动性与要害防护。穿上它能让你在枪林弹雨与尸群围攻中从容侧移开火，只要别被巨型投掷怪扔来的水泥板迎面砸中。",
        en = "Lightweight chest armor pieced together from Kevlar sheets and molded polymer plates. Offering superb protection without encumbering mobility, it keeps agile mercenaries alive until an oversized brute throws a reinforced concrete pillar at them.",
    },
    ["lsurvivor_jumpsuit"] = {
        zh = "用透气棉麻与轻质耐磨帆布手工缝制的夏日连体服，布满收纳工具与零件的插袋。在酷暑废土里穿着它干杂活既凉爽又耐刮，代价是每次遭遇急迫内急时，你都得把整件衣服全脱下来。",
        en = "A breathable summer jumpsuit sewn from tough cotton canvas, sporting dozens of pockets. While it keeps you remarkably cool during scorching salvage runs, sudden gastrointestinal emergencies require stripping off all your gear in frantic terror.",
    },
    ["lsurvivor_suit"] = {
        zh = "无数废土幸存者梦寐以求的轻型全套防护服，集成了防咬层、密封拉链与基础防辐射内衬。它轻便得宛如第二层皮肤，能在恶劣的变异废土中为你提供全方位的环境与物理防御庇护。",
        en = "The holy grail of wasteland tailoring: a lightweight, integrated suit boasting sealed seams, bite-resistant weave, and light rad-shielding. It fits like comfortable athletic wear while protecting against everything from toxic sludge to rabid claws.",
    },
    ["lucern_hammer"] = {
        zh = "装在两米长木柄末端的三合一破甲凶器，集成了四瓣重锤、破甲尖锥和锋利的顶刺。顺势挥击能把最坚硬的中世纪骑士板甲砸成凹坑，用来敲碎变异丧尸的骨化颅骨简直是大材小用。",
        en = "A devastating polearm mounting a four-pronged hammer, armor-piercing beak, and top spear spike atop a six-foot haft. Engineered to crumple hardened steel plate armor, it pulverizes mutated zombie skulls with terrifying, concussive finality.",
    },
    ["lucern_hammerfake"] = {
        zh = "一把采用空心铝合金管与薄铁皮拼凑出来的假冒卢森长柄战锤道具。原本用于中世纪主题漫展摆拍，外表威风凛凛但在真正肉搏战中一敲即瘪，切勿真的拿它去敲打变异巨兽的厚重天灵盖。",
        en = "A hollow prop replica of a medieval Lucerne hammer assembled from tin and light alloys. Imposing on display stands, striking an actual raging brute causes the hollow head to crumple like a soda can.",
    },
    ["ludo"] = {
        zh = "带有四个鲜艳色块与简单塑料骰子的经典英国飞行棋盘。在没有网络信号的末世漫漫长夜，几名满手血污的幸存者围坐在蜡烛前为谁先起飞而争吵不休，是重温童年天真的最佳途径。",
        en = "A colorful folding board game with plastic tokens and a single die. On endless electricity-free evenings, battle-hardened mercenaries arguing fiercely over token movement is the most heartwarming reminder of extinct childhood innocence available.",
    },
    ["lug_wrench"] = {
        zh = "十字交叉形状的重型碳钢汽车轮胎十字扳手，结构极其坚固结实。它不仅能在废弃高速公路上轻松卸下重卡的生锈轮胎螺栓，在近距离遭遇丧尸时，沉重的实心铁臂也是最靠谱的碎骨钝器。",
        en = "A four-way cross wrench forged from solid high-tensile steel. Beyond breaking loose seized wheel lug nuts along wrecked interstates, swinging its heavy forged arms delivers brutal, skull-splintering leverage during desperate roadside ambushes.",
    },
    ["lulo"] = {
        zh = "原产于南美安第斯山脉的柑橘风味多汁水果，切开后露出翡翠般诱人的绿色果肉。在吃够了干燥难咽的罐头肉排后，吸吮一大口酸甜清爽的露露果汁，能让干涸的灵魂瞬间重新焕发生机。",
        en = "An exotic Andean fruit revealing bright emerald pulp when sliced open. Bursting with tart citrus and rhubarb flavors, sipping its refreshing juice revitalizes dehydrated scavengers who have grown sick of chewing desiccated military rations.",
    },
    ["lump_cast_iron"] = {
        zh = "从报废发动机缸体或破碎暖气片上敲下来的重型铸铁大块。在铁匠眼里，只要将它重新丢进高温坩埚融化，就能铸造成锅碗瓢盆或锋利武器；在普通流浪汉手里，它就是一块能砸扁铁皮的大铁坨。",
        en = "A dense chunk of grey cast iron salvaged from shattered engine blocks or vintage radiators. While master blacksmiths melt it down for durable pots and anvils, clumsy survivors appreciate it as an indestructible doorstop.",
    },
    ["lunchbox"] = {
        zh = "印着灾前热门超级英雄卡通图案的马口铁便携午餐盒，卡扣依然严丝合缝。如今盒子里装的不再是涂满花生酱的白面包，而是压满子弹的备用弹匣和用锡纸包裹的烤变异蜥蜴肉串。",
        en = "A retro tin lunchbox featuring faded cartoon superhero lithographs. Long gone are PB&J sandwiches and juice boxes; today it carries thirty spare shotgun shells and a foil-wrapped skewer of charred mutant rattlesnake meat.",
    },
    ["lunchmeat"] = {
        zh = "封在马口铁罐头里的粉红色压块午餐肉，混合了淀粉、大豆蛋白和巨量防腐亚硝酸盐。在世界毁灭数十年后打开它，那层滑腻的油脂依然新鲜如初，让人既食指大动又对它的保质期心生敬畏。",
        en = "A dense block of pink, gelatinous mystery meat packed with starch and enough sodium nitrite to outlast eternity. Popping the aluminum lid reveals gleaming jelly that tastes remarkably edible despite surviving multiple world-ending cataclysms.",
    },
    ["lung"] = {
        zh = "从刚捕获的变异动物体内剥离出来的新鲜粉色生肺脏。质地海绵多孔且布满细小气管，虽直接生吃口感诡异微腥，但在断粮边缘，这团充满微孔的内脏器官依然能提供维持基础代谢的热量。",
        en = "A spongy, pale-pink lobe of fresh raw animal lung harvested in the field. Bizarrely chewy and rubbery when consumed uncooked, it nevertheless provides vital emergency calories when starvation claws at empty bellies.",
    },
    ["lung_cooked"] = {
        zh = "在沸水锅或油锅里与香草一同焖煮熟透的熟动物肺。原本滑腻的肺泡在高温下脱水紧缩，口感如富有嚼劲的牛筋软骨，切片拌入辣椒末与粗盐，便是一道地道香浓的荒原内脏杂碎风味小吃。",
        en = "Simmered animal lung seasoned with wild herbs and coarse salt. Cooking contracts its spongy alveolar texture into firm, chewy morsels, turning humble offal into a surprisingly palatable campfire offal stew.",
    },
    ["lung_provence"] = {
        zh = "用迷迭香、百里香和大量大蒜与切片变异兽肺片爆炒的法式炖菜。虽然肺脏特有的海绵海泡状口感让初尝者难以适应，但浓郁的普罗旺斯香草气息成功掩盖了内脏里最后一丝变异血腥味。",
        en = "Spongy slices of animal lung simmered with rosemary, thyme, and heaps of wild garlic. While its airy, rubbery texture takes getting used to, the fragrant Provençal herb blend successfully disguises the meat's mutant provenance.",
    },
    ["lupine_sample"] = {
        zh = "装在低温防震冷冻管里的变异灰狼血液与毛囊组织样本。生物黑客在简易离心机里提取其基因链，能诱发惊人的夜视力与狂暴犬齿，只要你能接受在满月之夜忍不住对着天空凄厉嚎叫。",
        en = "A sealed cryovial holding blood and genetic tissue harvested from an aggressive mutant timber wolf. Synthesizing its aggressive sequences grants keen nocturnal senses and feral fangs, along with an embarrassing compulsion to howl at full moons.",
    },
    ["lutefisk"] = {
        zh = "用强碱水反复浸泡脱胶后风干的北欧传统白鱼肉，煮熟后呈现出果冻般的半透明胶状。那股混合着氨水与腐鱼的冲天气味，足以让方圆五十米内的丧尸误以为遇到了同类而掩鼻绕行。",
        en = "Cod steeped in caustic lye until its flesh transforms into translucent, quivering gelatin. Emitting an eye-watering stench of ammonia and old seafoam, eating it requires legendary Nordic stoicism that terrifies even hardened wasteland raiders.",
    },
    ["luthier_toolset"] = {
        zh = "装在天鹅绒衬垫木盒里的精密制琴工具，包含精巧的弯刀、刮板与微型指刨。在枪炮轰鸣的末日，守着这套工具精雕细琢一把小提琴看似荒唐至极，却是守护文明灵魂火种的最后避难所。",
        en = "A velvet-lined chest filled with specialized finger planes, curved scrapers, and soundpost setters. Devoting precious daylight to carving acoustic violins amidst apocalyptic ruins seems absurd, yet crafting music preserves humanity's dying creative flame.",
    },
    ["lux_meter"] = {
        zh = "带有球形白色光电探头的便携式照度计，能以勒克斯为单位精确测量环境亮度。在地下温室培育无土蔬菜或为潜行暗杀校准阴影盲区时，这台仪器能提供毫发不爽的数字化环境指引。",
        en = "A digital light meter with a dome sensor calibrated to measure illumination in precise lux. Crucial for optimizing underground hydroponic grow lamps or mapping shadowy blind spots for stealth raids against well-lit bandit fortresses.",
    },
    ["lws32"] = {
        zh = "采用纯不锈钢精密铸造的微型双动袖珍手枪，外形极其光滑圆润且毫无凸起。它能神不知鬼不觉地藏在靴筒或烟盒里，威力虽然微弱，但在被人搜身后的最后关头贴脸开火，足够救你一命。",
        en = "A snag-free pocket pistol machined from solid stainless steel, small enough to vanish inside a cigarette pack. While its .32 caliber rounds lack heavy stopping power, delivering a point-blank surprise shot flips hostage situations instantly.",
    },
    ["lws32mag"] = {
        zh = "容弹量仅有六发的微型不锈钢弹匣，短小得像一枚金属打火机。单手填装那些纤细的小手枪弹需要绣花般的耐心，可一旦遇到生死关头，这沉甸甸的六发子弹就是你重回人间的车票。",
        en = "A diminutive six-round stainless steel magazine barely larger than a zippo lighter. Jamming tiny cartridges into its stiff spring demands nimble fingers, but keeping a loaded spare in your sock offers sweet insurance.",
    },
    ["lycra_patch"] = {
        zh = "从紧身运动服或泳衣上裁剪下来的高弹性氨纶布料补丁。在缝补破损的防化服接缝或给紧身衣打补丁时，这种极佳的延展性能保证你的关节在剧烈运动时不会崩开缝线。",
        en = "A scrap of stretchy elastane sheared from athletic swimwear. Invaluable for patching flexible joints in bio-hazard garments or reinforcing tight undersuits, it stretches smoothly across moving knees without popping fragile field stitches.",
    },
    ["lye"] = {
        zh = "用草木灰浸泡过滤制成的强腐蚀性液态氢氧化钠碱水，触感滑腻却极具烧灼性。它是手工熬制硬肥皂与处理兽皮脱毛的必备化工原料，操作时务必戴好护目镜，否则溅入眼眶后果不堪设想。",
        en = "A highly caustic alkaline solution leached from hardwood ashes, dangerously slippery to the touch. Essential for saponifying animal tallow into soap or removing pelt hair, splashing a single drop into your eyes causes permanent blindness.",
    },
    ["lye_potassium"] = {
        zh = "由木灰反复浸取浓缩得到的液态氢氧化钾纯碱液，腐蚀性极强且呈高度碱性。在末世简易化学实验室里，它是合成液体皂、高级清洁剂与精细有机中和反应的核心无机碱来源。",
        en = "A strong liquid potassium hydroxide solution concentrated through repeated boiling of wood ash leachate. Crucial for brewing soft liquid soaps and conducting specialized organic reactions, handle its corrosive glass bottle with utmost respect.",
    },
    ["lye_powder"] = {
        zh = "结晶干燥后的工业级氢氧化钠白色粉末，极易潮解并在遇水时放出惊人高热。只要在脏水中倒入一勺，就能快速调节酸碱度并溶解有机杂质，是废土化学家制造火药与肥皂的万能原料。",
        en = "Granular white caustic soda crystals that absorb ambient moisture hungrily and boil violently upon contacting water. A solitary scoop clears clogged pipes or dissolves organic tissue, making it a staple chemical for survivalist laboratories.",
    },
    ["m1014"] = {
        zh = "军规半自动战斗霰弹枪的巅峰之作，拥有坚不可摧的气动自动机与折叠枪托。在七发大威力鹿弹被扣动扳机倾泻而出的数秒内，狂暴的钢珠风暴足以将面前任何变异猛兽瞬间打成筛子。",
        en = "The gold standard of combat shotguns, utilizing self-regulating gas pistons and a sturdy collapsible stock. Emptying seven heavy buckshot shells downrange in two frantic seconds obliterates charging abominations into a fine crimson mist.",
    },
    ["m107a1"] = {
        zh = "采用高效枪口制退器的半自动点五零反器材步枪，一柄狂暴的人造手持巨炮。射击时掀起的剧烈冲击波足以震落身旁天花板上的灰尘，而射出的重型穿甲弹能在千米之外打穿轻型装甲车。",
        en = "A semi-automatic .50 BMG anti-materiel cannon sporting a massive baffle brake. Each deafening discharge kicks up dust clouds and rattles your internal organs, while delivering enough terminal energy to crack armored personnel carriers.",
    },
    ["m107a1mag"] = {
        zh = "冲压钢板制成的巨型十发点五零双排弹匣，沉重得像一块实心大砖头。装满十发手臂粗细的重型机枪弹后，仅仅单手拎着这个弹匣就足以用来直接当钝器砸死普通丧尸。",
        en = "A heavy stamped steel box holding ten colossal half-inch anti-materiel cartridges. Loaded to capacity, this massive magazine weighs as much as a cinder block and doubles as a formidable blunt weapon in emergencies.",
    },
    ["m11"] = {
        zh = "美军军官与航空机组长期配备的紧凑型九毫米服役手枪，拥有极高的可靠性与顺畅的握持感。在恶劣风沙泥水环境中依然能够从容击发，是末世独行侠最值得性命相托的腰间防线。",
        en = "A compact 9mm service pistol favored by military aviation crews for its superb reliability and crisp trigger. Swallowing gritty sand and mud without jamming, it remains a solitary wanderer's most dependable sidearm companion.",
    },
    ["m110a1"] = {
        zh = "基于HK417高精度平台改造的班组精确射手步枪，配有消音器与高倍战术瞄准镜。在六百米开外的废墟高层隐蔽架设，每一发平稳击发的七点六二毫米子弹都能悄无声息地带走一名变异体领袖。",
        en = "A designated marksman rifle built on the refined HK417 platform, outfitted with suppressors and match optics. Perched atop high-rise rubble, its precision 7.62mm rounds eliminate high-threat mutants at half a kilometer with muffled efficiency.",
    },
    ["m134"] = {
        zh = "拥有六根旋转枪管的电动加特林重机枪，每分钟能疯狂泼洒数千发高密度弹雨。开火时那犹如撕裂油布般的恐怖电锯声，是终结尸潮的最强物理法则，前提是你的弹药箱能经得起三秒钟的消耗。",
        en = "A six-barreled rotary machine gun spitting thousands of rounds per minute in an unbroken buzzsaw roar. Activating this terrifying weapon vaporizes advancing hordes instantaneously, assuming you have tractor trailers filled with linked ammo.",
    },
    ["m14_makeshiftmag"] = {
        zh = "用废铁皮、铝皮罐头和手工盘绕的弹簧土法拼凑出的五发M14步枪弹匣。虽然装弹时偶尔会卡住托弹板，但在缺枪少弹的废土，这五发能顺利击发的全威力子弹就是决定生死的筹码。",
        en = "A five-round box hastily hammered from food tins and stiff copper coil springs. Though its rough follower occasionally snags during cycling, having five functioning full-power cartridges ready in your rifle saves lives.",
    },
    ["m14ebr"] = {
        zh = "装在现代化铝合金战术底座中的经典强化战斗步枪，外形充满工业机械美感。沉重硬朗的枪身极大抑制了连发后坐力，在老练射手手中，它是兼具远程精确射击与中近程压制的致命多面手。",
        en = "A modernized M14 locked inside a rigid aircraft-aluminum chassis with telescoping stock and picatinny rails. Its substantial mass tames heavy recoil, providing precision semi-auto firepower capable of anchoring defensive perimeters against brutal mutants.",
    },
    ["m14mag"] = {
        zh = "标准二十发冲压钢制M14弹匣，表面涂装耐磨防锈磷化层。沉甸甸的双排供弹结构保证了在恶劣战场上的供弹稳定性，是每一位步枪手背包里最渴望摸到的可靠重金属疙瘩。",
        en = "A rugged twenty-round parkerized steel magazine built for standard 7.62x51mm battle rifles. Feeding cartridges reliably through dirt and freezing rain, carrying several loaded spares across your chest rig brings immense psychological peace.",
    },
    ["m14smallmag"] = {
        zh = "外形短小低调的五发M14运动型弹匣，底板完全不突出机匣下方。在草丛中伏卧潜行或将步枪固定在车架上时极其平整顺滑，专为不追求火力倾泻、只相信一枪毙命的荒野猎手而生。",
        en = "A flush-fitting five-round magazine designed for hunting and precision prone shooting. Slipping cleanly into the receiver without protruding, it allows sniper crawls through tall grass without digging into dirt or catching branches.",
    },
    ["m17"] = {
        zh = "美军现役模块化聚合物全尺寸服役手枪，拥有顺滑的双动扳机与大容量双排弹匣。符合现代人机工程学的握把贴合掌心，即使在满手汗水和泥浆的情况下，依然能快速拔枪完成精准连射。",
        en = "A modern modular service sidearm featuring a durable coyote-tan polymer frame and generous magazine capacity. Ergonomic and naturally pointing, its smooth striker trigger lets panic-stricken survivors double-tap charging abominations with reliable precision.",
    },
    ["m18"] = {
        zh = "缩短了套筒与枪管的紧凑型模块化军用手枪，隐蔽携带性能优异。它是特种侦察兵与载具驾驶员的最爱，既保留了全尺寸手枪的凶悍火力，又能在狭窄空间内极速出枪防卫。",
        en = "A shortened compact variant of the military's modular handgun system. Favored by scouts and vehicle drivers, it blends full-power 9mm capacity with a nimble, snag-free profile that draws lightning-fast from concealed underarm holsters.",
    },
    ["m1903"] = {
        zh = "历经百年战火洗礼的经典春田点三零旋转后拉枪机步枪，胡桃木枪托沉淀着岁月的包浆。每次拉开毛瑟式枪机退壳上膛的清脆金属撞击声，都在提醒射手：古老的机械工艺永远不会过时。",
        en = "A legendary bolt-action service rifle resting inside oiled American walnut furniture. Cycling its butter-smooth Mauser extractor ejects spent brass with crisp mechanical perfection, proving that century-old craftsmanship easily outlives modern plastic sporters.",
    },
    ["m1911"] = {
        zh = "发射狂暴点四五ACP子弹的传奇百年手枪，全钢机匣散发着不朽的硬汉气息。虽然七发单排弹匣容弹量在现代显得有些局促，但每一发重型铅弹砸碎丧尸脑壳时爆发出的纯粹动能无可匹敌。",
        en = "The immortal single-action steel pistol slinging fat .45 ACP slugs. While seven rounds feel stingy against encroaching hordes, every heavy bullet delivers sledgehammer kinetic energy that stops charging predators dead in their tracks.",
    },
    ["m1911_10"] = {
        zh = "口径狂暴升级为十毫米汽车弹的三角精英定制手枪，滑套后坐力凶猛如脱缰野马。它把原本优雅的老枪改装成了一头能近距离射杀变异巨熊的手炮，射击时请务必握紧虎口以防脱手。",
        en = "A beefed-up 1911 chambered in devastating 10mm Auto, famed for wrist-snapping recoil. Elevating a classic military design into a close-range grizzly bear cannon, firing it requires vice-like grip strength to keep sights on target.",
    },
    ["m1911_10mag"] = {
        zh = "专为十毫米全威力弹药打造的强化不锈钢弹匣，装有高张力复进弹簧。将八发昂贵且凶悍的大威力子弹一颗颗压入弹匣，那股沉甸甸的分量就是你穿行辐射废土的最强底牌。",
        en = "A heat-treated stainless steel magazine engineered to feed high-pressure 10mm Auto cartridges. Snapping eight loaded rounds into place feels like loading pure dynamite, giving you unmatched magnum confidence in shadowed alleyways.",
    },
    ["m1911a1_38super"] = {
        zh = "发射高膛压点三八超级弹的竞赛级1911改装手枪，弹道平直且穿透力极佳。这种老派黑帮与射击竞技选手深爱的奇特武器，在末世中能将钢制头盔或厚重骨甲像热刀切黄油般轻松穿透。",
        en = "A competition-tuned 1911 variant spitting flat-shooting, high-velocity .38 Super rounds. Cherished by vintage bootleggers and competitive shooters alike, its snappy projectiles punch through light steel helmets and thick beast hides effortlessly.",
    },
    ["m1911bigmag"] = {
        zh = "底部明显凸出握把的加长十发1911单排弹匣，配有厚实的防撞橡胶底座。多出来的三发宝贵弹药，往往就是在被尸群逼入死胡同、弹尽粮绝的最后数秒内绝处逢生的分水岭。",
        en = "An extended single-stack magazine carrying ten rounds of heavy .45 ACP, complete with protective rubber basepads. Those extra three shots represent the razor-thin margin between clearing the doorway or becoming an afternoon snack.",
    },
    ["m1911mag"] = {
        zh = "最经典可靠的七发单排冲压钢制1911弹匣，底板刻着原厂军规编码。它扁平纤薄的身躯能随手插进任何裤兜或靴筒里，百年来在泥浆、雨雪与战火中经历了无数次生死的终极考验。",
        en = "The classic flush-fitting seven-round steel magazine stamped with US military inspection marks. Thin and flat enough to slip into any vest pocket, this legendary design has fed cartridges flawlessly across a century of warfare.",
    },
    ["m1911mag_10rd_38super"] = {
        zh = "装有加强托弹簧的九发点三八超级弹单排弹匣，专为追求平直弹道与高穿透力的射手准备。供弹顺畅平滑，让射手能在极快射速下将整排高初速穿甲弹倾泻进变异体的硬化骨板内。",
        en = "A polished single-stack magazine holding nine rounds of high-velocity .38 Super ammunition. Its smooth follower guarantees friction-free cycling, enabling rapid follow-up shots against armored mutants before they can close the distance.",
    },
    ["m1918"] = {
        zh = "重达近十公斤的经典勃朗宁自动步枪BAR，由实心钢与厚胡桃木铸就的全自动战场推土机。趴在沙袋后扫射全威力三十零六子弹时，炽热的枪管与震耳欲聋的咆哮能轻易撕碎一切血肉。",
        en = "A twenty-pound chunk of walnut and ordnance steel known as the Browning Automatic Rifle. Firing full-power .30-06 rounds from a supported bipod, its thundering full-auto roar shreds encroaching flesh and brick barricades alike.",
    },
    ["m1918bigmag"] = {
        zh = "极为罕见的三十发加长型BAR步枪重型弹匣，原本用于防空阵地改装。插上这支修长沉重的钢弹匣后，整把步枪的分量足以媲美轻机枪，赋予你在阵地防御战中令人闻风丧胆的持久压制力。",
        en = "An uncommon thirty-round extended steel magazine originally developed for anti-aircraft configurations. Snapping this elongated behemoth into a BAR turns it into a true squad automatic weapon capable of shattering massed undead charges.",
    },
    ["m1918mag"] = {
        zh = "标准的二十发重型双排钢制BAR弹匣，装满三十零六重型穿甲弹后分量十足。更换这只厚重弹匣需要双手沉稳有力的配合，清脆的入膛锁定声是对阵地幸存者最强大的定海神针。",
        en = "A twenty-round box magazine fabricated from heavy gauge steel plate to house full-size rifle cartridges. Slapping it home into the receiver produces a resounding metallic clack that reassures everyone inside the besieged compound.",
    },
    ["m1a"] = {
        zh = "民用高精度半自动版本的M14战斗步枪，兼具精准射击与大威力弹药穿透力。无论是为营地提供远距离警戒掩护，还是在开阔林地猎杀狂暴变异鹿，它都是荒野独行客心中无可替代的重器。",
        en = "The civilian semi-automatic incarnation of the legendary M14 service rifle. Delivering punishing 7.62mm kinetic trauma with match-grade accuracy, it serves as an indispensable sentinel rifle for protecting remote forest homesteads from monstrous incursions.",
    },
    ["m1carbine"] = {
        zh = "极其轻巧灵活的二战半自动短卡宾枪，深受游击队员与女性射手喜爱。它发射平稳易控的点三零卡宾枪弹，虽然威力不及全尺寸步枪，但在近距离连珠开火时的极佳指向性让丧尸无所遁形。",
        en = "A lightweight, exceptionally handy semi-automatic carbine that points as naturally as an outstretched finger. Firing mild .30 Carbine cartridges, its featherweight recoil allows lightning-fast follow-up shots against fast-moving feral packs.",
    },
    ["m1carbinebigmag"] = {
        zh = "略带弧度的三十发大容量M1卡宾枪弯弹匣，让轻便卡宾枪拥有了近乎冲锋枪的倾泻火力。在扫荡被丧尸群占据的超市狭窄过道时，这三十发连绵不绝的弹雨能让你在无需换弹中杀穿全场。",
        en = "A curved thirty-round magazine converting the nimble carbine into a veritable storm of rapid-fire lead. Sweeping cramped supermarket aisles packed with groaning corpses, thirty continuous rounds ensure you reach the exit without empty clicks.",
    },
    ["m1carbinemag"] = {
        zh = "经典平底直身十五发M1卡宾枪钢弹匣，小巧轻便且极易收纳。你可以毫无负担地在战术背心袋里塞进六七只备用弹匣，随时随地在奔跑中单手完成潇洒利落的弹匣快速更换。",
        en = "A compact fifteen-round straight steel magazine that slides effortlessly into pocket pouches. Carrying half a dozen loaded spares adds negligible weight, letting agile scouts reload on the fly while hopping over shattered concrete barriers.",
    },
    ["m2010"] = {
        zh = "美军现役增强型旋转后拉枪机狙击步枪，发射狂暴的三零零温彻斯特马格南重弹。配合高倍率夜视瞄准镜与长管消音器，它是游荡在千米之外的死神化身，每一记扣动扳机都宣判一个目标的终结。",
        en = "A modernized sniper rifle chambered in thunderous .300 Winchester Magnum locked inside an ergonomic folding chassis. Equipped with high-magnification optics and heavy suppressors, it harvests targets at extreme ranges before the report ever reaches their ears.",
    },
    ["m2010mag"] = {
        zh = "单排五发点三零零马格南狙击步枪单体弹匣，内部由高强度特氟龙涂层托弹板支撑。压入五枚长如雪茄的马格南大弹壳，每一颗都承载着远距离摧毁坚固防御工事的毁灭性威能。",
        en = "A precision single-stack box holding five massive .300 Win Mag cartridges. Coated in slick Teflon to guarantee frictionless feeding, these five heavy rounds represent five guaranteed terminal decisions delivered from far beyond retribution range.",
    },
    ["m202_flash"] = {
        zh = "拥有四具发射管的方形便携式火箭发射器，可一次性或连发倾泻四枚六十六毫米燃烧火箭。当四枚铝热燃烧弹头在目标据点轰然炸开化作冲天火海时，任何变异怪物都会被烧成焦炭。",
        en = "A four-barreled rocket launcher firing salvos of 66mm incendiary warheads. Unleashing four blistering rockets simultaneously transforms hostile fortified nests into roiling seas of thermite flame that consume organic horrors to white ash.",
    },
    ["m203"] = {
        zh = "安装在突击步枪枪管下方的四十毫米单发榴弹发射器，单兵火力支援的绝对神器。向前推开滑套塞入一枚高爆破片榴弹，在两百米外炸碎一整群密集丧尸，能瞬间逆转濒临绝境的战局。",
        en = "A classic 40mm breech-loading launcher mounted beneath rifle barrels to supply instant explosive support. Sliding the tube forward to chamber a high-explosive fragmentation round allows solo riflemen to disperse charging mobs with one thundering blast.",
    },
    ["m203_mod"] = {
        zh = "经过废土枪匠改装并加装了独立手枪握把与皮卡汀尼导轨的独立型榴弹发射器。摆脱了依赖步枪前护木挂载的束缚，你可以把它当成一把折叠便携的微型迫击炮，挂在腰间随时随地轰击障碍。",
        en = "A modified 40mm launcher fitted with standalone pistol grips and stock adapters. Free from the cumbersome front-heavy weight of underbarrel mounting, it rides comfortably on a sling like an explosive mini-cannon ready for instant deployment.",
    },
    ["m235tpa"] = {
        zh = "填充了增稠自燃三乙基铝液体燃料的六十六毫米特种火箭弹，遇空气即刻自燃并粘附燃烧。在炸裂的瞬间飞溅出数千度的高温粘稠火雨，连最坚硬的变异外骨骼都会在烈焰中融化成流淌的骨浆。",
        en = "A 66mm rocket packing thickened pyrophoric triethylaluminum that ignites spontaneously upon atmospheric exposure. Detonating with terrifying fury, it splatters superheated flaming gel that adheres to mutated chitin, melting biological armor into bubbling sludge.",
    },
    ["m240"] = {
        zh = "美军现役全威力通用机枪，坚固厚重的全钢机匣能耐受万发弹药的连续倾泻。在避难所高墙上架设起这挺重型机枪，连绵不绝的七点六二毫米弹雨是让任何尸潮望而却步的钢铁防线。",
        en = "A battle-proven general-purpose machine gun built around a forged steel receiver. Perched upon fortified perimeter sandbags, its thundering belt-fed 7.62mm fire forms an impenetrable curtain of lead that breaks massed zombie charges.",
    },
    ["m240semi"] = {
        zh = "为满足民用合法化而特别设计的半自动击发控制组，去掉了原本全自动连发功能。在末世面对汹涌而来的暴走怪兽时，只能单发点射的限制让人急得想要把这套扳机当场砸碎在地上。",
        en = "A civilian-legal trigger group mechanically restricted to semi-automatic fire. When facing ravenous hordes lunging over the barricades, clicking through single shots will make you curse bureaucratic disarmament laws with every frantic trigger pull.",
    },
    ["m249"] = {
        zh = "久负盛名的班组自动武器SAW，可兼容弹链与标准北约步枪弹匣供弹。它将轻机枪的猛烈压制火力压缩到了单兵可携行的极限，是任何突击小队在清扫被占城镇时的火力核心。",
        en = "The iconic squad automatic weapon capable of feeding from disintegrating belts or standard STANAG magazines. Packing devastating suppression into a man-portable package, it anchors assault fireteams sweeping zombie-infested urban centers.",
    },
    ["m249_semi"] = {
        zh = "昂贵的民用半自动复刻版M249，保留了军规沉重外表却只能单发扣响。虽然被硬核枪迷嘲笑为最沉重的单发卡宾枪，但只要能连续稳定供弹，沉重枪身带来的几乎为零的后坐力依然极佳。",
        en = "A collector's semi-automatic replica of the military SAW, retaining full combat weight without automatic fire. Though mocked as a fifteen-pound carbine, its massive bulk completely soaks up recoil during rapid-fire target engagements.",
    },
    ["m249semi"] = {
        zh = "用来限制M249只能进行单发射击的民用改装快慢机零件。在失去法律束缚的废土世界，每一位捡到它的枪匠都会第一时间琢磨着用锉刀和焊枪，把那让人痛快淋漓的全自动功能重新焊接回来。",
        en = "A specialized trigger pack engineered to restrict M249 firing mechanisms to semi-auto operation. In a lawless wasteland, any enterprising gunsmith will immediately grab a file and torch to restore glorious full-auto mayhem.",
    },
    ["m26_mass"] = {
        zh = "可下挂在突击步枪枪管下方或加装枪托独立使用的模块化直拉式霰弹系统。专为特种破门与近距遭遇设计，让步枪手在无需切换武器的情况下，瞬间轰出毁灭性的鹿弹压制火力。",
        en = "A modular straight-pull shotgun system mountable beneath rifle forends or deployed standalone with an adapter stock. Built for tactical breaching, it arms point-men with instant high-gauge destruction without requiring sling swaps.",
    },
    ["m26_mass_mag_3"] = {
        zh = "紧凑型三发装M26霰弹枪单排盒式弹匣，外形极其扁平低调。虽然仅仅三发鹿弹让人有些缺乏安全感，但极为轻巧的体积保证了下挂步枪时不会被杂乱的障碍物和门框刮蹭绊住。",
        en = "A flat, ultra-compact three-round detachable box magazine for the M26 system. While three shells offer modest sustained firepower, its flush profile prevents the underbarrel weapon from snagging on tight doorframes during close-quarters entries.",
    },
    ["m26_mass_mag_5"] = {
        zh = "标准的五发装M26战术霰弹枪弹匣，兼具良好的弹药携行量与快速装填速度。在狭窄室内突入清剿时，连续扣动扳机轰出五发高压重弹，能瞬间将堵在走廊拐角的丧尸彻底撕碎。",
        en = "A standard five-round polymer magazine feeding 12-gauge shells smoothly into M26 shotguns. Pumping five continuous rounds of heavy buckshot down cramped residential hallways obliterates barricaded abominations before they can react.",
    },
    ["m26_mass_mod"] = {
        zh = "配有标准皮卡汀尼导轨卡扣的改装型M26霰弹模块，能稳固咬合在任何战术步枪前护木下方。在突发近身搏杀时，手指轻轻下移便能释放十二号口径的暴怒，是破门手最爱的终极底牌。",
        en = "A modified M26 modular shotgun outfitted with quick-locking rail clamps. Anchored beneath tactical carbines, sliding your trigger finger downward unleashes 12-gauge fury, giving point-men unmatched point-blank breaching authority.",
    },
    ["m26_mass_standalone"] = {
        zh = "加装了独立手枪握把与伸缩枪托的完整独立版M26战术霰弹枪。轻巧紧凑且机动性极强，单手便能轻松携行操控，是废土游侠在狭窄下水道或地窖搜刮时最轻便可靠的防身利器。",
        en = "A standalone configuration of the M26 shotgun equipped with dedicated pistol grip and collapsible skeleton stock. Exceptionally nimble in tight spaces, it makes a lightweight survival companion for clearing claustrophobic subterranean bunkers.",
    },
    ["m26_mass_stock"] = {
        zh = "由轻质航空铝合金与高强度聚合物结合打造的M26专用独立接合枪托套件。只需咔哒一声卡紧锁扣，就能把冰冷的下挂霰弹模块瞬间变成一把趁手的微型主战霰弹枪。",
        en = "A specialized aluminum buffer tube adapter and polymer buttstock built for M26 modules. Snapping it securely onto the receiver instantly transforms an awkward underbarrel attachment into an ergonomic shoulder-fired primary weapon.",
    },
    ["m2browning"] = {
        zh = "威震战场一个世纪的传奇点五零口径白朗宁M2重机枪，外号“老干妈”。重达近四十公斤的钢铁巨兽在车顶咆哮时，打出的重型钨芯穿甲弹能像切豆腐一样将变异巨兽连同砖墙一齐轰穿。",
        en = "The immortal Ma Deuce .50-caliber heavy machine gun, roaring continuously across a century of human conflict. Bolted onto technical trucks, its thundering kinetic slugs pulverize concrete bunkers and gargantuan mutants with ruthless historical authority.",
    },
    ["m2carbine"] = {
        zh = "在经典M1卡宾枪基础上增加了全自动连发机构的狂暴版本，射速惊人高达每分钟七百多发。由于整枪轻巧如玩具，全自动开火时枪口剧烈上跳，必须死死下压枪管才能把弹雨送进丧尸胸膛。",
        en = "The select-fire evolution of the M1 carbine, dumping .30 Carbine rounds at blistering cyclic rates. Because the weapon is light as a toy, firing full-auto requires muscular control to keep muzzle climb from spraying clouds.",
    },
    ["m320"] = {
        zh = "配有侧开式装填管、独立折叠握把与激光测距瞄具的先进独立榴弹发射器。侧开机构允许装入任何超长特种弹药，在废墟交火中单兵抬手一发精确高爆弹，便能瞬间瓦解敌方火力点。",
        en = "An advanced 40mm launcher featuring a side-swinging barrel that easily accommodates elongated specialty munitions. Deployed with its standalone folding stock, solo riflemen deliver precise explosive solutions across hundreds of meters of broken terrain.",
    },
    ["m320_mod"] = {
        zh = "专为下挂在步枪下方而设计的M320枪挂榴弹发射器组件。相较于老旧的前推式发射管，其侧开设计能让射手在任何别扭的卧姿掩体后轻松完成装填，为步兵小队提供连绵不绝的面杀伤威慑。",
        en = "The underbarrel configuration of the M320 designed to mount directly to military rifle handguards. The ergonomic side-loading breech allows effortless reloading while lying prone behind low rubble, maintaining steady explosive fire.",
    },
    ["m320_mod_mod"] = {
        zh = "经过废土技术工匠精巧打磨与改制接口的特种改装M320发射模块。它几乎能兼容安装在任何非标突击步枪或民用导轨护木上，让老旧步枪瞬间获得发射全套军用四十毫米弹药的能力。",
        en = "A field-modified M320 launcher module adapted with universal mounting clamps to fit non-standard civilian rails. It instantly elevates ordinary scavenged carbines into dual-threat platforms capable of firing standard military 40mm high explosives.",
    },
    ["m3_carlgustav"] = {
        zh = "享誉全球的八十四毫米多用途单兵无后坐力炮，炮膛内部刻有精密的旋转膛线。发射高爆破甲火箭弹时喷涌出惊天动地的尾焰，无论面前是狂暴变异尸王还是装甲掩体，都将在巨响中化作碎屑。",
        en = "An 84mm rifled shoulder-fired recoilless cannon delivering devastating anti-armor warheads. Blasting outward with a deafening backblast wave, its precision projectiles reduce armored vehicles and towering mutant abominations to smoking craters.",
    },
    ["m4_carlgustav"] = {
        zh = "采用超轻钛合金与碳纤维复合外壳全面减重的现代化M3E1无后坐力炮。不仅携带重量大幅减轻，还整合了智能火控接口，让单兵在高速机动作战中随时能轰出精准致命的重装穿甲打击。",
        en = "The modernized titanium-and-carbon-fiber evolution of the Carl Gustaf, shaving critical pounds off the infantryman's burden. Featuring digital fire-control mounts, it delivers pinpoint heavy ordnance against mobile threats while preserving operator agility.",
    },
    ["m60"] = {
        zh = "越野战场上名震天下的点三零八口径“猪”式重型通用机枪，带有标志性的前脚架与散热提把。只要弹链箱供弹不断，它沉稳而有力的连发重击声，就是防守孤岛营地时最让人安心的心跳律动。",
        en = "The legendary Vietnam-era M60 machine gun, affectionately christened \"The Pig\" by battle-hardened grunts. Delivering steady, rhythmic 7.62mm thumps from its integrated bipod, it reliably suppresses encroaching hordes as long as ammunition belts feed smoothly.",
    },
    ["m60_semi"] = {
        zh = "极为罕见的民用半自动复刻版M60机枪，庞大沉重的全钢枪身足以让人筋疲力尽。尽管失去了扫射压制力，但在中远距离充当重型半自动狙击连发机枪使用，弹道稳定得令人叹为观止。",
        en = "A rare semi-automatic civilian variant of the hefty M60 machine gun. Stripped of continuous belt-dumping capability, its substantial mass provides a rock-solid shooting platform that drops long-range rounds on target with virtually non-existent muzzle climb.",
    },
    ["m74_clip"] = {
        zh = "由四枚特种六十六毫米火箭弹并联封装而成的预装快速装填夹，专为M202发射器定制。将这一整组火箭弹平推滑入发射管后部，清脆的卡扣锁死声宣告着毁天灭地的四发连发齐射准备就绪。",
        en = "A four-tube rapid reload clip holding clustered 66mm incendiary rockets for the M202 launcher. Sliding this heavy pack into the breech latches all four rockets simultaneously, priming the quad-launcher for catastrophic multi-target bombardment.",
    },
    ["m79"] = {
        zh = "外形优雅如老式单管猎枪的经典折开式四十毫米榴弹发射器，外号“重击者”。向前折下枪管塞入榴弹，击发时那独特的“咚”的一声闷响，是整个战场上最动听却又最致命的死神敲门声。",
        en = "The iconic break-action 40mm \"Thumper\" launcher resembling an overgrown sporting shotgun. Popping the barrel open to slide a grenade home produces that unmistakable, resonant \"bloop\" sound that spells instant doom for distant enemy clusters.",
    },
    ["m9"] = {
        zh = "曾服役美军数十载的经典意大利血统半自动战斗手枪，经典的开放式套筒设计极大减少了卡壳概率。握把宽大饱满且扳机平顺，是无数退伍军人与末世流浪者心中最忠实顺手的防身伙伴。",
        en = "The open-slide 9mm combat sidearm that served military forces for decades with legendary operational reliability. Its ergonomic grip and smooth double-action pull make it a deeply familiar, reassuring sidearm for veteran survivors facing unknown perils.",
    },
    ["m9bigmag"] = {
        zh = "从握把下方突出大半截的三十发超长M9手枪弹匣，宛如一根沉重的黑钢拐杖。插上它虽然让手枪变得头重脚轻难以入套，但在遭遇群尸围堵的电梯狭窄空间内，它能让你化身无情的泼弹机器。",
        en = "A comedic yet terrifying thirty-round stick magazine protruding far past the M9's basepad. Making the handgun impossibly bulky for standard holsters, it transforms your sidearm into an emergency submachine gun during claustrophobic hallway ambushes.",
    },
    ["m9mag"] = {
        zh = "标准的十五发双排冲压钢制M9原装弹匣，配有防锈涂层与高可靠性复进簧。其优异的弹药包容性与顺滑供弹，是每一位搜刮废弃警局军火库的拾荒者最渴望找到的标准军规消耗品。",
        en = "The standard fifteen-round steel box magazine designed for Beretta service pistols. Feeding 9mm cartridges with flawless consistency through thousands of cycles, stocking your chest rig with clean spares ensures dependable tactical readiness.",
    },
    ["m9mag_10rd"] = {
        zh = "受限产地枪械法规而特别限容为十发的民用M9弹匣，侧面带有压槽限制托弹板下移。虽然容弹量略显不足，但在末世搜刮中只要能装上十颗黄澄澄的九毫米子弹，它依然是救命的利器。",
        en = "A ten-round compliant magazine restricted by civilian magazine capacity limits with crimped steel walls. While offering reduced capacity compared to military magazines, ten reliably feeding rounds remain far superior to an empty pistol chamber.",
    },
    ["m9mag_17rd"] = {
        zh = "采用现代化薄壁强化钢板冲压制成的高容十七发M9弹匣，底部与原装握把严密贴合。多出的两发弹容量在毫无额外突出的情况下，为射手提供了更加充裕的容错率与连发火力储备。",
        en = "A flush-fitting seventeen-round steel magazine utilizing optimized internal geometry. Offering two extra rounds over military surplus magazines without protruding from the grip, it maximizes compact firepower during fast-paced firefights.",
    },
    ["m9mag_18rd"] = {
        zh = "配有轻薄聚合物加厚底板的十八发M9加长弹匣，手感极其顺畅扎实。这多出的三发弹药在与变异猎犬贴身周旋时，往往就是决定你是否能活着清空滑套并全身而退的关键胜负手。",
        en = "An eighteen-round extended magazine fitted with a low-profile polymer floorplate for smooth handling. Those extra three rounds provide critical insurance when fending off aggressive feral packs that refuse to go down after standard taps.",
    },
    ["m9mag_20rd"] = {
        zh = "底部带有加厚铝合金配重底座的二十发M9战术弹匣，常用于特警破门分队。装弹二十发让整支手枪重心沉稳，在连续快速射击时能极大抑制后坐力跳动，提供密集的火力掩护。",
        en = "A tactical twenty-round magazine sporting an extended alloy basepad favored by counter-assault units. Adding substantial mass to the pistol's grip frame, it dampens muzzle flip while delivering generous firepower between necessary tactical reloads.",
    },
    ["m9mag_32rd"] = {
        zh = "长达近三十厘米的超高容量三十二发加长钢弹匣，外形霸道得像一根短棍。在被尸潮逼上楼顶的绝境关头，一口气将三十二发穿甲弹不间断泼洒而出，能为你的突围生生撕开一道血路。",
        en = "A foot-long steel magazine holding thirty-two rounds of continuous 9mm fire. Unloading its entire capacity into an advancing bottleneck creates a concentrated lead storm that carves escape corridors through overwhelming zombie barricades.",
    },
    ["m9mag_35rd"] = {
        zh = "市面上所能找到的极限容量三十五发超长M9弹匣，插在手枪上显得滑稽而致命。弹簧压满三十五发子弹需要惊人的拇指指力，但扣下扳机连绵不断的轰鸣能彻底治愈任何火力不足恐惧症。",
        en = "The absolute maximum-capacity thirty-five-round stick magazine engineered for Beretta handguns. Loading its ultra-stiff spring exhausts your fingers, but unleashing thirty-five uninterrupted rounds completely cures any lingering apocalyptic ammunition anxiety.",
    },
    ["m_fishspear"] = {
        zh = "用生锈铁管与多根削尖钢筋手工焊接而成的三股倒刺金属鱼叉。在浑浊的废土河流边涉水潜行，瞄准水底潜游的变异大头鱼猛力扎下，倒刺能死死锁住挣扎的猎物，为你带来一顿肥美鲜鱼。",
        en = "A barbed trident forged by welding sharpened rebar prongs to a hollow pipe handle. Wading murky, irradiated shallows, driving its sharp tines into schooling catfish secures high-protein dinners that cannot wriggle off the barbs.",
    },
    ["m_stellatum_berries"] = {
        zh = "从林下多花黄精植物上采摘的深色浆果，表面带有淡淡的果粉。虽然味道清甜多汁，但吃多了容易导致轻微恶心和腹泻，在饥肠辘辘的荒野求生中，浅尝几颗解渴是不错的选择。",
        en = "Dark berries plucked from forest-dwelling false Solomon's seal plants, dusted with faint natural bloom. Sweet yet mildly purgative in large quantities, popping a cautious handful moistens parched throats when clean streams are miles away.",
    },
    ["mac10mag"] = {
        zh = "粗壮厚实的三十发点四五口径MAC-10冲锋枪双排双进直弹匣。装满大威力的点四五钝头重铅弹后沉甸甸的，是这把疯狂喷弹机器在极高射速下维持凶悍破坏力的唯一食粮。",
        en = "A heavy stamped steel thirty-round box magazine built to feed chunky .45 ACP slugs into MAC-10 submachine guns. Built like a brick, it feeds fat cartridges reliably through the weapon's notoriously ravenous rate of fire.",
    },
    ["mac11mag"] = {
        zh = "专为九毫米或点三八零口径紧凑型MAC-11冲锋手枪定制的三十二发加长弹匣。以每分钟上千发的惊人射速倾泻时，这个弹匣在不到两秒钟内就会彻底打空，换来面前敌人身上一排密集的血洞。",
        en = "A slender thirty-two-round magazine tailored for the blistering cyclic rate of the MAC-11 machine pistol. Emptying its entire payload in two breathless seconds, it riddles close-range ambushers with a tight cluster of fatal perforations.",
    },
    ["mac_10"] = {
        zh = "采用粗暴冲压铁皮机匣打造的传奇微型冲锋枪，射速凶猛宛如狂暴的电锯。全自动射击时枪口疯狂上跳且毫无精度可言，但把它顶在狂暴丧尸的胸口扣死扳机，能在瞬间将其轰成漫天碎肉。",
        en = "A stamped-sheet-metal submachine gun spitting .45-caliber slugs with terrifying, chainsaw-like ferocity. Lacking long-range accuracy, pressing its stubby muzzle against an armored mutant's chest disintegrates bone and muscle in one roaring burst.",
    },
    ["mac_11"] = {
        zh = "进一步缩小尺寸的微型全自动冲锋手枪，小巧得几乎能塞进大衣暗袋。扣动扳机的瞬间，密集的弹雨会在一眨眼间倾泻而出，是一把极度考验射手控枪技巧与神经反射的近距肉搏杀器。",
        en = "A miniaturized machine pistol that dumps its entire magazine in a single blinding heartbeat. Demanding steel wrists to maintain control, it represents the ultimate point-blank panic button when horrifying monsters suddenly drop from basement ceilings.",
    },
    ["macaroni_cooked"] = {
        zh = "在一小锅滚水中煮至软弹并裹满金黄融化芝士酱的经典通心粉。浓郁黏稠的芝士拉出诱人长丝，每一口都充满了热气腾腾的高热量抚慰，是在末日暴雪夜里治愈心灵创伤的终极神菜。",
        en = "Tender tubular pasta smothered in rich, velvety melted cheese sauce. Piping hot and lavishly savory, slurping down a steaming bowl in a drafty shelter melts away the exhausting trauma of long wasteland scavenging runs.",
    },
