    ["offal"] = {
        zh = "一盆从猎杀的野鹿或牛体内掏出来的生内脏杂碎。虽然腥味冲天且混杂着未消化的草料，但在缺少油脂和维生素的废土上，稍微清洗后就是熬制浓汤的上等原料。",
        en = "A bowl of raw offal harvested from harvested game animals. Smelling pungently of digestive juices, a careful rinse and a hot pot turn these neglected organs into a nutrient-packed stew.",
    },
    ["offal_canned"] = {
        zh = "大灾变前军工厂生产的密封马口铁罐装动物内脏。开罐后虽然飘出一股油腻凝固的肝腥气，但防腐真空保存让它依然具备完整的食用价值，提供宝贵的蛋白质和热量。",
        en = "Pre-war canned offal preserved in heavy gelatin broth. Prying the lid open releases a greasy aroma, but the shelf-stable organs deliver crucial protein when winter blizzards pin you down.",
    },
    ["offal_cooked"] = {
        zh = "用沸水煮透并用盐巴调味熟透的动物杂碎。口感脆嫩软烂各异，热气腾腾地嚼在嘴里满口肉香，在饥寒交迫的夜晚来上一大碗，整个人都从脚趾暖和到了天灵盖。",
        en = "Tender boiled organ meats seasoned with a pinch of rock salt. Chewy and rich, downing a steaming bowl on freezing nights warms you thoroughly from your toes to your ears.",
    },
    ["offal_pickled"] = {
        zh = "用烈度极高的酸醋与黑胡椒粒腌制在玻璃罐里的杂碎肉。酸爽刺激的口感不仅彻底压制住了内脏的腥膻，更能长期存放在常温背包中，是远途侦察兵最喜爱的干粮。",
        en = "Organ cuts preserved in sharp vinegar brine with black peppercorns. The intense sour tang cuts through gamey richness, producing a durable ration that survives months inside travel packs without spoiling.",
    },
    ["offalcooking"] = {
        zh = "由名厨撰写的节日动物内脏全席硬皮烹饪食谱书。详尽记载了如何将动物肝脏、心肺与肠肚通过香料腌制转化为顶级美味，教导末日大厨践行从头吃到尾绝不浪费一丝肉食的生存哲学。",
        en = "A holiday culinary manual exploring recipes that transform animal organ meats into sumptuous feasts. Championing true nose-to-tail cooking, it instructs survivalists on converting humble hearts and livers into savory gourmet provisions.",
    },
    ["office_holepunch"] = {
        zh = "全金属冲压制造的小型桌面单孔打孔器。利用弹簧与锋利圆柱冲头能在纸张边沿精准打出规整圆孔，在工坊中用来装订散落的机械图纸或手工制作自制活页笔记极其顺手便捷。",
        en = "A compact steel office tool that punches neat circular perforations through sheets of paper. Ideal for binding loose technical schematics, maps, and salvaged journals into organized, ring-bound field survival manuals.",
    },
    ["office_letter_opener"] = {
        zh = "一把采用纯银打造、做工典雅如微型短剑的战前贵族开信刀。刀尖尖锐利落而刀刃未开，本是优雅裁开封蜡信封的文案摆件，在紧急遇险时握在手中刺入敌方眼眶也能防身制敌。",
        en = "A polished sterling silver letter opener shaped like an ornate stiletto. Featuring a sharp tapered point and blunted edges for slicing envelopes, it doubles as an elegant emergency shiv when cornered by lurkers.",
    },
    ["officer_uniform"] = {
        zh = "挺拔修身且缀有金色绶带与肩章的军官常服礼服。面料笔挺昂贵，穿上它自带着旧帝国统帅的威严气场，即便如今手下只有两只土狗与三个面黄肌瘦的流浪汉，也能过一把将军瘾。",
        en = "A tailored military dress uniform adorned with polished brass buttons and braided aiguillettes. Donning this ceremonial attire bestows an air of imperial authority, even if your entire army consists of mangy stray dogs.",
    },
    ["offset_grip"] = {
        zh = "安装在战术护木侧方呈四十五度倾斜的辅助前握把。符合快速近战反应的人体工学，让射手在狭窄拐角处侧身倾斜射击时手腕更加自然受力，极大提升了近距交火的控枪稳定性。",
        en = "A tactical foregrip angled forty-five degrees off the rifle rail. Allowing an ergonomic canted shooting stance around tight urban corners, it relieves wrist strain and vastly improves recoil control during frenetic close-quarters engagements.",
    },
    ["offset_sight_rail"] = {
        zh = "固定在机匣导轨侧面的四十五度倾斜式附加瞄准镜基座。为主瞄具旁加装微型红点提供了完美平台，只需微微侧倾枪身便能从高倍狙击视线无缝切入贴脸快瞄，是神枪手近战防身利器。",
        en = "A canted offset rail mount engineered to seat micro red dots alongside high-magnification scopes. Tilting the rifle slightly provides instantaneous target acquisition for surprise point-blank threats without disturbing long-range zeroing.",
    },
    ["offset_sights"] = {
        zh = "安装在高倍瞄准镜侧面四十五度角的倾斜机械瞄具。只需将步枪微微一侧，就能瞬间从远距离狙击模式切换为近战贴脸瞄准，避免在走廊转角被突脸丧尸打得措手不及。",
        en = "Canted iron sights mounted at forty-five degrees beside bulky optics. Tilting your rifle allows immediate reflex aiming during sudden close-quarters ambushes without fumbling with magnification knobs.",
    },
    ["oil_cooker"] = {
        zh = "以煤油或废弃植物油为燃料的便携式金属烹饪炉。炉火稳定且抗风耐用，拧开调节阀点燃棉芯，短短几分钟便能在寒夜里煮沸一锅热汤，是避难所工坊不可多得的无电烹饪神炉。",
        en = "A compact pressurized cooker designed to burn kerosene, lamp oil, or rendered fats. Providing a steady, adjustable flame without needing electrical grids, it rapidly boils hearty stews to keep shivering survivors fed and warm.",
    },
    ["oil_extractor_crude"] = {
        zh = "利用废铁管、蒸馏罐与冷凝铜管粗暴焊接而成的简易精油萃取器。利用水蒸气蒸馏原理从松针与野薄荷中提取浓缩挥发油，是末日自制防虫驱蚊药水与消毒芳香剂的核心设备。",
        en = "A cobbled distillation apparatus constructed from scrap metal pipe and coiled copper tubing. Utilizing steam evaporation, it extracts aromatic essential oils from wild herbs and pine needles to produce antiseptic salves and bug repellents.",
    },
    ["oil_lamp"] = {
        zh = "一盏带有防风玻璃罩与黄铜底座的经典手提煤油灯。目前处于熄灭状态，只要注入灯油并擦亮火柴，就能在昏暗的避难所木桌上散发出温暖持久的橘黄色光芒，陪伴你度过漫漫长夜。",
        en = "A traditional kerosene lantern fitted with a glass chimney and brass reservoir. Extinguished for now, filling its font and lighting the wick casts a long-lasting, comforting amber glow across drafty shelter workshops.",
    },
    ["oil_lamp_clay"] = {
        zh = "用黏土手工捏塑烧制而成的原始敞口油灯。目前尚未点燃，虽然完全没有任何防风设计、稍有微风就会熄灭，但在封闭的地下地窖中注入动物油脂，便能提供数小时朴素的微弱光亮。",
        en = "A primitive unglazed clay oil lamp molded by hand. Completely open to the elements and easily blown out by drafty gusts, burning animal tallow inside enclosed underground basements provides frugal, long-lasting ambient illumination.",
    },
    ["oil_lamp_clay_on"] = {
        zh = "正在微弱燃烧的原始黏土油灯。油芯浸润着油脂，散发着微弱的黄光与淡淡的动物油烟焦味，在漆黑静谧的洞穴深处，这点脆弱的火苗是驱赶永恒黑暗与未知恐惧的唯一依托。",
        en = "A burning clay oil lamp flickering softly in the quiet darkness. Emitting a humble yellow flame and faint tallow smoke, its gentle warmth keeps absolute blackness and creeping subterranean claustrophobia at a manageable distance.",
    },
    ["oil_lamp_on"] = {
        zh = "正在平稳燃烧的便携煤油防风灯。玻璃罩被擦拭得一尘不染，柔和明亮的火光将工作台照耀得格外温馨，静静燃烧的煤油味让人联想起大灾变前文明安宁的书房之夜。",
        en = "An active kerosene lantern glowing warmly behind a clean glass globe. Casting steady illumination across maps and disassembly benches, its quiet flame brings nostalgic comfort reminiscent of tranquil evenings before the civilized world ended.",
    },
    ["oil_press_electric"] = {
        zh = "一台工业级电机驱动的重型螺旋榨油机。虽然目前处于断电待机状态，但只要接入发电机电网，强劲的液压螺杆能轻松将几百公斤葵花籽压榨成清澈流淌的食用油与高能油饼。",
        en = "A heavy industrial electric screw press built for automated oilseed processing. While currently disconnected from power grids, linking it to generators yields torrents of clean cooking oil and nutrient-packed press cake from bulk seeds.",
    },
    ["oil_press_manual"] = {
        zh = "配有电热板预热辅助的手摇式紧凑型螺旋榨油机。通过手动摇柄旋转高强度螺杆，配合电热软化坚果外壳，能高效从向日葵籽和核桃仁中榨取出澄黄的植物油，省力又耐用。",
        en = "A rugged hand-cranked oil press augmented with a heated hopper plate. Manually turning its mechanical screw compresses softened seeds, efficiently extracting golden vegetable oil to keep survival larders and grease lamps abundantly supplied.",
    },
    ["oil_press_primitive"] = {
        zh = "以木桶与巨型金属螺旋压榨杆改造的煤油加热传统榨油机。底部煤油炉烘烤出坚果香气，拼尽全力转动横杆加压，金黄的初榨原油便顺着木槽汩汩流出，是野外自耕农的油脂重器。",
        en = "A crude barrel press heated by a kerosene burner beneath its hopper. Cranking the massive overhead screw exerts immense manual pressure, squeezing rich amber oil from roasted nuts into wooden collection buckets below.",
    },
    ["oj"] = {
        zh = "一瓶在超市冷柜废墟中幸运搜刮到的纸盒包装商业纯橙汁。酸甜爽口且富含纯天然维生素C，一口灌下去能彻底抚平溃疡嘴唇的疼痛，让人感受到久违的清新文明甘霖。",
        en = "A chilled carton of commercial orange juice scavenged from grocery coolers. Brimming with refreshing citrus acidity and essential Vitamin C, drinking it provides a lively energy boost that banishes lingering symptoms of scurvy.",
    },
    ["oj_fresh"] = {
        zh = "用新鲜多汁的大橙子在压汁器上手工压榨出的百分之百纯鲜橙汁。果肉颗粒分明，清甜纯粹毫无防腐剂怪味，在这片被尘土与死尸污染的废土上，喝上一杯简直是帝王般的奢靡享受。",
        en = "Freshly squeezed orange juice pressed directly from ripe citrus fruit. Tart, vibrant, and bursting with fresh pulpy goodness, enjoying a cold glass in the apocalypse feels like an extravagant luxury fit for emperors.",
    },
    ["old_key"] = {
        zh = "一把边缘磨损严重的旧式北美圆筒弹子门锁黄铜钥匙。钥匙上的齿痕平凡无奇，天知道它对应的锁孔留在哪栋早已坍塌成废墟的旧公寓里，但拾荒者总是不舍得把它随手扔掉。",
        en = "A worn brass cylinder key bearing nondescript notches. Its matching lock likely vanished beneath collapsed brick tenements decades ago, yet paranoid scavengers instinctively stash it in pockets, hoping to stumble upon its forgotten door.",
    },
    ["omelet"] = {
        zh = "在铁锅里打散鸡蛋并用小火煎至金黄软嫩的家常煎蛋卷。散发着令人垂涎欲滴的浓郁蛋香，软糯温热的蛋皮滑入口腔，能瞬间将你从血腥屠戮的残酷现实拉回和平岁月。",
        en = "A golden, fluffy omelet folded neatly over a camping skillet. Releasing heavenly buttery aromas, its gentle warmth offers a fleeting psychological retreat from the unending horrors outside your window.",
    },
    ["omni_wheel"] = {
        zh = "从退役防暴警用机器人底盘上完整拆卸下的一套全向轮组。外圈密布垂直滚轮，能赋予载具三百六十度原地平移漂移的惊人机动性，是改装避难所室内巡逻战车的黑科技核心部件。",
        en = "A set of specialized omnidirectional wheels salvaged from police drone chassis. Ringed with lateral rollers, they allow vehicles to strafe sideways and spin in place, offering unmatched indoor maneuverability for custom combat rigs.",
    },
    ["omnicamera"] = {
        zh = "带有超广角鱼眼镜头的工业级安防监控摄像头。虽然传感器分辨率不高、画面充满噪点，但连接显示屏后能提供近乎无死角的周边全景视野，是监控避难所外围动静的眼睛。",
        en = "An industrial security camera featuring an ultra-wide fisheye surveillance lens. Though video resolution is grainy and washed out, mounting it provides comprehensive panoramic perimeter monitoring to detect sneaking night stalkers.",
    },
    ["omnicamera_reinforced"] = {
        zh = "在广角摄像头外加装了高强度防弹防砸钢丝笼防护罩的特战监控头。不仅视野开阔毫无遮挡，更能抵御飞石碎屑撞击与行尸利爪撕扯，在恶劣阵地战中能始终保持侦查视线通畅。",
        en = "A panoramic security camera encased inside a heavy welded steel cage. Shielded against stray shrapnel, brick impacts, and grasping claws, it keeps vital external video feeds alive during fierce compound sieges.",
    },
    ["one_year_old_newspaper"] = {
        zh = "一整张出版于灾变一年前的完整旧报纸。上面刊登着新车促销广告与明星八卦绯闻，在这个连汽车电瓶都被搜刮一空、明星早已沦为丧尸的时代，读起来恍若隔世。",
        en = "A broadsheet printed a full year before the Cataclysm. Featuring dealership financing deals and celebrity scandals, reading about trivial pre-war gossip inside an armored bunker feels genuinely surreal.",
    },
    ["onigiri"] = {
        zh = "用喷香米饭手工捏成三角形、外层包裹着脆脆干海苔的日式传统饭团。内陷扎实可口，握在手里食用极其方便不沾手，是废土游侠跋涉荒野时最完美的便携充饥干粮。",
        en = "A triangular block of seasoned white rice wrapped in a crisp sheet of dried seaweed. Compact and mess-free to eat while marching, this handheld snack offers pure, convenient carbohydrate fuel for roving survivors.",
    },
    ["onion"] = {
        zh = "一颗包裹着干枯紫红外皮、水分饱满辛香浓郁的普通洋葱。切开时挥发性气体辣得人直掉眼泪，但在铁锅中炒出焦糖色后，却能让任何寡淡无味的罐头碎肉汤瞬间鲜甜升华。",
        en = "A pungent raw onion with crisp, layered bulbs. Slicing through its pungent layers burns tears into your eyes, but caramelizing it in hot grease elevates bland boiled forage into an aromatic culinary masterpiece.",
    },
    ["onion_rings"] = {
        zh = "裹上浓稠面糊下入滚油大火炸至金黄酥脆的洋葱圈。外壳咔嚓酥脆，内里洋葱软嫩多汁且带着甘甜，咬上一口油脂四溢，是犒劳疲惫胃袋的最堕落美味小吃。",
        en = "Golden-brown onion rings dipped in seasoned batter and deep-fried to crispy perfection. The sweet tender onion within contrasts deliciously against the crunchy shell, offering a greasy, high-calorie indulgence after grueling combat days.",
    },
    ["onion_sauteed"] = {
        zh = "在铁锅中用动物油脂慢慢文火煎炒至深褐焦香的焦糖洋葱。辛辣完全褪去，化作浓郁甜美的香气，随便铺在一块烤肉或干硬面包上，都能让粗糙的末日晚餐变成人间珍馐。",
        en = "Slices of onion slow-cooked in rich animal fat until deeply caramelized and tender. Their sharp bite mellows into rich savory sweetness, making them an incredible topping that transforms dry hardtack into gourmet fare.",
    },
    ["onyx"] = {
        zh = "一颗打磨得光滑如镜、通体乌黑深邃的天然高品质黑玛瑙原石。握在掌心冰凉细腻，虽然在大灾变后无法充当武器或食物，但其沉静典雅的光泽依然深受幸存者珠宝匠的喜爱。",
        en = "A polished black onyx gemstone boasting a deep, lustrous darkness. Smooth and cold against the skin, while useless for bludgeoning zombies, its timeless elegance makes it an exceptional specimen for delicate post-apocalyptic jewelry craft.",
    },
    ["onyx_gold_bracelet"] = {
        zh = "一条在纯金环带上对称镶嵌数颗漆黑玛瑙的奢华手镯。金黄的灿烂与玛瑙的深黑形成强烈反差，佩戴在布满老茧的手腕上，在废土黑市交易中能抵得上一整箱珍贵的高压子弹。",
        en = "A luxurious yellow-gold bracelet inset with gleaming black onyx stones. The stark contrast between radiant gold and midnight stone turns weary scarred wrists into aristocratic centerpieces prized by wealthy bunker merchants.",
    },
    ["onyx_gold_cufflinks"] = {
        zh = "一对镶嵌有八角切面黑玛瑙的黄金法式衬衫袖扣。做工极尽奢华考究，在尸骸遍野的焦土上虽然毫无战术价值，但出席避难所高层晚宴时戴上它，足以彰显旧世界权贵的气派。",
        en = "A pair of polished gold cufflinks set with faceted black onyx gems. Impractical against mutant claws, fastening them to dress shirt cuffs projects an aura of civilized sophistication amidst the ruins of collapsed society.",
    },
    ["onyx_gold_earring"] = {
        zh = "一对做工精巧、以纯金细钩悬挂黑色水滴玛瑙的耳环。在摇曳烛火下轻轻晃动闪烁微光，是任何爱美女性幸存者在残酷末世中依然不愿舍弃的生活品味见证。",
        en = "A pair of dangling gold earrings holding teardrop-shaped onyx stones. Catching soft candlelight as they sway, they represent a stubborn, radiant refusal to abandon personal grace and aesthetic beauty amidst apocalyptic horror.",
    },
    ["onyx_gold_pendant_necklace"] = {
        zh = "一根由细密黄金链条串起鸽子蛋大小黑玛瑙吊坠的高贵项链。深邃黑石在金边包裹下静默生辉，贴在胸口能感受到冰凉与金属沉重感，是末世里无可挑剔的顶级奢华饰品。",
        en = "A lustrous gold chain suspending a hefty, bezel-set black onyx pendant. Resting gracefully over armor padding, its dark centerpiece radiates timeless luxury that draws covetous glances across frontier barter trading posts.",
    },
    ["onyx_gold_ring"] = {
        zh = "一枚在宽厚纯金戒圈顶端平嵌平顶椭圆黑玛瑙的图章戒指。沉稳厚重大气，戴在食指上既能展现上位者的尊贵威严，在近身肉搏挥拳时也能充当一枚坚固纯金小指虎。",
        en = "A heavy gold signet ring featuring a flat, polished oval onyx table. Dignified and weighty on the finger, it projects commanding leadership while delivering a surprisingly solid metallic punch during desperate bare-knuckle scuffles.",
    },
    ["onyx_gold_tiara"] = {
        zh = "由高纯度黄金拉丝编织、顶端环绕镶嵌多颗黑玛瑙的精致贵族小王冠。戴在头顶虽然无法抵御丧尸飞扑撕咬，但那股高傲的帝王气度足以让你在废土营地中受尽众人瞩目。",
        en = "An ornate gold tiara studded with an array of midnight-black onyx stones. Offering negligible ballistic defense against mutant ambushes, crowning your brow with it commands immediate, bewildered deference from ragtag settlement residents.",
    },
    ["onyx_platinum_bracelet"] = {
        zh = "采用稀有重金属铂金铸造、镶满深黑玛瑙的冷冽手镯。白金的冷峻与黑玛瑙的深邃融为一体，沉甸甸的金属分量让人爱不释手，在任何大型据点都是不可多得的硬通货。",
        en = "A cold, substantial platinum bracelet accented with meticulously inset black onyx stones. Combining dense precious metal with dark gems, it embodies understated modern wealth that buys favors from the most jaded wasteland warlords.",
    },
    ["onyx_platinum_cufflinks"] = {
        zh = "一对用坚硬铂金底座托举镜面黑玛瑙的高档袖扣。永不褪色与氧化的稀有铂金赋予其永恒质感，是战前顶级富豪的专属配饰，佩戴在防化风衣袖口自有一种冷面杀手风范。",
        en = "A set of sleek platinum cufflinks securing square cuts of polished onyx. Resisting corrosion and tarnish through the harshest radioactive weather, they lend a sharp, steely edge of sophistication to any formal combat attire.",
    },
    ["onyx_platinum_earring"] = {
        zh = "一对闪烁着银白冷光与幽黑倒影的铂金玛瑙耳环。材质极为昂贵奢华，无论佩戴者穿梭在阴暗地道还是血腥战场，耳畔摇曳的冷艳光泽始终在低语着昔日文明的优雅记忆。",
        en = "A pair of lustrous platinum earrings dangling geometric onyx drops. Their cool silvery sheen and obsidian stones glimmer against grim ruins, serving as a defiant talisman of enduring elegance in an uncivilized world.",
    },
    ["onyx_platinum_pendant_necklace"] = {
        zh = "由纯净铂金细链悬挂一颗大颗粒精琢黑玛瑙的现代风格项链。铂金的坚硬确保链条不易被扯断，垂挂在颈项间冰凉舒适，是无数掠夺者首领争相掠夺的稀世藏品。",
        en = "A high-tensile platinum necklace carrying a precision-cut black onyx cabochon. Unyielding against sudden snags and resistant to wear, its stark modern aesthetic marks its wearer as a survivor of supreme taste and fortune.",
    },
    ["onyx_platinum_ring"] = {
        zh = "用致密坚硬的纯铂金一体切削而成、中嵌整块纯净黑玛瑙的重型戒指。坚不可摧的材质永不生锈变形，戴在指间不仅赏心悦目，在砸碎车窗玻璃时甚至比钢棒还要顺手。",
        en = "A monolithic platinum band featuring an embedded rectangular onyx gemstone. Virtually indestructible and immune to tarnishing, this weighty piece of fine jewelry doubles as an emergency glass-breaker when scavenging vehicular wrecks.",
    },
    ["onyx_platinum_tiara"] = {
        zh = "用纯度极高的冷艳铂金手工锻造、镶嵌有整圈切割黑玛瑙的华贵王冠。在冷冽月光下泛着冰霜般的光泽，戴上它宛如黑夜的冷血女王，气场强大得令人不敢直视。",
        en = "A magnificent tiara forged from brilliant platinum and crowned with sharp onyx crystals. Gleaming like frost under moonlight, wearing this unearthly crown radiates chilling regal poise that awes hardened raiders into submission.",
    },
    ["onyx_silver_bracelet"] = {
        zh = "用九二五纯银精心打造成繁复花纹、镶嵌整排黑玛瑙的古典手镯。银质虽然容易产生氧化包浆，但那种古典复古的岁月沧桑感，恰好与废土流浪者的粗粝风霜完美契合。",
        en = "A sterling silver bracelet decorated with filigree engravings and inset with smooth black onyx beads. Developing a rich antiqued patina over weeks of wasteland scavenging, it blends timeless craftsmanship with rugged frontier grit.",
    },
    ["onyx_silver_cufflinks"] = {
        zh = "一对由纯银包裹深邃黑玛瑙的小巧正装袖扣。银质光泽柔和内敛，虽然在缺少烫平衬衫的废土上略显英雄无用武之地，但用来当作贵金属熔炼原料也是不可多得的银料。",
        en = "A pair of tasteful sterling silver cufflinks clasping oval onyx gems. Though crisp pressed shirts are rare in the ruins, keeping these in your pouch ensures a ready source of meltable high-purity silver for smithing.",
    },
    ["onyx_silver_earring"] = {
        zh = "一对纯银手工弯折成环并垂吊黑色玛瑙珠的复古耳环。银光与墨色相得益彰，轻盈灵动，即使在泥泞荒野中翻滚跋涉，也能为佩戴者保留最后一丝体面与爱美之心。",
        en = "A pair of understated sterling silver hoop earrings dangling polished onyx stones. Lightweight and secure against accidental snagging, they provide a gentle spark of personal dignity amidst mud-spattered wasteland journeys.",
    },
    ["onyx_silver_pendant_necklace"] = {
        zh = "用做旧纯银托架镶嵌黑玛瑙吊坠的复古银项链。暗沉的银链带着复古的做旧黑化效果，低调不扎眼，既不用担心反光引来丧尸注意，又是一件让人安心的护身首饰。",
        en = "An oxidized sterling silver chain supporting a bezel-mounted black onyx pendant. Its muted non-reflective finish avoids alerting distant snipers, while the cold weight against the sternum offers grounding comfort during lonely watches.",
    },
    ["onyx_silver_ring"] = {
        zh = "一枚在纯银雕花戒臂上镶嵌深邃黑玛瑙的经典古典男戒。银质温润贴手，深色玛瑙宛如深潭之水，戴在手上低调沉稳，在幸存者聚集地的酒馆中是一张优雅的身份名片。",
        en = "A vintage sterling silver ring mounting an enigmatic black onyx cabochon. Comfortable and quietly handsome, wearing this understated band projects calm confidence across smoky settlement taverns where flashier gold breeds jealous violence.",
    },
    ["onyx_silver_tiara"] = {
        zh = "由纤细纯银枝蔓缠绕编织而成、点缀着多颗小巧黑玛瑙的银冠。造型轻盈如森林精灵的头饰，在夜风中轻颤闪烁，给血腥残酷的末日世界增添了一抹梦幻般的月夜童话色彩。",
        en = "A delicate silver tiara woven in twisting botanical vine motifs and set with glistening onyx accents. Evoking ethereal woodland folklore, it brings whimsical fairytale enchantment into a world otherwise drowned in radioactive mud.",
    },
    ["opal"] = {
        zh = "一颗在光线折射下变幻出五彩斑斓变彩效应的天然名贵蛋白石。转动时红、绿、蓝三种光芒在半透明石体内如星云般流转，美轮美奂，是旧世界大自然最神奇的结晶奇迹。",
        en = "A polished iridescent opal flashing spectacular spectral hues under direct sunlight. Rainbow flickers of fiery red and oceanic green dance across its milky interior, serving as a mesmerizing natural marvel in a shattered world.",
    },
    ["opal_gold_bracelet"] = {
        zh = "在闪耀纯金链带上镶嵌数枚炫彩蛋白石的高端华丽手镯。金色的富贵与欧珀石的梦幻游彩相互映衬，戴在手腕上抬手间光华流转，是任何废土行商都无法抗拒的顶级宝物。",
        en = "A vibrant yellow-gold bracelet embellished with radiant multicolored opals. The interplay of gleaming gold and shifting rainbow iridescence creates a dazzling piece of wearable art capable of purchasing armories full of munitions.",
    },
    ["opal_gold_cufflinks"] = {
        zh = "一对以黄金底座镶嵌圆顶凸面炫彩蛋白石的尊贵袖扣。每当手腕转动，袖扣内部的红绿火彩便如火焰般跳跃闪耀，哪怕穿着破旧的礼服，也能让旁人对你的来历肃然起敬。",
        en = "A pair of polished gold cufflinks holding dome-shaped iridescent opals. Flashing fiery colors with every wrist motion, they lend majestic aristocratic distinction to whichever lucky survivor finds and wears them with confidence.",
    },
    ["opal_gold_earring"] = {
        zh = "一对由纯金爪镶固定彩虹蛋白石的华美垂坠耳环。光线穿透石体泛出迷离的晨曦色泽，在暗沉的地下避难所中，它们就像两团悬挂在耳畔的跳跃微型彩虹，带来无尽欢欣。",
        en = "A pair of gold drop earrings securing radiant opals inside delicate claw settings. Scattering kaleidoscopic flashes through dim bunker shadows, they brighten the gloom with vibrant reflections that recall forgotten pre-war dawns.",
    },
    ["opal_gold_pendant_necklace"] = {
        zh = "由一条做工细腻的金项链挂载一颗硕大变彩蛋白石吊坠的梦幻首饰。欧珀石内部变幻莫测的色彩宛如被封印在水晶中的极光，美得摄人心魄，是送给心爱之人的无价礼物。",
        en = "A fine gold chain bearing a large, fire-filled opal pendant. Shimmering like trapped northern aurora borealis against your chest, this breathtaking treasure makes a poignant, unforgettable romantic gift in a dark, uncertain era.",
    },
    ["opal_gold_ring"] = {
        zh = "一枚在厚重纯金戒托上高耸镶嵌椭圆多彩蛋白石的华贵戒指。转动角度即可观赏到如同深海珊瑚般的斑斓光彩，戴在指间不仅赏心悦目，更是废土上象征滔天财力的至尊信物。",
        en = "A statement ring featuring a plump oval opal mounted atop a substantial gold shank. Shifting through kaleidoscopic turquoise and crimson hues, it serves as an unmistakable token of immense personal wealth across frontier towns.",
    },
    ["opal_gold_tiara"] = {
        zh = "由纯金精心打造、前冠簇拥镶嵌多颗璀璨蛋白石的奢华头冠。金黄冠冕流光溢彩，欧珀石在烛光下如漫天繁星般闪烁变幻，将佩戴者衬托得宛如神话中降临荒原的晨曦女神。",
        en = "A breathtaking royal tiara forged in pure gold and crowned with luminous iridescent opals. Blazing with celestial rainbow fire under torchlight, it transforms its wearer into an unearthly queen commanding respect across lawless territories.",
    },
    ["opal_platinum_bracelet"] = {
        zh = "采用坚硬沉重的高档铂金链扣、镶嵌多颗通透幻彩蛋白石的高贵手镯。铂金的冰清玉洁完美烘托出欧珀石梦幻空灵的色泽，沉甸甸的手感彰显出旧世界无与伦比的顶级珠宝工艺。",
        en = "A hefty platinum link bracelet showcasing a line of pristine, color-shifting opals. The mirror-bright platinum sets off the stones' iridescent blues and pinks, embodying peak pre-cataclysm metallurgical luxury for collectors.",
    },
    ["opal_platinum_cufflinks"] = {
        zh = "一对以铂金冷艳包边镶嵌七彩闪烁蛋白石的顶级袖扣。材质坚固永不磨损褪色，内部游彩如夜空闪电般变幻无常，佩戴在西装袖口上，将低调与极尽奢靡融合到了极致。",
        en = "A set of immaculate platinum cufflinks framing circular rainbow opals. Completely impervious to tarnishing in muddy trenches, their prismatic fire adds unmistakable grandeur to whoever dares maintain pre-war tailoring standards.",
    },
    ["opal_platinum_earring"] = {
        zh = "一对由铂金精工包镶水滴形变彩蛋白石的高贵耳环。银白的冷峻与蛋白石内部绚烂的火彩产生奇妙共鸣，悬垂在耳垂下方，宛如将两滴凝固的极光水珠挂在身旁，动人心弦。",
        en = "A pair of platinum drop earrings cradling vibrant teardrop opals. The juxtaposition of frosty platinum and pulsing internal color flashes transforms these delicate earrings into miniature droplets of captured planetary auroras.",
    },
    ["opal_platinum_pendant_necklace"] = {
        zh = "由一条坚韧冰冷的纯铂金链条串起一枚高品质幻彩蛋白石吊坠的项链。铂金的强韧与欧珀石的娇贵形成鲜明反差，戴在胸前无论走到哪里都是令人无法移开视线的视觉焦点。",
        en = "An enduring platinum chain suspending a magnificent freeform opal cabochon. Combining unyielding metallic strength with ethereal rainbow light, it serves as an enchanting talisman that stands out brilliantly against rugged combat armor.",
    },
    ["opal_platinum_ring"] = {
        zh = "用整块高纯度工业铂金数控切削戒圈、中心稳固抓镶一颗多彩蛋白石的现代戒指。结构紧凑结实，欧珀石的光芒如星云流转，是末日世界中集顶级硬度与梦幻美感于一身的绝品。",
        en = "A modern platinum band securing a vibrant iridescent opal inside precision prongs. Exceptionally durable and immune to corrosion, this futuristic piece of jewelry merges supreme structural integrity with breathtaking optical elegance.",
    },
    ["opal_platinum_tiara"] = {
        zh = "以高熔点铂金为主体骨架、环绕镶嵌大颗星彩蛋白石的冰霜王冠。全冠散发着月华般的高贵冷光与如梦似幻的七彩游彩，宛如冰雪王国女王的至高冠冕，美得令人窒息敬畏。",
        en = "An awe-inspiring platinum tiara crested with radiant color-play opals. Shimmering with glacial white luster and vibrant prismatic flashes, it resembles an enchanted frost-queen crown, inspiring awe across superstitious survivors.",
    },
    ["opal_silver_bracelet"] = {
        zh = "用九二五纯银编织成细腻链纹、点缀镶嵌数枚七彩蛋白石的手镯。银光的柔和完美烘托出欧珀石内部的游彩，价格虽然没有黄金昂贵，但清新脱俗的气质深受避难所少女的喜爱。",
        en = "A delicate sterling silver bracelet linking a procession of shimmering opals. The soft cool silver harmonizes gently with each stone's shifting pastel colors, providing subtle yet undeniable charm in a grim wasteland.",
    },
    ["opal_silver_cufflinks"] = {
        zh = "一对采用经典纯银包镶蛋白石的正装袖扣。银质边框经过细致抛光，欧珀石在自然光下展现出静谧的淡蓝与浅绿色泽，在粗犷的末日流浪生活中保留着难能可贵的文雅绅士风度。",
        en = "A pair of polished silver cufflinks centering translucent opals. Exhibiting calm azure and mint-green flashes, wearing them in a gritty survivor enclave preserves a charming, resilient touch of classic gentlemanly refinement.",
    },
    ["opal_silver_earring"] = {
        zh = "一对用纯银丝手工绕制抓托、悬挂彩虹蛋白石小珠的优雅耳环。随风摇曳时耳畔波光粼粼，如同一汪清澈的彩虹泉水，给满目焦黑的辐射废土带来一缕令人心旷神怡的温柔生机。",
        en = "A pair of handmade sterling silver drop earrings clutching vibrant round opals. Swaying softly in toxic breezes, their lively iridescence introduces a welcome splash of color into an otherwise bleak monochrome wasteland.",
    },
    ["opal_silver_pendant_necklace"] = {
        zh = "由做工精良的纯银锁骨链悬挂一枚卵形蛋白石吊坠的唯美项链。银色边框雕刻着复古藤蔓花纹，中心蛋白石转动间幻彩四溢，是废墟探险中能让疲倦心灵瞬间得到治愈的精致宝物。",
        en = "A vintage silver necklace featuring an oval-cut opal nestled within intricate leafy filigree. Shifting through dreamy lavender and sea-green hues, this sentimental heirloom provides comforting solace during lonely nights in the bunker.",
    },
    ["opal_silver_ring"] = {
        zh = "一枚在素雅纯银戒圈上镶嵌单颗椭圆多彩蛋白石的清新戒指。没有多余的浮夸装饰，唯有欧珀石在阳光下静静变换着绚丽光泽，佩戴在手指上显得干净利落且充满生命力。",
        en = "A sleek sterling silver ring crowned by a single iridescent opal stone. Free of ostentatious ornamentation, the pure purity of silver lets the gemstone's shifting spectral colors shine with understated, captivating vitality.",
    },
    ["opal_silver_tiara"] = {
        zh = "用纯银手工敲打打磨出优雅弧度、中央与两侧点缀多彩蛋白石的轻便小银冠。如同森林童话中微风吹拂的月影，虽然没有黄金王冠那般沉重耀眼，却别具一种清新灵动的浪漫仙气。",
        en = "A gracefully hammered silver tiara studded with an arrangement of colorful opals. Light on the brow yet mesmerizingly bright, it crowns the head with an ethereal, fairytale aura that defies the brutal surrounding apocalypse.",
    },
    ["openfire"] = {
        zh = "一套以指挥装甲排为主题的单人硬核战术战棋桌游。玩家独自在推演地图上遭遇突发事件并指挥钢铁洪流，在缺少同伴的末日长夜里，推演一场虚拟坦克战能极好地排遣漫长孤寂。",
        en = "A tactical solitaire wargame putting players in command of an armored tank platoon across scripted combat scenarios. Pushing cardboard panzers through simulated engagements offers absorbing intellectual escape during solitary wasteland nights.",
    },
    ["optical_cloak"] = {
        zh = "密布微型摄像头与高亮发光二极管的尖端高科技光学隐身披风。目前处于关闭断电状态，只要随身携带统一电源为其通电，就能让你的身体在肉眼前完全隐形，是潜行摸哨的终极神装。",
        en = "An advanced optical camouflage mantle embedded with micro-cameras and adaptive LED arrays. Currently powered down, connecting it to a unified power supply bends ambient light around your frame, rendering you completely invisible.",
    },
    ["optical_cloak_on"] = {
        zh = "正在全力运转、正以惊人速度吞噬统一电源电量的光学隐身披风。身周空气微微扭曲，完美抹去了所有光影轮廓，即使大摇大摆从丧尸跟前走过，对方也只会把微风当成错觉。",
        en = "An active optical cloak humming quietly as it voraciously drains unified battery cells. Projecting dynamic camouflage across its surface, it allows survivors to stroll right past oblivious zombie sentries unseen.",
    },
    ["orange"] = {
        zh = "一颗表皮金黄饱满、散发着清爽柑橘甘甜清香的新鲜甜橙。咬破薄皮瞬间汁水四溢，天然维生素与果糖在舌尖跳跃，在这片被尘土与腐朽充斥的废土上，它是滋润干裂嘴唇的无价珍果。",
        en = "A ripe, fragrant sweet orange bursting with bright citrus juice. Offering sweet hydration and a potent dose of natural Vitamin C, peeling this sun-kissed fruit provides pure, invigorating morale against dreary post-apocalyptic rot.",
    },
    ["orangeade"] = {
        zh = "装在廉价塑料瓶里的人工合成橙味果汁饮料。虽然几乎不含真正的天然果汁，但人工甜味剂与明亮橙色依然能给疲惫的旅人带来大口吞咽的痛快，是废土行军时解渴的甜水伴侣。",
        en = "A budget-friendly bottled beverage delivering artificial orange flavoring and a modest dash of vitamins. While largely synthetic syrup and water, its sugary sweetness reliably quenches parched throats during scorching overland marches.",
    },
    ["orangeade_powder"] = {
        zh = "一整包密封防潮的亮橙色速溶甜橙冲饮粉。只需用勺子舀入冷水中轻轻搅拌，便能瞬间化作一大壶甜酸适口的橙汁饮品，轻巧耐存放，是背包长途跋涉时携带维生素的极佳方式。",
        en = "A foil packet of bright orange drink crystals sealed against moisture. Stirring a generous spoonful into canteens yields a refreshing pitcher of sweet citrus hydration, packing lightweight flavor for arduous expeditions.",
    },
    ["orangesoda"] = {
        zh = "一罐未开封的经典易拉罐装高糖橙味碳酸汽水。拉开拉环瞬间二氧化碳伴随着甜香喷薄而出，虽然没有咖啡因提神，但那股刺激味蕾的气泡感能让人彻底忘却现实的残酷生存重压。",
        en = "An unopened can of effervescent, neon-orange carbonated soda. Free of caffeine yet loaded with bubbly corn syrup, popping the tab delivers a nostalgic rush of carbonation that lifts gloomy wasteland spirits.",
    },
    ["othello"] = {
        zh = "装有双面黑白棋子与八乘八棋盘的标准黑白翻转棋盒装桌游。规则简单易学但布局博大精深，一步落子即可翻转整行战局，是避难所同伴之间进行脑力博弈与消磨无聊时光的经典游戏。",
        en = "A classic boxed set of Reversi containing an eight-by-eight grid and reversible black-and-white disc tokens. Simple to learn yet intensely strategic, capturing rows of enemy pieces provides friendly rivalry in survival bunkers.",
    },
    ["ouija"] = {
        zh = "刻有二十六个字母、数字与占写游标的神秘实木通灵板。在遍地徘徊真实不死亡灵的末日废土，用它试图与幽灵对话显得有些荒诞，但偶尔也能引出某些来自空间裂隙的不速之客。",
        en = "An antique wooden Ouija board complete with an alphabet layout, numbers, and sliding heart-shaped planchette. Attempting to converse with restless spirits feels redundant amidst roaming undead herds, though occasionally other planar entities reply.",
    },
    ["outfit_storage"] = {
        zh = "包含便携挂衣杆、防皱夹板与防尘袋的精巧衣物收纳小套件。能将整套备用战斗服或换洗衣物妥善压平保存，只需与其交互便能一键换上一身清爽体面服装，告别满身血污泥泞。",
        en = "A compact garment organizer incorporating folding hangers, compression straps, and dust covers. Keeping a spare ensemble clean and wrinkle-free, interacting with it instantly swaps bloody armor for a tidy civilian change.",
    },
    ["outsert_breach"] = {
        zh = "卡扣在防毒面具目镜外侧的加固型防爆突击外置镜片。采用抗冲击聚碳酸酯打造，能有效抵挡霰弹破片与飞溅碎石的直击，保护脆弱的目镜不至于在破门交火中碎裂。",
        en = "Heavy polycarbonate protective lenses snapping over standard gas mask visors. Built to withstand shotgun pellets and gravel splinters, they protect your essential eyepieces during violent door-breach gun battles.",
    },
    ["outsert_clear"] = {
        zh = "采用高透光防弹聚碳酸酯制成的全景防毒面具外置透明保护镜片。直接卡在面罩主视窗外部，能有效阻挡碎石刮擦、酸液溅射与飞散破片，确保在激烈交火中视界始终清晰无阻。",
        en = "A tough polycarbonate protective outer lens designed to snap over panoramic gas mask viewports. Absorbing scratches, chemical splatter, and flying grit, it preserves pristine vision through toxic firefights without sacrificing visibility.",
    },
    ["outsert_sunlight"] = {
        zh = "带有深色偏光镀膜的防毒面具遮阳外置滤镜。在艳阳高照的雪原或强光照射下能极大缓解强光眩目，防止你在被闪光手雷或者烈日强光晃瞎双眼时沦为丧尸的美餐。",
        en = "Dark polarized outsert lenses designed to fit securely over respirator faceplates. Cutting harsh glare across sunlit snowfields, they prevent blinding light from leaving you helpless during daylight patrols.",
    },
    ["oven"] = {
        zh = "一台原本属于现代厨房的大型对流式不锈钢电烤箱。目前未接入电源，只要将其固定在重型房车生活区并连接电网，它就能让你在废土营地烘烤出香气扑鼻的松软面包与烤全羊。",
        en = "A heavy stainless-steel convection oven salvaged from a suburban kitchen. Completely dormant until wired into a vehicle power grid or generator bank, it transforms scavenged dough and butchered meats into glorious roasted feasts.",
    },
    ["oven_broiler_pan"] = {
        zh = "放置在烤箱底部的带槽金属拉出式烤肉沥油盘。坚硬的铁皮经得起炭火与高温烘烤，在野外露营时直接架在明火营火上，也能充当一面出色的平底铁板煎烤变异兽肉排。",
        en = "A heavy stamped sheet-metal broiler pan salvaged from the base of an electric oven. Designed with drainage slots to catch dripping grease, it doubles as an excellent griddle when laid directly across campfire coals.",
    },
    ["oven_cabinet"] = {
        zh = "电烤箱被拆空内部电气元件后遗留下的重型厚钢板外壳框架。结构沉重稳固且具备耐火夹层，既能在工作台上进一步拆解成优质废铁板，也可以在避难所入口充当临时的防弹掩体。",
        en = "A stripped, hollow steel chassis that previously housed an electric kitchen range. Retaining its rigid sheet-metal construction and heat insulation, it can be dismantled for flat plate or stacked into heavy perimeter barricades.",
    },
    ["oven_controls"] = {
        zh = "从高档电烤箱上完整拆卸下的微电脑控制面板与液晶显示屏组件。内含温控继电器、旋钮电位器与微处理器，是电子工坊维修高精度温控设备或改装自制恒温箱的宝贵电子零配件。",
        en = "The digital control module and LCD interface removed from an electric oven. Loaded with temperature sensors, dials, and printed logic boards, it offers prime electronic scrap for crafting custom laboratory incubators and smart heaters.",
    },
    ["oven_door"] = {
        zh = "从电烤箱上拆除下的带有防爆耐高温双层钢化玻璃的重型钢门。带有坚固的隔热拉手与铰链，在野外甚至可以当作一块自带观察视窗的单兵防暴防弹盾牌，抵御行尸抓挠与咬击。",
        en = "A reinforced oven door composed of heavy steel framing and thick double-paned tempered glass. Complete with an insulated handle, desperate scavengers can wield this insulated slab as a heavy improvised ballistic riot shield.",
    },
    ["oven_stovetop"] = {
        zh = "从电烤箱顶部完整拆解下的电炉灶面板。平整的黑色耐热微晶玻璃板上带有环形电热丝线圈，拆下电热丝可制作电烙铁或简易发热垫，坚硬的玻璃板则是手工打磨台的平整垫板。",
        en = "The dismantled top heating surface of an electric kitchen range. Its smooth glass-ceramic panel and coiled resistive heating elements can be salvaged for soldering tools, heating elements, or improvised flat work surfaces.",
    },
    ["oxy_powder"] = {
        zh = "一罐高纯度的强氧化剂化学白色粉末。在工坊化学台上是调配自制高能火箭推进剂、强效爆破火药或紧急供氧烛的核心原料，使用时必须严防明火静电，否则瞬间便会引发剧烈爆燃。",
        en = "A sealed canister of volatile white chemical oxidizer powder. Essential for compounding homemade rocket propellants, energetic blasting charges, or emergency chlorate oxygen candles, handling it demands extreme caution around stray sparks.",
    },
    ["oxy_torch"] = {
        zh = "一套手持式工业级氧乙炔切割与气焊枪组件。连接氧气瓶与乙炔气瓶点燃，炽白刺眼的聚焦火焰温度高达数千度，能在短短几秒内将坚固的银行金库铁门与重型装甲车残骸切成两半。",
        en = "A compact oxyacetylene cutting and welding torch assembly. Channeling pressurized gases into a blinding pinpoint flame exceeding thousands of degrees, it slices through hardened vault doors and armored hulls like warm butter.",
    },
    ["oxyacetylene"] = {
        zh = "充装在高压特种储罐中的高浓度易燃易爆乙炔气体。与纯氧混合点燃能释放出惊人的极致高温，是工坊切割厚重渗碳钢板不可替代的工业气体，也是末日改装重型战车的破拆法宝。",
        en = "Compressed, highly unstable acetylene gas stored inside dedicated safety cylinders. Mixed with pure oxygen for industrial torchwork, it produces superheated flames capable of fabricating robust vehicular armor plates.",
    },
    ["oxycodone"] = {
        zh = "一瓶属于阿片类强效中枢镇痛药的羟考酮药片。吞下一粒便能彻底麻痹神经、驱散粉碎性骨折带来的撕心裂肺剧痛，但其强烈的成瘾性极高，清醒的废土幸存者不到濒死关头绝不轻易服用。",
        en = "A bottle of potent semi-synthetic opioid pain relief tablets. Dulling catastrophic trauma and unbearable fractures, it keeps critically wounded survivors functional, though its intense addictive properties demand strict medical discipline.",
    },
    ["oxygen"] = {
        zh = "以极高压力密封在气瓶中的高纯度医用与工业级氧气。在密封地下防核避难所空气耗尽时是抢救窒息伤员的生命源泉，而在工坊气焊台上则是激发电焊火焰爆发出数千度高温的助燃灵魂。",
        en = "High-purity compressed oxygen gas held under intense pressure. Indispensable for resuscitating suffocating companions inside sealed airless bunkers, it also supercharges industrial torches to melt refractory metals in the workshop.",
    },
    ["oxygen_concentrator"] = {
        zh = "利用沸石分子筛物理吸附技术从空气中源源不断富集高纯氧气的便携式电动制氧机。只要有持续电源输入，就能为患有严重肺部感染与哮喘的重病幸存者提供无尽的生命支撑新鲜氧流。",
        en = "A motorized medical unit that utilizes molecular sieve beds to concentrate pure oxygen directly from ambient air. Connected to electricity, it supplies continuous therapeutic oxygen flows, sustaining survivors suffering from acute pulmonary trauma.",
    },
    ["oxygen_cylinder"] = {
        zh = "漆着亮白色警示防锈漆的沉重加厚高压钢制氧气钢瓶。瓶身极为结实耐压，能安全存储数百升压缩纯氧，在深入充满致命氯气与剧毒神经毒雾的废弃化工厂前，必须备足它的储气量。",
        en = "A heavy-duty steel cylinder painted white and built to withstand massive internal pressures. Storing compressed gas reserves, it guarantees hours of reliable life support when delving into poisonous chemical ruins.",
    },
    ["oxygen_tank"] = {
        zh = "由小型便携铝合金氧气瓶、精密调压阀与医用硅胶呼吸面罩组成的整套应急输氧套装。背在身上轻便随行，在遭遇有毒瓦斯泄漏或烟雾窒息的生死关头，扣上面罩深吸一口即可瞬间清醒脱险。",
        en = "A portable oxygen kit complete with an aluminum cylinder, precision pressure regulator, and clear medical face mask. Lightweight and rapid to deploy, breathing from it clears smoke-choked lungs during fiery structural escapes.",
    },
    ["oxylamp"] = {
        zh = "一盏由高压乙炔气瓶供能的复古重型黄铜工矿照明灯。目前处于关闭状态，点燃后能发出穿透浓厚瓦斯迷雾的刺目雪白强光，在漆黑危险的深层地下矿井与地铁隧道中是极佳的探索灯具。",
        en = "An antique brass carbide lantern designed to burn pressurized acetylene fuel. Currently turned off, igniting its burner produces brilliant incandescent white illumination that cuts through thick subterranean dust clouds.",
    },
    ["oxylamp_on"] = {
        zh = "正在剧烈燃烧喷射出刺眼炫目白色烈焰的黄铜乙炔灯。光芒炽烈得近乎无法直视，照耀范围远超普通煤油灯，在地下防空洞最阴暗的角落，它驱散了所有潜藏在死角里的不可名状阴影。",
        en = "A glowing brass acetylene lamp hissing loudly as it consumes pressurized gas. Projecting intense daylight-bright rays across ruined subway tunnels, its searing glare forces subterranean creeping horrors back into dark corners.",
    },
    ["oyster"] = {
        zh = "在未受核辐射严重污染的浅海岩礁上采集到的一只紧闭厚重硬壳的生鲜牡蛎。用短刀撬开坚固贝壳，里面的蚝肉晶莹剔透并浸泡在海水咸鲜的原汁中，是一口令人回味无穷的海洋天然珍馐。",
        en = "A wild saltwater oyster sealed tightly within its rugged calcareous shell. Prying it open with a sturdy knife reveals succulent meat brimming with briny liquor, delivering pure ocean flavors to landlocked apocalypse wanderers.",
    },
    ["oyster_crackers"] = {
        zh = "一整袋一口一个的小巧六角形酥脆牡蛎咸饼干。烘烤得干爽金黄，丢入热气腾腾的浓稠海鲜杂烩汤或碎肉罐头汤里，吸饱了鲜美汤汁后软糯咸香，是安抚空虚肠胃的经典主食配料。",
        en = "A bag of bite-sized hexagonal salted crackers baked to a crisp golden crunch. Dropped into piping hot clam chowders or savory meat broths, they soak up rich gravy, turning thin scavenged soups into hearty meals.",
    },
    ["oyster_shucked"] = {
        zh = "已经利落撬去坚硬上壳、浸润在天然咸鲜汁水中的新鲜肥美牡蛎肉。肉质滑嫩饱满且富含高吸收率的锌与优质蛋白，直接滑入口中吞下，那股纯粹的海风甘甜能瞬间抚平身心的疲惫。",
        en = "A freshly shucked raw oyster resting in its natural salty ocean liquor. Rich in zinc and essential proteins, slipping the cold succulent morsel down your throat delivers an invigorating wave of oceanic vitality.",
    },
    ["p08"] = {
        zh = "一战与二战德国军用经典的鲁格P08九毫米半自动手枪。标志性的肘节式起落枪机在击发时宛如精密的机械瑞士手表，握把指向性极佳，兼具绝佳的射击手感与无可替代的军械收藏价值。",
        en = "The legendary toggle-lock Luger P08 pistol chambered in 9x19mm. Featuring an unmistakable mechanical articulation reminiscent of fine clockwork, this historic firearm combines crisp trigger pulls with iconic European craftsmanship.",
    },
    ["p08mag_32rd"] = {
        zh = "专为鲁格P08手枪与炮兵型卡宾枪配发的一战原产三十二发重型蜗式弹鼓。沉重且上弹繁琐，虽然结构精密容易受泥沙影响供弹，但整整三十二发九毫米子弹连续倾泻的火力极其骇人。",
        en = "A cumbersome 32-round snail-drum magazine originally issued for artillery model Luger pistols. While awkward to reload and sensitive to wasteland grit, unleashing thirty-two consecutive rounds provides terrifying close-quarters suppressing fire.",
    },
    ["p08mag_8rd"] = {
        zh = "鲁格P08手枪的标准八发单排冲压钢制弹匣。底部带有经典的木质或电木抓握托块，装弹行程顺滑，八颗九毫米鲁格手枪弹在手枪机匣内精准咬合，是这把古董名枪可靠击发的心脏。",
        en = "A standard eight-round steel box magazine designed for the Luger P08. Featuring traditional wooden baseplugs and smooth spring tension, it feeds 9mm cartridges reliably into the chamber of this historic German sidearm.",
    },
    ["p220_10"] = {
        zh = "西格绍尔专为狩猎与防卫打造的十毫米大口径P220全金属重型半自动手枪。发射威力狂暴的点四零马格南级重弹，枪机做工严丝合缝，近距离扣动扳机能将变异暴熊的坚硬头盖骨轰成碎渣。",
        en = "A rugged full-metal combat handgun chambered in the ferocious 10mm Auto cartridge. Built with legendary Swiss-German tolerances, its thunderous terminal ballistics easily crack the skulls of charging mutated predators.",
    },
    ["p220_10_mag"] = {
        zh = "为十毫米口径西格P220重型手枪配发的八发单排不锈钢弹匣。加粗的特种托弹簧与坚固的防跌落底座，确保八发狂暴大威力十毫米弹药在恶劣泥水浸泡后依然能分秒不差精准供弹。",
        en = "An eight-round stainless steel box magazine engineered for the 10mm SIG P220. With heavy-duty spring tension keeping high-pressure cartridges properly aligned, it guarantees flawless feeding during desperate defensive encounters.",
    },
    ["p226_357sig"] = {
        zh = "发射三五七西格高速瓶颈瓶形重弹的高性能P226战斗手枪。弹道平直且初速高得惊人，兼具九毫米的穿透速度与三五七左轮的狂暴制止力，是废土特工清理防弹衣劫匪的破甲神兵。",
        en = "A tactical P226 pistol chambered in high-velocity .357 SIG bottleneck cartridges. Combining screaming projectile speed with devastating hydrostatic shock, it pierces improvised raider body armor with devastating efficiency.",
    },
    ["p226_9mm"] = {
        zh = "经过军方特种耐腐蚀磷化表面处理的海豹突击队MK25定制版P226手枪。全钢套筒配铝合金底把，在盐雾与泥沼浸泡中永不卡壳，是无数特战精英在末日极端环境下最信任的随身佩枪。",
        en = "The military-issue MK25 variant of the SIG P226, favored by Navy SEALs. Featuring corrosion-resistant internal coatings and uncompromising reliability, it discharges nine-millimeter rounds smoothly even after being dredged from stagnant swamp mud.",
    },
    ["p226mag_10rd_9x19mm"] = {
        zh = "符合战前某些民用法律限弹限制的十发容量P226九毫米手枪弹匣。虽然装弹量稍逊于军用大容量版，但紧凑的冲压钢制外壳结构皮实坚固，用来作为巡逻备用副弹匣极其便携保险。",
        en = "A restricted ten-round double-stack magazine manufactured for civilian P226 owners. Built with durable blued steel and stiff springs, it provides a dependable, compact secondary ammunition reserve for scouts patrolling quiet perimeter sectors.",
    },
    ["p226mag_12rd_357sig"] = {
        zh = "为三五七西格口径P226手枪量身打造的十二发双排钢制供弹匣。十二枚修长的高速穿甲弹药在弹匣内整齐排列，扣住扳机连续速射能以狂暴的枪口动能将前方的丧尸群尽数轰退。",
        en = "A twelve-round double-stack steel magazine feeding .357 SIG ammunition into P226 handguns. Maintaining tight retention on bottlenecked rounds, it delivers furious rapid-fire kinetic stopping power against encroaching ghouls.",
    },
    ["p226mag_15rd_9x19mm"] = {
        zh = "西格P226手枪最经典的军警制式十五发标准九毫米双排供弹匣。弹簧张力均匀且防跌落性能优异，整整十五发子弹的充沛备弹量，足以让特警与末日枪手在激烈的近战遭遇战中从容应对。",
        en = "The standard military-issue fifteen-round double-stack magazine for the 9mm P226. Renowned for flawless feeding and rugged steel durability, carrying several in tactical pouches ensures ample ammunition during brutal close-quarters firefights.",
    },
    ["p228mag_13rd_9x19mm"] = {
        zh = "为美军代号M11的紧凑型西格P228手枪配发的热处理钢制十三发弹匣。紧凑的弹匣长度兼顾了隐蔽携行与充足火力，扣在腰间手枪套内拔枪速射，是近战防身与狭小空间自卫的利器。",
        en = "A thirteen-round steel magazine manufactured for the compact SIG P228, designated M11 in military service. Balancing compact concealment with generous firepower, it feeds rapid point-blank double-taps cleanly.",
    },
    ["p320_357sig"] = {
        zh = "采用模块化击针平移式击发系统、发射三五七西格重弹的P320紧凑型战斗手枪。扳机行程清脆利落，模块化握把极易贴合手形，大威力的瓶颈弹赋予了它对抗变异防弹护甲的骇人威力。",
        en = "A striker-fired modular P320 Compact pistol chambered in powerful .357 SIG. Boasting a crisp trigger break and interchangeable grip ergonomics, this modern handgun punches high-velocity rounds cleanly through thick mutant hides.",
    },
    ["p320mag_10rd_9x19mm"] = {
        zh = "美军新一代制式军用手枪P320紧凑型的十发装填耐磨钢制供弹匣。外表经过抗腐蚀涂层处理，虽然弹容量受到压低，但极短的外壳便于在紧身隐蔽携行枪套中实现快速隐秘出枪。",
        en = "A ten-round steel magazine designed for civilian and compact configurations of the service P320 handgun. Its shortened profile avoids printing beneath survival jackets while reliably chambering nine-millimeter rounds.",
    },
    ["p320mag_13rd_357sig"] = {
        zh = "专为三五七西格口径P320紧凑手枪研发的十三发原厂双排弹匣。内部经过低摩擦处理，十三发狂暴弹药在弹匣内整齐推挤，在遭遇凶狠变异野兽扑击时能在两秒内打出致命的金属风暴。",
        en = "A thirteen-round steel magazine optimized for .357 SIG variants of the P320. Slick low-friction follower geometry ensures instant feeding, delivering a continuous stream of punishing kinetic energy into charging mutants.",
    },
    ["p320mag_17rd_9x19mm"] = {
        zh = "美军全尺寸新一代制式M17手枪的标准十七发双排耐磨钢弹匣。十七发九毫米弹药提供了令人安心的火力持续性，底托坚固耐摔，在剧烈战术换弹砸在水泥地面上时依然毫发无损。",
        en = "The standard seventeen-round service magazine issued with full-size military M17 and P320 pistols. Holding a generous load of nine-millimeter cartridges, its durable polymer baseplate withstands hard tactical drops onto concrete.",
    },
    ["p320mag_21rd_9x19mm"] = {
        zh = "为美军制式手枪配发的高容量加长二十一发扩容弹匣。伸出手柄底部的加长弹匣不仅提供了犹如冲锋枪般的持续压制火力，在遭遇被行尸潮包围的绝境时更是绝地逢生的火力顶梁柱。",
        en = "An extended twenty-one round high-capacity magazine developed for the United States service handgun. Extending slightly beyond the magwell, this elongated reservoir transforms sidearms into sustained-fire bullet hoses during desperate retreats.",
    },
    ["p365"] = {
        zh = "以极其纤薄微型体积极致容纳十发九毫米子弹的P365高科技便携自卫手枪。外形轻巧得能塞进牛仔裤口袋，但射击精度与后坐力控制极其优秀，是废土拾荒者最隐蔽贴身的防身底牌。",
        en = "A micro-compact 9mm pistol engineered for comfortable concealed carry without sacrificing ammunition capacity. Fitting smoothly inside lightweight vest pockets, its sharp sight picture and manageable recoil deliver instant self-defense.",
    },
    ["p365_mag"] = {
        zh = "采用专利倾斜双排收窄技术的P365微型手枪十发钢制弹匣。在惊人狭小的空间内塞入了整整十发九毫米弹药，做工精密，是每一位追求极致隐蔽战术射手梦寐以求的供弹奇迹。",
        en = "A compact ten-round steel magazine utilizing patented necked-down geometry for the P365 micro-pistol. It crams remarkable firepower into a minuscule footprint, ensuring reliable chambering whenever trouble strikes unexpectedly.",
    },
    ["p38mag"] = {
        zh = "二战经典瓦尔特P38双动半自动手枪的原装八发冲压钢弹匣。侧面开有方便观察剩余弹药的检查孔，弹簧强韧有力，八颗子弹依次推入枪膛，见证了半个多世纪枪械工业的经典传承。",
        en = "An authentic eight-round steel magazine designed for the historic Walther P38 military sidearm. Featuring classic side inspection slots and a heavy follower spring, it feeds vintage 9mm rounds with steadfast mechanical precision.",
    },
    ["p_carpet"] = {
        zh = "一大卷质感柔软厚实、色泽典雅高贵的深紫色羊毛混纺地毯。铺在避难所冰冷潮湿的水泥地面上，不仅能阻隔地底刺骨的湿寒，那抹亮丽的紫色更能让阴暗的地窖瞬间焕发出皇家般的奢华。",
        en = "A bulky roll of plush wool-blend carpet dyed in royal purple. Rolling it across damp subterranean bunker floors insulates boots against freezing drafts while introducing extravagant vibrant color into dreary post-apocalyptic shelters.",
    },
    ["paddle_plastic"] = {
        zh = "采用轻便高韧性工程塑料注塑成型的紧凑型小塑料桨。在划着充气橡皮艇穿越废弃水库时轻便好使，在近身被行尸贴脸时抡起来重重扇在怪物脸上，也能打得对方皮开肉绽失去平衡。",
        en = "A lightweight molded plastic paddle featuring a sturdy shaft and ribbed blade. While ideal for maneuvering small dinghies across flooded ruins, swinging it two-handed delivers a resounding crack against aggressive zombie skulls.",
    },
    ["paella_valenciana"] = {
        zh = "在大号浅口铁锅中用藏红花金黄肉汤精心煨煮出的正宗巴伦西亚大锅饭。金黄米粒吸透了兔肉、鸡肉与豆子的浓郁汤汁，底部焦香的锅巴酥脆诱人，是一顿足以让整个营地欢呼的丰盛盛宴。",
        en = "A magnificent pan of traditional Spanish paella infused with fragrant saffron broth, tender rabbit, chicken, and beans. The crunchy caramelized rice crust on the bottom provides exquisite umami that turns dinners into celebrations.",
    },
    ["paint_black"] = {
        zh = "一罐高遮盖力的深黑哑光工业油漆。涂刷在防暴盾牌、改装战车或侦查望远镜上能彻底消除金属反光，在黑夜潜行摸哨前把装备全涂成漆黑，能让你彻底化身为与阴影合二为一的暗夜幽灵。",
