    ["pandemic"] = {
        zh = "一套以阻止全球致命病毒蔓延为主题的经典硬核合作桌面游戏。围坐在摇曳烛火旁推演各洲疫情爆发，看着棋盘上迅速扩散的红色感染方块，回想起窗外真实的生化噩梦，让人倍感荒诞与唏嘘。",
        en = "An acclaimed cooperative board game challenging players to contain catastrophic global viral pandemics. Pushing plastic outbreak markers across the map by candlelight feels surreal when civilization outside was eradicated by literal biological abominations.",
    },
    ["panoramic_eyepiece"] = {
        zh = "采用耐化学腐蚀与高抗冲击聚碳酸酯制成的一体化全景护目镜片。超宽弧形视野完全消除了左右观察死角，安装在战术防毒面具上，能让佩戴者在复杂毒雾火场中始终洞察四周敌情。",
        en = "A broad panoramic lens molded from chemical-resistant ballistic polycarbonate. Snapping securely into tactical respirator facepieces, its seamless curved geometry eliminates tunnel vision, giving scouts uninterrupted peripheral awareness in smoky ruins.",
    },
    ["panties"] = {
        zh = "一条裁剪柔软舒适、透气排汗的纯棉女式贴身内裤。虽然在末日废土上提供不了任何防弹防砍护甲，但保持贴身私处的干爽洁净，是对抗严重皮肤湿疹与维持基本个人尊严的必要防线。",
        en = "A simple pair of soft, breathable cotton underwear. Offering zero protection against claws or bullets, keeping dry hygienic undergarments packed in your rucksack prevents debilitating friction chafing during long wilderness forced marches.",
    },
    ["pants"] = {
        zh = "一条面料挺括、带有两个斜插口袋的经典卡其色休闲长裤。比普通粗斜纹牛仔裤更加保暖且透气性适中，穿在身上干练得体，在城市废墟搜刮物资或避难所日常工作时都格外合身实用。",
        en = "A pair of durable khaki trousers woven from heavy cotton twill. Warmer than lightweight jeans and offering comfortable breathability, they provide practical everyday leg wear for clearing debris and running survival camp errands.",
    },
    ["pants_army"] = {
        zh = "采用防撕裂混纺面料缝制的军用迷彩长裤。大腿两侧带有大容量风琴风雨口袋，耐磨耐脏且防风防刺，是所有长期在废墟瓦砾与带刺铁丝网中摸爬滚打的幸存者首选。",
        en = "Ripstop cargo trousers patterned in standard military camouflage. Fitted with cavernous thigh pockets, their reinforced stitching endures endless crawling across broken concrete and tangled razor wire intact.",
    },
    ["pants_cargo"] = {
        zh = "裤腿两侧缝有整整六个大容量风琴折叠口袋的经典多袋工装长裤。耐磨抗撕裂的面料结实耐操，把螺丝刀、备用弹匣、绷带与火柴全部分门别类塞入裤袋，走起路来格外扎实安心。",
        en = "Sturdy cargo pants outfitted with an array of deep expanding pockets along the thighs. Capable of swallowing loose cartridges, bandages, multitools, and dry jerky rations, they keep vital equipment within arm's reach.",
    },
    ["pants_checkered"] = {
        zh = "印满黑白相间规整方格图案的复古花格休闲长裤。视觉冲击力极强，在无聊至极的废土休整时刻，把裤腿平铺在膝盖上甚至能当成现成的国际象棋或跳棋棋盘，兼具时尚与娱乐价值。",
        en = "A pair of retro casual trousers emblazoned with an unmistakable black-and-white checkerboard pattern. If survival boredom becomes unbearable, spreading the fabric across your knees provides an impromptu chessboard for friendly camp games.",
    },
    ["pants_faux_fur"] = {
        zh = "内衬缝有厚实人造保暖短毛绒的防寒长裤。外层防风棉布阻挡严寒刺骨的荒原冷风，内部人造毛绒锁住体温，虽然重量略显笨重，但在气温骤降的暴风雪季节能死死护住双腿免受冻伤。",
        en = "Heavy cotton trousers lined with plush synthetic faux fur. Trapping body heat while deflecting freezing gales, they protect legs from frostbite when traversing wind-scoured highways during bitter post-apocalyptic blizzards.",
    },
    ["pants_fur"] = {
        zh = "用整张熟化野兽厚皮毛手工粗线缝制而成的天然毛皮重型保暖裤。毛密油润且具有天然拒水防雪性能，穿在身上犹如给双腿披上一层天然棉袄，是在严冬极寒废土荒野狩猎的终极御寒装。",
        en = "A thick pair of winter pants crafted from tanned animal pelts with the dense fur turned inward. Naturally water-repellent and impervious to sub-zero blizzards, they keep legs toasty during grueling arctic foraging expeditions.",
    },
    ["pants_hiking"] = {
        zh = "采用轻量化四向弹力面料与表面特氟龙拒水涂层打造的专业登山徒步裤。速干耐磨且在膝关节处做了立体预成型剪裁，翻山越岭或翻越铁丝网拒马时动作伸展自如毫无束缚感。",
        en = "Lightweight performance hiking pants woven from quick-drying ripstop synthetic fabric. Treated with water-repellent coatings and articulated knees, they grant effortless agility when scrambling over rocky ridges or jumping collapsed fences.",
    },
    ["pants_leather"] = {
        zh = "由厚重坚韧的黑色熟牛皮精工缝制而成的重型皮裤。虽然穿在身上稍显闷热沉重且限制剧烈踢腿，但其变态的防刮耐磨防刺性能，能轻松弹开变异野犬的撕咬和荆棘灌木的划割。",
        en = "Rugged pants tailored from heavy black leather hide. While stiff and cumbersome during hot summer treks, their dense armored surface effortlessly deflects slashing zombie fingernails, feral dog bites, and jagged brambles.",
