    ["pearl_gold_bracelet"] = {
        zh = "在闪亮纯金铰链链节上间插镶嵌颗颗温润珍珠的华贵手镯。金色的耀眼夺目与珍珠的柔和含蓄相得益彰，戴在手腕上随着举手投足发出悦耳轻响，在黑市中能轻易换来一挺崭新重机枪。",
        en = "A polished yellow-gold link bracelet set with gleaming natural pearls. The brilliant contrast between warm burnished gold and iridescent white gems creates a stunning status symbol coveted by influential trading outpost barons.",
    },
    ["pearl_gold_cufflinks"] = {
        zh = "一对以纯金底座包镶圆润白珍珠的高档晚宴衬衫袖扣。造型沉稳内敛且不失高贵华美，在参加幸存者联盟高层和谈会议时佩戴在法式袖口上，瞬间为谈判者增添了难以言喻的文明威望。",
        en = "A pair of exquisite gold cufflinks framing smooth button pearls. Fastening formal dress shirt cuffs with these heirloom accessories projects unflinching poise and diplomatic stature during tense inter-faction summit negotiations.",
    },
    ["pearl_gold_earring"] = {
        zh = "一对由细致纯金耳钩挂载单颗大号水滴形珍珠的优雅吊坠耳环。光洁的珍珠在耳畔随风轻晃，反射出摇曳烛火的柔光，哪怕身处满是瓦砾的地下掩体，也掩盖不住佩戴者的高贵气质。",
        en = "A pair of dangling gold earrings featuring teardrop pearl drops. Swaying gently with every motion, their iridescent surface catches ambient firelight, bringing a defiant touch of civilized glamour to subterranean bunker life.",
    },
    ["pearl_gold_pendant_necklace"] = {
        zh = "一条由细腻纯金水波链悬挂一颗大直径天然海水珍珠的唯美项链。金光微泛，珍珠如晨露般晶莹剔透，垂挂在锁骨间静谧生辉，是末日荒原上见证永恒誓言的最深情定情信物。",
        en = "A delicate gold necklace carrying a solitary, immaculate marine pearl pendant. Resting over armor padding, its luminous organic sheen gleams with breathtaking purity, serving as an irreplaceable heirloom in turbulent times.",
    },
    ["pearl_gold_ring"] = {
        zh = "一枚在优雅四爪黄金戒托正中央高耸托举圆润白珍珠的奢华戒指。黄金的璀璨完美烘托了珍珠的月白光泽，戴在无名指上温润细腻，是在末日余烬中重温旧世界婚礼誓约的浪漫瑰宝。",
        en = "A polished gold ring securing a radiant spherical pearl within delicate prong settings. Elegant and velvety against the finger, it symbolizes enduring love and unyielding hope across a fractured, ash-covered world.",
    },
    ["pearl_gold_tiara"] = {
        zh = "由高纯度纯金枝条手工缠绕编织、冠顶整齐镶嵌一圈璀璨珍珠的华丽王冠。戴在额前金光四射且珍珠温润如玉，宛如童话中王后降临，能让粗俗野蛮的流浪掠夺者也为之惊叹倾倒。",
        en = "A regal tiara hand-wrought from pure gold filigree and crested with magnificent pearls. Blazing with imperial splendor, crowning your brow with this masterpiece commands instant awe across lawless frontier settlements.",
    },
    ["pearl_platinum_bracelet"] = {
        zh = "由坚硬冷冽的纯白铂金链扣串接数颗优质大珍珠的现代奢华手镯。铂金的冰清玉洁与珍珠的温润光泽完美契合，沉甸甸的分量与永不氧化的特性，让它成为世代相传的传家硬通货。",
        en = "A heavy platinum bracelet articulated with immaculate freshwater pearls. Merging the cool unyielding durability of platinum with the soft rainbow iridescence of nacre, this indestructible piece of jewelry buys boundless goodwill.",
    },
    ["pearl_platinum_cufflinks"] = {
        zh = "一对由耐磨铂金精工车削镶嵌大颗粒珍珠的奢华袖扣。永不磨损褪色的银白铂金衬托着珍珠的月夜清辉，即便穿着厚重防弹风衣出席避难所晚宴，也能在手腕翻转间展现顶级教养。",
        en = "A set of refined platinum cufflinks featuring bezel-mounted button pearls. Impervious to radioactive corrosion and tarnish, they add an aura of aristocratic sophistication to survival uniforms during formal gatherings.",
    },
    ["pearl_platinum_earring"] = {
        zh = "一对以铂金四爪牢牢抓取圆润珍珠的高级耳钉。银白冷峻与珍珠温婉交相辉映，小巧贴耳且绝不勾挂防毒面具带子，是兼顾废土实用安全性与极致优雅审美的顶级耳饰。",
        en = "A pair of platinum stud earrings gripping luminous spherical pearls securely. Compact and sitting flush against the earlobe, they avoid catching on gas mask harnesses while projecting effortless aristocratic grace.",
    },
    ["pearl_platinum_pendant_necklace"] = {
        zh = "由高强度铂金细链悬挂单颗巨型珍珠的现代风奢华项链。坚固的铂金链条不易拉断，冰凉的珍珠贴在胸前带来令人心安的宁静，是无论历经多少战火硝烟都依然闪耀的永恒珠宝。",
        en = "A sturdy platinum chain suspending a solitary, flawless giant pearl. Strong enough to resist accidental snags during frenzied combat escapes, its pristine elegance stands in glorious defiance against surrounding devastation.",
    },
    ["pearl_platinum_ring"] = {
        zh = "一枚在厚重高强度铂金戒臂上稳固镶嵌天然珍珠的重工戒指。铂金质地坚如磐石永不形变，中心珍珠圆润如满月，戴在指间既展现尊贵身价，在紧急关头挥拳也能造成沉重金属闷击。",
        en = "A hefty platinum ring mounting a lustrous natural pearl on a thick structural shank. Combining unbreakable metallurgical strength with delicate organic beauty, it doubles as an aristocratic fist load during unexpected brawls.",
    },
    ["pearl_platinum_tiara"] = {
        zh = "以稀有耐高温铂金精工打造冠架、前额呈拱形镶满大颗高光珍珠的冰霜王冠。全冠散发着冷艳如寒冬初雪的纯洁光芒，戴在头上高傲圣洁，宛如主宰冰雪废原的末世女神。",
        en = "A majestic royal tiara forged in brilliant white platinum and crested with rows of shimmering pearls. Glinting with icy, celestial radiance, it crowns the wearer with unshakeable sovereign dignity amidst anarchy.",
    },
    ["pearl_silver_bracelet"] = {
        zh = "用九二五纯银编织成柔软麻花链带、点缀多颗圆润白珍珠的典雅手镯。银质的光泽温润柔和，珍珠排列错落有致，戴在手腕上轻巧贴合，散发着江南水乡般的淡雅诗意与宁静。",
        en = "A sterling silver bracelet crafted with delicate braided links and strung with lustrous pearls. Its soft metallic sheen harmonizes naturally with the milky gems, providing a touch of poetic serenity amidst ruined cities.",
    },
    ["pearl_silver_cufflinks"] = {
        zh = "一对采用做旧纯银包边镶嵌小珍珠的古典正装袖扣。银质边框经过细致复古雕花处理，珍珠在烛光下泛着朦胧的象牙白微光，在末日工坊中擦拭干净，依然是一对令人赞叹的精美银饰。",
        en = "A pair of antiqued sterling silver cufflinks centering luminous ivory pearls. Featuring understated engraved rims, they preserve classic sartorial tradition for survivors who insist on dressing with dignity after the fall.",
    },
    ["pearl_silver_earring"] = {
        zh = "一对由细腻九二五纯银丝弯折抓镶圆润白珍珠的典雅耳环。柔和银光与淡雅珍珠相衬得宜，轻轻摇曳在耳际，让佩戴者在满目荒凉的辐射焦土上，依旧保留着一份不随波逐流的精致清幽。",
        en = "A pair of sterling silver drop earrings clutching lustrous freshwater pearls. Their gentle silvery glow harmonizes gracefully with soft nacre iridescence, offering a quiet touch of enduring dignity in ruined landscapes.",
    },
    ["pearl_silver_pendant_necklace"] = {
        zh = "由做工考究的纯银细链悬挂单颗温润大珍珠的唯美项链。暗沉的银色边框没有黄金的刺目招摇，在暗处巡逻时不会反射反光，静静垂于胸前，带给荒野流浪者无尽的宁静与慰藉。",
        en = "A tasteful sterling silver necklace suspending a luminous solitary pearl pendant. Free of ostentatious glitter, its discreet finish avoids catching hostile sniper glances while resting like a soothing talisman on your chest.",
    },
    ["pearl_silver_ring"] = {
        zh = "一枚在素雅纯银戒臂正中镶嵌一颗圆润光洁珍珠的典雅女戒。银质触感温润贴手，珍珠在月色下散发着皎洁光晕，是废墟搜刮中难得一见、能抚平心灵创伤的旧世界美好信物。",
        en = "An understated sterling silver ring adorned with a gleaming round pearl. Cool and smooth against the finger, its lunar sheen recalls serene peacetime memories that comfort hardened survivors resting after desperate battles.",
    },
    ["pearl_silver_tiara"] = {
        zh = "用纯银手工敲打成轻盈枝叶纹理、前额环绕点缀数颗天然珍珠的唯美小银冠。轻巧便携如林间仙子的发饰，佩戴在额前灵动非凡，让灰头土脸的幸存者少女瞬间化身为月夜公主。",
        en = "A whimsical silver tiara beaten into leafy tendrils and punctuated by glowing white pearls. Light on the brow, it imparts an ethereal fairytale charm that transcends the grim, muddy realities of post-cataclysm life.",
    },
    ["pebble"] = {
        zh = "在河滩或碎石堆里随手捡到的一颗表面光滑圆润的小石子。握在手心里沉甸甸的，装入弹弓皮兜用力拉满发射，是在弹药告罄时无声击晕远距离落单行尸与猎捕野鸟的零成本弹药。",
        en = "A smooth, water-worn river pebble picked from stony creek beds. Fitting snugly inside slingshot pouches, it provides silent, infinitely scavengeable kinetic ammunition for dispatching stray undead scouts and foraging wild game.",
    },
    ["pebble_clay"] = {
        zh = "用黏土手工搓成球形并放在篝火旁烘烤硬化的自制弹丸。质地坚硬且重量均匀，配合弹弓使用弹道极其平直，是在缺乏现代铅弹弹药的蛮荒旷野自给自足狩猎麻雀野兔的神器。",
        en = "A spherical pellet molded from damp clay and baked firm beside campfire coals. Inexpensive, uniform, and cleanly weighted, it supplies slingshot hunters with reliable practice and hunting ammo without consuming precious metal.",
    },
    ["pecan"] = {
        zh = "从野外参天碧根果树下捡拾到的一捧带硬壳的椭圆坚果。外壳坚硬紧实能长期防潮防虫，用石块敲开外壳，里面饱满油润的果仁蕴含着极高的植物脂肪，是废土森林中最耐存的天然热量库。",
        en = "A handful of hard-shelled wild pecans gathered beneath towering woodland trees. Their dense protective husks preserve rich, buttery nutmeat through harsh winters, providing foragers with reliable calories and wholesome plant proteins.",
    },
    ["pecan_roasted"] = {
        zh = "在营火铁板上慢慢烘烤至油脂溢出、散发着焦香坚果芬芳的熟碧根果仁。每一口咬下去都酥脆掉渣且回味甘甜，浓郁的天然油脂在舌尖融化，是对白天冒死搜刮最奢侈的美食犒赏。",
        en = "Plump pecan halves toasted slowly over campfire coals until sizzling with fragrant natural oils. Rich, buttery, and delightfully crunchy, munching these roasted delicacies elevates humble woodland camping into a feast.",
    },
    ["pecan_shelled"] = {
        zh = "已经细致剥去坚硬木质外壳、清洗整洁的原味生碧根果仁。形状宛如微型大脑，手感油润且极易消化吸收，大把塞进嘴里能为疲惫不堪的肌肉迅速注入源源不断的持久攀爬耐力。",
        en = "A handful of raw shelled pecans, a sweet variety of wild hickory nut. Packed with calorie-dense natural lipids, snacking on these tender golden morsels supplies steady, enduring physical endurance on exhausting hikes.",
    },
    ["pecorino_cheese"] = {
        zh = "切自整块熟化绵羊奶酪的一厚片正宗意大利佩科里诺硬干酪。质地坚硬干燥且极其耐储存，散发着浓郁深沉的咸鲜羊乳香气，刨成碎屑撒在粗粮糊里，能让整锅糊糊立刻变得鲜美无比。",
        en = "A wedge of hard aged sheep's milk pecorino cheese boasting sharp salty umami. Exceptionally shelf-stable, grating a dusting over bland boiled wheat berries transforms dull survival rations into savory gourmet masterpieces.",
    },
    ["pedal_extenders"] = {
        zh = "用厚实防滑橡胶与加固螺栓制成的一套车辆脚踏板延长垫。紧紧锁在刹车与油门踏板上，能将踩踏接触面垫高数寸，让身材矮小的变异幸存者也能稳稳当当驾驭大型重型装甲车。",
        en = "Heavy rubber extension blocks designed to bolt securely onto vehicular foot pedals. Extending reach by several crucial inches, they permit diminutive or mutated survivors to drive massive off-road haulers with ergonomic confidence.",
    },
    ["pedal_extenders_makeshift"] = {
        zh = "用废木块、厚鞋底与大量大力胶带粗暴绑在车辆脚踏板上的简易垫高块。虽然外表滑稽寒酸，甚至在急刹车时容易左右晃动，但至少解决了双脚够不着油门无法逃离尸群的致命窘境。",
        en = "A pair of makeshift pedal extenders cobbled together from scraps of two-by-four lumber and duct tape. Though slightly wobbly under hard braking, they allow vertically challenged drivers to reach the gas pedal during emergencies.",
    },
    ["pedal_grindstone"] = {
        zh = "利用废旧自行车脚踏传动系统驱动的大型圆形旋转砂轮机。双脚有节奏地蹬踏踏板，厚重的金刚砂轮便飞速旋转、火星四溅，无需消耗任何燃油电力就能把钝砍刀打磨得削铁如泥。",
        en = "A foot-pedaled circular grindstone assembled on a bicycle crank frame. Pumping the pedals spins the coarse abrasive stone at high speed without electricity, sending showers of bright sparks while honing blunt machetes razor-sharp.",
    },
    ["peeler"] = {
        zh = "一把带有双向摆动不锈钢锋利刀片的手持蔬果削皮器。刀锋锋利顺畅，轻轻一推便能快速削去土豆、胡萝卜与南瓜的粗糙泥皮，最大程度保留内部宝贵的营养果肉绝不浪费。",
        en = "A standard Y-shaped vegetable peeler with a pivoting stainless steel blade. Gliding effortlessly across lumpy scavenged potatoes and wild roots, it strips away bitter mud-caked rinds while conserving precious edible flesh beneath.",
    },
    ["peephole"] = {
        zh = "内置微型广角鱼眼透镜的黄铜门用窥视镜。将其钻孔安装在避难所厚重防盗铁门上，无需开门就能以一百八十度超大视野看清门外走廊动静，防止一开门迎面撞上埋伏的酸液行尸。",
        en = "A compact brass door viewer containing a miniature wide-angle optical fisheye lens. Installed through reinforced bunker doors, it provides a panoramic view of outer hallways, preventing fatal surprises when inspecting nocturnal scratching sounds.",
    },
    ["pekmez"] = {
        zh = "将新鲜成熟葡萄汁经过长时间慢火熬煮浓缩制成的浓稠深黑葡萄糖蜜。甜度极高且富含天然矿物质与铁元素，既是长途跋涉极佳的抗疲劳糖分补给，也是自制药膳的天然甜味剂。",
        en = "A thick, dark molasses syrup produced by simmering pressed grape must for hours. Rich in natural iron and concentrated fruit sugars, a spoonful provides an instant energy burst that keeps weary hikers marching.",
    },
    ["pelmeni"] = {
        zh = "一碗在滚烫热汤中煮熟的传统经典俄式牛肉猪肉馅小饺子。薄韧的面皮紧紧包裹着滚烫多汁的肉馅，在寒冬地窖里吃上一碗连汤带肉的热饺子，整个人立刻从刺骨寒意中满血复活。",
        en = "A piping hot bowl of boiled pelmeni dumplings stuffed with seasoned minced meat. Biting through tender dough releases savory steaming meat juices, banishing bitter frost from weary bones in freezing post-apocalyptic winters.",
    },
    ["pemmican"] = {
        zh = "将精瘦风干肉干碎、动物熬炼油脂与晒干野浆果紧密捶打压制而成的北美传统干肉饼。极其结实紧密，在常温下保存数年依然不会变质，是荒野流浪猎人长途穿越死域的不二神粮。",
        en = "A historic dense survival cake blending pounded lean jerked meat, rendered suet, and dried berries. Impervious to spoilage across decades of storage, a pocketful provides unmatched nutritional density during cross-country treks.",
    },
    ["pemmican_meat"] = {
        zh = "完全摒弃植物成分、仅由高纯度风干肉粉与动物骨髓牛油压制而成的纯肉干肉饼。能量密度近乎纯脂肪，咬下一小口慢慢咀嚼，能在胃中提供长达一整天的持久抗寒发热能量。",
        en = "An austere variant of traditional pemmican made purely from pulverized jerky and rich rendered tallow. Packed with pure lipids and protein, it delivers dense, long-burning metabolic warmth to sustain scouts through sub-zero blizzards.",
    },
    ["pemmican_veggy"] = {
        zh = "在动物油脂中大量混入脱水野生浆果、向日葵籽仁与风干蔬菜粉调和压制而成的素菜干肉饼。口感酸甜富有嚼劲，兼顾了植物维生素与油脂热量，不易引发便秘，营养均衡。",
        en = "A modified pemmican block heavily enriched with dried blueberries, sunflower kernels, and vegetable meal. Offering a sweeter, fiber-rich chew alongside essential fats, it provides balanced survival sustenance that prevents dietary deficiencies.",
    },
    ["pen"] = {
        zh = "全金属材质赋予了它远超一次性塑料笔的沉稳手感。旧时代的大人物用它签署兼并合同与抵押协议，而你用它在避难所水泥墙上划下度过末日的正字计数，或者在弹尽粮绝时插进丧尸的耳蜗里。",
        en = "Solid metal construction grants this writing implement dignity that cheap plastic disposables could never dream of. Pre-apocalypse executives used it to sign million-dollar foreclosures; you use it to scratch tally marks on cellar walls and occasionally pierce zombie ear canals.",
    },
    ["pencil"] = {
        zh = "美国标准“2号”对应HB硬度，因早年读卡机需要其特有的石墨导电率而普及。末日里它最大的美德是零下低温照常书写，并在写错求生笔记时提供一块早已硬化的干瘪橡皮。",
        en = "The Number 2 designation denotes standard HB graphite hardness, cemented in American culture because early Scantron optical test-scoring machines required its specific reflectivity and electrical conductivity. In the wasteland, its greatest virtue is simply functioning at subzero temperatures without freezing or leaking.",
    },
    ["pencil_case"] = {
        zh = "带有金属拉链与防水尼龙布料的小巧学生用拉链文具袋。内部整洁分隔，在末日中用来收纳缝纫钢针、手术刀片、打火石以及散装小口径子弹极其顺手，是翻找小零碎的整理神器。",
        en = "A compact zippered fabric pouch originally intended for school pencils. Perfectly sized for organizing loose suture needles, scalpel blades, spare fuses, and pistol cartridges, it keeps vital micro-supplies indexed inside cluttered rucksacks.",
    },
    ["pepper"] = {
        zh = "一瓶研磨细腻、散发着刺鼻辛辣芳香的纯天然黑胡椒粉。在工坊烹饪台上撒上一小撮，不仅能掩盖变异兽肉的土腥味，在遭遇近身袭击时冷不丁扬在丧尸眼眶里，也能起到强力防身效果。",
        en = "A container of finely ground pungent black peppercorns. Beyond masking the gamy tang of butchered mutant wildlife, tossing a handful of this stinging spice into an attacker's eyes creates an effective non-lethal distraction.",
    },
    ["pepperbone"] = {
        zh = "在烈火炭火上慢烤至骨油融化、表面撒满喷香黑胡椒碎的烤牛腿大骨髓。用小铁勺挖出如黄油般温热流淌的胡椒骨髓吸入口中，浓烈咸香顺喉而下，是废土旷野上最狂野的高脂美味。",
        en = "Split marrow bones roasted over campfire coals and dusted with freshly cracked pepper. Scooping the rich, bubbling marrow delivers decadently savory lipids that restore depleted stamina faster than any manufactured ration bar.",
    },
    ["pepperfat"] = {
        zh = "裹满黑胡椒碎与粗盐粒下锅煎烤至表面金黄微焦的厚切肥五花肉。油脂在咀嚼时在口中爆开，黑胡椒的微辣完美解腻，高密度的热量瞬间让冻僵的四肢重新充满无穷的活力与干劲。",
        en = "Thick slabs of fatty pork belly fried golden and heavily seasoned with coarse black pepper. The spicy crust balances the unctuous rendered lard, pumping desperate survivors full of vital calories on bitter winter nights.",
    },
    ["pepperhuman"] = {
        zh = "用粗黑胡椒粒和海盐腌制并煎熟的人肉切片。虽然浓烈的香料完全掩盖了肉质的气味，但当你大口咀嚼下咽时，心底那份残存的文明道德感正在不可逆转地彻底崩塌。",
        en = "Seared humanoid meat seasoned with coarse black pepper and salt. Heavy spices mask the true flavor, yet swallowing it systematically erodes whatever civilized morality remains within your soul.",
