    ["poultry_scrap_pepper"] = {
        zh = "用黑胡椒碎爆炒熟透的香辣碎禽肉。辛辣刺激的胡椒香气将禽肉原汁原味的鲜香彻底激发出来，虽然分量不多，但就着一杯清水吞下，能给冰冷的肠胃带来强烈的暖意。",
        en = "Scraps of chicken seared with a generous coating of black pepper. The spicy aroma masks stale refrigeration, warming chilly guts and revitalizing weary limbs on damp cellar patrols.",
    },
    ["poultry_smoked"] = {
        zh = "在果木熏房里经过浓密硬木烟雾长达数十小时慢火低温熏烤脱水的干熏禽肉条。肉质紧实泛着琥珀深色，浓郁的果木烟熏香气不仅赋予其绝佳风味，更能让它在常温下保存数月毫不变质。",
        en = "Strips of lean bird meat dried and cured over fragrant hardwood smoke inside a curing kiln. Thoroughly dehydrated and infused with deep hickory aromas, this poultry jerky provides lightweight, chewable protein on the road.",
    },
    ["poutine"] = {
        zh = "刚出锅滚烫酥脆的金黄薯条上堆满大块新鲜软弹奶酪凝乳、并浇淋上大量滚烫浓郁黑胡椒肉汁的经典肉汁奶酪薯条。奶酪在肉汁中拉出长丝，高热量脂肪碳水炸弹，是世界上最无可挑剔的慰藉美食。",
        en = "A steaming platter of crispy golden fries buried beneath fresh squeaky cheese curds and smothered in piping-hot brown gravy. Melding savory richness into high-calorie decadence, this Canadian staple offers supreme culinary comfort.",
    },
    ["powder_candy"] = {
        zh = "装在细长纸管吸管里的彩色酸甜水果味速溶粉末糖果。咬破纸管倒进嘴里，细密的酸甜粉末瞬间在舌尖融化并爆发出刺激的果酸冲击，是末日废土上最受儿童与疲惫拾荒者喜爱的无价甜食。",
        en = "Slender paper tubes filled with sweet and sour flavored candy powder. Tipping the fine tart powder onto your tongue sparks an electrifying rush of pure sugar that instantly brightens dreary moods inside survival bunkers.",
