    ["press_cake"] = {
        zh = "从坚果仁或油料种子中彻底压榨出植物油后遗留下的干燥致密渣饼。虽然油脂已被榨干，但富含粗蛋白与植物纤维，捏碎烘烤可制成高蛋白粗粮饼干，更是饲养避难所牲畜的顶级高能饲料。",
        en = "The dense, dry fiber cake left behind after pressing vegetable oils from roasted nuts. Still packed with concentrated plant protein, crumbling and baking this byproduct creates nutritious emergency hardtack or premium livestock feed.",
    },
    ["press_dowel"] = {
        zh = "用坚硬白蜡木车削打磨出的简易十二号霰弹土法复装木销工具组。配合木槌在营火旁手工将打过的旧塑料弹壳重新整容、压入底火与装填铅丸，结构虽然原始简陋，却能让你拥有无尽的霰弹火力。",
        en = "A set of whittled hardwood dowels tailored for manual shotshell reloading. Used alongside a wooden mallet to deprime, repack wadding, and crimp fired plastic hulls, it keeps scavenged shotguns fed without modern machines.",
    },
    ["pressin"] = {
        zh = "外形伪装成订书机或小型手电筒的冷战特工隐蔽手枪。枪身短小精致且仅能容纳极少发子弹，虽然没有任何人体工效可言，但在被掠夺者近身搜身时往往能打出绝地翻盘的奇迹。",
        en = "A clandestine pocket pistol disguised as an innocuous mechanic tool. Carrying meager capacity with awkward ergonomics, this concealable surprise turns invasive pat-downs by aggressive raiders into fatal ambush opportunities.",
    },
    ["pressure_cooker"] = {
        zh = "带有坚固旋转锁死密封盖与重力限压阀的厚壁合金高压烹饪锅。锅内高温高压能将原本坚韧如皮革的变异老兽肉在半小时内炖得软烂脱骨，更能作为野外医疗器械快速蒸汽消毒的高压灭菌釜。",
        en = "A heavy-duty aluminum pressure cooker featuring a locking lid and weighted relief valve. Trapping superheated steam, it tenderizes tough mutant meats in minutes or functions as an emergency field autoclave for sterilizing surgical needles.",
    },
    ["pressure_gauge"] = {
        zh = "带有波登管内部传动弹簧与刻度指针的工业级金属管道压力表。拧在气泵管道或蒸汽管路表面，表盘指针能直观精准指示当前的内部工作气压，防止储气储油罐因过载超压发生灾难性大爆炸。",
        en = "A dial pressure gauge encasing a mechanical Bourdon tube within brass and glass. Threaded into compressor lines and boilers, its needle monitors internal pressures, preventing devastating catastrophic ruptures in homemade workshops.",
    },
    ["pressure_tank"] = {
        zh = "带有加厚冲压封头与标准安全泄压阀的重型工业级高压储气钢罐。能承受数百个大气压的高压注气，在避难所工坊中是为气动钉枪、气动水井提水机或自制气动步枪提供源源不断压缩动力的储能罐。",
        en = "A thick-walled welded steel pressure vessel built to withstand hundreds of pounds per square inch. Anchored inside basecamps, it stores compressed air to power pneumatic tools, blast horns, and high-pressure pneumatic weaponry.",
    },
    ["pressurized_canister"] = {
        zh = "采用轻量化高韧性铝合金无缝拉伸冲压而成的小型便携高压气罐。接口处配有精密自闭螺纹阀门，可用来充装高压二氧化碳、丙烷或喷雾气体，是组装自制喷火器与气动注射枪的极佳储气构件。",
        en = "A compact seamless aluminum canister rated for containing high-pressure gases. Fitted with a standardized threaded valve, it stores propane or carbon dioxide for powering portable flamethrowers and pneumatic dart rifles.",
    },
    ["pressurized_tank"] = {
        zh = "专为背负式军用火焰喷射器设计的八升加厚高强度承压燃料钢罐。配有快速注油口与气压加压气嘴，注入凝固汽油并打入高压气体，背在身后能为火神般的喷火器提供毁灭性的狂暴火龙弹药支持。",
        en = "An eight-liter heavy steel fuel cylinder tailored for backpack flamethrower rigs. Built to withstand pressurized gelled fuel mixtures, it feeds continuous torrents of incinerating fire across fortified enemy encampments.",
    },
    ["pressurized_tank_chem"] = {
        zh = "用小型高压灭火器或特种气瓶改装而成的两升简易自制化学喷射承压罐。带有橡胶耐腐蚀密封圈与手动加压阀，在废土上装满浓硫酸或自制神经毒液，扣动喷枪便能对近身敌人喷射出致命酸雨。",
        en = "An improvised two-liter pressurized chemical canister built from a modified fire extinguisher. Impervious to caustic fluids, filling it with concentrated sulfuric acid creates a horrifying close-range chemical projector.",
    },
    ["pressurized_tank_modern"] = {
        zh = "采用先进碳纤维复合材料整体缠绕编织而成的九升超轻量化现代军用承压燃料罐。自重比传统钢罐轻了一半以上但承压极限更为惊人，背在身后奔跑轻便如风，能喷射出更远更炽热的毁灭烈焰。",
        en = "A state-of-the-art nine-liter fuel cylinder wrapped in high-tensile carbon fiber filaments. Featherlight compared to old steel tanks while handling higher operational pressures, it fuels extended, blistering flamethrower assaults.",
    },
    ["pretzels"] = {
        zh = "一小捧经过碱水浸泡后烘烤得金黄焦脆、表面镶嵌着粗大盐粒的经典蝴蝶形硬脆椒盐扭结饼。嘎嘣酥脆且咸香开胃，在缺少佐餐零食的末日黄昏就着一杯清凉淡啤咀嚼，是对疲惫灵魂最好的慰藉。",
        en = "A handful of hard-baked pretzel twists encrusted with coarse rock salt crystals. Crunchy, savory, and wonderfully shelf-stable, munching these salted pastries alongside a mug of cold ale brings true contentment to survival outposts.",
    },
    ["pride_flag"] = {
        zh = "一面色彩斑斓的彩虹骄傲旗帜。在大灾变前它象征着多元与包容的社会运动，如今把它挂在末日废土的武装防空洞外墙上，至少能让灰暗破败的瓦砾堆多出一抹鲜艳的人类文明色彩。",
        en = "A vibrant rainbow pride flag salvaged from a community center. Amidst monochromatic cinderblock ruins and ash-covered streets, draping it over your bunker parapet brings a defiant splash of pre-war humanity.",
    },
    ["priest_collar"] = {
        zh = "白塑料制成的神职罗马领。在大灾变前它代表着神圣与救赎，现在戴上它唯一的实际作用，是让变异狂信徒在用链锯切开你胸膛前，稍微犹豫半秒钟来决定是否需要先做告解。",
        en = "A white plastic clerical tab collar symbolizing divine piety. In the Cataclysm, wearing it buys you perhaps a half-second of hesitation from feral cultists before their makeshift chainblades bite deep into your chest.",
    },
    ["priest_diary"] = {
        zh = "用严谨拉丁文手写的随身神父日记。前面几页还满怀虔诚地记录着教区筹款与修缮风琴，后面几页字迹潦草凌乱，全是用颤抖笔触记下的地下墓穴哀嚎与猎枪弹药剩余数。",
        en = "A leatherbound priest's journal inscribed in archaic Latin cursive. Early pages detail parish charity and pipe organ repairs, while later frenzied scrawls frantically tally shotgun shells and horrors emerging from church crypts.",
    },
    ["primer_tray"] = {
        zh = "装配复装子弹底火专用的小巧塑料翻转盘。轻微摇晃就能让密密麻麻的小底火杯整齐朝上排列，极其考验幸存者在发电机轰鸣和门外抓挠声中紧绷欲裂的微操神经。",
        en = "A ribbed plastic flipper tray designed to orient tiny percussion primer cups anvil-side up. Shaking it requires ice-cold surgical patience while feral wanderers claw aggressively at the sheet-metal barricades outside.",
    },
    ["primitive_adze"] = {
        zh = "用削薄坚硬燧石绑在弯曲木柄上的原始石锛。用来刮削树皮或平整原木手感粗糙，但总比赤手空拳在荒野里用牙齿啃木头要体面得多，虽然挥舞起来手腕随时可能脱臼。",
        en = "A chipped flint blade lashed securely to an angled hardwood haft. While jarring your wrists with every swing, it shapes timber far better than chewing through green pine boughs with your bare teeth.",
    },
    ["primitive_axe"] = {
        zh = "用粗糙藤条将锋利石片绑在木棍末端的原始石斧。它能费力地砍倒灌木和干枯树枝，也能在丧尸靠得太近时敲碎对方的天灵盖，缺点是用力过猛石刃就会飞出去。",
        en = "A chipped river stone wedged into a split sapling handle with braided fibers. It fells scrub brush and fractures decayed zombie skulls, provided the stone head does not dislodge and fly backward.",
    },
    ["primitive_bow_silencer"] = {
        zh = "几团带有松紧绑带的兽皮毛条，缠在弓弦两端用于吸收震动。它能有效将射箭声响降到最低，让在黑夜中潜行的幸存者享受无声猎杀的快感，只要别被自己肚子饿得咕咕叫出卖。",
        en = "Simple strips of adhesive fur wrapped around bowstring notches to suppress twang vibrations. It ensures lethal stealth releases during moonlit ambushes, assuming your famished stomach does not growl louder than the bow.",
    },
    ["primitive_hammer"] = {
        zh = "一块用剥皮树皮死死捆在硬木短棍上的钝重岩石。虽然毫无人体工学可言且重心偏得离谱，但当你想在废墟里砸弯一颗钉子或砸碎一颗坚果时，它确实能完成使命。",
        en = "A heavy granite rock bound to a rough wooden branch with raw bark cordage. Horribly unbalanced and lacking ergonomic grace, it nonetheless crushes rusted nails, stubborn nuts, and the occasional intrusive zombie snout.",
    },
    ["primitive_knife"] = {
        zh = "将打磨出锋利边缘的薄石片嵌进掏空木柄制成的石刀。割割藤蔓剥剥兔皮尚算趁手，千万不要试图拿它去撬罐头或者刺穿凯夫拉防弹衣，除非你想收集一堆石粉。",
        en = "A knapped chert blade fitted into a hollowed wooden peg. Excellent for slicing cordage or skinning rodents, but liable to shatter into powdery shards if jammed against a steel tin or Kevlar vest.",
    },
    ["primitive_shovel"] = {
        zh = "用硬木实木整体削凿成型的原始木铲。虽然挖不动冻土和碎石路面，但在松软泥地里挖挖蚯蚓或给自己刨个应急避风坑还是绰绰有余的，只是铲头极易磨损开裂。",
        en = "A crude entrenching shovel carved entirely from a single split hardwood billet. It bounces uselessly off compacted gravel and frozen tarmac, but shovels loose loam adequately until the wooden edge frays.",
    },
    ["pritchel"] = {
        zh = "铁匠在砧台上给马蹄铁冲出钉孔专用的淬火钢冲子。如今真正的活马早已难觅踪影，但这个尖锐结实的高碳钢圆锥体，成了给自制铁甲和铰链打孔的无价神器。",
        en = "A hardened steel blacksmith punch traditionally used for punching nail holes through glowing horseshoes. With genuine equines long gone, it finds new life piercing clean holes through salvaged iron plates and armor hinges.",
    },
    ["processor"] = {
        zh = "从高档报废家电或车载电脑上拆下来的微处理器核心板。上面密布着早已停产的纳米级集成电路，在这个满地丧尸的荒原上，它就像外星文明遗留的无法解读的神圣符印。",
        en = "A printed circuit board sporting an intact high-frequency microprocessor. Once crunching billions of instructions per second, in the apocalyptic wasteland it sits like a mysterious relic from an extinct, unfathomably advanced silicon civilization.",
    },
    ["programmable_autopilot"] = {
        zh = "能直接接管车辆转向机构与引擎油门的工业级可编程自动驾驶仪。如果编程得当，它能让你的重型改装战车在无人驾驶状态下笔直碾过尸群，前提是代码里没有死循环逻辑。",
        en = "A ruggedized vehicular autopilot controller linked to steering actuators and electronic throttles. Programmed properly, it guides heavily armored deathmobiles through hordes without a driver, assuming your scripts do not crash into infinite loops.",
    },
    ["propane"] = {
        zh = "装在高压钢瓶里的液化丙烷气体。无论是作为便携喷枪的高温热源，还是点燃末日烧烤架烤变异肉排，只要阀门不漏气，它就是废墟中最稳定、最让人安心的蓝色火焰来源。",
        en = "Pressurized liquefied propane gas stored inside sturdy steel canisters. Fueling plumbing torches or backyard barbecue grills for charred mutant steaks, it delivers reliable, scorching blue flame whenever valves hold their seals.",
    },
    ["propane_cooker"] = {
        zh = "接上丙烷气瓶就能直接开火的轻便单头露营燃气灶。结构简单耐用且火力强劲，在没有柴火也没有电力的潮湿雨夜，它能以极高效率为你煮沸一锅不含寄生虫的热汤。",
        en = "A portable single-burner camp stove fueled by liquefied propane bottles. In damp subterranean shelters devoid of dry firewood or electricity, it efficiently boils questionable stream water into safe, steaming broth within minutes.",
    },
    ["propane_lantern"] = {
        zh = "使用丙烷作为燃料的露营汽灯，目前处于关闭状态。内置脆弱的发光白炽纱罩，只要轻轻旋开阀门并擦亮火柴，就能在漆黑的地窖中驱散绝望，带来温暖柔和的恒定白光。",
        en = "A compact propane-powered camping lantern resting in the off position. Its fragile thorium mantle awaits a hiss of fuel and a struck match to banish cellar gloom with radiant, comforting white light.",
    },
    ["propane_lantern_on"] = {
        zh = "正在咝咝燃烧发光的丙烷汽灯。灼热的纱罩散发着明亮而稳定的白光与微微暖意，照亮了整个安全屋的角落，同时也如灯塔般向窗外黑夜中的变异生物宣告着你的精确坐标。",
        en = "A lit propane lantern hissing softly as incandescent mantles glow with brilliance. While bathing your hideout in steady warmth, it also acts like a blazing beacon signaling your precise coordinates to nocturnal monstrosities.",
    },
    ["propane_torch"] = {
        zh = "配有旋钮点火阀的便携式手持丙烷喷枪。能喷射出足以软化铜管、融化焊锡甚至将丧尸衣服引燃的尖锐高温蓝焰，是机械修理、管道焊接以及紧急厨房消毒的全能工具。",
        en = "A handheld blowtorch head screwed atop a pressurized propane cylinder. Spitting focused high-temperature blue darts capable of sweating copper joints or thawing frozen padlocks, it doubles as an aggressive deterrent in a pinch.",
    },
    ["prophylactic_antivenom"] = {
        zh = "装在一次性预充注射器中的实验性广谱抗蛇毒血清。标签上写着军工复合体的绝密编号，据称能中和包括巨型变异响尾蛇在内的大多数神经毒素，注射时肌肉剧痛得令人窒息。",
        en = "An experimental prophylactic antivenom sealed within a single-use auto-injector pen. Developed to neutralize exotic neurotoxins from mutated vipers, injecting it triggers blistering intramuscular agony that easily eclipses the fear of death.",
    },
    ["protein_bar_evac"] = {
        zh = "原本由众筹救灾计划定制的真空包装应急高蛋白口粮。虽然口感如同压缩纸板与石膏粉的混合物，但极高的热量密度和长达数年的保质期，让挑食的幸存者不得不老实咽下肚。",
        en = "Dense emergency survival rations crowdfunded before civilization collapsed. Tasting remarkably like pulverized cardboard bound with chalk dust, its formidable calorie density and indefinite shelf life convince famished scavengers to chew without complaining.",
    },
    ["protein_bar_milk"] = {
        zh = "添加了大量乳清蛋白的坚果过敏友好型能量棒。咬下去质地紧实粘牙，带着淡淡的奶香与人造香草味，能为狂奔数公里的肌肉快速补充氨基酸，只是吃完口干得像含了把沙子。",
        en = "A dense, nut-free energy bar enriched with pasteurized whey protein. Chewy and faintly scented with synthetic vanilla, it repairs fatigued muscles after cross-country sprints, leaving your mouth as dry as desert alkali flats.",
    },
    ["protein_bar_peanut"] = {
        zh = "富含花生碎与花生酱的无乳制品高能蛋白棒。浓郁的烤花生油脂香味在末日简直是无上盛宴，只要你没有重度花生过敏，它就是荒野中不可多得的优质卡路里重型炸弹。",
        en = "A dairy-free protein bar packed with crunchy roasted peanuts and salted nut butter. Yielding immense caloric value, it represents pure ambrosia for weary scavengers, provided severe anaphylactic allergies do not kill you first.",
    },
    ["protein_bar_zero"] = {
        zh = "标榜无乳、无麸质、无坚果的绝对零过敏源纯植物蛋白棒。为了排除所有可能导致诉讼的过敏源，配料表纯净得只剩下豌豆分离蛋白和胶体，吃起来简直就像在咀嚼无味橡皮。",
        en = "A hyper-processed zero-allergen protein bar devoid of dairy, nuts, soy, and gluten. Formulated to avoid pre-cataclysm corporate liability lawsuits, it possesses the distinct texture and thrill of chewing unflavored vulcanized pencil erasers.",
    },
    ["protein_drink"] = {
        zh = "将浓缩蛋白粉直接兑入冷水摇晃调成的稀薄悬浮液。底部总有没化开的滑腻粉块，喝起来像是在灌下半凝固的豆浆油漆，但为了维持末日艰难锻炼出来的肌肉维度，只能闭眼咽下。",
        en = "A chalky suspension created by shaking refined protein powder with cold river water. Invariably lumpy and reminiscent of liquid drywall primer, desperate scavengers choke it down daily to preserve precious muscle mass.",
    },
    ["protein_powder"] = {
        zh = "装在巨大塑料桶里的精炼乳清与大豆浓缩蛋白粉。直接干吃会瞬间吸干你口腔里的所有唾液导致剧烈呛咳，但在物资匮乏的避难所里，它是最轻便易存的纯粹蛋白质原料。",
        en = "A massive tub of raw industrial protein isolate powder. Attempting to consume spoonfuls dry instantly desiccates your oral cavity, but blended into hot rations it offers unmatched protein density per carried ounce.",
    },
    ["protein_shake"] = {
        zh = "用大豆蛋白粉和清洁温水在塑料摇摇杯里调匀的黏稠健身饮料。口感沙涩且带着一股合成香精味，但里面富含的纯净氨基酸能在高强度拼杀后迅速修复撕裂的肌肉组织。",
        en = "A thick protein shake blended from powdered whey and purified water. Chalky with synthetic vanilla undertones, its concentrated amino acids rebuild torn muscle fibers after brutal days of clearing zombie-infested warehouses.",
    },
    ["protein_shake_fortified"] = {
        zh = "额外添加了复合维生素与矿物质强化粉的高能蛋白奶昔。喝起来浓稠得像是在吞石膏浆糊，但它能提供极其均衡的营养补充，让长期缺乏新鲜果蔬的幸存者免受败血症折磨。",
        en = "A nutrient-fortified protein shake packed with multivitamins and essential electrolytes. Swallowing its dense sludge feels like drinking wet plaster, but it decisively wards off scurvy and malnutrition in sunless bunkers.",
    },
    ["protein_smoothie"] = {
        zh = "用纯净水、蛋白粉和少量脱水野果混合搅拌出的浓稠奶昔。口感细腻顺滑，终于不再像喝泥浆那样折磨舌头，一口咽下能让疲惫不堪的身躯重新充满力量，堪称避难所的奢华饮品。",
        en = "A thick, velvety smoothie whipped from purified water, refined protein powder, and crushed wild berries. Savoring its creamy texture provides a fleeting illusion of pre-war luxury amid the grim realities of nuclear fallout.",
    },
    ["prozac"] = {
        zh = "封装在蓝绿胶囊里的百忧解抗抑郁药片。它通过调节大脑神经递质来平抑内心的绝望与创伤，但面对窗外遮天蔽日的丧尸海和酸雨，化学分子的镇定效果在现实荒谬面前显得格外单薄。",
        en = "Standard prescription capsules containing fluoxetine hydrochloride. While medically balancing serotonergic neurochemistry to blunt psychological dread, its chemical optimism struggles to offset the grim sight of flesh-eating horrors pounding incessantly at your windows.",
    },
    ["prussian_blue"] = {
        zh = "含有亚铁氰化铁盐晶体的深蓝色解毒胶囊。用于口服结合人体消化道中的放射性铯与铊并排出体外，虽然吃完后连排泄物都会变成诡异的深蓝孔雀色，但至少你的造血细胞保住了。",
        en = "Dark blue capsules containing insoluble Prussian blue crystals. Formulated to trap radioactive cesium and thallium within your digestive tract, they turn your excretions vibrant azure while shielding your bone marrow from lingering contamination.",
    },
    ["pseudo_app_hd_compressor_unit"] = {
        zh = "结构紧凑的重型高压空气压缩机总成。坚固的双级活塞能将空气强行压缩至极高压强，无论用来给深潜氧气瓶充气还是为自制气动步枪蓄压，都是不可或缺的动力枢纽。",
        en = "A heavy-duty high-pressure compressor pump powered by electric motors. Dual-stage pistons compress air up to extreme bars, essential for recharging diving cylinders and pneumatic sniper systems alike.",
    },
    ["pseudo_app_oxygen_concentrator"] = {
        zh = "从医院病房里搜刮来的医用分子筛制氧机。只要通上电就能从周围空气中源源不断提炼出高纯度医用氧气，对于肺部吸入致命毒气或在缺氧地下深井里施工的幸存者至关重要。",
        en = "A clinical molecular-sieve oxygen concentrator scavenged from abandoned hospitals. Drawing ambient air to generate therapeutic oxygen streams, it saves survivors recovering from toxic gas inhalation in sealed vaults.",
    },
    ["pseudo_archery_target_bale"] = {
        zh = "用致密干稻草和粗麻绳紧紧压实捆扎而成的传统草垛箭靶。能温和地吸收飞箭动能而不会折断宝贵的碳纤维箭杆，是你在避难所后院日复一日苦练百步穿杨神技的最佳陪练。",
        en = "A dense target bale bundled tightly from dried straw and jute twine. Absorbing arrow velocity without snapping expensive carbon shafts, it provides countless hours of silent archery practice behind shelter fences.",
    },
    ["pseudo_archery_target_box"] = {
        zh = "塞满旧衣服和废纸箱的简易方形射击靶箱。制作虽然极其敷衍潦草，但用来测试弓箭初速或自制弩箭落点却出奇的好用，至少省去了在草丛里到处找飞箭的无穷烦恼。",
        en = "A cardboard archery catch-box stuffed with rags and compressed packing foam. Flimsy in appearance, it catches target points reliably, saving you from losing scarce arrows in overgrown overgrown weed patches.",
    },
    ["pseudo_bio_picklock"] = {
        zh = "专为生化仿生植入体设计的虚拟开锁工具逻辑接口。虽然物理世界上根本不存在这把实体钥匙，但只要神经链路接通，它就能像幽灵般侵入老式机械弹子锁并将其无声弹开。",
        en = "A specialized virtual interface abstraction designed for cybernetic bionic lockpicks. Though physically non-existent as a tangible carryable tool, its algorithmic bypass routines command neural actuators to flick mechanical tumblers with spectral precision.",
    },
    ["pseudo_ergometer_mechanical"] = {
        zh = "依靠风阻飞轮运转的硬派机械划船健身器。不需要任何电力就能提供狂暴的背部阻力训练，在被尸潮围困无法外出的无聊日子里，它是排解幽闭恐惧与宣泄体力的绝佳工具。",
        en = "A mechanical flywheel rowing machine operating entirely without electrical current. Delivering punishing resistance workouts, it burns anxious adrenaline and preserves cardiovascular endurance during prolonged blizzard quarantines.",
    },
    ["pseudo_exercise_machine"] = {
        zh = "配重块完备的综合力量训练组合器械。虽然滑轮轴承已经有些生锈干涩，但坚持推胸和深蹲能让你那被末日生活折磨的身躯重新长出钢铁般的肌肉，挥动战斧时更有底气。",
        en = "A multi-station resistance exercise gym fitted with stacked cast-iron plates. Though pulley cables creak with surface rust, regular deadlifts ensure you swing sledgehammers with authoritative, skull-splintering force.",
    },
    ["pseudo_m203"] = {
        zh = "用于重型军用无人战车挂载的六联装 M203 榴弹发射器集成阵列组件。虽然不能手持，但通过火控计算机联动齐射时，能在瞬间将前方整整一条街区的尸潮化为血肉焦土。",
        en = "An integrated cluster of six vehicle-mounted M203 grenade launchers designed for autonomous robotic platforms. Incapable of shoulder-fired operation, coordinated volleys saturated target quadrants with concussive shrapnel, pulverizing swarms into fine red mist.",
    },
    ["pseudo_magazine"] = {
        zh = "为满足底层车辆供弹逻辑而生成的底层虚拟弹匣容器。它没有实体外壳，在物品栏中深不可测，却如同隐形的无底洞般不知疲倦地吞吐着炮弹，默默支撑着改装重机枪的狂暴倾泻。",
        en = "An engine-level virtual magazine abstraction facilitating unorthodox vehicle turret feeding mechanisms. Lacking tangible metal feed lips, this phantom container silently channels belt-fed ammunition into screaming heavy machine guns without mechanical jamming.",
    },
    ["pseudo_magazine_mod"] = {
        zh = "用于配合虚拟弹匣逻辑使用的内部系统插槽组件。你无法把它拿在手上端详，它如同机器灵魂深处的隐秘契约，确保那些狂野改装的装甲炮塔不会因为找不到弹药挂钩而当场死机。",
        en = "An internal software modifier managing pseudo magazine mounting hooks on custom chassis. Completely invisible to human touch, it bridges technical engine gaps so vehicular miniguns fire reliably without throwing catastrophic fatal script errors.",
    },
    ["pseudo_punching_bag"] = {
        zh = "用粗帆布缝制并塞满细沙与碎皮革的重型悬挂沙袋。一记记重拳轰上去发出沉闷的砰砰闷响，既能打磨指关节的硬度与出拳发力，也是对末日绝望情绪最健康的宣泄方式。",
        en = "A heavy hanging canvas punching bag stuffed with sand and leather scraps. Absorbing relentless boxing flurries with thudding patience, it conditions bare knuckles while venting pent-up apocalypse stress.",
    },
    ["pseudo_training_dummy_heavy"] = {
        zh = "套着防暴盾牌与废旧钢铁甲片的重型搏击训练假人。坚固的钢管骨架能经受住双手巨剑与霰弹枪近距离的疯狂轰击，是评估武器真实破坏力与穿甲深度的终极测试沙包。",
        en = "An armored training dummy wrapped in scrap iron plates and riot shielding. Anchored securely, it withstands punishing testing with warhammers and shotguns, measuring penetration before facing real monsters.",
    },
    ["pseudo_training_dummy_light"] = {
        zh = "用粗木头和旧麻袋粗暴绑扎而成的轻型刺杀训练假人。身上用红色油漆标出了致命要害，练习长矛穿刺与短刀突刺能让你在面对真正嘶吼的丧尸时做到毫不犹豫、一击毙命。",
        en = "A light combat dummy assembled from rough lumber and straw sacks. Stenciled with red bullseyes over vital zones, drilling spear lunges against it builds lethal muscle memory for close-quarters panic.",
    },
    ["pseudo_treadmill_mechanical"] = {
        zh = "依靠人体自身重力与蹬地力量驱动的无动力弯曲跑步机。跑带运转沉重且费力，但它能在完全断电的潮湿防空洞里为你提供极限有氧拉练，确保逃命时永远不会掉队。",
        en = "A curved mechanical treadmill driven purely by user momentum. The heavy rubber slats provide exhausting resistance, conditioning your legs for marathon sprints when ravenous feral predators cut off your retreat.",
    },
    ["psl"] = {
        zh = "罗马尼亚生产的 PSL 半自动精确射手步枪。外观酷似放大的 AK 步枪，发射强劲的 7.62x54R 凸缘弹，虽然连续射击后细长枪管容易发热下垂导致精度飘移，但威力足以掀翻远处的军阀巡逻兵。",
        en = "A Romanian designated marksman rifle built on a stretched stamped Kalashnikov receiver. Chambered in hard-hitting 7.62x54R, its slender barrel strings shots vertically when overheated, yet punches lethal holes through distant marauders.",
    },
    ["pslmag10"] = {
        zh = "容纳 10 发 7.62x54R 大威力凸缘步枪弹的 PSL 原厂钢制弹匣。冲压钢板结实厚重，能有效避免边缘带底缘的俄式步枪弹在双排供弹时发生咬尾卡壳，是精确猎杀的底气所在。",
        en = "A stamped steel 10-round box magazine manufactured for the Romanian PSL rifle. Heavy and rigid, its staggered geometry prevents rimmed 7.62x54R casings from locking rims, feeding dependable precision volleys downrange.",
    },
    ["pslmag5"] = {
        zh = "仅能容纳 5 发子弹的短款 PSL 步枪钢制弹匣。虽然容弹量少得可怜在尸潮围攻时令人绝望，但短小的尺寸在卧姿射击或隐蔽伪装时完全不会触地撑起枪身，深受伏击猎手喜爱。",
        en = "A stubby 5-round steel magazine for the PSL marksman rifle. While offering anemic sustained firepower against onrushing hordes, its ultra-low profile allows prone snipers to belly-crawl through dense brush without snagging roots.",
    },
    ["psych_file"] = {
        zh = "从地下秘密实验室档案柜搜刮出的一份绝密心理评估报告。泛黄纸张上密密麻麻记录着某位科学家在直面传送门未知实体后的不可逆精神崩溃过程，读得人后背发凉冷汗直流。",
        en = "A yellowed confidential laboratory dossier containing psychological evaluations of portal researchers. Reading transcripts of their irreversible descent into gibberish and sensory madness sends icy chills trickling down your neck.",
    },
    ["puck"] = {
        zh = "一块由高密度硬化硫化橡胶压制而成的标准冰球。不仅结实耐磨且质感沉重，除了在光滑冰面上击打滑行，紧急关头装进长筒袜里甩起来，就是一件足以砸扁丧尸颅骨的钝击凶器。",
        en = "A dense, vulcanized rubber hockey puck manufactured for professional icy rinks. Impervious to weathering and surprisingly heavy, slipping it inside a wool sock yields a devastating improvised blackjack that shatters skulls.",
    },
    ["pudding"] = {
        zh = "用发酵乳制品与大量白糖熬制冷却而成的浓郁布丁甜品。甜腻丝滑的口感能瞬间在味蕾上引爆多巴胺，在秩序彻底崩塌的血腥末世里，这小小一口香甜足以抚平幸存者千疮百孔的心灵。",
        en = "A decadent cup of chilled dairy pudding swimming with sugary goodness. Creamy and impossibly sweet on parched tongues, every spoonful floods traumatized minds with blissful dopamine, granting temporary respite from surrounding apocalypse.",
    },
    ["puller"] = {
        zh = "利用惯性冲击原理安全拆解各类枪弹的动能拔弹器。形似一把中空塑料锤，将子弹卡入并对硬物猛烈敲击，即可完整回收昂贵火药与毫无损伤的弹头，复装狂人的必备利器。",
        en = "A hollow plastic kinetic impact hammer designed to disassemble live cartridges. Slamming its nose onto an anvil extracts intact copper-jacketed bullets and unburnt powder kernels without detonating delicate primers.",
    },
    ["pulverizer"] = {
        zh = "在粗壮实心钢柄顶端焊接着方型致密铁砧的恐怖大钢锤。整把凶器重量惊人且没有任何多余装饰，全力抡圆砸下时带着摧枯拉朽的狂暴巨力，能将狂暴巨兽的头骨直接轰成碎渣。",
        en = "A monstrous sledgehammer sporting a monolithic block of welded steel atop a solid shaft. Delivering terrifying kinetic energy, a full overhead slam pulps skeletal abominations and engine blocks indiscriminately.",
    },
    ["pump_complex"] = {
        zh = "带有高精度铸钢涡轮与强化机械密封的高压工业泵。原本用于化工管线流体增压，在末世中常被用来改装超大威力车载水炮、高压喷火系统或避难所闭环深井排污系统。",
        en = "A heavy-duty multi-stage fluid pump built with reinforced steel impellers. Rescued from chemical refineries, it supplies exceptional pressure required for vehicle-mounted riot cannons, industrial flamethrowers, or deep geothermal coolant loops.",
    },
    ["pumpkin"] = {
        zh = "足有成年人脑袋那么大的饱满金黄大南瓜。不仅外壳结实耐放，掏空后能熬出一大锅香甜浓稠的暖心南瓜羹，还能随手在瓜皮上雕刻出滑稽鬼脸，在万圣节吓退窗外游荡的丧尸。",
        en = "A massive golden pumpkin roughly the size of a human head. Packed with dense orange flesh and edible seeds, carving a menacing grin into its rind offers festive amusement for bored apocalypse survivors.",
    },
    ["pumpkin_cut"] = {
        zh = "已经用刀劈开并刮去瓜瓤与南瓜籽的四分之一瓣新鲜南瓜。金黄多汁的瓜肉切块下锅无论是清蒸还是炖汤都清甜可口，是荒野深秋补充宝贵维生素与膳食纤维的不二之选。",
        en = "A freshly cleaved quadrant of ripe pumpkin, cleaned of fibrous pulp and seeds. Sliced into boiling stockpots, its tender golden flesh yields rich autumn sweetness packed with essential dietary fiber and vitamins.",
    },
    ["pumpkin_mask"] = {
        zh = "万圣节便利店廉价售卖的薄塑料南瓜面具。印着极其夸张诡异的橙黑色露齿坏笑，带在脸上除了遮挡视线和阻碍呼吸外毫无防护作用，但能让你在尸群中显得格外滑稽可笑。",
        en = "A flimsy vacuum-formed plastic novelty mask sporting a toothy jack-o'-lantern grin. Restricting peripheral vision while offering zero ballistic protection, it ensures you perish in the ruins looking like an obnoxious holiday mascot.",
    },
    ["pumpkin_muffins"] = {
        zh = "用新鲜南瓜泥、苹果丁和肉桂粉精心烘烤出的松软南瓜玛芬蛋糕。金黄诱人且香气扑鼻，每一口咬下去都满是深秋丰收的暖意，即便身处满目疮痍的废墟，也能品尝到家的味道。",
        en = "A golden, moist muffin baked with pumpkin puree, diced apples, and cinnamon. Its enticing autumnal aroma fills gloomy concrete bunkers, delivering a rare sensation of civilized domestic comfort amidst the endless ruined wastes.",
    },
    ["pumpkin_yeast_bread"] = {
        zh = "加入煮熟南瓜泥与活性酵母慢发酵烘烤而成的金黄南瓜面包。外皮泛着诱人的焦糖色泽，内部组织松软拉丝且带着淡淡天然甜味，无论抹自制果酱还是配热汤都堪称一绝。",
        en = "A fragrant loaf of golden yeast bread enriched with cooked pumpkin mash. Spongy and slightly sweet, tearing off warm chunks to dip into wild game stew transforms a grim campfire meal into a banquet.",
    },
    ["punch_bone"] = {
        zh = "用粗壮动物长骨经由磨石仔细打磨修尖制成的骨质冲子。虽然耐磨度无法与现代高碳合金钢相比，但在鞣制兽皮边缘冲孔或在硬木上定位钻孔时，它依然是一件趁手实用的野外工具。",
        en = "A tapered punch needle fashioned from a split mammal longbone. While fragile compared to carbon tool steel, it pierces neat lacing eyelets through cured leather hides and marks center-drilling indents on softwood boards.",
    },
    ["punch_dagger"] = {
        zh = "专为近战贴身肉搏设计的双刃拳刃。横握在手心将握把卡在指缝之间，能将整条手臂的冲拳爆发力百分之百转化为穿透力极强的刺击，瞬间贯穿厚实皮甲甚至薄弱的钢板夹层。",
        en = "A push dagger featuring a transverse handle gripped tightly inside a clenched fist. Channeling your entire bodyweight through rapid punches, its double-edged blade punches clean puncture wounds straight through boiled leather cuirasses.",
    },
    ["punch_nail"] = {
        zh = "将两块硬木夹紧一根粗钢钉并用铁丝死死缠绕制成的简易钉冲。虽然外观粗陋得宛如儿童玩具，但在没有工业冲子的情况下，它能精准引导锤击力道，将凹陷销轴顺利顶出。",
        en = "An improvised nail punch constructed by sandwiching a hardened steel nail between wooden splints. Though rudimentary, it focuses blunt hammer strikes onto recessed hinge pins, drifting stubborn mechanical parts free without mangling surrounding metal.",
    },
    ["pur_tablets"] = {
        zh = "用于将浑浊污水澄清并杀菌消毒的净水药片。扔进死水里会冒出一阵浓烈的刺鼻氯气味，虽然喝起来像是在咽下稀释的游泳池消毒水，但绝对能保证你不会因霍乱而拉脱水致死。",
        en = "Effervescent chlorine dioxide tablets designed to clarify and disinfect stagnant puddle water. Though imparting a pungent municipal swimming pool tang, they reliably safeguard your digestive tract against lethal amoebic dysentery.",
    },
    ["pure_meth"] = {
        zh = "结晶纯度极高的高纯度甲基苯丙胺冰晶。吸入后能强行榨干人体的最后一丝潜能，让你不知疲倦地狂奔三天三夜，代价是在药效退去的瞬间，肉体与精神将同时坠入不可逆的万丈深渊。",
        en = "Translucent high-purity methamphetamine shards salvaged from illicit labs. Squeezing every droplet of chemical adrenaline into your bloodstream keeps you awake for days, until catastrophic neurological exhaustion claims its overdue toll.",
    },
    ["purifier"] = {
        zh = "带有浓稠肉色光泽的基因净化药剂。喝下去如同吞下一团蠕动的活性细胞，能在剧烈抽搐与反胃中逆转绝大多数不稳定的变异特征，将你从不可名状的怪物边缘强行拉回人类形态。",
        en = "A thick, flesh-hued genetic stabilization slurry that aggressively suppresses volatile mutations. Choking it down causes violent cellular tremors and feverish nausea, pulling your mutating anatomy back toward human baseline.",
    },
    ["purifier_smart_shot"] = {
        zh = "带有微电脑智能靶向筛选芯片的实验性基因干细胞净化注射针。能在分子层面精准识别并定向清除有害畸变基因，同时完好保留那些能让你夜视或抵御辐射的实用良性变异。",
        en = "A smart stem-cell auto-injector governed by microchip biosensors. It selectively neutralizes debilitating anatomical flaws while deliberately preserving advantageous mutations like night vision or heavy dermal plating.",
    },
    ["purple_drink"] = {
        zh = "工业量产的廉价人造葡萄味高糖饮料。配料表里连半颗真葡萄的影子都没有，全靠人工色素与高果糖玉米糖浆勾兑，喝完舌头会染成艳丽的紫色，在末日是难得的甜美热量来源。",
        en = "Mass-market purple grape beverage sweetened with corn syrup and dyed with artificial chemicals. Devoid of actual fruit juice, it stains your tongue violet while supplying a cheap rush of liquid calories.",
    },
    ["purse"] = {
        zh = "大灾变前知名奢侈品牌出品的精致真皮女包。昂贵的小牛皮缝线细腻优雅，过去在专柜价值数千美元，如今被流浪幸存者用来塞满撬棍、止血带和发霉压缩饼干，依然结实耐磨。",
        en = "A designer leather handbag crafted with delicate stitching and polished brass accents. Once flaunted in upscale boutiques, it now serves as a remarkably durable pouch for rusty prybars, tourniquets, and moldy crackers.",
    },
    ["px4"] = {
        zh = "贝雷塔生产的 Px4 风暴半自动手枪。采用了独特的枪管回转闭锁机构与聚合物轻量下机匣，射击后坐力柔和且指向性极佳，即便在潮湿泥泞的下水道里也能保持顺畅射击。",
        en = "A modern Beretta Px4 Storm pistol utilizing an innovative rotating barrel action inside a lightweight polymer frame. Its subdued recoil impulse keeps double-taps on target during frantic close-quarters skirmishes with subterranean horrors.",
    },
    ["px4_40"] = {
        zh = "发射 .40 S&W 大威力弹药的贝雷塔 Px4 警用手枪。强劲的口径赋予了它远超普通 9 毫米的停止力，枪管回转机构吸收了大部分暴烈后坐力，是猎杀狂暴丧尸与变异犬的可靠副手。",
        en = "A Px4 Storm handgun chambered for the punchy .40 S&W cartridge. The rotating barrel effectively dampens stiff chamber pressures, driving heavy jacketed rounds through feral beast hides with decisive stopping power.",
    },
    ["px4_40mag"] = {
        zh = "容量为 14 发的 .40 S&W 口径 Px4 手枪原厂钢制双排弹匣。做工精良供弹平稳，在狭窄走廊遭遇变异生物时，这 14 发大威力手枪弹能为你筑起一道坚实无匹的金属火墙。",
        en = "A factory 14-round steel magazine engineered for .40 S&W Px4 handguns. Providing seamless dual-stack feeding under stress, it offers ample sustained firepower to break sudden ambushes inside claustrophobic sewer tunnels.",
    },
    ["px4_40mag_10"] = {
        zh = "受大灾变前民用枪支管制法律限制的 10 发短容量 .40 口径手枪弹匣。虽然在面对狂暴尸潮时很快就会打空挂机，但结实的原厂弹簧和防卡托底板依然保证了每一发的可靠输送。",
        en = "A compliant 10-round steel magazine restricted by pre-collapse civilian capacity legislation. Though running dry alarmingly fast during horde sieges, its robust follower spring guarantees that each heavy hollow-point feeds flawlessly.",
    },
    ["px4mag"] = {
        zh = "容纳 17 发 9x19mm 子弹的贝雷塔 Px4 标准原厂弹匣。弹匣背面带有观察孔便于快速清点余弹，高抛光钢制表面耐磨抗污，是战术探险家身上最受欢迎的弹药补给单元。",
        en = "A standard 17-round steel magazine for 9mm Beretta Px4 pistols. Outfitted with rear witness holes to count remaining ammunition, its polished surface sheds grime effortlessly during prolonged underground scavenger runs.",
    },
    ["px4mag_10rd"] = {
        zh = "为遵守法规而通过压痕缩容的 10 发 9 毫米 Px4 钢制弹匣。虽然容量缩水让幸存者感到无奈，但在找不到标准弹匣的废弃靶场，只要能往枪膛里压进子弹，没人会挑剔容量多少。",
        en = "A 10-round capacity-limited magazine designed for 9mm Px4 Storm handguns. While frustratingly skimpy against surging packs of bloated zombies, any functional magazine that chambers live rounds remains an invaluable treasure.",
    },
    ["px4mag_15rd"] = {
        zh = "容量为 15 发的 Px4 紧凑型 9 毫米双排钢制手枪弹匣。在握把便携性与持续火力之间达成了绝佳平衡，非常适合隐蔽携枪潜入变异生物盘踞的废弃警局或军火商店搜刮物资。",
        en = "A 15-round double-stack steel magazine tailored for compact Px4 sidearms. Balancing concealment with sustained fire, it serves stealthy scavengers breaching infested police precinct armories without printing through jackets.",
    },
    ["px4mag_20rd"] = {
        zh = "加装了加长底托底板的 20 发超大容量 Px4 手枪战术弹匣。长长的弹匣体从握把下方明显凸出，虽然略显笨重，但在遭遇狂暴尸潮围攻时，多出来的 3 发子弹往往就是生与死的分水岭。",
        en = "An extended 20-round tactical magazine protruding well past the Px4 pistol grip. Slightly ungainly when holstered, those extra rounds provide decisive suppressing fire when surrounded by screaming, fast-moving mutated runners.",
    },
    ["pyrometer"] = {
        zh = "带有激光红外测温传感器的手持式高温光学测温仪。能在安全距离外无接触测量熔炉铁水或引擎涡轮的超高温度，是末日铁匠精准淬火刃材、避免昂贵合金烧损变形的神器。",
        en = "A handheld optical pyrometer equipped with non-contact infrared sensors. Measuring intense kiln heats and smelting furnace crucibles from afar, it allows master armorers to achieve precise quenching temperatures for superior cutlery.",
    },
    ["q_staff"] = {
        zh = "用整根致密白蜡木精细旋削打磨制成的结实长齐眉棍。重量适中且极具韧性，挥舞起来呼呼生风，不仅能在安全距离外扫倒蹒跚丧尸，还能在泥泞崎岖的山路上当作登山手杖。",
        en = "A balanced quarterstaff fashioned from dense, seasoned ash wood. Lightweight and whip-like, swinging it sweeps decayed shins out from under approaching ghouls, while serving as a steady walking cane across rubble.",
    },
    ["qiang"] = {
        zh = "带有飘逸红缨与双刃淬火钢矛头的中国传统古红缨枪。枪头后方的红缨在挥舞突刺时能迷惑敌人的视线，更能有效阻挡喷溅的污血顺着枪杆流下导致手滑，是一寸长一寸强的典范。",
        en = "A traditional Chinese spear featuring a leaf-shaped steel tip and horsehair tassel. The scarlet fibers distract opponents during thrusting attacks while absorbing foul zombie gore before it slices your grip slick.",
    },
    ["qt_arming_sword"] = {
        zh = "经过精密油淬与回火热处理的经典中世纪骑士单手剑。双刃研磨得锋利无匹且刀身兼具惊人韧性，在狭窄走廊里挥砍刺击行云流水，绝不会在劈中坚硬骨骼时发生弯曲形变。",
        en = "A double-edged arming sword forged from oil-quenched spring steel. Balancing razor sharpness with flexible durability, its rigid blade glides through zombie flesh and deflects bone impacts without warping.",
    },
    ["qt_aztec_spear"] = {
        zh = "采用淬火弹簧钢替代黑曜石刃片重新打造的阿兹特克特波兹托皮利长矛。木柄两侧嵌满锋利剃刀般的钢质锯齿，一次强力横扫就能撕裂变异生物厚重的角质外皮，兼具长枪与巨剑威能。",
        en = "A modernized tepoztopili polearm mounting tempered steel blades along its wooden edges instead of brittle obsidian flakes. Sweeping swings cleave deep wounds through leathery mutated hides with savage reach and momentum.",
    },
    ["qt_aztec_sword"] = {
        zh = "用现代高强度淬火合金钢锯齿改良重铸的马夸威特尔黑曜石阔剑。扁平厚重的硬木剑身两侧固定着极其锋利的淬火钢刃，兼具重型战锤的钝击骨折力与刮骨剔肉的恐怖撕裂伤。",
        en = "A reinforced macuahuitl war club embedding razor-sharp tempered steel cutters into hardwood rims. Merging devastating concussive bludgeoning with catastrophic lacerating incisions, it demolishes armored chitin and bone alike in close melee.",
    },
    ["qt_battleaxe"] = {
        zh = "刃口经过严格回火强化的高碳钢单手战斧。厚重的斧身重心靠前，不仅劈砍时力道刚猛无匹能破开一切骨甲，反面的坚硬破甲锥更能直接在生锈铁皮车门上凿出拳头大的洞。",
        en = "A single-handed battleaxe featuring a differential tempered carbon steel head. Its forward-balanced mass delivers bone-splitting chops, while the reverse spike punches clean holes through reinforced sheet metal doors.",
    },
    ["qt_brigandine_hands"] = {
        zh = "在皮革手套内部精密缝入回火弹簧钢小甲片的顶级布面护手。手指屈伸灵巧自然，无论是紧握剑柄还是快速拉动枪栓都毫无阻滞，同时赋予手掌抵御重击撕咬的非凡防护。",
        en = "Supple leather gloves lined with articulated, tempered steel plates. Preserving delicate dexterity for operating rifle safeties, the spring-tempered backing deflects vicious bites and edged slashes across the knuckles.",
    },
    ["qt_brigandine_hands_xs"] = {
        zh = "专为瘦小手型量身定制的回火布面钢甲手套。精密的内衬甲片经过重新排列紧贴手掌，让体格纤细的拾荒者在近战格斗中也能自信地格挡开敌人的凶猛挥砍而不伤指节。",
        en = "Downsized tempered brigandine gloves tailored for slender hands. Tightly contoured steel plates distribute crushing pressure across small palms, letting agile survivors parry rusty crowbar strikes safely.",
    },
    ["qt_broadsword"] = {
        zh = "配有宽厚双刃与篮状护手的高品质回火碳钢阔剑。厚实的护手彻底保护了握剑的拳头免受伤害，刚韧并济的剑刃在群战中挥砍如风，是清剿密闭室内丧尸群的近战王者。",
        en = "A double-edged broadsword featuring an intricate basket hilt and tempered spring blade. The heavy cage shields fingers during chaotic scuffles, while the balanced blade cleaves limbs effortlessly in room clearing.",
    },
    ["qt_cavalry_sabre"] = {
        zh = "带有一体式护弓与优美轻微弧度的回火钢轻骑兵马刀。刀身配重极为考究，在高速移动中顺势一抹就能切开喉管，极佳的热处理工艺确保了刀刃经久耐用、不崩不卷。",
        en = "A curved cavalry saber crafted from tempered spring steel, featuring a brass knuckle bow. Engineered for fluid cutting on the move, its hardened edge slashes through rotting necks without chipping.",
    },
    ["qt_chain_link"] = {
        zh = "经过退火与油淬硬化处理的高强度弹簧钢锁甲环。切口严丝合缝，防锈耐磨且抗拉强度极高，是编制全套防刺防咬链甲衫或强化皮衣护肩的基础金属构件。",
        en = "A small open ring formed from heat-treated tempered spring steel wire. Offering superb tensile strength and rust resistance, weaving thousands together yields chainmail mesh impenetrable to feral teeth and serrated claws.",
    },
    ["qt_chainmail_arms"] = {
        zh = "采用淬火中碳钢细环手工细密铆接的顶级锁甲护臂。铁环硬度极高且不易拉伸变形，套在手臂上挥舞武器时清脆作响，完美隔绝了来自四周所有阴险突袭的尖牙利爪。",
        en = "Riveted chainmail sleeves woven from heat-treated tempered steel rings. Superior link hardness resists deformation against shearing forces, completely denying biting predators a foothold on your forearms.",
    },
    ["qt_chainmail_aventail"] = {
        zh = "悬挂在战盔边缘如银瀑般垂落的回火钢锁甲面肩甲。柔韧致密的钢环在锁骨与颈部之间构筑起无法逾越的屏障，即便被变异猎犬从后颈猛咬，也只能换来一嘴崩碎的烂牙。",
        en = "A curtain of heat-treated chainmail draped gracefully across the collarbones. Interlocking spring-steel rings form a slashing-proof barrier around throat arteries, splintering jaws that attempt surprise neck ambushes.",
    },
    ["qt_chainmail_face"] = {
        zh = "悬挂在头盔下沿、专精遮挡下巴与咽喉的回火锁环面颈甲。紧密贴合下颚线条，既不妨碍低头瞄准与战术呼喊，又杜绝了被矮小丧尸或爬行虫近距离咬穿喉咙的可能。",
        en = "A compact chainmail bib safeguarding chin and throat beneath your helmet. Rigid tempered links preserve vocal projection during frantic fire commands while stopping upward stabs from skulking vermin.",
    },
    ["qt_chainmail_feet"] = {
        zh = "完全包裹脚掌与小腿下段的回火弹簧钢锁环镫靴。坚韧的钢网不仅能硬顶带刺铁丝网的缠绕，在踩踏地面上扭动挣扎的变异肉虫时，坚硬的金属网面能将其彻底碾成肉酱。",
        en = "Fitted chainmail chausses wrapping feet and ankles in tempered steel mesh. Shrugging off tangled concertina wire, stomping down onto writhing bio-vermin pulps them without risking toxic punctures.",
    },
    ["qt_chainmail_half_legs"] = {
        zh = "覆盖小腿正面的回火钢锁甲半护胫。利用坚固皮带绑缚在小腿迎面骨上，在大幅减轻全身负重的同时，提供了坚不可摧的正向防劈砍能力，翻越碎玻璃窗台毫无顾虑。",
        en = "Lightweight half-leggings shielding shin bones with tempered chainmail mesh. Cinched with heavy buckles, they shed unnecessary rear bulk while letting you vault jagged glass-strewn sills without fear.",
    },
    ["qt_chainmail_hands"] = {
        zh = "由数千枚微型回火钢环手工铆接而成的全包覆手套。手掌部位经过强化防滑处理，握持沉重武器毫不打滑，在白刃拼杀中哪怕徒手去夺敌人的白刃战刀也毫发无损。",
        en = "Five-finger gloves woven entirely from micro-riveted tempered steel links. Offering remarkable flexibility, grasping naked machete blades during desperate hand-to-hand brawls leaves your palms completely unharmed.",
    },
    ["qt_chainmail_hauberk"] = {
        zh = "垂至大腿部位的中世纪回火钢全覆长锁甲衣。高强度的热处理使每个小钢环都具备极佳的抗拉弹性，穿在身上沉稳庄严，宛如披挂了一座移动的近战避难堡垒。",
        en = "A knee-length hauberk crafted from oil-quenched riveted steel rings. The hardened link matrix disperses tearing force evenly, transforming unarmored survivors into indomitable walking knights.",
    },
    ["qt_chainmail_hauberk_xs"] = {
        zh = "专为娇小幸存者精心缩减编织的回火长锁甲。剪裁贴身且重心紧凑，消除了多余铁环在跑动中产生的剧烈晃荡，让体格轻巧的战士也能拥有重骑兵级别的硬核防御力。",
        en = "A scaled-down tempered steel hauberk custom-tailored for compact frames. Its snug fit prevents noisy swinging links during sprints, granting smaller skirmishers the impenetrable defense of heavy cavalry.",
    },
    ["qt_chainmail_hood"] = {
        zh = "由回火钢环严密编织而成的锁甲头罩。从头顶一直保护到肩膀上沿，能将来自侧方的钝击砍杀顺畅滑开，配合内衬武装帽使用，是废土战场上最可靠的防断头战盔底衬。",
        en = "A close-fitting chainmail coif woven from hardened spring-steel links. Draping smoothly over neck muscles, it safely deflects downward axe strikes that would otherwise claim your head.",
    },
    ["qt_chainmail_jumpsuit"] = {
        zh = "从脖颈严丝合缝包裹至脚踝的整套回火钢连体锁甲。尽管整件穿上身重如铅铸且需要花费大量时间打理防锈，但在面对丧尸潮的重重包围撕咬时，它能让你体会到绝对安全的无敌从容。",
        en = "An all-in-one tempered steel chainmail bodysuit enclosing the body from throat to heels. Heavy and demanding regular oiling, standing inside this impenetrable cocoon renders frantic zombie swarms harmless.",
    },
    ["qt_chainmail_jumpsuit_xs"] = {
        zh = "按紧凑小号比例量身手工修整的回火钢连体锁甲。所有受力接缝均经过热处理强化，在狭窄的倒塌废墟和下水道管道中穿行时，既不卡顿受限又能抵御尖锐钢筋的刺击。",
        en = "A tailored XS chainmail jumpsuit scaled down for wiry survivalists. The tightly meshed links eliminate excess sag, letting agile scouts crawl through collapsed ducts without snagging on sharp rebar.",
    },
    ["qt_chainmail_legs"] = {
        zh = "全覆式回火钢锁甲长护腿。通过坚韧的皮质吊带悬挂在战术腰带上，彻底抵消了小腿前部的负重下坠感，在齐腰深的腐烂杂草堆里行军时完全免疫伏地丧尸的偷袭。",
        en = "Full-length leggings woven from tempered spring-steel rings, suspended securely from waistbelts. Dispersing weight comfortably, wading through waist-deep brush populated by lurking crawlers ceases to be hazardous.",
    },
    ["qt_chainmail_sjumpsuit"] = {
        zh = "特意去除了双袖结构以解放肩部灵活性的回火无袖连体锁甲。重点保护躯干骨盆与双腿要害，让双手在拉弓瞄准与快速换弹时不受丝毫束缚，将机动与防御完美统一。",
        en = "A sleeveless chainmail jumpsuit freeing shoulder joints while enclosing torso and legs. Hardened rings safeguard essential organs, permitting unrestricted rifle aiming and rapid reloading under siege.",
    },
    ["qt_chainmail_sjumpsuit_xs"] = {
        zh = "小号剪裁的回火钢无袖连体锁环甲。轻盈贴身的设计专为敏捷型巡逻队员打造，在树林中攀爬跳跃或翻越断墙时无声无息，提供毫无拖沓感的核心致命伤防护。",
        en = "A downsized sleeveless steel jumpsuit engineered for agile patrol scouts. Its snug profile makes zero noise when leaping across rooftops, granting vital organ security without slowing escape sprints.",
    },
    ["qt_chainmail_suit"] = {
        zh = "包含半袖与护膝下摆的标准回火钢全套锁甲套服。精益求精的热处理工艺赋予铁环难以想象的韧劲，即使面对变异巨兽的爪击撕裂，也不会发生铁环崩散脱落的惨剧。",
        en = "A comprehensive chainmail hauberk featuring half-sleeves and knee-length skirts. Superior heat treatment keeps individual rings from blowing open when enduring violent claw swipes from massive predators.",
    },
    ["qt_chainmail_suit_xs"] = {
        zh = "经过紧凑微调的小号全套回火钢锁甲衣。重心平稳分布在躯干中轴线上，让身材纤巧的幸存者在奔袭数公里后依然能保持充沛的体能，从容拔刀迎战堵路的尸群。",
        en = "A downsized tempered steel armor suit balancing mass squarely across the hips. Slender warriors maintain marathon sprint stamina while walking through hordes under absolute slash-proof security.",
    },
    ["qt_chainmail_vest"] = {
        zh = "仅护卫胸腹与后背核心要害的回火钢轻型锁环背心。重量轻巧得让人几乎忘记它的存在，套在皮夹克里面隐蔽性极佳，在废土酒吧或交易站防范冷枪暗箭时是救命的底牌。",
        en = "A lightweight tempered steel chainmail vest concealing seamlessly beneath everyday coats. Weighing little, it provides stealthy thoracic protection against treacherous backstabs in shadowy outpost taverns.",
    },
    ["qt_cutlass"] = {
        zh = "带有加宽护手盘与短粗坚韧单面刃的回火钢近战水手短弯刀。在逼仄杂乱的废弃客车车厢或昏暗地下室拐角处，它能以惊人的爆发力挥出干净利落的致命斜劈。",
        en = "A sturdy naval cutlass forged from tempered carbon steel with an enveloping handguard. In cramped RV cabins or narrow basement corridors, its compact blade delivers devastating close-quarters cleaves.",
    },
    ["qt_demi_gaunt"] = {
        zh = "在皮革战术手套外侧加装回火弹簧钢指关节板的半甲护手。裸露的手指保证了精细检修枪械与操作仪表的触感，钢板覆盖的手背在贴身肉搏中能打出致命的铁拳暴击。",
        en = "Reinforced gauntlets mounting curved plates of tempered steel over leather gloves. Preserving exposed fingertips for gunsmithing, the hardened steel backplates smash through infected jawbones with sledgehammer authority.",
    },
    ["qt_elbow_guards"] = {
        zh = "冲压成型并经过深冷淬火回火的高强度钢护肘。内衬减震软皮垫，在坚硬的花岗岩瓦砾上猛烈翻滚或硬接变异狂徒的铁棍挥击时，能稳稳护住脆弱的肘部尺骨关节。",
        en = "Contoured elbow cops stamped from high-strength tempered steel, lined with soft padding. Absorbing brutal iron bar swings, they keep vulnerable ulna joints intact during desperate alley brawls.",
    },
    ["qt_elbow_guards_xs"] = {
        zh = "专为瘦小手臂打造的小巧回火钢护肘套件。紧贴肘关节的弧度绝不滑脱，在狭小的通风管道里快速匍匐前进时，能彻底消除尖锐铁皮对骨头的磕碰创伤。",
        en = "Compact tempered steel elbow guards tailored for slender arms. Snug elastic straps prevent annoying displacement, preventing painful scrapes against rusty ducts during frantic stealth escapes.",
    },
    ["qt_esapi_plate"] = {
        zh = "用顶级回火装甲钢板精确热压成型的军规ESAPI防弹插板。不仅能正面硬扛多发全威力步枪弹的连续冲击而不破裂，抗多发打击能力更是远超那些一撞就碎的脆皮陶瓷板。",
        en = "A military-spec ESAPI plate press-formed from tempered ballistic armor steel. Shrugging off multiple high-velocity rifle hits without catastrophic shattering, it vastly outlasts brittle ceramic composites in sustained firefights.",
    },
    ["qt_esbi_plate"] = {
        zh = "安装在战术背心侧翼的回火钢制六边形ESBI防弹侧板。优异的回火韧性使其能在近距离霰弹破片狂暴洗礼下纹丝不动，忠实保卫幸存者的两肋与肝脾免遭致命穿刺。",
        en = "A hexagonal side ballistic plate forged from tempered armor steel. Wedged inside carrier waistbands, its resilient matrix absorbs jagged shrapnel clusters, saving flanks and liver from penetrating trauma.",
    },
    ["qt_estoc"] = {
        zh = "没有开刃但拥有极其坚硬无匹菱形断面的回火破甲穿甲剑。剑尖坚硬如金刚石凿子，双手持握猛烈刺击时能瞬间贯穿重型防暴盾牌与变异硬化外骨骼，直捣怪物核心。",
        en = "An edgeless, diamond-section estoc forged from spring-tempered carbon steel. Tapering into an armor-shattering spike, a two-handed thrust punches straight through heavy riot shields and calcified carapace plates.",
    },
    ["qt_falx"] = {
        zh = "反向内弯如死神收割镰刀般的回火高碳钢达西安镰刀。巨大的弯曲力矩让每一次双手下劈都化作撕碎一切防线的噩梦，一击就能将带有铁盔的丧尸脑袋连同肩膀整个削飞。",
        en = "A forward-curved two-handed war sickle hammered from tempered high-carbon steel. Its inward hook concentrates immense hacking leverage, shearing through iron helmets and rotten shoulders with horrifying momentum.",
    },
    ["qt_greaves_brigandine"] = {
        zh = "在耐磨帆布夹层中纵向排列回火弹簧钢条的重型夹板护胫。既吸收了正面棍棒击打的震荡，又能让幸存者毫不犹豫地一脚踢碎挡路爬行丧尸的面门而毫不伤脚骨。",
        en = "Splinted greaves encasing vertical tempered steel slats inside heavy canvas webbing. Absorbing devastating blunt club impacts, they let you boot advancing ankle-biters in the face with impunity.",
    },
    ["qt_heavyhelm_close"] = {
        zh = "十五世纪晚期大师级回火钢全封闭重型头盔。面罩闭合后密不透风，沉重的钢板能够硬顶大口径手枪弹的跳弹擦碰，将整颗脑袋保护得宛如一座攻不破的微型钢铁地堡。",
        en = "A masterwork late-fifteenth-century close helm forged from thick tempered plate. Sealing your skull inside an impregnable steel vault, it shrugs off shotgun pellets and glancing ricochets alike.",
    },
    ["qt_heavyhelm_close_raised"] = {
        zh = "将厚重铰接面罩向上翻起的回火钢封闭重盔。在脱离激烈交火后掀开面罩深吸一口清新的冷空气，广阔的视野能让你看清伏击在废墟角落里的阴险陷阱，保全性命。",
        en = "A heavy tempered close helm locked with its articulated visor flipped upward. Breathing fresh air restores stamina, giving vital situational awareness to spot tripwire ambushes in dark stairwells.",
    },
    ["qt_helm_close"] = {
        zh = "线条优雅且经过精密热处理的回火钢标准封闭式头盔。下颚甲片与面罩严丝合缝地咬合在一起，哪怕被暴徒的铁锤正面敲击，坚韧的钢板也只会发出悦耳的金石共鸣。",
        en = "A classic close helmet crafted from tempered spring steel with interlocking chin plates. Even direct hammer strikes ring harmlessly off its smooth curves, preventing concussive skull trauma.",
    },
    ["qt_helm_close_raised"] = {
        zh = "处于面罩升起观察状态的回火钢封闭头盔。虽然将面部毫无防备地暴露在外，但在搜刮光线幽暗的百货商场时，清晰敏锐的视野远比被蒙在铁罐头里瞎摸要实用得多。",
        en = "A tempered close helmet with its pivoting visor pushed back overhead. Sacrificing facial armor, the unhindered visibility prevents stumbling into cellar sinkholes while looting gloomy department stores.",
    },
    ["qt_helmet_nasal"] = {
        zh = "带有宽厚中央护鼻梁的回火钢早期中世纪鼻盔。视野宽阔透气性极佳，坚固的硬化鼻条多次挡下了丧尸迎面砸来的砖石飞块，堪称兼具轻便与防御的完美头盔典范。",
        en = "An early medieval conical helmet featuring a heavy tempered nasal bar. Providing open ventilation and wide fields of view, its rigid central rail saves your nose bridge from flying masonry.",
    },
    ["qt_helmet_turban"] = {
        zh = "带有高耸尖顶与流线型护颈的回火碳钢东方式头巾盔。独特的几何尖顶设计能将来自头顶上方的高空坠物和挥砍重击滑开卸力，在中世纪战乱中曾守护过无数精锐勇士。",
        en = "A fluted turban helmet forged with an elegant conical apex from tempered steel. Its angled contours slide falling debris and overhead mace strikes harmlessly away from vulnerable cranial crests.",
    },
    ["qt_jian"] = {
        zh = "遵从古法折叠锻打并精良回火的中式双刃直剑。剑身修长挺拔、刚柔并济，刃口寒光逼人，无论是格挡挑刺还是凌空斩截，都透出一股武道大师般的从容与致命杀力。",
        en = "A traditional double-edged straight sword folded and tempered with classical metallurgical precision. Rigid yet springy, its razor edges execute blinding parries and piercing thrusts with fluid martial grace.",
    },
    ["qt_katana"] = {
        zh = "采用现代精密温控油淬回火技术重生的战术武士刀。刀身弧度完美兼顾了高速拔刀与深度切削，锋利无比的刀尖能像裁纸一样轻易剖开变异生物坚韧的皮革外表皮。",
        en = "A contemporary tactical katana oil-quenched to optimal spring temper. Balancing agile handling with deep cutting geometry, its razor edge slices through tough bio-leather hides as easily as paper.",
    },
    ["qt_khopesh"] = {
        zh = "源自古埃及镰刀剑造型的回火高碳钢弯曲战刃。前段加宽外凸的厚重钩刃不仅能在挥砍时爆发出惊人劈力，甚至能在缠斗中顺势钩掉丧尸手中的武器或直接钩翻其下盘。",
        en = "An ancient sickle-sword design reincarnated in tempered carbon steel. The outward-hooking curved blade delivers chopping trauma while snagging enemy limbs and prying riot shields away in melee.",
    },
    ["qt_kilij"] = {
        zh = "刀头部位带有加宽双刃起脊特征的回火奥斯曼基利杰弯刀。极度前移的刀头重心让每一次斩击都如同战斧般沉重霸道，在疾速冲锋中能轻易将挡路的感染者斜向劈成两段。",
        en = "A Turkish kilij saber sporting a flared, double-edged yelman tip. The forward-heavy blade geometry lends axe-like momentum to every slash, cleaving through barricaded zombies during dynamic breaches.",
    },
    ["qt_knee_guards"] = {
        zh = "按照膝盖解剖结构冲压成型的回火钢护膝套件。坚固的回火钢壳即使猛烈撞击在水泥台阶的尖锐边缘上也毫无凹痕，让幸存者能够在狂风暴雨般的枪林弹雨中从容下蹲射击。",
        en = "Ergonomically contoured knee cops stamped from oil-quenched steel. Dropping onto sharp concrete curbs leaves zero dents on the plates, allowing stable, pain-free kneeling firing stances under fire.",
    },
    ["qt_knee_guards_xs"] = {
        zh = "专门缩减比例制造的小号回火钢护膝。内衬减震软皮革紧贴娇小的膝关节，在满是碎石和弹壳的废墟里匍匐前进时，为身材纤瘦的战地侦察员提供坚实不移的护膝屏障。",
        en = "Downsized tempered knee guards proportioned for smaller limbs. Lined with supple shock-absorbing leather, they protect delicate knee joints from jagged rubble during stealth crawls across shattered highway overpasses.",
    },
    ["qt_knife_rambo"] = {
        zh = "带有粗齿背锯与中空防水手柄的经典回火重型生存刀。刀身厚重坚硬且热处理极其到位，不仅能在野外开路劈柴砍伐树枝，贴身肉搏时一刀就能捅穿变异狼犬的厚实胸骨。",
        en = "A heavy-duty survival knife featuring an aggressive sawback and tempered carbon blade. Equally suited for chopping firewood or impaling charging mutant wolves, this formidable tool never snaps under abuse.",
    },
    ["qt_knife_trench"] = {
        zh = "剑身两侧带有三角指虎护手与破骨平头锥的一战风格战壕匕首。握在手中宛如一件精密的杀戮凶器，在狭窄的散兵坑与走廊里近身缠斗时，一拳一刺皆是致命绝杀。",
        en = "A World War I trench dagger featuring an integrated cast-knuckle hilt and tempered blade. In desperate hallway brawls, punching and stabbing flow seamlessly into single bone-shattering motions.",
    },
    ["qt_kriegsmesser"] = {
        zh = "单面开刃并配有剑格护铁的欧洲经典回火双手战刀。修长沉稳的刀身赋予了它令人胆寒的挥砍斩击力，双手全力下劈时能直接将狂暴丧尸的颅骨连同颈骨一起一刀两断。",
        en = "A German two-handed war knife forged from heat-treated spring steel. Its single-edged sweeping blade delivers bone-shearing chops, cleaving through armored zombies with authoritative historical battlefield lethality.",
    },
    ["qt_kukri"] = {
        zh = "带有标志性前重式下弯刀身的回火廓尔喀反曲弯刀。惊人的劈砍杠杆原理让每一次劈下都像一把微型断头台，在清剿茂密灌木丛和斩断丧尸颈椎时有着无与伦比的高效表现。",
        en = "A forward-curving Nepalese kukri machete forged from differential-tempered spring steel. The angled weight forward geometry concentrates immense chopping force, lopping limbs off shambling horrors like dry kindling.",
    },
    ["qt_lighthelm_close"] = {
        zh = "通过精算厚度有效减轻整备重量的回火钢轻型封闭头盔。保留了绝佳的回火韧性与面部全防护，大幅降低了脖颈肌肉的疲劳负担，让全天候高强度行军搜索变得不再痛苦不堪。",
        en = "A lightened close helm forged from tempered steel with optimized plate thickness. Providing complete facial coverage without crushing your cervical spine, it keeps scouts alert during all-day patrol operations.",
    },
    ["qt_lighthelm_close_raised"] = {
        zh = "将轻薄回火钢面罩掀起锁定的轻型封闭盔。面部视野全开的同时能感受到周围气流与危险声响，一旦听到丧尸逼近的咆哮，反手一按就能重新将面门锁入钢板掩护之下。",
        en = "A light tempered helmet with its visor securely flipped overhead. Broadening your sightlines, catching the distant snarl of stalkers lets you snap the visor shut in a single heartbeat.",
    },
    ["qt_link_sheet"] = {
        zh = "由上千个微型淬火钢环手工铆接编织而成的密实锁甲片。质地沉重却柔韧贴身，能直接剪裁拼接缝合在战术背心或皮衣内部，为重要脏器提供坚不可摧的防劈砍与抗撕裂保护。",
        en = "A flexible square sheet of riveted tempered steel chainmail links. Easily tailored into jacket linings, this dense metallic drapery absorbs vicious slashing strokes and jagged shrapnel without adding rigid unyielding bulk.",
    },
    ["qt_longsword"] = {
        zh = "比例极为完美的中世纪双手回火长剑。十字护手与配重圆球形成出色的重心平衡，刚硬锋锐的剑刃既能施展凌厉的半剑锁喉突刺，也能靠势大力沉的横扫将成群丧尸逼退。",
        en = "A balanced two-handed longsword crafted from oil-quenched spring steel. The cruciform crossguard and wheel pommel provide peerless balance, letting you seamlessly shift between sweeping cuts and half-sword thrusts.",
    },
    ["qt_mace"] = {
        zh = "将硬化淬火钢法兰盘牢固焊接在硬木柄头部的中世纪破甲钉头锤。重心集中在锤头，挥舞时带着可怕的破空呼啸，无论丧尸戴着钢盔还是身披重铠，一锤下去都能直接将其颅骨砸成肉泥。",
        en = "A brutal close-combat flanged mace crafted from tempered tool steel mounted on a wooden haft. Concentrating kinetic mass at its striking head, a single downward blow crumbles riot helmets and skull vaults effortlessly.",
    },
    ["qt_mirror_armor"] = {
        zh = "在皮革胸甲上铆接四块大型凸面抛光回火钢盘的精良镜甲。光滑致密的回火圆盘能极其有效地滑开刺击与撕咬，在火光掩映下折射出的金属冷芒宛如英雄战将的荣耀铠甲。",
        en = "Convex discs of heat-treated polished steel riveted over a thick leather cuirass. The deflective geometry turns deadly lunges into harmless glancing blows, gleaming impressively in campfire glow.",
    },
    ["qt_mitten_gaunt"] = {
        zh = "采用回火弹簧钢连指外壳包裹拳面的重型钢手套。坚固的钢壳宛如两个铁铸拳套，在近战搏杀中不仅能毫无顾忌地格挡开利刃挥击，顺势挥出的摆拳更能直接砸碎敌人的下颌骨。",
        en = "Heavy clamshell mittens encasing fingers within tempered curved plates. Doubling as devastating blunt weapons, punching forward while deflecting rusty blades shatters charging ghoul jawbones with resounding impacts.",
    },
    ["qt_nodachi"] = {
        zh = "全长近六英尺的特长回火双手大太刀。出色的现代回火热处理让这把超长巨刃在剧烈碰撞下依然韧性十足，在开阔地形全力抡动开来，足以构筑起一道无头丧尸倒下的死亡禁区。",
        en = "A colossal two-handed greatsword forged from oil-tempered spring steel. Its immense reach and resilient temper allow sweeping horizontal cleaves that reap through shambling undead hordes like scythed wheat.",
    },
    ["qt_pike"] = {
        zh = "装有淬火回火硬化四棱钢枪头的超长军阵重矛。枪头坚固得足以刺穿轻型装甲车侧板，配合长达数米的粗壮木杆，能让幸存者在变异怪物的攻击范围之外将其稳稳钉死在地上。",
        en = "An elongated pike tipped with a four-sided tempered steel point. Capable of skewering thick hides and piercing light sheet metal, its reach pins thrashing abominations safely beyond biting range.",
    },
    ["qt_rapier"] = {
        zh = "配有繁复护手碗与细长刚韧剑身的高碳回火迅捷剑。极快的出剑速度犹如毒蛇吐信，剑尖能精准刺入丧尸眼眶或头骨接缝处直捣脑髓，是一柄讲究优雅与致命精度的刺击神兵。",
        en = "A graceful thrusting rapier featuring an intricate swept hilt and tempered blade. Darting forward like striking vipers, its needle-fine point pierces through eye sockets directly into necrotic brains.",
    },
    ["qt_sabaton"] = {
        zh = "由数片精细铰接回火钢片构成的坚不可摧战靴护甲。鞋头加厚耐磨且完全免疫地刺与陷阱，在近战肉搏中顺势一记正踹，足以把趴在脚边的爬行丧尸脑袋当场踏成肉泥。",
        en = "Articulated sabatons formed from interlocking tempered steel plates strapped over boots. Impervious to hidden caltrops and ankle-biters, a downward heel stomp instantly crushes skulls against the tarmac.",
    },
    ["qt_scimitar"] = {
        zh = "弧度极大且配重极为流畅的东方回火碳钢弯刀。顺滑的斩击流线在切削肉体时几乎没有阻力，单手挥舞如同一道银色月牙在敌群中穿梭，带起漫天飞舞的腥臭断肢与污血。",
        en = "A deeply curved oriental shamshir forged from differential-tempered spring steel. Its sweeping edge draws through soft targets with near-zero drag, carving ribbons through hostile swarms in close-quarters combat.",
    },
    ["qt_sheet_metal_small"] = {
        zh = "一块经过精密热处理淬火的优质小块合金钢板。硬度极高且不易弯折变形，是机械工坊自制防弹插板、强化车辆发动机装甲或打造手工全身板甲的不可或缺基础原料。",
        en = "A compact sheet of hardened, oil-quenched steel. Boasting exceptional structural resilience, armorers weld it onto vehicular wheel cowlings or hammer it into curved breastplate inserts that stop high-velocity fragmentation.",
    },
    ["qt_shoulder_guards"] = {
        zh = "采用叠层回火钢片制作的重型肩甲。贴合肩胛骨与锁骨轮廓，巧妙的滑动铆钉在大幅挥动武器时毫无阻滞感，稳稳扛下天花板伏击者从天而降的所有狂暴撕扯与利爪拍击。",
        en = "Articulated shoulder pauldrons crafted from overlapping tempered steel plates. Sliding smoothly during vigorous sword swings, they reliably absorb violent ceiling-drop ambushes without binding your neck.",
    },
    ["qt_shoulder_guards_xs"] = {
        zh = "专为瘦小骨架精心调整的小号回火钢肩甲。减轻了多余分量却丝毫不减防护硬度，紧固皮带牢牢锁定在肩头，让敏捷的侦察员在钻行狭窄废墟通风井时毫无刮擦阻碍。",
        en = "Scaled-down tempered shoulder guards proportioned for slender scavengers. Stripping away unnecessary bulk without sacrificing hardness, they protect scouts scrambling through narrow rubble crawlspaces from sudden overhead ambushes.",
    },
    ["qt_spear_steel"] = {
        zh = "带有加宽倒钩与强韧套筒的回火钢制全能战矛。枪刃经过严格油淬回火，兼顾了刺穿坚硬骨板的硬度与防止卡滞的拔枪顺畅度，是野外生存防御变异巨熊的最强利器。",
        en = "A versatile combat spear socketed with a broad, tempered steel head. Hardened against snapping under high bending stress, it keeps raging mutant bears pinned down while you administer lethal finishing thrusts.",
    },
    ["qt_steel_chunk"] = {
        zh = "一块经过热处理油淬的不规则淬火钢块。表面残留着高温回火的深蓝氧化皮，沉重而坚硬，既能直接当成砸碎骨头的投掷凶器，也是铁匠重铸高等级冷兵器与工具的致密钢材。",
        en = "An irregular offcut of tempered high-carbon steel bearing blue thermal oxidation scales. Heavy and dense, scavengers hurl it as an improvised projectile or melt it down into hardened edge tools at the forge.",
    },
    ["qt_steel_facemask"] = {
        zh = "带有冷峻面部轮廓冲压与透气孔的高强度回火钢装甲面罩。坚不可摧的回火钢板将整个面门完全包裹，不仅能硬抗近距霰弹飞溅，在阴暗巷战中更是散发着令人胆寒的死神气息。",
        en = "A menacing armored face mask stamped from high-strength tempered steel plates. Encasing cheeks and jawline behind slash-proof metal, it deflects shrapnel sprays while striking psychological terror into raiders.",
    },
    ["qt_steel_lump"] = {
        zh = "一块经过完全锻打与油淬退火处理的重型成型淬火钢锭。组织致密无气孔，是锻造传奇级双手巨剑、重装动力装甲铰链或加农炮闩体的顶级金属原料，价值非凡。",
        en = "A solid, refined ingot of tempered structural steel. Possessing extraordinary density and toughness, it represents the foundational raw material required to forge masterwork bastard swords, vehicle mounts, and hydraulic armor joints.",
    },
    ["qt_steel_staff"] = {
        zh = "在坚韧硬木长棍两端镶嵌淬火钢箍并包覆钢皮的重型齐眉棍。不仅保留了木棍轻快灵动的扫击手感，两端沉重的钢头更能施展碎骨般的粉碎性打击，令近身丧尸闻风丧胆。",
        en = "A resilient hardwood quarterstaff shod with thick caps of tempered steel. Combining quick staff martial forms with bone-snapping impact mass at both terminals, it cracks zombie jaws without splintering under repeated strain.",
    },
    ["qt_talwar"] = {
        zh = "带有传统盘形护手与加厚刀身的回火印度塔瓦弯刀。独特的握柄限制了手腕活动，迫使挥刀者用整条手臂的蛮力甩出狂暴砍击，在破开坚韧的皮甲与肌肉时有着无可比拟的破坏力。",
        en = "An Indo-Persian talwar featuring a disc pommel and heavy curved tempered blade. Locking the wrist into powerful arm-driven slashes, it shears through reinforced leather armor and bio-mutant tissue effortlessly.",
    },
    ["qt_vambrace_brigandine"] = {
        zh = "在耐磨布料内衬嵌合回火弹簧钢纵条的前臂夹板甲。坚韧的钢条能硬生生弹开敌人的砍刀与水管横击，在拼刀博弈的紧要关头为你架起一道坚如磐石的手臂钢铁防线。",
        en = "Splinted vambraces sandwiching tempered spring-steel bars inside heavy protective fabric. Deflecting sudden machete swings and swinging iron rebar, they form an impenetrable shield across your defensive forearms.",
    },
    ["qt_wakizashi"] = {
        zh = "作为武士副刀的精良回火碳钢短胁差。刀身虽短却极其锋利坚固，在长刀施展不开的狭窄车厢或坍塌走廊里，反手拔出胁差一记抹喉就能瞬间解决贴身肉搏的狂暴敌人。",
        en = "A razor-sharp companion sword forged with optimal spring temper. When two-handed weapons are unwieldy inside cramped vehicles, drawing this agile blade delivers fatal throat slashes in the blink of an eye.",
    },
    ["qt_warhammer"] = {
        zh = "带有方型破甲锤头与修长穿甲背锥的回火战锤。沉重的钢锤能将狂暴丧尸的防弹钢盔直接砸瘪震碎脑浆，而尖锐的背锥更是一击就能凿穿厚重的变异几丁质外骨骼。",
        en = "A dedicated warhammer pairing a blunt striking face with a curved tempered beak. Shattering reinforced ballistic helmets with bone-pulverizing force, the sharp beak easily punches through hardened chitin carapaces.",
    },
    ["qt_wire"] = {
        zh = "一圈具有优异弹性与极高抗拉强度的优质淬火钢丝。难以被普通钳子剪断，无论是用来布置致命的战术绊雷陷阱、制作高拉力复合弓弦，还是捆扎加固车辆装甲都坚如磐石。",
        en = "A coil of high-tensile tempered steel piano wire. Resistant to dull snips, it is prized for rigging deadly perimeter tripwires, replacing heavy mechanical pull-cables, or trussing reinforced armor plates onto war buggies.",
    },
    ["qt_zweihander"] = {
        zh = "全长超过六英尺的传奇双手中世纪回火巨剑。带有侧翼突齿与厚重十字护手，双手挥舞起来如同一台旋转的绞肉风暴，任何企图围攻你的丧尸狂潮都会在这道钢铁旋风下被拦腰斩断。",
        en = "A legendary six-foot two-handed greatsword forged from spring-tempered carbon steel. Wielded in continuous spinning arcs, this devastating weapon tears through encircling zombie hordes like an unstoppable meat grinder.",
    },
    ["quad_rotors"] = {
        zh = "专为小型侦察四旋翼无人机设计的高转速多旋翼螺旋桨组件。采用碳纤维增强工程塑料注塑成型，质轻且动平衡极佳，只要装上微型无刷电机，就能让自制无人机轻盈升空侦察险情。",
        en = "A matched quartet of balanced counter-rotating drone propellers molded from carbon-fiber nylon. Engineered for high-speed brushless motors, they generate sufficient vertical thrust to hoist recon quads above zombie-infested rooftops.",
    },
    ["quesadilla_cheese"] = {
        zh = "在两层玉米薄饼中间夹入厚厚干酪并在铁板上烤至金黄焦脆的墨西哥起司薄饼。趁热撕开会拉出诱人的长长奶酪丝，浓郁的奶香与烤玉米香气在废墟中堪称无上的灵魂慰藉。",
        en = "A crisp toasted tortilla folded around molten, gooey cheese grilled over campfire embers. Pulling it apart yields elastic strands of melted dairy, delivering rich comforting fat and toasted corn bliss in ruined wastelands.",
    },
    ["quikclot"] = {
        zh = "装在撕拉铝箔包里的军用沸石止血粉。直接倒进喷血的开放性大伤口中能急速吸水并激活凝血级联反应，虽然伤口会产生剧烈灼烧高热，但能瞬间将人从失血性休克边缘救回。",
        en = "A packet of granular kaolin hemostatic powder for treating traumatic arterial hemorrhage. Dumping it straight into gaping wounds accelerates coagulation instantly, trading intense thermal burning for salvation from fatal hypovolemic shock.",
    },
    ["quill_ink"] = {
        zh = "用没食子、铁盐与天然树胶精心调制而成的古典羽毛笔专用墨水。色泽沉郁黑亮且具有优异的防水耐久性，写在羊皮纸或手工纸上经久不褪，适合记录末日生存日记或绘制避难所地图。",
        en = "A bottle of permanent iron gall ink brewed with oak galls and gum arabic. Resisting moisture and sunlight degradation, it allows scholars to draft indelible wasteland survival chronicles and detailed settlement maps.",
    },
    ["quilt"] = {
        zh = "用厚实纯羊毛织物按照经典三角花纹手工缝制的保暖大棉被。蓬松柔软且蓄热能力惊人，在没有暖气、窗外北风呼啸的刺骨寒冬长夜里，裹紧它就是抵御失温冻死的最强物理防线。",
        en = "A plush, thick wool quilt stitched together in traditional geometric patterns. Trapping body heat beneath insulating layers, burrowing under its heavy folds keeps you alive during sub-zero blizzards when electric heaters lie dead.",
    },
    ["quilt_patchwork"] = {
        zh = "收集各种废旧毛衣、斜纹粗布和法兰绒碎布头手工拼缝而成的厚重百家被。虽然花色杂乱滑稽得像小丑戏服，但层层叠叠的保暖棉絮能提供无与伦比的温暖，治愈疲惫冰冷的身躯。",
        en = "A massive patchwork quilt sewn from mismatched squares of salvaged wool and flannel shirts. Visually chaotic and homespun, its thick layers trap phenomenal warmth, banishing winter chill from damp earthen bunkers.",
    },
    ["quiver"] = {
        zh = "用坚韧熟牛皮缝制、配有可调节皮带的标准腰挂式箭袋。能稳妥容纳 20 支箭矢，拔箭开口经过硬化定型处理，让弓箭手在面对飞速逼近的怪物时能行云流水地完成盲抽速射。",
        en = "A classic side-mounted leather quiver equipped with an adjustable belt loop. Securing twenty arrows neatly along your hip, its flared mouth allows instinctive blind draws while dodging lunging predators in dense forests.",
    },
    ["quiver_birchbark"] = {
        zh = "用剥下的白桦树皮精细编制、以松胶与皮绳加固的轻巧桦皮箭袋。系在腰间轻若无物且完全防水，在潮湿林地穿行时绝不会受潮变形，散发着淡淡而令人安神的桦树清香。",
        en = "A rustic waist quiver plaited from broad strips of white birchbark and waterproofed with pine pitch. Feather-light on the hip, it shields wood arrows from torrential downpours during extended woodland hunts.",
    },
    ["quiver_large"] = {
        zh = "用加厚公牛皮精心缝制的重型大容量背负式箭袋。背带宽厚舒适并配有胸前快拆扣，能安全装载整整 40 支羽箭，为深入高危险度感染区的长距离游侠提供深不见底的弹药储备。",
        en = "A heavy-duty leather back quiver rigged with broad padded harness straps. Capable of carrying forty arrows without rattling, it ensures wilderness rangers never run out of silent shafts during protracted sieges against hordes.",
    },
    ["quiver_large_birchbark"] = {
        zh = "用多层厚白桦树皮与云杉根线复合缝制而成的大型背负式箭袋。能一次性装下数十支各型箭矢，不仅极其结实轻便耐磨，在被雨水浇透后还会散发干燥木香，是荒野隐士的骄傲杰作。",
        en = "A cavernous back quiver crafted from double-layered birchbark stitched with spruce root fibers. Accommodating dozens of broadheads, this resilient wilderness container repels torrential rain while keeping weight on your spine minimal.",
    },
    ["quiver_simple_cloth"] = {
        zh = "用结实粗帆布随手缝合成圆筒状并配有简易斜挎带的布面箭袋。虽然没有皮革的定型硬挺，剧烈奔跑时箭翎容易互相摩擦受损，但在物资极度匮乏时，它是最容易手工制作的装箭容器。",
        en = "A rudimentary cylindrical quiver stitched from salvaged cotton canvas and scrap webbing. Though arrows jostle and fletchings crinkle during full sprints, it provides an accessible homemade solution when proper cured hides are scarce.",
    },
    ["quiver_takedown_bow"] = {
        zh = "不仅能收纳 16 支箭矢、还能将分体反曲弓拆解后整体打包收纳的战术多功能帆布箭袋。布局紧凑且防护到位，背在身后宛如一个普通修长画筒，极佳地兼顾了战备携行与隐蔽搜刮。",
        en = "A versatile reinforced canvas quiver featuring dedicated internal sleeves for both arrows and a disassembled takedown bow. Concealing lethal archery gear inside an innocuous pack, it lets scouts roam ruins without drawing unwanted attention.",
    },
    ["r_carpet"] = {
        zh = "一整卷从高档剧院或废弃政府大楼剥下来的厚实大红地毯。除了铺在安全屋地面防滑保暖之外，剪碎后更是极佳的织物纤维与吸音原料，还能在逃生时卷成临时阻挡丧尸撕咬的护身软垫。",
        en = "A rolled length of plush crimson carpet salvaged from an abandoned municipal auditorium. Insulating chilly concrete bunker floors, strips cut from its woven wool pile serve as padding, cleaning rags, or soundproofing.",
    },
    ["rabbit_sample"] = {
        zh = "从变异前野兔肌肉组织中提取并浸泡在冷冻保护剂中的生物遗传样本管。相传野兔的脚掌象征着幸运，而管子里悬浮的这团活性细胞悬浊液，正是合成敏捷系与潜行系变异诱变剂的无价母液。",
        en = "A cryogenic vial containing preserved genetic tissue sampled from wild rabbits. Symbolizing folklore luck, this biological slurry serves as the essential catalytic base when synthesizing mutagens tailored for extreme speed and heightened reflexes.",
    },
    ["rack_test_tube"] = {
        zh = "带有数十个标准定位孔洞的聚丙烯塑料试管架。虽然本身没有任何杀伤力或高科技含量，但能让你的化学实验室远离试管倾倒碎裂、高纯酸液洒满工作台并烧穿鞋底的灾难性悲剧。",
        en = "A molded plastic test tube stand riddled with organized grid sockets. Though unremarkable as salvage, it prevents unstable chemicals from rolling off worktables, smashing on concrete, and eating corrosive holes through your boots.",
    },
    ["rack_test_tube_micro"] = {
        zh = "专为放置微量离心管与 PCR 扩增管设计的高密度塑料收纳托盘。小巧精致且孔距精密，是末日分子生物学学者提取纯化异种 DNA、配置微量纯化诱变剂时不可替代的精密实验辅助器具。",
        en = "A fine-gridded storage tray tailored for holding miniature microcentrifuge tubes. Crucial for organizing genetic samples during delicate mutagen synthesis, it keeps precious viral isolates from spilling across cluttered lab tables.",
    },
    ["rad_badge"] = {
        zh = "内置感光胶片乳剂层的一次性塑料个人辐射剂量胸卡。随着你在核辐射区滞留时间的累积，内置胶片颜色会从清亮逐渐变为触目惊心的深黑，无情地提醒你骨髓细胞正在以多快的速度走向凋亡。",
        en = "A clip-on plastic badge housing a calibrated photographic film strip. Progressively darkening as ionizing radiation passes through its emulsion layers, it serves as a grim optical tally of cumulative, cell-shredding radiological exposure.",
    },
    ["rad_monitor"] = {
        zh = "配有高灵敏度盖革计数管与液晶背光屏的便携式电子生物辐射监测仪。能实时测量环境伦琴值并在你吸收超标剂量时发出撕心裂肺的蜂鸣尖叫，是在废土废墟中探寻生路的最忠实哨兵。",
        en = "A compact electronic biomonitor incorporating a sensitive Geiger-Muller tube. Continually sampling ambient millisieverts, its shrill audio alarm screams a frantic warning the instant you wander into invisible plumes of radioactive death.",
    },
    ["radio"] = {
        zh = "一台使用电池供电的便携式晶体管收音机，目前处于关机状态。外壳虽然斑驳刮花，但内部天线与调谐旋钮完好无损，只要装入电池，就能在沙沙杂音中搜寻可能存在的生还者广播与神秘电波。",
        en = "A portable battery-powered AM/FM radio receiver resting in the off position. Awaiting dry cells to power its speakers, it stands ready to scan static-choked ether for military emergency broadcasts and lonely survivors.",
    },
    ["radio_book"] = {
        zh = "一本厚实详尽的业余无线电与民用波段通讯入门指南。泛黄书页上印满了天线增益图解、摩尔斯电码表与业余电台通联规范，读完能让你在电磁频谱被神秘干扰阻断的末日搭建自制无线电通信网。",
        en = "A comprehensive instructional manual detailing ham radio theory and antenna design. Studying its technical schematics teaches clever scavengers how to solder functional transceivers, bridging long-distance radio communication across silent, ruined continents.",
    },
    ["radio_car"] = {
        zh = "一辆带有越野大轮胎和独立减震悬挂的高速玩具遥控车。目前处于关机断电状态，虽然看起来只是小孩子的玩具，但在机智幸存者手里，它是绑上手雷开进尸群中央引爆的廉价自杀式无人地面车辆。",
        en = "A rugged radio-controlled toy monster truck equipped with knobby all-terrain tires. Powered off for now, imaginative scavengers frequently convert this harmless toy into a remote-piloted reconnaissance vehicle or mobile pipe-bomb delivery cart.",
    },
    ["radio_car_on"] = {
        zh = "正在嗡嗡通电运转的高速玩具遥控车。伺服舵机与电调随时待命，只要遥控器推杆轻轻一推，它就能飞速冲向街道对面，用电机的尖锐啸叫引开整条街的丧尸，为你创造绝佳的潜行搜刮窗口。",
        en = "A switched-on radio-controlled car buzzing with standby electricity. Guided by a distant transmitter, its electric motor whines loudly as it darts across tarmac, luring slavering zombie mobs away from scavenging objectives.",
    },
    ["radio_car_wheel"] = {
        zh = "一套带有深齿防滑花纹与微型尼龙轮毂的遥控车替换轮胎。虽然尺寸迷你，但高抓地力橡胶配方极其优良，既能用来修复损坏的遥控引诱车，也是制作微型机械传动轮与滑轮组的理想零件。",
        en = "A set of four knobby miniature rubber tires fitted onto nylon wheels. Designed for RC buggies, they grip tarmac tenaciously, making them ideal replacements for decoy vehicles or tiny bearing pulleys in homemade traps.",
    },
    ["radio_mod"] = {
        zh = "集成了微型解码继电器的无线电遥控引爆触发模块。能加装在各类自制爆炸物或照明灯具上，让你在数百米外的安全掩体后，仅凭手持对讲机的特定频率呼叫，就能瞬间引爆陷阱歼灭追兵。",
        en = "A compact radio-activation receiver board equipped with a sensitive switching relay. Wired into homemade explosives or generator ignitions, it enables survivors to trigger perimeter traps remotely from the safety of reinforced bunkers.",
    },
    ["radio_on"] = {
        zh = "正在开启通电的便携式收音机。内置扬声器不知疲倦地吐出刺耳的白噪音与微弱的摩尔斯电码断续音，虽然在寂静的黑夜里这声音宛如呼唤尸群的招魂曲，但至少能驱散安全屋中深入骨髓的孤独。",
        en = "A portable radio receiver actively hissing with electromagnetic static and faint intermittent frequencies. While its volume risks broadcasting your sanctuary to nocturnal hunters, hearing another living voice crackle over airwaves is priceless.",
    },
    ["radio_pouch"] = {
        zh = "采用耐磨考杜拉面料缝制、配有高弹力固定绳的战术电台挂包。通过背面 MOLLE 织带固定在战术背心侧面，能保证天线露在外侧的同时牢牢锁定机身，即便在剧烈摸爬滚打中也不会滑落摔碎。",
        en = "A heavy Cordura MOLLE pouch secured with elastic retention bungees. Keeping tactical transceivers accessible along chest rigs without blocking antennas, it prevents costly military comms gear from bouncing free during frantic escapes.",
    },
    ["radio_repeater_mod"] = {
        zh = "用于将废弃民用广播发射塔改装为高功率中继站的专用电子中继模块。它能大幅过滤天线杂波并以超高功率转发双向无线电信号，让你在方圆数百公里的辽阔废土上随时与远方车队保持清晰联络。",
        en = "An advanced electronic circuit package designed to modify broadcast towers into wide-area communication repeaters. Boosting faint signals across hundreds of miles, it pierces atmospheric electromagnetic interference to reunite scattered survivor enclaves.",
    },
    ["radiocontrol"] = {
        zh = "带有两根微型塑料摇杆的玩具遥控器。虽然外壳轻飘飘的像是随儿童套餐赠送的廉价赠品，但只要装上电池对准频段，你就能像下达死刑判决般操纵玩具小车引爆整条街的丧尸。",
        en = "A dual-joystick handheld radio transmitter originally bundled with toy cars. Though flimsy, synchronizing its frequency lets you steer motorized suicide bait into horde concentrations from safe rooftop perches.",
    },
    ["radish_taproot"] = {
        zh = "刚从泥土里拔出来、带着翠绿叶梗的鲜红小水萝卜主根。在嘴里用力咬碎会发出爽脆的咔嚓声，辛辣中透着微甜的生脆汁水，能在废墟里让早已吃惯死咸罐头的舌头重获新生。",
        en = "Freshly uprooted crimson radish taproots bearing feathery green tops. Biting into their crisp, peppery flesh delivers a burst of moisture that revitalizes tongues long dulled by desiccated survival rations.",
    },
    ["raft_board"] = {
        zh = "用几根粗圆木和剥皮藤条紧密捆扎而成的木筏船体底板。虽然没有任何流线型阻力设计、划动起来慢如蜗牛，但它能让你在变异食人鱼横行的大河上安全漂流而不至于落水丧命。",
        en = "Buoyant pine logs lashed side-by-side with heavy fiber cordage. Completely unhydrodynamic and painfully slow to paddle, it nonetheless keeps your fragile flesh floating safely above schools of mutated river carnivores.",
    },
    ["raging_bull"] = {
        zh = "陶鲁斯生产的愤怒公牛大口径左轮手枪。装填 5 发毁天灭地的 .454 卡苏尔麦格农重弹，枪口带有制退开孔来抑制那野马般的暴烈后坐力，一枪下去足以轰碎任何拦路怪物的颅骨。",
        en = "A massive Taurus Raging Bull revolver chambered in bone-shattering .454 Casull. Ported barrel compensators barely tame its violent recoil, unleashing thunderous kinetic devastation that crumples hulking mutant beasts in their tracks.",
    },
    ["raging_judge"] = {
        zh = "被称为愤怒法官的超大号转轮手枪。既能装填猎枪用的 .410 霰弹也能压进 .454 麦格农弹，沉重转轮宛如审判庭的铁锤，近距离轰击时能在怪物身上撕开碗口大的焦黑空洞。",
        en = "The behemoth Taurus Raging Judge revolver capable of chambering .410 shotshells and .454 Casull rounds. Its cavernous cylinder delivers catastrophic close-range judgment, chewing charging abominations into smoking, shredded confetti.",
    },
    ["ragpouch"] = {
        zh = "用各种破旧碎布和麻线手工粗糙缝合而成的小布袋。封口处只穿着一根细鞋带，虽然脏污发黑且毫无防水能力，但在废墟里搜刮时，它是装满散落子弹与止痛药片的称职小行囊。",
        en = "A rustic drawstring pouch stitched together from scrap denim and frayed twine. Though grubby and permeable to rain, it keeps valuable scavenged loose cartridges and painkiller blisters organized inside your jacket.",
    },
    ["rail_bayonet_lug"] = {
        zh = "可直接锁死在皮卡汀尼导轨上的战术刺刀卡座模块。将现代突击步枪与古老冷兵器暴力结合，当枪管里最后一发子弹打空时，至少还能让你端起步枪像中世纪长矛兵那样殊死冲锋。",
        en = "A rigid aluminum adapter that mounts standard bayonets onto Picatinny accessory rails. Bridging assault rifles with ancient spearcraft, it guarantees you can mount a desperate thrusting charge when chambers click empty.",
    },
    ["rail_laser_sight"] = {
        zh = "可安装在皮轨上的紧凑型可见红光激光瞄准器。红色的细小光点在阴暗走廊中极其醒目，能让你在根本无暇贴腮瞄准的慌乱交火中，凭借直觉快速将子弹倾泻在变异犬眉心。",
        en = "A compact red laser sight clamped onto an accessory rail. Projecting an intense crimson dot through gloom, it allows rapid point-shooting during frantic close-quarters ambushes when bringing iron sights up is impossible.",
    },
    ["rail_mount"] = {
        zh = "采用强化工程塑料注塑成型的枪械侧面导轨扩展基座。能将原本光秃秃的枪身侧面改装出标准的战术导轨槽，让你能够随心所欲地挂载强光战术手电或是激光瞄具，极大提升夜战能力。",
        en = "A molded polymer rail bracket designed to bolt onto firearm receivers. Adding auxiliary mounting slots, it enables scavengers to attach tactical flashlights or target illuminators essential for night sweeps through unlit subterranean tunnels.",
    },
    ["railroad_track_item"] = {
        zh = "长达一整米、沉重无比的标准工业重型钢轨节段。两名壮汉合力搬运都费劲，除了作为铁匠锻造台上最顶级的重型垫铁砧之外，装在工程车辆车头就是不可阻挡的末日破障撞角。",
        en = "A massive, one-meter length of solid industrial steel railway track. Weighing enough to strain your spine, it serves as an indestructible blacksmith anvil or a devastating battering ram welded onto armored vehicles.",
    },
    ["railroad_track_item_half"] = {
        zh = "截断为半米长度的重型锰钢铁轨段。重量依然沉重压手，但单人勉强可以搬运，是搭建坚固野战铁匠台不可多得的优质平整砧体，敲击上去会发出清脆悠长的高强度回响。",
        en = "A dense, half-meter cut of heavy railway track with a flat crown. Manageable by a single sturdy survivor, it makes a resilient field anvil that rings musically under relentless sledgehammer forging blows.",
    },
    ["railroad_track_small"] = {
        zh = "由几根粗木轨枕与轻便钢轨简单组装制成的小型铁轨路基段。虽然承受不了几万吨的重载货运火车，但用来在避难所矿坑内部推行载满矿石与泥土的自制轻型轨道推车堪称完美。",
        en = "A short segment of narrow-gauge light track secured to wooden crossties. Far too delicate for freight locomotives, it effortlessly guides hand-pushed ore carts and salvage trolleys through subterranean mining shafts and bunker tunnels.",
    },
    ["rake"] = {
        zh = "带有十几根淬火弹簧钢齿的结实金属园艺耙。原本在农庄用来清理落叶和耙松土壤，在末世中翻找草丛里隐藏的丧尸残肢、或者在安全屋周围把泥土耙出痕迹以发现夜间入侵者极其实用。",
        en = "A heavy-duty steel garden rake sporting rigid curved tines. Besides clearing brush or aerating soil, raking damp dirt outside your shelter creates an unmissable footprint detector against stealthy nocturnal stalkers.",
    },
    ["rake_plastic"] = {
        zh = "廉价注塑成型的亮黄色塑料落叶耙。齿爪单薄脆弱，用力耙两下干树枝就会折断几根爪齿，更不用提拿它去对付怪物，但如果在废墟里急需塑料碎片当助燃物，它倒是烧得挺旺。",
        en = "A flimsy injection-molded plastic leaf rake with flexible fingers. Snapping brittle tines against the mildest gravel, it makes a hopeless weapon, though its petroleum polymers burn with surprisingly vigorous smoky flames.",
    },
    ["ranger"] = {
        zh = "名为巡逻队长的单人战术棋盘策略游戏。玩家需要独自扮演小队指挥官在险象环生的敌后执行搜救与撤离，在这个满地丧尸的世界里玩这个，简直就像在真实生活里套娃练习荒野求生。",
        en = "A solitaire military strategy board game titled Patrol Leader. Directing imaginary fireteams through hostile insurgent sectors offers an eerily meta escape, practicing synthetic tactical maneuvers while actual mutants scratch at the bunker door.",
    },
    ["rapier"] = {
        zh = "配有华丽复杂护手盘的精钢中世纪刺剑。细长笔直的剑身极具弹性，专为快速穿刺与灵动击剑步法而设计，能像热刀切黄油般精准刺穿丧尸的眼眶并破坏脑干，姿态优雅而致命。",
        en = "A flexible steel rapier equipped with an ornate swept-hilt guard. Engineered for lightning-fast thrusts, its needle point easily pierces through zombie eye sockets directly into brain stems with lethal fencing precision.",
    },
    ["rapier_fake"] = {
        zh = "漫展道具店里售卖的不锈钢装饰细剑。护手是用电镀塑料铸造的，剑身薄脆如同一根大号铁丝，拿来戳丧尸不仅破不开皮肉，还会当场弯折成一个滑稽的九十度大钩子。",
        en = "A decorative costume rapier with a plated plastic basket hilt. Its flimsy stainless blade bends like wire upon contact with decayed clothing, leaving you clutching a ruined novelty stick.",
    },
    ["raptor_sample"] = {
        zh = "从凶残变异猛禽鸟类肌肉与羽管中提取的活性基因样本。悬浮在特制溶剂中的细胞仍在微微颤动，是提炼猛禽系诱变剂的核心原料，能赋予你猎鹰般锐利的远视眼与敏捷的猎杀爪刃。",
        en = "A sterile sample tube containing viable avian tissue extracted from mutated raptors. Pulsing faintly inside nutrient solution, it provides genetic material needed to synthesize mutagens that bestow predatory eyesight and taloned claws.",
    },
    ["rashguard"] = {
        zh = "采用高弹性防磨聚酯面料制成的长袖防磨衣。贴身透气且排汗迅速，原本用于冲浪或巴西柔术训练，穿在战术甲胄内侧能极大减轻板甲内衬对皮肤的剧烈摩擦与汗水淹皮疹。",
        en = "A snug, long-sleeved athletic rashguard made from synthetic stretch fabric. Preventing painful chafing when worn under rough canvas vests or heavy plate armor, it wicks away perspiration during arduous forced marches.",
    },
    ["raspberries"] = {
        zh = "刚从带刺灌木丛里小心翼翼摘下来的一小把鲜红覆盆子。果实中空娇嫩且酸甜爆汁，在没有糖分摄入的废土荒野，每一颗饱满的红浆果都是大自然赐予饥肠辘辘旅行者的纯天然红宝石。",
        en = "A handful of fragile wild red raspberries freshly picked from brambles. Plump and tangy-sweet, popping these delicate hollow fruit into your mouth delivers rare bursts of natural sucrose amidst ruined, ash-choked wilderness.",
    },
    ["rat_sample"] = {
        zh = "从满地乱窜的大变异死老鼠身上提取的活性基因组织悬浮液。带着一股难以言喻的下水道恶臭，却是合成鼠系诱变剂的核心原料，能让你获得在逼仄下水道啃食腐食的逆天生存能力。",
        en = "A cloudy biological vial containing genetic tissue harvested from bloated sewer rats. Despite smelling nauseatingly foul, it is indispensable for synthesizing rodent mutagens, granting unmatched disease resistance and scavenging tenacity.",
    },
    ["ravioli"] = {
        zh = "在小巧面团方块中包裹着肉馅与香料并捏花压边制成的意式肉饺。下锅煮熟后淋上番茄酱汁，一口咬开鲜嫩多汁，碳水化合物与肉香的完美结合让冷酷的末日荒原多了一份人情味。",
        en = "Tender square pasta pockets stuffed with seasoned minced meat and herbs. Boiled soft and tossed in campfire tomato sauce, these comforting dumplings offer savory warmth that momentarily soothes a hardened scavenger's weary soul.",
    },
    ["raw_artichoke"] = {
        zh = "大蓟科植物尚未开花的青绿色花苞。厚实重叠的苞片紧紧包裹在一起，虽然生吃苦涩难咽且纤维粗硬得像嚼树皮，但只要加盐水煮熟并剥下苞片蘸酱，其底部的肉质花托口感甘甜如坚果。",
        en = "The tightly layered green flower bud of an edible globe artichoke thistle. Bitterly astringent when chewed raw, boiling it soft renders its tender heart into an earthy, nutty delicacy worthy of pre-cataclysm dining.",
    },
    ["raw_asparagus"] = {
        zh = "一把刚从湿润沙土里采收的新鲜青芦笋嫩茎。笔直脆嫩且富含微量元素，无论是直接放在炭火余烬上轻微烘烤还是切碎煮汤，那股独特的青草清甜都能瞬间唤醒麻木的味蕾。",
        en = "A bunch of slender, vibrant green asparagus spears harvested from sandy loam. Lightly blistered over glowing campfire coals, their crisp texture and earthy sweetness rejuvenate taste buds dulled by canned emergency provisions.",
    },
    ["raw_bamboo"] = {
        zh = "从竹林泥土中挖出来的几节新鲜鲜嫩竹笋。外皮带有微毛与泥土芳香，剥去外层硬笋衣后切片焯水，能去除苦涩草酸，炒肉或煲汤口感爽脆清甜，是林区求生难得的膳食纤维补充。",
        en = "Freshly unearthed shoots of wild bamboo still clinging to damp soil. Peeling away fuzzy fibrous husks leaves crisp, pale cores that boil into crunchy vegetable stir-fries, providing vital fiber in forested survival zones.",
    },
    ["raw_beans"] = {
        zh = "一小把晒干的生芸豆颗粒。圆润坚硬如石子，富含有毒的植物红细胞凝集素，绝对不能抓起来生吃，但只要在沸水里充分浸泡并彻底煮透，就是提供饱腹感与优质植物蛋白的完美干粮。",
        en = "A handful of raw kidney beans dry and hard as gravel. Containing toxic phytohaemagglutinin that induces violent vomiting if swallowed raw, thorough boiling renders them into hearty, protein-rich stew staples.",
    },
    ["raw_bottle_gourd"] = {
        zh = "一个带着细长葫芦颈的成熟葫芦瓜。厚实硬壳内部藏着水分充沛的瓜肉，掏空晒干后不仅能做成滴水不漏的随身水壶，新鲜瓜肉切片下锅也是一道极其解渴消暑的清炒素菜。",
        en = "A bulbous gourd vegetable featuring a narrow neck and waxy rind. Once hollowed and dried it yields an airtight travel canteen, while its raw white flesh cooks into a mild, hydrating broth.",
    },
    ["raw_burdock"] = {
        zh = "从深厚泥土里费力挖出来的野生牛蒡长根。外表粗糙泥泞酷似枯木枯枝，但刮去泥皮切成细丝后，带着独特的泥土清香与韧脆口感，具有良好的清热药用价值与饱腹效果。",
        en = "A long, tapered wild burdock taproot caked in dry dirt. Resembling a weathered root stick, scrubbing and shaving its firm flesh yields earthy, fibrous shavings celebrated for nutritional stamina and mild medicinal properties.",
    },
    ["raw_butter"] = {
        zh = "从纯新鲜生牛奶中反复搅拌分离出来的未杀菌生黄油块。色泽乳黄且奶香纯正扑鼻，不仅能下锅作为煎烤高热量食材的高级油脂，抹在粗硬干瘪的面包上更是能让人感动落泪的美味。",
        en = "A pale, rich block of churned raw milkfat smelling strongly of fresh dairy cream. Providing concentrated cooking fat for campfire frying pans, slathering it over stale hardtack provides pure, calorie-dense comfort.",
    },
    ["raw_cured_fatty_meat"] = {
        zh = "经过整整一周盐渍与风干入味的一大块五花肉。肥瘦相间的肉层在食盐的作用下变得紧实暗红，肥膘晶莹剔透，虽然还是生肉不能直接生吞，但切片下锅煎烤时溢出的油脂香气能飘散半条街。",
        en = "A thick slab of pork belly cured under heavy salt and spices for a week. Rendered firm and translucent by the preservation process, frying savory ribbons over a fire releases an aroma intoxicating to starving survivors.",
    },
    ["raw_cured_meat"] = {
        zh = "经过厚盐彻底腌渍杀菌与脱水处理的生腌肉块。肉质收紧呈现深沉的绛红色，内部水分已大幅减少以抑制细菌滋生，只要挂在阴凉通风处继续风干，就能成为长途探险时永不变质的肉干口粮。",
        en = "A solid cut of red meat that has completed full salt curing. Firm and deeply crimson from moisture loss, it resists bacterial spoilage and hangs ready for smoking or long-term cellar storage against famine.",
    },
    ["raw_curing_fatty_meat"] = {
        zh = "表面抹满粗海盐与黑胡椒粒、正在盆中经历漫长脱水腌制过程的生猪五花肉。由于生产流程已迭代为动态计时逻辑，这块残留旧标记的腌肉仿佛被冻结在时间夹缝中，等待被替换为正规产物。",
        en = "A slab of pork belly packed in curing salts and peppercorns, caught in legacy recipe data structures. Frozen in temporal limbo by older engine flags, it simply awaits transition into modern active curing items.",
    },
    ["raw_curing_fatty_meat_active"] = {
        zh = "正埋在厚厚粗盐堆中缓慢排出多余水分与血水的生五花肉。盐分正在向肌肉纤维内部深层渗透，散发着独特的腌腊香气，耐心等待计时结束，就能收获一块耐储的高热量腊肉。",
        en = "A cut of fresh fatty pork actively undergoing osmotic dehydration beneath a blanket of curing salt. Brine draws outward daily, driving preservative nitrates deep into tissues to forge durable, high-calorie cured bacon.",
    },
    ["raw_curing_meat_active"] = {
        zh = "正处于一周盐腌周期当中的生兽肉块。表面覆盖着粗盐结晶与渗出的暗红卤水，微生物活性被高渗透压彻底锁死，只要不被雨水浸泡，时间就会将容易腐烂的生肉雕琢成坚韧耐存的口粮。",
        en = "Raw game meat nestled inside coarse salt crystals, actively progressing through its week-long cure. Osmotic pressure halts decay, transforming perishable muscle tissue into shelf-stable provisions that defy the march of rot.",
    },
    ["raw_dandelion"] = {
        zh = "刚从避难所墙角绿地连根拔起的一小捧鲜黄蒲公英。嫩叶虽略带微苦但富含维生素C，金黄的花瓣更是可以直接丢进开水冲泡成清香野茶，是末日初春防止坏血病的最廉价良药。",
        en = "A bundle of freshly plucked yellow dandelions with jagged green leaves. The slightly bitter greens supply critical vitamin C against scurvy, while steeping the bright blossoms in boiling water brews refreshing wilderness herbal tea.",
    },
    ["raw_demihumanleather"] = {
        zh = "从类人亚人变异体身上剥离下来的未鞣制生皮。皮质表面还残留着粗糙的毛孔与油脂，散发着令人极度不适的气味，在废土制革架上加工它需要极大的心理承受力。",
        en = "Uncured hide peeled from slain demihuman mutants. Still retaining coarse follicles and gamey grease, scraping and tanning this skin on survival racks demands formidable moral dissociation.",
    },
    ["raw_edamame"] = {
        zh = "一小把包裹在毛茸茸豆荚里尚未成熟的青大豆鲜毛豆。豆荚表面覆着一层细密绒毛，不能生吃，但在小铁锅里加一把粗盐连荚煮熟，剥出豆粒就是越嚼越香的高蛋白下酒小菜。",
        en = "Fuzzy green pods encasing tender, immature soybeans. Inedible raw due to bitter enzymes, boiling the whole pods in salted water yields tender emerald beans packed with complete plant protein and comforting nutty flavor.",
    },
    ["raw_fur"] = {
        zh = "从毛皮兽类身上小心剥下并整齐折叠起来的未鞣制生毛皮。虽然内侧还残留着少许油脂和血丝需要刮除防腐，但茂密厚实的天然毛绒，是缝制全套御寒大衣与防冻手套的无价原料。",
        en = "A carefully peeled pelt harvested from a fur-bearing wild mammal. Requiring scrape-fleshing and salt-tanning before it putrefies, its dense underfur represents an irreplaceable natural barrier against deadly sub-zero winter temperatures.",
    },
    ["raw_hfur"] = {
        zh = "从变异长毛人类或毛人身上割取剥离下的未经处理多毛皮张。上面密布着粗糙卷曲的毛发，触感令人反胃作呕，虽然能像普通毛皮一样鞣制成衣服，但穿上它需要彻底抛弃残存的道德良知。",
        en = "A pelt harvested from a mutated, fur-covered humanoid corpse. Morally horrifying and covered in wiry mammalian hair, scraping and tanning it into clothing signals the absolute erosion of your lingering civilized humanity.",
    },
    ["raw_hleather"] = {
        zh = "从人类遇难者身上完整剥离下来的未经鞣制生人皮。手感光滑惨白且散发着令人毛骨悚然的血腥气息，在丧失理智的边缘狂信徒聚集地，这种禁忌材料常常被用来缝制亵渎的皮具与灯罩。",
        en = "A gruesome hide peeled from a deceased human traveler. Clammy and morally abhorrent, depraved raiders and deranged cultists tan this taboo material into grotesque leather vests, proudly displaying their monstrous inhumanity.",
    },
    ["raw_leather"] = {
        zh = "从大型猎物身上剥离、精心折叠好的新鲜生兽皮。皮质厚重韧性十足，只要用钝刀刮净内侧结缔组织并用油脂或单宁酸充分鞣制，就能制成坚不可摧的皮甲、战术皮靴和背负枪套。",
        en = "A heavy raw hide flayed from a large woodland creature. Once scraped free of subcutaneous gristle and thoroughly tanned with wood ash or tannins, it yields tough, pliable leather suitable for rugged boots and armor.",
    },
    ["raw_tainted_fur"] = {
        zh = "从不可名状变异怪物残骸上剥下来的带毛畸变皮张。毛发呈现出不自然的荧光斑块且散发着令人头晕目眩的刺鼻异味，虽然带有致命的黑血污染，但耐酸耐热的特殊结构让工匠又爱又恨。",
        en = "A patchy, mutated pelt sliced from an unnatural Nether monstrosity. Emitting a chemical stench and bearing disquieting luminescence, it harbors vile pathogens yet provides weirdly resilient fibers for reckless leatherworkers.",
    },
    ["raw_tainted_leather"] = {
        zh = "从被未知异界能量污染的丧尸或憎恶巨怪身上剥取的恶心生皮。表面生有诡异的角质瘤与粘液孔，虽然触摸它令人反胃且极易引发感染，但在缺乏正常猎物的焦土上，它是唯一的生皮来源。",
        en = "A thick hide flayed from a necrotic monstrosity, studded with slimy keratinous tumors. Handling its foul, pathogen-slick surface turns the stomach, but desperate scavengers process it into crude defensive garments when all clean game has perished.",
    },
    ["raw_tainted_leather_scraps"] = {
        zh = "从各种异界变异生物身上碎裂剥落的污损生皮碎屑。每一小块边缘都参差不齐且沾染着发黑发臭的体液，无法整张利用，但经过强力沸水漂洗与化学脱水后，能凑出拼补护甲的胶质原料。",
        en = "Torn scraps of contaminated skin sliced from unnatural horrors. Far too ragged for tailoring complete jackets, patient survivors boil and bleach these festering remnants to extract sticky glues and patchwork armor repairs.",
    },
    ["razor_blade"] = {
        zh = "薄如蝉翼、两面开刃的超锋利双刃安全刮胡刀片。极度锋利且金属极薄，在手里宛如手术刀般危险，既能用来精细裁切皮料和拆解电线，也是在近身纠缠中神不知鬼不觉切断敌人颈动脉的暗器。",
        en = "A paper-thin double-edged safety razor blade made of surgical steel. Excelling at delicate suture-slicing and wire-stripping tasks, it also doubles as a vicious close-quarters weapon that can be hidden inside a closed fist.",
    },
    ["razor_blade_taped"] = {
        zh = "用一层结实黑胶布紧紧包裹住一侧开刃边缘的自制指间刀片。胶布包裹的一侧保证持握时不会划伤自己的手指，外露的另一侧依然寒光凛凛，是阴暗监牢或废墟搜刮时极具欺骗性的自卫暗器。",
        en = "A double-edged razor blade with one cutting edge muffled under heavy friction tape. Protecting your fingertips from accidental self-laceration, it provides a concealed palm scalpel for slit-throat escapes from predatory raider captors.",
    },
    ["razor_shaving"] = {
        zh = "安装在人体工学弧形握把上的双刃手动剃须刀。重心平衡手感舒适，在没有电力的卫生间里就着冷水和肥皂，刮去满脸杂乱邋遢的胡须，能让在泥沼中挣扎的幸存者重新找回作为人类的体面与尊严。",
        en = "A safety razor seated atop a comfortable, knurled metal handle. Scraping away bristly facial hair with cold water and lather restores a shred of civilized human dignity after weeks of crawling through muddy irradiated trenches.",
    },
    ["razorclaw_roe"] = {
        zh = "从凶狠的异变剃刀爪怪体内完整取出来的一整团半透明异种卵。卵粒紧密黏连且带有淡淡荧光，散发着海腥与微咸的奇特气味，虽然直接吃可能引起肠胃抽搐，但煮熟后却是极其奢华的末日鱼子酱。",
        en = "A cluster of translucent eggs harvested from a slain razorclaw monstrosity. Emitting faint bioluminescence and an intense marine funk, cooking these alien roe grains produces a surprisingly decadent and protein-dense delicacy.",
    },
    ["rc_car_box"] = {
        zh = "一个外观印刷着炫酷遥控越野赛车图案的彩印硬纸盒。虽然原本装载的小车早不知所踪，但厚实硬纸板和结实封底让它成为收纳螺栓、电阻原件或火柴盒的绝佳防尘小箱，还能当作引火纸壳。",
        en = "A glossy cardboard retail box decorated with vibrant illustrations of a radio-controlled buggy. Devoid of its mechanical contents, the sturdy cardboard container neatly stores loose electronic resistors, primers, or dry kindling.",
    },
    ["rdb_223"] = {
        zh = "采用向下抛壳设计的 5.56x45 毫米无托半自动步枪。全长紧凑却拥有完整的全尺寸枪管，向下飞出的灼热弹壳绝不会烫伤射手的脸颊，是狭窄建筑内部搜索与清理怪物的理想主武器。",
        en = "A 5.56x45mm semi-automatic bullpup rifle featuring downward case ejection. Compact yet retaining full barrel ballistics, ejected brass empties harmlessly at your boots rather than searing your cheek during intense room-clearing breaches.",
    },
    ["reading_light"] = {
        zh = "可直接夹在书页或头盔帽檐上的微型 LED 阅读小夹灯。目前处于关闭状态，仅消耗一颗纽扣电池，小巧隐蔽，是深夜躲在被窝或掩体深处研读机密手册时不会引来尸群的温柔光源。",
        en = "A tiny clip-on LED reading light clamped to paperback covers. Powered down for now, running on a single coin cell, it lets survivors study vital schematics beneath blanket forts without alerting prowling night horrors.",
    },
    ["reading_light_on"] = {
        zh = "正在散发柔和聚焦光束的夹式 LED 阅读灯。光斑被严格限制在面前展开的书页方寸之间，既能让你在伸手不见五指的地道中专心研读配方，又将侧向漏光压缩到了几乎无法察觉的极限。",
        en = "A switched-on clip-on LED reading lamp illuminating page margins with pinpoint brilliance. Confining glare to book pages, it allows scavengers to decode survival manuals deep underground without casting telltale shadows across windows.",
    },
    ["rebar"] = {
        zh = "从倒塌混凝土承重柱中暴力撬出来的一根粗重螺纹钢筋。表面布满防滑肋纹与风化红锈，质感沉重且坚不可摧，在手里挥舞起来呼呼作响，是敲碎丧尸天灵盖与粗加工锻造的废土硬通货。",
        en = "A jagged length of heavy ribbed construction rebar pried from pulverized concrete pillars. Dense, rusted, and indestructible, it crushes mutant skulls like ripe melons or gets forged into rugged blacksmith chisels.",
    },
    ["rebar_plate"] = {
        zh = "用多根粗螺纹钢纵横交叉焊接而成的坚固钢筋网格板。结构粗犷且通透通风，既能直接焊在车辆车窗外作为防抓咬防暴铁栅栏，也能铺设在深坑上方作为阻挡大型变异生物的战术陷阱盖。",
        en = "A heavy grate welded from intersecting lengths of ribbed steel rebar. Heavy and rigid, mechanics weld it across vehicle windshields as anti-grab screens or brace it over pitfalls to snare oversized mutated brutes.",
    },
    ["rebreather"] = {
        zh = "覆盖口鼻与喉部的封闭式循环呼吸器面罩。在未装入吸收净化罐时处于待机状态，一旦装配完整滤毒系统，就能在完全隔绝外界毒气与缺氧水下环境中实现人体呼吸气体的闭环循环再利用。",
        en = "A close-fitting silicone oral-nasal rebreather mask awaiting scrubbing canisters. Once properly configured with gas tanks and chemical filters, it recycles exhaled breath inside oxygen-depleted sewers and toxic spore clouds.",
    },
    ["rebreather_cartridge_air"] = {
        zh = "配有压缩空气微型气瓶与二氧化碳吸收过滤材料的循环呼吸面罩替换滤罐。能将呼出的废气中的二氧化碳高效过滤并补充压缩空气，为深入有毒下水道搜刮的探险家提供宝贵的新鲜空气。",
        en = "A replacement rebreather scrubber canister bundled with an integrated mini compressed air cylinder. Scrubbing metabolic carbon dioxide while metering ambient air, it sustains respirations inside poisonous subways and suffocating chemical plumes.",
    },
    ["rebreather_cartridge_o2"] = {
        zh = "集成了高压纯氧气瓶与超高密度二氧化碳吸收剂的高级循环呼吸滤罐。体积小巧且供氧纯度极高，能在长达数小时的剧烈潜水或深入生化污染核心区作战中，保证大脑获得最充沛的氧气供应。",
        en = "A high-performance rebreather canister incorporating a medical-grade pressurized oxygen reservoir and dense chemical scrubbers. Yielding exceptional operational endurance, it keeps divers and hazard operators oxygenated through protracted biohazard sweeps.",
    },
    ["rebreather_cartridge_regen"] = {
        zh = "利用超氧化物化学反应实现二氧化碳吸收与氧气自主再生的特种生氧呼吸罐。无需沉重的外置高压氧气瓶，只要人体呼出的湿润二氧化碳接触药剂，就会自发释放纯净氧气，军工黑科技杰作。",
        en = "An advanced chemical oxygen-regenerator canister operating without bulky compressed gas cylinders. Exhaled moisture and carbon dioxide react directly with chemical salts, spontaneously liberating breathable oxygen through purely passive chemical conversion.",
    },
    ["rebreather_filler_ko2"] = {
        zh = "密封在防潮铁桶中的高纯度超氧化钾化学药粉。遇水和二氧化碳会剧烈反应并释放出大量氧气，是重新装填化学氧气再生呼吸罐的核心反应药剂，受潮时极具腐蚀性与自燃危险。",
        en = "A sealed canister of dry potassium superoxide powder used for refilling rebreather cartridges. Reacting vigorously with moisture to produce oxygen while sequestering carbon dioxide, it demands cautious handling to avoid caustic burns.",
    },
    ["rebreather_filler_soda_lime"] = {
        zh = "由熟石灰与少量氢氧化钾配制而成的多孔二氧化碳吸收碱石灰颗粒。带有遇饱和变色的指示剂，是给循环呼吸器滤罐更换失效吸附滤料的基础化学物资，能彻底吸附呼出的二氧化碳。",
        en = "A container of granular soda lime formulated to sequester exhaled carbon dioxide. Impregnated with dye indicators that turn purple upon chemical exhaustion, it allows scavengers to repack expired rebreather scrubbers safely.",
    },
    ["rebreather_on"] = {
        zh = "正在嗡嗡工作运转的封闭式循环呼吸面罩。单向呼气阀发出轻柔而富有节奏的吸气咔哒声，完全阻隔了外界刺鼻的死尸腐臭、致死孢子与氯气烟雾，让你在致命毒气区如入无人之境。",
        en = "An active closed-circuit rebreather humming softly with each respiration cycle. Rhythmic check-valves click cleanly as internal scrubbers strip toxins, granting invulnerability against billowing tear gas and suffocating fungal spore swarms.",
    },
    ["rebreather_xl"] = {
        zh = "专为大体型幸存者或头部变异面孔设计的加大码循环呼吸面罩。硅胶裙边宽厚柔软，目前处于关闭待机状态，即便是生有粗壮下颌骨或厚重角质层的脸型，也能严丝合缝地实现气密贴合。",
        en = "An oversized rebreather facepiece engineered for broader head profiles and heavy mutant jawlines. Awaiting active filters, its expanded elastomeric seal conforms comfortably around protruding facial mutations without leaking toxic ambient fumes.",
    },
    ["rebreather_xl_on"] = {
        zh = "正在开启通气的大码循环呼吸面罩。加宽的硅胶密封条紧紧贴合在生有外骨骼或厚重皮肤的面颊上，内部循环回路平稳供氧，让大块头幸存者也能在浓烟毒雾中尽情冲锋陷阵。",
        en = "An active XL rebreather securely sealing over bulky facial mutations. Its heavy-duty valves deliver smooth, recycled air, ensuring hulking mutated scavengers breathe freely while battering through fiery chemical infernos and flooded chambers.",
    },
    ["rebreather_xs"] = {
        zh = "专为小巧脸型或骨架轻盈幸存者裁剪的特小码循环呼吸面罩。目前处于待机未装滤罐状态，贴面边缘非常紧凑，不会因为面罩过大而导致剧烈跑跳时发生滑脱漏气。",
        en = "A compact extra-small rebreather mask designed for slender jawlines and petite survivors. Dormant for now, its trimmed sealing flange avoids sloppy gaps, preventing fatal leakage during desperate sprints through noxious sewer ducts.",
    },
    ["rebreather_xs_on"] = {
        zh = "正在开启运转的小号循环呼吸面罩。极其贴合的面部弧度在剧烈战术规避时依旧密封如初，为小巧敏捷的潜行侦察兵源源不断地提供纯净循环气体，静默无声且毫无外泄气泡。",
        en = "An active extra-small rebreather operating in complete silence. Hugging slender facial contours tightly without restricting peripheral vision, it pumps fresh oxygen into a stealth scout's lungs during hazardous underground infiltration runs.",
    },
    ["receiver"] = {
        zh = "集成了多频段解调芯片的高灵敏度无线电信号接收器模块。从长波、短波到微波频段皆能解析，是电子工坊改装无人机图传天线、远程无线引爆器或避难所全频段预警雷达的核心信号处理中枢。",
        en = "A high-sensitivity multi-band radio receiver module salvaged from communications equipment. Demodulating broad frequency spectrums, it forms the electronic core for custom surveillance monitors, automated proximity alarms, and remote radio triggers.",
    },
    ["recharge_station"] = {
        zh = "带有多种智能快充插口与通用电压转换电路的车载通用充电基座。安装在改装战车或发电机母线上，能以极高效率同时为战术手电、动力外骨骼电池包与电子工具快速补能，绝地续航保证。",
        en = "A heavy-duty universal recharging station wired with multi-voltage balance leads. Bolted onto vehicle battery banks or bunker generators, it tops off depleted tool cells, thermal cameras, and exoskeleton batteries rapidly.",
    },
    ["recipe_alpha"] = {
        zh = "标有绝密代号 PE050 阿尔法计划的绝密实验初步报告装订册。纸张边缘泛黄，详细记录了通过基因改造培育出具有超人智力与肉体协调性的全能人类诱变剂配方，读来令人心潮澎湃。",
        en = "A classified scientific dossier detailing Project Alpha mutation trials. Outlining initial formulas for mutagens that elevate human physiology to peak athletic perfection, these archived lab notes outline the blueprint for synthetic transhuman evolution.",
    },
    ["recipe_animal"] = {
        zh = "迪奥娜科研小组遗留的变异生物诱变剂实验日志。封皮沾着陈旧发黑的兽血痕迹，密密麻麻的手写笔记记录了数百次利用哺乳动物基因诱变受试者的残酷实验流程，字里行间透着学术狂热。",
        en = "A stained team logbook penned by lead researcher Dionne. Documenting hundreds of volatile mammalian mutagen infusions and grotesque anatomical transitions, these detailed journal entries reveal the exact chemical ratios for beastly transmutations.",
    },
    ["recipe_arrows"] = {
        zh = "一本厚实详尽的传统制箭师之友手工指南。书中图文并茂地讲解了从选材削杆、打磨石质与铁质破甲箭头、到精准劈裂火鸡羽毛绑缚箭翎的全套工艺，是荒野弓箭手自给自足的圣经。",
        en = "A thick instructional manual titled The Fletcher's Friend. Crammed with woodcutting schematics and feather-fletching guides, it teaches patient archers how to balance cedar shafts and glue armor-piercing steel bodkins from salvage.",
    },
    ["recipe_atomic_battery"] = {
        zh = "从核工业研究中心终端打印出来的一张打孔计算机数据单。看似杂乱无章的工程代码背面，手写密注着如何将微量放射性同位素安全灌封进长寿命原子能贝塔电池的绝密组装工艺。",
        en = "A folded dot-matrix computer printout scribbled with technical schematics. Decoding its dense alphanumeric logs reveals classified manufacturing procedures for assembling long-lasting betavoltaic atomic batteries from spent radioactive isotopes.",
    },
    ["recipe_augs"] = {
        zh = "名为《工业机器人在现代制造业中的应用》的厚重精装技术书籍。虽然封面看似枯燥的自动化教科书，后半部分却详细拆解了高精度伺服电机与神经义肢接口的装配代码与制造工艺图。",
        en = "A hefty technical volume exploring robotic automation in heavy industry. Beyond dry manufacturing theory, its schematics teach engineers how to machine precision servomotors and calibrate neurological feedback loops for custom bionic implants.",
    },
    ["recipe_bows"] = {
        zh = "名为制弓大师指南的大型实用户外手工技术书。用大量铅笔手绘草图详细演示了如何伐木选材、蒸煮木料弯曲成型、并在硬木弓背上复合铺设动物肌腱与生角，教你纯手工打造大威力反曲弓。",
        en = "An exhaustive bowyer's compendium filled with meticulous woodcraft sketches. Covering steam-bending, horn-backing, and sinew-lamination techniques, studying its pages allows survivors to craft magnificent recurves capable of felling charging bears.",
    },
    ["recipe_bullets"] = {
        zh = "枪械发烧友与复装老手人手一本的《手工复装指南》。书中巨细靡遗地罗列了数十种口径弹药的火药克数、弹头压入深度与底火选型对照表，是废墟中利用残存材料自制子弹的救命宝典。",
        en = "A heavily dog-eared reference guide titled The Handloader's Helper. Detailing chamber pressures, grain weights, and bullet seating depths for dozens of calibers, it is the definitive manual for hand-pressing ammunition from scrap.",
    },
    ["recipe_caseless"] = {
        zh = "封面盖有未经授权阅读者将遭致命安保处置鲜红警示章的里夫泰克机密活页夹。内部详尽记载了高燃无壳弹药成型工艺与磁电点火机理，是制作高射速先进无壳枪械弹药的绝密蓝图。",
        en = "A classified Rivtech engineering binder stamped with lethal security warnings. Unraveling its proprietary chemical equations reveals the high-tech secrets behind molding solid-propellant caseless ammunition for advanced military firearms.",
    },
    ["recipe_chimera"] = {
        zh = "代号 PE065 奇美拉计划的极端变异最佳实践报告散页。记录了一系列将昆虫、掠食兽与爬行动物基因极端拼合的恐怖实验配方，服用这种诱变剂能让肉体变异为暴虐狂暴的战争绞肉机。",
        en = "Scattered confidential project sheets detailing Project Chimera mutagen trials. Combining predatory beast, insectoid, and reptilian DNA, following its recipes transforms your fragile human biology into a horrifying, ravenous multi-limbed engine of destruction.",
    },
    ["recipe_creepy"] = {
        zh = "斯迈思博士团队遗留的一本散发着发霉恶臭的地下实验日志。字迹在后期变得极其狂乱甚至伴有血手印，记录了如何提取深渊蠕虫与节肢变异体基因来合成令人毛骨悚然的异形变异药剂。",
        en = "A damp, odor-stained research journal kept by Dr. Smythe. As legible notes degenerate into deranged glyphs and dried blood smears, it details protocols for brewing chitinous, writhing insectoid mutagens from underworld specimens.",
    },
    ["recipe_dave_manual"] = {
        zh = "用硬纸板外壳简易装订的恐龙戴夫手写生存笔记。虽然笔触稚嫩且画满了滑稽恐龙涂鸦，但里面居然极其严肃地记录了利用废旧电磁炉与微波炉磁控管自制大威力电浆喷枪的奇葩天才改装法。",
        en = "A cardboard notebook scrawled by an eccentric tinkerer named Dino Dave. Filled with whimsical dinosaur sketches, it surprisingly contains brilliant, fully functional blueprints for repurposing microwave magnetrons into devastating homemade plasma weapons.",
    },
    ["recipe_elfa"] = {
        zh = "一本标注着供水竖管系统例行维护规程的厚硬壳活页夹。虽然前面上百页全是有害废液管道阀门检查单，但在附录技术注记中，居然记载了某种利用高压离心泵提纯神秘生化发光液体的配方。",
        en = "A heavy facilities binder cataloging scheduled maintenance for municipal water standpipes. Hidden behind mundane plumbing schematics are scribbled annex notes outlining precise methods to refine mysterious bioluminescent fluids using high-pressure pumps.",
    },
    ["recipe_fauxfur"] = {
        zh = "一本名为友好人道时尚的环保教育图册。生动详细地介绍了如何利用废弃化纤衣物、晴纶毛毯和聚酯聚合物拉丝热压制成手感逼真的人造皮草，在没有猎杀兽皮时依然能手工缝制保暖毛皮装。",
        en = "An illustrated instructional book promoting synthetic cruelty-free textile crafts. Providing step-by-step methods to melt and spin discarded polyester blankets into fluffy faux fur, it keeps survivors warm without hunting woodland mammals.",
    },
    ["recipe_lab_cvd"] = {
        zh = "古斯塔夫工程师遗留的技术日志笔记本。前面大部分都是枯燥的真空泵维护与压力读数，中间核心章节详细记录了如何搭建化学气相沉积 CVD 反应炉、在普通钢刃表面镀上高硬度金刚石膜的技术。",
        en = "A dog-eared laboratory journal kept by materials scientist Gustav. Skipping past endless vacuum chamber logs reveals invaluable industrial blueprints for operating chemical vapor deposition furnaces to coat steel blades in diamond crystal.",
    },
    ["recipe_lab_elec"] = {
        zh = "埃雷拉高级电气工程师遗留下来的加厚工作活页夹。里面塞满了极其复杂的电路图、高压变压器绕线规格表以及如何将车载储能电容改装为大威力EMP电磁脉冲发射器的绝密硬核方案。",
        en = "A bulky technical binder assembled by electrical specialist Herrera. Densely packed with wiring schematics and transformer windings, it explains how to wire vehicular battery arrays into devastating wide-band electromagnetic pulse generators.",
    },
    ["recipe_labchem"] = {
        zh = "盖有绝密机密红章的高级工业化学反应参考指南。用严密的化学方程式推导了硝化甘油、黑索金高爆炸药以及各类强腐蚀性超强酸的合成路径，稍有配比差错就会把整个避难所送上西天。",
        en = "A restricted reference manual stamped with classified security warnings. Outlining rigorous reaction pathways for synthesizing high-grade military explosives and industrial acids, a single miscalculated titration within its pages could level your shelter.",
    },
    ["recipe_maiar"] = {
        zh = "封面被严重烧焦且撕去研究人员姓名的神秘实验日志。破损纸页间残留着关于神经突触超导突变与以太能量共振的诡异笔记，照此调配出的诱变剂能诱发超自然的能量感知与幽能风暴变异。",
        en = "A charred team logbook with deliberately excised author credentials. Fragmented notes describe neural synaptic superconductivity and aetherial resonance, allowing daring alchemists to synthesize exotic serums that trigger supernatural psionic mutations.",
    },
    ["recipe_medicalmut"] = {
        zh = "标有 PE023 医疗计划应用与发现的绝密医学报告活页夹。详细阐述了如何利用特定诱变成分极速激活人体休眠干细胞，使重伤骨折与坏死内脏在几天内奇迹自愈，是末日医官梦寐以求的神书。",
        en = "A confidential medical dossier summarizing Project Medical clinical trials. Detailing mutagen formulas designed to hyper-accelerate cellular regeneration and knit fractured bones within hours, it is the ultimate pharmacological treasure for battlefield doctors.",
    },
    ["recipe_melee"] = {
        zh = "名为《街头霸王助手》的大开本手绘近战自卫指南。图文并茂地教授如何将废铁管、齿轮与链条改装成带倒刺的致命流星锤与狼牙棒，招招阴毒下流，专门传授给在巷战泥潭里挣扎求生的幸存者。",
        en = "A gritty underground survival guide titled The Streetfighter's Sidekick. Crammed with vicious hand-drawn diagrams, it shows how to assemble spiked cudgels, lead pipes, and weighted flails specifically engineered for brutal close-quarters alley brawling.",
    },
    ["recipe_migo_plate"] = {
        zh = "代号 WX010 的米戈活体护甲观察记录散页。用惊悚的文字记录了米戈异形活体生物装甲的角质外壳再生周期与维护流程，教你如何利用外星生物黏液和几丁质碎片拼合出具有活性防御力的活体甲胄。",
        en = "Field observation notes documenting extraterrestrial Mi-Go living carapace specimens. Deciphering these unsettling biology records allows brave armorers to graft living chitin plates and alien secretions into resilient organic body armor.",
    },
    ["recipe_mil_augs"] = {
        zh = "双科工业集团标有绝密等级的 2XI 军用生化义体设计活页夹。上面详细标示了微型聚变电池接口与皮下皮质防弹装甲植入体的神经吻合技术，是让凡人肉身飞升为钢铁终结者的终极蓝图。",
        en = "A classified DoubleTech Industries military binder detailing 2XI cybernetic designs. Containing blueprints for subcutaneous subdermal armor plates and neural-integrated bionic actuators, it offers the ultimate roadmap for transforming flesh into war machinery.",
    },
    ["recipe_raptor"] = {
        zh = "代号 PE070 猛禽计划的绝密立项提案草案。纸张上盖有未获批准的朱红水印，详细设想了通过融合猛禽掠食基因赋予人类夜视双眼、极速奔跑足弓与撕裂爪刃的完整诱变配方，野心勃勃。",
        en = "A speculative project proposal outlining Project Raptor mutagen protocols. Stamped with red experimental marks, it outlines formulas to engineer avian eyesight, hyper-agile talons, and lightweight aerodynamic bone densities into the human frame.",
    },
    ["recipe_serum"] = {
        zh = "名为《生化化合物靶向输送最佳实践》的研究所内部手册。不仅系统对比了皮下注射、静脉滴注与血清浓缩纯化工艺，更是教你如何把粗制诱变剂提纯为零副作用的终极浓缩血清的决定性指南。",
        en = "An internal pharmaceutical handbook addressing advanced compound delivery. Outlining centrifugation, ultra-purification, and chemical binding agents, it teaches scavengers how to refine volatile crude mutagens into permanent, highly stable genetic serums.",
    },
    ["reciprocating_saw"] = {
        zh = "采用大容量锂电池驱动的手持式电动往复锯。安装金属锯条后能以惊人的往复频率强力切断钢管、车辆防撞梁甚至坚硬的挂锁，是拆解车辆残骸与破拆金属防护门的工业级暴力利器。",
        en = "A heavy-duty cordless reciprocating saw powered by rechargeable tool packs. Snapping in bi-metal blades lets its rapid reciprocating stroke slice through hardened padlocks, structural rebar, and vehicle roll cages with ferocious speed.",
    },
    ["recoil_stock"] = {
        zh = "内置高强度阻尼弹簧与液压缓冲柱的枪械后坐力吸收枪托。安装在重型步枪或霰弹枪后部，射击瞬间能吸收大部分原本砸在肩膀上的狂暴后坐力，极大缓解长时间连发射击导致的锁骨淤青。",
        en = "A mechanical replacement buttstock incorporating internal dampening springs and hydraulic buffers. Soaking up punishing recoil impulses from high-powered calibers, it keeps sights aligned and protects shoulders during rapid continuous fire.",
    },
    ["recon_mech_laser"] = {
        zh = "专为轻型侦察外骨骼机甲定制的集成式激光精确射击系统。直接连接机甲动力电池组，能以光速射出烧蚀金属护甲的致命相干光束，射击无声无息且弹道绝不受重力与风偏影响，顶级杀器。",
        en = "An integrated directed-energy laser rifle hardwired into RMES reconnaissance exoskeletons. Drawing raw electrical current straight from chassis reactor banks, its silent coherent beams burn pinpoint holes through armor without bullet drop.",
    },
    ["recon_mech_laser_single"] = {
        zh = "从损毁的侦察机甲上完整拆解下来的军用精确射手激光发射模块。高能光束聚焦透镜虽然沾满机油，但接通高压电池后依然能发射出瞬间灼穿装甲的死亡光束。",
        en = "A salvaged marksman laser assembly extracted from downed reconnaissance mechs. Its optical lenses remain intact, focusing high-voltage battery discharges into instant armor-vaporizing beams over extreme engagement distances.",
    },
    ["record_accounting"] = {
        zh = "一本厚重的商业公司财务做账账本。里面密密麻麻记录着大灾变前各部门的报销凭证与虚假账目，虽然数字毫无意义，但撕下这数百页干燥优质的纸张，是上厕所擦拭或点燃篝火的顶级引火纸。",
        en = "A bound corporate accounting ledger crowded with forgotten corporate audits and petty tax filings. While financial ledgers are worthless in the ruins, its heavy wood-free pages make exquisite dry kindling or dependable hygiene paper.",
    },
    ["record_patient"] = {
        zh = "从大型综合医院档案库搜刮出的一大叠厚重病历治疗记录。里面记录了大量患者在灾变初期的诡异生理病变特征与抗生素试药反应，仔细研读能让荒野医生掌握大量宝贵的临床诊断经验。",
        en = "A thick folder of archived hospital clinical patient records. Documenting early physiological mutation symptoms and antibiotic reactions during the initial outbreak, reviewing these clinical logs sharpens medical diagnosis skills for apocalyptic medics.",
    },
    ["record_weather"] = {
        zh = "印着国家气象局官方印章的陈旧气象观测历史记录汇编。上面满是各个季度的降雨量曲线与台风气压图表，虽然看似枯燥乏味，但纸质厚实干燥，非常适合揉软后当成擦枪纸或引火耗材。",
        en = "A dusty compilation of historic meteorological transcripts published by the National Weather Service. Though historical barometric charts offer zero survival tactical value, their dry pages serve admirably as gun-cleaning swabs or campfire fuel.",
    },
    ["recovery_pump"] = {
        zh = "原本用于空调制冷剂回收的中型无油真空泵。耐压性与抽吸密封性极佳，在末日实验室中常被用来改装闭环溶剂蒸馏系统、回收易燃化学挥发物，防止有毒蒸气积聚引发剧烈爆炸。",
        en = "A medium-sized oil-less refrigerant recovery pump salvaged from HVAC workshops. Providing durable vacuum seals, it allows chemists to recover volatile distillation solvents safely without risking toxic atmospheric vapor buildups.",
    },
    ["recurbow"] = {
        zh = "采用现代玻璃纤维与碳纤维压层复合制成的反曲弓。弓臂末端优雅向前翻卷，能在较短拉距下爆发出惊人的箭矢初速与穿透力，重量轻便且完全不受雨水浸泡影响，是荒野猎手的完美无声利器。",
        en = "A modern recurve bow crafted with fiberglass and carbon laminates. Its forward-curving limb tips impart tremendous initial arrow velocity and punch, delivering lethal silent shots in torrential rain without rotting like traditional wood.",
    },
    ["red_dot_sight"] = {
        zh = "装在枪械顶部皮卡汀尼导轨上的战术红点反射式瞄准镜。镜片上投射出一枚明亮的小红点，射手无需将眼睛、准星和照门排成一线，只要两眼睁开将红点套住目标即可果断扣动扳机快速命中。",
        en = "A non-magnified reflex optic projecting an illuminated red reticle onto a coated lens. Enabling rapid binocular target acquisition without lining up traditional iron sights, it speeds up snap-shooting against rapidly lunging infected predators.",
    },
    ["red_pen"] = {
        zh = "一支普通的红色一次性圆珠笔。大灾变前是教师批改试卷与财务核查赤字时的梦魇之笔，如今在地图上用鲜红墨水圈出高危变异巢穴或阵亡队友坐标时，依然散发着令人心惊肉跳的刺眼红光。",
        en = "A standard red disposable ballpoint pen. Once the dread of errant schoolchildren and over-budget accountants, drawing crimson circles around mutant nests and lethal hazard zones on paper maps retains its ominous emotional gravity.",
    },
    ["red_pen_ink"] = {
        zh = "以曙红染料为主并加入成膜聚合物的高粘度红色笔用油墨。鲜艳如静脉热血且不易褪色，既能在自制羽毛笔或空笔芯中重新灌装，也能在紧急时刻当成显眼的红色标记颜料在水泥墙上涂写求救信号。",
        en = "A vial of viscous red ballpoint ink infused with eosin dye and resins. Resembling arterial blood, it refills empty pen cartridges or provides bright scarlet pigment for scrawling urgent distress warnings across concrete highway barriers.",
    },
    ["red_phosphorous"] = {
        zh = "装在棕色广口玻璃瓶里的深红色无定形红磷粉末。稳定性远高于致命的剧毒白磷，是火柴侧面摩擦引燃涂层的核心成分，更是某些绝命毒师和地下炸药工坊调配敏感起爆药与强力兴奋剂的关键原料。",
        en = "A sealed bottle of amorphous red phosphorus powder. Comparatively stable compared to pyrophoric white phosphorus, it coats matchbox strike plates and serves clandestine chemists synthesizing hair-trigger explosive primers or illicit stimulants.",
    },
    ["red_phosphorous_small"] = {
        zh = "从几十个废弃火柴盒侧面小心刮下来的一小撮红磷粉末碎屑。混有少量玻璃微粉与骨胶杂质，虽然份量微乎其微且收集过程极其考验耐心，但这一小撮粉末足以充当自制雷管极其珍贵的第一引燃药。",
        en = "A tiny pinch of red phosphorus dust patiently scraped from salvaged matchbox strike strips. Admixed with powdered glass and binders, this meager scraping is invaluable for priming homemade percussion caps when manufacturing fresh ammunition.",
    },
    ["red_winter_wheat_stalks"] = {
        zh = "一把刚从深秋农田里收割下来的硬红冬小麦麦秆。顶端麦穗饱满结实，麦芒尖锐硬挺，只要脱粒并用石磨磨碎，就是制作高筋面粉烤出松软面包的黄金谷物，麦秆还能用来编织草帽或垫窝取暖。",
        en = "A harvested sheaf of hard red winter wheat stalks. Heavy with golden grains, threshing and milling them between stones yields high-gluten flour for hearth loaves, while dry stalks provide insulating bedding for shelter cots.",
    },
    ["ree_33"] = {
        zh = "伊克索迪控制台设计的 3.3 毫米重型海军舰载半自动步枪。金属枪身极其粗壮厚重，发射带有脱壳穿甲弹芯的特种弹药，原本用于防御快艇与近海登舰战，巨大的后坐力需要稳固支架才能正常射击。",
        en = "A massive Exodii semi-automatic naval rifle chambered in high-velocity saboted 3.3mm rounds. Built to repel boarding craft, its punishing recoil necessitates mounting on heavy tripods to prevent dislocating a human marksman's shoulder.",
    },
    ["ree_33_4_mag"] = {
        zh = "容量仅为 4 发的 3.3 毫米伊克索迪海军步枪轻便弧形弹匣。做工沉重耐磨，虽然容弹量较少，但插在枪身侧面时重心紧凑，适合机动小组在转移阵地或遭遇零星变异海怪时进行快速精确射击。",
        en = "A heavy-duty curved 4-round box magazine designed for the Exodii 3.3mm naval rifle. While offering limited volume, its compact profile allows gunners to shoulder and reposition the heavy firearm without dragging along the ground.",
    },
    ["ree_33_53_mag"] = {
        zh = "整整装填 53 发高速穿甲弹的伊克索迪海军步枪巨型弹药箱。内部集成有柔性输弹导带，沉重得犹如一块金属铅砖，装上它能化身无情收割尸潮的固定炮台，但端着它奔跑几乎是不可能完成的任务。",
        en = "A colossal 53-round belted metal drum engineered for the Exodii naval rifle. Heavy as a granite tombstone, clamping it underneath turns the rifle into an impenetrable point-defense turret capable of mowing down entire hordes.",
    },
    ["ree_33_tripod"] = {
        zh = "专为承受大口径武器剧烈后坐力而设计的加重铸铁三脚架。三条支撑腿带有防滑地钉与双向微调手轮，能牢牢锚定在碎石地面上，彻底吸收巨型步枪的狂暴震颤，提供如同铁铸般的射击平台。",
        en = "A reinforced cast-steel combat tripod designed for the Exodii naval rifle. Spiked spade feet bite into concrete and gravel, absorbing ferocious recoil impulses to deliver pin-point bursts without shaking off line.",
    },
    ["ref_lighter"] = {
        zh = "配有经典铰链翻盖与滚轮火石的镀铬煤油防风打火机。单手咔哒一声甩开盖子并划燃火星，在强风中依然能燃起摇曳而稳定的黄色火苗，散发着好闻的煤油味，是硬派幸存者的浪漫随身物。",
        en = "A classic chrome-plated flip-top refillable fluid lighter with a flint striking wheel. Snapping open with a distinctive metallic clink, its windproof wick burns with an aromatic kerosene scent that keeps campfires lighting through rainstorms.",
    },
    ["ref_lighter_butane"] = {
        zh = "带有压电陶瓷点火与透明油窗的大号可充气丁烷打火机。按下扳机即可喷射出高温直冲蓝焰，不仅不易被狂风吹灭，还能从丁烷气罐多次注气续命，是野外烹饪与点燃导火索的省心利器。",
        en = "A heavy-duty refillable butane lighter equipped with a piezoelectric trigger and safety lock. Spitting a focused blue jet resistant to gales, it readily recharges from aerosol canisters to light stoves and fuses effortlessly.",
    },
    ["ref_lighter_on"] = {
        zh = "正处于点燃状态的翻盖煤油打火机。棉芯上的黄色火苗静静跳动，为阴冷的地下室带来一丝温暖微光，但也正在迅速蒸发昂贵的煤油储备，记得在手指被灼热金属烫伤前及时合上防风盖。",
        en = "A flicked-open fluid lighter burning with a dancing yellow flame. While shedding comforting warmth in freezing cellars, it drains volatile naphtha rapidly, demanding you snap the lid shut before the chimney burns your fingers.",
    },
    ["ref_matches"] = {
        zh = "一小盒带有粗糙侧面红磷摩擦面的安全火柴盒。只要轻轻一擦就能爆发出耀眼的硫磺火花与刺鼻烟雾，在没有打火机或电池没电的绝境中，这几十根小木棒就是生火取暖与驱散野兽的最后希望。",
        en = "A compact cardboard box of safety matches coated with coarse red phosphorus friction strips. Striking wooden splints generates brief bursts of sulfur and flame, offering primitive salvation when electronic igniters freeze or fail.",
    },
    ["reference_cooking"] = {
        zh = "精装厚重、堪比砖头的第四版《默克化学与烹饪实用大全》。从热力学分子重组到蛋白质变性深度解析了食材理化性质，读完能让你用发霉罐头、野草根和野兽内脏烹饪出米其林级别的安全大餐。",
        en = "A gargantuan hardbound reference manual combining industrial chemistry and gourmet food science. Demystifying enzymatic breakdown and protein denaturation, studying its pages teaches scavengers how to extract edible meals from dubious wilderness forage safely.",
    },
    ["reference_fabrication1"] = {
        zh = "被全球机械工程师奉为圣经的《机械工程手册》。里面密密麻麻印满了齿轮模数、螺纹公差、金属热处理曲线与车床切削参数，在这个文明断层的废墟上，只要读懂它你就能从零手搓出工业革命。",
        en = "A massive, thumb-indexed leather edition of Machinery's Handbook. Packed with screw tolerances, gear tooth geometries, and quenching curves, mastering its contents empowers apocalyptic machinists to reconstruct industrial civilization from twisted scrapyard junk.",
    },
    ["reference_firstaid1"] = {
        zh = "厚达数千页的全美内科医生案头参考手册。巨细靡遗地收录了所有处方药的禁忌症、过量解毒剂与创伤急救方案，是废弃药店搜刮时的无上藏宝图，能让你准确分清救命神药与剧毒死神。",
        en = "An exhaustive desk volume cataloging pharmaceuticals, contraindications, and emergency overdose protocols. Studying its exhaustive medical indices lets wilderness paramedics differentiate life-saving miracle antibiotics from lethal neurotoxins amidst looted hospital pharmacies.",
    },
    ["reference_firstaid2"] = {
        zh = "图文详尽的《默克兽医手册》。不仅覆盖了所有家畜的疫病防治与断肢缝合，其粗犷有力的止血与接骨外科手法在抗生素匮乏的末日，同样能以惊人成效直接套用在伤痕累累的人类幸存者身上。",
        en = "A thick reference guide detailing diagnostics and surgical interventions across domestic livestock. Its straightforward approaches to suturing trauma and splinting fractures translate remarkably well to saving battered human scavengers when human doctors are extinct.",
    },
    ["reflexbow"] = {
        zh = "由致密硬木、动物牛角片与背部牛筋复合粘合而成的轻型传统反曲复合弓。弓体紧凑且预应力惊人，拉满时爆发力极强，雨雪天需要悉心保养防止鱼鳔胶脱胶，是兼顾射速与威力的无声猎杀典范。",
        en = "A traditionally crafted composite recurve bow glued with horn strips, dense maple, and sinew fibers. Storing tremendous mechanical energy within a compact draw, it launches swift arrows silently, requiring careful waxing against damp weather.",
    },
    ["reflexrecurvebow"] = {
        zh = "采用轻量镁铝合金镂空握把与碳纤维弓片打造的奥运竞技级反曲弓。上面预留了大量平衡杆与瞄准器螺孔，拉感柔顺且射击震动极小，虽然在灌木丛中略显娇气，但百步穿杨的精度令人叹为观止。",
        en = "A precision Olympic target recurve bow engineered from machined aluminum and carbon-fiber limbs. Smooth on the draw and nearly vibrationless upon release, its incredible accuracy easily punches broadheads through distant zombie ocular cavities.",
    },
    ["refrigerant_tank"] = {
        zh = "装有压缩氟利昂或新型环保冷媒的小型加压钢罐。阀门密封完好，罐体带有安全防爆片，是组装车载车载空调、修复避难所食品冷库或者提取挥发性气体制备简易冷冻喷剂的不可或缺工业化工原料。",
        en = "A pressurized steel canister filled with compressed refrigerant gases. Essential for recharging automotive air conditioning compressors or restoring deep-freeze meat lockers, clever scavengers also bleed its icy expansion plumes to freeze mechanical padlocks brittle.",
    },
    ["rehydrated_chili"] = {
        zh = "将脱水干辣椒扔进开水重新浸泡泡胀的新鲜辣椒。褶皱的红皮重新吸饱了水分变得饱满多汁，辛辣刺鼻的辣椒素毫无衰减，切碎丢进毫无滋味的寡淡野菜汤里，能瞬间让人辣出浑身热汗驱散寒气。",
        en = "A wrinkled dried chili pepper restored to plump vitality after soaking in boiling water. Its fiery capsaicin oils hit your throat with undiminished fury, turning tasteless boiled turnip broth into a sweat-inducing spicy stew.",
    },
    ["rehydrated_corn_kernels"] = {
        zh = "在沸水中重新泡发煮软的脱水甜玉米粒。虽然嚼起来比新鲜玉米要韧上几分，但咬破外皮后迸发出的那一丝甜甜的汁水，足以让吃惯了无味泥糊的拾荒者感动得掉眼泪。",
        en = "Dehydrated sweet corn kernels rehydrated in boiling water. Though somewhat chewier than fresh garden harvests, their sweet burst of flavor brings tears to survivors accustomed to bland foraged tubers.",
    },
    ["rehydrated_eggs"] = {
        zh = "用温水重新调匀后在平底锅里炒熟的冷冻干燥全蛋粉。外观看起来像一盘金黄的炒鸡蛋，虽然口感稍显发粉发干，但货真价实的动物卵磷脂与蛋白质是无可替代的身体补品。",
        en = "Freeze-dried powdered eggs whipped with warm water and scrambled over campfires. Grainy in texture, these reconstituted curds provide clean animal protein that accelerates wound healing in cold shelters.",
    },
    ["rehydrated_fish"] = {
        zh = "在清汤里重新吸水泡发的脱水白身鱼肉干。虽然肉质纤维散碎且略带一股罐头腥气，但扔进锅里和几片野葱一起熬煮，依然能炖出一碗奶白浓郁的救命鲜鱼汤。",
        en = "Dehydrated whitefish fillets soaked back to life inside boiling water. While flaky and slightly rubbery, simmering them with wild scallions creates a nourishing broth after freezing river crossings.",
    },
    ["rehydrated_froglegs"] = {
        zh = "将干瘪脱水的青蛙腿放入温水重新泡发的白嫩蛙肉。肉质恢复了弹牙爽滑的口感，吃起来如同极嫩的鸡肉，无论裹上面粉煎炸还是搭配野葱清炒，都是林区泥潭搜刮归来后犒赏肠胃的高蛋白珍馐。",
        en = "Plump frog legs reconstituted in warm broth from shriveled dry rations. Their tender, springy meat tastes delightfully like delicate poultry, delivering complete protein whether quickly pan-fried over campfire grease or tossed into wild mushroom chowder.",
    },
    ["rehydrated_fruit"] = {
        zh = "将脱水混合水果干片泡在温水里重新泡发的一小碗多汁水果块。苹果干和浆果重新吸水胀大，酸甜可口的果汁在碗底沉淀，在缺少新鲜蔬果的末日地窖里，这是补充维生素和抚慰心灵的最佳甜品。",
        en = "A bowl of rehydrated mixed fruit flakes restored by soaking in warm purified water. Plumping with sweet juices, savoring these tender morsels supplies a much-needed vitamin surge that fends off debilitating scurvy in sunless bunkers.",
    },
    ["rehydrated_garlic"] = {
        zh = "经过清水浸泡重新恢复饱满的脱水大蒜瓣。蒜肉洁白且辛辣刺鼻的蒜素完全复苏，不仅能给腥膻的变异兽肉彻底去腥提味，其天然的广谱抑菌活性更是肠胃不适与预防伤口感染的廉价土抗生素。",
        en = "Dehydrated garlic cloves soaked in warm water until plump and pungent. Releasing sharp allicin aromas, they mask the foul gamey stench of mutated roadkill while providing natural antibacterial benefits against mild intestinal upsets.",
    },
    ["rehydrated_lobster"] = {
        zh = "冷冻干燥保存并在热锅中恢复原状的高档龙虾尾肉。即便肉质在脱水过程中失去了弹牙的鲜嫩，但在这片被怪物占领的荒原上大嚼龙虾肉，依然有一种极致荒诞的末日奢靡感。",
        en = "Freeze-dried lobster tails reconstituted inside simmering water. Lacking the crisp ocean snap of fresh catch, dining on high-end shellfish amidst radioactive ruins provides surreal, post-apocalyptic luxury.",
    },
    ["rehydrated_meat"] = {
        zh = "在热汤中浸泡数小时后重新膨胀软化的脱水牛肉块。虽然嚼起来像浸透了肉汁的厚海绵，但满满的蛋白质与盐分能迅速驱散四肢的疲劳，为接下来的长途跋涉注入能量。",
        en = "Dehydrated beef chunks soaked back to edible tenderness in boiling broth. Chewy like meat-flavored sponges, they supply high-octane protein and sodium to power grueling marathon marches across broken highways.",
    },
    ["rehydrated_mollusk"] = {
        zh = "在开水锅里重新泡开的干贝肉片。韧性十足且带着浓郁的海水咸腥气，把它扔进野菜粥里慢火慢熬，那股鲜美的海味能彻底掩盖野草的苦涩，唤醒麻木的味蕾。",
        en = "Dried shellfish rehydrated in bubbling cauldrons. Intensely chewy and brine-flavored, dropping a handful into dandelion mash completely masks botanical bitterness with rich savory ocean depth.",
    },
    ["rehydrated_poultry"] = {
        zh = "用热水重新泡发的大块脱水鸡肉干。原本硬如木屑的肉丝在吸收水分后重新变得软嫩多汁，虽然口感略逊于现杀活禽，但浓郁的鸡肉香气和实在的蛋白质纤维，足以让饥肠辘辘的旅行者恢复所有体力。",
        en = "Strips of freeze-dried poultry meat plumped back up in simmering broth. While slightly spongier than fresh farm poultry, its genuine savory fats and dense animal protein replenish exhausted muscles after day-long forced marches.",
    },
    ["rehydrated_veggy"] = {
        zh = "通过浸泡温水重新舒展开来的什锦脱水蔬菜碎。包含了胡萝卜丁、脱水甘蓝与青豆，虽然口感软烂缺乏清脆，但对于长期缺乏维生素的废土肠胃来说无异于久旱逢甘霖。",
        en = "Reconstituted medley of dried carrots, cabbage flakes, and peas. Soft and lacking fresh garden crunch, these rehydrated greens deliver vital ascorbic acid that keeps scurvy away from bunker residents.",
    },
    ["rehydration_drink"] = {
        zh = "由精准比例的纯净水、葡萄糖与电解质盐冲调而成的口服补液盐饮品。入口微咸带甜，能在腹泻脱水或在烈日下剧烈奔跑导致热衰竭时，以惊人速度重构细胞渗透压，将你从虚脱濒死边缘拉回。",
        en = "A balanced oral rehydration therapy beverage formulated with water, glucose, and electrolyte salts. Tasting faintly salty-sweet, it replenishes depleted blood volume rapidly after grueling desert marches, saving feverish survivors from fatal hypovolemic dehydration.",
    },
    ["reinforced_glass_pane"] = {
        zh = "由多层钢化玻璃与高韧性聚碳酸酯胶膜热压复合制成的小块防弹玻璃板。虽然边缘有轻微裂纹，但结构依然极其坚固，能直接抗住小口径手枪弹直击，是改装战术护盾射击孔或防暴门观察窗的极佳构件。",
        en = "A compact rectangular pane of laminated multi-ply bullet-resistant safety glass. Though bearing spiderweb stress fractures, it easily stops pistol-caliber rounds, making it ideal for crafting transparent firing slits on heavy tactical riot shields.",
    },
    ["reinforced_glass_sheet"] = {
        zh = "一整块厚重结实的大尺寸夹胶防弹玻璃整板。重量沉重且透光良好，能正面抵挡步枪穿甲弹的连续冲击与狂暴巨怪的疯狂锤击，将其整体焊接安装在末日装甲突击车前挡风位置，安全感无可比拟。",
        en = "A massive sheet of heavy laminated bulletproof glass. Thick enough to withstand sustained rifle fire and furious zombie pounding without shattering inward, welding it into vehicle windshield frames ensures complete forward situational awareness during vehicular breaches.",
    },
    ["reinforced_solar_panel"] = {
        zh = "在脆弱单晶硅光伏组件表面覆盖了一层高透光钢化防弹玻璃的重甲车载太阳能板。不仅能将免费阳光转化为宝贵电力，还能正面硬抗飞溅碎石、低垂树枝与丧尸爪牙的猛烈拍击而不碎裂。",
        en = "A monocrystalline solar panel shielded beneath a rugged sheet of laminated ballistic glass. Generating clean photovoltaic current from daylight, its armored surface withstands falling hail, low tree limbs, and gnawing mutant clutches without fracturing.",
    },
    ["reinforced_solar_panel_v2"] = {
        zh = "采用新一代高转换率砷化镓光伏电池与纳米陶瓷强化复合玻璃打造的顶级装甲太阳能板。即便在阴雨天也能高效发电，外壳防护力堪比轻型装甲板，是废土终极全电动力战车的永动能量核心。",
        en = "An advanced high-efficiency photovoltaic panel encapsulated within impact-resistant transparent ceramic armor. Absorbing diffuse solar energy even on overcast rainy days, it powers custom electric gunships while shrugging off stray bullet ricochets effortlessly.",
    },
    ["reins_tackle"] = {
        zh = "用结实牛皮条和锻铁马衔铁搭扣组装而成的整套缰绳与鞍具。结构牢固受力均衡，无论你驯服的是侥幸存活的纯种骏马、还是体型庞大性情温和的驯化巨型变异甲虫，这套缰绳都能让你牢牢掌握前进方向。",
        en = "A complete harness set of oiled leather reins, buckles, and iron curb bits. Buckling securely across muzzles, it allows daring survivors to steer saddled mounts or docile, giant mutated draft beetles across the wilderness.",
    },
    ["religieuse_au_chocolat"] = {
        zh = "一道用一大一小两枚叠放的巧克酥皮泡芙精巧组成的法式传统修女泡芙。表面淋着浓郁发亮的黑巧克力甘纳许，内馅填满丝滑香浓的巧克力卡仕达酱，在满目疮痍的废墟中品尝它，简直宛如圣光降临。",
        en = "A classic French pastry composed of stacked choux pastry buns enrobed in glossy dark chocolate ganache. Filled with velvety chocolate custard, savoring this delicate confection amidst bloodstained apocalyptic ruins feels like a divine, heavenly miracle.",
    },
    ["reloaded_10mmP"] = {
        zh = "在地下工作台上利用回收弹壳手工复装的高压大威力十毫米手枪弹。装药量加得几乎快要顶到弹头底缘，击发时狂暴的枪口焰与后坐力足以让握枪的手掌发麻，是专治变异巨兽的暴烈猛药。",
        en = "Bench-rest handloaded 10mm Auto cartridges packed to the brim with overpressure propellant. Belching concussive fireballs, the punishing recoil numbs your wrist while decisively halting charging mutant behemoths.",
    },
    ["reloaded_10mm_fmj"] = {
        zh = "在地下工作台上手工压装的全金属被甲十毫米手枪弹。装药量饱满且弹头压得严丝合缝，出膛动能依旧狂暴刚猛，是远距离逼退变异巨熊与尸化特警的可靠弹药。",
        en = "Hand-pressed full metal jacket 10mm rounds assembled on a workbench. Generous powder charges push dense copper penetrators, providing authoritative stopping power to halt charging mutant bears.",
    },
    ["reloaded_10mm_jhp"] = {
        zh = "手工复装的大开口十毫米空尖弹。弹头杯口用修表镊子小心翼翼清理平整，命中变异腐化血肉时会瞬间翻滚绽开成狰狞的铜爪，给凶悍的狂暴丧尸送上一记致命空腔。",
        en = "Bench-rested 10mm hollow points loaded into reclaimed brass casings. Hand-notched copper petals flower violently upon impacting mutated tissue, delivering devastating hydro-shock that drops raging abominations in their tracks.",
    },
    ["reloaded_123ln"] = {
        zh = "用异界罗马尼亚古怪口径弹壳手工复装的奇特子弹。底火压得略显松动，虽然在老式手枪里抽壳有些卡顿，但至少让这柄来自平行世界的冷门枪械重新喷吐火舌。",
        en = "Handloaded Romanian odd-caliber cartridges seated with improvised primers. Slightly loose tolerances cause occasional extraction hitches, yet they successfully restore firepower to obscure parallel-dimension surplus handguns.",
    },
    ["reloaded_123ln_ap"] = {
        zh = "压入自制硬化穿甲弹芯的异界口径复装弹药。黑色尖头在昏暗煤油灯下透着寒光，能在三十步内直接凿穿丧尸士兵身上的凯夫拉防弹衣，让废土刺客爱不释手。",
        en = "Parallel-dimension surplus brass retrofitted with hardened armor-piercing cores. Gleaming with a matte black tip, it punches through reinforced police flak jackets and armored skull plates effortlessly.",
    },
    ["reloaded_223"] = {
        zh = "从废弃靶场泥地里捡来的各色黄铜弹壳复装而成的点二二三步枪弹。弹壳底火品牌混杂不一，虽然射击精度参差不齐，但塞满三十发弹匣拿来扫射尸潮依然无比过瘾。",
        en = "Range-salvaged brass cases handloaded with surplus powder into utilitarian rifle rounds. Mixed headstamps cause slight velocity variations, yet thirty rounds roaring through an AR-15 chews through swarms reliably.",
    },
    ["reloaded_22_fmj"] = {
        zh = "用极细镊子在微小底缘弹壳里压入铅芯弹头的手工点二二边缘发火弹。击发声音微弱如折断枯枝，虽然对重型怪物毫无威胁，但清理屋檐下聒噪的变异乌鸦再合适不过。",
        en = "Handcrafted rimfire cartridges meticulously seated with miniature lead slugs. Popping with the gentle snap of breaking twigs, they harvest roosting wild game without alerting distant wandering hordes.",
    },
    ["reloaded_22_lr"] = {
        zh = "在台虎钳上小心翼翼复装的点二二标准运动步枪弹。只要底火没有受潮失效，它就是废土射击训练成本最低的子弹，能在百步开外精准射穿破铁罐或者松鼠的小脑袋。",
        en = "Carefully remanufactured .22 Long Rifle rounds squeezed into reclaimed brass. The cheapest ammunition across the ruined world, it plinks rusted soup cans and bags small game with surgical efficiency.",
    },
    ["reloaded_270win_fmj"] = {
        zh = "专为栓动猎枪手工配准的高速全金属被甲鹿弹。瓶颈形长弹壳里塞满了精选发射药，弹道平直得令人惊叹，能在四百米开外的山脊上直接掀翻巡逻的变异美洲狮。",
        en = "High-velocity hunting cartridges handloaded with pointed full metal jacket projectiles. Achieving flat trajectories across valley gaps, it snipes scouting predators off distant ridgelines before they scent your campsite.",
    },
    ["reloaded_270win_jsp"] = {
        zh = "带有外露纯铅软尖的复装温彻斯特长程步枪弹。铅尖在撞击软组织时会剧烈蘑菇化变形，倾泻出难以想象的粉碎性动能，是废土老猎人压在猎枪弹仓里的镇宅底牌。",
        en = "Long-range rifle cartridges featuring exposed soft lead noses. Flattening into wide mushrooms upon striking living targets, they transfer devastating kinetic energy to anchor massive mutant elk on the spot.",
    },
    ["reloaded_3006"] = {
        zh = "为加兰德与老式斯普林菲尔德步枪量身复装的全尺寸大威力步枪弹。沉重的铜弹头出膛时伴随着震耳欲聋的惊雷轰鸣，后坐力顶得肩膀生疼，但破坏力无可挑剔。",
        en = "Full-power battle rifle cartridges seated in stout vintage Springfield casings. Delivering thunderous muzzle blasts and bruising recoil, each shot easily shatters cinderblock walls hiding cowering bandit lookouts.",
    },
    ["reloaded_3006_incendiary"] = {
        zh = "弹尖灌注了手工提炼镁铝燃烧粉末的复装曳光穿甲弹。弹丸划破暮色留下一道刺眼的橙红弹道轨迹，击中木质据点或废旧油桶时能瞬间引燃熊熊烈火。",
        en = "Handloaded full-bore cartridges tipped with volatile magnesium tracer compounds. Leaving blazing orange streaks across twilight skies, impacts ignite dry lumber barricades and abandoned fuel reservoirs with spectacular fury.",
    },
    ["reloaded_3006_jsp"] = {
        zh = "配有软铅弹尖的复装大口径狩猎步枪弹。巨大的弹体带着蛮横的动能击碎沿途的一切阻碍，进入体腔后撕裂出惊人的空腔创口，任何庞然巨物挨上一发都得当场跪倒在地。",
        en = "Heavy hunting cartridges topped with expanding soft lead tips. Carrying monstrous kinetic shock, hitting a charging bio-behemoth tears dinner-plate cavities, bringing towering beasts crashing down into dust.",
    },
    ["reloaded_3006fmj"] = {
        zh = "重新压装了硬化钨碳钢芯的M2规格重型穿甲军用步枪弹。强装药配合极硬弹尖，在两百步距离上能轻松穿透废弃警用装甲车单薄的侧舷钢板，击碎里面的腐烂乘员。",
        en = "Military-spec armor-piercing cartridges fitted with salvaged tungsten penetrators. Designed for long-range material destruction, it punches clean through derelict vehicle doors and concrete barricades alike.",
    },
    ["reloaded_300_winmag"] = {
        zh = "带加强带的超大容量马格南步枪复装弹。弹壳内灌满了高燃速无烟火药，开火时枪口制退器喷出的气浪能掀飞地上的积雪，千米之外狙杀变异母体就指望它了。",
        en = "Belted magnum cases packed to maximum capacity with high-energy rifle propellant. The concussive muzzle blast blows snow away from your hide, delivering surgical execution across kilometer-long mountain valleys.",
    },
    ["reloaded_300blk"] = {
        zh = "用短粗的二二三截短弹壳手工压制而成的三零零黑视步枪弹。装药量经过严密计算以适配短突击步枪，在室内近战突击中既保证了致命射程又大幅降低了枪口过火。",
        en = "Fat thirty-caliber projectiles pressed into shortened, resized rifle brass. Optimized for compact carbines, it delivers brutal terminal punch through drywall during tense suburban house-clearing operations.",
    },
    ["reloaded_300blk_ss"] = {
        zh = "塞入超重纯铅弹头的亚音速专用特种复装弹。配合消音器射击时只听到枪机撞击的清脆金属咔哒声，在悄无声息的夜间潜行暗杀中，丧尸往往挨个倒下却不知枪声来自何方。",
        en = "Heavy subsonic cartridges loaded with massive lead penetrators. Paired with suppressors, firing produces only faint mechanical clicks, dropping guards into darkness before nearby patrols realize an assault has begun.",
    },
    ["reloaded_303"] = {
        zh = "带有开尖竞赛弹头的英制凸缘步枪复装弹。老式凸缘底火虽然容易在弹匣里相互卡勾，但精准调校的弹头飞行平稳，让李恩菲尔德步枪重新找回了狙击神枪的昔日荣光。",
        en = "Rimmed British surplus cartridges meticulously loaded with open-tip match projectiles. The cumbersome rims demand careful magazine packing, but stellar ballistic stability makes vintage Lee-Enfields sing with sniper precision.",
    },
    ["reloaded_3030"] = {
        zh = "专为杠杆步枪管状弹仓设计的软尖复装平头弹。钝圆的铅头防止在后坐力震荡下引爆前方底火，顺畅推弹上膛的瞬间，浓浓的旧西部荒野镖客情怀油然而生。",
        en = "Flat-nosed soft-point cartridges engineered specifically for tubular lever-action magazines. The blunt tips prevent chain detonations under recoil, keeping trusty brush guns running during frantic horseback sprints.",
    },
    ["reloaded_3030_bp"] = {
        zh = "用粗制自制黑火药手工填装的三十温彻斯特猎枪弹。击发时枪口喷吐出滚滚白烟与刺鼻硫磺味，虽然每次打完都得泡热水彻底刷洗枪膛，但在无烟药断供时能救性命。",
        en = "Classic lever-action brass filled with smoky homemade black powder. Firing blankets forest clearings in sulfur clouds, requiring tedious soapy water cleanups, yet keeps obsolete carbines firing when modern powder vanishes.",
    },
    ["reloaded_3030_fmj"] = {
        zh = "在废弃弹壳中手工重新压入底火、发射药与全金属被甲弹头的 .30-30 步枪弹。虽然手工复装导致各发火药量存在微小浮动，但在杠杆步枪管状弹仓里，这枚弹药依然能精准猎杀林间奔跑的鹿群。",
        en = "A hand-pressed .30-30 Winchester cartridge seated with a recycled full metal jacket bullet. While showing minor velocity variations from hand-measured powder charges, it chambers smoothly into classic lever-action carbines, reliably dropping game in brush.",
    },
    ["reloaded_3030_fmj_bp"] = {
        zh = "全金属被甲平头弹头搭配黑火药填装的复古温彻斯特子弹。沉重的纯铜外壳提供了更强的骨骼贯穿深度，开枪时震耳的爆鸣声响彻森林，把树梢上的乌鸦惊得四散奔逃。",
        en = "Full metal jacketed bullets wedded to coarse black powder propellants. The copper jacket prevents barrel lead-fouling, delivering stout brush-clearing penetration accompanied by billowing frontier smoke screens.",
    },
    ["reloaded_303fmj"] = {
        zh = "采用经典被甲弹头重新压装的英制大口径步枪弹。坚固的黄铜弹壳经过反复退火保养，出膛能量澎湃扎实，能轻易击穿老式避难所木门后面潜伏的丧尸。",
        en = "Standard military-pattern full metal jackets seated into annealed Enfield brass. Carrying substantial mid-century momentum, they smash through dry barricades and drop reanimated redcoats across muddy fields.",
    },
    ["reloaded_303sp"] = {
        zh = "配有软尖裸铅弹头的英制复装猎枪弹。在中距离遭遇战中命中变异野猪时，开花的铅芯能瞬间粉碎坚固的胸肋骨，将狂暴冲锋的野兽死死钉在泥地里。",
        en = "Soft-point big-bore cartridges optimized for dropping dangerous wasteland beasts. Expanding reliably inside thick hide, they shatter shoulder blades and anchor enraged mutant hogs in their tracks.",
    },
    ["reloaded_308"] = {
        zh = "废土通用度极高的三零八温彻斯特全威力步枪复装弹。无论是塞进栓动狙击枪还是半自动战斗步枪里，它都能提供无可挑剔的远距离压制力与恐怖的一枪击毙率。",
        en = "Ubiquitous full-power battle rifle rounds assembled with recycled brass. Feeding reliably into sniper rifles and battle carbines alike, its decisive punch anchors threats well past distant highway signs.",
    },
    ["reloaded_30carbine"] = {
        zh = "专为轻便短小的M1卡宾枪复装的圆头手枪兼步枪弹。后坐力温和轻快，压满二十发香蕉弹匣能在数秒内倾泻出密集的火力网，极其适合在狭窄巷道里压制成群的丧尸犬。",
        en = "Lightweight straight-walled carbine cartridges assembled from collected brass. Gentle recoil enables rapid-fire strings from vintage M1s, blanketing cramped alleyways in lead against rushing packs of zombie hounds.",
    },
    ["reloaded_30carbine_jsp"] = {
        zh = "压装了软尖裸铅弹头的卡宾枪高停止力复装弹。弥补了原版全被甲弹穿透有余而杀伤不足的缺陷，铅头在命中目标时迅速翻滚撕裂，大幅提升了近战击杀效率。",
        en = "Jacketed soft-point projectiles loaded into compact carbine casings. Remedying the over-penetration of standard military ball, the expanding lead nose transfers punishing kinetic energy into charging mutants.",
    },
    ["reloaded_32_acp"] = {
        zh = "短小精悍的欧洲老牌袖珍手枪复装弹。虽然击中丧尸前额往往只能弹开或者打出浅坑，但塞在特工袖珍手枪里拿来近距离补刀或者绝境自保依然有其存在的价值。",
        en = "Petite pocket pistol cartridges remanufactured with delicate powder measures. While incapable of shattering armored bone, carrying a loaded vest-pocket automatic provides desperate comfort when all primary rifles run dry.",
    },
    ["reloaded_32_acp_jhp"] = {
        zh = "带有微型空尖杯的袖珍手枪自卫复装弹。由于弹头初速较低，在稍微厚实一点的防寒冬衣面前可能无法完全开花，但在毫无护甲的贴身肉搏中能打出致命的内脏空腔。",
        en = "Miniature hollow-point rounds crafted for concealed vest-pocket sidearms. Low velocities hinder expansion against leather jackets, yet unarmored flesh absorbs gruesome lacerations when fired at point-blank breathing distances.",
    },
    ["reloaded_338lapua_api"] = {
        zh = "塞满穿甲燃烧复合弹芯的高端超远程拉普阿重狙复装弹。一发打出价值千金，弹丸在千米之外命中目标后会瞬间引发剧烈化学爆燃，把装甲车辆的油箱直接引爆成火球。",
        en = "Match-grade long-range cartridges fitted with armor-piercing incendiary penetrators. Firing one sends a fortune downrange, turning armored engine blocks into exploding fireballs across extreme sniper envelopes.",
    },
    ["reloaded_338lapua_fmjbt"] = {
        zh = "采用流线型船尾全金属被甲弹头的顶级重装狙击弹。在狂暴的侧风与气流中依然能够保持极高的弹道稳定性，是击杀高维裂隙边缘漂浮怪物的杀手锏。",
        en = "Streamlined boat-tail full metal jacket projectiles seated in heavy Lapua brass. Defying wicked crosswinds, its aerodynamic stability ensures surgical hits against rift anomalies hovering above ruined skylines.",
    },
    ["reloaded_338lapua_hpbt"] = {
        zh = "带有空尖船尾竞赛级弹头的终极狙击复装弹。由老练狙击手用电子天平一粒粒微调药粉压装而成，超高精度的飞行轨迹能在呼啸的风暴中精准洞穿千步之外的目标眼眶。",
        en = "Hollow-point boat-tail match ammunition calibrated to the tenth of a grain. When hostile snipers pin your party behind crumbling overpasses, this surgical cartridge ends the duel decisively.",
    },
    ["reloaded_357mag_fmj"] = {
        zh = "装药饱满的强威力三五七马格南全被甲复装弹。击发时转轮枪口爆发出耀眼的巨大火球，枪声清脆震耳，坚硬的弹头能连人带木门一起打个对穿。",
        en = "Full-house .357 Magnum cartridges loaded into shiny nickel-plated cases. Belching blinding cylinder flash and eardrum-splitting cracks, its dense penetrator punches through heavy wooden doors and necrotic spines.",
    },
    ["reloaded_357mag_jhp"] = {
        zh = "带有深度刻槽的马格南空尖复装弹。弹头在穿入腐化肉体的瞬间展开为锯齿状铜花，倾泻出令人胆寒的停止力，是荒野巡警抵御近身狂暴怪物的最佳防线。",
        en = "Aggressively notched hollow-point rounds driven by stout magnum powder charges. Blossoming into jagged copper petals inside soft tissue, it dumps massive kinetic shock that knocks charging horrors flat.",
    },
    ["reloaded_357sig_fmj"] = {
        zh = "采用瓶颈形手枪弹壳的高初速西格复装弹。将九毫米弹头推到了堪比微型步枪的惊人速度，在近战接敌中能干净利落地贯穿挡风玻璃与轻型凯夫拉背心。",
        en = "Bottlenecked handgun brass driving nine-millimeter projectiles at blistering velocities. The piercing trajectory punches effortlessly through automotive windshields and light tactical armor during highway ambush shootouts.",
    },
    ["reloaded_357sig_jhp"] = {
        zh = "高初速瓶颈弹壳配大空尖弹头的特工级复装弹药。在极高撞击速度下空尖展开极其剧烈，能瞬间在目标体内撕开足球大小的空腔，击倒效果立竿见影。",
        en = "High-velocity bottlenecked cartridges fitted with expanding hollow points. Violent hydraulic expansion upon entry tears catastrophic wound cavities, dropping bio-enhanced raiders before their fingers squeeze triggers.",
    },
    ["reloaded_380_FMJ"] = {
        zh = "专为超轻便单动袖珍手枪复装的三八零手枪弹。后坐力平稳轻巧且携带毫无负担，虽然打在重甲丧尸身上不痛不痒，但清理落单的落单爬行者依然得心应手。",
        en = "Mild-mannered .380 ACP rounds hand-seated into clean brass casings. Soft shooting and lightweight to carry, they provide adequate backup protection when dispatched against creeping nocturnal scavengers.",
    },
    ["reloaded_380_JHP"] = {
        zh = "经过精心扩口压制的三八零袖珍空尖复装弹。在短枪管中击发依然能获得不错的扩张表现，是藏在靴筒小手枪里的救命法宝，专为最后一刻的反抗而准备。",
        en = "Expanding hollow points crimped into diminutive semi-automatic pistol brass. Tuned for short barrels, they deliver respectable defensive expansion when wrestling mutants off your chest in dark crawlspaces.",
    },
    ["reloaded_380_p"] = {
        zh = "强行灌入高膛压发射药的特装强化三八零手枪弹。击发时枪口火舌狂喷且滑套后坐剧烈，让轻巧的小手枪爆发出接近标准九毫米的凶悍穿透威力。",
        en = "Overpressured .380 Auto rounds loaded with hot, fast-burning powder charges. Snapping violently under recoil, it pushes diminutive handguns to punch with authoritative stopping power rivaling standard service calibers.",
    },
    ["reloaded_38_fmj"] = {
        zh = "为老式三十八口径转轮手枪手工复装的黄铜被甲弹。弹道平缓且后坐力柔和，哪怕是未经训练的幸存者新人，也能在十步之内稳稳将弹丸送进丧尸的面门。",
        en = "Classic .38 Special rounds reloaded into polished revolver brass. Moderate recoil and predictable trajectory allow inexperienced survivors to place accurate headshots against shambling ghouls in cramped basement corridors.",
    },
    ["reloaded_38_special"] = {
        zh = "配有宽口空尖杯的三十八特制手枪复装弹。弹头铅芯质地柔软，在近距击中目标时能迅速外翻膨胀，提供远超纸面数据的极佳防卫停止效果。",
        en = "Jacketed hollow points seated over balanced pistol propellant charges. The soft lead core expands reliably at moderate velocities, delivering respectable knockdown power inside narrow fallout shelter passages.",
    },
    ["reloaded_38_special_p"] = {
        zh = "注入强装火药的三十八特制强化高压弹。只有坚固的钢制转轮才能安全承受这种狂暴膛压，开火时枪口喷出的白烟与震耳轰鸣足以震慑整条废弃走廊的狂徒。",
        en = "Overpressured .38 Special +P ammunition suited strictly for robust steel revolvers. Unleashing booming reports and dazzling muzzle flashes, it decisively halts feral brawlers lunging through breached doorways.",
    },
    ["reloaded_38_super"] = {
        zh = "专为竞技手枪底把复装的三十八超级空尖弹。高初速让轻质空尖弹头在撕裂空气时发出尖锐哨音，在撞击变异甲壳的一瞬间炸开成致命的金属碎片风暴。",
        en = "High-velocity .38 Super cartridges loaded with responsive expanding projectiles. Screaming downrange with supersonic crackle, impacts shatter hardened insect carapaces and pulp internal organs with brutal efficiency.",
    },
    ["reloaded_38super_fmj"] = {
        zh = "半底缘全金属被甲三十八超级高压复装弹。坚硬的铜被甲在穿透木质栅栏或轻型车门时几乎不发生偏转，是末日快枪手在街头遭遇战中的破障利刃。",
        en = "Semi-rimmed full metal jackets seated over hot propellant charges. Maintaining laser-straight trajectories through plywood barricades and car doors, it gives scavengers commanding superiority in urban street skirmishes.",
    },
    ["reloaded_40fmj"] = {
        zh = "大截锥铜被甲的四十口径手枪复装弹。沉重平头的弹丸在撞击骨骼时不会打滑反弹，而是将全部动能结结实实砸在骨架上，给冲锋的丧尸迎头一记闷击。",
        en = "Truncated cone full metal jackets assembled inside stout .40 S&W brass. The flat nose bites squarely into rotten bone, dumping massive blunt trauma that stumbles charging abominations backwards.",
    },
    ["reloaded_40sw"] = {
        zh = "配备深空尖开花杯的四十口径执法手枪复装弹。强劲的初速与巨大的弹尖开口相辅相成，在穿透厚重的废土皮夹克后依然能展开狰狞的铜爪，造成巨大创口。",
        en = "Deep-cavity hollow points crimped into heavy-duty semi-automatic brass. Punishing recoil accompanies every trigger pull, tearing ragged wound channels through thick leather coats worn by hostile raiders.",
    },
    ["reloaded_410shot_000"] = {
        zh = "在细长的四一零霰弹塑料壳里紧密塞入数颗三零大号铅弹丸的手工复装弹。近距轰击在窄门过道里犹如一道扇形铅弹风暴，能在一瞬间将来犯之敌打成筛子。",
        en = "Slender .410 bore plastic hulls packed with dense triple-aught lead pellets. Firing down narrow hallways throws a concentrated spread, shredding encroaching ghouls into ragged ribbons instantly.",
    },
    ["reloaded_410shot_bird"] = {
        zh = "灌入密集细小鸟弹铅砂的四一零猎鸟复装霰弹。虽然对大型装甲怪物如同隔靴搔痒，但用来对付成群扑击的变异吸血蝙蝠和狂暴飞鸟时，其密集的弹幕有着极高的捕杀率。",
        en = "Light shotgun shells packed with tiny birdshot pellets and thriftily measured powder. Perfect for swatting mutated mosquito swarms and radioactive crows, while saving heavier munitions for lethal threats.",
    },
    ["reloaded_410shot_slug"] = {
        zh = "在细长四一零弹壳里压入整颗实心铅铸独头弹的手工重装霰弹。虽然枪口动能比不上十二号大霰弹，但在五十步内精准将一颗大号重铅丸砸在怪物脸上依然致命无比。",
        en = "Rifled solid lead slugs seated inside slim shotgun hulls. Lacking the crushing energy of 12-gauge monsters, it still punches clean thumb-sized holes through charging predators at respectable combat distances.",
    },
    ["reloaded_44fmj"] = {
        zh = "四十四马格南手枪弹全被甲手工重装弹。巨大的黄铜弹壳里塞满了凶猛的发射药，枪响犹如晴空霹雳，沉重的实心铜弹能把变异野牛的坚硬头骨硬生生凿穿。",
        en = "Monolithic full metal jackets crimped into massive .44 Magnum brass. Detonating with deafening thunderclaps, the unstoppable copper slug punches clean through reinforced concrete walls and mutant bovine skulls.",
    },
    ["reloaded_44magnum"] = {
        zh = "让狂暴丧尸闻风丧胆的四十四马格南大号空尖复装弹。弹头在没入血肉后疯狂翻滚撕裂，倾泻出摧枯拉朽的毁灭性能量，开一枪能让人瞬间找回身为末日霸主的绝对自信。",
        en = "Classic Dirty Harry handloads topped with gaping hollow-point projectiles. Delivering bone-splintering hydro-shock, landing a center-mass shot on shambling horrors restores supreme confidence in your apocalyptic survival.",
    },
    ["reloaded_450_ftx"] = {
        zh = "在粗壮的大毒蛇直筒弹壳里压入FTX弹性聚合物尖头弹的手工大威力重弹。聚合物尖头在撞击时被猛烈压入铅芯引发剧烈蘑菇化膨胀，能在一瞬间把突变巨兽撞得倒飞出去。",
        en = "Straight-walled big-bore cartridges topped with polymer-tipped FTX bullets. The elastomeric tip drives violent, controlled expansion upon impact, delivering sledgehammer kinetic energy that stops armored horrors dead.",
    },
    ["reloaded_450_penetrator"] = {
        zh = "在四五零大毒蛇弹壳中压入淬火硬质合金穿甲弹头的终极重弹。沉甸甸的粗壮弹头出膛时伴随着地面颤抖，五十米内能把变异丧尸的骨甲与汽车引擎盖一起打成碎铁渣。",
        en = "Heavy big-bore rifle brass seated with solid copper penetrators. Unleashing concussive shockwaves that shake floorboards, it tears straight through armored bio-carapaces and vehicle engine blocks indiscriminately.",
    },
    ["reloaded_454_Casull"] = {
        zh = "装药量极其疯狂的四五四卡苏尔强威力复装弹。其狂暴后坐力甚至能把持枪不稳的射手手腕震脱臼，但出膛的重型软尖弹能在十步之内将狂暴变异巨熊彻底放倒。",
        en = "Brutal big-bore revolver cartridges crammed with overpressure propellant. The ferocious recoil threatens to dislocate unbraced wrists, yet the expanding bullet reliably drops charging mutant grizzly bears in their tracks.",
    },
    ["reloaded_4570_bp"] = {
        zh = "用粗制自制黑火药手工填装的经典四五七零政府型重马枪弹。开火时浓密的白烟伴随着火星喷涌而出，如同在密林里放了一门小型火炮，沉重的实心大铅块带着无匹的动能横扫一切阻碍。",
        en = "Antique frontier cartridges loaded with coarse black powder behind flat-nosed lead slugs. Billowing thick white sulfur smoke, firing one feels like deploying miniature field artillery against charging hordes.",
    },
    ["reloaded_4570_low"] = {
        zh = "采用减装药工艺以适配老式活门步枪的四五七零平头铅弹。后坐力温和许多且不会震碎脆弱的枪机，在百步之内依靠两百多格令的纯铅质量依然能稳稳砸断猎物的脊柱。",
        en = "Cowboy-action cartridges assembled with reduced powder charges to protect vintage actions. Gentle on antique breeches, the massive lead slug relies on sheer momentum to break mutant spine columns.",
    },
    ["reloaded_4570_pen"] = {
        zh = "专为现代强化杠杆枪打造的强装药四五七零高压重弹。出膛动能堪比重锤夯击，坚硬的弹头能将变异暴兽那厚达数寸的骨质护甲直接凿成漫天骨屑，威力惊世骇俗。",
        en = "Hot-rodded .45-70 Gov +P ammunition loaded specifically for modern lever-action rifles. Packing freight-train kinetic energy, it shatters reinforced exoskeleton plates like brittle porcelain in desperate close-quarters shootouts.",
    },
    ["reloaded_4570_sp"] = {
        zh = "带有外露软铅弹尖的标准四五七零狩猎复装弹。在丛林杂草中穿行时不易被树枝偏转，击中巨型猎物时翻滚形成的巨大永久空腔能在一瞬间让变异野猪因失血而失去反抗能力。",
        en = "Traditional soft-point cartridges engineered to punch through dense timber brush without deflection. Expanding into massive lead mushrooms, they anchor colossal mutant game animals before they vanish into thickets.",
    },
    ["reloaded_458wm"] = {
        zh = "源自非洲猎杀巨兽传奇的四五八温彻斯特马格南重装猎枪弹。巨大的弹药体积令人胆寒，在废土上只有面对巨型多足酸液异形时，你才会咬牙扣动这发震得肩膀生疼的救命狂暴巨弹。",
        en = "Elephant-stopping dangerous game cartridges assembled with heavyweight soft-point projectiles. Punishing both target and shooter, firing one is reserved for stopping colossal multi-legged horrors rumbling down forest roads.",
    },
    ["reloaded_45_acp"] = {
        zh = "废土手枪客最钟爱的经典四五全金属被甲复装弹。重达二百三十格令的大号亚音速铅芯在击中目标时发出沉闷的噗噗巨响，用蛮横的钝击动能把丧尸的大脑震成一滩浆糊。",
        en = "Time-honored .45 ACP ball cartridges hand-seated into reclaimed brass. The heavy subsonic projectile punches through decayed cranial bone with dull thuds, delivering authoritative stopping power favored by survivor gunslingers.",
    },
    ["reloaded_45_jhp"] = {
        zh = "带有十字深刻槽的大号四五空尖弹。在地下暗道遭遇战中击发，翻开的铜质弹翼能撕裂变异爬行者那充满肌肉纤维的坚韧胸膛，瞬间终结任何危险的近身扑击。",
        en = "Handloaded hollow-point rounds cut with cross-shaped expansion slots. Blossoming aggressively upon entering bio-tissue, they tear gaping exit wounds that instantly end leaping ambushes in dark sewers.",
    },
    ["reloaded_45_super"] = {
        zh = "经过膛压强化改装的四五超级手枪弹。装药量超越了普通军规标准，从强化的柯尔特手枪中击发时喷吐出耀眼的白炽光芒，将重型手枪的破坏力推向了极限。",
        en = "Overpressured .45 Super ammunition handloaded into heavy-webbed brass casings. Pushing classic 1911 platforms to their mechanical limits, its blistering velocity transforms sidearms into devastating hand cannons.",
    },
    ["reloaded_45colt_cowboy"] = {
        zh = "专为单动西部转轮复装的四五长柯尔特平头纯铅弹。装药温和稳定，铅丸在火药气体的推动下慢悠悠出膛，带着浓浓的十九世纪拓荒气息精准命中五十米开外的木靶。",
        en = "Authentic cowboy-style flat-nosed cartridges crafted with soft lead bullets. Mild pressures treat vintage cylinders gently, plinking rusted steel targets with the rhythmic nostalgia of nineteenth-century frontier outlaws.",
    },
    ["reloaded_45colt_fmj"] = {
        zh = "强行灌入高压现代无烟药的四五长柯尔特全金属被甲弹。赋予了老旧西部转轮媲美现代猎枪的惊人穿透力，开枪时震耳的爆鸣声响彻荒野，足以撕裂生锈卡车的薄铁皮车厢。",
        en = "Hot-rodded .45 Colt cartridges stoked with modern smokeless powder behind full metal jackets. Transforming gentle cowboy wheelguns into ferocious hunting tools, they punch straight through truck panels.",
    },
    ["reloaded_45colt_jhp"] = {
        zh = "强装药配空尖开花弹头的四五长柯尔特特装弹。在近战接敌中一击命中变异狂徒的胸口，炸裂的弹头能将整副肋骨轰得粉碎，让任何企图冲上来的敌人当场丧失战斗力。",
        en = "Jacketed hollow points seated over stout powder charges in long Colt brass. The devastating expansion shatters bone on impact, ensuring charging marauders collapse instantly before reaching spear distance.",
    },
    ["reloaded_460sw"] = {
        zh = "拥有惊人装药容量的四六零史密斯威森马格南高速复装弹。在超长枪管中加速到令人难以置信的步枪级初速，枪口喷出的火舌犹如喷火器，能在两百米开外精准猎杀变异飞禽。",
        en = "Blistering high-velocity revolver rounds driven by massive charges of slow-burning powder. Screaming downrange with rifle-like speeds, the erupting muzzle flash illuminates hillsides while dropping flying mutant predators cleanly.",
    },
    ["reloaded_460sw_jhp"] = {
        zh = "带有深凹空尖的四六零马格南巨型手枪弹。在极高撞击初速下瞬间炸裂解体，将狂暴的撕裂冲击波传导到目标的每一个器官，是近身迎击重型装甲变异丧尸的终极核按钮。",
        en = "Heavy hollow points propelled at extreme velocities by cavernous .460 S&W cases. The explosive hydro-shock tears through dense bio-musculature, shattering mutated skeletal structures in spectacular displays of terminal force.",
    },
    ["reloaded_500_Magnum"] = {
        zh = "手枪弹药界的终极王者五零零马格南巨弹。每发子弹都如同一枚小型炮弹，扣动扳机时枪口腾空跃起几乎砸在脸上，但眼前任何狂暴怪物的躯干都会被直接轰出一个透明大窟窿。",
        en = "The undisputed king of handgun ammunition, assembled with half-inch lead penetrators. The volcanic recoil snaps wrists upward violently, but leaves dinner-plate exit holes clean through rampaging behemoths.",
    },
    ["reloaded_50_incendiary"] = {
        zh = "弹尖涂有亮蓝标志的十二点七毫米重机枪复装穿甲燃烧弹。重达数百格令的巨弹在千米外命中目标后会瞬间引发上千度的高温铝热爆燃，将敌方轻装甲载具烧成一堆废铁。",
        en = "Half-inch anti-materiel rounds tipped with pyrotechnic incendiary mixtures. Impacting over a kilometer away, the pyrophoric core ignites roaring thermite blazes that cook enemy transport engines into scrap.",
    },
    ["reloaded_50ae_fmj"] = {
        zh = "专为沙漠之鹰手工复装的半英寸全金属被甲手枪弹。饱满的发射药配合坚硬的铜被甲，击发时的震耳巨响能把废弃车库的顶棚灰尘震得簌簌落下，一击就能打碎水泥石柱。",
        en = "Massive .50 Action Express cartridges assembled with heavy full metal jacket bullets. The thunderous concussion rattles dust from warehouse ceilings, easily cracking concrete pillars protecting ambushing raiders.",
    },
    ["reloaded_50ae_jhp"] = {
        zh = "杯口宽大的半英寸口径空尖重装手枪弹。在命中变异生物的一瞬间展现出骇人听闻的扩张破坏力，连同骨骼带内脏在内部绞成肉末，是重装幸存者最迷恋的暴力美学。",
        en = "Cavernous hollow-point handloads for heavy semi-automatic hand cannons. Expanding into serrated metal stars upon impact, they pulp internal vitals with absolute mechanical finality in close-quarters shootouts.",
    },
    ["reloaded_50beowulf_penetrator"] = {
        zh = "在粗短直筒弹壳里压入坚硬铜质穿甲芯的贝奥武夫大口径步枪弹。塞进标准AR步枪弹匣里单排供弹，近距离击发能一枪轰穿掩体水泥墙，将躲在后面的生化变异体当场撕碎。",
        en = "Short-cased heavy rifle rounds fitted with solid copper penetrator tips. Feeding through standard rifle magazines, pulling the trigger punches right through cinderblock bunkers to pulverize lurking biological horrors.",
    },
    ["reloaded_50beowulf_xtp"] = {
        zh = "配备XTP深度扩张弹头的五十贝奥武夫手掷火炮弹。狂暴的动能让开花的弹头在目标体表炸开触目惊心的空腔，是在废土废墟巡逻时对抗变异狂暴巨犀的绝命杀手锏。",
        en = "Substantial big-bore cartridges topped with controlled-expansion XTP bullets. Transferring devastating kinetic shock upon landing, it reliably crumples thick-skinned mutant monstrosities charging down suburban avenues.",
    },
    ["reloaded_50bmg"] = {
        zh = "经过高精度电子秤逐粒配药压装的十二点七毫米竞赛级重狙子弹。弹道系数极其惊人，在两公里外依然能保持稳定的超音速飞行，是超远距离狙杀变异暴君的王者弹药。",
        en = "Precision-crafted .50 BMG cartridges loaded with match-grade boat-tail projectiles. Maintaining supersonic flight past two kilometers, it turns impossible long-distance sniper shots against towering tyrants into routine marksmanship.",
    },
    ["reloaded_50ss"] = {
        zh = "装入硬化碳化钨穿甲弹芯的十二点七毫米特种军用复装狙击弹。沉重的硬核能够轻易凿穿两英寸厚的均质钢装甲板，把躲在银行保险库大门后面的变异母巢直接打穿。",
        en = "Tungsten-core anti-materiel cartridges assembled for maximum mechanical penetration. Punching through two inches of hardened steel armor, it penetrates reinforced bank vault doors to terminate sheltered mutant nests.",
    },
    ["reloaded_545"] = {
        zh = "为苏制AK74步枪手工复装的五四五小口径高速军用步枪弹。弹尖内部留有独特的空气配重空腔，击中软组织时会疯狂翻滚游走，造成极其惨烈的内部空腔创伤。",
        en = "Military surplus casings handloaded with 5.45x39mm full metal jacket bullets. The hollow cavity nose induces violent tumbling inside flesh, generating catastrophic internal trauma from compact, controllable carbines.",
    },
    ["reloaded_545_ap"] = {
        zh = "装有淬火硬钢穿甲芯的五四五特种破障复装弹。在保证轻快连发后坐力的同时，能在百米距离上轻易穿透军用陶瓷防弹插板，是废土游击队伏击机械化巡逻队的利器。",
        en = "Hardened steel-core cartridges assembled into lightweight assault rifle brass. Combining rapid follow-up shot control with impressive plate-penetrating lethality, they punch cleanly through scavenged ballistic body armor.",
    },
    ["reloaded_556"] = {
        zh = "废土上保有量最大的五点五六毫米北约标准小口径步枪复装弹。用废弃营地搜刮来的黄铜弹壳反复翻新压装，供弹顺畅稳定，是所有持枪幸存者防身与扫荡不可或缺的通用硬通货。",
        en = "Standard 5.56x45mm NATO cartridges recycled from ruined military outpost caches. Feeding reliably through countless platforms, these affordable rounds serve as the daily working currency for frontline wasteland scouts.",
    },
    ["reloaded_556_incendiary"] = {
        zh = "弹尖包裹了易燃化学粉末的五点五六毫米曳光燃烧复装弹。在夜战中射击能清晰看清弹着点并引燃干草棚与帐篷，将躲藏在阴影里的尸潮彻底暴露在火光之中。",
        en = "Pyrotechnic-tipped assault rifle rounds leaving brilliant phosphorescent streaks in their wake. Illuminating night gunfights with glowing trails, impacts ignite dry brush barricades and silhouette flanking zombie hordes.",
    },
    ["reloaded_57mm"] = {
        zh = "专为P90冲锋枪与五七手枪手工复装的高速穿甲微型步枪弹。细小的弹头在微型弹壳里爆发出惊人的初速，后坐力柔和得像一把气枪，却能在近身交火中轻易撕裂钛合金装甲板。",
        en = "Miniature high-velocity rounds handloaded for compact submachine guns and tactical pistols. Offering soft recoil, its needle-fine profile slices through Kevlar vests with surgical, armor-defeating precision.",
    },
    ["reloaded_762_25"] = {
        zh = "瓶颈形托卡列夫高膛压手枪复装弹。尖锐的钢芯在充沛的发射药推动下呼啸出膛，在手枪交火距离内能轻松凿穿厚实的硬木门板，是波波沙冲锋枪倾泻火力的最佳食粮。",
        en = "Bottlenecked Tokarev cartridges reloaded with hot pistol powders. Screaming out of barrels with shocking speed, they punch clean through thick oak doors and turn submachine guns into devastating buzzsaws.",
    },
    ["reloaded_762_51"] = {
        zh = "七点六二北约标准全威力重装战斗步枪弹。沉甸甸的铜被甲在远距离依然保持着惊人的杀伤动能，一发就能将躲在汽车发动机盖后面的变异伏击者当场掀翻在地。",
        en = "Full-power 7.62x51mm rifle cartridges loaded to standard military velocities. Carrying crushing kinetic force across long distances, each round flips ambushing marauders flat on the tarmac behind vehicle engine bays.",
    },
    ["reloaded_762_51_incendiary"] = {
        zh = "弹头灌装易燃镁铝粉末的七点六二重型曳光燃烧步枪弹。一道道耀眼的红色火光划破阴沉的废土长空，命中敌方防御沙袋时迸发出的滚烫火星能瞬间点燃附近的易燃物。",
        en = "Full-power battle rifle brass loaded with incendiary tracer bullets. Carving searing red paths across dark landscapes, impacts splash molten sparks that turn wooden watchtowers into roaring pyres under siege.",
    },
    ["reloaded_762_54R"] = {
        zh = "带有古老凸缘的大威力苏制莫辛纳甘与SVD狙击步枪复装弹。强劲的装药配合沉重的钢芯弹头，射击时枪托在肩膀上重重一撞，千米开外的丧尸脑袋应声炸裂开来。",
        en = "Rimmed Soviet cartridges assembled with heavy full metal jacket penetrators. The stout recoil kicks your shoulder forcefully, while the unstoppable projectile shatters distant zombie heads with uncompromising brutality.",
    },
    ["reloaded_762_jhp"] = {
        zh = "带有深凹空尖的七点六二中间威力步枪复装弹。为AK47量身打造，大幅改善了原版军规弹容易直接穿透的问题，命中软组织后剧烈翻滚开花，提供极为暴烈的击倒力。",
        en = "Hollow-point 7.62x39mm rounds assembled for rugged Kalashnikov platforms. Expanding violently inside soft muscle rather than over-penetrating, they deliver bone-splintering stopping power against charging bio-mutants.",
    },
    ["reloaded_762_m87"] = {
        zh = "使用回收铁壳与铜被甲弹头重新压装的经典AK步枪弹。原料易得且公差容忍度极高，即便浸泡过泥水也能在粗矿的导气管步枪中顺畅击发，是废土生存最忠实的好伙伴。",
        en = "Everyday Kalashnikov cartridges reloaded with cast bullets and salvaged steel cases. Tolerant of grit and wet mud, they cycle reliably through rusty actions when all delicate firearms choke.",
    },
    ["reloaded_77mm_arisaka_jsp"] = {
        zh = "为二战有阪栓动步枪手工复装的七点七毫米软尖猎弹。老式铜壳经过精心扩口清洗，纯铅软头在击中变异大鹿时展现出绝佳的开花膨胀，让这把博物馆古董重获新生。",
        en = "Antique Japanese military brass retrofitted with modern soft-point hunting bullets. Delivering excellent terminal expansion against mutant deer, it breathes lethal life back into century-old battlefield bolt-actions.",
    },
    ["reloaded_9mm"] = {
        zh = "废土流浪者弹药带上最常见的手工复装九毫米空尖弹。弹壳底火经过细心校平，虽然击发时的后坐力各有千秋，但贴脸一枪轰碎丧尸眼眶的可靠性从未让人失望过。",
        en = "Ubiquitous 9x19mm hollow points assembled from sweepings collected off gun shop floors. Slight powder variances exist, yet they expand reliably to blow rotten eye sockets open in tense alleyways.",
    },
    ["reloaded_9mmP"] = {
        zh = "强装药的高膛压九毫米手枪复装弹。弹头出膛速度大幅跃升，在手枪战术突击中能获得更加平直的弹道与穿透力，是老练警探在近距离遭遇变异甲虫时的破壳利器。",
        en = "Overpressured 9mm +P cartridges loaded with hot powder charges into reinforced casings. Snappier recoil yields higher velocities, punching straight through thick insect carapaces during room-clearing breaches.",
    },
    ["reloaded_9mmP2"] = {
        zh = "装药量逼近枪管耐压极限的极限九毫米超高压复装弹。击发时枪口火舌狂喷伴随着震耳欲聋的金属撞击声，只有全钢制现代战术手枪才能安全射击而不至于当场炸膛。",
        en = "Extreme +P+ handloads pushing chamber pressures to absolute structural margins. Belching blinding muzzle flares and concussive blasts, only modern steel-framed pistols handle this furious power without catastrophic blowouts.",
    },
    ["reloaded_9mmfmj"] = {
        zh = "数量充沛的九毫米全金属被甲通用手枪复装弹。结构简单可靠且不易卡膛，不管是压入微型冲锋枪大弹鼓还是塞在随身左轮里，它都是清除沿途杂兵最划算的弹药。",
        en = "Standard nine-millimeter ball rounds loaded into annealed range brass. Cycling smoothly through handguns and submachine gun drums alike, they clear street-level shamblers economically without draining scarce components.",
    },
    ["reloaded_9x18mm"] = {
        zh = "为马卡洛夫手枪手工复装的九乘十八粗短弹药。在锈蚀斑斑的老式军火库里很容易找到它的空弹壳，装药温和可靠，是俄系轻便自卫武器在废土上的口粮保障。",
        en = "Short-cased Makarov ammunition reloaded with recycled components. Tolerant of loose chamber tolerances, these dependable rounds keep rugged surplus sidearms functional across freezing wasteland patrol routes.",
    },
    ["reloaded_9x18mmP2"] = {
        zh = "压入过量速燃火药的马卡洛夫超高压特装复装弹。开火时让轻巧的小手枪剧烈震颤甚至震麻虎口，但飞出的实心弹头足以在十步之内打穿狂暴变异体的厚实头骨。",
        en = "Hot-rodded 9x18mm handloads stuffed with maximum charges of fast-burning propellant. The fierce recoil numbs hands, but sends heavy slugs crashing clean through mutant skulls at point-blank distances.",
    },
    ["reloaded_9x18mmfmj"] = {
        zh = "加装硬化穿甲钢芯的九乘十八马卡洛夫特战复装弹。弥补了该口径天生穿透力不足的缺陷，在近距离近身肉搏中能干净利落地凿开掠夺者简易防爆盾牌的铁皮护面。",
        en = "Armor-piercing steel-core bullets seated into compact Russian service brass. Overcoming typical penetration limits, it punches through makeshift scrap-iron shields carried by aggressive outpost marauders.",
    },
    ["reloaded_shot_00"] = {
        zh = "在塑料霰弹壳里整齐塞满九颗手工浇铸大号纯铅弹丸的十二号鹿弹。近距离一枪轰出如同铁扫帚扫过街角，能把整群拥挤在走廊里的丧尸撕扯成漫天碎肉。",
        en = "Classic 12-gauge hulls packed with nine cast double-aught lead pellets. Firing down crowded corridors sweeps advancing shamblers away like an iron broom, clearing tight breach choke points instantly.",
    },
    ["reloaded_shot_bird"] = {
        zh = "灌注了数百粒细小铅砂的十二号猎鸟手工复装霰弹。虽然无法击穿厚重的生化外骨骼，但其巨大的散射面用来对付成群扑面而来的变异飞蛾和寄生蝙蝠堪称灭虫神器。",
        en = "Light sporting shells filled with hundreds of tiny lead birdshot pellets. Useless against armored brutes, the wide spread obliterates swarms of mutated wasps and radioactive bats mid-air effortlessly.",
    },
    ["reloaded_shot_dragon"] = {
        zh = "在十二号霰弹壳里装满粗制镁铝易燃金属碎屑的自制龙息弹。扣动扳机能从枪口喷射出长达数米的耀眼烈焰火舌，将迎面扑来的丧尸狂潮瞬间点燃成凄厉嚎叫的活火人。",
        en = "Terrifying shotgun shells packed with powdered magnesium and chemical oxidizers. Pulling the trigger spews a roaring cone of liquid fire, incinerating charging zombie swarms in blinding displays of pyrotechnics.",
    },
    ["reloaded_shot_flechette"] = {
        zh = "装填了数十枚带尾翼微型钢镖的特种近战复装霰弹。出膛后微型钢镖在空中撕裂空气发出凄厉尖啸，能精准穿透厚实的棉衣与几丁质甲壳，将内脏刺得千疮百孔。",
        en = "Tactical shotgun shells packed with dozens of finned steel needles. Flying downrange with eerie hissing whistles, the steel darts pierce heavy winter clothing to pin vital organs with gruesome efficiency.",
    },
    ["reloaded_shot_slug"] = {
        zh = "在十二号塑料外壳内手工灌注一枚重达一盎司实心铅块的独头重霰弹。出膛时伴随着狂暴的后坐力，巨大的单体铅块在五十米内能把任何冲撞而来的变异狂徒直接砸得粉身碎骨。",
        en = "A massive one-ounce solid lead slug crimped into heavy-walled shotgun hulls. Delivering bone-crushing kinetic devastation, it stops charging bio-hulks in their tracks like a speeding freight locomotive.",
    },
    ["remington700_270"] = {
        zh = "发射 .270 温彻斯特高速弹药的雷明顿 700 经典栓动旋转后拉步枪。胡桃木枪托做工典雅，弹道平直且射程极远，在开阔的原野上，只要透过高倍瞄准镜扣下扳机，远处的狙击手根本无从躲避。",
        en = "A bolt-action Remington 700 hunting rifle chambered for high-velocity .270 Winchester. Featuring a handsome walnut stock and remarkably flat ballistic trajectory, it drops medium game and distant marauders cleanly across wind-swept cornfields.",
    },
    ["remington_1100"] = {
        zh = "雷明顿 1100 半自动 4 发滑膛霰弹枪。利用独特的导气系统大幅缓解了 12 号霰弹的暴烈后坐力，不仅击发平稳且射速极快，无论是打飞鸟还是近距离将扑脸的变异犬轰成碎片都游刃有余。",
        en = "A classic 4-round gas-operated Remington 1100 semi-automatic shotgun. Taming harsh 12-gauge kick into soft pulses, its rapid cyclic rate turns skyward fowl hunts or close-range ambushes by feral hounds into triumphant, lead-spraying victories.",
    },
    ["remington_700"] = {
        zh = "发射大威力 .30-06 全威力弹药的雷明顿 700 经典栓动狙击步枪。三环钢枪机闭锁极其牢固耐用，经受数十年的风吹雨打依然精度如初，是远距离狙杀狂暴丧尸与压制匪帮据点的绝对王牌。",
        en = "A legendary bolt-action rifle chambered in hard-hitting .30-06 Springfield. Boasting an ultra-rigid cylindrical steel receiver, its superb long-range mechanical accuracy makes it the premier platform for counter-sniping marauders across highway roadblocks.",
    },
    ["remington_700_308"] = {
        zh = "发射通用 .308 弹药的雷明顿 700 精准猎枪。短枪机行程上膛迅捷利落，高刚性重型枪管配合浮置枪托，能在数百米外将子弹精准送进猎物的致命弱点，弹药通用性与补给极其容易。",
        en = "A short-action Remington 700 chambered for abundant .308 Winchester ammunition. Its rigid free-floating barrel and crisp trigger break deliver pinpoint precision, dropping charging moose and heavily armored mutants with clinical, single-shot lethality.",
    },
    ["remington_870"] = {
        zh = "配备 5 发管状弹仓的雷明顿 870 经典泵动式霰弹枪。全钢机匣结实耐操到令人发指，无论是泥泞浸泡还是沙尘暴都不会阻碍它上膛开火，那声清脆的上膛声足以让任何黑暗中的潜行者胆战心惊。",
        en = "A legendary 5-round pump-action shotgun built around a solid billet steel receiver. Utterly impervious to mud, sand, and neglect, racking its twin action slide bars creates a universally terrifying sound that deters scavengers.",
    },
    ["remington_870_express"] = {
        zh = "带有 7 发加长管状弹仓的雷明顿 870 特警防暴型霰弹枪。加长弹仓赋予了它极其凶悍的压制火力，黑色哑光防锈表面经久耐用，是清理被尸群彻底堵死的逼仄走廊时最让人心安的近战重炮。",
        en = "A tactical variant of the Remington 870 sporting an extended 7-round magazine tube. Furnished with durable synthetic furniture, its formidable ammo capacity makes it an essential room-broom for sweeping cramped stairwells crowded with ravenous ghouls.",
    },
    ["remotevehcontrol"] = {
        zh = "带有加密射频天线与手持监视屏的车辆远程遥控终端。能与安装了自动驾驶仪的改装战车无缝配对，让你坐在高耸水塔顶端，一边喝着热咖啡一边遥控重装压路机在尸群中尽情碾压狂欢。",
        en = "A rugged handheld vehicle telemetry controller equipped with a live video feed. Interfacing directly with vehicle autopilots, it lets you steer a heavily spiked armored juggernaut through street barricades while lounging safely on a rooftop.",
    },
    ["rep_crossbow"] = {
        zh = "采用经典杠杆压杆与重力落箭箭匣设计的连发手拉十字弩。只要前后扳动杠杆，就能在短短数秒内连续将五支利箭射向目标，虽然单发穿透力略逊于重弩，但狂暴的射速足以将近身丧尸射成刺猬。",
        en = "A repeating crossbow utilizing an ingenious lever-action magazine mechanism. Rocking the cocking handle loads and fires bolts in rapid succession, trading raw penetration for a blistering rate of silent fire that shreds unarmored zombies.",
    },
    ["repeater_mod_guide"] = {
        zh = "手绘有大量高频电路图纸的无线电中继站改装施工方案。详尽图解了如何利用废弃变压器和石英晶振改造广播电台，按照指南组装中继天线，就能彻底消除辐射尘对无线电通讯的毁灭性屏障。",
        en = "A set of blueprints outlining how to modify civilian radio hardware into high-power repeaters. Following its hand-drawn diagrams enables amateur electricians to link isolated survivor colonies across mountain ranges despite intense atmospheric electromagnetic fallout.",
    },
    ["report_t_substrate"] = {
        zh = "封存在绝密公文包里的一份关于T基质生物工程的研究报告。纸页上详细记录了有机活体聚合物在受到外界刺激时的自我复制特性，揭示了大灾变背后细思极恐的深渊一角。",
        en = "A classified scientific dossier detailing bio-engineered T-substrate cellular behaviors. Its dense diagrams illustrate living synthetic polymers replicating under stimulus, shedding grim light on the origins of the apocalypse.",
    },
    ["resin_chunk"] = {
        zh = "一块散发着诡异松香与化学怪味的破碎异界树脂结晶。质地坚硬耐磨且具有优异的耐热绝缘性，是某些异界传送门生物筑巢分泌的奇特凝胶，在铁匠炉中熔化后是调制超高强度粘合剂的神秘原料。",
        en = "A jagged chunk of alien resin smelling of ozone and pine pitch. Salvaged from Nether portal hives, its strange polymer bonds resist extreme heat, melting down into supernaturally strong structural cements for reinforcing body armor.",
    },
    ["resonance_measurement_device"] = {
        zh = "利用精细石英悬臂与水银液滴平衡制成的异界维度共振测量仪。当周围空间出现隐形传送门裂隙或虚空怪物游弋时，仪器内的指针会剧烈震颤并发出刺耳金属音，是避免被空间撕碎的救命探针。",
        en = "A strange mechanical apparatus featuring suspended quartz needles and mercury vials. Vibrating frantically in the presence of invisible dimensional rifts and Nether anomalies, it alerts wary travelers before unseen spatial distortions rip them apart.",
    },
    ["restaurantbrochure"] = {
        zh = "大灾变前某家高档牛排馆印刷精美的三折页彩色宣传折页。封面上印着多汁诱人的厚切炭烤肉眼牛排与冰镇红酒，在饥肠辘辘啃食干燥压缩饼干的末日之夜阅读它，简直是对精神的残忍折磨与自虐。",
        en = "A glossy full-color tri-fold marketing brochure from a long-vanished steakhouse. Featuring photographs of sizzling charcoal-grilled ribeyes, reading its tantalizing menus while chewing bland dry rations is a form of exquisite psychological self-torture.",
    },
    ["restaurantmap"] = {
        zh = "印着本地数百家餐馆与酒吧名录的美食折页地图。虽然上面推荐的米其林餐厅与网红甜品店如今早已沦为满地残肢与腐肉的丧尸餐厅，但标示的后厨冷库与干货仓库位置依然是摸金宝地。",
        en = "A glossy printed pamphlet detailing local eateries, cafes, and taverns. While five-star dining rooms now feature rotting patrons chewing severed limbs, its street maps still accurately pinpoint treasure troves inside commercial dry-goods pantries.",
    },
    ["retool_ar15_22"] = {
        zh = "将 AR-15 步枪快速转换为 .22 LR 口径的轻型上机匣总成。后坐力轻若玩具且射击声音微弱，能让你尽情倾泻那些满地散落、极其廉价的边缘发火小口径子弹，专门用于打靶娱乐或清理鼠患。",
        en = "A dedicated .22 LR upper receiver assembly featuring an integral blowback bolt. Producing negligible recoil and whisper-quiet reports, it lets marksmen expend mountains of ubiquitous rimfire plinking ammunition without drawing wandering zombie hordes.",
    },
    ["retool_ar15_223rem"] = {
        zh = "配有中等长度枪管的 AR-15 标准 .223 雷明顿上机匣套件。在枪口初速与室内便携性之间达成了近乎完美的折中平衡，是枪械工坊最常见也最可靠的军警级快速替换总成模块。",
        en = "A mid-length .223 Remington upper receiver assembly featuring a balanced carbine barrel. Striking an optimal compromise between muzzle velocity and interior mobility, it remains the gold standard modular combat platform across ruined police armories.",
    },
    ["retool_ar15_223rem_extended"] = {
        zh = "装有 20 英寸重型竞赛级长枪管的 AR-15 .223 全尺寸步枪上机匣。全长较长且略微压手，但能将发射药能量发挥到极致，射程与弹道平直度极佳，是荒原狙击猎手搭建精确射手步枪的利器。",
        en = "A full-length 20-inch match rifle upper receiver chambered for .223 Remington. While unwieldy in stairwells, it burns propellant completely to wring maximum velocity and flat trajectories from standard cartridges at extended ranges.",
    },
    ["retool_ar15_223rem_medium"] = {
        zh = "配备 16 英寸标准卡宾枪管与皮轨护木的 AR-15 上机匣。最经典的军用 M4 构型衍生品，坚固耐用且导气顺畅，能在任何恶劣环境下稳定泼洒 5.56 毫米弹雨，配件通用性举世无双。",
        en = "A classic 16-inch carbine upper receiver assembly complete with full-length handguard rails. Emulating ubiquitous military M4 profiles, it cycles .223 ammo flawlessly across frozen trenches and accepts every imaginable tactical grip or light.",
    },
    ["retool_ar15_223rem_pistol"] = {
        zh = "配备超短 7.5 英寸超短枪管的 AR-15 手枪型上机匣。射击时枪口会喷吐出狂暴骇人的刺目火球与撕心裂肺的震耳音爆，虽然远距离弹道衰减严重，但在狭窄车厢内甩动开火极其灵活。",
        en = "A stubby 7.5-inch pistol upper receiver built for AR-15 platforms. Unleashing deafening sonic concussions and blinding fireballs with every trigger squeeze, it trades long-range velocity for unmatched handling inside cramped vehicles.",
    },
    ["retool_ar15_223rem_short"] = {
