    ["retool_ump_9"] = {
        zh = "将 UMP 冲锋枪转换为 9x19 毫米高射速口径的套件。换上轻量化枪机与弧形弹匣后，射击后坐力如同一阵轻风拂面，极易控制连发射击着弹点，弹药随手可得，是日常扫街搜刮的经济首选。",
        en = "A 9x19mm caliber conversion assembly for the HK UMP submachine gun. Reducing felt recoil down to gentle pulses, it lets shooters keep extended automatic bursts clustered tightly on target while consuming plentiful 9mm scavenged ammunition.",
    },
    ["revolver_shotgun"] = {
        zh = "在废铁加工台上利用转轮供弹机构魔改而成的左轮式多发霰弹枪。沉重的弹巢内能压入 5 发 12 号大威力霰弹，每次扳动击锤转动弹巢都带着工业粗犷的咔哒声，近身狂轰时宛如手摇加农炮。",
        en = "A crude home-machined shotgun utilizing an oversized revolving cylinder mechanism. Holding five 12-gauge shells, rotating the heavy cylinder clicks with mechanical brutality, unleashing thunderous buckshot volleys like a personal, handheld siege bombard.",
    },
    ["rfb_308"] = {
        zh = "采用前抛壳专利设计的 7.62x51 毫米全口径无托半自动战斗步枪。空弹壳会从枪管上方的滑槽安静滑落出来，既不会烫伤射手也方便回收复装，威力狂暴且结构紧凑，是废土单兵战斗步枪天花板。",
        en = "A 7.62x51mm semi-automatic bullpup battle rifle utilizing forward ejection chutes. Expelled brass chutes forward harmlessly away from your face for easy collection, packing full-power rifle destruction into a compact, close-quarters maneuverable chassis.",
    },
    ["rhubarb"] = {
        zh = "一根新鲜采摘下来、通体呈现艳丽红绿渐变色的酸大黄茎秆。咬下一口酸爽刺骨让人倒吸凉气，虽然叶片含有剧毒草酸不可食用，但多汁酸脆的茎秆加糖炖煮后，能制成令人精神大振的美味酸甜果酱。",
        en = "A crisp, tart stalk of red-and-green garden rhubarb. Blisteringly sour when gnawed raw, cooking its juicy stems with sugar produces zesty compotes, though its toxic oxalic acid leaves must be carefully discarded.",
    },
    ["rice_cooked"] = {
        zh = "用小铁锅在炭火上慢慢焖煮出来的一大碗香喷喷热白米饭。粒粒晶莹软糯且冒着热腾腾的白色蒸汽，在满是焦糊与腐烂气息的末日荒原里，捧着这碗纯粹的碳水化合物，是对疲惫身躯最踏实的救赎。",
        en = "A steaming, hearty bowl of fluffy long-grain white rice cooked over embers. Tender and moist, savoring these clean, plain carbohydrates provides pure bodily restoration after weeks of gnawing on petrified, salt-crusted emergency rations.",
    },
    ["riding_crop"] = {
        zh = "由弹性玻璃纤维杆芯外包皮革、顶端配有软皮拍的马鞭。原本用于驯马时轻拍指令，在末日中轻巧耐磨且抽击速度极快，挥动起来破空声尖锐刺耳，也能在近距离狠狠抽碎变异飞虫与微型害虫。",
        en = "A slender equestrian riding crop wrapped in braided leather and tipped with a flat popper. Light and whip-fast, it delivers sharp stinging lashes that effortlessly swat away aggressive giant wasps and pestilent vermin.",
    },
    ["rifle_22"] = {
        zh = "用一段细无缝钢管、废木块与橡皮筋拼凑而成的土制 .22 口径土枪。虽然外观粗陋得宛如随时会炸膛的玩具，击发全靠手动扳动击锤弹簧，但在没有真枪时，它能让你在安全距离外精准猎杀野兔充饥。",
        en = "A crude zip gun cobbled from scrap tubing, rubber bands, and carved 2x4 lumber. Resembling an explosive hazard waiting to happen, it reliably discharges single .22 rimfire cartridges to take small game from safety.",
    },
    ["rifle_38"] = {
        zh = "用自来水管与门闩铁件粗暴焊接而成的 .38 特种弹单发土枪。虽然打完一枪就得用铁丝把变形弹壳捅出来，但厚壁无缝管经受住了低压手枪弹考验，是穷困幸存者打发丧尸的廉价防身武器。",
        en = "A makeshift single-shot pipe rifle chambered in mild .38 Special. Requiring a screwdriver to pry spent casings loose after each blast, its thick steel water pipe barrel safely handles low pistol pressures, deterring nocturnal prowlers.",
    },
    ["rifle_44"] = {
        zh = "采用加厚高压液压管自制的 .44 麦格农土步枪。击发时枪管震颤且后坐力狂暴，粗糙的木托会狠狠砸向肩窝，但出膛的重弹威力惊人，能在十步之内将冲过来的凶悍丧尸直接打得凌空倒退。",
        en = "A hand-built firearm fashioned from heavy hydraulic tubing chambered for .44 Magnum. The brutal back-thrust bruises your collarbone with every pull, but the thunderous slug stops charging brutes dead in their tracks at short range.",
    },
    ["rifle_45_410"] = {
        zh = "既能装填 .45 柯尔特弹、也能填入 .410 霰弹的万能土制滑膛枪。结构简单到了极致，管壁厚实耐磨，让身无分文的游侠能将搜刮到的各类零散大弹药一股脑当成夺命凶器轰向敌人。",
        en = "A multi-caliber homebrew pipe gun chambering both .45 Colt cartridges and .410 shotshells. Its crude smoothbore design feeds whatever stray ammunition turns up in looted hunting lodges, providing adaptable close-quarters firepower on a shoestring budget.",
    },
    ["rifle_case_soft"] = {
        zh = "内衬厚实减震海绵、外覆耐磨尼龙面料的长款软质步枪枪袋。全长拉链开合顺畅，配有提手与单肩背带，能妥善保护娇贵的精密狙击瞄具与长枪管在颠簸路途中免遭磕碰与划痕损伤。",
        en = "A padded nylon soft rifle case lined with protective convoluted foam. Zipping shut smoothly, its reinforced webbing handles protect delicate telescopic optics and floating barrels from jostling during bumpy cross-country vehicle rides.",
    },
    ["rifle_case_soft_2"] = {
        zh = "带有中间加厚防撞隔层、可同时容纳两支全尺寸长枪的双支装步枪软包。内部配有多道魔术贴固定绑带，防止两支枪在剧烈奔跑中互相碰撞刮伤漆面，是军火搜刮者携带战利品的实用容器。",
        en = "A dual-compartment padded rifle case designed to transport two long guns simultaneously. Heavy internal dividers and hook-and-loop straps prevent fine firearms from clattering together while fleeing across jagged obstacle courses.",
    },
    ["rifle_case_soft_leather"] = {
        zh = "采用上等油鞣牛皮手工精工缝制的单支装软皮步枪套。手感细腻柔软且随着岁月沉淀出温润包浆，皮革天然的防泼水与缓冲特性，让猎手心爱的栓动步枪在荒野风雪中依然得到尊贵呵护。",
        en = "A supple oiled leather scabbard meticulously stitched for single hunting rifles. Aging with a handsome dark patina, its dense hide repels moisture and cushions prized heirloom firearms through blizzards and brambles.",
    },
    ["rifle_case_soft_leather_2"] = {
        zh = "双侧对称开合的奢华双支装真皮步枪套。厚实的黄牛皮料散发着好闻的天然皮脂芳香，内部分隔考究，两把爱枪并排沉睡其中，宛如一对被细心封存的死神孪生姐妹，兼具品味与防护。",
        en = "A double-sided luxury leather rifle case tailored from heavy cowhide. Smelling of saddle soap, its partitioned chambers cradle a matched pair of rifles securely, exuding pre-war elegance amid harsh wasteland survival.",
    },
    ["rifle_case_xl_soft_leather"] = {
        zh = "专为超长枪管重型反器材步枪或加装巨型消音器的枪械定制的特长款真皮枪套。修长优雅且皮质极其厚重，背在身后宛如一件古典乐器琴盒，能有效掩盖致命杀戮凶器的真实轮廓。",
        en = "An extra-long leather scabbard crafted for long-barrel precision rifles or suppressed sniper systems. Resembling an oversized musical instrument gig bag, it conceals imposing anti-materiel hardware from opportunistic bandits on the trail.",
    },
    ["rifle_flintlock"] = {
        zh = "击发机带有燧石夹头与传火药锅的复古燧发滑膛火枪。在现代军火弹药彻底打光后，这件古老武器重新焕发生机，只要手头有黑火药、碎铁砂或铅丸，它就能用震耳轰鸣继续收割丧尸头颅。",
        en = "A reproduction flintlock musket striking sparks into an external priming pan. When modern metallic cartridges vanish, this primitive black-powder relic shines, spitting loose scrap and cast lead balls with deafening clouds of smoke.",
    },
    ["rifle_scope"] = {
        zh = "带有 3 至 18 倍连续变倍旋钮与 44 毫米大口径镀膜物镜的步枪瞄准镜。十字分划线上带有精准密位点，调节手轮咔哒清脆，让射手能在数百米开外清晰辨认出怪物的瞳孔与喉咙弱点。",
        en = "A versatile 3-18x44 variable power rifle scope outfitted with multi-coated glass. Crisp turrets and illuminated mil-dot reticles allow patient snipers to resolve distant mutant eye sockets across shimmering thermal mirages.",
    },
    ["rifle_scope_high_end_mount"] = {
        zh = "预先安装了高刚性一体式 CNC 阳极氧化铝合金镜桥的顶级高倍瞄准镜。一体式镜架能承受大口径子弹的剧烈后坐震动而不产生丝毫位移，安装在导轨上严丝合缝，提供最极致的归零一致性。",
        en = "A premium 3-18x44 tactical scope pre-installed in a rigid, one-piece monolithic cantilever mount. Machined from aircraft-grade aluminum, it withstands punishing magnum recoil pulses without shifting zero a single fraction of a milliradian.",
    },
    ["rigid_kevlar_plate"] = {
        zh = "由多层凯夫拉芳纶纤维经由高温环氧树脂高压模压而成的硬质防弹板。既有合成纤维的吸能韧性，又有树脂板的抗凹陷刚性，塞进战术背心前后插板袋中，能完美抵挡致命破片与高速弹丸撞击。",
        en = "A rigid ballistic trauma plate molded from compressed Kevlar plies bound in cured resin. Melding fiber tensile strength with structural rigidity, it slips into armor carriers to absorb blunt trauma and stop fragmentation cold.",
    },
    ["rigid_plastic_sheet"] = {
        zh = "一整块大尺寸的高透明度聚碳酸酯刚性塑料板。抗冲击性能远超普通玻璃且质轻不易粉碎，既能切割打磨成自制防暴手盾的观察窗，也是改装避难所透光采光天窗或加固温室的理想防风建材。",
        en = "A massive, transparent sheet of impact-resistant rigid polycarbonate. Shrugging off blunt hammer blows without splintering, armorers carve it into lightweight riot shield viewports or weatherproof greenhouse skylights.",
    },
    ["ring_engagement"] = {
        zh = "戒圈由细腻白金铸造、正中镶嵌着一颗微型天然切割钻石的订婚戒指。曾经代表着山盟海誓与终身契约，如今在文明废墟中，这枚闪烁的冷冰冰小石头除了用来划开薄玻璃，只能换来一声自嘲叹息。",
        en = "A delicate platinum engagement ring mounting a brilliant-cut solitary diamond. Once enshrining lifetime devotion, in post-apocalyptic ruins this tiny glittering crystal serves little purpose beyond etching glass or sparking bittersweet sentimental memories.",
    },
    ["ring_purity"] = {
        zh = "镌刻着古典箴言的纯银贞洁誓言戒指。曾经象征着少年对纯洁自律与信仰的庄严承诺，在道德底线早已被饥饿与恐惧撕得粉碎的末日废土上，戴着它显得既荒诞滑稽又带着一种凄凉的纯真倔强。",
        en = "A simple sterling silver band inscribed with moral commitment mottos. In a lawless wasteland where survival erodes all pre-war ethics, wearing this promise of innocence looks heartbreakingly quaint and defiantly stubborn.",
    },
    ["ring_signet"] = {
        zh = "顶端刻有家族徽章图案印模的金银双色重型印章戒指。底面雕刻深邃清晰，大灾变前贵族用它在火漆上按压签署封地契约，如今在避难所交易时，它沉甸甸的贵金属分量是少数被普遍承认的硬通货。",
        en = "A heavy dual-toned gold and silver signet ring sporting a deeply engraved crest. Once pressed into warm sealing wax to ratify aristocratic treaties, its substantial precious metal heft buys real ammunition at barter outposts.",
    },
    ["ring_wedding"] = {
        zh = "戒圈由纯金与铂金交织缠绕、中央紧紧锁住一颗纯净钻石的结婚戒指。它曾许诺过直到死亡将彼此分离，如今死亡早已在大地上四处狂欢游荡，唯有这圈坚固的贵金属依然在死者苍白骨节上熠熠生辉。",
        en = "A flawless wedding band entwining strands of gold and platinum around a solitaire diamond. Pledging devotion until death does part, it now glints silently upon pale skeleton fingers while death itself roams the earth.",
    },
    ["rio_bravo"] = {
        zh = "装填 15 发 .22 LR 子弹的小猎物杠杆步枪。经典的下压杠杆动作清脆利落，虽然小威力边缘发火弹在面对巨型变异怪时如同隔靴搔痒，但连续快速收割野兔与火鸡填饱肚子却是一把好手。",
        en = "A classic lever-action small-game carbine feeding fifteen .22 rimfire cartridges through its tube magazine. While harmless against hulking monstrosities, cycling its slick action cleanly harvests wild turkeys to keep starvation at bay.",
    },
    ["riv_scope"] = {
        zh = "专为 RM11B 无壳狙击步枪系统定制的军规光电瞄准镜。内置高灵敏度激光测距传感器与弹道计算芯片，能在暴风雨或浓雾中自动修正风偏密位，是废土远距离精准狙杀的绝密光学神眼。",
        en = "The integrated RS1219 electro-optical scope designed for the RM11B caseless rifle. Housing advanced laser rangefinders and environmental ballistics computers, it computes real-time firing solutions through dense ash and torrential storms.",
    },
    ["rivets"] = {
        zh = "几颗高强度的实心退火软钢铆钉。虽然在现代电焊工眼里已经落伍过时，但在没有发电机也没有焊条的野外，只要有一把铁锤和垫铁，就能将两块厚重防弹钢板永久铆接得浑然一体。",
        en = "A handful of solid malleable steel rivets. Though eclipsed by modern welding rigs, all you need is a hammer and an anvil to bind two thick armor plates together into an indestructible, bulletproof seam.",
    },
    ["rm103a_pistol"] = {
        zh = "里夫泰克公司生产的 RM103A 大口径无壳弹自动马格农手枪。外观极具未来科幻美感，发射狂暴的大威力无壳弹药，沉重的后坐力和尖锐枪声无时无刻不在彰显着高科技军工霸权的蛮横威严。",
        en = "A futuristic caseless automagnum handgun manufactured by Rivtech. Prioritizing ostentatious aesthetics alongside terrifying chamber pressures, discharging its high-tech caseless charges delivers deafening concussive blows that shatter ceramic trauma plates.",
    },
    ["rm11b_sniper_rifle"] = {
        zh = "里夫泰克出品的 RM11B 高精度无壳弹侦察狙击步枪。全枪采用碳纤维复合轻量结构，高燃无壳弹药带来极其惊人的超高初速与激光般平直的弹道，在数百米外能无声洞穿厚重的防弹面罩。",
        en = "A lightweight caseless scout sniper rifle crafted from aerospace carbon composites. High-energy solid propellants grant its specialized projectiles hyper-velocity trajectories, punching laser-straight holes through fortified blast visors across open airfields.",
    },
    ["rm120c"] = {
        zh = "里夫泰克 RM120C 泵动式大口径无壳弹战术霰弹枪。摒弃了传统的塑料弹壳，连续推拉泵动护木上膛极其轻灵，每一次开火都会喷涌出成片致命的重合金钨砂，是清缴狭窄室内异形怪物的顶级破门炮。",
        en = "A smooth pump-action combat shotgun cycling proprietary caseless shells. Free of bulky plastic hulls, racking its forend chambers blistering clusters of tungsten buckshot that disintegrate close-range horrors into crimson vapor.",
    },
    ["rm121aux"] = {
        zh = "里夫泰克 RM121 下挂式无壳霰弹辅助武器系统。能通过导轨直接安装在突击步枪枪管下方，在步枪弹药耗尽或转角突遇变异体扑面撕咬时，瞬间提供一发毁天灭地的近身致命破门霰弹轰击。",
        en = "An underslung auxiliary caseless shotgun module that locks directly onto rifle accessory rails. Providing an instantaneous blast of close-range emergency buckshot when primary magazines run dry, it decisively resolves sudden face-to-face monster breaches.",
    },
    ["rm121aux_mod"] = {
        zh = "加装了独立手枪握把与伸缩轻型枪托的独立改装型 RM121 无壳霰弹枪。摆脱了只能下挂在主武器上的限制，变成了一把极其短小精悍的手持微型突击喷子，深受废土侦察潜行者的追捧。",
        en = "A standalone conversion of the RM121 aux shotgun outfitted with a dedicated pistol grip and compact stock. Liberated from underslung rifle rails, it serves as an ultra-compact trench broom for tight underground tunnel clearing.",
    },
    ["rm13_armor"] = {
        zh = "里夫泰克生产的 RM13 全身流线型高科技军用动力战斗装甲。目前处于休眠关机状态，哑光全黑的凯夫拉与纳米复合陶瓷护板完美贴合人体曲线，即便不通电也能提供顶级的物理防弹防刺。",
        en = "A sleek, black high-tech military exoskeleton armor suit manufactured by Rivtech. Resting in the off position, its ergonomic ceramic-composite shell and flexible Kevlar undergarments grant superb ballistic and thermal protection even unpowered.",
    },
    ["rm13_armor_on"] = {
        zh = "正在嗡嗡通电激活的高科技 RM13 全身战斗装甲。内置动力伺服电机轻柔辅助着你的每一次奔跑与挥砍，生化传感器与温度调节系统将恶劣废土彻底隔绝在外，让你化身为废土上的无敌黑色死神。",
        en = "An active RM13 combat suit humming with cybernetic power. Internal synthetic muscle fibers amplify your strength while integrated environmental seals filter radioactive fallout, turning the wearer into a lethal, impervious armored juggernaut.",
    },
    ["rm20"] = {
        zh = "里夫泰克 RM20 全自动无壳弹连发战斗霰弹枪。拥有极其惊人的全自动循环射速，扣住扳机不放能在短短两秒内将整匣无壳霰弹倾泻一空，密集的重弹幕能将坚固的砖墙与整群变异丧尸瞬间轰平。",
        en = "A ferocious full-automatic combat shotgun cycling proprietary caseless heavy shells. Emptying drum magazines within seconds, its deafening cyclic barrage shreds charging zombie swarms and pulverizes reinforced brick barriers into flying dust.",
    },
    ["rm2000_smg"] = {
        zh = "发射特种高穿透无壳弹药的里夫泰克 RM2000 冲锋枪。超高的射速让枪口吐出的枪声连成一片刺耳的电锯撕裂音，几乎感受不到后坐跳动，能在眨眼间在防弹装甲上打出一排整齐的致命穿孔。",
        en = "The high-tech RM2000 submachine gun chambered in hyper-velocity caseless ammunition. Its blistering cyclic rate hums like an electric chainsaw, punching surgical stitch-lines through heavy ballistic ceramic plates with negligible perceived muzzle rise.",
    },
    ["rm228"] = {
        zh = "专为飞行员与特勤人员设计的里夫泰克 RM228 便携单兵自卫霰弹枪。采用超短紧凑构型并使用无壳弹药，体积小巧到能塞进战术背心胸前快拔枪套，近距离轰击却具有毁灭性的致死停止力。",
        en = "A compact personal defense weapon shotgun chambered in Rivtech caseless shells. Small enough to stow in a drop-leg scabbard, its short-range concussive buckshot volleys blast armored marauders off their feet with ruthless efficiency.",
    },
    ["rm451_flamethrower"] = {
        zh = "由DARPA绝密实验室研制的紧凑型高能战术火焰喷射器。加压凝胶燃料点燃后能喷射出黏稠难熄的烈焰火柱，在清理阴暗潮湿的真菌母巢或变异蚁穴时具有无可替代的焚天神威。",
        en = "A high-tech tactical flamethrower engineered in covert DARPA labs. Unleashing high-pressure jets of sticky napalm, it incinerates fungal spires and subterranean insect nests with ruthless, blazing efficiency.",
    },
    ["rm51_assault_rifle"] = {
        zh = "原本作为正规军换装列装标准的里夫泰克 RM51 突击步枪。全枪完全摒弃抛壳窗，高密闭机匣在沙尘暴与泥浆浸泡中永不卡壳，高初速无壳弹在命中目标后剧烈翻滚碎裂，终极现代步枪杰作。",
        en = "The standard military-issue RM51 assault rifle firing caseless rounds. Sealed completely against sandstorms and toxic sludge due to its lack of ejection ports, its high-velocity ammunition fragments lethally upon impact with flesh.",
    },
    ["rm614_lmg"] = {
        zh = "里夫泰克 RM614 班用轻机枪。大容量无壳弹箱极大减轻了携行弹药的沉重金属壳死重，密集的无壳弹雨能提供持续不断的致命火力压制，狂暴开火时枪身平稳得宛如一具生根的重装火炮。",
        en = "A squad automatic light machine gun chambering Rivtech caseless cartridges. Shedding traditional metallic brass weight allows gunners to carry immense ammunition loads, pouring unrelenting suppressive streams across war-torn city squares.",
    },
    ["rm88_battle_rifle"] = {
        zh = "发射大威力全口径无壳步枪弹的里夫泰克 RM88 战斗步枪。强劲的远程动能让它能在千米之外撕开步兵战车的薄弱观察窗，虽然半自动后坐力沉重扎实，但精准的一枪足以终结任何巨型怪物的疯狂暴走。",
        en = "The heavy RM88 battle rifle engineered for full-power caseless munitions. Delivering colossal long-range terminal ballistics, a single well-placed shot punches through armored cockpit viewports to drop raging behemoths in an instant.",
    },
    ["rmi2_corpse"] = {
        zh = "一具被未知神秘巨型怪物残忍撕裂咬碎的干瘪人类遗体。胸口留着触目惊心的巨大穿刺空洞，全身水分与骨髓仿佛被某种无情口器吸食殆尽，残破的衣服碎片无声诉说着死者生前遭遇的极端恐惧。",
        en = "A horribly mutilated human corpse completely drained of moisture and marrow. Gaping puncture wounds through the crushed ribcage indicate feeding by an apex abomination, warning scavengers that unfathomable predators hunt nearby.",
    },
    ["roadmap"] = {
        zh = "大灾变前全美各州交通部门联合出版的彩色公路网络全图。清晰标注着横贯东西的高速公路、偏僻省道与服务区位置，是逃离被丧尸彻底堵死的城市废墟、规划长途车队迁徙路线的核心战略物资。",
        en = "A detailed regional highway road map printed on foldable paper. Delineating interstates, bypass routes, and truck stops, it provides crucial navigation data for routing armored survivor convoys around congested, vehicle-choked chokepoints.",
    },
    ["roasted_cattail_rhizome"] = {
        zh = "在篝火炭灰里慢火煨烤至熟透的野生香蒲草根茎。剥开焦黑的外皮露出富含淀粉的白色肉质，虽然嚼起来纤维粗硬且略带泥土腥气，但在荒野求生中它是救命的高热量主食。",
        en = "Wild wetland cattail roots roasted directly in campfire embers. Peeling away the charred skin reveals fibrous starchy flesh that tastes of river mud, yet provides crucial lifesaving calories in the wild.",
    },
    ["roasted_coffee_bean"] = {
        zh = "散发着浓郁迷人坚果与焦糖香气的烘焙咖啡豆。在满目疮痍的末日废墟中，将它们用两块石头细细研磨煮出一杯热咖啡，能唤醒麻木灵魂深处对文明的无限眷恋。",
        en = "Deeply roasted coffee beans exuding rich aromas of caramelized nuts and chocolate. Grinding them between two flat river stones brews steaming elixir that revives weary human souls amidst crumbling fallout ruins.",
    },
    ["robe"] = {
        zh = "采用轻薄柔软棉麻织物缝制而成的长袖宽松长袍。剪裁宽大透气，穿在身上毫无束缚感且能遮挡夏日烈日毒晒，虽然没有任何防弹防撕咬能力，但在安全的庇护所内睡觉或休息时极其舒适自在。",
        en = "A loose-fitting cotton robe featuring flowing sleeves and comfortable hems. Offering zero protection against feral bites or buckshot, its breathable weave shields skin from sunstroke while providing sublime comfort around the bunker.",
    },
    ["robe_wizard"] = {
        zh = "绣着神秘金色星辰与扭曲符文深蓝法师长袍。在大灾变前它可能只是万圣节扮演狂热道具，但在神秘传送门异界能量弥漫的今天，穿上它似乎真能让人产生某种能随手搓出末日火球术的荒诞狂妄幻觉。",
        en = "An arcane dark blue robe embroidered with mystical golden stars and runes. Once an eccentric cosplay costume, in a world shattered by extra-dimensional portal storms, wearing it makes you feel absurdly qualified to cast fireballs.",
    },
    ["robofac10"] = {
        zh = "枢纽 01 混合武器平台 HWP 专用的 10 发短款霰弹弹匣。结构方正坚固且供弹弹簧极其强劲，虽然容弹量有限，但在狭窄拐角近距离交火时完全不会因为弹匣过长而磕碰门框与障碍物。",
        en = "A compact 10-round box magazine designed for the Hub 01 Hybrid Weapons Platform shotgun module. Rigid polymer construction and heavy-duty follower springs ensure rapid feeding without snagging against low tunnel obstacles.",
    },
    ["robofac100"] = {
        zh = "整整装填 100 发 5.56 毫米子弹的枢纽 01 双鼓弹匣。形似黑色蜗牛壳，虽然装满子弹后沉重得手腕发酸，但在遭遇漫山遍野的狂暴尸潮时，深不见底的弹幕能提供最奢侈的火力覆盖。",
        en = "A massive 100-round dual-drum magazine for the Hub 01 rifle configuration. Resembling paired snail shells, its immense weight demands serious muscle, but dumping continuous 5.56mm streams halts overwhelming zombie charges cold.",
    },
    ["robofac20"] = {
        zh = "装填 20 发 7.62 毫米大威力步枪弹的枢纽 01 原厂直插式弹匣。采用军规强化聚合物外壳与低摩擦托弹板，在全自动射击时供弹顺畅稳定，是精准中距离猎杀变异强盗的标准弹药供给单体。",
        en = "A rugged 20-round stick magazine designed for the 7.62mm Hub 01 rifle module. Engineered with anti-tilt followers and reinforced polymer feed lips, it supplies dependable feeding for precision mid-range engagements.",
    },
    ["robofac30"] = {
        zh = "容量高达 30 发的枢纽 01 霰弹模块大号鼓形弹匣。黑色强化工程塑料外壳抗摔耐磨，内部发条机构不知疲倦地输送着大口径重霰弹，能让混合武器平台彻底化身为一台横扫战场的近战绞肉炮。",
        en = "A high-capacity 30-round drum magazine for the Hub 01 shotgun configuration. Its heavy-duty internal clockwork spring reliably drives large-gauge shells into the chamber, transforming the modular weapon into an unstoppable bunker-clearing whirlwind.",
    },
    ["robofac40"] = {
        zh = "可容纳 40 发 5.56 毫米子弹的加长款枢纽 01 步枪弹匣。比普通 30 发弹匣多出整整十发续航，却完全没有鼓形弹匣那般笨重累赘，是在战火纷飞的突击行动中兼顾机动与压制火力的黄金平衡选择。",
        en = "An extended 40-round polymer magazine tailored for 5.56mm Hub 01 weapon receivers. Offering ten additional rounds over standard military mags without the cumbersome bulk of drums, it strikes a sweet spot during dynamic skirmishes.",
    },
    ["robofac50"] = {
        zh = "装载 50 发 7.62 毫米大威力步枪弹的枢纽 01 专用旋涡弹鼓。沉甸甸的金属与工程塑料构架结实耐操，能让半自动精确射手步枪瞬间化身班用机枪，在远距离阻击战中将成排的敌对车队打得千疮百孔。",
        en = "A 50-round drum magazine engineered for 7.62mm Hub 01 configurations. Adding substantial firepower to battle rifles, it delivers sustained suppressive fire capable of disabling light convoy trucks and piercing fortified sandbag nests.",
    },
    ["robofac60"] = {
        zh = "采用精密螺旋输弹结构的枢纽 01 专用 60 发 9 毫米螺旋筒状弹匣。外形宛如一根粗壮的黑色圆筒，将整整六十发手枪弹紧凑收拢其中，重心平衡极佳，提供难以置信的超长冲锋泼水续航。",
        en = "A compact 60-round helical magazine chambering 9mm ammunition for the Hub 01 platform. Storing rounds along a spiraled internal drum, its sleek cylindrical profile provides immense submachine gun volume without awkward protrusions.",
    },
    ["robofac60_123ln"] = {
        zh = "专为 12.3 毫米重型口径特种枪机定制的枢纽 01 巨型大容量弹匣。能稳定容纳整整 60 发超大口径穿甲子弹，沉重的分量在扣下扳机的那一刻，会化作摧枯拉朽的金属风暴将前方一切障碍撕成碎片。",
        en = "A colossal box magazine feeding sixty massive 12.3mm rounds into custom Hub 01 receivers. Packing monumental armor-piercing kinetic payload, unloading this magazine shreds engine blocks and collapses concrete perimeter walls in seconds.",
    },
    ["robofac_armor_anchor"] = {
        zh = "枢纽 01 专为废土边境探险家量身定制的模块化防具披风底座。目前处于未激活休眠状态，采用抗撕裂纳米面料与快拆插扣结合，不仅能作为防风雨斗篷，更是外挂各种强化装甲板的核心固定龙骨。",
        en = "A modular defense anchor poncho tailored by Hub 01 engineers. Resting deactivated for now, its tear-resistant synthetic fabric repels radiation rain while serving as the foundational mounting chassis for external ballistic plates.",
    },
    ["robofac_armor_anchor_on"] = {
        zh = "正在开启通电工作的枢纽 01 模块化防御装甲底座。微型电路平稳运行，将挂载的防弹模块与能量缓冲层完美联动，在抵挡弹片暴击的同时极佳分散冲击钝力，是前线探险家最坚不可摧的移动堡垒。",
        en = "An activated Hub 01 defense anchor poncho humming with battery-powered stabilization circuits. Seamlessly distributing kinetic impacts across interlocking modular hard plates, it provides forward scouts with a resilient, high-tech personal shield.",
    },
    ["robofac_armor_rig"] = {
        zh = "整合了胸腹重型复合防弹插板与高透气战术骨架的枢纽 01 模块化防具全套战术背心。不仅能正面硬抗大威力步枪弹的近距离贯穿，多功能快拆插槽更能让你随身携带海量弹匣与急救医疗包，固若金汤。",
        en = "A complete modular defense rig designed by Hub 01, integrating composite chest plates with load-bearing harnesses. Stopping rifle rounds dead in their tracks, its quick-disconnect hardpoints organize magazines and trauma dressings cleanly.",
    },
    ["robofac_basic_greaves"] = {
        zh = "采用工业级 3D 打印技术快速成型的厚实聚合物护膝与胫甲。材料兼具韧性与硬度，能完美抵挡路边荆棘灌木刮擦、碎石飞溅以及矮小变异生物的阴毒撕咬，在剧烈跪姿射击时为膝关节提供极致缓冲。",
        en = "A pair of 3D-printed modular polymer greaves featuring thickened articulated knee caps. Resisting jagged gravel, brambles, and snapping ankle-biters, they absorb hard kneeling impacts during rapid tactical firing stances.",
    },
    ["robofac_basic_helmet"] = {
        zh = "枢纽 01 工业 3D 打印试制的高分子防弹头盔。外壳线条硬朗且充满几何未来感，内部衬有定制记忆发泡吸能垫，虽然略显厚重，但在面对飞溅跳弹与变异怪物当头一爪时，能保全你的头盖骨完好无损。",
        en = "A 3D-printed prototype ballistic helmet constructed from thick impact polymers. Its angular geometric shell deflects stray shrapnel, while internal memory foam suspension rings protect against skull-fracturing concussive monster strikes.",
    },
    ["robofac_basic_mantle"] = {
        zh = "保护上胸口、颈部与肩部关节的 3D 打印厚聚合物披肩护甲。采用模块化搭扣设计，严密覆盖了人体最脆弱的锁骨与大动脉区域，在面对丧尸扑咬时能有效阻断牙齿刺穿，是新手探险者的实用保命轻甲。",
        en = "A 3D-printed modular mantle protecting the shoulders, clavicles, and neck. Snapping over tactical jackets, its tough polymer plates shield vulnerable carotid arteries from sudden ambush bites in close-quarters skirmishes.",
    },
    ["robofac_basic_skirt"] = {
        zh = "由多片 3D 打印铰接聚合物甲片组合而成的大腿与腹股沟战术护裙。随着双腿迈步自然摆动，完全不阻碍奔跑与翻越障碍物，同时为缺乏骨骼保护的腹部与股动脉提供极具安全感的抗穿刺防护。",
        en = "An articulated 3D-printed armored skirt safeguarding the thighs and groin. Swiveling smoothly with running strides, its overlapping polymer flaps protect delicate femoral arteries from serrated claws without impeding obstacle vaulting.",
    },
    ["robofac_basic_vambraces"] = {
        zh = "3D 打印成型的大面积柔韧聚合物手臂护腕。内部配有亲肤透气衬垫与多道加固松紧绑带，能完美抵挡近身格斗中利刃的劈砍与尖牙啃咬，抬手格挡时让你拥有敢与怪物硬碰硬的底气。",
        en = "A pair of 3D-printed forearm vambraces crafted from impact-resistant flexible polymers. Padded with breathable mesh, they cushion desperate parrying blocks against rusted blades and snapping mutant jaws without adding dead weight.",
    },
    ["robofac_enviro_suit"] = {
        zh = "由枢纽 01 制造、融合了凯夫拉纤维与高密封合成膜的轻型防化生化防护服。不仅具有极佳的耐磨防刮性能，其内置高效过滤膜更能完全隔绝外界致命辐射尘、酸雨腐蚀以及生化孢子入侵。",
        en = "A lightweight environmental hazardous-materials suit fabricated with Kevlar weaves and chemical-resistant membranes. Providing remarkable puncture resistance, its airtight seals safeguard delicate internal organs from airborne radiation and corrosive acid rain.",
    },
    ["robofac_enviro_suit_casual"] = {
        zh = "由Hub01研发的轻便休闲型生化防护服。面料透气舒适且具备不错的防化防尘效果，外形剪裁颇具未来科技感，让你在满是酸雨与真菌孢子的野外巡逻时依然保持体面。",
        en = "A sleek lightweight environmental suit engineered by Hub 01 technicians. Balancing breathable comfort with chemical resistance, its futuristic tailoring keeps scouts remarkably stylish while trudging through toxic acid drizzles.",
    },
    ["robofac_gun"] = {
        zh = "枢纽 01 研发的颠覆性多口径混合武器平台原型枪。采用先进的模块化快拆机匣构型，只要更换枪管和供弹模块，就能在突击步枪、冲锋枪与重口径喷子之间自由切换，是全天候终极单兵武器库。",
        en = "The revolutionary Hub 01 Hybrid Weapons Platform. Featuring a quick-change modular receiver, swapping barrel inserts transforms it from an assault rifle to a close-quarters shotgun, delivering unmatched tactical adaptability across unpredictable ruins.",
    },
    ["robofac_gun_40mm"] = {
        zh = "采用紧凑模块化气动发射原理的Hub01战术四十毫米榴弹发射器。后坐力温和平顺，能将各色高爆弹或催泪毒气弹精准甩入两百米外的掩体枪眼，是攻坚破障的大杀器。",
        en = "A compact pneumatic 40mm launcher engineered by the Hub 01 robotics collective. Delivering soft recoil and pinpoint accuracy, it lobbs high-explosive payloads straight through distant sniper bunker slits.",
    },
    ["robofac_gun_40mm_10rd"] = {
        zh = "容量高达 10 发的 40 毫米低速榴弹专用巨型箱式弹匣。硕大的弹匣箱插在专用重型发射器下方，能在几秒钟内将十枚高爆榴弹或燃烧弹倾泻在敌方阵地上，化作彻底毁灭一切的焦土风暴。",
        en = "A gargantuan 10-round box magazine designed for 40x46mm grenade launcher platforms. Feeding high-explosive ordnance smoothly, unleashing its contents carpets enemy strongpoints in rolling thunder, concussive shrapnel, and roaring infernos.",
    },
    ["robofac_gun_40mm_3rd"] = {
        zh = "容纳 3 发 40 毫米低速榴弹的短款箱式弹匣。体积比全尺寸弹匣紧凑小巧许多，虽然持续轰炸火力有限，但在逼仄的下水道或狭小房门前，能提供恰到好处的破门面杀伤而不会卡住墙角。",
        en = "A stubby 3-round box magazine tailored for 40x46mm launcher modules. Considerably more maneuverable than full-sized drums, it delivers three decisive concussive explosive packets without catching on tight basement doorframes.",
    },
    ["robofac_gun_40mm_5rd"] = {
        zh = "装填 5 发 40 毫米榴弹的折中型容量弹匣。在单兵负重与压制火力之间达到了极佳平衡，连续射出的五发高爆弹或烟雾弹足以彻底瓦解强盗路障，是前线突击兵的最爱武器挂件。",
        en = "A balanced 5-round box magazine for 40mm grenade systems. Striking an optimal balance between carry weight and explosive firepower, five rapid high-explosive volleys are more than enough to obliterate fortified roadblocks.",
    },
    ["robofac_gun_57"] = {
        zh = "将枢纽 01 混合武器平台转换为发射 5.7x28 毫米高穿透弹药的个人防卫套件。枪身轻便无感且后坐力柔和，配合 50 发大容量弹匣，能以极高初速轻易打穿轻型防弹背心与变异甲壳。",
        en = "A personal defense conversion module chambering the Hub 01 weapon in 5.7x28mm. Offering gentle recoil and feeding from high-capacity magazines, its armor-piercing darts punch effortlessly through Kevlar flak jackets and insect carapaces.",
    },
    ["robofac_gun_ar"] = {
        zh = "枢纽 01 经典 5.56 毫米突击步枪全套转换模块。装上它即刻获得全尺寸步枪的威力和充沛射程，军规导气系统在冰原与酸雨泥泞中运转自如，是废土游侠探索未知感染区的中流砥柱。",
        en = "The standard 5.56mm assault conversion package for the Hub 01 platform. Granting full-length rifle velocities and dependable gas cycling through freezing sleet, it remains the ultimate versatile workhorse for frontline wasteland expeditions.",
    },
    ["robofac_gun_dmr"] = {
        zh = "为枢纽 01 混合枪械定制的 7.62 毫米精确射手步枪套件。配有长重型精锻枪管与精密导气活塞，能在远距离提供手术刀般精准的单发点杀能力，将远处的变异首领在暴起前当场爆头击杀。",
        en = "A 7.62mm designated marksman rifle conversion module featuring an extended heavy match barrel. Delivering surgical single-shot accuracy across sweeping vistas, it drops high-threat mutant alpha targets before they enter charge range.",
    },
    ["robofac_gun_exodii"] = {
        zh = "融合了异界伊克索迪控制台特种外星科技的混合武器奇特转换构型。发射神秘的高速奇异弹药，枪机内部闪烁着非人类机械的奇异光晕，开火时带着空间撕裂般的刺耳颤音，威能深不可测。",
        en = "An exotic conversion package marrying Hub 01 engineering with alien Exodii technologies. Firing bizarre high-velocity flechettes with a spatial hum, its non-human mechanical linkages channel devastating, reality-bending kinetic energy downrange.",
    },
    ["robofac_gun_kit"] = {
        zh = "印有枢纽 01 科技发光标识的重型专用武器维护工具包。内含微型扭力扳手、口径转换校准规、高级聚四氟乙烯润滑剂与备用销轴，是保证复杂混合武器平台永不卡壳的关键后勤圣物。",
        en = "A rugged field armorer kit bearing the Hub 01 emblem. Containing precision torque wrenches, headspace gauges, and Teflon lubricants, it keeps complex multi-caliber modular weapon platforms functioning flawlessly without catastrophic mechanical jams.",
    },
    ["robofac_gun_shotgun"] = {
        zh = "将枢纽 01 武器平台快速变为大口径近战泵动霰弹枪的模块总成。沉重的滑膛枪管能容纳各种常规 12 号霰弹与重头弹，近身轰击时能将冲过来的任何变异怪肉体直接打得倒飞碎裂。",
        en = "A close-quarters shotgun module transforming the Hub 01 into a devastating 12-gauge close-quarters powerhouse. Digesting heavy buckshot and solid slugs, its point-blank kinetic hammer blows splatter leaping horrors across adjacent walls.",
    },
    ["robofac_gun_shotgun_breach"] = {
        zh = "配备粗齿破门制退器与超短枪管的枢纽 01 破障霰弹枪模块。专为暴力轰碎防弹门锁与铰链而设计，能在抵近开火瞬间释放狂暴冲击波，撕碎防盗门的同时重创门后埋伏的任何活物。",
        en = "A breacher shotgun module outfitted with a jagged stand-off muzzle brake. Engineered for blowing hinges off reinforced steel vaults, its point-blank explosive blast simultaneously disintegrates security barricades and ambushing monstrosities lurking behind.",
    },
    ["robofac_gun_smg"] = {
        zh = "将平台压缩为高射速 9 毫米便携冲锋枪的战术转换套件。紧凑的枪机让整枪全长缩减到极致，扣下扳机即可倾泻出如雨点般密集的手枪弹丸，是清理狭窄电梯井与废弃车厢的绝对王者。",
        en = "A high-speed 9mm submachine gun conversion module for the Hub 01. Shrinking the platform into an ultra-compact form factor, its rapid automatic fire suppresses cramped elevator shafts and abandoned subway cars.",
    },
    ["robofac_handguard"] = {
        zh = "集成了下挂垂直防滑前握把的军用高强度复合材料护木。在剧烈连发射击时能提供极佳的控枪支点，有效抑制枪口剧烈上跳，并阻隔长时间扫射时导气管传来的滚烫灼人高温。",
        en = "A reinforced composite handguard featuring an integrated forward vertical grip. Suppressing fierce muzzle climb during full-auto bursts, it shields shooter palms from scorching barrel heat radiated during intense firefights.",
    },
    ["robofac_hardcase"] = {
        zh = "带有高抗冲阻燃外壳与气密压力平衡阀的国防高级研究计划局军规重型手提箱。内部填充有定制防震开孔海绵，即便从悬崖跌落或被压路机碾压，也能确保内部精密仪器与高科技枪械完好无损。",
        en = "A heavy-duty DARPA waterproof hard case equipped with automatic pressure valves and dense pick-and-pluck foam. Impervious to vehicle rollovers and cliffside drops, it safeguards delicate cybernetic prototypes and optics from catastrophic field damage.",
    },
    ["robofac_head_rig"] = {
        zh = "枢纽 01 专为废土边境侦察员量身打造的模块化兜帽头套。采用轻薄抗撕裂芳纶面料，兼顾了保暖与防风沙侵袭，内部预留了大量数据接口与导轨卡扣，可随意无缝加装各类夜视仪与战术面罩。",
        en = "A modular reconnaissance headgear hood engineered by Hub 01. Woven from tear-resistant aramid textiles, it blocks choking dust storms while providing standardized mounting rails for optical viewfinders, night-vision NODs, and ballistic face shields.",
    },
    ["robofac_head_rig_ar"] = {
        zh = "加装了视网膜增强现实 AR 投影透镜的枢纽 01 战术侦察头套。眼前的微型光导纤维能在视网膜上实时标示夜间环境轮廓、热源目标距离与弹药余量，让凡人在漆黑夜色中拥有神明般的战术全知视角。",
        en = "A high-tech recon hood integrating binocular augmented reality retinal displays. Overlaying thermal outlines, waypoint markers, and ammunition counters straight onto your visual cortex, it grants tactical omnipotence in moonless night battles.",
    },
    ["robofac_head_rig_ar_on"] = {
        zh = "处于全息增强现实开机状态的Hub01战术头环。眼前的半透明光幕实时标注出风速、测距与目标弱点轮廓，但过度密集的警报数据流很容易让精神衰弱的射手头晕目眩。",
        en = "An active augmented reality head rig projecting glowing HUD tactical feeds. Superimposing range calculations and weak-point silhouettes across your vision, its frantic data streams occasionally overwhelm exhausted operators.",
    },
    ["robofac_head_rig_nv"] = {
        zh = "集成了微光夜视与前视红外热成像的双光谱Hub01侦察头环。无论面对漆黑一片的地下防空洞还是弥漫着白色烟幕的战场，都能将潜伏怪物的热辐射轮廓看得清清楚楚。",
        en = "Dual-spectrum reconnaissance headgear combining thermal imaging with high-gain night vision. Piercing ink-black darkness and blinding chemical smoke, it renders lurking predators completely visible behind drywall partitions.",
    },
    ["robofac_kevlar_greaves"] = {
        zh = "采用Hub01高密度多层凯夫拉与碳纤维复合打造的轻量防弹护胫。能够抵挡近距离手枪弹与破片的直击，柔韧的贴合设计在跨越矮墙或快速冲刺时几乎感受不到阻力。",
        en = "Ballistic greaves molded from multi-layered Kevlar composites by Hub 01 armorers. Halting point-blank shrapnel without adding cumbersome bulk, they let scouts vault fractured masonry at full sprint.",
    },
    ["robofac_kevlar_helmet"] = {
        zh = "造型前卫且防护出色的Hub01凯夫拉轻量化战术头盔。内部衬有高吸能凝胶衬垫，在被破片手雷或大口径流弹擦过时，能保护佩戴者的颅骨免受脑震荡骨折重创。",
        en = "An advanced composite helmet manufactured in sealed subterranean robotic facilities. Lined with impact-absorbing gel pads, it deflects high-velocity shrapnel while mitigating concussive blunt trauma from close detonations.",
    },
    ["robofac_kevlar_mantle"] = {
        zh = "覆盖双肩与上胸部的Hub01凯夫拉防弹短斗篷。能严密守护颈动脉与锁骨等致命薄弱部位，在室内短兵相接的遭遇枪战中，它曾挡下过无数阴险致命的跳弹反弹。",
        en = "A contoured ballistic mantle draping protective Kevlar over neck and clavicle zones. Shielding fragile jugular arteries during violent room-clearing operations, it faithfully absorbs ricocheting buckshot sprays.",
    },
    ["robofac_kevlar_skirt"] = {
        zh = "悬挂在战术腰带下方的Hub01防弹战术护裙。分瓣式的凯夫拉甲片在不妨碍奔跑与下蹲的同时，为骨盆与大腿股动脉提供了密不透风的防破片掩护，防御力极佳。",
        en = "Articulated ballistic groin skirts crafted from dense Kevlar fabric by automated weavers. Permitting full running stride, they guard femoral arteries against upward-splashing fragmentation mines and razor-wire snags.",
    },
    ["robofac_kevlar_vambraces"] = {
        zh = "采用防弹芳纶纤维精密层压而成的Hub01轻型护臂。既能稳稳接下变异犬扑击时的尖牙撕扯，又能防止在碎玻璃窗框里进出时割伤小臂肌腱，是潜行搜刮的良伴。",
        en = "Lightweight composite armguards woven from high-tensile aramid fibers. Shrugging off gnashing beast fangs and jagged window glass during hasty window breaches, they preserve crucial forearm tendons intact.",
    },
    ["robofac_laser_sight"] = {
        zh = "直接嵌入在护木内部的枢纽 01 一体式战术激光指示器。无需外挂额外笨重导轨夹具，按下微动开关即可在目标胸口投射出清晰可见的明亮光点，在狭窄昏暗地道中出枪即中，毫无累赘外形。",
        en = "An integrated visible laser sight recessed directly into the Hub 01 weapon forend. Activating via momentary pressure pads, it projects an intense targeting dot onto threats, eliminating sight-alignment delay in gloomy ruins.",
    },
    ["robofac_lens_helmet"] = {
        zh = "枢纽 01 研发的低延迟外骨骼神经传感防弹头盔，目前处于关机状态。外壳由多层钛合金与陶瓷复合压制，后脑勺带有神经数据接驳口，只要装上电池，就能将外部战场态势以电信号直连大脑。",
        en = "A Low-latency ExoNeural Sensory ballistic helmet developed by Hub 01, resting offline. Forged from titanium-ceramic composites, its occipital neural links await power cells to stream high-fidelity battlefield telemetry directly into the wearer's brain.",
    },
    ["robofac_lens_helmet_on"] = {
        zh = "正在嗡嗡通电工作的枢纽 01 透镜神经头盔。眼罩内流淌着数字化全景战术视野，毫秒级的全息热成像将隐藏在拐角背后的变异潜伏者暴露无遗，并能以神经直觉辅助射击，凡人飞升的数字化感官。",
        en = "An active Hub 01 LENS helmet pulsing with cybernetic awareness. Holographic thermal feeds highlight ambushing horrors lurking behind drywall, while direct neural target-tracking loops drastically sharpen shooting reaction times to superhuman levels.",
    },
    ["robofac_lens_helmet_pat"] = {
        zh = "经过野外机修工匠粗暴打磨改良的透镜神经头盔。虽然焊补的走线和裸露电容略显粗糙，但解除了原厂的安全功耗限制，目前处于关闭待机状态，是废土老兵最信赖的自制神经外骨骼中枢。",
        en = "A field-modified Hub 01 LENS helmet patched with visible jumper wires and soldered capacitors. Deactivated for now, bypassing factory safety firmware allows seasoned wasteland veterans to overclock sensory inputs beyond standard manufacturer limits.",
    },
    ["robofac_lens_helmet_pat_on"] = {
        zh = "正在全功率超频运转的改装版透镜神经头盔。虽然强劲的电流刺激会让太阳穴隐隐刺痛，但眼前的微光夜视与电磁感知被推至极限，甚至能察觉到隐形传送门生物带起的细微空气电离涟漪。",
        en = "An overclocked custom LENS helmet actively buzzing with raw electrical current. While mild neural feedback aches at your temples, its hypersensitive sensory arrays detect faint ion turbulence stirred by cloaked, extra-dimensional monstrosities.",
    },
    ["robofac_lens_mask_bal"] = {
        zh = "配有大量微型泄压透气孔的枢纽 01 透镜防弹战术面罩。厚实的高硬度碳化硅陶瓷板能正面格挡手枪弹直接射击，细密的斜切透气孔既保证了呼吸顺畅，又完全杜绝了飞溅跳弹钻入面颊的致命危险。",
        en = "A ballistic face mask with many tiny vents holes, designed to form a tight, comfortable seal with the Hub 01 LENS helmet. Machined silicon carbide plates deflect shrapnel without compromising airflow.",
    },
    ["robofac_lens_mask_filter"] = {
        zh = "内置双侧紧凑型颗粒物滤毒棉舱的透镜系统过滤防护面罩。与防弹头盔严密卡扣锁定，不仅能阻挡物理破片撞击，更能过滤掉荒野漫天飞舞的致命放射性火山灰、工业煤烟与变异植物的剧毒花粉。",
        en = "A ballistic face mask featuring integrated dual particulate filter ports. Locking tightly against the LENS helmet frame, it repels incoming shrapnel while scrubbing out choking ash, toxic soot, and weaponized mutant pollen.",
    },
    ["robofac_lens_mask_gas"] = {
        zh = "达到最高军用 CBRN 防护标准的透镜全密封防化毒气面罩。厚实的丁基橡胶密封圈紧紧吸附在面庞上，能彻底隔绝一切神经毒气、浓芥子气、生物炭疽孢子与高剂量辐射尘，毒雾深处的避风港湾。",
        en = "A military CBRN-rated hermetic gas mask engineered for the LENS platform. Thick butyl seals bond around facial contours, completely isolating mucous membranes from sarin vapors, blister agents, and lethal airborne biohazard clouds.",
    },
    ["robofac_lens_mask_papr"] = {
        zh = "带有微型电动鼓风增压动力送风系统的透镜 PAPR 正压防毒面罩。电池驱动的微型离心泵源源不断地向面罩内输送纯净正压空气，呼吸毫无阻力且镜片永不起雾，在恶臭毒沼中奔跑依然呼吸自如。",
        en = "A powered air-purifying respirator ballistic mask driven by a micro-blower fan. Forcing filtered air into the facepiece under positive pressure, it eliminates breathing resistance and prevents interior lens fogging during grueling marches.",
    },
    ["robofac_military_greaves"] = {
        zh = "采用军规重型复合装甲板压制的Hub01士兵防弹胫甲。沉重坚硬的金属骨架提供了顶级的防劈砍与抗压爆能力，即便被重型变异丧尸正面狠踹一脚也能屹立不倒。",
        en = "Reinforced military greaves forged for heavy frontline infantry deployment by Hub 01. Combining rigid alloys with ballistic weaves, they absorb concussive shockwaves and brute stomps without buckling.",
    },
    ["robofac_military_helmet"] = {
        zh = "带有全覆式硬质外壳的Hub01军规重型步兵头盔。整合了护耳与后颈护盾，能正面硬顶全威力步枪弹的直击，虽然分量沉重压迫颈部，但安全感令人叹为观止。",
        en = "Full-coverage combat helmets deployed by automated facility garrisons. Engineered to resist direct rifle fire, its hardened shell provides comforting cranial invulnerability during desperate trench standoffs.",
    },
    ["robofac_military_mantle"] = {
        zh = "采用防弹钢板与复合陶瓷加固的Hub01重装士兵护肩护颈披肩。厚重的护甲严丝合缝地扣在胸前，在抵御从天花板突然俯冲的变异飞禽突袭时犹如一副坚固的铁铸枷锁。",
        en = "A heavy soldier mantle reinforced with ceramic inserts and steel plating. Fastened securely across chest harnesses, it repels swooping avian predators and falling concrete slabs without flinching.",
    },
    ["robofac_military_skirt"] = {
        zh = "下摆垂至膝盖部位的Hub01重型模块化军规战裙。重叠的厚实装甲片犹如微型推土机挡板，无论是在雷区探路还是强行冲卡，都能确保下半身要害免遭狂暴破坏。",
        en = "Heavy overlapping armored skirts descending over thigh and knee joints. Operating like walking bulldozer shields, they protect lower extremities from directional explosive traps and savage claw sweeps.",
    },
    ["robofac_military_vambraces"] = {
        zh = "加厚硬质装甲构筑的Hub01军用机械臂甲。前臂外侧带有突出的耐磨强化棱脊，在贴身肉搏中举臂格挡敌人的铁棍重砸时，发出的金铁脆响足以震碎对方的虎口。",
        en = "Hardened composite vambraces fitted with raised deflection ribs along the forearms. Raising them to block swinging iron pipes turns bone-shattering impacts into harmless metallic ringing.",
    },
    ["robofac_mobile_weather_station"] = {
        zh = "装在坚固手提箱内部的移动式环境辐射与微气象监测分析工作站。升起折叠式风速计和盖革传感器探头，便能精准测定环境温湿度、酸雨酸度与放射性沉降速率，是探险车队规避极端灾害的气象参谋。",
        en = "A portable environmental monitoring station packed inside a weatherized Pelican trunk. Deploying telescoping sensors, it analyzes ambient humidity, acid rain acidity, and fallout decay rates, charting safe routes around catastrophic anomalies.",
    },
    ["robofac_nomex_greaves"] = {
        zh = "采用诺梅克斯阻燃特种芳纶与耐热陶瓷复合制造的Hub01防火护胫。穿戴它跨越熊熊燃烧的汽油火海时如同闲庭信步，丝毫不用担心靴筒被滚烫的熔渣引燃。",
        en = "Thermal-resistant turnout greaves layered with Nomex cloth and ceramic insulations. Permitting confident strides through raging petroleum infernos, they prevent burning slag from melting your footwear.",
    },
    ["robofac_nomex_helmet"] = {
        zh = "配有金质耐高温反射面罩的Hub01特种消防防火头盔。不仅能阻挡高达上千度的剧烈热辐射，还能在浓烟滚滚的地下火灾现场保证头部免受落瓦砸击与烈焰灼烧。",
        en = "A high-temperature protective helmet equipped with a gold-coated heat-reflective visor. Resisting blistering thermal flash, it keeps heads cool and unscathed when clearing flaming laboratory ruins.",
    },
    ["robofac_nomex_mantle"] = {
        zh = "垂至前胸后背的Hub01长款耐火阻燃斗篷。厚实的阻燃面料能将狂暴喷火丧尸吐出的烈焰完全隔绝在外，给勇敢冲入火场抢救物资的拾荒队员筑起不可动摇的防火屏障。",
        en = "A protective turnout mantle shielding shoulders and chest from radiant combustion. Completely immune to melting, it repels fireballs belched by blazing mutant horrors during frantic urban rescue sweeps.",
    },
    ["robofac_nomex_skirt"] = {
        zh = "阻燃防火织物多层复合剪裁的Hub01战术护裙。有效防止地面翻滚的燃烧油料沾染并烧毁裤管，在遍布火灾陷阱的废弃化工厂里是不可多得的保命救星。",
        en = "A heat-deflecting protective skirt tailored from heavy layered Nomex fabric. Preventing burning fuel splashes from igniting trouser hems, it proves invaluable when exploring chemical facility fires.",
    },
    ["robofac_nomex_vambraces"] = {
        zh = "能够耐受极端明火直烤的Hub01阻燃耐热臂甲。在被烈焰缠身的焦尸伸手撕扯时，你可以毫无顾忌地抬手将其一把推开，而手臂皮肤甚至感受不到多余的热浪侵袭。",
        en = "Thermal-resistant forearm protectors lined with multi-layer aramid insulation. Bracing against burning zombie limbs allows operators to shove flaming abominations backward without singeing hair or blistering skin.",
    },
    ["robofac_poncho_liner"] = {
        zh = "被前线军人亲切称为乌比神毯的枢纽 01 纳米聚酯保暖披风内胆。重量轻若鸿毛却能在零下严寒中锁住全身热量，折叠起来仅有拳头大小，既能绑在披风内部当保暖夹层，也是夜晚抵御失温的魔毯。",
        en = "A quilted synthetic poncho liner revered by soldiers as the legendary 'woobie.' Feather-light yet capturing immense radiant body heat, it snaps into tactical ponchos or wraps around shivering limbs during sub-zero bivouacs.",
    },
    ["robofac_resonance_suit"] = {
        zh = "枢纽 01 研制的重型异界空间共振有害物质特种防护服。目前处于未激活断电状态，厚实的凯夫拉涂层下编织着致密的超导抗畸变网丝，专为深入裂隙频发的异界实验室搜刮而设计，防护登峰造极。",
        en = "A heavy-duty hazmat suit engineered by Hub 01, resting offline. Beneath thick Kevlar fabric lies a dense mesh of superconducting resonance-dampening wires designed to shield daring scavengers venturing into unstable dimensional rift zones.",
    },
    ["robofac_resonance_suit_on"] = {
        zh = "正在开启通电循环的重型异界共振防护服。超导网格在周身建立起一层肉眼难辨的微弱相位缓冲场，不仅彻底阻断一切强腐蚀酸液与烈火，更能中和虚空裂隙散发的心灵扭曲辐射，宛如人间泰坦装甲。",
        en = "An activated hazardous-environment suit humming with active resonance harmonic fields. Erecting an invisible phase buffer, it completely neutralizes corrosive chemical pools and dampens reality-warping mental radiation emitted by Nether portals.",
    },
    ["robofac_robotrig"] = {
        zh = "经过深度改装的军用无人机操作员重型战术背带。加宽的受力背带上布满了无人机专用快拆挂钩、备用锂电池夹与遥控天线支架，能让一名机师单兵随身携带并快速部署多架微型侦察四旋翼蜂群。",
        en = "A heavily modified military load-bearing harness configured for drone operators. Reinforced webbing channels balance heavy lithium battery banks, antenna leads, and snap-release holsters for carrying multiple autonomous quadcopter scouts into the field.",
    },
    ["robofac_rubber_greaves"] = {
        zh = "采用重型绝缘高弹性高分子橡胶浇铸而成的动能护胫。不仅能完美绝缘放电丧尸狂暴的十万伏特高压电弧，在被巨石撞击时还能凭借橡胶弹性吸收大部分钝击冲量。",
        en = "Shock-absorbing greaves molded from dense dielectric vulcanized rubber. Completely insulating against crackling electrical discharges from shocker zombies, the flexible compound softens brutal blunt impacts.",
    },
    ["robofac_rubber_helmet"] = {
        zh = "经过全密封绝缘防电击涂层处理的Hub01动能防护头盔。外壳拥有惊人的弹性吸能结构，戴上它面对电磁变异体的雷霆打击时，能彻底消除触电休克与头骨碎裂的危险。",
        en = "A dielectric safety helmet engineered to dissipate electrostatic arcs and kinetic concussions. Deflecting lightning bursts from mutated husks, its rubberized shell saves wearers from fatal neural overload.",
    },
    ["robofac_rubber_mantle"] = {
        zh = "加厚绝缘橡胶精制而成的防电击护肩斗篷。覆盖了脖颈与锁骨部位的导电弱点，在暴雨天气的开阔原野上遭遇高压电击怪突袭时，这层厚橡胶就是隔绝死神的绝缘壁垒。",
        en = "A thick rubberized mantle providing total electrical insulation across the upper torso. Shrugging off lightning bolts in pouring thunderstorms, it lets scavengers neutralize shocker mutants without electrocution.",
    },
    ["robofac_rubber_skirt"] = {
        zh = "重型抗震防电击橡胶挂裙。垂挂在腰间不仅能抵挡飞溅的酸液与烂泥，在涉水穿过带有漏电高压电缆的水坑时，能确保电流不会顺着双腿击穿心脏要害。",
        en = "A protective kinetic skirt crafted from flexible heavy-gauge rubberized sheets. Deflecting splashing caustic puddle slime, it prevents lethal current from traversing legs when wading near severed power conduits.",
    },
    ["robofac_rubber_vambraces"] = {
        zh = "由致密绝缘合成橡胶压铸的动能防护臂甲。在挥动电击警棍或近身格挡放电丧尸的抓咬时毫无触电后顾之忧，厚实的回弹橡胶更是能硬顶铁锤的沉重钝砸。",
        en = "Heavy rubber forearm guards designed for hazardous electrical demolition work. Absorbing brutal shocks from both swinging blunt pipes and crackling stun batons, they keep defensive limbs completely grounded.",
    },
    ["robofac_stock"] = {
        zh = "可多档调节长度与贴腮高度的无托枪械专用人体工学枪托。尾部带有厚实的蜂窝状吸能橡胶垫，安装在枢纽 01 枪身后能极大改善贴腮瞄准舒适度，并将全威力步枪弹的暴烈后坐力化解为柔顺的后推。",
        en = "An adjustable ergonomic replacement buttstock engineered for bullpup weapon configurations. Featuring a shock-absorbing honeycomb rubber recoil pad, it improves cheek weld consistency and cushions violent battle rifle back-thrust significantly.",
    },
    ["robofac_test_data"] = {
        zh = "存储在Hub01加固数据卡里的原型输入输出测试记录仪。里面密密麻麻记录着自动化仿生外骨骼在极限压力下的伺服电机传感数据，在避难所工程师眼中价值连城。",
        en = "A hardened data cartridge containing prototype input-output diagnostic logs from Hub 01. Packed with telemetry on neural-interfaced servo actuators, survivalist technicians barter fortunes for its data.",
    },
    ["robofac_yrax_trifacet_deactivation_manual"] = {
        zh = "一本厚实杂乱的异形机械三棱体应急失效处置操作手册。里面用晦涩的技术图解详细拆解了如何用脉冲电流逆向短路神秘自动化三棱机械体，读懂它能让你在遭遇这些冷酷机械杀手时获得一线生机。",
        en = "A dense technical manual detailing deactivation and disarmament protocols for lethal automated alien trifacet constructs. Decoding its diagrams allows engineers to short-circuit lethal hunter-killer automata using targeted electrical pulses.",
    },
    ["robofacmultimag"] = {
        zh = "枢纽 01 混合武器平台专用的 50 发 5.7 毫米大容量水平供弹弹匣。透明聚合物外壳能清晰看清剩余弹药，五十发高穿甲弹药平顺旋转上膛，在近距离全自动泼洒时提供连绵不绝的弹幕洗礼。",
        en = "A translucent 50-round horizontal magazine chambered in 5.7x28mm for the Hub 01. Clear polymer casings let operators check ammunition reserves at a glance, feeding fifty high-velocity armor-piercing rounds smoothly into the chamber.",
    },
    ["robot_controls"] = {
        zh = "由高精度伺服电机、微控制器主板与多轴陀螺仪组成的机器人运动驱动单元。从报废工业机械臂上拆卸而来，是车间自动化改装、自制战斗漫游车底盘或让固定机枪塔实现自动追踪转向的核心驱动中枢。",
        en = "An integrated robotic motion controller package comprising servomotors, microcontrollers, and multi-axis gyroscopes. Salvaged from industrial assembly robots, it supplies essential drive logic for automated sentry turrets or remote-piloted track buggies.",
    },
    ["robot_kit_box"] = {
        zh = "印着儿童动手组装益智机器人明亮图案的彩色硬纸包装盒。虽然里面的伺服马达和电子模块早已被淘金者搜刮一空，但坚固防水的硬纸壳用来存放微型电子元器件或当作干燥的引火碎屑依然非常实用。",
        en = "A colorful cardboard retail box showing cheerful illustrations of children assembling educational robots. Stripped of motors and circuit boards, its sturdy partitioned shell serves as an organized parts caddy for screws or kindling.",
    },
    ["rock"] = {
        zh = "千万年地壳运动凝结出的终极智慧。无需充电，没有复杂的机械故障，更不用担心固件更新。当所有尖端科技在末世中化为废铁，它依然恪尽职守地充当物理学最原始的投射物。",
        en = "Millions of years of tectonic pressure, finally achieving peak tactical perfection. It never requires recharging, boasts zero mechanical moving parts, and effortlessly resolves theological debates with the undead through pure Newtonian physics.",
    },
    ["rock_flaking"] = {
        zh = "一块棒球大小、质地极其致密均匀的天然燧石或黑曜石打制石核。沿着石层纹理轻轻敲击就会脱落出边缘比手术刀还要锋利的贝壳状薄石片，是荒野工匠手搓石刀、石箭镞与刮削器的理想母石。",
        en = "A baseball-sized nodule of high-grade flint or obsidian displaying predictable conchoidal fracturing. Striking its edges flints razor-sharp flakes thinner than surgical scalpels, forming the mother material for primitive stone craft.",
    },
    ["rock_large"] = {
        zh = "一块沉重坚硬、足有脸盆大小的天然大岩石。虽然单手根本无法拿动，但在荒野中它是最完美的天然重型垫铁与石砧，搬到陷阱上方拉起绳索，更是能直接将过路丧尸砸成肉酱的重力滚石陷阱。",
        en = "A massive, heavy boulder roughly the size of a water basin. Requiring two straining hands to shift, it serves as an immovable natural anvil or can be rigged above doorframes as a skull-crushing gravitational deadfall trap.",
    },
    ["rock_quern"] = {
        zh = "由两块凿有研磨凹槽的坚硬圆石与结实木柄组装而成的简易手摇石磨。虽然转动起来费劲且咯吱作响，但只要在磨眼里慢慢撒入小麦或干玉米粒，就能把坚硬谷物研磨成细腻面粉，温饱自足。",
        en = "A primitive hand-cranked rotary quern assembled from two grooved circular millstones. Groaning with each rotation, patient survivors feed dried grains into its central eye to grind whole wheat into fresh baking flour.",
    },
    ["rock_sock"] = {
        zh = "将一块沉甸甸的坚硬鹅卵石塞入两层厚羊毛长筒袜底部制成的简易飞石索。挥舞甩动起来带着可怕的破空呼啸，利用离心力猛烈砸向敌人的下巴，能在瞬间将颅骨打碎而自己的手指却毫发无损。",
        en = "A heavy granite river rock securely tied inside the toe of nested wool socks. Whirling it around your head generates vicious centrifugal momentum, cracking enemy jaws and shattering collarbones while costing absolutely zero scavenged metal.",
    },
    ["rock_wool_bat"] = {
        zh = "由玄武岩熔融拉丝压制而成、单面覆有防潮铝箔的矿棉绝热保温棉毡。既不会被明火点燃，又能彻底隔绝严寒与外界噪音，塞进避难所墙壁夹层或车辆防弹板内侧，保暖隔音效果立竿见影。",
        en = "A dense slab of spun basalt rock-wool insulation backed with reflective foil. Incombustible and waterproof, stuffing it into shelter drywall or vehicle frame voids provides superb thermal retention and acoustic muffling against undead ears.",
    },
    ["rocuronium"] = {
        zh = "密封在医用无菌西林瓶中的罗库溴铵注射液。一种起效极快且作用强烈的非去极化骨骼肌松弛剂，原本用于手术气管插管，若在箭头上涂抹，能让哪怕体型庞大的变异猛兽在短短两分钟内窒息瘫痪倒地。",
        en = "A sterile vial of rocuronium bromide, a fast-acting non-depolarizing neuromuscular blocking agent. Dipping arrow tips into this paralyzing solution causes rapid diaphragm failure, collapsing charging megafauna into suffocating immobility within minutes.",
    },
    ["roller_blades"] = {
        zh = "配有坚固硬壳靴身与四颗高耐磨直排聚氨酯轮子的双排旱冰鞋。在平整干燥的柏油公路或商场地砖上滑行速度快若奔马，能轻松甩开狂奔的尸潮，但在坑洼泥泞的碎石烂路上会让你摔得头破血流。",
        en = "A pair of molded hard-shell inline skates rolling on smooth polyurethane wheels. Gliding across flat asphalt highways outpaces sprinting infected mobs effortlessly, though hitting a gravel patch sends you skidding across concrete face-first.",
    },
    ["roller_shoes_off"] = {
        zh = "鞋底后跟暗藏可拆卸微型钢轮的暴步鞋，目前处于收起滑轮的普通步行模式。外观与普通便携运动鞋毫无二致，穿上它在废墟瓦砾间稳步行走毫无阻滞，只要脚跟一蹬，随时准备切换滑行模式。",
        en = "A pair of casual sneakers concealing retractable roller wheels in their heels, currently set to walking mode. Indistinguishable from ordinary running shoes, they allow sure-footed trekking across rubble until smooth floors invite spontaneous gliding escapes.",
    },
    ["roller_shoes_on"] = {
        zh = "已将后跟金属滑轮完全弹出锁定的暴步滑行鞋。只要身体重心向后微倾落在脚跟上，就能在废弃超市光滑如镜的环氧地坪上轻快飞驰，一边优雅躲避货架后扑来的丧尸，一边完成物资搜刮。",
        en = "A pair of wheeled sneakers with heel bearings clicked into rolling engagement. Tilting weight onto your heels sends you flying across polished supermarket linoleum, out-maneuvering grasping ghouls while carrying armfuls of scavenged canned goods.",
    },
    ["rollerskates"] = {
        zh = "带有两排四个对称橡胶轮的复古皮革四轮旱冰鞋。前掌配有橡胶刹车制动块，在平整的水磨石地面上滑行姿态优美而滑稽，虽然不能越野，但在废弃轮滑场里躲避慢吞吞的丧尸极具怀旧喜感。",
        en = "A retro pair of leather quad roller skates featuring paired polyurethane wheels and front toe-stops. Gliding gracefully across polished rink floors, they let survivors out-maneuver shambling ghouls with flamboyant disco-era nostalgia.",
    },
    ["rolling_paper"] = {
        zh = "极其轻薄半透明的优质木浆慢燃卷烟纸。一侧涂有天然阿拉伯树胶粘性胶条，是烟民将野外晒干的变异烟叶或野生香草卷制成提神香烟的必备载体，燃烧均匀且绝不会带来呛人的劣质纸浆味。",
        en = "A booklet of translucent rice rolling papers lined with natural gum adhesive. Essential for hand-rolling crushed mutant tobacco leaves and wild herbs into calming cigarettes, its slow, even burn soothes frayed nerves after desperate firefights.",
    },
    ["rolling_pin"] = {
        zh = "用整块硬木车削打磨光滑的厚重实木擀面杖。不仅能将发酵面团轻松擀平压薄制作饺子皮或披萨饼底，在厨房遭遇变异丧尸偷袭时，沉甸甸的木质分量抡圆了就是一根敲碎头骨的趁手短棍。",
        en = "A heavy hardwood rolling pin turned and polished to a satin sheen. While indispensable for rolling flatbread dough over bunker counters, swinging its solid heft delivers a skull-cracking bludgeon against kitchen-raiding zombies.",
    },
    ["rollmat"] = {
        zh = "采用封闭式发泡材料制成的高弹性便携防潮睡垫。卷起时可用绑带固定在背包底部，展开铺在冰冷潮湿的水泥地面或泥土上，能有效隔绝地表刺骨寒气与湿气，是露宿荒野防止风湿的保命垫层。",
        en = "A lightweight closed-cell foam sleeping rollmat secured with elastic straps. Unfurled across freezing bunker concrete or damp mossy soil, it insulates your spine from ground chill, preventing debilitating hypothermia during wilderness bivouacs.",
    },
    ["rootbeer"] = {
        zh = "带有浓郁萨沙草根与冬青植物精油独特香气的经典根汁汽水。不含咖啡因却气泡十足，独特的风味在末日甚至会被某些幸存者误以为是风湿跌打药水，但冰镇一口下肚，甘甜直冲天灵盖。",
        en = "A can of bubbly sassafras-flavored root beer infused with wintergreen extracts. Caffeine-free and smelling distinctly like medicinal muscle liniment to uninitiated survivors, ice-cold sips deliver nostalgic effervescent bliss amidst charred urban ruins.",
    },
    ["rootbeer_brewed"] = {
        zh = "利用野生黄樟树根皮、香草荚与酵母手工自然发酵酿造成的自酿根啤。开盖时泡沫丰富且带有纯正的微甜泥土草本芬芳，完全没有工业人工香精的假甜，是末日小酒馆里最受欢迎的健康饮品。",
        en = "A stoneware bottle of traditionally brewed root beer fermented with wild sassafras bark, molasses, and yeast. Foaming with natural carbonation and rustic herbal sweetness, it reigns supreme as the finest non-alcoholic brew in survivor settlements.",
    },
    ["rope_30"] = {
        zh = "足足三十英尺长的高强度多股编织尼龙登山绳。抗拉强度惊人且耐磨耐酸蚀，无论是从倒塌大楼的十层窗口索降逃生，还是捆扎满载物资的手推车，都是最信得过的生存利器。",
        en = "A thirty-foot braided nylon climbing rope rated for immense tensile loads. Indispensable for rappelling down shattered elevator shafts or securing mountainous supply caches to armored buggies.",
    },
    ["rope_6"] = {
        zh = "一段长约六英尺的紧凑便携尼龙短绳。盘好后随手塞在战术背包侧袋，无论是临时包扎制作骨折夹板、捆绑俘虏还是搭建简易野外吊床，拿出来就能派上大用场。",
        en = "A versatile six-foot length of durable synthetic utility cordage. Slipping unobtrusively into pocket pouches, it quickly binds hostile prisoners, secures splints, or anchors survival shelter tarps.",
    },
    ["rope_loop"] = {
        zh = "在一端打好活动滑动活结的高强度尼龙绳圈。拉动主绳即可迅速收紧套圈，既能在林间小径布置倒吊猎捕野兔与变异鹿的灵敏套索陷阱，也能在长途跋涉时用来捆扎固定大件行李与车辆辎重。",
        en = "A length of braided nylon rope tied with a smooth-running slip knot. Tightening instantly under tension, it sets deadly trail snares for wild game or lashes bulky scrap salvage onto the rear racks of buggies.",
    },
    ["rope_makeshift_30"] = {
        zh = "用撕碎的旧床单、布条与野草纤维手工编接搓成的三十英尺长粗绳。虽然看起来疙疙瘩瘩且结实程度参差不齐，但在没有工业绳索的废墟里，它能帮你吊装沉重的物资箱。",
        en = "A thirty-foot improvised rope braided from torn bedsheets, electrical wiring, and plant fibers. Knotted and uneven, it reliably hauls salvage crates up to hidden attic lofts.",
    },
    ["rope_makeshift_6"] = {
        zh = "利用零碎布条和皮革下脚料手工编织的一小捆简易短绳。承重虽然有限且不敢拿来攀爬绝壁，但用来把备用撬棍绑在背包外侧或者捆扎干柴火却相当称职。",
        en = "A short six-foot cord braided from scrap rags and leather cords. While unsuitable for sheer mountaineering descents, it lashes firewood bundles and secures loose tools to backpack frames.",
    },
    ["rose_hips"] = {
        zh = "从野玫瑰凋谢后的花托处采摘的一小把鲜红刺玫果。外皮鲜红油亮且果肉坚实，富含惊人浓度的天然维生素C，虽然直接生吃酸得倒牙，但在沸水里煮沸过滤掉毛刺后，是荒野最强抗坏血病神茶。",
        en = "A handful of bright scarlet wild rose hips harvested from thorny briars. Boasting extraordinary vitamin C concentrations, steeping these tart fruits in boiling water brews a restorative crimson tea that banishes scurvy from sun-deprived survivors.",
    },
    ["rose_hips_cut"] = {
        zh = "已经用小刀纵向切开并仔细刮除内部刺痒细毛的干净刺玫果肉。消除了导致喉咙瘙痒咳嗽的绒毛后，可以直接丢进炖锅里与野生浆果一同熬制成酸甜浓稠的果酱，风味酸香开胃。",
        en = "Halved rose hip pods scraped clean of their irritating, itchy internal seeds and hairs. Prepared properly, these tart fleshy husks simmer down into sweet vitamin-dense preserves or stew broths without irritating sensitive throats.",
    },
    ["rosin"] = {
        zh = "一块从松树树脂精炼提纯而来的半透明琥珀色松香块。除了用来给提琴弓弦擦拭增加抓弦摩擦力之外，在电子维修台上，它是让电烙铁焊锡顺畅流动、消除金属氧化层不可或缺的顶级助焊剂。",
        en = "A golden chunk of refined natural pine rosin. Beyond rubbing across horsehair violin bows to enhance acoustic friction, soldering hobbyists crumble its amber crystals as essential flux to strip oxide layers and flow solder beads cleanly.",
    },
    ["rossi_gallery"] = {
        zh = "带有复古胡桃木枪托的罗西画廊型 .22 口径泵动式轻便步枪。推拉护木上膛极其轻快顺滑，管状弹仓能容纳大量小口径子弹，虽然打不死大丧尸，但在废弃嘉年华射击摊般猎杀耗子乐趣无穷。",
        en = "A lightweight wooden pump-action rimfire rifle chambered in .22 Long Rifle. Cycling its slide briskly feeds a generous tube magazine, making it a joy for clearing out irradiated rodents from ruined grain silos without wasting powder.",
    },
    ["rossi_r92_357_16"] = {
        zh = "配备 16 英寸短枪管的罗西 R92 经典 .357 麦格农杠杆卡宾枪。全枪小巧轻盈且马鞍环挂带方便携行，下压杠杆动作如同西部牛仔般潇洒利落，大威力转轮弹药在近距离足以轰碎一切拦截。",
        en = "A nimble 16-inch lever-action carbine chambered in versatile .357 Magnum. Compact enough for saddle scabbards, working its slick underlever chambers potent revolver cartridges that punch punishing holes through armored raiders at brush ranges.",
    },
    ["rossi_r92_357_20"] = {
        zh = "配有 20 英寸八角形全长重枪管的罗西 R92 .357 杠杆步枪。加长枪管不仅提供了更多的弹仓容量与更高初速，沉重的枪口配重更让快速连续射击时的枪口跳动降到了最低，百步穿杨利器。",
        en = "A 20-inch octagonal-barreled lever-action rifle chambered for .357 Magnum. The extended barrel increases magazine tube capacity while wringing maximum magnum velocity, its muzzle-heavy balance stabilizing rapid successive shots across scrub fields.",
    },
    ["rossi_r92_44_16"] = {
        zh = "发射 .44 麦格农重型弹药的 16 英寸罗西 R92 短管杠杆步枪。粗壮的枪身在开火时会爆发出令人震撼的后坐力与轰鸣，但倾泻出的沉重大口径铅弹，能在十步之内将冲过来的变异狂暴野猪直接掀翻。",
        en = "A hard-hitting 16-inch lever-action brush gun chambered in bone-breaking .44 Magnum. Though delivering sharp recoil, pumping heavy flat-nosed lead through its compact barrel stops raging mutant boars dead in their tracks at close range.",
    },
    ["rossi_r92_44_20"] = {
        zh = "配有 20 英寸全长枪管的罗西 R92 .44 麦格农全尺寸杠杆步枪。大容量管状弹仓装满大威力重弹宛如一座小型移动军火库，平直的远程弹道配合杠杆步枪的高射速，是荒原游侠威慑宵小的终极仪仗。",
        en = "A full-sized 20-inch lever rifle chambered in devastating .44 Magnum. Housing a generous tubular magazine of heavy-grained cartridges, it delivers hammer-blow kinetic energy across open pastures, terrifying bandits with thunderous lever-cocking authority.",
    },
    ["rotovap"] = {
        zh = "由旋转烧瓶、水浴锅与冷凝回收管组成的精密旋转蒸发仪。仅是端详这套复杂的硼硅酸盐玻璃与真空管路就让人宛如专业化学家，在末日中常用于在极低温度下温和浓缩纯化极其娇贵的生化诱变剂。",
        en = "A sophisticated laboratory rotary evaporator complete with distillation flasks and water baths. Looking upon its labyrinthine glassware makes you feel like an elite chemist, gently concentrating delicate mutagens under low-temperature vacuum extraction.",
    },
    ["rough_rider_pistol"] = {
        zh = "配有经典纯铜准星与淬火弹巢的粗犷骑手 .22 单动转轮手枪。装填 6 发廉价边缘发火小弹，每次扣动扳机前都必须用大拇指手动压倒击锤，虽然火力贫弱，但那声清脆的压锤声满是古典西部浪漫。",
        en = "A single-action .22 LR revolver styled after classic wild-west six-shooters. Requiring manual thumb-cocking for every shot, its mild report and cheap rimfire diet make it a charming, nostalgic tool for small-game hunting.",
    },
    ["rough_rider_pistol_9"] = {
        zh = "装有一根长达 9 英寸加长枪管的 .22 单动转轮手枪。长枪管让它看起来宛如滑稽马戏团道具，但超长瞄准基线赋予了它惊人的单孔级命中率，让小口径弹药也能在远距离精准钻入丧尸眼眶。",
        en = "An absurdly long-barreled 9-inch .22 LR single-action revolver. Looking like a comical trick gun from a cartoon, its elongated sight radius yields incredible precision, drilling tiny lead slugs through distant ghoul eye sockets.",
    },
    ["router"] = {
        zh = "台面中心嵌装有高速电动修边电机的木工雕刻台，目前处于断电待机状态。只要通上电，飞速旋转的硬质合金铣刀就能以毫秒级在硬木边缘铣削出精密的榫卯接头或战术枪托导轨，木工圣机。",
        en = "A standalone woodworking router table housing an inverted high-speed electric motor spindle. Dormant without electricity, spinning its carbide bits cuts precision mortises, dado grooves, and custom wooden gunstocks with microscopic perfection.",
    },
    ["router_tool"] = {
        zh = "带有高转速金刚石铣刀的高精度电动木工雕刻机。只要接入避难所电网，它就能在坚硬的橡木板上飞速铣出精密的凹槽与榫卯，是打造高级木工家具与枪托的工业利器。",
        en = "A high-speed electric woodworking router fitted with sharp carbide bits. Whirring smoothly when wired to generator circuits, it routes precision mortise channels for custom rifle stocks and bunker doors.",
    },
    ["royal_beef"] = {
        zh = "表面厚厚涂抹了一层黏稠金黄蜂王浆的顶级熟牛肉排。蜂王浆的天然抗氧化酶锁住了肉汁的全部鲜美，咬下去肉香四溢且带着特殊的酸甜花蜜风味，吃完不仅气力大增，还能奇迹般加速伤口愈合。",
        en = "A premium cut of roasted beef smothered in golden, royal jelly glaze. The royal nutrients preserve savory juices while imparting sweet floral notes, speeding traumatic wound tissue regeneration after grueling close-quarters combat.",
    },
    ["royal_jelly"] = {
        zh = "从巨型变异蜂巢核心王台小心割取下来的一块半透明六角蜂蜡块。内部灌满了乳白色的高纯蜂王浆，是大自然中最神奇的广谱生物刺激剂，吞服下去能清除体内绝大多数致命毒素与顽固基因畸变。",
        en = "A translucent hexagonal comb chunk dripping with viscous, bioluminescent royal jelly. Harvested from mutant hive queens, this miracle apian panacea purges systemic toxins and stabilizes volatile genetic cellular degradation within hours.",
    },
    ["rp63"] = {
        zh = "不锈钢打造的 RP63 紧凑型 .357 麦格农短管转轮手枪。短粗的枪管配合沉重的全钢枪身，虽然隐蔽携行性极佳，但开火时手掌会感受到如同手握手雷引爆般的凶猛震荡，近身最后一道防线。",
        en = "A snub-nosed stainless-steel revolver chambered in .357 Magnum. Heavy and remarkably compact for concealed carry, dropping its hammer unleashes concussive wrist-wrenching muzzle blasts that destroy point-blank assailants in tight hallways.",
    },
    ["rpk74mag"] = {
        zh = "容量高达 45 发的 5.45x39 毫米 RPK-74 班用机枪长弧形聚合物弹匣。亮橘色玻璃纤维增强工程塑料结实耐摔，插在普通 AK 步枪上也完全通用，提供无与伦比的持续倾泻火力和深沉安全感。",
        en = "An extended 45-round polymer magazine built for the RPK-74 squad automatic weapon. Compatible with standard 5.45mm Kalashnikov rifles, its ribbed orange shell supplies relentless automatic firepower that breaks charging mutant mobs.",
    },
    ["ruana_sci_fi"] = {
        zh = "表面流淌着暮色渐变微光的科幻风格斗篷披风。采用特殊的变色智能光学纤维纺织而成，既轻薄透气又能随环境光线微微变暗融入阴影，穿在身上不仅保暖防风，更是废土潜行者梦寐以求的隐蔽斗篷。",
        en = "A futuristic wrap poncho shimmering with evening-hued twilight gradients. Woven from responsive optoelectronic threads, it sheds wind chill while adapting to ambient darkness, offering aesthetic elegance and subtle visual camouflage across moonlit wastes.",
    },
    ["rubber_armor_cow"] = {
        zh = "专为耕牛与奶牛裁剪的轻便防水聚酯雨披护罩。通过多道可调节腹带固定在牛身上，虽然没有任何防弹防撕咬抗力，但能在连续数周的连绵酸雨中保护牲畜娇嫩皮肤不被酸水烧伤起泡，农业贵重物。",
        en = "A tailored vinyl waterproof poncho designed to keep bovine livestock dry. Strapping securely around cow bellies, it offers zero protection against mutant teeth, but shields precious draft animals from corrosive acid rain blisters.",
    },
    ["rubber_armor_horse"] = {
        zh = "为纯种马匹量身缝制的透明橡胶防雨马衣。紧密贴合马背与马颈线条，能有效阻隔酸性泥水与毒性蚊虫叮咬，让幸存者心爱的坐骑在寒风冷雨中免遭风寒失温，是建立荒野骑兵巡逻队的后勤保障。",
        en = "A durable rubberized rain sheet fitted with adjustable surcingles for equine mounts. Protecting prized riding horses from stinging irradiated downpours and biting swamp insects, it keeps horses healthy during grueling cross-country reconnaissance patrols.",
    },
    ["rubber_band"] = {
        zh = "一圈带有优异弹性的普通天然橡胶皮筋。随手一拉就能紧紧捆扎散落的铅笔、绑紧自制卷轴地图或者给伤口做紧急指压止血，更是机械工坊制作微型弹射扳机与原始弹弓捕鸟器的黄金零件。",
        en = "A stretchy looped strip of vulcanized rubber. Commonly used to bundle loose pens or tie rolled maps, this versatile elastic loop also serves as miniature tension springs for homemade mechanical triggers or bird slingshots.",
    },
    ["rubber_harness_dog"] = {
        zh = "专为忠诚猎犬量身缝制的黄色防水防酸橡胶雨衣背带。不仅能让爱犬在倾盆酸雨中免受皮肉灼伤，醒目的黄色反光条还能让你在漆黑树林里一眼锁定狗狗的位置。",
        en = "A bright yellow waterproof rubber suit tailored for loyal canine companions. Shielding your four-legged scout from acidic precipitation, reflective safety stripes make tracking your hound easy in pitch-black woods.",
    },
    ["rubber_slug"] = {
        zh = "从防暴豆袋霰弹中取出来的坚硬圆柱形高密度硫化橡胶弹丸。原本用于非致命防暴镇压，利用钝击动能让人丧失行动能力，但在面对没有痛觉神经的丧尸时，它顶多只能像重重拍了对方一巴掌。",
        en = "A dense molded cylinder of vulcanized rubber extracted from riot control beanbag rounds. Lacking penetration against armored foes and harmless against pain-immune zombies, it merely delivers an insulting blunt swat across shambling snouts.",
    },
    ["rubber_tire_chunk"] = {
        zh = "从废弃重型卡车轮胎上费力切割下来的一大块加厚半硬化橡胶块。内部嵌有密集的增强钢丝帘线，极其耐磨抗砸，既能在铁匠砧上当成减震垫块，也是自制防弹轮胎与重型胶垫护甲的无价原材料。",
        en = "A thick, semi-rigid chunk of vulcanized tread sliced from an abandoned freight truck tire. Reinforced with braided steel cords, it makes an indestructible hammering pad or gets trimmed into puncture-proof vehicle armor liners.",
    },
    ["rubber_tire_strip"] = {
        zh = "从汽车旧轮胎外胎上撕削下来的一根长长带状厚实橡胶条。柔韧且极具抓地耐磨性，可以缠在方向盘或冷兵器握把上作为绝佳防滑防震握把皮，也能剪裁成无数耐用的自制凉鞋鞋底与固定绑带。",
        en = "A long curled strip of thick tire rubber sliced from salvaged vehicle casings. Tough and weather-resistant, wrapping it around weapon hafts yields non-slip shock-absorbing grips, or it can be carved into durable tire-tread sandals.",
    },
    ["rubik_farthing"] = {
        zh = "一枚表面压铸着鲁比克星际硬核商会飞船徽标的金光闪闪黄铜硬币。做工精细且边缘有防伪齿纹，虽然大灾变前没人见过这种神秘钱币，但在隐秘的外星伊克索迪据点里，它是换取高科技神器的通用筹码。",
        en = "A gleaming brass coin stamped with the stern insignia of a starfarer merchant guild. While unrecognized by pre-cataclysm banks, passing this mysterious farthing to Exodii cyborg traders buys specialized cybernetic bionics and foreign armaments.",
    },
    ["ruby"] = {
        zh = "一颗在阳光下折射出如鲜血般耀眼光芒的天然纯净切割红宝石。切工精美且晶莹剔透，虽然不能吃也不能抵挡子弹，但在黑市贵金属交易商眼里，这颗永恒的血色晶体依然拥有无可争议的保值价值。",
        en = "A brilliant, faceted natural red gemstone sparkling with deep crimson fire. Completely useless as sustenance or ballistic armor, its eternal crystalline perfection commands substantial barter wealth among aristocratic warlords and black-market jewelers.",
    },
    ["ruby_dental_grill"] = {
        zh = "用纯金底托镶嵌了整整两排细密碎红宝石的嘻哈风定制宝石假牙套。扣在牙齿上笑起来红光闪闪宛如满嘴血浆，虽然咀嚼干肉饼极其别扭，但绝对能让你在荒野匪帮中成为最拉风暴发户头领。",
        en = "A custom gold dental grill encrusted with genuine faceted rubies. Snapping tightly over front incisors, it looks like a bloody predatory grimace, proving to rival wasteland gang bosses that your vanity eclipses your sanity.",
    },
    ["ruby_gold_bracelet"] = {
        zh = "由多节精雕纯金链环环环相扣、正中镶嵌数颗浓艳红宝石的华贵黄金手链。金灿灿的光泽与鲜红的宝石交相辉映，戴在沾满机油与泥土的手腕上显得格格不入，却是一笔能随身隐蔽携带的巨额财富。",
        en = "A heavy 24-karat gold chain bracelet set with glistening pigeon-blood rubies. Contrasting starkly against soot-stained wrists and grease-smeared tactical sleeves, this heirloom jewelry represents an easily concealed, high-value portable emergency treasury.",
    },
    ["ruby_gold_cufflinks"] = {
        zh = "一对在实心纯金底座上镶嵌着椭圆形深红宝石的奢华衬衫袖扣。大灾变前是绅士参加国宴与名流晚会时的身份象征，如今被荒野流浪汉用来当成缝补皮甲的贵金属固定螺栓，暴殄天物却又无可奈何。",
        en = "A pair of matching gold cufflinks set with polished crimson rubies. Once securing tailored French cuffs at high-society galas, desperate survivors now barter them for antibiotics or use the gold posts as fancy rivet pins.",
    },
    ["ruby_gold_earring"] = {
        zh = "一对精巧的水滴状纯金红宝石耳坠。在耳垂边轻轻摇曳时会折射出动人心魄的猩红光晕，戴上它在阳光下搜刮时虽然可能会因为反光暴露行踪，但能在绝望废墟中带来仅存的美丽与贵族尊严。",
        en = "A pair of glittering gold teardrop earrings mounting faceted crimson rubies. Dangling from earlobes, their bright reflections risk catching the gaze of distant snipers, yet preserving fine personal vanity provides stubborn psychological comfort.",
    },
    ["ruby_gold_pendant_necklace"] = {
        zh = "一条由粗纯金细密编织链条、吊坠正中镶嵌着一颗鸽血红宝石的奢华金项链。沉甸甸的黄金贴着锁骨散发着温润微光，在这个道德沦丧的世界里，唯有这颗血色宝石依然闪耀着不灭的冰冷光彩。",
        en = "A heavy woven gold necklace suspending an opulent, oval-cut ruby pendant. Resting against collarbones, its warm precious metal heft feels like a link to a lost era of peace, commanding high barter prices at trading posts.",
    },
    ["ruby_gold_ring"] = {
        zh = "戒圈由实心黄金铸造、顶端高高托起一颗精密切割红宝石的贵族金戒指。红宝石在火光照耀下宛如一滴凝固的炽热心血，不仅能作为彰显地位的首饰，也是末日黑市中最易被所有阵营承认的等价交换物。",
        en = "A solid yellow gold band presenting a prominent claw-set faceted ruby. Glowing like an ember beside glowing campfires, this heirloom ring easily buys drums of clean gasoline or crates of rifle cartridges at survivor markets.",
    },
    ["ruby_gold_tiara"] = {
        zh = "用实心纯金锻造出荆棘花冠造型、上面密布着数十颗璀璨红宝石的奢华金冠。戴在头上沉甸甸且璀璨夺目，虽然面对丧尸的抓咬毫无防护作用，但能让你在破败的废墟王国里自封为末日废土的女王。",
        en = "An exquisite solid gold tiara adorned with clusters of glittering rubies. Yielding zero ballistic resistance against shrapnel, crowning your grimy brow with this royal relic allows you to reign over the ash heaps in regal majesty.",
    },
    ["ruby_platinum_bracelet"] = {
        zh = "由冰冷纯白金打造成几何链节、每节均嵌有一枚剔透红宝石的顶级白金手链。白金永不氧化的纯净光泽衬托得红宝石愈发猩红耀眼，质感沉重压手，是旧时代顶级工艺与无上奢华的最后绝唱。",
        en = "A geometric platinum link bracelet set with alternating, channel-set rubies. Impervious to rust and atmospheric tarnish, its brilliant silvery-white luster frames deep red jewels, representing an indestructible pinnacle of pre-cataclysm artisan metallurgy.",
    },
    ["ruby_platinum_cufflinks"] = {
        zh = "一对采用顶级白金材质打造、镶有方形切割深邃红宝石的贵重袖扣。做工严丝合缝且具有惊人的耐酸抗腐蚀能力，在这个早已没人穿法式正装衬衫的时代，它是熔铸高导电电极或防腐饰品的绝佳材料。",
        en = "A matched pair of square platinum cufflinks set with rich scarlet rubies. Wholly impervious to acid rain and environmental corrosion, survivalists prize them as dense chunks of pure, unreactive platinum for delicate electrical experiments.",
    },
    ["ruby_platinum_earring"] = {
        zh = "由抗过敏纯铂金精工打造的一对闪耀红宝石耳钉。鲜艳欲滴的红宝石被六爪铂金稳稳固定在耳畔，小巧精致且永不褪色，即使在满地泥泞与血泊中摸爬滚打，摘下来擦净依然纯洁如初。",
        en = "A pair of six-prong platinum stud earrings mounting vivid round-cut rubies. Completely hypoallergenic and tarnish-proof, wiping mud and grime off their gleaming surfaces restores their dazzling brilliance instantly.",
    },
    ["ruby_platinum_pendant_necklace"] = {
        zh = "一条由高纯度纯白金细链悬挂着一颗硕大水滴状红宝石的奢华项链。白金链条坚韧不易被扯断，猩红的水滴形宝石贴在心口，宛如一颗永不凝固的鲜红眼泪，是对那个繁华旧世界最凄美的挽歌。",
        en = "A shimmering platinum chain necklace displaying an imposing pear-cut teardrop ruby. Strong and resistant to snapping, its crimson stone hangs over your sternum like an eternal blood droplet weeping for a shattered world.",
    },
    ["ruby_platinum_ring"] = {
        zh = "采用坚硬耐磨的纯铂金戒圈、中央镶嵌一颗正方形切割鲜红红宝石的顶级戒指。白金的冷冽银白与红宝石的炽热鲜红碰撞出惊心动魄的对比美感，沉甸甸的贵重金属分量是废土最高信用的货币。",
        en = "A pristine platinum signet ring mounting a square-cut blood-red ruby. Combining frosty white metal with fiery crimson crystals, its unmatched metallurgical density guarantees instant respect and top-tier bartering credit across trade settlements.",
    },
    ["ruby_platinum_tiara"] = {
        zh = "由纯白金精密拉丝焊接而成、镶嵌着百颗大小红宝石的极度奢华王冠。拿在手中沉重无比，白金光泽与漫天繁星般的红宝石交相辉映，是旧时代皇室贵族权力与财富的至高象征，现已成为废土绝响。",
        en = "A breathtaking platinum tiara encrusted with dozens of matched natural rubies. Impossibly heavy and dazzling under the midday sun, this museum-grade crown transforms anyone walking through desolate wasteland ruins into an immortal monarch.",
    },
    ["ruby_silver_bracelet"] = {
        zh = "由复古雕花纯银链扣与数颗鲜艳红宝石手工编织而成的优雅银手链。虽然随着时间流逝银质表面会泛起一层沧桑的氧化包浆，但在深黑包浆的衬托下，那一抹抹血色红宝石反而显得更加摄人心魄。",
        en = "An ornate sterling silver bracelet decorated with filigree scrollwork and faceted rubies. While dark oxidation patinas naturally coat the silver links, the deep tarnish makes the glittering crimson gems stand out with brooding elegance.",
    },
    ["ruby_silver_cufflinks"] = {
        zh = "一对在雕花纯银底座上镶嵌着深红红宝石的复古法式袖扣。虽然表面的纯银因年代久远而有些许硫化发黑，但中心透亮的红宝石依然闪烁着高贵血光，是能换取整箱罐头的硬通货首饰。",
        en = "A pair of antique sterling silver cufflinks mounting faceted crimson rubies. Though atmospheric sulfur has darkened their silver backings, the deep red gems gleam brightly, easily bartered for crates of canned goods.",
    },
    ["ruby_silver_earring"] = {
        zh = "一对由精工纯银细丝悬挂着水滴状红宝石的优雅耳环。银质的素雅冷光完美衬托出红宝石的炽热艳丽，在荒凉破败的安全屋里佩戴它，能在绝望的黑夜中为心灵带来一丝对旧日美好的慰藉。",
        en = "A pair of graceful sterling silver earrings suspending teardrop rubies. The cool silver mounts frame the fiery crimson gems, lending a touch of aristocratic pre-cataclysm beauty to life inside gloomy subterranean bunkers.",
    },
    ["ruby_silver_pendant_necklace"] = {
        zh = "一条由纯银麻花链悬挂着精美红宝石吊坠的典雅项链。银链贴合肌肤带着微微凉意，中央红宝石在昏暗烛光下宛如一滴不会凝固的鲜血，在这个充斥暴力的世界里散发着凄美的艺术魅力。",
        en = "A delicate sterling silver rope chain suspending an oval-cut ruby pendant. Resting lightly over your collarbone, the crimson jewel glints like an eternal drop of fresh blood amidst a ruined, violent world.",
    },
    ["ruby_silver_ring"] = {
        zh = "一枚戒托由纯银复古花丝缠绕、顶端托起一颗明亮红宝石的银戒指。银光内敛而红宝石夺目，虽然不能作为武器敲碎丧尸的骨头，但在流浪幸存者聚集的黑市里，它是极为抢手的通用硬通货。",
        en = "A filigree sterling silver band holding a prominent solitaire ruby. Offering no blunt damage against shambling horrors, its fine metallurgical craft commands universal bartering respect among wandering merchant caravans.",
    },
    ["ruby_silver_tiara"] = {
        zh = "由高纯度纯银精心打造成月桂枝条造型、上面点缀着数十颗璀璨红宝石的奢华银冠。虽然白银在露天极易氧化发黑，但擦拭一新后戴在头顶，依然能让你在焦土上宛如神话中走出的月夜精灵。",
        en = "An ornate sterling silver tiara fashioned like laurel branches and studded with sparkling rubies. Polishing away its surface tarnish transforms any battle-scarred wanderer into a mythical monarch reigning over desolate ruin mounds.",
    },
    ["rucksack"] = {
        zh = "采用超厚防撕裂考杜拉尼龙缝制的军规重型大容量野战背包。带有铝合金外骨骼负重支架与加厚腰封，能将数十公斤的罐头、弹药与杂物轻松收拢其中，是末日废土远征探险家的终极移动仓库。",
        en = "A cavernous military-issue external-frame rucksack tailored from heavyweight Cordura nylon. Equipped with padded waist belts and internal stays, it shoulders mountains of scavenged ammo and rations comfortably over endless forced marches.",
    },
    ["ruger10"] = {
        zh = "容量为 10 发的鲁格 Mini-14 卡宾枪冲压钢制短弹匣。紧凑的弹匣体完全不凸出枪身底部，在卧姿潜伏射击或钻过低矮通风管道时绝不会挂碰障碍，供弹平稳可靠，深受潜行斥候喜爱。",
        en = "A flush-fitting 10-round steel box magazine for the Ruger Mini-14 carbine. Its ultra-compact profile prevents snags while crawling through brush or narrow air ducts, feeding reliable .223 rifle rounds without mechanical failure.",
    },
    ["ruger100"] = {
        zh = "容量高达 100 发的 Mini-14 双鼓形超大容量供弹具。虽然装满子弹后沉重得让人端枪手腕颤抖，但在遭遇无边无际的尸潮疯狂涌来时，持续倾泻而出的连绵火网能筑起一道不可逾越的铜墙铁壁。",
        en = "A colossal 100-round dual-drum magazine for the Ruger Mini-14 carbine. Adding massive dead weight to the forend, dumping its sustained .223 barrage transforms a sporting carbine into an unrelenting horde-clearing machine.",
    },
    ["ruger1022bigmag"] = {
        zh = "容量为 25 发的鲁格 10/22 步枪香蕉形加长弹匣。经典的弧形设计供弹顺畅，极大拓展了这支小口径轻便步枪的持续火力，让你在清剿成群变异大鼠或野兔时完全不必频繁换弹。",
        en = "A curved 25-round extended magazine designed for the Ruger 10/22 rifle. Providing ample capacity for rimfire plinking, it lets pest controllers sweep entire nests of irradiated sewer rats without pausing to reload.",
    },
    ["ruger1022mag"] = {
        zh = "鲁格 10/22 经典的 10 发旋转式平齐弹匣。独特的转轮式聚合物内部导轨让脆弱的边缘发火弹药绝不会发生咬尾卡壳，完全收纳于枪身内部，是手感最好也最耐用的原厂传奇弹匣。",
        en = "The legendary 10-round rotary magazine engineered for the Ruger 10/22 rifle. Fitting completely flush within the stock, its internal rotor prevents rim-locking, ensuring that every fragile .22 LR round feeds flawlessly into the chamber.",
    },
    ["ruger1022mag_110"] = {
        zh = "容量高达 110 发的鲁格 10/22 超级旋转大弹鼓。简直就像在小口径步枪底下挂载了一个巨型平底锅，虽然装弹过程极其痛苦费手，但扣下扳机尽情倾泻上百发子弹的快乐简直无可比拟。",
        en = "A massive 110-round drum magazine for the Ruger 10/22 platform. While taking an eternity to hand-load, unleashing an unending stream of rimfire lead without a single reload brings immense joy to apocalyptic pest controllers.",
    },
    ["ruger1022mag_15"] = {
        zh = "容量为 15 发的鲁格 10/22 中等长度加长聚合物弹匣。弹匣底端微凸出握把数厘米，在保持整枪轻巧重心的同时多提供了五发宝贵的火力富余，是林地狩猎小型猎物的黄金搭档。",
        en = "A 15-round semi-extended magazine tailored for the Ruger 10/22 rifle. Protruding slightly below the receiver, it grants five extra shots over flush magazines while maintaining balance for dynamic woodland squirrel hunting.",
    },
    ["ruger1022mag_30"] = {
        zh = "容纳 30 发 .22 LR 子弹的鲁格 10/22 小型弹鼓。内部发条机构发力均匀，能避免长条香蕉弹匣在卧姿射击时触地的尴尬，提供整整三十发持续火力的同时让持枪姿势更加稳定自然。",
        en = "A compact 30-round drum magazine manufactured for Ruger 10/22 rimfire rifles. Its circular profile prevents ground clearance issues during prone shooting, feeding thirty rounds smoothly through reliable internal torsion springs.",
    },
    ["ruger1022mag_32"] = {
        zh = "容量整整 32 发的透明工程塑料 10/22 加长弧形弹匣。半透明的聚碳酸酯外壳能让你随时查看剩余弹药，沉甸甸的三十余发边缘发火弹药排成一列，是清理谷仓害虫的廉价泼水神器。",
        en = "An extended 32-round translucent polymer magazine designed for Ruger 10/22 rifles. Clear plastic walls allow instant ammunition accounting, providing an economical high-volume feeding solution for spraying hordes of radioactive roaches.",
    },
    ["ruger1022mag_55"] = {
        zh = "容量为 55 发的鲁格 10/22 旋转式中型弹鼓。黑色强化聚合物外壳坚固抗摔，内部采用精密多层旋转盘导轨，让你在遭遇大群变异变异幼虫突袭时，能够从容不迫地扣动扳机连续点名射杀。",
        en = "A 55-round rotary drum magazine configured for the Ruger 10/22 carbine. Molded from rugged black polymer, its multi-track internal feed rotor provides relentless rimfire fire superiority when ambushed by swarming mutant insects.",
    },
    ["ruger1022mag_70"] = {
        zh = "足足容纳 70 发子弹的鲁格 10/22 重型弹药鼓。将近百发小口径弹药紧凑容纳在圆形弹鼓内，虽然连扣扳机到手指发酸枪管也会微微发热，但毫无间断的射击节奏能彻底压制小体型怪物群。",
        en = "A heavy 70-round drum magazine built for the Ruger 10/22 platform. Keeping an absurd volume of rimfire ammunition on tap, it suppresses aggressive packs of mutant rodents without giving them a moment to close the distance.",
    },
    ["ruger20"] = {
        zh = "容量为 20 发的鲁格 Mini-14 原厂双排钢制弹匣。军用规格的厚钢板与强化热处理托弹簧，在泥沙和冰霜中依然能平稳顺畅地上弹，是 Mini-14 射手最常用的标准战术容量弹匣。",
        en = "A classic 20-round steel box magazine manufactured for the Ruger Mini-14. Constructed with heat-treated steel feed lips and heavy-gauge springs, it delivers battle-proven reliability through dirt, mud, and arctic cold.",
    },
    ["ruger30"] = {
        zh = "容纳 30 发 5.56 毫米弹药的 Mini-14 高容量钢制弹匣。加长的弧形弹体赋予了这支民用半自动卡宾枪媲美军用突击步枪的持续压制火力，在遭遇大群丧尸围攻时是拉开火力网的中坚力量。",
        en = "A high-capacity 30-round steel box magazine tailored for Ruger Mini-14 rifles. Giving the semi-auto ranch carbine firepower comparable to military assault rifles, it provides crucial sustaining volume during desperate perimeter defenses.",
    },
    ["ruger5"] = {
        zh = "因打猎法规限制由 10 发弹匣打铆钉改装而来的 5 发 Mini-14 短弹匣。容量极小且几乎与枪托平齐，虽然在尸潮围城时令人抓狂，但在荒野潜伏猎杀变异鹿时，能最大程度保证整枪流线轻便。",
        en = "A 5-round capacity-limited steel magazine for the Ruger Mini-14 carbine. Sitting completely flush with the receiver, its tiny capacity is agonizing during horde sieges, yet ideal for snag-free hunting through dense underbrush.",
    },
    ["ruger90"] = {
        zh = "容量高达 90 发的 Mini-14 蜗牛形超大螺旋弹鼓。沉重且造型夸张，内部复杂发条结构能将近百发步枪弹源源不断送入枪膛，虽然装上后整枪严重左倾，但狂暴扫射时的安全感无可比拟。",
        en = "A massive 90-round snail drum magazine designed for the Ruger Mini-14. Unbalancing the rifle with its heavy, eccentric bulk, it compensates by unleashing a continuous storm of .223 lead that disintegrates advancing mutant mobs.",
    },
    ["ruger_1022"] = {
        zh = "享誉全球的鲁格 10/22 半自动小口径猎枪。全枪小巧轻便且人机工效极佳，发射随处可得的 .22 LR 边缘发火子弹，射击声音微弱且几乎没有后坐力，是荒野猎捕野兔与松鼠度过饥荒的神器。",
        en = "The world-famous Ruger 10/22 semi-automatic rimfire carbine. Lightweight, modular, and practically recoilless, its quiet bark and ubiquitous .22 LR ammunition make it the premier survival tool for harvesting small woodland game.",
    },
    ["ruger_1022_auto"] = {
        zh = "被地下枪匠私自改装了全自动阻铁的狂暴版鲁格 10/22 步枪。扣住扳机能在两秒内将弹匣清空，射速快得宛如电锯蜂鸣，虽然打不死重装甲目标，但近距离糊脸能把脆弱的丧尸打成筛子。",
        en = "An illicit full-auto conversion of the humble Ruger 10/22 carbine. Emptying magazines in a blistering chainsaw-like buzz, it lacks armor penetration yet stitches soft zombie targets with dozens of lethal rimfire punctures.",
    },
    ["ruger_57"] = {
        zh = "鲁格公司生产的 Ruger-57 全尺寸现代半自动手枪。发射高速高穿透力的 5.7x28 毫米弹药，握把虽薄却能容纳整整 20 发子弹，后坐力柔和且弹道极平，能轻易撕裂凯夫拉防弹衣与骨质胸甲。",
        en = "A full-sized Ruger-57 semi-automatic pistol chambered in 5.7x28mm. Slim yet housing twenty rounds, its ultra-flat trajectory and negligible recoil allow rapid double-taps that pierce through soft body armor and mutant carapaces.",
    },
    ["ruger_57_10_round_mag"] = {
        zh = "受大灾变前民用法规限制的 10 发短容量 Ruger-57 钢制弹匣。虽然在面对尸群时很快就会打空挂机，但结实的原厂弹簧依然保证了每一发 5.7 高速穿甲弹都能顺畅上膛，可靠性毋庸置疑。",
        en = "A restricted 10-round steel magazine built for the Ruger-57 pistol. While running dry far too quickly against teeming mutant hordes, its stiff factory follower spring ensures that high-velocity 5.7mm rounds feed without stovepipes.",
    },
    ["ruger_57mag"] = {
        zh = "容量整整 20 发的 Ruger-57 原厂双排钢制弹匣。平滑的冲压钢板表面能有效防沙抗污，二十发大容量弹药能为手枪提供极其凶猛的近战压制火力，是废土手枪射手最梦寐以求的弹药匣。",
        en = "The standard 20-round double-stack steel magazine for the Ruger-57 handgun. Coated with anti-friction finishes that shed grit, its generous capacity gives sidearm carriers formidable firepower during dynamic close-range skirmishes.",
    },
    ["ruger_arr"] = {
        zh = "鲁格美洲人农场卡宾枪。短小精悍的枪身配合旋转后拉枪机，支持通用步枪弹匣供弹，枪口带有螺纹可加装消音器，弹道精准且结实耐用，是牧场与荒野游侠抵御强盗与野兽侵扰的终极猎枪。",
        en = "The Ruger American Ranch Rifle, a compact bolt-action rifle accepting detachable box magazines. Rugged, weather-resistant, and threaded for suppressors, its superb out-of-the-box accuracy fends off feral marauders across vast ruined homesteads.",
    },
    ["ruger_arr_mag"] = {
        zh = "容量为 3 发的鲁格美洲人步枪短款原厂聚合物弹匣。弹匣体积极其小巧，安装后完全平齐于枪身下方，虽然容弹量较少，但在深山雪地里卧倒打猎或攀爬悬崖时完全不会产生任何磕碰刮擦。",
        en = "A compact 3-round rotary polymer box magazine for the Ruger American Rifle. Snapping flush into the underside of the stock, it eliminates external snags when stalking wary quarry through snowy mountain ridges.",
    },
    ["ruger_lcr_22"] = {
        zh = "采用轻量聚合物握把底把与不锈钢弹巢的鲁格 LCR .22 转轮手枪。精致小巧得只有手掌大，装填 8 发边缘发火小弹，扳机行程柔顺平滑，虽然威力有限，但放在裤兜里隐蔽自卫完全不压份量。",
        en = "A lightweight polymer-framed double-action revolver holding eight .22 LR rounds. Dainty and virtually weightless in a coat pocket, its smooth trigger pull provides reliable, snag-free defensive backup when larger primary weapons are unreachable.",
    },
    ["ruger_lcr_38"] = {
        zh = "发射 .38 特种大威力手枪弹的鲁格 LCR 纯双动便携防身转轮手枪。隐藏式击锤设计绝不会勾挂衣物，虽然打满负荷弹药时手掌震颤剧烈，但在被丧尸逼入死角时，这 5 发子弹是最后的保命护符。",
        en = "A snag-free double-action-only five-shot revolver chambered in .38 Special. Its friction-reducing polymer fire-control housing and concealed hammer ensure rapid, snagless draws from coat pockets during frantic grapple defenses.",
    },
    ["ruger_m77"] = {
        zh = "配有厚重层压木枪托与大口径枪管的鲁格 M77 向导向导步枪。经典的毛瑟式可控供弹抓壳钩能确保任何姿势下绝不发生卡壳，一枪即可放倒冲锋的变异巨熊，是荒原顶级猎手的终生伴侣。",
        en = "The formidable Ruger Guide Rifle built on the controlled-round-feed M77 bolt action. Renowned for unflinching reliability in freezing blizzards, its heavy caliber stops charging megafauna and rampaging abominations with single-shot finality.",
    },
    ["ruger_makeshiftmag"] = {
        zh = "用铁皮罐头皮与自行车弹簧手工敲打焊接制成的 5 发 Mini-14 土制简易弹匣。外观粗糙且边缘锋利刮手，虽然上弹时偶尔会因为公差卡壳，但在真弹匣全部丢失的废墟里，能装上子弹就是奇迹。",
        en = "An improvised 5-round Mini-14 magazine hammered from salvaged food tins and bicycle seat springs. Ragged and prone to feeding hiccups, having any working magazine that seats live rounds beats single-loading chambers during a firefight.",
    },
    ["ruger_mini"] = {
        zh = "鲁格 Mini-14 经典半自动 5.56 毫米卡宾枪。汲取了传奇 M14 步枪的成熟旋转闭锁枪机设计，全木质枪托外观平易近人，射击稳定顺畅且皮实耐用，是农庄防卫与废土探索的常青树枪支。",
        en = "The classic Ruger Mini-14 semi-automatic carbine scaled down from the venerable M14 battle rifle. Combining traditional wood sporting ergonomics with rapid 5.56mm cycling, it remains a beloved wasteland companion for homestead defense.",
    },
    ["ruger_mk4"] = {
        zh = "鲁格经典 Mark IV .22 LR 靶场手枪。一键式快速解脱机构让清理积碳极其轻松，厚重靶枪管带来惊人的射击稳定性，在精准射手手里能像飞针般精准穿透猎物眼眶。",
        en = "A precision Ruger Mark IV target pistol chambered in .22 LR. Featuring a simple one-button takedown for effortless field stripping, its heavy bull barrel delivers tack-driving accuracy that drops small game cleanly with pinpoint headshots.",
    },
    ["ruger_mk4_mag"] = {
        zh = "容量为 10 发的鲁格 Mark IV 手枪原厂单排钢制弹匣。侧面带有装弹滑块便于拇指下压快速压弹，金属表面光滑无毛刺，能保证每一发小口径子弹都以最佳角度送入枪膛，绝不卡壳。",
        en = "A standard 10-round single-stack steel magazine for the Ruger Mark IV pistol. Outfitted with an easy-assist loading button that saves thumbs, it feeds rimfire cartridges into target barrels with match-grade consistency.",
    },
    ["ruger_pr"] = {
        zh = "带有全可调折叠枪托与自由浮置枪管的鲁格高精度战术狙击步枪。铝合金机匣刚性极佳，直拉式枪栓操作顺滑无比，在远距离狙杀中能轻易打出重叠弹孔，是废土狙击手梦寐以求的竞赛级杀戮利刃。",
        en = "The Ruger Precision Rifle featuring a fully adjustable folding stock and free-floating handguard. Designed for competition long-range shooting, its rigid inline chassis consistently places match rounds into the same ragged hole across vast distances.",
    },
    ["ruger_pr_mag"] = {
        zh = "专为鲁格高精度步枪定制的 5 发单排可拆卸聚合物弹匣。体积小巧且结构坚固，紧密贴合步枪弹匣井，能在卧姿射击时提供毫无晃动的稳固供弹支持，是狙击手精准猎杀的可靠弹药伙伴。",
        en = "A detachable 5-round single-stack polymer magazine for the Ruger Precision Rifle. Fitting snugly into the magazine well, its stable feed lips support match ammunition without deforming soft projectile tips during bolt closing.",
    },
    ["rugerlcp"] = {
        zh = "极度轻巧的 .380 口径袖珍聚合物防身手枪。虽然握把小到连两根手指都难以完全握牢，后坐力震手且准星短得几乎纯凭感觉，但在近身撕扯的绝境下，它是能塞进袜子里的最后一根救命稻草。",
        en = "A featherweight polymer .380 pocket pistol barely larger than a smartphone. While snappy recoil and non-existent sight radius defy accurate marksmanship, having a hideout gun tucked into your sock beats pleading with ravenous zombies.",
    },
    ["rugerlcpmag"] = {
        zh = "仅能容纳 6 发 .380 子弹的鲁格 LCP 单排钢制弹匣。娇小的体积甚至塞不下一盒火柴，扣动扳机几秒钟便会彻底打空，提醒所有幸存者每一次击发都必须算准命中点，绝无挥霍余地。",
        en = "A petite 6-round single-stack steel magazine for the Ruger LCP. Emptying in seconds during close-quarters panic, its meager capacity constantly reminds desperate survivors that every trigger pull must count before resort to frantic hand-to-hand brawling.",
    },
    ["rugerpcc"] = {
        zh = "兼容格洛克手枪弹匣的 9 毫米半自动卡宾枪。枪管可快速拆卸收纳，机匣耐用且供弹顺畅，让幸存者能用最泛滥的手枪弹打出步枪级的精准落点，堪称废土中最经济实惠的清道利器。",
        en = "A rugged 9mm take-down pistol caliber carbine accepting ubiquitous Glock magazines. Splitting neatly into backpacks and spitting common handgun rounds with rifle-grade precision, it represents the ultimate economical scavenger sweeper.",
    },
    ["ruined_chunks"] = {
        zh = "屠宰失手或野兽啃噬后遗留的碎肉与污血残渣。虽然散发着令人作呕的血腥恶臭且完全无法下咽，但对于饥肠辘辘的野狗或缺乏警惕的丧尸而言，这依然是诱敌上钩的绝佳血腥诱饵。",
        en = "Mangled chunks of bloodied meat and gristle ruined by sloppy butchery. While completely unfit for civilized human consumption, the sickening stench makes surprisingly effective bait for distracting mutant beasts or luring lumbering zombies into spike pits.",
    },
    ["ruler"] = {
        zh = "刻度清晰的塑料直尺。在文明时代用来丈量图纸几何与教训顽皮学生，而在大灾变后，无论是测量自制长矛的重心，还是在火炉旁掰断充当塑料引火片，都算没有辱没它的身价。",
        en = "A simple thirty-centimeter plastic ruler with faded millimeter markings. Once measuring classroom geometric homework, in the apocalypse it gauges homemade spear balance before inevitably snapping in half to serve as plastic fire starter.",
    },
    ["rum"] = {
        zh = "以甘蔗糖蜜发酵蒸馏而成的烈性朗姆酒。浓郁的焦糖香气混合着火辣的灼烧感，既能让瑟瑟发抖的流浪者忘却窗外的暴雨与丧尸咆哮，也能在紧急时刻充当消毒伤口的灼痛烈酒。",
        en = "High-proof liquor distilled from fermented sugarcane molasses. Carrying bold aromas of burnt caramel and liquid fire, a stout swig numbs the howling storm outside while doubling as excruciating emergency wound wash.",
    },
    ["rummy"] = {
        zh = "装在布袋里的全套拉密数字牌。这些坚硬的塑料数字牌曾让一家人在壁炉边消磨数小时，如今在避难所漫长的停电长夜里，依然是保持幸存者心智健全与阻止同伴拔刀的绝佳桌游。",
        en = "A full set of durable numbered Rummy-o tiles packed into a cloth pouch. Originally providing peaceful family evening entertainment, sorting color sets now keeps paranoid shelter dwellers sane during tense, candlelit blackout vigils.",
    },
    ["runner_bag"] = {
        zh = "贴合人体工学设计的轻量化跑步腰包。紧贴腰际绝不随奔跑剧烈晃动，虽然容量仅能塞下止血带、几发散装子弹和半包能量胶，但能让你在尸群围追堵截中保持全速冲刺。",
        en = "A lightweight, ergonomic waist pack designed to eliminate bouncy movement during dead sprints. Holding merely a tourniquet, loose cartridges, and energy paste, it keeps vital gear accessible while fleeing ravenous mutant hordes.",
    },
    ["rx11_stimpack"] = {
        zh = "军用级 RX11 高效肾上腺与神经兴奋剂注射器。高压喷射针头能直接穿透防弹衣刺入皮下，强行驱散致命剧痛并榨干骨髓里的最后体力，但药效过后的虚脱往往比外伤更加致命。",
        en = "A military-grade RX11 stimulant injector designed to fire through ballistic armor. Flooding weary veins with synthetic adrenaline, it suppresses crippling pain and borrows tomorrow's stamina at the steep price of catastrophic post-rush exhaustion.",
    },
    ["rx12_injector"] = {
        zh = "高科技 RX12 无针气压高压注射器。利用微秒级脉冲气流将救命药剂无痛穿透角质层注入血管，避免了传统注射器折断针头的致命隐患，是战地医疗兵在混战火线中的生命保障。",
        en = "A cutting-edge needleless jet injector pushing life-saving pharmacopeia straight through dermis with high-pressure gas pulses. Eliminating broken needles during desperate firefights, it delivers emergency medical compounds instantly without missing a beat.",
    },
    ["sabaton_metal_sheets"] = {
        zh = "用废旧铁皮与金属合页手工敲打而成的简易铁足护甲。走起路来像踢着铁桶般叮当作响，虽然沉重拖沓且磨损皮靴，但能有效防止脚踝被匍匐在草丛中的变异毒蛇或爬行丧尸咬穿。",
        en = "Crude protective footwear hammered together from scrap sheet metal and salvaged rivets. Clanking like falling cookware with every stride, they severely hamper stealth yet stop creeping ankle-biting abominations from gnawing off your toes.",
    },
    ["saddle"] = {
        zh = "以厚实皮革与钢制鞍架缝制的老式骑乘马鞍。只要你能找到一匹尚未感染变异的幸存骏马，或者驯服一头性情温顺的巨大变异鹿，它就能让你在旷野中摆脱用双腿逃亡的痛苦折磨。",
        en = "A classic riding saddle stitched from heavy harness leather and forged metal trees. Should you locate an uninfected horse or tame a docile mutant herbivore, it converts exhausting cross-country foot slogs into grand mounted travel.",
    },
    ["saddlebag"] = {
        zh = "搭挂在坐骑后背两侧的双联厚皮革马鞍袋。容量充沛且防水耐磨，能将搜刮而来的罐头与枪支均匀分担在牲畜两肋，是废土游侠携带全部家当长途跋涉的理想移动货舱。",
        en = "A pair of rugged leather panniers draped across a beast of burden. Waterproof and capacious, they balance scavenged rations and heavy ammunition across flanks, keeping wandering riders equipped with mobile survival hoards.",
    },
    ["safe_box"] = {
        zh = "银行保险库专用的厚重双锁孔金属保管箱。原本存放着旧世界的地契、钻石与绝密遗嘱，如今在废土上除了充当坚固的金属收纳盒外，还能直接抡起来砸扁游荡丧尸的脑袋。",
        en = "A heavy steel safe deposit box pulled from subterranean bank vaults. Once safeguarding paper deeds and diamond heirlooms that mean nothing now, it functions either as an impenetrable toolbox or an unwieldy bludgeon against zombies.",
    },
    ["saiga10mag"] = {
        zh = "塞加-12 突击霰弹枪专用的 10 发加长聚合物盒式弹匣。装满重型 12 号鹿弹后沉甸甸的，能将半自动霰弹枪变成短时间内撕裂走廊尸群的暴风骤雨收割机，清理狭窄房间的不二之选。",
        en = "A 10-round extended box magazine built for the Saiga-12 assault shotgun. Packed with heavy buckshot, it converts the semi-automatic scattergun into a hallway-clearing woodchipper capable of erasing breaches before smoke clears.",
    },
    ["saiga30mag"] = {
        zh = "为塞加-12 霰弹枪量身打造的大容量 20 发供弹具。虽然体积庞大笨重犹如挂着一个小型汽油桶，但提供的前所未有的持续狂暴霰弹轰炸，能让任何冲锋而来的巨型异种饮恨倒下。",
        en = "A massive high-capacity drum magazine engineered for 12-gauge Saiga shotguns. Though extraordinarily bulky and heavy as an iron anchor, unleashing continuous devastating buckshot salvos obliterates hulking mutant beasts in seconds.",
    },
    ["saiga410mag_10rd"] = {
        zh = "塞加-410 霰弹枪原厂 10 发单排直弹匣。细长的弹体装填着较为柔和的 .410 霰弹，后坐力平稳温顺，适合幸存者在室内巡逻时从容应对突然扑来的小型变异生物或野狗群。",
        en = "A slender 10-round stick magazine crafted for the gentle Saiga-410 shotgun. Feeding mild .410 shells with dependable smooth action, it offers comfortable recoil control for dispatching annoying pests and feral dogs indoors.",
    },
    ["saiga410mag_30rd"] = {
        zh = "专为塞加-410 打造的 30 发圆形加长弹鼓。虽然口径偏小导致弹丸穿透力有限，但整整三十次毫无间歇的连发射击声浪，足以把任何胆敢靠近的变异害虫打成筛子。",
        en = "A specialized 30-round drum magazine manufactured for .410 caliber semi-automatic shotguns. While each small pellet carries modest kinetic punch, thirty continuous bangs quickly turn encroaching swarm pests into shredded organic confetti.",
    },
    ["saiga_12"] = {
        zh = "基于卡拉什尼科夫步枪自动机原理改进的十二号弹匣式半自动突击霰弹枪。狂暴的连射火力能在三秒内清空整支大容量弹匣，把扑面而来的丧尸潮彻底轰杀成漫天肉雨。",
        en = "A magazine-fed semi-automatic 12-gauge shotgun built on rugged Kalashnikov internals. Emptying drum magazines into cramped hallways in seconds, it vaporizes advancing zombie hordes into flying red mulch.",
    },
    ["saiga_410"] = {
        zh = "基于经典 AK 平台改进而来的塞加 .410 口径半自动霰弹枪。有着步枪般的熟悉外形与顺滑机匣，发射的细长散弹后坐微弱，是练习移动射击与清理弱小猎物的省力好帮手。",
        en = "A Kalashnikov-pattern semi-automatic shotgun chambered in modest .410 bore. Operating with familiar AK reliability and gentle kick, it provides dependable pest control for marksmen seeking rapid target transitions without bruised shoulders.",
    },
    ["sail"] = {
        zh = "由结实防撕裂帆布缝制的中型简易船帆。架设在木筏或小型水运载具上，便能借助变幻莫测的废土狂风在江河湖泊上无声航行，彻底摆脱划桨带来的臂力耗竭与引擎噪音。",
        en = "A sturdy canvas sail stitched with reinforced seams for lightweight watercraft. Rigged upon a wooden raft or canoe, it harnesses fickle post-cataclysm breezes to cruise silent waterways without tiring paddling arms or roaring motors.",
    },
    ["sail_large_item"] = {
        zh = "专为大型帆船或废土风力旱地车定制的巨型风帆。广阔的迎风面积能在劲风呼啸时迸发出惊人的牵引推力，让沉重的货船或滑行车在开阔水域与公路上一骑绝尘飞驰前行。",
        en = "A massive maritime sail cut from heavy-duty treated cloth for full-sized rigs. Catching howling wasteland gusts across wide surface area, it generates monstrous propulsion to drive laden vessels or land yachts across barren expanses.",
    },
    ["sake_filtered"] = {
        zh = "经过精细滤渣与熟化处理的传统日本清酒。清澈透明的酒液散发着优雅的米香与果木甘甜，在满目疮痍的废墟避难所里温上一壶，是对逝去精致文明最温柔的凭吊与抚慰。",
        en = "Carefully filtered and matured traditional Japanese rice wine. Clear as mountain spring water with delicate floral sweetness, warming a cup amid broken concrete offers profound spiritual solace honoring lost civilized graces.",
    },
    ["sake_koji_rice"] = {
        zh = "接种了米曲霉菌丝并精心发酵的酿酒曲米。表面泛着一层均匀细腻的白色菌丝孢子，散发出温暖浓郁的谷物发酵香气，是废土酿酒大师开启高品质自酿酒精饮料的神奇催化剂。",
        en = "Steamed rice inoculated with delicate white Aspergillus oryzae mold cultures. Emitting rich earthy aromas of active enzymatic fermentation, these potent grains form the essential catalyst for crafting exquisite homemade spirits.",
    },
    ["sake_unfiltered"] = {
        zh = "保留了部分细微酒糟微粒的浑浊白浊酒。乳白色的酒体浓郁醇厚，带着质朴的米浆香气与天然微甜，饱腹感十足，既是一杯让人微醺的美酒，也是热量充沛的流动粮食补给。",
        en = "Cloudy nigori sake bottled with unpressed rice sediment. Featuring a milky appearance and creamy rice nectar texture, this hearty traditional brew nourishes empty stomachs while imparting a comforting, mellow buzz.",
    },
    ["salca"] = {
        zh = "阳光日晒风干并浓缩而成的浓稠土耳其番茄辣椒酱。酸甜中带着浓郁的深沉咸香，只要挖上一小勺拌入粗糙的压缩饼干或炖肉汤中，就能让难以下咽的废土残羹化作珍馐美味。",
        en = "Thick, sun-ripened paste crafted from slow-cooked tomatoes and red peppers. Packing intensely savory Umami depth with tangy warmth, a single spoonful transforms bland boiled hardtack rations into aromatic Mediterranean feast.",
    },
    ["saline"] = {
        zh = "无菌封装的 0.9% 医用氯化钠生理盐水。渗透压与人体血液完全相同，无论是冲洗沾满污泥与感染碎屑的撕裂伤口，还是清洗沾染酸液的眼睛，都是废土医生不可或缺的救命甘霖。",
        en = "Sterile 0.9% sodium chloride isotonic solution matching human blood salinity. Ideal for flushing irradiated grit from open wounds or washing caustic acid spatters from eyes, it represents medical purity in an infected world.",
    },
    ["saline_bag_1000"] = {
        zh = "容量整整一升的标准医用生理盐水输液袋。配有输液管插口与挂钩，在幸存者遭受严重失血休克、烧伤脱水或食物中毒时，挂在高处静脉滴注是维持循环血量与抢救生命的底牌。",
        en = "A full 1000ml clinical intravenous saline drip bag fitted with sterile tubing ports. Essential for treating severe trauma shock, massive blood loss, or dehydration, hanging this bag overhead literally drips life back into critical survivors.",
    },
    ["saline_bag_1000_empty"] = {
        zh = "药液用尽后留下的 1000 毫升医用聚氯乙烯储液袋。结实耐折且密封性能极佳，冲洗干净后挂在腰带上，不仅是轻便耐摔的便携水囊，也是收集汽油或蒸馏酒精的隐秘储液软袋。",
        en = "An emptied 1000ml medical-grade intravenous bag made of flexible clear plastic. Tough, transparent, and completely leak-proof when capped, it converts into an ultra-lightweight canteen or airtight reservoir for distilled fuel.",
    },
    ["saline_bag_2000"] = {
        zh = "足足两升装的巨型医用生理盐水输液软袋。沉重而饱满的液体包通常用于大型外科抢救手术，在大灾变中能为濒死的重伤幸存者提供持续数小时的输液补液支持，稳定脆弱的生命体征。",
        en = "A colossal two-liter intravenous infusion pouch containing sterile saline. Primarily found in hospital surgical wards, hanging this monster bag delivers hours of life-sustaining fluid volume restoration for battered wasteland combat casualties.",
    },
    ["saline_bag_2000_empty"] = {
        zh = "腾空后的两升超大医用塑料输液软袋。体积庞大且韧性出众，折叠起来甚至只有手掌大小，展开后却能容纳整整两公升净水，是长途跨区域侦察时绝不占负重空间的优质软质水囊。",
        en = "A drained two-liter medical infusion bladder made of heavy-duty polymer. Rolling up smaller than a fist when empty yet holding substantial emergency drinking water, it makes the ultimate foldaway pack reservoir for nomadic scouts.",
    },
    ["saline_bag_250"] = {
        zh = "容量仅为 250 毫升的小型便携式医用生理盐水输液袋。小巧玲珑便于塞入战术急救包中，适合快速为失水患者补充电解质，或是用来稀释高浓度抗生素药剂进行精准微量滴注。",
        en = "A compact 250ml intravenous saline bag built for rapid field deployment. Fitting neatly into compact trauma kits, it serves either for rehydrating injured scouts or accurately diluting concentrated injectable antibiotics.",
    },
    ["saline_bag_250_empty"] = {
        zh = "用空的小型 250 毫升医用塑料软袋。虽然容量不大，但其优异的化学惰性与严密的密封嘴，用来分装自制硝化甘油、稀有消毒酒精或纯净眼药水简直是量身定做的神器容器。",
        en = "A discarded 250ml IV plastic pouch with intact sealing ports. Its inert medical polymer construction and leak-free nozzles make it perfect for carrying small doses of precious tinctures, venom antidotes, or concentrated acids.",
    },
    ["saline_bag_500"] = {
        zh = "半升装的中型标准医用生理盐水输液袋。兼顾了容量与便携性，是救护车与野战医院最常用的规格，能在野外紧急抗休克与大面积创面持续冲洗中发挥关键中坚力量。",
        en = "A versatile 500ml IV saline pack striking an ideal balance between portable weight and fluid volume. Common in pre-collapse ambulances, it proves invaluable for field trauma resuscitation and sterile cleansing of open wounds.",
    },
    ["saline_bag_500_empty"] = {
        zh = "抽空后的 500 毫升透明医用储液袋。耐磨耐挤压且无异味，无论是倒插一根塑料管自制临时水袋，还是密封储存采集到的珍贵变异生物体液样本，都让人格外放心可靠。",
        en = "An empty 500ml medical drip pouch stripped of fluids. Durable, odorless, and resistant to punctures, it adapts seamlessly into a makeshift hydration bladder or a secure vessel for storing weird biochemical specimen extracts.",
    },
    ["salsa"] = {
        zh = "由切碎的番茄、辣椒、洋葱与芫荽调制而成的萨尔萨鲜辣酱。酸辣爽口且富含维生素，哪怕浇在硬得像石头的玉米干饼上，也能激发起胃部沉寂已久的狂暴食欲与生存意志。",
        en = "A vibrant salsa mix combining chopped tomatoes, spicy peppers, onions, and zesty herbs. Packing tangy heat and essential vitamins, slathering this condiment over rock-hard hardtack transforms grim sustenance into a fiery fiesta.",
    },
    ["salsify_baked"] = {
        zh = "在火堆炭火中慢火烤熟的蒜叶婆罗门参根茎。原本粗糙的根须变得软糯多汁，散发着类似生蚝与芦笋交织的奇特鲜甜香气，在物资匮乏的废土上堪比奢华的野生海鲜盛宴。",
        en = "Slow-roasted salsify taproots baked gently over campfire coals. Softening woody fibers into creamy, steaming flesh reminiscent of artichokes and cooked oysters, this wild root provides unexpected gourmet dining in ash-covered ruins.",
    },
    ["salsify_raw"] = {
        zh = "野外挖掘出来的蒜叶婆罗门参新鲜粗根。外皮带着潮湿的黑泥与细密根须，看似不起眼的枯黄树根，洗净后却蕴含着饱满的淀粉与甘甜汁水，是采集者度过荒野荒冬的生命根基。",
        en = "A freshly unearthed wild salsify taproot covered in damp soil. Though resembling a dirty, unremarkable dried branch, peeling reveals crisp nutrient-dense pulp that sustains resourceful foragers through bitter post-apocalyptic winters.",
    },
    ["salt"] = {
        zh = "纯净洁白的氯化钠结晶细盐。自古以来就是人类争夺与维持生存的血液之源，在末日里更是腌制防腐新鲜猎物、补充剧烈运动电解质以及给难吃废土乱炖提味的硬通货之王。",
        en = "Pure granular sodium chloride crystals sparkling like crushed glass. The timeless white gold of human civilization, salt preserves perishable fresh meat, sustains vital nervous systems, and makes bland survival slop palatable.",
    },
    ["salt_lick"] = {
        zh = "专供牛羊马匹舔舐的厚重浓缩矿物盐砖。质地坚硬如花岗岩，不仅含有丰富盐分还掺杂了微量微量元素，既能放在农场吸引驯服野生食草兽，也能在迫不得已时用刀刮下细屑做菜。",
        en = "A heavy compressed block of mineral-enriched salt intended for livestock licking. Hard as granite, it lures wandering ruminants into corral traps or provides endless scraped shavings for desperately unseasoned survivor stews.",
    },
    ["salt_water"] = {
        zh = "从大海或高盐咸水湖中舀取的高浓度含盐水。直接大口饮用会急剧加速脱水并导致肾脏衰竭发狂，但经过简单蒸馏装置提纯后，既能获得宝贵的淡水，锅底还能刮下防腐的白盐。",
        en = "Briny mineral water scooped from oceans or alkaline evaporation basins. Lethal to drink raw due to dehydrating cellular shock, running it through improvised solar stills yields precious pure drinking water and crusty cooking salt.",
    },
    ["salted_fish"] = {
        zh = "用粗海盐彻底脱水腌透的硬身海鱼。咸得发苦且肉质硬如老树皮，但在没有任何制冷设备的严酷末日里，这一条条腌鱼就是能陪伴你安然度过漫长严冬的蛋白质宝库。",
        en = "A whole river fish thoroughly cured in coarse rock salt. Stiff as a wooden board, boiling it into broths sustains lonely trappers through frozen months without power grids.",
    },
    ["salted_mollusk"] = {
        zh = "裹满白色盐霜的脱水腌制贝类软肉。放进嘴里嚼上半天才能渐渐化开咸鲜的滋味，胜在随手抓一把塞进风衣口袋放上数月也不会变质，是远征行商的传统便携口粮。",
        en = "Preserved shellfish meat heavily crusted in white sea salt crystals. Chewy and intensely briny, a handful stored in travel pouches provides durable sodium and calories during cross-country treks.",
    },
    ["samghati"] = {
        zh = "由各色旧布料拼接缝制而成的佛教传统大衣僧伽黎。虽然毫无防弹与防刺功能，但宽大的下摆透气飘逸，在废土漫漫苦行路上披在身上，能带来远离尘世杀戮的精神宁静与超脱。",
        en = "A traditional Buddhist monk's outer patchwork robe stitched from weathered fabric remnants. Offering virtually zero ballistic protection, its loose flowing folds bring spiritual tranquility and detachment while wandering ruined, violent wastes.",
    },
    ["samosa_veggy"] = {
        zh = "外皮炸得金黄酥脆的传统蔬菜咖喱三角饺。里面塞满了温热辛香的土豆泥、青豆与浓郁香料，咬下一口满嘴香酥热气升腾，让人瞬间忘却周围破败阴冷的变异废土现实。",
        en = "A golden-fried triangular pastry stuffed with spiced potatoes, green peas, and fragrant herbs. Biting through the blistered crispy crust releases clouds of aromatic curry steam, completely dispelling gloomy damp cellar chills.",
    },
    ["sample_t_substrate"] = {
        zh = "装在恒温密封管内的神秘 T-基质生化科研样本。在微光下泛着幽绿色的微弱荧光，蕴含着灾变前尖端基因工程的致命秘密，哪怕不慎摔碎一丝泄漏，都可能引发难以预料的异变。",
        en = "A sealed cryo-vial containing luminous T-substrate bio-engineering compound. Faintly phosphorescent under dim lighting, this precursor chemical holds catastrophic genomic secrets capable of triggering monstrous mutations if carelessly handled.",
    },
    ["sandbox_kit"] = {
        zh = "色彩斑斓的儿童塑料沙坑铲子与小水桶玩具套装。明亮的亮黄色与粉蓝色在这个灰暗死寂的绝望废土上显得格外刺眼，偶尔有幸存者拿它在废墟花坛里刨土播种，当作最后的黑色幽默。",
        en = "A colorful set of molded plastic sand shovels and toy buckets. Their bright cheerful hues contrast sharply against monochrome nuclear ash, serving as bitterly ironic trowels for planting radishes in roadside flowerbeds.",
    },
    ["sandpaper"] = {
        zh = "附着坚硬金刚砂颗粒的高标号耐水砂纸。在工匠手里能打磨光滑弓臂毛刺、修整精细枪托木纹并磨平机械接合缝隙，是让粗劣手工自制工具跃升为顺手兵刃的幕后功臣。",
        en = "A sheet of heavy-grit abrasive sandpaper backed by tough treated paper. Smoothing rough splintering tool handles and polishing scarred metal slides, it transforms jagged scrap scavenges into ergonomic implements of survival.",
    },
    ["sandwich_cheese"] = {
        zh = "两片干燥面包之间夹着厚厚陈年硬质奶酪的极简三明治。虽然没有鲜肉与酱汁点缀显得略为干噎，但在废墟中跋涉时能提供极高密度的脂肪与蛋白质热量，是可靠实用的速食干粮。",
        en = "A no-nonsense sandwich consisting of sharp cheese tucked between dry bread slices. Lacking fancy condiments, its concentrated protein and dairy fats provide reliable, dense energy to keep weary legs marching onward.",
    },
    ["sandwich_cheese_grilled"] = {
        zh = "在平底锅或热铁板上用动物油脂煎至两面金黄的烤奶酪三明治。咬破酥脆的面包外壳，滚烫浓郁的融化奶酪丝拉出长长细线，带来让人幸福落泪的极致碳水与脂肪治愈体验。",
        en = "A comforting grilled sandwich toasted golden brown over sizzling animal fat. Biting the crisp, buttery crust reveals molten threads of gooey cheese, delivering an intoxicating rush of nostalgic calories that warms the soul.",
    },
    ["sandwich_cucumber"] = {
        zh = "切成薄片的爽脆黄瓜夹入抹了黄油的软面包而成的英式黄瓜三明治。清脆多汁且带着一抹令人神清气爽的瓜果清香，在浑浊污秽的末日里，每一口都是对文明下午茶时光的优雅复刻。",
        en = "Crisp, wafer-thin cucumber slices layered across lightly buttered sandwich bread. Refreshingly crunchy with clean garden fragrance, enjoying this delicate snack in filthy bunkers evokes the refined decadence of aristocratic afternoon tea.",
    },
    ["sandwich_deluxe"] = {
        zh = "层层叠叠堆满烟熏肉片、融化奶酪、酸黄瓜与特调酱汁的巨无霸特级三明治。厚重得连下巴脱臼都难以一口咬全，是废土大厨在搜刮到所有顶级食材后炫耀烹饪技艺的巅峰杰作。",
        en = "A towering multi-layered sandwich overflowing with cured meat slices, melted cheese, pickles, and rich dressing. Requiring both hands and an unhinged jaw to bite, it represents the absolute pinnacle of post-apocalyptic gastronomy.",
    },
    ["sandwich_egg_salad"] = {
        zh = "以碎熟鸡蛋拌入浓稠蛋黄酱与黑胡椒制成的鸡蛋沙拉三明治。口感绵密细腻且散发着浓郁蛋香，虽然在高温下极易变质必须尽快享用，但刚做好的滋味足以抚平一切末日创伤。",
        en = "Creamy hard-boiled eggs mashed with mayonnaise and cracked black pepper between soft bread. Rich and velvety on the tongue, it must be consumed quickly before spoiling under harsh sunlight, granting fleeting moments of bliss.",
    },
    ["sandwich_fairy"] = {
        zh = "抹上厚厚黄油并撒满五彩缤纷糖珠颗粒的澳洲传统彩糖面包。甜腻的糖粒在舌尖噼啪碎裂，这曾经属于孩子狂欢派对的甜美点心，在残破废墟中闪烁着如同童话幻梦般的荒诞色彩。",
        en = "A slice of buttered white bread generously smothered in kaleidoscopic sugary sprinkles. Known as classic fairy bread, this colorful childhood party snack brings wildly surreal, glittering sweetness to grimy post-collapse concrete ruins.",
    },
    ["sandwich_honey"] = {
        zh = "将金黄黏稠的野蜂蜜涂抹在厚切粗麦面包上制成的甜美三明治。蜂蜜慢慢渗入松软的气孔中，每一口都洋溢着高热量单糖带来的暴风吸入快感，是搜刮蜂巢死里逃生后最甜蜜的疗伤战利品。",
        en = "Golden sticky honey generously slathered across rustic thick-cut wheat bread. Seeping into spongy crumb pockets, each sugary mouthful delivers instant glycemic euphoria, serving as the sweetest reward after braving agitated mutant beehives.",
    },
    ["sandwich_jam"] = {
        zh = "以浆果熬制的浓缩果酱作为夹心的简易三明治。鲜艳的深红色果酱在按压下从面包边缘溢出，酸甜解腻的果香仿佛能将末日的尘土与硝烟气息瞬间驱散，让精神为之一振。",
        en = "A simple sandwich loaded with sweet boiled berry preserves. Bright crimson jam squishing from the crusty edges cuts through stale post-collapse gloom, providing refreshing fruity tartness that lifts weary spirits after brutal skirmishes.",
    },
    ["sandwich_jam_butter"] = {
        zh = "底层涂抹香浓黄油、上层覆满果酱的双重美味三明治。浓郁的动物乳脂与酸甜果香在口中完美平衡，既解除了单纯油脂的腻滞，又为长途跋涉的肌肉提供了扎实充盈的热量支持。",
        en = "Rich churned butter paired with tart fruit jam between hearty sandwich halves. Balancing dense dairy lipids with refreshing sweetness, it provides enduring energy reserves for weary scavengers facing endless miles of cracked asphalt.",
    },
    ["sandwich_jam_cheese"] = {
        zh = "结合了咸香硬质干酪与甜美果酱的大胆风味三明治。咸甜交织的浓烈味觉碰撞让人初尝惊愕、再嚼上瘾，是那些搜刮到零散军粮后随性搭配出来的废土厨艺创新范例。",
        en = "A daring culinary combination uniting sharp savory cheese with sweet fruit jam. The contrasting clash of salty dairy and sugary fruit sparks intense palate confusion that quickly turns into an addictive apocalypse delicacy.",
    },
    ["sandwich_pb"] = {
        zh = "涂满厚厚一层黏稠花生酱的饱腹三明治。虽然浓郁的花生油脂黏在上颚上让人难以开口说话，但在缺乏水源与炉灶的紧急逃亡途中，它是能一口气顶住大半天饥饿的蛋白质炸弹。",
        en = "Thick, pasty peanut butter spread generously between dry bread slices. While sticking stubbornly to the roof of your mouth and defying articulation, it packs massive protein density to fuel grueling escapes across barren wastelands.",
    },
    ["sandwich_pbf"] = {
        zh = "花生酱与蓬松棉花糖奶油酱双重夹心的经典狂欢三明治。黏稠的花生咸香交织着几乎能溶化牙齿的极致香甜，哪怕周围遍布废墟与丧尸，也能瞬间唤醒童年放学后的极乐回忆。",
        en = "A decadent fluffernutter sandwich sandwiching sticky peanut butter alongside airy marshmallow creme. Delivering an almost tooth-melting wave of nostalgic sweetness, this sugar-bomb banishes apocalyptic dread with every sticky, joyful bite.",
    },
    ["sandwich_pbh"] = {
        zh = "融合了黏密花生酱与纯正天然蜂蜜的高能量双拼三明治。糖分与坚果油脂相得益彰，吃上一块不仅能快速恢复体力，黏稠的口感还能逼迫焦虑的幸存者专心咀嚼并冷静下来。",
        en = "Peanut butter and pure golden honey layered together within chewy survival bread. Combining rich nutty lipids with fast-burning simple sugars, it rapidly restores spent stamina while forcing anxious scavengers to chew meditatively.",
    },
    ["sandwich_pbj"] = {
        zh = "旧时代美式家庭的灵魂之作——花生酱果酱三明治。咸香细腻的花生酱与酸甜多汁的果酱相濡以沫，只要两片面包还能吃，咬下去的瞬间就仿佛文明从未曾崩塌过一样安详。",
        en = "The quintessential American comfort classic pairing salty creamy peanut butter with sweet grape jelly. Stacking familiar childhood solace between humble bread, eating it makes the smoking ruins of civilization feel temporarily distant.",
    },
    ["sandwich_pbm"] = {
        zh = "花生酱浸润着浓郁深色枫糖浆的特调风味三明治。枫树提取物独特的焦香木质甜味与烘烤花生碎完美融合，给单调乏味的避难所生活增添了一抹加拿大森林般的豪放风情。",
        en = "Creamy peanut butter drenched in aromatic dark maple syrup between bread slices. The deep woody sweetness of forest tapped syrup harmonizes with savory roasted peanuts, lending rustic frontier elegance to grim bunker dining.",
    },
    ["sandwich_reuben"] = {
        zh = "堆满咸牛肉薄片、瑞士奶酪、德式酸菜与特调俄式沙司的经典鲁宾三明治。热压烘烤后外皮金黄酥脆、内里酸香爆汁，是在大灾变厨房里重构顶级餐厅繁复工艺的奢靡证明。",
        en = "A legendary grilled Reuben packed with layers of savory corned beef, melted Swiss, tart sauerkraut, and Russian dressing. Crisped golden over hot skillets, this towering sandwich resurrects pre-cataclysm delicatessen splendor amid ash-choked ruins.",
    },
    ["sandwich_sauce"] = {
        zh = "仅抹了薄薄一层泛黄蛋黄酱与番茄酱的单调白面包三明治。虽然里面连一片像样的火腿碎末都找不到，但松软的面包片混着酸甜酱汁，依然能给空瘪的胃囊带来踏实的慰藉。",
        en = "A plain sandwich made from stale bread slices smeared with mayonnaise and ketchup. Bereft of cheese or meat, its acidic, oily sauce trick fills grumbling bellies when rations run dangerously thin.",
    },
    ["sandwich_t"] = {
        zh = "夹着整块煎熟肉排或厚切熟肉的质朴荤食三明治。朴实无华的面包夹肉结构提供了最简单纯粹的动物蛋白质与嚼劲，是在旷野巡逻间隙快速补充体能的不二硬派干粮。",
        en = "A hearty carnivore sandwich packed with thick slices of cooked meat between coarse bread. Stripped of pretentious garnishes, it delivers pure animal protein and satisfying chew to keep weary patrols alert and marching.",
    },
    ["sandwich_veggy"] = {
        zh = "层叠堆放着新鲜生菜、番茄片与黄瓜丝的爽脆蔬菜三明治。清脆多汁的天然纤维在口中爆开，为长期依赖罐头和肉干而饱受坏血病威胁的废土游侠送来宝贵的维生素甘泉。",
        en = "Crisp garden lettuce, ripe tomato rounds, and sliced cucumbers packed between fresh bread. Bursting with refreshing moisture and raw dietary fiber, it rescues scorbutic wasteland wanderers tired of salty canned rations and pemmican.",
    },
    ["sandwich_veggy_cheese"] = {
        zh = "在新鲜脆嫩蔬菜之上覆盖一片浓郁奶酪的营养均衡三明治。奶酪的厚重奶香补足了蔬菜纤维的清淡，入口兼具爽脆与柔韧，是废土温室种植者最引以为傲的健康午餐标配。",
        en = "Fresh garden vegetables paired with a thick slab of savory cheese within rustic bread. Marrying crisp botanical crunch with creamy dairy indulgence, it represents the proud culinary bounty of fortified rooftop greenhouse farmers.",
    },
    ["santa_beard"] = {
        zh = "用人造聚酯纤维制成的雪白蓬松圣诞老人大假胡子。戴在脸上虽然扎得下巴发痒且极易吸附灰尘，但能有效挡住刺骨寒风，偶尔还能在昏暗走廊里吓退一两个迷信的流浪拾荒者。",
        en = "A fluffy white novelty beard fashioned from synthetic polyester fibers. While itching uncomfortably against stubble, this festive holiday prop provides surprisingly cozy neck insulation while bewildering jumpy scavengers in dark corridors.",
    },
    ["santa_belt"] = {
        zh = "配有超大金色塑料方扣的宽版黑色仿皮圣诞腰带。原本是用来勒住圣诞老人圆滚滚假肚子的节日饰品，如今其厚实宽阔的版型在固定沉重枪套和防止裤子滑脱方面表现极佳。",
        en = "An extra-wide black pleather belt boasting an oversized faux-gold buckle. Designed to restrain Santa's padded belly during mall appearances, its wide profile securely anchors heavy holster rigs without pinching your waist.",
    },
    ["santa_dress"] = {
        zh = "饰有毛茸茸白色毛边的大红色天鹅绒圣诞连衣裙。鲜艳的红色在末日灰暗雪原上格外醒目，虽然在潜行狙击时犹如活靶子，但在废土狂欢晚会中穿上它绝对能成为全场目光焦点。",
        en = "A festive bright crimson velvet dress trimmed with snowy faux-fur cuffs. While transforming stealthy scouts into vibrant sniper targets across winter wastes, sporting this holiday attire guarantees cheerful applause during shelter festivities.",
    },
    ["santa_dress_long"] = {
        zh = "拖地长度的高级厚实红色天鹅绒圣诞礼服长裙。宽大的裙摆下衬着保暖绒布，即便在严寒冬夜的避难所壁炉旁，也能让人兼顾优雅的节日贵气与抵御穿堂冷风的实用保暖功能。",
        en = "A sweeping floor-length Santa gown cut from plush scarlet velvet and lined with warm fleece. Providing elegant festive grandeur alongside genuine thermal insulation, it keeps charismatic leaders warm while hosting fireside bunker banquets.",
    },
    ["santa_dress_short"] = {
        zh = "剪裁短俏轻便的红色圣诞短裙。没有多余布料拖累双腿奔跑步伐，红白相间的节日配色虽然略显轻浮，但在燥热的地下室温控失效时，却成了难得通风透气的清凉节日装束。",
        en = "A playful short Santa dress trimmed with fluffy white hems. Offering uninhibited leg movement for sprinting away from trouble, it brings cheerful holiday spirit without overheating survivors trapped inside stuffy basement havens.",
    },
    ["santa_gloves"] = {
        zh = "一双带有白色蓬松毛圈袖口的鲜红色圣诞手套。柔软的绒布能防止冰冷金属枪柄冻伤手掌，亮眼的红色虽然不利于伪装，但能确保你的同伴在黑夜混乱交火中一眼看清战术手势。",
        en = "A pair of bright red fabric gloves adorned with puffy white wrist cuffs. Keeping numb fingers agile during freezing winter watches, their vibrant color helps squadmates clearly spot hand signals during chaotic dusk skirmishes.",
    },
    ["santa_hat"] = {
        zh = "顶端缀有一颗毛绒白球的经典鲜红圣诞老人锥形帽。虽然没有任何防弹防护，但柔软的绒毛能妥善捂热冻僵的双耳，在冰天雪地的末日残垣中为所有人带来一丝苦涩而温暖的笑容。",
        en = "The iconic pointed red cap tipped with a fuzzy white pompom. Lacking any ballistic protection against wasteland perils, its soft fabric nevertheless covers cold ears while reminding scarred survivors of happier forgotten Decembers.",
    },
    ["santa_jacket"] = {
        zh = "带有洁白人造毛皮滚边的鲜红色大号圣诞老人绒布夹克。虽然防弹防刺性能约等于零，但穿上它手持霰弹枪在丧尸小镇扫荡物资，有一种极其狂野荒诞的节日恶趣味。",
        en = "A plush crimson winter coat trimmed with white faux fur. Offering zero ballistic defense, clearing infested shopping malls with a combat shotgun while dressed as Santa brings hilarious, dark holiday joy.",
    },
    ["santa_jacket_short"] = {
        zh = "剪短了下摆的改良版轻便红色圣诞夹克。去掉了拖沓的衣角方便奔跑拔枪，醒目的鲜红色彩在白雪皑皑的废墟里格外显眼，堪称荒野狙击手绝不会错过的活靶子服装。",
        en = "A cropped version of the iconic red holiday jacket designed for mobility. Freeing belt holsters for quick draws, its glaring red hue nonetheless makes wearers brilliant targets across snowdrifts.",
    },
    ["santa_pants"] = {
        zh = "带有松紧带腰头的宽松鲜红色圣诞长裤。肥大的裤管方便内穿保暖秋裤，柔软的面料在潜行移动时悄无声息，只可惜过于张扬的红色在枯黄荒原上宛如一面招引丧尸的活动旗帜。",
        en = "Loose-fitting red trousers outfitted with an elastic waistband and fluffy white ankle cuffs. Accommodating thick thermal undergarments beneath, their loud hue unfortunately acts like an enraged bull cape for roaming feral beasts.",
    },
    ["santa_shorts"] = {
        zh = "裁剪至膝盖上方的红色圣诞主题短裤。适合南半球酷热圣诞节或地下暖气失控避难所的奇特装束，穿着它在废墟中翻爬虽然容易擦伤膝盖，但至少能保住下半身的清爽透气。",
        en = "Lightweight red holiday shorts edged with synthetic white trim. Geared toward sweltering southern hemisphere Christmases, wearing them through brambly ruins invites scratched knees but grants unmatched ventilation during blazing summer heat.",
    },
    ["sapphire"] = {
        zh = "切割精湛、内部毫无瑕疵的天然深蓝色蓝宝石原石。湛蓝如深海的冷艳光泽在火把下流转，虽不能充当子弹也不能填饱肚子，但在大型废土商队眼中依然是坚挺的稀有硬通货。",
        en = "A masterfully faceted natural sapphire gleaming with rich royal blue clarity. Unusable as ammunition or emergency rations, this dazzling gemstone remains intensely coveted by wealthy wandering caravan bosses seeking untainted wealth.",
    },
    ["sapphire_dental_grill"] = {
        zh = "镶嵌着细小深蓝宝石的白金牙套饰品。原本属于旧时代说唱歌手或浮夸富豪的牙齿炫耀物，扣在嘴里虽然咯牙且妨碍咬碎硬饼干，但在废土掠夺者眼里绝对是令人敬畏的凶悍排场。",
        en = "A flashy dental grill studded with micro-set polished sapphires. Awkwardly clipping over teeth and impeding hardtack chewing, this ostentatious pre-cataclysm status symbol terrifies superstitious raiders with gleaming, diamond-hard smiles.",
    },
    ["sapphire_gold_bracelet"] = {
        zh = "纯金链条上串连着数颗切割蓝宝石的精致女式手镯。冰凉温润的宝石与黄金的光泽相映成趣，虽然在摸爬滚打时极易刮花断裂，但送给避难所中的心上人足以抵得上一百句甜言蜜语。",
        en = "A delicate gold bracelet linking brilliant blue sapphires along an ornate chain. While dangerously fragile during rough scavenger scuffles, gifting this gleaming heirloom conveys genuine affection more effectively than a crate of MREs.",
    },
    ["sapphire_gold_cufflinks"] = {
        zh = "镶嵌深蓝宝石的纯金法式衬衫袖扣一对。小巧精致且工艺考究，在废土人均披着破布麻袋的当下显得格格不入，但如果你想在谈判桌上震慑对手，扣上它能瞬间彰显上位者的威严。",
        en = "A matching pair of polished gold cufflinks each securing a cushion-cut sapphire. Looking absurdly out of place against dirt-stained scavenger flannels, sporting them during faction summits projects aristocratic pre-cataclysm authority.",
    },
    ["sapphire_gold_earring"] = {
        zh = "金丝环绕着璀璨蓝宝石的一对奢华吊坠耳环。随着走动在耳畔轻轻摇曳折射出湛蓝微光，虽然在近身肉搏中容易被敌人一把扯烂耳垂，但戴上它能让你彻底找回当人的体面与尊严。",
        en = "A lavish pair of dangle earrings featuring brilliant sapphires suspended from pure gold loops. Risking catastrophic earlobe tearing during desperate scuffles, they nonetheless restore unmatched glamour and human dignity to grim wasteland evenings.",
    },
    ["sapphire_gold_pendant_necklace"] = {
        zh = "由细腻金链悬挂着一颗硕大水滴形蓝宝石的典雅项链。蓝宝石宛如深邃星空般纯净无瑕，紧贴在胸口能感受到黄金的温润与宝石的清凉，是废土乱世中不可多得的传世艺术珍宝。",
        en = "An exquisite gold pendant chain showcasing a breathtaking teardrop sapphire. Resting coolly against scarred collarbones, this mastercrafted necklace represents an enduring relic of timeless civilized artistry amid endless ruins.",
    },
    ["sapphire_gold_ring"] = {
        zh = "以厚实纯金戒托紧密镶嵌着椭圆蓝宝石的昂贵指环。沉甸甸的黄金质感与深邃的宝石蓝光芒互相辉映，在商贸据点不仅能换来整箱高阶子弹，必要时还能充当防身的金属指虎一击制敌。",
        en = "A substantial gold ring crowned with a rich oval-cut sapphire. Heavy enough to command high prices in trading strongholds, the solid precious metal mount doubles as a surprisingly painful improvised knuckle-duster in tight brawls.",
    },
    ["sapphire_gold_tiara"] = {
        zh = "镶满群星般碎钻与硕大主蓝宝石的黄金王冠。华丽夺目的皇家造型戴在沾满机油的发丝上透着一股末世女王般的荒诞威严，足以让手持锈铁棍的手下们肃然起敬、俯首称臣。",
        en = "A magnificent golden tiara set with starry clusters of glittering sapphires. Perched upon grime-streaked survivor hair, this royal headpiece commands fierce apocalyptic reverence from scrap-armored warband followers.",
    },
    ["sapphire_platinum_bracelet"] = {
        zh = "由高纯度铂金精雕细琢、并排嵌满湛蓝宝石的高级奢华手镯。冰冷的铂金永不生锈褪色，在放射性尘埃与酸雨洗礼下依然光洁如新，是经得起末日浩劫考验的永恒信物。",
        en = "A heavy platinum bracelet channel-set with glowing royal blue sapphires. Immune to rust, acidic rain, and radioactive fallout, this incorruptible luxury relic stands completely untarnished by the cruel march of time.",
    },
    ["sapphire_platinum_cufflinks"] = {
        zh = "以耐磨铂金底座托举顶级蓝宝石的考究袖扣。金属坚实且重量十足，在大灾变前曾出入跨国财阀的顶级峰会，如今静静躺在废墟抽屉里，等待懂得欣赏它的新主人将它重见天日。",
        en = "A set of immaculate platinum cufflinks framing deep indigo sapphires. Originally fastening French cuffs in boardroom skyscrapers, they now lie waiting within desk drawers for cultured wanderers seeking forgotten luxury.",
    },
    ["sapphire_platinum_earring"] = {
        zh = "抗腐蚀铂金丝爪紧扣璀璨蓝宝石的昂贵耳环。无论是在阴暗潮湿的地底防空洞还是在酸雾弥漫的沼泽地带，它都能保持永不氧化的纯净光辉，点亮佩戴者坚毅的面庞。",
        en = "Dazzling sapphire earrings mounted upon hypoallergenic platinum studs. Enduring humid subterranean vaults and toxic chemical fogs without a speck of tarnish, they sparkle defiantly through the gloomy apocalyptic twilight.",
    },
    ["sapphire_platinum_pendant_necklace"] = {
        zh = "悬挂于坚韧铂金细链上的深邃海蓝宝石吊坠。铂金的银白高冷完美衬托出蓝宝石的深远冷艳，贴近跳动的心脏宛如一面护身符，提醒幸存者在残酷荒原中永远坚守理智与希望。",
        en = "A magnificent deep ocean-blue sapphire suspended from a durable platinum necklace. The cool luster of untarnished metal accentuates the gem's hypnotic depths, serving as a beacon of sanity amidst endless devastation.",
    },
    ["sapphire_platinum_ring"] = {
        zh = "质地极为致密的铂金戒身环抱着一颗深蓝宝石的奢华戒指。耐磨防刮且永不损耗，即便戴着它挥舞铁镐敲碎砖石也不会变形，是废土贵族与军阀头目彰显永恒权势的终极首饰。",
        en = "An exceptionally dense platinum ring clutching a faceted blue sapphire in four sturdy prongs. Resisting scratches and deformation even during rough labor, it signifies unyielding survival dominance to all who gaze upon it.",
    },
    ["sapphire_platinum_tiara"] = {
        zh = "由白金铸造王冠骨架、通体点缀着无数蓝宝石的绝世珍品王冠。戴在头上有着令人眩晕的沉重分量，冷冽的白金与幽蓝宝石交相辉映，是只有统治整个定居点的领袖才配享有的无上荣耀。",
        en = "A breathtaking platinum tiara shimmering with rows of brilliant cut sapphires. Imposingly heavy upon the brow, its icy brilliance radiates untouchable sovereign glory suited only for warlords governing entire regional settlements.",
    },
    ["sapphire_silver_bracelet"] = {
        zh = "由 925 纯银精细编织、中央嵌有一颗深邃蓝宝石的典雅手镯。银质虽然会随时间产生一层复古的深色氧化膜，但微泛蓝光的宝石依然璀璨，在夜间篝火旁展现出温婉内敛的迷人魅力。",
        en = "A delicate sterling silver bracelet mounting a polished sapphire centerpiece. Though slowly tarnishing in humid bunker air, the deep indigo jewel continues to flash mesmerizing sparks beside flickering campfire embers.",
    },
    ["sapphire_silver_cufflinks"] = {
        zh = "纯银铸造底托配以深蓝色蓝宝石的绅士袖扣。虽然容易被废土酸雾熏黑表面，但只需用粗布和牙膏轻轻擦拭便能重焕光彩，是废土谈判官在维持体面外表时最易入手的珠宝配饰。",
        en = "Handsome sterling silver cufflinks clamping faceted blue sapphires. Readily polished back to high luster with a pinch of wood ash and cloth, they offer accessible gentility for sharp-dressing wasteland diplomats.",
    },
    ["sapphire_silver_earring"] = {
        zh = "以纯银丝线缠绕蓝宝石的一对摇曳耳环。银色与蓝色的搭配清新脱俗且轻盈便携，随手放进贴身口袋几乎不占负重，是前往游商集市换取食物与医疗物资的极佳保值交换物。",
        en = "A pair of swaying sterling silver earrings suspending sparkling sapphires. Lightweight and compact enough to conceal inside a boot lining, they serve as excellent lightweight trade currency during merchant enclave rendezvous.",
    },
    ["sapphire_silver_pendant_necklace"] = {
        zh = "带有复古雕花银托的蓝宝石吊坠项链。精细的银饰花纹勾勒出昔日工匠的非凡造诣，挂在脖颈上不仅美观大方，在废土黑市上更是连贪婪的雇佣兵也会心动不已的高保值抵押物。",
        en = "A vintage sterling silver pendant necklace framing an azure sapphire within filigree metalwork. Highlighting master jewelry craftsmanship from days gone by, it serves as high-value collateral acceptable to ruthless mercenaries.",
    },
    ["sapphire_silver_ring"] = {
        zh = "925 纯银戒托镶嵌单颗切割蓝宝石的简约戒指。相比昂贵的黄金与铂金更加低调实用，银质的抗菌特性在末日也为人称道，是一枚兼具朴素美感与硬通货交换价值的可靠首饰。",
        en = "A classic sterling silver ring crowned with a single faceted sapphire. More understated than flashy gold pieces, its subtle elegance and inherent metal value make it an ideal universal trade token across frontier towns.",
    },
    ["sapphire_silver_tiara"] = {
        zh = "由纯银细丝弯折编织成繁复花纹、镶满晶莹蓝宝石的优雅小王冠。虽然比铂金版本轻巧许多，但戴在发间依然光彩照人，能让破衣烂衫的流浪女孩瞬间化身为废墟童话里的森林公主。",
        en = "An intricately woven sterling silver tiara studded with sparkling blue sapphires. Significantly lighter than royal platinum crowns, resting this lovely adornment on your brow transforms ragged scavengers into regal post-apocalyptic royalty.",
    },
    ["sapra"] = {
        zh = "流亡族工匠利用异星合金打造的萨普拉重型榴弹发射器。粗犷的机械外表下流淌着神秘的液压反馈动力，能以惊人的初速将大口径高爆榴弹倾泻至尸群核心，将整条街道夷为焦土。",
        en = "A heavy Exodii grenade launcher forged from strange, unearthly alloys. Driven by clanking hydraulic action, it hurls heavy high-explosive ordnance with devastating velocity, erasing encroaching mutant throngs in thunderous, scorching fireballs.",
    },
    ["sarcophagus_access_code"] = {
        zh = "写在一张耐辐射防静电磁卡上的危险品石棺开启密码。这串复杂的十六进制代码掌握着封闭地下高危生化与放射性反应堆的最后钥匙，一旦输入错误，引发的自动净化程序将毁灭一切。",
        en = "A laminated rad-resistant card recording an encrypted hexadecimal access sequence. Unlocking heavily shielded underground hazardous storage sarcophagi, entering this code grants access to catastrophic bio-weapons or prompts immediate facility incinerations.",
    },
    ["sarma"] = {
        zh = "用酸腌葡萄叶或白菜叶紧紧包裹碎肉与大米焖煮而成的传统萨尔玛叶卷。肉汁与谷物的香浓被牢牢锁在酸香开胃的菜叶中，一口一个软糯咸鲜，是荒野流浪中不可多得的治愈系热食。",
        en = "Savory minced meat and seasoned rice tightly rolled inside tender fermented grape or cabbage leaves. Steamed to succulent perfection, each savory roll releases rich juices that satisfy hollow stomachs after freezing woodland treks.",
    },
    ["sashimi"] = {
        zh = "用锋利柳刃刀将刚捕捞上来的淡水白鱼切出的晶莹生鱼片。肉质鲜甜弹牙、入口即化，在核辐射与生化病毒泛滥的废土上大啖生鱼片，是一场赌上寄生虫感染的顶级味觉盛宴。",
        en = "Thinly sliced raw fish fillets carved cleanly with a razor-sharp blade. Sweet and delicate on the tongue, dining on raw wasteland catch remains a daring gamble against freshwater flukes.",
    },
    ["sassafras_root"] = {
        zh = "从野外黄樟树根部掘出的芳香根皮。切开后散发着浓郁迷人的天然沙士汽水清香，将其投入滚水中慢炖，便能煮出一锅风味独特、发汗驱寒并舒缓肌肉酸痛的古法药草热饮。",
        en = "A freshly harvested taproot cut from wild sassafras bushes. Emitting that distinct, nostalgic root beer fragrance when scraped, simmering it in water yields a comforting traditional herbal tonic that soothes aching joints.",
    },
    ["satellitemap"] = {
        zh = "高分辨率军用轨道侦察卫星拍摄的地表全景俯视图。巨幅地图上精准标出了周围城镇的公路网络、大型工业区与地下掩体入口，是幸存者规划远征路线与避开辐射死地的无价指南针。",
        en = "A high-resolution satellite reconnaissance printout depicting regional terrain before orbital blackouts. Marking highway arteries, industrial complexes, and subterranean bunker entrances, it offers peerless navigational foresight for ambitious expedition planners.",
    },
    ["sauce_pesto"] = {
        zh = "用新鲜罗勒叶、松子、大蒜、橄榄油与硬奶酪在石臼中研磨而成的香蒜沙司青酱。翠绿诱人的酱体散发着霸道扑鼻的草本清香，拌入粗麦面条能让粗茶淡饭瞬间跃升为顶级意式盛宴。",
        en = "Vibrant green pesto pounded from fresh basil, pine nuts, garlic, olive oil, and hard cheese. Intensely herbaceous and garlicky, a dollop of this fragrant sauce turns plain boiled pasta into an exquisite Mediterranean feast.",
    },
    ["sauce_red"] = {
        zh = "精选熟透番茄搭配香草慢火煨炖而成的纯正红番茄酱。质地浓稠红亮且酸甜平衡，无论是涂抹在自制披萨面饼上，还是作为烤肉蘸酱，都是废土厨房中安抚味蕾的万能红宝石基底。",
        en = "Thick, slow-simmered tomato sauce enriched with aromatic herbs and olive oil. Boasting bright acidity and deep savory richness, it serves as the essential base for baking makeshift pizzas or elevating tough wild game.",
    },
    ["sauerkraut"] = {
        zh = "经乳酸菌充分自然发酵而成的爽脆德式酸菜。丝丝分明且酸香浓烈，富含有益肠道菌群与宝贵的维生素 C，搭配油腻的烤肉不仅完美解腻，还能彻底断绝坏血病对幸存者的致命威胁。",
        en = "Crisp, finely shredded cabbage fermented naturally by lactic acid bacteria. Packing sharp sour punch and abundant vitamin C, it cuts through greasy campfire meats while serving as an indispensable shield against catastrophic scurvy.",
    },
    ["sauerkraut_ferment"] = {
        zh = "装在密封玻璃罐中正在发酵的白菜丝。罐壁上凝结着细密的气泡，在适宜的室温下需要耐心等待数周才能酿出正宗风味，提醒焦躁的幸存者美好事物往往需要与漫长时间为伴。",
        en = "A sealed jar packed with salted cabbage undergoing active microbial fermentation. Tiny gas bubbles rising through brine signify beneficial bacteria at work, teaching restless wasteland survivors that good food demands patient, uninterrupted time.",
    },
    ["sauerkraut_ferment_active"] = {
        zh = "发酵进入白热化阶段的德式酸菜罐。罐内持续咕嘟咕嘟冒出微小的二氧化碳气泡，散发出略带刺激性的发酵酸气，必须定期拧松盖子释放气压，否则可能会在架子上发生剧烈爆裂。",
        en = "A jar of fermenting sauerkraut churning with vigorous bubble activity. Releasing pungent sour vapors as carbon dioxide builds, it requires occasional burping to vent internal pressure and prevent dramatic pantry glass explosions.",
    },
    ["sauerkraut_onions"] = {
        zh = "与切碎洋葱在动物板油中翻炒至焦香金黄的熟德式酸菜。酸菜的尖锐酸涩被洋葱的焦糖甘甜完美中和，温热多汁且香气扑鼻，是寒冬夜里就着烤肉大快朵颐的终极暖胃配菜。",
        en = "Tangy fermented sauerkraut pan-fried alongside caramelized onions in sizzling animal fat. The savory sweetness of browned onions softens tart vinegar sharpness, creating an intensely comforting winter skillet accompaniment for freshly roasted meats.",
    },
    ["sausage"] = {
        zh = "经过硬木果木冷烟熏制而成的紧致风干香肠。暗红色的外皮紧绷有嚼劲，浓缩了肉类的纯粹脂肪与蛋白质，便于长期携带且无需烹饪即可直接切片食用，是行军背包里的黄金干粮。",
        en = "Firm cured sausage slow-smoked over aromatic hardwood embers. Tightly packed with dense meat proteins and shelf-stable fats, this savory stick requires zero cooking and endures endless miles within grueling marching packs.",
    },
    ["sausage_casings"] = {
        zh = "经过刮洗、盐渍消毒处理的天然动物肠衣。薄如蝉翼却韧性十足，能紧紧包裹住搅拌均匀的肉馅与香料，在烟熏或水煮时防止内部汁水溢出，是废土灌肠手艺人视若珍宝的基础包材。",
        en = "Cleaned and salted natural animal intestines prepared for meat stuffing. Surprisingly resilient despite paper-thin translucence, they seal minced meats and herbs firmly, preventing precious savory juices from escaping over smoking coals.",
    },
    ["sausage_casings_artificial"] = {
        zh = "由胶原蛋白或纤维素合成的高韧性人造香肠肠衣。口径极其均匀且不易戳破爆膛，免去了繁重恶心的刮洗猪肠劳作，让大批量加工耐储存灌肠干粮的工作变得轻松高效。",
        en = "Manufactured collagen or cellulose casings engineered with uniform diameter and exceptional tensile strength. Spared the grim chore of cleaning messy animal entrails, survivors can rapidly pack massive batches of uniform travel sausages.",
    },
    ["sausage_cooked"] = {
        zh = "在炭火上烤得外皮焦脆爆汁的美味熟香肠。咬破肠衣的瞬间肉汁与香料在舌尖四溅，带来浓郁扎实的油脂香气与饱腹快感，是抚慰疲惫流浪者肠胃与灵魂的硬派温热盛宴。",
        en = "A savory sausage link cooked over sizzling campfire embers until the casing blisters. Snapping with every bite to release bursting seasoned juices, it delivers rich fats and deep satisfaction to road-weary wanderers.",
    },
    ["sausage_raw"] = {
        zh = "刚用新鲜碎肉、油脂与香辛料灌入肠衣制成的生香肠。表面湿润柔软，充满了生鲜肉类的诱人光泽，必须尽快挂上烟熏架或下锅煎熟，否则在温暖天气里极易成为细菌滋生的温床。",
        en = "Freshly stuffed raw sausage packed with ground meats, diced fat, and coarse spices. Plump and moist, this perishable protein link must be smoked or cooked promptly before ambient wasteland heat ruins the batch.",
    },
    ["sausage_wasteland"] = {
        zh = "用各种来源可疑的废土变异野味碎肉灌制并烤熟的硬汉香肠。虽然肉质纤维粗硬且带着一股难以名状的沼泽土腥味，但扎实的蛋白质与烈性调料足以让你在严寒夜晚熬过饥肠辘辘。",
        en = "Cooked survival sausage concocted from dubious wasteland mystery meats and heavy seasoning. Though stringy and carrying an unmistakable gamey swamp funk, its dense protein and searing spices keep shivering scouts fueled through freezing nights.",
    },
    ["sausage_wasteland_raw"] = {
        zh = "把来历不明的杂碎变异野肉绞碎后手工灌出的生废土香肠。散发着野性十足的怪异酸气，必须依赖大火彻底炙烤或重度盐熏才能安心食用，否则肠胃炎将比丧尸更快要了你的命。",
        en = "Uncooked sausage links stuffed with butchered mutant remnants and forage herbs. Exuding an intimidating pungent musk, they demand scorching fire or aggressive brine cure unless you fancy battling crippling gastrointestinal cramps amidst mutant hordes.",
    },
    ["sausagegravy"] = {
        zh = "以煎香肠析出的浓郁肉油、面粉与牛奶慢熬而成的浓稠香肠肉汁。热气腾腾且奶香四溢，淋在硬邦邦的面包块或烤土豆上，便是一顿能瞬间融化所有疲惫与寒意的传统南方暖胃美食。",
        en = "Thick, comforting country gravy simmered from rendered sausage drippings, flour, and milk. Ladled steaming hot over hardtack or boiled potatoes, it provides an avalanche of creamy calories that banishes cold drafts instantly.",
    },
    ["savage112"] = {
        zh = "配有重型比赛级浮置枪管的萨维奇 112 旋转后拉枪机单发靶射步枪。虽然每次射击都需要手动装填单发弹药，但极度刚性的机匣与精准的微偏调校能保证千米之外弹着点分毫不差。",
        en = "A precision single-shot Savage 112 target bolt-action rifle equipped with a heavy bull barrel. Requiring deliberate hand-feeding for each cartridge, its exceptional chassis rigidity and match accuracy punch tight groups across distant horizons.",
    },
    ["savage_rascal"] = {
        zh = "专为青少年启蒙射击设计的萨维奇 .22 LR 超轻单发小型步枪。重量轻巧得如同儿童玩具，结构极为简单可靠，虽无法用来阻挡狂暴的变异巨熊，但打松鼠与野兔几乎百发百中。",
        en = "An ultra-lightweight Savage Rascal single-shot .22 LR rimfire rifle. Resembling a modest youth training implement, its dependable simplicity and lack of recoil make it an ideal featherweight tool for harvesting wild rabbits.",
    },
    ["saw"] = {
        zh = "配有坚固木质手柄与锋利交错齿刃的传统木工手板锯。无论是在森林中锯断原木构筑防御木栅栏，还是在废墟中切割废弃家具当柴火，都是幸存者营地建设中无可替代的基础工具。",
        en = "A traditional hand saw featuring sharp crosscut steel teeth set into a solid handle. Indispensable for felling timber to erect defensive palisades or sectioning abandoned furniture for winter warmth, it anchors every builder's pack.",
    },
    ["saw_bronze"] = {
        zh = "以高硬度锡青铜古法冶炼铸造并手工开齿的坚固木工锯。虽然金属锋利度不及高碳钢刃且锯切较慢，但其绝不生锈腐蚀的优良特性让它成为后末日时代永不磨灭的匠人传家宝。",
        en = "A hand-cast bronze crosscut saw filed with durable teeth from ancient metallurgical recipes. While slower cutting than modern high-carbon steel, its absolute immunity to rust ensures it will outlive centuries of post-collapse dampness.",
    },
    ["saxophone"] = {
        zh = "由抛光黄铜精细打造、带有复杂按键连杆机构的中音萨克斯管。在死寂破败的废墟瓦砾间吹响一段悠扬沙哑的爵士旋律，不仅能抚慰战栗的灵魂，也可能招引来整条街的行尸走肉。",
        en = "An ornate brass alto saxophone intricate with polished keys and lacquer. Blown amidst hollow concrete ruins, its sultry jazz tones echo hauntingly across empty streets, soothing grief-stricken survivors while inadvertently alerting nearby roaming horrors.",
    },
    ["scabbard"] = {
        zh = "专为单手长剑或砍刀打造并配有大腿固定绑带的战术硬皮剑鞘。紧贴腿侧能在奔跑与翻越障碍物时防止刀剑剧烈晃动，顺畅的拔刀内衬能保证在遭遇袭击时实现瞬时拔刃反击。",
        en = "A rigid leather scabbard fitted with secure thigh retention straps. Fastened securely to the leg to eliminate awkward bouncing while sprinting, its smooth waxed interior allows lightning-fast blade draws when mutated ambushes erupt.",
    },
    ["scalpel"] = {
        zh = "以高品质不锈钢锻造、刀刃锋利如剃刀的医用精细手术刀。极度纤薄的刀尖能在微米级操作中切开脓肿或剔除嵌入体内的弹片，在缺乏战地医生的废土，它也是切开绝望的最后手术器械。",
        en = "A precision medical scalpel forged from high-grade surgical stainless steel. Razor-sharp and perfectly balanced, it excels at delicate field surgeries, digging out buried shrapnel or making clean, lethal cuts in desperate close-quarters self-defense.",
    },
    ["scar_16s"] = {
        zh = "民用版 FN SCAR-L 半自动突击步枪。发射通用的 5.56 毫米北约步枪弹，短行程导气活塞系统运行平稳可靠，优秀的折叠枪托与皮卡汀尼导轨让它成为废土游侠最向往的顶尖自卫利器。",
        en = "The civilian semi-automatic version of the FN SCAR-L chambered in 5.56x45mm NATO. Featuring smooth short-stroke piston cycling, monolithic top rails, and folding ergonomics, it represents a gold-standard survival rifle coveted by elite scouts.",
    },
    ["scar_17s"] = {
        zh = "民用版 FN SCAR-H 重型半自动战斗步枪。发射威力强劲的 7.62 毫米全威力步枪弹，虽然单发后坐力凶猛，但在远距离对峙中能轻而易举贯穿轻装甲防弹衣与砖石掩体，威慑力十足。",
        en = "A civilian semi-automatic FN SCAR-H firing formidable 7.62x51mm rounds. Packing massive punch into an ergonomic polymer chassis, it punches clean holes through armored raiders and brick barriers across distant defensive perimeters.",
    },
    ["scar_h"] = {
        zh = "军用特种作战部队专用的全自动 FN SCAR-H 重型战斗步枪。兼具致命的 7.62 毫米穿甲打击力与可折叠枪托设计，无论是中远距离精准压制还是短点射撕裂变异巨兽，都是无可争议的步兵凶器。",
        en = "The military select-fire FN SCAR-H battle rifle developed for special forces operators. Delivering devastating 7.62mm kinetic trauma with full-auto capability, it dominates engagements whether picking off distant sentries or pulverizing charging brute mutants.",
    },
    ["scar_h_mk20"] = {
        zh = "基于 SCAR-H 平台深度特化的 Mk 20 狙击手支援高精度步枪。加长加厚的比赛级浮置枪管与微调狙击枪托，赋予其在恶劣环境下连发狙杀千米外高价值目标的恐怖统治力。",
        en = "The Mk 20 Sniper Support Rifle evolved from the SCAR-H chassis. Outfitted with an extended receiver, heavy match-grade barrel, and precision-adjustable stock, it delivers rapid semi-automatic sniper fire across immense desolate kill zones.",
    },
    ["scar_l"] = {
        zh = "特种作战突击步枪标准配置的军规级 FN SCAR-L。发射 5.56 毫米弹药，具有出色的模块化与抗风沙污泥耐受力，轻便的聚合物下机匣能在高强度全自动扫射中保持从容不迫的控枪精度。",
        en = "A military select-fire FN SCAR-L assault rifle chambered in 5.56mm NATO. Renowned for modular field stripping and exceptional fouling tolerance, its balanced recoil impulse allows controlled automatic bursts during chaotic breach engagements.",
    },
    ["scarf"] = {
        zh = "由纯羊毛紧密编织而成的柔软保暖围巾。层层缠绕在脖颈上不仅能彻底阻断灌入衣领的刺骨寒风，在风沙漫天的废墟中拉起遮住口鼻，还能当成简易的防风尘口罩使用。",
        en = "A cozy scarf knitted tightly from natural sheep wool. Wrapping generously around chilled necks, it stops icy winter gales from invading collars while pulling up over noses to filter swirling road dust.",
    },
    ["scarf_faux_fur"] = {
        zh = "以保暖人造化纤毛皮缝制而成的毛绒围巾。触感蓬松舒适且绝不怕水霉变，裹在脖子上能迅速蓄积体温，给在冰雨与寒风中搜寻物资的废土拾荒者带来难能可贵的暖意。",
        en = "A plush neck scarf crafted from synthetic faux-fur fibers. Resisting rot and moisture much better than untreated pelts, it traps radiant body warmth reliably to keep shivering scavengers functional in damp, biting sleet.",
    },
    ["scarf_faux_fur_headwrap"] = {
        zh = "将人造毛皮围巾紧密缠绕在头部充当简易毛皮风帽的保暖包头。不仅能妥善捂热双耳与头顶，毛茸茸的外观还能在雪地潜伏中打散头部轮廓，兼顾抗冻保暖与伪装遮蔽。",
        en = "A synthetic fur scarf wrapped tightly around the skull like an improvised winter hood. Shielding sensitive ears against frostbite, its shaggy outline breaks up human silhouettes during tense winter observation vigils.",
    },
    ["scarf_faux_fur_long"] = {
        zh = "长度超过两米的加长款人造毛皮围巾。超长的尺寸能从容地在颈部缠绕三圈并垂至腰际，犹如一条毛茸茸的小毛毯随身披戴，在没有供暖的废弃公寓里是御寒的贴身利器。",
        en = "An extra-long faux-fur scarf extending well past standard lengths. Wrapping thrice around the neck with generous tails left over, it acts like a wearable plush blanket during freezing nights inside derelict high-rise apartments.",
    },
    ["scarf_faux_fur_long_headwrap"] = {
        zh = "利用加长人造毛皮围巾层层包裹头部与口鼻的严寒风雪包裹模式。只露出一双警惕的双眼，厚实的人造绒毛能有效阻挡暴风雪中如刀割般的冰晶碎屑，守护脆弱的面部皮肤。",
        en = "An extra-long synthetic fur scarf swathed meticulously around the face and head. Leaving only eyes exposed to the elements, its dense synthetic fleece shields delicate skin from razor-sharp swirling blizzard shards.",
    },
    ["scarf_faux_fur_long_loose"] = {
        zh = "宽松随意搭在双肩上的加长人造毛皮围巾。松垮的披挂方式不仅通风透气不显闷热，随着奔跑在身后飞扬的毛茸茸下摆，还颇有一股废土荒原废墟流浪贵族的狂放气派。",
        en = "An extra-long faux-fur scarf draped loosely across shoulders. Offering airy ventilation during brisk marches without overheating the neck, the flowing ends flutter dramatically behind you like tattered aristocratic regal banners.",
    },
    ["scarf_faux_fur_loose"] = {
        zh = "松散围在领口四周的人造毛皮围巾。没有紧紧勒住脖子，既提供了基础的防风保暖效果，又便于在遭遇突发威胁时瞬间解脱甩掉，绝不会被身后近身的丧尸一把揪住勒窒息。",
        en = "A synthetic fur scarf loosely looped around the collar. Providing gentle draft protection without choking the neck, it can be ripped free instantly if grabbed from behind by clutching ghoulish claws.",
    },
    ["scarf_fur"] = {
        zh = "由野生动物真实毛皮鞣制缝合而成的顶级保暖毛皮围巾。浓密顺滑的天然针毛与绒毛能将体温牢牢锁死在领口，散发着质朴原始的荒野气息，是抵御极寒冻土的王者装束。",
        en = "A premium winter scarf fashioned from tanned natural pelt. Dense guard hairs and soft underfur lock escaping body heat around the throat, exuding rugged wilderness authority while defeating severe arctic freezes.",
    },
    ["scarf_fur_headwrap"] = {
        zh = "将厚实真毛皮围巾精细盘裹在头顶构成的真皮毛帽护头。密实的野兽皮毛将暴风雪彻底隔绝在外，在零下几十度的荒野林地里，能保护额头与耳朵免受冻疮与组织坏死的威胁。",
        en = "A thick natural pelt scarf coiled snugly around the crown and temples. Impermeable to howling gale-force blizzards, it guards ears and foreheads against crippling frostbite during sub-zero wilderness reconnaissance.",
    },
    ["scarf_fur_long"] = {
        zh = "用整条上等动物皮毛缝接而成的加长款真毛皮围巾。厚重而奢华，尾端带着随风摆动的柔软毛梢，披在身上犹如一件温暖的小披肩，展现着荒原顶级猎手无可争议的捕猎荣耀。",
        en = "An extra-long luxury scarf pieced together from prime animal furs. Substantial and warm as a mantle, its sweeping fluffy length proclaims the hunting prowess of wilderness stalkers capable of harvesting magnificent beasts.",
    },
    ["scarf_fur_long_headwrap"] = {
        zh = "以整条加长真毛皮围巾将整个头部与面颊裹得密不透风的极地护头缠法。天然毛皮散发的微弱动物油脂气味在呼出的热气中回荡，为幸存者构筑起一道抵抗极端寒潮的生命护盾。",
        en = "An expansive natural fur scarf swaddled completely around the head and cheeks. The faint, earthy scent of tanned hide mingles with warm breath, sealing facial extremities within an impenetrable fortress of primal warmth.",
    },
    ["scarf_fur_long_loose"] = {
        zh = "将加长真毛皮围巾随意搭在胸前与身后的松弛披挂状态。既不会在剧烈砍杀或劳作时过度积汗，蓬松奢华的兽毛又在风中微微颤动，尽显废土旷野领袖从容不迫的霸者风范。",
        en = "An extra-long natural fur scarf worn unknotted across the torso. Preventing excessive sweat buildup during heavy labor, the swaying pelts convey untamed frontier majesty suited for respected clan elders.",
    },
    ["scarf_fur_loose"] = {
        zh = "松松垮垮搭在肩颈四周的天然毛皮围巾。蓬松的兽毛不仅不会让人感到喉咙受束缚，还能在疾行中带走多余的湿热，微风吹拂下毛梢轻轻摇曳，尽显废土猎人荒野游荡时的野性与洒脱。",
        en = "A natural pelt scarf worn loosely over shoulders. Allowing refreshing ventilation during rapid wilderness marches, its flowing animal furs flutter softly in post-apocalyptic breezes, conveying the untamed swagger of experienced frontier hunters.",
    },
    ["scarf_headwrap"] = {
        zh = "把厚羊毛围巾紧密缠绕在整个头部的防寒包头法。不仅将脆弱的双耳与后颈死死护在温暖的羊毛层内，还能在暴风雪天阻挡漫天狂风与冰晶，只留出一双警惕的双眼搜寻猎物。",
        en = "A thick wool scarf wound snugly around the skull and temples. Shielding vulnerable ears and neck against biting frostbite, it blocks howling blizzards while leaving keen eyes clear to scan desolate white horizons.",
    },
    ["scarf_long"] = {
        zh = "长度惊人的加长款粗针织纯羊毛围巾。绕着脖子缠上三圈后依然有长长的下摆垂到膝盖附近，犹如一件轻便随身的小披风，在寒风呼啸的废墟高楼巡逻时带来无微不至的温暖关怀。",
        en = "An extra-long knitted wool scarf stretching past normal dimensions. Coiling thrice around the neck with generous fringes dangling to the knees, it wraps weary scouts like a miniature blanket during drafty rooftop sentry duties.",
    },
    ["scarf_long_headwrap"] = {
        zh = "利用超长羊毛围巾将头部、面颊与下颌层层严密裹紧的极寒包裹模式。厚重的羊毛纤维将呼出的热气循环保留在面部周围，是深入冰封废弃军营或雪山勘探时不可或缺的防冻屏障。",
        en = "An extra-long wool scarf wrapped thoroughly around the face and cranium. Trapping warm breath within dense wool fibers, it creates a cozy micro-climate shielding explorers from crippling hypothermia in freezing abandoned mountain research labs.",
    },
    ["scarf_long_loose"] = {
        zh = "将超长羊毛围巾随意搭在肩头、任由长长下摆在身后飘扬的松散佩戴法。虽然在狂奔穿过荆棘灌木时极易被树枝挂住，但在定居点酒馆里绝对能为你赢得一众拾荒者的注目礼。",
        en = "An extra-long woolen scarf draped casually across shoulders. While recklessly prone to snagging on thorny brambles during dead sprints, its sweeping trailing tails grant undeniable dramatic flair inside smoky survivor trading taverns.",
    },
    ["scarf_loose"] = {
        zh = "松散系在胸前的普通羊毛围巾。既保留了基本的领口挡风性能，又不会在室内或剧烈劈砍战斗中造成闷热憋汗，若遭遇突发近身肉搏，还能单手瞬间扯下充当临时的绞索武器。",
        en = "A standard wool scarf draped loosely around collarbones. Providing basic draft deflection without trapping suffocating sweat during heavy melee, it can be ripped free in an instant to serve as an improvised strangling cord.",
    },
    ["scarh_makeshiftmag"] = {
        zh = "用废旧铁皮罐头和弹簧手工敲打拼凑出来的 SCAR-H 5发应急弹匣。做工粗糙且供弹阻力极大，虽然只能装五发沉重的 7.62 毫米子弹，但在弹匣匮乏的战场上依然能救你一命。",
        en = "A crude 5-round SCAR-H magazine hammered from food tins and salvaged springs. Clunky and prone to feeding hiccups, having five live 7.62mm rounds seated reliably in battery beats single-loading empty chambers under fire.",
    },
    ["scarhbigmag"] = {
        zh = "专为 SCAR-H 重型战斗步枪打造的 50 发双室加长聚合物弹鼓。重达数公斤的大弹鼓让整支步枪重心严重前倾，但其倾泻而出的持续全威力火力狂潮足以将任何尸潮彻底撕成肉泥。",
        en = "A massive 50-round twin-drum magazine engineered for the SCAR-H battle rifle. Throwing weapon balance drastically forward, the devastating sustained barrage of heavy 7.62mm lead shreds approaching horde waves into smoking crimson mist.",
    },
    ["scarhmag"] = {
        zh = "FN SCAR-H 步枪原厂标配的 20 发双排钢制弹匣。坚固耐磨且托弹簧力道强劲，能在极寒冰冻与泥浆污垢中稳定向枪膛推送大威力 7.62 毫米步枪弹，是精锐射手最信赖的供弹基石。",
        en = "A factory-standard 20-round steel magazine for the FN SCAR-H rifle. Renowned for rugged feed lips and stiff springs, it chambers full-power rifle cartridges flawlessly even through thick mud and freezing sleet.",
    },
    ["scarhmag_10"] = {
        zh = "容量缩减为 10 发的紧凑型 SCAR-H 步枪短弹匣。弹身极其短小且绝不凸出机匣下沿，非常适合卧姿精确狙击或伏卧在瓦砾堆中潜伏射击，极大降低了暴露身位的风险。",
        en = "A compact 10-round flush magazine manufactured for SCAR-H precision platforms. Barely protruding beneath receiver wells, it facilitates ultra-low prone sniper profiles among rubble piles without digging into dirt or snagging gravel.",
    },
    ["scarhmag_30rd"] = {
        zh = "经过战地改装加长底板的 SCAR-H 30 发扩容弹匣。比原厂弹匣足足多出十发全威力杀戮弹药，虽然插在枪身上显得格外修长突兀，但在面对冲锋的变异巨熊时多出的十发子弹就是生死之别。",
        en = "A modified 30-round extended magazine fabricated for the hungry SCAR-H. Adding ten extra heavy cartridges beyond factory limits, that extended firepower reserve makes the difference between surviving a mutant bear charge and becoming luncheon.",
    },
    ["schematics_antimateriel"] = {
        zh = "记录着全自动反器材重型防卫炮塔内部构造的军用工程蓝图。上面详细标明了高压伺服电机回路与大口径机炮装配公差，是军工工程师将避难所大门改造成死亡禁区的神级技术宝典。",
        en = "Technical blueprints detailing internal electromechanical layouts of an automated anti-materiel turret. Depicting high-torque servo linkages and heavy cannon tolerances, these schematics turn fortified shelter gates into impenetrable automated kill zones.",
    },
    ["schematics_dispatch"] = {
        zh = "记载着工业调度与巡逻派遣机器人组装线路的精密蓝图。通过破解其内置的自主导航与无线中继控制逻辑，有能力的机械师可以重新组装出不知疲倦的废墟巡逻看守机器人哨兵。",
        en = "Engineering schematics detailing circuitry and chassis assembly for robotic dispatch platforms. Mastering its autonomous navigation routing allows clever tinkerers to reconstruct tireless sentry drones that patrol wasteland encampment borders day and night.",
    },
    ["schematics_dispatch_military"] = {
        zh = "印有五角星军用绝密印章的高级武装派遣机器人装配图纸。上面详述了强化防弹外壳焊接工艺与武器挂架电路，是打造能与成群丧尸正面对抗的重甲机械猎犬的终极技术蓝图。",
        en = "Top-secret military diagrams outlining construction for armored combat dispatch units. Detailing reinforced plating welds and active weapon interfaces, it allows survivors to assemble terrifying robotic warhounds capable of tearing ghouls apart.",
    },
    ["schematics_grocerybot"] = {
        zh = "旧时代大型超级市场生鲜与杂货理货机器人的结构设计图。电路中包含精密的果蔬搬运吸盘与履带底盘，稍作改装便能将它变成替你在废弃超市中疯狂搜刮罐头的勤劳小推车助手。",
        en = "Commercial schematics illustrating the mechanisms of pre-cataclysm grocery replenishment automatons. Adapting its gentle shelf-stocking servos and tracks produces an obedient motorized cart that hauls scavenged canned goods home without protest.",
    },
    ["schematics_hazmatbot"] = {
        zh = "工业级化学泄漏与高危放射性废料清洁机器人的全套装配原理图。指导如何利用抗酸蚀聚合物外壳与高压洗消喷头，造出能替你深入辐射泄漏核心区打扫战场的机械替死鬼。",
        en = "Industrial schematics outlining assembly for hazardous material containment drones. Detailing corrosion-proof polymer hulls and decontamination sprayers, it enables survivors to construct expendable mechanical scavengers that brave lethal radiation hot-zones without flinching.",
    },
    ["schematics_nursebot"] = {
        zh = "民营医院全自动看护与注射医疗机器人的电子线路设计图。虽然其内置的手术刀连杆和止血钳让初见者毛骨悚然，但掌握了装配原理就能在营地里拥有一位永不颤抖的无菌机械主刀医助。",
        en = "Schematic diagrams detailing internal robotics of an automated hospital care unit. While gleaming mechanical scalpels and retractors appear terrifying, assembling one grants your bunker an unflinching, sterile mechanical surgical assistant.",
    },
    ["schematics_sciencebot"] = {
        zh = "绝密地下实验室多功能防御与生化样本回收无人机的蓝图。图纸上绘制着精密的能量护盾回路与防爆样本夹持臂，是破解各大研究所地下隔离区并保全珍贵样本的必备钥匙。",
        en = "Classified blueprints for high-security underground laboratory defense drones. Featuring energy shielding pathways and blast-resistant specimen graspers, it guides the construction of specialized machines suited for breaching hazard containment labs.",
    },
    ["schematics_searchlight"] = {
        zh = "军规级超高功率防空探照灯与自动转塔底座的电路图。指导如何将大功率氙气灯泡与聚光透镜组合，能把数公里外的夜空照得如同白昼，让潜伏在黑夜中的尸群彻底无所遁形。",
        en = "Military specifications detailing installation of high-candlepower motorized searchlights. Harmonizing massive xenon arc bulbs with optical condenser reflectors, building this rig turns pitch-black midnight sieges into glaring daylight spotlights.",
    },
    ["schematics_secubot"] = {
        zh = "执法机关通用武装巡逻安防无人机的核心装配图纸。图纸涵盖了防暴电击枪、橡胶子弹机枪接口与警报扬声器，是幸存者构筑自动化夜间警卫体系不可多得的工业蓝图。",
        en = "Comprehensive diagrams for automated civilian security patrols. Covering non-lethal taser mounts, beanbag launchers, and ear-piercing siren systems, it facilitates establishing automated perimeter sentries that ward off midnight prowlers.",
    },
    ["schematics_skitterbot"] = {
        zh = "多足快速掠行微型无人机的机械连杆与陀螺仪原理图。能够指导工程师用小型电机与钢丝制造出速度惊人、攀爬废墟如履平地的四足机械蜘蛛，是绝佳的远距离微型侦察兵。",
        en = "Mechanical drawings illustrating the high-speed multi-legged chassis of a skitterbot. Using miniaturized actuators and gyroscopic balancing, assembling this mechanical spider yields a rapid scout capable of scrambling through tight rubble tunnels.",
    },
    ["scimitar"] = {
        zh = "带有优雅大弧度单面开刃的古典东方舍施尔弯刀。出色的流线型刀身将挥砍动能发挥得淋漓尽致，单手借着马步一刀抹过，能将扑过来的变异狂徒整颗头颅齐刷刷削下。",
        en = "A sweeping oriental shamshir forged with deep curvature and distal taper. Slashing smoothly through unarmored targets, a fluid one-handed draw slice cleanly decapitates leaping ghouls with effortless momentum.",
    },
    ["scimitar_fake"] = {
        zh = "漫展摊位上随处可见的不锈钢电镀廉价弯刀。金光闪闪的塑料刀柄靠双面胶固定，刀身又薄又脆，用力劈在硬木桩上都会崩裂成三截，纯粹是拿来挂墙拍照的玩具。",
        en = "A decorative stainless steel wall-hanger bought from a costume bazaar. Glued to a plated plastic hilt, striking an undead skull violently snaps the brittle blade into flying, dangerous metal shards.",
    },
    ["scimitar_inferior"] = {
        zh = "废土铁匠用生锈废铁条生生砸出来的粗制弯刀。弧度扭曲怪异且刀口布满崩口锯齿，虽然挥舞起来显得粗笨笨重，但凭借那股蛮力和破伤风涂层依然能砍翻拦路的丧尸。",
        en = "A crude curved sword hammered out of rusted scrap metal on an anvil. Coarse and poorly balanced, its jagged, jagged edge still tears through rotten flesh with terrifying blunt force.",
    },
    ["scissors"] = {
        zh = "原本负责在空调办公室里拆快递和剪打印纸的文职工具，如今在废土上转行成了战地裁缝与急救外科医生的搭档。只要塑料手柄还没被你捏爆，它就能忠实地将死人身上的防弹衣剪成碎布条。",
        en = "Formerly employed in climate-controlled cubicles to trim cardstock and slice delivery packaging, now drafted into post-apocalyptic battlefield tailoring. Provided you do not snap the plastic grip under stress, it dutifully strips salvageable Kevlar and fabric from unfortunate casualties.",
    },
    ["scissors_child"] = {
        zh = "刀头打磨成安全圆钝弧形的小学手工塑料儿童剪刀。刀刃迟钝得连厚纸板都难以剪断，更不用说指望拿它刺穿丧尸脑壳，但在大灾变中用来裁切软布条做绷带还算差强人意。",
        en = "Blunt-nosed plastic safety scissors manufactured for kindergarten arts and crafts. Completely useless for stabbing undead skulls or slicing tough leather, they still manage to snip clean cloth strips for makeshift emergency bandages.",
    },
    ["scissors_medical"] = {
        zh = "高品质不锈钢锻造、带有平头导向防护的专业医用手术剪。不仅能精准剪除感染坏死肌肉组织与粗壮缝合线，在紧急抢救时还能像切纸一样瞬间剪碎伤者厚重的防弹衣物与浸血裤管。",
        en = "Surgical shears forged from high-grade stainless steel with blunt safety guide tips. Designed to slice smoothly through denim and ballistic vests during trauma triage, they also excise necrotic tissue with clinical precision.",
    },
    ["scissors_wavy"] = {
        zh = "刀刃带有波浪形交错咬合齿的手工花边剪刀。剪出的布料边缘呈锯齿状能有效防止织物脱线散边，虽然外形充满少女心，但在缺乏缝纫机拷边的情况下是处理衣料边缘的神奇利器。",
        en = "Crafting shears equipped with jagged interlocking wave-pattern blades. Slicing through woven fabric leaves decorative zigzag edges that resist fraying, serving as a clever zero-effort seam finish when sewing machines are extinct.",
    },
    ["scorecard"] = {
        zh = "一张大灾变前高尔夫球场遗留的空白记分卡纸片。上面还印着十八个球洞的击球标准杆数，如今铅笔早已折断，背面被拾荒者密密麻麻写满了避难所物资清单与丧尸击杀统计。",
        en = "A paper scorecard salvaged from an overgrown country club golf course. Once tracking fairway handicaps, scavengers now use its reverse side to tally ammo counts and confirmed zombie headshots.",
    },
    ["scots_cookbook"] = {
        zh = "用古老晦涩的苏格兰方言手写的破旧烹饪食谱大书。里面记载着哈吉斯肉馅羊肚、燕麦炖肉与重度烈酒浸泡乱炖的硬核烹调法，虽言辞粗鲁古怪，却能把最难以入口的内脏化为美味能量。",
        en = "A weathered tome penned in thick, archaic Scots dialect celebrating haggis and salted porridge. Though its dense vernacular baffles modern eyes, its rugged recipes transform the grimiest animal offal into hearty warrior sustenance.",
    },
    ["scots_tailor"] = {
        zh = "泛黄纸页上记录着苏格兰传统粗呢褶裙与厚羊毛披肩缝制技艺的手工书。传授如何用最粗糙的麻线与骨针缝合耐磨保暖的凯尔特战袍，让披挂者在严酷风雨中傲然挺立。",
        en = "A dog-eared crafting manual detailing traditional Highland kilt-making and heavy wool mantle tailoring. Teaching sturdy hand-stitching with coarse twine and bone needles, it produces rugged tartan garments that mock freezing gales.",
    },
    ["scout_bipod"] = {
        zh = "斯太尔侦察步枪护木一体化设计的折叠聚合物两脚架。平时紧密贴合在枪身两侧浑然一体毫无凸起，收拢状态下便于快速穿行于密林灌木之间，绝不挂绊任何藤蔓树枝。",
        en = "An integral polymer bipod nested flush into the Steyr Scout rifle's forearm. Completely streamlined when folded, it eliminates bulky snag points while darting through tangled brush, waiting silently for rapid precision deployment.",
    },
    ["scout_bipod_deployed"] = {
        zh = "从斯太尔侦察步枪护木下方展开的两脚架支腿。触地稳定轻巧，能在瓦砾、汽车发动机盖或倒塌原木上瞬间构筑起纹丝不动的射击平台，让远距离点名变异怪物变得从容自若。",
        en = "The integrated bipod legs flipped downward into firing position. Providing rock-steady three-point stability across car hoods or broken masonry, it instantly transforms a mobile scout rifle into a lethal precision sniper platform.",
    },
    ["scout_stock"] = {
        zh = "采用人体工程学轻量化设计的斯太尔中空聚合物枪托。底板内藏有备用弹匣收纳插槽，即便在混战中打空枪膛，也能从枪托底部瞬间抽出一夹满装子弹，完成教科书级的闪电续航。",
        en = "A hollow lightweight polymer buttstock designed with an integrated magazine well. Storing a spare loaded magazine within its buttpad cavity, it allows marksmen to execute lightning-fast tactical reloads straight from the shoulder.",
    },
    ["scrabble"] = {
        zh = "装在天鹅绒布袋里的全套拼字游戏木质字母块。每个方块上刻着字母与对应分值，在电力彻底断绝的漆黑废土长夜中，它是避难所同伴们维持词汇记忆与克制拔枪冲动的极佳益智玩具。",
        en = "A full set of wooden letter tiles tucked into a velvet drawstring pouch. Scoring clever vocabulary combos beside sputtering tallow candles keeps literacy sharp and prevents cabin fever brawls during grueling underground winters.",
    },
    ["scrambled_eggs"] = {
        zh = "在铁锅里用动物油脂慢火翻炒至松软金黄的热气腾腾炒蛋。散发着纯净自然的浓郁蛋香，虽然没有撒黑胡椒和细盐调味，但每一口温热软嫩的蛋块都让人感动得眼角发湿。",
        en = "Fresh eggs scrambled gently in rendered animal tallow over morning coals. Fragrant and velvety, its simple, unseasoned warmth restores emotional fortitude after long, terrified nights barricaded in basements.",
    },
    ["scrambledeggsandbrain"] = {
        zh = "将变异鸟蛋与采集到的新鲜脑花混合动物油滑炒出的诡异料理。虽然脑组织的软糯口感让不知情者头皮发麻，但其饱含的卵磷脂与丰富脂肪热量，是废土极客提神醒脑的硬核暗黑珍馐。",
        en = "A bizarre culinary scramble combining bird eggs with fresh animal brains sizzled in animal lard. Though its squishy texture unsettles squeamish stomachs, the intense blast of fats and lecithin powers exhausted minds through midnight watches.",
    },
    ["scrambler"] = {
        zh = "外表缠满导线与电容元件的高科技电子干扰手雷。投掷引爆后不会产生撕裂肉体的破片，而是爆发出一道强烈的定向电磁脉冲与逻辑干扰波，让范围内的敌对机器人当场短路瘫痪甚至倒戈互射。",
        en = "A specialized electromagnetic grenade wrapped in exposed capacitors and emitter arrays. Detonating without lethal shrapnel, it emits a ferocious logical disruption pulse that scrambles nearby robotic friend-or-foe algorithms into chaotic firefights.",
    },
    ["scrambler_act"] = {
        zh = "引信已被激活、蜂鸣器发出刺耳倒计时的电子干扰手雷。电容内部正疯狂聚集致命高压电荷，表面指示灯剧烈闪烁，任何明智的幸存者都必须在两秒钟内将其狠狠掷向敌方机械哨兵。",
        en = "An armed scrambler grenade whining furiously as internal capacitors build to critical discharge. With LED strobes pulsing in frantic countdown, you have barely seconds to lob this disruptor straight into robotic patrol formations.",
    },
    ["scrap"] = {
        zh = "从废墟和汽车残骸中拆卸下来的各种无规则形状废金属碎片。边缘锋利且生锈斑驳，虽然外表毫不起眼，但在铁匠炉火中经过重新锻打便能化为刀剑、箭头或防御装甲的百变源泉。",
        en = "Irregular jagged shards of rusted scrap metal scavenged from ruins. While resembling junk to the uninitiated, heating and hammering these rough iron bits upon an anvil forges crude knives, arrowheads, or sturdy armor plating.",
    },
    ["scrap_aluminum"] = {
        zh = "从废弃易拉罐、窗框或破损飞机蒙皮上撕扯下来的轻质铝废料。质地轻盈且导热极佳，在废土坩埚中极易融化铸造，是打造轻量化餐具、箭杆与战术机械配件的优质轻金属原料。",
        en = "Lightweight aluminum scrap gathered from soda cans, window frames, and wrecked aircraft skins. Melting easily in crude foundries, this corrosion-resistant metal casts perfectly into custom mess kits, arrow shafts, and aerodynamic drone braces.",
    },
    ["scrap_brass"] = {
        zh = "带有暗哑金黄色光泽的废弃黄铜碎片与水龙头五金残料。延展性好且摩擦阻力低，是废土军火作坊在车床上旋削手工弹壳、冲压精密齿轮或铸造防锈轴套时梦寐以求的软金属原料。",
        en = "Lustrous chunks of salvaged brass hardware and plumbing fittings. Malleable and self-lubricating, this golden alloy is treasured by reloaders and gunsmiths for turning custom cartridge casings or casting durable clockwork bushings.",
    },
    ["scrap_bronze"] = {
        zh = "从公园废弃纪念雕像或古董器皿上凿下的高硬度青铜金属块。表面泛着一层古朴的铜绿，重新熔化后流动性极佳，能铸造出锋利坚韧且永不锈蚀的复古刀剑与战斧刃口。",
        en = "Heavy chunks of antique bronze chipped from municipal statues and decorative urns. Coated in verdigris, melting this copper-tin alloy casts durable, rust-proof toolheads and bladed weapons that outlast flimsy modern steels.",
    },
    ["scrap_canvas"] = {
        zh = "从破损帐篷、货车雨棚或粗布邮包上剪下的高密度帆布碎块。织纹极其紧密结实且具有良好的防撕裂性能，是打补丁修补重型行军背包、制作自制战术枪套或补强帐篷的优质材料。",
        en = "Rugged scraps of heavy woven canvas sliced from torn tents and cargo tarps. Highly resistant to punctures and tears, these durable swatches serve admirably for reinforcing worn rucksacks or tailoring heavy-duty tool sheaths.",
    },
    ["scrap_carpet"] = {
        zh = "从废弃办公室地板上用刀割下的一块块厚重化纤地毯碎片。虽然沾满灰尘且略显笨重，但将其铺在潮湿冰冷的避难所水泥地面上，能立竿见影地隔绝地气寒意并吸收走动脚步声。",
        en = "Heavy synthetic carpet remnants cut from ruined office suites. While dirty and unwieldy, laying these dense mats over freezing concrete bunker floors dampens footsteps while insulating beds from damp subterranean drafts.",
    },
    ["scrap_cast_iron"] = {
        zh = "从破裂暖气片、老式铁锅或排污下水管道上砸下来的生铁碎片。质地脆硬且耐热性极佳，在铁匠炉中敲打容易碎裂，但经过高温熔炼能浇铸成厚重的熔炉底板与破片重力炸弹外壳。",
        en = "Brittle shards of heavy cast iron harvested from shattered woodstoves and plumbing mains. While resisting ductile forging, melting these iron chunks casts excellent heat-retaining hearth grates or brutal fragmentation bomb casings.",
    },
    ["scrap_copper"] = {
        zh = "从变压器线圈、房屋电线与导电排上剥离出来的纯铜块。红润的金属光泽散发着无与伦比的导电与导热魅力，是维修太阳能蓄电池、手工绕制发电机线圈以及配制合金的无价宝藏。",
        en = "Pure reddish copper chunks recovered from stripped electrical wiring and transformer cores. Delivering unmatched thermal and electrical conductivity, these malleable scraps are vital for rewinding damaged alternators or soldering electronics.",
    },
    ["scrap_cotton"] = {
        zh = "从废旧棉被、撕破 T 恤或纯棉床单上裁剪出的一把柔软棉布碎片。吸水透气且触感亲肤，既能直接当成包扎伤口的急救止血棉垫，也是擦拭枪膛积碳与制作油灯引火芯的必备日常消耗品。",
        en = "Soft scraps of absorbent woven cotton salvaged from torn shirts and bedsheets. Gentle against skin, they clean fouled gun actions, ignite easily as char cloth tinder, or serve as sterile wound dressings in field clinics.",
    },
    ["scrap_denim"] = {
        zh = "从破烂牛仔裤与工装夹克上剪下的坚韧斜纹牛仔布碎片。耐磨抗刮蹭且结实耐用，用来给破洞的膝盖与手肘打上厚实补丁，能让磨损严重的探险衣物重新焕发战术防护活力。",
        en = "Tough indigo twill denim patches cut from worn-out work jeans. Exceptionally abrasion-resistant, stitching these heavy swatches over frayed elbows and knees extends the field lifespan of ragged exploration attire.",
    },
    ["scrap_esapi_plate"] = {
        zh = "被大口径穿甲弹击碎或严重撞裂的军用陶瓷防弹插板残片。虽然整体防弹结构已经粉碎失效，但这些坚硬无比的碳化硅或氧化铝陶瓷碎片，依然能磨成超硬磨石或缝入自制护甲关键部位。",
        en = "Shattered shards of military-grade silicon carbide ceramic armor plates. Though structurally compromised against high-velocity rifle fire, these ultra-hard ceramic fragments make exceptional sharpening hones or makeshift armored chest inserts.",
    },
    ["scrap_esbi_plate"] = {
        zh = "在激战中被重弹轰碎的增强型侧身陶瓷防弹板残骸。虽然失去了拦截步枪弹的整体完整度，但剥离出内部的轻质超高分子量聚乙烯背衬与陶瓷碎块，依然是改装轻量化防刺护臂的上好材料。",
        en = "Cracked fragments of an enhanced side ballistic armor insert. Stripping its resilient composite backing and ceramic chips yields lightweight, spike-resistant shims that scavengers stitch into makeshift forearm guards and shin greaves.",
    },
    ["scrap_faux_fur"] = {
        zh = "从破旧毛绒玩具或化纤冬衣内胆上撕下的人造毛皮边角料。柔软蓬松且不易吸水发霉，塞入靴底当鞋垫能彻底告别冻伤，也是缝制保暖耳罩或自制毛绒手套的绝佳隔热填充料。",
        en = "Fluffy scraps of synthetic fur shorn from battered plush toys and winter parkas. Resisting rot and dampness, stuffing these plush bits into boots cushions sore soles while lining homemade mittens against winter frost.",
    },
    ["scrap_felt"] = {
        zh = "从老式毛毡帽子、台球桌呢或音响隔音板上割下的致密毛毡碎片。质地厚密且具有绝佳的缓冲消音特性，贴在刀鞘内部能彻底消除拔刀异响，也是制作防震工具垫与密封垫圈的上乘原料。",
        en = "Dense swatches of compressed wool felt salvaged from billiard tables and hats. Providing excellent acoustic and shock dampening, lining knife sheaths with felt silences draws while cutting custom gaskets stops grease leaks.",
    },
    ["scrap_fur"] = {
        zh = "鞣制狩猎猎物时剥离修剪下来的天然动物真毛皮边角碎料。虽然不成整块大皮子，但拼接在一起能制作暖和的护膝、耳套，或是为严寒中的木质枪托裹上一层绝不冻脸的贴心绒毛护贴。",
        en = "Small cutoffs of genuine tanned animal pelts left over from butchery. Stitched together into patchwork mittens or wrapped around freezing steel rifle cheekpieces, they prevent frostbite burns during sub-zero sniper vigils.",
    },
    ["scrap_kevlar"] = {
        zh = "从报废防弹衣和防暴头盔内衬中费力拆解下来的黄色芳纶纤维布碎片。抗拉强度极高且耐刀剑劈刺，把这些芳纶层层缝入皮衣内侧，能以极小的自重为幸存者构筑起一道抵抗丧尸利爪的无形金钟罩。",
        en = "Yellow aramid woven cloth scraps pulled from expired body armor vests. Boasting extraordinary tensile strength, sewing these cut-resistant patches beneath leather jackets crafts featherweight claw-proof armor against lurking zombie ambushes.",
    },
    ["scrap_leather"] = {
        zh = "从废弃皮沙发、破皮鞋或重型皮带上裁剪下来的厚实熟皮革碎片。耐磨抗穿刺且易于打孔穿线，无论是用来制作小刀皮鞘、修补靴底，还是缝制结实的工具绑带，都是废土皮匠的日常黄金原料。",
        en = "Tough scraps of tanned leather salvaged from battered boots and upholstery. Easy to punch and awl, these resilient hide fragments form dependable knife sheaths, boot sole patches, and durable load-bearing gear straps.",
    },
    ["scrap_lycra"] = {
        zh = "从破损紧身运动衣和瑜伽裤上剪下的高弹性氨纶布料碎块。具有惊人的延展回弹力，在制作贴身速干护膝、弹性止血带收纳环以及紧身伪装头套时能提供毫无束缚感的极佳贴合度。",
        en = "Stretchy fragments of synthetic Lycra cut from torn athletic compression wear. Exhibiting remarkable elasticity and quick-drying properties, they are ideal for fashioning snug joint braces or elastic retention loops on tactical gear.",
    },
    ["scrap_neoprene"] = {
        zh = "从废弃潜水服与减震笔记本电脑包上切下的防水合成氯丁橡胶碎片。内部充满密闭微孔，既完全不透水又兼具优良的保温与减震回弹性，是制作防潮护膝、保温水壶套以及密封舱门密封垫的万能材料。",
        en = "Foamed neoprene rubber cut from derelict wetsuits and laptop sleeves. Completely waterproof and shock-absorbent, its closed-cell structure makes superior thermal cup sleeves, impact knee pads, and airtight hatch gasket seals.",
    },
    ["scrap_nomex"] = {
        zh = "从专业赛车服或消防防护服上剪下的难燃诺梅克斯织物碎片。遭遇明火时不会融化滴落，层层缝在手套或裤腿外层，能在迎战喷火丧尸或穿越燃烧残骸时提供难能可贵的隔热防护。",
        en = "Flame-resistant Nomex cloth remnants sliced from racing overalls or firefighter turnouts. Refusing to melt or burn when exposed to open flame, they shield extremities against blazing wreckage and flamethrower-wielding abominations.",
    },
    ["scrap_nylon"] = {
        zh = "从废旧登山包、防风衣或雨伞上撕下的轻韧合成尼龙布块。抗拉伸且极耐磨损，用来修补帐篷破洞、缝制轻巧的工具收纳袋或是加固磨损严重的背包肩带都格外皮实趁手。",
        en = "Durable synthetic nylon swatches torn from weathered hiking packs and windbreakers. Highly tensile and abrasion-resistant, they make reliable patch material for mending torn tents, reinforced strap loops, or lightweight kit pouches.",
    },
    ["scrap_tin"] = {
        zh = "带有银白色哑光光泽的纯锡金属碎片。熔点极低且质地柔软，在营火旁用小铁勺即可轻松融化，是调配软钎焊焊锡、修补漏水铁锅或是浇铸精细小工艺品的理想低熔点焊料。",
        en = "Soft silvery shards of salvaged tin metal bearing low melting points. Easily liquefied over a simple campfire spoon, they serve as prime solder stock for patching leaky cooking pots or casting decorative trade figurines.",
    },
    ["scraper_steel"] = {
        zh = "采用高碳工具钢制成的坚硬锋利平头刮刀。在木工作业中能精准刨平粗糙木料毛刺，在剥皮时能刮净附着在皮张上的多余油脂，清理生锈枪管外壁积垢时更是手到病除。",
        en = "A rigid high-carbon steel scraper ground with a fine scraping burr. Excelling at shaving wood splinters flush and scraping stubborn fat from curing hides, it also strips baked carbon from fouled gun actions.",
    },
    ["scrapple"] = {
        zh = "将碎猪肉杂碎、骨汤与玉米粉混合慢熬后凝固切块的面饼。切片在热油中煎至两面金黄焦脆，虽然用料粗放全凭碎肉内脏拼凑，但油脂与淀粉的饱满结合能提供极其抗饿的热量充盈感。",
        en = "A traditional Pennsylvania Dutch loaf crafted from boiled pork trimmings, organ meats, and cornmeal. Pan-fried in hot grease until golden and crusty, this rustic mystery-meat cake provides intense caloric stamina for hard labor.",
    },
    ["screen_mesh"] = {
        zh = "用细金属丝编织而成的高密度防虫窗纱网。安装在避难所通风口或窗框上，能彻底阻挡变异蚊虫与毒蜂的夜间潜入，在河边淘洗沙金或过滤污水中的粗大杂质时也堪称神器。",
        en = "Fine-woven wire insect screening salvaged from residential window frames. Fitted across bunker air ducts, it stops venomous mutant wasps while doubling as a coarse sieve for filtering floating river debris and gravel.",
    },
    ["screw_press"] = {
        zh = "配有粗壮梯形螺杆与重型铁压板的固定式机械压榨机。转动杠杆旋紧螺杆能产生数十吨的均匀压榨力，无论是从发酵苹果中压榨果汁，还是从油菜籽中压榨植物油，都极其省力高效。",
        en = "A heavy stationary press operated by a massive threaded central steel screw. Turning the crossbar drives tremendous mechanical downforce, efficiently squeezing sweet cider from mashed apples or pure edible oil from oilseeds.",
    },
    ["screw_press_tool"] = {
        zh = "便于搬运携带的中型便携式螺旋压榨装置。小巧紧凑的铸铁框架能在任何坚固营地桌面上固定作业，是小规模提炼药草精油、榨取浆果汁水以及压实弹药发射药柱的得力工具。",
        en = "A compact benchtop screw press engineered for mobile workshop setups. Clamping firmly to any sturdy tabletop, it compresses herbal tinctures, extracts fresh berry juices, or consolidates loose black powder pellets reliably.",
    },
    ["screwdriver"] = {
        zh = "一切废土精密机械与电子拆解的核心钥匙。然而每个技工都知道它的诅咒：当你身处尸潮边缘、十万火急想要拧开配电箱逃生时，十字槽总会因为用力过猛而瞬间滑丝，将求生通道变成一道冰冷绝壁。",
        en = "The indispensable heart of all electronics dismantling and vehicle mechanics. Every survivor understands its subtle curse: the very moment you frantically attempt to unscrew an escape hatch while running from predators, the crosshead will instantly strip the rusted screw entirely smooth.",
    },
    ["screwdriver_set"] = {
        zh = "包含十字、一字、梅花与内六角等多种可替换刀头的全套螺丝刀组。小巧的塑料收纳盒里收纳着各种规格批头，是拆解精密电子仪器、改装机械枪械与拆锁入室时不可或缺的万能钥匙。",
        en = "A complete multi-bit screwdriver kit packed neatly in an impact-resistant polymer case. Featuring Phillips, slotted, and Torx drivers, it provides the precise leverage needed to disassemble complicated cybernetics or scavenged firearms.",
    },
    ["scuba_tank"] = {
        zh = "装满高压压缩空气的重型铝合金水下潜水气瓶。沉重的气瓶不仅能为水下潜泳搜刮沉船提供充足呼吸，在陆地上遭遇致命毒气云或浓烟封锁时，也是保障呼吸通畅的生命源泉。",
        en = "A heavy aluminum diving cylinder filled with high-pressure breathable air. Designed for underwater salvaging expeditions, hauling this tank also guarantees untainted oxygen when navigating poison gas chambers and toxic smog ruins.",
    },
    ["scuba_tank_on"] = {
        zh = "已经开启主气阀、气流呼呼作响的潜水气瓶。减压呼吸阀随时准备向咬嘴输送清凉干燥的高压洁净空气，在恶臭熏天、充斥毒瘴的废墟下水道中，每一口呼吸都显得无比珍贵。",
        en = "A diving cylinder with its primary regulator opened and whistling with pressurized air. Delivering cool, dry oxygen on demand, it allows intrepid explorers to trek through suffocating sewer gases with supreme pulmonary confidence.",
    },
    ["sculpture_clay"] = {
        zh = "用河滩红黏土手工捏塑并晾干的简陋小泥塑。虽然手法粗糙得像小孩子的即兴涂鸦，但摆在阴暗避难所的木桌上，能为这个残酷冰冷的世界添上一丝温馨的人性光辉。",
        en = "A primitive clay figurine molded by hand from riverbank silt and dried. Crudely proportioned, resting on a rough wooden table it provides comforting reminders of creative human joy.",
    },
    ["sculpture_rock"] = {
        zh = "用高碳钢凿子在花岗岩碎块上耐心雕琢出的人脸石头雕塑。历经风吹雨打依然沉稳坚毅，凝视着它那张饱经沧桑的石面，仿佛在提醒你无论文明如何崩溃，坚韧的意志永不磨灭。",
        en = "A weathered stone visage chiseled meticulously from a hunk of granite. Standing stoic against acidic rains, its impassive gaze inspires wandering survivors to endure whatever horrors await tomorrow.",
    },
    ["scutcheritem"] = {
        zh = "装有旋转木制打麻刀叶的固定式打麻脱胶机。通过反复抽打沤洗过的麻类与荨麻茎秆，能迅速敲落干枯硬脆的木质麻骨，剥离出洁白柔韧的天然长纤维用于纺纱织布。",
        en = "A stationary mechanical scutcher fitted with blunt revolving wooden blades. Repeatedly thrashing retted flax and hemp stalks breaks away brittle woody cores, freeing smooth lustrous fibers for spinning durable survival cordage.",
    },
    ["scythe"] = {
        zh = "配有修长弯曲木柄与锋利弧形大刀刃的传统双手大农镰。原本是在麦浪与牧草中大片收割作物的农具，其夸张的攻击范围与沉重的挥砍势能，在横扫群聚丧尸时同样令人胆寒。",
        en = "A sweeping two-handed agricultural scythe featuring a curved wooden snath and long arc blade. Masterfully mowing tall meadow hay in summer, its terrifying sweeping cleave equally decapitates creeping zombie clusters in battle.",
    },
    ["scythe_fake"] = {
        zh = "万圣节装扮死神用的空心塑料大镰刀。巨大的弧形刀刃连纸张都割不破，手柄轻轻一折就会断裂，除了在狂欢夜吓唬无知儿童之外，面对丧尸只能当作一根滑稽的烧火棍。",
        en = "A novelty costume scythe manufactured from hollow black and silver plastics. Flimsy and completely dull, brandishing this toy against real slavering monsters results only in shattered plastic and painful regret.",
    },
    ["scythe_game"] = {
        zh = "以架空一战柴油朋克机甲为背景的豪华重策桌游「蒸汽装备」。精美的微缩机甲模型与精细木质资源指示物，让幸存者在断电的长夜里排兵布阵，重温昔日人类对钢铁巨兽的浪漫幻想。",
        en = "A lavish dieselpunk board game set featuring miniature mechs and wooden resource tokens. Plotting alternate-history faction dominations by candlelight provides hours of tactical mental escape, temporarily distracting players from grim wasteland reality.",
    },
    ["scythe_toy"] = {
        zh = "万圣节派对专用的中空塑料死神长柄大镰刀。刀刃涂着发光的银色漆料但轻飘飘毫无杀伤力，拿来吓唬小孩或者在营火晚会上客串死神逗乐同伴很合适，千万别指望拿它防身。",
        en = "A hollow novelty scythe made of molded black and silver plastic for costume parties. Completely incapable of cutting grass let alone flesh, waving this ridiculous prop at least provides grim comedic entertainment around campfires.",
    },
    ["scythe_war"] = {
        zh = "将大镰刀刃重新锻打并垂直装在长木柄前端的致命长柄战镰。改造后的直刃兼具强悍的刺杀与钩割功能，能在数米开外轻松刺穿敌人喉咙或将马背上的掠夺者硬生生扯下坐骑。",
        en = "A lethal polearm created by re-forging a farm scythe blade straight along a sturdy hardwood shaft. Combining devastating thrusting reach with vicious back-hooking cuts, it dismounts armored raiders and pierces mutant hides with ease.",
    },
    ["sea_lettuce"] = {
        zh = "漂浮在潮间带或搁浅在礁石上、碧绿如翠玉的新鲜石莼海萝。口感柔嫩爽滑且带着淡淡的海盐咸香，富含碘元素与多种微量营养，是海滨拾荒者预防甲状腺肿大的天然解药。",
        en = "Translucent ribbons of bright green edible sea lettuce harvested from ocean shallows. Tender and lightly salted, tossing these fresh macroalgae into campfire broths provides essential iodine and trace minerals that prevent endocrine deficiency.",
    },
    ["seabag"] = {
        zh = "采用军规加厚重磅防水帆布缝制的海员水手背囊。圆筒形包身容量极其惊人，配有坚固的顶部穿孔金属扣与双肩背带，哪怕硬塞进几十公斤废旧零件也能被它牢牢兜住而不崩线。",
        en = "A heavy-duty cylindrical canvas duffel designed for naval sea deployments. Bound with brass eyelets and heavy shoulder webbing, this massive top-loading sack swallows weeks of scavenged rations and ammunition without ripping its seams.",
    },
    ["seasoned_fried_eggs"] = {
        zh = "在平底锅里煎得边缘焦脆、蛋黄流心的调味双黄煎蛋。表面撒满了细盐与干辣椒碎，一口咬下去蛋黄爆浆在唇齿间，是废土大厨在清晨能为你奉上的最奢华早餐。",
        en = "Fried eggs seared crisp around the lacy edges, dusted with salt and wild herbs. Puncturing the runny yolk spreads creamy richness across stale bread, delivering five-star breakfast bliss in ruins.",
    },
    ["seasoned_scrambled_eggs"] = {
        zh = "撒入野葱碎与胡椒粉调味炒制出的金黄嫩炒蛋。香气扑鼻且口感极为顺滑，每一勺滑入喉咙都带来无与伦比的营养与满足感，让你精力充沛地迎接一整天的危险冒险。",
        en = "Scrambled eggs folded with foraged wild chives and freshly cracked pepper. Fluffy and deeply aromatic, every warm mouthful replenishes vital stamina before departing on dangerous scavenging expeditions.",
    },
    ["seasoning_italian"] = {
        zh = "混合了牛至、罗勒、迷迭香与百里香碎叶的经典意式复合香料粉。开罐瞬间草本清香扑鼻而来，只需随手撒上一小撮，就能让淡而无味的粗糙野味炖肉散发出地中海餐厅般的优雅香气。",
        en = "A fragrant dry blend combining crushed oregano, basil, thyme, and rosemary. Sprinkled over tough boiled venison or canned beans, this aromatic Mediterranean herb mix disguises gamey wasteland musk with rustic culinary elegance.",
    },
    ["seasoning_salt"] = {
        zh = "混合了精细食盐、辣椒粉、洋葱粉与大蒜粉的多功能复合调味红盐。咸中带辣且鲜味浓郁，无论是煎烤变异野味排还是撒在烤土豆片上，都能让最挑剔的幸存者胃口大开。",
        en = "A savory seasoned salt blend spiked with garlic powder, paprika, and onion essence. Delivering an instant flavor punch to freshly harvested meats, it turns grim survival rations into mouthwatering, lip-smacking campfire delicacies.",
    },
    ["seat"] = {
        zh = "包裹着耐磨织物面料的经典汽车单人斗式座椅。贴合人体的侧向支撑能在车辆高速过弯或颠簸越野时牢牢固定驾驶员，拆下来装在营地里也是一张极其舒适的战术工作椅。",
        en = "A standard automotive bucket seat upholstered in hard-wearing synthetic fabric. Providing solid lateral torso bolstering across rugged off-road tracks, bolting it inside a bunker delivers unmatched fireside lounging comfort.",
    },
    ["seat_bench"] = {
        zh = "拆卸自面包车或皮卡后排的宽大三人联排长座椅。虽然缺乏单人包裹性，但平坦的坐垫能让两三名幸存者并排挤在一起取暖，夜间甚至可以直接横躺在上面当作简易小床小憩。",
        en = "A wide vehicle bench seat capable of seating three survivors side-by-side. While offering minimal cornering support during wild chases, its flat padded surface converts easily into an improvised bunk for weary scouts.",
    },
    ["seat_bench_leather"] = {
        zh = "采用奢华真皮包裹的高级汽车联排真皮长座椅。皮质细腻顺滑且极易擦拭灰尘污渍，坐上去柔软富有弹性，让坐在后排的幸存者在残酷破败的末世中重温昔日豪车巡游的惬意体验。",
        en = "A plush bench seat trimmed in genuine automotive leather. Easy to wipe clean of mud and blood, its supple cushioning allows weary passengers to endure cross-country hauls with luxurious, dignified comfort.",
    },
    ["seat_leather"] = {
        zh = "来自豪华轿车的真皮单人斗式座椅。包裹感与腰部支撑无可挑剔，柔软的真皮散发着优雅质感，将其焊接在末日改装战车驾驶位上，能大幅减缓长途巡逻带来的腰背酸痛与驾驶疲劳。",
        en = "A premium contoured leather bucket seat extracted from an upscale passenger sedan. Hugging the spine with ergonomic lumbar support, mounting this throne behind the steering wheel prevents chronic backache during grueling cross-country expeditions.",
    },
    ["seatbelt"] = {
        zh = "从废弃皮卡车座上整条割下来的高强度聚酯安全带。编织密度极高且抗拉强度惊人，在野外绑扎重型装甲板、拖曳受损车辆或者制作止血带时，它的耐用性无可挑剔。",
        en = "A strip of industrial polyester webbing salvaged from a vehicle cabin. Boasting immense tensile tolerance, it serves flawlessly as towing towline, cargo tie-downs, or improvised emergency medical tourniquets.",
    },
    ["seaweed"] = {
        zh = "从海岸岩石上采集而来的新鲜褐色海藻。滑腻的表面附着着海盐与矿物质，切碎煮汤不仅能补充人体必需的微量盐分与碘，在烘干脱水后还能长期作为紧急救命口粮储存。",
        en = "Fresh dark seaweed harvested from coastal tidal pools. Coated in briny ocean minerals, chopping and boiling these salty fronds yields nourishing broth packed with bioavailable iodine and trace minerals that prevent radiation sickness.",
    },
    ["seaweed_pile"] = {
        zh = "堆积在海滩或营地地面上的一大堆湿漉漉的收获海藻。散发着浓烈的海腥味，必须趁着晴好天气尽快摊开晾晒或下锅脱水加工，否则在高温潮湿环境下几天就会腐烂成一滩恶臭黑泥。",
        en = "A dripping heap of freshly gathered marine algae emitting pungent ocean odors. Requiring prompt sun-drying upon canvas tarps, leaving this massive pile damp invites rapid bacterial decay that ruins valuable food stocks.",
    },
    ["security_file"] = {
        zh = "装在保密牛皮纸袋内的绝密安防实验事件报告。上面记录了地下生化研究所在灾难初期的警报记录、武器配置与异常生物突破封锁的血腥细节，是解密沦陷真相的关键线索。",
        en = "A classified security incident dossier bound within a water-damaged confidential folder. Detailing facility breach alarms, automated turret protocols, and monstrous containment failures, it provides invaluable tactical intelligence regarding subterranean underground horrors.",
    },
    ["seed_artichoke"] = {
        zh = "颗粒饱满的洋蓟蔬菜种子。播种在肥沃疏松的菜园土壤中并悉心浇灌，来年便能长出带刺的硕大花苞，蒸熟后蘸上黄油，能让人品尝到文明世界最优雅细腻的草本风味。",
        en = "Plump artichoke seeds capable of producing prickly architectural thistle bushes. Rewarding patient greenhouse cultivation with succulent edible flower buds, dipping steamed bracts in melted butter brings refined luxury back to grim ruins.",
    },
    ["seed_asparagus"] = {
        zh = "坚硬乌黑的芦笋多年生宿根种子。虽然播种后需要耐心照料数年才能迎来初次丰收，但一旦扎根立足，每年春天破土而出的鲜嫩脆甜笋尖将成为定居点源源不断的美食供给。",
        en = "Hard black asparagus seeds meant for long-term perennial farming investments. While demanding years before full harvest maturity, established crowns yield sweet, crispy spears every subsequent spring to enrich the community's seasonal diet.",
    },
    ["seed_barley"] = {
        zh = "装在干燥小纸袋里的一捧饱满大麦种子。只要在开春时播撒进避难所旁边的肥沃泥土里，不仅能在秋天收割维持生命的大麦面包，更是手工酿造废土麦芽啤酒的希望源泉。",
        en = "A packet of dry, viable barley grains scavenged from a garden shed. Sown in springtime soil, they yield nutritious porridge, durable hardtack, and the foundational malt for glorious post-apocalyptic beer.",
    },
    ["seed_beans"] = {
        zh = "颗粒坚硬且表面光滑的四季菜豆种子。发芽率极高且善于在贫瘠土地里固氮生长，顺着栅栏爬藤结出的累累豆荚，能为缺乏肉食的避难所提供全年源源不断的蛋白质补充。",
        en = "Hardy dried pole bean seeds sealed in paper envelopes. Nitrogen-fixing and eager to climb timber fences, they produce bountiful green pods to sustain communities through meat-scarce autumns.",
    },
    ["seed_bee_balm"] = {
        zh = "微小的香蜂草药用植物种子。盛开时会绽放出绚烂如火的红色花朵并招引大量传粉昆虫，其带有佛手柑香气的叶片既能冲泡舒缓神经的花草茶，也是治疗烫伤与湿疹的天然药膏原料。",
        en = "Tiny bee balm seeds that mature into vibrant crimson blossoms beloved by pollinators. Crushing the bergamot-scented foliage yields soothing herbal teas that calm nervous jitters and treat minor skin ailments.",
    },
    ["seed_bell_pepper"] = {
        zh = "扁平淡黄色的甜味灯笼椒种子。种植在日照充足的温室或避难所菜园里，能结出硕大肉厚、色彩鲜艳的多汁甜椒，生吃爽脆清甜，炒肉更是提升菜肴色泽与维生素含量的绝佳食材。",
        en = "Flat, pale yellow bell pepper seeds yielding crisp thick-walled sweet peppers. Requiring warm sunny plots, the resulting colorful fruit supplies abundant vitamin C and refreshing crunch to perk up dull survivor stews.",
    },
    ["seed_blackberries"] = {
        zh = "从甜美多汁的野生黑莓果肉中挑选出来的微小坚硬种子。长成的灌木不仅会长满倒刺形成天然的防盗防御树篱，夏末结出的黑亮浆果更是熬制果酱与酿造果酒的无价馈赠。",
        en = "Hard tiny seeds harvested from ripe wild blackberries. The resulting thorny bramble bushes form impenetrable defensive perimeter hedges around camps while yielding sweet, dark berries for canning jam and fermenting fruit wine.",
    },
    ["seed_blueberries"] = {
        zh = "喜酸性土壤的多年生高丛蓝莓果实种子。悉心播种在松针与泥炭混合土中，成年灌木会在盛夏挂满宛如蓝宝石般的白霜甜美浆果，为幸存者提供保护视力与抗氧化的天然良药。",
        en = "Acid-loving blueberry seeds best sown within pine needle mulch and peat beds. Maturing into fruitful shrubs, the powdery indigo berries deliver potent antioxidants that sharpen tired night vision during perimeter watches.",
    },
    ["seed_bottle_gourd"] = {
        zh = "外形扁平、两端带有凹角的大葫芦种子。攀爬藤蔓结出的坚硬葫芦成熟晒干后，锯开掏空内部不仅能制成结实耐用的天然储水葫芦水壶，还能雕刻成舀水勺与杂物收纳罐。",
        en = "Flat, angular bottle gourd seeds growing into vigorous climbing vines. When dried and hollowed, the rock-hard gourds transform into lightweight water canteens, durable ladles, and airtight seed storage jars that never rust.",
    },
    ["seed_broccoli"] = {
        zh = "细小圆滚的耐寒西兰花十字花科种子。在冷凉湿润的春秋季节生长旺盛，收获紧实翠绿的花球含有极为丰富的微量元素与膳食纤维，是废土自给自足农业中抵御营养不良的中流砥柱。",
        en = "Round, dark brassica seeds thriving in cool, damp spring weather. Developing into tight, nutrient-dense green florets, broccoli provides indispensable vitamins and dietary fiber to bolster weak survivor immune systems against rampant infections.",
    },
    ["seed_brussels_sprout"] = {
        zh = "极具耐寒性的小型抱子甘蓝种子。粗壮的茎秆上能密密麻麻结出数十个像微缩卷心菜般的小球芽，哪怕在初冬降雪与轻霜洗礼后采收依然甘甜爽脆，是寒冬菜园里的耐冻奇迹。",
        en = "Hardy seeds producing tall stalks studded with tiny cabbage-like sprouts. Thriving through early winter frosts that kill lesser crops, these sweet little brassica buds guarantee fresh green rations deep into November.",
    },
    ["seed_buckwheat"] = {
        zh = "呈不规则三角锥形的小粒荞麦种子。极其耐寒且对土壤毫不挑剔，即便在辐射落尘较轻的贫瘠荒地里也能快速成熟，磨成荞麦粉做成黑乎乎的面条既顶饱又健康。",
        en = "Triangular buckwheat grains capable of thriving in depleted, frost-bitten soil. Maturing in short growing seasons, grinding their groats produces dark, earthy noodles that fill bellies during harsh winters.",
    },
    ["seed_cabbage"] = {
        zh = "高产耐储存的结球卷心菜种子。成株叶片层层紧密包裹形成沉甸甸的坚实菜头，不仅产量巨大且耐磕碰，更是发酵制作大坛德式酸菜以彻底战胜坏血病的农业王牌作物。",
        en = "Prolific round cabbage seeds yielding dense, heavy vegetable heads. Extremely durable and long-storing in root cellars, this crop serves as the vital backbone for fermenting massive sauerkraut crocks to eradicate scurvy.",
    },
    ["seed_cactus"] = {
        zh = "耐旱至极的肉质仙人掌硬质种子。即便播种在干燥贫瘠的砂石沙土中也能顽强萌芽，长成的多肉茎叶既能切片做成酸脆仙人掌菜肴，成熟的仙人掌果更是多汁甘甜的沙漠解渴圣品。",
        en = "Tough drought-tolerant cactus seeds capable of thriving within arid sands. Maturing into spiny pads and juicy prickly pears, they supply hydrating survival fruit and crisp nopales vegetables requiring zero irrigation.",
    },
    ["seed_canola"] = {
        zh = "细小如砂砾的深黑色双低油菜籽。春天播种能开出一望无际的金黄色花海，收获后的饱满菜籽通过榨油机压榨，能源源不断地供给宝贵的食用烹饪油与调制生物柴油的优质油料。",
        en = "Tiny dark canola seeds that transform wasteland fields into rolling oceans of brilliant yellow blossoms. Pressing the harvested seeds yields gallons of clean cooking oil and biofuel stock to keep generators humming.",
    },
    ["seed_carrot"] = {
        zh = "带有微弱芳香气味的细长胡萝卜种子。播种在深厚松软的沙质土壤中，能长出笔直橙红、富含胡萝卜素的清甜块根，无论是生嚼解渴还是切块炖肉，都是保障夜间视力的关键营养素。",
        en = "Fragrant, slender carrot seeds requiring loose, rock-free soil for ideal root expansion. Harvesting these crisp orange taproots loads survivor diets with beta-carotene, boosting natural visual acuity during dark midnight watches.",
    },
    ["seed_cattail"] = {
        zh = "从水边干枯香蒲花序中搓落的绒毛状种子。适合播种在池塘浅滩与泥泞湿地中，香蒲成熟后根茎富含淀粉、嫩芽鲜美多汁、花粉可作面粉，连毛绒都能充当救生衣与冬衣保暖填充物。",
        en = "Fluffy downy seeds gathered from wild wetland cattail heads. Colonizing muddy pond banks, every part of the mature plant proves useful: starchy roots for survival flour, young shoots for greens, and seed fuzz for down insulation.",
    },
    ["seed_cauliflower"] = {
        zh = "细小的白色花椰菜农用种子。精心培育后能生长出硕大纯洁的奶油色花球，口感软糯香甜，富含维生素 C 与抗氧化物，是提升废土聚居地餐桌档次的高级十字花科蔬菜。",
        en = "Tiny brassica seeds requiring rich compost to produce dense, ivory flower heads. Mild, buttery, and versatile in stews or roasted over coals, it elevates post-cataclysm garden dining to gourmet civilized standards.",
    },
    ["seed_celery"] = {
        zh = "带有特殊浓郁药香气味的微小芹菜种子。喜水耐阴，长成的青翠叶柄爽脆多汁且自带天然微咸风味，切碎后与洋葱、胡萝卜同炒，能构成任何高级高汤的核心风味三剑客基底。",
        en = "Pungent, microscopic celery seeds that produce crisp, juicy green stalks. Naturally rich in organic sodium and moisture, diced celery forms the foundational holy trinity for simmering aromatic, restorative survivor stocks.",
    },
    ["seed_chamomile"] = {
        zh = "微如尘埃的德国洋甘菊药草种子。播种后能迅速蔓延出一片开满雏菊般白色小花的芬芳花海，采摘花头烘干冲泡成温热的花草茶，能有效平复末日幸存者紧绷的精神创伤并安抚神经助眠。",
        en = "Dust-like chamomile seeds yielding carpets of delicate white daisy flowers. Brewing the dried blossoms into fragrant evening tea calms battle fatigue and anxious tremors, coaxing deep sleep without dangerous pharmaceutical narcotics.",
    },
    ["seed_chicory"] = {
        zh = "开着淡蓝色花朵的菊苣菜耐寒植物种子。其鲜嫩的苦味叶片是极佳的开胃沙拉，深长的主根洗净烘焙研磨后，更是能泡出香气浓郁、足以乱真且抚慰心灵的战时咖啡替代热饮。",
        en = "Resilient chicory seeds sprouting into blue-flowered wild greens. While bitter leaves make appetizing digestive salads, roasting and grinding the parsnip-like taproot brews rich, dark pseudo-coffee that satisfies morning caffeine rituals.",
    },
    ["seed_chili_pepper"] = {
        zh = "扁平金黄、内藏烈火的朝天椒硬质种子。在温室中极易发芽生长并结满火红的辛辣辣椒，采收风干磨碎后不仅能驱寒发汗、掩盖腐变野味异味，还能装进纸筒改造成防暴辣椒催泪瓦斯喷罐。",
        en = "Fiery little chili pepper seeds that sprout into bushes heavy with blistering peppers. Crushed into red flakes, they mask gamey meat flavors, warm freezing marrow, and load improvised pepper-spray canisters.",
    },
    ["seed_corn"] = {
        zh = "金黄干燥的杂交甜玉米种子颗粒。在充足阳光与雨水的滋润下能长成两米多高的茂密青纱帐，结出的饱满玉米棒既能当主粮啃咬，也是潜行躲避尸潮视线的天然屏障。",
        en = "Dried yellow sweet corn seeds packaged for commercial planting. Towering into two-meter stalks under summer sunshine, they furnish sweet roasting ears while providing concealment from roving zombie patrols.",
    },
    ["seed_cotton_boll"] = {
        zh = "包裹在白色蓬松棉絮内部的黑色天然棉花籽。种植在避难所外围田地里，秋季吐絮时采摘下的一朵朵白棉花，是定居点实现纯棉纺线织布、自制无菌纱布与保暖棉被的农业命脉。",
        en = "Dark cotton seeds encased within fluffy white cellulose bolls. Harvesting this essential fiber crop enables survivor communities to spin genuine thread, weave breathable clothing, and produce sterile medical bandages.",
    },
    ["seed_cranberries"] = {
        zh = "喜酸性湿地与沼泽环境的蔓越莓果实硬核种子。蔓延生长的匍匐灌木在秋季挂满鲜红透亮的酸爽浆果，极高含量的天然酸与抗氧化剂让它能极长久储存，是预防尿路感染的神奇野果。",
        en = "Hard seeds extracted from tart, acid-loving wetland cranberries. Spreading across acidic bog beds, the crimson berries resist spoilage for months and supply potent compounds that guard against urinary tract infections.",
    },
    ["seed_cucumber"] = {
        zh = "两头尖尖的白绿色清脆沙拉黄瓜种子。攀爬在竹架或废铁丝网上能在盛夏结出无数多汁清脆的条形黄瓜，洗净直接咬下一口满嘴清爽，是烈日高温劳作后最快速解渴生津的天然补水棒。",
        en = "Pointed white seeds of sweet salad cucumbers. Trellised along chain-link fences, the vines pump out crisp, water-heavy fruit that quenches searing summer thirst faster than stale canteen water.",
    },
    ["seed_dahlia"] = {
        zh = "开花硕大艳丽的大丽花球根与植物种子。除了盛夏盛开出如盘子般巨大的华丽多色花朵抚慰疲惫心灵外，其地下膨大的块根洗净煮熟后还含有丰富的菊粉淀粉，是兼顾美观与充饥的双重宝藏。",
        en = "Ornamental dahlia seeds yielding magnificent multi-petaled dinnerplate blossoms. Beyond uplifting war-torn survivor morale with dazzling floral displays, their swollen tubers can be boiled and eaten as starchy survival tubers.",
    },
    ["seed_dogbane"] = {
        zh = "长在细长豆荚内、带有丝状绒毛降落伞的罗布麻种子。这种古老的野生纤维植物皮层韧皮极度结实，剥离搓捻出的罗布麻绳抗拉力甚至超过生皮，是野外自制弓弦、钓鱼线与陷阱绳索的无上极品。",
        en = "Silky wind-dispersed seeds of the tough wild dogbane plant. The fibrous bark strips yield extraordinarily strong bast cordage, superior even to rawhide for fashioning bowstrings, fishing lines, and snare triggers.",
    },
    ["seed_eggplant"] = {
        zh = "微小扁平的深紫色茄子蔬菜种子。在炎热夏季挂满油光水滑的深紫长茄，海绵状的果肉极其擅长吸收烹饪时的油脂与酱汁，切片油煎后口感软糯如同肥美的肉片，深受素食者与饥民喜爱。",
        en = "Tiny flat seeds that yield glossy deep-purple eggplants during hot summer months. Its spongy flesh acts like a flavor sponge, absorbing rendered animal fats to mimic rich savory meats in skillet fry-ups.",
    },
    ["seed_elderberries"] = {
        zh = "从深紫色接骨木果实中提纯出的小浆果种子。长成的灌木结满密密麻麻的小黑果，虽然生食含有微毒，但煮沸熬制成接骨木糖浆后，是治疗感冒咳嗽、驱散高热寒战的传奇民间草药圣品。",
        en = "Small seeds gathered from wild elderberry clusters. While mildly toxic raw, boiling the harvested dark berries into rich purple syrup yields a legendary immune-boosting tonic that breaks stubborn bronchial fevers.",
    },
    ["seed_flower"] = {
        zh = "混合了万寿菊、牵牛花与向日葵等多种庭院观赏植物的混合花籽包。播撒在废弃废墟的花坛与阳台上，怒放的群芳不仅能引来珍贵的蜜蜂授粉，更是幸存者心中文明文明火种不熄的美学誓言。",
        en = "A mixed assortment of hardy annual and perennial flower seeds. Scattering these across ash-covered flowerbeds summons pollinating bees while blooming as vibrant living proof that beauty and hope endure beyond armageddon.",
    },
    ["seed_garlic"] = {
        zh = "由饱满干硬的大蒜瓣或顶生蒜珠构成的繁殖种蒜。深埋入土中度过严冬，来年能收获一头头辛辣冲鼻的白皮大蒜，不仅是提鲜去腥的烹饪灵魂，天然大蒜素更是不可多得的广谱抗菌生化盾牌。",
        en = "Cloves and bulbils of pungent winter garlic ready for trench planting. Overwintering beneath frost to emerge strong in spring, the harvested bulbs provide intense culinary zest and natural allicin antimicrobial defense.",
    },
    ["seed_garlic_clove"] = {
        zh = "分瓣完好且带根须的纯天然大蒜种瓣。埋进土里不仅能长出辛辣驱虫的绿蒜苗，收获的饱满大蒜头更是废土上天然的抗生素消炎药与炖煮变异怪肉的必备除腥神器。",
        en = "Firm cloves of seed garlic ready for autumn planting. Producing pungent shoots that deter insect pests, the harvested bulbs double as natural antibiotics and essential flavor maskers for dubious meats.",
    },
    ["seed_gherkin"] = {
        zh = "专为酸腌渍定制的迷你小黄瓜种子。结出的小黄瓜表面带有细密尖刺且果肉紧致不易发软，采摘后整根塞入莳萝与醋盐水中密封腌制，数周后便能开坛收获嘎嘣爽脆的顶级酸黄瓜配菜。",
        en = "Specialized seeds breeding bumpy, crisp miniature gherkin cucumbers. Highly resistant to going mushy, tossing these firm little pickles into dill-infused vinegar brine produces extraordinarily snappy accompaniments for fatty cured meats.",
    },
    ["seed_grapes"] = {
        zh = "从干瘪葡萄干或变异葡萄中剔出的硬质葡萄籽。搭起坚固的木制棚架任由葡萄藤攀爬蔓延，深秋结出的串串紫黑多汁浆果，不仅是解渴佳果，更是避难所重构手工酿酒工坊的希望之源。",
        en = "Hard little grape seeds collected from dried raisins and wild vine clusters. Climbing arbor trellises, their sweet autumn berries nourish thirsty wanderers while anchoring the revival of artisan bunker winemaking.",
    },
    ["seed_groundnut"] = {
        zh = "耐寒野生美国土豆豆芋的繁殖块茎种子。这种多年生蔓生植物在地下结出一串串宛如项链般的高蛋白坚果状块茎，煮熟后兼具马铃薯与坚果的软糯香甜，是荒野流浪求生的抗荒王牌。",
        en = "Tuberous propagation seeds of the hardy wild American groundnut. Forming long strings of high-protein underground tubers reminiscent of nutty potatoes, this native vine offers extraordinary famine insurance in scarred wilderness soils.",
    },
    ["seed_hops"] = {
        zh = "带有鲜活休眠芽点的啤酒花宿根根茎。顺着高大的绳索杆架攀援飞速生长，秋季盛开出散发着浓烈松香与柑橘苦香的黄绿色球果，是废土啤酒狂热者赋予自酿麦芽酒灵魂香气的核心原料。",
        en = "Vigorous underground hop rhizomes bearing dormant spring nodes. Climbing towering twine supports, the resulting aromatic cones pack essential alpha acids that preserve homebrewed ales while imparting crisp citrus bitterness.",
    },
    ["seed_horseradish"] = {
        zh = "生命力极其顽强霸道的辣根宿根种子。一旦埋入土中便会疯狂深扎地下，粗壮的主根刨出研磨成泥，能释放出直冲天灵盖的辛辣芥末冲劲，用来搭配油腻烤肉能瞬间逼退一切鼻塞与困意。",
        en = "Persistent root cuttings of wild horseradish that aggressively colonize soil beds. Grated into pungent white paste, the volatile mustard oils blast through nasal passages, providing fiery contrast for greasy campfire meats.",
    },
    ["seed_huckleberries"] = {
        zh = "生长在林地阴凉处的野生高丛越橘坚硬种子。长成的灌木结满酸甜适口的深蓝色野生浆果，无论是在巡逻间隙抓一把生嚼提神，还是拌入面粉烘烤浆果松饼，都是大自然无私的抗疲劳馈赠。",
        en = "Hard seeds of wild mountain huckleberries adapted to acidic forest shade. Bearing sweet tart blue fruits, handfuls eaten raw sustain weary scouting patrols while baking wonderfully into crumbly survival campfire scones.",
    },
    ["seed_japanese_knotweed"] = {
        zh = "生命力强悍到能穿透水泥裂缝的日本虎杖粗壮地下茎。在废墟中蔓延犹如绿色瘟疫，虽然成株木质化难以清除，但早春破土而出的鲜嫩红绿脆茎酸甜多汁，口感宛如大黄般生脆可口。",
        en = "Unstoppable rhizome cuttings of Japanese knotweed capable of cracking asphalt. While despised as an aggressive weed, its tender spring shoots offer a crunchy, sour-sweet flavor resembling rhubarb that enlivens survivor salads.",
    },
    ["seed_jerusalem_artichoke"] = {
        zh = "开着黄色小葵花且极度耐贫瘠的洋姜地下块茎。无需过多照料便能在废弃砖瓦土堆里疯狂疯长，秋末挖出的一串串凹凸不平的脆爽块茎，富含菊粉多糖，是生吃腌制两相宜的高产救命粮。",
        en = "Knobby tubers of the ultra-hardy Jerusalem artichoke sunflower. Thriving in gravelly rubble without fertilizer, these prolific roots yield crisp starchy tubers packed with prebiotic inulin that nourish battered digestive tracts.",
    },
    ["seed_kale"] = {
        zh = "抗冻耐寒的羽衣甘蓝十字花科蔬菜种子。起皱发卷的深绿叶片即使覆盖在皑皑白雪之下也依然生机盎然，微霜过后更是变得微甜多汁，是漫长寒冬废土中为数不多的常青维生素宝库。",
        en = "Cold-tolerant brassica seeds producing crinkled, nutrient-dense kale leaves. Braving heavy snow and frost without wilting, these frost-sweetened green ruffles supply vital iron and calcium when all other garden crops wither.",
    },
    ["seed_lentils"] = {
        zh = "一小罐干瘪扁平的农家小扁豆种子。耐旱耐瘠薄且储藏期极长，煮成浓稠的扁豆糊糊哪怕只撒一把粗盐，也是中东游牧幸存者在漫长迁徙途中最扎实的热量支柱。",
        en = "A mason jar filled with speckled dried lentil seeds. Drought-resistant and virtually non-perishable, simmering them with salt produces dense, fiber-rich porridge that fuels endless desert migrations.",
    },
    ["seed_lettuce"] = {
        zh = "细如柳絮的嫩脆生菜种子。生长周期极其短暂，只需短短数周浇水照料便能采收一捧捧鲜嫩翠绿的水灵菜叶，在终日以干硬军用压缩干粮为食的避难所里，它是最抚慰人心的舌尖清泉。",
        en = "Lightweight seeds of crisp garden lettuce that germinate rapidly. Yielding tender green foliage within a few short weeks, this fast-growing green brings refreshing hydration and civilized salad luxury to canned-ration survivors.",
    },
    ["seed_lotus"] = {
        zh = "外壳如铁甲般坚硬的椭圆莲子种坚果。寿命悠长甚至能在淤泥中沉睡千年，投入池塘淤泥深处能在水面撑开一把把碧绿莲叶与优雅荷花，是净化污染死水并提供地下莲藕的高洁水生作物。",
        en = "Hard-shelled lotus nuts famous for remaining viable across centuries of dormancy. Sunk into muddy pond bottoms, they raise umbrella-like leaves and fragrant blossoms, purifying stagnant wetland waters while growing crisp starchy roots.",
    },
    ["seed_lotus_boiled"] = {
        zh = "经过文火久煮直至彻底软烂粉糯的成熟莲子。剥去微苦的绿芯后散发着幽雅的荷香与甘甜，含在嘴里粉质细腻如栗子，既能迅速填补辘辘饥肠，也是调理心悸焦虑的传统食疗佳品。",
        en = "Tender lotus seeds simmered in pure water until soft and meal-like. Free of bitter embryonic sprouts, their delicate nutty texture soothes nervous indigestion while delivering clean plant carbohydrates to convalescing patients.",
    },
    ["seed_maianthemum_stellatum"] = {
        zh = "耐阴喜湿的多花黄精多年生野草种子。长成的植株在林下开满繁星般的白色小花，夏末结出的红色小浆果虽味道微苦，但其肥厚甘甜的地下根茎煮熟后是极佳的强健体魄荒野中药材。",
        en = "Forest-dwelling seeds of starry false Solomon's seal adapted to woodland loam. While bearing speckled summer berries, its thick nutritious rhizomes are boiled into sweet medicinal teas that fortify exhausted respiratory systems.",
    },
    ["seed_mayapple"] = {
        zh = "林下野生鬼臼的繁殖种子。在阴湿林地撑开伞状绿叶，夏末熟透掉落的金黄果实散发着热带水果般的浓郁甜香，但必须彻底成熟才能食用，全株其余部位均有剧毒，务必格外小心辨识。",
        en = "Seeds of the umbrella-leafed wild mayapple woodland plant. While unripe foliage and stems contain dangerous toxins, the fully ripened golden fruit offers an intensely sweet tropical pulp that delights knowledgeable forest gatherers.",
    },
    ["seed_melon"] = {
        zh = "网纹哈密瓜与甜瓜的扁平饱满种子。对阳光与温暖土壤有着极高要求，成功收获的橙黄果肉宛如蜜糖般多汁香甜，吃下一瓣能让人彻底忘却身处地狱般的末日，仿佛重回阳光普照的旧日夏日沙滩。",
        en = "Pale, flat cantaloupe seeds demanding warm soil and radiant sunshine. The resulting heavy netted melons burst with honeyed orange flesh, supplying heavenly hydration that makes survivors temporarily forget nuclear winters.",
    },
    ["seed_mugwort"] = {
        zh = "带有特殊浓烈草药香气的野生艾草微细种子。生命力顽强抗旱耐践踏，银绿色羽状叶片晒干揉碎不仅是驱逐蚊虫毒瘴的天然熏香，在营火旁灸烤穴位还能有效驱除关节风湿陈伤寒气。",
        en = "Aromatic wild mugwort seeds flourishing in barren soil and rubble cracks. Dried silvery leaves burn as insect-repelling smudge sticks, while steeped herbal infusions stimulate sluggish appetites and ease arthritic joint stiffness.",
    },
    ["seed_mulberries"] = {
        zh = "从深红到紫黑熟透桑椹中洗出的微小坚硬种子。长成的桑树枝繁叶茂，甘甜多汁的桑果能染紫整个手掌与嘴唇，繁茂的鲜嫩桑叶更是为定居点重新饲养蚕虫织造纯丝提供了独门可能。",
        en = "Tiny seeds gleaned from sweet wild mulberries. Growing into hardy deciduous trees, the abundant summer berries provide sweet syrup and juice, while their tender foliage sustains silkworms for revitalizing luxury textiles.",
    },
    ["seed_mushroom"] = {
        zh = "附着在潮湿纸板或灭菌谷物基质上的普通食用菌菌丝孢子。无需任何阳光照射，只要在避难所阴暗潮湿的地下室角落堆上腐殖土和烂木头，几天之内就能如雨后春笋般冒出一丛丛救命鲜菇。",
        en = "Microscopic fungal spores inoculated onto moist grain or cardboard mediums. Requiring zero sunlight in damp subterranean basement corners, they rapidly fruit into edible mushroom caps that convert dead organic rot into protein.",
    },
    ["seed_mushroom_morel"] = {
        zh = "珍稀野生羊肚菌的真菌孢子混合物。表面遍布蜂窝状凹坑的羊肚菌是大自然最昂贵的山珍，在林火烧焦的灰烬土壤中特别容易萌发，煮入野味汤中能激发出令人欲罢不能的极致鲜甜滋味。",
        en = "Prized spores of the elusive honeycomb morel mushroom. Thriving particularly across ash-strewn burn scars and moist forest hollows, simmering these earthy delicacies in wild game broths creates an intensely savory culinary masterpiece.",
    },
    ["seed_mustard"] = {
        zh = "细小圆润且带有强烈辣味的深黄色芥菜籽。种植能采收辛辣开胃的宽大芥菜叶，收获的干燥菜籽研磨调和醋与冷水，就能自制出冲鼻提神的黄芥末酱，给单调的避难所肉食注入灵魂。",
        en = "Tiny round mustard seeds packed with fiery sinigrin enzymes. The leafy greens provide spicy stir-fry fodder, while the ground seeds blend into sharp yellow mustard paste that cuts through greasy canned meats.",
    },
    ["seed_oats"] = {
        zh = "带着金黄硬壳的优质粮用燕麦种子。播种收获后压成燕麦片煮粥，浓稠黏滑的口感能极其温和地呵护脆弱的肠胃，是病患和伤员从生死线上康复的最佳滋补流质食物。",
        en = "Hulled oat seeds harvested from abandoned farming cooperatives. Processing them into rolled oats yields velvety porridge that gently soothes irritated stomachs of survivors recovering from sickness.",
    },
    ["seed_onion"] = {
        zh = "表面粗糙乌黑的球茎洋葱黑色小种子。从幼嫩的葱花绿苗一直到埋在地下的层叠辛辣球茎全都可以食用，耐储存且越放越甜，是废土乱炖中不可或缺的去腥提鲜第一功臣。",
        en = "Wrinkled black seeds of pungent bulb onions. Sown in early spring, they develop into thick, layer-packed aromatic bulbs that keep through winter cellars, forming the savory backbone for nearly every wasteland soup.",
    },
    ["seed_pea"] = {
        zh = "圆滚滚且表面略有皱皮的干豌豆种子。春季点播入土很快就能抽出鲜嫩的卷须龙须菜，成熟后晒干的干豌豆可以长期保存数年，随时抓一把扔进铁锅里熬出浓郁豆汤。",
        en = "Wrinkled dried garden pea seeds awaiting moist spring furrows. They produce tender shoots for fresh salads, while dried harvests keep for years to thicken savory campfire stews.",
    },
    ["seed_popcorn"] = {
        zh = "拥有极厚坚硬外壳的特种爆裂玉米种子。除了能够正常播种繁殖之外，抓一把扔进烧红的平底锅盖上盖子，噼里啪啦爆开的一碗雪白爆米花能让压抑的废土充满欢声笑语。",
        en = "Hard-shelled flint corn seeds specially bred for explosive popping. Beyond farming future crops, tossing a handful into a lidded skillet yields fluffy white popcorn that brightens gloomy shelter evenings.",
    },
    ["seed_poppy_bud"] = {
        zh = "从干燥罂粟蒴果中抖落的灰黑色微小籽粒。撒在自制面包表面能烘焙出独特的坚果香气，种植盛开出艳丽娇花结出乳汁，更是末日土制鸦片酊强效止痛镇静剂的关键原材料来源。",
        en = "Tiny slate-blue poppy seeds shaken from dried seed capsules. Imparting nutty crunch to baked breads, cultivating the delicate flowers produces latex sap that can be processed into crude analgesics for traumatic battle wounds.",
    },
    ["seed_potato_raw"] = {
        zh = "表面长出几颗紫色嫩芽的生马铃薯块茎。切块埋进松软的泥土里，几乎不需要复杂照料就能在地下收获一窝硕大块茎，是任何末日农业基地抵御大饥荒的绝对中流砥柱。",
        en = "Sprouting seed potatoes covered in purple eyes and dry loam. Sliced into sections and planted in loose earth, they multiply into mounds of hearty carbohydrates to conquer apocalyptic famines.",
    },
    ["seed_pumpkin"] = {
        zh = "饱满厚实的扁平奶油白色南瓜大种子。攀爬藤蔓在秋季能结出重达几十公斤的硕大橙红金瓜，厚实的瓜肉耐储藏且甘甜软糯，掏出的南瓜子在铁锅中炒香，更是高热量的极品追剧零食。",
        en = "Plump flat pumpkin seeds sprouting into sprawling vigorous vines. The resulting massive orange squash store safely in root cellars for months, while toasted salty seeds provide valuable zinc and healthy fats.",
    },
    ["seed_radish"] = {
        zh = "生长期极其迅速的红皮小水萝卜种子。只需两到三周时间浇水，便能从泥土里拔出一颗颗爽脆多汁、微带辛辣红玛瑙般的小萝卜，是初春菜园中最早带来新鲜活蔬菜喜悦的先锋作物。",
        en = "Fast-growing radish seeds capable of producing crisp crimson taproots within weeks. Slicing through their peppery, refreshing flesh brings immediate hydration and dietary crunch during the earliest barren weeks of spring.",
    },
    ["seed_raspberries"] = {
        zh = "从红润酸甜的覆盆子果实中淘洗出的微小硬核种子。带有细刺的灌木枝条能在营地四周筑起天然防线，盛夏枝头挂满的红彤彤空心小浆果，更是熬制酸甜果酱与酿造果醋的顶级浆果。",
        en = "Hard tiny seeds harvested from ripe red raspberries. Establishing tangled thorny thickets that deter unwanted trespassers, their fragile ruby fruits yield heavenly fruit jams and tangy vinegars that mask stale hardtack.",
    },
    ["seed_raw_bamboo"] = {
        zh = "几十年难得一遇、在竹林大面积开花枯死后遗留的珍稀竹米种子。一旦在水土丰茂之处萌芽扎根，几年内便能蔓延出一片郁郁葱葱的茂密竹林，为营地提供取之不尽的建筑材料与锋利竹矛。",
        en = "Rare grain seeds harvested during rare bamboo flowering cycles. Once rooted near wetlands, they establish fast-growing bamboo groves providing endless structural timber, weaving shoots, and lightweight lethal spear shafts.",
    },
    ["seed_raw_burdock"] = {
        zh = "长满倒刺球头、极易挂在裤腿与动物皮毛上的野生牛蒡种子。不要嫌弃它粘人烦躁，其深入地下近一米的新鲜主根富含菊糖与微量元素，切丝与胡萝卜同炒，口感脆嫩鲜美赛过珍馐。",
        en = "Hooked burdock seeds famous for clinging tenaciously to socks and dog fur. Beneath those annoying prickles lies a deep medicinal taproot that, when scrubbed and stir-fried, provides crunchy earthy nourishment.",
    },
    ["seed_raw_dandelion"] = {
        zh = "带有白色绒毛降落伞的蒲公英毛茸茸种子。风吹即走且在任何恶劣瓦砾砖缝中都能顽强生根，开出的金黄小花能酿酒，苦味幼叶富含铁与维生素，粗壮苦根烘焙后更是救命的解毒良药。",
        en = "Feathery parachute seeds of the ubiquitous wild dandelion. Colonizing scorched rubble with relentless vigor, its sunny yellow blooms yield wine, bitter leaves enrich salads, and roasted taproots brew detoxifying liver tonics.",
    },
    ["seed_red_winter_wheat"] = {
        zh = "深红色的高筋红冬小麦耐寒农作种子。秋天播种后能在厚厚的冰雪覆盖下顽强存活，来年盛夏翻滚的金黄麦浪能磨出洁白细腻的精粉，烤出久违的面包香气。",
        en = "Cold-hardy red winter wheat grains designed to germinate under autumn chills. Sleeping beneath blanket snows, they awaken to yield high-gluten flour for baking crusty, genuine loaves of bread.",
    },
    ["seed_rhubarb"] = {
        zh = "带有粗壮休眠侧芽的大黄地下肉质根茎。春天舒展出巨大的叶片，其红艳粗壮的酸爽叶柄切碎拌糖能烤出惊艳绝伦的酸甜大黄派，但千万牢记含有剧毒草酸的绿色大叶片绝对不能误食。",
        en = "Fleshy crowns of perennial garden rhubarb bearing crimson dormant buds. While its massive toxic leaves must be discarded, stewing the tart ruby stalks with sugar yields lip-smacking pies that revitalize exhausted scavengers.",
    },
    ["seed_rose"] = {
        zh = "从秋天饱满红艳的野生玫瑰果中剥出的带毛硬核种子。长成多刺的玫瑰灌木既能防御野兽翻越，花瓣能蒸馏出舒缓芳香的玫瑰纯露，富含维 C 的红果更是熬制抗感冒抗坏血病果茶的红宝石。",
        en = "Bristly seeds extracted from wild scarlet rosehips. Blooming into prickly defensive hedgerows, the fragrant petals perfume homemade salves, while dried autumn hips provide massive vitamin C doses to conquer winter sickness.",
    },
    ["seed_salsify_raw"] = {
        zh = "形如蒲公英降落伞的蒜叶婆罗门参细长羽状种子。随风飘荡在旷野草原上，收获的深长肉质根带着奇妙的生蚝鲜味，在灾变后的漫漫荒野里，是不可多得的伪野生海鲜风味根茎蔬菜。",
        en = "Slender tufted seeds of the wild oyster plant salsify. Drifting across grassy meadows, they burrow down to develop creamy taproots whose distinct shellfish flavor brings bizarre culinary sophistication to wasteland campfire pots.",
    },
    ["seed_spinach"] = {
        zh = "外表带有微小硬刺或圆滑外壳的深绿菠菜种子。极其耐寒且喜肥，初春播种便能收获大片柔嫩肥厚、富含铁质与叶绿素的翠绿菜叶，是让废土大力水手们重新长出健壮肌肉的绿色源泉。",
        en = "Hardy seeds of dark green garden spinach thriving in brisk chilly weather. Rapidly filling garden beds with tender iron-packed foliage, it revitalizes pale anemic survivors battling the aftermath of harsh winter sieges.",
    },
    ["seed_spurge"] = {
        zh = "耐旱大戟科肉质植物的坚硬种子。全株折断后会流出具有腐蚀性与强刺激性的白色有毒乳汁，虽然绝不能作为食物入口，但提炼其毒素能制作毒箭淬火液，或是用来配制强效杀虫灭鼠药剂。",
        en = "Tough seeds of wild spurge succulents that secrete caustic white sap. Strictly inedible due to blister-causing resins, processing this toxic milky latex creates potent vermin poisons and lethal coatings for hunting darts.",
    },
    ["seed_strawberries"] = {
        zh = "附着在鲜红熟透草莓外表皮上的微小金色种子粒。匍匐茎会在肥沃苗床上迅速四向蔓延，初夏结出的一颗颗多汁红心小草莓，每一口甜蜜都能让人感动得潸然泪下，重温童年草莓冰淇淋的幸福。",
        en = "Tiny golden seeds embedded along the skin of wild strawberries. Spreading across forest clearings with leafy runners, their fragrant summer berries bring intoxicating sweetness that evokes fond childhood ice cream memories.",
    },
    ["seed_sugar_beet"] = {
        zh = "带有粗糙木质化种皮的甜菜复合种子球。深埋在泥土中能膨大成重达数公斤的雪白圆锥形大块根，将其切丝水煮榨汁浓缩，能源源不断熬制出珍贵纯正的白糖与糖浆，是废土真正的甜味源泉。",
        en = "Rough multi-germ seed clusters of commercial white sugar beets. Swelling into massive conical roots rich in sucrose, boiling and refining the grated mash produces sweet crystalline syrup to replenish depleted sugar bowls.",
    },
    ["seed_sunflower"] = {
        zh = "带有黑白相间条纹的饱满向日葵坚果种子。盛夏能长出三四米高的粗壮花盘追逐骄阳，秋季低垂的大花盘结满数千粒葵花籽，不仅是香脆的零食，更是榨取清亮耐用食用植物油的高产支柱。",
        en = "Striped black-and-white seeds yielding towering sunflowers that follow the wasteland sun. Each enormous golden disc produces thousands of oil-rich seeds, feeding tired scouts or pressing into gallons of versatile cooking oil.",
    },
    ["seed_thyme"] = {
        zh = "极其细小的百里香多年生矮生芳香药草种子。长成贴地蔓延的密实小灌木，其细碎绿叶富含百里香酚天然抗菌成分，揉碎撒入炖肉中不仅去腥解腻，更能有效抑制肉类腐败变质并强健呼吸道。",
        en = "Microscopic seeds of low-growing garden thyme packed with thymol essential oils. Smothering garden edges in fragrant evergreen foliage, its pungent leaves season wild game stews while lending natural antibacterial protection.",
    },
    ["seed_tobacco"] = {
        zh = "微如尘埃的金黄色烟草细小种子。在温暖日光下能长出比芭蕉还宽阔的油亮大叶片，采摘阴干发酵切丝后卷成雪茄或装入烟斗，是废土集市上能换取武器弹药与硬通货的王牌经济作物。",
        en = "Dust-fine seeds that mature into broad, sticky tobacco leaves. Drying and fermenting these nicotine-rich leaves creates hand-rolled cigars and pipe shreds that command premium prices in cutthroat wasteland barter hubs.",
    },
    ["seed_tomato"] = {
        zh = "表面包裹着一层细滑绒毛的番茄蔬菜种子。搭架引蔓在盛夏会挂满如红玛瑙般沉甸甸的酸甜多汁大番茄，无论是生吃爆汁解渴、熬制浓稠番茄酱，还是搭配炒蛋，都是无可挑剔的菜园明珠。",
        en = "Fuzzy pale seeds of plump, vine-ripened tomatoes. Heavy with succulent red fruit through hot summer months, they supply the zesty acid foundation for rich pasta sauces, stews, and refreshing raw field snacks.",
    },
    ["seed_veggy_wild"] = {
        zh = "从各种可食用的杂草与野草上采摘捆扎的新鲜嫩茎扦插株。虽然外表杂乱无章难登大雅之堂，但只要随手插进避难所潮湿的泥土中，便能顽强生根发芽，为食不果腹的灾民提供无尽的原生态苦涩野菜。",
        en = "Hardy cut stems and root fragments of diverse wild edible weeds. Requiring zero greenhouse coddling, sticking these tenacious cuttings into moist soil produces reliable harvests of rustic bitter greens for starving camps.",
    },
    ["seed_watermelon"] = {
        zh = "光滑黑亮的水果之王——大西瓜扁平种子。夏日瓜藤爬满开阔沙地，结出的墨绿条纹大圆瓜一切两半鲜红多汁，在酷暑难耐且淡水紧缺的热浪中，一口冰凉甜瓜能让人舒服得连灵魂都直打颤。",
        en = "Smooth black teardrop seeds that sprawl into heavy watermelon vines. Slicing open crisp green rinds reveals gallons of icy, ruby-red hydration that rescues heat-exhausted wanderers from scorching apocalyptic heat waves.",
    },
    ["seed_weed"] = {
        zh = "坚硬灰褐色的精选工业与药用大麻种子。种植能收获极其坚韧耐磨的天然大麻植物纤维用于纺绳织布，其成熟雌花分泌的芳香树脂更是平复战后创伤应激障碍与剧烈神经痛的天然良药。",
        en = "Tough mottled seeds yielding fast-growing hemp and cannabis stalks. The fibrous stems strip into indestructible survival twine, while harvested resinous flower buds provide calming herbal relief from chronic neuropathic battle pain.",
    },
    ["seed_wheat"] = {
        zh = "最经典普通的面包小麦农作种子。承载着整个人类文明一万年农业辉煌的黄金麦粒，只要避难所还有未受污染的清泉与泥土，它就能在微风中重新铺展出人类生存的底气。",
        en = "Standard bread wheat seeds embodying ten millennia of agrarian civilization. As long as unpolluted soil and clean rain persist, scattering these golden grains promises that humanity will eat again.",
    },
    ["seed_wild_garlic"] = {
        zh = "生长在林地阴凉溪畔的野生熊葱与野蒜黑色小种子。早春萌发时整片林下都弥漫着浓郁诱人的蒜香，宽大的绿叶口感辛香柔嫩，全株均可食用，是唤醒冬眠后身体机能的春季第一补品。",
        en = "Pungent seeds of wild woodland ramps and bears' garlic. Carpeted along damp creek beds, the tender green leaves perfume the spring air with intoxicating allium zest, banishing winter lethargy with potent restorative sulfur compounds.",
    },
    ["seed_wild_herbs"] = {
        zh = "从野外采风收集而来的各种杂生芳香药用野草混合种子包。包含薄荷、欧夏至草与贯叶连翘等多种野生品种，播撒一捧便能收获一座微型草药园，为自制止血药水和清凉驱蚊油提供天然原料。",
        en = "An eclectic grab-bag of gathered wild medicinal herb seeds. Sowing this diverse mix creates a functional apothecary garden yielding wild mint, feverfew, and horehound for compounding fever teas and healing wound poultices.",
    },
    ["seed_wild_rice"] = {
        zh = "细长坚硬且带有长芒的深棕色野生菰米湿地谷物种子。必须播撒在清浅流动的水洼、浅滩湖湾与沼泽泥潭中，秋季长出的高大菰禾结满富含蛋白质与矿物质的坚果香黑米，是荒野水域的大粮仓。",
        en = "Slender awned grains of aquatic wild rice adapted to northern lake shallows. Thriving in marsh silt, harvesting the dark nutty grains provides exceptionally clean protein and starch to sustain nomadic canoeing scavengers.",
    },
    ["seed_wild_sarsaparilla"] = {
        zh = "林间野生洋菝葜的多年生匍匐灌木种子。长成的植株在林下结出深色小浆果，其芳香扑鼻的地下匍匐根茎洗净煎熬，能释放出天然根汁汽水般的甜美草本风味，是调理肠胃的古法养生热饮配方。",
        en = "Hard seeds of wild sarsaparilla thriving in shaded northern forests. Simmering its creeping aromatic roots extracts sweet, earthy compounds reminiscent of old-fashioned root beers, soothing inflamed joints and sour stomachs.",
    },
    ["seed_wildcarrot"] = {
        zh = "开着伞状蕾丝白花的野胡萝卜野生祖先刺毛种子。采收其幼嫩的白色细长主根有着浓郁奔放的胡萝卜与芹菜复合香气，虽然口感略硬纤维粗，但在荒山野岭中是补充碳水化合物的坚固救命草。",
        en = "Spiny clinging seeds of wild Queen Anne's lace or ancestor carrots. While their wiry white taproots are woodier than domestic carrots, simmering them tender provides clean root starches during desperate foraged treks.",
    },
    ["seed_wintergreen"] = {
        zh = "耐寒常绿的林地矮生冬青小灌木种子。贴地生长的厚实革质绿叶散发着极其清凉提神的冬青油水杨酸甲酯香气，咀嚼一片不仅能让口臭全消提神醒脑，还能缓解牙痛与头痛困扰。",
        en = "Tiny seeds of low-growing evergreen wintergreen shrubs. Nibbling the leathery leaves releases pleasant methyl salicylate oils that freshen stale bunker breath while acting as natural aspirin to dull nagging toothaches.",
    },
    ["seed_zucchini"] = {
        zh = "扁平乳白色的美洲西葫芦蔬菜种子。以极其霸道恐怖的结瓜爆发力闻名于世，只需两三株健壮植株，盛夏结出的绿皮嫩瓜就会多到让你、你的狗以及整个避难所同伴吃到怀疑人生的疯狂地步。",
        en = "Flat, ivory seeds of the absurdly prolific summer zucchini squash. Planting just two mounds yields such overwhelming avalanches of glossy green squash that your entire bunker community will plead for a meat ration reprieve.",
    },
    ["self_monitoring_module"] = {
        zh = "集成在高科技自动化设备内部的精密自诊断状态传感器模块。能够毫秒级监测母机内部电路短路、轴承磨损与过热风险，是机械师检修高级动力装甲与修复战损机器人时不可替代的核心传感单元。",
        en = "A sophisticated diagnostic telemetry module salvaged from advanced automated machinery. Continuously probing circuitry continuity, bearing friction, and thermal spikes, it enables precise maintenance for powered exosuits and combat drones.",
    },
    ["selfbow"] = {
        zh = "用一整根坚韧原木削磨成型、没有任何层压复合结构的纯手工简易单体弓。虽然拉感生硬且威力不及现代复合滑轮弓，但悄无声息的致命箭矢让它成为废土猎人在无声暗杀变异怪物时的极佳利刃。",
        en = "A primitive single-piece stave bow carved patiently from a solid branch of seasoned hardwood. While lacking modern pulley cams, its near-silent arrow releases silently harvest mutant game without alerting nearby undead sentries.",
    },
    ["senet"] = {
        zh = "重现古埃及三十格棋盘与象牙质感棋子的古老塞尼特棋套装。在数千年前曾陪伴法老度过漫漫长夜，在核冬天摇曳微弱的蜡烛微光下，推演棋子通往来世的旅途能让焦躁的灵魂重归永恒与宁静。",
        en = "An ancient Egyptian Senet board game crafted with thirty checkered squares and symbolic tokens. Guiding pawns through mythological trials across candlelit tables calms claustrophobic bunker dread with timeless antiquarian contemplation.",
    },
    ["sensor_module"] = {
        zh = "将光学红外摄像头、热成像镜头与微波多普勒雷达高度集成的多光谱传感器阵列。能够瞬间洞穿伸手不见五指的暴风雪与浓重迷雾，精准锁定数百米开外潜行生物的微弱心跳与体温红外信号。",
        en = "A multi-spectral sensor cluster combining infrared thermography, optical cameras, and Doppler radar. Peering effortlessly through blinding blizzards and noxious smoke, it pinpoints hidden bio-signatures across barren perimeters with clinical accuracy.",
    },
    ["serum_learning"] = {
        zh = "标有“76x-数据”的湛蓝半透明基因血清。注射后能让大脑神经突触飞速重组放电，使求知欲与学习能力暴涨，代价则是偶尔出现目空一切的机械狂妄幻觉。",
        en = "A sealed cryo-ampule containing shimmering blue liquid labeled '76x-Lore'. Flooding neural synapses with accelerated plasticity, it exponentially supercharges learning speed at the minor expense of grandiose android-like megalomania.",
    },
    ["serum_night_operations"] = {
        zh = "代号“09x-阿那克西曼德”的漆黑半透明改造血清。注入后能重塑视网膜感光细胞，让黑夜在视野中如白昼般清晰明亮，使你化身为夜间狩猎的无声幽灵。",
        en = "An obsidian-hued biochemical serum sealed within a light-proof ampule labeled '09x-Anaximander'. Mutating retinal rod photoreceptors to perceive night as day, it converts daytime survivors into lethal, silent nocturnal apex predators.",
    },
    ["serum_regen"] = {
        zh = "代号“48x-洛库图斯”的乳白半透明细胞修复血清。注射能在体内唤醒超常愈合能力，让严重骨折与撕裂伤飞速收口结痂，宛如经历机械同化般重获新生。",
        en = "A milky semi-translucent hyper-regenerative compound marked '48x-Locutus'. Accelerating cellular mitosis to terrifying speeds, it knits shattered bones and gaping lacerations back together as if assimilation protocols were restoring damaged hulls.",
    },
    ["serum_resilience"] = {
        zh = "标有“16x-阿穆斯”的灰褐半透明神秘血清。推入静脉后能让结缔组织与表皮硬化如护甲，大幅降低钝器撞击撕裂与辐射穿透伤害，带来无情顽强的抗性。",
        en = "A murky grayish serum ampule cryptically designated '16x-Armus'. Densifying subcutaneous tissues and bone structure with resilient organic matrices, it shrugs off blunt impacts and radiation hazards with pitiless, spiteful endurance.",
    },
    ["serum_speed"] = {
        zh = "标签印有“51x-兰德鲁”的金黄色半透明高能神经兴奋血清。注射后犹如全身电路被接通千万伏特高压，肌肉收缩速度与反射弧被强行压缩到非人微秒级极限，让你在枪林弹雨间穿梭如金色闪电。",
        en = "A radiant amber stimulant fluid stamped '51x-Landru'. Overclocking neuromotor pathways into high-frequency overdrive, it tightens physical reflex loops until bullets seem to crawl through air while you sprint with blistering haste.",
    },
    ["serum_super_soldier"] = {
        zh = "标有“29x-努尼恩”的鲜红半透明超级战士强化血清。注入后能强行改写端粒酶与肌肉肌纤维密度，赋予受试者压倒性的怪力与残暴侵略性，宛如唤醒了潜伏在基因深处的基因暴君灵魂。",
        en = "A crimson translucent mutagenic ampule stamped '29x-Noonien'. Rewriting muscular density and metabolic endurance into superhuman proportions, it grants ferocious physical dominance accompanied by chilling, tyrannical megalomania.",
    },
    ["service_medal"] = {
        zh = "以红白蓝绶带悬挂、铸有荣誉军徽的铜质服役勋章。曾代表着军人保家卫国的无上荣光，如今在避难所集市上，其厚实的黄铜分量被小贩拿来当砝码，偶尔换得半块发硬的面包。",
        en = "A stamped bronze military service medal dangling from a faded tri-color ribbon. Once commemorating patriotic sacrifice in forgotten conflicts, this tarnished relic now serves as an accurate brass counterweight in trading posts.",
    },
    ["sewermap"] = {
        zh = "印在防水油纸上的旧城区地下排污与雨水管网工程蓝图。上面标明了深邃的主干管道、溢流闸门与维修竖井出口，是拾荒者在地面被尸群围攻时潜入暗无天日地下世界的逃生秘道指南。",
        en = "An architectural blueprint detailing subterranean storm drainage and sewage networks. Marking overflow sluices and maintenance manholes, it guides desperate survivors seeking subterranean passage beneath horde-infested surface streets.",
    },
    ["sewing_kit"] = {
        zh = "装满细针和五彩线轴的塑料小盒。它能把破损的军用防弹背心缝补得服服帖帖，但前提是你在拔出针头时千万别手抖——在杂草丛生的废土泥地里找掉落的绣花针，比赤手空拳单挑尸王还要让人绝望。",
        en = "A compact plastic box containing tiny needles and colorful thread spools. Capable of reinforcing armored vests, provided you never drop a needle into the dead grass. Searching for a fallen needle in wasteland mud is substantially more agonizing than facing a zombie horde.",
    },
    ["sewing_machine"] = {
        zh = "配有铸铁飞轮与踏板连杆机构的古董脚踏机械缝纫机。无需丝毫电力驱动，飞针走线间能轻而易举穿透坚韧帆布与厚实皮革，是营地裁缝将破烂碎布重构成耐磨防具的高效利器。",
        en = "An antique treadle sewing machine powered by cast-iron foot pedals and flywheels. Requiring zero electricity, its rhythmic needle effortlessly punches through heavy canvas and leather to tailor durable post-apocalyptic armor.",
    },
    ["sextant"] = {
        zh = "采用抛光黄铜精制而成的高精度航海反射六分仪。配有微调游标刻度弧与精密分划目镜，在卫星导航全数瘫痪的后末日世界，仰望星空测算日月地平夹角是远征队永不迷航的硬核基石。",
        en = "An exquisite brass navigational sextant equipped with precision vernier mirrors and optics. With orbital GPS constellations long dead, sighting celestial stars against the horizon provides indispensable navigation for cross-continental wanderers.",
    },
    ["sextoy"] = {
        zh = "由亲肤硅胶与微型振动电机组装而成的旧时代成人玩具。在满目疮痍、道德沦丧的残酷废土上显得尤为荒诞，拆下内部的微型偏心电机与高密度锂电池，是极佳的自制爆炸引信配件。",
        en = "A skin-safe silicone adult novelty fitted with an internal vibration motor. While absurdly out of place amid ruins, stripping its rechargeable lithium cell and eccentric motor yields fantastic components for crafting improvised triggers.",
    },
    ["sf_watch"] = {
        zh = "采用蓝宝石水晶镜面与十八 K 金表壳的奢华机械名表。无论外界如何风云变幻，精密的瑞士擒纵机构依然滴答不息，在废土商贾眼中，它是能换取重机枪与装甲车皮的终极财富象征。",
        en = "A luxury mechanical wristwatch boasting eighteen-karat gold and a scratch-proof sapphire crystal. Ticking with immaculate Swiss precision amid ruins, this ostentatious status symbol commands entire armories at frontier trading posts.",
    },
    ["shark_plushie"] = {
        zh = "风靡旧世界商场的蓝色大白鲨毛绒毛绒玩具公仔。那双呆萌无辜的大眼睛与软绵绵的怀抱，能给予精神崩溃边缘的幸存者无限的心灵治愈，是无数废土流浪汉在寒夜里死死抱住的精神支柱。",
        en = "A famous blue plush shark doll stuffed with soft synthetic polyester down. Its harmless wide-eyed expression and huggable softness bring miraculous psychological comfort to traumatized wastelanders shivering through desolate nights.",
    },
    ["shark_suit"] = {
        zh = "由成千上万个微型不锈钢环密密麻麻手工铆接而成的防鲨潜水锁子甲。虽然沉重且穿脱繁琐，但其绝佳的抗撕咬防刺穿性能，能让扑上来的变异丧尸利齿瞬间咬崩牙齿、无功而返。",
        en = "A full-body diving mesh suit woven from thousands of interlocking stainless steel chain rings. Heavy and cumbersome, its bite-proof weave causes snapping zombie jaws to shatter harmlessly against impenetrable metallic mesh.",
    },
    ["shark_suit_faraday"] = {
        zh = "在防鲨锁子甲外层额外铺设了高导电闭合网孔的法拉第笼防护潜水服。不仅彻底免疫尖牙利爪的近身撕咬，还能将致命的高压电击与变异放电怪物的球状闪电瞬间导入大地，毫发无损。",
        en = "A specialized chainmail sharksuit lined with continuous conductive bonding to form a mobile Faraday cage. Deflecting both razor teeth and lethal high-voltage discharges, it allows operators to shrug off electrical shocks unharmed.",
    },
    ["sharp_rebar"] = {
        zh = "在砂轮上将一端斜切打磨出冰冷锋芒的粗壮建筑螺纹钢筋。沉重坚硬且带有螺旋抓握防滑纹，双手合力凶猛突刺，能凭借巨大的重力势能硬生生凿穿废土重甲掠夺者的胸膛。",
        en = "A heavy ribbed construction rebar ground to an angled chisel point upon concrete. Boasting punishing heft and grippy ridges, driving this brutal metal stake two-handed punches straight through makeshift raider breastplates.",
    },
    ["sharp_rock"] = {
        zh = "带有极其锋利贝壳状断口的坚硬燧石或石英碎块。大自然鬼斧神工的古老刀刃，从人类茹毛饮血的石器时代起就是生存利器，无论是切割动物皮肉还是削制尖锐木矛，都简单可靠。",
        en = "A dense chunk of fractured flint boasting razor-sharp conchoidal edges. The primordial cutting tool of prehistoric humanity, this stone slice carves raw meat and whittles sharp spears when refined steel tools are unavailable.",
    },
    ["sharp_toothbrush"] = {
        zh = "在水泥地面上反复磨削塑料柄端、打磨出致命三角尖头的自制牙刷匕首。轻巧无声且完全不含任何金属成分，能轻易躲过金属探测门扫描，是暗室偷袭与近身抹喉的经典阴暗凶器。",
        en = "A plastic toothbrush handle filed down against rough concrete into a lethal triangular point. Completely invisible to metal detectors, this classic improvised shiv delivers swift, silent punctured jugulars in narrow prison hallways.",
    },
    ["sharpened_pipe"] = {
        zh = "将报废镀锌自来水铁管一端切削出倾斜刺尖的简易刺杀长矛。中空结构兼顾了刚性与自重，不仅能保持安全距离戳穿丧尸眼窝，插在拒马障碍物上更是阻挡尸潮冲击的血肉栅栏。",
        en = "A length of galvanized plumbing pipe cut diagonally to form a vicious hollow spearhead. Light enough to thrust with reach while retaining bludgeoning rigidity, it pierces zombie skulls from behind safe barbed barricades.",
    },
    ["sharpener"] = {
        zh = "配有一枚微型高硬度刀片的小巧塑料儿童卷笔刀。虽然本意是用来切削铅笔木屑，但在大灾变中拆下那枚薄如蝉翼的微型锋利刀片，是制作简易剃刀、解剖显微样本或排脓切口的微型手术刀。",
        en = "A tiny plastic pencil sharpener mounting a miniature high-carbon razor blade. Salvaging that paper-thin cutting edge yields a razor-sharp scalpel substitute ideal for lancing boils or shaving fine wooden ignition shavings.",
    },
    ["sharps"] = {
        zh = "复刻十九世纪经典工艺的夏普斯重型后膛落锤步枪。发射大威力全尺寸黑火药铅弹，枪机下落闭锁沉重可靠，其恐怖的远距离停止作用能像重锤般把正面冲锋的变异巨兽一枪放倒。",
        en = "A faithful reproduction of the classic falling-block Sharps 1874 buffalo rifle. Firing massive heavy-caliber lead slugs, its thunderous black-powder discharge hits charging abominations with the freight-train kinetic shock of bygone frontiers.",
    },
    ["shavingkit"] = {
        zh = "包含老式双面安全刮胡刀、猪鬃剃须刷与一盒备用刀片的男士剃须套装。在这个满脸污垢与寄生虫横行的末世，仔仔细细刮净胡须不仅关乎尊严，更能确保防毒面具橡胶贴面绝对气密严实。",
        en = "A classic wet-shaving kit packed with a double-edge razor, bristle brush, and spare blades. Scraping away filthy beard stubble restores civilized self-respect while guaranteeing airtight rubber seals on lifesaving gas masks.",
    },
    ["shears"] = {
        zh = "配有超长厚重杠杆手柄与宽大刀刃的重型金属修枝大剪刀。沉重的剪切力道能像切纸一样斩断粗壮树枝、带刺铁丝网以及顽固锁链，挥舞起来也是令人闻风丧胆的近战碎骨兵刃。",
        en = "Heavy-duty bypass shears fitted with long steel handles for maximum mechanical leverage. Effortlessly snipping through thick branches and rusted chainlink fences, snapping these blades shut makes a terrifying sound during close-quarters encounters.",
    },
    ["sheath"] = {
        zh = "配有快速解脱搭扣与大腿固定弹力带的战术硬皮直刀鞘。无论在烂泥中翻滚还是在瓦砾堆中狂奔，都能死死锁住刀身不脱落，出刀内衬顺滑无声，是突击队员随身利刃的最佳巢穴。",
        en = "A molded leather combat knife sheath secured by quick-release snaps and thigh retention straps. Keeping large blades anchored flush against the leg during frantic sprints, it enables instantaneous, silent draws under pressure.",
    },
    ["sheath_birchbark"] = {
        zh = "用几层新鲜白色桦树皮精巧编织而成的传统腰挂小刀鞘。树皮富含天然防腐防水树脂，质地轻盈且永不生锈霉变，在林间潜伏涉水时能妥善保护高碳钢小刀免受潮气锈蚀侵害。",
        en = "A rustic knife sheath woven from layers of flexible white birchbark. Naturally waterproof and resin-infused, this traditional bushcraft holster protects high-carbon blades from damp decay while weighing next to nothing on your belt.",
    },
    ["shed_snakeskin"] = {
        zh = "变异小蛇在灌木丛蜕皮遗留下的半透明干燥角质蛇蜕。带有细密整齐的六角鳞片纹理，质地脆弱而干爽，碾碎后是炼制传统止痒药膏的偏方成分，也是附近有潜伏毒蛇的警戒信号。",
        en = "A translucent papery skin shed by a molting serpent among dry brush. Brittle and patterned with delicate hexagonal scales, grinding it into ointment soothes inflamed skin while signaling dangerous venomous serpents nearby.",
    },
    ["shed_snakeskin_big"] = {
        zh = "从体型庞大的变异大蟒身上脱落的完整半透明长蛇蜕。长度足有数米，角质层坚韧且带有淡淡的腥臊气味，揉搓浸油后能充当天然防水密封皮膜，警告着丛林中有巨兽出没。",
        en = "A massive molted skin cast off by an oversized constrictor snake. Measuring meters in length with surprisingly tough keratin texture, treating it with grease yields flexible waterproof sheeting for lining pack flaps.",
    },
    ["shed_snakeskin_giant"] = {
        zh = "犹如巨型卡车车厢般骇人的庞大变异巨蟒干枯蜕皮。鳞片坚硬如甲胄残片，散发着令人汗毛倒竖的掠食者威压，将其剥下不仅能缝制大批防水皮甲，更能让人对未知的巨型怪兽敬畏三分。",
        en = "A terrifyingly vast shed snakeskin left behind by a truly titanic mutant serpent. Hard as cuirass armor and reeking of apex predator musk, harvesting these scales yields enough flexible material to armor whole scouting squads.",
    },
    ["shed_snakeskin_little"] = {
        zh = "一条纤细小蛇在石缝间蜕下的小片蛇皮残片。阳光下泛着微弱的彩虹珍珠光泽，虽然由于面积太小做不成皮具，但随手放进药罐里研磨成粉，能为土制止血粉增添一丝神秘的生化药效。",
        en = "A petite shedding cast off by a juvenile garden snake. Glistening with faint iridescence in the sun, this gossamer-thin scrap is too delicate for apparel but adds valuable organic minerals to apothecary healing salves.",
    },
    ["shed_snakeskin_scales"] = {
        zh = "从巨型变异蛇蜕上剥落下来的一叠坚硬角质鳞片。每一片都有手掌大小，质地柔韧且耐磨抗穿刺，钻孔后用铜丝串连缝合，能轻松打造出一套轻便贴身且防御利爪撕咬的鳞甲护胸。",
        en = "Palm-sized keratin scales detached from colossal reptilian moltings. Lightweight, puncture-resistant, and remarkably flexible, punching holes and riveting them over boiled leather crafts an exceptionally protective scale cuirass against slashing claws.",
    },
    ["shed_stick"] = {
        zh = "由光滑硬木精心削磨而成的织布分纱棒。边缘光滑圆润绝不挂伤纤细经纱，在原始织布机上手工挑起经线开辟梭道，是废土织女将粗纺棉麻线编织成紧密布料的传统灵魂工具。",
        en = "A polished hardwood shed stick carved with smooth tapered bevels. Gliding effortlessly through loom warps to separate yarn sheds, it facilitates rhythmic, snag-free weaving when transforming hand-spun yarn into wearable woven yardage.",
    },
    ["sheet"] = {
        zh = "从民宅卧室搜刮来的大尺寸纯棉家用床单。洗涤后质地柔软吸汗，除了铺在木板床上当被单外，随手撕开就是几十条现成的无菌应急包扎绷带，或是绑在绳上充当临时降落伞和搬运吊床。",
        en = "A large cotton bedsheet reclaimed from suburban linen closets. Clean and comfortable, it serves as cozy bunk bedding, tears into dozens of sterile emergency bandages, or knot-ties into a heavy-duty casualty drag hammock.",
    },
    ["sheet_aluminum"] = {
        zh = "表面平整光滑、厚度适中的工业级纯铝薄板。重量极其轻巧且易于使用铁皮剪修剪弯折，既不会生锈腐蚀，又能轻松敲打成防雨挡风罩、改装车挡泥板或轻质工具箱外壳。",
        en = "A versatile flat sheet of structural aluminum alloy. Lightweight and effortlessly sheared with tin snips, it bends into aerodynamic fairings, rust-free vehicle splash guards, and custom scavenged toolbox liners.",
    },
    ["sheet_aluminum_small"] = {
        zh = "一小块切边平整的耐腐蚀轻质铝薄板。尺寸如同书本大小，方便塞入工具包随身携带，是现场给受损排气管打补丁、制作简易风门挡片或是冲压小垫片的得力修理补丁原材。",
        en = "A handheld swatch of malleable sheet aluminum. Slipping easily into field rucksacks, this handy scrap is perfect for riveting patches over cracked exhaust headers, crafting carburetor shims, or forming custom brackets.",
    },
    ["sheet_canvas"] = {
        zh = "由粗亚麻或重磅纯棉经纬紧密交织而成的大块重型帆布。质地厚重且防风防泼水，是构筑野外生存庇护所帐篷、缝制重负荷行军背囊与加固卡车车厢篷布的无可替代的强韧织物。",
        en = "A wide, heavy-duty expanse of tightly woven cotton-linen canvas. Weather-resistant and nearly tear-proof, it serves as the foundational material for pitching durable field tents, stitching heavy rucksacks, and covering trailer cargos.",
    },
    ["sheet_canvas_patchwork"] = {
        zh = "用各种不同颜色与磨损程度的帆布碎料、通过粗麻线紧密拼缝成的大张拼布帆布。虽然布面斑驳如百衲衣，但双重加固的针脚赋予了其惊人的抗撕拉韧性，是废土手艺人的实用主义杰作。",
        en = "A broad patchwork tarp meticulously assembled from colorful salvaged canvas offcuts. Though resembling a ragged mosaic, double-stitched overlapping seams grant rugged tensile strength capable of withstanding howling stormy winds.",
    },
    ["sheet_cotton"] = {
        zh = "一整匹由天然纯棉纺织而成的透气吸湿棉布面料。触感舒适亲肤且不起静电，是为避难所居民缝制内衣裤、贴身衬衫以及制作医疗消毒纱布的最基础也最紧缺的生活织物资产。",
        en = "A generous bolt of breathable, natural woven cotton fabric. Hypoallergenic and gentle against scarred skin, it forms the irreplaceable foundation for tailoring comfortable base layers, clean shirts, and sterile surgical dressings.",
    },
    ["sheet_cotton_patchwork"] = {
        zh = "将无数块五颜六色的废旧纯棉衣服碎片手工拼缝在一起的花布大面料。充满质朴温情的拼接图案在死寂废土中散发着家的回忆，无论是做成温暖的拼布棉被还是窗帘，都让人倍感安心。",
        en = "A charming patchwork sheet sewn from dozens of mismatched scrap cotton rags. Radiating nostalgic home warmth across dim bunker quarters, this quilted textile serves as cozy bedspread insulation or morale-boosting window drapes.",
    },
    ["sheet_denim"] = {
        zh = "由高密度斜纹织法编织而成的大块坚韧纯棉牛仔布面料。经典的深蓝色表面经久耐磨，抗刮蹭防穿刺，是缝制结实耐用的工装裤、耐磨防滑手套以及防荆棘护腿套的最佳硬派布料。",
        en = "A large expanse of heavy-gauge twill indigo denim fabric. Renowned for timeless abrasion resistance and structural density, this rugged weave tailors indestructible chore jackets, work dungarees, and bramble-proof trail gaiters.",
    },
    ["sheet_denim_patchwork"] = {
        zh = "用十几条破损牛仔裤裤腿与口袋拼接缝合而成的大幅牛仔拼布面料。多重重叠的牛仔布料厚重如甲胄，虽然重量沉甸甸，但在地面摸爬滚打时能提供无与伦比的耐磨与防石子擦伤防护。",
        en = "A rugged patchwork sheet constructed from recycled work pants and denim jacket remnants. Heavy and stiff with reinforced triple-stitching, it delivers unbeatable protection against scraping gravel and thorny brush crawls.",
    },
    ["sheet_faux_fur"] = {
        zh = "表面覆有厚密蓬松人造化纤绒毛的大块仿毛皮面料。无需伤害任何珍稀野生动物便能享有极佳的保温锁热效果，且不怕水洗与虫蛀，是缝制极寒冬衣内胆与保暖毛毯的现代化人造暖炉。",
        en = "A generous swath of plush synthetic faux-fur fabric backed by knit mesh. Providing superb loft and thermal trapping without harming wildlife, it resists rot and washes clean, lining winter heavy parkas reliably.",
    },
    ["sheet_faux_fur_patchwork"] = {
        zh = "由各种长短毛色各异的人造毛皮碎料手工拼接而成的花斑拼布面料。花哨古怪的外表下隐藏着扎实的保暖实力，裹在身上犹如披着一件魔幻异兽皮草，是废土流浪汉抵御严冬风雪的暖心披肩。",
        en = "A wild patchwork sheet pieced together from variegated synthetic fur offcuts. Looking delightfully bizarre yet insulating with ferocious efficiency, it wraps freezing wanderers like a mythical beast's pelt against zero-degree freezes.",
    },
    ["sheet_felt"] = {
        zh = "经高温高压湿热揉搓紧密缩绒而成的一整块厚实致密毛毡面料。不散边且防风吸震，剪裁后无需锁边即可直接使用，是制作保暖雪地靴内胆、隔音密封条以及枪械缓冲垫板的万能材料。",
        en = "A dense sheet of non-woven compressed wool felt. Requiring no sewn hems thanks to its interlocking fiber matrix, it cuts cleanly into warm boot liners, acoustic soundproofing panels, and vibration-dampening machine gaskets.",
    },
    ["sheet_felt_patchwork"] = {
        zh = "由多块回收的废旧毛毡碎片缝合压制而成的大张拼布毛毡。色彩深浅不一且质地敦厚坚实，铺在冰冷的铁皮车厢内壁不仅能大幅削减发动机轰鸣噪音，还能有效阻止刺骨寒气向室内渗透。",
        en = "A sturdy patchwork sheet quilted from reclaimed felt trimmings. Delivering exceptional thermal insulation and acoustic deadening, lining vehicle hulls with this mat deadens engine clatter while keeping cabins toasty warm.",
    },
    ["sheet_fur_patchwork"] = {
        zh = "把兔皮、鹿皮与野狼毛皮等不同天然真皮毛边角料悉心拼接鞣制的大幅毛皮拼布。散发着狂野的原始荒原气息，厚重的天然针毛与绒毛交织，是废土旷野部落首领专属的御寒奢华大氅原料。",
        en = "A massive patchwork mantle pieced together from tanned wolf, deer, and rabbit pelts. Reeking of primal wilderness, the layered animal furs provide legendary warmth fit for clan chieftains navigating brutal arctic tundras.",
    },
    ["sheet_kevlar"] = {
        zh = "由高纯度芳纶聚合纤维经纬编织成的大张黄色凯夫拉防弹面料。同等重量下强度达到钢铁的五倍，具有惊人的抗撕裂抗劈砍与吸收高速弹片冲击波的性能，是自制战术防弹背心的核心灵魂。",
        en = "A wide golden sheet of woven high-strength aramid Kevlar. Five times stronger than structural steel on an equal-weight basis, it absorbs bullet impacts and deflects knife slashes when stitched into plate carrier sleeves.",
    },
    ["sheet_kevlar_layered"] = {
        zh = "由数十层黄色芳纶布通过高压树脂致密层叠固化而成的军规防弹复合板。厚重紧实且坚硬如木板，能依靠层间形变瞬间化解手枪子弹与致命手雷破片的动能撕裂，是真正的随身护命铁壁。",
        en = "A multi-ply laminated panel constructed from heat-pressed aramid plies impregnated with ballistic resin. Dissipating projectile kinetic energy through progressive layer deformation, it stops handgun rounds and shrapnel cold.",
    },
    ["sheet_kevlar_patchwork"] = {
        zh = "从各处报废防弹头盔与碎裂防弹背心内衬上拆解回收、重新拼接缝合的拼布凯夫拉面料。虽然防弹连续性有所折损，但缝入防刺服内层依然能为幸存者抵御丧尸利爪与锐器背刺的凶险偷袭。",
        en = "A patchwork sheet cobbled together from reclaimed ballistic vest fragments. While lacking the integrity of virgin armor plates, it still offers phenomenal slash resistance when stitched into lightweight stealth garments.",
    },
    ["sheet_leather"] = {
        zh = "整张经植物单宁酸或铬鞣工艺精心鞣制而成的大块坚韧熟牛皮面料。表面油润光滑，兼具卓越的耐磨、防风与抗穿刺性能，是手工缝制厚底军靴、重甲皮衣以及坚固枪套马鞍的顶级原料。",
        en = "A magnificent whole hide of vegetable-tanned bovine leather. Supple yet rugged, its impenetrable grain shields against driving rain, windburn, and sharp briars, forming the premier stock for crafting fine boots and holsters.",
    },
    ["sheet_leather_patchwork"] = {
        zh = "用不同质感、深浅棕色的碎皮革边料手工冲孔穿绳缝缀成的大张拼接皮革面料。粗犷原始的缝合线犹如废土战甲的战痕徽记，虽显斑驳古旧，但在抵御变异野兽撕咬与石块撞击时格外抗造。",
        en = "A heavy patchwork hide stitched from mismatched scraps of brown and black leather. Its rugged lacing resembles gladiator armor, providing brutal abrasion protection against rocky scrambles and ferocious beast bites.",
    },
    ["sheet_lycra"] = {
        zh = "具备惊人四向回弹拉伸延展性能的合成聚氨酯氨纶面料。轻薄贴身、吸湿排汗且速干无痕，是剪裁运动紧身衣、关节减震固定绷带以及防风面罩等贴身装备的现代化高科技高弹性织物。",
        en = "A smooth, four-way stretch synthetic Lycra fabric bolt. Yielding exceptional recovery without restricting athletic mobility, this high-tech textile tailors form-fitting compression garments, thermal hoods, and joint retention bands.",
    },
    ["sheet_lycra_patchwork"] = {
        zh = "将多种不同颜色图案的废旧运动紧身裤碎片拼接缝合的拼布氨纶面料。色彩斑斓且极具弹性张力，尽管拼缝接头较多，但在制作透气贴身的防尘头套或弹性护肘护膝套时依然发挥着奇效。",
        en = "A colorful elastic sheet pieced together from athletic compression garments. While displaying erratic neon seams, its stretchy breathability adapts perfectly into flexible dust masks and snug limb support wraps.",
    },
    ["sheet_metal"] = {
        zh = "大尺寸的标准工业冷轧低碳钢薄钢板。质地坚硬平整，在废土焊工手中能通过电焊与铆钉拼接成坚不可摧的末日改装装甲车防弹防撞板，或是焊死避难所大门窗户构筑起防御要塞。",
        en = "A wide standard sheet of cold-rolled industrial mild steel. Rigid and weldable, metalworkers transform this plate into reinforced armored vehicle cladding, window blast shutters, and spike-studded fortress barricades.",
    },
    ["sheet_metal_small"] = {
        zh = "大约电脑机箱侧盖大小的便携式低碳钢小铁板。轻便耐砸且硬度适中，无需吊车即可单人搬运操作，适合在越野车轮胎外侧补焊防刮挡板，或是作为壁炉台下垫防燃屑的安全防火铁皮板。",
        en = "A compact rectangle of mild steel plate easy to maneuver single-handedly. Ideal for welding quick fender patches on off-road rigs or lining stove hearths to catch errant sparks, it remains an essential workshop staple.",
    },
    ["sheet_neoprene"] = {
        zh = "一整块带有微孔闭孔海绵结构的黑色合成氯丁橡胶大面料。百分之百防水且兼具极佳的隔热保暖与抗震缓冲弹性，是剪裁潜水服、密封舱门防漏气密封胶条以及水壶保温套的无上神料。",
        en = "A continuous sheet of foamed black closed-cell neoprene rubber. Completely waterproof and thermally insulating, it shapes into custom diving suits, shockproof laptop cases, and airtight vehicle hatch gaskets.",
    },
    ["sheet_neoprene_patchwork"] = {
        zh = "用废弃潜水服与冲浪防寒衣的橡胶碎块通过专用胶水粘接缝合的拼布氯丁橡胶面料。虽然外观如同拼图般杂乱，但优良的防水抗震性能丝毫不减，是制作防水防潮靴套与护膝垫的实用好料。",
        en = "A patchwork panel cemented together from scrap diving suit segments. Retaining resilient waterproof cushioning despite jigsaw seams, it fashions water-resistant overshoes and impact-absorbing knee pads for scavenging damp basements.",
    },
    ["sheet_nomex"] = {
        zh = "由高科技耐高温阻燃芳纶纤维织造而成的整块诺梅克斯面料。遇到熊熊烈火时不会燃烧也不会熔融滴落，而是迅速碳化形成隔热屏障，是缝制赛车服、消防防爆斗篷与特战手套的顶级防火布。",
        en = "An expansive bolt of specialized high-temperature flame-resistant Nomex cloth. Refusing to ignite or melt in ferocious infernos, it insulates firefighters and combat operators against blazing backdrafts and chemical fires.",
    },
    ["sheet_nomex_patchwork"] = {
        zh = "从各处烧损报废的消防服与飞行员夹克上剥离拼缝而成的拼布诺梅克斯面料。虽布满熏黑烟渍与粗糙缝线，但其骨子里的防明火性能依旧可靠，是废土防爆破拆突击队员最后的保命防火布衣。",
        en = "A patched together sheet salvaged from singed firefighting gear and flight suits. Though charred and scuffed, its inherent fireproof qualities remain intact, shielding scrappy engineers during fiery breaching operations.",
    },
    ["sheet_nylon"] = {
        zh = "采用现代合成高分子纤维紧密梭织而成的大张尼龙面料。轻薄强韧且具备出色的抗拉伸耐磨损特性，遇水速干不易霉烂，是裁切缝制冲锋衣、防雨披风与轻量化背包的理想化纤材料。",
        en = "A wide bolt of lightweight, tightly woven synthetic nylon fabric. Highly tensile, abrasion-resistant, and quick to shed moisture, it serves as the premier modern textile for tailoring rain parkas and ultralight backpacks.",
    },
    ["sheet_nylon_patchwork"] = {
        zh = "由破损帐篷、破雨伞与废弃尼龙背包拼接缝合的大块化纤拼布面料。轻质坚韧且具有良好挡风能力，虽然各色拼块显得滑稽杂乱，但在荒野中拉开搭建临时避雨天幕却表现得极其可靠实用。",
        en = "A patchwork sheet sewn from shredded umbrellas, damaged tents, and nylon straps. Though displaying a chaotic collage of neon synthetic swatches, its water-shedding resilience makes a dependable makeshift rainfly in wild storms.",
    },
    ["shelter_kit"] = {
        zh = "装在紧凑便携包内的全套预制轻便简易棚屋构件。包含轻质铝合金支柱、防风拉绳、地钉与防撕裂防水篷布，只需几分钟快速拼接，便能在荒凉旷野上凭空搭建起一座遮风挡雨的庇护营地。",
        en = "A portable emergency kit containing pre-cut aluminum poles, guy lines, and heavy-duty stormproof tarps. Snapping together in mere minutes, it erects an instant weather-resistant bivouac shelter across windswept wasteland terrain.",
    },
    ["sherry"] = {
        zh = "产自古老酒庄、经过独特开花发酵与木桶陈酿的加强型雪利葡萄酒。酒体呈现深邃的琥珀光泽，散发着烘烤核桃、干无花果与海风般的浓郁坚果甜香，小酌一口能让人瞬间忘却周围的残垣断壁。",
        en = "A fortified amber wine aged through solera barrels into complex, nutty perfection. Exuding aromatic dried fig, toasted walnut, and briny ocean notes, a refined glass provides transcendental warmth against desolate concrete ruins.",
    },
    ["shield_visor"] = {
        zh = "采用高透光防弹聚碳酸酯注塑成型的战术防暴头盔面罩。能够有效抵御飞溅的碎石流弹、强酸黏液以及暴徒投掷的自制燃烧瓶火焰，为幸存者脆弱的面庞筑起一道清晰透明的安全屏障。",
        en = "A thick, optical-grade polycarbonate visor engineered for riot suppression helmets. Shrugging off blunt brick impacts, caustic chemical spatters, and incendiary flares, it keeps your eyes and facial profile intact behind clear armor.",
    },
    ["shillelagh"] = {
        zh = "由质地极其坚硬致密的黑刺李木精心熏烤制成的传统爱尔兰手杖木槌。顶端带有天然膨大的坚实树瘤，既能优雅地充当散步手杖，挥舞起来其凶暴的钝击势能也能轻易砸碎任何丧尸的颅骨。",
        en = "A traditional Irish shillelagh fire-hardened from dense blackthorn root wood. Finished with an intimidating natural root-burl clubhead, this elegant gentleman's walking stick doubles as a skull-shattering bludgeon in tight scuffles.",
    },
    ["shillelagh_fake"] = {
        zh = "用廉价中空松木车削、刷上黑漆冒充高档黑刺李木的旅游纪念品小木槌。质地轻飘且极其松脆，敲在硬木上都会当场开裂，在生死攸关的废土遭遇战中挥击两下就会碎成两截引人发笑。",
        en = "A tourist souvenir shillelagh lathe-turned from brittle painted softwood. Hollow and deceptively light, bringing this flimsy knockoff down onto an armored skull results in comic wooden splinters rather than incapacitating trauma.",
    },
    ["shillelagh_weighted"] = {
        zh = "在木槌顶端树瘤空腔内浇铸了熔融重铅的致命配重木槌。重心的极度前倾赋予了其毁天灭地的挥击冲击力，沉重的一击宛如挥动战锤，能将戴着防暴头盔的敌方掠夺者颈椎当场震断砸塌。",
        en = "A lethal blackthorn stick whose hollowed clubhead has been packed with dense poured lead. Shifting mass forward with brutal kinetic momentum, a clean two-handed swing crumbles reinforced riot helmets and crushes bone effortlessly.",
    },
    ["shirt_straw"] = {
        zh = "用晒干的野生草叶与植物纤维紧密编织而成的纯天然草衣。虽然质地扎人且摩擦皮肤容易发痒，但在烈日炙烤下通风凉爽，散发着原始的田园干草香气，是缺乏棉麻布料时的应急遮羞衣衫。",
        en = "A rustic sleeveless shirt woven from dried prairie grass and wild reeds. Prickling bare skin with scratchy fibers, it nonetheless offers breezy solar shade and rustic modesty when civilized woven garments are completely nonexistent.",
    },
    ["shock_epee"] = {
        zh = "在锋利重剑护手内侧改装了高压电容与锂电池的电击重剑。刺中目标的瞬间爆发出耀眼的淡蓝电弧，高压电流瞬间麻痹肌肉神经，让狂暴扑杀的丧尸当场抽搐倒地。",
        en = "A modified fencing épée wired to a high-voltage discharge capacitor in the bell guard. Thrusting the needle point discharges shocking currents that paralyze ferocious monsters in mid-stride.",
    },
    ["shock_foil"] = {
        zh = "带有高频电击触点的花剑改装武器。极其柔韧纤细的剑身如毒蛇吐信，剑尖轻点即可释放出令人麻痹的数万伏特电压，让击剑比赛的优雅点刺变成了致命的防身电刑。",
        en = "A lightweight foil retrofitted with stun electrodes along its flexible blade. Whipping forward with blinding agility, touch taps deliver painful electric shocks that stagger hostile marauders during duels.",
    },
    ["shock_sabre"] = {
        zh = "剑身通电改装的电击马术佩剑。沿着长刀刃铺设了绝缘电极导线，顺势劈砍不仅能造成严重的割裂伤，附带的高压电击更是能将丧尸的神经系统瞬间烧毁瘫痪。",
        en = "A slashing fencing saber wired with insulated conductive rails along the spine. Sweeping cuts deliver vicious lacerations accompanied by blinding arcs of current that lock enemy nervous systems instantly.",
    },
    ["shock_staff"] = {
        zh = "装有内置高压放电线圈与微型锂电池电极的战术防暴长棍。双手握持挥舞范围极大，棍端在触及目标瞬间能释放数万伏特脉冲强电弧，让狂暴的变异猛兽在痛苦哀鸣与痉挛中瞬间瘫软倒地。",
        en = "A reinforced tactical quarterstaff outfitted with high-voltage stun capacitors at its tips. Delivering broad two-handed sweeping control alongside bone-numbing electric discharges, it drops charging mutant predators in spasming heaps.",
    },
    ["shocktonfa_off"] = {
        zh = "处于待机断电状态的战术防暴电击拐。坚固的合金骨架与侧握把设计兼顾了格挡利刃与快速旋击能力，内部电池与升压电路静默待命，是警卫人员进退自如的近距离攻防防暴兵刃。",
        en = "An unpowered riot-control tonfa forged from rigid aircraft alloy with a perpendicular handle. Excellent for spinning strikes and forearm parries, its deactivated high-voltage capacitors wait silently for the flip of a thumb switch.",
    },
    ["shocktonfa_on"] = {
        zh = "已经开启主开关、电极间噼啪跳跃着蓝色耀眼电弧的战术拐。每一次横扫格挡与侧向突击都附带高压电击麻痹效果，让任何胆敢近身搏击的持刀暴徒在剧烈电击抽搐中当场弃械投降。",
        en = "A live tactical tonfa crackling with blinding blue electric arcs along its striking surface. Parrying strikes while simultaneously electrocuting assailants with high-amp shocks, it turns close-quarters grappling into an overwhelming dominance display.",
    },
    ["shoes_birchbark"] = {
        zh = "由柔韧白桦树皮多层交叉编织而成的古老传统桦树皮鞋。质地极为轻巧且散发着木质清香，在林地中潜行能大幅降低脚步声响，只要不穿着它趟过深水烂泥，就是一双舒服省力的天然草鞋。",
        en = "Traditional folk footwear woven from flexible interwoven strips of peeled birchbark. Exceptionally light and whisper-quiet across woodland leaf litter, they cushion nomadic feet well provided you avoid soaking them in muddy bogs.",
    },
    ["shoes_bowling"] = {
        zh = "带有特殊光滑硬质皮底的红蓝拼色复古保龄球鞋。光滑的鞋底专为保龄球馆木地板滑步助投设计，穿在废土湿滑青苔水泥地面上奔跑犹如踩上香蕉皮，稍不留神就会摔出个四脚朝天。",
        en = "Retro leather bowling shoes sporting smooth, untextured sliding soles. Perfect for polished bowling lane approaches, sprinting across wet rubble or mossy concrete in these slick shoes guarantees spectacular, face-first cartoon wipeouts.",
    },
    ["shoes_denim"] = {
        zh = "采用坚韧牛仔布缝制鞋面、配以防滑橡胶大底的手工运动帆布鞋。耐磨透气且易于洗涤晾干，朴实无华的深蓝鞋面伴随着废土长途跋涉逐渐泛白，是每位流浪探索者忠实可靠的贴地足下伴侣。",
        en = "Handcrafted low-top sneakers featuring durable denim canvas uppers vulcanized to rubber soles. Breathable, easily washed, and wearing into handsome faded battle scars, they cushion endless miles across cracked interstate highways.",
    },
    ["shogi"] = {
        zh = "刻有汉字铭文的五角形木质将棋棋子与木盘套装。独树一帜的打入规则能将俘获的敌方棋子收为己用，在漫漫避难所长夜里，推演运筹帷幄的棋局是训练幸存者战术大局观的绝佳智力训练。",
        en = "A classic Japanese Shogi set featuring pentagonal wooden tiles carved with kanji. The unique mechanic of deploying captured opposing pieces as your own keeps tactical minds razor-sharp through long, claustrophobic winter vigils.",
    },
    ["sholster"] = {
        zh = "采用硬质低摩擦工程聚合物热成型注塑的竞技级快拔枪套。带有微倾竞技角度与磁吸定位导槽，手指扣动锁扣瞬间便能顺滑无阻拔枪出膛，让快枪手在毫秒之争的遭遇战中占尽生死先机。",
        en = "A molded competition Kydex fast-draw holster engineered for zero friction. Featuring flared mouth funnels and tension adjustments, it allows lightning-quick firearm presentations that let quick-draw gunslingers shoot first during split-second wasteland ambushes.",
    },
    ["short_dress"] = {
        zh = "一条大灾变前随处可见的棉质印花短连衣裙。质地轻薄透气且没有任何护甲防御可言，但在闷热难耐的废土盛夏午后穿在身上，清凉舒服得让人忘却外面的无尽杀戮。",
        en = "A pre-war patterned cotton sundress salvaged from a bedroom closet. Offering zero armor against ravenous jaws, its airy drape brings refreshing respite during sweltering summer scavenging expeditions.",
    },
    ["short_dress_sleeved"] = {
        zh = "带有短袖剪裁的淑女风纯棉短裙。虽然在与变异荆棘灌木刮擦时毫无抵抗力，但干爽柔顺的面料能让你在避难所难得的休息日里彻底换下笨重肮脏的金属铠甲。",
        en = "A tailored short-sleeved cotton dress designed for casual pre-war social outings. Slipping into its soft fabric offers therapeutic psychological relief from wearing sweat-soaked combat harnesses day after day.",
    },
    ["shortbow"] = {
        zh = "弓身短小紧凑、两端带有反曲弧度的轻便传统短弓。非常适合在密林灌木丛或狭窄建筑物走廊中机动回旋，虽然极限射程不及长弓，但快速搭箭连射的射速能让扑来的野兽瞬间变成刺猬。",
        en = "A compact, recurved traditional short bow designed for maneuvering through dense foliage. While lacking the extreme range of heavy longbows, its rapid draw cycle peppers leaping mutant predators with rapid arrows in tight corridors.",
    },
    ["shorts"] = {
        zh = "剪裁过膝的休闲纯棉轻便短裤。在酷暑难耐的盛夏提供极佳的通风排汗性能，虽然将小腿与膝盖毫无防备地暴露在荆棘与丧尸抓伤威胁之下，但在烈日暴晒长途跋涉时确实凉爽无比。",
        en = "Basic casual cotton shorts tailored above the knees. Sacrificing shin protection against thorny brambles and grabbing undead fingers, they grant glorious leg ventilation that keeps core body temperatures cool during scorching heat waves.",
    },
    ["shorts_cargo"] = {
        zh = "大腿两侧缝有超大立体风琴褶收纳口袋的硬核军规工装短裤。结实耐磨且储物空间极其充沛，能随手塞下几个备用弹匣、止血带与半盒火柴，是废土拾荒者最青睐的随身杂物收纳裤装。",
        en = "Rugged utility cargo shorts loaded with bellowed flap pockets down both thighs. Swallowing spare magazines, rolled bandages, and loose batteries with ease, they remain the beloved uniform of practical post-apocalyptic scavengers.",
    },
    ["shorts_denim"] = {
        zh = "用旧牛仔长裤粗暴剪短并带有毛边的经典牛仔短裤。耐磨结实且活动自如，虽然小腿毫无保护容易被蚊虫叮咬，但那种粗犷不羁的末日废土朋克范儿直接拉满。",
        en = "Denim work pants roughly hacked off above the knees with fraying hemlines. Tough, flexible, and utterly iconic, they withstand rough handling while keeping you cool on sunbaked highway patrols.",
    },
    ["shot_00"] = {
        zh = "装填有八到九颗大型淬火硬铅弹丸的 12 号标准双零鹿弹。近距离轰击下能爆发出毁灭性的散布覆盖面积，密集的重型弹丸如重拳般撕碎防弹衣并粉碎骨骼，是狭窄走廊清场的绝对王者。",
        en = "Standard 12-gauge 00 buckshot shells packing nine hardened lead pellets. Detonating with ferocious close-range muzzle energy, the devastating shotgun cone shreds flesh and shatters skeletal structures in narrow hallway firefights.",
    },
    ["shot_beanbag"] = {
        zh = "装填有致密铅砂软布袋的 12 号低致命防暴动能弹。击中人体瞬间能以巨大的钝击动能造成剧烈淤青与剧痛休克，既能瞬间放倒狂暴的掠夺者，又不会像真铅弹那样造成不可逆的开膛破肚。",
        en = "A less-lethal 12-gauge cartridge firing a lead-shot-filled fabric beanbag. Striking targets with tremendous blunt kinetic shock, it knocks unruly rioters flat on their backs with broken ribs rather than fatal perforations.",
    },
    ["shot_bird"] = {
        zh = "装填数百颗细小微型铅砂颗粒的 12 号轻量化猎鸟霰弹。弹丸密集如暴雨但在远距离穿透力极其微弱，适合用来捕猎受惊飞起的野鸭与野鸡，或是对着扑上来的蜂群与小飞虫来上一记大面积覆盖。",
        en = "Light 12-gauge shells loaded with hundreds of tiny lead birdshot pellets. Expanding into a massive swarm pattern, it cleanly harvests flying waterfowl while functioning as an effective exterminator against buzzing mutant swarms.",
    },
    ["shot_dragon"] = {
        zh = "原厂军规级十二号龙息高能燃烧霰弹。击发时从枪口轰出长达五米的炫目镁铝白炽烈火，不仅能把迎面的尸群化为火海，那耀眼的强光更是能瞬间晃瞎周围所有的夜行动物。",
        en = "Factory-grade 12-gauge dragon breath incendiary shells packed with zirconium flakes. Erupting into a roaring five-meter cone of blinding fire, it immolates approaching zombie swarms like a pocket sun.",
    },
    ["shot_flechette"] = {
        zh = "弹体内塞满了数十枚细长带尾翼微型淬火钢飞镖的特种战术霰弹。击发后钢镖如暴风般尖啸呼啸而出，在丛林密叶中能轻易穿透灌木与轻掩体，将躲藏其后的敌人钉在树干之上。",
        en = "A specialized tactical 12-gauge shell packed with dozens of fin-stabilized steel darts. Whistling downrange in high-velocity clusters, these piercing flechettes slice cleanly through dense foliage and light wooden cover to impale targets.",
    },
    ["shot_glass"] = {
        zh = "用厚底透明玻璃压铸而成的标准单盎司烈酒小酒杯。杯壁坚厚耐碰，在废土吧台上倒上一杯高度蒸馏烈酒一口闷下，烈火烧喉的快感能让哪怕最疲惫的战士重新燃起活下去的勇气。",
        en = "A thick-bottomed one-ounce glassware tumbler built to endure boisterous tavern thumps. Tossing back raw distilled moonshine from this heavy glass numbs battle fatigue, warming cold bones before the next perimeter rotation.",
    },
    ["shot_hull"] = {
        zh = "已经击发空掉的 12 号高强度聚乙烯塑料霰弹空弹壳。带有金属底火座与卷边痕迹，只要底火座未开裂，拾荒者就能重新压入新底火、装填黑火药与碎铁屑，手工复装成致命弹药。",
        en = "A spent plastic 12-gauge shotgun hull fitted with a brass head base. Undamaged by firing, reloading survivalists eagerly collect these empty hulls to press fresh primers, black powder, and scrap iron into homemade shells.",
    },
    ["shot_scrap"] = {
        zh = "在塑料弹壳里塞满生锈铁钉、螺母与碎铁丝的粗制复装霰弹。击发时枪管里喷出一蓬乱七八糟的致命破片金属风暴，十步之内把毫无护甲的狂暴敌人打得血肉模糊。",
        en = "Improvised 12-gauge shells crammed with clipped nails, ball bearings, and wire fragments. The chaotic spread acts like a handheld claymore mine, turning close-quarters doorways into shredded meat grinders.",
    },
    ["shot_slug"] = {
        zh = "重达一盎司、带有螺旋导流槽的实心纯铅独头霰弹。将霰弹枪全部威力浓缩在一颗巨大金属弹头中，出膛后能在百米范围内一击轰穿轻型装甲车钢板与巨型突变异种的厚重颅骨。",
        en = "A heavy one-ounce rifled lead slug loaded into a 12-gauge shell. Concentrating all shotgun kinetic payload into a single crushing projectile, it punches straight through vehicle doors and obliterates armored mutant brutes at distance.",
    },
    ["shot_speedloader6"] = {
        zh = "能预装 6 发 12 号霰弹的快速管状装弹器。对准泵动或半自动霰弹枪弹仓装弹口向前猛力一推，六发散弹便在半秒钟内瞬间灌满弹仓，是霰弹枪手在激战间隙完成闪电续航的神级利器。",
        en = "A tubular six-round speedloader designed for rapid shotgun tube reloads. Aligned against the receiver loading gate, a single forward push chambers six heavy shells simultaneously, cutting reloading downtime to a mere fraction.",
    },
    ["shot_speedloader8"] = {
        zh = "足足可容纳 8 发霰弹的加长竞技型快速装弹管。在激烈遭遇战中只需单手精准卡位推挤，整整八枚重磅弹药便如行云流水般送入弹仓，让你的火力网绝不因繁琐的逐颗塞弹而发生停滞。",
        en = "An extended eight-round tubular magazine speedloader built for IPSC shotgun competitors. Dumping eight cartridges into the feed tube in a single fluid shove, it keeps heavy scatterguns perpetually primed to repel overwhelming undead assaults.",
    },
    ["shot_suppressor"] = {
        zh = "内部装有多室膨胀挡板与尼龙导轨的重型 12 号霰弹枪消音器。虽然体积沉重如一根消声砖头，但能将震耳欲聋的霰弹轰鸣大幅削减为沉闷的机械碰撞声，避免在开火瞬间招引来全城尸潮。",
        en = "A massive box-type suppressor engineered to tame chaotic 12-gauge muzzle blasts. Dampening thunderous scattergun explosions down to manageable mechanical thuds, it allows perimeter clearing without attracting wandering regional hordes.",
    },
    ["shotbelt_20"] = {
        zh = "由弹力帆布环与加固织带制成的可装填 20 发霰弹的便携弹链带。斜挂在胸前或系在腰间犹如全副武装的重装突击兵，随手一抽即可快速摸到子弹，在战火纷飞的突击战中提供充足弹药补给。",
        en = "A heavy nylon bandolier belt fitted with twenty elastic shotshell retention loops. Slung across the chest pancho-style, it keeps devastating buckshot rounds resting immediately at your fingertips during intense, moving firefights.",
    },
    ["shotgun_d"] = {
        zh = "拥有双联并排或上下排列枪管的经典折管式双管霰弹枪。结构极其质朴纯粹，掰开枪管一览无余，双击扳机能瞬间喷射出两股致命的铅弹风暴，是末日自卫中最皮实可靠的护院神兵。",
        en = "A classic break-action double-barreled shotgun featuring twin steel barrels. Immune to feeding jams thanks to its simple mechanical lock, unleashing both barrels simultaneously delivers unmatched point-blank kinetic devastation.",
    },
    ["shotgun_primer"] = {
        zh = "带有独立砧桥与击发药杯的标准 209 规格霰弹火帽底火。极其敏感的微型火药击发单元，被撞针撞击瞬间便能喷射出灼热火花引燃主装药，是废土手工复装各种霰弹的绝对核心点火源泉。",
        en = "Standard 209-type battery-cup primers designed specifically for shotshell reloading. Emitting an intense, instantaneous ignition flame upon firing pin impact, these tiny metallic cups are the indispensable spark resurrecting spent hulls.",
    },
    ["shotgun_s"] = {
        zh = "采用单发折开式装填机构的最基础单管猎枪。虽然每次击发后都必须手动掰开枪膛退壳并重新塞入一发弹药，但极低廉的成本与近乎零故障的纯机械结构，让它成为流浪拾荒者的第一把大口径护身火器。",
        en = "An inexpensive break-action single-barrel utility shotgun. Requiring deliberate manual reloading after every shot, its absolute mechanical simplicity and dirt-cheap maintenance make it a beloved starter weapon for hard-luck wanderers.",
    },
    ["shotgun_trap"] = {
        zh = "利用绊线、弹簧触发扳机与固定铁架改装而成的霰弹枪陷阱装置。隐蔽架设在走廊转角或营地隐秘入口，任何不速之客一旦绊动钢丝，黑洞洞的枪口便会瞬间喷出致命的双零鹿弹将其撕碎。",
        en = "A lethal perimeter tripwire device rigged to a fixed shotgun receiver. Concealed within dark doorways or narrow forest paths, tripping the taut wire pulls the trigger to unleash point-blank buckshot into unsuspecting intruders.",
    },
    ["shotgun_triple"] = {
        zh = "极为罕见的三根枪管组合装配的德式三管钻猎霰弹枪。巧夺天工的机械击发机构能让射手在极短时间内依次倾泻三发沉重的 12 号弹药，兼顾了传统双管枪的稳定与三连击的毁天灭地爆发力。",
        en = "A rare handcrafted triple-barrel drilling shotgun combining three steel barrels upon a single receiver. Allowing three devastating shotgun blasts in rapid succession, it bridges the gap between classic double-guns and frantic repeating firepower.",
    },
    ["shoulder_holster"] = {
        zh = "采用皮革背带交叉固定在双肩下方的便携式腋下枪套系统。不仅能将手枪完美隐藏在夹克或风衣内侧，还能在驾驶车辆或伏卧射击时提供毫无阻碍的顺手拔枪角度，尽显老派侦探干练风范。",
        en = "A leather shoulder rig featuring crisscrossing harness straps that suspend a pistol beneath the armpit. Concealing heavy handguns under duster coats, it allows unencumbered draws while seated in cramped vehicle cockpits.",
    },
    ["shoulder_strap"] = {
        zh = "配有快速调节滑扣与金属挂钩的多功能战术枪背带。能在几秒钟内收紧枪支紧贴胸前便于双手攀爬，或是放松背带将长枪瞬间甩至射击姿态，是长途携带沉重武器的减负神器。",
        en = "A durable nylon weapon sling fitted with quick-adjust cam buckles and swivel clips. Tightening firmly against the chest for hands-free climbing or extending instantly into a ready stance, it relieves shoulder fatigue during endless patrols.",
    },
    ["shoulder_strap_front"] = {
        zh = "经过快速调整处于胸前低姿待命状态的战术枪背带配置。枪托稳稳搭在胸前，枪口朝下，能在遭遇突发险情时以最短运动弧线将步枪举至目镜前射击，是突击队攻坚搜索的标准持枪姿态。",
        en = "An adjustable weapon sling cinched into an aggressive front-carry tactical configuration. Keeping the long arm centered across the chest, it enables lightning transitions from idle marching to aimed shoulder fire in milliseconds.",
    },
    ["shoulder_strap_simple"] = {
        zh = "采用质朴纯纯帆布或皮革带制成的基础两点式步枪背带。没有繁琐的滑扣机构，两端直接系在枪托与枪管前背带环上，简简单单地挂在肩头，便能让你在跋山涉水时彻底解放双手。",
        en = "A classic two-point rifle sling stitched from durable canvas webbing with simple attachment loops. Free of complicated tactical hardware, it slung across a shoulder reliably frees both hands for climbing or foraging.",
    },
    ["shovel"] = {
        zh = "配有坚固木柄与经过淬火锻造的弧形铁锹头重型铁锹。不仅是挖掘堑壕、构筑掩体防线与挖掘地窖的工程神器，其带有锋利边缘的钢锹头抡打起来也是能削飞丧尸半个脑壳的近战凶器。",
        en = "A sturdy trenching spade featuring a forged steel blade mounted on a solid ash shaft. Indispensable for digging defensive slit trenches and pit traps, swinging its sharpened steel edge equally cleaves through zombie necks.",
    },
    ["shovel_snow"] = {
        zh = "配有超大面积弧形钢板铲头的坚固重型金属除雪铲。能在寒冬暴雪过后迅速推开堵塞营地大门与道路的积雪，沉重的全金属结构在铲除坚硬冰层时格外有力，挥舞砸人也颇有威力。",
        en = "A broad-bladed steel snow shovel designed for clearing deep drifts from defensive perimeters. Reinforced with a wear-strip leading edge, it chops through packed winter ice while doubling as an unwieldy bludgeon.",
    },
    ["shovel_snow_plastic"] = {
        zh = "采用高韧性抗冻工程塑料注塑成型的宽板家用除雪铲。重量轻巧便于快速推雪作业，但在对付冻得像石头的陈年坚冰时极易崩裂破损，千万别妄想指望拿它去硬磕变异怪物的坚硬脑门。",
        en = "A lightweight scoop shovel molded from frost-resistant orange polymer with an aluminum handle. Great for shifting fresh powdery snow off roofs, striking solid ice or armored skulls snaps the plastic scoop with comical ease.",
    },
    ["shrapnel"] = {
        zh = "在剧烈高爆轰鸣中被炸裂撕扯出的带锯齿金属不规则弹片。边缘薄如剃刀且扭曲翻卷，带着灼热与狂暴动能飞溅，即便只是从废墟弹坑中捡起的残片，也是土制破片手雷的最佳杀伤装填物。",
        en = "Jagged, razor-edged steel shards blasted from detonated artillery shells. Twisted and scorched by infernal heat, gathering these lethal metal fragments provides ideal fragmentation filler for compounding homemade pipe bombs.",
    },
    ["shredded_rubber"] = {
        zh = "用大型机械粉碎机将废旧汽车轮胎撕碎成的一大堆细小橡胶碎颗粒。富有弹性且防水阻燃，既能铺设在靶场后方充当吸收流弹的吸能缓冲层，也是重新硫化浇铸自制实心轮胎的基础原材料。",
        en = "Crumbed rubber pellets processed from shredded automobile tires. Bouncy, waterproof, and chemically resilient, this granular recycled rubber serves as impact-absorbing backstop bedding or vulcanizing stock for casting solid cart tires.",
    },
    ["shrink_wrap"] = {
        zh = "缠绕在硬纸芯上的一整大卷高韧性聚乙烯塑料热缩膜。用火烤热便能紧密收缩包裹物体，无论是将多件散碎物资紧密捆扎成防水防尘货包，还是给破裂车窗封上一层防雨薄膜都极其神速便利。",
        en = "A substantial roll of flexible polyethylene heat-shrink packaging film. Shrinking tightly when warmed with hot air or campfire glow, it bundles loose cargo into weatherproof packages or seals cracked greenhouse panes seamlessly.",
    },
    ["shuttlecock"] = {
        zh = "由十六根天然鹅毛插在软木底托上制成的羽毛球。在末世阳光洒满的废弃网球场上打上一场羽毛球对决，看着轻盈的羽球在空中优雅翻飞，能让劫后余生的幸存者找回身为人最纯粹的运动欢愉。",
        en = "A genuine feather shuttlecock ringed with sixteen goose feathers rooted in a cork base. Batting this buoyant projectile back and forth across overgrown court nets restores wholesome athletic laughter to grim apocalypse survivors.",
    },
    ["sickle"] = {
        zh = "配有贴合掌心木手柄与月牙形锋利弧刃的传统单手收割小镰刀。在草丛中收割庄稼与草药时轻快省力，在遭遇近身袭击时，反手挥割的月牙钩刃能顺势割断敌人的脚筋或咽喉，阴狠毒辣。",
        en = "A traditional crescent-bladed hand sickle fitted with an ergonomic wooden grip. Reaping wheat stalks and wild herbs with effortless wrist flicks, hooking this curved razor blade inward equally severs raider hamstrings in ambushes.",
    },
    ["sickle_stone"] = {
        zh = "以木弯柄镶嵌数十片细小锋利微燧石刀片制成的新石器时代石镰。骨胶与松脂将石刃牢牢固化在槽口中，虽然无法劈砍硬物，但在收割草药与麦穗时展现出惊人的古老智慧与锋芒。",
        en = "A Neolithic sickle crafted by embedding sharp flint microliths into a curved wooden haft with pine pitch. Incapable of chopping hard wood, it glides through wild grasses with astonishing prehistoric cutting efficiency.",
    },
    ["side_double_holster"] = {
        zh = "采用双层加厚熟牛皮并联缝制的双联快拔手枪套。能够在一侧腰胯同时稳妥收纳两柄自卫手枪，虽然走起路来略显笨重，但在遭遇突发短兵相接时能提供翻倍的副武器掏枪安全感。",
        en = "A heavy leather side-by-side double holster rig designed to seat two handguns along one hip. Though adding noticeable bulk to your gait, presenting twin sidearms instantaneously doubles your close-range tactical insurance.",
    },
    ["side_nylon_double_holster"] = {
        zh = "由高密度军规耐磨尼龙织造而成的轻便并联双枪套。配有魔术贴紧固带与模块化快速卡扣，重量比传统真皮轻巧许多且不怕雨水泥浆浸润，是末日快枪手随身佩戴双枪的高机动装备。",
        en = "A lightweight dual holster constructed from heavy-duty tactical nylon webbing. Resisting water and mud much better than leather, its modular Velcro retention loops keep two backup sidearms secure during frantic acrobatics.",
    },
    ["sieve_primitive"] = {
        zh = "用晒干的野生柳条与韧皮细藤手工交叉编织而成的简易圆形筛子。网眼大小质朴粗犷，在溪流边淘洗粗砂中的金粒与矿石碎片，或是筛除发霉谷物中的泥块杂草时格外顺手好用。",
        en = "A rustic round sieve woven from split willow wands and wild root fibers. Coarsely meshed, it efficiently separates grain kernels from chaff or screens gravelly creek sediments when panning for alluvial minerals.",
    },
    ["sieve_steel"] = {
        zh = "配有冲压不锈钢金属外框与微米级致密不锈钢丝网的标准实验室钢筛。坚固耐酸碱腐蚀，在配制纯净黑火药颗粒分级、分离精细研磨面粉或过滤生化沉淀物时能实现极其精准的颗粒分选。",
        en = "A professional laboratory sieve featuring a stamped stainless steel rim and fine wire mesh. Resisting corrosion, it provides clinical particle fractionation necessary for graining uniform gunpowders or refining chemical precipitates.",
    },
    ["sieve_steel_makeshift"] = {
        zh = "在废弃金属罐头盒底部用钉子密集凿孔制作而成的土制筛网。虽然孔径大小不一且毛刺扎手，但在缺乏正规工具的废墟工坊里，用来筛洗草木灰提取硝石或过筛粗木炭粉依然立下汗马功劳。",
        en = "A makeshift sieve punched from a salvaged tin can bottom using hammer and nails. Despite uneven jagged holes, it sifts crushed charcoal and wood ash adequately for producing homemade saltpeter batches.",
    },
    ["sig40mag"] = {
        zh = "西格绍尔 Pro 手枪原厂 12 发 .40 S&W 口径钢制双排弹匣。弹身开有余弹观察孔，强力托弹簧与抗磨损进弹口设计，能确保每一发大口径重弹在高速连击中平稳推进枪膛，绝不卡壳脱爪。",
        en = "A factory 12-round steel magazine built for the SIG Pro chambered in .40 S&W. Outfitted with high-tensile feed springs and witness holes, it feeds heavy-caliber rounds reliably without stovepipes during panic fire.",
    },
    ["sig_40"] = {
        zh = "采用轻量化高强度聚合物套筒座的西格 Pro .40 半自动警用手枪。发射停止作用凶狠的 .40 口径弹药，扳机行程顺畅且握把防滑颗粒扎实，是废土执法者信赖的近距离一枪制敌神兵。",
        en = "The SIG Pro polymer-framed service pistol firing punchy .40 S&W ammunition. Blending European engineering reliability with formidable stopping power, its crisp double-action trigger tames snapping abominations with decisive authority.",
    },
    ["sig_assault_rifle"] = {
        zh = "瑞士精密工业制造的西格民用半自动运动步枪。采用久经考验的长行程活塞导气系统与优质冷锻枪管，射击后坐极其平稳顺滑，远距离点名变异生物时弹孔密集得令人惊叹不已。",
        en = "A precision civilian semi-automatic rifle manufactured by SIG with fine Swiss craftsmanship. Operating via an ultra-reliable gas piston, its match-grade barrel prints remarkably tight shot groups across distant engagement zones.",
    },
    ["sig_mcx_rattler_sbr"] = {
        zh = "枪管仅有五点五英寸的西格 MCX 响尾蛇超短管短突击步枪。紧凑得如同冲锋枪却能发射致命的 .300 亚音速重弹，搭配折叠枪托与消音器，是狭窄地下掩体与室内破障肃清的近战凶神。",
        en = "The ultra-compact SIG MCX Rattler short-barreled rifle sporting a stubby 5.5-inch barrel. Chambered in hard-hitting .300 Blackout with a minimalist folding stock, it delivers brutal terminal ballistics inside tight bunker hallways.",
    },
    ["sig_mosquito"] = {
        zh = "专为射击训练打造的西格萤火虫 .22 LR 口径小型聚合物手枪。虽然外形酷似全尺寸大口径战斗手枪，但几乎毫无后坐力，发射廉价易得的小口径边缘发火弹药，是练习控枪与猎捕松鼠的省钱利器。",
        en = "A lightweight .22 LR training pistol built on an ergonomic polymer frame. Mimicking full-sized combat sidearms with negligible recoil, it provides inexpensive target practice and small-game hunting without burning precious rifle ammunition.",
    },
    ["sigflare_lit"] = {
        zh = "被击发点燃、剧烈喷射出数千度刺眼红光的化学照明信号弹。不仅能照亮方圆数百米漆黑如墨的夜晚废墟，其滚烫的金属火花若直接击中目标，还能瞬间引燃衣物并造成严重的深度化学烧伤。",
        en = "A brilliantly burning emergency flare spewing thousands of lumens of incandescent chemical fire. Illuminating midnight ruins across vast distances, its searing phosphorus shower equally ignites wooden barricades and roasts flammable abominations.",
    },
    ["sights_mount"] = {
        zh = "以航空级 6061-T6 铝合金 CNC 铣削而成的通用皮卡汀尼光学瞄具转接底座。结构刚性极高且锁止严丝合缝，能为你的无导轨枪械牢固架设全息红点或高倍狙击镜，确保剧烈震动绝不偏位。",
        en = "A rigid 1913 Picatinny optics mounting rail CNC-machined from aircraft aluminum. Clamping securely across rifle receivers, it allows precise mounting of red dots and telescopic scopes without losing zero during combat.",
    },
    ["sights_mount_launcher"] = {
        zh = "专为榴弹发射器设计的可调仰角曲射瞄具转接底座。带有清晰的多距离仰角测距旋钮与锁定棘轮，能在远距离抛射高爆榴弹时精确校正弹道下坠，让每一枚杀伤炮弹都能如雨点般砸进敌阵中央。",
        en = "A specialized launcher quadrant sight mount featuring calibrated elevation adjustments. Designed to calculate steep mortar-like trajectories, it guides high-explosive grenade rounds directly into enemy foxholes with artillery-like accuracy.",
    },
    ["sights_mount_pistol"] = {
        zh = "精细车削、直接固定在手枪滑套后方的微型微型红点瞄准镜适配基座。超薄轻量化设计绝不影响滑套后坐循环，让射手能在出枪瞬间双眼睁开快速捕获红点，将近距离瞄准射速提升至极致。",
        en = "A low-profile reflex optic mounting plate engineered for handgun slides. Maintaining proper ejection cycling without added drag, it allows rapid two-eyes-open red-dot target acquisitions during sudden chaotic ambushes.",
    },
    ["signal_flare"] = {
        zh = "装填有锶盐发光氧化剂与推进火药的 12 号高流明信号弹。装填进猎枪向高空击发，能在夜空中悬浮燃烧数分钟划出明亮夺目的警报火球，是向数公里外定居点同伴发送求援信号的末日灯塔。",
        en = "A 12-gauge aerial pyrotechnic flare shell loaded with bright strontium compounds. Fired skyward, it launches a glowing red orb visible for miles, signaling nearby survivor encampments or confusing nocturnal predators.",
    },
    ["signed_chit"] = {
        zh = "由避难所商人或据点军阀亲笔签署、盖有私章的物资兑换凭证欠条。在这个货币体系全面瓦解的世界里，这脆弱的纸片承载着微弱的商业信用，只要发条者没被变异怪咬死，就能换来粮食与弹药。",
        en = "A stamped paper promissory IOU penned by a reputable outpost trading factor. Representing fragile merchant trust amid shattered currencies, it redeems clean drinking water and fresh cartridges—provided the issuer stays alive.",
    },
    ["silicone"] = {
        zh = "装在密封压力铝管内的工业级中性耐候硅胶填缝剂。挤出后遇空气湿气能固化为富有弹性的防水密封胶层，在修补破漏雨水罐、密封自制防毒面具边缘以及修补破窗缝隙时均有神效。",
        en = "A tube of industrial-grade elastomeric silicone caulk with an applicator nozzle. Curing into a resilient, waterproof rubber seal, it patches leaky rainwater cisterns, reseals cracked vehicle windshields, and weather-proofs bunker ventilation ducts.",
    },
    ["silver_anklet"] = {
        zh = "由 925 纯银丝编织、点缀着细小银铃的波西米亚风格女式脚链。走起路来在脚踝发出悦耳的叮咚脆响，在死寂幽暗的地下室里或许不利于潜行伪装，但在战后舞会上绝对能引来阵阵赞叹。",
        en = "A delicate sterling silver anklet jingling with tiny chime beads. While disastrous for stealthily creeping past sound-sensitive mutant stalkers, wearing it around cheerful campfire dances adds delightful charm to grim apocalypse life.",
    },
    ["silver_bracelet"] = {
        zh = "质地光洁、通体打磨光滑的经典纯银手镯。银质本身具有天然的微量抗菌与变色反应特性，戴在手腕上不仅沉静大方，在废土商贸集市上更是所有游商都乐于按克兑换生活物资的硬通货。",
        en = "A polished sterling silver cuff bracelet bearing subtle artisan engravings. Naturally antibacterial and resistant to corrosion, this gleaming adornment is readily accepted by weight among frontier barter caravans.",
    },
    ["silver_ear"] = {
        zh = "一对由高纯度银线弯折成型的典雅水滴形银耳环。金属光泽冷冽内敛，佩戴轻盈且绝不过敏化脓，在满目疮痍的废墟世界里，戴上它能让你重拾对美与体面生活的尊严与追求。",
        en = "A pair of hypoallergenic sterling silver hoop earrings designed with simple elegance. Free from irritation even in grimy post-cataclysm environments, wearing them preserves a proud spark of civilized glamour amidst ruins.",
    },
    ["silver_hair_beads"] = {
        zh = "一套雕刻有复杂古老维京符文的中空纯银发珠。串在脏辫或发辫梢头不仅能防止发丝在奔跑中散乱遮眼，微风吹拂时金属撞击发出细微轻响，展现出勇士般狂放不羁的荒野风骨。",
        en = "A set of tubular silver beads etched with intricate knotwork runes. Threaded through braided hair to tame untamed locks during dead sprints, their metallic clinking lends fierce warrior aesthetics to hardened wasteland wanderers.",
    },
    ["silver_hairpin"] = {
        zh = "一端雕刻成花叶纹饰、另一端打磨锋利的实心纯银长发簪。既能妥善盘起随风飞舞的长发保持视野开阔，在遭遇刺客扼喉的绝命关头，随手拔下也能充当瞬间刺穿敌人眼窝的致命毒刃暗器。",
        en = "A solid silver hair stick tapering into a needle-sharp point. Holding long hair securely off your face during physical labor, it doubles as an unsuspected, lethal shank capable of puncturing eyeballs in desperate grappling.",
    },
    ["silver_lip_ring_loop"] = {
        zh = "打磨极其光滑圆润的纯银圆环唇环。紧贴唇瓣佩戴带有叛逆不羁的朋克气息，纯银的抗菌性让穿刺孔免于在恶劣环境中感染溃烂，是废土赛博朋克拾荒者的个性标志。",
        en = "A seamless sterling silver hoop loop designed for labret lip piercings. Polished to a mirror sheen, the naturally antibacterial precious metal resists festering infections common in filthy underground survival encampments.",
    },
    ["silver_lip_ring_stud"] = {
        zh = "带有扁平内垫片与抛光银球的纯银唇钉。小巧贴合且在咀嚼粗糙食物时绝不刮伤牙龈，低调而不失张扬的金属光泽，在昏暗酒吧篝火下泛着微光，尽显废土朋克猎手的独特气质。",
        en = "A discrete silver labret stud capped with a threaded silver sphere. Snug and comfortable during hardtack chewing, its subtle metallic flash marks you as a fearless denizen of wild frontier outpost bars.",
    },
    ["silver_locket"] = {
        zh = "表面刻有繁复蔷薇藤蔓花纹、可开合的复古纯银盒式吊坠。打开内盖，里面珍藏着灾变前心爱之人褪色的微缩照片与一小缕头发，是幸存者在漫长绝望黑夜中坚守理智与爱意的唯一精神锚点。",
        en = "An ornate sterling silver locket opening on a delicate hinge. Preserving a tiny, faded pre-cataclysm photograph and a lock of hair within, it anchors weary souls to hope during terrifying nocturnal sieges.",
    },
    ["silver_medal"] = {
        zh = "挂在红蓝丝带上的厚重体育竞赛第二名纯银质奖牌。正面铸刻着胜利女神与橄榄枝浮雕，昔日的亚军荣耀如今已无人问津，但其沉甸甸的高纯度银质在熔炉中能提炼出极佳的银块硬通货。",
        en = "A hefty silver athletic prize medal awarded for second-place sporting excellence. While athletic achievements matter little to mutant horrors, melting its solid silver content yields substantial precious metal bullion.",
    },
    ["silver_necklace"] = {
        zh = "由无数细密银环紧密咬合编织而成的纯银费加罗链条项链。冰凉温润的金属贴在胸口散发着素雅的光芒，虽然在丛林摸爬中容易勾扯灌木，但在商贸集市上能够换来数箱关键急救药品。",
        en = "A finely linked sterling silver chain necklace shining with subdued white luster. Resting coolly against scarred collarbones, this classic jewelry piece trades seamlessly for crates of vital medical supplies and food rations.",
    },
    ["silver_nose_ring_loop"] = {
        zh = "采用医用级纯银弯折制成的圆润鼻环。扣在鼻翼或鼻中隔上彰显出野性难驯的废土战士狂野气息，抗过敏的银质能在风沙污浊的恶劣环境中始终保持穿孔伤口干爽清洁。",
        en = "A sleek circular nose ring bent from annealed sterling silver wire. Clamping securely through the septum, it projects aggressive wasteland swagger while its pure silver construction prevents ugly nasal tissue necrosis.",
    },
    ["silver_nose_ring_stud"] = {
        zh = "顶端带有精细微凸银珠的纯银鼻钉。小巧玲珑犹如鼻翼上的一颗闪亮星辰，牢固的弯钩固定脚能防止在剧烈翻滚格斗时脱落，是废土年轻游侠展示个性与审美的精致小首饰。",
        en = "A delicate silver nose stud ending in a tiny polished dome. Tucked securely inside the nostril with a curved post, it resists snagging on gas masks while adding charming sparkle to weathered faces.",
    },
    ["silver_ring"] = {
        zh = "没有过多繁复花纹雕饰的厚实质朴 925 纯银素圈指环。表面虽带有岁月留下的细微划痕，但纯银的本质经久不衰，不仅是佩戴者对逝去誓约的铭记，更是关键时刻随时能掏出的交换货币。",
        en = "A simple, unadorned sterling silver band ring polished by years of pocket wear. Enduring, humble, and universally recognized for its intrinsic metallurgical value, it functions as ready emergency cash anywhere.",
    },
    ["silver_small"] = {
        zh = "经小型喷枪融化杂碎首饰后浇铸在模具中冷却而成的一枚便携纯银小银块。印有粗糙的克重标记，质地致密且散发着迷人的银白光泽，是废土无货币交易体系中不可撼动的标准硬通货块。",
        en = "A compact cast silver bullion ingot stamped with crude weight marks. Smelted down from salvaged heirlooms, this dense precious bar constitutes universal currency across all civilized frontier settlements.",
    },
    ["silver_toe_ring"] = {
        zh = "带有开口弹性调节结构的纯银脚趾环。原本是旧时代海滩度假时套在脚趾上的时髦饰物，如今穿在沾满泥浆的草鞋里显得荒唐滑稽，但在游商眼里其银金属含量依然分毫不少。",
        en = "An adjustable open-ended silver band designed to wrap around toes. Looking delightfully absurd when paired with filthy rag-wrapped feet, caravan merchants nevertheless evaluate its melted bullion value without irony.",
    },
    ["silver_watch"] = {
        zh = "配有全纯银表壳与复古机械发条齿轮的典雅怀表。打开银盖，有节奏的清脆擒纵滴答声宛如旧时代的沉稳脉搏，在时间概念逐渐模糊的末日荒原上，它能为你精准守护每分每秒的宝贵时光。",
        en = "An elegant vintage mechanical pocket watch encased in solid sterling silver. Its rhythmic ticking echoes like the steady heartbeat of bygone eras, keeping impeccable time when electronic clocks have all fallen silent.",
    },
    ["simple_crank"] = {
        zh = "由废弃金属连杆与转轴拼装而成的简易手动曲柄传动装置。虽然转动时发出刺耳的金属摩擦嘎吱声，但能用最朴素的人力驱动水井绞车、手动绞肉机或是自制发电机，在停电的末日极其实用。",
        en = "A crude mechanical hand crank cobbled together from salvaged steel rods and bushings. Squeaking with friction at every rotation, it harnesses honest muscle power to turn well winches, grain grinders, or emergency alternators without fuel.",
    },
    ["simple_ordnance_cartridge_necklace"] = {
        zh = "用重型大口径炮弹底火引信壳穿在皮绳上制成的粗犷项链。沉甸甸地垂在胸前如同行走的护身符，向所有靠近的废土暴徒昭示着佩戴者从枪林弹雨中生还的硬核资历。",
        en = "A hefty necklace fashioned by threading spent heavy ordnance brass onto rawhide cords. Bumping against your chest, it stands as an intimidating badge of survival through hellish artillery bombardments.",
    },
    ["simple_pike_pipe"] = {
        zh = "将厚壁无缝自来水钢管一端斜向重击切削打磨出锋锐刺尖的重型长矛。超长的管身赋予了它惊人的攻击安全距离，双手握持向前凶狠贯刺，其沉重的钢管惯性足以凿碎厚重木盾与颅骨。",
        en = "A heavy defensive pike fashioned from a long length of seamless galvanized iron pipe. Providing immense reach behind barricades, driving this weighted steel shaft forward punches clean through wooden shields and reinforced bone structures.",
    },
    ["simple_pistol_cartridge_necklace"] = {
        zh = "用一颗打空的九毫米黄铜手枪弹壳穿线做成的纪念吊坠。弹壳上用刀尖刻着幸运日期，挂在脖子上冰凉沉稳，时刻提醒着你必须在绝境中留下最后一发救命的子弹。",
        en = "A pendant made from a fired nine-millimeter brass casing strung on paracord. Polished smooth by chest sweat, it serves as a silent reminder to always save the final bullet for yourself.",
    },
    ["simple_rifle_cartridge_necklace"] = {
        zh = "用一发修长的狙击步枪空弹壳精心打孔串联的战术吊坠。弹壳表面隐约可见斑驳的火药黑烟痕迹，似乎在无声诉说着那发曾击毙变异巨兽的致命一击。",
        en = "A long bottlenecked rifle casing suspended from a steel ball chain. Still carrying powder residue inside, wearing this keepsake commemorates a legendary long-distance shot that saved your hunting companion.",
    },
    ["simple_spear_pipe"] = {
        zh = "截取较短空心铁管压扁磨尖后制成的简易近战投刺长矛。轻便且重心平衡，既能在两三米开外隔着铁丝网戳杀游荡丧尸，也能在紧急时刻奋力掷出充当重型飞矛，是新晋幸存者的入门标配兵刃。",
        en = "A lightweight spear created by flattening and sharpening the tip of a hollow metal pipe. Easy to maneuver in tight spaces, it allows cautious survivors to poke zombies through chain-link fences safely.",
    },
    ["sinew"] = {
        zh = "从大型猎物四肢与脊椎上剥离、晾干撕裂出的坚韧动物筋腱。富含胶原蛋白且抗拉伸延展力惊人，用温水泡软后是古法制作复合弓背贴片、缝合厚实皮甲与绑扎锋利箭头的极品天然生物强线。",
        en = "Dried animal sinew stripped from harvested herbivore backstraps and leg joints. Packed with natural collagen, soaking and pounding these tough fibers produces indestructible biological cordage for backing recurve bows and lashing spearheads.",
    },
    ["single_malt_whiskey"] = {
        zh = "仅使用单一蒸馏厂发芽大麦、在橡木桶中静置熟成十余年的奢华单一麦芽威士忌。金黄色的酒液带着泥煤烟熏、香草与海盐的层叠风味，在这冰冷绝望的废墟世界里，每一滴都是对人类文明荣光的敬意。",
        en = "A distinguished single malt scotch whisky distilled from pure malted barley and aged in charred oak casks. Peaty, smoky, and complex with vanilla notes, sip by sip it honors human distilling artistry amid ruined cities.",
    },
    ["single_pot_whiskey"] = {
        zh = "采用发芽与未发芽大麦混合、在传统纯铜壶式蒸馏器中三次蒸馏的经典爱尔兰威士忌。口感油润柔滑且散发着烤面包与辛香水果的迷人气息，在篝火旁痛饮大半瓶，能彻底融化内心的恐惧与寒意。",
        en = "Traditional Irish whiskey triple-distilled within copper pot stills from mixed malted and unmalted barley. Silky, oily, and brimming with spiced fruit warmth, sharing a glass beside flickering campfires banishes lingering terror and damp chills.",
    },
    ["single_sling"] = {
        zh = "利用弹力尼龙织带与单金属快拆扣环绕在主躯干上的单点式战术枪背带。能够让长枪自如垂在胸前正中央，不仅便于左右手快速换肩射击，更能在狭窄车厢与楼道搜索中展现极佳的出枪机动性。",
        en = "A single-point bungee tactical sling looping over one shoulder and clipping to a weapon receiver. Centering long arms across the chest, it enables effortless shoulder transitions and lightning weapon presentations inside cramped doorways.",
    },
    ["sinister_cane"] = {
        zh = "手柄处雕刻着獠牙恶魔骷髅头的乌木拐杖。不仅手感沉重可以充当防身钝器敲碎丧尸的膝盖，杖身内更是暗藏杀机，握住它走路时自带着一股反派大枭雄的气场。",
        en = "A polished black hardwood cane crowned with a sinister brass gargoyle head. Heavy enough to crack zombie shins like a club, strolling through apocalyptic ruins with it looks theatrically menacing.",
    },
    ["sippy_cup"] = {
        zh = "带有双侧防滑手柄与防漏硅胶吸嘴的儿童学饮杯。密封性极好即便从二楼摔在水泥地上也不会漏出一滴水，拿来装珍贵的抗生素药水或净水出门再合适不过。",
        en = "A colorful toddler cup featuring spill-proof valves and dual gripping handles. Virtually indestructible when dropped down stairwells, it provides a leak-free flask for carrying scarce sterile medicine.",
    },
    ["six_bottle_box"] = {
        zh = "带有提手和六个独立隔舱的硬纸板饮料手提箱。不仅能防止搜刮来的玻璃啤酒瓶在背包里相互碰撞碎裂，也是在废弃酒窖或便利店中成组转移贵重酒水与自制燃烧瓶的最佳便携收纳箱。",
        en = "An open-topped cardboard six-pack carrier partitioned with cardboard dividers and a central handle. Preventing glass beer bottles from shattering inside rucksacks, it ferries precious beverage scavenges or Molotov cocktails safely across rubble.",
    },
    ["six_pack_rings"] = {
        zh = "旧时代易拉罐装啤酒与可乐常用的聚乙烯六联塑料套环。弹性十足且不易降解，在海洋里曾是海龟的噩梦，如今在废土上除了缠绕当临时的橡胶捆扎带，也是野外制作捕捉鸟雀绊脚陷阱的材料。",
        en = "Stretchy polyethylene rings originally binding six-packs of canned soda. Infamous for ensnaring wildlife in bygone days, post-apocalyptic trappers repurpose these flexible plastic loops into effective snare triggers for catching unwary waterfowl.",
    },
    ["sketch"] = {
        zh = "在发黄纸页上用炭笔迅速勾勒出的一幅手绘素描。画中记录着夕阳下的破败废墟与远方的绿树，虽然笔触匆忙凌乱，但在残酷的世界里依然散发着动人心魄的美感。",
        en = "A charcoal sketch rendered across foxed paper by an observant survivor hand. Depicting overgrown highway ruins against a golden sunset, its hurried strokes preserve quiet beauty amidst fallen worlds.",
    },
    ["skewer_bone"] = {
        zh = "将坚硬野兽腿骨一端削磨平整、另一端打磨锋利的自制骨签。耐热且绝不导热烫手，串上切好的变异肉块架在炭火上翻烤，油脂滋滋作响，是荒野猎人围炉夜话时最质朴省事的烧烤餐具。",
        en = "A slender meat skewer carved and sharpened from a dense animal leg bone. Heat-resistant and cool to grip, skewering chunks of seasoned mutant game over glowing coals provides simple, rustic campfire dining without burning fingers.",
    },
    ["ski_bib"] = {
        zh = "覆盖胸口与双肩、带有可调背带的加厚保暖滑雪背带裤。密闭的防风防水面料能死死阻止任何雪花与冰雨灌入腰腹，厚实的高效保温填充棉让你在及膝深雪中跋涉数小时依然双腿温暖如春。",
        en = "Heavy-duty insulated winter ski bib overalls held by adjustable shoulder suspenders. Completely sealing off the midriff from blowing blizzards, its waterproof shell and thick thermal fleece keep legs toasty during grueling snow slogs.",
    },
    ["ski_bib_unzipped"] = {
        zh = "将胸前主拉链拉开通风透气的滑雪背带裤状态。在剧烈滑雪奔跑或伐木劳作时能迅速释放多余的体表湿热，避免汗水浸透内衣导致致命失温，兼顾了保暖下半身与上半身透气散热的平衡。",
        en = "A warm ski bib with its heavy chest zipper pulled down for dynamic ventilation. Releasing suffocating body moisture during strenuous hauling labor, it prevents dangerous sweat accumulation that leads to hypothermia during arctic rests.",
    },
    ["ski_jacket"] = {
        zh = "采用高透气防水涂层面料注塑拉链缝制的专业滑雪冲锋夹克。带有可拆卸雪裙与多处透气拉链，鲜艳醒目的撞色设计虽然在废土上犹如移动靶标，但其无懈可击的防风抗冻性能无可挑剔。",
        en = "A technical ski parka engineered with waterproof membranes and powder skirts. While its vibrant neon color scheme screams your presence across bleak snowy wastes, the impenetrable windproof shell defends against sub-zero blizzards.",
    },
    ["skirt"] = {
        zh = "一条剪裁简约、带有松紧腰带的普通休闲短裙。穿在身上清爽透气且毫无拘束感，虽然在穿越荆棘灌木或在碎石堆中匍匐前进时会让你吃尽皮肉之苦，但在炎热晴夏确实轻便凉爽。",
        en = "A simple lightweight casual skirt fitted with an elastic waistband. Granting total lower-body freedom and refreshing breeze during humid summer dog days, it leaves knees painfully vulnerable to scratching brambles and crawling ambushes.",
    },
    ["skirt_bostonchan"] = {
        zh = "印有二次元吉祥物“波士顿酱”图案的百褶动漫二次元短裙。亮丽的卡通印花与死寂阴郁的瓦砾废墟形成荒诞鲜明的黑色幽默对比，穿上它在避难所漫步，绝对能让所有幸存者哭笑不得。",
        en = "A pleated anime novelty skirt emblazoned with vibrant Boston-Chan mascot motifs. Looking wildly absurd against scorched ruins, wearing this cheerful relic proves that otaku pop culture miraculously survived humanity's apocalyptic fall.",
    },
    ["skirt_denim"] = {
        zh = "采用耐磨粗斜纹牛仔布车缝而成的经典牛仔短裙。结实抗刮且带有实用的后口袋，不仅比起普通化纤短裙更能抵御灌木划伤，随着岁月磨砺褪出的粗犷战痕更添一份野性废土女孩的英气。",
        en = "A durable western-style skirt stitched from heavy-gauge blue twill denim. Far tougher than flimsy synthetic fabrics, it resists bramble scrapes while developing rugged, handsome wash wear through months of trail survival.",
    },
    ["skirt_grass"] = {
        zh = "用长长的干燥草叶与编织韧皮打结连缀而成的波利尼西亚风情草裙。走起路来草叶沙沙作响，虽然毫无任何保暖防刺与防弹功能，但在热带海滩篝火边跳上一段草裙舞能极大振奋同伴的士气。",
        en = "A traditional Polynesian grass skirt braided from dried tropical leaves and natural twine. Rustling loudly with every footstep while offering zero defense against teeth, performing an exuberant hula dance beside campfires boosts collective morale.",
    },
    ["skirt_leather"] = {
        zh = "以厚实熟牛皮裁剪铆接而成的朋克重金属皮短裙。带有金属铆钉与拉链装饰，不仅能抵挡近距离飞溅的碎石与爪痕刮擦，更散发着一股生人勿近、桀骜不驯的废土掠夺者女王霸气。",
        en = "A tough leather mini-skirt reinforced with metal studs and heavy brass zippers. Deflecting stray rock chips and thorny briars, its bold apocalyptic aesthetic projects the untamed authority of an experienced wasteland raider queen.",
    },
    ["skirt_long"] = {
        zh = "一直垂到脚踝附近的宽松轻盈长裙。宽大的裙摆能有效遮挡烈日暴晒并防止蚊虫叮咬双腿，轻拂微风凉爽舒适，虽然在狂奔逃命翻越铁丝网时容易拖泥带水挂住障碍，但充满优雅生活气息。",
        en = "An airy floor-length skirt sweeping gracefully around the ankles. Shading sunbaked legs from solar burns and insect swarms, its billowy hem unfortunately risks snagging on rusty barbed wire during dead-sprint retreats.",
    },
    ["sks"] = {
        zh = "带有固定十发弹仓与折叠刺刀的经典西蒙诺夫半自动卡宾枪。发射廉价易得的 7.62 毫米中间型步枪弹，全钢机匣皮实耐用，哪怕浸满泥浆黄沙也能从容击发，是废土游侠最忠诚可靠的老伙计。",
        en = "The venerable Simonov SKS semi-automatic carbine featuring an internal 10-round magazine and folding bayonet. Firing common 7.62x39mm cartridges with unyielding piston reliability, it remains the ultimate rugged workhorse for pragmatic frontier marksmen.",
    },
    ["skull_bear"] = {
        zh = "一颗硕大厚重、带有修长犬齿的成年变异巨熊头骨。骨质致密如岩石且眼眶巨大，放在避难所据点大门顶上充当图腾，足以让所有窥探的掠夺者吓得绕道而行。",
        en = "A massive, heavy skull taken from a fallen mutant grizzly bear. Sporting terrifying curved canine fangs, mounting it above your reinforced outpost gate sends an unequivocal warning to trespassers.",
    },
    ["skull_beaver"] = {
        zh = "长有一对橘红色锋利大门齿的变异河狸头骨。坚硬的凿形门牙即便在死后依然锋利如凿刀，稍微打磨一下甚至能拿来当作刮削木头与开凿硬壳的天然工具。",
        en = "A rodent skull equipped with bright orange, self-sharpening chisel incisors. Even cleaned of flesh, those formidable teeth pry open pine bark and carve timber as effectively as steel chisels.",
    },
    ["skull_beaver_huge"] = {
        zh = "来自庞大溃坝巨河狸的畸变骨质颅骨。骨壁厚重堪比轻型装甲车，两侧的重型咬肌附着点大得吓人，看着这副头骨，完全可以想象它生前一口咬断大树的恐怖怪力。",
        en = "The terrifyingly massive cranium of an overgrown dambreaker beaver monstrosity. The thickened jaw attachments reflect jaw power capable of felling mature oak trees and chewing through concrete culverts.",
    },
    ["skull_bovine"] = {
        zh = "带有粗壮对称弯角的变异黄牛头骨。在烈日暴晒下已经白骨化，挂在越野装甲改装车的车头进气格栅正中央，散发出一股纯正硬派的狂暴末日公路骑士范儿。",
        en = "A bleached cow skull sporting twin sweeping horns, cleansed by weather and scavengers. Bolted to the front radiator grille of an armored truck, it completes the quintessential post-apocalyptic road warrior aesthetic.",
    },
    ["skull_canis"] = {
        zh = "经过风化白骨化的大型变异野犬或恶狼头骨。那对突出的粗壮犬齿即使在死后也依然闪烁着森冷寒芒，清洗干净后绑在长矛顶端或是固定在车辆保险杠前，是威慑敌对部落的凶悍战功徽标。",
        en = "The weathered bleach-white cranium of a massive wild canine. Its prominent jagged fangs still gleam with predatory menace, making an intimidating hood ornament for war rigs or a tribal totem crowning defensive palisades.",
    },
    ["skull_canis_medium"] = {
        zh = "中型变异野狗那狭长而锐利的颅骨样本。牙床上的犬齿交错咬合，颅骨顶部骨缝紧密闭合，是荒野猎人挂在腰间用于清点当日野外捕猎战果的残酷纪念物。",
        en = "The elongated skull of a feral mutant dog with sharp shearing molars. Tied to your survival harness, it serves as a macabre tally mark of wilderness ambushes survived and neutralized.",
    },
    ["skull_canis_small"] = {
        zh = "巴掌大小的微型犬颅骨。脆弱的鼻梁骨与小巧的下颌让人难以联想到凶猛的野兽，洗刷干净后放在书架上，常被孤独的避难所守夜人当做无言倾听的桌上玩伴。",
        en = "A delicate canine skull scarcely larger than an orange. Cleaned and placed beside your bedside candle, it acts as a silent, patient listener during long, solitary underground night shifts.",
    },
    ["skull_canis_triclopean"] = {
        zh = "前额正中央赫然开有第三个空洞眼窝的畸变三目变异犬头骨。令人毛骨悚然的骨骼变异见证了地下高辐射生化污染的扭曲杰作，佩戴在胸前当护身符，能让最迷信的掠夺者吓得瑟瑟发抖。",
        en = "A grotesque canine cranium boasting a distinct third orbital socket centered along its forehead. Concrete anatomical evidence of catastrophic radiation-induced mutation, wearing this freakish trophy unnerves superstitious raiders in dark ruins.",
    },
    ["skull_cervine"] = {
        zh = "顶着多分叉优雅骨质鹿角的白尾鹿颅骨。对称分布的角冠宛如天然的艺术品，无论是挂在壁炉上方还是用来悬挂战术耳机，都能为粗糙的木屋营地增添野性典雅。",
        en = "An intact whitetail deer skull crowned with sweeping multi-tined antlers. Mounted over a stone fireplace, the graceful bone rack serves as a rustic hanger for drying gun belts and headsets.",
    },
    ["skull_cervine_spideer"] = {
        zh = "令人头皮发麻的蜘蛛异化鹿头骨。眼窝周围畸形增生出了八个对称的多重小眼孔，牙床上甚至长出了细碎的螯牙，无声展现着异界突变对温顺食草动物的疯狂扭曲。",
        en = "A horrifying mutant skull combining deer antlers with multiple arachnid orbital sockets. Tiny venomous fangs line its palate, showcasing the grotesque reality of interdimensional biological corruption.",
    },
    ["skull_cougar"] = {
        zh = "线条流畅且咬合力惊人的变异美洲狮头骨。短粗的吻部与弯曲的匕首状利齿彰显着它生前顶级掠食者的霸气，握在手中能感受到大自然最纯粹的杀戮工艺造化。",
        en = "A streamlined feline skull boasting lethal saber-like canine teeth. Its short snout indicates tremendous clamping bite force, representing the lethal perfection of nature apex ambush predators.",
    },
    ["skull_equine"] = {
        zh = "狭长而坚固的野马头骨。经过风蚀脱水后呈现出象牙般的苍白色泽，沉重的骨架记录着曾经在草原上自由奔腾的岁月，如今只能静静躺在废墟角落任凭尘土覆盖。",
        en = "The long, dignified skull of a prairie horse bleached white by relentless weather. A silent monument to creatures that once galloped freely across open plains, it now gathers dust in ruins.",
    },
    ["skull_feline_medium"] = {
        zh = "中型山猫颅骨标本。圆润的脑颅与尖锐的门牙相得益彰，在显微镜下甚至能看到突变诱发的骨质增厚，是研究大灾变对肉食动物神经中枢影响的宝贵生物样本。",
        en = "A compact bobcat skull showing abnormal bone thickening around the braincase. Intact and scrubbed, biology enthusiasts examine it to understand how mutagens hyper-evolved predatory instincts.",
    },
    ["skull_feline_small"] = {
        zh = "只有拳头大小的变异家猫头骨。虽然体积娇小，但尖锐如针尖的牙齿依然在灯光下闪闪发亮，让人联想到那些在阴暗废墟房梁上悄无声息飞扑咬人的变异恶猫。",
        en = "A tiny domestic cat skull small enough to fit inside your mug. Needle-sharp fangs gleam menacingly, evoking memories of feral felines stalking from rafters in darkened grocery aisles.",
    },
    ["skull_goat"] = {
        zh = "长有一对后弯坚硬角核的野山羊头骨。粗壮的额骨曾经抵御过无数次雄性求偶撞击，坚固程度堪比钢板，拿在手里沉甸甸的，宛如一面微型的骨质单手小圆盾。",
        en = "A wild goat skull reinforced with backward-curving horn cores. The thickened frontal bone endured countless mating headbutts, functioning almost like a natural bone buckler when gripped tightly.",
    },
    ["skull_human"] = {
        zh = "空洞眼眶里只剩风沙与落尘的人类颅骨。在无声中诉说着旧世界数十亿生灵瞬间蒸发的惨烈浩劫，捧在手中犹如哈姆雷特面对命运的终极拷问，既令人悲悯，也是废土残酷法则的冷酷警钟。",
        en = "A bleached human skull with cavernous eye sockets staring blankly into eternity. A chilling relic testifying to billions who vanished during the Cataclysm, handling it serves as a sobering reminder of human mortality.",
    },
    ["skull_human_tainted"] = {
        zh = "表面覆盖着不规则黑色骨刺增生的人类头骨。骨质被丧尸病毒腐蚀得千疮百孔却异常坚硬，空洞的眼眶仿佛依然在无声控诉着大灾变降临时那场撕心裂肺的人间惨剧。",
        en = "A human skull warped with jagged, blackened bone spurs. Corrupted by the infection yet paradoxically dense, its empty hollow sockets stare back, echoing the tragic horrors of civilization sudden fall.",
    },
    ["skull_llama"] = {
        zh = "带有修长颈椎结合部的变异羊驼头骨。独特的牙齿咬合面适合研磨纤维粗糙的荆棘灌木，白骨化的脸颊看起来永远带着一种若有若无的迷之微笑，透着滑稽感。",
        en = "The elongated skull of a farm llama showing broad grinding molars. Even stripped of woolly flesh, the jawline retains an aloof, amused grin that mocks the earnest grimness of your survival.",
    },
    ["skull_moose"] = {
        zh = "重达几十磅的成年雄性驼鹿头骨。巨大的掌状阔角向前舒展遮天蔽日，光是将它从森林里拖回营地就要耗费半天力气，挂在墙上是最震撼人心的狩猎战利品。",
        en = "A colossal bull moose skull carrying expansive palmate antlers. Weighing dozens of pounds, hauling this trophy back through tangled spruce bogs was exhausting, but it dominates your bunker wall.",
    },
    ["skull_moose_tusked"] = {
        zh = "发生极度畸变的獠牙驼鹿异化头骨。在原本就庞大威武的鹿角下方，竟然从上颚离奇长出了一对如野猪般弯曲外翻的锋利长獠牙，看起来宛如神话中屠城的远古凶兽。",
        en = "A nightmarish moose skull sporting both massive antlers and curving tusks erupting from upper jawbones. This mutated chimera looks like a mythical war-beast resurrected to terrorize boreal woodlands.",
    },
    ["skull_opossum"] = {
        zh = "吻部尖锐且长满密集细碎牙齿的小型负鼠头骨。作为荒野上最善于装死和苟延残喘的拾荒幸存大师，将它的头骨随身携带，据说能带来某种躲避死神的神秘好运。",
        en = "A pointed opossum skull displaying fifty needle-like teeth. Revered as the ultimate masters of playing dead and surviving against all odds, scavengers carry this talisman for good luck.",
    },
    ["skull_pig"] = {
        zh = "额骨极其倾斜厚实的变异野猪头骨。两侧突出的粗长獠牙如同两把弯曲短刀，骨骼坚硬得能硬顶手枪子弹的正面直射，是一头在泥地里横冲直撞的钢铁推土机。",
        en = "A heavy wild boar skull sloping upward into an iron-hard brow ridge. Curved tusks jut outward like wicked daggers, reflecting an animal that crashed through thick timber without decelerating.",
    },
    ["skull_rabbit"] = {
        zh = "小巧玲珑且骨壁薄如纸张的野兔头骨。大大的眼眶占据了头颅两侧的大部分空间，拿在手中轻若无物，让人不禁感叹在残酷的废土食物链底层，弱小者存活究竟有多么艰难。",
        en = "A fragile, paper-thin wild rabbit skull with cavernous eye sockets. Weighing almost nothing, it serves as a sobering reminder of how desperately small herbivores struggle at the food chain bottom.",
    },
    ["skull_raccoon"] = {
        zh = "前额饱满、脑容量在小动物中出奇优异的浣熊头骨。这群昔日的垃圾桶大盗在大灾变后依然活得风生水起，这颗小脑瓜子里曾经装满了破解人类门锁与保险扣的绝妙鬼点子。",
        en = "The rounded skull of a clever masked scavenger. Houses an impressively large braincase, this little rogue spent its lifetime outsmarting human trash can lids before joining the bone collection.",
    },
    ["skull_rodent"] = {
        zh = "一颗普通的变异大老鼠头骨。两对坚硬耐磨的黄色门齿在死后依然微微发亮，正是这种永远在啃噬电线与塑料的顽强生物，陪伴人类见证了世界末日的全程演变。",
        en = "A commonplace rodent skull boasting sharp, chisel-edged incisors. Ubiquitous across every sewer and pantry, this resilient creature witnessed the collapse of humanity and inherited the subterranean empire.",
    },
    ["skull_sheep"] = {
        zh = "带有两柄向后弯曲大角的高地绵羊白骨头骨。厚实的骨板与盘旋的弯角充满原始野性魅力，固定在营地大门上方充当辟邪兽首，或是打磨角质制作骨柄工具都是极好的天然工艺原料。",
        en = "A weathered ram skull crowned with sweeping curled horns. Exuding untamed pastoral majesty, mounting this rugged osseous centerpiece over camp gateposts creates a striking decorative guardian that ward off wandering scavengers.",
    },
    ["skull_skunk"] = {
        zh = "带有钝圆吻部的野生臭鼬头骨。虽然骨头经过清水与双氧水反复煮沸清洗，但每次凑近闻上去，总觉得那股刺鼻的硫醇恶臭依然阴魂不散地附着在骨缝深处。",
        en = "A compact skunk skull scrubbed thoroughly with boiling water and peroxide. Despite intense cleaning, phantom olfactory memories convince you that foul defensive musk still lingers deep within nasal cavities.",
    },
    ["skunk_spray_neutralizing_solution"] = {
        zh = "由过氧化氢、小苏打与浓缩表面活性剂特殊调配而成的臭鼬恶臭中和液。能够化学氧化分解臭鼬喷雾中致命的硫醇有机物，及时清洗能拯救被臭得几乎窒息并被整个营地驱逐的倒霉幸存者。",
        en = "A chemical de-skunking wash compounding hydrogen peroxide, baking soda, and liquid detergent. Rapidly oxidizing putrid sulfur-based thiols into odorless compounds, it rescues unfortunate scouts from olfactory banishment by disgusted bunker mates.",
    },
    ["sl8"] = {
        zh = "基于经典 G36 平台改造而来的民用单边开孔枪托半自动步枪。灰白色的外表散发着前卫科幻感，冷锻重枪管射击精准无比，只可惜原厂弹匣井被限制为单排供弹，无法直接插入标准弹匣。",
        en = "The civilian target sporting variation of the Heckler & Koch G36 rifle. Featuring a thumbhole stock and match barrel, its space-age polymer lines deliver surgical accuracy, though hindered by a frustrating single-stack magazine well.",
    },
    ["sl8mag"] = {
        zh = "专为民用 HK SL8 运动步枪定制的 10 发单排半透明聚合物弹匣。弹身轻巧且能清晰看见剩余子弹，虽然容量较小且不能与军规 G36 弹匣通用，但供弹顺畅稳定，是精准靶场射击的好伙伴。",
        en = "A proprietary 10-round single-stack translucent magazine manufactured for the HK SL8. Displaying brass cartridges through tinted polymer walls, its smooth feed geometry prevents jams during precision varmint-hunting sequences.",
    },
    ["slag"] = {
        zh = "在冶炼矿石或熔接金属时浮在液面上的多孔玻璃质熔渣残渣。虽然是金属提纯后的废料无法锻造，但其坚硬粗糙的颗粒在铺设泥泞营地道路、充当磨刀研磨砂或是压制土砖时颇有用处。",
        en = "Glassy vitrified byproduct skimmed from molten forge crucibles. While useless for smithing blades, crushing this brittle porous stone yields excellent abrasive grinding grit or stabilizes muddy footpaths around workshop doors.",
    },
    ["slamfire_shotgun"] = {
        zh = "由两根可嵌套滑动的自来水镀锌铁管组成的极简撞击式霰弹枪。将内管向后猛力撞击底火座上的固定撞针即可瞬间开火，结构粗暴原始得令人发指，虽然每次只能单发，但糊脸威力同样致命。",
        en = "A rudimentary pipe shotgun crafted from two nesting lengths of galvanized conduit. Manually slamming the rear barrel against a fixed receiver firing pin discharges a heavy 12-gauge shell with terrifying point-blank finality.",
    },
    ["slamfire_shotgun_d"] = {
        zh = "焊接了两套滑动水管枪管的自制猛击式双管霰弹枪。双手向前一拉一扣能依次或同时打出两发致命铅弹风暴，虽然每次射击震得手掌发麻虎口开裂，但两连发的暴力输出足以放倒任何近身变异怪物。",
        en = "A double-barreled homebuilt slamfire shotgun joining twin sliding pipe assemblies. Slamming both barrels rearward unleashes a synchronized double blast of buckshot, shattering charging mutant beasts at the minor expense of bruised palms.",
    },
    ["sleeping_bag"] = {
        zh = "采用防风尼龙外壳与多层人造保暖中空棉填充的标准木乃伊睡袋。拉紧抽绳风帽后能紧紧锁住全身散发的体温，在零下严寒的废弃楼宇或潮湿防空洞里，它能让你安然入梦而不致冻毙于夜半。",
        en = "A civilian mummy sleeping bag packed with synthetic hollow-fiber insulation. Cinching the draft collar tightly around your nose traps radiant body heat, ensuring restful, warm slumber inside freezing concrete basements.",
    },
    ["sleeping_bag_fur"] = {
        zh = "内部满铺厚密野生动物天然毛皮的奢华极寒毛皮睡袋。散发着粗犷的荒野兽息，天然皮毛强大的蓄热保温性能哪怕置身冰天雪地的露天荒原，也能为你营造出一个如春日般温暖干燥的生命茧房。",
        en = "A heavyweight arctic sleeping bag lined internally with prime tanned animal pelts. Reeking of primal wilderness, the thick fur loft defies sub-zero blizzards, cradling freezing explorers within an impenetrable cocoon of primal warmth.",
    },
    ["sleeping_bag_fur_roll"] = {
        zh = "用坚固皮带紧紧捆扎卷起的毛皮睡袋。虽然卷起后依然分量沉重且体积庞大犹如一根原木，但捆绑在背包底部或马鞍后方随行携带，是远征队挺进极北严寒冻土探险时最让人心安的保命家当。",
        en = "A heavy fur bedroll cinched tightly using thick leather buckled straps. While substantial to haul on foot, strapping this warm bundle behind a saddle ensures survival through the harshest arctic wasteland nights.",
    },
    ["sleeping_bag_improvised"] = {
        zh = "用几张旧棉被、废地毯碎片与麻绳手工打结卷起的简易自制睡袋卷。虽然外观粗陋且缝隙偶尔漏风，但在露宿荒野无处容身时，将其铺在干草堆上能为你抵御夜间地气的刺骨阴寒。",
        en = "A makeshift bedroll bundled together from salvaged wool blankets and twine. While leaky around the edges during biting drafts, unrolling it across dried straw provides vital thermal insulation against freezing dirt floors.",
    },
    ["sleeping_bag_roll"] = {
        zh = "排空气体后紧凑卷起、并用两条织带扎成圆柱形的标准合成睡袋。体积小巧且重量轻盈，可以轻松挂在战术背包下方的挂载点上，伴随行军者穿州过省，走到哪里便能在哪里安歇扎营。",
        en = "A synthetic sleeping bag compressed into a tight cylindrical bedroll via dual webbing straps. Compact and featherweight, it clips neatly beneath exploration rucksacks, ready to deploy instant shelter wherever darkness overtakes you.",
    },
    ["sleeveless_duster"] = {
        zh = "去除了双袖的粗帆布防尘长大衣。长长的下摆随着狂奔在身后猎猎作响，无袖设计让双手拔枪挥刀毫无布料牵绊阻滞，既能抵挡后背风沙脏污，又兼顾了快意恩仇的极致近战灵活性。",
        en = "A long canvas trail duster modified by shearing away its sleeves. The sweeping ankle-length mantle deflects grit and road dust while leaving shoulders completely unencumbered for rapid blade draws and athletic combat rolls.",
    },
    ["sleeveless_duster_faux_fur"] = {
        zh = "采用人造毛皮内衬制成的加厚无袖防尘长风衣。长摆防风护腿，宽敞的袖孔在内穿重型防弹护臂时也绝不臃肿卡壳，让巡逻队员在寒风呼啸的高地既有风度又有温度，行动敏捷如风。",
        en = "A floor-length canvas duster lined with plush synthetic faux fur and stripped of sleeves. Providing serious core insulation without bunching uncomfortably over bulky forearm guards, it keeps roving scouts warm and agile.",
    },
    ["sleeveless_duster_fur"] = {
        zh = "内衬奢华天然动物真毛皮的无袖长款防尘风衣。厚重的兽毛包裹着躯干驱散严寒，无袖裁剪让握持重机枪扫射或挥舞砍刀劈砍畅通无阻，尽显废土旷野军阀头目冷酷狂放的领袖风采。",
        en = "A sweeping leather duster lined with natural wolf pelts and featuring sleeveless armholes. Trapping body warmth securely around your vitals while freeing arms to swing heavy broadswords, it radiates ruthless frontier warlord majesty.",
    },
    ["sleeveless_duster_leather"] = {
        zh = "由整块厚重熟牛皮手工鞣制缝合的无袖皮革防尘大衣。皮面油光锃亮且耐磨抗爪，长下摆在风沙中如黑色披风飞舞，无袖结构便于在炎炎夏日散热并让臂部刺青与护腕战术装备一览无遗。",
        en = "A rugged full-length duster fashioned from heavy tanned cowhide without sleeves. Deflecting scratching claws and barbed wires, its flowing leather skirt bellows behind you like a battle cape while maintaining arm mobility.",
    },
    ["sleeveless_trenchcoat"] = {
        zh = "剪掉双袖的经典双排扣防水华达呢无袖风衣。保留了帅气的肩章、腰带与大翻领设计，没有了束缚双臂的衣袖，在狭窄街巷中遭遇近身伏击时能以最快速度从腰间拔枪出膛射击。",
        en = "A double-breasted gabardine trenchcoat altered by lopping off both sleeves. Retaining its storm flaps and belted silhouette, the unconstrained arm openings enable split-second draw strokes during frantic close-quarters ambushes.",
    },
    ["sleeveless_trenchcoat_faux_fur"] = {
        zh = "带有柔软人造毛皮衬里与翻领的无袖战术风衣。兼顾了躯干核心部位的防风御寒与双臂剧烈活动的极致轻便，即使在寒气逼人的初冬夜间潜行，也不会因为笨拙的袖管拖慢动作。",
        en = "A warm sleeveless trenchcoat lined with insulating synthetic faux fur. Keeping your chest and kidneys toasty during freezing twilight watches, its bare shoulders prevent fabric bunching over ballistic plate carriers.",
    },
    ["sleeveless_trenchcoat_fur"] = {
        zh = "翻领处镶着真兽毛、内胆衬有厚实动物毛皮的无袖风衣。质地沉稳奢华，大灾变后只有战功赫赫的猎人才能凑齐足够的毛皮定做这件战袍，在寒风中昂首阔步，霸气十足。",
        en = "A stylish trenchcoat sporting genuine fur lapels and pelt lining without sleeves. Crafted from the spoils of successful mutant hunts, this imposing garment keeps wandering champions warm while displaying their trophies.",
    },
    ["sleeveless_trenchcoat_leather"] = {
        zh = "纯黑皮革材质缝制、去除了双袖的末日重装风格风衣。宽大挺括的皮革下摆防刮抗刺，无袖剪裁露出强健有力的臂膀与战术护具，在暗影重重的废墟走廊中犹如降临人间的复仇判官。",
        en = "A sleeveless trenchcoat tailored from supple black leather. Offering dependable torso slashing resistance while leaving arms bare to flex scarred muscle and tactical forearm sheaths, it projects an intimidating vigilante persona.",
    },
    ["sleeveless_tunic"] = {
        zh = "用粗麻布缝制、套头穿戴的质朴无袖长束腰上衣。系上一根皮带便能利落贴身，没有任何繁琐纽扣或多余装饰，透气轻便且易于清洗，是废土平民与劳作工匠最基本的日常劳动工装。",
        en = "A primitive pullover linen tunic sewn without sleeves. Secured around the waist with a simple leather belt, this breathable and easily laundered shirt provides humble, practical daily workwear for settlement laborers.",
    },
    ["slime_sample"] = {
        zh = "装在密封硼硅玻璃试管内的一小团半透明活性变形怪黏液样本。在微光下微微搏动抽搐，散发着微弱的奇异荧光与生物电流，是研究异星生物组织融合与变异活性的无价实验标本。",
        en = "A sealed borosilicate test tube preserving a quivering globule of translucent amoebic slime. Pulsing with eerie bioluminescence, this erratic organic sample is deeply coveted by bunker scientists researching mutagenic tissue plasticity.",
    },
    ["slime_scrap"] = {
        zh = "在激战后从变形怪残骸上铲下的一大团黏稠恶心果冻状凝胶糊。冰凉滑腻且带有强烈的酸腐有机气味，虽然令人作呕，但提炼其化学成分能制作强效工业黏合剂或特殊润滑油脂。",
        en = "A sticky, gelatinous glob scooped from the steaming remains of a slain amoebic monstrosity. Cold and faintly acidic, processing this revolting organic goo produces potent biological adhesives or specialized machinery lubricants.",
    },
    ["sling"] = {
        zh = "由两根坚韧编织绳索连接一块熟皮革兜囊构成的远古投石索。结构极其质朴，只要在废墟地上随手捡起一枚鹅卵石，经过头顶高速旋转甩出，便能以重炮般的破空呼啸将丧尸脑门砸个稀烂。",
        en = "The primordial projectile weapon consisting of two braided cords joined to a leather stone cradle. Spinning this sling overhead and releasing one cord launches river pebbles with bone-crushing velocity, silently felling zombies.",
    },
    ["sling-ready_grenade"] = {
        zh = "改装有快拆拉环与加固皮兜挂钩的军规破片手雷。专门适配投石杖的长臂杠杆原理，无需极度贴近危险尸潮，轻轻一甩便能将死亡高爆引信投掷到数十米开外炸成一片火海。",
        en = "A military fragmentation grenade modified with an extended lanyard for staff-sling cups. Utilizing long mechanical leverage, throwing it hurls explosive death across vast distances without exposing throwers to shrapnel.",
    },
    ["sling-ready_homemade_grenade"] = {
        zh = "为投石杖量身改造的自制黑火药破片手雷。外部缠有便于兜囊兜牢的布条，借助木杖挥舞产生的强劲离心力，能把装满生锈铁钉与炸药的致命铁罐如炮弹般轰入敌阵深处。",
        en = "A makeshift black-powder pipe bomb wrapped in friction tape for secure sling-cup seating. Harnessing centrifugal whip from a fustibal staff, it propels a lethal canister of scrap shrapnel into distant clusters.",
    },
    ["sling-ready_homemade_grenade_2"] = {
        zh = "装填军用高能塑胶炸药的重型自制投石手雷。经过精确动平衡配重，配有投石杖专用卡槽，飞向目标时弹道极其平稳，落地爆发的剧烈冲击波足以将重甲暴徒瞬间掀翻震碎。",
        en = "A devastating homebrewed grenade packed with salvaged military C4 and balanced for staff slings. Soaring on stable parabolic arcs, the resulting high-order detonation levels fortified raider bunkers and mangles armored monstrosities.",
    },
    ["sling-ready_molotov"] = {
        zh = "经过外壁防撞缓冲与特制引火带加固的投石杖专用莫洛托夫燃烧瓶。大幅削减了空中意外脱落爆裂的风险，让投掷手能将熊熊燃烧的汽油烈焰精准抛射到远处的坚固据点窗口。",
        en = "A glass Molotov cocktail fitted with a reinforced neck cradle for launch via staff slings. Greatly extending incendiary reach beyond normal arm throwing, it drops blooming fireballs into distant sniper nests.",
    },
    ["sling-ready_small_homemade_grenade"] = {
        zh = "小巧紧凑的迷你自制破片手雷改装版。重量轻盈且适配细窄投石兜，挥杆甩出初速极高如同高尔夫球飞射，爆炸虽然杀伤半径有限，但精准定点清除单体敌人的效率令人称奇。",
        en = "A compact improvised explosive device contoured for slings and staff cradles. Whistling downrange at shocking velocity like a driven golf ball, its concentrated blast cleanly dispatches single high-threat sentries.",
    },
    ["sling-ready_small_homemade_grenade_2"] = {
        zh = "以军用高爆炸药装药的微型自制投石手雷。浓缩的爆轰威力与极高的投掷初速相得益彰，犹如一枚受控的手掷高爆枪榴弹，在悄无声息间将远距离火力点炸成一团焦黑碎屑。",
        en = "A miniature grenade packed with condensed military explosive and tailored for staff slings. Merging rapid aerodynamic delivery with surgical high-brisance trauma, it acts like a silent hand-thrown mortar shell.",
    },
    ["sling_bullet"] = {
        zh = "浇铸成两头尖削梭形的致密铅质或金属投石弹丸。流线型的气动外形能有效减少空气阻力并在飞行中高速自旋，命中目标时尖锐的侵彻力能将冲击动能尽数灌入敌人肉体深处。",
        en = "A cast metal sling bullet shaped into an aerodynamic biconical slug. The streamlined profile induces gyroscopic spin through air, punching through leather armor and driving crushing blunt energy into internal organs.",
    },
    ["sling_bullet_clay_250"] = {
        zh = "用纯净黏土搓圆并在火堆中烘烤硬化的 250 克轻型投石泥丸。重量轻便且制作极为廉价，击中坚硬岩石会粉碎爆裂成一团泥尘，适合用来骚扰驱赶低阶野生动物与练习投掷准星。",
        en = "A 250-gram baked clay sphere rolled by hand and dried over embers. Dirt cheap to mass-produce, striking hard targets shatters it into harmless clay dust, making it ideal for target practice and small pest scaring.",
    },
    ["sling_bullet_clay_500"] = {
        zh = "重达半公斤的实心烧结红黏土投石弹丸。分量十足且表面平整，从长投石索中高速甩出带有呼呼破空风声，虽然硬度不及钢铁，但纯粹的半公斤重力砸在脸上依然能让人满面挂彩眩晕。",
        en = "A substantial half-kilogram ball of fire-hardened red clay. Whistling through the air from a whirling sling, the raw blunt impact of half a kilo of fired earth knocks breath from encroaching ghouls.",
    },
    ["sling_bullet_clay_750"] = {
        zh = "足足 750 克重的大号烤制黏土弹球。如同小号实心保龄球般沉重，必须依赖双手挥动或投石杖长臂才能完全发力，砸碎在木栅栏上犹如泥巴迫击炮，具有惊人的面冲击威慑力。",
        en = "A massive 750-gram baked ceramic clay orb resembling a miniature cannonball. Demanding heavy two-handed sling windups, its weighty impact splatters against defensive palisades with concussive, demoralizing force.",
    },
    ["sling_bullet_lead_250"] = {
        zh = "采用高密度纯铅浇铸的 250 克紧凑橄榄形投石弹。体积小巧却沉甸甸的，在风中阻力极小且飞行速度奇快，击中骨骼瞬间能产生可怕的粉碎性骨折，是罗马军团传世的致命暗器。",
        en = "A compact 250-gram cast lead sling bullet shaped like an acorn. Dense mass packed into a tiny aerodynamic profile allows blisteringly fast flight speeds, fracturing skulls with ruthless classical efficiency.",
    },
    ["sling_bullet_lead_500"] = {
        zh = "重达五百克的重型纯铅两头尖投石弹。沉重无比的铅块在离心力加速下脱弦而出，呼啸声犹如撕裂空气的铅弹飞弹，哪怕隔着厚实防暴盾牌也能将敌人的手臂骨骼生生震断碎裂。",
        en = "A crushing half-kilogram lead slug molded for heavy sling deployment. Delivering terrifying kinetic momentum downrange, this dense metallic missile shatters forearm bones straight through reinforced riot shields.",
    },
    ["sling_bullet_lead_750"] = {
        zh = "重达 750 克的实心纯铅巨型投石破城弹。沉重得犹如握着一块铅砖，投掷需要极高的臂力与技巧，一旦命中目标头部，哪怕是披挂钢板的重甲狂战士也会被这一击当场砸爆头盔毙命。",
        en = "A colossal 750-gram solid lead projectile built for maximum concussive demolition. Requiring tremendous athletic strength to launch, a direct hit to the head crumples steel helmets and pulps cranial bone instantly.",
    },
    ["sling_bullet_steel_250"] = {
        zh = "采用工业淬火高碳钢精磨而成的 250 克圆形重钢珠。硬度极高且永不变形，命中硬物时甚至能擦出耀眼火花并发生剧烈跳弹，无论重复使用多少次都保持完美的球体穿透几何形状。",
        en = "A precision 250-gram high-carbon hardened steel bearing ball. Immune to deformation and endlessly reusable, it sparks blindingly off masonry while punching neat holes through light sheet metal plates.",
    },
    ["sling_bullet_steel_500"] = {
        zh = "重达半公斤的实心淬火大钢球。表面镀铬光滑防锈，握在手里沉如铁坨，高速甩击命中丧尸膝盖或胸膛，能在清脆的骨折声中直接打断骨骼，让目标像被保龄球击中的木瓶般倒下。",
        en = "A heavy half-kilogram solid steel sphere gleaming with anti-corrosive polish. Traveling downrange like a localized artillery shell, its unyielding steel surface shatters kneecaps and collapses rib cages.",
    },
    ["sling_bullet_steel_750"] = {
        zh = "足足 750 克重的超大号工业实心轴承钢球。极其恐怖的钢质分量在强力投石索甩动下化作毁灭性动能流星，不仅能把坚固木门砸得木屑横飞，也是砸烂变异巨兽坚硬外骨骼的铁锤。",
        en = "A monstrous 750-gram hardened industrial bearing sphere. Acting like a handheld cannon shot, its devastating momentum splintering heavy oak doors and pulverizing chitinous mutant armor plates.",
    },
    ["sling_bullet_stone_250"] = {
        zh = "在急流河滩上千挑万选出来的 250 克纯天然光滑鹅卵石。形状圆润如鹅蛋且没有任何棱角卡挂，大自然千百年的冲刷赋予了它绝佳的投射气动性，是废土拾荒者最廉价随取的杀戮弹药。",
        en = "A naturally tumbled 250-gram river cobblestone selected for smooth symmetry. Polished by centuries of current, it flies with admirable aerodynamic stability, serving as universal free ammunition across ruins.",
    },
    ["sling_bullet_stone_500"] = {
        zh = "重达五百克的致密花岗岩或玄武岩椭圆天然石块。沉甸甸的石头在长索甩动下呼啸破空，砸在坚硬地面上碎裂飞溅，粗暴而直接的重力钝击能轻易打烂任何游荡丧尸的半边脑壳。",
        en = "A half-kilogram granite river stone handpicked for uniform oval balance. Delivering substantial concussive shock, this dense natural rock pulps decaying undead skulls with thunderous primitive finality.",
    },
    ["sling_bullet_stone_750"] = {
        zh = "足足 750 克重的大号天然石卵。重量几乎达到了单手投石索的投射极限，需要全身腰胯协力旋转才能甩出，砸在变异怪物堆里犹如天降小型陨石，足以砸出大面积剧痛钝击伤害。",
        en = "A massive 750-gram natural basalt stone testing the structural limits of hand slings. Launched with full rotational torso drive, it descends upon targets like a mini-meteorite, crushing multiple limbs.",
    },
    ["sling_long"] = {
        zh = "绳长超过一米、专门用于极限远距离抛射的加长型牧羊人投石索。极长的力臂能够积蓄极为恐怖的线速度与动能，虽然需要广阔的开阔空地来旋转发力，但百米外的射程足以媲美强弓。",
        en = "An extra-long shepherd's sling featuring extended braided cords. Generating ferocious centrifugal tip speeds through wider rotational arcs, it hurls heavy stone slugs across distances rivaling composite warbows.",
    },
    ["slingpack"] = {
        zh = "采用单斜跨背带设计的现代战术机动胸包。无需脱下背包即可单手将包体从身后迅速转至胸前拉开拉链取物，内有多层弹匣固定带，是穿行在废墟窄巷中保持高度戒备的优秀携行具。",
        en = "A modern tactical sling pack slung across the chest with a single wide padded strap. Swiveling forward to access interior gear in seconds without taking it off, it keeps emergency ammunition ready.",
    },
    ["slingshot"] = {
        zh = "采用坚韧木质叉架或高强度工程合金、配有医用乳胶弹力带的弹弓。结构小巧能直接揣进口袋，发射钢珠或小石子悄无声息，是远距离打破路灯灯泡或无声捕猎麻雀松鼠的刺客玩具。",
        en = "A sturdy y-frame slingshot fitted with high-tensile latex bands and a leather pouch. Pocket-sized and near-silent, it plucks wild pigeons from perches and snuffs out perimeter halogen floodlights unseen.",
    },
    ["slippers"] = {
        zh = "带有毛绒内胆与柔软防滑泡沫底的居家保暖棉拖鞋。穿在脚上轻柔如踩在云端，在漫长寒冷的搜刮归来后脱下沉重军靴换上它，能给磨破起泡的双脚带来宛如天堂般的放松与慰藉。",
        en = "Cozy indoor slippers cushioned with soft fleece lining and non-marking foam soles. Slipping battered, blistered feet into these warm clouds after arduous scavenging marches brings instantaneous, heavenly relief.",
    },
    ["sloppyjoe"] = {
        zh = "将碎牛肉末与洋葱、甜椒和酸甜番茄辣酱一同慢炖、并大量浇在汉堡圆面包上的碎肉三明治。咬上一口浓郁滚烫的肉酱便从四面八方疯狂溢出，吃得满手油腻却带给肠胃无与伦比的暴风狂欢。",
        en = "A messy American sandwich heaping simmered ground meat and tangy tomato sauce between soft buns. Overflowing across knuckles with every bite, this saucy, savory carbohydrate feast warms hollow bellies thoroughly.",
    },
    ["sm_extinguisher"] = {
        zh = "装填有两磅干粉灭火剂的紧凑型车载手提灭火器。带有清晰的压力表与保险销，喷射出的磷酸铵盐干粉能迅速扑灭油料泄漏、电路短路以及自制燃烧瓶引发的初期明火，是随车必备安全屏障。",
        en = "A compact two-pound dry chemical fire extinguisher equipped with an inspection pressure gauge. Discharging smothering ammonium phosphate powder, it rapidly suffocates fuel spills and electrical fires before they engulf your shelter.",
    },
    ["small_aluminum_bar_flat"] = {
        zh = "切边平直整齐的小尺寸纯铝扁条五金坯料。质地轻巧且易于使用钢锯锯断、钻孔攻丝与打磨成型，是机械师手工制作轻量化武器挂轨支架、仪表盘框架或是加固刀柄衬片的极佳原料。",
        en = "A handheld length of extruded structural aluminum flat bar stock. Lightweight and effortlessly drilled, tapped, or shaped with hand files, it forms custom sight mounts, drone chassis braces, and knife handle liners.",
    },
    ["small_aluminum_bar_round"] = {
        zh = "直径适中的小截实心圆柱形铝合金棒料。金属表面光滑无暇，在小型废土车床上能极快旋削出精密的垫圈、活塞连杆销钉或是高强度螺纹接头，是工匠车间里的万能轻金属坯件。",
        en = "A smooth cylindrical rod of machinable aluminum alloy bar stock. Turning cleanly on improvised mini-lathes, it crafts lightweight spacers, fuel fittings, and customized firearm takedown pins without dulling cutting bits.",
    },
    ["small_biogas_tank"] = {
        zh = "配有进出气调压阀与冷凝水排放口的小型生物沼气储气罐。收集有机粪便与烂菜叶在密闭发酵罐中产生的甲烷气体，能在无电无油的废墟避难所里为你持续提供做饭与照明的清洁燃气。",
        en = "A compact pressurized canister designed to store purified methane derived from anaerobic manure digesters. Providing steady fuel for cooking stoves and mantle lamps, it harnesses rotting waste into sustainable utility power.",
    },
    ["small_checkboard"] = {
        zh = "采用折叠木板或硬纸板绘制的黑白相间八乘八格紧凑型棋盘。合拢后体积仅如一本平装小说，无论在晃动的卡车车厢里还是在昏暗的防空洞床板上，展开便是一方考验谋略的黑白天地。",
        en = "A travel-sized folding checkerboard painted with alternating eight-by-eight black and white squares. Packing down flat like a paperback novel, unfolding it brings tactical diversion to cramped vehicle cabs and gloomy bunkers.",
    },
    ["small_checkers"] = {
        zh = "装在小铁盒内的便携式木质或塑料红黑西洋跳棋全套棋子。规则简单却暗藏跳吃杀机，在死寂无声的漫漫废土长夜中，它是避难所老少咸宜、缓解焦虑抑郁与拉近同伴关系的极佳智力桌游。",
        en = "A compact tin case holding wooden red and black checker discs. With simple hop-and-capture rules fostering fierce friendly rivalries, playing beside sputtering tallow candles eases claustrophobic survival anxieties.",
    },
    ["small_chess"] = {
        zh = "带有磁吸防滑底座的全套便携式微型国际象棋。三十二枚雕刻精美的立体棋子牢牢吸附在棋盘上，即便在颠簸行驶的末日改装车上对弈也不会移位，是谋士们锤炼大局观的掌中战场。",
        en = "A pocket chess set featuring thirty-two magnetized pieces anchoring firmly to an iron board. Playable without interruption even across jolting off-road journeys, it offers rigorous mental exercise for strategic minds.",
    },
    ["small_demihuman_stomach_boiled"] = {
        zh = "在沸水中彻底煮熟的一只小型亚人变异体胃囊。缩水成灰白色如同一块厚实的橡胶水袋，虽然提供了活命急需的微薄卡路里，但在吞咽时内心的道德防线几乎被彻底碾碎。",
        en = "A small demihuman stomach boiled down to a rubbery gray pouch. Providing crucial survival nourishment, forcing down each chewy mouthful inflicts heavy moral penalties on civilized human conscience.",
    },
    ["small_hc_steel_bar_flat"] = {
        zh = "采用高纯度高碳工具钢精制而成的小尺寸扁平钢条。经过热处理淬火回火后具有极佳的硬度与刃口保持性，是刀匠手工打磨开刃锻造顶级猎刀、折刀刀身与木工凿子刃口的无上宝料。",
        en = "A prized length of annealed high-carbon steel flat bar. Responding beautifully to forge heat treating and quenching, this dense metallic billet grinds into razor-sharp hunting knives, surgical scalpels, and rugged woodworking chisels.",
    },
    ["small_hc_steel_bar_round"] = {
        zh = "高硬度高碳合金实心圆钢小棒料。质地极为紧密抗扭曲，能够在砂轮机上车削加工成超硬开锁撞针、枪械击针、强力冲子以及微型淬火穿甲箭镞，是军械维修师视若珍宝的精工硬料。",
        en = "A short cylindrical rod of tough high-carbon tool steel. Boasting exceptional torsional strength, grinding it produces hardened firearm firing pins, heavy-duty center punches, and armor-piercing bodkin arrowheads.",
    },
    ["small_helicopter_rotor"] = {
        zh = "来自轻型双座民用直升机尾桨或微型主旋翼的高强度复合材料旋翼叶片。质地坚韧且带有完美的气动翼型弧度，拆下来不仅能改装风力发电机叶片，两端磨尖更是摧枯拉朽的巨型直升机大砍刀。",
        en = "A composite rotor blade salvaged from a lightweight civilian scout helicopter. Engineered for immense centrifugal stress, mounting it onto wind generator turbines generates steady juice or converts into a horrifying oversized combat cleaver.",
    },
    ["small_homemade_grenade"] = {
        zh = "装在密封铁皮药品罐内部的微型自制破片手雷。虽然装药量不大，但罐体内紧密填充了淬火钢珠与碎铁钉，拔掉安全引火帽后投出，在室内逼仄狭窄房间内能形成致命的无死角破片杀伤区。",
        en = "A compact homebuilt grenade constructed within a sealed steel pill tin. Packed with black powder and hardened steel ball bearings, tossing this pocket bomb clears tight bedrooms with lethal shrapnel ricochets.",
    },
    ["small_homemade_grenade_act"] = {
        zh = "引信已经被摩擦点燃、冒着白色刺鼻硝烟与火花的微型自制手雷。短短三秒的燃烧时间容不得半点犹豫迟疑，必须在瞬间发力将其猛力掷入门缝或丧尸群腹地，否则后果不堪设想。",
        en = "A miniature pipe bomb hissing angrily with spitting ignition sparks and white chemical smoke. With a hair-raising three-second fuse burning down fast, you must lob this live explosive instantly to avoid self-disassembly.",
    },
    ["small_hstomach_boiled"] = {
        zh = "在沸水与重度香料中经过长时间文火慢炖的人类胃部器官。虽然肉质纤维在慢熬下变得软烂柔韧，但那股若有若无的怪异酸臊腥味与触目惊心的解剖现实，时刻提醒着食客底线正在无可挽回地崩塌。",
        en = "A human gastric organ stewed thoroughly within boiling seasoned broth until tender. Though technically edible calories, the sickening knowledge of what simmered in your pot tests moral humanity against beastly desperation.",
    },
    ["small_lc_steel_bar_flat"] = {
        zh = "延展性优良且极易冷弯塑形的低碳钢扁条坯料。虽然由于含碳量低无法淬火变硬磨刀，但非常适合电焊焊接制作加固门闩、卡车底盘角码与各类抗震机械结构件，加工省力顺手。",
        en = "A malleable section of low-carbon mild steel flat bar stock. Unsuitable for quenching into hard blades, its forgiving ductility and weldability make it ideal for fabricating gate latches and reinforcing vehicle bumpers.",
    },
    ["small_lc_steel_bar_round"] = {
        zh = "小截实心圆柱形低碳软钢圆钢料。在手摇台虎钳上加热即可轻松弯折成 U 型螺栓、金属挂钩与链条环扣，在没有高级热处理设备的简陋废土作坊中，是搭建基础结构连接件的得力原料。",
        en = "A short length of ductile mild steel round bar stock. Easily heated and bent across an anvil horn into sturdy hooks, U-bolts, and chain links, it provides dependable structural hardware without demanding heat-treating ovens.",
    },
    ["small_lcd_screen"] = {
        zh = "从废弃手持掌机或测距仪上完整拆卸下来的单色微型 LCD 液晶显示屏。超低功耗且带有背光排线，是极客工程师组装自制盖革计数器、电子罗盘与微型动力装甲状态面板的无价核心显示元件。",
        en = "A miniature backlit monochrome LCD screen salvaged from a handheld rangefinder. Drawing negligible battery current, this display module connects cleanly to homemade Geiger counters and digital compass units.",
    },
    ["small_lighter"] = {
        zh = "外形短小精悍的经典一次性迷你丁烷打火机。小巧得能塞进任何子弹袋或烟盒侧缝，拇指轻轻一按即可点燃稳定的防风火苗，在寒冷潮湿的末世长夜中是带来光明与温暖的最忠诚守护神。",
        en = "A compact disposable mini butane lighter small enough to hide in watch pockets. Striking its flint wheel summons an instant, reliable flame to kindle damp kindling, illuminate keyholes, or light emergency flares.",
    },
    ["small_mc_steel_bar_flat"] = {
        zh = "兼具良好综合韧性与强度的中碳钢扁铁坯料。具有出色的耐冲击韧性与抗疲劳寿命，在砂轮上开刃并经过合理热处理，能打造出绝不崩刃也绝不断裂的坚固斧头、撬棍与工兵铲头。",
        en = "A handy length of medium-carbon structural steel flat bar. Balancing tensile toughness with impact absorption, it shapes into reliable crowbars, hatchet heads, and entrenching tools that endure abusive shocks without shattering.",
    },
    ["small_mc_steel_bar_round"] = {
        zh = "高韧性中碳钢实心圆柱棒料。车削与锻打性能极为均衡，常用于机械维修中车削传动齿轮轴、高强度固定螺栓以及耐磨转轴铰链，能承受车辆长期颠簸越野带来的剧烈交变应力。",
        en = "A sturdy cylindrical bar of medium-carbon steel stock. Offering balanced machinability and shear strength, it turns into heavy-duty suspension pivot pins, drive axles, and indestructible chassis hinge pins.",
    },
    ["small_plant"] = {
        zh = "种植在破裂塑料盆或金属罐头盒里的一小株生机勃勃的绿色盆栽植物。嫩绿的叶片在灰暗破败的废土世界里散发着生命的光芒，不仅带来一丝新鲜氧气，更在无声中守护着幸存者心中未熄的希望。",
        en = "A living green houseplant potted within a cut-down tin can. Its vibrant foliage stands out in defiant contrast against radioactive ash, purifying stale room air while reminding scarred survivors that the earth will eventually heal.",
    },
    ["small_pressure_vessel"] = {
        zh = "由高强度合金钢无缝旋压成型的小型高压耐压容器罐。带有防爆安全泄压阀与耐高压螺纹接口，能承受数十个大气压的极端压力，是改装自制气动气枪储气瓶或便携化学反应釜的关键母体。",
        en = "A thick-walled seamless steel pressure canister fitted with threaded high-pressure ports. Engineered to contain extreme atmospheres safely, it serves as the foundation for pneumatic rifle tanks or chemical reaction vessels.",
    },
    ["small_printout_portal_storm_data"] = {
        zh = "由军用空间物理监测仪在传送门风暴期间自动吐出的一截简短穿孔纸带记录。上面印满了令人费解的量子涨落读数与时空曲率异常峰值，是解密大灾变维度撕裂机制的核心科研绝密数据。",
        en = "A narrow thermal paper strip printed by dimensional monitoring equipment during a portal storm. Recording spacetime curvature spikes and Nether fluctuations, it contains crucial clues regarding the physics of the Cataclysm.",
    },
    ["small_propane_tank"] = {
        zh = "装有一磅液化丙烷气体的露营便携式蓝绿色小气罐。拧在便携卡式炉或防风喷灯上能提供强劲稳定的高温蓝色火焰，不管是烧开一壶纯净雪水还是焊接铜管，都是极其轻巧可靠的热源。",
        en = "A one-pound disposable propane bottle fitted with a universal threaded valve. Powering portable camping stoves or plumber's blowtorches, it provides clean, instant cooking heat and metal-working BTUs in field camps.",
    },
    ["small_relic"] = {
        zh = "从维度撕裂空间裂隙或异星祭坛深处拾取而来的微型神秘圣物。表面漂浮着常理无法解释的幽异微光与微弱的反重力脉冲，握在掌心能感受到轻微刺痛，蕴含着超越凡人认知的超自然未知伟力。",
        en = "A bizarre, palm-sized extraterrestrial relic recovered from the epicenter of a portal rift. Hovering with faint gravitational distortions and whispering cold resonance, it channels unnatural trans-dimensional reality warps.",
    },
    ["small_repairkit"] = {
        zh = "包含黄铜通条、不同口径黄铜铜丝刷、小油壶与多功能拆卸扳手的轻巧便携枪械保养包。能够随时随地清理枪膛内的严重火药积碳与泥沙，防止卡壳哑火，是每位枪手随身携带的火器保命包。",
        en = "A compact field gunsmithing kit packed with brass bore snakes, carbon scraper picks, and synthetic lubricant. Scrubbing out corrosive primer salts and mud deposits keeps scavenged firearms operating reliably without jams.",
    },
    ["small_scuba_tank"] = {
        zh = "容量仅为数升的小型紧凑型便携水下潜水气瓶。虽然无法支撑长时间的深海潜水作业，但小巧的体积能固定在胸前或潜水面罩旁，提供十余分钟救命高压洁净空气，是水下逃生与涉毒排险的利器。",
        en = "A compact pony diving cylinder containing a brief reserve of high-pressure air. Fitting easily into rucksacks, it supplies fifteen minutes of emergency oxygen for submerged car salvages or escaping smoke-choked basements.",
    },
    ["small_scuba_tank_on"] = {
        zh = "已经开启主阀门、呼吸阀随时随地待命的小型潜水气瓶。随着咬嘴吸气平稳释放清凉的干燥氧气，在充满致命浓烟、刺鼻酸雾与水下浸泡的密闭废墟深处，为你筑起一道最坚实的气态生命线。",
        en = "A miniature pony cylinder with its primary air valve turned on. Delivering crisp oxygen with every breath through its silicone mouthpiece, it grants crucial minutes of clear respiration when navigating toxic chemical plumes.",
    },
    ["small_space_heater"] = {
        zh = "采用陶瓷发热体与静音送风风扇的小型便携电暖风机。接通电源便能迅速向冰冷的卧室吹送滚滚暖流，在寒夜里是驱散潮湿霉气与防止手脚生冻疮的现代化过冬暖房神器。",
        en = "A compact electric space heater utilizing ceramic heating elements and an integrated blower fan. Plugging it into battery banks rapidly bathes drafty rooms in toasty warmth, banishing frostbite from damp sleeping quarters.",
    },
    ["small_space_heater_on"] = {
        zh = "内部陶瓷发热板已经烧得通红、风扇轻柔呼呼旋转的运行中电取暖器。源源不断的热浪将逼仄地窖烤得温暖宜人，虽然耗电量颇大，但在严寒暴雪夜能让你享受宛如灾前的极致舒适。",
        en = "An active ceramic heater glowing with cherry-red heating elements as its internal fan hums softly. Discharging generous thermal convection across chilly floors, it turns desolate bunkers into cozy sanctuaries at heavy battery cost.",
    },
    ["small_squeeze_tube"] = {
        zh = "装在柔软铝皮软管内的高强度多用途强力快干胶。挤出一滴涂抹在断裂的塑料扣件、开胶的靴底或脱落的镜片边缘，几分钟内便能紧密固化，是现场快速修补零碎小物件的应急胶水。",
        en = "A flexible squeeze tube filled with high-strength universal adhesive. Squeezing a drop bonds cracked plastic housings, flapping boot soles, and loose optics brackets within minutes, serving as indispensable field repair glue.",
    },
    ["small_steel_bar_flat"] = {
        zh = "切割平整的一小截通用结构钢扁铁坯料。具备良好的锻造与切削韧性，在铁砧上稍微加热捶打即可锻打成坚固的撬棍、大号垫片或是自制武器的强化龙骨，是工坊不可或缺的钢铁食粮。",
        en = "A convenient length of structural mild steel flat bar stock. Machining, filing, and forging with dependable consistency, smiths transform this billet into robust brackets, crowbars, and reinforced weapon spines on camp anvils.",
    },
    ["small_steel_bar_round"] = {
        zh = "尺寸适中的小截实心纯钢圆棒料。金属密度均匀且抗弯折强度高，在小型机床或手工锉刀下能迅速修整成机械销钉、轴承轴芯或是锋利的自制穿甲重弩箭镞，用途极其广泛多样。",
        en = "A short cylindrical steel bar stock offering high shear and tensile resistance. Easily turned into pivot pins, mechanical axles, or heavy armor-piercing crossbow bolts, it forms the versatile backbone of metal fabrication.",
    },
    ["small_stomach_boiled"] = {
        zh = "在滚水与盐巴中经过彻底水煮清洗煮熟的动物胃囊。口感筋道弹牙且富含动物胶质，切片拌上野葱与辣酱，便是一道能有效填饱空虚肠胃、提供扎实蛋白质能量的废土特色下酒菜。",
        en = "An animal stomach thoroughly cleaned and boiled tender with salt and foraged herbs. Chewy, gelatinous, and rich in bioavailable proteins, slicing this offal provides hearty, dense nutrition from otherwise discarded livestock scraps.",
    },
    ["small_storage_battery"] = {
        zh = "采用免维护密封铅酸或高倍率锂电电芯的小型储能蓄电池。体积轻巧便于搬运，能够稳定储存并释放宝贵的直流电，是为小型通信电台、战术无人机充电器以及营地夜灯供电的心脏电源。",
        en = "A sealed rechargeable storage battery engineered for auxiliary power banks. Compact and portable, it absorbs surplus solar juice to power night sentry lamps, transceivers, and medical equipment through long blackout hours.",
    },
    ["small_turbine_engine"] = {
        zh = "足足拥有 650 匹强劲马力的紧凑型航空与战车级燃气涡轮引擎。只要通入航空煤油或柴油，涡轮高速旋转爆发出的轰鸣咆哮能将你的末日装甲战车瞬间化身公路喷气飞弹，推背感极其狂暴。",
        en = "A high-output 650-horsepower compact gas turbine engine capable of swallowing any liquid fuel. Screaming with jet-turbine fury at full throttle, it propels heavily armored combat vehicles across wastelands with earth-shattering torque.",
    },
    ["smallweldtank"] = {
        zh = "装填有压缩乙炔或高纯氧气的小型便携气焊气瓶。配有双表减压阀与防回火装置，连接焊枪喷射出的数千度炽热蓝色焊焰，能轻松熔断粗壮钢筋、切开银行防盗门或补焊战车装甲板。",
        en = "A compact oxy-acetylene welding gas cylinder fitted with dual pressure regulators. Feeding intensely hot flame to cutting torches, it slices through bank vault doors or welds heavy armor plating to wasteland rigs.",
    },
    ["smart_lamp"] = {
        zh = "处于休眠断电状态的旧时代无线遥控多彩智能氛围灯。虽然内置的无线网络早因大灾变彻底瘫痪，但其高品质发光二极管与内置锂电池依然完好，连接直流电后是极度节能的营地照明灯。",
        en = "A dormant pre-cataclysm programmable LED smart lamp fitted with wireless receivers. Though defunct communication grids ignore its microchips, hardwiring its energy-efficient diode array yields brilliant multi-colored bunker illumination.",
    },
    ["smart_lamp_on"] = {
        zh = "通电发光、散发着柔和温馨白光的智能台灯。明亮柔和的照明彻底驱散了地下室墙角阴森可怖的阴影，让伏案研究地图与擦拭枪械的幸存者在文明的光辉中重新感受到久违的安全感。",
        en = "An illuminated smart lamp radiating warm glare-free lighting across your workbench. Dispelling claustrophobic gloom, its soft glow eases eye strain while plotting scavenge routes or meticulously cleaning firearm mechanisms.",
    },
    ["smart_phone"] = {
        zh = "已经解锁、操作系统完全畅通的旧时代高配大屏智能手机。虽然早已没有蜂窝基站网络信号，但其内部集成的离线百科、高精度陀螺仪、照相机与高亮手电筒功能依然是顶尖的废土掌上电脑。",
        en = "An unlocked touchscreen smartphone loaded with pre-collapse digital utilities. Though cellular towers stand silent, its offline encyclopedia caches, high-resolution cameras, and bright LED torch make it a premier survival pocket tool.",
    },
    ["smart_phone_flashlight"] = {
        zh = "屏幕碎成蜘蛛网但手电筒功能依然常开的智能手机。背面双色温LED发出刺眼的白光，屏幕上电量正以每分钟百分之五的速度狂跌，照亮前路的同时也在倒计时你的生命。",
        en = "A spiderweb-cracked smartphone actively projecting illumination from its rear camera LED. The battery gauge drops precipitously with each passing minute, rationing precious lumens down dark basement stairwells.",
    },
    ["smart_phone_locked"] = {
        zh = "屏幕上显示密码锁定与多次错误倒计时的智能手机。里面或许封存着未知的私人日记、实验室门禁通行码或宝贵的物资坐标，如果懂得电子黑客技术，破解它将带来意想不到的丰厚情报回报。",
        en = "A locked smartphone demanding an alphanumeric passcode across a cracked touchscreen. Potentially guarding bunker access codes, encrypted memoirs, or supply depot coordinates, cracking its biometric barrier requires skilled electronic hacking.",
    },
    ["smart_phone_locked_flashlight"] = {
        zh = "处于锁屏状态却依然开着强光手电的智能手机。由于不知道四位数字锁屏密码，你无法查看里面珍藏的家人照片或离线地图，只能无奈地把它当成一块沉重的昂贵发光砖头。",
        en = "A locked touchscreen phone with its emergency flashlight blazing. Unable to bypass the security passcode, you cannot access offline survival guides, leaving you clutching a glorified five-hundred-dollar tactical torch.",
    },
    ["smart_watch"] = {
        zh = "采用有机发光显示屏、带有心率脉搏与气压传感器的智能手表。戴在手腕上不仅能精确计时与记录行军步数，其高灵敏气压计还能提前数小时预警即将来临的致命雷暴与恶劣气旋。",
        en = "A wrist-worn smartwatch integrating optical heart sensors and a digital barometer. Tracking vital signs and elapsed march times, its sensitive pressure sensor warns of approaching barometric drops hours before lethal storms hit.",
    },
    ["smart_watch_adv"] = {
        zh = "配有蓝宝石镜面与钛合金表壳的高级智能手表。不仅能实时监测你的狂暴心率、血氧浓度与体表温度，在丧尸扑咬导致的肾上腺素狂飙时，还会贴心地提醒你注意深呼吸减压。",
        en = "A titanium-cased luxury smartwatch fitted with sapphire crystal glass. Monitoring heart rate and oxygenation, it unhelpfully vibrates to recommend breathing exercises while you frantically fend off rabid zombie dogs.",
    },
    ["smart_watch_adv_music"] = {
        zh = "正在通过骨传导耳机循环播放激昂交响乐的高级智能手表。高保真音乐回荡在耳畔，让你在双手挥动战锤砸碎丧尸脑壳时，竟然有一种在指挥维也纳新年音乐会的宏大错觉。",
        en = "An advanced smartwatch streaming classical orchestral movements into connected headsets. Splattering necrotic horrors with warhammers while Beethoven swells in your ears turns desperate survival into dark opera.",
    },
    ["smart_watch_music"] = {
        zh = "机载芯片正持续播放着大灾变前流行金曲的轻便智能手表。伴随着电音洗脑舞曲的节奏在街道上狂奔逃命，虽然能缓解极度恐慌，但过大的外放音量容易招惹附近的夜魔。",
        en = "A sporty smartwatch playing upbeat pre-war pop hits on external speakers. Sprinting away from screaming abominations to infectious synth-pop beats relieves terror while dangerously broadcasting your location.",
    },
    ["smartphone_music"] = {
        zh = "插着单边破旧耳机播放老式摇滚乐的智能手机。嘶吼的电吉他失真音色掩盖了窗外丧尸撕咬木栏杆的抓挠声，在这个崩溃的世界里为你守住最后一片属于人类的音乐净土。",
        en = "A battered smartphone playing vintage rock anthems through a fraying earbud. Roaring guitar distortion drowns out scratching claws at the bunker shutters, carving out a private sanctuary of sonic sanity.",
    },
    ["smg_40"] = {
        zh = "依据英国枪械大师卢蒂图纸用废旧五金钢管与角铁手工打造的 .40 口径全自动冲锋枪。做工粗糙但机匣沉重结实，开火时倾泻的强劲 .40 弹雨能在极短时间内将狭窄楼梯间的丧尸彻底打烂。",
        en = "An expedient homebuilt submachine gun fabricated from hardware pipe and sheet steel according to Luty designs. Spitting heavy .40 S&W slugs in uncontrollable automatic bursts, it dominates hallway ambushes with brutal scrap-heap firepower.",
    },
    ["smg_40_mag"] = {
        zh = "手工用薄钢板折弯焊接、装有自制硬弹簧的卢蒂 .40 冲锋枪 20 发双排弹匣。虽然外观带有粗粝焊渣且进弹口偶有毛刺，但压满沉重的子弹后供弹坚挺可靠，是民间土制军火的硬核代表。",
        en = "A 20-round double-stack box magazine hand-folded from mild steel sheet for the Luty .40. Displaying rough spot welds and crude feed lips, its stiff handmade spring feeds heavy cartridges reliably during close-quarters panic.",
    },
    ["smg_45"] = {
        zh = "仿照经典 MAC-10 外形结构简易组装的卢蒂式 .45 大口径全自动冲锋枪。极度短小精悍且射速极其疯狂，发射的大威力亚音速重弹在走廊扫射时如同死神撕扯破布，后坐力震颤剧烈凶猛。",
        en = "A crude blowback submachine gun mimicking the boxy MAC-10 layout chambered in .45 ACP. Empties its magazine in a terrifying blink of automatic fire, delivering deafening hammer-blow kinetic trauma at point-blank range.",
    },
    ["smg_45_mag"] = {
        zh = "专为自制 MAC-10 冲锋枪纯手工敲打焊接的 20 发 .45 口径应急直弹匣。弹身沉甸甸且容弹空间充足，虽然装弹时需要借助工具用力压入，但在遭遇凶残近战肉搏时多出的连发火力能救你一命。",
        en = "A makeshift 20-round box magazine fabricated for improvised .45 submachine guns. Demanding significant thumb force to load its stiff hand-wound spring, having twenty heavy rounds locked and loaded turns tides against charging mutant packs.",
    },
    ["smg_9mm"] = {
        zh = "汲取了二战斯登冲锋枪精髓的 9 毫米自制卢蒂式冲锋枪。采用最为纯粹的自由枪机与开膛待击原理，侧向插弹匣的设计虽然怪异，但极耐泥沙污垢，是在恶劣环境中挥洒通用手枪弹的泼弹利刃。",
        en = "A 9mm open-bolt blowback submachine gun blending Sten simplicity with Luty manual blueprints. The awkward horizontal magazine feed sheds grit easily, allowing scavengers to spray ubiquitous 9mm ammunition with cheerful industrial abandon.",
    },
    ["smle_mk3"] = {
        zh = "经历两次大战洗礼的英国李-恩菲尔德经典旋转栓动步枪。疯狂一分钟极速射击的传奇缔造者，顺滑的枪栓与十发弹仓让它在远距离交火中如同一柄精准的杀戮标尺。",
        en = "The legendary British Lee-Enfield No. 1 Mk III* bolt-action battle rifle. Famous for lightning-fast cycling during the historic 'Mad Minute', its 10-round magazine and buttery action drop targets with commanding British imperial precision.",
    },
    ["smokebomb"] = {
        zh = "装填有氯酸钾、乳糖与特种发烟剂的军规高浓度发烟手雷。拔出保险销投掷后几秒钟内便能喷涌出翻滚浓密的白色烟幕墙，彻底遮断敌方狙击手与机枪工事的射界，掩护队友绝境撤退。",
        en = "A military screening smoke grenade packed with potassium chlorate and chemical fuels. Igniting upon spoon release, it belches billowing plumes of dense white aerosol, blinding enemy snipers and granting flawless visual retreat cover.",
    },
    ["smokebomb_act"] = {
        zh = "喷嘴正发出震耳欲聋呼啸声、疯狂向外喷射浓密白烟的被激活烟雾弹。灼热的罐体温度高达数百摄氏度，瞬间形成的高密度烟雾屏蔽层能够迅速吞没整条街道，让任何视线锁定当场失效。",
        en = "An active smoke canister hissing furiously as thick, impenetrable white smoke erupts from its vents. Scalding hot to touch, the expanding aerosol cloud blankets streets in seconds, neutralizing thermal optics and direct line-of-sight.",
    },
    ["smokebomb_primed"] = {
        zh = "保险销已被拔掉、击发握片即将弹开的蓄势待发烟雾弹。只需松开手指轻轻一抛，滚滚浓烟便会瞬间爆发，任何明智的特战队员都会抓住这决定撤退生死的最后几秒钟。",
        en = "A primed smoke grenade with its safety pin yanked and strike mechanism tensioned under hand pressure. Tossing it releases the safety lever, ready to transform open kill zones into swirling impenetrable visual sanctuaries.",
    },
    ["smores"] = {
        zh = "在全麦饼干中间夹入烤至焦黄流心的棉花糖与半融化黑巧克力的经典野营甜点。咬下去酥脆、软糯与浓郁巧克力的香甜在口中同时爆发，在残酷破败的末日废土上，这一口美味堪称灵魂救赎。",
        en = "The quintessential campfire confection layering toasted gooey marshmallows and melted chocolate between crisp graham crackers. Sticky, crunchy, and dripping with decadent nostalgic sugar, it restores broken human spirits miraculously.",
    },
    ["smoxygen_tank"] = {
        zh = "装有纯净高压医用氧气与鼻吸管的小型便携吸氧急救瓶。在幸存者遭受浓烟窒息、肺部被毒气腐蚀或是高原急性缺氧反应时，吸入高浓度纯氧能迅速缓解呼吸衰竭，将生命从鬼门关拉回。",
        en = "A compact medical oxygen cylinder equipped with a pressure regulator and nasal cannula. Delivering pure life-saving oxygen to gasping lungs damaged by toxic smoke or lung rot, it stabilizes critical trauma patients.",
    },
    ["smpistol_primer"] = {
        zh = "专供 9 毫米与 .38 特种弹等小口径手枪弹药复装的小型手枪雷汞火帽底火。微小而极为敏感，在撞针强力撞击下瞬间爆燃，是废土枪匠在流水线上批量翻新手枪弹药的绝对核心点火源泉。",
        en = "Small pistol primers packaged in neat plastic staging trays. Engineered with sensitive explosive anvil cups, seating these metallic sparks into decapped brass hulls is the crucial first step in mass-reloading 9mm and .38 cartridges.",
    },
    ["smrifle_primer"] = {
        zh = "专为 .223 雷明顿与 5.56 毫米北约等小口径高速步枪弹设计的高强度小步枪底火。杯壁加厚耐高压，能承受步枪发射时极高的枪膛膛压而不致击穿漏气，是手工复装高精度步枪弹的基石。",
        en = "Reinforced small rifle primers built to withstand blistering chamber pressures generated by high-velocity 5.56mm cartridges. Thicker metallic cups prevent dangerous firing pin perforations, ensuring clean, match-grade rifle ignitions.",
    },
    ["snack_bread"] = {
        zh = "密封在三层铝箔充氮包装内的军用耐储全麦烘焙小面包。无论经历严寒酷暑或长期受潮都绝不发霉变质，虽然口感略显扎实干硬像啃硬海绵，但在缺乏主食的漫漫巡逻路上是极其顶饿的高能口粮。",
        en = "A vacuum-sealed shelf-stable military ration bread baked from fortified wheat flour. Resisting mold and staling for decades inside foil packaging, its dense chewy crumb satisfies gnawing hunger during endless reconnaissance treks.",
    },
    ["snail_garden"] = {
        zh = "背着螺旋钙质硬壳、在潮湿菜叶间慢悠悠爬行的新鲜小花园蜗牛。在饥肠辘辘的废土居民眼里，用清水吐沙静置后投入蒜香黄油锅中油煎，便是一道富含优质蛋白质与微量元素的野味法式大餐。",
        en = "A common garden snail carrying its spiral shell while leaving glistening mucus trails. Purged in clean water and pan-seared with wild garlic and lard, this humble gastropod transforms into a protein-dense survival delicacy.",
    },
    ["snakesnladders"] = {
        zh = "印有盘旋巨蛇与攀升梯子的一百格儿童经典桌游蛇梯棋。沿着格子掷骰子前进，踏上梯子一飞冲天、跌入蛇口急转直下，大起大落的游戏机制在黑夜烛光下常常逗得同伴们抚掌大笑忘却忧虑。",
        en = "The classic hundred-square Snakes and Ladders board game printed on sturdy cardstock. Rolling dice to climb lucky ladders or slide down treacherous snakes provides lighthearted laughter that distracts shelter crews from grim perimeter sieges.",
    },
    ["snapfastener_steel"] = {
        zh = "采用冲压不锈钢精制而成的子母四合按扣组件。咔哒一声紧密锁合，在剧烈奔跑撕扯中绝不轻易松脱，是给战术背心口袋、枪套防脱带以及加固帐篷门帘手工打扣钉扣的理想金属五金件。",
        en = "Durable stamped stainless steel snap fasteners consisting of interlocking male and female studs. Snapping shut with positive mechanical clicks, they secure tactical pouch flaps, holster straps, and weather flaps against whipping winds.",
    },
    ["sneakers"] = {
        zh = "鞋盒上印着“助你飞跃极限”，却没写明橡胶鞋底在光滑瓷砖上急停时会发出多么凄厉尖锐的吱呀声。在寂静昏暗的医院走廊里，那声响就像是在给整栋楼的丧尸摇响开饭的铜铃。",
        en = "The shoebox guaranteed extraordinary speed and aerial prowess, but conveniently failed to mention how loudly the rubber soles squeak on clean supermarket linoleum, acting as a personal dinner bell for every slumbering monstrosity within earshot.",
    },
    ["sneakers_steel"] = {
        zh = "在鞋头内置坚硬防护钢包头、外观却如日常滑板鞋般的防砸安全运动鞋。兼具运动鞋的灵活减震脚感与防砸防护，哪怕重物砸在脚趾上也能安然无恙，在近身肉搏中一记飞踢更是能碎骨裂石。",
        en = "Low-profile athletic sneakers concealed with hardened steel toe caps inside rubber soles. Combining lightweight running agility with industrial crushing protection, a sharp front kick delivers pulverizing blunt trauma to invading mutant shins.",
    },
    ["snow_machine_home"] = {
        zh = "配有高压水雾喷头与高转速强力轴流风机的小型家用人工造雪机。只要接通水管和电源并在零度以下运行，便能喷射出漫天飘舞的雪白人造雪花，给死寂的废墟广场重塑一片纯洁梦幻的冰雪奇境。",
        en = "A compact residential snow gun pairing high-pressure water atomizers with a powerful electric fan. Operating below freezing temperatures, it blankets charred ruins in powdery white artificial snow to the bittersweet delight of survivors.",
    },
    ["snowcone"] = {
        zh = "盛在纸杯里、淋上鲜艳水果风味糖浆的细腻清凉刨冰。细密的碎冰在舌尖瞬间融化化作阵阵沁人心脾的冰爽与甘甜，在酷热难耐的末日盛夏午后，这一杯冰品能让人瞬间驱散所有燥热中暑威胁。",
        en = "A paper cone packed with finely shaved clean ice and drenched in vibrant sweet syrup. Melting into icy refreshing sweetness on the tongue, it provides divine cooling relief during blistering post-cataclysm summer heat waves.",
    },
    ["snowcone_alcoholic"] = {
        zh = "淋上烈性高度蒸馏酒与果味糖浆的成人特调微醺刨冰。冰凉碎冰在嘴里爆发出辛辣酒精与甜蜜果香的双重风暴，既能迅速降温防暑，又能借着微醺酒意让疲惫的守夜人暂时忘却身外的腥风血雨。",
        en = "A frosty shaved-ice cone spiked generously with high-proof moonshine and fruit cordials. Combining freezing sweetness with fiery distilled warmth, it delivers an intoxicating, cooling buzz that numbs apocalyptic exhaustion.",
    },
    ["snuggie"] = {
        zh = "带有肥大宽松袖子的柔软抓绒连体懒人保暖毯。坐在破沙发上翻看地图或擦拭枪械时能将双手完全解放，宽大的下摆将全身包裹得严严实实，既滑稽可笑又能带来抵御寒风的极致懒人舒适。",
        en = "The infamous fleece blanket tailored with oversized sleeves. Keeping arms unencumbered for reading technical manuals or cleaning rifles while enveloping the torso in soft warmth, it represents supreme, unapologetic bunker lounging comfort.",
    },
    ["soaked_dandelion"] = {
        zh = "经过清水长时间浸泡滤除苦涩汁液后得到的清亮蒲公英浸出提取液。去除了刺激性苦味，富含有机钾盐与利尿排毒成分，是调配温和降火草药茶以及减轻下肢水肿的古法养生药液。",
        en = "Clear dandelion infusion water strained after long soaking to leach away harsh bitter resins. Packed with natural potassium and gentle diuretic compounds, sipping this herbal liquid cleanses toxins and reduces limb swelling.",
    },
    ["soaking_dandelion"] = {
        zh = "已经完成脱苦过程、浸泡在水盆中的发酵蒲公英老叶。经过漫长时间的浸润，苦汁已基本析出，只需轻轻捞起沥干水分，便能切碎拌入油脂下锅炒菜，化为毫无怪味的温和野菜菜肴。",
        en = "Mature dandelion greens resting in water crocks through completed debittering cycles. With bitter tannins fully leached out, draining and sautéing these tender leaves provides mild, palatable salad greens free of acrid bitterness.",
    },
    ["soaking_dandelion_active"] = {
        zh = "正浸泡在装满清凉生水的陶盆中进行苦味脱涩的野生蒲公英叶片。水面上浮着细微的气泡，需要定时换水冲洗带走浓烈的生物碱苦味，是野外生存大厨将苦涩野菜驯化为美味盘中餐的必经步骤。",
        en = "Fresh dandelion foliage actively steeping inside a water basin to extract caustic plant resins. Requiring periodic water changes, this methodical soaking process tames harsh roadside weeds into mild nutritious greens.",
    },
    ["soaking_long_pole"] = {
        zh = "完全浸泡在特制天然防腐油脂槽中的长硬木杆。干燥的木质纤维正贪婪地吸收着桐油与蜂蜡，数天后捞出阴干，木杆将变得抗水抗裂、极富韧性且永不被虫蛀霉变，是制作高级长枪的顶级枪杆。",
        en = "A long straight hardwood stave submerged within a trough of preservative oils and waxes. Deeply absorbing hydrophobic resins, curing this pole renders it crack-proof and impervious to rot, ideal for mounting polearm heads.",
    },
    ["soaking_spear_shaft"] = {
        zh = "正在油桶中深层浸泡矿物油与熟桐油的削制长矛木柄。油分慢慢渗透进每一处导管缝隙，能大幅增强木料在猛烈突刺冲击下的抗弯折强度，让你的长矛在刺穿重甲目标时绝不至于折断脱手。",
        en = "A hand-planed spear shaft soaking within penetrating linseed and mineral oils. Sinking deep into the grain, this oil bath dramatically improves flexural toughness, preventing spear shafts from snapping when impaling thrashing brutes.",
    },
    ["soap"] = {
        zh = "末日里将文明人与丧尸区分开的唯一防线。就算全世界都在溃烂发臭，只要身上还带着一股柑橘或薰衣草香气，你就坚信自己依然属于高等灵长类动物——哪怕你刚在泥潭里摔了个狗吃屎。",
        en = "The fragile boundary separating a hardened survivor from a shambling corpse. Even as civilization rots around you, carrying a faint scent of lavender proves you are still human, even if you just slipped and dropped it in radioactive mud.",
    },
    ["soap_flakes"] = {
        zh = "由天然动物油脂与草木灰碱皂化后刨刮出来的一大包细腻干肥皂薄片。遇温水即可迅速溶解起泡，在洗涤浸满机油与血污的脏衣服时能彻底瓦解油垢，是避难所保持无菌卫生的清洁主力。",
        en = "Delicate dried soap shavings grated from cured blocks of tallow-lye soap. Dissolving swiftly into warm wash basins, these frothy suds strip grease and blood from filthy fatigues, halting the spread of bunker skin parasites.",
    },
    ["soap_holder"] = {
        zh = "带有条形沥水槽与防滑底脚的便携式硬塑料旅行肥皂盒。不仅能防止湿润的肥皂在背包里化成一滩烂泥污染重要物资，更能让肥皂在空气流通中快速风干硬化，极大地延长使用寿命。",
        en = "A molded plastic travel soap container equipped with draining ridges and a snap-tight lid. Keeping wet soap bars from turning into messy slime across your gear, it allows bars to dry properly between decontamination washes.",
    },
    ["soapy_water"] = {
        zh = "融化了肥皂、表面漂浮着厚厚一层五彩泡沫的温热肥皂水。不仅能用来刷洗沾满丧尸黑血的作战靴与防弹衣，在紧急时刻灌入误食毒物者的喉咙催吐，也是简单有效的野战急救偏方。",
        en = "A warm bucket of water frothing with slippery soap suds. Beyond laundering mud-caked field clothing and disinfecting work surfaces, drinking a warm cup can induce urgent emesis to purge accidentally ingested poisons.",
    },
    ["socket_screwdriver_set"] = {
        zh = "配有微型棘轮双向扳手手柄与全套六角套筒的精密螺丝刀组。小巧的手柄能在狭窄逼仄的枪身机匣内部灵活转动螺丝，是维修复杂光学仪器与机械枪机时不可或缺的高扭矩维修套件。",
        en = "A compact driver handle fitted with a reversible mini-ratchet and miniature metric sockets. Slipping into tight engine recesses and firearm chassis cavities, it provides high-torque turning leverage where ordinary screwdrivers cannot fit.",
    },
    ["socket_wrench_set"] = {
        zh = "装在重型铁皮手提工具箱内的专业级棘轮套筒扳手全套工具组。包含半英寸与八分之三驱动飞扳、加长接杆以及数十种不同规格的铬钒钢套筒，是彻底拆解并重新组装整辆卡车的重型修车灵魂神器。",
        en = "A comprehensive mechanic's socket wrench kit packed within a rugged metal toolbox. Featuring chrome-vanadium ratchets, extension bars, and universal joints, it provides the essential muscle for rebuilding vehicle transmissions and armor mounts.",
    },
    ["sockmitts"] = {
        zh = "在脚跟处剪出拇指孔、套在双手上当防寒手套的一对厚羊毛旧袜子。外表虽然显得滑稽古怪，但厚实保暖的羊毛针织物能妥善捂热冻僵的指头，是在寒风刺骨的废墟中毫无花费的保暖手套替代品。",
        en = "A pair of thick wool socks snipped with thumb holes to serve as improvised mittens. Looking delightfully ridiculous on your hands, their dense woolen knit wards off frostbite when proper winter combat gloves are nowhere to be scavenged.",
    },
    ["socks"] = {
        zh = "由纯棉与弹力纤维混纺而成的标准男女通用保暖长袜。紧密包裹脚踝与足底，吸收长途拉练产生的汗水并有效减少靴底摩擦起水泡的惨剧，在废土行军法则中，一双干爽好袜子的价值甚至超过子弹。",
        en = "A pair of comfortable crew socks knitted from breathable cotton with elastic arch supports. Absorbing march sweat and preventing crippling heel blisters, seasoned infantry know dry clean socks are worth more than loose cartridges.",
    },
    ["socks_ankle"] = {
        zh = "仅覆盖到脚踝下方的轻薄运动透气船袜。适合炎炎夏日搭配轻量化跑鞋穿戴，通风清凉不易积汗，虽然无法提供小腿防灌木刮擦保护，但极短的版型能在剧烈奔跑中保持足部干爽轻快。",
        en = "Low-cut athletic ankle socks designed to remain invisible inside running shoes. Offering maximum ankle coolness and rapid sweat evaporation during sweltering summer marches, they keep feet dry during high-speed supply runs.",
    },
    ["socks_bag"] = {
        zh = "采用极其宽松剪裁的宽筒棉袜。没有紧绷勒肉的松紧带束缚，穿在脚上松松垮垮却通风透气，在避难所漫长的静坐休息或病榻调养时穿戴，能彻底避免小腿水肿并维持舒爽足部微循环。",
        en = "Loose-fitting cotton slouch socks designed without constricting elastic bands. Permitting airy foot breathability during long convalescent bunk rests, they prevent lower-leg edema while keeping sore feet warm.",
    },
    ["socks_bowling"] = {
        zh = "保龄球馆发给顾客穿戴的超薄廉价一次性无纺布短袜。薄如蝉翼且完全没有任何保暖防磨功能，唯一的用处是在穿上别人的公用鞋子时，充当阻隔脚气真菌交叉感染的单薄心理防线。",
        en = "Ultra-thin disposable non-woven socks handed out at bowling alleys. Offering virtually zero thermal warmth or blister cushioning, their flimsy existence merely acts as a psychological barrier against communal fungal spores.",
    },
    ["socks_wool"] = {
        zh = "采用天然纯羊毛粗线手工编织而成的重磅保暖厚冬袜。即便被冰雪雪水浸湿，天然羊毛纤维依然能神奇地锁住体温保持发热，是极地风雪巡逻中防止脚趾坏死发黑截肢的贴身护命神袜。",
        en = "Heavy winter socks hand-knitted from coarse sheep wool yarns. Miraculously retaining insulating warmth even when thoroughly soaked by slush, they form an indispensable bulwark against catastrophic toes frostbite.",
    },
    ["soft_3a_vest"] = {
        zh = "由数十层轻量化高分子防弹纤维复合叠合而成的 III-A 级软质防弹背心。贴身轻便且隐蔽性极佳，能从容抵御绝大多数大威力手枪子弹与致命爆炸破片的近距离轰击，保护躯干内脏。",
        en = "A concealable Level III-A soft ballistic armor vest constructed from multi-layered aramid sheets. Flexible and discreet under jackets, it reliably absorbs high-velocity handgun rounds and explosive shrapnel impacts.",
    },
    ["soft_adobe_brick"] = {
        zh = "将黏土、沙子与稻草碎屑混合加水在木模中压实成型的湿土坯砖。虽然质地沉重，但内部水分尚未蒸发完全，一捏就碎，必须在干燥通风的托盘上经过数周烈日暴晒才能硬化成坚固砌块。",
        en = "A freshly pressed earthen adobe block compacted from damp clay, sand, and straw binder. Still soft and malleable, this unfired masonry block must dry under hot sunlight before bearing construction loads.",
    },
    ["soft_adobe_brick_active"] = {
        zh = "正摆在通风处接受风吹日晒、处于积极脱水硬化过程中的土坯砖。表面已经逐渐泛白结壳并散发出泥土芬芳，内部正缓慢析出湿气，是自力更生修筑厚实避难所防御夯土墙的核心基石。",
        en = "A curing adobe brick actively drying on an open-air rack. Its clay surface gradually lightens and hardens under gentle breezes, steadily locking starchy straw fibers into rock-like sustainable masonry blocks.",
    },
    ["software_archived_data"] = {
        zh = "存储在军规优盘里的海量历史灾难存档数据。里面记录着各大避难所失联时间表与各州沦陷的绝密报告，翻阅这些冰冷的数字，能清晰还原文明是如何在一周内分崩离析的。",
        en = "A ruggedized thumb drive packed with encrypted municipal disaster archives. Chronological logs detail fallen regional outposts and military retreats, documenting the terrifying speed at which society dissolved into ash.",
    },
    ["software_blood_data"] = {
        zh = "记录着变异黑血样本生化分析结果的科研数据库文件。密密麻麻的核酸变异序列与细胞重组图表令人目眩神迷，是逆向破解变异血清与生物疫苗的无价知识钥匙。",
        en = "A specialized software package archiving biochemical assays on contaminated black blood. Dense charts illustrating mutating genetic strands provide crucial stepping stones for synthesizing theoretical neutralizing vaccines.",
    },
    ["software_electronics_reference"] = {
        zh = "收录了上万种集成电路芯片引脚图与电气参数的技术资料库。对于在工作台前摆弄烙铁与电容的末日工程师来说，它是从无到有手搓高级激光武器与发电机组的圣经宝典。",
        en = "A comprehensive digital datasheet repository cataloging thousands of integrated circuit schematics. To workbench engineers rewiring salvaged motherboards, it functions as a holy text for crafting high-tech energy armaments.",
    },
    ["software_encryption_codes"] = {
        zh = "包含联邦政府高层战时加密通信密钥的保密软件载体。虽然白宫早已化为废墟且各级指挥中心无人应答，但用它来破译军用通讯中继站广播依然能截获关键空投情报。",
        en = "A secured partition holding federal wartime encryption algorithms. While commanding generals are long dead, utilizing these cryptographic keys decrypts automated military repeater broadcasts to pinpoint emergency supply drops.",
    },
    ["software_hacking"] = {
        zh = "大灾变前黑客圈流传的顶级入侵套件hackPRO。集成了全自动溢出攻击与逻辑后门跳板，只需将其插入银行金库或军火库的电子锁控制面板，就能像推开自家房门一样轻松破译。",
        en = "The legendary hackPRO automated intrusion suite copied onto an optical disc. Featuring brute-force exploits and zero-day backdoors, inserting it into secured military terminals cracks electronic lockouts in seconds.",
    },
    ["software_lab_data"] = {
        zh = "从绝密地下生化实验室主机中强行拷贝出来的原始实验记录。里面详尽记载着异界传送门打开时引发的空间畸变参数，字里行间充满了研究人员从狂喜走向无尽绝望的心理转变。",
        en = "Raw laboratory experimental telemetry extracted from deep subterranean mainframes. Detailing portal containment ruptures and dimensional incursions, it reveals the chilling descent from scientific hubris into horrific annihilation.",
    },
    ["software_math"] = {
        zh = "一套专为高阶微积分与微分几何打造的极客数学计算软件。在没有电脑的末日里虽然无法直接运行，但在旧手提电脑上加载后，能帮你精确测算自制加农炮的远距离抛物线弹道。",
        en = "Advanced computational mathematics software designed for calculus and ballistics modeling. Running it on salvaged laptops helps survivors calculate precise artillery firing solutions for improvised perimeter mortars.",
    },
    ["software_medical"] = {
        zh = "综合临床急救与战地外科手术指南数据库MediSoft。从截肢止血到处理重度变异毒液感染，里面详尽的三维动画演示能让一个手足无措的门外汉勉强冒充战地主刀医生。",
        en = "A comprehensive combat triage and emergency surgical database titled MediSoft. Step-by-step diagnostic algorithms guide trembling hands through complex amputations and alien toxin neutralizations in battlefield shelters.",
    },
    ["software_useless"] = {
        zh = "塞满无聊电子宠物、过期杀毒软件和毫无意义推箱子小游戏的杂项磁盘。在大灾变后的大多数时候它纯粹是在浪费磁盘空间，但在极度无聊的漫漫长夜里，它确实能消磨时间。",
        en = "A disorganized directory packed with obsolete bloatware and pixelated desktop pets. Useless for survival, booting up a forgotten tile-matching puzzle game helps maintain sanity through grim rainy nights.",
    },
    ["soggy_hardtack"] = {
        zh = "在热咖啡、肉汤或白开水中浸泡泡软的军用压缩饼干硬饼。原本硬得能崩碎大牙的石化面饼吸饱水分后化为糊状面泥，虽然口感黏糊烂熟，但终于能让牙齿松动的幸存者顺利吞咽充饥。",
        en = "A brick of rock-hard survival hardtack thoroughly soaked in boiling water or broth. Once capable of shattering molars, it softens into a warm mush that elderly wanderers can finally chew without dental catastrophe.",
    },
    ["solar_cell"] = {
        zh = "采用单晶硅或多晶硅切片加工而成的标准光伏太阳能发电池片。表面带有精细的银色集电栅线，只要在白昼朝向阳光，便能源源不断将光子转化为清洁电能，是末日能源重建的先锋元件。",
        en = "A crystalline silicon solar photovoltaic cell etched with fine silver gridlines. Silently converting cascading sunlight photons into direct electric current, it serves as the foundational semiconductor component for post-collapse power grids.",
    },
    ["solar_cell_v2"] = {
        zh = "应用了钙钛矿层叠技术的高效军规级第二代先进光电薄膜电池片。即便在阴雨连绵或浓烟遮蔽的昏暗天色下也能维持极高光电转化率，是为前沿高科技动力外骨骼自充储能的顶级能源明珠。",
        en = "An advanced multi-junction perovskite solar cell boasting revolutionary photon conversion efficiency. Generating robust voltage even under gloomy storm clouds and smoke plumes, it fuels elite experimental electronics reliably.",
    },
    ["solar_cooker"] = {
        zh = "带有抛物面高反光镜片与中心悬挂锅架的户外聚光太阳灶。将无处不在的太阳光线汇聚于焦点一处，无需消耗一滴柴火或汽油即可在几分钟内烧开一锅雪水，悄无声息且毫无烟雾暴露风险。",
        en = "A parabolic solar cooker featuring curved mirror facets concentrating sunlight upon a suspended cookware mount. Boiling water and roasting game without firewood or exhaust smoke, it eliminates detection risks across treeless plains.",
    },
    ["solar_panel"] = {
        zh = "封装在坚固耐震铝合金外框与钢化玻璃下的车载单晶硅太阳能电池板。牢固焊接在改装战车车顶，只要在烈日下巡航行军，便能为车载大容量蓄电池组源源不断补充电力，摆脱油荒困扰。",
        en = "A ruggedized vehicle-mounted solar panel framed within impact-resistant aluminum and tempered glass. Bolted atop roving survival rigs, it constantly trickles clean solar amperage into hungry storage batteries.",
    },
    ["solar_panel_v2"] = {
        zh = "军工特制的高功率增强型战车太阳能装甲板。具备超高光电转化效率与抗破片冲击涂层，不仅能在移动中以惊人速度灌满车底动力蓄电池，还能抵挡狂风飞石与轻弹流弹的飞溅撞击。",
        en = "A heavy-duty military-grade vehicular solar array surfaced with shatterproof ballistic polycarbonate. Delivering massive charging current while withstanding rock spatters, it keeps armored electric combat vehicles rolling indefinitely.",
    },
    ["solder_wire"] = {
        zh = "内部包裹松香助焊剂芯线的卷装锡铅合金软钎焊锡丝。熔点低且润湿流动性极佳，在电烙铁尖端轻轻一触便能化作明亮锡珠，牢牢焊死断裂的导线焊盘，是修复受损电子电路板的金属红娘。",
        en = "A spool of flux-cored tin-lead solder wire engineered for electronics assembly. Melting smoothly under modest heat, it bridges broken PCB traces and secures frayed wire splices with gleaming metallic bonds.",
    },
    ["soldering_iron"] = {
        zh = "制作精密电路不可或缺的神器，但它那根短得可怜的电线和对电网的严苛依赖，无时无刻不在嘲笑你这处连电灯都没有的破烂庇护所。更别提松香烟雾呛进肺里时，那股熟悉又致癌的旧工业时代余香。",
        en = "Crucial for fabricating high-tech circuitry, yet hamstrung by a comically stubby power cable that demands a functioning electrical grid. It perpetually mocks your off-grid shack, waiting for an opportunity to scorch your fingertips and fill your lungs with noxious rosin smoke.",
    },
    ["soldering_iron_portable"] = {
        zh = "由小型可充锂电池或丁烷气体供能的便携式无线电烙铁。几秒钟内烙铁头便能升温至数百摄氏度，无需拖拽繁琐的电线即可在狭窄车底或废墟机箱内快速焊接精密焊点，灵活机动。",
        en = "A wireless portable soldering iron powered by rechargeable lithium cells or refillable butane. Reaching operating temperature in seconds, it provides nimble precision repair capability inside cramped vehicle dashboards.",
    },
    ["sole_rubber"] = {
        zh = "采用耐磨硫化橡胶压铸成型、底面带有深凹槽抓地齿纹的独立靴底配件。抗刺穿防滑且耐机油腐蚀，用强力胶水与粗线缝合在磨穿的旧鞋底上，能瞬间让濒临报废的行军靴重焕新生。",
        en = "A replacement heavy vulcanized rubber shoe sole stamped with aggressive multi-directional lug treads. Resistant to punctures and oils, cementing it beneath worn boot uppers resurrects exhausted footwear instantly.",
    },
    ["soup_blood"] = {
        zh = "在热锅中将新鲜动物活血与醋汁、黑胡椒及草药文火慢熬而成的传统血汤。浓稠红褐的汤汁蕴含着极高浓度的生物活性铁与充沛蛋白质，趁热大口咽下，能让贫血虚脱的重伤员迅速恢复血色。",
        en = "A rich crimson soup simmered from fresh blood, vinegar, salt, and aromatic herbs. Thick and metallic on the tongue, swallowing this hot brew floods exhausted circulatory systems with bioavailable iron.",
    },
    ["soup_chicken"] = {
        zh = "用肥美整鸡、胡萝卜块、洋葱与爽滑面条慢熬出金黄油脂的热腾腾鸡汤面。汤清油润且鲜美四溢，每一口温热都抚平了受风寒折磨的咽喉，在末日破烂瓦砾间是一剂抚慰灵魂的心灵鸡汤。",
        en = "A steaming bowl of comforting chicken noodle soup bubbling with golden rendered fat and garden vegetables. Salty, savory, and restorative, it conquers bronchial chills while lifting war-torn survivor morale.",
    },
    ["soup_cullenskink"] = {
        zh = "以烟熏黑线鳕鱼干、土豆泥块、牛奶与洋葱慢炖而成的传统苏格兰卡伦浓汤。浓郁的烟熏海鱼鲜美与醇厚的乳香在舌尖交织，质地厚重如奶油浓汤，一碗下肚便能抵御整夜北海刺骨狂风。",
        en = "A thick traditional Scottish soup simmered from flaked smoked haddock, tender potatoes, onions, and creamy milk. Smoky, briny, and decadently hearty, it shields coastal survivors against howling freezing gales.",
    },
    ["soup_dumplings"] = {
        zh = "将鲜嫩鸡肉丁、松软面团团子与浓稠鸡高汤一同炖煮的经典鸡丁馄饨汤。浸润了浓郁肉汁的面团团子软糯可口，荤素交织且热气腾腾，是在阴冷潮湿防空洞里补充碳水与蛋白质的治愈盛宴。",
        en = "Fluffy dough dumplings simmered directly within savory chicken stock studded with shredded meat. Pillowy and soaked with herb broth, this classic comfort dish brings civilized warmth to damp survival bunkers.",
    },
    ["soup_fish"] = {
        zh = "用刚从清澈溪流中钓起的鲜活野鱼搭配野菜生姜煮成的清甜鱼汤。汤色乳白如牛乳，鱼肉鲜嫩且汤头清香回甘，不仅能有效补充消耗过度的电解质，更让饥民重温大自然最纯净鲜美的馈赠。",
        en = "A milky white broth simmered from freshly caught freshwater fish, wild alliums, and ginger. Clean, light, and naturally rich in essential fatty acids, it restores depleted electrolytes without burdening digestive tracts.",
    },
    ["soup_instant_chicken_noodle_powder"] = {
        zh = "脱水蔬菜碎、鸡肉香精晶体与细碎脱水面条混合干燥粉末包。保质期长达数年，只需往杯中注入滚烫沸水轻轻搅拌，几分钟内便能还原出一碗热气腾腾、香气扑鼻的速食鸡汤面。",
        en = "A sealed packet of dehydrated noodles, vegetable flecks, and savory chicken seasoning crystals. Shelf-stable for decades, stirring boiling water transforms this lightweight powder into steaming instant noodles.",
    },
    ["soup_instant_chicken_noodle_prepared"] = {
        zh = "刚刚冲入滚水冲泡开来的速食鸡汤方便面。弯曲的面条在金黄色的咸香汤头中翻滚，散发着熟悉的工业化味精与香精香气，在冰天雪地的废墟里捧在手心，能带来无可比拟的速食幸福感。",
        en = "A freshly reconstituted cup of instant chicken noodle soup emitting savory sodium-rich steam. While undeniably artificial in origin, slurping these warm noodles brings immediate caloric euphoria inside freezing outpost huts.",
    },
    ["soup_instant_vegetable_powder"] = {
        zh = "包含脱水胡萝卜碎、玉米粒、豌豆与综合蔬菜清汤粉的速食春菜汤粉包。小巧轻便且绝不怕潮发霉，是远征单兵行军口粮包里用来在夜晚迅速调配温热素菜汤的便携维生素补给源。",
        en = "A dehydrated soup packet packed with freeze-dried carrot cubes, green peas, and vegetable seasoning powders. Weighing almost nothing in packs, it reconstitutes with boiling water into wholesome garden broth.",
    },
    ["soup_instant_vegetable_prepared"] = {
        zh = "用沸水焖泡还原的热气腾腾速食春菜汤。各种脱水蔬菜片重新吸饱水分变得鲜嫩爽脆，碧绿与橙黄的蔬菜在清透的汤水中沉浮，给长途跋涉口干舌燥的拾荒者送来一口解渴暖胃的热蔬菜汤汁。",
        en = "A steaming mug of prepared instant vegetable soup colorful with reconstituted garden vegetables. Light, fragrant, and easy on stressed stomachs, it provides gentle hydration and essential micronutrients after bitter marches.",
    },
    ["soup_lobsterstew"] = {
        zh = "将整只鲜活变异大龙虾剁块、浸润在融化黄油、鲜牛奶与香草高汤中慢煨而成的豪华炖龙虾。肥美紧实的龙虾肉弹牙鲜甜，汤汁金黄浓郁，是废土海滨聚居地领袖在庆功宴上的奢靡天花板。",
        en = "A lavish maritime stew bubbling with succulent chunks of mutant lobster simmered in melted butter and cream. Sweet, tender lobster tail bathed in rich seafood stock represents absolute culinary decadence in ruins.",
    },
    ["soup_meat"] = {
        zh = "用各种搜刮来的杂肉切块与骨头在瓦罐中长时间炖煮而成的浓厚肉汤。表面浮着一层厚实凝固的动物油脂保温，舀上一大勺肉香四溢且咸鲜可口，是维持重体力劳动者力量与体温的硬派主食。",
        en = "A hearty pot of rich brown broth loaded with simmered meat chunks and marrow bones. Sealed by a glistening layer of rendered fat that traps boiling heat, it restores strength and warms bone marrow.",
    },
    ["soup_mushroom"] = {
        zh = "采集野生可食用牛肝菌与白蘑菇、拌入面粉黄油与骨汤煨成的浓郁野菌菇汤。散发着林间泥土与落叶般的深沉鲜香，汤质浓稠滑顺如丝绒，每一口都洋溢着大自然原生态的极致鲜味。",
        en = "Velvety cream soup simmered from wild foraged boletes and fresh meadow mushrooms. Earthy, rich, and fragrant with forest loam, its creamy texture soothes parched throats and delivers deep fungal Umami warmth.",
    },
    ["soup_three_sisters"] = {
        zh = "遵循美洲原住民传统农法将玉米粒、菜豆与南瓜块共同熬煮的“三姐妹”杂粮炖菜。三种作物在土地上相伴相生，在汤锅中碳水化合物、植物蛋白与维生素完美互补，是高产又均衡的素食奇迹。",
        en = "A traditional Native American succotash stew harmonizing sweet corn kernels, tender beans, and squash. Providing complete plant proteins and balanced carbohydrates, this ancestral recipe nourishes camps through harsh winters.",
    },
    ["soup_tomato"] = {
        zh = "用熟透新鲜红番茄剥皮切碎、搭配洋葱香草慢火煨出的红亮番茄浓汤。酸甜多汁且富含茄红素，搭配烤热的面包片蘸着吃，能瞬间唤醒被恶心干粮折磨得麻木不仁的味蕾。",
        en = "A vibrant scarlet soup pureed from vine-ripened tomatoes, sweet onions, and garden herbs. Bright with refreshing acidity and natural lycopene, dipping toasted hardtack creates an irresistible civilized comfort meal.",
    },
    ["soup_veggy"] = {
        zh = "将南瓜、胡萝卜、马铃薯与切碎甘蓝菜叶汇聚一锅熬出的杂菜浓汤。汤汁清甜爽口且富含膳食纤维与多种维生素，对于长期依赖咸肉干干粮而饱受坏血病折磨的幸存者而言是名副其实的救命汤。",
        en = "A thick multi-vegetable soup bubbling with root tubers, diced squash, and shredded cabbage leaves. Rich in dietary fiber and essential vitamins, this cleansing vegetable medley reverses scurvy and revitalizes digestion.",
    },
    ["soup_woods"] = {
        zh = "把林间猎获的野兔、松鼠肉丁与沿途采摘的野生草药野菜混合铁锅乱炖的森林杂烩肉汤。融合了荒原动物的野性肉香与天然草本的清冽，是一锅充满游侠探索浪漫的野战热食。",
        en = "A rustic wilderness stew concocted from foraged wild game cuts and woodland herbs simmered over open campfires. Combining rich gamey proteins with fresh botanical aromatics, it fuels nomadic scouts tracking through deep pine woods.",
    },
    ["soup_woods_egg"] = {
        zh = "在滚烫野草高汤中淋入打散的变异鸟蛋蛋液制成的森林杂烩蛋花汤。金黄色的蛋花在碧绿野草汤中如云朵般漂浮，入口软嫩丝滑且清香解渴，是树林安营扎寨后最快速简便的高蛋白温热晚餐。",
        en = "A delicate egg drop soup swirling whisked wild bird eggs into boiling herbal broth. Light, fragrant, and packed with gentle proteins, it provides quick, soothing nourishment beside flickering sunset campfires.",
