    ["subwaystationmap"] = {
        zh = "张贴在地铁站台墙面上的旧世界换乘路线与站点分布全图。上面用不同色线标注着纵横交错的地下交通网络，虽然许多区间早已坍塌积水，但能帮你指引通往相邻街区的隐秘地下通道。",
        en = "A color-coded subway transit route map salvaged from subterranean platform walls. Though cave-ins and radioactive water floods block various sections, it reveals secret underground tunnels linking distant metropolitan districts.",
    },
    ["succotash"] = {
        zh = "将甜玉米粒与利马豆混合在动物油脂中一同慢煮而成的传统美洲玉米菜豆饭。软糯的豆子与爽脆清甜的玉米粒在口中交融，不仅易于咀嚼消化，更能提供极其均衡全面的植物蛋白质热量补给。",
        en = "A wholesome Native American succotash combining sweet corn kernels and lima beans simmered in lard. Soft, sweet, and comforting on weary palates, it supplies well-balanced amino acids from modest garden harvests.",
    },
    ["succotash_deluxe"] = {
        zh = "在玉米菜豆中额外加入大量香脆咸肉丁、红椒碎与香浓黄油的豪华版炖菜。浓郁的荤油香气将蔬菜的甘甜烘托到极致，热气升腾间每一勺都洋溢着富足与治愈，是荒原难得的顶级盛宴。",
        en = "A gourmet upgrade of classic succotash bursting with crispy salted bacon crumbles, bell peppers, and melted butter. Elevating humble field legumes into rich savory perfection, it turns basic survival rations into festive banquets.",
    },
    ["sugar"] = {
        zh = "纯净雪白的精制结晶蔗糖或甜菜糖颗粒。不仅是烹饪烘焙时抚慰焦虑神经的甜蜜调味品，在战伤急救中将厚厚白糖直接倒在严重感染创口上，也是利用高渗透压杀菌排脓的古法救命偏方。",
        en = "Granulated pure sucrose crystals sparkling like refined white sand. Beyond satisfying desperate sugar cravings, pouring sterile sugar granules directly over deep suppurating wounds draws out infectious moisture via osmotic pressure.",
    },
    ["sugar_beet"] = {
        zh = "从肥沃农田中挖掘出来的沉甸甸白色圆锥形大甜菜根。切开后质地紧实，含有高达近百分之二十的纯天然蔗糖，切丝加水慢熬熬出糖浆并结晶，是避难所实现食糖自给自足的农业王牌根茎。",
        en = "A massive conical white taproot harvested from deep fertile garden soil. Packing nearly twenty percent sucrose by weight, boiling down its grated pulp yields sweet crystalline syrup to restock depleted post-collapse pantries.",
    },
    ["sugar_fried"] = {
        zh = "将纯白糖在铁锅中加热熔融、在高温下缓慢焦糖化凝固而成琥珀色脆焦糖。散发着令人欲罢不能的黄油焦香与烘烤坚果香气，含在嘴里慢慢融化，能让麻木的味蕾瞬间被汹涌的纯甜风暴淹没。",
        en = "Golden-brown brittle caramel produced by slow-melting granulated sugar until deep pyrolysis occurs. Emitting intoxicating toasted toffee aromas, letting a shard dissolve over your tongue delivers intense glycemic bliss.",
    },
    ["suit"] = {
        zh = "采用精纺纯羊毛裁剪缝制的旧时代商务西装套装。线条挺括且带有优雅的丝绸衬里，虽然在末日泥泞废墟中摸爬滚打极其容易被扯烂刮花，但穿上它出席谈判峰会能彰显不可动摇的体面威仪。",
        en = "A tailored wool two-piece business suit featuring structured shoulders and silk lining. Looking hilariously impractical amid smoking craters, donning this crisp attire commands aristocratic diplomatic respect during tense faction summits.",
    },
    ["suitcase_l"] = {
        zh = "配有伸缩拉杆与静音滑轮的大号硬壳旅行行李箱。坚固的聚碳酸酯外壳抗摔耐磨，内部空间充沛得能塞下几十件衣服与整箱罐头，在平整的水泥公路或地铁隧道中拖行搜刮极为省力。",
        en = "A large hardshell rolling suitcase fitted with an extendable pull handle and spinner wheels. Swallowing weeks of scavenged clothing and canned goods within cavernous compartments, it rolls effortlessly along smooth highway pavements.",
    },
    ["suitcase_m"] = {
        zh = "中等尺寸的便携式带轮旅行行李箱。既兼顾了充裕的储物装载容量，又能在紧急时刻单手拎起快步奔跑，是游走于废弃机场、豪华酒店与火车站之间搜刮高价值轻工物资的黄金移动货舱。",
        en = "A versatile medium rolling suitcase balancing substantial storage capacity with nimble mobility. Handily lifted single-handedly over barricades, it remains the favored mobile treasure chest for raiding abandoned luxury hotels.",
    },
    ["sun_shield"] = {
        zh = "采用宽大防紫外线镀膜镜片制成的手术或日常防晒面罩。能够从额头一直覆盖到下巴，将刺眼的烈日暴晒、致命紫外线以及飞扬的微尘彻底阻隔在外，保护面部皮肤免遭严重日光灼伤与脱皮。",
        en = "A full-face UV-blocking visor shield descending from brow to chin. Deflecting blinding solar glare and harsh radiation, it prevents debilitating facial sunburns when trudging endlessly across shade-free asphalt wastelands.",
    },
    ["sundae_cup"] = {
        zh = "装有冰淇淋、淋上巧克力熔浆并点缀着酒渍樱桃的甜点圣代杯。融化的奶油在舌尖化作无尽的甜蜜甘泉，在酷热难耐的废墟午后挖上一大勺，能让饱受精神摧残的幸存者幸福得几乎窒息。",
        en = "A decadent sundae cup layering frozen cream, hot fudge sauce, and a candied cherry. Melting into pure frozen ecstasy on the tongue, it offers an almost tearful taste of lost civilization's sweetest indulgences.",
    },
    ["sundress"] = {
        zh = "采用轻薄纯棉碎花布缝制的无袖吊带连衣裙。面料透气飘逸，在夏日微风吹拂下清凉无比，虽然在近身厮杀中毫无防御，但那明媚的碎花在灰暗废墟中犹如一朵傲然绽放的希望之花。",
        en = "An airy floral sundress stitched from lightweight printed cotton with delicate shoulder straps. Refreshingly cool against summer heat, its cheerful blossoms inject defiant beauty and tender humanity into grim ruins.",
    },
    ["sunflower"] = {
        zh = "一朵硕大如盘、开满金黄色鲜艳花瓣的怒放向日葵花盘。中心密密麻麻排列着即将成熟的葵花籽，不仅是引来珍贵蜜蜂传粉的生态明珠，花谢之后更能收获满满一碗高热量高油脂的饱腹坚果。",
        en = "A radiant golden sunflower blossom as wide as a dinnerplate. Following the post-cataclysm sun, its dense seeded center matures into hundreds of calorie-rich, oil-heavy sunflower seeds to sustain long winters.",
