    ["surv_rocket_launcher"] = {
        zh = "用厚壁灌浆钢管、废弃手电筒把手与自制压电引信拼凑焊接而成的土制火箭发射筒。虽然外表粗暴如同一截生锈排水管，但能将自制高爆火箭弹以致命动能抛射出去，将敌方轻装甲载具炸成火球。",
        en = "A crude shoulder-fired rocket launcher improvised from thick steel casing and an electrical piezo-igniter. Lacking optics and safety interlocks, it hurls homemade rockets that obliterate enemy technicals in thunderous fireballs.",
    },
    ["survival_book"] = {
        zh = "记载着十九世纪落基山脉毛皮猎人旷野求生绝技的《山人自传》。书中图文并茂详述了徒手钻木取火、生皮鞣制、雪地设伏陷阱与野外辨识草药的硬核绝活，是自力更生荒原求生的至高启蒙宝典。",
        en = "A classic frontiersman manual chronicling raw 19th-century mountain survival techniques. Detailing friction fire-starting, wilderness trapping, and medicinal plant foraging, absorbing its timeless wisdom turns green scavengers into grizzled trailblazers.",
    },
    ["survival_kit_box"] = {
        zh = "采用气密防水密封圈、表面带有防滑凹槽的抗冲击聚合物野外生存工具箱。内部包含线锯、火石、净水片与微型鱼钩，只要把它塞入随身背包，即使流落荒山野岭也能迅速展开全套求生自救。",
        en = "A waterproof crushproof polymer container packed with essential survival sundries. Holding wire saws, ferrocerium rods, purification tablets, and fishing line, carrying this compact case secures baseline life support in emergencies.",
    },
    ["survival_marker"] = {
        zh = "装有高浓度耐候快干油墨的加粗战术防水记号笔。笔尖坚硬如凿，能在潮湿的岩石、生锈的铁皮与满是油污的废弃砖墙上留下永不褪色的黑色粗体标记，为远征队友留下珍贵的方位指引路标。",
        en = "A heavy-duty waterproof permanent marker filled with industrial pigmented ink. Writing legibly across damp stone, greasy metal, and rusted brick, it scrawls durable directional waypoints that guide following squadmates safely.",
    },
    ["survival_match"] = {
        zh = "药头极长且通体包裹厚实防水蜡质的特战风暴生存火柴。引燃后哪怕被狂风呼啸吹拂甚至浸入冰冷溪水中也依然狂暴喷射烈火，是狂风暴雨与极寒冰雪绝境中点燃救命营火的无上点火神物。",
        en = "Extra-long stormproof survival matches coated in water-resistant sulfur lacquer. Burning with fierce chemical intensity even when submerged in icy rivers, they guarantee campfire ignition in ferocious gale-force blizzards.",
    },
    ["survivor223mag"] = {
        zh = "用废弃铁皮罐头手工折弯打孔、配以自制钢丝弹簧的 5 发 .223 口径自制弹匣。虽然外观凹凸不平带有手作铁锤敲击痕迹，但紧凑短小的体积能平齐弹匣井，为自制步枪提供可靠的五连发供弹支持。",
        en = "A 5-round homemade STANAG-compatible magazine hammered from food tin scrap and piano wire springs. Fitting flush inside magwells, this humble handmade magazine feeds five rifle rounds without jamming.",
    },
    ["survivor9mm_mag"] = {
        zh = "为斯登冲锋枪量身手工焊接敲打的 20 发 9 毫米自制钢制直弹匣。弹身质感粗粝但托弹簧力道十足，进弹口经过手工细心锉磨去毛刺，在物资奇缺的废土上能让你的自动武器始终保持压制输出。",
        en = "An improvised 20-round steel stick magazine hand-brazed for STEN submachine guns. Though bearing rough filing marks across its feed lips, its stiff handmade spring feeds twenty 9mm rounds during frantic hallway shootouts.",
    },
    ["survivor_adhoc_leather_pants"] = {
        zh = "在耐磨帆布裤腿的膝盖与大腿正面大面积缝钉厚实熟牛皮防刮垫片的工装裤。兼顾了纯棉裤装的透气舒适与皮革的耐磨抗刺性能，在瓦砾碎石中频繁跪地攀爬也不会磨破皮肉。",
        en = "Rugged canvas work trousers reinforced across knees and thighs with thick tanned leather patches. Combining fabric breathability with heavy hide abrasion resistance, they protect patellas when scrambling over jagged concrete debris.",
    },
    ["survivor_adhoc_leather_shirt"] = {
        zh = "在胸口、后背与手肘部位缝衬了柔软厚牛皮护垫的改装长袖衬衫。既能有效阻挡近身撕扯的利爪刮擦与流弹碎石飞溅，又绝不会像沉重全钢铠甲那样拖慢战术动作，兼顾防护与轻盈灵动。",
        en = "A heavy flannel shirt reinforced across the chest, shoulders, and elbows with supple leather panels. Deflecting glancing claws and gravel without the crushing weight of steel armor, it keeps agile scouts nimble.",
    },
    ["survivor_adhoc_leather_sleeves"] = {
        zh = "由多层加厚熟牛皮管与可调松紧绑带制作的一对自制战术护臂袖套。套在小臂上能在近身肉搏格斗中从容格挡丧尸的撕咬与锐器砍击，保护手腕与前臂尺骨免受穿透骨折之灾。",
        en = "A pair of heavy leather forearm sleeves fitted with adjustable cinch straps. Sliding over arms, they form an impenetrable shield to absorb snapping bites and knife parries during frantic hand-to-hand brawls.",
    },
    ["survivor_adhoc_leather_torso"] = {
        zh = "躯干核心重要部位包裹厚实硬牛皮护胸的无袖衬衫战术背心。去除了双袖以释放双臂极速挥刀劈砍的灵活性，坚韧的皮革胸甲紧紧贴合胸腹，为心肺脏器构筑起一道抵抗锐刺的轻质护盾。",
        en = "A sleeveless vest constructed from thick leather armor plates riveted over tough canvas. Freeing arms for uninhibited sword slashes, the rigid chest plating shields vital heart and lung zones against stabbing shivs.",
    },
    ["survivor_belt_notools"] = {
        zh = "采用双层加厚军规尼龙织带与合金快速插扣手工缝制的多功能战术腰带。腰带外圈整齐缝满了模块化战术挂载环扣与小刀鞘挂点，结实得足以承受数十公斤外挂负重而不下坠变形。",
        en = "A heavy-duty handmade utility belt crafted from double-thick nylon webbing and a quick-release buckle. Ringed with reinforced gear loops, it distributes heavy holsters and pouches across hips without sagging or pinching.",
    },
    ["survivor_dry_bag"] = {
        zh = "采用防弹凯夫拉编织层与加厚 PVC 防水涂层复合制成的装甲级气密防水包。顶部采用经典三折卷口卡扣闭锁，不仅丢入深潭中内部绝对滴水不渗，坚硬的芳纶外层更能防止被树枝岩石划破。",
        en = "An armored dry bag fusing ballistic Kevlar fabric with waterproof polymer roll-top closures. Completely submersible without leaking, its slash-resistant outer armor protects sensitive electronics and medical supplies from thorns.",
    },
    ["survivor_dry_duffelbag"] = {
        zh = "大容量圆筒形装甲气密防水行李包。外表包裹防刮耐撕裂的重型复合纤维层，配有加粗承重提手与双肩背带，哪怕扛着它涉渡齐胸深的急流毒河，内部沉重的被褥与枪械弹药依然绝对干燥如初。",
        en = "A cavernous cylindrical duffel bag constructed from puncture-proof rubberized armor cloth. Featuring watertight heat-sealed seams, wading through waist-deep radioactive runoff leaves packed blankets and ammunition bone-dry.",
    },
    ["survivor_duffel_bag"] = {
        zh = "在重磅粗帆布行李袋关键受力部位与底部缝缀了防割凯夫拉与厚牛皮的装甲行李包。容量极其庞大惊人，耐磨抗拖拽，能把从整座超市搜刮来的数百听罐头与重零件一口气打包拖曳回营地。",
        en = "A high-capacity military duffel reinforced across the base with Kevlar and heavy leather scuff-pads. Built to survive abusive gravel drags, it hauls mountains of scavenged canned goods home without ripping.",
    },
    ["survivor_goggles"] = {
        zh = "采用厚实防弹聚碳酸酯镜片与柔软密封硅胶圈纯手工组装的自制防护护目镜。全封闭式防风尘防酸雾设计，配有宽大弹力头带，无论是迎战喷酸变异巨虫还是穿越沙暴废墟都能护得双眼周全。",
        en = "Handcrafted hazard goggles pairing shatterproof polycarbonate lenses with a soft rubber sealing gasket. Fully sealing against toxic dust storms, acid splashes, and smoke, they preserve priceless vision in apocalyptic environments.",
    },
    ["survivor_hairtrimmer"] = {
        zh = "由小巧锋利的打薄剪刀、不锈钢细密梳子与一把老式直剃刀组成的简易手工理发工具包。在满头长满虱子寄生虫与沾满污泥脏物的绝望废土上，仔仔细细剃光或修整短发是保持卫生的头等大事。",
        en = "A compact personal grooming roll containing thinning shears, a fine-toothed comb, and a folding razor. Keeping hair neatly cropped halts parasitic lice outbreaks while ensuring comfortable airtight fits on gas masks.",
    },
    ["survivor_jumpsuit"] = {
        zh = "在坚韧连体工装服全身要害关节处复合了高韧性防刺皮革与轻质阻燃纤维的自制多功能战斗服。一体化剪裁彻底杜绝冷风与灰尘从腰际灌入，多达十几个战术口袋让所有求生杂物触手可及。",
        en = "A custom-tailored survival jumpsuit reinforced with leather limb pads and flame-resistant fabric layers. Its one-piece design eliminates drafty waist openings, while dozens of cargo pockets keep tools organized and ready.",
    },
    ["survivor_machete_qt"] = {
        zh = "经过精心回火处理的顶级高碳弹簧钢幸存者战斗砍刀。刀头加宽重心靠前，刀刃刚韧兼备永不卷刃，在劈开丛林荆棘与斩飞丧尸肢体时如热刀切黄油般顺滑高效。",
        en = "A combat machete crafted from tempered spring steel with a forward-weighted chopping head. Impervious to chipping or warping, it carves through dense briars and undead spines with devastating fluid momentum.",
    },
    ["survivor_pack"] = {
        zh = "外层覆有凯夫拉防割面料、内衬硬质铝合金内背负支架的战术装甲中型背包。不仅具备卓越的人体工学背负减震系统，坚硬的背板还能在背后遭受丧尸突然从阴影中扑咬时充当防刺护盾。",
        en = "A medium survival backpack armored with slash-resistant Kevlar exterior paneling over an internal aluminum frame. Distributing loads comfortably across hips, its rigid armored back panel doubles as an improvised spine protector.",
    },
    ["survivor_rig"] = {
        zh = "基于人体力学精巧缝制的全身分布式负重外挂索具系统。能够将沉重的武器、手雷袋与水壶负重从双肩均匀分散到腰胯骨盆与双腿之间，让全副武装的废土战士在长途急行军中保持惊人的耐力。",
        en = "An ergonomic load-bearing webbing harness distributing equipment mass across the hips and pelvis. Preventing chronic shoulder strain, it allows fully geared combatants to sprint and maneuver without painful bouncing gear.",
    },
    ["survivor_rucksack"] = {
        zh = "容量超过八十升、通体经防弹芳纶加固的重型远征装甲旅行大背包。配有可调节厚实腰封与重型外挂织带系统，能够背负幸存者迁徙移动的整套营地家当，是在危机四伏的无名荒野开荒的移动堡垒。",
        en = "A massive eighty-liter expedition rucksack armored with ripstop aramid canvas and heavy load-transfer hip belts. Packing entire base camps across uncharted wastes, it serves as the ultimate nomadic survival life-support vessel.",
    },
    ["survivor_runner_pack"] = {
        zh = "采用防割凯夫拉与加厚耐磨皮革手工复合缝制的装甲轻量化跑步包。紧密贴合腰际绝无颠簸晃动，不仅能随身携带弹药与止血带，坚硬的外层在被丧尸背后飞扑时还能充当防咬小护盾。",
        en = "A streamlined runner's waist pack armored with slash-proof Kevlar and harness leather. Hugging the hips securely during full sprints, its tough outer shell prevents biting claws from tearing into your kidneys.",
    },
    ["survivor_scope"] = {
        zh = "利用废弃相机变焦镜头与黄铜套管手工拼装而成的便携式多节可伸缩单筒望远镜。拉开镜筒在微光下能清晰观察数公里外的敌方哨卡与尸潮动向，折叠收拢后仅有一掌大小，轻便隐蔽。",
        en = "A brass drawtube field telescope assembled from camera optics and scavenged tubing. Extending smoothly to reveal distant sentry movements across barren ruins, it collapses neatly into pocket dimensions when marches resume.",
    },
    ["survivor_shavingkit"] = {
        zh = "由打磨锋利的折叠老式刮刀、粗陶磨石与猪鬃剃须刷拼凑而成的自制剃须套件。在缺乏现代日化用品的野外，定期刮去发痒的面部胡须不仅让人神清气爽，更能让防毒面具的橡胶边缘绝对贴合气密。",
        en = "An austere grooming kit containing a strop-sharpened straight razor and bristle brush. Scraping away filthy beard growth preserves civilized dignity while guaranteeing airtight rubber seals on lifesaving gas masks.",
    },
    ["survivor_suit"] = {
        zh = "融合了防弹芳纶、防刺熟皮革与耐磨厚帆布的终极自制全覆式幸存者战斗套装。全方位防护全身要害脏器与脆弱关节，不仅抗撕咬防刀砍，甚至能抵御流弹破片洗礼，是末日生存的重装终极战甲。",
        en = "A mastercrafted suit of modular survival armor compounding Kevlar weave, ballistic leather, and treated canvas. Offering balanced coverage against feral bites, shiv thrusts, and shrapnel blasts, it defines hardened frontier champions.",
    },
    ["survivor_vest"] = {
        zh = "由高强度尼龙织带与多组模块化皮套手工编织缝缀的轻量化自制战术携行具。能够将弹匣、投掷物、医疗急救包与随身匕首科学收纳在胸前易于抓取的位置，极大提升了拔刀掏枪的近身交火反应速度。",
        en = "A lightweight handmade tactical chest harness braided from high-tensile nylon webbing. Distributing magazines, trauma dressings, and combat knives across your chest, it provides instantaneous weapon access during chaotic skirmishes.",
