    ["sushi_fishroll"] = {
        zh = "用烘烤紫菜海苔包裹新鲜醋饭与鲜嫩野生鱼肉卷切而成的经典鱼肉卷寿司。鱼肉爽滑弹牙，米饭酸甜适口，海苔的爽脆海盐风味在舌尖绽放，在满目疮痍的废土上能带来无可挑剔的极致雅致享受。",
        en = "A classic rolled maki sushi wrapped in crisp toasted nori seaweed and seasoned vinegar rice. Starring fresh river fish fillets, each bite-sized roll delivers refined culinary elegance and clean protein amidst ruins.",
    },
    ["sushi_meatroll"] = {
        zh = "用整张海苔卷成圆锥形、里面塞满温热米饭与香煎熟肉条的豪迈肉手卷寿司。外脆内软且肉香扑鼻，无需筷子即可单手直接大口享用，兼顾了日式料理的精致风味与行军战士对纯粹肉食的狂热渴望。",
        en = "A cone-shaped temaki hand roll packed with seasoned sushi rice and savory grilled meat slices. Designed for quick one-handed eating without chopsticks, it satisfies primal carnivore appetites with sophisticated street-food flair.",
