    ["suspenders_cloth"] = {
        zh = "采用纯棉织带与弹性松紧带制作的经典 Y 字型织物吊裤带。金属夹扣牢牢咬住裤腰边缘，将沉重的战术裤子重量从腰腹部转移至双肩分担，彻底避免了在狂奔逃命时裤子被重装备坠落绊脚的尴尬。",
        en = "Classic Y-back fabric suspenders fitted with durable steel alligator clips. Shifting the downward weight of tool-laden trousers directly onto the shoulders, they keep pants from unceremoniously dropping during dead sprints.",
    },
    ["suspenders_holster"] = {
        zh = "在宽大耐磨背带两侧巧妙整合了隐蔽手枪皮套的战术吊裤带。既承担着提拉裤子的本职功能，又能在腋下肋侧妥善隐藏一把自卫手枪，外穿夹克毫无痕迹，拔枪动作顺滑而极具老牌特工的优雅隐蔽感。",
        en = "A clever harness system combining heavy-duty pant suspenders with underarm holster sleeves. Concealing a compact sidearm flush along the ribs under jackets, it ensures pants stay up and sidearms stay hidden.",
    },
    ["suspenders_leather"] = {
        zh = "由油润厚实的熟牛皮带与坚固黄铜针扣铆接而成的老式粗犷真皮吊裤带。质地坚硬耐磨，散发着复古工装的厚重工业气息，哪怕裤兜里揣着大号铁锤与整盒重弹药，也能将裤头牢牢锁在腰际。",
        en = "Rugged work suspenders hand-cut from thick harness leather and secured with brass buckles. Built to endure decades of brutal wear, they shoulder the heaviest tool-laden trousers without stretching or failing.",
    },
    ["sustainment_pouch"] = {
        zh = "配有快速插扣盖板与内部束口抽绳的军规大容量持续保障战术副包。两侧带有标准莫利织带，可以快速外挂在大背包两侧，专门用来存放野战口粮、净水滤芯以及换洗衣物，大幅扩充巡逻续航能力。",
        en = "A large-capacity MOLLE sustainment pouch featuring an internal snow-collar drawstring and buckled lid. Mounting along backpack flanks, it carries three days of MRE rations and water bladders on long patrols.",
    },
    ["sw617"] = {
        zh = "拥有全钢重枪管与足足 10 发高容量弹巢的史密斯-韦森 617 竞赛级双动左轮手枪。发射微小的 .22 LR 子弹，射击精度惊人且后坐力微弱如吹气，十发连发能像手术刀般精准点射猎物的眼眶。",
        en = "The Smith & Wesson Model 617 stainless steel revolver sporting a full-underlug target barrel and 10-shot cylinder. Delivering virtually non-existent recoil, its smooth action punches ten rapid, pinpoint rimfire hits.",
