    ["tanto_fake"] = {
        zh = "旅游纪念品店里摆放的金属日式短刀工艺品。塑料电镀手柄配上未开刃的薄不锈钢片，拿来裁信封或者开快递还凑合，真要是拿去刺丧尸，刀刃当场就会从刀銎处滑脱。",
        en = "A decorative stainless steel tanto manufactured as an inexpensive souvenir. Lacking a hardened edge and glued into a loose cast fitting, thrusting it against bone immediately snaps the flimsy hilt.",
    },
    ["tanto_inferior"] = {
        zh = "废土拾荒者用生锈废铁条手工磨制而成的粗短刀。刃口粗糙且打磨痕迹杂乱，虽然重心偏手感极差，但那截坚硬的尖头在近距离摔跤肉搏中依然能稳稳凿入丧尸后颈。",
        en = "A crude short dagger ground from scrap spring steel on a sandstone wheel. Unrefined and ugly, its sharp triangular point nevertheless punches through necrotic cervical vertebrae in desperate ground wrestling.",
    },
    ["tape_measure"] = {
        zh = "带有自动收卷弹簧与醒目亮黄工程塑料外壳的二十五英尺钢卷尺。在末日搭建木工工事或丈量车辆改装底盘时必不可少，当然，无聊时把它拉得极长然后突然松手弹回也是最好的解压消遣。",
        en = "A spring-loaded steel tape measure encased in high-visibility yellow plastic. Indispensable for precise shelter construction and vehicle fabrication, whipping out several meters and letting it snap back remains peak post-apocalyptic boredom relief.",
    },
    ["target_spinner"] = {
        zh = "装有旋转轴承与双向对称厚钢板的专业射击训练靶标。当大威力步枪子弹命中一侧钢板时，整个靶身会在清脆的金铁撞击声中疯狂翻转，是在安全营地内检验枪法与发泄弹药过剩的绝佳玩具。",
        en = "A mechanical steel shooting target balancing paddle-shaped plates on a low-friction swivel axis. Striking plates with high-caliber rounds spins the apparatus with satisfying metallic clangs, sharpening marksmanship during quiet base defense rotations.",
    },
    ["targeting_module"] = {
        zh = "集成了高精度光学测距传感器、风速补偿算法与陀螺仪的高级火控瞄准计算模块。不仅能作为生化插件植入大脑以获得神级锁头辅助，也是改装军用自动防御哨戒机枪的智能核心。",
        en = "An advanced fire-control coprocessor combining digital rangefinders, ballistic windage calculators, and gyroscopic sensors. Installable as a bionic neural assist or wired into automated turrets, it delivers pinpoint aiming solutions across battlefield chaos.",
    },
    ["tarp"] = {
        zh = "由涂胶高密度聚乙烯织物制成的耐磨防撕裂防水帆布罩。四周边缘打满了金属加固穿绳孔，无论是用来在荒野大树间拉起简易防雨庇护所，还是包裹住皮卡后斗防止战利品淋湿，都格外实用。",
        en = "A heavy-duty waterproof polyethylene sheet reinforced with perimeter brass grommets. Tied between trees, it improvises an emergency storm shelter, or straps tightly across pickup truck beds to keep scavenged loot bone-dry.",
    },
    ["tarp_raincatcher"] = {
        zh = "利用四根木桩拉起防水帆布、中央自然下垂汇聚雨水的简易集水漏斗装置。在末日干净自来水彻底断供的荒郊野岭，一场及时的瓢泼大雨就能通过它为你积攒起足以饮用数天的珍贵天然淡水。",
        en = "A practical rainwater collection funnel rigged from four sturdy stakes and suspended waterproof tarpaulin. With municipal taps long dry, a single afternoon downpour channeled through this sloping sheet yields gallons of pure survival water.",
    },
    ["tattered_garment"] = {
        zh = "经过风吹雨淋、丧尸撕扯与岁月侵蚀后彻底破败的褴褛布条衣物残骸。早已无法蔽体御寒，但把它剪裁撕碎后依然能回收出几团干净棉线或当成擦拭枪械油污与点燃篝火的引火碎布。",
        en = "A wretched collection of rotted fabric shreds shredded by weather, scavengers, and zombie claws. No longer offering warmth or modesty, cutting these rags up yields salvageable cotton thread or dry kindling for campfires.",
    },
    ["taurus_judge"] = {
        zh = "拥有加长转轮弹巢的重型不锈钢双动左轮手枪，能随意混装.45柯尔特手枪弹与.410轻型霰弹。在近距离面对飞扑过来的丧尸群时扣下扳机，喷涌而出的霰弹弹丸能瞬间给任何不法之徒宣判死刑。",
        en = "A heavy stainless steel revolver featuring an elongated cylinder accepting both .45 Colt and .410 shotgun shells. Unleashing deafening buckshot sprays at point-blank range, it hands down brutal capital verdicts to overeager undead muggers.",
    },
    ["tavor_12"] = {
        zh = "造型极具科幻色彩的无托结构半自动战术霰弹枪，底部配备了三个可旋转切换的独立管状弹仓。十六发大容量霰弹配合紧凑短小的枪身，让幸存者在清理狭窄走廊与地下实验室时犹如移动军火库。",
        en = "A futuristic bullpup semi-automatic shotgun fed by three rotating magazine tubes beneath its barrel. Packing sixteen devastating shells within a compact chassis, sweeping claustrophobic lab corridors transforms paranoid survivors into walking demolition squads.",
    },
    ["tazer"] = {
        zh = "能通过前部接触电极释放出数万伏特脉冲高压电击的便携式防身电击枪。能瞬间击溃生物神经肌肉使其剧烈痉挛倒地，虽然对没有痛觉神经的丧尸效果减半，但在制服暴躁的人类同伴时极其管用。",
        en = "A handheld stun gun discharging tens of thousands of volts through twin barbed contact probes. Overwhelming nervous systems into involuntary spasms, it subdues unruly human drifters instantly, even if pain-immune zombies merely twitch in confusion.",
    },
    ["tdi_10mm_mag"] = {
        zh = "采用金属骨架包裹耐磨聚合物外壳的三十发超长容量10mmAuto大威力弹匣。插在手枪握把下方显得突兀得像根拐杖，但在遭遇凶狠变异野兽围攻时，这三十发狂暴弹药就是生存的最大依仗。",
        en = "An extended metal-reinforced polymer stick magazine holding thirty rounds of high-pressure 10mm Auto ammunition. Protruding clumsily from pistol grips like an awkward baton, its lavish firepower proves utterly indispensable against swarming mutant fauna.",
    },
    ["tdi_mag"] = {
        zh = "专为冲锋枪与全自动格洛克改型配套设计的三十发9毫米高可靠性长弹匣。顺滑的防倾斜托弹板保证了狂暴射速下的连续供弹，在遭遇尸潮突脸时扣紧扳机，密集的金属弹雨能在两秒内扫清前方视野。",
        en = "A reliable thirty-round third-party extended magazine tailored for Glock pistols and compatible submachine guns. Featuring an anti-tilt follower, holding the trigger during terrifying ambushes floods chokepoints with uninterrupted streams of 9mm lead.",
    },
    ["tea"] = {
        zh = "经过完全发酵烘干精制而成的醇厚全发酵红茶叶。用滚烫的开水冲泡后汤色红艳透亮，散发着优雅的麦芽与果木香气，在末日阴冷的雨天细细品上一小杯，能让疲惫的灵魂重新燃起对文明的渴望。",
        en = "Fully fermented black tea leaves cured to deliver a deep amber infusion with malty undertones. Sipping a steaming mug amidst ruined wasteland tenements rekindles gentlemanly composure while gently purging lingering exhaustion from your bones.",
    },
    ["tea_bag"] = {
        zh = "将一撮风干碎叶封进滤纸袋，丢进刚煮沸的混浊泥塘水里，就能让末日幸存者产生一种置身维多利亚式下午茶的荒谬错觉。只要假装看不见杯底沉淀的铁锈色淤泥，优雅就依然永不过时。",
        en = "Dunking bleached paper pulp and desiccated fannings into boiled ditch water gives survivors an absurd illusion of British aristocratic dignity. So long as you ignore the rust sediment swirling at the mug bottom, civilizational etiquette remains miraculously preserved.",
    },
    ["tea_bag_chamomile"] = {
        zh = "封装着干燥洋甘菊花蕾的小巧滤纸茶包。投入开水中片刻便会飘散出苹果般温和的草本甜香，睡前喝上一杯不仅能有效安抚狂躁紧绷的末日神经，还能带来长达数小时无噩梦打扰的宁静安眠。",
        en = "A porous paper sachet packed with crushed dried chamomile blossoms. Steeping it in boiling water releases gentle apple-like floral fragrances, soothing combat-frayed nerves and coaxing fitful minds into deep, nightmare-free sleep.",
    },
    ["tea_bag_dandelion"] = {
        zh = "装满了经过烘焙粉碎的野生蒲公英根茎的简易草药茶包。泡出的茶汤带有类似淡咖啡的焦苦回甘，不仅能促进身体排毒利尿，在缺乏正规药品的野外更是调理消化不良与肝脏疲劳的天然保健饮品。",
        en = "A convenient tea bag filled with roasted and ground dandelion roots. Yielding an earthy, coffee-like brew, its natural herbal bitterness stimulates digestion and gently flushes toxins accumulated from questionable post-apocalyptic rations.",
    },
    ["tea_bark"] = {
        zh = "用野外刮取的普通树皮粗暴加水煮沸熬成的暗色苦汤。虽然口感涩得让人舌头发麻且喝完甚至会感觉更加口干舌燥，但在饥寒交迫、发烧感冒的绝境中，这碗苦涩热汤往往是吊住小命的唯一寄托。",
        en = "A murky astringent tonic brewed by boiling raw tree bark strips over open flames. Tasting violently bitter and leaving your throat parched, it nonetheless provides crucial medicinal warmth when fevers strike far from civilized clinics.",
    },
    ["tea_fruit"] = {
        zh = "混合了烘干野生浆果碎与芬芳草药冲泡出的酸甜无咖啡因茶饮。宝石红色的澄澈茶汤在口中回荡着丰富的维生素酸甜风味，无论是热饮驱寒还是冰镇解暑，都能大幅驱散末日生存的沉闷压抑。",
        en = "A naturally caffeine-free herbal infusion blending dehydrated wild berries and fragrant blossoms. Sparkling with ruby brilliance and tart fruity sweetness, gulping down a cup revitalizes demoralized wanderers with an intense splash of vitamins.",
    },
    ["tea_fruit_bag"] = {
        zh = "内部混合了脱水苹果粒、玫瑰茄与野生蓝莓干的小巧泡茶袋。只要扔进煮沸的干净水壶里，几分钟内就能将寡淡无味的白开水转化为香气扑鼻的酸甜果味琼浆，是废土拾荒者的奢华小甜点。",
        en = "A tidy mesh pouch packed with dried diced fruits, hibiscus petals, and wild berry bits. Dropping it into boiled spring water transforms dull canteen liquids into an aromatic sweet nectar that lifts gloomy spirits instantly.",
    },
    ["tea_green"] = {
        zh = "经过高温杀青烘干后保留了天然青翠色泽的优质绿茶。沸水冲泡后茶香清幽高雅，微苦中带着持久的回甘，其中蕴含的茶多酚与适度咖啡因既能提神醒脑，又能帮助身体抵抗末日微量的辐射侵蚀。",
        en = "Fresh unfermented green tea leaves steeped to produce a pale emerald brew packed with antioxidants. Delivering crisp botanical bitterness and gentle caffeine focus, it sharpens combat reflexes while helping bodies shrug off ambient wasteland radiation.",
    },
    ["tea_green_bag"] = {
        zh = "装有细碎精选绿茶叶末的单次冲泡环保纸茶包。外出搜刮物资时只需随身揣上两包，随时随地就着篝火热水泡上一杯清香好茶，既方便快捷又不会让茶叶渣粘在牙缝里影响拔枪嚼口香糖。",
        en = "A single-serving bleached filter bag enclosing finely ground green tea leaves. Allowing instant roadside brewing over glowing embers without loose foliage floating around your mug, it delivers pure herbal serenity on exhausting scouting patrols.",
    },
    ["tea_green_raw"] = {
        zh = "采摘自野生茶树枝头、经简单晒干脱水但未揉捻的原始绿茶叶片。虽然直接放进嘴里咀嚼苦涩刺舌且毫无饱腹感，但只要在铁锅中慢慢烘焙炒青，就能制成提神醒脑的优质日常饮茶原叶。",
        en = "Sun-dried whole green tea foliage harvested from untended roadside bushes. Chewing these brittle leaves raw offers foul, unfilling bitterness, but roasting them gently over cast-iron skillets unlocks delightful antioxidant-rich tea ceremonies.",
    },
    ["tea_raw"] = {
        zh = "经过揉捻但尚未彻底干燥发酵完毕的半成品红茶树叶。散发着微酸的发酵青草味，直接干嚼不仅难以下咽还会吸走口腔中宝贵的水分，只有放在阴凉通风处耐心发酵才能烘焙出扑鼻茶香。",
        en = "Crushed tea foliage undergoing oxidative fermentation into traditional black tea. Unpleasant to chew dry and devoid of nutritional value, proper curing and slow baking transforms these humble leaves into liquid aristocratic gold.",
    },
    ["tea_sweetened"] = {
        zh = "用开水冲泡干茶树叶并拌入大勺白糖的香甜热红茶。热气腾腾的红润茶汤散发着悠扬的茶香与焦糖甘甜，啜饮一口能瞬间扫清全天的疲乏，在阴雨连绵的废土上温暖心扉。",
        en = "Steaming black tea steeped from dried leaves and heavily sweetened with scavenged sugar. The soothing botanical fragrance and sweet warmth dissolve mental fatigue, warming fingers wrapped around tin camp mugs.",
    },
    ["tea_wild_sarsaparilla"] = {
        zh = "用在林间挖取洗净的野生洋菝葜芳香根茎慢慢熬煮出的传统土草药茶。带有浓郁类似根啤汽水的甜香风味，大口喝下能迅速驱散长途跋涉带来的四肢酸痛与肌肉疲劳，提神醒脑效果拔群。",
        en = "A fragrant herbal decoction boiled from wild sarsaparilla rootstocks scavenged across deciduous woodlands. Carrying sweet root-beer notes, drinking this invigorating tonic washes away muscular aches and boosts physical vitality across grueling cross-country treks.",
    },
    ["tea_willowbark"] = {
        zh = "剥取新鲜柳树内皮在开水中慢火煎熬出的金黄色苦涩药茶。虽然入口微苦涩口，但其富含的天然水杨苷在体内能发挥天然阿司匹林的奇效，是废土游侠治疗头痛发热与关节剧痛的救命良方。",
        en = "A pale amber medicinal broth simmered from freshly peeled inner willow bark. Despite a sharply bitter taste, its natural salicin compounds mimic aspirin, soothing splitting headaches and raging joint inflammation when commercial painkillers run dry.",
    },
    ["teapot"] = {
        zh = "带有倒流防滴漏长壶嘴与隔热把手的精美小巧金属冲茶壶。在充满废弃垃圾的末日营地里，架上炉子静静等待壶嘴喷出欢快的蒸汽白雾，能带来一种仿佛仍在和平时代享受下午茶的荒诞仪式感。",
        en = "A compact metal teapot featuring a curved pouring spout and an insulated loop handle. Watching steam whistle cheerfully above glowing camp stoves provides a wonderfully absurd illusion of civilized afternoon leisure amidst bleak post-apocalyptic ruins.",
    },
    ["tear_gas_payload"] = {
        zh = "封装在金属筒内的高浓度CS催泪瓦斯化学装药模块。本应是军用防暴发生器内部的核心组份，但在某些神秘的底层调试空间里，它只是个安静躺在那里的占位符代码，只要不激活就人畜无害。",
        en = "An internal chemical canister packed with compressed CS irritant compounds. Originally engineered as payload munitions for riot dispensers, encountering this raw logic placeholder outside developer debug prompts suggests reality itself is glitching slightly.",
    },
    ["tear_gas_payload_act"] = {
        zh = "内部化学导火索已被触发、正在急剧升温读秒的活跃催泪瓦斯装药。刺鼻的微量白烟已经开始从接缝处逸出，随时会爆开漫天剧毒白雾，不管你是玩家还是丧尸，现在唯一的明智之举就是拔腿狂奔。",
        en = "An activated chemical irritant canister hissing furiously as its internal reaction counts down to zero. Leaking acrid aerosol from its seams, surviving this impending volcanic fog of blinding tears requires running immediately in the opposite direction.",
    },
    ["tearer"] = {
        zh = "密布交错高硬度旋转合金重型刀片的工业级机械粉碎机组件。只要将其机械轴系连接到战车的柴油引擎上，任何卷入其中的废旧家具、僵尸躯体甚至金属保险箱都会在两秒内被绞成均匀肉泥碎屑。",
        en = "An industrial-grade shredder drum bristling with interlocking hardened steel teeth. Hooked up to a vehicle transmission, its ferocious rotary blades chew through sheet metal, furniture, and charging zombie hordes, spitting out pulverized organic mulch.",
    },
    ["teargas_spray"] = {
        zh = "雾化加压罐装的高浓度邻氯苯甲丙二腈刺激性有毒气体。只需迎面喷射一小股，就能瞬间导致吸入者眼睛刺痛失明、鼻涕眼泪狂流并剧烈咳嗽窒息，无论是凶恶暴徒还是变异棕熊都会被当场逼退。",
        en = "An aerosolized chemical irritant formulated to overwhelm mucosal membranes. Blasting a cloud into attacker faces unleashes uncontrollable coughing, stinging blindness, and weeping mucus, sending aggressive raiders and mutant bears fleeing in blind agony.",
    },
    ["teargas_sprayer"] = {
        zh = "带有防误触安全翻盖与指压扳机的随身口袋型催泪瓦斯喷雾罐。比普通的民用防狼辣椒喷雾更为暴烈致命，在狭小电梯或走廊里使用时务必屏住呼吸，否则伤敌一千的同时自己也会被熏得跪地干呕。",
        en = "A pocket-sized pressurized canister with a flip-top safety cap containing military-grade tear gas. Superior to standard pepper spray, discharge it cautiously in confined spaces, lest you blind yourself along with your snarling assailants.",
    },
    ["technician_coveralls"] = {
        zh = "采用加厚耐磨防水斜纹布裁制的全覆盖一体式工程技术员连身工装服。全身遍布大大小小的工具插袋与卷尺挂扣，不仅防污防油耐刮擦，穿上后更自带一种“我马上就能修好这台发电机”的专业气场。",
        en = "Heavy-duty canvas utility coveralls designed to protect technicians from workshop grime and hazardous sparks. Boasting countless deep pockets and hammer loops, donning them immediately projects an aura of competent mechanical authority across wasteland bases.",
    },
    ["technician_coveralls_h"] = {
        zh = "内层复合保暖羊毛衬里、外层涂覆阻燃防水涂层的加厚重型技术员防寒连体服。能抵御机械维修时的尖锐铁屑与飞溅焊渣，同时在零下冬日里也能锁住体温，是废土机械师户外抢修车辆的神装。",
        en = "Insulated heavy-duty work coveralls lined with quilted thermal fleece and flame-resistant outer canvas. Defending against jagged scrap metal and freezing wind chills, it keeps frontier mechanics warm while repairing snow-buried vehicle engines.",
    },
    ["technician_pants_gray"] = {
        zh = "采用防油污重型斜纹布缝制的灰色技术工装长裤。膝盖处带有双层补强加厚布，双腿两侧分布着插放螺丝刀与扳手的细长口袋，耐磨耐脏且在废墟里极不易被划破。",
        en = "Heavy gray twill work trousers designed for industrial maintenance technicians. Double-reinforced knees and narrow tool slots resist sharp rebar snags while crawling beneath disabled generator trucks in oily garages.",
    },
    ["technician_shirt_gray"] = {
        zh = "印有废弃电子厂标志的耐磨灰色工作短袖T恤。面料吸汗透气且不易沾染机油污渍，虽然外观平平无奇像个普通的蓝领工人，但在闷热的避难所工坊里干活极其舒爽。",
        en = "A gray polyester-cotton utility shirt sporting faded electronics company emblems. Breathable and resistant to oil smudges, it provides practical, comfortable attire for long days turning wrenches over forge anvils.",
    },
    ["technologybrochure"] = {
        zh = "全彩印刷并标注着旧世界本地街机厅、电器城与网吧地址的促销广告折页。在断网断电的末日，阅读它能让你在地图上精确定位出数个潜在的高价值搜刮点。",
        en = "A glossy promotional flyer advertising local arcade halls, computer cafes, and hardware superstores across town. In an unpowered world, cross-referencing its cheerful business addresses reveals prime urban locations ripe for harvesting rare electronics and tools.",
    },
    ["teddy_bear"] = {
