    ["wetsuit_booties_thick"] = {
        zh = "加厚型高保温潜水靴。厚实的氯丁橡胶配合加固橡胶外底，不仅能在零度以下的冰封湖泊潜泳时抵御刺骨严寒，坚硬的橡胶底即使踩在水底隐藏的尖锐贝壳上也安然无恙。",
        en = "Heavy-duty neoprene dive boots fitted with vulcanized rubber treads. Providing extreme thermal insulation for freezing submerged dives, the thick soles resist razor-sharp freshwater clams and underwater scrap metal.",
    },
    ["wetsuit_gloves"] = {
        zh = "采用带防滑纹路的厚实发泡橡胶缝制的潜水保暖手套。既能保证十指在冰冷水下操作机械开关时的灵活性，也能保护手掌免遭水下碎玻璃和变异水蛭等吸血水生寄生虫的直接蜇刺。",
        en = "Insulated neoprene diving gloves featuring textured palm grips. Preserving finger dexterity in freezing depths, they protect scavenger hands from sharp barnacles, rusted metal edges, and aquatic parasitic leeches.",
    },
    ["wetsuit_gloves_thick"] = {
        zh = "采用加厚微孔发泡橡胶缝制的三指保暖潜水手套。在冰水潜行搜刮时能牢牢锁住双手温度防止手指僵硬，虽然稍微牺牲了细微手感，但在极寒环境下能保住握枪的知觉。",
        en = "Thick neoprene diving gloves engineered to preserve hand dexterity inside sub-zero waters. Sacrificing fine fingertip sensitivity for thermal security, they keep trigger fingers functional during amphibious winter raids.",
    },
    ["wetsuit_hood"] = {
        zh = "紧密贴合头颈部曲线的氯丁橡胶潜水头套。仅露出双眼与口鼻区域，有效锁住头部散发的大量热量，是在冰冷刺骨的黑水河流或被淹没的下水道深潜探险时抵御冻伤的核心防护配件。",
        en = "A snug-fitting neoprene diving hood covering the head and neck. Minimizing heat loss from the skull, it prevents debilitating cold-water headaches while exploring murky, submerged pre-collapse sewer networks.",
    },
    ["wetsuit_hood_thick"] = {
        zh = "全包覆式厚潜水氯丁橡胶头套。仅留出面部镜框区域，紧紧包裹住头颅、颈部与下颚，在刺骨寒风呼啸的深水水库里潜水打捞物资时，能彻底隔绝让人头痛欲裂的冰冷刺激。",
        en = "A heavy neoprene diving hood enclosing skull, ears, and chin with snug watertight seals. Eliminating ice-cream headache chills during deep salvage dives, it protects head vitals in murky reservoir depths.",
    },
    ["wetsuit_jacket"] = {
        zh = "带有结实耐腐塑料前拉链的厚款长袖潜水夹克。采用高弹性合成发泡材料压制，不仅具有出色的抗风保暖与浮力辅助性能，其平滑外皮在泥泞湿地匍匐时也不会轻易挂蹭灌木枝条。",
        en = "A heavy long-sleeved wetsuit jacket featuring a corrosion-resistant front zipper. Offering thermal insulation and buoyant padding, its slick rubber exterior effortlessly slips through tangled swamp reeds.",
    },
    ["wetsuit_pants"] = {
        zh = "护膝部位经过额外耐磨补强处理的全长厚款潜水长裤。弹性紧致且贴合腿部肌肉，在涉水渡过湍急冰河或是潜水搜寻沉船物资时，能为你提供极佳的下肢抗寒保暖与防刮蹭保护。",
        en = "Full-length neoprene diving pants reinforced with abrasion-resistant kneepads. Providing reliable thermal protection and snag resistance, they allow long wades through chilly marshes without losing feeling in your legs.",
    },
    ["wetsuit_pants_thin"] = {
        zh = "采用轻薄薄型氯丁橡胶剪裁而成的贴身长款潜水裤。厚度较薄使得下肢活动近乎毫无束缚，适合在初秋温暖水域涉水泅渡，既能防水草刮擦水蛭吸附，又不会在剧烈游泳时积聚过多闷热。",
        en = "Lightweight thin neoprene dive pants designed for moderate water temperatures. Permitting unhindered swimming mobility, they shield bare legs against stinging jellyfish tentacles and sharp underwater river stones.",
    },
    ["wetsuit_shorts"] = {
        zh = "包裹大腿和臀部的中等厚度潜水防寒短裤。质地坚韧耐磨且弹性十足，常与长袖潜水衣或快干防晒衫搭配穿着，在保证核心下腹温暖的同时让双腿保持完全自由的大幅度踢水与攀爬能力。",
        en = "Mid-weight neoprene diving shorts covering the waist and thighs. Warming core abdominal muscle groups while granting total freedom of movement, they excel for warm-weather coastal foraging and kayak paddling.",
    },
    ["wetsuit_shorts_technical"] = {
        zh = "大腿两侧缝制了带尼龙搭扣大容量加固口袋的专业技术潜水短裤。不仅具备出色的防寒浮力，两侧口袋还能让你在潜水时轻松装入备用潜水手电、割网刀、配重铅块或是搜刮来的防水战利品。",
        en = "Technical diving shorts equipped with expanding cargo pockets on each thigh. Perfect for aquatic scavengers, they secure dive knives, slate boards, and waterproofed loot while maintaining core warmth.",
    },
    ["wetsuit_shorts_technical_loose"] = {
        zh = "采用松散宽大剪裁并配有快开大口袋的潜水技术工装短裤。既能提供氯丁橡胶的保温防风效果，外侧加固的风雨口袋又能塞入潜水手电与撬棍，是两栖拾荒队员的心头好。",
        en = "Loose-fitting technical dive shorts equipped with drainage grommets and expansive thigh pockets. Merging neoprene insulation with cargo utility, they stow underwater lights and prybars during amphibious coastal salvaging.",
    },
    ["wetsuit_spring"] = {
        zh = "短袖短裤式的一体化春季轻量潜水连体服。设计用于水温微凉的温水环境，穿脱极其迅速且在陆地上奔跑时完全不会束缚关节活动，是探索水陆交错湿地沼泽时的轻便选择。",
        en = "A classic shorty springsuit featuring short sleeves and truncated legs. Ideal for mild aquatic foraging, it preserves core body heat while letting survivors jog, climb, and sprint across shorelines unencumbered.",
    },
    ["wetsuit_spring_sleeveless"] = {
        zh = "无袖短裤剪裁的超轻便氯丁橡胶春季潜水服。上身如背心般彻底解放双肩与腋下活动范围，划皮划艇、挥舞鱼叉或是长距离游泳冲刺时手臂毫无阻力，适合在阳光明媚的水域轻装潜渡。",
        en = "A sleeveless shorty wetsuit granting unrestricted shoulder and arm articulation. Highly favored by kayakers and spear-fishers, it prevents chafing during aggressive paddling while keeping vital chest organs warm.",
    },
    ["wetsuit_thick"] = {
        zh = "采用加厚七毫米超弹发泡氯丁橡胶热压而成的重型极寒潜水服。厚重如盔甲般的发泡层能牢牢锁住体温，让你即使下潜到极寒冰封湖底或水下冷库深处，也不会轻易被刺骨严寒夺走意识。",
        en = "A heavy-duty seven-millimeter cold-water wetsuit. Dense neoprene insulation combats freezing sub-surface currents, allowing daring divers to salvage pristine sunken stockpiles from flooded sub-basements.",
    },
    ["wetsuit_top"] = {
        zh = "无袖背心式的轻便贴身潜水保暖上衣。设计紧贴胸背核心部位以减少热量流失，既可作为内胆套在厚外套里面充当防风保暖夹层，也可以在涉水摸鱼时单穿，行动极为灵便轻巧。",
        en = "A sleeveless neoprene dive vest covering the torso. Trapping core warmth without restricting arm swings, it doubles effectively as an insulating thermal underlayer beneath heavy wasteland combat coats.",
    },
    ["wetsuit_top_sleeved"] = {
        zh = "标准厚度的长袖套头式潜水保暖上衣。严密包裹上肢与躯干并配有防滑袖口，不仅能阻挡冰冷水流直接冲刷胸膛，在水下搜寻金属破片时也能保护双臂免受锋利锈蚀铁皮割伤。",
        en = "A standard long-sleeve neoprene diving pullover. Providing consistent insulation from wrist to collar, it shields arms from scrapes against jagged underwater wreckage while hunting for sunken salvage.",
