    ["xs_boots_fur"] = {
        zh = "用变异兔皮与厚实生皮缝制的小号皮毛冬靴。保暖性极其变态，紧紧包裹住容易失温的纤细脚踝，是在冰封冻土废墟上长途跋涉时的保命神器。",
        en = "Stitched from mutant rabbit pelts and thick hide, these miniature fur boots retain heat fiercely. They protect fragile ankles from crippling frostbite across frozen tundra ruins.",
    },
    ["xs_boots_hsurvivor"] = {
        zh = "在脚趾和脚后跟嵌入加厚钢板的小号重型生存战靴。虽然对身材矮小的幸存者而言略显沉重，但一脚飞踢出去，足以把爬行丧尸的脑袋当场踹扁。",
        en = "Reinforced with steel caps at toe and heel, these small heavy survivor boots pack devastating momentum. A snapping kick crushes crawling zombie skulls like brittle clay pots.",
    },
    ["xs_boots_larmor"] = {
        zh = "硬化牛皮层层包裹成型的小号硬皮战靴。鞋底带有手工打磨的防滑沟槽，兼顾了优良的脚踝支撑与防刺穿性能，非常适合在复杂废墟中上下攀爬。",
        en = "Molded from hardened steer hide with hand-carved tread grooves, these petite boots offer supreme ankle stability and puncture resistance, perfect for scrambling across crumbling multi-story ruins.",
    },
    ["xs_boots_plate"] = {
        zh = "外覆铰接小铁片的小号板甲战靴。虽然娇小的腿部需要花费更多力气迈步，但任何来自地面的犬齿撕咬或老鼠啃噬，都会在这层铁靴面前撞得头破血流。",
        en = "Covered in articulated miniature steel plates, these plate boots protect petite legs against low-angle bites. Stray mutant hounds snapping at your feet leave only dull tooth marks.",
    },
    ["xs_boots_scrap"] = {
        zh = "用废弃铁罐头皮、粗电线和旧球鞋底捆绑出来的小号铁皮靴。虽然走起路来咔啦乱响，但坚硬的废铁底面确实成功阻挡了无数次地钉穿刺的噩梦。",
        en = "Cobbled from crushed cans, thick wire, and sneaker outsoles, these small scrap boots clatter loudly. Nonetheless, the improvised metal armor stops rusty floor spikes from impaling feet.",
    },
    ["xs_boots_winter"] = {
        zh = "小号标准冬用保暖防滑棉靴。厚实的保温海绵紧紧包裹着娇小双足，深齿大底在积雪覆盖的结冰路面上提供稳固的摩擦力，防止你在逃命时滑倒摔断鼻梁。",
        en = "Insulated with dense foam and deep rubber lugs, these small winter boots conquer icy terrain. They keep small feet warm while preventing humiliating, face-first slips during desperate chases.",
    },
    ["xs_boots_wsurvivor"] = {
        zh = "多层防水透气膜与天然皮毛复合缝制的小号冬用生存靴。专为极寒废土环境设计，兼具了涉雪不湿和零下三十度防冻伤的卓越特性，伴你踏破风雪。",
        en = "Combining waterproof breathable membranes with dense fur lining, these petite winter survivor boots conquer Arctic wastes. Slender feet remain completely dry through slush and freezing snowbanks.",
    },
    ["xs_boots_wsurvivor_nofur"] = {
        zh = "无动物皮毛的小号合成防寒生存靴。利用现代中空隔热纤维填充，轻便且吸湿快干，让矮小的长途跋涉者在连续行军数天后依然脚部干爽舒适。",
        en = "Packed with synthetic thermal microfibers instead of pelt, these furless winter boots dry rapidly. Petite hikers trudging across subzero ruins enjoy lightweight warmth without damp, clammy socks.",
    },
    ["xs_bra"] = {
        zh = "小尺码的轻薄纯棉内衣。剪裁合体贴身，在高温湿热的废墟中能够迅速吸干汗水，为娇小幸存者在穿戴沉重防弹背心前提供一层柔和的皮肤屏障。",
        en = "Soft and breathable, this petite cotton bra absorbs sweat rapidly in muggy wasteland ruins. It forms an essential anti-chafing barrier beneath stiff ballistic carriers and survival gear.",
    },
    ["xs_cestus"] = {
        zh = "缠裹在娇小双拳上的硬皮铁铆拳套。虽然拳头看似小巧玲珑，但在坚硬金属铆钉的强化下，挥出的寸劲直拳能轻而易举地打碎强盗的鼻梁骨与门牙。",
        en = "Laced with hardened leather and steel studs, these petite cestus wraps turn small fists lethal. A snapping short hook shatters enemy teeth and caves in nasal cartilage.",
    },
    ["xs_ch_chainmail_arms"] = {
        zh = "用表面硬化钢环密密编织而成的小号锁甲袖。紧密贴合细瘦手臂，在不影响手腕极速翻转的同时，彻底阻绝了敏捷丧尸的利爪抓伤和刺刀劈砍。",
        en = "Woven from case-hardened steel links, these small chainmail sleeves hug slender arms. They deflect razor claws and bayonet slashes without restricting wrist agility during close blade work.",
    },
    ["xs_ch_chainmail_aventail"] = {
        zh = "悬挂在小号头盔边缘的硬化钢环护颈。像一片精巧的银色幕布垂护在纤弱的脖颈周围，彻底打消了敌对刺客在背后使用绞索或抹脖子暗杀的企图。",
        en = "Draping like a silvery curtain around slender necks, this case-hardened aventail foils assassination. Enemy garrotes and backstab daggers skate harmlessly off the flexible interlocking steel rings.",
    },
    ["xs_ch_chainmail_face"] = {
        zh = "小巧玲珑的表面硬化钢环锁甲面帘。罩在下半张脸上像一层精致的面纱，既能保护稚嫩的下颌免遭撕咬，又能把呼吸喷出的热气自然散入冷风中。",
        en = "This diminutive case-hardened mail veil shields small jaws from feral bites. Resembling an intricate metallic veil, it turns away teeth while venting warm breath into the frosty air.",
    },
    ["xs_ch_chainmail_feet"] = {
        zh = "用硬化细钢环织造的小号锁甲足套。套在小靴子外面能有效防范爬行丧尸的下段偷袭，即便不小心踩到变异刺猬背上，钢环也能保你安然无恙。",
        en = "Fitted over petite footwear, these case-hardened chainmail shoe covers repel ground crawlers. Stepping directly onto mutated hedgehogs or caltrops will not pierce the resilient steel mesh.",
    },
    ["xs_ch_chainmail_half_legs"] = {
        zh = "覆盖大腿前侧的小号硬化半截锁甲。为娇小身材的突变战士提供了关键部位的防劈砍屏障，同时极力降低整体自重，确保随时可以全力加速逃命。",
        en = "Protecting upper thighs with case-hardened links, these miniature half-chausses deflect downward cuts. Minimizing dead weight ensures small scavengers retain full sprinting speed to escape lethal ambushes.",
    },
    ["xs_ch_chainmail_hands"] = {
        zh = "硬化钢环手工编织的小号锁甲手套。虽然抓握微型螺丝刀稍显费劲，但在近身撕扯肉搏时，你可以毫不犹豫地徒手格挡迎面刺来的锋利碎玻璃或刀尖。",
        en = "Crafted from case-hardened rings, these petite mail mittens handle broken glass and bare blades fearlessly. While micro-tinkering is tricky, hand-to-hand parries feel completely safe and decisive.",
    },
    ["xs_ch_chainmail_hood"] = {
        zh = "罩在小巧脑袋上的表面硬化锁甲头巾。紧致贴身，不仅能滑开自上而下劈落的砍刀，还能在矮小幸存者钻入狭窄岩洞时防止头皮被钟乳石划伤。",
        en = "Conforming snugly to petite heads, this case-hardened coif deflects overhead cleaves. Crawling through low cave ceilings protects tender scalps from sharp stalactite grazes and rocky projections.",
    },
    ["xs_ch_chainmail_legs"] = {
        zh = "全套小号硬化锁甲长裤。细密的钢环随着轻快的步伐泛起微弱金属光泽，全面防御低矮草丛中潜藏的变异毒蛇与嗜血水蛭，穿行荒野如履平地。",
        en = "Encasing slender legs in case-hardened steel links, these small chausses offer comprehensive lower protection. Lurking vipers and giant marsh leeches cannot pierce through the interlocking mesh.",
    },
    ["xs_ch_chainmail_vest"] = {
        zh = "小体型专用的表面硬化锁甲背心。重量分配极其考究，紧紧守护着胸腔与脊椎要害，是矮小体型战士在混战中防止被长矛穿心最靠得住的铁布衫。",
        en = "Engineered for petite physiques, this case-hardened mail vest protects vital chest organs. It functions as an indispensable core barrier, preventing thrusting spears from piercing lungs in chaotic scuffles.",
    },
    ["xs_ch_greaves_brigandine"] = {
        zh = "在皮革内衬上精密排列硬化钢条的小号板条胫甲。完美护住纤细的小腿胫骨，哪怕被狂奔的野猪直接撞在小腿上，坚硬的钢板也能将冲击力迅速分散消解。",
        en = "Lining soft leather with case-hardened steel splints, these petite greaves shield fragile shins. Absorbing sudden collisions from charging mutant boars, they disperse force safely without fracturing bone.",
    },
    ["xs_ch_helmet_nasal"] = {
        zh = "带有硬化鼻甲横梁的小号诺曼铁盔。尺寸专为娇小头颅冲压，坚硬挺直的鼻梁护条能有效阻挡正面飞来的碎石飞屑，守护那张小脸蛋的容貌完整。",
        en = "Featuring a rigid case-hardened nasal bar, this small Norman helm shields petite faces. It stops flying gravel and front-on fist strikes from crushing delicate nasal bridges.",
    },
    ["xs_ch_helmet_turban"] = {
        zh = "尖顶流线造型的小号硬化缠头盔。精巧的穹顶不仅外观华美，还能顺滑地将来袭的钝器重击向侧面卸开，小体型穿戴者戴上它宛如童话里的铁甲小精灵。",
        en = "Topped with an elegant pointed dome, this miniature case-hardened helmet deflects blunt strikes gracefully. Petite warriors wearing it resemble mythic iron-clad fairy knights exploring post-apocalyptic ruins.",
    },
    ["xs_ch_mirror_armor"] = {
        zh = "四面小巧而平滑的表面硬化钢盘用皮带固定在胸背。虽然甲片尺寸不大，但经过淬硬的镜面不仅刀枪不入，还能在废土刺眼的烈日下折射出致盲敌人的反光。",
        en = "Four compact case-hardened discs strap across petite torsos. Besides turning away thrusts, the polished surfaces reflect dazzling sunbeams directly into bandits' eyes during midday skirmishes.",
    },
    ["xs_ch_steel_facemask"] = {
        zh = "小巧精致的硬化钢制面具。孔洞细致且边缘圆润，严密遮盖住娇小幸存者的容貌，在隔绝毒刺和碎瓦的同时，赋予了穿戴者一种令人捉摸不透的神秘威严。",
        en = "Perforated with neat ventilation slits, this diminutive case-hardened steel mask conceals facial expressions completely. It keeps venomous thorns away while projecting cold, mysterious authority across encounters.",
    },
    ["xs_ch_vambrace_brigandine"] = {
        zh = "在坚韧皮革上以细钢铆钉固定硬化钢条的小号护臂。戴在细小前臂上坚如铁箍，格挡敌方挥来的铁管或柴刀时，清脆的撞击声宣告了敌方攻击的彻底破产。",
        en = "Securing case-hardened splints onto tough hide, these small vambraces turn slender arms rigid. Parrying pipe strikes produces sharp clangs that instantly halt aggressive raider assault attempts.",
    },
    ["xs_chestrig"] = {
        zh = "针对小身材裁剪的紧凑型微胸挂。没有臃肿冗余的织带拖泥带水，胸前紧密排布的弹匣包和杂物袋让娇小射手在战壕中匍匐前进时毫无阻力。",
        en = "Scaled down for petite frames, this compact chest rig eliminates trailing slack. Neatly positioned magazine pouches let small scouts crawl through low trenches without snagging on tree roots.",
    },
    ["xs_coat_faux_fur"] = {
        zh = "蓬松轻柔的小号人造皮毛大衣。穿在娇小幸存者身上像是一团移动的棉花糖，虽然被雨水淋湿后会变得有些沉重，但干燥时提供的暖意让人忍不住想缩在里面冬眠。",
        en = "Fluffy and plush, this small faux fur coat makes petite survivors look like moving marshmallows. It keeps subzero chills at bay, tempting wearers into peaceful, cozy wasteland hibernation.",
    },
    ["xs_coat_fur"] = {
        zh = "用真毛皮精细拼接缝制的小号皮草外套。防风保温效果拔群，轻盈贴身，是那些在极寒风雪中搜刮物资的小个子猎人们最珍贵也最奢华的保暖防线。",
        en = "Stitched from natural pelts, this miniature fur coat delivers unmatched cold insulation. Petite wasteland hunters cherish its lightweight warmth when tracking mutant game across blizzard-swept ridges.",
    },
    ["xs_cuirass_bronze"] = {
        zh = "按照娇小体格浇铸的小号青铜胸甲。在废墟晨曦中泛着暗红色的古老金属微光，不仅将胸腔要害保护得严严实实，甚至还能让人依稀梦回古希腊的神话时代。",
        en = "Cast in ancient bronze for diminutive frames, this small cuirass shines with reddish hues. It provides resolute chest coverage, evoking mythic Spartan heroism amidst smoking post-apocalyptic craters.",
    },
    ["xs_cuirass_lightplate"] = {
        zh = "用超薄轻型均质钢板压制而成的小号轻板甲胸甲。完美兼顾了重量与防护上限，即使是力量较弱的矮小突变者穿上它，也不会感到呼吸困难或步履维艰。",
        en = "Pressed from thin, uniform plate steel, this miniature cuirass optimizes weight distribution. Fragile mutants can run and vault barricades without crushing fatigue restricting their lung capacity.",
    },
    ["xs_cuirass_scrap"] = {
        zh = "用铁皮饼干盒、报废机箱侧板拼接打磨成的小号废料胸甲。虽然接缝处布满粗糙的焊疤，但在迎面挨上一记流弹时，这块破铁片确实能拯救一条娇小无辜的生命。",
        en = "Hammered together from cookie tins and computer case covers, this small scrap cuirass looks crude. Yet its improvised plating reliably catches stray shrapnel, preserving fragile lives.",
    },
    ["xs_cuirass_tire"] = {
        zh = "将废旧汽车轮胎割条编扎而成的小号橡胶胸甲。不仅具备出色的韧性与抗咬合力，跳跃落地时厚实的橡胶层甚至还能起到微弱的减震防摔缓冲作用。",
        en = "Braided from repurposed vehicle tire strips, this miniature rubber cuirass absorbs brutal teeth marks. Landing awkwardly from high ledges, the shock-absorbing rubber softens concussive chest impacts.",
    },
    ["xs_duster"] = {
        zh = "专为身材矮小的漫步者定制的小号牛仔风衣。衣摆正好垂至小腿，在狂风扬起的辐射尘暴中能把娇小的身躯严实遮盖，走在废土黄沙中显得格外英姿飒爽。",
        en = "Tailored for pint-sized wanderers, this small canvas duster falls perfectly to calf height. Wrapping tightly in radioactive dust storms, it gives tiny gunslingers undeniable frontier wasteland swagger.",
    },
    ["xs_duster_faux_fur"] = {
        zh = "内衬人造软毛的小号风衣。既保留了流浪枪手潇洒的大衣外形，又兼备了不输棉袄的御寒能力，让矮小的独行侠在冰冷废墟小镇的酒馆前昂首阔步。",
        en = "Lined with synthetic fleece, this petite duster blends gunslinger silhouettes with winter-jacket warmth. Petite lone wanderers stride into ruined saloons protected against freezing, howling wasteland winds.",
    },
    ["xs_duster_fur"] = {
        zh = "内里缝满真实动物毛皮的小号风衣大氅。毛茸茸的内衬隔绝了外界一切刺骨寒意，即便矮小的你蜷缩在没有火炉的废弃破车里过夜，也能安然入睡到天明。",
        en = "Lined with natural animal pelts, this miniature winter duster locks in body heat completely. Sleeping curled up inside unheated abandoned cars becomes comfortable even through freezing blizzards.",
    },
    ["xs_duster_leather"] = {
        zh = "由硬朗熟皮裁剪而成的小号皮风衣。油润耐磨，不仅能像雨衣一样弹开泥泞酸水，还能有效抵御小动物或灌木丛对娇小身体的抓擦撕扯，帅气与实用兼备。",
        en = "Cut from oiled steer hide, this small leather duster sheds mud and acidic drizzle cleanly. It shields fragile explorers from bramble scratches while looking effortlessly formidable and stylish.",
    },
    ["xs_espadrilles"] = {
        zh = "麻绳编织鞋底配合棉布鞋面的小号草编帆布鞋。轻如羽毛，透气无声，矮小的刺客穿上它踩在木地板上几乎完全不会发出声音，是隐秘潜入时的绝配装备。",
        en = "Braided from jute rope and light canvas, these miniature espadrilles are completely silent. Petite infiltrators stepping across creaky floorboards make zero sound, moving like untraceable ghosts.",
    },
    ["xs_fsurvivor_suit"] = {
        zh = "采用高级阻燃复合材料小尺码剪裁的防火生存外套。能够全面阻绝高温热浪与火焰喷溅，让体格轻巧的生存大师在变异火海中自由穿梭而无需担心衣服被点燃。",
        en = "Engineered with flameproof composite textiles for small frames, this survivor suit repels thermal firestorms. Pint-sized survivalists sprint through burning ruins without risking lethal clothing ignition.",
    },
    ["xs_gambeson_canvas"] = {
        zh = "多层加厚粗帆布缝制而成的小号武装衣。紧凑的衍缝结构能像海绵一样吸收外来钝击冲击力，无论是单穿还是作为金属铠甲的衬垫，都是小个子战士的忠实保镖。",
        en = "Quilted from multiple canvas sheets, this small gambeson dampens concussive blunt trauma like a dense sponge. Worn standalone or under armor, it reliably guards petite frontline fighters.",
    },
    ["xs_gambeson_canvas_thinsleeved"] = {
        zh = "衣袖经过削薄处理的小号帆布武装衣。躯干部分保持原有的多层厚实减震，而轻薄的双袖则让矮小战士在高速挥动短剑或刺击长矛时感受不到任何阻力。",
        en = "Thinning the sleeves on this small canvas gambeson preserves arm speed while maintaining heavy torso padding. Petite duelists thrust daggers and spears with unimpeded, lightning-fast cadence.",
    },
    ["xs_gambeson_canvas_vest"] = {
        zh = "无袖粗帆布小号夹棉背心。短小轻盈，专注保护胸腔、背脊与腹部等致命器官，同时完全解放了双臂与肩关节，专为极速奔跑与近身缠斗的小个子量身定做。",
        en = "This sleeveless canvas gambeson vest focuses protection purely on vital torso organs. Unencumbering shoulders and arms, it caters to pint-sized brawlers who prioritize raw speed and wrestling.",
    },
    ["xs_gambeson_gloves_canvas"] = {
        zh = "帆布多层衍缝小号武装手套。虽然套在细小手指上略显臃肿，但在抓握粗糙的木柄长矛或攀登生锈金属铁梯时，能提供绝佳的手掌防磨泡保护与减震支持。",
        en = "Quilted from dense canvas layers, these small arming gloves appear slightly bulky. However, they stop painful blister friction when gripping wooden spear shafts or climbing rusted fire escapes.",
    },
    ["xs_gambeson_gloves_nylon"] = {
        zh = "外覆高密度耐磨尼龙的小号衍缝手套。不仅抗撕裂耐穿刺，光滑的外表面还能有效抵御污水渗入，是娇小幸存者在泥泞沼泽中翻找金属废料时的得力工具。",
        en = "Faced with abrasion-resistant nylon, these small quilted gloves resist punctures and water. They allow petite scavengers to dig through wet mud and metal scrap without getting soaked.",
    },
    ["xs_gambeson_gloves_wool"] = {
        zh = "采用羊毛填塞的小号武装手套。质地柔韧温热，不仅能消除手握重兵器时震击反弹的麻痹感，还能在刺骨寒风中呵护娇小幸存者的敏捷双手。",
        en = "Padded with insulating wool, these small arming gloves dampen weapon recoil and blunt vibration. They keep fragile fingers warm and nimble through freezing wasteland winds.",
    },
    ["xs_gambeson_hood"] = {
        zh = "标准小号夹棉武装头巾。如同一个柔软的抗震包子罩在娇小的头顶，在佩戴坚硬的金属铁盔时，充当不可或缺的防磨皮与化解钝击的缓冲气囊。",
        en = "This diminutive padded coif cradles small heads like a protective cushion. Worn beneath rigid iron helmets, it prevents abrasive scalp chafing while dispersing concussive impacts.",
    },
    ["xs_gambeson_nylon"] = {
        zh = "采用高抗撕裂尼龙外壳缝制的小号武装衣。光滑的面料具有优良的防污泼水性能，为娇小突变者在低矮潮湿的下水管网中穿行提供了绝佳的减震防刮软甲。",
        en = "Faced with slick ripstop nylon, this small quilted gambeson sheds moisture and grime. Petite wanderers crawl through wet sewer mains protected against rough concrete scrapes.",
    },
    ["xs_gambeson_nylon_thinsleeved"] = {
        zh = "衣袖削薄的小号尼龙武装衣。专注于胸腹核心部位的厚实防震，同时赋予了纤细双臂最大程度的灵巧活动范围，非常适合高机动的微型刺客。",
        en = "Thinning the nylon sleeves retains heavy torso shock absorption while freeing slender arms. Pint-sized assassins strike with maximum wrist speed and lightning-fast blade recoveries.",
    },
    ["xs_gambeson_nylon_vest"] = {
        zh = "无袖小号尼龙武装背心。重量轻若无物，专为小体型战士在炎热天气下提供最干练的心脏与脊椎减震防护，完全不影响双臂攀岩和弓箭速射。",
        en = "This sleeveless nylon gambeson vest weighs practically nothing. It protects vital torso organs through scorching heat without hindering bow handling or frantic emergency climbing.",
    },
    ["xs_gambeson_pants_canvas"] = {
        zh = "粗帆布小号夹棉护腿长裤。密集的排线衍缝能够有效化解变异野兽的抓挠与冲撞，让身材瘦小的幸存者在穿过满是荆棘与废铁的战场时步伐稳健。",
        en = "Stitched from rugged canvas with dense quilting, these small padded chausses absorb beast swipes. Petite survivors traverse bramble thickets and scrap piles with sturdy confidence.",
    },
    ["xs_gambeson_pants_nylon"] = {
        zh = "高强度尼龙面料制作的小号夹棉裤。防风抗水性能一流，紧密包裹着细瘦的双腿，在冰冷的雨夜中持续锁住体温，防止肌肉因失温而发生致命抽筋。",
        en = "Crafted from weather-resistant nylon, these small quilted chausses lock in warmth effortlessly. Slender legs stay dry through icy rainstorms, preventing lethal muscle cramps during retreats.",
    },
    ["xs_gambeson_pants_wool"] = {
        zh = "纯羊毛填充的小号武装裤。保暖性能极其卓越，穿在细小的双腿上既松软又防寒，是矮小突变者在废土严冬里保证双腿奔跑爆发力的终极秘密武器。",
        en = "Insulated with pure wool batting, these petite arming pants feel exceptionally soft. They keep miniature legs warm and primed for explosive sprints across snowbound ruins.",
    },
    ["xs_gambeson_sleeve"] = {
        zh = "独立剪裁的小号武装袖套。通过系绳固定在肩部，让小个子战士在穿着无袖护胸时，依然能获得对手臂尺桡骨与肘关节的坚实防割防震支持。",
        en = "Laced onto shoulder harness straps, these small arming sleeves protect forearms and elbows. They provide vital cushioning against blunt impacts while preserving torso coolness.",
    },
    ["xs_gambeson_wool"] = {
        zh = "采用纯羊毛絮片精心衍缝的小号全套武装衣。柔软厚实且天然调温，不仅为娇小身躯提供了极高的钝击容错率，还带来如同蜷缩在暖炉旁的贴心安全感。",
        en = "Quilted with natural wool, this miniature full-sleeve gambeson dampens heavy blunt blows. Wearing it feels like curling near a hearth while traversing dangerous ruins.",
    },
    ["xs_gambeson_wool_thinsleeved"] = {
        zh = "双袖轻量化剪裁的小号羊毛武装衣。躯干部位保持着羊毛特有的厚实蓄温与吸震能力，双臂则轻便灵巧，让矮小的剑士在格斗中出招疾如闪电。",
        en = "Combining thinned wool sleeves with heavily quilted torso batting, this petite gambeson maximizes combat cadence. Petite duelists deliver lightning-fast parries without torso protection fatigue.",
    },
    ["xs_gambeson_wool_vest"] = {
        zh = "羊毛夹棉的小号武装背心。短小利索，能把娇小躯干的体温牢牢锁在体内，同时在近身肉搏中充当吸收暗劲重击的人体防撞垫，实穿性无可挑剔。",
        en = "This diminutive wool-padded vest locks body heat into small torsos. It functions as an ergonomic shock absorber against blunt blows while keeping shoulder joints totally free.",
    },
    ["xs_gauntlets_acidchitin"] = {
        zh = "利用变异酸蚁坚硬甲壳精巧拼合而成的小号板甲手套。不仅天然免疫酸性腐蚀，坚硬的几丁质外壳还能让纤细的手指在抓取灼热或腐蚀性物资时毫无顾忌。",
        en = "Assembled from acid-ant carapace fragments, these petite gauntlets shrug off chemical burns completely. Fragile mutant fingers handle caustic batteries and acidic organs with total safety.",
    },
    ["xs_gauntlets_chitin"] = {
        zh = "用变异甲虫硬壳手工打磨成型的小号甲虫手套。重量极轻且硬度惊人，贴合娇小手形，让小个子战士在近战格挡时拥有空手入白刃的底气与从容。",
        en = "Carved from giant beetle shell, these miniature chitin gauntlets feel weightless. Snugly fitting slender hands, they allow tiny duelists to swat aside incoming blades fearlessly.",
    },
    ["xs_gauntlets_larmor"] = {
        zh = "采用经过高温油煮硬化的优质厚皮制作的小号手甲。表面坚如软钢且没有任何金属反光与碰撞声，是身材瘦小的暗杀者进行夜间割喉突袭的最佳搭档。",
        en = "Formed from boiled hardened leather, these small gauntlets avoid all metallic glare and rattling. They serve as the quintessential tool for stealthy night infiltrators.",
    },
    ["xs_gloves_faux_fur"] = {
        zh = "内衬人造软毛的小号保暖手套。手感毛茸茸的十分可爱，能把细小瘦弱的手指保护在温暖的棉花糖包裹中，适合在干燥寒冷的冬日废墟里搜寻零碎零件。",
        en = "Lined with plush faux fur, these petite gloves feel delightfully fluffy. They shield fragile fingers from biting cold, perfect for sifting through frozen scrap for tiny components.",
    },
    ["xs_gloves_fsurvivor"] = {
        zh = "采用特种阻燃纤维精制的小号防火生存手套。掌心覆有耐高温防滑胶层，矮小的生存狂即便赤手抓握烧红的金属枪管或火把，也绝不会损伤手部娇嫩肌肤。",
        en = "Stitched from flame-retardant aramid with heat-resistant palm grips, these petite gloves let small survivors grab red-hot gun barrels and torches without blistering delicate skin.",
    },
    ["xs_gloves_fur"] = {
        zh = "用变异兔皮缝制的小号真皮毛手套。触感极其温润柔和，紧紧包裹着娇小的手掌，在零下严寒的废土荒野中，是预防细小指节冻伤发黑坏死的灵丹妙药。",
        en = "Tailored from genuine mutant rabbit fur, these small mittens radiate natural warmth. They keep petite wanderers from developing crippling frostbite across fragile knuckles during Arctic expeditions.",
    },
    ["xs_gloves_hsurvivor"] = {
        zh = "在掌背和指骨嵌入复合防弹甲片的小号重型生存手套。虽然套在细手上略显沉重，但握拳砸在丧尸下巴上时，产生的破坏力堪比小型冲锋锤砸击。",
        en = "Lined with composite armor plates over slender knuckles, these small heavy survivor gloves turn tiny fists into punishing mini-sledgehammers that fracture shambler jawbones on impact.",
    },
    ["xs_gloves_leather"] = {
        zh = "小号标准纯牛皮手套。皮质柔韧耐磨，既能有效防范攀爬废墟脚手架时生锈铁丝的扎刺，又让纤细的小手能够灵活自如地组装精密手表或扣动扳机。",
        en = "Classic small leather gloves crafted from pliable cowhide protect hands from rusty rebar slivers. They preserve enough finger tactile feedback to pick locks and assemble firearms.",
    },
    ["xs_gloves_light"] = {
        zh = "超薄轻盈的小号日常手套。贴合细小双手如同第二层皮肤，几乎感受不到任何负重，专为那些注重手感敏锐度的小体型神枪手与机械师打造。",
        en = "Featherlight and thin, these petite gloves hug slender fingers like a second skin. They provide essential dust protection while allowing marksmen to feel hair triggers clearly.",
    },
    ["xs_gloves_liner"] = {
        zh = "小尺码的超薄保暖内胆手套。可以轻松套入任何厚重的小号硬壳手套之内，在严寒天气下为娇小幸存者的指尖构筑一道额外的防失温保温内壁。",
        en = "Sized for small hands, these thin liners slip inside heavy gauntlets easily. They add a crucial micro-thermal barrier, keeping petite fingertips from freezing in subzero expeditions.",
    },
    ["xs_gloves_plate"] = {
        zh = "由数片精细小铁片铰接而成的小号板甲手套。戴上后手指屈伸时伴随着清脆的钢铁交错声，让矮小的战士在肉搏缠斗中拥有徒手击碎丧尸头骨的自信。",
        en = "Articulated from miniature steel plates, these plate gauntlets clink crisply as fingers curl. They grant small fighters the formidable confidence to smash zombie skulls bare-handed.",
    },
    ["xs_gloves_studded"] = {
        zh = "在指关节处铆接微型硬质金属铆钉的小号皮手套。虽然拳面尺寸较小，但在敏捷出拳速度的加持下，挥出的每一击都能在敌人的面门上留下深深的血印。",
        en = "Studded with steel rivets across slender knuckles, these petite brawler gloves turn agile punches vicious. Fast straight jabs leave bloody welts and fractures on enemy faces.",
    },
    ["xs_gloves_survivor"] = {
        zh = "结合了凯夫拉防割纤维与减震手掌衬垫的小号幸存者手套。剪裁极其严整贴身，是那些活跃在第一线的娇小拾荒者处理尖锐玻璃与碎金属时的标配装备。",
        en = "Integrating cut-resistant Kevlar with palm padding, these small survivor gloves hug tiny wrists neatly. They are indispensable for petite scavengers rummaging through jagged glass and twisted scrap.",
    },
    ["xs_gloves_wool"] = {
        zh = "手工粗毛线编织的小号羊毛手套。柔软可爱，保暖性能优秀，能够有效抵御冬日废墟里无处不在的刺骨穿堂风，让矮小的探险家双手始终温暖如春。",
        en = "Hand-knitted from coarse wool, these small gloves radiate rustic comfort. They block icy draft howling through broken windows, keeping petite explorers snug while searching frozen rooms.",
    },
    ["xs_gloves_wool_fingerless"] = {
        zh = "露出纤细指节的小号露指羊毛手套。为小体型变异者保留了拨动保险、翻阅旧地图和数弹药的指尖灵敏度，同时手掌部位依然被羊毛紧紧温暖包裹。",
        en = "Exposing slender fingertips, these fingerless wool gloves retain tactile sensitivity for handling cartridges and reading faded maps, while keeping palms and wrists delightfully cozy.",
    },
    ["xs_gloves_wsurvivor"] = {
        zh = "多层防风防水织物配合厚实毛皮里衬的小号冬用生存手套。在极寒暴风雪肆虐的废土上，为身材矮小的求生者筑起了一座坚不可摧的手部温室要塞。",
        en = "Layering windproof textiles over plush fur lining, these petite winter survivor gloves conquer Arctic gales. They function as miniature thermal greenhouses for fragile, frost-prone hands.",
    },
    ["xs_gloves_wsurvivor_nofur"] = {
        zh = "无动物皮毛的小号合成防寒手套。完全采用高科技中空合成保暖纤维填充，就算不小心跌入雪水浸湿表面，内层依然能在短时间内迅速恢复干爽与温暖。",
        en = "Filled with synthetic hollowfibers instead of pelt, these small winter gloves dry quickly. Dropping your hands into wet slush will not leave your fingers freezing and numb.",
    },
    ["xs_hc_chainmail_arms"] = {
        zh = "由高碳淬火钢环密编而成的小号锁甲袖。紧实包裹细长双臂，重量分配均匀，即便是近距离遭遇狂暴撕咬，也休想咬开这层坚如磐石的微型钢网护壁。",
        en = "Woven from hardened high-carbon rings, these small chainmail sleeves hug slender limbs. Feral beasts lunging at your forearms break their incisors against the unyielding steel mesh.",
    },
    ["xs_hc_chainmail_aventail"] = {
        zh = "垂吊于小头盔下方的高碳钢锁甲护颈。密不透风的钢环如同一条冰冷项圈护住纤细脖颈，彻底粉碎了掠食者企图从背后发动致命割喉奇袭的阴谋。",
        en = "Draping from small helmets, this high-carbon aventail encloses slender necks in cold rings. Lurking stalkers attempting throat slashes from behind produce only helpless friction sparks.",
    },
    ["xs_hc_chainmail_face"] = {
        zh = "遮覆下半边面孔的小号高碳钢锁甲面帘。微小的钢环在呼吸间发出细微的铁声，不仅能防范贴脸扑咬，还让矮小战士散发出一种冷酷无情的刺客威仪。",
        en = "Covering petite jaws with dense high-carbon links, this mail veil muffles heavy panting. It turns away face-biting crawlers while cloaking small fighters in cold, ruthless mercenary mystique.",
    },
    ["xs_hc_chainmail_feet"] = {
        zh = "高碳钢环密织的小号锁甲足套。套在小靴子外层能够从容践踏满布尖锐铁钉和碎石的危险地形，让娇小的穿戴者在逃脱围攻时脚步稳如磐石。",
        en = "Enclosing petite boots in high-carbon steel mesh, these foot wraps brave spike-strewn ground fearlessly. Small scavengers dash over nail-studded floorboards without puncturing their fragile soles.",
    },
    ["xs_hc_chainmail_half_legs"] = {
        zh = "高碳钢编织的小号半截护腿锁甲。专注于覆盖大腿前方要害，在抵御劈砍的同时保留了娇小身体短跑冲刺所需的灵敏轻盈，攻守兼备。",
        en = "Shielding upper thighs with high-carbon links, these small half-chausses deflect downward machete chops. They keep vital arteries safe without burdening pint-sized fighters with crushing weight.",
    },
    ["xs_hc_chainmail_hands"] = {
        zh = "由高碳钢环手工串接而成的小号锁甲手套。让纤细的小手具备了空手抓握带刺铁丝网和格挡短刀的强悍实力，挥掌抽击时更是沉重如铁掌般致命。",
        en = "Knitted from high-carbon steel links, these small mail mittens grab barbed wire and parry daggers directly. Landing an open-handed slap delivers shocking, iron-weighted kinetic blunt force.",
    },
    ["xs_hc_chainmail_hood"] = {
        zh = "紧贴小巧头颅的高碳钢锁甲头巾。坚韧的钢环能轻而易举地弹开高处掉落的碎石瓦砾，是微型幸存者在结构脆弱的倾塌楼房中搜刮物资时的守护神。",
        en = "Fitting petite heads snugly, this high-carbon coif deflects falling brickwork and loose masonry. It protects fragile craniums while exploring unstable, earthquake-shattered apartment ruins.",
    },
    ["xs_hc_chainmail_legs"] = {
        zh = "全覆盖的高碳钢小号锁甲护腿。无数枚精制钢环在走动中宛若流水般包裹住细弱的双腿，让穿行在满是异化毒虫的沼泽荒草中的旅程变得彻底无忧无虑。",
        en = "Encasing slender legs in high-carbon mail, these small chausses offer total lower defense. Wading through serpent-infested swamp grass becomes an entirely painless, worry-free stroll.",
    },
    ["xs_hc_chainmail_vest"] = {
        zh = "专为娇小体格量身打造的高碳钢锁甲背心。紧凑的钢环网在不增加过多死重的前提下，为心肺要害筑起一道坚不可摧的壁垒，正面硬接长矛突刺毫无压力。",
        en = "Tailored for petite physiques, this high-carbon chainmail vest guards vital thoracic organs securely. Interlocking hardened rings turn aside direct spear thrusts without overburdening tiny fighters.",
    },
    ["xs_hc_greaves_brigandine"] = {
        zh = "在皮革衬垫上铆固高碳钢板条的小号胫甲。坚固平滑的钢板条完美契合细瘦小腿，任凭变异恶犬在地面如何疯狂啃咬，也休想伤及皮肉半寸。",
        en = "Riveted with high-carbon splints over tough leather, these petite greaves shield slender shins. Low-angle snapping from feral hounds leaves zero marks on your protected legs.",
    },
    ["xs_hc_helmet_nasal"] = {
        zh = "带有高碳钢鼻甲护梁的小号诺曼头盔。粗壮坚硬的鼻梁护条为娇小突变者的面门提供了坚不可摧的庇护，防止在巷战近身推搡中被打碎鼻骨。",
        en = "Featuring a rigid high-carbon nasal bar, this small Norman helmet guards delicate facial features. Close-quarters barroom shoves and thrown stones bounce off the central metal spine.",
    },
    ["xs_hc_helmet_turban"] = {
        zh = "造型优雅的小号高碳钢尖顶缠头盔。独特的锥形盔顶能够高效分散顶部下砸的重击，让矮小的废土战士在废墟冲锋时兼备童话般的英气与绝对防御。",
        en = "Featuring a pointed high-carbon dome, this small turban helm sheds overhead hammer blows gracefully. Petite fighters charging across rubble look heroically mythic while remaining completely bulletproof.",
    },
    ["xs_hc_mirror_armor"] = {
        zh = "四片高碳淬火钢圆盘用真皮固定在娇小胸背。坚硬明亮的镜面不仅具备优异的抗刺穿能力，在反光照耀下更是宛如给矮小英雄披上了一层闪耀的神圣光环。",
        en = "Four high-carbon steel mirrors strap tightly over petite chests. Beyond delivering exceptional stab protection, their polished sheen blinds foes under bright sun like a mythic aura.",
    },
    ["xs_hc_steel_facemask"] = {
        zh = "高碳钢板精冲成型的小号冷酷铁面具。严实封闭娇小面庞，在隔绝毒气飞沫与利爪撕扯的同时，让穿戴者在混乱战场上展现出一副无可动摇的钢铁扑克脸。",
        en = "Pressed from rigid high-carbon steel, this small face mask hides tender expressions completely. It blocks flying debris while projecting an unflinching, stoic presence across desperate wasteland standoffs.",
    },
    ["xs_hc_vambrace_brigandine"] = {
        zh = "紧固高碳钢板条的小号板条护臂。戴在纤细小臂上坚硬如铁箍，格挡劈砍过来的消防斧或钢管时，迸射出的耀眼火星足以令任何狂妄的袭击者心惊胆战。",
        en = "Reinforced with high-carbon splints, these small vambraces turn slender arms into steel deflectors. Parrying fire axes and lead pipes produces brilliant sparks that rattle attacking raiders.",
    },
    ["xs_helmet_bronze"] = {
        zh = "小尺码浇铸成型的古典青铜头盔。暗金色的铜壁散发出沉静古朴的历史厚重感，扣在小脑袋上宛如远古斯巴达神童降临人间，威风凛凛。",
        en = "Cast in ancient bronze for smaller heads, this helmet gleams with historic gravity. Wearing it transforms a diminutive survivor into a pint-sized Spartan warrior ready for Thermopylae.",
    },
    ["xs_helmet_nomad"] = {
        zh = "参考游牧猎手护具制作的小号尖顶头盔。带有柔软舒适的皮护耳与护颈，在狂野废土荒原上飞驰时，不仅能抵御颠簸撞击，还能阻绝凛冽呼啸的寒风。",
        en = "Modeled after nomadic hunter gear, this small pointed helm features soft leather flaps. It protects tiny skulls from overhead impacts while blocking freezing winds on barren wastes.",
    },
    ["xs_hood_fsurvivor"] = {
        zh = "采用芳纶阻燃面料小尺码剪裁的防火生存兜帽。严密包裹小巧的头颅与后颈，面对火焰丧尸喷薄而出的炽热爆弹，它能确保每一根娇嫩的头发都安然无损。",
        en = "Tailored from flameproof aramid fabric for petite heads, this survivor hood shrugs off thermal fireballs. Searing explosions from incendiary zombies leave your hair completely unsinged.",
    },
    ["xs_hood_wsurvivor"] = {
        zh = "内衬丰厚动物皮毛的小号冬用生存兜帽。紧紧抽拉防风抽绳后，就像给小巧的脑袋安了一间保温温室，任由零下几十度的暴风雪在兜帽外肆虐呼啸。",
        en = "Lined with plush fur for small frames, this winter hood creates an impenetrable pocket of warmth. Pulling the drawstring tight isolates delicate ears from shrieking subzero blizzards.",
    },
    ["xs_hood_wsurvivor_nofur"] = {
        zh = "无动物皮毛的小号合成防寒生存兜帽。依靠多孔科技保暖棉锁住热量，不沾雪水且不易吸附异味，是讲究清洁卫生的微型幸存者在寒冬行军时的理想伙伴。",
        en = "Insulated with synthetic microfibers instead of pelt, this small winter hood repels slush cleanly. It provides odor-free, hypoallergenic warmth for petite travelers trekking across frozen ruins.",
    },
    ["xs_hsurvivor_jumpsuit"] = {
        zh = "集成钛合金插板、凯夫拉织层与缓冲内衬的小号重型生存连体服。虽然穿在矮小身躯上略显沉甸，但赋予你的综合抗打击能力足以媲美小型步兵战车。",
        en = "Integrating titanium inserts and dense Kevlar weave into a petite frame, this heavy jumpsuit feels substantial. It turns a tiny survivor into a walking, armored personnel carrier.",
    },
    ["xs_k_gambeson_sleeve"] = {
        zh = "在衍缝棉层内混纺了高强度凯夫拉防弹纤维的小号武装袖。贴合细瘦手臂，在提供柔韧减震的同时，彻底消除了被弹片撕裂大动脉的致命风险。",
        en = "Blending ballistic Kevlar fibers into quilted cotton layers, these small sleeves protect slender arms. They absorb heavy blunt impacts while preventing shrapnel from slicing vital arteries.",
    },
    ["xs_knuckle_brass"] = {
        zh = "针对小手掌精铸的微型黄铜指虎。指孔紧凑贴合，挥出的小拳头在黄铜硬块加持下力道暴增，一记精准的面门短勾拳能把丧尸的牙齿砸得七零八落。",
        en = "Precision-cast with compact finger loops for tiny hands, these brass knuckles multiply punching force. A crisp short jab shatters shambler incisors without bruising delicate knuckles.",
    },
    ["xs_knuckle_impact"] = {
        zh = "装配微型铅芯配重块与硅胶减震垫的小号冲击指虎。虽然拳头体积不大，但挥拳撞击时释放的爆发动能，足以让两倍于自己体重的袭击者当场眼冒金星。",
        en = "Fitted with miniature lead counterweights and silicone dampeners, these small impact knuckles hit with shocking kinetic inertia, rattling adversaries twice your size instantly.",
    },
    ["xs_knuckle_nail"] = {
        zh = "在小号铁指套前端焊接数根淬火小铁钉的凶悍打架道具。矮小突变者挥拳出击不需要任何繁琐武术套路，只要擦中目标，就能撕下一大块血肉模糊的皮肉。",
        en = "Sprouting sharpened steel nails across compact finger loops, this nasty weapon turns petite punches lethal. A frantic swing shreds through clothing and gouges deep bloody furrows.",
    },
    ["xs_knuckle_skewer"] = {
        zh = "带有三根三棱锋利细钢刺的小号指虎。出拳轻快狠辣，如毒蛇吐信般直接破开防弹布与厚皮甲，让任何胆敢小觑矮个子战士的敌人付出惨痛血的代价。",
        en = "Featuring three triangular steel skewers over tiny knuckles, this brawling weapon pierces leather effortlessly. It reminds overconfident bandits that pint-sized duelists strike with venomous lethality.",
    },
    ["xs_knuckle_steel"] = {
        zh = "由整块实心高碳钢线切割抛光而成的小号精钢指虎。质地冷硬纯粹，贴合娇小指节，一记沉重的下勾拳挥出，足以让任何自命不凡的废土掠夺者下巴脱臼。",
        en = "Machined from a solid high-carbon steel billet, these diminutive knuckles fit tiny fingers seamlessly. Landing a firm uppercut dislocates jaws and fractures cheekbones without deformation.",
    },
    ["xs_knuckle_steel_forged"] = {
        zh = "铁匠在小型铁砧上手工锤打而成的小号锻钢指虎。表面带有细碎粗糙的锻打锤痕，抓握极度牢靠，在泥泞近身缠斗中砸击敌人骨骼时手感扎实硬朗。",
        en = "Hand-forged on a miniature anvil, these steel knuckles bear textured hammer scars that enhance grip. Slamming them into enemy bone during muddy scuffles produces solid, resounding thuds.",
    },
    ["xs_lc_chainmail_arms"] = {
        zh = "用低碳软钢环手工串编而成的小号锁甲袖。质地柔韧舒适，完美包裹娇小双臂，虽然防刺穿稍逊一筹，但抵挡普通丧尸的撕咬与抓挠完全绰绰有余。",
        en = "Woven from pliable mild steel links, these small chainmail sleeves hug slender arms comfortably. They deflect scratching claws and wandering shambler teeth without burdening delicate muscles.",
    },
    ["xs_lc_chainmail_aventail"] = {
        zh = "悬挂在小头盔底缘的低碳钢锁甲护颈。柔软的铁环如瀑布般护在细小的肩膀上，有效封堵了致命的颈部要害缝隙，防止矮个子战士在贴身战中被抹喉偷袭。",
        en = "Draping softly from petite helmets, this mild steel aventail covers slender necks. It seals fatal collar gaps, keeping pint-sized fighters safe from sudden close-quarters throat slashes.",
    },
    ["xs_lc_chainmail_face"] = {
        zh = "由普通细铁环编缀而成的小号锁甲面网。虽然经常需要抹点机油防止水汽生锈，但它能把迎面泼来的酸液和碎石有效弹开，守护娇小幸存者的下半张脸孔。",
        en = "Rust-prone breath moisture discolors this small mild steel mail veil over time. Still, oiling it regularly maintains a dependable barrier against flying gravel and acidic spittle.",
    },
    ["xs_lc_chainmail_feet"] = {
        zh = "为小码鞋履定制的低碳钢锁甲足套。踩碎废墟碎石与瓦砾时金属清脆响亮，细密的钢环能有效防止地面爬行幼虫或变异跳蚤钻入靴口咬破皮肤。",
        en = "Fitted over petite shoes, these mild steel chainmail covers clink across broken rubble. Dense rings stop burrowing mutant fleas and crawling grubs from slipping beneath footwear cuffs.",
    },
    ["xs_lc_chainmail_half_legs"] = {
        zh = "小号低碳钢半截锁甲护腿。轻便小巧，专注于保护大腿正面要害免遭劈砍重创，同时减轻下肢负担，让娇小敏捷的突变者在逃命时依然健步如飞。",
        en = "Covering petite thighs with mild steel links, these half-chausses absorb overhead swings. Saving dead weight ensures nimble mutants sprint across rubble-strewn alleys at blazing speeds.",
    },
    ["xs_lc_chainmail_hands"] = {
        zh = "由低碳钢环细密串编而成的小号锁甲手套。握持粗糙的废铁水管时不仅摩擦力十足，在面对扑咬上来的变异老鼠时，抬手一挥就能将其直接砸晕。",
        en = "Woven from mild steel links, these small mail mittens grip rough pipes securely. Swatting away lunging mutant rats delivers enough blunt kinetic punch to stun rodents cold.",
    },
    ["xs_lc_chainmail_hood"] = {
        zh = "紧扣娇小脑袋的低碳钢锁甲头巾。轻巧柔韧，不仅能弹开高处掉落的细小碎石，还能在矮小幸存者钻入狭窄通风管或铁丝网缺口时保护头皮免受划伤。",
        en = "Hugging petite heads snugly, this mild steel coif deflects falling debris. Crawling through rusted wire fences or low ducts shields delicate scalps from painful jagged tears.",
    },
    ["xs_lc_chainmail_legs"] = {
        zh = "全套小号低碳钢锁甲长裤。细密的铁环随轻盈的步伐沙沙作响，为双腿筑起一道防刮防咬的坚实防护，横穿带刺草丛和毒虫泥沼毫无顾忌。",
        en = "Encasing slender legs in mild steel mesh, these small chausses rustle with every step. Wading through thorny briars and infested wetlands becomes an easy, painless journey.",
    },
    ["xs_lc_chainmail_vest"] = {
        zh = "轻巧实用的低碳钢小号锁甲背心。重量完全在矮小体格的承受范围内，贴合保护胸腹主要脏器，是微型突变战士在近距离混战中最亲民的铁甲护身符。",
        en = "Pragmatically tailored for small frames, this mild steel vest protects vital organs. It serves as an accessible, dependable steel talisman for pint-sized front-line combatants.",
    },
    ["xs_lc_greaves_brigandine"] = {
        zh = "以低碳钢板条细致铆固于牛皮内的小号胫甲。韧性极佳且易于整饬，即便在碰撞中砸出小浅坑，拿块鹅卵石在膝头敲几下就能迅速恢复原状。",
        en = "Riveted with mild steel splints inside soft leather, these petite greaves deform under heavy impacts. Fortunately, flattening dents requires merely a smooth roadside stone.",
    },
    ["xs_lc_helmet_nasal"] = {
        zh = "配有低碳钢鼻梁护梁的小号诺曼圆锥盔。简单坚韧，粗挺的金属鼻甲横梁为那张稚嫩的小脸构筑起坚实屏障，防止在狂野乱斗中面部中招。",
        en = "Featuring a simple mild steel nasal bar, this small Norman conical helmet shields petite faces. It halts errant fist strikes and thrown rocks from crushing delicate features.",
    },
    ["xs_lc_helmet_turban"] = {
        zh = "线条圆润的小号低碳钢缠头尖顶盔。优美的曲面穹顶能够顺畅偏斜来自上方的钝器敲击，让娇小玲珑的战士在废土乱军中显得宛如灵动的小武士。",
        en = "Topped with an elegant pointed dome of mild steel, this small helmet deflects downward cleaves. Petite warriors moving through ruins look like nimble fairytale knights in armor.",
    },
    ["xs_lc_mirror_armor"] = {
        zh = "四片低碳钢盘固定在娇小身躯前后的小号护胸镜甲。虽然需要经常上油擦拭以防生锈，但在明亮日光下反射出的耀眼强光，总能让突袭的对手措手不及。",
        en = "Four mild steel discs strap across petite chests, demanding regular oiling against rust. In direct noon sunlight, their dazzling reflections catch charging raiders completely off-guard.",
    },
    ["xs_lc_steel_facemask"] = {
        zh = "低碳钢板手工敲打成型的小号金属面具。虽然表情呆滞宛如玩具铁皮人，但面对扑面而来的尖牙和碎石，这层铁皮能忠实守卫娇小幸存者的容颜安全。",
        en = "Hand-hammered from mild steel, this petite mask looks like a toy tin soldier. Facing flying debris and frantic claws, it faithfully guards delicate facial features from harm.",
    },
    ["xs_lc_vambrace_brigandine"] = {
        zh = "在皮革衬垫上铆接低碳钢条的小号护臂。柔韧坚固，戴在细胳膊上严丝合缝，抬手格挡生锈砍刀或木棒挥击时，能将震荡冲击力迅速化解。",
        en = "Lining tough hide with mild steel splints, these small vambraces wrap slender forearms snugly. Raising an arm deflects rusty machetes and clubs without fracturing brittle bones.",
    },
    ["xs_legguard_acidchitin"] = {
        zh = "用变异酸蚁腿部几丁质手工打磨而成的小号防酸护腿。天然免疫任何强酸腐蚀液，穿上它在酸液横流的地下蚁穴中穿梭，细瘦的双腿丝毫不受侵蚀。",
        en = "Crafted from acid-ant leg carapaces, these petite legguards resist corrosive chemicals. Petite scouts wade through acid-coated subterranean ant tunnels without risking lethal burns.",
    },
    ["xs_legguard_bronze"] = {
        zh = "按照娇小体型浇铸成型的小号青铜护腿。散发着古典厚重的金属光泽，严密包裹小腿迎面骨，抵御钝击与利刃劈砍的综合性能极为可靠扎实。",
        en = "Cast in solid bronze for small frames, these ancient-styled legguards gleam with reddish luster. Encasing shins completely, they provide dependable defense against clubs and blades.",
    },
    ["xs_legguard_chitin"] = {
        zh = "利用变异甲虫背壳边角料打磨加工的小号昆虫护腿。重量极轻却硬如坚石，娇小幸存者穿戴它奔跑跳跃时毫无赘重拖累，轻巧敏捷宛如飞燕掠地。",
        en = "Polished from beetle shell fragments, these tiny chitin legguards feel featherlight. Petite survivors dash and leap across obstacles without clumsy weight slowing down their strides.",
    },
    ["xs_legguard_larmor"] = {
        zh = "多层加厚熟牛皮经烘烤硬化制成的小号皮护腿。表面光滑无反光，在保护小腿免遭变异灌木划伤的同时，走动间完全不会发出任何金属撞击噪音。",
        en = "Molded from hardened boiled leather, these small legguards eliminate all metallic rattling. They shield shins against jagged briars while letting stealthy scouts sneak through darkness.",
    },
    ["xs_legguard_metal"] = {
        zh = "采用薄钢板弯折打磨成型的小号金属护腿。结构坚固简洁，正面迎向低矮丧尸或变异犬撕咬时坚不可摧，彻底断绝了小腿被偷袭撕裂的隐患。",
        en = "Bent from thin steel plate, these miniature metal legguards feature a clean, rigid profile. Facing lunging dogs and crawling zombies, they turn away bites with absolute rigidity.",
    },
    ["xs_legguard_metal_sheets"] = {
        zh = "用废旧罐头盒铁皮叠压包裹成型的小号铁皮护腿。虽然外观有些粗糙寒酸，但重叠的多层薄金属皮确实能有效挡住刺猬倒刺与灌木硬刺的扎扎刺刺。",
        en = "Layered from salvaged tin cans, these makeshift small legguards look rustic. Yet their multi-ply metal construction successfully blocks barbed briars and mutant porcupine quills.",
    },
    ["xs_legguard_scrap"] = {
        zh = "生锈铁皮、铁丝和摩托车链条混搭拼制的小号废料护腿。外观虽然充满末日废土的狂放与破烂，但结实的废料护甲确实能救你细嫩的小腿于水火之中。",
        en = "Pieced together from rusted sheet metal, wire, and bike chains, these scrap legguards look chaotic. Nevertheless, their bulk absorbs heavy pipe blows and stops bleeding cuts.",
    },
    ["xs_legguard_tire"] = {
        zh = "废弃小踏板摩托车外胎裁剪制成的小号橡胶护腿。防咬减震性能出众且完全不怕雨水浸泡，是身材矮小的废土拾荒者最廉价也最耐用的腿部防具。",
        en = "Carved from discarded scooter tires, these small rubber legguards absorb crushing bites and resist water. They offer petite wasteland wanderers affordable, near-indestructible protection.",
    },
    ["xs_lsurvivor_armor"] = {
        zh = "针对小身材剪裁的轻型生存护甲套装。集成轻薄防刺芳纶板与透气网眼布，在保留极端奔跑爆发力的同时，为脆弱娇小的胸腹提供了可靠的防撕裂屏障。",
        en = "Tailored for small builds, this lightweight survivor armor combines aramid sheets with breathable mesh. It maintains explosive sprinting agility while shielding chests from vicious claws.",
    },
    ["xs_lsurvivor_jumpsuit"] = {
        zh = "防刺织物精裁而成的小号轻型生存连身服。体贴包裹纤弱肢体，透气快干，即使在阴湿闷热的废墟下水道中长期跋涉，也能保持皮肤干爽舒适无异味。",
        en = "Stitched from puncture-resistant weave for petite frames, this light jumpsuit hugs limbs snugly. It dries rapidly in humid subterranean ruins, keeping sensitive skin clean and comfortable.",
    },
    ["xs_mc_chainmail_arms"] = {
        zh = "由中碳钢环紧密串接而成的小号锁甲袖。硬度与韧性维持在完美黄金比例，套在纤细手臂上轻便灵活，能轻松弹开迎面扫来的砍刀与丧尸扑咬。",
        en = "Woven from medium-carbon links, these small chainmail sleeves balance strength with flex. Hugging slender arms, they glance away machete cleaves and frantic shambler bites effortlessly.",
    },
    ["xs_mc_chainmail_aventail"] = {
        zh = "悬挂在小头盔周围的中碳钢护颈锁甲。紧密的钢环在肩膀上铺展成一层厚实的防割护圈，彻底粉碎了任何自阴暗角落刺向咽喉的致命偷袭企图。",
        en = "Draping from helmet rims across petite shoulders, this medium-carbon aventail forms a cut-proof curtain. Lurking ambushers seeking sudden throat thrusts break their daggers on steel.",
    },
    ["xs_mc_chainmail_face"] = {
        zh = "罩在娇小下半张脸孔上的中碳钢锁甲面帘。不仅能在近身混战中挡住正面飞来的碎玻璃片，还能在严冬中将呼出的热气转化为微弱的下颌保温层。",
        en = "Covering petite jaws with medium-carbon mesh, this mail veil stops flying glass shrapnel. In subzero gales, it traps exhaled warm breath to keep small chins comfortable.",
    },
    ["xs_mc_chainmail_feet"] = {
        zh = "中碳钢环细密编缀而成的小号锁甲足套。套在鞋外轻盈无负担，踩在铺满碎瓦片与生锈铁丝的恶劣路面上，能彻底打消被锋利毛刺穿透鞋底的恐慌。",
        en = "Woven from medium-carbon links, these small foot wraps slip over boots easily. Stomping across shattered roof tiles and rusted rebar never threatens to pierce delicate soles.",
    },
    ["xs_mc_chainmail_half_legs"] = {
        zh = "覆盖大腿前侧的中碳钢小号半截锁甲。为娇小战士的大腿动脉提供了至关重要的防劈砍保护，同时敞开后侧以最大限度保留短跑冲刺的绝佳机动性。",
        en = "Shielding upper thighs with medium-carbon rings, these half-chausses protect femoral arteries. Leaving calves unencumbered ensures petite duelists sprint through alleyways with blazing speed.",
    },
    ["xs_mc_chainmail_hands"] = {
        zh = "中碳钢环手工编排而成的小号锁甲手套。不仅让细小的手掌在格挡利刃时毫无后顾之忧，在徒手翻爬布满带刺铁丝的围墙时更能提供无与伦比的安全感。",
        en = "Crafted from medium-carbon links, these petite mail mittens handle bare steel blades fearlessly. Scaling walls topped with razor wire becomes completely safe and painless.",
    },
    ["xs_mc_chainmail_hood"] = {
        zh = "紧密贴合小巧头颅的中碳钢锁甲头巾。坚固的中碳钢能平滑偏转高空坠落的水泥碎屑，是身材娇小的斥候深入摇摇欲坠的瓦砾危房时的保命护具。",
        en = "Fitting petite heads snugly, this medium-carbon coif deflects falling cement fragments. It serves as essential skull protection for petite scouts probing dilapidated, unstable ruins.",
    },
    ["xs_mc_chainmail_legs"] = {
        zh = "由中碳钢环紧密咬合构成的小号全套锁甲裤。紧致贴身，全面防御从膝盖到脚踝的所有低空咬噬与突刺，穿行在毒虫遍布的泥沼中宛如穿上了铁甲长袜。",
        en = "Encasing slender legs in interlocking medium-carbon rings, these chausses prevent low-angle bites. Wading through serpent-infested marshlands feels as secure as wearing iron stockings.",
    },
    ["xs_mc_chainmail_vest"] = {
        zh = "选用中碳钢打造的小巧锁甲背心。重量分配极其符合人体工程学，精准护卫娇小躯干的致命要害，让你在正面面对长矛直刺时胸有成竹、毫不慌乱。",
        en = "Ergonomically scaled for small builds, this medium-carbon chainmail vest guards vital organs. Interlocking steel links absorb thrusting spears, keeping tiny fighters calm during chaotic melees.",
    },
    ["xs_mc_greaves_brigandine"] = {
        zh = "在坚实皮革内衬中精密铆合中碳钢条的小号胫甲。坚固平整，完美包覆细长小腿，即便是变异野猪的低空獠牙挑击，也能在这副硬甲前被顺势滑开。",
        en = "Securing medium-carbon splints onto supple leather, these petite greaves encase fragile shins. Low-angle tusk strikes from charging boars glance harmlessly off the reinforced plates.",
    },
    ["xs_mc_helmet_nasal"] = {
        zh = "配有加固中碳钢鼻甲的小号圆锥盔。刚硬的鼻梁护梁为娇小面孔守住了中路要道，在狭窄走廊遭遇突发近战时，能有效抵挡迎面掷来的砖块与钝器击打。",
        en = "Featuring a reinforced medium-carbon nasal bar, this small conical helmet shields delicate facial bones. Thrown bricks and sudden pipe swings bounce safely off the rigid centerline.",
    },
    ["xs_mc_helmet_turban"] = {
        zh = "中碳钢冲压而成的小号尖顶缠头盔。高耸圆润的穹顶结构能极佳地卸掉上方劈落的刀刃，戴在小巧头顶上不仅安全感十足，还带有一种英姿飒爽的神话风韵。",
        en = "Topped with an elegant medium-carbon pointed dome, this small turban helm deflects heavy cleaves. Petite warriors wearing it look effortlessly heroic while staying totally safe.",
    },
    ["xs_mc_mirror_armor"] = {
        zh = "四片中碳钢圆盘用皮带精密固定在娇小躯干上的小号护胸镜甲。坚固硬朗，在防御穿刺之余，强烈的金属反光在晴天能让贴身肉搏的对手瞬间眩目失神。",
        en = "Four medium-carbon steel roundels strap firmly over petite torsos. Besides turning aside thrusts, their polished glare temporarily blinds adversaries during bright wasteland skirmishes.",
    },
    ["xs_mc_steel_facemask"] = {
        zh = "中碳钢板冲压打孔制作的小号铁面具。严实遮掩住娇小突变者的面貌，细密的透气孔防止水汽积聚，冰冷的钢面能为柔弱脸庞挡下所有飞溅的腐蚀毒刺。",
        en = "Perforated with neat ventilation slits, this small medium-carbon face mask hides tender expressions. The rigid steel barrier stops spitting spider toxins and flying gravel cold.",
    },
    ["xs_mc_vambrace_brigandine"] = {
        zh = "在厚皮内衬上紧固中碳钢条的小号护臂。戴在细小前臂上宛如坚实小盾，在混乱近身搏杀中抬臂格挡，能让狂暴挥落的铁管当场被反弹震飞。",
        en = "Riveted with medium-carbon splints, these small vambraces turn slender arms into rigid deflectors. Parrying swung lead pipes produces sharp clangs that disarm clumsy attackers.",
    },
    ["xs_qt_chainmail_arms"] = {
        zh = "采用经过高温油淬处理的淬火钢环精密编织的小号锁甲袖。每个微小钢环都拥有惊人的抗拉硬度，任凭变异怪物的利齿如何疯狂咀嚼，也休想咬断这层冰冷钢网。",
        en = "Woven from oil-quenched steel links, these small chainmail sleeves possess absurd tensile strength. Ravenous mutant predator teeth gnawing on your forearms will snap and shatter instantly.",
    },
    ["xs_qt_chainmail_aventail"] = {
        zh = "悬挂在小头盔下方的高规格淬火钢护颈锁甲。沉实坚固的钢环层层重叠，如同一座密不透风的钢铁瀑布，彻底杜绝了利刃抹喉或尖刺穿喉的任何微小可能。",
        en = "Draping from helmet rims, this quenched steel aventail encloses slender necks in hardened links. It completely eliminates the possibility of razor blades or stingers piercing throats.",
    },
    ["xs_qt_chainmail_face"] = {
        zh = "用顶级淬火硬化钢环密织而成的小号锁甲面帘。冰冷坚固的钢网覆在面颊下半部，在彻底抵御近身抓挠撕咬的同时，赋予娇小战士一种冷峻沉着的终极气场。",
        en = "Knitted from hardened quenched links, this petite mail veil shields small jaws from feral bites. It protects delicate bone while lending pint-sized warriors cold, unshakeable confidence.",
    },
    ["xs_qt_chainmail_feet"] = {
        zh = "采用顶级油淬钢丝细密织造的小号锁甲足套。即便纤细的小脚不慎踩中满布毒刺的捕兽陷阱，坚硬的淬火钢环也能让尖刺折断，保全脚掌骨骼完好无损。",
        en = "Knitted from oil-quenched steel links, these small chainmail foot wraps laugh at spiked traps. Stepping directly onto rusted caltrops snaps the spikes while keeping tiny soles unscathed.",
    },
    ["xs_qt_chainmail_half_legs"] = {
        zh = "覆盖大腿前侧的淬火钢小号半截锁甲。兼顾了惊人的抗劈砍硬度与极佳的下肢轻盈度，让身材瘦小的敏捷剑士在发起贴地突刺时毫无后顾之忧。",
        en = "Shielding upper thighs with quenched steel links, these small half-chausses deflect downward cuts. Petite duelists deliver low lunges without worrying about stray machetes slicing femoral arteries.",
    },
    ["xs_qt_chainmail_hands"] = {
        zh = "由硬化淬火钢环纯手工密编的小号锁甲手套。徒手握持锋利刀刃或是抓取带刺铁丝网宛如儿戏，握拳挥出时更能以小巧拳头爆发出令人震撼的钢铁重击。",
        en = "Woven from quenched steel rings, these miniature mail mittens grab razor blades safely. Punching opponents delivers shocking blunt force packed tightly into an unyielding metallic fist.",
    },
    ["xs_qt_chainmail_hood"] = {
        zh = "全方位覆盖娇小头颈部的淬火钢小号锁甲头巾。即便是高处坠落的混凝土碎块砸中头顶，坚韧的环网也能顺滑化解冲力，保全脆弱娇嫩的中枢神经。",
        en = "Encasing petite heads and slender necks in quenched steel links, this heavy coif cushions falling rubble. Its tensile integrity prevents severe concussions during collapsing building breaches.",
    },
    ["xs_qt_chainmail_legs"] = {
        zh = "淬火钢环编织成的完整小号锁甲护腿。沉实坚固的钢网将细瘦双腿紧密锁在铁壁之中，任凭尸群怎样在地面抓挠撕扯，也休想在这坚不可摧的铁裤上留下划痕。",
        en = "Covering slender legs in hardened quenched links, these small chausses laugh at swarming crawlers. Frantic claws scratching at your calves leave zero marks on the indestructible steel mesh.",
    },
    ["xs_qt_chainmail_vest"] = {
        zh = "专为娇小躯干核心要害量身打造的淬火钢锁甲背心。重量调校极其精准，紧密咬合的硬化钢环能直接弹开手枪跳弹和锋利长矛，给予微型战士绝对的心脏防护。",
        en = "Tailored for petite builds, this quenched steel vest protects vital organs without exhaustion. Interlocking hardened links deflect ricochets and thrusting spears, delivering absolute peace of mind.",
    },
    ["xs_qt_greaves_brigandine"] = {
        zh = "在坚韧皮革内衬中紧固顶级淬火钢板条的小号胫甲。坚固平滑，完美贴合细小腿骨，无论是变异野犬的飞扑撕咬还是低空霰弹扫射，都宛如撞上一堵微型铁墙。",
        en = "Securing quenched steel splints inside heavy hide, these miniature greaves encase fragile shins. Lunging wolf bites and low shotgun pellets glance harmlessly off like hail hitting armor.",
    },
    ["xs_qt_helmet_nasal"] = {
        zh = "带有一根高韧性淬火钢鼻梁横梁的小号诺曼盔。刚硬的鼻甲护梁为娇小面孔守住了中路防线，无论遭遇怎样凶狠的正面直拳，都能保全稚嫩鼻梁不被砸扁。",
        en = "Featuring an oil-quenched nasal bar, this small Norman helmet shields delicate facial features. Brutal frontal punches and thrown cobblestones bounce harmlessly off the rigid centerline.",
    },
    ["xs_qt_helmet_turban"] = {
        zh = "淬火钢锻造的小号尖顶缠头盔。经过精密热处理的锥形穹顶拥有绝佳的偏转斜角，不仅让重击劈砍滑溜无处受力，还彰显出一股横扫废土的冷峻小英雄风采。",
        en = "Forged from heat-treated steel into a tall onion dome, this small turban helm deflects cleaves smoothly while lending pint-sized mutants the undeniable swagger of wasteland champions.",
    },
    ["xs_qt_mirror_armor"] = {
        zh = "四片经过镜面抛光的高强淬火钢盘固定在娇小胸背。不仅具备坚如磐石的防穿刺性能，在烈日下反射出的刺眼强光，总能让企图偷袭的变异掠食者瞬间炫目失神。",
        en = "Four mirror-polished quenched steel discs strap over petite torsos. Besides turning aside daggers, their blinding midday glare dazzles stalking predators, buying precious seconds to strike back.",
    },
    ["xs_qt_steel_facemask"] = {
        zh = "采用顶级淬火钢板一体冲压成型的小号冷酷铁面具。冰冷平滑的面具上仅留细密的呼吸孔，戴上它宛如一尊微型钢铁死神，让任何狂妄的敌手感到不寒而栗。",
        en = "Seamlessly pressed from quenched steel, this miniature mask hides facial expressions behind an impenetrable barrier, projecting the terrifying stoic presence of a pint-sized wasteland reaper.",
    },
    ["xs_qt_vambrace_brigandine"] = {
        zh = "紧密排布淬火钢板条的小号板条护臂。戴在纤细小臂上坚硬似铁箍，抬手格挡生锈砍刀或重型撬棍时，清脆激荡的金属撞击声足以震得偷袭者虎口发麻甚至脱手。",
        en = "Reinforced with quenched steel splints, these small vambraces turn slender arms into impenetrable shields. Parrying crowbars produces jarring clangs that disarm overconfident attackers on contact.",
    },
    ["xs_shark_suit"] = {
        zh = "专为防范鲨鱼咬伤设计的不锈钢密织防鲨潜水服，经过精密缩减剪裁以契合娇小体型。穿上它走入尸潮中，丧尸那腐烂的尖牙咬在钢丝网上只会像在嚼钢丝擦锅球。",
        en = "Tailored down for petite frames, this stainless steel shark mail suit repels bites completely. Shamblers gnawing on your limbs feel like they are chewing kitchen scouring pads in vain.",
    },
    ["xs_shark_suit_faraday"] = {
        zh = "在小号防鲨锁甲服的基础上加装完整接地回路的法拉第潜水服。除了物理防撕咬外，电击丧尸喷射出的万伏高压电弧也会被金属网无害地导入大地，安全可靠。",
        en = "Integrating grounded circuits into a stainless shark mail suit, this Faraday variant shields tiny mutants from high-voltage arc attacks unleashed by roaming electric shocker zombies.",
    },
    ["xs_survivor_vest"] = {
        zh = "采用多层凯夫拉、缓冲海绵和耐磨帆布专为小身材剪裁的幸存者战术背心。紧凑的躯干防护不带丝毫累赘，外挂的迷你织带还能稳稳插满急救针剂与备用弹匣。",
        en = "Blending Kevlar weave, shock foam, and rugged canvas, this small vest protects petite torsos while providing abundant MOLLE loops for injectors and spare pistol magazines.",
    },
    ["xs_tacvest"] = {
        zh = "小尺码军规防弹插板战术背心。小巧紧凑的包覆让矮小射手在战壕中趴卧探头时毫不臃肿，胸前模块化附包里塞满了能维持数天高强度作战的微型补给品。",
        en = "Scaled down for petite frames, this tactical plate carrier prevents encumbrance. Snug modular pouches hold enough concentrated rations and ammunition for prolonged wasteland reconnaissance patrols.",
    },
    ["xs_vambrace_larmor"] = {
        zh = "用多层熟牛皮经油脂浸透烘干制成的小号皮护臂。轻巧贴合且毫无金属反光，细弱小臂戴上它之后既能防范灌木刮擦，又能在伏击掠夺者时保持绝对的无声隐蔽。",
        en = "Molded from hardened boiled leather, these small vambraces eliminate metallic glare. They protect slender forearms against jagged brambles while keeping ambush positions perfectly silent.",
    },
    ["xs_wetsuit"] = {
        zh = "采用加厚氯丁橡胶精密裁剪的小号潜水湿衣。紧紧贴合娇小纤弱的变异身躯，让你在冰冷的下水道水流或废弃化工厂污水池中潜泳作业时，依然能牢牢锁住核心体温。",
        en = "Cut from thick neoprene for small frames, this wetsuit insulates fragile bodies snugly. Swimming through freezing sewer currents or chemical runoff basins will not trigger crippling hypothermia.",
    },
    ["xs_wetsuit_booties"] = {
        zh = "带有防滑橡胶底的小号潜水靴套。能严实包裹住细小的脚掌，在布满湿滑绿苔的水下排污管道或废弃泳池底部行走时，提供稳定可靠的抓地力，杜绝意外滑倒。",
        en = "Equipped with vulcanized rubber soles, these miniature neoprene booties wrap small feet. They offer dependable traction while wading through slimy sewer pipes and flooded basement corridors.",
    },
    ["xs_wetsuit_booties_thick"] = {
        zh = "额外加厚氯丁橡胶保暖层的小号潜水靴。专为极寒水域搜刮设计，即便在初春浮冰密布的冰冷河床中赤足涉水，娇嫩的脚趾也能始终保持温暖与灵活奔跑力。",
        en = "Featuring extra-thick neoprene insulation, these small booties conquer freezing waters. Trudging through slushy riverbeds in early spring will not numb your delicate toes or slow your escape.",
    },
    ["xs_wetsuit_gloves"] = {
        zh = "具有优异防水与保暖性能的小号潜水手套。掌心覆有微型防滑胶粒，让娇小的手掌在浑浊的淹没地下室中摸索生锈阀门或拾取零件时，绝对不会因为滑腻而失手。",
        en = "These small neoprene gloves keep petite hands warm underwater. Textured palm grips prevent slippery accidents when turning rusty valves inside flooded subterranean maintenance bunkers.",
    },
    ["xs_wetsuit_gloves_thick"] = {
        zh = "加厚型氯丁橡胶小号潜水手套。虽然手指弯曲时略感阻力，但在零下低温的废土冰窟深处打捞沉没物资时，它能确保每一根细小的手指都免受严重冻疮侵袭。",
        en = "Thickly padded with neoprene, these small diving gloves reduce dexterity slightly. In exchange, plunging into subzero icy aquifers will not inflict crippling frostbite on fragile fingers.",
    },
    ["xs_wetsuit_hood"] = {
        zh = "紧绷贴合的小号潜水兜帽。将小巧头颅和纤细脖颈严密封闭在橡胶膜内，潜入幽暗深水区时不仅能阻挡刺骨冰水灌入耳膜，还能杜绝变异水蛭的悄悄叮咬附着。",
        en = "Hugging petite craniums and necks snugly, this small neoprene hood seals out freezing water, preventing icy currents and parasitic mutant leeches from entering ears during dives.",
    },
    ["xs_wetsuit_hood_thick"] = {
        zh = "极地级别加厚的小号氯丁橡胶潜水帽。极致的隔热性能宛如给整颗小脑袋扣上了一只橡胶保温杯，是身材娇小的潜水员在冰封湖泊深处捞取遗失空投时的必备神器。",
        en = "Arctic-grade thick neoprene turns this small diving hood into a thermal thermos for your skull. It is indispensable for petite divers salvaging sunken caches from frozen lakes.",
    },
    ["xs_wetsuit_jacket"] = {
        zh = "配有防锈前拉链的小号潜水夹克。穿脱相比连身衣便利得多，在潮湿多雨的变异沼泽中跋涉时，它既能挡住刺骨阴风，又完全不妨碍矮小射手端枪瞄准或挥舞匕首。",
        en = "Featuring a heavy-duty front zipper, this petite neoprene jacket slips on easily. It sheds chilling drizzle in murky swamps without restricting your rifle aim or rapid dagger thrusts.",
    },
    ["xs_wetsuit_pants"] = {
        zh = "加厚氯丁橡胶剪裁而成的小号潜水长裤。弹性面料紧紧收束纤细双腿，在涉水穿过废弃地铁淹没隧道时，能有效避免腿部肌肉因冰冷死水浸泡而陷入剧烈痉挛。",
        en = "Made from elastic neoprene, these small wetsuit pants hug slender legs snugly. Wading through submerged subway tunnels protects delicate calf muscles from debilitating cold-water cramps.",
    },
    ["xs_wetsuit_pants_thin"] = {
        zh = "轻薄速干氯丁橡胶制作的小号潜水裤。适合较为温和的春夏季节使用，既能防止水下尖锐石块划伤娇嫩皮肤，又不会让矮小的潜水者在走上海滩时热得虚脱乏力。",
        en = "Cut from lightweight quick-drying neoprene, these small wetsuit pants suit milder seasons. They shield skin from submerged debris without baking petite runners alive once back ashore.",
    },
    ["xs_wetsuit_shorts"] = {
        zh = "轻便干练的小号潜水短裤。为细瘦小腿和膝关节提供了毫无拘束的活动自由，非常适合那些经常需要在废弃港口浅滩与岸上断壁残垣间来回飞跃的小个子侦察员。",
        en = "These small neoprene shorts give petite knees and calves complete freedom. They are perfect for nimble scouts transitioning frequently between shallow coastal reefs and rocky shoreline rubble.",
    },
    ["xs_wetsuit_shorts_technical"] = {
        zh = "加装了耐磨垫与快速排水网袋的小号技术潜水短裤。坚固贴合，即便在腿侧口袋里塞入重型手电筒与水下切割器，也不会在急流冲击下从娇小腰部松脱滑落。",
        en = "Fitted with reinforced friction patches and drainage pockets, these small technical diving shorts stay anchored securely across narrow hips even while carrying heavy salvage tools underwater.",
    },
    ["xs_wetsuit_shorts_technical_loose"] = {
        zh = "宽松版型的小号技术潜水短裤。剪裁余量充裕，完全不会勒压大腿神经与血液循环，腿侧宽大的网袋能从容收纳娇小潜水员搜集到的大量贝壳与微型金属废料。",
        en = "Cut with a roomy fit, these small technical diving shorts never pinch slender thighs. The spacious mesh pockets easily swallow loose electronic chips and salvaged brass components.",
    },
    ["xs_wetsuit_spring"] = {
        zh = "短袖短裤样式的小号春季潜水湿衣。为那些需要经常在废土半淹没水渠中来回涉水作业的娇小幸存者，提供了最清凉、最具机动性且兼顾防失温的折中选择。",
        en = "Short-sleeved and short-legged, this small spring wetsuit is the ultimate compromise for petite scavengers wading through partially submerged culverts without risking overheating.",
    },
    ["xs_wetsuit_spring_sleeveless"] = {
        zh = "无袖款式的小号春季潜水湿衣。彻底解放了娇小双肩与大臂的活动空间，在冰凉水流中保住核心脏器温度的同时，让你在狭窄水下缝隙中攀爬脱身毫无窒碍。",
        en = "Sleeveless spring neoprene grants petite shoulders unrestricted movement. Swimming through cold drainage pipes keeps your core organs warm while allowing effortless climbing through narrow grates.",
    },
    ["xs_wetsuit_thick"] = {
        zh = "整件厚达七毫米的小号全封闭极寒潜水服。穿上后整个人圆滚滚的像一只黑色小海豹，但即便在漂浮着碎冰的极寒辐射海湾中长时间潜泳，也绝不会被冻得瑟瑟发抖。",
        en = "Measuring seven millimeters thick, this petite wetsuit turns you into a baby seal. Swimming for hours amid floating icebergs inside irradiated bays will not freeze your blood.",
    },
    ["xs_wetsuit_top"] = {
        zh = "加厚氯丁橡胶缝制的小号潜水背心。套在娇小身躯上穿脱迅速利索，能把脆弱的心脏与胸腔紧紧包裹在防水保温层内，是阴雨天穿过泛滥泥塘时不可或缺的贴身防线。",
        en = "Stitched from thick neoprene, this small wetsuit vest slips on quickly over slender chests. It serves as an excellent water-resistant thermal underlayer across rainy, mud-drenched wastes.",
    },
    ["xs_wetsuit_top_sleeved"] = {
        zh = "带有完整长袖的小号潜水上衣。将细瘦手臂与后背严实包裹在隔热橡胶之下，无论是潜入阴冷深井打捞物资还是顶着冰雨行军，都能牢牢锁住每一缕宝贵体温。",
        en = "Featuring full-length neoprene sleeves, this small top insulates slender arms and backs. It locks in body heat whether diving into deep wells or marching under freezing downpours.",
    },
    ["xs_wetsuit_top_sleeved_thin"] = {
        zh = "轻薄面料剪裁的长袖小号潜水衣。弹性极佳且排水迅速，既能避免纤细小臂被暗礁藤壶与锋利碎石割伤，又不会在剧烈划水冲刺时在衣服内积聚过多燥热汗水。",
        en = "Crafted from thin quick-drying neoprene, this small long-sleeved top offers great stretch. It prevents barnacles and submerged debris from scraping delicate forearms without trapping excessive heat.",
    },
    ["xs_wsurvivor_jumpsuit"] = {
        zh = "塞满隔热羽绒与防弹芳纶纤维的小号冬季生存连身服。厚实沉重的躯干装甲在矮小身材上宛如一间微型移动火炉，专为在暴雪废墟中独自猎杀变异怪物的独行侠定制。",
        en = "Packed with insulating down and ballistic aramid layers, this small winter jumpsuit acts like a personal mobile furnace for lone hunters stalking frozen radioactive ruins.",
    },
    ["xs_wsurvivor_jumpsuit_nofur"] = {
        zh = "不使用任何动物皮毛的小号无毛冬用连体服。完全依靠先进合成多孔保温层，即使在雪堆里摸爬滚打浸湿了外壳，内里依然能持续保持着令人赞叹的干爽与温暖。",
        en = "Relying purely on synthetic micro-insulation without animal fur, this petite winter jumpsuit keeps small wanderers dry and toasty even after rolling across deep, wet snowbanks.",
    },
    ["xsboxer_briefs"] = {
        zh = "小尺码的高弹力纯棉平角内裤。柔软亲肤，能够紧密包覆住细小臀部与大腿根部，在长时间穿着粗糙武装裤或沉重板甲行军时，杜绝任何痛苦的皮肤摩擦红肿。",
        en = "Sewn from elastic cotton, these petite boxer briefs fit slender hips neatly. They effectively prevent agonizing inner-thigh chafing caused by walking long miles in coarse armor.",
    },
    ["xsboxer_shorts"] = {
        zh = "宽松透气的小号平角短裤。轻飘飘的面料透气通风极佳，穿在娇小的废土求生者身上显得宽松舒适，是在酷热难耐的末日盛夏午后躲在防空洞里纳凉的至高法宝。",
        en = "Airy and lightweight, these small boxer shorts deliver superb ventilation. Lounging inside cool fallout shelters during sweltering wasteland afternoons, they offer unmatched comfort and freedom.",
    },
    ["xsboy_shorts"] = {
        zh = "贴身剪裁的小号平角短裤。柔软面料紧紧贴合娇小臀胯轮廓，在穿戴狭窄的小号金属板甲或硬质护腿时，能充当一层柔和温存的人体防磨缓冲垫，极其贴心。",
        en = "Snugly fitting across narrow hips, these small boy shorts provide soft undergarment cushioning. They protect tender skin from harsh chafing beneath tight-fitting chainmail or plate armor.",
    },
    ["xshsurvivor_suit"] = {
        zh = "重型生存装甲的小体型巅峰杰作。将微型陶瓷插板、钛合金铰链与高密度凯夫拉编织成一体，身材娇小的幸存者穿上它，宛如一尊所向披靡的微缩型主战坦克。",
        en = "The absolute pinnacle of petite wasteland armor, combining ceramic plates, titanium hinges, and Kevlar weave. Wearing this transforms a small survivor into an unstoppable pocket-sized battle tank.",
    },
    ["xsnomex_socks"] = {
        zh = "小号诺梅克斯阻燃长袜。能够严实包裹细小双足，在踏过熊熊燃烧的废墟残渣或滚烫的沥青碎块时，确保娇嫩的脚底板和脚趾绝不会被高温灼伤起泡。",
        en = "These small Nomex socks stretch over slender feet. Trudging across smoldering building rubble or scalding asphalt will never scorch your delicate soles or melt your toes.",
    },
    ["xssocks"] = {
        zh = "小尺码的标准棉袜。纯棉吸汗，虽然穿久了后脚跟处容易磨破两个小洞，但有总比没有强，至少能防止细嫩脚后跟被硬邦邦的废土军靴磨得血肉模糊。",
        en = "Classic small cotton socks absorb moisture reliably. Though heels wear thin eventually, wearing them spares tender feet from bloody blister agony inside stiff, scavenged combat boots.",
    },
    ["xssocks_wool"] = {
        zh = "用粗毛线手工编织的小号羊毛厚袜。蓬松柔软，踩上去像踩在两团暖和的棉花糖上，是在冰天雪地的漫长寒冬中保全细嫩脚趾不受冻伤的无价圣物。",
        en = "Hand-knitted from thick wasteland yarn, these small wool socks feel pleasantly spongy. They are an absolute lifesaver for protecting delicate toes from frostbite during subzero blizzards.",
    },
    ["xssports_bra"] = {
        zh = "采用加宽弹力织带的小号运动抹胸。提供了不可思议的紧密支撑，让娇小的突变游侠在废墟瓦砾间飞檐走壁狂奔时，胸部依然稳如磐石、毫无颠簸痛感。",
        en = "Engineered with reinforced elastic webbing, this small sports bra provides exceptional torso support. Petite scouts can sprint and vault rubble piles without suffering painful chest bouncing.",
    },
    ["xssurvivor_jumpsuit"] = {
        zh = "缝合了防刺纤维与强化关节垫的小号标准生存连体服。既能抵御变异野兽的抓挠，又保留了钻爬狭窄狗洞与通风管道所需的绝佳柔韧性，娇小拾荒者不可或缺。",
        en = "Reinforced with puncture-proof fibers and flexible joint pads, this small survivor jumpsuit repels beast claws while offering enough flexibility to squeeze through tiny ventilation shafts.",
    },
    ["y_carpet"] = {
        zh = "一整卷色泽温暖明亮的黄色提花绒面地毯。铺在避难所冰冷潮湿的水泥地面上，不仅能有效隔绝地底升腾的寒气与脚步回音，那抹明快的暖色调更能抚慰长期生活在地下者的压抑心灵。",
        en = "A roll of plush, bright yellow woven floor carpeting. Unrolled across chilly concrete bunker floors, it insulates bare feet against subterranean damp while brightening subterranean rooms with cheerful color.",
    },
    ["yarn"] = {
        zh = "一整团缠绕紧实的原色细羊毛纺织毛线球。柔软蓬松且富含天然弹性，配合两根织针就能在温暖的篝火旁为你编织出一顶暖和的毛线帽、一双厚实的羊毛袜或是修补破损不堪的旧毛衣。",
        en = "A neatly wound skein of spun wool yarn. Soft and elastic, sitting beside the embers with two whittled knitting needles allows patient survivors to weave warm winter beanies, socks, and patch frayed coats.",
    },
    ["years_old_newspaper"] = {
        zh = "发黄变脆的旧时代报纸。头版还在一本正经地报道议会预算案与明星花边绯闻，翻到末尾几版却已充斥着神秘暴乱与实验室封锁的惊恐呼喊，读来令人唏嘘。",
        en = "This yellowed, brittle newspaper opens with mundane fiscal debates and celebrity gossip. Turning to the final pages reveals frantic, panicked headlines chronicling lab containment breaches and apocalyptic chaos.",
    },
    ["yeast"] = {
        zh = "一包处于休眠干燥状态的活性酵母颗粒。只要在温水与少量糖分的唤醒下便会重新沸腾生长，是末日面包烘焙中赋予面团松软气孔的灵魂，也是酿造啤酒与蒸馏高浓度烈酒不可或缺的生物基石。",
        en = "A sealed packet of dehydrated active baker's yeast granules. Revived in lukewarm sweetened water, it provides the rising power for crusty loaves and ferments grain mashes into life-saving distilled spirits.",
    },
    ["yoghurt"] = {
        zh = "一罐口感浓稠、微酸爽口的天然发酵酸奶。不仅含有丰富的优质蛋白质与钙质，活跃的有益乳酸菌群更能显著改善因常年吃粗砺野草和干瘪咸肉而紊乱受损的肠道菌群，堪称肠胃救星。",
        en = "A fresh jar of thick, pleasantly tart fermented yogurt. Rich in wholesome proteins and active probiotic cultures, it restores digestive health beaten down by months of fibrous weeds and stale jerky.",
    },
    ["yogurt_starter_culture"] = {
        zh = "一小瓶经过冷冻干燥精选提纯的活性酸奶发酵菌粉。只要将其按比例接种入温热的煮沸鲜牛奶或豆浆中恒温静置，几小时内就能诱导整锅液体凝固成香浓丝滑的极品酸奶，可无限代接种繁殖。",
        en = "A small vial of freeze-dried thermophilic yogurt starter cultures. Inoculated into warm milk, these beneficial bacteria coagulate rich curds, creating endless batches of nutritious cultured dairy.",
    },
    ["yoke_harness"] = {
        zh = "采用结实熟皮与硬木弧度精心打磨缝制的牲畜挽具套轭。结构贴合马匹或骡子的肩颈肌肉，受力均匀分散，能够让温顺的驮兽为你轻松拉动装满数百磅废铁与粮食的粗重手推木车。",
        en = "A traditional wooden draft yoke lined with padded leather harnessing. Contoured to rest comfortably over working beast shoulders, it translates animal muscle into effortless cart-towing power across rough terrain.",
    },
    ["yoke_harness_heavyduty"] = {
        zh = "加装了锻造铁质挂钩与加宽双层厚牛皮垫板的重型重载牲畜拉车轭具。专为套驾变异巨公牛或重型挽马而强化设计，足以承受巨兽发力冲刺时的狂暴拉力，拉动重型战车越过泥潭壕沟毫无问题。",
        en = "A heavy-duty draft yoke reinforced with forged iron brackets and thick leather pads. Built to harness massive draft horses or mutated oxen, it endures colossal pulling loads without splintering.",
    },
    ["young_koji"] = {
        zh = "刚完成米曲霉接种并开始在温润蒸米上萌发菌丝的新鲜幼苗期米曲。表面泛着一层极微薄的白绒薄膜并散发着菌菇与栗子般的清香，是酿造醇正日本清酒、鲜美味噌和纯粮酱油的最初关键起点。",
        en = "Steamed grain newly inoculated with Aspergillus oryzae spores. A faint dusting of fragrant white mycelium spreads across the grains, signaling the delicate opening phase of artisanal sake and miso brewing.",
    },
    ["young_koji_active"] = {
        zh = "菌丝旺盛交织、正处于剧烈放热分解阶段的活跃生长中米曲。曲堆温度明显升高并散发出一股醉人的甘甜香气，必须密切翻动散热防止过热烧菌，其旺盛的淀粉酶正在将大米淀粉疯狂转化为糖。",
        en = "Vigorously fermenting koji rice covered in a blooming network of white mycelial fleece. Generating heat as its enzymes break down starch into sweet sugars, regular aeration keeps the fungal culture thriving.",
    },
    ["young_koji_done"] = {
        zh = "菌丝已经彻底包裹每一粒熟米、结成坚实曲块的优质成熟米曲。散发着如同新鲜蘑菇般的迷人芳香，酶系活性达到了顶峰，可以直接掰碎投入盐水桶或发酵缸中开启顶级的美味酱料酿造之旅。",
        en = "A fully colonized, fragrant cake of mature white koji rice. Densely bound by velvety mycelium and rich in active amylase enzymes, it is ready to be crumbled into brewing vessels for soy sauce fermentation.",
    },
    ["young_leaves"] = {
        zh = "在早春暖阳下刚刚从枝头或灌木间冒出的鲜嫩浅绿色幼芽嫩叶。质地娇嫩且几乎没有粗硬的纤维感，洗净后直接入口清甜爽脆，是漫长寒冬过去后补充体内匮乏维生素的最美味大自然赠礼。",
        en = "Tender, bright-green young leaves gathered from spring tree shoots and hedgerows. Soft, mildly sweet, and completely free of bitter tannins, eating them fresh provides an essential infusion of vitamins.",
    },
    ["young_yeast"] = {
        zh = "处于对数快速增殖期的一小碗起泡泛白的新鲜幼年酵母培养液。表层浮动着细腻的碳酸气泡并散发着清新的麦芽面包芳香，活力充沛，只需舀上两勺拌入面粉便能让面团在极短时间内膨胀发酵。",
        en = "A foaming, bubbling culture of vigorous young yeast suspended in malt broth. Teeming with rapid cellular division, stirring spoonfuls into flour dough causes rapid rising and heavenly baking aromas.",
    },
    ["yoyo"] = {
        zh = "一只采用彩色工程塑料外壳与滚珠轴承转轴的经典花式悠悠球。顺着棉线甩下并在指间翻飞出睡眠与遛狗的花哨技巧，在枯燥乏味的漫长守夜中，它是消磨无聊时光并锻炼手指灵巧度的绝妙玩具。",
        en = "A classic ball-bearing trick yo-yo strung with braided cotton twine. Whirling through sleeping tricks and around-the-world loops, practicing fingertip maneuvers banishes boredom during quiet guard shifts.",
    },
    ["yrax_computer"] = {
        zh = "从坠毁的伊拉克斯高维机械造物残骸中剥离出的异星控制计算核心。表面泛着神秘的金色纳米几何回路并带有无声的冷光脉动，虽然人类无法直接读取其底层逻辑，但拆解研究能极大启发高能电子技术。",
        en = "An alien logic processor core retrieved from the wreckage of an extradimensional Yrax automaton. Pulsing with cold crystalline light, analyzing its quantum circuitry reveals bizarre computing paradigms.",
    },
    ["yrax_delta_laser_gun"] = {
        zh = "拆卸自伊拉克斯重型战斗机兵的高能德尔塔定向激光发射炮。能够发射出穿透力极强的聚焦紫外相干光束，射击时毫无后坐力且在空气中留下电离臭氧焦痕，能将重装甲目标当场烧穿熔解。",
        en = "A high-output directed energy weapon salvaged from a Yrax Delta chassis. Emitting coherent ultraviolet beams with zero mechanical recoil, it leaves sizzling ionized trails while punching straight through hardened steel armor.",
    },
    ["yrax_deterrent_laser"] = {
        zh = "原本作为异界哨兵自卫武装的伊拉克斯威慑级脉冲激光器。射速极快且能量转化效率惊人，射击时伴随着轻微的高频蜂鸣声，虽名为威慑，但一梭子激光脉冲打过去足以将密集步兵烤成焦炭。",
        en = "A compact high-rate-of-fire pulse laser salvaged from Yrax scout automatons. Humming softly with alien power, its rapid pulse bursts incinerate organic flesh despite its clinical sounding bureaucratic designation.",
    },
    ["yrax_electronics"] = {
        zh = "一系列由超导晶体与自愈微导线交织而成的伊拉克斯异星电子元件板。抗电磁脉冲能力完美无瑕，是制造高级外星激光武器、能量力场发生器及超导储能设备时最不可或缺的稀世科技瑰宝。",
        en = "A cluster of superconducting crystalline circuit boards recovered from alien Yrax machines. Completely impervious to EMP interference, these advanced components unlock miraculous high-tier energy weaponry.",
    },
    ["yrax_metal"] = {
        zh = "一块散发着暗哑油亮光泽的伊拉克斯高维合金装甲残片。分子结构具有奇异的自组织抗疲劳特性，硬度远超传统钨钛合金且密度轻如铝合金，是锻造终极单兵近战神兵或顶级防弹装甲板的奇迹神铁。",
        en = "A fragment of dull, iridescent armor plating salvaged from destroyed Yrax automatons. Possessing strange self-knitting molecular matrices, it offers absurd strength-to-weight ratios unmatched by terrestrial alloys.",
    },
    ["yrax_metaljet_cannon"] = {
        zh = "利用超导高频感应瞬间将金属融化为液态并通过超高压磁流体喷射的伊拉克斯铁水喷流加农炮。喷射出数千度炽热的金属熔流射流，能以液态穿甲的恐怖威能瞬间将任何坚不可摧的掩体直接熔解洞穿。",
        en = "A terrifying ferro-hydraulic cannon designed by alien Yrax fabricators. Flash-melting internal metallic reservoirs into superheated liquid jets propelled by magnetic rails, it liquefies fortified bunkers in seconds.",
    },
    ["yrax_robotics"] = {
        zh = "从伊拉克斯战斗机械人上完整剥离的高精度微电机与仿生关节组件。内部采用人造肌腱与无摩擦液压伺服，响应速度与承载力远超地球工程技术，是改装顶级智能假肢与动力外骨骼的无价之宝。",
        en = "A cluster of high-precision micro-servos and synthetic tendons salvaged from a downed Yrax unit. Operating with frictionless fluidics, their response speeds unlock peerless bionic limb upgrades.",
    },
    ["yrax_scrap"] = {
        zh = "在剧烈等离子爆炸中扭曲变形的伊拉克斯高维机械破碎残片。虽然已经失去了精密的逻辑机能，但其独特的异界分子记忆金属依然能够被重新回炉熔铸，为末日工坊提供顶级耐热防弹原料。",
        en = "Twisted fragments of otherworldly alloy scavenged from destroyed Yrax automatons. Though severed from their central control logic, their heat-resistant metallic structure can be melted into resilient armor.",
    },
    ["yrax_sensor"] = {
        zh = "一颗镶嵌在多面体外壳内的伊拉克斯多光谱复合观测传感器。不仅能接收全波段红外与微波雷达，甚至能观测到多维空间褶皱与生命电磁场，是探索浓雾与深渊遗迹时洞察一切的神之眼。",
        en = "A multi-faceted compound sensory module extracted from alien Yrax reconnaissance units. Piercing through dense fog and dimensional phase shifts, it reveals concealed hostiles lurking behind reinforced bulkheads.",
    },
    ["yrax_trinket"] = {
        zh = "一块表面雕刻着微缩分形回路的纯金微型异星金属薄片。不知是伊拉克斯军团的身份信标还是某种宗教祭祀几何护身符，在阳光下翻转泛着神秘金芒，在任何避难所行商眼中都是极其昂贵的通货。",
        en = "A tiny rectangular plate of burnished gold etched with microscopic fractal circuits. Whether an alien identification tag or a geometrical talisman, its exquisite perfection commands immense trade wealth.",
    },
    ["yukata"] = {
        zh = "一件采用纯棉布缝制、带有典雅几何靛蓝花纹的传统日式夏日浴衣。质地轻薄透气且穿脱宽松舒适，虽然没有任何实质性的护甲防御力，但清凉飘逸的衣摆在闷热夏夜能为你带来难得的惬意平静。",
        en = "A traditional lightweight cotton summer kimono decorated with classic indigo patterns. Offering zero armor against ravenous teeth, its loose, breathable drape brings soothing aesthetic grace to sweltering wasteland evenings.",
    },
    ["zentai"] = {
        zh = "一件将整个人从头顶到脚尖完全包裹在内的纯色紧身氨纶全身服。弹性极佳且紧密勾勒出身形，穿上后除了视野受阻与呼吸略显闷热外没有任何防御价值，但足以让你的队友在黑暗中被你吓一大跳。",
        en = "A full-body elastane bodysuit covering you from crown to toe in skin-tight synthetic fabric. Severely impairing peripheral vision while offering zero ballistic protection, it reliably startles wary base sentries.",
    },
    ["zerocola"] = {
        zh = "一罐使用人造阿斯巴甜代糖调配的无糖零卡路里可乐。虽然无法为你提供任何赖以生存的真实碳水热量，但开罐时那声清脆的汽水噗嗤声与充满口腔的刺激气泡，依然能极大抚慰绝望的心灵。",
        en = "A chilled aluminum can of zero-calorie diet cola sweetened with aspartame. Devoid of the precious carbohydrates starving wanderers crave, its fizzy carbonation and nostalgic caramel taste bring immense mental joy.",
    },
    ["zeromdew"] = {
        zh = "一罐泛着荧光淡绿色泽的无糖柑橘风味高咖啡因苏打汽水。添加了巨量人工代糖与高浓度咖啡因，入口酸甜刺激且回甘微苦，能在不增加任何热量负担的前提下瞬间驱散浓重睡意、强行打起精神。",
        en = "A can of neon-green zero-sugar citrus energy soda packed with synthetic caffeine. Delivering an electric jolt to exhausted nerves without providing caloric fuel, it powers desperate all-night perimeter watches.",
    },
    ["zeroorange"] = {
        zh = "一罐散发着浓烈人工香精气味的无糖香橙味碳酸汽水。亮橙色的汽水在舌尖上跳跃起泡，虽然没有任何真正的橙汁成分，但冰镇饮用时依然是一抹能打破末日苦涩生活的短暂甜美亮色。",
        en = "A brightly colored can of zero-sugar orange soda brimming with fizzy carbonation. While lacking any trace of genuine fruit juice, its sweet artificial tang offers a vibrant, bubbly escape from dreary survival rations.",
    },
    ["zerotropical"] = {
        zh = "一罐融合了人工芒果、百香果与菠萝香精风味的无糖热带综合风味气泡水。气泡绵密酸甜，让置身于废墟泥泞中的幸存者仿佛在恍惚中嗅到了昔日阳光海滩与摇曳椰树的遥远度假气息。",
        en = "A refreshing aluminum can of zero-calorie tropical fruit soda. Bursting with aromatic passionfruit and pineapple flavorings, popping the tab evokes hazy, wistful daydreams of distant sun-drenched beaches.",
